		{
			prev = (next = (draw_prev = (draw_next = null)));
			tcb = null;
			pause_level = 0;
			obj_type = 0;
			vib_timer = (hitstop_timer = (invincible_timer = 0));
			view_out_ofst = 0;
			Array.Clear(view_out_ofst_plus, 0, view_out_ofst_plus.Length);
			user_work_OBJECT = null;
			user_flag_OBJECT = null;
			flag = 0u;
			move_flag = 0u;
			disp_flag = 0u;
			gmk_flag = 0u;
			sys_flag = 0u;
			user_timer = 0;
			dir.Clear();
			scale.Clear();
			pos.Clear();
			ofst.Clear();
			prev_ofst.Clear();
			parent_ofst.Clear();
			lock_obj = null;
			prev_pos.Clear();
			spd.Clear();
			spd_add.Clear();
			flow.Clear();
			move.Clear();
			spd_m = 0;
			dir_slope = (dir_fall = 0);
			spd_slope = (spd_slope_max = (spd_fall = (spd_fall_max = (push_max = 0))));
			col_flag = (col_flag_prev = 0u);
			Array.Clear(field_rect, 0, field_rect.Length);
			field_ajst_w_db_f = (field_ajst_w_db_b = (field_ajst_w_dl_f = (field_ajst_w_dl_b = 0)));
			field_ajst_w_dt_f = (field_ajst_w_dt_b = (field_ajst_w_dr_f = (field_ajst_w_dr_b = 0)));
