		public OBS_OBJECT_WORK Assign(OBS_OBJECT_WORK objectWork)
		{
			if (this != objectWork)
			{
				prev = objectWork.prev;
				next = objectWork.next;
				draw_prev = objectWork.draw_prev;
				draw_next = objectWork.draw_next;
				tcb = objectWork.tcb;
				pause_level = objectWork.pause_level;
				obj_type = objectWork.obj_type;
				vib_timer = objectWork.vib_timer;
				hitstop_timer = objectWork.hitstop_timer;
				invincible_timer = objectWork.invincible_timer;
				view_out_ofst = objectWork.view_out_ofst;
				for (int i = 0; i < view_out_ofst_plus.Length; i++)
				{
					view_out_ofst_plus[i] = objectWork.view_out_ofst_plus[i];
				}
				flag = objectWork.flag;
				move_flag = objectWork.move_flag;
				disp_flag = objectWork.disp_flag;
				gmk_flag = objectWork.gmk_flag;
				sys_flag = objectWork.sys_flag;
				user_flag = objectWork.user_flag;
				user_work = objectWork.user_work;
				user_timer = objectWork.user_timer;
				dir.Assign(objectWork.dir);
				scale.Assign(objectWork.scale);
				pos.Assign(objectWork.pos);
				ofst.Assign(objectWork.ofst);
				prev_ofst.Assign(objectWork.prev_ofst);
				parent_ofst.Assign(objectWork.parent_ofst);
				lock_ofst.Assign(objectWork.lock_ofst);
				prev_pos.Assign(objectWork.prev_pos);
				spd.Assign(objectWork.spd);
				spd_add.Assign(objectWork.spd_add);
