				move.Assign(objectWork.move);
				spd_m = objectWork.spd_m;
				dir_slope = objectWork.dir_slope;
				dir_fall = objectWork.dir_fall;
				spd_slope = objectWork.spd_slope;
				spd_slope_max = objectWork.spd_slope_max;
				spd_fall = objectWork.spd_fall;
				spd_fall_max = objectWork.spd_fall_max;
				push_max = objectWork.push_max;
				col_flag = objectWork.col_flag;
				col_flag_prev = objectWork.col_flag_prev;
				for (int j = 0; j < field_rect.Length; j++)
				{
					field_rect[j] = objectWork.field_rect[j];
