	public class NNS_TEXLIST
	{
		public int nTex;

		public NNS_TEXINFO[] pTexInfoList;

		public NNS_TEXLIST()
		{
		}

		public NNS_TEXLIST(NNS_TEXLIST pFrom)
		{
			nTex = pFrom.nTex;
			pTexInfoList = new NNS_TEXINFO[nTex];
			for (int i = 0; i < nTex; i++)
			{
				pTexInfoList[i] = new NNS_TEXINFO(pFrom.pTexInfoList[i]);
			}
		}

		public void Clear()
		{
			nTex = 0;
			pTexInfoList = null;
		}
	}

	public struct VecFx32 : IClearable
	{
		public int x;

		public int y;

		public int z;

		public void Clear()
		{
			x = (y = (z = 0));
		}

		public VecFx32(int _x, int _y, int _z)
		{
			x = _x;
			y = _y;
			z = _z;
		}

		public VecFx32(VecFx32 vecFx32)
		{
			x = vecFx32.x;
			y = vecFx32.y;
			z = vecFx32.z;
		}

		public void Assign(VecFx32 vecFx32)
		{
			x = vecFx32.x;
			y = vecFx32.y;
