		public byte pos_y;

		public ushort id;

		public ushort flag;

		public sbyte left;

		public sbyte top;

		public byte width;

		public byte height;

		public byte[] byte_param = new byte[2];

		public ushort word_param
		{
			get
			{
				return (ushort)((byte_param[1] << 8) | byte_param[0]);
			}
			set
			{
				byte_param[0] = (byte)(value & 0xFF);
				byte_param[1] = (byte)((value >> 8) & 0xFF);
			}
		}
	}

