	public class GMS_EVE_DATA_EV_HEADER
	{
		public ushort width;

		public ushort height;

		public uint[] ofst;

		public GMS_EVE_DATA_EV_LIST[] ev_list;

		public GMS_EVE_DATA_EV_HEADER()
		{
		}

		public GMS_EVE_DATA_EV_HEADER(AmbChunk data)
		{
			using (MemoryStream input = new MemoryStream(data.array, data.offset, data.array.Length - data.offset))
			{
				using (BinaryReader binaryReader = new BinaryReader(input))
				{
					width = binaryReader.ReadUInt16();
					height = binaryReader.ReadUInt16();
					int num = width * height;
					ofst = new uint[num];
					for (int i = 0; i < num; i++)
					{
						ofst[i] = binaryReader.ReadUInt32();
					}
					ev_list = New<GMS_EVE_DATA_EV_LIST>(num);
					for (int j = 0; j < num; j++)
					{
						binaryReader.BaseStream.Seek(ofst[j], SeekOrigin.Begin);
						ev_list[j].eve_num = binaryReader.ReadUInt16();
						if (ev_list[j].eve_num > 0)
						{
							ev_list[j].eve_rec = New<GMS_EVE_RECORD_EVENT>(ev_list[j].eve_num);
							for (int k = 0; k < ev_list[j].eve_num; k++)
							{
								ev_list[j].eve_rec[k].pos_x = binaryReader.ReadByte();
								ev_list[j].eve_rec[k].pos_y = binaryReader.ReadByte();
								ev_list[j].eve_rec[k].id = binaryReader.ReadUInt16();
								ev_list[j].eve_rec[k].flag = binaryReader.ReadUInt16();
								ev_list[j].eve_rec[k].left = binaryReader.ReadSByte();
								ev_list[j].eve_rec[k].top = binaryReader.ReadSByte();
								ev_list[j].eve_rec[k].width = binaryReader.ReadByte();
								ev_list[j].eve_rec[k].height = binaryReader.ReadByte();
								ev_list[j].eve_rec[k].word_param = binaryReader.ReadUInt16();
							}
						}
					}
				}
			}
		}

		public void loadData(byte[] data)
		{
			using (MemoryStream input = new MemoryStream(data))
			{
				using (BinaryReader binaryReader = new BinaryReader(input))
				{
					width = binaryReader.ReadUInt16();
					height = binaryReader.ReadUInt16();
					int num = width * height;
					for (int i = 0; i < num; i++)
					{
						ev_list[i].eve_num = binaryReader.ReadUInt16();
						if (ev_list[i].eve_num <= 0)
						{
							continue;
						}
						for (int j = 0; j < ev_list[i].eve_num; j++)
						{
							byte pos_x = binaryReader.ReadByte();
							byte pos_y = binaryReader.ReadByte();
							ushort num2 = binaryReader.ReadUInt16();
							ushort flag = binaryReader.ReadUInt16();
							ushort word_param = binaryReader.ReadUInt16();
							if (num2 < 60 || (300 <= num2 && num2 < 300) || (308 <= num2 && num2 < 335))
							{
								ev_list[i].eve_rec[j].pos_x = pos_x;
								ev_list[i].eve_rec[j].pos_y = pos_y;
								ev_list[i].eve_rec[j].id = num2;
								ev_list[i].eve_rec[j].flag = flag;
								ev_list[i].eve_rec[j].word_param = word_param;
							}
						}
					}
				}
			}
		}

		public byte[] saveData()
		{
			byte[] array = null;
			using (MemoryStream memoryStream = new MemoryStream())
			{
				using (BinaryWriter binaryWriter = new BinaryWriter(memoryStream))
				{
					binaryWriter.Write(width);
					binaryWriter.Write(height);
					int num = width * height;
					for (int i = 0; i < num; i++)
					{
						binaryWriter.Write(ev_list[i].eve_num);
						if (ev_list[i].eve_num > 0)
						{
							for (int j = 0; j < ev_list[i].eve_num; j++)
							{
								binaryWriter.Write(ev_list[i].eve_rec[j].pos_x);
								binaryWriter.Write(ev_list[i].eve_rec[j].pos_y);
								binaryWriter.Write(ev_list[i].eve_rec[j].id);
								binaryWriter.Write(ev_list[i].eve_rec[j].flag);
								binaryWriter.Write(ev_list[i].eve_rec[j].word_param);
							}
						}
					}
				}
				byte[] array2 = memoryStream.ToArray();
				int num2 = array2.Length;
				array = new byte[num2];
				Array.Copy(array2, array, num2);
				return array;
			}
		}

		public void Clear()
		{
			width = 0;
			height = 0;
			ofst = null;
			ev_list = null;
		}
	}

