		public ushort y;

		public ushort z;

		public VecU16(ushort _x, ushort _y, ushort _z)
		{
			x = _x;
			y = _y;
			z = _z;
		}

		public VecU16(VecU16 vecU16)
		{
			x = vecU16.x;
			y = vecU16.y;
			z = vecU16.z;
		}

		public void Assign(VecU16 vecU16)
		{
			x = vecU16.x;
			y = vecU16.y;
			z = vecU16.z;
		}

		public void Clear()
		{
			x = (y = (z = 0));
		}
	}

