	public struct ArrayPointer<T>
	{
		public T[] array;

		public int offset;

		public static readonly ArrayPointer<T> NULL = default(ArrayPointer<T>);

		public T this[int _index]
		{
			get
			{
				return array[offset + _index];
			}
		}

		public ArrayPointer(T[] _array)
			: this(_array, 0)
		{
		}

		public ArrayPointer(T[] _array, int _offset)
		{
			array = _array;
			offset = _offset;
		}

		public static ArrayPointer<T> operator ++(ArrayPointer<T> _pointer)
		{
			_pointer.offset++;
			return _pointer;
		}

		public static ArrayPointer<T> operator --(ArrayPointer<T> _pointer)
		{
			_pointer.offset--;
			return _pointer;
		}

		public static ArrayPointer<T> operator +(ArrayPointer<T> _pointer, int _offset)
		{
			_pointer.offset += _offset;
			return _pointer;
		}

		public static ArrayPointer<T> operator -(ArrayPointer<T> _pointer, int _offset)
		{
			_pointer.offset -= _offset;
			return _pointer;
		}

		public static bool operator <(ArrayPointer<T> _pointer1, ArrayPointer<T> _pointer2)
		{
			if (_pointer1.array != _pointer2.array)
			{
				throw new InvalidOperationException();
			}
			return _pointer1.offset < _pointer2.offset;
		}

		public static bool operator >(ArrayPointer<T> _pointer1, ArrayPointer<T> _pointer2)
		{
			if (_pointer1.array != _pointer2.array)
			{
				throw new InvalidOperationException();
			}
			return _pointer1.offset > _pointer2.offset;
		}

		public static bool operator ==(ArrayPointer<T> _pointer1, ArrayPointer<T> _pointer2)
		{
