	public class NNS_MOTION : IClearable
	{
		public uint fType;

		public float StartFrame;

		public float EndFrame;

		public int nSubmotion;

		public NNS_SUBMOTION[] pSubmotion;

		public float FrameRate;

		public uint Reserved0;

		public uint Reserved1;

		public NNS_MOTION()
		{
		}

		public NNS_MOTION(NNS_MOTION motion)
		{
			fType = motion.fType;
			StartFrame = motion.StartFrame;
			EndFrame = motion.EndFrame;
			nSubmotion = motion.nSubmotion;
			pSubmotion = motion.pSubmotion;
			FrameRate = motion.FrameRate;
			Reserved0 = motion.Reserved0;
			Reserved1 = motion.Reserved1;
		}

		public NNS_MOTION Assign(NNS_MOTION motion)
		{
			if (this != motion)
			{
				fType = motion.fType;
				StartFrame = motion.StartFrame;
				EndFrame = motion.EndFrame;
				nSubmotion = motion.nSubmotion;
				pSubmotion = motion.pSubmotion;
				FrameRate = motion.FrameRate;
				Reserved0 = motion.Reserved0;
				Reserved1 = motion.Reserved1;
			}
			return this;
		}

		public void Clear()
		{
			fType = 0u;
			StartFrame = 0f;
			EndFrame = 0f;
			nSubmotion = 0;
			pSubmotion = null;
			FrameRate = 0f;
			Reserved0 = 0u;
			Reserved1 = 0u;
		}

		public static NNS_MOTION Read(BinaryReader reader, long data0Pos)
		{
			NNS_MOTION nNS_MOTION = new NNS_MOTION();
			nNS_MOTION.fType = reader.ReadUInt32();
			nNS_MOTION.StartFrame = reader.ReadSingle();
			nNS_MOTION.EndFrame = reader.ReadSingle();
			nNS_MOTION.nSubmotion = reader.ReadInt32();
			uint num = reader.ReadUInt32();
			if (num != 0)
			{
				long position = reader.BaseStream.Position;
				reader.BaseStream.Seek(data0Pos + num, SeekOrigin.Begin);
				nNS_MOTION.pSubmotion = new NNS_SUBMOTION[nNS_MOTION.nSubmotion];
				for (int i = 0; i < nNS_MOTION.nSubmotion; i++)
				{
					nNS_MOTION.pSubmotion[i] = NNS_SUBMOTION.Read(reader, nNS_MOTION.fType & 0x1F, data0Pos);
				}
				reader.BaseStream.Seek(position, SeekOrigin.Begin);
			}
			nNS_MOTION.FrameRate = reader.ReadSingle();
			nNS_MOTION.Reserved0 = reader.ReadUInt32();
			nNS_MOTION.Reserved1 = reader.ReadUInt32();
			return nNS_MOTION;
		}
	}

