	public class AMS_FS
	{
		public string dir;

		public int count;

		public string[] files;

		public sbyte[] types;

		public sbyte[] flag;

		public sbyte type;

		public byte[] data;

		public int[] offsets;

		public int[] lengths;

		public sbyte stat;

		public string file_name;

		public Stream stream;

		public FsBackgroundReadComplete callback;

		public AMS_AMB_HEADER amb_header;

		public static explicit operator AMS_AMB_HEADER(AMS_FS fs)
		{
			return readAMBFile(fs);
		}

		public void makeAmbHeader()
		{
			amb_header = new AMS_AMB_HEADER();
			amb_header.dir = dir;
			amb_header.file_num = count;
			amb_header.files = new string[files.Length];
			amb_header.types = new sbyte[types.Length];
			amb_header.flag = new sbyte[flag.Length];
			amb_header.offsets = new int[files.Length];
			amb_header.lengths = new int[files.Length];
			amb_header.data = data;
			amb_header.buf = new object[count];
			Array.Copy(files, 0, amb_header.files, 0, files.Length);
			Buffer.BlockCopy(types, 0, amb_header.types, 0, types.Length);
			Buffer.BlockCopy(flag, 0, amb_header.flag, 0, flag.Length);
			Buffer.BlockCopy(offsets, 0, amb_header.offsets, 0, offsets.Length * 4);
			Buffer.BlockCopy(lengths, 0, amb_header.lengths, 0, lengths.Length * 4);
			amPreLoadAmbItems(amb_header);
		}
	}

