	public class CriAuPlayer
	{
		public const int TYPE_FX = 0;

		public const int TYPE_BGM = 1;

		public const int STOP_MODE_RELEASE = 0;

		public const int STOP_MODE_IMMEDIATE = 1;

		public const int STATUS_STOP = 0;

		public const int STATUS_PREP = 1;

		public const int STATUS_PLAYING = 2;

		public const int STATUS_PLAYEND = 3;

		public const int STATUS_ERROR = 4;

		private const float NON_AISAC = -1000f;

		public MediaState m_stGMState;

		public float m_fBGVolume;

		public static string m_ActiveSong;

		public int type;

		public bool status_paused;

		public string se_name;

		private string aisac;

		public int cue = -1;

		private int activefx = -1;

		private float[] volume;

		public bool m_bLoop;

		private float pitch;

		public int status;

		public SoundEffectInstance[] sound;

		private SoundEffect m_sndEffect;

		private AISAC_LIST[] aisac_list;

		private float oldAisacParam = -1000f;

		private int effectscount;

		public static Song m_songBGM;

		public CriAuPlayer()
		{
			status = 0;
			cue = -1;
		}

		public static uint GetCueId(string name)
		{
			SOUND_TABLE sOUND_TABLE = sound_fx_list[name];
			return (uint)sOUND_TABLE.cue;
		}

		public static string GetCueName(uint id)
		{
			foreach (KeyValuePair<string, SOUND_TABLE> item in sound_fx_list)
			{
				if (item.Value.cue == id)
				{
					return item.Key;
				}
			}
			return null;
		}

		public void SetPitch(float val)
		{
			pitch = val;
		}

		public void SetAisac(string s, float val)
		{
			if (type == 0)
			{
				Pause((double)val < 0.1);
			}
		}

		internal int GetStatus()
		{
			return status;
		}

		internal void Stop()
		{
			if (type == 0)
			{
				activefx = 0;
				status_paused = false;
				for (int i = 0; i < effectscount; i++)
				{
					if (sound[i] != null)
					{
						sound[i].Stop();
					}
				}
				status = 0;
				status_paused = false;
			}
			else
			{
				m_stGMState = MediaState.Stopped;
				if (se_name != null && se_name == m_ActiveSong)
				{
					MediaPlayer.Stop();
				}
				status = 0;
			}
			oldAisacParam = -1000f;
		}

		internal void Update()
		{
			bool flag = true;
			if (type == 0)
			{
				if (cue == 128)
				{
					if (status == 2 && !status_paused)
					{
						if (sound[0].State != SoundState.Stopped || sound[1].State != SoundState.Paused)
						{
							flag = ((sound[0].State == SoundState.Stopped && sound[1].State == SoundState.Stopped) ? true : false);
						}
						else
						{
							activefx = 1;
							sound[1].Play();
							flag = false;
						}
					}
					else
					{
						flag = false;
					}
					sound[activefx].Volume = volume[0];
				}
				else
				{
					for (int i = 0; i < effectscount; i++)
					{
						if (sound[i] != null)
						{
							sound[i].Volume = volume[i];
							if (status != 2 || sound[i].State != SoundState.Stopped)
							{
								flag = false;
								break;
							}
						}
					}
				}
				if (flag)
				{
					status = 3;
				}
			}
			if (type == 1)
			{
				if (m_ActiveSong == se_name && m_fBGVolume != volume[0])
				{
					MediaPlayer.Volume = volume[0];
					m_fBGVolume = volume[0];
				}
				if (status != 2 || m_stGMState != MediaState.Stopped)
				{
					flag = false;
				}
				if (flag)
				{
					status = 3;
				}
			}
		}

		internal void Stop(int mode)
		{
			Stop();
			if (mode == 0)
			{
				ReleaseCue();
			}
		}

		internal void Pause(bool pause)
		{
			if (type == 0)
			{
				if (cue == 128)
				{
					if (sound[activefx] != null)
					{
						if (pause)
						{
							sound[activefx].Pause();
						}
						else
						{
							sound[activefx].Resume();
						}
					}
				}
				else
				{
					for (int i = 0; i < effectscount; i++)
					{
						if (sound[i] != null)
						{
							if (pause)
							{
								sound[i].Pause();
							}
							else
							{
								sound[i].Resume();
							}
						}
					}
				}
				status_paused = pause;
			}
			else if (pause)
			{
				m_stGMState = MediaState.Paused;
				if (se_name == m_ActiveSong)
				{
					MediaPlayer.Pause();
				}
			}
			else if (m_ActiveSong != se_name)
			{
				string text = se_name;
				se_name = null;
				SetCue(text);
				Play();
			}
			else
			{
				m_stGMState = MediaState.Playing;
				MediaPlayer.Resume();
			}
		}

		internal void SetVolume(float volume)
		{
			if (aisac != null)
			{
				return;
			}
			if (type == 0)
			{
				for (int i = 0; i < effectscount; i++)
				{
					if (sound[i] != null)
					{
						this.volume[i] = volume;
						sound[i].Volume = volume;
					}
				}
			}
			else if (m_ActiveSong == se_name && m_fBGVolume != volume)
			{
				m_fBGVolume = volume;
				this.volume[0] = volume;
				MediaPlayer.Volume = volume;
			}
		}

		public static int LoadSound(string fileName, bool loop, ref int loopStart, ref int loopEnd, out byte[] byteArray, ref int sampleRate, ref int channels, bool bgMusic)
		{
			byteArray = null;
			if (!bgMusic && cacheFxSounds.ContainsKey(fileName))
			{
				return 0;
			}
			int result = 0;
			using (Stream stream = GameData.OpenStream("Content\\SOUND\\" + fileName + ".wav"))
			{
				using (BinaryReader binaryReader = new BinaryReader(stream))
				{
					if (!bgMusic)
					{
						SoundEffect value = SoundEffect.FromStream(stream);
						cacheFxSounds.Add(fileName, value);
					}
					else
					{
						binaryReader.ReadInt32();
						binaryReader.ReadInt32();
						binaryReader.ReadInt32();
						binaryReader.ReadInt32();
						int num = binaryReader.ReadInt32();
						binaryReader.ReadInt16();
						channels = binaryReader.ReadInt16();
						sampleRate = binaryReader.ReadInt32();
						binaryReader.ReadInt32();
						int num2 = binaryReader.ReadInt16();
						binaryReader.ReadInt16();
						if (num == 18)
						{
							int count = binaryReader.ReadInt16();
							binaryReader.ReadBytes(count);
						}
						binaryReader.ReadInt32();
						int num3 = binaryReader.ReadInt32();
						byteArray = binaryReader.ReadBytes(num3);
						result = num3;
						if (loop && loopEnd == 0)
						{
							loopEnd = byteArray.Length;
						}
						loopStart += loopStart % num2;
						loopEnd -= loopEnd % num2;
					}
				}
			}
			return result;
		}

		internal void SetCue(string se_name)
		{
			try
			{
				while (this.se_name != null)
				{
					if (this.se_name != se_name)
					{
						this.se_name = null;
						continue;
					}
					Stop();
					status = 1;
					return;
				}
				SOUND_TABLE sOUND_TABLE = null;
				if (sound_fx_list.ContainsKey(se_name))
				{
					cue = -1;
					type = 0;
					sOUND_TABLE = sound_fx_list[se_name];
				}
				else if (sound_bgm_list.ContainsKey(se_name))
				{
					type = 1;
					sOUND_TABLE = sound_bgm_list[se_name];
				}
				if (sOUND_TABLE != null)
				{
					effectscount = sOUND_TABLE.count;
					this.se_name = se_name;
					aisac_list = sOUND_TABLE.asiac;
					cue = sOUND_TABLE.cue;
					sound = new SoundEffectInstance[effectscount];
					volume = new float[effectscount];
					if (type == 0)
					{
						activefx = 0;
						status_paused = false;
						for (int i = 0; i < effectscount; i++)
						{
							if (cacheFxSounds.ContainsKey(sOUND_TABLE.filename[i]))
							{
								SoundEffect soundEffect = (m_sndEffect = cacheFxSounds[sOUND_TABLE.filename[i]]);
								if (sOUND_TABLE.loop[i])
								{
									SoundEffectInstance soundEffectInstance = null;
									try
									{
										soundEffectInstance = soundEffect.CreateInstance();
									}
									catch (Exception)
									{
										GC.Collect();
										try
										{
											soundEffectInstance = soundEffect.CreateInstance();
										}
										catch (Exception)
										{
											status = 4;
											return;
										}
									}
									sound[i] = soundEffectInstance;
									sound[i].IsLooped = sOUND_TABLE.loop[i];
									soundEffectInstance.Volume = 0f;
									soundEffectInstance.Pitch = pitch;
									soundEffectInstance.Play();
									soundEffectInstance.Pause();
									soundEffectInstance.Volume = sOUND_TABLE.volume[i];
								}
								else
								{
									sound[i] = soundEffect.CreateInstance();
									sound[i].Volume = sOUND_TABLE.volume[i];
									sound[i].Play();
								}
							}
							else
							{
								mppAssertNotImpl();
							}
						}
					}
					else
					{
						m_songBGM = _GetPreloadedBGM(sOUND_TABLE.filename[0]);
						if (m_songBGM == null)
						{
							m_songBGM = Sonic4Ep1.pInstance.GameContent.Load<Song>("SOUND/" + sOUND_TABLE.filename[0]);
							bgmPreloadedList.Add(sOUND_TABLE.filename[0], m_songBGM);
						}
						m_ActiveSong = se_name;
						m_fBGVolume = -1f;
						m_bLoop = sOUND_TABLE.loop[0];
					}
					status = 1;
				}
				else
				{
					status = 4;
				}
			}
			catch (Exception ex3)
			{
				ex3.ToString();
				status = 4;
			}
		}

		internal void Play()
		{
			if (type == 1)
			{
				if (se_name != m_ActiveSong)
				{
					string text = se_name;
					se_name = null;
					SetCue(text);
				}
				if (se_name != null && se_name == m_ActiveSong)
				{
					try
					{
						MediaPlayer.IsRepeating = m_bLoop;
						MediaPlayer.Stop();
						m_stGMState = MediaState.Playing;
						MediaPlayer.Play(m_songBGM);
					}
					catch (UnauthorizedAccessException)
					{
						g_ao_sys_global.is_playing_device_bgm_music = true;
					}
				}
				status = 2;
				return;
			}
			if (cue == 128)
			{
				activefx = 0;
				if (sound[0] != null)
				{
					sound[activefx].Resume();
				}
			}
			else
			{
				for (int i = 0; i < effectscount; i++)
				{
					if (sound[i] != null)
					{
						sound[i].Pitch = pitch;
						sound[i].Resume();
					}
					else if (m_sndEffect != null)
					{
						m_sndEffect.Play();
					}
				}
			}
			status = 2;
		}

		internal void ReleaseCue()
		{
			se_name = null;
			aisac = null;
			activefx = -1;
			status_paused = false;
			if (type == 0)
			{
				for (int i = 0; i < effectscount; i++)
				{
					if (sound[i] != null)
					{
						sound[i].Stop();
						sound[i].Dispose();
						sound[i] = null;
					}
				}
				cue = -1;
				status = 0;
			}
			else
			{
				m_stGMState = MediaState.Stopped;
				if (se_name != null && se_name == m_ActiveSong)
				{
					MediaPlayer.Stop();
				}
				m_ActiveSong = null;
				status = 0;
			}
			oldAisacParam = -1000f;
		}

		internal void ResetParameters()
		{
			for (int i = 0; i < effectscount; i++)
			{
				volume[i] = 1f;
				aisac = null;
			}
		}

		internal bool IsPaused()
		{
			if (type == 0)
			{
				if (cue == 128)
				{
					return status_paused;
				}
				int num = 0;
				if (num < effectscount && sound[num] != null)
				{
					return sound[num].State == SoundState.Paused;
				}
				return false;
			}
			return m_stGMState == MediaState.Paused;
		}

		internal int GetNumPlayedSamples()
		{
			return 1;
		}

		internal void Destroy()
		{
			ReleaseCue();
		}

