	public struct AOS_TVX_VERTEX
	{
		public float x;

		public float y;

		public float z;

		public uint c;

		public float u;

		public float v;

		public static uint SizeBytes
		{
			get
			{
				return 32u;
			}
		}

		public AOS_TVX_VERTEX(byte[] data, int offset)
		{
			x = MppBitConverter.ToSingle(data, offset);
			y = MppBitConverter.ToSingle(data, offset + 4);
			z = MppBitConverter.ToSingle(data, offset + 8);
			c = MppBitConverter.ToUInt32(data, offset + 12);
			u = MppBitConverter.ToSingle(data, offset + 16);
			v = MppBitConverter.ToSingle(data, offset + 20);
		}
	}

