	public class TVX_FILE
	{
		public TVXS_HEADER header;

		public TVXS_TEXTURE[] textures;

		public AOS_TVX_VERTEX[][] vertexes;

		public TVX_FILE(AmbChunk data)
		{
			header = new TVXS_HEADER(data.array, data.offset);
			textures = new TVXS_TEXTURE[header.tex_num];
			vertexes = new AOS_TVX_VERTEX[header.tex_num][];
			for (int i = 0; i < textures.Length; i++)
			{
				int offset = (int)(header.tex_tbl_ofst + i * TVXS_TEXTURE.SizeBytes) + data.offset;
				textures[i] = new TVXS_TEXTURE(data.array, offset);
				vertexes[i] = new AOS_TVX_VERTEX[textures[i].vtx_num];
				for (int j = 0; j < textures[i].vtx_num; j++)
				{
					offset = (int)(textures[i].vtx_tbl_ofst + j * (int)AOS_TVX_VERTEX.SizeBytes) + data.offset;
					vertexes[i][j] = new AOS_TVX_VERTEX(data.array, offset);
				}
			}
		}
	}

