	public class NNS_TEXFILE
	{
		public uint fType;

		public string Filename;

		public ushort MinFilter;

		public ushort MagFilter;

		public uint GlobalIndex;

		public uint Bank;

		public static NNS_TEXFILE Read(BinaryReader reader, long data0Pos)
		{
			NNS_TEXFILE nNS_TEXFILE = new NNS_TEXFILE();
			nNS_TEXFILE.fType = reader.ReadUInt32();
			uint num = reader.ReadUInt32();
			nNS_TEXFILE.MinFilter = reader.ReadUInt16();
			nNS_TEXFILE.MagFilter = reader.ReadUInt16();
			nNS_TEXFILE.GlobalIndex = reader.ReadUInt32();
			nNS_TEXFILE.Bank = reader.ReadUInt32();
			if (num != 0)
			{
				long position = reader.BaseStream.Position;
				reader.BaseStream.Seek(data0Pos + num, SeekOrigin.Begin);
				StringBuilder stringBuilder = new StringBuilder();
				byte value;
				while ((value = reader.ReadByte()) != 0)
				{
					stringBuilder.Append((char)value);
				}
				nNS_TEXFILE.Filename = stringBuilder.ToString().ToUpper();
				reader.BaseStream.Seek(position, SeekOrigin.Begin);
			}
			return nNS_TEXFILE;
		}
	}

	public class NNS_TEXFILELIST
	{
		public int nTex;

		public NNS_TEXFILE[] pTexFileList;

		public static NNS_TEXFILELIST Read(BinaryReader reader, long data0Pos)
		{
			NNS_TEXFILELIST nNS_TEXFILELIST = new NNS_TEXFILELIST();
			nNS_TEXFILELIST.nTex = reader.ReadInt32();
			nNS_TEXFILELIST.pTexFileList = new NNS_TEXFILE[nNS_TEXFILELIST.nTex];
			uint num = reader.ReadUInt32();
			reader.BaseStream.Seek(data0Pos + num, SeekOrigin.Begin);
			for (int i = 0; i < nNS_TEXFILELIST.nTex; i++)
			{
				nNS_TEXFILELIST.pTexFileList[i] = NNS_TEXFILE.Read(reader, data0Pos);
			}
			return nNS_TEXFILELIST;
		}
	}

