	public abstract class ITaskLinkAsv : ITaskAsv
	{
		protected class EDestructorCbType
		{
			public const int DetachTask = 0;

			public const int MtTaskClear = 1;

			public const int Max = 2;

			public const int None = 3;
		}

		private class SWork
		{
			public ITaskLinkAsv owner;
		}

		private AMS_TCB m_task_tcb;

		public void AttachTask()
		{
			AttachTask("", 4096u, 0u, 2u, 0, 1u, uint.MaxValue);
		}

		public void AttachTask(string name)
		{
			AttachTask(name, 4096u, 0u, 2u, 0, 1u, uint.MaxValue);
		}

		public void AttachTask(string name, uint priority)
		{
			AttachTask(name, priority, 0u, 2u, 0, 1u, uint.MaxValue);
		}

		public void AttachTask(string name, uint priority, uint user)
		{
			AttachTask(name, priority, user, 2u, 0, 1u, uint.MaxValue);
		}

		public void AttachTask(string name, uint priority, uint user, uint attribute)
		{
			AttachTask(name, priority, user, attribute, 0, 1u, uint.MaxValue);
		}

		public void AttachTask(string name, uint priority, uint user, uint attribute, int group)
		{
			AttachTask(name, priority, user, attribute, group, 1u, uint.MaxValue);
		}

		public void AttachTask(string name, uint priority, uint user, uint attribute, int group, uint stall_mask)
		{
			AttachTask(name, priority, user, attribute, group, stall_mask, uint.MaxValue);
		}

		public void AttachTask(string name, uint priority, uint user, uint attribute, int group, uint stall_mask, uint run_mask)
		{
			DetachTask();
			m_task_tcb = amTaskMake(procedure, destructor, priority, user, attribute, name, stall_mask, group, run_mask);
			m_task_tcb.work = new SWork();
			SWork sWork = (SWork)amTaskGetWork(m_task_tcb);
			sWork.owner = this;
		}

		public void DetachTask()
		{
			if (m_task_tcb != null)
			{
				amTaskSetDestructor(m_task_tcb, null);
				amTaskDelete(m_task_tcb);
				TaskDestructor(0);
				m_task_tcb = null;
			}
		}

		public static ITaskLinkAsv CastFromTaskTcb(AMS_TCB tcb)
		{
			if (new TaskProc(procedure) == tcb.procedure || new TaskProc(destructor) == tcb.destructor)
			{
				SWork sWork = (SWork)amTaskGetWork(tcb);
				if (sWork.owner != null && sWork.owner.m_task_tcb == tcb)
				{
					return sWork.owner;
				}
			}
			return null;
		}

		public override AMS_TCB GetTaskTcb()
		{
			return m_task_tcb;
		}

		public bool IsTask()
		{
			return null != m_task_tcb;
		}

		protected virtual void TaskDestructor(int type)
		{
		}

		private void TcbLinkDestructorCb()
		{
			TaskDestructor(1);
			m_task_tcb = null;
		}

		private static void procedure(AMS_TCB tcb)
		{
			SWork sWork = (SWork)amTaskGetWork(tcb);
			sWork.owner.operator_brackets();
		}

		private static void destructor(AMS_TCB tcb)
		{
			SWork sWork = (SWork)amTaskGetWork(tcb);
			sWork.owner.TcbLinkDestructorCb();
		}
	}

