		public class SAction
		{
			public class BFlag
			{
				public enum ESAction
				{
					NoUpdate,
					NoDraw,
					SortDraw,
					Max,
					None
				}
			}

			public AOS_ACTION act;

			public AOS_TEXTURE tex;

			public bool[] flag = new bool[3];

			public CArray2<float> scale;

			public CArray3<float> pos;

			public AOS_ACT_COL color;

			public void AcmInit()
			{
				pos = CArray3<float>.initializer(0f, 0f, 0f);
				scale = CArray2<float>.initializer(1f, 1f);
				color.c = uint.MaxValue;
				act.sprite.texlist = tex.texlist;
			}

			public void Update()
			{
				AoActAcmPush();
				float frame = (flag[0] ? 0f : 1f);
				AoActSetTexture(AoTexGetTexList(tex));
				if (!CArray2<float>.initializer(1f, 1f).equals(scale))
				{
					AoActAcmApplyScale(scale.x, scale.y);
				}
				if (!CArray3<float>.initializer(0f, 0f, 0f).equals(pos))
				{
					AoActAcmApplyTrans(pos.x, pos.y, pos.z);
				}
				if (-1 != (int)color.c)
				{
					AoActAcmApplyColor(color);
				}
				AoActUpdate(act, frame);
				AoActAcmPop();
			}

			public void Draw()
			{
				if (!flag[1])
				{
					if (flag[2])
					{
						AoActSortRegAction(act);
					}
					else
					{
						AoActDraw(act);
					}
				}
			}
		}

