		private void fileLoadingStart()
		{
			m_fs[0] = amFsReadBackground(c_global);
			int num = GsEnvGetLanguage();
			m_fs[1] = amFsReadBackground(c_lang[num]);
			m_flag[3] = true;
			m_pTaskLink.AttachTask("dmBuyScreen::Load", c_priority, c_user, c_attribute);
			SetProc(fileLoading);
