		private void fileLoading()
		{
			bool flag = true;
			for (int i = 0; i < 2; i++)
			{
				if (!amFsIsComplete(m_fs[i]))
				{
					flag = false;
					break;
				}
			}
			if (!flag)
			{
				return;
			}
			for (int j = 0; j < 2; j++)
			{
				m_file[j] = m_fs[j];
			}
			for (uint num = 0u; num < 6; num++)
			{
				SLocalUnfoldTable sLocalUnfoldTable = c_local_unfold_table[num];
				int file = (int)sLocalUnfoldTable.file;
				int num2 = 2;
				if (file < num2)
				{
					string sPath;
					AmbChunk ambChunk = amBindGet(m_fs[(int)sLocalUnfoldTable.file], (int)sLocalUnfoldTable.index, out sPath);
					object obj = ((!AoActIsAma(ambChunk.array, ambChunk.offset)) ? ((object)readAMBFile(ambChunk)) : ((object)readAMAFile(ambChunk)));
					m_file[num] = obj;
				}
			}
			m_flag[4] = true;
			m_pTaskLink.DetachTask();
		}

		private void creatingStart()
		{
			EFile.EFileEnum[] array = new EFile.EFileEnum[2]
			{
				EFile.EFileEnum.GlobalAmb,
				EFile.EFileEnum.LangAmb
			};
			for (int i = 0; i < 2; i++)
			{
				AoTexBuild(m_tex[i], (AMS_AMB_HEADER)m_file[(int)array[i]]);
				AoTexLoad(m_tex[i]);
			}
			m_flag[5] = true;
			m_pTaskLink.AttachTask("dmBuyScreen::Build", c_priority, c_user, c_attribute);
