		private void fadeInStart()
		{
			for (uint num = 0u; num < c_local_create_action_table.Length; num++)
			{
				SLocalCreateActionTable sLocalCreateActionTable = c_local_create_action_table[num];
				A2S_AMA_HEADER ama = readAMAFile(m_file[(int)sLocalCreateActionTable.file]);
				SAction sAction = m_act[num];
				sAction.act = AoActCreate(ama, (uint)sLocalCreateActionTable.idx);
				sAction.tex = m_tex[(int)sLocalCreateActionTable.tex];
				sAction.flag[0] = true;
				sAction.AcmInit();
			}
			for (uint num2 = 0u; num2 < c_local_create_trg_table.Length; num2++)
			{
				SAction sAction2 = m_act[(int)c_local_create_trg_table[num2]];
				CTrgAoAction cTrgAoAction = m_trg[num2];
				cTrgAoAction.Create(sAction2.act);
			}
			IzFadeInitEasy(0u, 0u, 30f);
			m_flag[7] = true;
			m_pTaskLink.AttachTask("dmBuyScreen::Execute", c_priority, c_user, c_attribute);
			SetProc(fadeIn);
		}

		private void fadeIn()
		{
			if (IzFadeIsEnd())
			{
				IzFadeExit();
				waitStart();
			}
		}

		private void waitStart()
		{
			SetProc(wait);
		}

		private void wait()
		{
			bool flag = false;
			int i = 0;
			for (int num = _am_tp_touch.Length; i < num; i++)
			{
				if (amTpIsTouchOn(i))
				{
					flag = true;
					break;
				}
			}
			if (!flag || 60 < GetCount())
			{
				selectStart();
			}
		}

		private void selectStart()
		{
			SetProc(select);
		}

		private void select()
		{
			int num = -1;
			for (int i = 0; i < 2; i++)
			{
				CTrgAoAction cTrgAoAction = m_trg[i];
				float frame;
				if (!cTrgAoAction.GetState(0u)[10] || !cTrgAoAction.GetState(0u)[1])
				{
					frame = ((!cTrgAoAction.GetState(0u)[0]) ? 0f : 2f);
				}
				else
				{
					frame = 1f;
					num = i;
				}
				for (uint num2 = 0u; num2 < arrayof(c_btn_action_table[i]); num2++)
				{
					EAct.Type[] array = c_btn_action_table[i];
					AoActSetFrame(m_act[(int)array[num2]].act, frame);
				}
			}
			if (-1 != num)
			{
				EAct.Type[] array2 = c_btn_action_table[num];
				for (int j = (int)array2[0]; j < (int)(array2[2] + 1); j++)
				{
					m_act[j].flag[0] = false;
				}
				DmSoundPlaySE("Ok");
				m_result[0] = TrgIdxToReturnIdx(num);
				enterEfctStart();
			}
		}

		private void enterEfctStart()
		{
			SetProc(enterEfct);
		}

		private void enterEfct()
		{
			if (30 >= GetCount())
			{
				return;
			}
			if (m_result[0] == 0)
			{
				XBOXLive.showGuide();
				if (!Guide.IsVisible)
				{
					XBOXLive.isTrial(true);
					fadeOutStart();
				}
			}
			else
			{
				fadeOutStart();
			}
		}

		private void fadeOutStart()
		{
			IzFadeInitEasy(0u, 1u, 30f);
			SetProc(fadeOut);
		}

		private void fadeOut()
		{
			if (IzFadeIsEnd())
			{
				for (int i = 0; i < 9; i++)
				{
					AoActDelete(m_act[i].act);
				}
				m_flag[7] = false;
				m_pTaskLink.DetachTask();
			}
		}

		private void releasingStart()
		{
			for (int i = 0; i < 2; i++)
			{
				AoTexRelease(m_tex[i]);
			}
			m_pTaskLink.AttachTask("dmBuyScreen::Flush", c_priority, c_user, c_attribute);
			SetProc(releasing);
		}

		public static void releasingS(object pArg)
		{
			((CMain)pArg).releasing();
		}

		private void releasing()
		{
			bool flag = true;
			for (int i = 0; i < 2; i++)
			{
				if (!AoTexIsReleased(m_tex[i]))
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				m_flag[5] = false;
				m_flag[6] = false;
				m_pTaskLink.DetachTask();
			}
		}

