	public class CPadPolarHandle
	{
		private class BFlag
		{
			public const int Setup = 0;

			public const int Max = 1;

			public const int None = 2;
		}

		private bool[] m_flag = new bool[1];

		private CArray4<float> m_area;

		private CArray2<float> m_center;

		private int m_focus;

		private CArray2<float> m_prev;

		private int m_around;

		private float m_value;

		private float m_zero_point;

		public static CPadPolarHandle p_instance = null;

		public static readonly float c_pi = (float)Math.Atan2(0.0, -1.0) * 2f;

		public static CPadPolarHandle CreateInstance()
		{
			if (p_instance == null)
			{
				p_instance = new CPadPolarHandle();
			}
			return p_instance;
		}

		public bool Create()
		{
			m_area.left = -Sonic4Ep1.WideExtra2D;
			m_area.top = 0f;
			m_area.right = AMD_SCREEN_2D_WIDTH + Sonic4Ep1.WideExtra2D;
			m_area.bottom = 320f;
			m_center.x = AMD_SCREEN_2D_WIDTH * 0.5f;
			m_center.y = 144f;
			return create();
		}

		public bool Create(CArray4<float> area)
		{
			m_area = area;
			m_center.x = (m_area.left + m_area.right) * 0.5f;
			m_center.y = (m_area.top + m_area.bottom) * 0.5f;
			return create();
		}

		public bool Create(float[] area)
		{
			m_area.left = area[0];
			m_area.top = area[1];
			m_area.right = area[2];
			m_area.bottom = area[3];
			m_center.x = (m_area.left + m_area.right) * 0.5f;
			m_center.y = (m_area.top + m_area.bottom) * 0.5f;
			return create();
		}

		public bool Create(float area_left, float area_top, float area_right, float area_bottom)
		{
			m_area.left = area_left;
			m_area.top = area_top;
			m_area.right = area_right;
			m_area.bottom = area_bottom;
			m_center.x = (m_area.left + m_area.right) * 0.5f;
			m_center.y = (m_area.top + m_area.bottom) * 0.5f;
			return create();
		}

		public bool Create(CArray2<float> center)
		{
			m_area.left = -Sonic4Ep1.WideExtra2D;
			m_area.top = 0f;
			m_area.right = AMD_SCREEN_2D_WIDTH + Sonic4Ep1.WideExtra2D;
			m_area.bottom = 320f;
			m_center = center;
			return create();
		}

		public bool Create(float center_x, float center_y)
		{
			m_area.left = -Sonic4Ep1.WideExtra2D;
			m_area.top = 0f;
			m_area.right = AMD_SCREEN_2D_WIDTH + Sonic4Ep1.WideExtra2D;
			m_area.bottom = 320f;
			m_center.x = center_x;
			m_center.y = center_y;
			return create();
		}

		public bool Create(CArray4<float> area, CArray2<float> center)
		{
			m_area = area;
			m_center = center;
			return create();
		}

		public bool Create(float[] area, float[] center)
		{
			m_area.left = area[0];
			m_area.top = area[1];
			m_area.right = area[2];
			m_area.bottom = area[3];
			m_center.x = center[0];
			m_center.y = center[1];
			return create();
		}

		public bool Create(float area_left, float area_top, float area_right, float area_bottom, float center_x, float center_y)
		{
			m_area.left = area_left;
			m_area.top = area_top;
			m_area.right = area_right;
			m_area.bottom = area_bottom;
			m_center.x = center_x;
			m_center.y = center_y;
			return create();
		}

		public void Release()
		{
			if (m_flag[0])
			{
				m_flag[0] = false;
			}
		}

		public bool IsValid()
		{
			return m_flag[0];
		}

		public void Update()
		{
			if (!m_flag[0])
			{
				return;
			}
			if (-1 == m_focus)
			{
				int pushTpIndex = getPushTpIndex();
				if (0 <= pushTpIndex)
				{
					m_focus = pushTpIndex;
					float currentValue = getCurrentValue();
					m_zero_point += currentValue;
				}
			}
			else if (amTpIsTouchOn(m_focus))
			{
				float currentValue2 = getCurrentValue();
				m_value = currentValue2 - m_zero_point;
			}
			else if (amTpIsTouchPull(m_focus))
			{
				m_zero_point = 0f - m_value;
				m_focus = -1;
			}
		}

		public float GetFloatValue()
		{
			return m_value;
		}

		public int GetAngle32Value()
		{
			return NNM_RADtoA32(m_value);
		}

		public bool IsFocus()
		{
			return -1 != m_focus;
		}

		public int GetFocusTpIndex()
		{
			return m_focus;
		}

		public void SetValue(float value)
		{
			m_zero_point = getCurrentValue() - value;
			m_value = value;
		}

		public void SetValue(int value)
		{
			SetValue(NNM_A32toRAD(value));
		}

		private bool create()
		{
			Release();
			m_value = 0f;
			m_focus = getOnTpIndex();
			if (0 <= m_focus)
			{
				float currentValue = getCurrentValue();
				m_zero_point = currentValue;
			}
			else
			{
				m_zero_point = 0f;
			}
			m_flag[0] = true;
			return true;
		}

		private float getCurrentValue()
		{
			if (0 <= m_focus && amTpIsTouchOn(m_focus))
			{
				ushort[] array = _am_tp_touch[m_focus].on;
				if (amTpIsTouchPush(m_focus))
				{
					m_around = 0;
				}
				else if ((float)(int)array[0] <= m_center.x && m_prev.x <= m_center.x)
				{
					if (m_center.y <= (float)(int)array[1])
					{
						if (m_prev.y < m_center.y)
						{
							m_around--;
						}
					}
					else if (m_center.y <= m_prev.y)
					{
						m_around++;
					}
				}
				m_prev = CArray2<float>.initializer((int)array[0], (int)array[1]);
				CArray2<float> cArray = _SubrtactArray2(m_prev, m_center);
				return (float)Math.Atan2(cArray.y, cArray.x) + c_pi * (float)m_around;
			}
			return 0f;
		}

		private int getOnTpIndex()
		{
			int result = -1;
			int i = 0;
			for (int num = _am_tp_touch.Length; i < num; i++)
			{
				if (amTpIsTouchOn(i) && isHit(_am_tp_touch[i].on))
				{
					result = i;
					break;
				}
			}
			return result;
		}

		private int getPushTpIndex()
		{
			int result = -1;
			int i = 0;
			for (int num = _am_tp_touch.Length; i < num; i++)
			{
				if (amTpIsTouchPush(i) && isHit(_am_tp_touch[i].push))
				{
					result = i;
					break;
				}
			}
			return result;
		}

		private bool isHit(ushort[] point)
		{
			return isHit(CArray2<float>.initializer((int)point[0], (int)point[1]));
		}

		private bool isHit(CArray2<float> pos)
		{
			bool result = false;
			if (!(pos.x < m_area.left) && !(m_area.right < pos.x) && !(pos.y < m_area.top) && !(m_area.bottom < pos.y))
			{
				result = true;
			}
			return result;
		}
	}

