	public class NNS_MATRIXSTACK
	{
		private readonly NNS_MATRIX identity = NNS_MATRIX.CreateIdentity();

		private List<NNS_MATRIX> stack;

		private NNS_MATRIX invert;

		public NNS_MATRIXSTACK(uint uiSize)
		{
			stack = new List<NNS_MATRIX>((int)uiSize);
		}

		public NNS_MATRIXSTACK()
		{
			stack = new List<NNS_MATRIX>(16);
		}

		public void push(NNS_MATRIX matrix)
		{
			invert = null;
			stack.Add(matrix);
		}

		public NNS_MATRIX pop()
		{
			invert = null;
			int index = stack.Count - 1;
			NNS_MATRIX result = stack[index];
			stack.RemoveAt(index);
			return result;
		}

		public NNS_MATRIX get()
		{
			if (stack.Count == 0)
			{
				return identity;
			}
			return stack[stack.Count - 1];
		}

		public void set(NNS_MATRIX mtx)
		{
			if (stack.Count > 0)
			{
				stack[stack.Count - 1] = mtx;
			}
			else
			{
				push(mtx);
			}
		}

		public void clear()
		{
			stack.Clear();
		}

		public NNS_MATRIX getInvert()
		{
			if (invert == null)
			{
				NNS_MATRIX src = get();
				invert = GlobalPool<NNS_MATRIX>.Alloc();
				nnInvertMatrix(invert, src);
			}
			return invert;
		}
	}

