	public class Vector3_VertexData : OpenGL.GLVertexData
	{
		private Vector3[] data_;

		protected OpenGL.GLVertexElementType[] compType_ = new OpenGL.GLVertexElementType[1];

		public OpenGL.GLVertexElementType[] DataComponents
		{
			get
			{
				return compType_;
			}
		}

		public int VertexCount
		{
			get
			{
				return data_.Length;
			}
		}

		public Vector3_VertexData(Vector3[] data)
		{
			data_ = data;
		}

		public void ExtractTo(OpenGL.Vertex[] dst, int count)
		{
			for (int i = 0; i < count; i++)
			{
				dst[i].Position = data_[i];
			}
		}

		public void ExtractTo(OpenGL.VertexPosTexColNorm[] dst, int dstOffset, int count)
		{
			for (int i = 0; i < count; i++)
			{
				dst[i + dstOffset].Position = data_[i];
			}
		}
	}

	public class GLVertexBuffer_ : OpenGL.GLVertexData
	{
		private OpenGL.GLVertexElementType[] elementTypes_;

		private NNS_VTXARRAY_GL posArray_;

		private NNS_VTXARRAY_GL normArray_;

		private NNS_VTXARRAY_GL colArray_;

		private NNS_VTXARRAY_GL texCoord0Array_;

		private NNS_VTXARRAY_GL texCoord1Array_;

		private NNS_VTXARRAY_GL blWeightArray_;

		private NNS_VTXARRAY_GL blIndexArray_;

		private NNS_VTXLIST_GL_DESC pVtxDesc_;

		public OpenGL.GLVertexElementType[] DataComponents
		{
			get
			{
				return elementTypes_;
			}
		}

		public int VertexCount
		{
			get
			{
				return pVtxDesc_.nVertex;
			}
		}

		public GLVertexBuffer_(NNS_VTXLIST_GL_DESC pVtxDesc)
		{
			pVtxDesc_ = pVtxDesc;
			elementTypes_ = new OpenGL.GLVertexElementType[pVtxDesc_.nArray];
			for (int i = 0; i < pVtxDesc_.nArray; i++)
			{
				switch (pVtxDesc_.pArray[i].Type)
				{
				case 1u:
					posArray_ = pVtxDesc_.pArray[i];
					elementTypes_[i] = OpenGL.GLVertexElementType.Position;
					break;
				case 8u:
					normArray_ = pVtxDesc_.pArray[i];
					elementTypes_[i] = OpenGL.GLVertexElementType.Normal;
					break;
				case 16u:
					colArray_ = pVtxDesc_.pArray[i];
					elementTypes_[i] = OpenGL.GLVertexElementType.Color;
					break;
				case 256u:
					texCoord0Array_ = pVtxDesc_.pArray[i];
					elementTypes_[i] = OpenGL.GLVertexElementType.TextureCoordinate0;
					break;
				case 512u:
					texCoord1Array_ = pVtxDesc_.pArray[i];
					elementTypes_[i] = OpenGL.GLVertexElementType.TextureCoordinate1;
					break;
				case 2u:
					blWeightArray_ = pVtxDesc_.pArray[i];
					elementTypes_[i] = OpenGL.GLVertexElementType.BlendWeight;
					break;
				case 4u:
					blIndexArray_ = pVtxDesc_.pArray[i];
					elementTypes_[i] = OpenGL.GLVertexElementType.BlendIndex;
					break;
				}
			}
		}

		public void ExtractTo(OpenGL.Vertex[] dst, int count)
		{
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			int num4 = 0;
			int num5 = 0;
			int num6 = 0;
			int num7 = 0;
			for (int i = 0; i < count; i++)
			{
				float x = posArray_.Pointer.GetFloat(num);
				float y = posArray_.Pointer.GetFloat(num + 4);
				float z = posArray_.Pointer.GetFloat(num + 8);
				dst[i].Position = new Vector3(x, y, z);
				num += posArray_.Stride;
				if (normArray_ != null)
				{
					x = normArray_.Pointer.GetFloat(num2);
					y = normArray_.Pointer.GetFloat(num2 + 4);
					z = normArray_.Pointer.GetFloat(num2 + 8);
					dst[i].Normal = new Vector3(x, y, z);
					num2 += normArray_.Stride;
				}
				if (colArray_ != null)
				{
					byte r = colArray_.Pointer[num3];
					byte g = colArray_.Pointer[num3 + 1];
					byte b = colArray_.Pointer[num3 + 2];
					byte a = colArray_.Pointer[num3 + 3];
					dst[i].Color = new Color(r, g, b, a);
					num3 += colArray_.Stride;
				}
				else
				{
					dst[i].Color = Color.White;
				}
				if (texCoord0Array_ != null)
				{
					x = texCoord0Array_.Pointer.GetFloat(num4);
					y = texCoord0Array_.Pointer.GetFloat(num4 + 4);
					dst[i].TextureCoordinate = new Vector2(x, y);
					num4 += texCoord0Array_.Stride;
				}
				if (texCoord1Array_ != null)
				{
					x = texCoord1Array_.Pointer.GetFloat(num5);
					y = texCoord1Array_.Pointer.GetFloat(num5 + 4);
					dst[i].TextureCoordinate2 = new Vector2(x, y);
					num5 += texCoord1Array_.Stride;
				}
				else
				{
					dst[i].TextureCoordinate2 = Vector2.Zero;
				}
				if (blWeightArray_ != null)
				{
					x = blWeightArray_.Pointer.GetFloat(num6);
					y = ((blWeightArray_.Size > 1) ? blWeightArray_.Pointer.GetFloat(num6 + 4) : 0f);
					z = ((blWeightArray_.Size > 2) ? blWeightArray_.Pointer.GetFloat(num6 + 8) : 0f);
					float w = ((blWeightArray_.Size > 3) ? blWeightArray_.Pointer.GetFloat(num6 + 12) : 0f);
					dst[i].BlendWeight = new Vector4(x, y, z, w);
					num6 += blWeightArray_.Stride;
				}
				else
				{
					dst[i].BlendWeight = Vector4.UnitX;
				}
				if (blIndexArray_ != null)
				{
					byte b2 = blIndexArray_.Pointer[num7];
					byte b3 = (byte)((blIndexArray_.Size > 1) ? blIndexArray_.Pointer[num7 + 1] : 0);
					byte b4 = (byte)((blIndexArray_.Size > 2) ? blIndexArray_.Pointer[num7 + 2] : 0);
					byte b5 = (byte)((blIndexArray_.Size > 3) ? blIndexArray_.Pointer[num7 + 3] : 0);
					dst[i].BlendIndices = new Byte4((int)b2, (int)b3, (int)b4, (int)b5);
					num7 += blIndexArray_.Stride;
				}
				else
				{
					dst[i].BlendIndices = default(Byte4);
				}
			}
		}

		public void ExtractTo(OpenGL.VertexPosTexColNorm[] dst, int dstOffset, int count)
		{
			throw new NotImplementedException();
		}
