	public class MatrixPool
	{
		private List<NNS_MATRIX> cache_;

		public MatrixPool()
		{
			cache_ = new List<NNS_MATRIX>();
		}

		public NNS_MATRIX Alloc()
		{
			NNS_MATRIX result;
			if (cache_.Count > 0)
			{
				int index = cache_.Count - 1;
				result = cache_[index];
				cache_.RemoveAt(index);
			}
			else
			{
				result = new NNS_MATRIX();
			}
			return result;
		}

		public void Release(NNS_MATRIX obj)
		{
			cache_.Add(obj);
		}
	}

