	public class CPadVirtualPad
	{
		private class CLocalLogic
		{
			public static float Cross(CArray2<float> p1, CArray2<float> p2)
			{
				return p1.x * p2.y - p1.y * p2.x;
			}
		}

		private class BFlag
		{
			public const int Setup = 0;

			public const int Max = 1;

			public const int None = 2;
		}

		private const int c_tp_index_max = 4;

		private static CPadVirtualPad p_instance;

		private bool[] m_flag = new bool[1];

		private CArray4<float> m_area;

		private readonly bool[] m_focus = new bool[4];

		private CCircularBuffer<ushort> m_on_flag = new CCircularBuffer<ushort>(2);

		public static CPadVirtualPad CreateInstance()
		{
			if (p_instance == null)
			{
				p_instance = new CPadVirtualPad();
			}
			return p_instance;
		}

		public bool Create()
		{
			m_area.left = -Sonic4Ep1.WideExtra2D;
			m_area.top = 0f;
			m_area.right = AMD_SCREEN_2D_WIDTH + Sonic4Ep1.WideExtra2D;
			m_area.bottom = 320f;
			return create();
		}

		public bool Create(ref CArray4<float> area)
		{
			m_area = area;
			return create();
		}

		public bool Create(ref CArray2<float> area_xy1, ref CArray2<float> area_xy2)
		{
			m_area.left = area_xy1.x;
			m_area.top = area_xy1.y;
			m_area.right = area_xy2.x;
			m_area.bottom = area_xy2.y;
			return create();
		}

		public bool Create(float[] area)
		{
			for (int i = 0; i < 4; i++)
			{
				m_area[i] = area[i];
			}
			return create();
		}

		public bool Create(float[] area_xy1, float[] area_xy2)
		{
			m_area.left = area_xy1[0];
			m_area.top = area_xy1[1];
			m_area.right = area_xy2[0];
			m_area.bottom = area_xy2[1];
			return create();
		}

		public bool Create(float area_left, float area_top, float area_right, float area_bottom)
		{
			m_area.left = area_left;
			m_area.top = area_top;
			m_area.right = area_right;
			m_area.bottom = area_bottom;
			return create();
		}

		public void Release()
		{
			if (m_flag[0])
			{
				m_flag[0] = false;
			}
		}

		public bool IsValid()
		{
			return m_flag[0];
		}

		public void Update()
		{
			if (!m_flag[0])
			{
				return;
			}
			int i = 0;
			for (int num = m_focus.Length; i < num; i++)
			{
				if (m_focus[i])
				{
					if (!amTpIsTouchOn(i) || !isHit(_am_tp_touch[i].on))
					{
						m_focus[i] = false;
					}
				}
				else if (amTpIsTouchOn(i) && isHit(_am_tp_touch[i].on))
				{
					m_focus[i] = true;
				}
			}
			ushort num2 = 0;
			int j = 0;
			for (int num3 = m_focus.Length; j < num3; j++)
			{
				if (m_focus[j])
				{
					num2 |= getOnFlag(_am_tp_touch[j].on);
				}
			}
			if (12 == (0xC & num2))
			{
				num2 &= 0xFFFB;
			}
			if (3 == (3 & num2))
			{
				num2 &= 0xFFFE;
			}
			m_on_flag.push_front(num2);
		}

		public ushort GetValue()
		{
			return m_on_flag[0];
		}

		public bool IsFocus(int tp_index)
		{
			return m_focus[tp_index];
		}

		public bool create()
		{
			Release();
			m_flag[0] = true;
			return true;
		}

		public bool isHit(ushort[] point)
		{
			CArray2<float> pos = CArray2<float>.initializer((int)point[0], (int)point[1]);
			return isHit(pos);
		}

		public bool isHit(CArray2<float> pos)
		{
			bool result = false;
			if (!(pos.x < m_area.left) && !(m_area.right < pos.x) && !(pos.y < m_area.top) && !(m_area.bottom < pos.y))
			{
				result = true;
			}
			return result;
		}

		public ushort getOnFlag(ushort[] point)
		{
			CArray2<float> pos = CArray2<float>.initializer((int)point[0], (int)point[1]);
			return getOnFlag(pos);
		}

		public ushort getOnFlag(CArray2<float> pos)
		{
			CArray2<float> p = CArray2<float>.initializer((m_area.left + m_area.right) * 0.5f, (m_area.top + m_area.bottom) * 0.5f);
			pos.y -= 16f;
			pos.y /= 1.05f;
			ushort num = 0;
			float num2 = 0.4f;
			float num3 = (m_area.bottom - m_area.top) * num2 * 0.5f;
			CArray2<float> xy = CArray2<float>.initializer(m_area.left, p.y - num3);
			CArray2<float> xy2 = CArray2<float>.initializer(p.x, p.y + num3 - 17f);
			CArray2<float> xy3 = CArray2<float>.initializer(p.x, p.y - num3);
			CArray2<float> xy4 = CArray2<float>.initializer(m_area.right, p.y + num3 - 17f);
			if (isHit(pos, xy3, xy4))
			{
				num = 8;
			}
			else if (isHit(pos, xy, xy2))
			{
				num = 4;
			}
			if (num == 0)
			{
				CArray2<float> cArray = CArray2<float>.initializer(m_area.left, m_area.top);
				CArray2<float> cArray2 = CArray2<float>.initializer(m_area.right, m_area.top);
				CArray2<float> cArray3 = CArray2<float>.initializer(m_area.left, m_area.bottom);
				CArray2<float> cArray4 = CArray2<float>.initializer(m_area.right, m_area.bottom);
				if (isHit(pos, p, cArray2, cArray4))
				{
					num = 8;
				}
				else if (isHit(pos, p, cArray3, cArray))
				{
					num = 4;
				}
				else if (isHit(pos, p, cArray, cArray2))
				{
					num = 1;
				}
				else if (isHit(pos, p, cArray4, cArray3))
				{
					num = 2;
				}
			}
			return num;
		}

		public bool isHit(CArray2<float> target, CArray2<float> xy1, CArray2<float> xy2)
		{
			bool result = false;
			if (!(target.x < xy1.x) && !(xy2.x < target.x) && !(target.y < xy1.y) && !(xy2.y < target.y))
			{
				result = true;
			}
			return result;
		}

		public bool isHit(CArray2<float> target, CArray2<float> p1, CArray2<float> p2, CArray2<float> p3)
		{
			float num = CLocalLogic.Cross(_SubrtactArray2(p1, target), _SubrtactArray2(p2, target));
			float num2 = CLocalLogic.Cross(_SubrtactArray2(p2, target), _SubrtactArray2(p3, target));
			float num3 = CLocalLogic.Cross(_SubrtactArray2(p3, target), _SubrtactArray2(p1, target));
			if (0f < num * num2 && 0f < num * num3)
			{
				return true;
			}
			return false;
		}
	}

