	public class VecFx16
	{
		public short x;

		public short y;

		public short z;

		public VecFx16()
			: this(0, 0, 0)
		{
		}

		public VecFx16(short _x, short _y, short _z)
		{
			x = _x;
			y = _y;
			z = _z;
		}

		public VecFx16(VecFx16 vecFx16)
		{
			x = vecFx16.x;
			y = vecFx16.y;
			z = vecFx16.z;
		}

		public VecFx16 Assign(VecFx16 vecFx16)
		{
			if (this != vecFx16)
			{
				x = vecFx16.x;
				y = vecFx16.y;
				z = vecFx16.z;
			}
			return this;
		}
	}

