	public class OBS_RECT : IClearable
	{
		public short left;

		public short top;

		public short back;

		public short right;

		public short bottom;

		public short front;

		public VecFx32 pos = default(VecFx32);

		public ushort width
		{
			get
			{
				return (ushort)right;
			}
			set
			{
				right = (short)value;
			}
		}

		public ushort height
		{
			get
			{
				return (ushort)bottom;
			}
			set
			{
				bottom = (short)value;
			}
		}

		public short depth
		{
			get
			{
				return front;
			}
			set
			{
				front = value;
			}
		}

		public void Clear()
		{
			left = (top = (back = 0));
			right = 0;
			width = 0;
			height = 0;
			bottom = 0;
			height = 0;
			front = 0;
			depth = 0;
		}
	}

