	public class CActionDraw
	{
		public CCircularBuffer<AOS_ACTION> m_action_array = new CCircularBuffer<AOS_ACTION>(100);

		public void Entry(A2S_AMA_HEADER ama, uint id, float frame, float x, float y)
		{
			if (_am_sample_draw_enable)
			{
				AOS_ACTION aOS_ACTION = AoActCreate(ama, id, frame);
				AoActAcmPush();
				AoActAcmInit();
				AoActAcmApplyTrans(x, y, 0f);
				AoActUpdate(aOS_ACTION, 0f);
				AoActSortRegAction(aOS_ACTION);
				AoActAcmPop();
				m_action_array.push_back(aOS_ACTION);
			}
		}

		public void Entry(A2S_AMA_HEADER ama, uint id, float frame, float x, float y, float scalex, float scaley)
		{
			if (_am_sample_draw_enable)
			{
				AOS_ACTION aOS_ACTION = AoActCreate(ama, id, frame);
				AoActAcmPush();
				AoActAcmInit();
				AoActAcmApplyTrans(x, y, 0f);
				AoActAcmApplyScale(scalex, scaley);
				AoActUpdate(aOS_ACTION, 0f);
				AoActSortRegAction(aOS_ACTION);
				AoActAcmPop();
				m_action_array.push_back(aOS_ACTION);
			}
		}

		public void Clear()
		{
			for (int i = 0; i < m_action_array.size(); i++)
			{
				AoActDelete(m_action_array[i]);
			}
			m_action_array.clear();
		}

		public void Draw()
		{
			if (_am_sample_draw_enable)
			{
				AoActSortExecute();
				AoActSortDraw();
			}
			AoActSortUnregAll();
		}

		public void CActionDraw_destructor()
		{
			Clear();
		}
	}

