	public struct MD_BLOCK
	{
		public sbyte ofst_x;

		public sbyte ofst_y;

		public MD_BLOCK(sbyte bitFieldValue)
		{
			int num = bitFieldValue & 0xF;
			ofst_x = ((num >= 8) ? ((sbyte)(num - 16)) : ((sbyte)num));
			ofst_y = (sbyte)(bitFieldValue >> 4);
		}
	}

