		public YSDS_PAGE[] pages;

		public YSDS_HEADER(byte[] data)
		{
			using (MemoryStream input = new MemoryStream(data))
			{
				using (BinaryReader binaryReader = new BinaryReader(input))
				{
					masic = binaryReader.ReadBytes(4);
					page_num = binaryReader.ReadUInt32();
					pages = New<YSDS_PAGE>((int)page_num);
					for (int i = 0; i < page_num; i++)
					{
						pages[i].time = binaryReader.ReadUInt32();
						pages[i].show = binaryReader.ReadInt32();
						pages[i].hide = binaryReader.ReadInt32();
						pages[i].option = binaryReader.ReadUInt32();
						pages[i].line_num = binaryReader.ReadUInt32();
						pages[i].line_tbl_ofst = binaryReader.ReadUInt32();
						pages[i].lines = New<YSDS_LINE>((int)pages[i].line_num);
					}
					for (int j = 0; j < page_num; j++)
					{
						binaryReader.BaseStream.Seek(pages[j].line_tbl_ofst, SeekOrigin.Begin);
						for (int k = 0; k < pages[j].line_num; k++)
						{
							pages[j].lines[k].id = binaryReader.ReadUInt32();
							pages[j].lines[k].str_ofst = binaryReader.ReadUInt32();
						}
					}
					for (int l = 0; l < page_num; l++)
					{
						for (int m = 0; m < pages[l].line_num; m++)
						{
							binaryReader.BaseStream.Seek(pages[l].lines[m].str_ofst, SeekOrigin.Begin);
							pages[l].lines[m].s = readChars(binaryReader);
						}
					}
				}
			}
		}
	}

