			AoActAcmPush();
			AoActAcmApplyTrans(0f, 0f, -1000f);
			for (int i = 0; i < m_act.Length; i++)
			{
				m_act[i].Update();
				if (i == 16 || i == 15)
				{
					m_act[i].act.sprite.center_y += 5f;
				}
			}
			AoActAcmPop();
		}

