		private void fileLoadingStart()
		{
			m_file[0] = readAMAFile("G_COM/MENU/G_PAUSE.AMA");
			pause_amb = amFsReadBackground("G_COM/MENU/G_PAUSE.AMB");
			m_file[1] = readAMAFile("G_COM/MENU/G_PAUSE_L.AMA");
			int num = GsEnvGetLanguage();
			lang_amb = amFsReadBackground(file.c_lang_amb[num]);
			m_flag[0] = true;
			m_flag[3] = true;
			AttachTask("gmPauseMenu.Load", 28928u, 0u, 0u);
			m_procCount.SetProc(fileLoading);
		}

		private void fileLoading()
		{
			if (amFsIsComplete(pause_amb))
			{
				m_file[2] = readAMBFile(pause_amb);
				GsEnvGetLanguage();
				if (amFsIsComplete(lang_amb))
				{
					m_file[3] = readAMBFile(lang_amb);
					m_flag[4] = true;
					DetachTask();
				}
			}
		}

		private void creatingStart()
		{
			for (int i = 0; i < c_local_create_table.Length; i++)
			{
				int num = c_local_create_table[i];
				AoTexBuild(m_tex[i], (AMS_AMB_HEADER)m_file[num]);
				AoTexLoad(m_tex[i]);
			}
			m_flag[5] = true;
			AttachTask("gmPauseMenu.Build", 28928u, 0u, 0u);
			m_procCount.SetProc(creating);
		}

		private void creating()
		{
			bool flag = true;
			for (int i = 0; i < m_tex.Length; i++)
			{
				if (!AoTexIsLoaded(m_tex[i]))
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				m_flag[6] = true;
				DetachTask();
			}
		}

		private void fadeInStart()
		{
			fadeInStart(28928);
		}

		private void fadeInStart(int prio)
		{
			if (!canGoStageSelect())
			{
				local_create_action_table[11].idx = 2;
				local_create_action_table[14].idx = 7;
			}
			else
			{
				local_create_action_table[11].idx = 1;
				local_create_action_table[14].idx = 5;
			}
			if (isSpecialStage())
			{
				local_create_action_table[13].idx = 6;
			}
			else
			{
				local_create_action_table[13].idx = 4;
			}
			for (int i = 0; i < 17; i++)
			{
				SLocalCreateActionTable sLocalCreateActionTable = local_create_action_table[i];
				A2S_AMA_HEADER ama = (A2S_AMA_HEADER)m_file[sLocalCreateActionTable.file];
				SAction sAction = m_act[i];
				sAction.act = AoActCreate(ama, (uint)sLocalCreateActionTable.idx);
				sAction.tex = m_tex[sLocalCreateActionTable.tex];
				sAction.flag[0] = true;
				sAction.flag[1] = true;
				sAction.AcmInit();
			}
			for (int j = 0; j < 3; j++)
			{
				SAction sAction2 = m_act[c_local_create_trg_table[j]];
				CTrgAoAction cTrgAoAction = m_trg[j];
				cTrgAoAction.Create(sAction2.act);
			}
			m_flag[7] = true;
			m_act[0].flag[1] = false;
			m_act[0].scale = new Vector2(0f, 0f);
			m_se_handle = GsSoundAllocSeHandle();
			AttachTask("gmPauseMenu.Execute", (uint)prio, 0u, 0u);
			playSe(0);
