		private void fadeOutStart()
		{
			SAction[] act = m_act;
			foreach (SAction sAction in act)
			{
				sAction.flag[0] = true;
				sAction.flag[1] = true;
			}
			m_act[0].flag[0] = false;
			m_act[0].flag[1] = false;
			playSe(3);
			m_procCount.SetProc(fadeOut);
		}

		private void fadeOut()
		{
			float num = 1f - (float)(m_procCount.GetCount() / 8);
			m_act[0].scale = new Vector2(num, num);
			if (8 < m_procCount.GetCount())
			{
				SAction[] act = m_act;
				foreach (SAction sAction in act)
				{
					AoActDelete(sAction.act);
				}
				GsSoundFreeSeHandle(m_se_handle);
				m_flag[7] = false;
				DetachTask();
			}
		}

		private void releasingStart()
		{
			AOS_TEXTURE[] tex = m_tex;
			foreach (AOS_TEXTURE tex2 in tex)
			{
				AoTexRelease(tex2);
			}
			AttachTask("gmPauseMenu.Flush", 28928u, 0u, 0u);
			m_procCount.SetProc(releasing);
		}

		private void releasing()
		{
			bool flag = true;
			AOS_TEXTURE[] tex = m_tex;
			foreach (AOS_TEXTURE tex2 in tex)
			{
				if (!AoTexIsReleased(tex2))
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				m_flag[5] = false;
				m_flag[6] = false;
				DetachTask();
			}
		}

		private void playSe(int se)
		{
			GmSoundPlaySE(c_se_name_tbl[se]);
		}

		private static bool canGoStageSelect()
		{
			if (GsMainSysIsStageClear(0))
			{
				return !GsTrialIsTrial();
			}
			return false;
		}

		private static bool isSpecialStage()
		{
			return GSM_MAIN_STAGE_IS_SPSTAGE();
		}

		private static int TrgIdxToReturnIdx(int trg_idx)
		{
			int num = c_return_table[trg_idx];
			if (!canGoStageSelect() && 2 == num)
			{
				num = 3;
			}
			return num;
		}
	}

