	public class SimplePool<T> where T : class, new()
	{
		private List<T> cache_;

		public SimplePool()
		{
			cache_ = new List<T>();
		}

		public T Alloc()
		{
			T result;
			if (cache_.Count > 0)
			{
				int index = cache_.Count - 1;
				result = cache_[index];
				cache_.RemoveAt(index);
			}
			else
			{
				result = new T();
			}
			return result;
		}

		public void Release(T obj)
		{
			cache_.Add(obj);
		}
	}

	public class Pool<T> where T : class, new()
	{
		private int freeObjectsCount_;

		private int usedObjectsCount_;

		private T[] freeObjects_ = new T[1024];

		private T[] usedObjects_ = new T[1024];

		public T Alloc()
		{
			T val;
			if (freeObjectsCount_ > 0)
			{
				int num = freeObjectsCount_ - 1;
				val = freeObjects_[num];
				freeObjects_[num] = null;
				freeObjectsCount_--;
			}
			else
			{
				val = new T();
			}
			if (usedObjects_.Length == usedObjectsCount_)
			{
				T[] destinationArray = new T[usedObjects_.Length * 2];
				Array.Copy(usedObjects_, destinationArray, usedObjects_.Length);
				usedObjects_ = destinationArray;
			}
			usedObjects_[usedObjectsCount_] = val;
			usedObjectsCount_++;
			return val;
		}

		public void Release(T obj)
		{
			if (freeObjects_.Length == freeObjectsCount_)
			{
				T[] destinationArray = new T[freeObjects_.Length * 2];
				Array.Copy(freeObjects_, destinationArray, freeObjects_.Length);
				freeObjects_ = destinationArray;
			}
			freeObjects_[freeObjectsCount_] = obj;
			freeObjectsCount_++;
			int num = Array.IndexOf(usedObjects_, obj);
			if (num >= 0)
			{
				for (num++; num < usedObjectsCount_; num++)
				{
					usedObjects_[num - 1] = usedObjects_[num];
				}
				usedObjectsCount_--;
			}
		}

		public void ReleaseUsedObjects()
		{
			for (int i = 0; i < usedObjectsCount_; i++)
			{
				freeObjects_[freeObjectsCount_ + i] = usedObjects_[i];
			}
			freeObjectsCount_ += usedObjectsCount_;
			for (int j = 0; j < usedObjectsCount_; j++)
			{
				usedObjects_[j] = null;
			}
			usedObjectsCount_ = 0;
		}

		public void Clear()
		{
			for (int i = 0; i < freeObjectsCount_; i++)
			{
				freeObjects_[i] = null;
			}
			freeObjectsCount_ = 0;
			for (int j = 0; j < usedObjectsCount_; j++)
			{
				usedObjects_[j] = null;
			}
			usedObjectsCount_ = 0;
		}
	}

	public class ArrayPool<T> where T : new()
	{
		private List<T[]> freeArrays_ = new List<T[]>();

		private List<T[]> usedArrays_ = new List<T[]>();

		public T[] AllocArray(int size)
		{
			int num = -1;
			int num2 = ((freeArrays_.Count > 0) ? freeArrays_[0].Length : (-1));
			for (int i = 0; i < freeArrays_.Count; i++)
			{
				int num3 = freeArrays_[i].Length;
				if (num3 >= size && num3 <= num2)
				{
					num = i;
				}
			}
			T[] array;
			if (num >= 0)
			{
				array = freeArrays_[num];
				freeArrays_.RemoveAt(num);
			}
			else
			{
				array = new T[size];
			}
			usedArrays_.Add(array);
			return array;
		}

		public void ReleaseArray(T[] array)
		{
			freeArrays_.Add(array);
			usedArrays_.Remove(array);
		}

		public void ReleaseUsedArrays()
		{
			freeArrays_.AddRange(usedArrays_);
			usedArrays_.Clear();
		}

		public void Clear()
		{
			freeArrays_.Clear();
			usedArrays_.Clear();
		}
	}

	public class ArrayPoolFast<T> where T : new()
	{
		private List<T[]> freeArrays_ = new List<T[]>();

		private List<T[]> usedArrays_ = new List<T[]>();

		public T[] AllocArray(int size)
		{
			int num = -1;
			for (int i = 0; i < freeArrays_.Count; i++)
			{
				if (size <= freeArrays_[i].Length)
				{
					num = i;
					break;
				}
			}
			T[] array;
			if (num >= 0)
			{
				array = freeArrays_[num];
				freeArrays_.RemoveAt(num);
			}
			else
			{
				array = new T[size];
			}
			usedArrays_.Add(array);
			return array;
		}

		public void ReleaseArray(T[] array)
		{
			freeArrays_.Add(array);
			usedArrays_.Remove(array);
		}

		public void ReleaseUsedArrays()
		{
			freeArrays_.AddRange(usedArrays_);
			usedArrays_.Clear();
		}

		public void Clear()
		{
			freeArrays_.Clear();
			usedArrays_.Clear();
		}

		public int GetFreeCount()
		{
			return freeArrays_.Count;
		}
	}

	public class ArrayPoolMultisize<T> where T : new()
	{
		private List<int> arrayElementCapacity_ = new List<int>();

		private List<ArrayPoolFast<T>> Arrays_ = new List<ArrayPoolFast<T>>();

		public T[] AllocArray(int size)
		{
			int index = _GetArrayPoolIDBestForCapacity(size);
			return Arrays_[index].AllocArray(size);
		}

		public void ReleaseArray(T[] array)
		{
			int index = _GetArrayPoolIDBestForCapacity(array.Length);
			Arrays_[index].ReleaseArray(array);
		}

		public void ReleaseUsedArrays()
		{
			for (int i = 0; i < Arrays_.Count; i++)
			{
				Arrays_[i].ReleaseUsedArrays();
			}
		}

		public void Clear()
		{
			for (int i = 0; i < Arrays_.Count; i++)
			{
				Arrays_[i].Clear();
			}
		}

		public void AddCacheWithCapacity(int iCapacity, int iAmount)
		{
			if (arrayElementCapacity_.Count > 0 && arrayElementCapacity_[arrayElementCapacity_.Count - 1] > iCapacity)
			{
				throw new NotSupportedException();
			}
			arrayElementCapacity_.Add(iCapacity);
			ArrayPoolFast<T> arrayPoolFast = new ArrayPoolFast<T>();
			for (int i = 0; i < iAmount; i++)
			{
				arrayPoolFast.AllocArray(iCapacity);
			}
			arrayPoolFast.ReleaseUsedArrays();
			Arrays_.Add(arrayPoolFast);
		}

		private int _GetArrayPoolIDBestForCapacity(int iCapacity)
		{
			int num = 0;
			for (num = 0; num < arrayElementCapacity_.Count; num++)
			{
				if (iCapacity <= arrayElementCapacity_[num] && Arrays_[num].GetFreeCount() > 0)
				{
					return num;
				}
			}
			if (iCapacity <= arrayElementCapacity_[arrayElementCapacity_.Count - 1])
			{
				return arrayElementCapacity_.Count - 1;
			}
			AddCacheWithCapacity(iCapacity, 1);
			return arrayElementCapacity_.Count - 1;
		}
	}

