	private static int ObjBlockCollisionDet(int lPosX, int lPosY, ushort usFlag, ushort usVec, ushort[] pDir, uint[] pAttr)
	{
		OBS_COL_CHK_DATA oBS_COL_CHK_DATA = GlobalPool<OBS_COL_CHK_DATA>.Alloc();
		oBS_COL_CHK_DATA.pos_x = lPosX;
		oBS_COL_CHK_DATA.pos_y = lPosY;
		oBS_COL_CHK_DATA.dir = pDir;
		oBS_COL_CHK_DATA.attr = pAttr;
		oBS_COL_CHK_DATA.flag = usFlag;
		oBS_COL_CHK_DATA.vec = usVec;
		int result = ObjBlockCollision(oBS_COL_CHK_DATA);
		GlobalPool<OBS_COL_CHK_DATA>.Release(oBS_COL_CHK_DATA);
		return result;
	}

	private static int ObjBlockCollision(OBS_COL_CHK_DATA pData)
	{
		int a = 0;
		short num = 0;
		short num2 = 0;
		short num3 = 1;
		if (_obj_bcol.pData[0] == null)
		{
			switch (pData.vec)
			{
			case 2:
				a = _obj_bcol.bottom - pData.pos_y;
				break;
			case 3:
				a = pData.pos_y - _obj_bcol.top;
				break;
			case 0:
				a = _obj_bcol.right - pData.pos_x;
				break;
			case 1:
				a = pData.pos_x - _obj_bcol.left;
				break;
			}
			return MTM_MATH_CLIP(a, -31, 31);
		}
		if (pData.dir != null)
		{
			ushort num6 = pData.dir[0];
		}
		if (pData.attr != null)
		{
			uint num7 = pData.attr[0];
		}
		a = objGetBlockColData(pData);
		if ((pData.vec & 2) != 0)
		{
			num3 = (short)(pData.pos_y & 0xF);
			switch (((pData.vec & 1) == 0) ? ((short)(num3 + (short)a)) : ((short)(num3 - (short)a)))
			{
			case 0:
				num2 = -16;
				break;
			case 15:
				num2 = 16;
				break;
			}
		}
		else
		{
			num3 = (short)(pData.pos_x & 0xF);
			switch (((pData.vec & 1) == 0) ? ((short)(num3 + (short)a)) : ((short)(num3 - (short)a)))
			{
			case 0:
				num = -16;
				break;
			case 15:
				num = 16;
				break;
			}
		}
		if (num != 0 || num2 != 0)
		{
			uint num4 = 0u;
			ushort num5 = 0;
			if (pData.dir != null)
			{
				num5 = pData.dir[0];
			}
			if (pData.attr != null)
			{
				num4 = pData.attr[0];
			}
			pData.pos_x += num;
			pData.pos_y += num2;
			a = objGetBlockColData(pData);
			pData.pos_x -= num;
			pData.pos_y -= num2;
			if (a >= 0)
			{
				if (pData.dir != null)
				{
					pData.dir[0] = num5;
				}
				if (pData.attr != null)
				{
					pData.attr[0] = num4;
				}
			}
			if (num < 0)
			{
				num++;
			}
			if (num > 0)
			{
				num--;
			}
			if (num2 < 0)
			{
				num2++;
			}
			if (num2 > 0)
			{
				num2--;
			}
			a = (((pData.vec & 1) == 0) ? (a + (num + num2)) : (a - (num + num2)));
		}
		return a;
	}

	private static int objGetBlockColData(OBS_COL_CHK_DATA pData)
	{
		int num = 0;
		int num2 = 0;
		if ((pData.flag & 0x40) != 0)
		{
			int num3 = objBlockColLimit(pData);
			if (num3 < 0)
			{
				return num3;
			}
		}
		else
		{
			num = MTM_MATH_CLIP(pData.pos_x, _obj_bcol.left, _obj_bcol.right - 1);
			num2 = MTM_MATH_CLIP(pData.pos_y, _obj_bcol.top, _obj_bcol.bottom - 1);
		}
		uint num4 = (uint)((num2 >> 4) * _obj_bcol.width + (num >> 4));
		ushort num5 = _obj_bcol.pData[pData.flag & 1][num4];
		return _obj_block_collision_func[num5](pData);
	}

	private static int objBlockColLimit(OBS_COL_CHK_DATA pData)
	{
		switch (pData.vec)
		{
		case 2:
			if (_obj_bcol.bottom - 1 < pData.pos_y)
			{
				return _obj_bcol.bottom - 1 - pData.pos_y;
			}
			goto case 3;
		case 3:
			if (_obj_bcol.top > pData.pos_y)
			{
				return pData.pos_y - _obj_bcol.top;
			}
			goto case 0;
		case 0:
			if (_obj_bcol.right - 1 < pData.pos_x)
			{
				return _obj_bcol.right - 1 - pData.pos_x;
			}
			goto case 1;
		case 1:
			if (_obj_bcol.left > pData.pos_x)
			{
				return pData.pos_x - _obj_bcol.left;
			}
			break;
		}
		return 1;
	}

	private static int objBlockCalcEmpty(OBS_COL_CHK_DATA pData)
	{
		switch (pData.vec)
		{
		case 2:
			return 15 - (pData.pos_y & 0xF);
		case 3:
			return pData.pos_y & 0xF;
		case 0:
			return 15 - (pData.pos_x & 0xF);
		case 1:
			return pData.pos_x & 0xF;
		default:
			return 15;
		}
	}

	private static int objBlockCalcFill(OBS_COL_CHK_DATA pData)
	{
		switch (pData.vec)
		{
		case 2:
			return -(pData.pos_y & 0xF);
		case 3:
			return -(15 - (pData.pos_y & 0xF));
		case 0:
			return -(pData.pos_x & 0xF);
		case 1:
			return -(15 - (pData.pos_x & 0xF));
		default:
			return 15;
		}
	}

	private static int objBlockColEmpty(OBS_COL_CHK_DATA pData)
	{
		if (pData.dir != null)
		{
			pData.dir[0] = 0;
		}
		return objBlockCalcEmpty(pData);
	}

	private static int objBlockColBlockFill(OBS_COL_CHK_DATA pData)
	{
		if (pData.dir != null)
		{
			pData.dir[0] = 0;
		}
		return objBlockCalcFill(pData);
	}

	private static int objBlockColBlockFillThrough(OBS_COL_CHK_DATA pData)
	{
		if (pData.dir != null)
		{
			pData.dir[0] = 0;
		}
		if (pData.attr != null)
		{
			pData.attr[0] |= 2u;
		}
		if ((pData.flag & 0x80) != 0)
		{
			return objBlockCalcEmpty(pData);
		}
		return objBlockCalcFill(pData);
	}

