	private static void nnCalcNodeStatusListMatrixPaletteNode(int nodeIdx)
	{
		mppAssertNotImpl();
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		NNS_MATRIX nNS_MATRIX2 = GlobalPool<NNS_MATRIX>.Alloc();
		NNS_NODE nNS_NODE;
		do
		{
			nNS_NODE = nnnodestatuslist.nnsNodeList[nodeIdx];
			int iMatrix = nNS_NODE.iMatrix;
			if (iMatrix != -1)
			{
				NNS_MATRIX nNS_MATRIX3 = nnnodestatuslist.nnsMtxPal[iMatrix];
				if ((nNS_NODE.fType & 8) != 0)
				{
					nnCopyMatrix(nNS_MATRIX, nNS_MATRIX3);
				}
				if ((nNS_NODE.fType & 0x80) != 0)
				{
					nnInvertOrthoMatrix(nNS_MATRIX2, nNS_NODE.InvInitMtx);
					nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX3, nNS_MATRIX2);
				}
				else
				{
					nnInvertMatrix(nNS_MATRIX2, nNS_NODE.InvInitMtx);
					nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX3, nNS_MATRIX2);
				}
				nnCalcClipSetNodeStatus(nnnodestatuslist.nnsNodeStatList, nnnodestatuslist.nnsNodeList, nodeIdx, nNS_MATRIX, 1f, nnnodestatuslist.nnsNSFlag);
			}
			if (nNS_NODE.iChild != -1)
			{
				nnCalcNodeStatusListMatrixPaletteNode(nNS_NODE.iChild);
			}
			nodeIdx = nNS_NODE.iSibling;
		}
		while (nNS_NODE.iSibling != -1);
	}

	private static void nnCalcNodeStatusListMatrixPalette(uint[] nodestatlist, NNS_MATRIX[] mtxpal, NNS_OBJECT obj, uint flag)
	{
		nnnodestatuslist.nnsMtxPal = mtxpal;
		nnnodestatuslist.nnsNodeStatList = nodestatlist;
		nnnodestatuslist.nnsNodeList = obj.pNodeList;
		nnnodestatuslist.nnsNSFlag = flag;
		nnCalcNodeStatusListMatrixPaletteNode(0);
	}

