	public static void nnmRotateMatrixFast(NNS_MATRIX mtx, int ang, int ma, int mb)
	{
		if (ang != 0)
		{
			float s;
			float c;
			nnSinCos(ang, out s, out c);
			float num = s;
			float num2 = c;
			float num3 = mtx.M(0, ma);
			float num4 = mtx.M(0, mb);
			mtx.SetM(0, ma, num3 * num2 + num4 * num);
			mtx.SetM(0, mb, num3 * (0f - num) + num4 * num2);
			float num5 = mtx.M(1, ma);
			float num6 = mtx.M(1, mb);
			mtx.SetM(1, ma, num5 * num2 + num6 * num);
			mtx.SetM(1, mb, num5 * (0f - num) + num6 * num2);
			num3 = mtx.M(2, ma);
			num4 = mtx.M(2, mb);
			mtx.SetM(2, ma, num3 * num2 + num4 * num);
			mtx.SetM(2, mb, num3 * (0f - num) + num4 * num2);
		}
	}

