	private void amTrailEFInitialize()
	{
		_amTrailEF_head.Clear();
		_amTrailEF_tail.Clear();
		_amTrailEF_head.pNext = _amTrailEF_tail;
		_amTrailEF_head.pPrev = null;
		_amTrailEF_tail.pNext = null;
		_amTrailEF_tail.pPrev = _amTrailEF_head;
		_amTrailEF_alloc = 0;
		_amTrailEF_free = 0;
		for (int i = 0; i < 8; i++)
		{
			_amTrailEF_buf[i].Clear();
			_amTrailEF_ref[i] = _amTrailEF_buf[i];
		}
	}

	private static void amTrailEFUpdate(ushort handleId)
	{
		for (AMS_TRAIL_EFFECT pNext = _amTrailEF_head.pNext; pNext != _amTrailEF_tail; pNext = pNext.pNext)
		{
			if (pNext.Procedure != null && (pNext.handleId & handleId) != 0 && pNext.Procedure != -1)
			{
				((AMTREffectProc)pNext.Procedure)(pNext);
				AMS_TRAIL_PARAM work = pNext.Work;
				if ((work.state & 0x8000) != 0)
				{
					_amTrailEFDelete(pNext);
				}
				else
				{
					pNext.fFrame += amEffectGetUnitFrame();
					if (pNext.fEndFrame > 0f && pNext.fFrame > pNext.fEndFrame)
					{
						_amTrailEFDelete(pNext);
					}
				}
			}
		}
		for (AMS_TRAIL_EFFECT pNext = _amTrailEF_head.pNext; pNext != _amTrailEF_tail; pNext = pNext.pNext)
		{
			if (pNext.Procedure == -1)
			{
				_amTrailEFDeleteEffectReal(pNext);
			}
		}
	}

	private static void amTrailEFDraw(ushort handleId, NNS_TEXLIST texlist, uint state)
	{
		for (AMS_TRAIL_EFFECT pNext = _amTrailEF_head.pNext; pNext != _amTrailEF_tail; pNext = pNext.pNext)
		{
			if (pNext.Procedure != null && (pNext.handleId & handleId) != 0 && pNext.Procedure != -1)
			{
				pNext.drawState = state;
				AMS_TRAIL_PARAM work = pNext.Work;
				work.texlist = texlist;
				_amTrailDrawNormal(pNext);
			}
		}
	}

	private static void amTrailEFDeleteGroup(ushort handleId)
	{
		for (AMS_TRAIL_EFFECT pNext = _amTrailEF_head.pNext; pNext != _amTrailEF_tail; pNext = pNext.pNext)
		{
			if ((pNext.handleId & handleId) != 0)
			{
				_amTrailEFDelete(pNext);
			}
		}
	}

	private static void amTrailEFOffsetPos(ushort handleId, NNS_VECTOR offset)
	{
		for (AMS_TRAIL_EFFECT pNext = _amTrailEF_head.pNext; pNext != _amTrailEF_tail; pNext = pNext.pNext)
		{
			if ((pNext.handleId & handleId) != 0)
			{
				_amTrailAddPosition(pNext, offset);
			}
		}
	}

	private static void amTrailMakeEffect(AMS_TRAIL_PARAM param, ushort handleId, short flag)
	{
		pTr.trailNum++;
		AMS_TRAIL_EFFECT aMS_TRAIL_EFFECT = _amTrailEFMake(handleId);
		if (aMS_TRAIL_EFFECT != null)
		{
			aMS_TRAIL_EFFECT.Procedure = (AMTREffectProc)_amTrailUpdateNormal;
			aMS_TRAIL_EFFECT.Destractor = (AMTREffectProc)_amTrailFinalizeNormal;
			aMS_TRAIL_EFFECT.fEndFrame = -1f;
			aMS_TRAIL_EFFECT.flag = flag;
			AMS_TRAIL_PARAM work = aMS_TRAIL_EFFECT.Work;
			work = work.Assign(param);
			work.time = work.life * amEffectGetUnitFrame();
			work.trailId = pTr.trailId;
			if (pTr.trailEffect[work.trailId] != null)
			{
				_amTrailEFDelete(pTr.trailEffect[work.trailId]);
			}
			pTr.trailEffect[work.trailId] = aMS_TRAIL_EFFECT;
			_amTrailInitNormal(aMS_TRAIL_EFFECT);
			pTr.trailId++;
			if (pTr.trailId >= 8)
			{
				pTr.trailId = 0;
			}
		}
	}

	private static void _amTrailEFDelete(AMS_TRAIL_EFFECT pEffect)
	{
		pEffect.Procedure = -1;
		if (pEffect.Destractor != null && pEffect.Destractor != -1)
		{
			((AMTREffectProc)pEffect.Destractor)(pEffect);
		}
	}

	private static AMS_TRAIL_EFFECT _amTrailEFMake(ushort handleId)
	{
		AMS_TRAIL_EFFECT aMS_TRAIL_EFFECT = _amTrailEFAlloc();
		if (aMS_TRAIL_EFFECT == null)
		{
			return null;
		}
		_amTrailEF_tail.pPrev.pNext = aMS_TRAIL_EFFECT;
		aMS_TRAIL_EFFECT.pPrev = _amTrailEF_tail.pPrev;
		_amTrailEF_tail.pPrev = aMS_TRAIL_EFFECT;
		aMS_TRAIL_EFFECT.pNext = _amTrailEF_tail;
		aMS_TRAIL_EFFECT.handleId = handleId;
		return aMS_TRAIL_EFFECT;
	}

	private static AMS_TRAIL_EFFECT _amTrailEFAlloc()
	{
		AMS_TRAIL_EFFECT aMS_TRAIL_EFFECT = _amTrailEF_ref[_amTrailEF_alloc];
		_amTrailEF_alloc++;
		if (_amTrailEF_alloc >= 8)
		{
			_amTrailEF_alloc = 0;
		}
		aMS_TRAIL_EFFECT.Clear();
		return aMS_TRAIL_EFFECT;
	}

	private static void _amTrailEFFree(AMS_TRAIL_EFFECT pEffect)
	{
		_amTrailEF_ref[_amTrailEF_free] = pEffect;
		_amTrailEF_free++;
		if (_amTrailEF_free >= 8)
		{
			_amTrailEF_free = 0;
		}
	}

	private static void _amTrailEFDeleteEffectReal(AMS_TRAIL_EFFECT pEffect)
	{
		pEffect.pPrev.pNext = pEffect.pNext;
		pEffect.pNext.pPrev = pEffect.pPrev;
		_amTrailEFFree(pEffect);
	}

	private static void _amTrailInitNormal(AMS_TRAIL_EFFECT pEffect)
	{
		AMS_TRAIL_PARAM work = pEffect.Work;
		AMS_TRAIL_PARTSDATA aMS_TRAIL_PARTSDATA = pTr.trailData[work.trailId];
		AMS_TRAIL_PARTS aMS_TRAIL_PARTS = aMS_TRAIL_PARTSDATA.parts[0];
		AMS_TRAIL_PARTS trailTail = aMS_TRAIL_PARTSDATA.trailTail;
		AMS_TRAIL_PARTS trailHead = aMS_TRAIL_PARTSDATA.trailHead;
		aMS_TRAIL_PARTSDATA.Clear();
		aMS_TRAIL_PARTS.pNext = trailTail;
		trailTail.pPrev = aMS_TRAIL_PARTS;
		aMS_TRAIL_PARTS.pPrev = trailHead;
		trailHead.pNext = aMS_TRAIL_PARTS;
		if ((pEffect.flag & 1) != 0)
		{
			aMS_TRAIL_PARTS.pos.x = AMD_FX32_TO_FLOAT(work.trail_pos.x);
			aMS_TRAIL_PARTS.pos.y = 0f - AMD_FX32_TO_FLOAT(work.trail_pos.y);
			aMS_TRAIL_PARTS.pos.z = AMD_FX32_TO_FLOAT(work.zBias);
		}
		else
		{
			aMS_TRAIL_PARTS.pos.x = MppBitConverter.Int32ToSingle(work.trail_pos.x);
			aMS_TRAIL_PARTS.pos.y = MppBitConverter.Int32ToSingle(work.trail_pos.y);
			aMS_TRAIL_PARTS.pos.z = MppBitConverter.Int32ToSingle(work.trail_pos.z);
		}
		aMS_TRAIL_PARTS.time = work.life;
		aMS_TRAIL_PARTS.partsId = 0;
		work.trailPartsId = 1;
		work.trailPartsNum++;
	}

	private static int _amTrailFinalizeNormal(AMS_TRAIL_EFFECT pEffect)
	{
		AMS_TRAIL_PARAM work = pEffect.Work;
		if (pTr.trailNum > 0)
		{
			pTr.trailNum--;
			if (pTr.trailNum == 0)
			{
				pTr.trailState &= short.MaxValue;
			}
		}
		pTr.trailEffect[work.trailId] = null;
		return 0;
	}

	private static int _amTrailUpdateNormal(AMS_TRAIL_EFFECT pEffect)
	{
		AMS_TRAIL_PARAM work = pEffect.Work;
		AMS_TRAIL_PARTSDATA aMS_TRAIL_PARTSDATA = pTr.trailData[work.trailId];
		AMS_TRAIL_PARTS aMS_TRAIL_PARTS = aMS_TRAIL_PARTSDATA.parts[work.trailPartsId];
		AMS_TRAIL_PARTS trailTail = aMS_TRAIL_PARTSDATA.trailTail;
		AMS_TRAIL_PARTS trailHead = aMS_TRAIL_PARTSDATA.trailHead;
		if ((work.state & -32768) != 0)
		{
			return 1;
		}
		AMS_TRAIL_PARTS pPrev = trailTail.pPrev;
		if (aMS_TRAIL_PARTS.pNext != null && aMS_TRAIL_PARTS == trailHead.pNext)
		{
			trailHead.pNext.pNext.pPrev = trailHead;
			trailHead.pNext = trailHead.pNext.pNext;
		}
		aMS_TRAIL_PARTS.Clear();
		aMS_TRAIL_PARTS.pNext = trailTail;
		aMS_TRAIL_PARTS.pPrev = trailTail.pPrev;
		trailTail.pPrev = aMS_TRAIL_PARTS;
		aMS_TRAIL_PARTS.pPrev.pNext = aMS_TRAIL_PARTS;
		if ((pEffect.flag & 1) != 0)
		{
			aMS_TRAIL_PARTS.pos.x = AMD_FX32_TO_FLOAT(work.trail_pos.x);
			aMS_TRAIL_PARTS.pos.y = 0f - AMD_FX32_TO_FLOAT(work.trail_pos.y);
			aMS_TRAIL_PARTS.pos.z = AMD_FX32_TO_FLOAT(work.zBias);
		}
		else
		{
			aMS_TRAIL_PARTS.pos.x = MppBitConverter.Int32ToSingle(work.trail_pos.x);
			aMS_TRAIL_PARTS.pos.y = MppBitConverter.Int32ToSingle(work.trail_pos.y);
			aMS_TRAIL_PARTS.pos.z = MppBitConverter.Int32ToSingle(work.trail_pos.z);
		}
		nnSubtractVector(aMS_TRAIL_PARTS.dir, aMS_TRAIL_PARTS.pos, aMS_TRAIL_PARTS.pPrev.pos);
		if (amIsZerof(aMS_TRAIL_PARTS.dir.x) && amIsZerof(aMS_TRAIL_PARTS.dir.y) && amIsZerof(aMS_TRAIL_PARTS.dir.z))
		{
			aMS_TRAIL_PARTS.dir.x = 1f;
		}
		_amTrailAddParts(aMS_TRAIL_PARTS, work);
		aMS_TRAIL_PARTS.m_Flag |= 1u;
		work.time -= amEffectGetUnitFrame();
		if (work.time < 0f)
		{
			work.time = 0f;
			work.state |= short.MinValue;
		}
		return 0;
	}

	private static void _amTrailDrawNormal(AMS_TRAIL_EFFECT pEffect)
	{
		AMS_TRAIL_PARAM work = pEffect.Work;
		AMS_TRAIL_PARTSDATA aMS_TRAIL_PARTSDATA = pTr.trailData[work.trailId];
		AMS_TRAIL_PARTS trailTail = aMS_TRAIL_PARTSDATA.trailTail;
		AMS_TRAIL_PARTS trailHead = aMS_TRAIL_PARTSDATA.trailHead;
		AMS_TRAIL_PARTS pPrev = trailTail.pPrev;
		if (trailTail.pPrev.pPrev == trailHead || work.time <= 0f)
		{
			return;
		}
		NNS_RGBA startColor = work.startColor;
		NNS_RGBA ptclColor = work.ptclColor;
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR2 = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR3 = GlobalPool<NNS_VECTOR>.Alloc();
		float num = 1f;
		float num2 = 0f;
		AMS_PARAM_DRAW_PRIMITIVE aMS_PARAM_DRAW_PRIMITIVE = GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Alloc();
		int ablend = 1;
		amDrawGetPrimBlendParam(work.blendType, aMS_PARAM_DRAW_PRIMITIVE);
		if (work.zTest != 0)
		{
			aMS_PARAM_DRAW_PRIMITIVE.zTest = 1;
		}
		if (work.zMask != 0)
		{
			aMS_PARAM_DRAW_PRIMITIVE.zMask = 1;
		}
		amVectorSet(nNS_VECTOR3, 0f, 0f, 1f);
		if (work.time < work.vanish_time)
		{
			num = work.time / work.vanish_time;
		}
		work.vanish_rate = num;
		startColor.a = work.startColor.a * num;
		ptclColor.a = work.ptclColor.a * num;
		float startSize = work.startSize;
		float ptclSize = work.ptclSize;
		if (work.ptclFlag != 0 && work.ptclTexId != -1)
		{
			NNS_PRIM3D_PCT_ARRAY nNS_PRIM3D_PCT_ARRAY = amDrawAlloc_NNS_PRIM3D_PCT(6);
			NNS_PRIM3D_PCT[] buffer = nNS_PRIM3D_PCT_ARRAY.buffer;
			int offset = nNS_PRIM3D_PCT_ARRAY.offset;
			num2 = nnDistanceVector(pPrev.pos, _am_ef_camPos);
			mppAssertNotImpl();
			buffer[offset].Col = AMD_FCOLTORGBA8888(ptclColor.r, ptclColor.g, ptclColor.b, ptclColor.a);
			buffer[offset + 1].Col = (buffer[offset + 2].Col = (buffer[offset + 5].Col = buffer[offset].Col));
			buffer[offset].Tex.u = 0f;
			buffer[offset].Tex.v = 0f;
			buffer[offset + 1].Tex.u = 1f;
			buffer[offset + 1].Tex.v = 0f;
			buffer[offset + 2].Tex.u = 0f;
			buffer[offset + 2].Tex.v = 1f;
			buffer[offset + 5].Tex.u = 1f;
			buffer[offset + 5].Tex.v = 1f;
			buffer[offset + 3] = buffer[offset + 1];
			buffer[offset + 4] = buffer[offset + 2];
			aMS_PARAM_DRAW_PRIMITIVE.format3D = 4;
			aMS_PARAM_DRAW_PRIMITIVE.type = 0;
			aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D = nNS_PRIM3D_PCT_ARRAY;
			aMS_PARAM_DRAW_PRIMITIVE.texlist = work.texlist;
			aMS_PARAM_DRAW_PRIMITIVE.texId = work.ptclTexId;
			aMS_PARAM_DRAW_PRIMITIVE.count = 6;
			aMS_PARAM_DRAW_PRIMITIVE.ablend = ablend;
			aMS_PARAM_DRAW_PRIMITIVE.sortZ = num2;
			amDrawPrimitive3D(pEffect.drawState, aMS_PARAM_DRAW_PRIMITIVE);
		}
		if (work.trailPartsNum < 3)
		{
			return;
		}
		if (work.texlist == null || work.texId == -1)
		{
			NNS_PRIM3D_PC[] array = amDrawAlloc_NNS_PRIM3D_PC(6 * (work.trailPartsNum - 1));
			NNS_PRIM3D_PC[] vtxPC3D = array;
			int num3 = 0;
			num2 = nnDistanceVector(pPrev.pos, _am_ef_camPos);
			nnCrossProductVector(nNS_VECTOR, nNS_VECTOR3, pPrev.dir);
			nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
			nnScaleVector(nNS_VECTOR2, nNS_VECTOR, startSize);
			nnAddVector(ref array[0].Pos, pPrev.pos, nNS_VECTOR2);
			nnAddVector(ref array[1].Pos, pPrev.pPrev.pos, nNS_VECTOR2);
			nnSubtractVector(ref array[2].Pos, pPrev.pos, nNS_VECTOR2);
			nnSubtractVector(ref array[5].Pos, pPrev.pPrev.pos, nNS_VECTOR2);
			array[5].Col = AMD_FCOLTORGBA8888(startColor.r, startColor.g, startColor.b, startColor.a);
			array[0].Col = (array[1].Col = (array[2].Col = array[5].Col));
			array[3] = array[1];
			array[4] = array[2];
			num3 += 6;
			pPrev = pPrev.pPrev;
			work.list_no = 1;
			while (pPrev != trailHead.pNext)
			{
				mppAssertNotImpl();
				pPrev.m_Flag &= 4294967293u;
				work.list_no++;
				_amTrailDrawPartsNormal(pPrev, work, array, num3);
				pPrev = pPrev.pPrev;
				num3 += 6;
			}
			aMS_PARAM_DRAW_PRIMITIVE.format3D = 2;
			aMS_PARAM_DRAW_PRIMITIVE.type = 0;
			aMS_PARAM_DRAW_PRIMITIVE.vtxPC3D = vtxPC3D;
			aMS_PARAM_DRAW_PRIMITIVE.texlist = work.texlist;
			aMS_PARAM_DRAW_PRIMITIVE.texId = work.texId;
			aMS_PARAM_DRAW_PRIMITIVE.count = 6 * (work.trailPartsNum - 1);
			aMS_PARAM_DRAW_PRIMITIVE.ablend = ablend;
			aMS_PARAM_DRAW_PRIMITIVE.sortZ = num2;
			amDrawPrimitive3D(pEffect.drawState, aMS_PARAM_DRAW_PRIMITIVE);
		}
		else
		{
			NNS_PRIM3D_PCT_ARRAY nNS_PRIM3D_PCT_ARRAY2 = amDrawAlloc_NNS_PRIM3D_PCT(6 * (work.trailPartsNum - 1));
			NNS_PRIM3D_PCT[] buffer2 = nNS_PRIM3D_PCT_ARRAY2.buffer;
			int offset2 = nNS_PRIM3D_PCT_ARRAY2.offset;
			int num4 = offset2;
			float num5 = (float)(work.trailPartsNum - 1) / (float)work.trailPartsNum;
			num5 *= work.vanish_rate;
			num2 = nnDistanceVector(pPrev.pos, _am_ef_camPos);
			nnCrossProductVector(nNS_VECTOR, nNS_VECTOR3, pPrev.dir);
			nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
			nnScaleVector(nNS_VECTOR2, nNS_VECTOR, startSize);
			nnAddVector(ref buffer2[offset2].Pos, pPrev.pos, nNS_VECTOR2);
			nnAddVector(ref buffer2[offset2 + 1].Pos, pPrev.pPrev.pos, nNS_VECTOR2);
			nnSubtractVector(ref buffer2[offset2 + 2].Pos, pPrev.pos, nNS_VECTOR2);
			nnSubtractVector(ref buffer2[offset2 + 5].Pos, pPrev.pPrev.pos, nNS_VECTOR2);
			buffer2[offset2 + 5].Col = AMD_FCOLTORGBA8888(startColor.r, startColor.g, startColor.b, startColor.a);
			buffer2[offset2].Col = (buffer2[offset2 + 1].Col = (buffer2[offset2 + 2].Col = buffer2[offset2 + 5].Col));
			buffer2[offset2].Tex.u = 1f;
			buffer2[offset2].Tex.v = 0f;
			buffer2[offset2 + 1].Tex.u = num5;
			buffer2[offset2 + 1].Tex.v = 0f;
			buffer2[offset2 + 2].Tex.u = 1f;
			buffer2[offset2 + 2].Tex.v = 1f;
			buffer2[offset2 + 5].Tex.u = num5;
			buffer2[offset2 + 5].Tex.v = 1f;
			buffer2[offset2 + 3] = buffer2[offset2 + 1];
			buffer2[offset2 + 4] = buffer2[offset2 + 2];
			num4 += 6;
			pPrev = pPrev.pPrev;
			work.list_no = 1;
			while (pPrev != trailHead.pNext)
			{
				pPrev.m_Flag &= 4294967293u;
				work.list_no++;
				_amTrailDrawPartsNormalTex(pPrev, work, buffer2, num4);
				pPrev = pPrev.pPrev;
				num4 += 6;
			}
			aMS_PARAM_DRAW_PRIMITIVE.format3D = 4;
			aMS_PARAM_DRAW_PRIMITIVE.type = 0;
			aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D = nNS_PRIM3D_PCT_ARRAY2;
			aMS_PARAM_DRAW_PRIMITIVE.texlist = work.texlist;
			aMS_PARAM_DRAW_PRIMITIVE.texId = work.texId;
			aMS_PARAM_DRAW_PRIMITIVE.count = 6 * (work.trailPartsNum - 1);
			aMS_PARAM_DRAW_PRIMITIVE.ablend = ablend;
			aMS_PARAM_DRAW_PRIMITIVE.sortZ = num2;
			amDrawPrimitive3D(pEffect.drawState, aMS_PARAM_DRAW_PRIMITIVE);
		}
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR2);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR3);
	}

	private static void _amTrailDrawPartsNormal(AMS_TRAIL_PARTS pNow, AMS_TRAIL_PARAM work, NNS_PRIM3D_PC[] _pv, int pv)
	{
		int num = pv - 6;
		float startSize = work.startSize;
		float num2 = (float)(work.trailPartsNum - work.list_no) / (float)work.trailPartsNum;
		startSize = work.startSize * num2 + work.endSize * (1f - num2);
		num2 *= work.vanish_rate;
		NNS_RGBA nNS_RGBA = default(NNS_RGBA);
		nNS_RGBA.r = work.startColor.r * num2 + work.endColor.r * (1f - num2);
		nNS_RGBA.g = work.startColor.g * num2 + work.endColor.g * (1f - num2);
		nNS_RGBA.b = work.startColor.b * num2 + work.endColor.b * (1f - num2);
		nNS_RGBA.a = work.startColor.a * num2 + work.endColor.a * (1f - num2);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR2 = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR3 = GlobalPool<NNS_VECTOR>.Alloc();
		nnDistanceVector(pNow.pos, _am_ef_camPos);
		amVectorSet(nNS_VECTOR3, 0f, 0f, 1f);
		nnCrossProductVector(nNS_VECTOR, nNS_VECTOR3, pNow.dir);
		nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
		nnScaleVector(nNS_VECTOR2, nNS_VECTOR, startSize);
		nnAddVector(ref _pv[pv + 1].Pos, pNow.pPrev.pos, nNS_VECTOR2);
		nnSubtractVector(ref _pv[pv + 5].Pos, pNow.pPrev.pos, nNS_VECTOR2);
		_pv[pv] = _pv[num + 1];
		_pv[pv + 2] = _pv[num + 5];
		_pv[pv + 4] = _pv[num + 2];
		_pv[pv + 5].Col = AMD_FCOLTORGBA8888(nNS_RGBA.r, nNS_RGBA.g, nNS_RGBA.b, nNS_RGBA.a);
		_pv[pv + 1].Col = _pv[pv + 5].Col;
		_pv[pv + 3] = _pv[pv + 1];
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR2);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR3);
	}

