	private static void _amTrailAddParts(AMS_TRAIL_PARTS pNew, AMS_TRAIL_PARAM work)
	{
		AMS_TRAIL_PARTSDATA aMS_TRAIL_PARTSDATA = pTr.trailData[work.trailId];
		AMS_TRAIL_PARTS trailHead = aMS_TRAIL_PARTSDATA.trailHead;
		pNew.time = work.life;
		pNew.partsId = work.trailPartsId;
		work.trailPartsId++;
		work.trailPartsNum++;
		if (work.trailPartsNum >= work.partsNum)
		{
			work.trailPartsNum = work.partsNum;
			work.trailPartsId = trailHead.pNext.partsId;
		}
		if (work.trailPartsNum >= 64)
		{
			work.trailPartsNum = 64;
			work.trailPartsId = trailHead.pNext.partsId;
		}
	}

	private static void _amTrailAddPosition(AMS_TRAIL_EFFECT pEffect, NNS_VECTOR offset)
	{
		AMS_TRAIL_PARAM work = pEffect.Work;
		AMS_TRAIL_PARTSDATA aMS_TRAIL_PARTSDATA = pTr.trailData[work.trailId];
		AMS_TRAIL_PARTS trailTail = aMS_TRAIL_PARTSDATA.trailTail;
		AMS_TRAIL_PARTS trailHead = aMS_TRAIL_PARTSDATA.trailHead;
		AMS_TRAIL_PARTS pPrev = trailTail.pPrev;
		if (trailTail.pPrev.pPrev != trailHead && !(work.time <= 0f))
		{
			while (pPrev != trailHead)
			{
				nnAddVector(pPrev.pos, pPrev.pos, offset);
				pPrev = pPrev.pPrev;
			}
		}
	}

	private static int _amTrailCalcSplinePos(NNS_VECTOR[] Pos, NNS_VECTOR[] Dir, AMS_TRAIL_PARTS pNPP, AMS_TRAIL_PARTS pNP, AMS_TRAIL_PARTS pNow, AMS_TRAIL_PARTS pNext, float len, int MaxComp)
	{
		AMTRS_FC_PARAM aMTRS_FC_PARAM = new AMTRS_FC_PARAM();
		aMTRS_FC_PARAM.m_flag = 0u;
		if (pNPP != null)
		{
			aMTRS_FC_PARAM.m_x[0] = pNPP.pos.x;
			aMTRS_FC_PARAM.m_y[0] = pNPP.pos.y;
			aMTRS_FC_PARAM.m_z[0] = pNPP.pos.z;
		}
		else
		{
			aMTRS_FC_PARAM.m_flag |= 1u;
		}
		aMTRS_FC_PARAM.m_x[1] = pNP.pos.x;
		aMTRS_FC_PARAM.m_y[1] = pNP.pos.y;
		aMTRS_FC_PARAM.m_z[1] = pNP.pos.z;
		aMTRS_FC_PARAM.m_x[2] = pNow.pos.x;
		aMTRS_FC_PARAM.m_y[2] = pNow.pos.y;
		aMTRS_FC_PARAM.m_z[2] = pNow.pos.z;
		if (pNext != null)
		{
			aMTRS_FC_PARAM.m_x[3] = pNext.pos.x;
			aMTRS_FC_PARAM.m_y[3] = pNext.pos.y;
			aMTRS_FC_PARAM.m_z[3] = pNext.pos.z;
		}
		else
		{
			aMTRS_FC_PARAM.m_flag |= 2u;
		}
		aMTRS_FC_PARAM.m_flag |= 512u;
		if (pNPP != null)
		{
			aMTRS_FC_PARAM.m_Dx[0] = pNPP.dir.x;
			aMTRS_FC_PARAM.m_Dy[0] = pNPP.dir.y;
			aMTRS_FC_PARAM.m_Dz[0] = pNPP.dir.z;
		}
		else
		{
			aMTRS_FC_PARAM.m_flag |= 1u;
		}
		aMTRS_FC_PARAM.m_Dx[1] = pNP.dir.x;
		aMTRS_FC_PARAM.m_Dy[1] = pNP.dir.y;
		aMTRS_FC_PARAM.m_Dz[1] = pNP.dir.z;
		aMTRS_FC_PARAM.m_Dx[2] = pNow.dir.x;
		aMTRS_FC_PARAM.m_Dy[2] = pNow.dir.y;
		aMTRS_FC_PARAM.m_Dz[2] = pNow.dir.z;
		if (pNext != null)
		{
			aMTRS_FC_PARAM.m_Dx[3] = pNext.dir.x;
			aMTRS_FC_PARAM.m_Dy[3] = pNext.dir.y;
			aMTRS_FC_PARAM.m_Dz[3] = pNext.dir.z;
		}
		else
		{
			aMTRS_FC_PARAM.m_flag |= 2u;
		}
		aMTRS_FC_PARAM.m_flag |= 512u;
		return _amTrailCalcSplinePos(Pos, Dir, aMTRS_FC_PARAM, len, MaxComp);
	}

	private static int _amTrailCalcSplinePos(NNS_VECTOR[] pos, NNS_VECTOR[] dir, AMTRS_FC_PARAM FcWk, float len, int MaxComp)
	{
		int num = (int)len;
		num = (int)amClamp(num, 0f, MaxComp);
		int num2 = 0;
		_amTrailCalcSpline(FcWk, FcWk.m_x);
		for (num2 = 0; num2 < num; num2++)
		{
			float t = (float)(num2 + 1) / (float)(num + 1);
			pos[num2].x = _amTrailGetValue(FcWk, t);
		}
		_amTrailCalcSpline(FcWk, FcWk.m_y);
		for (num2 = 0; num2 < num; num2++)
		{
			float t = (float)(num2 + 1) / (float)(num + 1);
			pos[num2].y = _amTrailGetValue(FcWk, t);
		}
		_amTrailCalcSpline(FcWk, FcWk.m_z);
		for (num2 = 0; num2 < num; num2++)
		{
			float t = (float)(num2 + 1) / (float)(num + 1);
			pos[num2].z = _amTrailGetValue(FcWk, t);
		}
		_amTrailCalcSpline(FcWk, FcWk.m_Dx);
		for (num2 = 0; num2 < num; num2++)
		{
			float t = (float)(num2 + 1) / (float)(num + 1);
			dir[num2].x = _amTrailGetValue(FcWk, t);
		}
		_amTrailCalcSpline(FcWk, FcWk.m_Dy);
		for (num2 = 0; num2 < num; num2++)
		{
			float t = (float)(num2 + 1) / (float)(num + 1);
			dir[num2].y = _amTrailGetValue(FcWk, t);
		}
		_amTrailCalcSpline(FcWk, FcWk.m_Dz);
		for (num2 = 0; num2 < num; num2++)
		{
			float t = (float)(num2 + 1) / (float)(num + 1);
			dir[num2].z = _amTrailGetValue(FcWk, t);
		}
		return num;
	}

	private static void _amTrailCalcSpline(AMTRS_FC_PARAM param, float[] P)
	{
		float num = 0f;
		float num2 = 0f;
		switch (param.m_flag & 3)
		{
		case 2u:
			num = (P[2] - P[0]) / 1f;
			num2 = (P[2] - P[1]) / 4f;
			break;
		case 1u:
			num = (P[2] - P[1]) / 4f;
			num2 = (P[3] - P[1]) / 1f;
			break;
		default:
			num = (P[2] - P[0]) / 2f;
			num2 = (P[3] - P[1]) / 2f;
			break;
		}
		param.m_CalcParam.x = 2f * P[1] - 2f * P[2] + num + num2;
		param.m_CalcParam.y = -3f * P[1] + 3f * P[2] - 2f * num - num2;
		param.m_CalcParam.z = num;
		param.m_CalcParam.w = P[1];
		param.m_flag |= 256u;
	}

	private static float _amTrailGetValue(AMTRS_FC_PARAM param, float t)
	{
		float result = 0f;
		if ((param.m_flag & 0x100) == 0)
		{
			return result;
		}
		NNS_VECTOR4D calcParam = param.m_CalcParam;
		return t * t * t * calcParam.x + t * t * calcParam.y + t * calcParam.z;
	}

	public static void GmPauseInit()
	{
		uint num = 0u;
		ObjObjectPause(2);
		g_gm_main_system.game_flag |= 64u;
		g_gm_main_system.game_flag &= 4294967167u;
		num = g_gm_main_system.game_flag & 0xC00;
		g_gm_main_system.game_flag &= 4294964223u;
		gm_pause_tcb = MTM_TASK_MAKE_TCB(gmPauseMain, gmPauseDest, 0u, 3, 28928u, 6, () => new GMS_PAUSE_WORK(), "GM_PAUSE");
		GMS_PAUSE_WORK gMS_PAUSE_WORK = (GMS_PAUSE_WORK)gm_pause_tcb.work;
		gMS_PAUSE_WORK.Clear();
		gMS_PAUSE_WORK.time_count_flag_save = num;
		gmPauseProcUpdateInit(gMS_PAUSE_WORK);
	}

	private static void GmPauseExit()
	{
		if (!GmPauseMenuIsFinished())
		{
			GmPauseMenuCancel();
		}
		if (gm_pause_tcb != null)
		{
			mtTaskClearTcb(gm_pause_tcb);
			gm_pause_tcb = null;
		}
	}

	public static bool GmPauseCheckExecutable()
	{
		if (gm_pause_tcb == null && (g_gm_main_system.game_flag & 0x1F710E8) == 0 && g_gm_main_system.ply_work[0] != null && (g_gm_main_system.ply_work[0].player_flag & 0x400) == 0)
		{
			return true;
		}
		return false;
	}

	private static void gmPauseDest(MTS_TASK_TCB tcb)
	{
		GMS_PAUSE_WORK gMS_PAUSE_WORK = (GMS_PAUSE_WORK)tcb.work;
		g_gm_main_system.game_flag |= gMS_PAUSE_WORK.time_count_flag_save & 0xC00;
		g_gm_main_system.game_flag &= 4294967231u;
		gm_pause_tcb = null;
	}

	private static void gmPauseMain(MTS_TASK_TCB tcb)
	{
		GMS_PAUSE_WORK gMS_PAUSE_WORK = (GMS_PAUSE_WORK)tcb.work;
		bool prevUi = amUiEnqueue;
		amUiEnqueue = true;
		try
		{
			if (gMS_PAUSE_WORK.proc_update != null)
			{
				gMS_PAUSE_WORK.proc_update(gMS_PAUSE_WORK);
			}
		}
		finally
		{
			amUiEnqueue = prevUi;
		}
		if ((gMS_PAUSE_WORK.flag & 1) != 0)
		{
			mtTaskClearTcb(tcb);
		}
	}

	private static void gmPauseExecRecoverRoutine(GMS_PAUSE_WORK pause_work, bool b_rec_snd)
	{
		ObjObjectPauseOut();
		pause_work.flag |= 1u;
		if (b_rec_snd)
		{
			GmSoundAllResume();
		}
	}

	private static void gmPauseProcUpdateInit(GMS_PAUSE_WORK pause_work)
	{
		pause_work.proc_update = gmPauseProcUpdatePauseMenuStart;
	}

	private static void gmPauseProcUpdateReinit(GMS_PAUSE_WORK pause_work)
	{
		GmPauseMenuStart(28928u);
		pause_work.proc_update = gmPauseProcUpdateWaitDecision;
	}

	private static void gmPauseProcUpdatePauseMenuStart(GMS_PAUSE_WORK pause_work)
	{
		GmSoundAllPause();
		GmPauseMenuStart(28928u);
		pause_work.proc_update = gmPauseProcUpdateWaitDecision;
	}

	private static void gmPauseProcUpdateWaitDecision(GMS_PAUSE_WORK pause_work)
	{
		if (GmPauseMenuIsFinished())
		{
			int num = GmPauseMenuGetResult();
			bool flag = false;
			switch (num)
			{
			case 1:
				flag = true;
				pause_work.proc_update = gmPauseProcUpdateFadeOutToOption;
				break;
			case 0:
			case 2:
			case 3:
				SaveState.deleteSave();
				flag = true;
				pause_work.proc_update = gmPauseProcUpdateFadeOutToExitGame;
				break;
			default:
				gmPauseExecRecoverRoutine(pause_work, true);
				pause_work.proc_update = null;
				break;
			}
			if (flag)
			{
				IzFadeInitEasyColor(0, 32767, 61439, 18u, 0u, 1u, 20f, true);
			}
		}
	}

	private static void gmPauseProcUpdateFadeOutToOption(GMS_PAUSE_WORK pause_work)
	{
		if (IzFadeIsEnd())
		{
			DmOptionStart(null);
			pause_work.proc_update = gmPauseProcUpdateWaitRecover;
		}
	}

	private static void gmPauseProcUpdateWaitRecover(GMS_PAUSE_WORK pause_work)
	{
		bool flag = true;
		if (!DmOptionIsExit())
		{
			flag = false;
		}
		if (flag)
		{
			IzFadeInitEasyColor(0, 32767, 61439, 18u, 1u, 0u, 20f, true);
			pause_work.proc_update = gmPauseProcUpdateFadeInFromDemo;
		}
	}

	private static void gmPauseProcUpdateFadeInFromDemo(GMS_PAUSE_WORK pause_work)
	{
		if (IzFadeIsEnd())
		{
			IzFadeExit();
			gmPauseProcUpdateReinit(pause_work);
		}
	}

	private static void gmPauseProcUpdateFadeOutToExitGame(GMS_PAUSE_WORK pause_work)
	{
		if (IzFadeIsEnd())
		{
			g_gm_main_system.game_flag |= 128u;
			gmPauseExecRecoverRoutine(pause_work, false);
		}
	}

