	private static void gmGmkSlot_ReelControl(GMS_GMK_SLOT_REEL_STATUS_WORK preel)
	{
		if (preel.reel_time > 0)
		{
			preel.reel_time--;
		}
		if (preel.reel_time <= 0 && preel.reel_acc != 0)
		{
			preel.reel_spd += preel.reel_acc;
			if (preel.reel_spd > GMD_GMK_SLOT_REEL_MAX_SPEED)
			{
				preel.reel_spd = GMD_GMK_SLOT_REEL_MAX_SPEED;
				preel.reel_acc = 0;
			}
			else if (preel.reel_spd < 0)
			{
				preel.reel_spd = 0;
				preel.reel_acc = 0;
			}
		}
		preel.reel += (short)preel.reel_spd;
	}

	private static void gmGmkSlotStart(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SLOT_WORK gMS_GMK_SLOT_WORK = (GMS_GMK_SLOT_WORK)obj_work;
		gMS_GMK_SLOT_WORK.reel_status[0].reel = (short)(GMD_GMK_SLOT_REEL1KOMA_HEIGHT * 15);
		GMS_GMK_SLOT_REEL_STATUS_WORK obj = gMS_GMK_SLOT_WORK.reel_status[1];
		short gMD_GMK_SLOT_REEL1KOMA_HEIGHT = GMD_GMK_SLOT_REEL1KOMA_HEIGHT;
		obj.reel = (short)0;
		gMS_GMK_SLOT_WORK.reel_status[2].reel = GMD_GMK_SLOT_REEL1KOMA_HEIGHT;
		gMS_GMK_SLOT_WORK.reel_status[0].reel_spd = 0;
		gMS_GMK_SLOT_WORK.reel_status[1].reel_spd = 0;
		gMS_GMK_SLOT_WORK.reel_status[2].reel_spd = 0;
		gMS_GMK_SLOT_WORK.reel_status[0].reel_acc = 0;
		gMS_GMK_SLOT_WORK.reel_status[1].reel_acc = 0;
		gMS_GMK_SLOT_WORK.reel_status[2].reel_acc = 0;
		gMS_GMK_SLOT_WORK.reel_status[0].reel_time = 0;
		gMS_GMK_SLOT_WORK.reel_status[1].reel_time = 0;
		gMS_GMK_SLOT_WORK.reel_status[2].reel_time = 0;
		gMS_GMK_SLOT_WORK.prob[0] = GMD_GMK_SLOT_PROB_JJJ;
		gMS_GMK_SLOT_WORK.prob[1] = GMD_GMK_SLOT_PROB_EEE;
		gMS_GMK_SLOT_WORK.prob[2] = GMD_GMK_SLOT_PROB_SSS;
		gMS_GMK_SLOT_WORK.prob[4] = GMD_GMK_SLOT_PROB_BBB;
		gMS_GMK_SLOT_WORK.prob[3] = GMD_GMK_SLOT_PROB_RRR;
		obj_work.ppFunc = gmGmkSlotStay;
	}

	private static void gmGmkSlotStay(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SLOT_WORK gMS_GMK_SLOT_WORK = (GMS_GMK_SLOT_WORK)obj_work;
		rand_result <<= 16;
		rand_result += mtMathRand();
		if (slot_start_call == gMS_GMK_SLOT_WORK.slot_id)
		{
			gmGmkSlotGameStart(obj_work);
		}
	}

	private static uint getRand()
	{
		rand_result = rand_result % 13 * 330382099 + rand_result / 13;
		return rand_result;
	}

	private static void gmGmkSlotGameStart(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SLOT_WORK gMS_GMK_SLOT_WORK = (GMS_GMK_SLOT_WORK)obj_work;
		gMS_GMK_SLOT_WORK.slot_step = 0;
		gMS_GMK_SLOT_WORK.current_reel = 0;
		gMS_GMK_SLOT_WORK.slot_se_timer = 0;
		int num = (int)(rand_result % 100);
		num -= GMD_GMK_SLOT_1ST_LOT;
		if (num >= 0)
		{
			num = num * 100 / (100 - GMD_GMK_SLOT_1ST_LOT);
			int i;
			for (i = 0; i < 5; i++)
			{
				num -= gMS_GMK_SLOT_WORK.prob[i];
				if (num <= 0)
				{
					gMS_GMK_SLOT_WORK.prob[i] = tbl_gmk_slot_prob[i];
					break;
				}
				if (gMS_GMK_SLOT_WORK.prob[i] < tbl_gmk_slot_prob_max[i])
				{
					gMS_GMK_SLOT_WORK.prob[i] += tbl_gmk_slot_prob[i];
					if (gMS_GMK_SLOT_WORK.prob[i] > tbl_gmk_slot_prob_max[i])
					{
						gMS_GMK_SLOT_WORK.prob[i] = tbl_gmk_slot_prob_max[i];
					}
				}
			}
			gMS_GMK_SLOT_WORK.lotresult = (short)i;
			if (i != 5)
			{
				gMS_GMK_SLOT_WORK.reel_status[0].reel_target_mark = (gMS_GMK_SLOT_WORK.reel_status[1].reel_target_mark = (gMS_GMK_SLOT_WORK.reel_status[2].reel_target_mark = i));
			}
			else
			{
				int num2 = 0;
				for (i = 0; i < 3; i++)
				{
					gMS_GMK_SLOT_WORK.reel_status[i].reel_target_mark = (int)(getRand() % 5);
					if (gMS_GMK_SLOT_WORK.reel_status[i].reel_target_mark == 4)
					{
						num2++;
					}
				}
				int num3 = (int)(getRand() % 3);
				if (num2 <= 1)
				{
					gMS_GMK_SLOT_WORK.lotresult = 5;
					if (num2 == 0)
					{
						gMS_GMK_SLOT_WORK.reel_status[num3].reel_target_mark = 4;
					}
				}
				else if (num2 >= 2)
				{
					gMS_GMK_SLOT_WORK.lotresult = 6;
					if (num2 == 3)
					{
						gMS_GMK_SLOT_WORK.reel_status[num3].reel_target_mark = (int)(getRand() % 4);
					}
				}
			}
		}
		else if (num < -GMD_GMK_SLOT_EGG_LOT)
		{
			gMS_GMK_SLOT_WORK.lotresult = -1;
			for (int j = 0; j < 3; j++)
			{
				gMS_GMK_SLOT_WORK.reel_status[j].reel_target_mark = (int)(getRand() % 4);
			}
			if (gMS_GMK_SLOT_WORK.reel_status[0].reel_target_mark == gMS_GMK_SLOT_WORK.reel_status[1].reel_target_mark && gMS_GMK_SLOT_WORK.reel_status[1].reel_target_mark == gMS_GMK_SLOT_WORK.reel_status[2].reel_target_mark)
			{
				if (gMS_GMK_SLOT_WORK.reel_status[0].reel_target_mark == 1)
				{
					gMS_GMK_SLOT_WORK.lotresult = 8;
				}
				else
				{
					int num4;
					do
					{
						num4 = (int)(getRand() % 4);
					}
					while (gMS_GMK_SLOT_WORK.reel_status[0].reel_target_mark == num4);
					gMS_GMK_SLOT_WORK.reel_status[2].reel_target_mark = num4;
				}
			}
		}
		else
		{
			gMS_GMK_SLOT_WORK.reel_status[0].reel_target_mark = (gMS_GMK_SLOT_WORK.reel_status[1].reel_target_mark = (gMS_GMK_SLOT_WORK.reel_status[2].reel_target_mark = 1));
			gMS_GMK_SLOT_WORK.lotresult = 8;
		}
		for (int k = 0; k < 3; k++)
		{
			ushort num5 = (ushort)getRand();
			do
			{
				num5 = (ushort)((num5 + 1) % GMD_GMK_SLOT_REEL_ALLMARK);
				gMS_GMK_SLOT_WORK.reel_status[k].reel_target_pos = num5;
			}
			while (tbl_gmk_reel_mark[k][(GMD_GMK_SLOT_REEL_ALLMARK - num5) & 0xF] != gMS_GMK_SLOT_WORK.reel_status[k].reel_target_mark);
		}
		gMS_GMK_SLOT_WORK.freestop = 0;
		gmGmkSlotGameStart_100(obj_work);
		obj_work.ppFunc = gmGmkSlotGameStart_100;
	}

	private static void gmGmkSlotGameStart_100(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SLOT_WORK gMS_GMK_SLOT_WORK = (GMS_GMK_SLOT_WORK)obj_work;
		if (gMS_GMK_SLOT_WORK.timer <= 0)
		{
			GMS_GMK_SLOT_REEL_STATUS_WORK gMS_GMK_SLOT_REEL_STATUS_WORK = gMS_GMK_SLOT_WORK.reel_status[gMS_GMK_SLOT_WORK.current_reel];
			switch (gMS_GMK_SLOT_WORK.slot_step)
			{
			case 0:
				gMS_GMK_SLOT_WORK.reel_status[0].reel_time = 0;
				gMS_GMK_SLOT_WORK.reel_status[1].reel_time = 15;
				gMS_GMK_SLOT_WORK.reel_status[2].reel_time = 30;
				gMS_GMK_SLOT_WORK.reel_status[0].reel_acc = GMD_GMK_SLOT_REEL_ACC;
				gMS_GMK_SLOT_WORK.reel_status[1].reel_acc = GMD_GMK_SLOT_REEL_ACC;
				gMS_GMK_SLOT_WORK.reel_status[2].reel_acc = GMD_GMK_SLOT_REEL_ACC;
				gMS_GMK_SLOT_WORK.timer = 10;
				gMS_GMK_SLOT_WORK.timer += mtMathRand() % 1;
				gMS_GMK_SLOT_WORK.slot_step = 10;
				break;
			case 10:
				gMS_GMK_SLOT_WORK.current_reel = 0;
				gMS_GMK_SLOT_WORK.slot_step = 40;
				gMS_GMK_SLOT_WORK.timer_next = 0;
				gMS_GMK_SLOT_WORK.freestop = 1;
				gMS_GMK_SLOT_WORK.timer = 0;
				break;
			case 20:
				gMS_GMK_SLOT_WORK.current_reel = 1;
				gMS_GMK_SLOT_WORK.slot_step = 40;
				gMS_GMK_SLOT_WORK.timer_next = 0;
				gMS_GMK_SLOT_WORK.freestop = 1;
				gMS_GMK_SLOT_WORK.timer = 0;
				break;
