				}
				else if (gMS_GMK_SLOT_WORK.current_reel == 1)
				{
					gMS_GMK_SLOT_WORK.timer = gMS_GMK_SLOT_WORK.timer_next;
					gMS_GMK_SLOT_WORK.timer += mtMathRand() % 1;
					gMS_GMK_SLOT_WORK.slot_step = 30;
				}
				else
