	private static void gmGmkSlotGameHit(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SLOT_WORK gMS_GMK_SLOT_WORK = (GMS_GMK_SLOT_WORK)obj_work;
		if (gMS_GMK_SLOT_WORK.lotresult != 1)
		{
			GmRingSlotSetNum(slot_start_player, tbl_slot_bonus_ring[gMS_GMK_SLOT_WORK.lotresult]);
			obj_work.ppFunc = gmGmkSlotGameHit_100;
		}
		else
		{
			GmEfctCmnEsCreate(slot_start_player.obj_work, 96);
			obj_work.ppFunc = gmGmkSlotGameHit_200;
			gMS_GMK_SLOT_WORK.timer = 30;
		}
	}

	private static void gmGmkSlotGameHit_100(OBS_OBJECT_WORK obj_work)
	{
		if (GmRingCheckRestSlotRing() == 0)
		{
			GMS_GMK_SLOT_WORK gMS_GMK_SLOT_WORK = (GMS_GMK_SLOT_WORK)obj_work;
			GmPlayerAddScore(slot_start_player, tbl_slot_bonus_score[gMS_GMK_SLOT_WORK.lotresult], slot_start_player.obj_work.pos.x, slot_start_player.obj_work.pos.y);
			slot_start_call = -1;
			obj_work.ppFunc = gmGmkSlotStay;
		}
	}

	private static void gmGmkSlotGameHit_200(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SLOT_WORK gMS_GMK_SLOT_WORK = (GMS_GMK_SLOT_WORK)obj_work;
		gMS_GMK_SLOT_WORK.timer--;
		if (gMS_GMK_SLOT_WORK.timer <= 0)
		{
			gMS_GMK_SLOT_WORK.ppos_x = slot_start_player.obj_work.pos.x;
			gMS_GMK_SLOT_WORK.ppos_y = slot_start_player.obj_work.pos.y;
			gMS_GMK_SLOT_WORK.timer = 100;
			obj_work.ppFunc = gmGmkSlotGameHit_210;
		}
	}

	private static void gmGmkSlotGameHit_210(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SLOT_WORK gMS_GMK_SLOT_WORK = (GMS_GMK_SLOT_WORK)obj_work;
		slot_start_player.obj_work.pos.x = gMS_GMK_SLOT_WORK.ppos_x + (tbl_dam_ofst_xy[gMS_GMK_SLOT_WORK.timer % 8][0] << 12);
		slot_start_player.obj_work.pos.y = gMS_GMK_SLOT_WORK.ppos_y + (tbl_dam_ofst_xy[gMS_GMK_SLOT_WORK.timer % 8][1] << 12);
		GmPlayerRingDec(slot_start_player, 1);
		if (gMS_GMK_SLOT_WORK.timer % 12 == 0)
		{
			GmSoundPlaySE("Damage2");
		}
		gMS_GMK_SLOT_WORK.timer--;
		if (gMS_GMK_SLOT_WORK.timer <= 0)
		{
			slot_start_player.obj_work.pos.x = gMS_GMK_SLOT_WORK.ppos_x;
			slot_start_player.obj_work.pos.y = gMS_GMK_SLOT_WORK.ppos_y;
			slot_start_call = -1;
			obj_work.ppFunc = gmGmkSlotStay;
		}
	}

	private static void gmGmkSlotGameLose(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SLOT_WORK gMS_GMK_SLOT_WORK = (GMS_GMK_SLOT_WORK)obj_work;
		slot_start_call = -1;
		obj_work.ppFunc = gmGmkSlotStay;
	}

	private static void gmGmkSlot_CreateReel(GMS_GMK_SLOT_WORK pwork)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)pwork;
		for (int i = 0; i < 3; i++)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GMM_EFFECT_CREATE_WORK(() => new GMS_GMK_SLOTPARTS_WORK(), null, 0, "Gmk_SlotReel");
			GMS_GMK_SLOTPARTS_WORK gMS_GMK_SLOTPARTS_WORK = (GMS_GMK_SLOTPARTS_WORK)oBS_OBJECT_WORK2;
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK2, gm_gmk_slot_obj_3d_list[tbl_gmk_slot_reelmodel_id[i]], gMS_GMK_SLOTPARTS_WORK.eff_work.obj_3d);
			oBS_OBJECT_WORK2.parent_obj = oBS_OBJECT_WORK;
			oBS_OBJECT_WORK2.pos.x = oBS_OBJECT_WORK.pos.x + (48 * i - 48) * 4096;
			oBS_OBJECT_WORK2.pos.y = oBS_OBJECT_WORK.pos.y;
			oBS_OBJECT_WORK2.pos.z = oBS_OBJECT_WORK.pos.z;
			oBS_OBJECT_WORK2.obj_3d.drawflag |= 268435456u;
			oBS_OBJECT_WORK2.flag &= 4294966271u;
			oBS_OBJECT_WORK2.flag |= 2u;
			oBS_OBJECT_WORK2.move_flag |= 256u;
			oBS_OBJECT_WORK2.disp_flag &= 4294967039u;
			oBS_OBJECT_WORK2.disp_flag |= 138412032u;
			oBS_OBJECT_WORK2.ppFunc = gmGmkSlotReel;
			gMS_GMK_SLOTPARTS_WORK.reel_id = i;
			gMS_GMK_SLOTPARTS_WORK.slot_work = pwork;
		}
	}

	private static void gmGmkSlotReel(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SLOTPARTS_WORK gMS_GMK_SLOTPARTS_WORK = (GMS_GMK_SLOTPARTS_WORK)obj_work;
		ushort num = (ushort)((ushort)gMS_GMK_SLOTPARTS_WORK.slot_work.reel_status[gMS_GMK_SLOTPARTS_WORK.reel_id].reel >> 12);
		int num2 = tbl_reel_tex_u[num / 5];
		int num3 = tbl_reel_tex_v[num2][num % 5] << 12;
		num3 += gMS_GMK_SLOTPARTS_WORK.slot_work.reel_status[gMS_GMK_SLOTPARTS_WORK.reel_id].reel & 0xFFF;
		float num4 = (float)num3 / 32768f;
		float u = (float)num2 / 8f;
		gMS_GMK_SLOTPARTS_WORK.eff_work.obj_3d.draw_state.texoffset[0].v = 0f - num4;
		gMS_GMK_SLOTPARTS_WORK.eff_work.obj_3d.draw_state.texoffset[0].u = u;
	}

	private static int GmGmkSlotStartRequest(int slot_id, GMS_PLAYER_WORK ply_work)
	{
		if (slot_start_call != -1)
		{
			return 0;
		}
		slot_start_call = slot_id;
		slot_start_player = ply_work;
		return 1;
	}

	private static int GmGmkSlotIsStatus(int slot_id)
	{
		if (slot_start_call == -1)
		{
			return 1;
		}
		UNREFERENCED_PARAMETER(slot_id);
		return 0;
	}

	private static OBS_OBJECT_WORK GmGmkSlotInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		GMS_GMK_SLOT_WORK gMS_GMK_SLOT_WORK = (GMS_GMK_SLOT_WORK)GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_SLOT_WORK(), "Gmk_Slot");
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gMS_GMK_SLOT_WORK;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)gMS_GMK_SLOT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_slot_obj_3d_list[3], gMS_ENEMY_3D_WORK.obj_3d);
		ObjAction3dNNMaterialMotionLoad(gMS_ENEMY_3D_WORK.obj_3d, 0, null, null, 0, (AMS_AMB_HEADER)ObjDataGet(875).pData, 1, 1);
		ObjDrawAction3dActionSet3DNNMaterial(gMS_ENEMY_3D_WORK.obj_3d, 0);
		oBS_OBJECT_WORK.pos.z = -135168;
		oBS_OBJECT_WORK.move_flag |= 256u;
		oBS_OBJECT_WORK.disp_flag |= 4194308u;
		gMS_GMK_SLOT_WORK.slot_id = eve_rec.left;
		if (slot_start_call == 0)
		{
			slot_start_call = -1;
		}
		gmGmkSlot_CreateReel(gMS_GMK_SLOT_WORK);
		gmGmkSlotStart(oBS_OBJECT_WORK);
		return oBS_OBJECT_WORK;
	}

	private static void GmGmkSlotBuild()
	{
		gm_gmk_slot_obj_3d_list = GmGameDBuildRegBuildModel(GmGameDatGetGimmickData(873), GmGameDatGetGimmickData(874), 0u);
		slot_start_call = 0;
	}

	private static void GmGmkSlotFlush()
	{
		AMS_AMB_HEADER aMS_AMB_HEADER = GmGameDatGetGimmickData(873);
		GmGameDBuildRegFlushModel(gm_gmk_slot_obj_3d_list, aMS_AMB_HEADER.file_num);
	}

	private static void GmGmkBumperBuild()
	{
