	private static GMS_ENEMY_3D_WORK gmGmkBumperLoadObjNoModel(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, int type)
	{
		UNREFERENCED_PARAMETER(type);
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_BUMPER_WORK(), "GMK_BUMPER");
