	private static GMS_ENEMY_3D_WORK gmGmkBumperLoadObj(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, int type)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = gmGmkBumperLoadObjNoModel(eve_rec, pos_x, pos_y, type);
		OBS_OBJECT_WORK obj_work = gMS_ENEMY_3D_WORK.ene_com.obj_work;
		int num = g_gm_gmk_bumper_model_id[type];
		ObjObjectCopyAction3dNNModel(obj_work, g_gm_gmk_bumper_obj_3d_list[num], gMS_ENEMY_3D_WORK.obj_3d);
		int index = g_gm_gmk_bumper_motion_id[type];
		object pData = ObjDataGet(855).pData;
		ObjObjectAction3dNNMaterialMotionLoad(obj_work, 0, null, null, index, pData);
		return gMS_ENEMY_3D_WORK;
	}

	private static void gmGmkBumperInit(OBS_OBJECT_WORK obj_work, int bumper_type)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		gmGmkBumperSetRect(gMS_ENEMY_3D_WORK, bumper_type);
		obj_work.move_flag = 8448u;
		obj_work.dir.z = g_gm_gmk_bumper_angle_z[bumper_type];
		ObjDrawObjectActionSet3DNNMaterial(obj_work, 0);
		obj_work.disp_flag |= 4194324u;
		obj_work.pos.z = -122880;
		GMS_GMK_BUMPER_WORK gMS_GMK_BUMPER_WORK = (GMS_GMK_BUMPER_WORK)gMS_ENEMY_3D_WORK;
		gMS_GMK_BUMPER_WORK.se_handle = GsSoundAllocSeHandle();
		obj_work.ppFunc = null;
		obj_work.ppMove = null;
		obj_work.ppOut = gmGmkBumperDrawFunc;
		mtTaskChangeTcbDestructor(obj_work.tcb, gmGmkBumperDestFunc);
	}

	private static void gmGmkBumperSetRect(GMS_ENEMY_3D_WORK gimmick_work, int bumper_type)
	{
		OBS_RECT_WORK oBS_RECT_WORK = gimmick_work.ene_com.rect_work[2];
		short cLeft = g_gmk_bumper_rect[bumper_type][0];
		short cRight = g_gmk_bumper_rect[bumper_type][2];
		short cTop = g_gmk_bumper_rect[bumper_type][1];
		short cBottom = g_gmk_bumper_rect[bumper_type][3];
		ObjRectWorkZSet(oBS_RECT_WORK, cLeft, cTop, -500, cRight, cBottom, 500);
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		oBS_RECT_WORK.ppDef = gmGmkBumperDefFunc;
	}

	private static void gmGmkBumperDestFunc(MTS_TASK_TCB tcb)
	{
		GMS_GMK_BUMPER_WORK gMS_GMK_BUMPER_WORK = ((tcb.work is GMS_GMK_BUMPER_WORK) ? ((GMS_GMK_BUMPER_WORK)tcb.work) : ((GMS_GMK_BUMPER_WORK)mtTaskGetTcbWork(tcb)));
		if (gMS_GMK_BUMPER_WORK.se_handle != null)
		{
			GmSoundStopSE(gMS_GMK_BUMPER_WORK.se_handle);
			GsSoundFreeSeHandle(gMS_GMK_BUMPER_WORK.se_handle);
			gMS_GMK_BUMPER_WORK.se_handle = null;
		}
		GmEnemyDefaultExit(tcb);
	}

	private static void gmGmkBumperDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		OBS_ACTION3D_NN_WORK obj_3d = obj_work.obj_3d;
		if (obj_3d.motion != null)
		{
			float num = amMotionMaterialGetStartFrame(obj_3d.motion, obj_3d.mat_act_id);
			float num2 = amMotionMaterialGetEndFrame(obj_3d.motion, obj_3d.mat_act_id);
			float num3 = num2 - num;
			float num4 = gmGmkBumpereGameSystemGetSyncTime();
			obj_3d.mat_frame = num4 % num3;
		}
		ObjDrawActionSummary(obj_work);
	}

