		{
			VecFx32 line_end = new VecFx32(gimmick_pos);
			line_end.x += FX_F32_TO_FX32((float)g_gmk_bumper_rect[type][2] * 0.2f);
			line_end.y += FX_F32_TO_FX32(g_gmk_bumper_rect[type][1]);
			VecFx32 line_start = new VecFx32(gimmick_pos);
			line_start.x += FX_F32_TO_FX32(g_gmk_bumper_rect[type][0]);
			line_start.y += FX_F32_TO_FX32((float)g_gmk_bumper_rect[type][1] * 0.2f);
			if (gmGmkBumperCheckLeft(line_start, line_end, target_pos))
			{
				return false;
			}
			break;
		}
		}
		return true;
	}

	private static bool gmGmkBumperCheckLeft(VecFx32 line_start, VecFx32 line_end, VecFx32 point)
	{
		int v = line_end.x - line_start.x;
		int v2 = line_end.y - line_start.y;
		int v3 = point.x - line_start.x;
		int v4 = point.y - line_start.y;
		int num = FX_Mul(v, v4) - FX_Mul(v2, v3);
		if (num <= 0)
		{
			return true;
		}
		return false;
	}

	private static bool gmGmkBumperCheckHitEffect(GMS_GMK_BUMPER_WORK bumper_work)
	{
		if (bumper_work.se_handle == null)
		{
			return false;
		}
		if (bumper_work.se_handle.au_player == null)
		{
			return false;
		}
		if (2 == bumper_work.se_handle.au_player.GetStatus() || 1 == bumper_work.se_handle.au_player.GetStatus())
		{
			return false;
		}
		return true;
	}

