			num = 2;
			break;
		case 2:
			array = gm_eve_local_deco_obj_use_flag;
			num = 2;
			break;
		default:
			return 0;
		}
		for (short num2 = 0; num2 < num; num2++)
		{
			if (array[num2] < uint.MaxValue)
			{
				for (short num3 = 0; num3 < 32; num3++)
				{
