	private static void GmEnemyDefaultDefFunc(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = null;
		if (match_rect.parent_obj != null && match_rect.parent_obj.obj_type == 1)
		{
			gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		}
		if (gMS_ENEMY_COM_WORK.vit == 0)
		{
			if ((gMS_ENEMY_COM_WORK.obj_work.move_flag & 0x1000) == 0 || gMS_ENEMY_COM_WORK.obj_work.obj_type == 3)
			{
				gMS_ENEMY_COM_WORK.enemy_flag |= 65536u;
			}
			gMS_ENEMY_COM_WORK.obj_work.flag |= 2u;
			gMS_ENEMY_COM_WORK.rect_work[0].flag |= 2048u;
			gMS_ENEMY_COM_WORK.rect_work[1].flag |= 2048u;
			gMS_ENEMY_COM_WORK.rect_work[2].flag |= 2048u;
			if (gMS_ENEMY_COM_WORK.obj_work.obj_type == 2)
			{
				GmSoundPlaySE("Enemy");
				GmComEfctCreateHitPlayer(gMS_ENEMY_COM_WORK.obj_work, (mine_rect.rect.left + mine_rect.rect.right) * 4096 / 2, (mine_rect.rect.top + mine_rect.rect.bottom) * 4096 / 2);
				GmComEfctCreateEneDeadSmoke(gMS_ENEMY_COM_WORK.obj_work, (mine_rect.rect.left + mine_rect.rect.right) * 4096 / 2, (mine_rect.rect.top + mine_rect.rect.bottom) * 4096 / 2);
				GmGmkAnimalInit(gMS_ENEMY_COM_WORK.obj_work, 0, 0, 0, 0, 0, 0);
				GMM_PAD_VIB_SMALL();
				if (gMS_PLAYER_WORK != null)
				{
					GmPlayerComboScore(gMS_PLAYER_WORK, gMS_ENEMY_COM_WORK.obj_work.pos.x, gMS_ENEMY_COM_WORK.obj_work.pos.y + -65536);
				}
				HgTrophyIncEnemyKillCount(gMS_ENEMY_COM_WORK.obj_work);
			}
			gMS_ENEMY_COM_WORK.obj_work.flag |= 8u;
		}
		else
		{
			gMS_ENEMY_COM_WORK.vit--;
			gMS_ENEMY_COM_WORK.eve_rec.byte_param[1]++;
			gMS_ENEMY_COM_WORK.invincible_timer = 245760;
			gMS_ENEMY_COM_WORK.rect_work[1].hit_power = 0;
		}
		if (gMS_PLAYER_WORK != null && gMS_PLAYER_WORK.obj_work.obj_type == 1)
		{
			GmPlySeqAtkReactionInit(gMS_PLAYER_WORK);
		}
	}

