	private static void GmEfctCmnBuildDataInit()
	{
		gm_efct_cmn_proc_state = 1u;
	}

	private static bool GmEfctCmnBuildDataLoopInitPart()
	{
		int num = 97 / StageCount;
		int num2 = num * stage;
		int num3 = num2 + num;
		if (stage == StageCount - 1)
		{
			num3 = 97;
		}
		for (int i = num2; i < num3; i++)
		{
			GMS_EFCT_CMN_CREATE_PARAM gMS_EFCT_CMN_CREATE_PARAM = gm_efct_cmn_create_param_tbl[i];
			int model_idx = gMS_EFCT_CMN_CREATE_PARAM.create_param.model_idx;
			int index = gmEfctCmnGetModelDworkNo(i);
			int index2 = gmEfctCmnGetObjectDworkNo(i);
			int mdl_ambtex_idx = gMS_EFCT_CMN_CREATE_PARAM.mdl_ambtex_idx;
			int index3 = gmEfctCmnGetMdlAmbtexDworkNo(i);
			int index4 = gmEfctCmnGetMdlTexlistDworkNo(i);
			if (model_idx != -1)
			{
				ambtex_dwork = ObjDataGet(index3);
				ObjDataLoadAmbIndex(ambtex_dwork, mdl_ambtex_idx, eff_cmn_arc);
				gm_efct_cmn_mdl_tex_reg_id_list[model_reg_cnt] = ObjAction3dESTextureLoadToDwork(ObjDataGet(index4), readAMBFile(ambtex_dwork.pData), ref texlistbuf);
				ObjDataLoadAmbIndex(ObjDataGet(index), model_idx, eff_cmn_arc);
				gm_efct_cmn_model_reg_id_list[model_reg_cnt] = ObjAction3dESModelLoadToDwork(ObjDataGet(index2), (AmbChunk)ObjDataGet(index).pData, 0u);
				model_reg_cnt++;
			}
		}
		if (stage == StageCount - 1)
		{
			eff_cmn_arc = null;
			ambtex_dwork = null;
			texlistbuf = null;
			model_reg_cnt = 0;
			stage = 0;
			return true;
		}
		stage++;
		return false;
	}

	private static void GmEfctCmnBuildDataLoopInit()
	{
		OBS_DATA_WORK pWork = ObjDataGet(5);
		eff_cmn_arc = readAMBFile(ObjDataGetInc(pWork));
		gm_efct_cmn_model_reg_num = 97;
		if (gm_efct_cmn_model_reg_num > 0)
		{
			gm_efct_cmn_model_reg_id_list = new int[gm_efct_cmn_model_reg_num];
			gm_efct_cmn_mdl_tex_reg_id_list = new int[gm_efct_cmn_model_reg_num];
			for (int i = 0; i < gm_efct_cmn_model_reg_num; i++)
			{
				gm_efct_cmn_model_reg_id_list[i] = (gm_efct_cmn_mdl_tex_reg_id_list[i] = -1);
			}
		}
		ambtex_dwork = ObjDataGet(17);
		ObjDataLoadAmbIndex(ambtex_dwork, 97, eff_cmn_arc);
		gm_efct_cmn_tex_reg_id = ObjAction3dESTextureLoadToDwork(ObjDataGet(18), readAMBFile(ambtex_dwork.pData), ref texlistbuf);
		GmEfctCmnBuildDataLoopInitPartWorking = true;
	}

	private static bool GmEfctCmnBuildDataLoop()
	{
		bool flag = true;
		if (gm_efct_cmn_proc_state == 0)
		{
			return true;
		}
		if (gm_efct_cmn_proc_state == 1)
		{
			if (GsMainSysGetDisplayListRegistNum() < 192)
			{
				if (!GmEfctCmnBuildDataLoopInitPartWorking)
				{
					GmEfctCmnBuildDataLoopInit();
				}
				else if (GmEfctCmnBuildDataLoopInitPart())
				{
					gm_efct_cmn_proc_state = 2u;
					GmEfctCmnBuildDataLoopInitPartWorking = false;
				}
			}
			return false;
		}
		if (gm_efct_cmn_tex_reg_id != -1)
		{
			if (amDrawIsRegistComplete(gm_efct_cmn_tex_reg_id))
			{
				gm_efct_cmn_tex_reg_id = -1;
			}
			else
			{
				flag = false;
			}
		}
		for (int i = 0; i < gm_efct_cmn_model_reg_num; i++)
		{
			if (gm_efct_cmn_mdl_tex_reg_id_list[i] != -1)
			{
				if (amDrawIsRegistComplete(gm_efct_cmn_mdl_tex_reg_id_list[i]))
				{
					gm_efct_cmn_mdl_tex_reg_id_list[i] = -1;
				}
				else
				{
					flag = false;
				}
			}
			if (gm_efct_cmn_model_reg_id_list[i] != -1)
			{
				if (amDrawIsRegistComplete(gm_efct_cmn_model_reg_id_list[i]))
				{
					gm_efct_cmn_model_reg_id_list[i] = -1;
				}
				else
				{
					flag = false;
				}
			}
		}
		if (flag)
		{
			gm_efct_cmn_proc_state = 0u;
		}
		return flag;
	}

	private static void GmEfctCmnFlushDataInit()
	{
		gm_efct_cmn_proc_state = 1u;
	}

	private static void GmEfctCmnFlushDataLoopInit()
	{
		int num = 0;
		for (int i = 0; i < 97; i++)
		{
			GMS_EFCT_CMN_CREATE_PARAM gMS_EFCT_CMN_CREATE_PARAM = gm_efct_cmn_create_param_tbl[i];
			int index = gmEfctCmnGetModelDworkNo(i);
			int index2 = gmEfctCmnGetObjectDworkNo(i);
			if (gMS_EFCT_CMN_CREATE_PARAM.create_param.model_idx != -1)
			{
				gm_efct_cmn_model_reg_id_list[num] = ObjAction3dESModelReleaseDwork(ObjDataGet(index2));
				OBS_DATA_WORK pWork = ObjDataGet(index);
				ObjDataRelease(pWork);
				gm_efct_cmn_mdl_tex_reg_id_list[num] = ObjAction3dESTextureReleaseDwork(ObjDataGet(gmEfctCmnGetMdlTexlistDworkNo(i)));
				ObjDataRelease(ObjDataGet(gmEfctCmnGetMdlAmbtexDworkNo(i)));
				num++;
			}
		}
		gm_efct_cmn_tex_reg_id = ObjAction3dESTextureReleaseDwork(ObjDataGet(18));
		OBS_DATA_WORK pWork2 = ObjDataGet(17);
		ObjDataRelease(pWork2);
		OBS_DATA_WORK pWork3 = ObjDataGet(5);
		ObjDataRelease(pWork3);
	}

	private static bool GmEfctCmnFlushDataLoop()
	{
		bool flag = true;
		int num = 0;
		if (gm_efct_cmn_proc_state == 0)
		{
			return true;
		}
		if (gm_efct_cmn_proc_state == 1)
		{
			if (GsMainSysGetDisplayListRegistNum() < 240)
			{
				GmEfctCmnFlushDataLoopInit();
				gm_efct_cmn_proc_state = 2u;
			}
			return false;
		}
		if (gm_efct_cmn_model_reg_num != 0)
		{
			for (int i = 0; i < 97; i++)
			{
				GMS_EFCT_CMN_CREATE_PARAM gMS_EFCT_CMN_CREATE_PARAM = gm_efct_cmn_create_param_tbl[i];
				if (gMS_EFCT_CMN_CREATE_PARAM.create_param.model_idx == -1)
				{
					continue;
				}
				if (gm_efct_cmn_model_reg_id_list[num] != -1)
				{
					int index = gmEfctCmnGetObjectDworkNo(i);
					if (ObjAction3dESModelReleaseDworkCheck(ObjDataGet(index), gm_efct_cmn_model_reg_id_list[num]))
					{
						gm_efct_cmn_model_reg_id_list[num] = -1;
					}
					else
					{
						flag = false;
					}
				}
				if (gm_efct_cmn_mdl_tex_reg_id_list[num] != -1)
				{
					if (ObjAction3dESTextureReleaseDworkCheck(ObjDataGet(gmEfctCmnGetMdlTexlistDworkNo(i)), gm_efct_cmn_mdl_tex_reg_id_list[num]))
					{
						gm_efct_cmn_mdl_tex_reg_id_list[num] = -1;
					}
					else
					{
						flag = false;
					}
				}
				num++;
			}
		}
		if (gm_efct_cmn_tex_reg_id != -1)
		{
			if (ObjAction3dESTextureReleaseDworkCheck(ObjDataGet(18), gm_efct_cmn_tex_reg_id))
			{
				gm_efct_cmn_tex_reg_id = -1;
			}
			else
			{
				flag = false;
			}
		}
		if (flag)
		{
			if (gm_efct_cmn_mdl_tex_reg_id_list != null)
			{
				gm_efct_cmn_mdl_tex_reg_id_list = null;
			}
			if (gm_efct_cmn_model_reg_id_list != null)
			{
				gm_efct_cmn_model_reg_id_list = null;
				gm_efct_cmn_model_reg_num = 0;
			}
			gm_efct_cmn_proc_state = 0u;
		}
		return flag;
	}

	private static GMS_EFFECT_3DES_WORK GmEfctCmnEsCreate(OBS_OBJECT_WORK parent_obj, int efct_cmn_idx)
	{
		GMS_EFCT_CMN_CREATE_PARAM gMS_EFCT_CMN_CREATE_PARAM = gm_efct_cmn_create_param_tbl[efct_cmn_idx];
		OBS_DATA_WORK model_dwork;
		OBS_DATA_WORK object_dwork;
		OBS_DATA_WORK oBS_DATA_WORK;
		OBS_DATA_WORK texlist_dwork;
		if (gMS_EFCT_CMN_CREATE_PARAM.create_param.model_idx != -1)
		{
			int ame_idx = gMS_EFCT_CMN_CREATE_PARAM.create_param.ame_idx;
			model_dwork = ObjDataGet(gmEfctCmnGetModelDworkNo(ame_idx));
			object_dwork = ObjDataGet(gmEfctCmnGetObjectDworkNo(ame_idx));
			oBS_DATA_WORK = ObjDataGet(gmEfctCmnGetMdlAmbtexDworkNo(ame_idx));
			texlist_dwork = ObjDataGet(gmEfctCmnGetMdlTexlistDworkNo(ame_idx));
		}
		else
		{
			model_dwork = null;
			object_dwork = null;
			oBS_DATA_WORK = ObjDataGet(17);
			texlist_dwork = ObjDataGet(18);
		}
		return GmEffect3dESCreateByParam(gMS_EFCT_CMN_CREATE_PARAM.create_param, parent_obj, ObjDataGet(5).pData, ObjDataGet(gmEfctCmnGetAmeDworkNo(gMS_EFCT_CMN_CREATE_PARAM.create_param.ame_idx)), oBS_DATA_WORK, texlist_dwork, model_dwork, object_dwork);
	}

