	private static void GmEfctCmnUpdateInvincibleSubPart(GMS_EFFECT_3DES_WORK efct_3des, OBS_OBJECT_WORK ply_obj)
	{
		OBS_OBJECT_WORK obj_work = efct_3des.efct_com.obj_work;
		obj_work.dir.z += 1820;
		obj_work.spd.x = FX_Mul(ply_obj.pos.x - obj_work.pos.x, 204);
		obj_work.spd.y = FX_Mul(ply_obj.pos.y - obj_work.pos.y, 204);
		if ((obj_work.spd.x > 0 && ply_obj.move.x > 0) || (obj_work.spd.x < 0 && ply_obj.move.x < 0))
		{
			obj_work.spd.x += FX_Mul(ply_obj.move.x, 1024);
		}
		if ((obj_work.spd.y > 0 && ply_obj.move.y > 0) || (obj_work.spd.y < 0 && ply_obj.move.y < 0))
		{
			obj_work.spd.y += FX_Mul(ply_obj.move.y, 1024);
		}
	}

