	public static void gmBoss5EfctTargetCursorStartProcMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS5_BODY_WORK body_work = (GMS_BOSS5_BODY_WORK)obj_work.parent_obj;
		GMS_BOSS5_EFCT_GENERAL_WORK gMS_BOSS5_EFCT_GENERAL_WORK = (GMS_BOSS5_EFCT_GENERAL_WORK)obj_work;
		GmBoss5BodyGetPlySearchPos(body_work, out obj_work.pos);
		float a = 1f - (float)gMS_BOSS5_EFCT_GENERAL_WORK.timer / 120f;
		a = MTM_MATH_CLIP(a, 0f, 1f);
		obj_work.obj_3des.speed = 0.5f + a * 0.5f;
		float nodisp_time = 10f / obj_work.obj_3des.speed;
		float cycle_time = 20f / obj_work.obj_3des.speed;
		gmBoss5EfctTargetCursorUpdateFlickerNoDisp(gMS_BOSS5_EFCT_GENERAL_WORK, nodisp_time, cycle_time);
		if (gMS_BOSS5_EFCT_GENERAL_WORK.timer != 0)
		{
			gMS_BOSS5_EFCT_GENERAL_WORK.timer--;
			return;
		}
		gmBoss5EfctCreateTargetCursorLoop(body_work, gMS_BOSS5_EFCT_GENERAL_WORK.efct_3des.efct_com);
		obj_work.flag |= 4u;
	}

