	public static void gmBoss5EfctTargetCursorInitFlickerNoDisp(GMS_BOSS5_EFCT_GENERAL_WORK targ_cursor)
	{
		targ_cursor.ratio_timer = 0f;
	}

	public static void gmBoss5EfctTargetCursorUpdateFlickerNoDisp(GMS_BOSS5_EFCT_GENERAL_WORK targ_cursor, float nodisp_time, float cycle_time)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)targ_cursor;
		targ_cursor.ratio_timer += 1f;
		if (targ_cursor.ratio_timer >= cycle_time)
		{
			targ_cursor.ratio_timer = 0f;
		}
		if (targ_cursor.ratio_timer >= nodisp_time)
		{
			oBS_OBJECT_WORK.disp_flag &= 4294967263u;
		}
		else
		{
			oBS_OBJECT_WORK.disp_flag |= 32u;
		}
	}

