		else if (((pWork.move_flag & 0x10) == 0 || pWork.spd.y >= 0) && (pWork.sys_flag & (uint)(17 << (int)num7)) == 0)
		{
			pWork.move_flag |= 1u;
		}
		if ((pWork.move_flag & 1) != 0)
		{
			if ((pWork.move_flag & 0x10000000) == 0)
			{
				if ((pWork.col_flag & 1) == 0 && (pWork.move_flag & 0x40) != 0)
				{
					if (b >= b2)
					{
						if (b > b2)
						{
							array2 = array3;
						}
						else if (Math.Abs((ushort)(pWork.dir.z + pWork.dir_fall) - array2[0]) > Math.Abs((ushort)(pWork.dir.z + pWork.dir_fall) - array3[0]))
						{
							array2 = array3;
						}
					}
					if ((pWork.move_flag & 0x800000) != 0)
					{
						pWork.dir.z = ObjRoopMove16(pWork.dir.z, (ushort)(array2[0] - pWork.dir_fall), 256);
					}
					else
					{
						pWork.dir.z = (ushort)(array2[0] - pWork.dir_fall);
					}
				}
				else if (GSM_MAIN_STAGE_IS_SPSTAGE_NOT_RETRY() && (pWork.move_flag & 0x400000) == 0)
				{
					pWork.dir.z = (ushort)(-(((g_gm_main_system.pseudofall_dir + 8192) & 0x3FFF) - 8192));
				}
			}
			if ((pWork.move_flag & 0x4000) == 0 && (pWork.move_flag & 0x20000000) == 0)
			{
				switch ((ushort)(((pWork.move_flag & 0x10) == 0) ? ((ushort)(((pWork.dir.z + 8192) & 0xC000) >> 14)) : 0))
				{
				default:
					if (pWork.spd.y > 0)
					{
						if ((pWork.move_flag & 0x20000) != 0)
						{
							pWork.spd.x += pWork.spd.y * mtMathSin((ushort)(pWork.dir.z - g_gm_main_system.pseudofall_dir + pWork.dir_fall)) >> 12;
						}
						pWork.spd.y = 0;
					}
					break;
				case 1:
					if (pWork.spd.x < 0)
					{
						pWork.spd.x = 0;
					}
					break;
				case 2:
					if (pWork.spd.y < 0)
					{
						pWork.spd.y = 0;
					}
					break;
				case 3:
					if (pWork.spd.x > 0)
					{
						pWork.spd.x = 0;
					}
					break;
				}
			}
		}
		else
		{
			pWork.ride_obj = ride_obj;
		}
		if ((pWork.move_flag & 0x40000000) != 0 || num8 < 256)
		{
			oBS_COL_CHK_DATA.flag |= 128;
			switch (oBS_COL_CHK_DATA.vec)
			{
			default:
				num3 = (short)(pWork.field_rect[1] + 2);
				num4 = (short)(pWork.field_rect[1] + 2);
				oBS_COL_CHK_DATA.vec = 3;
				break;
			case 1:
				num = (short)(pWork.field_rect[2] - 2);
				num2 = (short)(pWork.field_rect[2] - 2);
				oBS_COL_CHK_DATA.vec = 0;
				break;
			case 3:
				num3 = (short)(pWork.field_rect[3] - 2);
				num4 = (short)(pWork.field_rect[3] - 2);
				oBS_COL_CHK_DATA.vec = 2;
				break;
			case 0:
				num = (short)(pWork.field_rect[0] + 2);
				num2 = (short)(pWork.field_rect[0] + 2);
				oBS_COL_CHK_DATA.vec = 1;
				break;
			}
			oBS_COL_CHK_DATA.attr = null;
			oBS_COL_CHK_DATA.dir = null;
			oBS_COL_CHK_DATA.pos_x = lPosX + num;
			oBS_COL_CHK_DATA.pos_y = lPosY + num3;
			b = (sbyte)ObjCollisionUnion(pWork, oBS_COL_CHK_DATA);
			oBS_COL_CHK_DATA.pos_x = lPosX + num2;
			oBS_COL_CHK_DATA.pos_y = lPosY + num4;
			b2 = (sbyte)ObjCollisionUnion(pWork, oBS_COL_CHK_DATA);
			sbyte b6 = ((b >= b2) ? b2 : b);
			if (b6 <= 0)
			{
				pWork.move_flag |= 2u;
				if (((pWork.move_flag & 0x40000000) == 0 && b6 >= -14) || ((pWork.move_flag & 0x40000000) != 0 && b6 >= -28))
