							{
								pWork.spd.y = 0;
							}
							else
							{
								pWork.spd.x = 0;
							}
						}
					}
					else if ((pWork.move_flag & 0x4000) == 0)
					{
						pWork.spd_m = 0;
						if ((pWork.move_flag & 0x20000000) == 0)
						{
							pWork.spd.x = 0;
							pWork.spd.y = 0;
						}
