	}

	private static void objDiffColDirMove(ref int lPosX, ref int lPosY, sbyte cDelta, ushort usColFlag)
	{
		switch (usColFlag)
		{
		default:
			lPosY += cDelta;
			break;
		case 1:
			lPosX -= cDelta;
			break;
		case 3:
			lPosY -= cDelta;
			break;
		case 0:
			lPosX += cDelta;
			break;
		}
	}

	private static int ObjCameraInit(int cam_id, NNS_VECTOR pos, int group, ushort pause_level, int prio)
	{
		OBS_CAMERA_SYS oBS_CAMERA_SYS = new OBS_CAMERA_SYS();
		if (obj_camera_tcb == null)
		{
			obj_camera_tcb = MTM_TASK_MAKE_TCB(objCameraMain, objCameraDest, 0u, pause_level, (uint)prio, group, () => new OBS_CAMERA_SYS(), "objCamera");
			oBS_CAMERA_SYS = (OBS_CAMERA_SYS)obj_camera_tcb.work;
			oBS_CAMERA_SYS.Clear();
			obj_camera_sys = oBS_CAMERA_SYS;
		}
		else
		{
			oBS_CAMERA_SYS = obj_camera_sys;
		}
		if (oBS_CAMERA_SYS.camera_num >= 8)
		{
			return -1;
		}
		int num;
		if (cam_id < 0)
		{
			for (num = 0; num < 8 && oBS_CAMERA_SYS.obj_camera[num] != null; num++)
			{
			}
		}
		else
		{
			if (oBS_CAMERA_SYS.obj_camera[cam_id] != null)
			{
				return -1;
			}
			num = cam_id;
		}
		if (num >= 8)
		{
			return -1;
		}
		if (oBS_CAMERA_SYS.obj_camera[num] != null)
		{
			return -1;
		}
		oBS_CAMERA_SYS.obj_camera[num] = new OBS_CAMERA();
		oBS_CAMERA_SYS.camera_num++;
		OBS_CAMERA oBS_CAMERA = oBS_CAMERA_SYS.obj_camera[num];
		oBS_CAMERA.camera_id = num;
		oBS_CAMERA.command_state = 0u;
		oBS_CAMERA.spd_max.x = 16f;
		oBS_CAMERA.spd_max.y = 16f;
		oBS_CAMERA.spd_max.z = 4f;
		oBS_CAMERA.spd_add.x = 3f;
		oBS_CAMERA.spd_add.y = 3f;
		oBS_CAMERA.spd_add.z = 0.5f;
		oBS_CAMERA.shift = 1;
		oBS_CAMERA.limit[0] = 8;
		oBS_CAMERA.limit[1] = 8;
		oBS_CAMERA.limit[2] = oBS_CAMERA.limit[0] + OBD_LCD_X;
		oBS_CAMERA.limit[3] = oBS_CAMERA.limit[1] + OBD_LCD_Y;
		oBS_CAMERA.limit[4] = -4096;
		oBS_CAMERA.limit[5] = 4096;
		oBS_CAMERA.pos.Assign(pos);
		oBS_CAMERA.prev_pos.Assign(pos);
		oBS_CAMERA.disp_pos.Assign(pos);
		oBS_CAMERA.prev_disp_pos.Assign(pos);
		return num;
	}

	private static void ObjCamera3dInit(int cam_id)
	{
		if (obj_camera_sys == null)
		{
			return;
		}
		if (obj_camera_sys.obj_camera[cam_id] == null)
		{
			NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
			int num = ObjCameraInit(cam_id, nNS_VECTOR, 0, 0, 61438);
			if (num == -1)
			{
				return;
			}
			GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		}
		OBS_CAMERA oBS_CAMERA = obj_camera_sys.obj_camera[cam_id];
		oBS_CAMERA.flag |= 16u;
		oBS_CAMERA.znear = 1f;
		oBS_CAMERA.zfar = 60000f;
		oBS_CAMERA.aspect = AMD_SCREEN_ASPECT;
		oBS_CAMERA.fovy = NNM_DEGtoA32(45f);
		nnMakePerspectiveMatrix(oBS_CAMERA.prj_pers_mtx, oBS_CAMERA.fovy, oBS_CAMERA.aspect, oBS_CAMERA.znear, oBS_CAMERA.zfar);
		oBS_CAMERA.scale = 5f / 64f * CAMERA_ZOOM;
		float num2 = g_obj.disp_height * oBS_CAMERA.scale * 0.5f * 1f;
		// El aspecto ensancha el eje horizontal (top/bottom); el vertical queda como en el juego original.
		float num3 = num2 * oBS_CAMERA.aspect;
		oBS_CAMERA.left = 0f - num2;
		oBS_CAMERA.right = num2;
		oBS_CAMERA.bottom = 0f - num3;
		oBS_CAMERA.top = num3;
		nnMakeOrthoMatrix(oBS_CAMERA.prj_ortho_mtx, oBS_CAMERA.left, oBS_CAMERA.right, oBS_CAMERA.bottom, oBS_CAMERA.top, oBS_CAMERA.znear, oBS_CAMERA.zfar);
		switch (oBS_CAMERA.camera_type)
		{
		case OBE_CAMERA_TYPE.OBE_CAMERA_TYPE_TARGET_ROLL:
		{
			NNS_CAMERA_TARGET_ROLL nNS_CAMERA_TARGET_ROLL = new NNS_CAMERA_TARGET_ROLL();
			ObjCameraGetTargetRollCamera(oBS_CAMERA, nNS_CAMERA_TARGET_ROLL);
			nnMakeTargetRollCameraViewMatrix(oBS_CAMERA.view_mtx, nNS_CAMERA_TARGET_ROLL);
			break;
		}
		case OBE_CAMERA_TYPE.OBE_CAMERA_TYPE_TARGET_UP_TARGET:
		{
			NNS_CAMERA_TARGET_UPTARGET nNS_CAMERA_TARGET_UPTARGET = new NNS_CAMERA_TARGET_UPTARGET();
			ObjCameraGetTargetUpTargetCamera(oBS_CAMERA, nNS_CAMERA_TARGET_UPTARGET);
			nnMakeTargetUpTargetCameraViewMatrix(oBS_CAMERA.view_mtx, nNS_CAMERA_TARGET_UPTARGET);
			break;
		}
		case OBE_CAMERA_TYPE.OBE_CAMERA_TYPE_TARGET_UP_VEC:
		{
			NNS_CAMERA_TARGET_UPVECTOR nNS_CAMERA_TARGET_UPVECTOR = new NNS_CAMERA_TARGET_UPVECTOR();
			ObjCameraGetTargetUpVecCamera(oBS_CAMERA, nNS_CAMERA_TARGET_UPVECTOR);
			nnMakeTargetUpVectorCameraViewMatrix(oBS_CAMERA.view_mtx, nNS_CAMERA_TARGET_UPVECTOR);
			break;
		}
		}
	}

	private static void ObjCameraExit()
	{
		if (obj_camera_tcb != null)
		{
			mtTaskClearTcb(obj_camera_tcb);
		}
	}

	private static void ObjCameraGetTargetRollCamera(OBS_CAMERA obj_camera, NNS_CAMERA_TARGET_ROLL troll_camera)
	{
		troll_camera.User = 0u;
		troll_camera.Fovy = obj_camera.fovy;
		troll_camera.Aspect = obj_camera.aspect;
		troll_camera.ZNear = obj_camera.znear;
		troll_camera.ZFar = obj_camera.zfar;
		troll_camera.Position.x = obj_camera.disp_pos.x;
		troll_camera.Position.y = obj_camera.disp_pos.y;
		troll_camera.Position.z = obj_camera.disp_pos.z;
		if (obj_camera.target_obj != null)
		{
			troll_camera.Target.x = FXM_FX32_TO_FLOAT(obj_camera.target_obj.pos.x);
			troll_camera.Target.y = FXM_FX32_TO_FLOAT(obj_camera.target_obj.pos.y);
			troll_camera.Target.z = FXM_FX32_TO_FLOAT(obj_camera.target_obj.pos.z);
		}
		else
		{
			troll_camera.Target.x = obj_camera.target_pos.x;
			troll_camera.Target.y = obj_camera.target_pos.y;
			troll_camera.Target.z = obj_camera.target_pos.z;
		}
		troll_camera.Roll = obj_camera.roll + 16384;
	}

