	}

	private static float ObjCameraDispScaleGet(int cam_id)
	{
		mppAssertNotImpl();
		OBS_CAMERA oBS_CAMERA = obj_camera_sys.obj_camera[cam_id];
		if (oBS_CAMERA.disp_pos.z >= 0f)
		{
			return 1f - oBS_CAMERA.disp_pos.z / 2f;
		}
		return 1f - oBS_CAMERA.disp_pos.z;
	}

