	private static void objCameraDest(MTS_TASK_TCB pTcb)
	{
		obj_camera_tcb = null;
		obj_camera_sys = null;
		OBS_CAMERA_SYS oBS_CAMERA_SYS = (OBS_CAMERA_SYS)pTcb.work;
		for (int i = 0; i < 8; i++)
		{
			if (oBS_CAMERA_SYS.obj_camera[i] != null)
			{
				object user_work = oBS_CAMERA_SYS.obj_camera[i].user_work;
			}
		}
	}

	private static void objCameraMain(MTS_TASK_TCB tcb)
	{
		if (ObjObjectPauseCheck(0u) != 0)
		{
			return;
		}
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		for (int i = 0; i < 8; i++)
		{
			OBS_CAMERA oBS_CAMERA = obj_camera_sys.obj_camera[i];
			if (oBS_CAMERA == null)
			{
				continue;
			}
			oBS_CAMERA.prev_disp_pos.x = oBS_CAMERA.disp_pos.x;
			oBS_CAMERA.prev_disp_pos.y = oBS_CAMERA.disp_pos.y;
			oBS_CAMERA.prev_disp_pos.z = oBS_CAMERA.disp_pos.z;
			if (oBS_CAMERA.user_func != null)
			{
				oBS_CAMERA.user_func(oBS_CAMERA);
			}
			else
			{
				if ((oBS_CAMERA.flag & 4) != 0)
				{
					objCameraMove(oBS_CAMERA);
				}
				nNS_VECTOR.x = oBS_CAMERA.pos.x;
				nNS_VECTOR.y = oBS_CAMERA.pos.y;
				nNS_VECTOR.z = oBS_CAMERA.pos.z;
				if ((oBS_CAMERA.flag & 8) != 0)
				{
					nNS_VECTOR.x -= (nNS_VECTOR.x - oBS_CAMERA.work.x) * 2f;
					nNS_VECTOR.y -= (nNS_VECTOR.y - oBS_CAMERA.work.y) * 2f;
					nNS_VECTOR.z -= (nNS_VECTOR.z - oBS_CAMERA.work.z) * 2f;
				}
				oBS_CAMERA.disp_pos.x = nNS_VECTOR.x + oBS_CAMERA.ofst.x;
				oBS_CAMERA.disp_pos.y = nNS_VECTOR.y + oBS_CAMERA.ofst.y;
				oBS_CAMERA.disp_pos.z = nNS_VECTOR.z + oBS_CAMERA.ofst.z;
			}
			if ((oBS_CAMERA.flag & 0x20) != 0)
			{
				objCameraLimitCheck(oBS_CAMERA);
			}
			oBS_CAMERA.disp_pos.x += oBS_CAMERA.disp_ofst.x;
			oBS_CAMERA.disp_pos.y += oBS_CAMERA.disp_ofst.y;
			oBS_CAMERA.disp_pos.z += oBS_CAMERA.disp_ofst.z;
			oBS_CAMERA.disp_ofst.x = 0f;
			oBS_CAMERA.disp_ofst.y = 0f;
			oBS_CAMERA.disp_ofst.z = 0f;
			if ((oBS_CAMERA.flag & 0x10) == 0)
			{
				continue;
			}
			nnMakePerspectiveMatrix(oBS_CAMERA.prj_pers_mtx, oBS_CAMERA.fovy, oBS_CAMERA.aspect, oBS_CAMERA.znear, oBS_CAMERA.zfar);
			float num = AMD_SCREEN_2D_WIDTH * oBS_CAMERA.scale * 0.5f * 1f;
			float num2 = num * oBS_CAMERA.aspect;
			oBS_CAMERA.left = 0f - num;
			oBS_CAMERA.right = num;
			oBS_CAMERA.bottom = 0f - num2;
			oBS_CAMERA.top = num2;
			nnMakeOrthoMatrix(oBS_CAMERA.prj_ortho_mtx, oBS_CAMERA.left, oBS_CAMERA.right, oBS_CAMERA.bottom, oBS_CAMERA.top, oBS_CAMERA.znear, oBS_CAMERA.zfar);
			switch (oBS_CAMERA.camera_type)
			{
			case OBE_CAMERA_TYPE.OBE_CAMERA_TYPE_TARGET_ROLL:
			{
				NNS_CAMERA_TARGET_ROLL nNS_CAMERA_TARGET_ROLL = GlobalPool<NNS_CAMERA_TARGET_ROLL>.Alloc();
				int roll = oBS_CAMERA.roll;
				if ((oBS_CAMERA.flag & 0x40000000) != 0)
				{
					oBS_CAMERA.roll = 0;
				}
				ObjCameraGetTargetRollCamera(oBS_CAMERA, nNS_CAMERA_TARGET_ROLL);
				nnMakeTargetRollCameraViewMatrix(oBS_CAMERA.view_mtx, nNS_CAMERA_TARGET_ROLL);
				oBS_CAMERA.roll = roll;
				GlobalPool<NNS_CAMERA_TARGET_ROLL>.Release(nNS_CAMERA_TARGET_ROLL);
				break;
			}
			case OBE_CAMERA_TYPE.OBE_CAMERA_TYPE_TARGET_UP_TARGET:
			{
				NNS_CAMERA_TARGET_UPTARGET nNS_CAMERA_TARGET_UPTARGET = new NNS_CAMERA_TARGET_UPTARGET();
				ObjCameraGetTargetUpTargetCamera(oBS_CAMERA, nNS_CAMERA_TARGET_UPTARGET);
				nnMakeTargetUpTargetCameraViewMatrix(oBS_CAMERA.view_mtx, nNS_CAMERA_TARGET_UPTARGET);
				break;
			}
			case OBE_CAMERA_TYPE.OBE_CAMERA_TYPE_TARGET_UP_VEC:
			{
				NNS_CAMERA_TARGET_UPVECTOR nNS_CAMERA_TARGET_UPVECTOR = new NNS_CAMERA_TARGET_UPVECTOR();
				ObjCameraGetTargetUpVecCamera(oBS_CAMERA, nNS_CAMERA_TARGET_UPVECTOR);
				nnMakeTargetUpVectorCameraViewMatrix(oBS_CAMERA.view_mtx, nNS_CAMERA_TARGET_UPVECTOR);
				break;
			}
			}
		}
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	private static void objCameraMove(OBS_CAMERA obj_camera)
	{
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		if (obj_camera.target_obj != null)
		{
			nNS_VECTOR.x = FXM_FX32_TO_FLOAT(obj_camera.target_obj.pos.x) + obj_camera.target_ofst.x;
			nNS_VECTOR.y = FXM_FX32_TO_FLOAT(obj_camera.target_obj.pos.y - ((OBD_LCD_Y << 1) + 200 << 12)) + obj_camera.target_ofst.y;
			nNS_VECTOR.z = FXM_FX32_TO_FLOAT(obj_camera.target_obj.pos.z) + obj_camera.target_ofst.z;
		}
		else
		{
			nNS_VECTOR.x = obj_camera.target_pos.x - FXM_FX32_TO_FLOAT(OBD_LCD_X >> 1 << 12) + obj_camera.target_ofst.x;
			nNS_VECTOR.y = obj_camera.target_pos.y - FXM_FX32_TO_FLOAT(OBD_LCD_Y >> 1 << 12) + obj_camera.target_ofst.y;
			nNS_VECTOR.z = obj_camera.target_pos.z + obj_camera.target_ofst.z;
		}
		obj_camera.work.x = nNS_VECTOR.x;
		obj_camera.work.y = nNS_VECTOR.y;
		obj_camera.work.z = nNS_VECTOR.z;
		obj_camera.prev_pos.x = obj_camera.pos.x;
		obj_camera.prev_pos.y = obj_camera.pos.y;
		obj_camera.prev_pos.z = obj_camera.pos.z;
		if ((obj_camera.flag & 1) != 0)
		{
			if (obj_camera.target_obj != null)
			{
				obj_camera.pos.x = nNS_VECTOR.x;
				obj_camera.pos.y = nNS_VECTOR.y;
				obj_camera.pos.z = nNS_VECTOR.z;
			}
			return;
		}
		if ((obj_camera.flag & 2) != 0)
		{
			obj_camera.pos.x = ObjShiftSetF(obj_camera.pos.x, nNS_VECTOR.x, obj_camera.shift, obj_camera.spd_max.x, obj_camera.spd_add.x);
			obj_camera.pos.y = ObjShiftSetF(obj_camera.pos.y, nNS_VECTOR.x, obj_camera.shift, obj_camera.spd_max.y, obj_camera.spd_add.y);
			obj_camera.pos.z = ObjShiftSetF(obj_camera.pos.z, nNS_VECTOR.x, obj_camera.shift, obj_camera.spd_max.z, obj_camera.spd_add.z);
		}
		else
		{
			if (nNS_VECTOR.x != obj_camera.pos.x)
			{
				obj_camera.spd.x = ObjSpdUpSetF(obj_camera.spd.x, obj_camera.spd_add.x, obj_camera.spd_max.x);
			}
			else
			{
				obj_camera.spd.x = ObjSpdDownSetF(obj_camera.spd.x, obj_camera.spd_add.x);
			}
			if (nNS_VECTOR.y != obj_camera.pos.y)
			{
				obj_camera.spd.y = ObjSpdUpSetF(obj_camera.spd.y, obj_camera.spd_add.y, obj_camera.spd_max.y);
			}
			else
			{
				obj_camera.spd.y = ObjSpdDownSetF(obj_camera.spd.y, obj_camera.spd_add.y);
			}
			if (nNS_VECTOR.z != obj_camera.pos.z)
			{
				obj_camera.spd.z = ObjSpdUpSetF(obj_camera.spd.z, obj_camera.spd_add.z, obj_camera.spd_max.z);
			}
			else
			{
				obj_camera.spd.z = ObjSpdDownSetF(obj_camera.spd.z, obj_camera.spd_add.z);
			}
			if (nNS_VECTOR.x > obj_camera.pos.x)
			{
				obj_camera.pos.x += obj_camera.spd.x;
				if (obj_camera.pos.x > nNS_VECTOR.x)
				{
					obj_camera.pos.x = nNS_VECTOR.x;
				}
			}
			else
			{
				obj_camera.pos.x -= obj_camera.spd.x;
				if (obj_camera.pos.x < nNS_VECTOR.x)
				{
					obj_camera.pos.x = nNS_VECTOR.x;
				}
			}
			if (nNS_VECTOR.y > obj_camera.pos.y)
			{
				obj_camera.pos.y += obj_camera.spd.y;
				if (obj_camera.pos.y > nNS_VECTOR.y)
				{
					obj_camera.pos.y = nNS_VECTOR.y;
				}
			}
			else
			{
				obj_camera.pos.y -= obj_camera.spd.y;
				if (obj_camera.pos.y < nNS_VECTOR.y)
				{
					obj_camera.pos.y = nNS_VECTOR.y;
				}
			}
			if (nNS_VECTOR.z > obj_camera.pos.z)
			{
				obj_camera.pos.z += obj_camera.spd.z;
				if (obj_camera.pos.z > nNS_VECTOR.z)
				{
					obj_camera.pos.z = nNS_VECTOR.z;
				}
			}
			else
			{
				obj_camera.pos.z -= obj_camera.spd.z;
				if (obj_camera.pos.z < nNS_VECTOR.z)
				{
					obj_camera.pos.z = nNS_VECTOR.z;
				}
			}
		}
		if (Math.Abs(nNS_VECTOR.x - obj_camera.pos.x) > obj_camera.play_ofst_max.x)
		{
			if (nNS_VECTOR.x > obj_camera.pos.x)
			{
				obj_camera.pos.x = nNS_VECTOR.x - obj_camera.play_ofst_max.x;
			}
			else
			{
				obj_camera.pos.x = nNS_VECTOR.x + obj_camera.play_ofst_max.x;
			}
		}
		if (Math.Abs(nNS_VECTOR.y - obj_camera.pos.y) > obj_camera.play_ofst_max.y)
		{
			if (nNS_VECTOR.y > obj_camera.pos.y)
			{
				obj_camera.pos.y = nNS_VECTOR.y - obj_camera.play_ofst_max.y;
			}
			else
			{
				obj_camera.pos.y = nNS_VECTOR.y + obj_camera.play_ofst_max.y;
			}
		}
		if (Math.Abs(nNS_VECTOR.z - obj_camera.pos.z) > obj_camera.play_ofst_max.z)
		{
			if (nNS_VECTOR.z > obj_camera.pos.z)
			{
				obj_camera.pos.z = nNS_VECTOR.z - obj_camera.play_ofst_max.z;
			}
			else
			{
				obj_camera.pos.z = nNS_VECTOR.z + obj_camera.play_ofst_max.z;
			}
		}
		obj_camera.pos.z += obj_camera.ofst.z;
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	private static void objCameraLimitCheck(OBS_CAMERA obj_camera)
	{
		objCameraPosLimitCheck(obj_camera, obj_camera.disp_pos);
	}

	private static void objCameraPosLimitCheck(OBS_CAMERA obj_camera, NNS_VECTOR pPos)
	{
		int num = 0;
		if (pPos.z != 0f)
		{
			if ((float)obj_camera.limit[4] > pPos.z)
			{
				pPos.z = obj_camera.limit[4];
			}
			if ((float)obj_camera.limit[5] < pPos.z)
			{
				pPos.z = obj_camera.limit[5];
			}
			if (1f / ObjCameraDispScaleGet(obj_camera.index) * (float)OBD_LCD_X > (float)(obj_camera.limit[2] - obj_camera.limit[0]))
			{
				float num2 = (float)(obj_camera.limit[2] - obj_camera.limit[0]) / (float)OBD_LCD_X;
				num2 = 1f / num2;
				if (pPos.z >= 0f)
				{
					pPos.z = (num2 - 1f) * -2f;
				}
				else
				{
					pPos.z = (num2 - 1f) * -1f;
				}
			}
			if (1f / ObjCameraDispScaleGet(obj_camera.index) * (float)OBD_LCD_Y > (float)(obj_camera.limit[3] - obj_camera.limit[1]))
			{
				float num2 = (float)(obj_camera.limit[3] - obj_camera.limit[1]) / (float)OBD_LCD_X;
				num2 = 1f / num2;
				if (pPos.z >= 0f)
				{
					pPos.z = (num2 - 1f) * -2f;
				}
				else
				{
					pPos.z = (num2 - 1f) * -1f;
				}
			}
		}
		if (pPos.z > 0f)
		{
			num = FXM_FLOAT_TO_FX32(1f / ObjCameraDispScaleGet(obj_camera.index) * (float)OBD_LCD_X);
			num -= OBD_LCD_X << 12;
			num >>= 13;
		}
		if ((float)(obj_camera.limit[0] + num) > pPos.x)
		{
			pPos.x = obj_camera.limit[0] + num;
		}
		if ((float)(obj_camera.limit[2] - OBD_LCD_X - num) < pPos.x)
		{
			pPos.x = obj_camera.limit[2] - OBD_LCD_X - num;
		}
		if (pPos.z > 0f)
		{
			num = FXM_FLOAT_TO_FX32(1f / ObjCameraDispScaleGet(obj_camera.index) * (float)OBD_LCD_Y);
			num -= OBD_LCD_Y << 12;
			num >>= 13;
		}
		if ((float)(obj_camera.limit[1] + num) > pPos.y)
		{
			pPos.y = obj_camera.limit[1] + num;
		}
		if ((float)(obj_camera.limit[3] - OBD_LCD_Y - num) < pPos.y)
		{
			pPos.y = obj_camera.limit[3] - OBD_LCD_Y - num;
		}
	}

