	public static int nnNormalizeVector(NNS_VECTOR dst, NNS_VECTOR src)
	{
		float num = nnLengthSqVector(src);
		if (num == 0f)
		{
			dst.x = 0f;
			dst.y = 0f;
			dst.z = 0f;
			return 0;
		}
		num = nnInvertSqrt(num);
		dst.x = src.x * num;
		dst.y = src.y * num;
		dst.z = src.z * num;
		return 1;
	}

	public static int nnNormalizeVector(ref SNNS_VECTOR dst, ref SNNS_VECTOR src)
	{
		float num = nnLengthSqVector(ref src);
		if (num == 0f)
		{
			dst.x = 0f;
			dst.y = 0f;
			dst.z = 0f;
			return 0;
		}
		num = nnInvertSqrt(num);
		dst.x = src.x * num;
		dst.y = src.y * num;
		dst.z = src.z * num;
		return 1;
	}

	public static int nnNormalizeVector(float[] dst, float[] src)
	{
		float num = nnLengthSqVector(src);
		if (num == 0f)
		{
			dst[0] = 0f;
			dst[1] = 0f;
			dst[2] = 0f;
			return 0;
		}
		num = nnInvertSqrt(num);
		dst[0] = src[0] * num;
		dst[1] = src[1] * num;
		dst[2] = src[2] * num;
		return 1;
	}

	public static int nnNormalizeVector(ref OpenGL.glArray4f dst, ref OpenGL.glArray4f src)
	{
		float num = nnLengthSqVector(ref src);
		if (num == 0f)
		{
			dst.f0 = 0f;
			dst.f1 = 0f;
			dst.f2 = 0f;
			return 0;
		}
		num = nnInvertSqrt(num);
		dst.f0 = src.f0 * num;
