	private static void nnDrawObject(NNS_OBJECT obj, NNS_MATRIX[] mtxpal, uint[] nodestatlist, uint subobjtype, uint flag, uint alternativeLighting)
	{
		int num = -1;
		if ((flag & 1) != 0 || obj.nSubobj <= 0)
