		nngDrawCallBackVal.pObject = obj;
		nngDrawCallBackVal.pMatrixPalette = mtxpal;
		nngDrawCallBackVal.pNodeStatusList = nodestatlist;
		nngDrawCallBackVal.DrawSubobjType = subobjtype;
		nngDrawCallBackVal.DrawFlag = flag;
