			nngDrawCallBackVal.iSubobject = i;
			if ((nNS_SUBOBJ.fType & 0x200) != 0)
			{
				OpenGL.glMatrixMode(5888u);
				OpenGL.glLoadIdentity();
			}
			for (int j = 0; j < nNS_SUBOBJ.nMeshset; j++)
			{
				NNS_MESHSET nNS_MESHSET = nNS_SUBOBJ.pMeshsetList[j];
				NNS_VTXLISTPTR nNS_VTXLISTPTR = obj.pVtxListPtrList[nNS_MESHSET.iVtxList];
				NNS_PRIMLISTPTR plistptr = obj.pPrimListPtrList[nNS_MESHSET.iPrimList];
				if (nodestatlist != null && (nodestatlist[nNS_MESHSET.iNode] & 1) != 0)
				{
					continue;
				}
				nngDrawCallBackVal.iMeshset = j;
				nngDrawCallBackVal.iNode = nNS_MESHSET.iNode;
				nngDrawCallBackVal.iMaterial = nNS_MESHSET.iMaterial;
				nngDrawCallBackVal.pMaterial = obj.pMatPtrList[nNS_MESHSET.iMaterial];
				nngDrawCallBackVal.iVtxList = nNS_MESHSET.iVtxList;
				nngDrawCallBackVal.pVtxListPtr = nNS_VTXLISTPTR;
				nngDrawCallBackVal.bModified = 0;
				nngDrawCallBackVal.bReDraw = 0;
				OpenGL.glMatrixMode(5888u);
				if ((nNS_SUBOBJ.fType & 0x100) != 0)
				{
					Matrix matrix = (Matrix)mtxpal[nNS_MESHSET.iMatrix];
					OpenGL.glLoadMatrixf(ref matrix);
				}
				else
				{
					OpenGL.glLoadIdentity();
				}
				while (nnPutMaterial(nngDrawCallBackVal) != 0)
				{
					nngDrawCallBackVal.iPrevMaterial = nNS_MESHSET.iMaterial;
					nngDrawCallBackVal.iPrevVtxList = nNS_MESHSET.iVtxList;
					if ((nNS_VTXLISTPTR.fType & 1) != 0)
					{
						if ((flag & 0x300) != 0)
						{
							nnDrawObjectNormal(nNS_VTXLISTPTR, plistptr, mtxpal, flag);
						}
						else
						{
							if ((nNS_SUBOBJ.fType & 0x200) != 0)
							{
								NNS_VTXLIST_GL_DESC nNS_VTXLIST_GL_DESC = (NNS_VTXLIST_GL_DESC)nNS_VTXLISTPTR.pVtxList;
								int nMatrix = nNS_VTXLIST_GL_DESC.nMatrix;
								OpenGL.glEnable(34880u);
								OpenGL.glMatrixMode(34880u);
								for (uint num4 = 0u; num4 < nMatrix; num4++)
								{
									OpenGL.glCurrentPaletteMatrixOES(num4);
									Matrix matrix2 = (Matrix)mtxpal[nNS_VTXLIST_GL_DESC.pMatrixIndices[num4]];
									OpenGL.glLoadMatrixf(ref matrix2);
								}
							}
							else
							{
								OpenGL.glDisable(34880u);
							}
							if (num != nNS_MESHSET.iVtxList || num2 != nnGetTexCoordSrc(0) || num3 != nnGetTexCoordSrc(1))
							{
								nnDrawObjectVertexList(nNS_VTXLISTPTR, flag, alternativeLighting);
								num = nNS_MESHSET.iVtxList;
								num2 = nnGetTexCoordSrc(0);
								num3 = nnGetTexCoordSrc(1);
								if (nNS_MESHSET.iMatrix != -1)
								{
									nnPutEnvironmentTextureMatrix(mtxpal[nNS_MESHSET.iMatrix]);
								}
								else
								{
									nnPutEnvironmentTextureMatrix(mtxpal[0]);
								}
							}
							nnDrawObjectPrimitiveList(plistptr, flag);
						}
					}
					else
					{
						uint num5 = nNS_VTXLISTPTR.fType & 0xFF0000;
					}
					if (nngDrawCallBackVal.bReDraw == 0)
					{
						break;
					}
				}
			}
		}
		OpenGL.glDisable(34880u);
	}

	private void nnMakeCameraPointerViewMatrix(NNS_MATRIX mtx, NNS_CAMERAPTR camptr)
	{
		mppAssertNotImpl();
		switch (camptr.fType)
		{
		case 3135u:
			nnMakeRotationCameraViewMatrix(mtx, (NNS_CAMERA_ROTATION)camptr.pCamera);
			break;
		case 255u:
			nnMakeTargetRollCameraViewMatrix(mtx, (NNS_CAMERA_TARGET_ROLL)camptr.pCamera);
			break;
		case 383u:
			nnMakeTargetUpVectorCameraViewMatrix(mtx, (NNS_CAMERA_TARGET_UPVECTOR)camptr.pCamera);
			break;
		case 639u:
			nnMakeTargetUpTargetCameraViewMatrix(mtx, (NNS_CAMERA_TARGET_UPTARGET)camptr.pCamera);
			break;
		}
	}

