	private static void nnMakeTargetRollCameraViewMatrix(NNS_MATRIX mtx, NNS_CAMERA_TARGET_ROLL cam)
	{
		SNNS_VECTOR dst = default(SNNS_VECTOR);
		SNNS_VECTOR dst2 = default(SNNS_VECTOR);
		SNNS_VECTOR ilook = new SNNS_VECTOR
		{
			x = cam.Position.x - cam.Target.x,
			y = cam.Position.y - cam.Target.y,
			z = cam.Position.z - cam.Target.z
		};
		nnNormalizeVector(ref ilook, ref ilook);
		dst.x = ilook.z;
		dst.y = 0f;
		dst.z = 0f - ilook.x;
		nnNormalizeVector(ref dst, ref dst);
		nnCrossProductVector(ref dst2, ref ilook, ref dst);
		nnMakeVectorCameraViewMatrix(mtx, cam.Position, ref dst, ref dst2, ref ilook);
		SNNS_MATRIX dst3;
		nnMakeRotateZMatrix(out dst3, -cam.Roll);
		nnMultiplyMatrix(mtx, ref dst3, mtx);
	}

	private static void nnMakeTargetUpVectorCameraViewMatrix(NNS_MATRIX mtx, NNS_CAMERA_TARGET_UPVECTOR cam)
	{
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR2 = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR3 = GlobalPool<NNS_VECTOR>.Alloc();
		nNS_VECTOR.x = cam.Position.x - cam.Target.x;
		nNS_VECTOR.y = cam.Position.y - cam.Target.y;
		nNS_VECTOR.z = cam.Position.z - cam.Target.z;
		nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
		nnCrossProductVector(nNS_VECTOR2, cam.UpVector, nNS_VECTOR);
		nnNormalizeVector(nNS_VECTOR2, nNS_VECTOR2);
		nnCrossProductVector(nNS_VECTOR3, nNS_VECTOR, nNS_VECTOR2);
		nnMakeVectorCameraViewMatrix(mtx, cam.Position, nNS_VECTOR2, nNS_VECTOR3, nNS_VECTOR);
	}

