	private static void nnMakeVectorCameraViewMatrix(NNS_MATRIX mtx, NNS_VECTOR pos, NNS_VECTOR right, NNS_VECTOR up, NNS_VECTOR ilook)
	{
		mtx.M00 = right.x;
		mtx.M01 = right.y;
		mtx.M02 = right.z;
		mtx.M03 = 0f - (right.x * pos.x + right.y * pos.y + right.z * pos.z);
		mtx.M10 = up.x;
		mtx.M11 = up.y;
		mtx.M12 = up.z;
		mtx.M13 = 0f - (up.x * pos.x + up.y * pos.y + up.z * pos.z);
		mtx.M20 = ilook.x;
		mtx.M21 = ilook.y;
		mtx.M22 = ilook.z;
		mtx.M23 = 0f - (ilook.x * pos.x + ilook.y * pos.y + ilook.z * pos.z);
		mtx.M30 = (mtx.M31 = (mtx.M32 = 0f));
		mtx.M33 = 1f;
	}

	private static void nnMakeVectorCameraViewMatrix(NNS_MATRIX mtx, NNS_VECTOR pos, ref SNNS_VECTOR right, ref SNNS_VECTOR up, ref SNNS_VECTOR ilook)
	{
		mtx.M00 = right.x;
		mtx.M01 = right.y;
		mtx.M02 = right.z;
		mtx.M03 = 0f - (right.x * pos.x + right.y * pos.y + right.z * pos.z);
		mtx.M10 = up.x;
		mtx.M11 = up.y;
		mtx.M12 = up.z;
		mtx.M13 = 0f - (up.x * pos.x + up.y * pos.y + up.z * pos.z);
		mtx.M20 = ilook.x;
		mtx.M21 = ilook.y;
		mtx.M22 = ilook.z;
		mtx.M23 = 0f - (ilook.x * pos.x + ilook.y * pos.y + ilook.z * pos.z);
		mtx.M30 = (mtx.M31 = (mtx.M32 = 0f));
		mtx.M33 = 1f;
	}

	public static uint AMD_RGBA8888(uint r, uint g, uint b, uint a)
	{
		return ((r & 0xFF) << 24) | ((g & 0xFF) << 16) | ((b & 0xFF) << 8) | (a & 0xFF);
	}

	public static uint AMD_RGBA8888(byte r, byte g, byte b, byte a)
	{
		return (uint)(((r & 0xFF) << 24) | ((g & 0xFF) << 16) | ((b & 0xFF) << 8) | (a & 0xFF));
	}

	public static void amFlagOn(ref uint dst_, uint on_)
	{
		dst_ |= on_;
	}

	public static void amFlagOff(ref uint dst_, uint off_)
	{
		dst_ &= ~off_;
	}

	public static void amFlagFlip(ref uint dst_, uint flip_)
	{
		dst_ ^= flip_;
	}

	public static void amFlagOnOff(ref uint dst_, uint on_, uint off_)
	{
		dst_ = (dst_ & ~off_) | on_;
	}

	public static float amSqrt(float fs_)
	{
		return nnSqrt(fs_);
	}

	public static float amPow2(float n_)
	{
		return n_ * n_;
	}

	public static float amPow3(float n_)
	{
		return n_ * n_ * n_;
	}

	public static bool amIsZerof(float fs)
	{
		if (0f < fs || fs < 0f)
		{
			return false;
		}
		return true;
	}

	public static float amClamp(float n_, float min_, float max_)
	{
		if (!(n_ < min_))
		{
			if (!(n_ > max_))
			{
				return n_;
			}
			return max_;
		}
		return min_;
	}

