	public static T amMax<T>(T a, T b) where T : IComparable<T>
	{
		if (a.CompareTo(b) <= 0)
		{
			return b;
		}
		return a;
	}

	public static T amMin<T>(T a, T b) where T : IComparable<T>
	{
		if (a.CompareTo(b) >= 0)
		{
			return b;
		}
		return a;
	}

