	}

	public bool amDrawBegin(AMS_RENDER_TARGET target, uint flag, NNS_RGBA_U8 color, float depth, int stencil)
	{
		_am_draw_offset_x = 0;
		amRenderSetTarget(target, flag, color, depth, stencil);
		if (_am_draw_in_scene != 0)
		{
			return true;
		}
		if (flag != 0)
		{
			uint num = 0u;
			if ((flag & AMD_RENDER_CLEAR_COLOR) != 0)
			{
				if (color != null)
				{
					_am_draw_bg_color.r = color.r;
					_am_draw_bg_color.g = color.g;
					_am_draw_bg_color.b = color.b;
					_am_draw_bg_color.a = color.a;
				}
				float red = (float)(int)_am_draw_bg_color.r / 255f;
				float green = (float)(int)_am_draw_bg_color.g / 255f;
				float blue = (float)(int)_am_draw_bg_color.b / 255f;
				float alpha = (float)(int)_am_draw_bg_color.a / 255f;
				OpenGL.glClearColor(red, green, blue, alpha);
				num |= 0x4000;
			}
			if ((flag & AMD_RENDER_CLEAR_DEPTH) != 0)
			{
				OpenGL.glClearDepthf(depth);
				num |= 0x100;
			}
			OpenGL.glClear(num);
		}
		return true;
	}

