	public static void amDrawEndScene()
	{
		AMS_DISPLAYLIST_MANAGER am_displaylist_manager = _am_displaylist_manager;
		int sort_num = am_displaylist_manager.sort_num;
		am_displaylist_manager.sort_num = 0;
		if (sort_num == 0)
		{
			return;
		}
		AMS_DRAW_SORT aMS_DRAW_SORT = new AMS_DRAW_SORT();
		ArrayPointer<AMS_DRAW_SORT> arrayPointer = new ArrayPointer<AMS_DRAW_SORT>(am_displaylist_manager.sortlist);
		int num = sort_num - 1;
		while (num > 0)
		{
			ArrayPointer<AMS_DRAW_SORT> arrayPointer2 = arrayPointer;
			ArrayPointer<AMS_DRAW_SORT> arrayPointer3 = arrayPointer + 1;
			int num2 = (~arrayPointer2).key;
			int num3 = num;
			while (num3 > 0)
			{
				int key = (~arrayPointer3).key;
				if (key >= num2)
				{
					num2 = key;
					arrayPointer2 = arrayPointer3;
				}
				num3--;
				++arrayPointer3;
			}
			aMS_DRAW_SORT.Assign(arrayPointer);
			(~arrayPointer).Assign(~arrayPointer2);
			(~arrayPointer2).Assign(aMS_DRAW_SORT);
			num--;
			++arrayPointer;
		}
		amDrawPushState();
		arrayPointer = new ArrayPointer<AMS_DRAW_SORT>(am_displaylist_manager.sortlist);
		num = sort_num;
		while (num > 0)
		{
			AMS_COMMAND_HEADER command = (~arrayPointer).command;
			if (command.command_id >= 0)
			{
				_am_draw_command_sort(command, 0u);
			}
			else
			{
				_am_draw_sort_system_exec[-command.command_id](command, 0u);
			}
			num--;
			++arrayPointer;
		}
		amDrawPopState();
	}

