	public static void amDrawExecCommand(uint state, uint drawflag)
	{
		AMS_DISPLAYLIST_MANAGER am_displaylist_manager = _am_displaylist_manager;
		AMS_DISPLAYLIST aMS_DISPLAYLIST = am_displaylist_manager.displaylist[am_displaylist_manager.read_index];
		object[] array = aMS_DISPLAYLIST.command_buf.array;
		AMS_COMMAND_BUFFER_HEADER aMS_COMMAND_BUFFER_HEADER = (AMS_COMMAND_BUFFER_HEADER)array[0];
		int num = aMS_DISPLAYLIST.command_buf_size - 1;
		for (int i = 0; i < num; i++)
		{
			AMS_COMMAND_HEADER aMS_COMMAND_HEADER = (AMS_COMMAND_HEADER)array[i + 1];
			if (aMS_COMMAND_HEADER.state == state)
			{
				if (aMS_COMMAND_HEADER.command_id >= 0)
				{
					_am_draw_command_func(aMS_COMMAND_HEADER, drawflag);
				}
				else
				{
					_am_draw_system_exec[-aMS_COMMAND_HEADER.command_id](aMS_COMMAND_HEADER, drawflag);
				}
			}
		}
	}

	private static void amDrawExecRegist()
	{
		AMS_DISPLAYLIST_MANAGER am_displaylist_manager = _am_displaylist_manager;
		int regist_num = am_displaylist_manager.regist_num;
		int num = am_displaylist_manager.reg_read_index;
		int reg_end_index = am_displaylist_manager.reg_end_index;
		if (regist_num != 0)
		{
			regist_num = 0;
			while (num != reg_end_index)
			{
				AMS_REGISTLIST aMS_REGISTLIST = am_displaylist_manager.registlist[num];
				num = (num + 1) % 256;
				regist_num++;
				_am_draw_regist_func[aMS_REGISTLIST.command_id](aMS_REGISTLIST);
			}
			am_displaylist_manager.regist_num -= regist_num;
			am_displaylist_manager.reg_read_index = num;
		}
	}

