	private static void amDrawSetMaterialTexOffset(int slot, int mode, float u, float v)
	{
		ArrayPointer<AMS_DRAWSTATE_TEXOFFSET> arrayPointer;
		if (slot != -1)
		{
			if (mode != -1)
			{
				nnSetMaterialControlTextureOffset(slot, mode, u, v);
				_am_draw_state.drawflag |= 268435456u;
			}
			else
			{
				_am_draw_state.drawflag &= 4026531839u;
			}
			arrayPointer = new ArrayPointer<AMS_DRAWSTATE_TEXOFFSET>(_am_draw_state.texoffset, slot);
			(~arrayPointer).mode = mode;
			(~arrayPointer).u = u;
			(~arrayPointer).v = v;
			return;
		}
		arrayPointer = new ArrayPointer<AMS_DRAWSTATE_TEXOFFSET>(_am_draw_state.texoffset, 0);
		if (mode != -1)
		{
			int num = 0;
			while (num < 4)
			{
				nnSetMaterialControlTextureOffset(num, mode, u, v);
				_am_draw_state.drawflag |= 268435456u;
				(~arrayPointer).mode = mode;
				(~arrayPointer).u = u;
				(~arrayPointer).v = v;
				num++;
				++arrayPointer;
			}
		}
		else
		{
			int num = 0;
			while (num < 4)
			{
				_am_draw_state.drawflag &= 4026531839u;
				(~arrayPointer).mode = mode;
				(~arrayPointer).u = u;
				(~arrayPointer).v = v;
				num++;
				++arrayPointer;
			}
		}
	}

