	private static void _amDrawObjectCore(AMS_COMMAND_HEADER command, uint drawflag)
	{
		NNS_MATRIX nNS_MATRIX = amDrawAlloc_NNS_MATRIX();
		amMatrixPush();
		AMS_PARAM_DRAW_OBJECT aMS_PARAM_DRAW_OBJECT = (AMS_PARAM_DRAW_OBJECT)command.param;
		int nNode = aMS_PARAM_DRAW_OBJECT._object.nNode;
		if (__amDrawObject.plt_mtx == null || __amDrawObject.plt_mtx.Length < nNode)
		{
			__amDrawObject.nstat = new uint[nNode];
			__amDrawObject.plt_mtx = new NNS_MATRIX[nNode];
			for (int i = 0; i < nNode; i++)
			{
				__amDrawObject.plt_mtx[i] = new NNS_MATRIX();
			}
		}
		NNS_MATRIX[] plt_mtx = __amDrawObject.plt_mtx;
		uint[] nstat = __amDrawObject.nstat;
		if (aMS_PARAM_DRAW_OBJECT.mtx != null)
		{
			nnMultiplyMatrix(nNS_MATRIX, amMatrixGetCurrent(), aMS_PARAM_DRAW_OBJECT.mtx);
			nnMultiplyMatrix(nNS_MATRIX, _am_draw_world_view_matrix, nNS_MATRIX);
		}
		else
		{
			nnMultiplyMatrix(nNS_MATRIX, _am_draw_world_view_matrix, amMatrixGetCurrent());
		}
		nnSetUpNodeStatusList(nstat, nNode, 0u);
		nnCalcMatrixPalette(plt_mtx, nstat, aMS_PARAM_DRAW_OBJECT._object, nNS_MATRIX, _am_default_stack, 1u);
		if (aMS_PARAM_DRAW_OBJECT.texlist != null)
		{
			nnSetTextureList(aMS_PARAM_DRAW_OBJECT.texlist);
		}
		nnSetMaterialCallback(aMS_PARAM_DRAW_OBJECT.material_func);
		if (command.command_id == -6)
		{
			nnDrawObject(aMS_PARAM_DRAW_OBJECT._object, plt_mtx, nstat, aMS_PARAM_DRAW_OBJECT.sub_obj_type | 0x100 | 0x200 | 7, aMS_PARAM_DRAW_OBJECT.flag | drawflag | _am_draw_state.drawflag, 0u);
		}
		else
		{
			nnDrawMaterialMotionObject(aMS_PARAM_DRAW_OBJECT._object, plt_mtx, nstat, aMS_PARAM_DRAW_OBJECT.sub_obj_type | 0x100 | 0x200 | 7, aMS_PARAM_DRAW_OBJECT.flag | drawflag | _am_draw_state.drawflag);
		}
		if (aMS_PARAM_DRAW_OBJECT.material_func != null)
		{
			nnSetMaterialCallback(null);
		}
		amMatrixPop();
	}

	private static void _amDrawObjectSetMaterial(AMS_COMMAND_HEADER command, uint drawflag)
	{
		AMS_PARAM_DRAW_OBJECT_MATERIAL aMS_PARAM_DRAW_OBJECT_MATERIAL = (AMS_PARAM_DRAW_OBJECT_MATERIAL)command.param;
		amDrawPushState();
		if ((aMS_PARAM_DRAW_OBJECT_MATERIAL.flag & 0x300000) != 0)
		{
			amDrawSetMaterialDiffuse(3, aMS_PARAM_DRAW_OBJECT_MATERIAL.color.r, aMS_PARAM_DRAW_OBJECT_MATERIAL.color.g, aMS_PARAM_DRAW_OBJECT_MATERIAL.color.b);
			amDrawSetMaterialAmbient(3, aMS_PARAM_DRAW_OBJECT_MATERIAL.color.r, aMS_PARAM_DRAW_OBJECT_MATERIAL.color.g, aMS_PARAM_DRAW_OBJECT_MATERIAL.color.b);
		}
		if ((aMS_PARAM_DRAW_OBJECT_MATERIAL.flag & 0x800000) != 0)
		{
			amDrawSetMaterialAlpha(3, aMS_PARAM_DRAW_OBJECT_MATERIAL.color.a);
		}
		if ((aMS_PARAM_DRAW_OBJECT_MATERIAL.flag & 0x10000000) != 0)
		{
			amDrawSetMaterialTexOffset(0, 1, aMS_PARAM_DRAW_OBJECT_MATERIAL.scroll_u, aMS_PARAM_DRAW_OBJECT_MATERIAL.scroll_v);
		}
		command.command_id = -6;
		_amDrawObject(command, drawflag);
		amDrawPopState();
	}

