	private static void _amDrawSortPrimitive3DCore(AMS_COMMAND_HEADER command, uint drawflag)
	{
		NNS_MATRIX amDrawSortPrimitive3D_base_mtx = _amDrawSortPrimitive3D_base_mtx;
		AMS_PARAM_DRAW_PRIMITIVE aMS_PARAM_DRAW_PRIMITIVE = (AMS_PARAM_DRAW_PRIMITIVE)command.param;
		if (aMS_PARAM_DRAW_PRIMITIVE.texlist != null && aMS_PARAM_DRAW_PRIMITIVE.texId != -1)
		{
			nnSetPrimitiveTexNum(aMS_PARAM_DRAW_PRIMITIVE.texlist, aMS_PARAM_DRAW_PRIMITIVE.texId);
			nnSetPrimitiveTexState(0, 0, 0, 0);
		}
		nnCopyMatrix(amDrawSortPrimitive3D_base_mtx, aMS_PARAM_DRAW_PRIMITIVE.mtx);
		nnMultiplyMatrix(amDrawSortPrimitive3D_base_mtx, amDrawGetWorldViewMatrix(), amDrawSortPrimitive3D_base_mtx);
		nnSetPrimitive3DMatrix(amDrawSortPrimitive3D_base_mtx);
		_amDrawSetPrimitive3DParam(command, drawflag);
		nnBeginDrawPrimitive3D(aMS_PARAM_DRAW_PRIMITIVE.format3D, aMS_PARAM_DRAW_PRIMITIVE.ablend, 0, 0);
		switch (aMS_PARAM_DRAW_PRIMITIVE.format3D)
		{
		case 4:
			nnDrawPrimitive3D(aMS_PARAM_DRAW_PRIMITIVE.type, aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D, aMS_PARAM_DRAW_PRIMITIVE.count);
			break;
		case 2:
			nnDrawPrimitive3D(aMS_PARAM_DRAW_PRIMITIVE.type, aMS_PARAM_DRAW_PRIMITIVE.vtxPC3D, aMS_PARAM_DRAW_PRIMITIVE.count);
			break;
		}
		nnEndDrawPrimitive3D();
	}

	// Las piezas del HUD y del menú de pausa se dibujan en su capa (sin zoom del nivel).
	private static bool amInLayerPass;

	private static void _amDrawInLayer(AMS_COMMAND_HEADER command, uint drawflag, _am_draw_command_delegate draw)
	{
		Sonic4Ep1 inst = Sonic4Ep1.pInstance;
		if (!(command.hud || command.uiLayer) || inst == null || !Sonic4Ep1.HUD_LAYER_ENABLED)
		{
			draw(command, drawflag);
			return;
		}
		// Si ya estamos dentro de una pasada de capa, no se cambia el destino otra vez (evita quedarse en la capa).
		if (amInLayerPass)
		{
			draw(command, drawflag);
			return;
		}
		amInLayerPass = true;
		// Pausa y resultados (uiLayer sin hud) van a su capa propia; el HUD a la suya.
		inst.BeginHudPass();
		try
		{
			draw(command, drawflag);
		}
		finally
		{
			inst.EndHudPass();
			amInLayerPass = false;
		}
	}

	private static void _amDrawSortPrimitive2D(AMS_COMMAND_HEADER command, uint drawflag)
	{
		_amDrawInLayer(command, drawflag, _amDrawSortPrimitive2DCore);
	}

	private static void _amDrawSortPrimitive2DCore(AMS_COMMAND_HEADER command, uint drawflag)
	{
		AMS_PARAM_DRAW_PRIMITIVE aMS_PARAM_DRAW_PRIMITIVE = (AMS_PARAM_DRAW_PRIMITIVE)command.param;
		NNS_MATRIX amDrawSortPrimitive2D_mtx = _amDrawSortPrimitive2D_mtx;
		hudProjActive = command.hud;
		AmMakeOrtho2D(amDrawSortPrimitive2D_mtx);
		amDrawSetProjection(amDrawSortPrimitive2D_mtx, 1);
		if (aMS_PARAM_DRAW_PRIMITIVE.texlist != null && aMS_PARAM_DRAW_PRIMITIVE.texId != -1)
		{
			nnSetPrimitiveTexNum(aMS_PARAM_DRAW_PRIMITIVE.texlist, aMS_PARAM_DRAW_PRIMITIVE.texId);
			nnSetPrimitiveTexState(0, 0, 0, 0);
		}
		_amDrawSetPrimitive2DParam(command, drawflag);
		nnBeginDrawPrimitive2D(aMS_PARAM_DRAW_PRIMITIVE.format2D, aMS_PARAM_DRAW_PRIMITIVE.ablend);
		switch (aMS_PARAM_DRAW_PRIMITIVE.format2D)
		{
		case 2:
			nnDrawPrimitive2D(aMS_PARAM_DRAW_PRIMITIVE.type, aMS_PARAM_DRAW_PRIMITIVE.vtxPCT2D, aMS_PARAM_DRAW_PRIMITIVE.count, aMS_PARAM_DRAW_PRIMITIVE.zOffset);
			break;
		case 1:
			nnDrawPrimitive2D(aMS_PARAM_DRAW_PRIMITIVE.type, aMS_PARAM_DRAW_PRIMITIVE.vtxPC2D, aMS_PARAM_DRAW_PRIMITIVE.count, aMS_PARAM_DRAW_PRIMITIVE.zOffset);
			break;
		}
		nnEndDrawPrimitive2D();
	}

