	private static void _amDrawSetPrimitive3DParam(AMS_COMMAND_HEADER command, uint drawflag)
	{
		AMS_PARAM_DRAW_PRIMITIVE aMS_PARAM_DRAW_PRIMITIVE = (AMS_PARAM_DRAW_PRIMITIVE)command.param;
		if (aMS_PARAM_DRAW_PRIMITIVE.aTest != 0)
		{
			nnSetPrimitive3DAlphaFuncGL(516u, 0.5f);
		}
		else
		{
			nnSetPrimitive3DAlphaFuncGL(519u, 0.5f);
		}
		if (aMS_PARAM_DRAW_PRIMITIVE.zMask != 0)
		{
			nnSetPrimitive3DDepthMaskGL(false);
		}
		else
		{
			nnSetPrimitive3DDepthMaskGL(true);
		}
		if (aMS_PARAM_DRAW_PRIMITIVE.zTest != 0)
		{
			nnSetPrimitive3DDepthFuncGL(515u);
		}
		else
		{
			nnSetPrimitive3DDepthFuncGL(519u);
		}
		if (aMS_PARAM_DRAW_PRIMITIVE.ablend != 0 && aMS_PARAM_DRAW_PRIMITIVE.bldMode == 32774)
		{
			switch ((uint)aMS_PARAM_DRAW_PRIMITIVE.bldDst)
			{
			case 1u:
				nnSetPrimitiveBlend(0);
				break;
			case 771u:
				nnSetPrimitiveBlend(1);
				break;
			default:
				nnSetPrimitiveBlend(1);
				break;
			}
		}
	}

