	private static void _amDrawLoadTexture(AMS_REGISTLIST regist)
	{
		AMS_PARAM_LOAD_TEXTURE aMS_PARAM_LOAD_TEXTURE = (AMS_PARAM_LOAD_TEXTURE)regist.param;
		OpenGL.glGenTexture(out aMS_PARAM_LOAD_TEXTURE.pTexInfo.TexName);
		OpenGL.glBindTexture(3553u, aMS_PARAM_LOAD_TEXTURE.pTexInfo.TexName);
		OpenGL.mppglTexImage2D(aMS_PARAM_LOAD_TEXTURE.tex);
		_amSetTextureAttribute(aMS_PARAM_LOAD_TEXTURE);
		aMS_PARAM_LOAD_TEXTURE.buf_delete = null;
		regist.command_id = 0;
	}

	private static void _amSetTextureAttribute(AMS_PARAM_LOAD_TEXTURE param)
	{
		param.pTexInfo.Bank = param.bank;
		param.pTexInfo.GlobalIndex = param.globalIndex;
		param.pTexInfo.Flag = 0u;
	}

	private static void _amDrawReleaseTexture(AMS_REGISTLIST regist)
	{
		AMS_PARAM_RELEASE_TEXTURE aMS_PARAM_RELEASE_TEXTURE = (AMS_PARAM_RELEASE_TEXTURE)regist.param;
		int nTex = aMS_PARAM_RELEASE_TEXTURE.texlist.nTex;
		ArrayPointer<NNS_TEXINFO> arrayPointer = aMS_PARAM_RELEASE_TEXTURE.texlist.pTexInfoList;
		int num = nTex - 1;
		arrayPointer += nTex - 1;
		while (num >= 0)
		{
			if ((~arrayPointer).TexName != 0)
			{
				OpenGL.glDeleteTextures(1, new uint[1] { (~arrayPointer).TexName });
			}
			num--;
			--arrayPointer;
		}
		aMS_PARAM_RELEASE_TEXTURE.texlist.nTex = -1;
		aMS_PARAM_RELEASE_TEXTURE.texlist.pTexInfoList = null;
		aMS_PARAM_RELEASE_TEXTURE.texlist = null;
		regist.command_id = 0;
	}

