	private static void gmGmkStopperStart(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STOPPER_WORK gMS_GMK_STOPPER_WORK = (GMS_GMK_STOPPER_WORK)obj_work;
		gMS_GMK_STOPPER_WORK.gmk_work.ene_com.col_work.obj_col.obj = obj_work;
		gMS_GMK_STOPPER_WORK.gmk_work.ene_com.col_work.obj_col.width = (ushort)tbl_gm_gmk_piston_col_rect[0];
		gMS_GMK_STOPPER_WORK.gmk_work.ene_com.col_work.obj_col.height = (ushort)tbl_gm_gmk_piston_col_rect[1];
		gMS_GMK_STOPPER_WORK.gmk_work.ene_com.col_work.obj_col.ofst_x = tbl_gm_gmk_piston_col_rect[2];
		gMS_GMK_STOPPER_WORK.gmk_work.ene_com.col_work.obj_col.ofst_y = tbl_gm_gmk_piston_col_rect[3];
		gMS_GMK_STOPPER_WORK.gmk_work.ene_com.col_work.obj_col.dir = 0;
		gMS_GMK_STOPPER_WORK.gmk_work.ene_com.rect_work[0].flag &= 4294967291u;
		gMS_GMK_STOPPER_WORK.gmk_work.ene_com.rect_work[1].flag &= 4294967291u;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_GMK_STOPPER_WORK.gmk_work.ene_com.rect_work[2];
		oBS_RECT_WORK.ppDef = gmGmkStopperHit;
		oBS_RECT_WORK.ppHit = null;
		ObjRectAtkSet(oBS_RECT_WORK, 0, 0);
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		ObjRectWorkSet(oBS_RECT_WORK, tbl_gm_gmk_piston_col_rect[4], tbl_gm_gmk_piston_col_rect[5], tbl_gm_gmk_piston_col_rect[6], tbl_gm_gmk_piston_col_rect[7]);
		obj_work.flag &= 4294967293u;
		gMS_GMK_STOPPER_WORK.se_handle = null;
		mtTaskChangeTcbDestructor(obj_work.tcb, gmGmkStopperExit);
		obj_work.ppFunc = gmGmkStopperStay;
	}

	private static void gmGmkStopperStay(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STOPPER_WORK gMS_GMK_STOPPER_WORK = (GMS_GMK_STOPPER_WORK)obj_work;
		if (gMS_GMK_STOPPER_WORK.ply_work != null)
		{
			if (gMS_GMK_STOPPER_WORK.call_slot_id == -1)
			{
				gmGmkStopperStay_Norm(obj_work);
			}
			else
			{
				gmGmkStopperStay_Slot(obj_work);
			}
		}
	}

	private static void gmGmkStopperStay_100(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STOPPER_WORK gMS_GMK_STOPPER_WORK = (GMS_GMK_STOPPER_WORK)obj_work;
		if (obj_work.user_timer < gMS_GMK_STOPPER_WORK.ply_work.obj_work.pos.y >> 12)
		{
			gmGmkStopperReset(obj_work);
		}
	}

	private static void gmGmkStopperStay_Norm(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STOPPER_WORK gMS_GMK_STOPPER_WORK = (GMS_GMK_STOPPER_WORK)obj_work;
		ObjDrawObjectActionSet3DNNMaterial(obj_work, 0);
		obj_work.disp_flag &= 4294967279u;
		obj_work.disp_flag |= 4u;
		gMS_GMK_STOPPER_WORK.player_pass_timer = 143;
		obj_work.ppFunc = gmGmkStopperStay_Norm_100;
		GmCameraAllowSet(15f, 32f, 0f);
	}

	private static void gmGmkStopperStay_Norm_100(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STOPPER_WORK gMS_GMK_STOPPER_WORK = (GMS_GMK_STOPPER_WORK)obj_work;
		if (gMS_GMK_STOPPER_WORK.ply_work != g_gm_main_system.ply_work[0] || gMS_GMK_STOPPER_WORK.ply_work.gmk_obj != obj_work || gMS_GMK_STOPPER_WORK.ply_work.seq_state != 40)
		{
			gmGmkStopperReset(obj_work);
			return;
		}
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
		GmCameraPosSet(FXM_FLOAT_TO_FX32(oBS_CAMERA.pos.x), FXM_FLOAT_TO_FX32(0f - oBS_CAMERA.pos.y) + 16384, FXM_FLOAT_TO_FX32(oBS_CAMERA.pos.z));
		gMS_GMK_STOPPER_WORK.player_pass_timer--;
		if (gMS_GMK_STOPPER_WORK.player_pass_timer <= 0)
		{
			obj_work.disp_flag &= 4294967291u;
			gmGmkStopperStay_Norm_110(obj_work);
		}
		else if (gMS_GMK_STOPPER_WORK.player_pass_timer % 16 == 0)
		{
			GmPlayerAddScore(gMS_GMK_STOPPER_WORK.ply_work, 1000, gMS_GMK_STOPPER_WORK.ply_work.obj_work.pos.x, gMS_GMK_STOPPER_WORK.ply_work.obj_work.pos.y);
			gsSoundStopSe(gMS_GMK_STOPPER_WORK.se_handle);
			gMS_GMK_STOPPER_WORK.se_handle.snd_ctrl_param.pitch = 0.8f - (float)gMS_GMK_STOPPER_WORK.player_pass_timer / 160f;
			GmSoundPlaySE("Casino3", gMS_GMK_STOPPER_WORK.se_handle);
			if (gMS_GMK_STOPPER_WORK.player_pass_timer <= 16)
			{
				GmSoundPlaySE("Casino3_1");
			}
		}
	}

	private static void gmGmkStopperStay_Norm_110(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STOPPER_WORK gMS_GMK_STOPPER_WORK = (GMS_GMK_STOPPER_WORK)obj_work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		gMS_GMK_STOPPER_WORK.player_pass_timer = 0;
		gMS_GMK_STOPPER_WORK.gmk_work.obj_3d.mat_frame = 0f;
		obj_work.disp_flag |= 16u;
		obj_work.ppFunc = gmGmkStopperStay_100;
		if (gMS_PLAYER_WORK.seq_state == 40)
		{
			GmPlySeqInitStopperEnd(gMS_GMK_STOPPER_WORK.ply_work);
		}
	}

	private static void gmGmkStopperStay_Slot(OBS_OBJECT_WORK obj_work)
	{
		ObjDrawObjectActionSet3DNNMaterial(obj_work, 0);
		obj_work.disp_flag &= 4294967279u;
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmGmkStopperStay_Slot_100;
		GmCameraAllowSet(15f, 56f, 0f);
	}

	private static void gmGmkStopperStay_Slot_100(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STOPPER_WORK gMS_GMK_STOPPER_WORK = (GMS_GMK_STOPPER_WORK)obj_work;
		if (gMS_GMK_STOPPER_WORK.ply_work != g_gm_main_system.ply_work[0] || gMS_GMK_STOPPER_WORK.ply_work.gmk_obj != obj_work || gMS_GMK_STOPPER_WORK.ply_work.seq_state != 40)
		{
			gmGmkStopperReset(obj_work);
			return;
		}
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
		GmCameraPosSet(FXM_FLOAT_TO_FX32(oBS_CAMERA.pos.x), FXM_FLOAT_TO_FX32(0f - oBS_CAMERA.pos.y) + 16384, FXM_FLOAT_TO_FX32(oBS_CAMERA.pos.z));
		if (GmGmkSlotIsStatus(gMS_GMK_STOPPER_WORK.call_slot_id) != 0)
		{
			obj_work.disp_flag &= 4294967291u;
			obj_work.ppFunc = gmGmkStopperStay_Slot_110;
			gmGmkStopperStay_Slot_110(obj_work);
		}
	}

	private static void gmGmkStopperStay_Slot_110(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STOPPER_WORK gMS_GMK_STOPPER_WORK = (GMS_GMK_STOPPER_WORK)obj_work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		gMS_GMK_STOPPER_WORK.gmk_work.obj_3d.mat_frame = 0f;
		obj_work.disp_flag |= 16u;
		obj_work.ppFunc = gmGmkStopperStay_100;
		if (gMS_PLAYER_WORK.seq_state == 40)
		{
			GmPlySeqInitStopperEnd(gMS_GMK_STOPPER_WORK.ply_work);
		}
	}

	private static void gmGmkStopperReset(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STOPPER_WORK gMS_GMK_STOPPER_WORK = (GMS_GMK_STOPPER_WORK)obj_work;
		gMS_GMK_STOPPER_WORK.gmk_work.ene_com.col_work.obj_col.obj = obj_work;
		obj_work.flag &= 4294967293u;
		gMS_GMK_STOPPER_WORK.player_pass_timer = 0;
		gMS_GMK_STOPPER_WORK.ply_work = null;
		gMS_GMK_STOPPER_WORK.gmk_work.obj_3d.mat_frame = 0f;
		obj_work.disp_flag |= 16u;
		obj_work.ppFunc = gmGmkStopperStay;
		if (gMS_GMK_STOPPER_WORK.se_handle != null)
		{
			GmSoundStopSE(gMS_GMK_STOPPER_WORK.se_handle);
			GsSoundFreeSeHandle(gMS_GMK_STOPPER_WORK.se_handle);
			gMS_GMK_STOPPER_WORK.se_handle = null;
		}
	}

	private static void gmGmkStopperLockWait(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STOPPER_WORK gMS_GMK_STOPPER_WORK = (GMS_GMK_STOPPER_WORK)obj_work;
		if (gMS_GMK_STOPPER_WORK.ply_work != g_gm_main_system.ply_work[0] || gMS_GMK_STOPPER_WORK.ply_work.gmk_obj != obj_work || gMS_GMK_STOPPER_WORK.ply_work.seq_state != 40)
		{
			gmGmkStopperReset(obj_work);
			return;
		}
		GMS_PLAYER_WORK ply_work = gMS_GMK_STOPPER_WORK.ply_work;
		if (obj_work.pos.x != ply_work.obj_work.pos.x || obj_work.pos.y != ply_work.obj_work.pos.y)
		{
			return;
		}
		if (gMS_GMK_STOPPER_WORK.call_slot_id >= 0)
		{
			GmGmkSlotStartRequest(gMS_GMK_STOPPER_WORK.call_slot_id, ply_work);
			obj_work.ppFunc = gmGmkStopperStay_Slot;
			GmSoundPlaySE("Casino3");
			return;
		}
		obj_work.ppFunc = gmGmkStopperStay_Norm;
		if (gMS_GMK_STOPPER_WORK.se_handle != null)
		{
			GmSoundStopSE(gMS_GMK_STOPPER_WORK.se_handle);
			GsSoundFreeSeHandle(gMS_GMK_STOPPER_WORK.se_handle);
		}
		gMS_GMK_STOPPER_WORK.se_handle = GsSoundAllocSeHandle();
		gMS_GMK_STOPPER_WORK.se_handle.flag |= 2147483648u;
		GmSoundPlaySE("Casino3", gMS_GMK_STOPPER_WORK.se_handle);
	}

	private static void gmGmkStopperHit(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		OBS_OBJECT_WORK parent_obj = mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		GMS_GMK_STOPPER_WORK gMS_GMK_STOPPER_WORK = (GMS_GMK_STOPPER_WORK)parent_obj;
		int num = 0;
		if (gMS_PLAYER_WORK != g_gm_main_system.ply_work[0])
		{
			return;
		}
		if (parent_obj.pos.y > gMS_PLAYER_WORK.obj_work.pos.y)
		{
			if (gMS_PLAYER_WORK.obj_work.spd.y >= 0)
			{
				num = 1;
			}
		}
		else if (gMS_PLAYER_WORK.obj_work.spd.y <= 0)
		{
			num = 1;
		}
		if (num != 0)
		{
			GmPlySeqInitStopper(gMS_PLAYER_WORK, gMS_GMK_STOPPER_WORK.gmk_work.ene_com);
			gMS_GMK_STOPPER_WORK.gmk_work.ene_com.col_work.obj_col.obj = null;
			parent_obj.flag |= 2u;
			gMS_GMK_STOPPER_WORK.ply_work = gMS_PLAYER_WORK;
			parent_obj.user_timer = (parent_obj.pos.y >> 12) + gMS_GMK_STOPPER_WORK.gmk_work.ene_com.col_work.obj_col.height + gMS_GMK_STOPPER_WORK.gmk_work.ene_com.col_work.obj_col.ofst_y - gMS_PLAYER_WORK.rect_work[0].rect.top;
			parent_obj.ppFunc = gmGmkStopperLockWait;
		}
		else
		{
			mine_rect.flag &= 4294573823u;
		}
	}

	private static void gmGmkStopperExit(MTS_TASK_TCB tcb)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(tcb);
