	private static void gmGmkSpCtpltStart(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SPCTPLT_WORK gMS_GMK_SPCTPLT_WORK = (GMS_GMK_SPCTPLT_WORK)obj_work;
		ObjObjectAction3dNNMotionLoad(obj_work, 0, false, ObjDataGet(885), null, 0, null);
		ObjDrawObjectActionSet(obj_work, 0);
		ObjObjectAction3dNNMaterialMotionLoad(obj_work, 0, ObjDataGet(886), null, 0, null);
		obj_work.obj_3d.mat_speed = 1f;
		ObjDrawObjectActionSet3DNNMaterial(obj_work, 1);
		obj_work.disp_flag &= 4294967291u;
		((NNS_MATERIAL_GLES11_DESC)obj_work.obj_3d._object.pMatPtrList[0].pMaterial).fFlag |= 1u;
		((NNS_MATERIAL_GLES11_DESC)obj_work.obj_3d._object.pMatPtrList[1].pMaterial).fFlag |= 1u;
		gMS_GMK_SPCTPLT_WORK.gmk_work.ene_com.rect_work[2].flag &= 4294967291u;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_GMK_SPCTPLT_WORK.gmk_work.ene_com.rect_work[2];
		oBS_RECT_WORK.ppDef = null;
		oBS_RECT_WORK.ppHit = gmGmkSpCtplt_PlayerHit;
		ObjRectWorkSet(oBS_RECT_WORK, tbl_gm_gmk_spctplt_rect[gMS_GMK_SPCTPLT_WORK.ctplt_id][0], tbl_gm_gmk_spctplt_rect[gMS_GMK_SPCTPLT_WORK.ctplt_id][1], tbl_gm_gmk_spctplt_rect[gMS_GMK_SPCTPLT_WORK.ctplt_id][2], tbl_gm_gmk_spctplt_rect[gMS_GMK_SPCTPLT_WORK.ctplt_id][3]);
		obj_work.flag &= 4294967293u;
		obj_work.dir.z = gMS_GMK_SPCTPLT_WORK.ctplt_tilt;
		gMS_GMK_SPCTPLT_WORK.ply_work = null;
		gMS_GMK_SPCTPLT_WORK.ctplt_height = 319488;
		obj_work.ppFunc = gmGmkSpCtpltStay;
	}

	private static void gmGmkSpCtpltStay(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SPCTPLT_WORK gMS_GMK_SPCTPLT_WORK = (GMS_GMK_SPCTPLT_WORK)obj_work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (gMS_GMK_SPCTPLT_WORK.ply_work == gMS_PLAYER_WORK)
		{
			obj_work.ppFunc = gmGmkSpCtplt_PlayerHold;
			gmGmkSpCtplt_PlayerHold(obj_work);
		}
	}

	private static void gmGmkSpCtplt_PlayerHold(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SPCTPLT_WORK gMS_GMK_SPCTPLT_WORK = (GMS_GMK_SPCTPLT_WORK)obj_work;
		GMS_PLAYER_WORK ply_work = gMS_GMK_SPCTPLT_WORK.ply_work;
		if ((ply_work.player_flag & 0x400) != 0 || (g_gm_main_system.game_flag & 0x40200) != 0)
		{
			return;
		}
		if ((g_gm_main_system.game_flag & 0x1001000) == 0)
		{
			if ((ply_work.key_release & 0xA0) != 0)
			{
				int num = 0;
				int num2 = (319488 - gMS_GMK_SPCTPLT_WORK.ctplt_height) / 2;
				ply_work.obj_work.spd_m = num2;
				if (gMS_GMK_SPCTPLT_WORK.ctplt_tilt != 0)
				{
					num = (num2 = (int)(2896.3093 * (double)num2 / 4096.0));
					if (gMS_GMK_SPCTPLT_WORK.ctplt_tilt == 57344)
					{
						num = -num;
					}
				}
				else if (num2 < 8192)
				{
					num2 = 8192;
				}
				else if (num2 > 36864)
				{
					num2 = 36864 + 9 * num2 / 21;
				}
				ObjDrawObjectActionSet3DNNMaterial(obj_work, 1);
				obj_work.disp_flag &= 4294967291u;
				ObjDrawObjectActionSet(obj_work, 2);
				gMS_GMK_SPCTPLT_WORK.ctplt_height = 319488;
				ply_work.obj_work.dir.z = (ushort)(gMS_GMK_SPCTPLT_WORK.ctplt_tilt + 49152);
				GmPlySeqInitPinballCtplt(ply_work, num, -num2);
				GMM_PAD_VIB_SMALL();
				obj_work.ppFunc = gmGmkSpCtplt_PlayerHold_100;
				gMS_GMK_SPCTPLT_WORK.ctplt_return_timer = 4;
				gMS_GMK_SPCTPLT_WORK.ply_work = null;
				gmGmkSpCtpltSeStop(obj_work);
			}
			else if ((ply_work.key_on & 0xA0) != 0)
			{
				if (gMS_GMK_SPCTPLT_WORK.ctplt_height == 319488)
				{
					ObjDrawObjectActionSet3DNNMaterial(obj_work, 0);
					obj_work.disp_flag &= 4294967291u;
					ObjDrawObjectActionSet(obj_work, 1);
					gMS_GMK_SPCTPLT_WORK.se_handle = GsSoundAllocSeHandle();
					GmSoundPlaySE("Catapult1", gMS_GMK_SPCTPLT_WORK.se_handle);
				}
				if (gMS_GMK_SPCTPLT_WORK.ctplt_height > 147456)
				{
					gMS_GMK_SPCTPLT_WORK.ctplt_height -= 3018;
					if (gMS_GMK_SPCTPLT_WORK.ctplt_height < 147456)
					{
						gMS_GMK_SPCTPLT_WORK.ctplt_height = 147456;
					}
				}
			}
		}
		int num3;
		int num4;
		if (gMS_GMK_SPCTPLT_WORK.ctplt_tilt == 0)
		{
			num3 = 0;
			num4 = -gMS_GMK_SPCTPLT_WORK.ctplt_height;
		}
		else
		{
			num3 = (num4 = -(int)(2896.3093 * (double)gMS_GMK_SPCTPLT_WORK.ctplt_height / 4096.0));
			if (gMS_GMK_SPCTPLT_WORK.ctplt_tilt == 8192)
			{
				num3 = -num3;
			}
		}
		ply_work.obj_work.pos.x = obj_work.pos.x + num3;
		ply_work.obj_work.pos.y = obj_work.pos.y + num4;
	}

	private static void gmGmkSpCtplt_PlayerHold_100(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SPCTPLT_WORK gMS_GMK_SPCTPLT_WORK = (GMS_GMK_SPCTPLT_WORK)obj_work;
		gMS_GMK_SPCTPLT_WORK.ctplt_return_timer--;
		if (gMS_GMK_SPCTPLT_WORK.ctplt_return_timer <= 0)
		{
			obj_work.flag &= 4294967293u;
			obj_work.ppFunc = gmGmkSpCtpltStay;
			gmGmkSpCtpltStay(obj_work);
		}
	}

	private static void gmGmkSpCtplt_PlayerHit(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		OBS_OBJECT_WORK parent_obj = mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if ((gMS_PLAYER_WORK.player_flag & 0x400) == 0 && (gMS_PLAYER_WORK.obj_work.flag & 2) == 0 && (g_gm_main_system.game_flag & 0x40200) == 0 && gMS_PLAYER_WORK == g_gm_main_system.ply_work[0])
		{
			GMS_GMK_SPCTPLT_WORK gMS_GMK_SPCTPLT_WORK = (GMS_GMK_SPCTPLT_WORK)parent_obj;
			GmPlySeqInitPinballCtpltHold(gMS_PLAYER_WORK, gMS_GMK_SPCTPLT_WORK.gmk_work.ene_com);
			gMS_PLAYER_WORK.obj_work.flag |= 2u;
			parent_obj.flag |= 2u;
			gMS_GMK_SPCTPLT_WORK.ply_work = gMS_PLAYER_WORK;
		}
	}

