		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.disp_flag &= 4294967263u;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.move_flag &= 4294967167u;
		oBS_OBJECT_WORK.ppFunc = gmGmkBoss5TriggerMain;
		return oBS_OBJECT_WORK;
	}

	private static void gmGmkBoss5TriggerMain(OBS_OBJECT_WORK obj_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)g_gm_main_system.ply_work[0];
		if (oBS_OBJECT_WORK != null && oBS_OBJECT_WORK.pos.x >= obj_work.pos.x && gmGmkBoss5TriggerTryAnnounce())
		{
			obj_work.flag |= 4u;
		}
	}

	private static bool gmGmkBoss5TriggerTryAnnounce()
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, 2);
		while (oBS_OBJECT_WORK != null)
		{
			GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)oBS_OBJECT_WORK;
			if (gMS_ENEMY_COM_WORK.eve_rec != null && gMS_ENEMY_COM_WORK.eve_rec.id == 55)
			{
				break;
			}
		}
		if (oBS_OBJECT_WORK == null)
		{
			return false;
		}
		GMS_BOSS5_MGR_WORK mgr_work = (GMS_BOSS5_MGR_WORK)oBS_OBJECT_WORK;
		GmBoss5MgrAnnouncePassedTrigger(mgr_work);
		return true;
	}

	private static void GmBoss5MgrAnnouncePassedTrigger(GMS_BOSS5_MGR_WORK mgr_work)
	{
		mgr_work.flag |= 4194304u;
	}

