	private static void gmGmkBeltConveyor_ppOut(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_BELTC_WORK gMS_GMK_BELTC_WORK = (GMS_GMK_BELTC_WORK)obj_work;
		if (GmMainIsDrawEnable() && (obj_work.disp_flag & 0x20) == 0)
		{
			if (_tvx_roller == null)
			{
				_tvx_roller = new TVX_FILE((AmbChunk)amBindGet(gm_gmk_beltconv_obj_tvx_list, 0));
				_tvx_axis = new TVX_FILE((AmbChunk)amBindGet(gm_gmk_beltconv_obj_tvx_list, 1));
				_tvx_belt_up = new TVX_FILE((AmbChunk)amBindGet(gm_gmk_beltconv_obj_tvx_list, 2));
				_tvx_belt_down = new TVX_FILE((AmbChunk)amBindGet(gm_gmk_beltconv_obj_tvx_list, 3));
			}
			TVX_FILE tvx_roller = _tvx_roller;
			TVX_FILE tvx_axis = _tvx_axis;
			TVX_FILE tvx_belt_up = _tvx_belt_up;
			TVX_FILE tvx_belt_down = _tvx_belt_down;
			NNS_TEXLIST texlist = obj_work.obj_3d.texlist;
			short rotate_z = (short)(-obj_work.dir.z);
			VecFx32 pos = obj_work.pos;
			GmTvxSetModel(tvx_roller, texlist, ref pos, ref obj_work.scale, GMD_TVX_DISP_ROTATE, rotate_z);
			pos.z += 4096;
			GmTvxSetModel(tvx_axis, texlist, ref pos, ref obj_work.scale, 0u, 0);
			pos.x += gMS_GMK_BELTC_WORK.roller;
			GmTvxSetModel(tvx_axis, texlist, ref pos, ref obj_work.scale, 0u, 0);
			pos.z -= 4096;
			GmTvxSetModel(tvx_roller, texlist, ref pos, ref obj_work.scale, GMD_TVX_DISP_ROTATE, rotate_z);
			pos.x -= gMS_GMK_BELTC_WORK.roller;
			int num = ((gMS_GMK_BELTC_WORK.vect == 0) ? 262144 : (-262144));
			int num2 = gMS_GMK_BELTC_WORK.roller;
			GMS_TVX_EX_WORK ex_work = new GMS_TVX_EX_WORK
			{
				u_wrap = 1,
				v_wrap = 1,
				coord = 
				{
					v = 0f
				},
				color = 0u
			};
			pos.y += -65536;
			pos.z = -73728;
			if (gMS_GMK_BELTC_WORK.vect == 32768)
			{
				pos.x += num;
			}
			while (num2 != 0)
			{
				ex_work.coord.u = gMS_GMK_BELTC_WORK.tex_u;
				GmTvxSetModelEx(tvx_belt_up, texlist, ref pos, ref obj_work.scale, 0u, 0, ref ex_work);
				pos.y -= -131072;
				ex_work.coord.u = 0f - gMS_GMK_BELTC_WORK.tex_u;
				GmTvxSetModelEx(tvx_belt_down, texlist, ref pos, ref obj_work.scale, 0u, 0, ref ex_work);
				pos.y += -131072;
				pos.x += num;
				num2 -= num;
			}
		}
	}

	private static void gmGmkBeltConveyorStay(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_BELTC_WORK gMS_GMK_BELTC_WORK = (GMS_GMK_BELTC_WORK)obj_work;
		OBS_OBJECT_WORK obj_work2 = g_gm_main_system.ply_work[0].obj_work;
		bool flag = false;
		if (obj_work2.ride_obj == obj_work)
		{
			obj_work2.flow.x = gMS_GMK_BELTC_WORK.speed;
			flag = true;
		}
		if (gMS_GMK_BELTC_WORK.last_under && !flag && g_gm_main_system.ply_work[0].seq_state == 1 && (obj_work2.move_flag & 1) == 0 && ((gMS_GMK_BELTC_WORK.speed > 0 && obj_work2.spd_m < 0 && obj_work2.pos.x > obj_work.pos.x) || (gMS_GMK_BELTC_WORK.speed < 0 && obj_work2.spd_m > 0 && obj_work2.pos.x < obj_work.pos.x)))
		{
			obj_work2.spd_m = gMS_GMK_BELTC_WORK.speed;
		}
		gMS_GMK_BELTC_WORK.last_under = flag;
		gMS_GMK_BELTC_WORK.rolldir += gMS_GMK_BELTC_WORK.diradd;
		obj_work.dir.z = (ushort)(gMS_GMK_BELTC_WORK.rolldir >> 12);
		gMS_GMK_BELTC_WORK.tex_u -= (float)(gMS_GMK_BELTC_WORK.speed >> 12) / 128f;
		while (gMS_GMK_BELTC_WORK.tex_u >= 0.125f)
		{
			gMS_GMK_BELTC_WORK.tex_u -= 0.125f;
		}
		while (gMS_GMK_BELTC_WORK.tex_u <= -0.125f)
		{
			gMS_GMK_BELTC_WORK.tex_u += 0.125f;
		}
	}

	private static void gmGmkBeltConveyorStart(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_BELTC_WORK gMS_GMK_BELTC_WORK = (GMS_GMK_BELTC_WORK)obj_work;
		gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.obj = obj_work;
		gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.diff_data = g_gm_default_col;
		gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.flag |= 134217728u;
		gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.width = (ushort)gMS_GMK_BELTC_WORK.width;
		gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.ofst_x = (short)((gMS_GMK_BELTC_WORK.vect != 0) ? (-gMS_GMK_BELTC_WORK.width) : 0);
		gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.height = 8;
		gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.ofst_y = -16;
		if ((((GMS_ENEMY_COM_WORK)obj_work).eve_rec.flag & 0x10) != 0)
		{
			gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.width += 16;
			gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.ofst_x -= 16;
		}
		if ((((GMS_ENEMY_COM_WORK)obj_work).eve_rec.flag & 0x20) != 0)
		{
			gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.width += 16;
		}
		gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.dir = 0;
		gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.flag |= 32u;
		gMS_GMK_BELTC_WORK.gmk_work.ene_com.col_work.obj_col.attr = 1;
		gMS_GMK_BELTC_WORK.last_under = false;
		gMS_GMK_BELTC_WORK.tex_u = 0f;
		obj_work.ppFunc = gmGmkBeltConveyorStay;
	}

	private static void GmFadeSetFade(GMS_FADE_OBJ_WORK fade_obj, uint fade_set_type, byte start_col_r, byte start_col_g, byte start_col_b, byte start_col_a, byte end_col_r, byte end_col_g, byte end_col_b, byte end_col_a, float time, int draw_start, int conti_state)
	{
