	private static GMS_FADE_OBJ_WORK GmFadeCreateFadeObj(ushort prio, byte group, byte pause_level, TaskWorkFactoryDelegate work_size, ushort dt_prio, uint draw_state)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = OBM_OBJECT_TASK_DETAIL_INIT(prio, group, pause_level, 0, work_size, "FADE_OBJ");
		GMS_FADE_OBJ_WORK gMS_FADE_OBJ_WORK = (GMS_FADE_OBJ_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.obj_type = 7;
		oBS_OBJECT_WORK.flag |= 18u;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		gMS_FADE_OBJ_WORK.fade_work.dt_prio = dt_prio;
		gMS_FADE_OBJ_WORK.fade_work.draw_state = draw_state;
		gMS_FADE_OBJ_WORK.fade_work.time = 1f;
		gMS_FADE_OBJ_WORK.obj_work.ppOut = gmFadeDispFunc;
		return gMS_FADE_OBJ_WORK;
	}

	private static void gmFadeDispFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_FADE_OBJ_WORK gMS_FADE_OBJ_WORK = (GMS_FADE_OBJ_WORK)obj_work;
		if ((obj_work.disp_flag & 0x1010) == 0)
		{
			IzFadeUpdate(gMS_FADE_OBJ_WORK.fade_work);
		}
		if ((obj_work.disp_flag & 0x20) == 0)
		{
			IzFadeDraw(gMS_FADE_OBJ_WORK.fade_work);
		}
	}

