	public static OBS_OBJECT_WORK GmEneHaroInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		UNREFERENCED_PARAMETER(type);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENE_HARO_WORK(), "ENE_HARO");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_ENE_HARO_WORK gMS_ENE_HARO_WORK = (GMS_ENE_HARO_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_haro_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(689), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.z = 655360;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -11, -24, 11, 0);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -32, 19, 0);
		oBS_RECT_WORK.flag |= 4u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -32, 19, 0);
		oBS_RECT_WORK.flag &= 4294967291u;
		oBS_OBJECT_WORK.move_flag &= 4294967167u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		if ((eve_rec.flag & GMD_ENE_HARO_EVE_FLAG_RIGHT) == 0)
		{
			oBS_OBJECT_WORK.disp_flag |= 1u;
		}
		oBS_OBJECT_WORK.user_work = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left << 12));
		oBS_OBJECT_WORK.user_flag = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left + eve_rec.width << 12));
		gMS_ENE_HARO_WORK.spd_dec = GMD_ENE_HARO_MOVE_SPD_X / (GMD_ENE_HARO_TURN_FRAME / 2);
		gMS_ENE_HARO_WORK.spd_dec_dist = GMD_ENE_HARO_MOVE_SPD_X * (GMD_ENE_HARO_TURN_FRAME / 2) / 2;
		gMS_ENE_HARO_WORK.vec.x = 0;
		gMS_ENE_HARO_WORK.vec.y = FX_F32_TO_FX32(1.0);
		gMS_ENE_HARO_WORK.angle = 0;
		gMS_ENE_HARO_WORK.angle_add = 0;
		gMS_ENE_HARO_WORK.lighton = 0;
		GmEneUtilInitNodeMatrix(gMS_ENE_HARO_WORK.node_work, oBS_OBJECT_WORK, 16);
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmEneHaroExit);
		GmEneUtilGetNodeMatrix(gMS_ENE_HARO_WORK.node_work, 2);
		gmEneHaroWaitInit(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

	public static void gmEneHaroExit(MTS_TASK_TCB tcb)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(tcb);
		GMS_ENE_HARO_WORK gMS_ENE_HARO_WORK = (GMS_ENE_HARO_WORK)oBS_OBJECT_WORK;
		GmEneUtilExitNodeMatrix(gMS_ENE_HARO_WORK.node_work);
		GmEnemyDefaultExit(tcb);
	}

	public static int gmEneHaroGetLength2N(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
		{
			return int.MaxValue;
		}
		int x = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
		int x2 = gMS_PLAYER_WORK.obj_work.pos.y - obj_work.pos.y;
		float num = FX_FX32_TO_F32(x);
		float num2 = FX_FX32_TO_F32(x2);
		return (int)(num * num + num2 * num2);
	}

	public static int gmEneHaroIsPlayerLeft(GMS_ENE_HARO_WORK obj_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)g_gm_main_system.ply_work[0];
		if ((g_gm_main_system.ply_work[0].player_flag & 0x400) != 0)
		{
			return 1;
		}
		VecFx32 vecFx = new VecFx32
		{
			x = oBS_OBJECT_WORK.pos.x - obj_work.ene_3d_work.ene_com.obj_work.pos.x,
			y = oBS_OBJECT_WORK.pos.y - obj_work.ene_3d_work.ene_com.obj_work.pos.y
		};
		int num = FX_Mul(vecFx.x, obj_work.vec.y) - FX_Mul(vecFx.y, obj_work.vec.x);
		if (num > 0)
		{
			return 0;
		}
		return 1;
	}

	public static int gmEneHaroIsPlayerCenter(GMS_ENE_HARO_WORK obj_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)g_gm_main_system.ply_work[0];
		if ((g_gm_main_system.ply_work[0].player_flag & 0x400) != 0)
		{
			return 1;
		}
		VecFx32 vecFx = new VecFx32
		{
			x = oBS_OBJECT_WORK.pos.x - obj_work.ene_3d_work.ene_com.obj_work.pos.x,
			y = oBS_OBJECT_WORK.pos.y - obj_work.ene_3d_work.ene_com.obj_work.pos.y
		};
		int num = FX_Mul(vecFx.x, obj_work.vec.y) - FX_Mul(vecFx.y, obj_work.vec.x);
		if (num < FX_F32_TO_FX32(0.2f) && num > -FX_F32_TO_FX32(0.2f))
		{
			return 1;
		}
		return 0;
	}

	public static int gmEneHaroIsPlayerFront(GMS_ENE_HARO_WORK obj_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)g_gm_main_system.ply_work[0];
		if ((g_gm_main_system.ply_work[0].player_flag & 0x400) != 0)
		{
			return 1;
		}
		VecFx32 vecFx = new VecFx32
		{
			x = oBS_OBJECT_WORK.pos.x - obj_work.ene_3d_work.ene_com.obj_work.pos.x,
			y = oBS_OBJECT_WORK.pos.y - obj_work.ene_3d_work.ene_com.obj_work.pos.y
		};
		int num = FX_Mul(vecFx.x, obj_work.vec.x) + FX_Mul(vecFx.y, obj_work.vec.y);
		if (num > 0)
		{
			return 1;
		}
		return 0;
	}

	public static void gmEneHaroWaitInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_HARO_WORK gMS_ENE_HARO_WORK = (GMS_ENE_HARO_WORK)obj_work;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		ObjDrawObjectActionSet(obj_work, 0);
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneHaroWaitMain;
		obj_work.move_flag &= 4294967291u;
		int num = FX_Sqrt(FX_Mul(gMS_ENE_HARO_WORK.vec.x, gMS_ENE_HARO_WORK.vec.x) + FX_Mul(gMS_ENE_HARO_WORK.vec.y, gMS_ENE_HARO_WORK.vec.y));
		if (num == 0)
		{
			gMS_ENE_HARO_WORK.vec.x = 0;
			gMS_ENE_HARO_WORK.vec.y = FX_F32_TO_FX32(1f);
		}
		else
		{
			gMS_ENE_HARO_WORK.vec.x = FX_Div(gMS_ENE_HARO_WORK.vec.x, num);
			gMS_ENE_HARO_WORK.vec.y = FX_Div(gMS_ENE_HARO_WORK.vec.y, num);
		}
	}

	public static void gmEneHaroWaitMain(OBS_OBJECT_WORK obj_work)
	{
		if (gmEneHaroGetLength2N(obj_work) <= 10000)
		{
			GmSoundPlaySE("Halogen");
			obj_work.obj_3d.blend_spd = 0.05f;
			ObjDrawObjectActionSet3DNNBlend(obj_work, 1);
			obj_work.disp_flag |= 4u;
			obj_work.ppFunc = gmEneHaroWalkInit;
		}
	}

	public static void gmEneHaroWalkInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_HARO_WORK gMS_ENE_HARO_WORK = (GMS_ENE_HARO_WORK)obj_work;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneHaroWalkMain;
		obj_work.move_flag &= 4294967291u;
		int num = FX_Sqrt(FX_Mul(gMS_ENE_HARO_WORK.vec.x, gMS_ENE_HARO_WORK.vec.x) + FX_Mul(gMS_ENE_HARO_WORK.vec.y, gMS_ENE_HARO_WORK.vec.y));
		if (num == 0)
		{
			gMS_ENE_HARO_WORK.vec.x = 0;
			gMS_ENE_HARO_WORK.vec.y = FX_F32_TO_FX32(1f);
		}
		else
		{
			gMS_ENE_HARO_WORK.vec.x = FX_Div(gMS_ENE_HARO_WORK.vec.x, num);
			gMS_ENE_HARO_WORK.vec.y = FX_Div(gMS_ENE_HARO_WORK.vec.y, num);
		}
		gMS_ENE_HARO_WORK.timer = 120;
		if (gMS_ENE_HARO_WORK.lighton == 0)
		{
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctEneEsCreate(obj_work, 6);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = gmEneEffectMainFuncHarogen;
			gMS_ENE_HARO_WORK.lighton = 1;
		}
		if (gmEneHaroGetLength2N(obj_work) <= 10000)
		{
			GmSoundPlaySE("Halogen");
			ObjDrawObjectActionSet(obj_work, 1);
			obj_work.disp_flag |= 4u;
		}
		else
		{
			ObjDrawObjectActionSet(obj_work, 1);
			obj_work.disp_flag |= 4u;
		}
	}

	public static void gmEneHaroWalkMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_HARO_WORK gMS_ENE_HARO_WORK = (GMS_ENE_HARO_WORK)obj_work;
		if (gmEneHaroIsPlayerCenter(gMS_ENE_HARO_WORK) == 0)
		{
			if (gmEneHaroIsPlayerLeft(gMS_ENE_HARO_WORK) != 0)
			{
				gMS_ENE_HARO_WORK.angle_add -= AKM_DEGtoA32(0.03f);
				if (gMS_ENE_HARO_WORK.angle_add < -AKM_DEGtoA32(0.35f))
				{
					gMS_ENE_HARO_WORK.angle_add = -AKM_DEGtoA32(0.35f);
				}
				gMS_ENE_HARO_WORK.angle += gMS_ENE_HARO_WORK.angle_add;
			}
			else
			{
				gMS_ENE_HARO_WORK.angle_add += AKM_DEGtoA32(0.03f);
				if (gMS_ENE_HARO_WORK.angle_add > AKM_DEGtoA32(0.35f))
				{
					gMS_ENE_HARO_WORK.angle_add = AKM_DEGtoA32(0.35f);
				}
				gMS_ENE_HARO_WORK.angle += gMS_ENE_HARO_WORK.angle_add;
			}
			if (gMS_ENE_HARO_WORK.angle < -AKM_DEGtoA32(1.3f))
			{
				gMS_ENE_HARO_WORK.angle = -AKM_DEGtoA32(1.3f);
			}
			if (gMS_ENE_HARO_WORK.angle > AKM_DEGtoA32(1.3f))
			{
				gMS_ENE_HARO_WORK.angle = AKM_DEGtoA32(1.3f);
			}
		}
		int v = FX_Cos(gMS_ENE_HARO_WORK.angle);
		int num = FX_Sin(gMS_ENE_HARO_WORK.angle);
		gMS_ENE_HARO_WORK.vec.x = FX_Mul(gMS_ENE_HARO_WORK.vec.x, v) + FX_Mul(gMS_ENE_HARO_WORK.vec.y, num);
		gMS_ENE_HARO_WORK.vec.y = FX_Mul(gMS_ENE_HARO_WORK.vec.x, -num) + FX_Mul(gMS_ENE_HARO_WORK.vec.y, v);
		gMS_ENE_HARO_WORK.vvv.x = (int)((float)gMS_ENE_HARO_WORK.vvv.x * 0.96f);
		gMS_ENE_HARO_WORK.vvv.y = (int)((float)gMS_ENE_HARO_WORK.vvv.x * 0.96f);
		gMS_ENE_HARO_WORK.vvv.x += gMS_ENE_HARO_WORK.vec.x;
		gMS_ENE_HARO_WORK.vvv.y += gMS_ENE_HARO_WORK.vec.y;
		gMS_ENE_HARO_WORK.spd = FX_F32_TO_FX32(1.5f);
		obj_work.spd.x = FX_Mul(gMS_ENE_HARO_WORK.vec.x, gMS_ENE_HARO_WORK.spd);
		obj_work.spd.y = FX_Mul(gMS_ENE_HARO_WORK.vec.y, gMS_ENE_HARO_WORK.spd);
		obj_work.spd.x += FX_Mul(gMS_ENE_HARO_WORK.vvv.x, FX_F32_TO_FX32(0.025));
		obj_work.spd.y += FX_Mul(gMS_ENE_HARO_WORK.vvv.y, FX_F32_TO_FX32(0.025));
		if (gMS_ENE_HARO_WORK.timer > 0)
		{
			gMS_ENE_HARO_WORK.timer--;
		}
		else
		{
			obj_work.ppFunc = gmEneHaroWalkInit;
		}
		if (gMS_ENE_HARO_WORK.vec.x < 0)
		{
			obj_work.disp_flag &= 4294967294u;
			gMS_ENE_HARO_WORK.targetAngle = AKM_DEGtoA32(250);
		}
		else
		{
			obj_work.disp_flag &= 4294967294u;
			gMS_ENE_HARO_WORK.targetAngle = AKM_DEGtoA32(330);
		}
		if (obj_work.dir.y > gMS_ENE_HARO_WORK.targetAngle)
		{
			obj_work.dir.y -= (ushort)AKM_DEGtoA32(5);
		}
		if (obj_work.dir.y < gMS_ENE_HARO_WORK.targetAngle)
		{
			obj_work.dir.y += (ushort)AKM_DEGtoA32(5);
		}
	}

