	public static void gmEneEffectMainFuncHarogen(OBS_OBJECT_WORK obj_work)
	{
		NNS_MATRIX nNS_MATRIX = null;
		if (obj_work.parent_obj != null)
		{
			GMS_ENE_HARO_WORK gMS_ENE_HARO_WORK = (GMS_ENE_HARO_WORK)obj_work.parent_obj;
			nNS_MATRIX = GmEneUtilGetNodeMatrix(gMS_ENE_HARO_WORK.node_work, 2);
			if (nNS_MATRIX != null)
			{
				float num = nNS_MATRIX.M03 - FX_FX32_TO_F32(gMS_ENE_HARO_WORK.ene_3d_work.ene_com.obj_work.pos.x);
				float num2 = nNS_MATRIX.M13 + FX_FX32_TO_F32(gMS_ENE_HARO_WORK.ene_3d_work.ene_com.obj_work.pos.y);
				float num3 = nNS_MATRIX.M23 - FX_FX32_TO_F32(gMS_ENE_HARO_WORK.ene_3d_work.ene_com.obj_work.pos.z);
				num += FX_FX32_TO_F32(gMS_ENE_HARO_WORK.ene_3d_work.ene_com.obj_work.spd.x);
				num2 -= FX_FX32_TO_F32(gMS_ENE_HARO_WORK.ene_3d_work.ene_com.obj_work.spd.y);
				num3 += FX_FX32_TO_F32(gMS_ENE_HARO_WORK.ene_3d_work.ene_com.obj_work.spd.z);
				obj_work.parent_ofst.x = FX_F32_TO_FX32(num);
				obj_work.parent_ofst.y = -FX_F32_TO_FX32(num2 - 10f);
				obj_work.parent_ofst.z = FX_F32_TO_FX32(num3);
			}
		}
		else
		{
			obj_work.flag |= 4u;
		}
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.flag |= 4u;
		}
	}

