	public static void GmEfctEneBuildDataInit(int zone_no)
	{
		object texlist_buf = null;
		for (int i = 0; i < 13; i++)
		{
			gm_efct_ene_tex_reg_id_list[i] = -1;
			gm_efct_ene_model_reg_id_list[i] = -1;
		}
		gm_efct_ene_target_zone_no = zone_no;
		for (int j = 0; j < 13; j++)
		{
			GMS_EFCT_ENE_CREATE_PARAM gMS_EFCT_ENE_CREATE_PARAM = gm_efct_ene_create_param_tbl[j];
			int arc_dwork_no = gMS_EFCT_ENE_CREATE_PARAM.arc_dwork_no;
			if ((gMS_EFCT_ENE_CREATE_PARAM.stage_flag & GMM_EFCT_ENE_STAGE_FLAG(zone_no)) != 0)
			{
				OBS_DATA_WORK pWork = ObjDataGet(arc_dwork_no);
				AMS_AMB_HEADER amb = readAMBFile(ObjDataGetInc(pWork));
				int model_idx = gMS_EFCT_ENE_CREATE_PARAM.create_param.model_idx;
				int index = GMM_EFCT_ENE_MODEL_DW_NO(gMS_EFCT_ENE_CREATE_PARAM);
				int index2 = GMM_EFCT_ENE_OBJECT_DW_NO(gMS_EFCT_ENE_CREATE_PARAM);
				OBS_DATA_WORK oBS_DATA_WORK;
				OBS_DATA_WORK texlist_dwork;
				if (model_idx != -1)
				{
					ObjDataLoadAmbIndex(ObjDataGet(index), model_idx, amb);
					gm_efct_ene_model_reg_id_list[j] = ObjAction3dESModelLoadToDwork(ObjDataGet(index2), (AmbChunk)ObjDataGet(index).pData, 0u);
					oBS_DATA_WORK = ObjDataGet(GMM_EFCT_ENE_MDL_AMBTEX_DW_NO(gMS_EFCT_ENE_CREATE_PARAM));
					texlist_dwork = ObjDataGet(GMM_EFCT_ENE_MDL_TEXLIST_DW_NO(gMS_EFCT_ENE_CREATE_PARAM));
				}
				else
				{
					oBS_DATA_WORK = ObjDataGet(GMM_EFCT_ENE_AMBTEX_DW_NO(gMS_EFCT_ENE_CREATE_PARAM));
					texlist_dwork = ObjDataGet(GMM_EFCT_ENE_TEXLIST_DW_NO(gMS_EFCT_ENE_CREATE_PARAM));
				}
				ObjDataLoadAmbIndex(oBS_DATA_WORK, gMS_EFCT_ENE_CREATE_PARAM.ambtex_idx, amb);
				gm_efct_ene_tex_reg_id_list[j] = ObjAction3dESTextureLoadToDwork(texlist_dwork, readAMBFile(oBS_DATA_WORK.pData), ref texlist_buf);
			}
		}
	}

	public static bool GmEfctEneBuildDataLoop()
	{
		bool flag = true;
		if (gm_efct_ene_target_zone_no == -1)
		{
			return flag;
		}
		for (int i = 0; i < 13; i++)
		{
			GMS_EFCT_ENE_CREATE_PARAM gMS_EFCT_ENE_CREATE_PARAM = gm_efct_ene_create_param_tbl[i];
			if ((gMS_EFCT_ENE_CREATE_PARAM.stage_flag & GMM_EFCT_ENE_STAGE_FLAG(gm_efct_ene_target_zone_no)) == 0)
			{
				continue;
			}
			if (gm_efct_ene_tex_reg_id_list[i] != -1)
			{
				if (amDrawIsRegistComplete(gm_efct_ene_tex_reg_id_list[i]))
				{
					gm_efct_ene_tex_reg_id_list[i] = -1;
				}
				else
				{
					flag = false;
				}
			}
			if (gm_efct_ene_model_reg_id_list[i] != -1)
			{
				if (amDrawIsRegistComplete(gm_efct_ene_model_reg_id_list[i]))
				{
					gm_efct_ene_model_reg_id_list[i] = -1;
				}
				else
				{
					flag = false;
				}
			}
		}
		if (flag)
		{
			gm_efct_ene_target_zone_no = -1;
		}
		return flag;
	}

	public static void GmEfctEneFlushDataInit(int zone_no)
	{
		gm_efct_ene_target_zone_no = zone_no;
		for (int i = 0; i < 13; i++)
		{
			GMS_EFCT_ENE_CREATE_PARAM gMS_EFCT_ENE_CREATE_PARAM = gm_efct_ene_create_param_tbl[i];
			if ((gMS_EFCT_ENE_CREATE_PARAM.stage_flag & GMM_EFCT_ENE_STAGE_FLAG(zone_no)) != 0)
			{
				OBS_DATA_WORK pWork;
				OBS_DATA_WORK texlist_dwork;
				if (gMS_EFCT_ENE_CREATE_PARAM.create_param.model_idx != -1)
				{
					gm_efct_ene_model_reg_id_list[i] = ObjAction3dESModelReleaseDwork(ObjDataGet(GMM_EFCT_ENE_OBJECT_DW_NO(gMS_EFCT_ENE_CREATE_PARAM)));
					ObjDataRelease(ObjDataGet(GMM_EFCT_ENE_MODEL_DW_NO(gMS_EFCT_ENE_CREATE_PARAM)));
					pWork = ObjDataGet(GMM_EFCT_ENE_MDL_AMBTEX_DW_NO(gMS_EFCT_ENE_CREATE_PARAM));
					texlist_dwork = ObjDataGet(GMM_EFCT_ENE_MDL_TEXLIST_DW_NO(gMS_EFCT_ENE_CREATE_PARAM));
				}
				else
				{
					pWork = ObjDataGet(GMM_EFCT_ENE_AMBTEX_DW_NO(gMS_EFCT_ENE_CREATE_PARAM));
					texlist_dwork = ObjDataGet(GMM_EFCT_ENE_TEXLIST_DW_NO(gMS_EFCT_ENE_CREATE_PARAM));
				}
				gm_efct_ene_tex_reg_id_list[i] = ObjAction3dESTextureReleaseDwork(texlist_dwork);
				ObjDataRelease(pWork);
				ObjDataRelease(ObjDataGet(GMM_EFCT_ENE_ARC_DW_NO(gMS_EFCT_ENE_CREATE_PARAM)));
			}
		}
	}

	public static bool GmEfctEneFlushDataLoop()
	{
		bool flag = true;
		if (gm_efct_ene_target_zone_no == -1)
		{
			return flag;
		}
		for (int i = 0; i < 13; i++)
		{
			GMS_EFCT_ENE_CREATE_PARAM gMS_EFCT_ENE_CREATE_PARAM = gm_efct_ene_create_param_tbl[i];
			if ((gMS_EFCT_ENE_CREATE_PARAM.stage_flag & GMM_EFCT_ENE_STAGE_FLAG(gm_efct_ene_target_zone_no)) == 0)
			{
				continue;
			}
			OBS_DATA_WORK texlist_dwork = ((gMS_EFCT_ENE_CREATE_PARAM.create_param.model_idx == -1) ? ObjDataGet(GMM_EFCT_ENE_TEXLIST_DW_NO(gMS_EFCT_ENE_CREATE_PARAM)) : ObjDataGet(GMM_EFCT_ENE_MDL_TEXLIST_DW_NO(gMS_EFCT_ENE_CREATE_PARAM)));
			if (gm_efct_ene_model_reg_id_list[i] != -1)
			{
				if (ObjAction3dESModelReleaseDworkCheck(ObjDataGet(GMM_EFCT_ENE_OBJECT_DW_NO(gMS_EFCT_ENE_CREATE_PARAM)), gm_efct_ene_model_reg_id_list[i]))
				{
					gm_efct_ene_model_reg_id_list[i] = -1;
				}
				else
				{
					flag = false;
				}
			}
			if (gm_efct_ene_tex_reg_id_list[i] != -1)
			{
				if (ObjAction3dESTextureReleaseDworkCheck(texlist_dwork, gm_efct_ene_tex_reg_id_list[i]))
				{
					gm_efct_ene_tex_reg_id_list[i] = -1;
				}
				else
				{
					flag = false;
				}
			}
		}
		if (flag)
		{
			gm_efct_ene_target_zone_no = -1;
		}
		return flag;
	}

	public static GMS_EFFECT_3DES_WORK GmEfctEneEsCreate(OBS_OBJECT_WORK parent_obj, int efct_ene_idx)
	{
		GMS_EFCT_ENE_CREATE_PARAM gMS_EFCT_ENE_CREATE_PARAM = gm_efct_ene_create_param_tbl[efct_ene_idx];
		OBS_DATA_WORK model_dwork;
		OBS_DATA_WORK object_dwork;
		if (gMS_EFCT_ENE_CREATE_PARAM.create_param.model_idx != -1)
		{
			model_dwork = ObjDataGet(GMM_EFCT_ENE_MODEL_DW_NO(gMS_EFCT_ENE_CREATE_PARAM));
			object_dwork = ObjDataGet(GMM_EFCT_ENE_OBJECT_DW_NO(gMS_EFCT_ENE_CREATE_PARAM));
		}
		else
		{
			model_dwork = null;
			object_dwork = null;
		}
		return GmEffect3dESCreateByParam(gMS_EFCT_ENE_CREATE_PARAM.create_param, parent_obj, ObjDataGet(GMM_EFCT_ENE_ARC_DW_NO(gMS_EFCT_ENE_CREATE_PARAM)).pData, ObjDataGet(GMM_EFCT_ENE_AME_DW_NO(gMS_EFCT_ENE_CREATE_PARAM)), ObjDataGet(GMM_EFCT_ENE_AMBTEX_DW_NO(gMS_EFCT_ENE_CREATE_PARAM)), ObjDataGet(GMM_EFCT_ENE_TEXLIST_DW_NO(gMS_EFCT_ENE_CREATE_PARAM)), model_dwork, object_dwork);
	}

