	private static GMS_EFFECT_3DES_WORK GmBoss4EffCommonInit(int id, VecFx32? pos, OBS_OBJECT_WORK parent_obj, uint type, uint flag, GMS_BOSS4_NODE_MATRIX mtx, int link, VecFx32? rot, uint[] ctrl_flag, uint mask)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_BOSS4_EFF_COMMON_WORK(), parent_obj, 0, "B04_CapOver");
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = (GMS_EFFECT_3DES_WORK)oBS_OBJECT_WORK;
		GMS_BOSS4_EFF_COMMON_WORK gMS_BOSS4_EFF_COMMON_WORK = (GMS_BOSS4_EFF_COMMON_WORK)oBS_OBJECT_WORK;
		ObjObjectAction3dESEffectLoad(GMM_BS_OBJ(gMS_EFFECT_3DES_WORK), gMS_EFFECT_3DES_WORK.obj_3des, ObjDataGet(id), null, 0, null);
		ObjObjectAction3dESTextureLoad(GMM_BS_OBJ(gMS_EFFECT_3DES_WORK), gMS_EFFECT_3DES_WORK.obj_3des, ObjDataGet(733), null, 0, null, false);
		ObjObjectAction3dESTextureSetByDwork(oBS_OBJECT_WORK, ObjDataGet(734));
		GmEffect3DESSetupBase(gMS_EFFECT_3DES_WORK, type, flag);
		if (pos.HasValue)
		{
			VEC_Set(ref oBS_OBJECT_WORK.pos, pos.Value.x, pos.Value.y, pos.Value.z);
		}
		oBS_OBJECT_WORK.ppFunc = gmBoss4EffMainFuncFlagLink;
		oBS_OBJECT_WORK.flag |= 32u;
		gMS_BOSS4_EFF_COMMON_WORK.lookflag = ctrl_flag;
		gMS_BOSS4_EFF_COMMON_WORK.lookmask = mask;
		if (gMS_BOSS4_EFF_COMMON_WORK.lookflag != null)
		{
			gMS_BOSS4_EFF_COMMON_WORK.lookflag[0] |= gMS_BOSS4_EFF_COMMON_WORK.lookmask;
		}
		gMS_BOSS4_EFF_COMMON_WORK.link = -1;
		if (link >= 0)
		{
			gMS_BOSS4_EFF_COMMON_WORK.link = link;
			gMS_BOSS4_EFF_COMMON_WORK.node_work = mtx;
			if (rot.HasValue)
			{
				GmEffect3DESSetDispRotation(gMS_EFFECT_3DES_WORK, AKM_DEGtoA16(FX_FX32_TO_F32(rot.Value.x)), AKM_DEGtoA16(FX_FX32_TO_F32(rot.Value.y)), AKM_DEGtoA16(FX_FX32_TO_F32(rot.Value.z)));
			}
			if (pos.HasValue)
			{
				GmEffect3DESAddDispOffset(gMS_EFFECT_3DES_WORK, FX_FX32_TO_F32(pos.Value.x), FX_FX32_TO_F32(pos.Value.y), FX_FX32_TO_F32(pos.Value.z));
			}
		}
		return gMS_EFFECT_3DES_WORK;
	}

	private static void GmBoss4EffBombInitCreate(GMS_BOSS4_EFF_BOMB_WORK bomb_work, int bomb_type, OBS_OBJECT_WORK parent_obj, int pos_x, int pos_y, int width, int height, uint interval_min, uint interval_max)
	{
		MTM_ASSERT(bomb_work);
		MTM_ASSERT(parent_obj);
		bomb_work.parent_obj = parent_obj;
		bomb_work.bomb_type = bomb_type;
		bomb_work.interval_timer = 0u;
		bomb_work.interval_min = interval_min;
		bomb_work.interval_max = interval_max;
		bomb_work.pos[0] = pos_x;
		bomb_work.pos[1] = pos_y;
		bomb_work.area[0] = width;
		bomb_work.area[1] = height;
		bomb_work.interval_timer_sound = 0;
	}

	private static void GmBoss4EffBombUpdateCreate(GMS_BOSS4_EFF_BOMB_WORK bomb_work)
	{
		MTM_ASSERT(bomb_work.parent_obj);
		bomb_work.pos[0] += GmBoss4GetScrollOffset();
		if (bomb_work.interval_timer != 0)
		{
			bomb_work.interval_timer--;
			return;
		}
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = null;
		int num = bomb_work.area[0];
		int num2 = bomb_work.area[1];
		int num3 = FX_Mul(AkMathRandFx(), num);
		int num4 = FX_Mul(AkMathRandFx(), num2);
		switch (bomb_work.bomb_type)
		{
		case 0:
			gMS_EFFECT_3DES_WORK = GmEfctCmnEsCreate(null, 7);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = null;
			GmEffect3DESSetupBase(gMS_EFFECT_3DES_WORK, 2u, 1u);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = gmBoss4EffMainFuncDeleteAtEnd;
			if (--bomb_work.interval_timer_sound <= 0)
			{
				bomb_work.interval_timer_sound = 3;
				GmSoundPlaySE("Boss0_02");
			}
			break;
		case 5:
			gMS_EFFECT_3DES_WORK = GmBoss4EffCommonInit(743, null);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = null;
			GmEffect3DESSetupBase(gMS_EFFECT_3DES_WORK, 2u, 64u);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = gmBoss4EffMainFuncDeleteAtEnd;
			break;
		default:
			MTM_ASSERT(false);
			return;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(gMS_EFFECT_3DES_WORK);
		MTM_ASSERT(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.x = bomb_work.pos[0] - (num >> 1) + num3;
		oBS_OBJECT_WORK.pos.y = bomb_work.pos[1] - (num2 >> 1) + num4;
		oBS_OBJECT_WORK.pos.z = GMM_BS_OBJ(bomb_work.parent_obj).pos.z + 131072;
		uint num5 = (uint)(AkMathRandFx() * (bomb_work.interval_max - bomb_work.interval_max) >> 12);
		bomb_work.interval_timer = bomb_work.interval_min + num5;
	}

	private static void gmBoss4EffMainFuncFlagLink(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_EFF_COMMON_WORK gMS_BOSS4_EFF_COMMON_WORK = (GMS_BOSS4_EFF_COMMON_WORK)obj_work;
		obj_work.disp_flag &= 4294963199u;
		if ((g_obj.flag & 1) != 0)
		{
			obj_work.disp_flag |= 4096u;
		}
		else
		{
			obj_work.pos.x += GmBoss4GetScrollOffset();
		}
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.flag |= 4u;
			if (gMS_BOSS4_EFF_COMMON_WORK.lookflag != null)
			{
				gMS_BOSS4_EFF_COMMON_WORK.lookflag[0] &= ~gMS_BOSS4_EFF_COMMON_WORK.lookmask;
			}
		}
		if (gMS_BOSS4_EFF_COMMON_WORK.lookflag != null && (gMS_BOSS4_EFF_COMMON_WORK.lookflag[0] & gMS_BOSS4_EFF_COMMON_WORK.lookmask) == 0)
		{
			ObjDrawKillAction3DES(obj_work);
		}
		if (gMS_BOSS4_EFF_COMMON_WORK.link >= 0)
		{
			GmBsCmnUpdateObject3DESStuckWithNode(obj_work, gMS_BOSS4_EFF_COMMON_WORK.node_work.snm_work, gMS_BOSS4_EFF_COMMON_WORK.node_work.work[gMS_BOSS4_EFF_COMMON_WORK.link], 1);
		}
	}

	private static void gmBoss4EffMainFuncDeleteAtEnd(OBS_OBJECT_WORK obj_work)
	{
		obj_work.pos.x += GmBoss4GetScrollOffset();
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.flag |= 4u;
		}
	}

