	private MTS_TASK_TCB DmLogoComLoadFileCreate(Reference<MTS_TASK_TCB> load_tcb_addr)
	{
		MTS_TASK_TCB mTS_TASK_TCB = MTM_TASK_MAKE_TCB(null, dmLogoComDataLoadDest, 0u, ushort.MaxValue, 4096u, 0, () => new DMS_LOGO_COM_LOAD_WORK(), "DM_LC_LOAD");
		DMS_LOGO_COM_LOAD_WORK dMS_LOGO_COM_LOAD_WORK = (DMS_LOGO_COM_LOAD_WORK)mTS_TASK_TCB.work;
		load_tcb_addr.Target = mTS_TASK_TCB;
		dMS_LOGO_COM_LOAD_WORK.load_tcb_addr = load_tcb_addr;
		return mTS_TASK_TCB;
	}

	private void DmLogoComLoadFileReg(Reference<MTS_TASK_TCB> tcb, DMS_LOGO_COM_LOAD_FILE_INFO[] file_info, int file_num)
	{
		DMS_LOGO_COM_LOAD_WORK dMS_LOGO_COM_LOAD_WORK = (DMS_LOGO_COM_LOAD_WORK)tcb.Target.work;
		ArrayPointer<DMS_LOGO_COM_LOAD_CONTEXT> arrayPointer = new ArrayPointer<DMS_LOGO_COM_LOAD_CONTEXT>(dMS_LOGO_COM_LOAD_WORK.context, dMS_LOGO_COM_LOAD_WORK.context_num);
		int num = 0;
		while (num < file_num && dMS_LOGO_COM_LOAD_WORK.context_num < 10)
		{
			(~arrayPointer).no = dMS_LOGO_COM_LOAD_WORK.context_num;
			(~arrayPointer).file_info = file_info[num];
			DmLogoComLoadFile(arrayPointer);
			num++;
			dMS_LOGO_COM_LOAD_WORK.context_num++;
			++arrayPointer;
		}
	}

	private void DmLogoComLoadFileStart(Reference<MTS_TASK_TCB> tcb)
	{
		mtTaskChangeTcbProcedure(tcb.Target, dmLogoComDataLoadMain);
	}

	private DME_LOGO_COM_LOAD_STATE DmLogoComLoadFile(DMS_LOGO_COM_LOAD_CONTEXT context)
	{
		switch (context.state)
		{
		case DME_LOGO_COM_LOAD_STATE.DMD_LOGO_COM_LOAD_STATE_LOAD_WAIT:
			context.file_path_buf = context.file_info.file_path;
			context.fs_req = amFsReadBackground(context.file_path_buf);
			if (context.fs_req != null)
			{
				context.state = DME_LOGO_COM_LOAD_STATE.DMD_LOGO_COM_LOAD_STATE_LOADING;
			}
			break;
		case DME_LOGO_COM_LOAD_STATE.DMD_LOGO_COM_LOAD_STATE_LOADING:
			if (amFsIsComplete(context.fs_req))
			{
				if (context.file_info.post_func != null)
				{
					context.file_info.post_func(context);
				}
				amFsClearRequest(context.fs_req);
				context.fs_req = null;
				context.state = DME_LOGO_COM_LOAD_STATE.DMD_LOGO_COM_LOAD_STATE_COMPLETE;
			}
			break;
		}
		return context.state;
	}

	private void dmLogoComDataLoadMain(MTS_TASK_TCB tcb)
	{
		DMS_LOGO_COM_LOAD_WORK dMS_LOGO_COM_LOAD_WORK = (DMS_LOGO_COM_LOAD_WORK)tcb.work;
		ArrayPointer<DMS_LOGO_COM_LOAD_CONTEXT> arrayPointer = dMS_LOGO_COM_LOAD_WORK.context;
		int num = 0;
		while (num < dMS_LOGO_COM_LOAD_WORK.context_num)
		{
			DME_LOGO_COM_LOAD_STATE dME_LOGO_COM_LOAD_STATE = DmLogoComLoadFile(arrayPointer);
			if (dME_LOGO_COM_LOAD_STATE != DME_LOGO_COM_LOAD_STATE.DMD_LOGO_COM_LOAD_STATE_COMPLETE)
			{
				return;
			}
			num++;
			++arrayPointer;
		}
		mtTaskClearTcb(tcb);
	}

	private void dmLogoComDataLoadDest(MTS_TASK_TCB tcb)
	{
		DMS_LOGO_COM_LOAD_WORK dMS_LOGO_COM_LOAD_WORK = (DMS_LOGO_COM_LOAD_WORK)tcb.work;
		if (dMS_LOGO_COM_LOAD_WORK.load_tcb_addr != null && dMS_LOGO_COM_LOAD_WORK.load_tcb_addr.Target == tcb)
		{
			dMS_LOGO_COM_LOAD_WORK.load_tcb_addr.Target = null;
		}
	}

