	private static bool _FillBGMCache(int iListIndex)
	{
		string[] array = bgmLists[iListIndex];
		for (int i = 0; i < array.Length; i++)
		{
			SOUND_TABLE sOUND_TABLE = sound_bgm_list[array[i]];
			Song value = Sonic4Ep1.pInstance.GameContent.Load<Song>("SOUND/" + sOUND_TABLE.filename[0]);
			bgmPreloadedList.Add(sOUND_TABLE.filename[0], value);
		}
		return true;
	}

	private static Song _GetPreloadedBGM(string sName)
	{
		Song value;
		if (!bgmPreloadedList.TryGetValue(sName, out value))
		{
			return null;
		}
		return value;
	}

	public static bool PrepareBGMForLevel(int iLevel)
	{
		if (m_iBGMPreparedLevel == iLevel)
		{
			return true;
		}
		bgmPreloadedList.Clear();
		_FillBGMCache(0);
		int num = 0;
		if (iLevel >= 0 && iLevel <= 3)
		{
			num = 1;
		}
		else if (iLevel >= 4 && iLevel <= 7)
		{
			num = 2;
		}
		else if (iLevel >= 8 && iLevel <= 11)
		{
			num = 3;
		}
		else if (iLevel >= 12 && iLevel <= 15)
		{
			num = 4;
		}
		if (num != 0)
		{
			_FillBGMCache(num);
		}
		m_iBGMPreparedLevel = iLevel;
		return true;
	}

