	private static void fillSoundTable(string filename, Dictionary<string, SOUND_TABLE> list)
	{
		using (Stream stream = GameData.OpenStream("Content\\SOUND\\" + filename))
		{
			using (StreamReader streamReader = new StreamReader(stream))
			{
				while (streamReader.Peek() >= 0)
				{
					string text = streamReader.ReadLine();
					string[] array = text.Split('|');
					int count = array.Length;
					SOUND_TABLE sOUND_TABLE = new SOUND_TABLE(count);
					for (int i = 0; i < array.Length; i++)
					{
						int num = array[i].IndexOf("Aisac");
						string text2 = "";
						if (num != -1)
						{
							text2 = array[i].Substring(num);
							array[i] = array[i].Substring(0, num - 1);
							string[] array2 = text2.Split('#');
							sOUND_TABLE.asiac[i] = new AISAC_LIST(array2.Length - 1);
							for (int j = 1; j < array2.Length; j++)
							{
								string[] array3 = null;
								if (array2[j].StartsWith("Volume"))
								{
									sOUND_TABLE.asiac[i].types[j - 1] = 0;
									array3 = array2[j].Substring(7).Split(' ');
								}
								else if (array2[j].StartsWith("Pitch"))
								{
									sOUND_TABLE.asiac[i].types[j - 1] = 1;
									array3 = array2[j].Substring(6).Split(' ');
								}
								sOUND_TABLE.asiac[i].values[j - 1] = new float[array3.Length][];
								for (int k = 0; k < array3.Length; k++)
								{
									string[] array4 = array3[k].Split(',');
									sOUND_TABLE.asiac[i].values[j - 1][k] = new float[2];
									sOUND_TABLE.asiac[i].values[j - 1][k][0] = float.Parse(array4[0], CultureInfo.InvariantCulture);
									sOUND_TABLE.asiac[i].values[j - 1][k][1] = ((sOUND_TABLE.asiac[i].types[j - 1] == 1) ? (float.Parse(array4[1], CultureInfo.InvariantCulture) / 1000f) : float.Parse(array4[1], CultureInfo.InvariantCulture));
								}
							}
						}
						string[] array5 = array[i].Split(',');
						if (i == 0)
						{
							sOUND_TABLE.name = array5[0];
							sOUND_TABLE.cue = int.Parse(array5[1]);
							sOUND_TABLE.uid = array5[2];
						}
						sOUND_TABLE.volume[i] = float.Parse(array5[(i == 0) ? 3 : 0], CultureInfo.InvariantCulture);
						if (sOUND_TABLE.volume[i] > 1f)
						{
							sOUND_TABLE.volume[i] = 1f;
						}
						else if (sOUND_TABLE.volume[i] < -1f)
						{
							sOUND_TABLE.volume[i] = -1f;
						}
						sOUND_TABLE.pitch[i] = (float)int.Parse(array5[(i != 0) ? 1 : 4]) / 1000f;
						sOUND_TABLE.filename[i] = array5[(i == 0) ? 5 : 2];
						sOUND_TABLE.loop[i] = int.Parse(array5[(i == 0) ? 6 : 3]) == 1;
						sOUND_TABLE.loopStart[i] = int.Parse(array5[(i == 0) ? 7 : 4]);
						sOUND_TABLE.loopEnd[i] = int.Parse(array5[(i == 0) ? 8 : 5]);
					}
					list[sOUND_TABLE.name] = sOUND_TABLE;
				}
			}
		}
	}

	public static void MediaPlayer_MediaStateChanged(object sender, EventArgs e)
	{
		if (g_ao_sys_global.is_playing_device_bgm_music)
		{
			return;
		}
		MediaState state = MediaPlayer.State;
		AMS_CRIAUDIO_INTERFACE aMS_CRIAUDIO_INTERFACE = amCriAudioGetGlobal();
		string text = ((MediaPlayer.Queue.ActiveSong != null) ? MediaPlayer.Queue.ActiveSong.Name : null);
		for (int i = 0; i < aMS_CRIAUDIO_INTERFACE.auply.Length; i++)
		{
			if (text == null || aMS_CRIAUDIO_INTERFACE.auply[i].se_name == null || aMS_CRIAUDIO_INTERFACE.auply[i].se_name == null || !(text == "Sound\\" + sound_bgm_list[aMS_CRIAUDIO_INTERFACE.auply[i].se_name].filename[0]))
			{
				continue;
			}
			double totalMilliseconds = CriAuPlayer.m_songBGM.Duration.TotalMilliseconds;
			double totalMilliseconds2 = MediaPlayer.PlayPosition.TotalMilliseconds;
			if (state == MediaState.Paused && aMS_CRIAUDIO_INTERFACE.auply[i].m_stGMState != MediaState.Paused)
			{
				if (totalMilliseconds2 + 1.0 >= totalMilliseconds || totalMilliseconds2 == 0.0)
				{
					if (!aMS_CRIAUDIO_INTERFACE.auply[i].m_bLoop && aMS_CRIAUDIO_INTERFACE.auply[i].se_name.IndexOf("_speedup") != -1)
					{
						string cue = aMS_CRIAUDIO_INTERFACE.auply[i].se_name.Replace("_speedup", "");
						aMS_CRIAUDIO_INTERFACE.auply[i].SetCue(cue);
						aMS_CRIAUDIO_INTERFACE.auply[i].Play();
					}
					else
					{
						aMS_CRIAUDIO_INTERFACE.auply[i].m_stGMState = MediaState.Stopped;
						aMS_CRIAUDIO_INTERFACE.auply[i].status = 3;
					}
				}
				else if (aMS_CRIAUDIO_INTERFACE.auply[i].m_stGMState == MediaState.Playing)
				{
					MediaPlayer.Resume();
				}
			}
			else if (state == MediaState.Stopped && aMS_CRIAUDIO_INTERFACE.auply[i].m_stGMState != MediaState.Stopped)
			{
				if (totalMilliseconds2 == 0.0 && !aMS_CRIAUDIO_INTERFACE.auply[i].m_bLoop && aMS_CRIAUDIO_INTERFACE.auply[i].se_name.IndexOf("_speedup") != -1)
				{
					string cue2 = aMS_CRIAUDIO_INTERFACE.auply[i].se_name.Replace("_speedup", "");
					aMS_CRIAUDIO_INTERFACE.auply[i].SetCue(cue2);
					aMS_CRIAUDIO_INTERFACE.auply[i].Play();
				}
				else
				{
					aMS_CRIAUDIO_INTERFACE.auply[i].m_stGMState = state;
					aMS_CRIAUDIO_INTERFACE.auply[i].status = 3;
				}
			}
			break;
		}
	}

	private static void GsSoundInit()
	{
		MediaPlayer.MediaStateChanged += MediaPlayer_MediaStateChanged;
		if (sound_fx_list == null)
		{
			sound_fx_list = new Dictionary<string, SOUND_TABLE>(130);
			fillSoundTable("SND_FX.inf", sound_fx_list);
		}
		if (sound_bgm_list == null)
		{
			sound_bgm_list = new Dictionary<string, SOUND_TABLE>(50);
			fillSoundTable("SND_BGM.inf", sound_bgm_list);
		}
		LoadPrioritySoundsIntoCache();
		GC.Collect();
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		gsSoundInitSystemMainInfo();
		gsSoundInitSndScbHeap();
		gsSoundInitSeHandleHeap();
		int vol_bgm;
		int vol_se;
		GetSavedSoundVolumes(out vol_bgm, out vol_se);
		gSS_MAIN_SYS_INFO.bgm_volume = (float)vol_bgm / 10f;
		gSS_MAIN_SYS_INFO.se_volume = (float)vol_se / 10f;
		for (int i = 0; i < 2; i++)
		{
			GsSoundSetVolume(i, 1f);
		}
	}

	private static void GetSavedSoundVolumes(out int vol_bgm, out int vol_se)
	{
		vol_bgm = 10;
		vol_se = 10;
		try
		{
			using (IsolatedStorageFileStream isolatedStorageFileStream = store.OpenFile(g_ao_storage_filename, FileMode.Open))
			{
				isolatedStorageFileStream.Seek(72L, SeekOrigin.Begin);
				BinaryReader binaryReader = new BinaryReader(isolatedStorageFileStream);
				vol_bgm = binaryReader.ReadInt32();
				vol_se = binaryReader.ReadInt32();
			}
		}
		catch (Exception)
		{
		}
	}

	private static void GsSoundHalt()
	{
		amCriAudioGetGlobal();
		for (int i = 0; i < 8; i++)
		{
			if ((gs_sound_scb_heap[i].flag & 1) != 0)
			{
				GsSoundStopBgm(gs_sound_scb_heap[i]);
			}
		}
	}

	private static void LoadSFX(SOUND_TABLE tbl)
	{
		try
		{
			for (int i = 0; i < tbl.count; i++)
			{
				byte[] byteArray = null;
				int channels = 0;
				int sampleRate = 0;
				CriAuPlayer.LoadSound(tbl.filename[i], tbl.loop[i], ref tbl.loopStart[i], ref tbl.loopEnd[i], out byteArray, ref sampleRate, ref channels, false);
			}
		}
		catch (FileNotFoundException ex)
		{
			string text = ex.ToString();
			text += text;
			mppSoundNotImplAssert();
		}
	}

	private static void LoadPrioritySoundsIntoCache()
	{
		if (!b_bPrioritySoundsLoaded)
		{
			LoadSFX(sound_fx_list["Sega_Logo"]);
			LoadSFX(sound_fx_list["Ok"]);
			LoadSFX(sound_fx_list["Window"]);
			LoadSFX(sound_fx_list["Cancel"]);
			LoadSFX(sound_fx_list["Cursol"]);
			b_bPrioritySoundsLoaded = true;
		}
	}

	private static bool SoundPartialCache(int iPercent)
	{
		if (g_bSoundsPrecached)
		{
			return true;
		}
		int count = sound_fx_list.Count;
		int num = Math.Min(Math.Max(count * iPercent / 100, 1), count - g_iCurrentCachedIndex);
		for (int i = g_iCurrentCachedIndex; i < g_iCurrentCachedIndex + num; i++)
		{
			LoadSFX(sound_fx_list.ElementAt(i).Value);
		}
		g_iCurrentCachedIndex += num;
		g_bSoundsPrecached = g_iCurrentCachedIndex == count;
		return g_bSoundsPrecached;
	}

	private static void GsSoundReset()
	{
		for (int i = 0; i < 2; i++)
		{
			GsSoundSetVolume(i, 1f);
		}
		gsSoundResetSeHandleHeap();
		gsSoundResetSndScbHeap();
		gsSoundResetSystemMainInfo();
	}

	private static void GsSoundExit()
	{
		for (int i = 0; i < 2; i++)
		{
			GsSoundSetVolume(i, 0f);
		}
		GsSoundHalt();
		GsSoundEnd();
		gsSoundClearSeHandleHeap();
		gsSoundResetSndScbHeap();
		gsSoundClearSystemMainInfo();
	}

