	private static void GsSoundPlayBgm(GSS_SND_SCB scb, string bgm_name, int fade_frame)
	{
		scb.cur_pause_level = 0u;
		if (scb.snd_data_type == 1 || g_ao_sys_global.is_playing_device_bgm_music)
		{
			return;
		}
		gsSoundCriStrmStop(scb, 0);
		AMS_CRIAUDIO_INTERFACE aMS_CRIAUDIO_INTERFACE = amCriAudioGetGlobal();
		CriAuPlayer criAuPlayer = aMS_CRIAUDIO_INTERFACE.auply[scb.auply_no];
		if (criAuPlayer != null)
		{
			criAuPlayer.ReleaseCue();
			criAuPlayer.ResetParameters();
		}
		for (int i = 0; i < aMS_CRIAUDIO_INTERFACE.auply.Length; i++)
		{
			if (aMS_CRIAUDIO_INTERFACE.auply[i].se_name == bgm_name)
			{
				aMS_CRIAUDIO_INTERFACE.auply[i].ReleaseCue();
				aMS_CRIAUDIO_INTERFACE.auply[i].ResetParameters();
				break;
			}
		}
		amCriAudioStrmPlay((uint)scb.auply_no, bgm_name);
		gsSoundCriStrmSetFadeIn(scb, fade_frame);
		gsSoundUpdateVolume();
		criAuPlayer.Update();
	}

