			if ((gs_sound_scb_heap_usage_flag[i >> 3] & (1 << (i & 7))) == 0)
			{
				gs_sound_scb_heap_usage_flag[i >> 3] |= (byte)(1 << (i & 7));
				gsSoundInitSndScb(gs_sound_scb_heap[i], i, snd_data_type);
