	private static void gsSoundProcMain(MTS_TASK_TCB tcb)
	{
		amCriAudioGetGlobal();
		gsSoundUpdateSystemSuspendWait();
		gsSoundUpdateSystemControlVolume();
		for (int i = 0; i < 8; i++)
		{
			if ((gs_sound_scb_heap[i].flag & 1) != 0)
			{
				gsSoundUpdateSndScb(gs_sound_scb_heap[i]);
			}
		}
		for (int j = 0; j < 16; j++)
		{
			GSS_SND_SE_HANDLE gSS_SND_SE_HANDLE = gs_sound_se_handle_heap[j];
			if ((gSS_SND_SE_HANDLE.flag & 1) != 0)
			{
				gsSoundUpdateSndSeHandle(gSS_SND_SE_HANDLE);
			}
		}
		if ((gs_sound_se_handle_error.flag & 1) != 0)
		{
			gsSoundUpdateSndSeHandle(gs_sound_se_handle_error);
		}
		gsSoundUpdateVolume();
		for (int k = 0; k < 16; k++)
		{
			GSS_SND_SE_HANDLE gSS_SND_SE_HANDLE2 = gs_sound_se_handle_heap[k];
			if ((gSS_SND_SE_HANDLE2.flag & 1) != 0)
			{
				switch (gSS_SND_SE_HANDLE2.au_player.GetStatus())
				{
				case 4:
					gSS_SND_SE_HANDLE2.au_player.Stop();
					goto case 0;
				case 0:
				case 3:
					if ((gSS_SND_SE_HANDLE2.flag & 0x10) != 0)
					{
						GsSoundFreeSeHandle(gSS_SND_SE_HANDLE2);
					}
					else if ((gSS_SND_SE_HANDLE2.flag & 2) != 0 && (gSS_SND_SE_HANDLE2.flag & 0x80000000u) == 0)
					{
						gsSoundClearSeHandle(gSS_SND_SE_HANDLE2);
					}
					break;
				default:
					gSS_SND_SE_HANDLE2.au_player.Update();
					break;
				}
			}
			else if ((gSS_SND_SE_HANDLE2.flag & 0x10) != 0)
			{
				GsSoundFreeSeHandle(gSS_SND_SE_HANDLE2);
			}
		}
		if ((gs_sound_se_handle_error.flag & 1) != 0)
		{
			switch (gs_sound_se_handle_error.au_player.GetStatus())
			{
			case 4:
				gs_sound_se_handle_error.au_player.Stop();
				goto case 0;
			case 0:
			case 3:
				if ((gs_sound_se_handle_error.flag & 0x10) != 0)
				{
					GsSoundFreeSeHandle(gs_sound_se_handle_error);
				}
				else if ((gs_sound_se_handle_error.flag & 2) != 0)
				{
					gsSoundClearSeHandle(gs_sound_se_handle_error);
				}
				break;
			default:
				gs_sound_se_handle_error.au_player.Update();
				break;
			}
		}
		else if ((gs_sound_se_handle_error.flag & 0x10) != 0)
		{
			GsSoundFreeSeHandle(gs_sound_se_handle_error);
		}
		for (int l = 0; l < 8; l++)
		{
			if ((gs_sound_scb_heap[l].flag & 1) != 0)
			{
				gsSoundUpdateSndScbStatus(gs_sound_scb_heap[l]);
			}
		}
		for (int m = 0; m < 16; m++)
		{
			if ((gs_sound_se_handle_heap[m].flag & 1) != 0)
			{
				gsSoundUpdateSeHandleStatus(gs_sound_se_handle_heap[m]);
			}
		}
		if ((gs_sound_se_handle_error.flag & 1) != 0)
		{
			gsSoundUpdateSeHandleStatus(gs_sound_se_handle_error);
		}
	}

