	public static void nnSetClipPlane()
	{
		if (nngProjectionType != 1)
		{
			float num = 1f / nngProjectionMatrix.M00;
			float num2 = 1f / nngProjectionMatrix.M11;
			float num3 = num2 * (nngProjectionMatrix.M12 - nngClip3d.y0 / nngScreen.cy);
			float num4 = nnSqrt(num3 * num3 + 1f);
			float nz = num3 / num4;
			float ny = 1f / num4;
			nngClipPlane.Top.ny = ny;
			nngClipPlane.Top.nz = nz;
			num3 = num2 * (nngProjectionMatrix.M12 - nngClip3d.y1 / nngScreen.cy);
			num4 = nnSqrt(num3 * num3 + 1f);
			nz = num3 / num4;
			ny = 1f / num4;
			nngClipPlane.Bottom.ny = 0f - ny;
			nngClipPlane.Bottom.nz = 0f - nz;
			num3 = num * (nngProjectionMatrix.M02 + nngClip3d.x1 / nngScreen.cx);
			num4 = nnSqrt(num3 * num3 + 1f);
			nz = num3 / num4;
			ny = 1f / num4;
			nngClipPlane.Right.nx = ny;
			nngClipPlane.Right.nz = nz;
			num3 = num * (nngProjectionMatrix.M02 + nngClip3d.x0 / nngScreen.cx);
			num4 = nnSqrt(num3 * num3 + 1f);
			nz = num3 / num4;
			ny = 1f / num4;
			nngClipPlane.Left.nx = 0f - ny;
			nngClipPlane.Left.nz = 0f - nz;
		}
		else
		{
			float num5 = 2f / nngProjectionMatrix.M11 / 2f;
			float ofs = 0f - nngProjectionMatrix.M13 / nngProjectionMatrix.M11;
			nngClipPlane.Top.mul = num5 * (nngClip3d.y0 / (0f - nngScreen.cy));
			nngClipPlane.Top.ofs = ofs;
			nngClipPlane.Bottom.mul = (0f - num5) * (nngClip3d.y1 / nngScreen.cy);
			nngClipPlane.Bottom.ofs = ofs;
			num5 = 2f / nngProjectionMatrix.M00 / 2f;
			ofs = 0f - nngProjectionMatrix.M03 / nngProjectionMatrix.M00;
			nngClipPlane.Right.mul = num5 * (nngClip3d.x0 / (0f - nngScreen.cx));
			nngClipPlane.Right.ofs = ofs;
			nngClipPlane.Left.mul = (0f - num5) * (nngClip3d.x1 / nngScreen.cx);
			nngClipPlane.Left.ofs = ofs;
		}
	}

