	private static void nnInvertTransposeMatrix33(NNS_MATRIX dst, NNS_MATRIX src)
	{
		float m = src.M00;
		float m2 = src.M01;
		float m3 = src.M02;
		float m4 = src.M10;
		float m5 = src.M11;
		float m6 = src.M12;
		float m7 = src.M20;
		float m8 = src.M21;
		float m9 = src.M22;
		float num = m5 * m9 - m6 * m8;
		float num2 = m6 * m7 - m4 * m9;
		float num3 = m4 * m8 - m5 * m7;
		float num4 = m * num + m2 * num2 + m3 * num3;
		if (num4 == 0f)
		{
			dst.M00 = 0f;
			dst.M01 = 0f;
			dst.M02 = 0f;
			dst.M10 = 0f;
			dst.M11 = 0f;
			dst.M12 = 0f;
			dst.M20 = 0f;
			dst.M21 = 0f;
			dst.M22 = 0f;
		}
		else
		{
			float num5 = 1f / num4;
			dst.M00 = num * num5;
			dst.M10 = (0f - (m2 * m9 - m8 * m3)) * num5;
			dst.M20 = (m2 * m6 - m5 * m3) * num5;
			dst.M01 = num2 * num5;
			dst.M11 = (m * m9 - m7 * m3) * num5;
			dst.M21 = (0f - (m * m6 - m4 * m3)) * num5;
			dst.M02 = num3 * num5;
			dst.M12 = (0f - (m * m8 - m7 * m2)) * num5;
			dst.M22 = (m * m5 - m4 * m2) * num5;
		}
	}

	private static void nnInvertTransposeMatrix33NotNormalized(NNS_MATRIX dst, NNS_MATRIX src)
	{
		float m = src.M00;
		float m2 = src.M01;
		float m3 = src.M02;
		float m4 = src.M10;
		float m5 = src.M11;
		float m6 = src.M12;
		float m7 = src.M20;
		float m8 = src.M21;
		float m9 = src.M22;
		dst.M00 = m5 * m9 - m8 * m6;
		dst.M10 = 0f - (m2 * m9 - m8 * m3);
		dst.M20 = m2 * m6 - m5 * m3;
		dst.M01 = 0f - (m4 * m9 - m7 * m6);
		dst.M11 = m * m9 - m7 * m3;
		dst.M21 = 0f - (m * m6 - m4 * m3);
		dst.M02 = m4 * m8 - m7 * m5;
		dst.M12 = 0f - (m * m8 - m7 * m2);
		dst.M22 = m * m5 - m4 * m2;
	}

