	}

	private static void nnPutMaterialTexturesGLES11(NNS_DRAWCALLBACK_VAL val, NNS_MATERIAL_GLES11_TEXMAP_DESC[] texdesc, int num)
	{
		int max_texture_units = nngGLExtensions.max_texture_units;
		int i = 0;
		for (int j = 0; j < num; j++)
		{
			NNS_MATERIAL_GLES11_TEXMAP_DESC pTex = texdesc[j];
			nnPutMaterialTextureOneGLES11(i, val, ref pTex);
			i++;
			if (i >= max_texture_units)
			{
				return;
			}
		}
		for (; i < max_texture_units; i++)
		{
			nnSetTextureNum(i, -1);
			nnSetTexCoordSrc(i, 0);
		}
	}

