	private static int nnPutMaterialCore(NNS_DRAWCALLBACK_VAL val)
	{
		NNS_MATERIALPTR pMaterial = val.pMaterial;
		if ((val.DrawFlag & 0x7300) != 0)
		{
			nnPutDisableTexturesGL();
			if ((val.DrawFlag & 0x300) != 0)
			{
				nnPutFixedMaterialGL();
				return 1;
			}
			if ((val.DrawFlag & 0x7000) != 0)
			{
				nnPutFixedMaterialGL();
				switch (val.DrawFlag & 0x60)
				{
				case 32u:
					OpenGL.glDisable(2884u);
					break;
				case 64u:
					OpenGL.glEnable(2884u);
					OpenGL.glCullFace(1028u);
					break;
				case 96u:
					OpenGL.glEnable(2884u);
					OpenGL.glCullFace(1029u);
					break;
				default:
					if ((((NNS_MATERIAL_DESC)pMaterial.pMaterial).fFlag & 1) != 0)
					{
						OpenGL.glDisable(2884u);
						break;
					}
					OpenGL.glEnable(2884u);
					OpenGL.glCullFace(1029u);
					break;
				}
				switch (val.DrawFlag & 0x7000)
				{
				case 4096u:
					nnPutWireColor();
					break;
				case 16384u:
					nnPutColorMeshset(val.iMeshset, val.iSubobject);
					break;
				case 20480u:
					nnPutColorMaterial(val.iMaterial);
					break;
				case 24576u:
					nnPutColorNWeight(val.pVtxListPtr);
					break;
				case 8192u:
					if ((pMaterial.fType & 8) != 0)
					{
						NNS_MATERIAL_GLES11_DESC nNS_MATERIAL_GLES11_DESC = (NNS_MATERIAL_GLES11_DESC)pMaterial.pMaterial;
						nnPutColorNTexture(nNS_MATERIAL_GLES11_DESC.nTex);
					}
					else
					{
						nnPutColorNTexture(0);
					}
					break;
				}
				return 1;
			}
		}
		if (val.iPrevMaterial == -1 || val.bModified != 0)
		{
			nnInitPreviousMaterialValueGL();
		}
		else if (val.iMaterial == val.iPrevMaterial)
		{
			return 1;
		}
		if ((pMaterial.fType & 8) != 0)
		{
			NNS_MATERIAL_GLES11_DESC nNS_MATERIAL_GLES11_DESC2 = (NNS_MATERIAL_GLES11_DESC)pMaterial.pMaterial;
			uint fFlag = nNS_MATERIAL_GLES11_DESC2.fFlag;
			if (fFlag != nnmaterialcore.nngPreMatFlag)
			{
				nnPutMaterialFlagGL(val, fFlag);
			}
			if (nNS_MATERIAL_GLES11_DESC2.pColor != nnmaterialcore.nngpPreMatColor)
			{
				nnPutMaterialColorGL(1032u, val, nNS_MATERIAL_GLES11_DESC2.pColor);
			}
			if (nNS_MATERIAL_GLES11_DESC2.pLogic != nnmaterialcore.nngpPreMatLogic)
			{
				nnPutMaterialLogicGLES11(val, nNS_MATERIAL_GLES11_DESC2.pLogic);
			}
			if ((val.DrawFlag & 0x800) == 0)
			{
				nnPutMaterialTexturesGLES11(val, nNS_MATERIAL_GLES11_DESC2.pTexDesc, nNS_MATERIAL_GLES11_DESC2.nTex);
			}
			else
			{
				nnPutDisableTexturesGL();
			}
		}
		else if ((pMaterial.fType & 1) != 0)
		{
			NNS_MATERIAL_DESC nNS_MATERIAL_DESC = (NNS_MATERIAL_DESC)pMaterial.pMaterial;
			uint fFlag2 = nNS_MATERIAL_DESC.fFlag;
			if (fFlag2 != nnmaterialcore.nngPreMatFlag)
			{
				nnPutMaterialFlagGL(val, fFlag2);
			}
			if (nNS_MATERIAL_DESC.pColor != nnmaterialcore.nngpPreMatColor)
			{
				nnPutMaterialColorGL(1032u, val, (NNS_MATERIAL_STDSHADER_COLOR)nNS_MATERIAL_DESC.pColor);
			}
			if (nNS_MATERIAL_DESC.pLogic != nnmaterialcore.nngpPreMatLogic)
			{
				nnPutMaterialLogicGL(val, nNS_MATERIAL_DESC.pLogic);
			}
			if ((val.DrawFlag & 0x800) == 0)
			{
				nnPutMaterialTexturesGL(val, nNS_MATERIAL_DESC.pTexDesc, nNS_MATERIAL_DESC.nTex);
			}
			else
			{
				nnPutDisableTexturesGL();
			}
		}
		return 1;
	}

