	public static void GmMainDatLoadBossBattleStart(int boss_type)
	{
		if (g_gm_main_system.boss_load_no == boss_type)
		{
			return;
		}
		if (GmMainDatReleaseBossBattleReleaseCheck())
		{
			GmGameDatReleaseBossBattleExit();
		}
		if (g_gs_main_sys_info.stage_id == 16 && boss_type > 0 && boss_type < 4)
		{
			if (_bossThread != null && _bossThread.IsAlive)
			{
				_bossThread.Join();
			}
			_bossThread = null;
			_bossThread = new Thread(_GmMainDatLoadBossBattleStart);
			_bossFinishThread = false;
			_bossThread.Start(boss_type);
			return;
		}
		_bossFinishThread = true;
		GmGameDatLoadBoosBattleInit(boss_type);
		gm_main_load_bossbattle_tcb = MTM_TASK_MAKE_TCB(gmMainDataLoadBoosBattleMgr_LoadWait, null, 0u, ushort.MaxValue, 2048u, 5, () => new GMS_MAIN_LOAD_BB_MGR_WORK(), "GM_LOAD_BBM");
		GMS_MAIN_LOAD_BB_MGR_WORK gMS_MAIN_LOAD_BB_MGR_WORK = (GMS_MAIN_LOAD_BB_MGR_WORK)gm_main_load_bossbattle_tcb.work;
		gMS_MAIN_LOAD_BB_MGR_WORK.boss_type = boss_type;
		gMS_MAIN_LOAD_BB_MGR_WORK.b_end = false;
		g_gm_main_system.game_flag |= 2097152u;
	}

	public static void _GmMainDatLoadBossBattleStart(object o)
	{
		int num = (int)o;
		bool flag = false;
		do
		{
			int x = g_gm_main_system.ply_work[0].obj_work.pos.x;
			switch (num)
			{
			case 0:
				flag = true;
				break;
			case 1:
				if (x >= 10424705)
				{
					flag = true;
				}
				break;
			case 2:
				if (x >= 23266972)
				{
					flag = true;
				}
				break;
			case 3:
				if (x >= 37948249)
				{
					flag = true;
				}
				break;
			case 4:
				if (x >= 52666673)
				{
					flag = true;
				}
				break;
			}
			if (_bossFinishThread)
			{
				return;
			}
			if (!flag)
			{
				Thread.Sleep(30);
			}
		}
		while (!flag);
		GmGameDatLoadBoosBattleInit(num);
		gm_main_load_bossbattle_tcb = MTM_TASK_MAKE_TCB(gmMainDataLoadBoosBattleMgr_LoadWait, null, 0u, ushort.MaxValue, 2048u, 5, () => new GMS_MAIN_LOAD_BB_MGR_WORK(), "GM_LOAD_BBM");
		GMS_MAIN_LOAD_BB_MGR_WORK gMS_MAIN_LOAD_BB_MGR_WORK = (GMS_MAIN_LOAD_BB_MGR_WORK)gm_main_load_bossbattle_tcb.work;
		gMS_MAIN_LOAD_BB_MGR_WORK.boss_type = num;
		gMS_MAIN_LOAD_BB_MGR_WORK.b_end = false;
		g_gm_main_system.game_flag |= 2097152u;
		_bossFinishThread = true;
	}

	private static bool GmMainDatLoadBossBattleLoadCheck()
