		if (g_gm_main_system.boss_load_no != -1 && (g_gm_main_system.game_flag & 0x400000) == 0 && (boss_type == -1 || boss_type == g_gm_main_system.boss_load_no))
		{
			return true;
		}
		return false;
	}

	private static bool GmMainDatLoadBossBattleLoadNowCheck()
	{
		if ((g_gm_main_system.game_flag & 0x200000) != 0)
		{
