	// Zona del botón de pausa (coordenadas del juego). La fija Sonic4Ep1 para que coincida con el botón dibujado.
	public static uint pauseKeyX = 215u;
	// Zoom de la cámara del juego: menor = más cerca. 0.9 acerca un 10%.
	public const float CAMERA_ZOOM = 0.9f;

	private static int GmMainKeyCheckPauseKeyOn()
	{
		int result = -1;
		uint num = pauseKeyX;
		uint num2 = 0u;
		if (GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			num = 390u;
			num2 = 0u;
		}
		else if (GsGetMainSysInfo().game_mode == 1)
		{
			num = 275u;
			num2 = 0u;
		}
		for (int i = 0; i < 4; i++)
		{
			if (!amTpIsTouchOn(i))
			{
				continue;
			}
			ushort num3 = _am_tp_touch[i].on[0];
			ushort num4 = _am_tp_touch[i].on[1];
			if (num3 >= num && num3 <= num + 115 && num4 >= num2 && num4 <= num2 + 60)
			{
				num3 = _am_tp_touch[i].push[0];
				num4 = _am_tp_touch[i].push[1];
				if (num3 >= num && num3 <= num + 115 && num4 >= num2 && num4 <= num2 + 60)
				{
					result = i;
					break;
				}
			}
		}
		return result;
	}

	private static int GmMainKeyCheckPauseKeyPush()
	{
		int result = -1;
		uint num = pauseKeyX;
		uint num2 = 0u;
		if (GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			num = 390u;
			num2 = 0u;
		}
		else if (GsGetMainSysInfo().game_mode == 1)
		{
			num = 275u;
			num2 = 0u;
		}
		for (int i = 0; i < 4; i++)
		{
			if (amTpIsTouchPush(i))
			{
				ushort num3 = _am_tp_touch[i].push[0];
				ushort num4 = _am_tp_touch[i].push[1];
				if (num3 >= num && num3 <= num + 115 && num4 >= num2 && num4 <= num2 + 60)
				{
					result = i;
					break;
				}
			}
		}
		if (g_pause_flag)
		{
			g_pause_flag = false;
			return 1;
		}
		return result;
	}

	private static void gmMainSysInit()
	{
		g_gm_main_system.Clear();
		g_gm_main_system.player_rest_num[0] = g_gs_main_sys_info.rest_player_num;
		if (g_gm_main_system.player_rest_num[0] == 0)
		{
			g_gm_main_system.player_rest_num[0] = 1u;
		}
		mtMathSRand((uint)(nnRandom() * 32767f));
	}

	private static void gmMainLoad(int load_proc)
	{
		short[] array = new short[1];
		GmMainClearSuspendedPause();
		DmLoadingStart();
		GmPauseMenuLoadStart();
		for (int i = 0; (long)i < 1L; i++)
		{
			array[i] = (short)g_gs_main_sys_info.char_id[i];
		}
		GmGameDatLoadInit(load_proc, g_gs_main_sys_info.stage_id, array);
		gm_main_load_wait_tcb = MTM_TASK_MAKE_TCB(gmMainDataLoadWait, gmMainDataLoadDest, 0u, ushort.MaxValue, 4096u, 0, null, "GM_LOAD_WAIT");
	}

	private static void gmMainDataLoadWait(MTS_TASK_TCB tcb)
	{
		gmMainUpdateSuspendedPause();
		if (GmPauseMenuLoadIsFinished() && GmGameDatLoadCheck() == GME_GAMEDAT_LOAD_PROGRESS.GMD_GAMEDAT_LOAD_PROGRESS_COMPLETE)
		{
			if (!SaveState.shouldResume())
			{
				SaveState.deleteSave();
			}
			GmGameDatBuildInit();
			GmGameDatBuildStandard();
			GmGameDatBuildArea();
			mtTaskChangeTcbProcedure(tcb, gmMainDataBuildWait);
			GC.Collect();
			GC.WaitForPendingFinalizers();
			GC.Collect();
		}
	}

	private static void gmMainDataBuildWait(MTS_TASK_TCB tcb)
	{
		gmMainUpdateSuspendedPause();
		if (GmGameDatBuildStandardCheck() && GmGameDatBuildAreaCheck() && SoundPartialCache(5) && PrepareBGMForLevel(g_gs_main_sys_info.stage_id))
		{
			GmGameDatLoadExit();
			g_gs_main_sys_info.game_flag |= 16u;
			DmLoadingSetLoadComplete();
			mtTaskChangeTcbProcedure(tcb, gmMainDataLoadingEndWait);
		}
	}

	private static void gmMainDataLoadingEndWait(MTS_TASK_TCB tcb)
	{
		gmMainUpdateSuspendedPause();
		if (DmLoadingIsExit())
		{
			gmMainGameStart();
			mtTaskClearTcb(tcb);
		}
	}

	private static void gmMainDataLoadDest(MTS_TASK_TCB tcb)
	{
		gm_main_load_wait_tcb = null;
	}

	private static void gmMainRebuild()
	{
		gm_main_load_wait_tcb = MTM_TASK_MAKE_TCB(gmMainRebuildWait, gmMainRebuildDest, 0u, ushort.MaxValue, 4096u, 0, null, "GM_REBUILD_WAIT");
		GmGameDatReBuildRestart();
	}

