	private static void gmMainGameStart()
	{
		bool flag = false;
		if (SaveState.shouldResume())
		{
			SaveState.resumePlayerState();
			SaveState.resumeMapData();
		}
		amIPhoneTouchCanceled();
		CPadVirtualPad cPadVirtualPad = CPadVirtualPad.CreateInstance();
		float[] area = new float[4] { -120f, 166f, 232f, 318f };
		cPadVirtualPad.Create(area);
		CPadPolarHandle cPadPolarHandle = CPadPolarHandle.CreateInstance();
		if (g_gs_main_sys_info.stage_id == 9)
		{
			cPadPolarHandle.Create(0f, 0f, AMD_SCREEN_2D_WIDTH * 4f / 5f, AMD_SCREEN_2D_HEIGHT);
		}
		else
		{
			cPadPolarHandle.Create();
		}
		cPadPolarHandle.SetValue(0f);
		g_gm_main_system.polar_now = 0;
		g_gm_main_system.polar_diff = 0;
		if ((GsGetMainSysInfo().game_flag & 1) == 0)
		{
			GsMainSysSetSleepFlag(false);
			GsMainSysSetAccelFlag(true);
		}
		else if ((GsGetMainSysInfo().game_flag & 0x200) == 0 && (GsGetMainSysInfo().stage_id == 9 || GSM_MAIN_STAGE_IS_SPSTAGE()))
		{
			GsMainSysSetSleepFlag(false);
			GsMainSysSetAccelFlag(true);
		}
		else
		{
			GsMainSysSetSleepFlag(true);
			GsMainSysSetAccelFlag(false);
		}
		GmPadVibInit();
		if ((g_gm_main_system.game_flag & 0x200) != 0)
		{
			g_gm_main_system.game_time = 0u;
			flag = true;
		}
		g_gm_main_system.game_flag &= 4187479041u;
		g_gm_main_system.die_event_wait_time = 0;
		g_gm_main_system.pseudofall_dir = 0;
		g_gm_main_system.boss_load_no = -1;
		g_gm_main_system.pre_tcb = MTM_TASK_MAKE_TCB(gmMainPre, null, 0u, 0, 4096u, 5, null, "GM_MAIN_PRE");
		g_gm_main_system.post_tcb = MTM_TASK_MAKE_TCB(gmMainPost, null, 0u, 0, 32768u, 5, null, "GM_MAIN_POST");
		g_obj.flag = 4194408u;
		g_obj.ppPre = GmObjPreFunc;
		g_obj.ppPost = null;
		g_obj.ppCollision = GmObjCollision;
		g_obj.ppObjPre = GmObjObjPreFunc;
		g_obj.ppObjPost = GmObjObjPostFunc;
		g_obj.ppRegRecAuto = GmObjRegistRectAuto;
		g_obj.draw_scale.x = (g_obj.draw_scale.y = (g_obj.draw_scale.z = 13107));
		g_obj.inv_draw_scale.x = (g_obj.inv_draw_scale.y = (g_obj.inv_draw_scale.z = FX_Div(4096, g_obj.draw_scale.x)));
		g_obj.depth = 128;
		ObjDebugRectActionInit();
		gmMainInitLight();
		if ((g_gs_main_sys_info.game_flag & 4) != 0)
		{
			g_gm_main_system.game_time = g_gm_main_system.time_save;
			if (g_gm_main_system.marker_pri == 0)
			{
				g_gm_main_system.ply_dmg_count = 0u;
				g_gm_main_system.game_flag &= 4227858431u;
			}
			else
			{
				g_gm_main_system.game_flag |= 67108864u;
				if (flag)
				{
					g_gs_main_sys_info.game_flag |= 256u;
				}
			}
		}
		GmMapInit();
		GmTvxInit();
		GmMapFarInit();
		GmDecoInit();
		GmWaterSurfaceInit();
		GmPlyEfctTrailSysInit();
		GmFixInit();
		GmCameraInit();
		GmSoundInit();
		GmRingInit();
		GmEventMgrInit();
		GmEventMgrStart();
		for (int i = 0; (long)i < 1L; i++)
		{
			if (g_gs_main_sys_info.char_id[i] != 32767)
			{
				g_gm_main_system.ply_work[i] = GmPlayerInit(g_gs_main_sys_info.char_id[i], 0, (ushort)i, 0);
			}
		}
		GmEveMgrCreateStateEvent();
		if ((g_gs_main_sys_info.game_flag & 4) != 0 && g_gm_main_system.marker_pri != 0)
		{
			SaveState.saveCurrentState(0);
		}
		if (g_gs_main_sys_info.stage_id != 28)
		{
			g_gm_main_system.game_flag |= 268435456u;
			g_gm_main_system.game_flag &= 4160749567u;
		}
		g_gm_main_system.game_flag &= 4294964223u;
		g_gm_main_system.game_flag |= 2048u;
		if (GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			GmSplStageStart();
		}
		else if (g_gs_main_sys_info.game_mode == 2)
		{
			GmEndingStart();
		}
		else
		{
			GmStartDemoStart();
		}
	}

	private static void gmMainInitLight()
	{
		NNS_RGBA col = new NNS_RGBA(1f, 1f, 1f, 1f);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		if (g_gs_main_sys_info.stage_id == 2 || g_gs_main_sys_info.stage_id == 3)
		{
			g_obj.ambient_color.r = 1f;
			g_obj.ambient_color.g = 0f;
			g_obj.ambient_color.b = 0f;
		}
		else if (g_gs_main_sys_info.stage_id == 14)
		{
			g_obj.ambient_color.r = 0.1f;
			g_obj.ambient_color.g = 0.1f;
			g_obj.ambient_color.b = 0.1f;
		}
		else
		{
			g_obj.ambient_color.r = 0.8f;
			g_obj.ambient_color.g = 0.8f;
			g_obj.ambient_color.b = 0.8f;
		}
		if (GMM_MAIN_GET_ZONE_TYPE() == 3)
		{
			nNS_VECTOR.x = -0.95f;
			nNS_VECTOR.y = 0.25f;
			nNS_VECTOR.z = -1f;
		}
		else if (g_gs_main_sys_info.stage_id == 16)
		{
			nNS_VECTOR.x = -1f;
			nNS_VECTOR.y = -1f;
			nNS_VECTOR.z = -1f;
		}
		else
		{
			nNS_VECTOR.x = 0f;
			nNS_VECTOR.y = 0f;
			nNS_VECTOR.z = -1f;
		}
		nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
		ObjDrawSetParallelLight(intensity: (g_gs_main_sys_info.stage_id != 14) ? 1f : 0.8f, light_no: NNE_LIGHT_0, col: ref col, vec: nNS_VECTOR);
		g_gm_main_system.def_light_vec.Assign(nNS_VECTOR);
		g_gm_main_system.def_light_col = col;
		float intensity = ((g_gs_main_sys_info.stage_id != 14) ? 1.5f : 1f);
		if (GMM_MAIN_GET_ZONE_TYPE() == 3)
		{
			nNS_VECTOR.x = 0.05f;
			nNS_VECTOR.y = 0.15f;
			nNS_VECTOR.z = -0.05f;
		}
		else
		{
			nNS_VECTOR.x = -0.5f;
			nNS_VECTOR.y = -0.4f;
			nNS_VECTOR.z = -0.25f;
		}
		nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
		ObjDrawSetParallelLight(NNE_LIGHT_6, ref col, intensity, nNS_VECTOR);
		g_gm_main_system.ply_light_vec.Assign(nNS_VECTOR);
		g_gm_main_system.ply_light_col = col;
		GmMapSetLight();
		if (GMM_MAIN_GET_ZONE_TYPE() == 0)
		{
			GmGmkBreakLandSetLight();
		}
		else if (GMM_MAIN_GET_ZONE_TYPE() == 3)
		{
			GmGmkGearSetLight();
			GmGmkNeedleSetLight();
		}
		else if (GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			GmSplStageSetLight();
		}
		else if (GMM_MAIN_GET_ZONE_TYPE() == 4)
		{
			GmBoss5LandSetLight();
			GmDecoSetLightFinalZone();
		}
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	private static void gmMainPre(MTS_TASK_TCB tcb)
	{
		gmMainUpdateSuspendedPause();
		GMS_MAIN_SYSTEM gMS_MAIN_SYSTEM = g_gm_main_system;
		if ((gMS_MAIN_SYSTEM.game_flag & 0x8000000) != 0)
		{
			g_gm_main_system.game_flag &= 4160749567u;
			if (g_gs_main_sys_info.stage_id != 28 && (g_gm_main_system.game_flag & 0x80000) == 0)
			{
				GmSoundPlayStageBGM(0);
			}
		}
		CPadVirtualPad cPadVirtualPad = CPadVirtualPad.CreateInstance();
		cPadVirtualPad.Update();
		CPadPolarHandle cPadPolarHandle = CPadPolarHandle.CreateInstance();
		cPadPolarHandle.Update();
		int polar_now = gMS_MAIN_SYSTEM.polar_now;
		gMS_MAIN_SYSTEM.polar_now = cPadPolarHandle.GetAngle32Value();
		gMS_MAIN_SYSTEM.polar_diff = gMS_MAIN_SYSTEM.polar_now - polar_now;
		if (!gmMainIsUseWaitUpCamera())
		{
			return;
		}
		if (GmPlayerIsStateWait(gMS_MAIN_SYSTEM.ply_work[0]))
		{
			if (gMS_MAIN_SYSTEM.camscale_state == GME_MAIN_CAMSCALE_STATE.GMD_MAIN_CAMSCALE_STATE_NON)
			{
				gMS_MAIN_SYSTEM.camscale_state = GME_MAIN_CAMSCALE_STATE.GMD_MAIN_CAMSCALE_STATE_ZOOM;
			}
		}
		else
		{
			gMS_MAIN_SYSTEM.camscale_state = GME_MAIN_CAMSCALE_STATE.GMD_MAIN_CAMSCALE_STATE_NON;
			gMS_MAIN_SYSTEM.camera_scale = 0.67438334f;
		}
		if (gMS_MAIN_SYSTEM.camscale_state == GME_MAIN_CAMSCALE_STATE.GMD_MAIN_CAMSCALE_STATE_ZOOM)
		{
			gMS_MAIN_SYSTEM.camera_scale -= 0.01f;
			if (gMS_MAIN_SYSTEM.camera_scale < 0.33719167f)
			{
				gMS_MAIN_SYSTEM.camera_scale = 0.33719167f;
				gMS_MAIN_SYSTEM.camscale_state = GME_MAIN_CAMSCALE_STATE.GMD_MAIN_CAMSCALE_STATE_UP;
			}
		}
		for (int i = 0; i < 7; i++)
		{
			OBS_CAMERA oBS_CAMERA = ObjCameraGet(i);
			if (oBS_CAMERA != null)
			{
				oBS_CAMERA.scale = gMS_MAIN_SYSTEM.camera_scale * CAMERA_ZOOM;
			}
		}
	}

	private static void gmMainPost(MTS_TASK_TCB tcb)
	{
		CPadEmu.CreateInstance();
		if ((g_gm_main_system.ply_work[0].player_flag & 0x400) != 0 && g_gm_main_system.die_event_wait_time < 491520 && (g_gm_main_system.game_flag & 0x40) == 0)
		{
			g_gm_main_system.die_event_wait_time = ObjTimeCountUp(g_gm_main_system.die_event_wait_time);
			if (g_gm_main_system.die_event_wait_time >= 491520)
			{
				if (g_gs_main_sys_info.game_mode == 1)
				{
					GmClearDemoRetryStart();
				}
				else
				{
					g_gm_main_system.player_rest_num[0]--;
					if ((int)g_gm_main_system.player_rest_num[0] < 0)
					{
						g_gm_main_system.player_rest_num[0] = 0u;
					}
					if (g_gm_main_system.player_rest_num[0] == 0)
					{
						g_gm_main_system.game_flag |= 32u;
						GmOverStart(0);
						GmSoundPlayGameOver();
					}
					else
					{
						g_gm_main_system.game_flag |= 2u;
						g_gs_main_sys_info.game_flag |= 4u;
						if ((g_gm_main_system.game_flag & 0x200) != 0)
						{
							g_gm_main_system.game_flag |= 32u;
							GmOverStart(1);
						}
						else
						{
							IzFadeInitEasy(0u, 1u, 15f);
						}
					}
				}
			}
		}
		if ((g_gs_main_sys_info.game_mode == 1 && (g_gm_main_system.game_flag & 0x10) != 0) || (g_gs_main_sys_info.game_mode != 1 && ((g_gm_main_system.game_flag & 0x100) != 0 || ((g_gm_main_system.game_flag & 0x300) == 0 && (g_gm_main_system.game_flag & 2) != 0 && IzFadeIsEnd()) || (g_gm_main_system.game_flag & 0x14) == 20)))
		{
			gmMainDecideNextEvt();
			if ((g_gm_main_system.game_flag & 2) != 0)
			{
				GmMainRestartExit();
				if (g_gs_main_sys_info.game_mode == 1)
				{
					GmMainGSRetryInit();
				}
			}
			else
			{
				GmMainExit();
			}
			return;
		}
		if (!AoAccountIsCurrentEnable())
		{
			SyDecideEvtCase(5);
			IzFadeInitEasy(0u, 3u, 1f);
			GmMainExit();
			return;
		}
		if ((g_gm_main_system.game_flag & 4) != 0 && (g_gm_main_system.game_flag & 8) == 0)
		{
			g_gs_main_sys_info.game_flag |= 2u;
			GmClearDemoStart();
			g_gm_main_system.game_flag |= 8u;
		}
		if (GmMainCheckExeTimerCount())
		{
			if (!GSM_MAIN_STAGE_IS_SPSTAGE())
			{
				g_gm_main_system.game_time++;
			}
			else if (g_gm_main_system.game_time != 0)
			{
				g_gm_main_system.game_time--;
			}
		}
		if (gmMainCheckExeSyncTimerCount())
		{
			g_gm_main_system.sync_time++;
		}
		if ((GmMainKeyCheckPauseKeyPush() != -1 || gmMainIsSuspendedPause() || isBackKeyPressed() || !isForeground || g_ao_sys_global.is_show_ui) && GmPauseCheckExecutable())
		{
			setBackKeyRequest(false);
			GmMainClearSuspendedPause();
			GmPauseInit();
		}
		else if ((g_gm_main_system.game_flag & 0x80) != 0)
		{
			gmMainDecideNextEvt();
			g_gm_main_system.game_flag &= 4294967167u;
			if (GmPauseMenuGetResult() == 0)
			{
				GmMainRestartExit();
				GmMainGSRetryInit();
			}
			else
			{
				GmMainExit();
			}
		}
	}

	private static void gmMainDecideNextEvt()
	{
		short num = 0;
		if ((g_gm_main_system.game_flag & 0x80) != 0)
		{
			switch (GmPauseMenuGetResult())
			{
			case 0:
				num = 1;
				break;
			case 2:
				num = 0;
				break;
			case 3:
				num = 4;
				break;
			default:
				num = 1;
				break;
			}
		}
		else if ((g_gm_main_system.game_flag & 2) == 0 && GsTrialIsTrial())
		{
			g_gs_main_sys_info.game_flag &= 4294967009u;
			nextDemoLevel = 0;
			num = 6;
		}
		else if (g_gs_main_sys_info.game_mode != 1)
		{
			num = (short)(((g_gm_main_system.game_flag & 4) != 0) ? (((g_gm_main_system.game_flag & 0x4000) != 0) ? 3 : ((g_gs_main_sys_info.stage_id == 16) ? 2 : 0)) : (((g_gm_main_system.game_flag & 2) != 0) ? 1 : ((!GsMainSysIsStageClear(0)) ? 4 : 0)));
		}
		else
		{
			GmMainClearSuspendedPause();
			num = (short)(((g_gm_main_system.game_flag & 2) != 0) ? 1 : ((!GsMainSysIsStageClear(0)) ? 4 : 0));
		}
		SyDecideEvtCase(num);
	}

	private static bool gmMainCheckExeSyncTimerCount()
	{
		if ((g_gm_main_system.game_flag & 0x800) != 0)
		{
			return true;
		}
		return false;
	}

