	private static OBS_OBJECT_WORK GmGmkPressPillarInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_P_PIL_TOP");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		uint num = 0u;
		if (eve_rec.id == 285)
		{
			num = 1u;
		}
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_press_pillar_obj_3d_list[2 + num], gMS_ENEMY_3D_WORK.obj_3d);
		oBS_OBJECT_WORK.pos.z = -126976;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.move_flag |= 512u;
		oBS_OBJECT_WORK.move_flag |= 1040u;
		oBS_OBJECT_WORK.flag |= 1u;
		oBS_OBJECT_WORK.user_flag = 0u;
		OBS_COLLISION_WORK col_work = gMS_ENEMY_3D_WORK.ene_com.col_work;
		col_work.obj_col.obj = oBS_OBJECT_WORK;
		col_work.obj_col.width = (ushort)GMD_GMK_PPIL_COL_WIDTH;
		col_work.obj_col.height = (ushort)GMD_GMK_PPIL_COL_HEIGHT;
		col_work.obj_col.ofst_x = (short)(-col_work.obj_col.width / 2);
		col_work.obj_col.ofst_y = 0;
		if (eve_rec.id == 285)
		{
			col_work.obj_col.ofst_y = (short)(-col_work.obj_col.height);
		}
		if (eve_rec.id == 284)
		{
			ObjObjectFieldRectSet(oBS_OBJECT_WORK, (short)(-GMD_GMK_PPIL_COL_WIDTH / 2 + 2), -1, (short)(GMD_GMK_PPIL_COL_WIDTH / 2 - 2), GMD_GMK_PPIL_COL_HEIGHT);
		}
		else
		{
			ObjObjectFieldRectSet(oBS_OBJECT_WORK, (short)(-GMD_GMK_PPIL_COL_WIDTH / 2 + 2), (short)(-GMD_GMK_PPIL_COL_HEIGHT), (short)(GMD_GMK_PPIL_COL_WIDTH / 2 - 2), -1);
		}
		oBS_OBJECT_WORK.ppFunc = gmGmkPPillarTopWait;
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GMM_EFFECT_CREATE_WORK(() => new GMS_EFFECT_3DNN_WORK(), oBS_OBJECT_WORK, 0, "GMK_P_PIL_BODY");
		GMS_EFFECT_3DNN_WORK gMS_EFFECT_3DNN_WORK = (GMS_EFFECT_3DNN_WORK)oBS_OBJECT_WORK2;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK2, gm_gmk_press_pillar_obj_3d_list[num], gMS_EFFECT_3DNN_WORK.obj_3d);
		ObjAction3dNNMaterialMotionLoad(gMS_EFFECT_3DNN_WORK.obj_3d, 0, null, null, (int)num, readAMBFile(ObjDataGet(953).pData));
		ObjDrawObjectActionSet3DNNMaterial(oBS_OBJECT_WORK2, 0);
		oBS_OBJECT_WORK2.pos.z = -131072;
		oBS_OBJECT_WORK2.move_flag |= 256u;
		oBS_OBJECT_WORK2.disp_flag |= 4194308u;
		oBS_OBJECT_WORK2.ppFunc = gmGmkPPillarBodyFollow;
		oBS_OBJECT_WORK2 = GMM_EFFECT_CREATE_WORK(() => new GMS_EFFECT_3DNN_WORK(), oBS_OBJECT_WORK, 0, "GMK_P_PIL_SPRING");
		gMS_EFFECT_3DNN_WORK = (GMS_EFFECT_3DNN_WORK)oBS_OBJECT_WORK2;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK2, gm_gmk_press_pillar_obj_3d_list[4], gMS_EFFECT_3DNN_WORK.obj_3d);
		oBS_OBJECT_WORK2.pos.z = -131072;
		oBS_OBJECT_WORK2.move_flag |= 256u;
		oBS_OBJECT_WORK2.disp_flag |= 4194304u;
		oBS_OBJECT_WORK2.ppFunc = gmGmkPPillarSpringFollow;
