	private static void GmGmkPressPillarClear()
	{
		Array.Clear(gm_gmk_press_pillar_sw, 0, gm_gmk_press_pillar_sw.Length);
	}

	private static void gmGmkPPillarTopWait(OBS_OBJECT_WORK obj_work)
	{
		GMS_EVE_RECORD_EVENT eve_rec = ((GMS_ENEMY_COM_WORK)obj_work).eve_rec;
		byte b = (byte)(eve_rec.flag & GMD_GMK_PPIL_ID_NUM_MASK);
		if (gm_gmk_press_pillar_sw[b] != 0)
		{
			int a = eve_rec.top << 10;
			a = MTM_MATH_ABS(a);
			if (a == 0)
			{
				a = 4096;
			}
			if (eve_rec.id == 284)
			{
				obj_work.spd.y = -a;
			}
			else
			{
				obj_work.spd.y = a;
			}
			obj_work.ppFunc = gmGmkPPillarTopMove;
		}
	}

	private static void gmGmkPPillarTopMove(OBS_OBJECT_WORK obj_work)
	{
		GMS_EVE_RECORD_EVENT eve_rec = ((GMS_ENEMY_COM_WORK)obj_work).eve_rec;
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)obj_work;
		int num = eve_rec.height << 12;
		bool flag = false;
		if (num != 0)
		{
			if (eve_rec.id == 284)
			{
				num = gMS_ENEMY_COM_WORK.born_pos_y - num;
				if (obj_work.pos.y <= num)
				{
					obj_work.pos.y = num;
					flag = true;
				}
			}
			else
			{
				num = gMS_ENEMY_COM_WORK.born_pos_y + num;
				if (obj_work.pos.y >= num)
				{
					obj_work.pos.y = num;
					flag = true;
				}
			}
		}
		if ((obj_work.move_flag & 0xF) != 0)
		{
			flag = true;
		}
		if (!flag)
		{
			return;
		}
		obj_work.spd.y = 0;
		obj_work.ppFunc = null;
		obj_work.user_flag |= GMD_GMK_PPIL_COLHIT;
		if ((eve_rec.flag & GMD_GMK_PPIL_FLAG_EFFECT) == 0)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)GmEfctZoneEsCreate(obj_work, 3, 1);
			if (eve_rec.id == 284)
			{
				oBS_OBJECT_WORK.dir.z = 32768;
			}
		}
	}

	private static void gmGmkPPillarBodyFollow(OBS_OBJECT_WORK obj_work)
	{
		OBS_OBJECT_WORK parent_obj = obj_work.parent_obj;
		int y = parent_obj.pos.y;
		y = ((((GMS_ENEMY_COM_WORK)parent_obj).eve_rec.id != 284) ? (y - GMD_GMK_PPIL_PIL_OFS_MAX) : (y + GMD_GMK_PPIL_PIL_OFS_MAX));
		obj_work.pos.y = y;
		if ((parent_obj.user_flag & GMD_GMK_PPIL_COLHIT) != 0)
		{
			if ((((GMS_ENEMY_COM_WORK)parent_obj).eve_rec.flag & GMD_GMK_PPIL_FLAG_SHOCK_ABS) != 0)
			{
				obj_work.spd.y = 0;
				obj_work.ppFunc = null;
			}
			else
			{
				obj_work.spd.y = obj_work.user_timer;
				obj_work.ppFunc = gmGmkPPillarBodyMove;
				obj_work.user_flag = 0u;
			}
		}
		else if (parent_obj.spd.y != 0)
		{
			obj_work.user_timer = parent_obj.spd.y;
		}
	}

	private static void gmGmkPPillarBodyMove(OBS_OBJECT_WORK obj_work)
	{
		OBS_OBJECT_WORK parent_obj = obj_work.parent_obj;
		GMS_EVE_RECORD_EVENT eve_rec = ((GMS_ENEMY_COM_WORK)parent_obj).eve_rec;
		int num = obj_work.spd.y * 3 / 4;
		if (16 < MTM_MATH_ABS(num))
		{
			obj_work.spd.y = num;
		}
		else
		{
			if (eve_rec.id == 284)
			{
				obj_work.spd.y = -obj_work.user_timer / 32;
			}
			else
			{
				obj_work.spd.y = -obj_work.user_timer / 32;
			}
			obj_work.ppFunc = gmGmkPPillarBodyMoveEx;
		}
		if (eve_rec.id == 284)
		{
			if (obj_work.pos.y <= parent_obj.pos.y + GMD_GMK_PPIL_PIL_OFS_MIN)
			{
				obj_work.pos.y = parent_obj.pos.y + GMD_GMK_PPIL_PIL_OFS_MIN;
				obj_work.spd.y = 32;
				obj_work.ppFunc = gmGmkPPillarBodyMoveEx;
			}
		}
		else if (obj_work.pos.y >= parent_obj.pos.y - GMD_GMK_PPIL_PIL_OFS_MIN)
		{
			obj_work.pos.y = parent_obj.pos.y - GMD_GMK_PPIL_PIL_OFS_MIN;
			obj_work.spd.y = -32;
			obj_work.ppFunc = gmGmkPPillarBodyMoveEx;
		}
		parent_obj.user_work = (uint)obj_work.pos.y;
	}

	private static void gmGmkPPillarBodyMoveEx(OBS_OBJECT_WORK obj_work)
	{
		OBS_OBJECT_WORK parent_obj = obj_work.parent_obj;
		GMS_EVE_RECORD_EVENT eve_rec = ((GMS_ENEMY_COM_WORK)parent_obj).eve_rec;
		if (obj_work.user_flag == 0)
		{
			obj_work.spd.y = obj_work.spd.y * 8 / 7;
			if (2048 <= MTM_MATH_ABS(obj_work.spd.y))
			{
				obj_work.user_flag = 1u;
			}
		}
		else
		{
			int y = obj_work.spd.y * 7 / 8;
			if (128 < MTM_MATH_ABS(obj_work.spd.y))
			{
				obj_work.spd.y = y;
			}
		}
		if (eve_rec.id == 284)
		{
			if (obj_work.pos.y >= parent_obj.pos.y + GMD_GMK_PPIL_PIL_OFS_MAX)
			{
				obj_work.pos.y = parent_obj.pos.y + GMD_GMK_PPIL_PIL_OFS_MAX;
				obj_work.spd.y = 0;
				obj_work.ppFunc = null;
			}
		}
		else if (obj_work.pos.y <= parent_obj.pos.y - GMD_GMK_PPIL_PIL_OFS_MAX)
		{
			obj_work.pos.y = parent_obj.pos.y - GMD_GMK_PPIL_PIL_OFS_MAX;
			obj_work.spd.y = 0;
			obj_work.ppFunc = null;
		}
		parent_obj.user_work = (uint)obj_work.pos.y;
	}

	private static void gmGmkPPillarSpringFollow(OBS_OBJECT_WORK obj_work)
	{
		OBS_OBJECT_WORK parent_obj = obj_work.parent_obj;
		int y = parent_obj.pos.y;
		y = ((((GMS_ENEMY_COM_WORK)parent_obj).eve_rec.id != 284) ? (y - GMD_GMK_PPIL_SPR_OFS_MAX) : (y + GMD_GMK_PPIL_SPR_OFS_MAX));
		obj_work.pos.y = y;
		if ((parent_obj.user_flag & GMD_GMK_PPIL_COLHIT) != 0)
		{
			if ((((GMS_ENEMY_COM_WORK)parent_obj).eve_rec.flag & GMD_GMK_PPIL_FLAG_SHOCK_ABS) != 0)
			{
				obj_work.ppFunc = null;
			}
			else
			{
				obj_work.ppFunc = gmGmkPPillarSpringMove;
			}
			obj_work.spd.y = 0;
		}
	}

	private static void gmGmkPPillarSpringMove(OBS_OBJECT_WORK obj_work)
	{
		OBS_OBJECT_WORK parent_obj = obj_work.parent_obj;
		GMS_EVE_RECORD_EVENT eve_rec = ((GMS_ENEMY_COM_WORK)parent_obj).eve_rec;
		if (eve_rec.id == 284)
		{
			int num = parent_obj.pos.y + GMD_GMK_PPIL_PIL_OFS_MIN - (int)parent_obj.user_work;
			num /= 2;
			obj_work.pos.y = parent_obj.pos.y + GMD_GMK_PPIL_SPR_OFS_MIN - num;
			int a = obj_work.pos.y - (parent_obj.pos.y + GMD_GMK_PPIL_SPR_OFS_MIN);
			a = MTM_MATH_ABS(a);
			float a2 = (float)a / (float)(GMD_GMK_PPIL_SPR_OFS_MAX - GMD_GMK_PPIL_SPR_OFS_MIN);
			obj_work.scale.y = FXM_FLOAT_TO_FX32(a2);
		}
		else
		{
			int num = parent_obj.pos.y - GMD_GMK_PPIL_PIL_OFS_MIN - (int)parent_obj.user_work;
			num /= 2;
			obj_work.pos.y = parent_obj.pos.y - GMD_GMK_PPIL_SPR_OFS_MIN - num;
			int a = obj_work.pos.y - (parent_obj.pos.y - GMD_GMK_PPIL_SPR_OFS_MIN);
			a = MTM_MATH_ABS(a);
			float a2 = (float)a / (float)(GMD_GMK_PPIL_SPR_OFS_MAX - GMD_GMK_PPIL_SPR_OFS_MIN);
			obj_work.scale.y = FXM_FLOAT_TO_FX32(a2);
		}
	}

