	private static void gmEneMereonHideSearchMain(OBS_OBJECT_WORK obj_work)
	{
		float[] array = new float[2];
		float[] array2 = new float[2];
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		OBS_RECT_WORK oBS_RECT_WORK = gMS_PLAYER_WORK.rect_work[2];
		array[0] = FXM_FX32_TO_FLOAT(gMS_PLAYER_WORK.obj_work.pos.x + (oBS_RECT_WORK.rect.top + oBS_RECT_WORK.rect.bottom >> 1));
		array[1] = FXM_FX32_TO_FLOAT(gMS_PLAYER_WORK.obj_work.pos.y + (oBS_RECT_WORK.rect.left + oBS_RECT_WORK.rect.right >> 1));
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)obj_work;
		oBS_RECT_WORK = gMS_ENEMY_COM_WORK.rect_work[2];
		array2[0] = FXM_FX32_TO_FLOAT(obj_work.pos.x + (oBS_RECT_WORK.rect.top + oBS_RECT_WORK.rect.bottom >> 1));
		array2[1] = FXM_FX32_TO_FLOAT(obj_work.pos.y + (oBS_RECT_WORK.rect.left + oBS_RECT_WORK.rect.right >> 1));
		float num = array2[0] - array[0];
		float num2 = array2[1] - array[1];
		float num3 = ((gMS_ENEMY_COM_WORK.eve_rec.id != 4) ? 192f : 96f);
		if (num * num + num2 * num2 <= num3 * num3)
		{
			obj_work.disp_flag &= 4294967263u;
			gmEneMereonAppearInit(obj_work);
		}
	}

