		obj_work.ppFunc = gmEneMereonRocketFallMain;
	}

	private static void gmEneMereonRocketFallMain(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.user_timer != 0)
		{
			obj_work.dir.y = (ushort)(obj_work.dir.y + obj_work.user_timer);
			if (obj_work.dir.y >= 32768)
			{
				obj_work.dir.y = 32768;
				obj_work.user_timer = 0;
			}
		}
		if (obj_work.user_work != 0)
		{
			obj_work.user_work = (uint)ObjTimeCountDown((int)obj_work.user_work);
			if (obj_work.user_work == 0)
			{
				GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
				ObjAction3dNNMotionRelease(obj_work.obj_3d);
				ObjObjectAction3dNNModelReleaseCopy(obj_work);
				ObjObjectCopyAction3dNNModel(obj_work, gm_ene_mereon_r_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
				ObjObjectAction3dNNMotionLoad(obj_work, 0, false, ObjDataGet(673), null, 0, null);
				ObjDrawObjectSetToon(obj_work);
				ObjObjectFieldRectSet(obj_work, -4, -4, 4, 4);
				ObjDrawObjectActionSet(obj_work, 5);
				obj_work.disp_flag |= 4u;
				if (obj_work.dir.y != 0 || obj_work.user_timer != 0)
				{
					obj_work.dir.y = 0;
					obj_work.disp_flag &= 4294967294u;
				}
				else
				{
					obj_work.disp_flag |= 1u;
				}
				obj_work.move_flag |= 64u;
				if ((obj_work.disp_flag & 1) != 0)
				{
					obj_work.spd_m = -8192;
				}
				else
				{
					obj_work.spd_m = 8192;
				}
				obj_work.move_flag |= 1024u;
				obj_work.ppFunc = gmEneMereonRocketMain;
				obj_work.user_flag = 0u;
				obj_work.user_timer = 0;
				GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctEneEsCreate(obj_work, 1);
				GmComEfctSetDispOffsetF(gMS_EFFECT_3DES_WORK, -38f, -11f, 0f);
				gMS_EFFECT_3DES_WORK.efct_com.obj_work.flag |= 524288u;
			}
		}
		else if ((obj_work.disp_flag & 8) != 0 && (obj_work.move_flag & 1) != 0)
		{
			obj_work.user_work = 4096u;
			GMS_EFFECT_3DES_WORK efct_work = GmEfctEneEsCreate(obj_work, 4);
			GmComEfctAddDispOffsetF(efct_work, 0f, -16f, 16f);
		}
	}

	private static void gmEneMereonRocketMain(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.user_flag == 0 && (ushort)(obj_work.dir.z + 8192) > 16384)
		{
			obj_work.user_flag = 1u;
			obj_work.move_flag &= 4294967231u;
			obj_work.move_flag |= 257u;
			obj_work.spd.x = obj_work.spd_m;
		}
		if (obj_work.user_timer != 0)
		{
			obj_work.user_timer--;
			if (obj_work.user_timer == 0)
			{
				obj_work.move_flag |= 64u;
				obj_work.user_flag = 0u;
				obj_work.spd.x = 0;
			}
		}
		else if (obj_work.user_flag != 0)
		{
			obj_work.dir.z = ObjRoopMove16(obj_work.dir.z, 0, 1024);
			if (obj_work.dir.z == 0)
			{
				obj_work.user_timer = 4;
			}
		}
	}

	private static void gmEneMereonCheckFwFlip(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (gMS_PLAYER_WORK.obj_work.pos.x < obj_work.pos.x)
		{
			if (obj_work.obj_3d.act_id[0] != 0)
			{
				ObjDrawObjectActionSet(obj_work, 0);
				obj_work.disp_flag &= 4294967294u;
			}
		}
		else if (gMS_PLAYER_WORK.obj_work.pos.x > obj_work.pos.x && obj_work.obj_3d.act_id[0] != 1)
		{
			ObjDrawObjectActionSet(obj_work, 1);
			obj_work.disp_flag |= 1u;
		}
		obj_work.disp_flag |= 4u;
	}

	private static OBS_OBJECT_WORK GmEneHariSenboInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENE_HARI_WORK(), "ENE_HARI");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		if (eve_rec.id == 0)
		{
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_harisenbo_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		}
		else
		{
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_harisenbo_r_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		}
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(660), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		ObjDrawObjectActionSet(oBS_OBJECT_WORK, 0);
		oBS_OBJECT_WORK.pos.z = 655360;
		gMS_ENEMY_3D_WORK.obj_3d.mtn_cb_func = gmEneHariMotionCallback;
		gMS_ENEMY_3D_WORK.obj_3d.mtn_cb_param = oBS_OBJECT_WORK;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -12, -12, 12, 12);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		ObjRectWorkSet(oBS_RECT_WORK, -22, -22, 22, 22);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, -22, -22, 22, 22);
		oBS_RECT_WORK.flag &= 4294967291u;
		ObjObjectFieldRectSet(oBS_OBJECT_WORK, -4, -8, 4, 0);
		oBS_OBJECT_WORK.move_flag |= 8448u;
		if ((eve_rec.flag & 1) == 0)
		{
			oBS_OBJECT_WORK.disp_flag |= 1u;
		}
		if (eve_rec.id == 0)
		{
			gmEneHarisenboFwInit(oBS_OBJECT_WORK);
			oBS_OBJECT_WORK.flag |= 1073741824u;
		}
		else
		{
			oBS_OBJECT_WORK.user_work = (uint)(eve_rec.width * 30 * 4096);
			if (oBS_OBJECT_WORK.user_work == 0)
			{
				oBS_OBJECT_WORK.user_work = 1228800u;
			}
			oBS_OBJECT_WORK.user_flag = (uint)(eve_rec.height * 30 * 4096);
			if (oBS_OBJECT_WORK.user_flag == 0)
			{
				oBS_OBJECT_WORK.user_flag = 1228800u;
			}
			gmEneHarisenboRedAtkWaitInit(oBS_OBJECT_WORK);
		}
		gmEneHariCreateJetEfct((GMS_ENE_HARI_WORK)oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

