	private static void gmEneHariMotionCallback(AMS_MOTION motion, NNS_OBJECT _object, object param)
	{
		NNS_MATRIX nNS_MATRIX = gmEneHariMotionCallback_node_mtx;
		NNS_MATRIX nNS_MATRIX2 = gmEneHariMotionCallback_base_mtx;
		GMS_ENE_HARI_WORK gMS_ENE_HARI_WORK = (GMS_ENE_HARI_WORK)(OBS_OBJECT_WORK)param;
		nnMakeUnitMatrix(nNS_MATRIX2);
		nnMultiplyMatrix(nNS_MATRIX2, nNS_MATRIX2, amMatrixGetCurrent());
		nnCalcNodeMatrixTRSList(nNS_MATRIX, _object, 7, motion.data, nNS_MATRIX2);
		gMS_ENE_HARI_WORK.jet_mtx.Assign(nNS_MATRIX);
	}

	private static void gmEneHariCreateJetEfct(GMS_ENE_HARI_WORK hari_work)
	{
		if (hari_work.efct_jet == null)
		{
			hari_work.efct_jet = GmEfctEneEsCreate((OBS_OBJECT_WORK)hari_work, 12);
			hari_work.efct_jet.efct_com.obj_work.flag |= 524304u;
			hari_work.efct_jet.efct_com.obj_work.user_work_OBJECT = hari_work.jet_mtx;
			hari_work.efct_jet.efct_com.obj_work.ppFunc = gmEneHariJetEfctMain;
		}
	}

	private static void gmEneHariJetEfctMain(OBS_OBJECT_WORK obj_work)
	{
		NNS_MATRIX nNS_MATRIX = (NNS_MATRIX)obj_work.user_work_OBJECT;
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		if (obj_work.parent_obj == null)
		{
			obj_work.flag |= 4u;
			return;
		}
		nNS_VECTOR.x = nNS_MATRIX.M03 - FXM_FX32_TO_FLOAT(obj_work.parent_obj.pos.x);
		nNS_VECTOR.y = 0f - nNS_MATRIX.M13 - FXM_FX32_TO_FLOAT(obj_work.parent_obj.pos.y);
		nNS_VECTOR.z = nNS_MATRIX.M23 - FXM_FX32_TO_FLOAT(obj_work.parent_obj.pos.z);
		if ((obj_work.parent_obj.disp_flag & 1) != 0)
		{
			nNS_VECTOR.x = 0f - nNS_VECTOR.x;
			nNS_VECTOR.z = 0f - nNS_VECTOR.z;
		}
		nNS_VECTOR.y += 5f;
		GmComEfctSetDispOffsetF((GMS_EFFECT_3DES_WORK)obj_work, nNS_VECTOR.x, nNS_VECTOR.y, nNS_VECTOR.z);
		GmEffectDefaultMainFuncDeleteAtEnd(obj_work);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

