	public static void gmDecoDrawServerMain(MTS_TASK_TCB tcb)
	{
		if (!GmMainIsDrawEnable())
		{
			return;
		}
		uint command = 0u;
		GMS_DECO_FALL_MANAGER gMS_DECO_FALL_MANAGER = null;
		float dividend = gmDecoGameSystemGetSyncTime();
		for (int i = 0; i < 16; i++)
		{
			gMS_DECO_FALL_MANAGER = g_deco_fall_manager[i];
			if (gMS_DECO_FALL_MANAGER.dec_id == 0)
			{
				continue;
			}
			switch (gMS_DECO_FALL_MANAGER.dec_id)
			{
			case 20u:
			case 40u:
			case 41u:
			case 42u:
				command = 9u;
				break;
			case 27u:
			case 47u:
			case 48u:
			case 49u:
				command = 12u;
				ObjDraw3DNNSetCameraEx(0, 1, 12u);
				break;
			}
			VecFx32 vecFx = default(VecFx32);
			vecFx.Assign(gMS_DECO_FALL_MANAGER.reg[0].vec);
			NNS_TEXLIST texlist = gMS_DECO_FALL_MANAGER.texlist;
			NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
			nnMakeUnitMatrix(nNS_MATRIX);
			nnTranslateMatrix(nNS_MATRIX, nNS_MATRIX, FX_FX32_TO_F32(vecFx.x), FX_FX32_TO_F32(vecFx.y), FX_FX32_TO_F32(vecFx.z));
			AMS_PARAM_DRAW_PRIMITIVE aMS_PARAM_DRAW_PRIMITIVE = GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Alloc();
			aMS_PARAM_DRAW_PRIMITIVE.type = 0;
			aMS_PARAM_DRAW_PRIMITIVE.count = 6 * gMS_DECO_FALL_MANAGER.reg_num;
			aMS_PARAM_DRAW_PRIMITIVE.ablend = 1;
			aMS_PARAM_DRAW_PRIMITIVE.bldSrc = 770;
			aMS_PARAM_DRAW_PRIMITIVE.bldDst = 771;
			aMS_PARAM_DRAW_PRIMITIVE.bldMode = 32774;
			aMS_PARAM_DRAW_PRIMITIVE.aTest = 0;
			aMS_PARAM_DRAW_PRIMITIVE.zMask = 0;
			aMS_PARAM_DRAW_PRIMITIVE.zTest = 1;
			aMS_PARAM_DRAW_PRIMITIVE.noSort = 1;
			aMS_PARAM_DRAW_PRIMITIVE.uwrap = 1;
			aMS_PARAM_DRAW_PRIMITIVE.vwrap = 0;
			aMS_PARAM_DRAW_PRIMITIVE.texlist = texlist;
			aMS_PARAM_DRAW_PRIMITIVE.texId = texlist.nTex - 1;
			aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D = amDrawAlloc_NNS_PRIM3D_PCT(aMS_PARAM_DRAW_PRIMITIVE.count);
			NNS_PRIM3D_PCT[] buffer = aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D.buffer;
			int offset = aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D.offset;
			aMS_PARAM_DRAW_PRIMITIVE.format3D = 4;
			uint num = 0u;
			float num2 = fmod(dividend, gMS_DECO_FALL_MANAGER.frame) / gMS_DECO_FALL_MANAGER.frame * 5.027991f;
			NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
			VecFx32 vecFx2 = default(VecFx32);
			for (uint num3 = 0u; num3 < 8; num3++)
			{
				vecFx2.Assign(gMS_DECO_FALL_MANAGER.reg[num3].vec);
				if (vecFx2.x != 0)
				{
					int num4 = offset + (int)(6 * num);
					buffer[num4].Tex.u = (buffer[num4 + 1].Tex.u = 1f);
					buffer[num4 + 2].Tex.u = (buffer[num4 + 3].Tex.u = 0f);
					buffer[num4].Tex.v = (buffer[num4 + 2].Tex.v = -1f * (float)gMS_DECO_FALL_MANAGER.reg[num3].num - num2);
					buffer[num4 + 1].Tex.v = (buffer[num4 + 3].Tex.v = 0f - num2);
					buffer[num4].Col = uint.MaxValue;
					buffer[num4 + 1].Col = (buffer[num4 + 2].Col = (buffer[num4 + 3].Col = buffer[num4].Col));
					nNS_VECTOR.x = FX_FX32_TO_F32(vecFx2.x - vecFx.x);
					nNS_VECTOR.y = FX_FX32_TO_F32(vecFx2.y - vecFx.y);
					nNS_VECTOR.z = FX_FX32_TO_F32(vecFx2.z - vecFx.z);
					buffer[num4].Pos.x = (buffer[num4 + 1].Pos.x = 32f + nNS_VECTOR.x);
					buffer[num4 + 2].Pos.x = (buffer[num4 + 3].Pos.x = -32f + nNS_VECTOR.x);
					buffer[num4].Pos.y = (buffer[num4 + 2].Pos.y = 32f + nNS_VECTOR.y);
					buffer[num4 + 1].Pos.y = (buffer[num4 + 3].Pos.y = -32f + nNS_VECTOR.y + -64f * (float)(gMS_DECO_FALL_MANAGER.reg[num3].num - 1));
					buffer[num4].Pos.z = (buffer[num4 + 1].Pos.z = (buffer[num4 + 2].Pos.z = (buffer[num4 + 3].Pos.z = 1f + nNS_VECTOR.z)));
					buffer[num4 + 4] = buffer[num4 + 2];
					buffer[num4 + 5] = buffer[num4 + 3];
					buffer[num4 + 3] = buffer[num4 + 1];
					gMS_DECO_FALL_MANAGER.reg[num3].vec.y = 0;
					num++;
				}
			}
			GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
			amMatrixPush(nNS_MATRIX);
			GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
			ObjDraw3DNNDrawPrimitive(aMS_PARAM_DRAW_PRIMITIVE, command, 0, 0);
			amMatrixPop();
			GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Release(aMS_PARAM_DRAW_PRIMITIVE);
		}
		gmDecoExecuteDrawPrimitive();
		gmDecoInitDrawPrimitive();
	}

	private static uint gmDecoGameSystemGetSyncTime()
	{
		return g_gm_main_system.sync_time;
	}

	private static void gmDecoExecuteDrawPrimitive()
	{
		GMS_DECO_PRIM_DRAW_WORK[] array = g_deco_tvx_work;
		GMS_DECO_PRIM_DRAW_STACK gMS_DECO_PRIM_DRAW_STACK = null;
		if (array[0].tex == null)
		{
			return;
		}
		SNNS_MATRIX dst = default(SNNS_MATRIX);
		SNNS_MATRIX dst2 = default(SNNS_MATRIX);
		SNNS_MATRIX dst3 = default(SNNS_MATRIX);
		nnMakeUnitMatrix(ref dst3);
		nnMakeScaleMatrix(out dst, -1f, 1f, 1f);
		nnMakeScaleMatrix(out dst2, 1f, -1f, 1f);
		uint num = GmMainGetLightColor();
		_AMS_PARAM_DRAW_PRIMITIVE.ablend = 0;
		_AMS_PARAM_DRAW_PRIMITIVE.bldSrc = 770;
		_AMS_PARAM_DRAW_PRIMITIVE.bldDst = 1;
		_AMS_PARAM_DRAW_PRIMITIVE.bldMode = 32774;
		_AMS_PARAM_DRAW_PRIMITIVE.aTest = 1;
		_AMS_PARAM_DRAW_PRIMITIVE.zMask = 0;
		_AMS_PARAM_DRAW_PRIMITIVE.zTest = 1;
		_AMS_PARAM_DRAW_PRIMITIVE.noSort = 1;
		_AMS_PARAM_DRAW_PRIMITIVE.uwrap = 1;
		_AMS_PARAM_DRAW_PRIMITIVE.vwrap = 1;
		_AMS_PARAM_DRAW_PRIMITIVE.format3D = 4;
