				int num11 = (int)gMS_DECO_PRIM_DRAW_STACK.vtx_num / 3;
				float num5 = FXM_FX32_TO_FLOAT(gMS_DECO_PRIM_DRAW_STACK.pos.x);
				float num6 = 0f - FXM_FX32_TO_FLOAT(gMS_DECO_PRIM_DRAW_STACK.pos.y) + gMS_DECO_PRIM_DRAW_STACK.off_y;
				float num7 = FXM_FX32_TO_FLOAT(gMS_DECO_PRIM_DRAW_STACK.pos.z);
				int num8 = num3;
				AOS_TVX_VERTEX[] vtx = gMS_DECO_PRIM_DRAW_STACK.vtx;
				for (int i = 0; i < gMS_DECO_PRIM_DRAW_STACK.vtx_num; i++)
				{
