					buffer[num9].Pos.x += num5;
					buffer[num9].Pos.y += num6;
					buffer[num9].Pos.z += num7;
					buffer[num9].Tex.u = vtx[i].u;
					buffer[num9].Tex.v = vtx[i].v;
					buffer[num9].Col = vtx[i].c & num;
				}
				num3 = num3 + (int)gMS_DECO_PRIM_DRAW_STACK.vtx_num + 2;
				if (num4 != 0)
