	private static void GmDecoBuildData()
	{
		int num = g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id];
		GMS_DECO_DATA gMS_DECO_DATA = gmDecoDataGetInfo();
		AMS_AMB_HEADER header = null;
		if (gMS_DECO_DATA != null)
		{
			header = gmDecoDataGetAmbHeader();
		}
		string sPath;
		if (gmDecoIsUseModel(0))
		{
			gMS_DECO_DATA.tvx_model = readAMBFile(amBindGet(header, 0, out sPath));
			gMS_DECO_DATA.tvx_model_data = new TVX_FILE[gMS_DECO_DATA.tvx_model.file_num];
			gMS_DECO_DATA.tvx_model.dir = sPath;
			AoTexBuild(gMS_DECO_DATA.tvx_tex, readAMBFile(amBindGet(header, 1)));
			AoTexLoad(gMS_DECO_DATA.tvx_tex);
		}
		if (gmDecoIsUseModel(1))
		{
			AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile(amBindGet(header, 4, out sPath));
			aMS_AMB_HEADER.dir = sPath;
			AMS_AMB_HEADER aMS_AMB_HEADER2 = readAMBFile(amBindGet(header, 5, out sPath));
			aMS_AMB_HEADER2.dir = sPath;
			uint draw_flag = 0u;
			gMS_DECO_DATA.obj_3d_list_fall = GmGameDBuildRegBuildModel(aMS_AMB_HEADER, aMS_AMB_HEADER2, draw_flag);
		}
	}

	private static bool GmDecoCheckLoading()
	{
		GMS_DECO_DATA gMS_DECO_DATA = gmDecoDataGetInfo();
		if (gmDecoIsUseModel(0) && !AoTexIsLoaded(gMS_DECO_DATA.tvx_tex))
		{
			return false;
		}
		gmDecoIsUseModel(1);
		return true;
	}

	private static void GmDecoRelease()
	{
		GmDecoGlareDataRelease();
		gmDecoDataRelease();
		gmDecoReleaseMgr();
	}

	private static void GmDecoFlushData()
	{
		int num = g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id];
		GMS_DECO_DATA gMS_DECO_DATA = gmDecoDataGetInfo();
		AMS_AMB_HEADER header = null;
		if (gMS_DECO_DATA != null)
		{
			header = gmDecoDataGetAmbHeader();
		}
		if (gmDecoIsUseModel(0))
		{
			AoTexRelease(gMS_DECO_DATA.tvx_tex);
		}
		if (gmDecoIsUseModel(1))
		{
			string sPath;
			AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile(amBindGet(header, 4, out sPath));
			aMS_AMB_HEADER.dir = sPath;
			GmGameDBuildRegFlushModel(gMS_DECO_DATA.obj_3d_list_fall, aMS_AMB_HEADER.file_num);
			gMS_DECO_DATA.obj_3d_list_fall = null;
		}
	}

	private static bool GmDecoCheckFlushing()
	{
		GMS_DECO_DATA gMS_DECO_DATA = gmDecoDataGetInfo();
		if (gmDecoIsUseModel(0) && !AoTexIsReleased(gMS_DECO_DATA.tvx_tex))
		{
			return false;
		}
		return true;
	}

