	private static void GmDecoSetLoopState()
	{
		GMS_DECO_MGR gMS_DECO_MGR = gmDecoGetMgr();
		if (gMS_DECO_MGR == null)
		{
			return;
		}
		int num = 0;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, 4);
		while (oBS_OBJECT_WORK != null)
		{
			if (oBS_OBJECT_WORK.ppFunc == new MPP_VOID_OBS_OBJECT_WORK(gmDecoMainFuncLoop))
			{
				if (num < 2)
				{
					gMS_DECO_MGR.motion_frame_loop[num] = 1;
					num++;
					continue;
				}
				if (num < 12)
				{
					gMS_DECO_MGR.motion_frame_loop[num] = oBS_OBJECT_WORK.user_timer;
					num++;
				}
				oBS_OBJECT_WORK.flag |= 8u;
				oBS_OBJECT_WORK.disp_flag |= 32u;
				GMS_DECO_WORK gMS_DECO_WORK = (GMS_DECO_WORK)oBS_OBJECT_WORK;
				GMS_EVE_RECORD_DECORATE event_record = gMS_DECO_WORK.event_record;
				if (event_record != null)
				{
					if (event_record.pos_x == byte.MaxValue)
					{
						event_record.pos_x = gMS_DECO_WORK.event_x;
						gMS_DECO_WORK.event_x = 0;
					}
					gMS_DECO_WORK.event_record = null;
				}
			}
			oBS_OBJECT_WORK = ObjObjectSearchRegistObject(oBS_OBJECT_WORK, 4);
		}
	}

	private static void GmDecoClearLoopState()
	{
		GMS_DECO_MGR gMS_DECO_MGR = gmDecoGetMgr();
