	private static void gmDecoDraw(OBS_OBJECT_WORK obj_work)
	{
		uint p_disp_flag = obj_work.disp_flag;
		GMS_DECO_WORK gMS_DECO_WORK = (GMS_DECO_WORK)obj_work;
		if (gMS_DECO_WORK.model_tex != null)
		{
			if (GmMainIsDrawEnable() && (p_disp_flag & 0x20) == 0)
			{
				if ((obj_work.user_flag & 2) == 0)
				{
					gmDecoSetDrawPrimitive(gMS_DECO_WORK.model_index, gMS_DECO_WORK.model_tex, obj_work.pos, 0f, gMS_DECO_WORK.obj_3d.command_state, p_disp_flag);
				}
				if ((obj_work.user_flag & 4) != 0)
				{
					GMS_DECO_SUBMODEL_WORK gMS_DECO_SUBMODEL_WORK = (GMS_DECO_SUBMODEL_WORK)gMS_DECO_WORK;
					gmDecoSetDrawPrimitive(gMS_DECO_SUBMODEL_WORK.sub_model_index, gMS_DECO_WORK.model_tex, obj_work.pos, 0f, gMS_DECO_WORK.obj_3d.command_state, p_disp_flag);
				}
			}
			return;
		}
		if ((obj_work.user_flag & 2) == 0)
		{
			OBS_ACTION3D_NN_WORK obj_3d = obj_work.obj_3d;
			if (obj_3d != null)
			{
				if ((obj_work.user_flag & 8) != 0 && obj_3d != null && obj_3d.motion != null && obj_3d.motion.mmobject != null)
				{
					float num = amMotionMaterialGetStartFrame(obj_3d.motion, obj_3d.mat_act_id);
					float num2 = amMotionMaterialGetEndFrame(obj_3d.motion, obj_3d.mat_act_id);
					float divisor = num2 - num;
					float dividend = gmDecoGameSystemGetSyncTime();
					obj_3d.mat_frame = fmod(dividend, divisor);
					obj_work.disp_flag |= 16u;
				}
				if (obj_3d.command_state != 0)
				{
					ObjDraw3DNNSetCameraEx(0, 1, obj_work.obj_3d.command_state);
				}
				ObjDrawActionSummary(obj_work);
				obj_work.disp_flag = p_disp_flag;
			}
		}
		if ((obj_work.user_flag & 4) != 0)
		{
			if (ObjObjectPauseCheck(0u) != 0)
			{
				p_disp_flag |= 0x1000;
			}
			GMS_DECO_SUBMODEL_WORK gMS_DECO_SUBMODEL_WORK2 = (GMS_DECO_SUBMODEL_WORK)obj_work;
			gMS_DECO_SUBMODEL_WORK2.obj_3d_sub.command_state = 17u;
			if (gMS_DECO_SUBMODEL_WORK2.obj_3d_sub.command_state != 17)
			{
				ObjDraw3DNNSetCameraEx(0, 1, gMS_DECO_SUBMODEL_WORK2.obj_3d_sub.command_state);
			}
			ObjDrawAction3DNN(gMS_DECO_SUBMODEL_WORK2.obj_3d_sub, obj_work.pos, obj_work.dir, obj_work.scale, ref p_disp_flag);
		}
	}

	private static float fmod(float dividend, float divisor)
	{
		return (Math.Abs(dividend) - Math.Abs(divisor) * (float)Math.Floor(Math.Abs(dividend) / Math.Abs(divisor))) * (float)Math.Sign(dividend);
	}

