	private static AMS_RENDER_TARGET gmDecoDrawFallCopyRenderFront()
	{
		int num = g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id];
		AMS_RENDER_TARGET aMS_RENDER_TARGET = null;
		switch (num)
		{
		case 0:
			aMS_RENDER_TARGET = gmDecoGetRenderWorkFront();
			if (aMS_RENDER_TARGET == null)
			{
				aMS_RENDER_TARGET = _gm_mapFar_render_work;
				if (aMS_RENDER_TARGET.width == 0)
				{
					return null;
				}
			}
			break;
		case 2:
			aMS_RENDER_TARGET = GmWaterSurfaceGetRenderTarget();
			if (aMS_RENDER_TARGET != null)
			{
				gmDecoCopySetRenderTargetForFront(aMS_RENDER_TARGET);
				return aMS_RENDER_TARGET;
			}
			aMS_RENDER_TARGET = _am_render_manager.targetp;
			aMS_RENDER_TARGET = ((aMS_RENDER_TARGET != _gm_mapFar_render_work) ? _gm_mapFar_render_work : _am_draw_target);
			break;
		default:
			return null;
		}
		GMS_DECO_MGR gMS_DECO_MGR = gmDecoGetMgr();
		if (gMS_DECO_MGR != null && !gMS_DECO_MGR.flag_render_front)
		{
			NNS_RGBA_U8 color = g_deco_rendaer_target_color;
			amRenderCopyTarget(aMS_RENDER_TARGET, color);
			gmDecoCopySetRenderTargetForFront(aMS_RENDER_TARGET);
		}
		return aMS_RENDER_TARGET;
	}

