	private static GMS_DECO_WORK gmDecoLoadObj(GMS_EVE_RECORD_DECORATE dec_rec, TaskWorkFactoryDelegate work_size, int pos_x, int pos_y, MPP_VOID_OBS_OBJECT_WORK main_func, MPP_VOID_OBS_OBJECT_WORK move_func, MPP_VOID_OBS_OBJECT_WORK out_func, GSF_TASK_PROCEDURE dest_func)
	{
		GMS_DECO_WORK gMS_DECO_WORK = (GMS_DECO_WORK)OBM_OBJECT_TASK_DETAIL_INIT(5376, 5, 0, 0, work_size, "DECO OBJ");
		OBS_OBJECT_WORK obj_work = gMS_DECO_WORK.obj_work;
		mtTaskChangeTcbDestructor(obj_work.tcb, dest_func);
		obj_work.obj_type = 4;
		obj_work.pos.x = pos_x + g_gm_deco_pos[dec_rec.id][0];
		obj_work.pos.y = pos_y + g_gm_deco_pos[dec_rec.id][1];
		obj_work.pos.z = g_gm_deco_pos[dec_rec.id][2];
		obj_work.dir.z = g_gm_deco_rot_z[dec_rec.id];
		obj_work.move_flag |= 8448u;
		obj_work.ppFunc = main_func;
		obj_work.ppMove = move_func;
		obj_work.ppOut = out_func;
		obj_work.view_out_ofst = (short)(g_gm_decorate_size_tbl[dec_rec.id] + 16 + 32 + 16);
		obj_work.ppViewCheck = ObjObjectViewOutCheck;
		gMS_DECO_WORK.event_record = dec_rec;
		gMS_DECO_WORK.event_x = dec_rec.pos_x;
		dec_rec.pos_x = byte.MaxValue;
		return gMS_DECO_WORK;
	}

