	private static void gmDecoMainFuncMotionCount(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_timer--;
		if (0 >= obj_work.user_timer)
		{
			obj_work.obj_3d.frame[0] = 0f;
			obj_work.user_timer = 0;
			obj_work.disp_flag |= 16u;
			obj_work.ppFunc = null;
		}
	}

	private static void gmDecoMainFuncDecreaseMotionSpeed(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_timer--;
		if (obj_work.user_timer > 0)
		{
			float num = obj_work.user_timer;
			float num2 = obj_work.obj_3d.speed[0] / num;
			obj_work.obj_3d.speed[0] -= num2;
			obj_work.obj_3d.frame[0] += obj_work.obj_3d.speed[0];
			float num3 = amMotionGetStartFrame(obj_work.obj_3d.motion, obj_work.obj_3d.act_id[0]);
			float num4 = amMotionGetEndFrame(obj_work.obj_3d.motion, obj_work.obj_3d.act_id[0]);
			if (obj_work.obj_3d.frame[0] < num3)
			{
				obj_work.obj_3d.frame[0] = num4;
			}
			else if (obj_work.obj_3d.frame[0] > num4)
			{
				obj_work.obj_3d.frame[0] = num3;
			}
		}
		else
		{
			obj_work.user_timer = 0;
			obj_work.obj_3d.speed[0] = 0f;
			obj_work.ppFunc = null;
		}
	}

	private static void gmDecoMainFuncMotionApplyCommonFrame(OBS_OBJECT_WORK obj_work)
	{
		GMS_DECO_MGR gMS_DECO_MGR = gmDecoGetMgr();
		if (gMS_DECO_MGR == null)
		{
			return;
		}
		OBS_ACTION3D_NN_WORK[] array = new OBS_ACTION3D_NN_WORK[2];
		OBS_ACTION3D_NN_WORK[] array2 = array;
		array2[0] = obj_work.obj_3d;
		if ((obj_work.user_flag & 4) != 0)
		{
			GMS_DECO_SUBMODEL_WORK gMS_DECO_SUBMODEL_WORK = (GMS_DECO_SUBMODEL_WORK)obj_work;
			array2[1] = gMS_DECO_SUBMODEL_WORK.obj_3d_sub;
		}
		int num = Convert.ToInt32(obj_work.user_work);
		int num2 = 0;
		if ((obj_work.user_flag & 0x20) != 0)
		{
			num2 = 1;
		}
		for (int i = 0; 2 > i; i++)
		{
			OBS_ACTION3D_NN_WORK oBS_ACTION3D_NN_WORK = array2[i];
			if (oBS_ACTION3D_NN_WORK == null || oBS_ACTION3D_NN_WORK.motion == null)
			{
				continue;
			}
			if (oBS_ACTION3D_NN_WORK.motion.mtnbuf[0] != null)
			{
				oBS_ACTION3D_NN_WORK.frame[0] = gMS_DECO_MGR.common_frame_motion[num2] + num;
				float num3 = amMotionGetStartFrame(oBS_ACTION3D_NN_WORK.motion, oBS_ACTION3D_NN_WORK.act_id[0]);
				float num4 = amMotionGetEndFrame(oBS_ACTION3D_NN_WORK.motion, oBS_ACTION3D_NN_WORK.act_id[0]);
				if (oBS_ACTION3D_NN_WORK.frame[0] < num3)
				{
					oBS_ACTION3D_NN_WORK.frame[0] = num3;
				}
				else if (oBS_ACTION3D_NN_WORK.frame[0] >= num4)
				{
					oBS_ACTION3D_NN_WORK.frame[0] = num4 - 1f;
				}
			}
			if (oBS_ACTION3D_NN_WORK.motion.mmobject != null)
			{
				oBS_ACTION3D_NN_WORK.mat_frame = gMS_DECO_MGR.common_frame_motion[num2] + num;
				float num5 = amMotionMaterialGetStartFrame(oBS_ACTION3D_NN_WORK.motion, oBS_ACTION3D_NN_WORK.mat_act_id);
				float num6 = amMotionMaterialGetEndFrame(oBS_ACTION3D_NN_WORK.motion, oBS_ACTION3D_NN_WORK.mat_act_id);
				if (oBS_ACTION3D_NN_WORK.mat_frame < num5)
				{
					oBS_ACTION3D_NN_WORK.mat_frame = num5;
				}
				else if (oBS_ACTION3D_NN_WORK.mat_frame >= num6)
				{
					oBS_ACTION3D_NN_WORK.mat_frame = num6 - 1f;
				}
			}
		}
	}

	private static void gmDecoMainFuncMotionCheckCommonFrame(OBS_OBJECT_WORK obj_work)
	{
		if ((g_gm_main_system.game_flag & 0x1000) != 0)
		{
			return;
		}
		GMS_DECO_MGR gMS_DECO_MGR = gmDecoGetMgr();
		if (gMS_DECO_MGR != null)
		{
			if (obj_work.user_timer < 254)
			{
				obj_work.user_timer++;
				obj_work.disp_flag &= 4294967279u;
			}
			int num = 0;
			if ((obj_work.user_flag & 0x20) != 0)
			{
				num = 1;
			}
			if (gMS_DECO_MGR.common_frame_motion[num] == 0)
			{
				obj_work.flag &= 4294967279u;
				obj_work.user_timer = 0;
			}
			else
			{
				obj_work.flag |= 16u;
			}
		}
	}

	private static void gmDecoMainFuncLoop(OBS_OBJECT_WORK obj_work)
	{
		GMS_DECO_MGR gMS_DECO_MGR = gmDecoGetMgr();
		if (gMS_DECO_MGR == null)
		{
			return;
		}
		int num = 0;
		if ((obj_work.user_flag & 0x20) != 0)
		{
			num = 1;
		}
		if (gMS_DECO_MGR.state_loop == 0)
		{
			obj_work.flag |= 16u;
		}
		else if (gMS_DECO_MGR.state_loop == 1)
		{
			gmDecoMainFuncMotionCheckCommonFrame(obj_work);
			obj_work.flag &= 4294967279u;
		}
		else
		{
			gmDecoMainFuncMotionCheckCommonFrame(obj_work);
		}
		if (obj_work.user_timer != 0 && gMS_DECO_MGR.common_frame_motion[num] != 0 && gMS_DECO_MGR.common_frame_motion[num] + 1 >= obj_work.user_timer)
		{
			gMS_DECO_MGR.common_frame_motion[num] = obj_work.user_timer;
		}
		GMS_DECO_WORK gMS_DECO_WORK = (GMS_DECO_WORK)obj_work;
		int id = gMS_DECO_WORK.event_record.id;
		if (gMS_DECO_MGR.se_handle != null)
		{
			if (gMS_DECO_MGR.common_frame_motion[num] > Convert.ToInt32(obj_work.user_work))
			{
				GmSoundStopSE(gMS_DECO_MGR.se_handle);
				GsSoundFreeSeHandle(gMS_DECO_MGR.se_handle);
				gMS_DECO_MGR.se_handle = null;
			}
		}
		else if (gMS_DECO_MGR.state_loop == 1 && gMS_DECO_MGR.common_frame_motion[num] < Convert.ToInt32(obj_work.user_work) && id != 0)
		{
			gMS_DECO_MGR.se_handle = GsSoundAllocSeHandle();
			int num2 = id;
			if (num2 == 183)
			{
				GmSoundPlaySE("Shutter1", gMS_DECO_MGR.se_handle);
			}
		}
		if (obj_work.user_timer == Convert.ToInt32(obj_work.user_work) && id != 0)
		{
			int num3 = id;
			if (num3 == 183)
			{
				GmSoundPlaySE("Shutter2");
			}
		}
	}

