	private static void gmDecoTcbDest(MTS_TASK_TCB tcb)
	{
		GMS_DECO_WORK gMS_DECO_WORK = (GMS_DECO_WORK)mtTaskGetTcbWork(tcb);
		gmDecoDelFallEvent(gMS_DECO_WORK.event_record, gMS_DECO_WORK.obj_work.pos.x + gMS_DECO_WORK.obj_work.ofst.x);
		if ((gMS_DECO_WORK.obj_work.user_flag & 4) != 0 && gMS_DECO_WORK.model_tex == null)
		{
			GMS_DECO_SUBMODEL_WORK gMS_DECO_SUBMODEL_WORK = (GMS_DECO_SUBMODEL_WORK)gMS_DECO_WORK;
			ObjAction3dNNMotionRelease(gMS_DECO_SUBMODEL_WORK.obj_3d_sub);
		}
