		}
		ObjObjectExit(tcb);
	}

	private static void gmDecoRectFuncChangeMotionCount(OBS_RECT_WORK own_rect_work, OBS_RECT_WORK target_rect_work)
	{
		OBS_OBJECT_WORK parent_obj = own_rect_work.parent_obj;
		GMS_DECO_WORK gMS_DECO_WORK = (GMS_DECO_WORK)parent_obj;
		uint id = gMS_DECO_WORK.event_record.id;
		parent_obj.user_timer = g_gm_deco_user_timer[id];
		float num = amMotionGetStartFrame(parent_obj.obj_3d.motion, parent_obj.obj_3d.act_id[0]);
		float num2 = amMotionGetEndFrame(parent_obj.obj_3d.motion, parent_obj.obj_3d.act_id[0]);
		float num3 = (num2 - num) * (float)Convert.ToInt32(parent_obj.user_work);
		parent_obj.obj_3d.speed[0] = num3 / (float)parent_obj.user_timer;
		parent_obj.disp_flag &= 4294967279u;
		parent_obj.ppFunc = gmDecoMainFuncMotionCount;
	}

	private static void gmDecoRectFuncChangeDecreaseMotionSpeed(OBS_RECT_WORK own_rect_work, OBS_RECT_WORK target_rect_work)
	{
		OBS_OBJECT_WORK parent_obj = own_rect_work.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = target_rect_work.parent_obj;
		float num = 0f;
		num = (((parent_obj2.move_flag & 0x8000) == 0) ? FX_FX32_TO_F32(parent_obj2.spd_m) : FX_FX32_TO_F32(parent_obj2.spd.x));
		num = num * (float)Convert.ToInt32(parent_obj.user_work) / 10f;
		parent_obj.obj_3d.speed[0] = num;
		if ((parent_obj.user_flag & 0x10) == 0)
		{
			parent_obj.obj_3d.speed[0] = MTM_MATH_ABS(parent_obj.obj_3d.speed[0]);
		}
		parent_obj.ppFunc = gmDecoMainFuncDecreaseMotionSpeed;
		GMS_DECO_WORK gMS_DECO_WORK = (GMS_DECO_WORK)parent_obj;
		uint id = gMS_DECO_WORK.event_record.id;
		parent_obj.user_timer = g_gm_deco_user_timer[id];
	}

