	private static void gmDecoAdjustIPhone(OBS_OBJECT_WORK obj_work, int id)
	{
		if (obj_work == null)
		{
			return;
		}
		if (id != 71)
		{
			return;
		}
		float num = 0f;
		float num2 = 0f;
		ushort stage_id = g_gs_main_sys_info.stage_id;
		if (stage_id != 8)
		{
			return;
		}
		if (obj_work.pos.x > FX_F32_TO_FX32(1024f) && obj_work.pos.x < FX_F32_TO_FX32(1280f))
		{
			num = 576f;
			num2 = 54.4f;
		}
		else if (obj_work.pos.x > FX_F32_TO_FX32(3008f) && obj_work.pos.x < FX_F32_TO_FX32(3072f))
		{
			num = 768f;
			num2 = 40f;
		}
		else
		{
			if (obj_work.pos.x <= FX_F32_TO_FX32(6848f) || obj_work.pos.x >= FX_F32_TO_FX32(6976f) || obj_work.pos.y <= FX_F32_TO_FX32(1213f))
			{
				return;
			}
			num = 1213f;
			num2 = 61f;
		}
		obj_work.scale.y = FX_F32_TO_FX32(num2 / 64f);
		float num3 = FX_FX32_TO_F32(obj_work.pos.y) - num;
		num3 /= 64f;
		obj_work.pos.y = FX_F32_TO_FX32(num + num3 * num2);
	}

	private static GMS_DECO_WORK gmDecoInitNomodel(GMS_EVE_RECORD_DECORATE dec_rec, int x, int y, byte type, TaskWorkFactoryDelegate work_size)
	{
