		if ((g_gm_deco_user_flag[id] & 1) != 0 && (g_gs_main_sys_info.game_flag & 0x20) == 0)
		{
			dec_rec.pos_x = byte.MaxValue;
			return null;
		}
		GMS_DECO_WORK gMS_DECO_WORK = gmDecoLoadObj(dec_rec, work_size, x, y, g_gm_deco_func_main[id], g_gm_deco_func_move[id], g_gm_deco_func_out[id], g_gm_deco_func_dest[id]);
		gMS_DECO_WORK.obj_work.disp_flag |= g_gm_deco_disp_flag[id];
		gMS_DECO_WORK.obj_work.user_work = g_gm_deco_user_work[id];
		gMS_DECO_WORK.obj_work.user_timer = g_gm_deco_user_timer[id];
		gMS_DECO_WORK.obj_work.user_flag = g_gm_deco_user_flag[id];
		gMS_DECO_WORK.obj_work.flag |= 2u;
		if ((gMS_DECO_WORK.obj_work.disp_flag & 1) != 0)
		{
			gMS_DECO_WORK.obj_work.scale.x = -4096;
			gMS_DECO_WORK.obj_work.disp_flag &= 4294967294u;
		}
		if ((gMS_DECO_WORK.obj_work.disp_flag & 2) != 0)
		{
			gMS_DECO_WORK.obj_work.scale.y = -4096;
			gMS_DECO_WORK.obj_work.disp_flag &= 4294967293u;
		}
		if ((gMS_DECO_WORK.obj_work.user_flag & 0x200) != 0)
		{
			gMS_DECO_WORK.obj_work.flag |= 16u;
		}
		return gMS_DECO_WORK;
	}

	private static GMS_DECO_WORK gmDecoInitModel(GMS_EVE_RECORD_DECORATE dec_rec, int x, int y, byte type)
	{
		int id = dec_rec.id;
		TaskWorkFactoryDelegate taskWorkFactoryDelegate = null;
		int num = -1;
		if ((g_gm_deco_user_flag[id] & 4) != 0)
		{
			taskWorkFactoryDelegate = () => new GMS_DECO_SUBMODEL_WORK();
			num = g_gm_deco_model_index[id][1];
		}
		else
		{
			taskWorkFactoryDelegate = () => new GMS_DECO_WORK();
		}
		GMS_DECO_WORK gMS_DECO_WORK = gmDecoInitNomodel(dec_rec, x, y, type, taskWorkFactoryDelegate);
