			gMS_DECO_WORK.obj_3d.command_state = g_gm_deco_command_state[id];
			gMS_DECO_WORK.model_index = model_index;
			if (num != -1)
			{
				GMS_DECO_SUBMODEL_WORK gMS_DECO_SUBMODEL_WORK = (GMS_DECO_SUBMODEL_WORK)gMS_DECO_WORK;
				gMS_DECO_SUBMODEL_WORK.obj_3d_sub.command_state = g_gm_deco_command_state[id];
				gMS_DECO_SUBMODEL_WORK.sub_model_index = num;
			}
			gMS_DECO_WORK.obj_work.disp_flag |= g_gm_deco_disp_flag[id];
		}
		else
		{
			int num2 = g_gm_deco_model_index[id][0];
			if (num2 != -1)
			{
				gmDecoLoadModel(gMS_DECO_WORK, array[num2]);
				gMS_DECO_WORK.obj_3d.command_state = g_gm_deco_command_state[id];
			}
			if (num != -1)
			{
				GMS_DECO_SUBMODEL_WORK gMS_DECO_SUBMODEL_WORK2 = (GMS_DECO_SUBMODEL_WORK)gMS_DECO_WORK;
				ObjCopyAction3dNNModel(array[num], gMS_DECO_SUBMODEL_WORK2.obj_3d_sub);
				gMS_DECO_SUBMODEL_WORK2.obj_3d_sub.drawflag |= 32u;
				if ((g_gm_deco_user_flag[id] & 0x80) != 0)
				{
					gMS_DECO_SUBMODEL_WORK2.obj_3d_sub.use_light_flag &= 4294967294u;
					gMS_DECO_SUBMODEL_WORK2.obj_3d_sub.use_light_flag |= 4u;
				}
				gMS_DECO_SUBMODEL_WORK2.obj_3d_sub.command_state = g_gm_deco_command_state[id];
			}
			gMS_DECO_WORK.obj_work.disp_flag |= g_gm_deco_disp_flag[id];
			if ((gMS_DECO_WORK.obj_work.disp_flag & 1) != 0)
			{
				gMS_DECO_WORK.obj_work.scale.x = -4096;
				gMS_DECO_WORK.obj_work.disp_flag &= 4294967294u;
			}
			if ((gMS_DECO_WORK.obj_work.disp_flag & 2) != 0)
			{
				gMS_DECO_WORK.obj_work.scale.y = -4096;
				gMS_DECO_WORK.obj_work.disp_flag &= 4294967293u;
			}
		}
		gmDecoSetLightSpecial(gMS_DECO_WORK.obj_work, id);
		return gMS_DECO_WORK;
	}

