	private static GMS_DECO_WORK gmDecoInitModelLoop(GMS_EVE_RECORD_DECORATE dec_rec, int x, int y, byte type)
	{
		GMS_DECO_WORK gMS_DECO_WORK = gmDecoInitModel(dec_rec, x, y, type);
		if (gMS_DECO_WORK == null)
		{
			return null;
		}
		GMS_DECO_MGR gMS_DECO_MGR = gmDecoGetMgr();
		if (gMS_DECO_MGR != null)
		{
			if (gMS_DECO_MGR.state_loop == 0)
			{
				gmDecoMainFuncLoop(gMS_DECO_WORK.obj_work);
			}
			else if (gMS_DECO_MGR.state_loop == 1)
			{
				for (int i = 0; 12 > i; i++)
				{
					if (gMS_DECO_MGR.motion_frame_loop[i] != 0)
					{
						gMS_DECO_WORK.obj_work.user_timer = gMS_DECO_MGR.motion_frame_loop[i];
						gMS_DECO_MGR.motion_frame_loop[i] = 0;
						gmDecoMainFuncLoop(gMS_DECO_WORK.obj_work);
						break;
					}
				}
			}
			else
			{
				GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
				if (gMS_DECO_WORK.obj_work.pos.x < gMS_PLAYER_WORK.obj_work.pos.x)
				{
					gMS_DECO_WORK.obj_work.user_timer = 254;
				}
				else
				{
					int num = 0;
					if ((gMS_DECO_WORK.obj_work.user_flag & 0x20) != 0)
					{
						num = 1;
					}
					if (16 < gMS_DECO_MGR.common_frame_motion[num])
					{
						gMS_DECO_WORK.obj_work.user_timer = gMS_DECO_MGR.common_frame_motion[num] - 16;
					}
				}
				gmDecoMainFuncLoop(gMS_DECO_WORK.obj_work);
			}
		}
		return gMS_DECO_WORK;
	}

	private static GMS_DECO_WORK gmDecoInitModelEffect(GMS_EVE_RECORD_DECORATE dec_rec, int x, int y, byte type)
	{
		GMS_DECO_WORK gMS_DECO_WORK = gmDecoInitModel(dec_rec, x, y, type);
		if (gMS_DECO_WORK == null)
		{
			return null;
		}
		int id = dec_rec.id;
		int efct_zone_idx = g_gm_deco_model_index[id][1];
		int zone_no = g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id];
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctZoneEsCreate(gMS_DECO_WORK.obj_work, zone_no, efct_zone_idx);
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.dir.z = g_gm_deco_rot_z[dec_rec.id];
		int num = (int)g_gm_deco_user_work[id];
		num <<= 16;
		num >>= 16;
		int num2 = (int)g_gm_deco_user_work[id];
		num2 >>= 16;
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.x = gMS_DECO_WORK.obj_work.pos.x + num * 4096;
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.y = gMS_DECO_WORK.obj_work.pos.y + num2 * 4096;
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.z = gMS_DECO_WORK.obj_work.pos.z + 131072;
		if (gMS_DECO_WORK.obj_3d.command_state == 17)
		{
			gMS_EFFECT_3DES_WORK.obj_3des.command_state = 17u;
		}
		return gMS_DECO_WORK;
	}

