	private static GMS_DECO_WORK gmDecoInitEffect(GMS_EVE_RECORD_DECORATE dec_rec, int x, int y, byte type)
	{
		int id = dec_rec.id;
		GMS_DECO_WORK gMS_DECO_WORK = gmDecoInitNomodel(dec_rec, x, y, type, () => new GMS_DECO_WORK());
		if (gMS_DECO_WORK == null)
