		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctZoneEsCreate(gMS_DECO_WORK.obj_work, zone_no, efct_zone_idx);
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.dir.z = g_gm_deco_rot_z[dec_rec.id];
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.disp_flag |= g_gm_deco_disp_flag[id];
		int user_flag = (int)gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_flag;
		user_flag |= (int)g_gm_deco_user_flag[id];
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_flag = (uint)user_flag;
		user_flag = (int)gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_work;
		user_flag |= (int)g_gm_deco_user_work[id];
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_work = (uint)user_flag;
		gMS_EFFECT_3DES_WORK.obj_3des.command_state = g_gm_deco_command_state[id];
		if (gMS_DECO_WORK.obj_work.ppFunc != null)
		{
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = gMS_DECO_WORK.obj_work.ppFunc;
			gMS_DECO_WORK.obj_work.ppFunc = null;
		}
		return gMS_DECO_WORK;
	}

	private static GMS_DECO_WORK gmDecoInitEffectBlock(GMS_EVE_RECORD_DECORATE dec_rec, int x, int y, byte type)
	{
		int id = dec_rec.id;
		int num = x >> 18;
		num <<= 18;
		int num2 = y >> 18;
		num2 <<= 18;
		GMS_DECO_WORK gMS_DECO_WORK = gmDecoInitNomodel(dec_rec, num, num2, type, () => new GMS_DECO_WORK());
		if (gMS_DECO_WORK == null)
		{
			return null;
		}
		int efct_zone_idx = g_gm_deco_model_index[id][0];
		int zone_no = g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id];
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctZoneEsCreate(gMS_DECO_WORK.obj_work, zone_no, efct_zone_idx);
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.dir.z = g_gm_deco_rot_z[dec_rec.id];
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.disp_flag |= g_gm_deco_disp_flag[id];
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_flag = gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_flag | g_gm_deco_user_flag[id];
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_work = gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_work | g_gm_deco_user_work[id];
		gMS_EFFECT_3DES_WORK.obj_3des.command_state = g_gm_deco_command_state[id];
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_flag = gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_flag | gMS_DECO_WORK.obj_work.user_flag;
		if (gMS_DECO_WORK.obj_work.ppFunc != null)
		{
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = gMS_DECO_WORK.obj_work.ppFunc;
			gMS_DECO_WORK.obj_work.ppFunc = null;
		}
		if ((g_gm_deco_user_flag[id] & 0x100) != 0)
		{
			int num3 = (int)g_gm_deco_user_work[id];
			num3 <<= 16;
			num3 >>= 16;
			int num4 = (int)g_gm_deco_user_work[id];
			num4 >>= 16;
			GmEffect3DESSetDuplicateDraw(gMS_EFFECT_3DES_WORK, num3, num4, 0f);
		}
		return gMS_DECO_WORK;
	}

