		gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_work = gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_work | g_gm_deco_user_work[id];
		gMS_EFFECT_3DES_WORK.obj_3des.command_state = g_gm_deco_command_state[id];
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK2 = GmEfctZoneEsCreate(gMS_DECO_WORK.obj_work, zone_no, num3 + 1);
		gMS_EFFECT_3DES_WORK2.efct_com.obj_work.dir.z = g_gm_deco_rot_z[dec_rec.id];
		gMS_EFFECT_3DES_WORK2.efct_com.obj_work.disp_flag |= g_gm_deco_disp_flag[id];
