		gMS_EFFECT_3DES_WORK2.efct_com.obj_work.user_work = gMS_EFFECT_3DES_WORK2.efct_com.obj_work.user_work | g_gm_deco_user_work[id];
		gMS_EFFECT_3DES_WORK2.obj_3des.command_state = g_gm_deco_command_state[id];
