	private static void gmDecoAddFallEvent(GMS_EVE_RECORD_DECORATE dec_rec, int x, NNS_TEXLIST texlist, float frame)
	{
		if (dec_rec == null)
		{
			return;
		}
		ushort id = dec_rec.id;
		GMS_DECO_FALL_MANAGER gMS_DECO_FALL_MANAGER = null;
		GMS_DECO_FALL_REGISTER gMS_DECO_FALL_REGISTER = null;
		switch (id)
		{
		case 20:
		case 27:
		case 40:
		case 41:
		case 42:
		case 47:
		case 48:
		case 49:
		{
			for (int i = 0; i < 16; i++)
			{
				GMS_DECO_FALL_MANAGER gMS_DECO_FALL_MANAGER2 = g_deco_fall_manager[i];
				if (gMS_DECO_FALL_MANAGER2.dec_id == 0)
				{
					if (gMS_DECO_FALL_MANAGER == null)
					{
						gMS_DECO_FALL_MANAGER = gMS_DECO_FALL_MANAGER2;
					}
				}
				else if (gMS_DECO_FALL_MANAGER2.dec_id == id)
				{
					gMS_DECO_FALL_MANAGER = gMS_DECO_FALL_MANAGER2;
					break;
				}
			}
			gMS_DECO_FALL_MANAGER.dec_id = id;
			gMS_DECO_FALL_MANAGER.texlist = texlist;
			gMS_DECO_FALL_MANAGER.frame = frame;
			gMS_DECO_FALL_MANAGER.all_num++;
			for (int i = 0; i < 8; i++)
			{
				GMS_DECO_FALL_REGISTER gMS_DECO_FALL_REGISTER2 = gMS_DECO_FALL_MANAGER.reg[i];
				if (gMS_DECO_FALL_REGISTER2.num == 0)
				{
					if (gMS_DECO_FALL_REGISTER == null)
					{
						gMS_DECO_FALL_REGISTER = gMS_DECO_FALL_REGISTER2;
					}
				}
				else if (gMS_DECO_FALL_REGISTER2.vec.x == x)
				{
					gMS_DECO_FALL_REGISTER = gMS_DECO_FALL_REGISTER2;
					break;
				}
			}
			if (gMS_DECO_FALL_REGISTER.num == 0)
			{
				gMS_DECO_FALL_MANAGER.reg_num++;
			}
			gMS_DECO_FALL_REGISTER.num++;
			gMS_DECO_FALL_REGISTER.vec.x = x;
			break;
		}
		}
	}

	private static void gmDecoDelFallEvent(GMS_EVE_RECORD_DECORATE dec_rec, int x)
	{
		if (dec_rec == null)
		{
			return;
		}
		ushort id = dec_rec.id;
		switch (id)
		{
		case 20:
		case 27:
		case 40:
		case 41:
		case 42:
		case 47:
		case 48:
		case 49:
		{
			for (int i = 0; i < 16; i++)
			{
				GMS_DECO_FALL_MANAGER gMS_DECO_FALL_MANAGER = g_deco_fall_manager[i];
				if (gMS_DECO_FALL_MANAGER.dec_id != id)
				{
					continue;
				}
				gMS_DECO_FALL_MANAGER.all_num--;
				if (gMS_DECO_FALL_MANAGER.all_num == 0)
				{
					gMS_DECO_FALL_MANAGER.dec_id = 0u;
					gMS_DECO_FALL_MANAGER.texlist = null;
				}
				for (int j = 0; j < 8; j++)
				{
					GMS_DECO_FALL_REGISTER gMS_DECO_FALL_REGISTER = gMS_DECO_FALL_MANAGER.reg[j];
					if (gMS_DECO_FALL_REGISTER.vec.x == x)
					{
						gMS_DECO_FALL_REGISTER.num--;
						if (gMS_DECO_FALL_REGISTER.num == 0)
						{
							gMS_DECO_FALL_REGISTER.vec.x = 0;
							gMS_DECO_FALL_MANAGER.reg_num--;
						}
						break;
					}
				}
				break;
			}
			break;
		}
		}
	}

	private static void gmDecoSetDrawFall(OBS_OBJECT_WORK obj_work)
	{
		if (!GmMainIsDrawEnable())
		{
			return;
		}
		GMS_DECO_WORK gMS_DECO_WORK = (GMS_DECO_WORK)obj_work;
		VecFx32 vecFx = new VecFx32
		{
			x = obj_work.pos.x + obj_work.ofst.x,
			y = -(obj_work.pos.y + obj_work.ofst.y),
			z = obj_work.pos.z + obj_work.ofst.z
		};
		GMS_EVE_RECORD_DECORATE event_record = gMS_DECO_WORK.event_record;
		GMS_DECO_FALL_REGISTER gMS_DECO_FALL_REGISTER = null;
		for (int i = 0; i < 16; i++)
		{
			if (g_deco_fall_manager[i].dec_id != event_record.id)
			{
				continue;
			}
			for (int j = 0; j < 8; j++)
			{
				if (g_deco_fall_manager[i].reg[j].vec.x == vecFx.x)
				{
					gMS_DECO_FALL_REGISTER = g_deco_fall_manager[i].reg[j];
					break;
				}
			}
		}
		if (gMS_DECO_FALL_REGISTER != null)
		{
			gMS_DECO_FALL_REGISTER.vec.z = vecFx.z;
			if (gMS_DECO_FALL_REGISTER.vec.y == 0 || gMS_DECO_FALL_REGISTER.vec.y < vecFx.y)
			{
				gMS_DECO_FALL_REGISTER.vec.y = vecFx.y;
			}
		}
	}

	private static void gmDecoSetDrawPrimitive(int model_index, AOS_TEXTURE model_tex, VecFx32 pos, float off_y, uint command, uint disp_flag)
	{
		if (!GmMainIsDrawEnable())
		{
			return;
		}
		if (gmDecoDataGetInfo().tvx_model_data[model_index] == null)
		{
			AmbChunk data = (AmbChunk)amBindGet(gmDecoDataGetInfo().tvx_model, model_index);
			gmDecoDataGetInfo().tvx_model_data[model_index] = new TVX_FILE(data);
		}
		TVX_FILE file = gmDecoDataGetInfo().tvx_model_data[model_index];
		uint num = AoTvxGetTextureNum(file);
		GMS_DECO_PRIM_DRAW_WORK[] array = g_deco_tvx_work;
		GMS_DECO_PRIM_DRAW_STACK gMS_DECO_PRIM_DRAW_STACK = null;
		for (uint num2 = 0u; num2 < num; num2++)
		{
			uint num3 = AoTvxGetVertexNum(file, num2);
			int num4 = AoTvxGetTextureId(file, num2);
			for (int i = 0; i < 16; i++)
			{
				if ((array[i].tex == null && array[i].tex_id == -1 && array[i].command == uint.MaxValue) || (array[i].tex == model_tex && array[i].tex_id == num4 && array[i].command == command))
				{
					array[i].tex = model_tex;
					array[i].tex_id = num4;
					array[i].command = command;
					array[i].all_vtx_num += (ushort)num3;
					gMS_DECO_PRIM_DRAW_STACK = array[i].stack[array[i].stack_num];
					gMS_DECO_PRIM_DRAW_STACK.vtx = AoTvxGetVertex(file, num2);
					gMS_DECO_PRIM_DRAW_STACK.vtx_num = num3;
					gMS_DECO_PRIM_DRAW_STACK.pos.Assign(pos);
					gMS_DECO_PRIM_DRAW_STACK.off_y = off_y;
					gMS_DECO_PRIM_DRAW_STACK.disp_flag = disp_flag;
					array[i].stack_num++;
					break;
				}
			}
		}
	}

	private static bool gmDecoIsUseModel(int type)
	{
		bool result = false;
		int num = g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id];
		if (type == 0 && 5 != num)
		{
			result = true;
		}
		if (1 == type && (num == 0 || 2 == num))
		{
			result = true;
		}
		return result;
	}

