	public static void ObjDrawAction3DNN(OBS_ACTION3D_NN_WORK obj_3d, VecFx32? pos, VecU16? dir, VecFx32? scale, ref uint? p_disp_flag)
	{
		uint p_disp_flag2 = 0u;
		if (p_disp_flag.HasValue)
		{
			uint? num = p_disp_flag & 0x10;
			if (num.GetValueOrDefault() == 0 && num.HasValue)
			{
				p_disp_flag &= 4261412855u;
			}
			p_disp_flag2 = p_disp_flag.Value;
		}
		if (obj_3d != null && obj_3d._object != null)
		{
			bool flag = false;
			p_disp_flag2 &= 0xDFFFFFFFu;
			if (pos.HasValue && (p_disp_flag2 & 0x11802000) == 0)
			{
				OBS_CAMERA oBS_CAMERA = ObjCameraGet(_g_obj.glb_camera_id);
				float num2 = oBS_CAMERA.disp_pos.x + oBS_CAMERA.bottom;
				float num3 = oBS_CAMERA.disp_pos.x + oBS_CAMERA.top;
				float num4 = 0f - (oBS_CAMERA.disp_pos.y + oBS_CAMERA.top);
				float num5 = 0f - (oBS_CAMERA.disp_pos.y + oBS_CAMERA.bottom);
				float num6 = 1f;
				if ((p_disp_flag2 & 0x10000) == 0)
				{
					int num7 = scale.Value.x;
					int y = scale.Value.y;
					if (num7 < y)
					{
						num7 = y;
					}
					y = scale.Value.z;
					if (num7 < y)
					{
						num7 = y;
					}
					num6 = FX_FX32_TO_F32(num7);
				}
				num6 *= 3.2f;
				float num8 = FX_FX32_TO_F32(pos.Value.x) - obj_3d._object.Radius * 1.2f * num6;
				float num9 = FX_FX32_TO_F32(pos.Value.x) + obj_3d._object.Radius * 1.2f * num6;
				float num10 = FX_FX32_TO_F32(pos.Value.y) - obj_3d._object.Radius * 1.2f * num6;
				float num11 = FX_FX32_TO_F32(pos.Value.y) + obj_3d._object.Radius * 1.2f * num6;
				if (num2 > num9)
				{
					flag = true;
				}
				if (num3 < num8)
				{
					flag = true;
				}
				if (num4 > num11)
				{
					flag = true;
				}
				if (num5 < num10)
				{
					flag = true;
				}
			}
			if (flag)
			{
				p_disp_flag2 |= 0x20000020;
			}
		}
		if ((p_disp_flag2 & 0x40000000) != 0)
		{
			if (p_disp_flag.HasValue)
			{
				p_disp_flag &= 3758096383u;
				p_disp_flag |= p_disp_flag2 & 0x22000008;
			}
			return;
		}
		NNS_MATRIX objDrawAction3DNN_obj_mtx = ObjDrawAction3DNN_obj_mtx;
		VecFx32 vecFx = new VecFx32(4096, 4096, 4096);
		nnMakeUnitMatrix(objDrawAction3DNN_obj_mtx);
		if (pos.HasValue && (p_disp_flag2 & 0x2000) == 0)
		{
			VecFx32 value = pos.Value;
			if ((p_disp_flag2 & 0x200000) == 0)
			{
				value.y = -value.y;
			}
			if ((p_disp_flag2 & 0x80000) == 0)
			{
				if (_g_obj.glb_scale.x != 4096)
				{
					value.x = FX_Mul(value.x, _g_obj.glb_scale.x);
				}
				if (_g_obj.glb_scale.y != 4096)
				{
					value.y = FX_Mul(value.y, _g_obj.glb_scale.y);
				}
				if (_g_obj.glb_scale.z != 4096)
				{
					value.z = FX_Mul(value.z, _g_obj.glb_scale.z);
				}
			}
			nnTranslateMatrix(objDrawAction3DNN_obj_mtx, objDrawAction3DNN_obj_mtx, FX_FX32_TO_F32(value.x), FX_FX32_TO_F32(value.y), FX_FX32_TO_F32(value.z));
		}
		if (dir.HasValue && (p_disp_flag2 & 0x100) == 0)
		{
			if ((p_disp_flag2 & 0x200000) == 0)
			{
				nnRotateXYZMatrix(objDrawAction3DNN_obj_mtx, objDrawAction3DNN_obj_mtx, -dir.Value.x, dir.Value.y, -dir.Value.z);
			}
			else
			{
				nnRotateXYZMatrix(objDrawAction3DNN_obj_mtx, objDrawAction3DNN_obj_mtx, dir.Value.x, dir.Value.y, dir.Value.z);
			}
		}
		if ((p_disp_flag2 & 0x400000) == 0)
		{
			if ((p_disp_flag2 & 0x4000000) == 0)
			{
				if ((p_disp_flag2 & 1) != 0)
				{
					nnRotateYMatrix(objDrawAction3DNN_obj_mtx, objDrawAction3DNN_obj_mtx, 49152);
				}
				else
				{
					nnRotateYMatrix(objDrawAction3DNN_obj_mtx, objDrawAction3DNN_obj_mtx, 16384);
				}
			}
			else
			{
				if ((p_disp_flag2 & 2) != 0)
				{
					nnRotateXMatrix(objDrawAction3DNN_obj_mtx, objDrawAction3DNN_obj_mtx, 32768);
				}
				if ((p_disp_flag2 & 1) != 0)
				{
					nnRotateYMatrix(objDrawAction3DNN_obj_mtx, objDrawAction3DNN_obj_mtx, 32768);
				}
			}
		}
		if (scale.HasValue && (p_disp_flag2 & 0x10000) == 0)
		{
			vecFx = scale.Value;
		}
		if ((p_disp_flag2 & 0x100000) == 0)
		{
			vecFx.x = FX_Mul(vecFx.x, _g_obj.draw_scale.x);
			vecFx.y = FX_Mul(vecFx.y, _g_obj.draw_scale.y);
			vecFx.z = FX_Mul(vecFx.z, _g_obj.draw_scale.z);
		}
		if ((p_disp_flag2 & 0x80000) == 0)
		{
			vecFx.x = FX_Mul(vecFx.x, _g_obj.glb_scale.x);
			vecFx.y = FX_Mul(vecFx.y, _g_obj.glb_scale.y);
			vecFx.z = FX_Mul(vecFx.z, _g_obj.glb_scale.z);
		}
		nnScaleMatrix(objDrawAction3DNN_obj_mtx, objDrawAction3DNN_obj_mtx, FX_FX32_TO_F32(vecFx.x), FX_FX32_TO_F32(vecFx.y), FX_FX32_TO_F32(vecFx.z));
		if ((p_disp_flag2 & 0x800000) != 0)
		{
			nnMultiplyMatrix(objDrawAction3DNN_obj_mtx, obj_3d.user_obj_mtx, objDrawAction3DNN_obj_mtx);
		}
		if ((p_disp_flag2 & 0x1000000) != 0)
		{
			nnMultiplyMatrix(objDrawAction3DNN_obj_mtx, objDrawAction3DNN_obj_mtx, obj_3d.user_obj_mtx_r);
		}
		amMatrixPush(objDrawAction3DNN_obj_mtx);
		if (obj_3d.motion != null && obj_3d.motion.mmobject != null)
		{
			ObjDrawAction3DNNMaterialUpdate(obj_3d, ref p_disp_flag2);
		}
		if (obj_3d.motion != null && obj_3d.motion.mtnbuf[0] != null)
		{
			ObjDrawAction3DNNMotionUpdate(obj_3d, ref p_disp_flag2);
			if (obj_3d.mtn_cb_func != null)
			{
				obj_3d.mtn_cb_func(obj_3d.motion, obj_3d._object, obj_3d.mtn_cb_param);
			}
			if ((p_disp_flag2 & 0x20) == 0)
			{
				AMS_DRAWSTATE draw_state = null;
				if ((p_disp_flag2 & 0x8000000) != 0)
				{
					draw_state = obj_3d.draw_state;
				}
				if (obj_3d.marge == 0f || obj_3d.marge == 1f)
				{
					int num12;
					float num13;
					if (obj_3d.marge == 0f)
					{
						num12 = obj_3d.act_id[0];
						num13 = obj_3d.frame[0];
					}
					else
					{
						num12 = obj_3d.act_id[1];
						num13 = obj_3d.frame[1];
					}
					NNS_MOTION motion = obj_3d.motion.mtnbuf[num12 & 0xFFFF];
					num13 += amMotionGetStartFrame(obj_3d.motion, num12);
					if (obj_3d.motion != null && obj_3d.motion.mmobject != null)
					{
						ObjDraw3DNNMotionMaterialMotion(obj_3d.motion, obj_3d.texlist, obj_3d.drawflag, obj_3d.sub_obj_type, obj_3d.user_func, obj_3d.user_param, obj_3d.command_state, obj_3d.mplt_cb_func, obj_3d.mplt_cb_param, obj_3d.material_cb_func, obj_3d.material_cb_param, draw_state, obj_3d.use_light_flag);
					}
					else
					{
						ObjDraw3DNNDrawMotion(motion, num13, obj_3d._object, obj_3d.texlist, obj_3d.drawflag, obj_3d.sub_obj_type, obj_3d.user_func, obj_3d.user_param, obj_3d.command_state, obj_3d.mplt_cb_func, obj_3d.mplt_cb_param, obj_3d.material_cb_func, obj_3d.material_cb_param, draw_state, obj_3d.use_light_flag);
					}
				}
				else if (obj_3d.motion != null && obj_3d.motion.mmobject != null)
				{
					ObjDraw3DNNMotionMaterialMotion(obj_3d.motion, obj_3d.texlist, obj_3d.drawflag, obj_3d.sub_obj_type, obj_3d.user_func, obj_3d.user_param, obj_3d.command_state, obj_3d.mplt_cb_func, obj_3d.mplt_cb_param, obj_3d.material_cb_func, obj_3d.material_cb_param, draw_state, obj_3d.use_light_flag);
				}
				else
				{
					ObjDraw3DNNMotion(obj_3d.motion, obj_3d.motion._object, obj_3d.texlist, obj_3d.drawflag, obj_3d.sub_obj_type, obj_3d.user_func, obj_3d.user_param, obj_3d.command_state, obj_3d.mplt_cb_func, obj_3d.mplt_cb_param, obj_3d.material_cb_func, obj_3d.material_cb_param, draw_state, obj_3d.use_light_flag);
				}
			}
			obj_3d.user_param = null;
			obj_3d.mplt_cb_param = null;
			obj_3d.material_cb_param = null;
		}
		else
		{
			if ((p_disp_flag2 & 0x20) == 0)
			{
				AMS_DRAWSTATE draw_state2 = null;
				if ((p_disp_flag2 & 0x8000000) != 0)
				{
					draw_state2 = obj_3d.draw_state;
				}
				if (obj_3d.motion != null && obj_3d.motion.mmobject != null)
				{
					ObjDraw3DNNMotionMaterialMotion(obj_3d.motion, obj_3d.texlist, obj_3d.drawflag, obj_3d.sub_obj_type, obj_3d.user_func, obj_3d.user_param, obj_3d.command_state, null, null, obj_3d.material_cb_func, obj_3d.material_cb_param, draw_state2, obj_3d.use_light_flag);
				}
				else
				{
					ObjDraw3DNNModel(obj_3d._object, obj_3d.texlist, obj_3d.drawflag, obj_3d.sub_obj_type, obj_3d.user_func, obj_3d.user_param, obj_3d.command_state, obj_3d.material_cb_func, obj_3d.material_cb_param, draw_state2, obj_3d.use_light_flag);
				}
			}
			obj_3d.user_param = null;
			obj_3d.mplt_cb_param = null;
			obj_3d.material_cb_param = null;
		}
		amMatrixPop();
		if (p_disp_flag.HasValue)
		{
			p_disp_flag &= 3758096383u;
			p_disp_flag |= p_disp_flag2 & 0x22000008;
		}
	}

	public static void ObjDrawAction3DNNMotionUpdate(OBS_ACTION3D_NN_WORK obj_3d, ref uint p_disp_flag)
	{
		uint? p_disp_flag2 = p_disp_flag;
		ObjDrawAction3DNNMotionUpdate(obj_3d, ref p_disp_flag2);
		p_disp_flag = p_disp_flag2.Value;
	}

	public static void ObjDrawAction3DNNMotionUpdate(OBS_ACTION3D_NN_WORK obj_3d, ref uint? p_disp_flag)
	{
		uint num = 0u;
		float num2 = 0f;
		float num3 = 0f;
		if (p_disp_flag.HasValue)
		{
			num = p_disp_flag.Value;
		}
		if ((num & 0x1000) == 0)
		{
			if ((num & 0x10) == 0)
			{
				if ((obj_3d.flag & 1) != 0)
				{
					obj_3d.marge -= obj_3d.blend_spd;
					if (obj_3d.marge <= 0f)
					{
						obj_3d.marge = 0f;
						obj_3d.flag &= 4294967294u;
					}
				}
				if ((num & 0x1010) == 0)
				{
					num2 = obj_3d.speed[0] * FX_FX32_TO_F32(g_obj.speed);
					num3 = obj_3d.speed[1] * FX_FX32_TO_F32(g_obj.speed);
				}
				if (obj_3d.marge < 1f || (obj_3d.flag & 3) != 0)
				{
					obj_3d.frame[0] += num2;
				}
				if ((obj_3d.flag & 1) == 0 && (obj_3d.marge > 0f || (obj_3d.flag & 3) != 0))
				{
					obj_3d.frame[1] += num3;
				}
				if ((num & 4) != 0)
				{
					for (int i = 0; i < 2; i++)
					{
						float num4 = amMotionGetEndFrame(obj_3d.motion, obj_3d.act_id[i]) - amMotionGetStartFrame(obj_3d.motion, obj_3d.act_id[i]);
						while (obj_3d.frame[i] >= num4)
						{
							obj_3d.frame[i] = obj_3d.frame[i] - num4;
							if (i == 0)
							{
								num |= 8;
							}
						}
					}
				}
				else
				{
					for (int i = 0; i < 2; i++)
					{
						float num5 = amMotionGetEndFrame(obj_3d.motion, obj_3d.act_id[i]) - amMotionGetStartFrame(obj_3d.motion, obj_3d.act_id[i]);
						if (obj_3d.frame[i] >= num5 - 1f)
						{
							obj_3d.frame[i] = num5 - 1f;
							if (i == 0)
							{
								num |= 8;
							}
						}
					}
				}
			}
			if (obj_3d.marge < 1f || (obj_3d.flag & 3) != 0)
			{
				amMotionSetFrame(obj_3d.motion, 0, obj_3d.frame[0] + amMotionGetStartFrame(obj_3d.motion, obj_3d.act_id[0]));
			}
			if (obj_3d.marge > 0f || (obj_3d.flag & 3) != 0)
			{
				amMotionSetFrame(obj_3d.motion, 1, obj_3d.frame[1] + amMotionGetStartFrame(obj_3d.motion, obj_3d.act_id[1]));
			}
			amMotionGet(obj_3d.motion, obj_3d.marge, obj_3d.per);
		}
		if (p_disp_flag.HasValue)
		{
			p_disp_flag |= num & 8;
		}
	}

	public static void ObjDrawAction3DNNMaterialUpdate(OBS_ACTION3D_NN_WORK obj_3d, ref uint p_disp_flag)
	{
		uint? p_disp_flag2 = p_disp_flag;
		ObjDrawAction3DNNMaterialUpdate(obj_3d, ref p_disp_flag2);
		p_disp_flag = p_disp_flag2.Value;
	}

	public static void ObjDrawAction3DNNMaterialUpdate(OBS_ACTION3D_NN_WORK obj_3d, ref uint? p_disp_flag)
	{
		uint num = 0u;
		float num2 = 0f;
		if (p_disp_flag.HasValue)
		{
			num = p_disp_flag.Value;
		}
		if ((num & 0x1000) == 0)
		{
			if ((num & 0x10) == 0)
			{
				if ((num & 0x1010) == 0)
				{
					num2 = obj_3d.mat_speed * FX_FX32_TO_F32(g_obj.speed);
				}
				obj_3d.mat_frame += num2;
				if ((num & 4) != 0)
				{
					float num3 = amMotionMaterialGetEndFrame(obj_3d.motion, obj_3d.mat_act_id) - amMotionMaterialGetStartFrame(obj_3d.motion, obj_3d.mat_act_id);
					while (obj_3d.mat_frame >= num3)
					{
						obj_3d.mat_frame -= num3;
						num |= 0x2000000;
					}
				}
				else
				{
					float num4 = amMotionMaterialGetEndFrame(obj_3d.motion, obj_3d.mat_act_id) - amMotionMaterialGetStartFrame(obj_3d.motion, obj_3d.mat_act_id);
					if (obj_3d.mat_frame >= num4 - 1f)
					{
						obj_3d.mat_frame = num4 - 1f;
						num |= 0x2000000;
					}
				}
			}
			amMotionMaterialSetFrame(obj_3d.motion, obj_3d.mat_frame + amMotionMaterialGetStartFrame(obj_3d.motion, obj_3d.mat_act_id));
			amMotionMaterialCalc(obj_3d.motion);
		}
		if (p_disp_flag.HasValue)
		{
			p_disp_flag |= num & 0x2000000;
		}
	}

	public static void ObjDraw3DNNModel(NNS_OBJECT _object, NNS_TEXLIST texlist, uint drawflag, uint sub_obj_type, MPP_VOID_OBJECT_DELEGATE user_func, object user_param, uint command_state, MPP_BOOL_NNSDRAWCALLBACKVAL_OBJECT_DELEGATE material_cb_func, object material_cb_param, AMS_DRAWSTATE draw_state, uint use_light_flag)
	{
		if (GmMainIsDrawEnable())
		{
			OBS_DRAW_PARAM_3DNN_MODEL oBS_DRAW_PARAM_3DNN_MODEL = _ObjDraw3DNNModel_Pool.Alloc();
			NNS_MATRIX mtx = oBS_DRAW_PARAM_3DNN_MODEL.mtx;
			nnCopyMatrix(mtx, amMatrixGetCurrent());
			AMS_PARAM_DRAW_OBJECT param = oBS_DRAW_PARAM_3DNN_MODEL.param;
			param._object = _object;
			if (gmMapTransX != 0f)
			{
				nnScaleMatrix(mtx, mtx, 1.005f, 1.005f, 1f);
			}
			param.mtx = mtx;
			param.sub_obj_type = sub_obj_type;
			param.flag = drawflag;
			param.texlist = texlist;
			param.material_func = null;
			param.scaleZ = 1f;
			oBS_DRAW_PARAM_3DNN_MODEL.state = null;
			if (draw_state != null)
