	public static void ObjDraw3DNNMotionMaterialMotion(AMS_MOTION motion, NNS_TEXLIST texlist, uint drawflag, uint sub_obj_type, MPP_VOID_OBJECT_DELEGATE user_func, object user_param, uint command_state, MPP_VOID_ARRAYNNSMATRIX_NNSOBJECT_OBJECT mplt_cb_func, object mplt_cb_param, MPP_BOOL_NNSDRAWCALLBACKVAL_OBJECT_DELEGATE material_cb_func, object material_cb_param, AMS_DRAWSTATE draw_state, uint use_light_flag)
	{
		if (!GmMainIsDrawEnable())
		{
			return;
		}
		if (motion.mmobject == null)
		{
			ObjDraw3DNNMotion(motion, motion._object, texlist, drawflag, sub_obj_type, user_func, user_param, command_state, mplt_cb_func, mplt_cb_param, material_cb_func, material_cb_param, draw_state, use_light_flag);
			return;
		}
		int node_num = motion.node_num;
		OBS_DRAW_PARAM_3DNN_MOTION oBS_DRAW_PARAM_3DNN_MOTION = amDrawAlloc_OBS_DRAW_PARAM_3DNN_MOTION();
		NNS_MATRIX mtx = oBS_DRAW_PARAM_3DNN_MOTION.mtx;
		mtx.Assign(amMatrixGetCurrent());
		AMS_PARAM_DRAW_MOTION_TRS param = oBS_DRAW_PARAM_3DNN_MOTION.param;
		param.mtx = mtx;
		param.sub_obj_type = sub_obj_type;
		param.flag = drawflag;
		param.texlist = texlist;
		param.trslist = amDrawAlloc_NNS_TRS(node_num);
		param.material_func = null;
		for (int i = 0; i < node_num; i++)
		{
			param.trslist[i] = amDraw_NNS_TRS_Pool.Alloc();
			param.trslist[i].Assign(motion.data[i]);
		}
		param._object = motion._object;
		param.mmotion = motion.mmtn[motion.mmotion_id];
		param.mframe = motion.mmotion_frame;
		int motion_id = motion.mbuf[0].motion_id;
		if (motion.mtnfile[motion_id >> 16].file != null)
		{
			param.motion = motion.mtnfile[motion_id >> 16].motion[motion_id & 0xFFFF];
			param.frame = motion.mbuf[0].frame;
		}
		else
		{
			param.motion = null;
			param.frame = 0f;
		}
		oBS_DRAW_PARAM_3DNN_MOTION.state = null;
		if (draw_state != null)
		{
			oBS_DRAW_PARAM_3DNN_MOTION.state = oBS_DRAW_PARAM_3DNN_MOTION.draw_state;
			oBS_DRAW_PARAM_3DNN_MOTION.draw_state.Assign(draw_state);
		}
		oBS_DRAW_PARAM_3DNN_MOTION.use_light_flag = use_light_flag;
		oBS_DRAW_PARAM_3DNN_MOTION.user_func = user_func;
		oBS_DRAW_PARAM_3DNN_MOTION.user_param = user_param;
		oBS_DRAW_PARAM_3DNN_MOTION.mplt_cb_func = mplt_cb_func;
		oBS_DRAW_PARAM_3DNN_MOTION.mplt_cb_param = mplt_cb_param;
		oBS_DRAW_PARAM_3DNN_MOTION.material_cb_func = material_cb_func;
		oBS_DRAW_PARAM_3DNN_MOTION.material_cb_param = material_cb_param;
		amDrawRegistCommand(command_state, OBD_DRAW_USER_COMMAND_3DNN_MOTION_MATMTN, param);
	}

