	public static uint ObjDraw3DNNGetMaterialUserData(NNS_DRAWCALLBACK_VAL val)
	{
		uint result = 0u;
		switch (val.pMaterial.fType)
		{
		case 8u:
			result = ((NNS_MATERIAL_GLES11_DESC)val.pMaterial.pMaterial).User;
			break;
		case 2u:
			mppAssertNotImpl();
			break;
		case 4u:
			mppAssertNotImpl();
			break;
		case 1u:
			mppAssertNotImpl();
			break;
		default:
			result = 0u;
			break;
		}
		return result;
	}

