	public static void ObjDrawObjectAction3DES(OBS_OBJECT_WORK obj_work, OBS_ACTION3D_ES_WORK obj_3des)
	{
		VecFx32 value = default(VecFx32);
		VecU16 dir = default(VecU16);
		value.Assign(obj_work.pos);
		dir.Assign(obj_work.dir);
		value.x += obj_work.ofst.x;
		value.y += obj_work.ofst.y;
		value.z += obj_work.ofst.z;
		if (obj_work.dir_fall != 0)
		{
			dir.z += obj_work.dir_fall;
		}
		ObjDrawAction3DES(obj_3des, value, ref dir, obj_work.scale, ref obj_work.disp_flag);
	}

	public static void ObjDrawAction3DES(OBS_ACTION3D_ES_WORK obj_3des, VecFx32? pos, ref VecU16 dir, VecFx32? scale, ref uint p_disp_flag)
	{
		uint? p_disp_flag2 = p_disp_flag;
		ObjDrawAction3DES(obj_3des, pos, dir, scale, ref p_disp_flag2);
		p_disp_flag = p_disp_flag2.Value;
	}

	public static void ObjDrawAction3DES(OBS_ACTION3D_ES_WORK obj_3des, VecFx32? pos, VecU16? dir, VecFx32? scale, ref uint? p_disp_flag)
	{
		if (obj_3des.ecb == null)
		{
			return;
		}
		uint num = 0u;
		NNS_MATRIX nNS_MATRIX = amDrawAlloc_NNS_MATRIX();
		NNS_QUATERNION pQuat = default(NNS_QUATERNION);
		NNS_QUATERNION pQuat2 = default(NNS_QUATERNION);
		NNS_QUATERNION pQuat3 = default(NNS_QUATERNION);
		NNS_QUATERNION pQuat4 = default(NNS_QUATERNION);
		vec_posObjDrawAction3DES.w = 0f;
		amQuatInit(ref pQuat);
		amVectorInit(ref vecObjDrawAction3DES);
		nnMakeUnitMatrix(nNS_MATRIX);
		if (p_disp_flag.HasValue)
		{
			num = p_disp_flag.Value;
			if ((p_disp_flag.Value & 0x10) == 0)
			{
				p_disp_flag &= 4294967287u;
			}
		}
		amQuatEulerToQuatXYZ(ref pQuat2, obj_3des.disp_rot.x, obj_3des.disp_rot.y, obj_3des.disp_rot.z);
		if ((num & 0x400000) == 0)
		{
			if ((num & 1) != 0)
			{
				if ((obj_3des.flag & 4) != 0)
				{
					amQuatEulerToQuatXYZ(ref pQuat3, NNM_DEGtoA32(0f), NNM_DEGtoA32(0f), NNM_DEGtoA32(270f));
				}
				else
				{
					amQuatEulerToQuatXYZ(ref pQuat3, NNM_DEGtoA32(0f), NNM_DEGtoA32(270f), NNM_DEGtoA32(0f));
				}
			}
			else if ((obj_3des.flag & 4) != 0)
			{
				amQuatEulerToQuatXYZ(ref pQuat3, NNM_DEGtoA32(0f), NNM_DEGtoA32(0f), NNM_DEGtoA32(90f));
			}
			else
			{
				amQuatEulerToQuatXYZ(ref pQuat3, NNM_DEGtoA32(0f), NNM_DEGtoA32(90f), NNM_DEGtoA32(0f));
			}
		}
		else
		{
			amQuatInit(ref pQuat3);
		}
		if (dir.HasValue && (num & 0x100) == 0)
		{
			if ((num & 0x200000) == 0)
			{
				amQuatEulerToQuatXYZ(ref pQuat4, -dir.Value.x, dir.Value.y, -dir.Value.z);
			}
			else
			{
				amQuatEulerToQuatXYZ(ref pQuat4, dir.Value.x, dir.Value.y, dir.Value.z);
			}
			if ((obj_3des.flag & 0x20) != 0)
			{
				nnMultiplyQuaternion(ref pQuat4, ref pQuat4, ref obj_3des.user_dir_quat);
			}
		}
		else
		{
			amQuatInit(ref pQuat4);
		}
		vec_dispObjDrawAction3DES.w = 0f;
		amVectorSet(out vec_dispObjDrawAction3DES, obj_3des.disp_ofst.x, obj_3des.disp_ofst.y, obj_3des.disp_ofst.z);
		if (pos.HasValue)
		{
			VecFx32 value = pos.Value;
			if ((num & 0x200000) == 0)
			{
				value.y = -value.y;
			}
			amVectorSet(out vec_posObjDrawAction3DES, FX_FX32_TO_F32(value.x), FX_FX32_TO_F32(value.y), FX_FX32_TO_F32(value.z));
		}
		else
		{
			amVectorInit(ref vec_posObjDrawAction3DES);
		}
		amVectorOne(ref vec_scaleObjDrawAction3DES);
		if (scale.HasValue && (num & 0x10000) == 0)
		{
			if ((obj_3des.flag & 8) != 0)
			{
				amVectorSet(out vec_scaleObjDrawAction3DES, FX_FX32_TO_F32(scale.Value.x), FX_FX32_TO_F32(scale.Value.y), FX_FX32_TO_F32(scale.Value.z));
				amEffectSetSizeRate(obj_3des.ecb, 1f);
			}
			else
			{
				amEffectSetSizeRate(obj_3des.ecb, FX_FX32_TO_F32(scale.Value.x));
			}
		}
		if ((obj_3des.flag & 1) != 0)
		{
			amVectorAdd(ref vecObjDrawAction3DES, ref vec_dispObjDrawAction3DES, ref vecObjDrawAction3DES);
			amQuatMulti(ref pQuat, ref pQuat3, ref pQuat);
			amQuatMulti(ref pQuat, ref pQuat4, ref pQuat);
			SNNS_MATRIX dst;
			nnMakeQuaternionMatrix(out dst, ref pQuat);
			SNNS_VECTOR dst2 = default(SNNS_VECTOR);
			dst2.x = vecObjDrawAction3DES.x;
			dst2.y = vecObjDrawAction3DES.y;
			dst2.z = vecObjDrawAction3DES.z;
			nnTransformVector(ref dst2, ref dst, ref dst2);
			vecObjDrawAction3DES.x = dst2.x;
			vecObjDrawAction3DES.y = dst2.y;
			vecObjDrawAction3DES.z = dst2.z;
			amQuatMulti(ref pQuat, ref pQuat, ref pQuat2);
			if ((obj_3des.flag & 0x10) != 0)
			{
				amEffectSetRotate(obj_3des.ecb, ref pQuat, 1);
			}
			else
			{
				amEffectSetRotate(obj_3des.ecb, ref pQuat);
			}
			SNNS_MATRIX dst3;
			nnMakeScaleMatrix(out dst3, vec_scaleObjDrawAction3DES.x, vec_scaleObjDrawAction3DES.y, vec_scaleObjDrawAction3DES.z);
			nnMultiplyMatrix(nNS_MATRIX, ref dst3, nNS_MATRIX);
			if ((obj_3des.flag & 2) != 0)
			{
				SNNS_MATRIX dst4;
				nnMakeTranslateMatrix(out dst4, vec_posObjDrawAction3DES.x, vec_posObjDrawAction3DES.y, vec_posObjDrawAction3DES.z);
				nnMultiplyMatrix(nNS_MATRIX, ref dst4, nNS_MATRIX);
			}
			else
			{
				amVectorAdd(ref vecObjDrawAction3DES, ref vec_posObjDrawAction3DES, ref vecObjDrawAction3DES);
			}
			amEffectSetTranslate(obj_3des.ecb, ref vecObjDrawAction3DES);
		}
		else
		{
			amQuatMulti(ref pQuat, ref pQuat3, ref pQuat);
			amQuatMulti(ref pQuat, ref pQuat4, ref pQuat);
			nnMakeQuaternionMatrix(nNS_MATRIX, ref pQuat);
			SNNS_VECTOR vec = default(SNNS_VECTOR);
			vec.x = vec_posObjDrawAction3DES.x;
			vec.y = vec_posObjDrawAction3DES.y;
			vec.z = vec_posObjDrawAction3DES.z;
			nnCopyVectorMatrixTranslation(nNS_MATRIX, ref vec);
			SNNS_MATRIX dst5;
			nnMakeScaleMatrix(out dst5, vec_scaleObjDrawAction3DES.x, vec_scaleObjDrawAction3DES.y, vec_scaleObjDrawAction3DES.z);
			nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX, ref dst5);
			SNNS_MATRIX dst6;
			nnMakeTranslateMatrix(out dst6, vec_dispObjDrawAction3DES.x, vec_dispObjDrawAction3DES.y, vec_dispObjDrawAction3DES.z);
			nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX, ref dst6);
			SNNS_MATRIX dst7;
			nnMakeQuaternionMatrix(out dst7, ref pQuat2);
			nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX, ref dst7);
		}
		ObjDraw3DESSetCamera(obj_3des, nNS_MATRIX);
		ObjDraw3DESMatrixPush(nNS_MATRIX, obj_3des.command_state);
		float speed = amEffectGetUnitFrame();
		if ((num & 0x1000) == 0)
		{
			if ((num & 0x10) != 0)
			{
				amEffectSetUnitTime(0f, 60);
			}
			else
			{
				amEffectSetUnitTime(obj_3des.speed * FX_FX32_TO_F32(_g_obj.speed), 60);
			}
			amEffectUpdate(obj_3des.ecb);
			if (amEffectIsDelete(obj_3des.ecb) != 0)
			{
				obj_3des.ecb = null;
				if (p_disp_flag.HasValue)
				{
					p_disp_flag |= 8u;
				}
			}
		}
		amEffectSetUnitTime(speed, 60);
		if ((num & 0x20) == 0 && obj_3des.ecb != null)
		{
			ObjDraw3DESEffect(obj_3des.ecb, obj_3des.texlist, obj_3des.command_state);
			if ((obj_3des.flag & 0x40) != 0)
			{
				NNS_MATRIX nNS_MATRIX2 = amDrawAlloc_NNS_MATRIX();
				nnMakeTranslateMatrix(nNS_MATRIX2, obj_3des.dup_draw_ofst.x, obj_3des.dup_draw_ofst.y, obj_3des.dup_draw_ofst.z);
				nnMultiplyMatrix(nNS_MATRIX2, nNS_MATRIX2, nNS_MATRIX);
				ObjDraw3DESMatrixPop(obj_3des.command_state);
				ObjDraw3DESSetCamera(obj_3des, nNS_MATRIX2);
				ObjDraw3DESMatrixPush(nNS_MATRIX2, obj_3des.command_state);
				ObjDraw3DESEffect(obj_3des.ecb, obj_3des.texlist, obj_3des.command_state);
			}
		}
		ObjDraw3DESMatrixPop(obj_3des.command_state);
	}

