	public static void ObjDrawObjectAction2DAMA(OBS_OBJECT_WORK obj_work, OBS_ACTION2D_AMA_WORK obj_2d)
	{
		if (GmMainIsDrawEnable())
		{
			VecFx32 value = new VecFx32(obj_work.pos);
			new VecU16(obj_work.dir);
			value.x += obj_work.ofst.x;
			value.y += obj_work.ofst.y;
			value.z += obj_work.ofst.z;
			ObjDrawAction2DAMA(obj_2d, value, obj_work.dir, obj_work.scale, ref obj_work.disp_flag);
		}
	}

	public static void ObjDrawAction2DAMA(OBS_ACTION2D_AMA_WORK obj_2d, VecFx32? pos, VecU16? dir, VecFx32? scale, ref uint p_disp_flag)
	{
		uint num = 0u;
		if (!GmMainIsDrawEnable())
		{
			return;
		}
		if (p_disp_flag != 0)
		{
			if ((p_disp_flag & 0x10) == 0)
			{
				p_disp_flag &= 4294967287u;
			}
			num = p_disp_flag;
		}
		AoActSetTexture(obj_2d.texlist);
		AOS_ACT_ACM objDrawAction2DAMA_acm = ObjDrawAction2DAMA_acm;
		AoActAcmInit(objDrawAction2DAMA_acm);
		if (pos.HasValue && (num & 0x2000) == 0)
		{
			objDrawAction2DAMA_acm.trans_x = FXM_FX32_TO_FLOAT(pos.Value.x);
			objDrawAction2DAMA_acm.trans_y = FXM_FX32_TO_FLOAT(pos.Value.y);
			objDrawAction2DAMA_acm.trans_z = FXM_FX32_TO_FLOAT(pos.Value.z);
		}
		if (dir.HasValue && (num & 0x100) == 0)
		{
			objDrawAction2DAMA_acm.rotate = NNM_A32toDEG(dir.Value.z);
		}
		if (scale.HasValue && (num & 0x10000) == 0)
		{
			objDrawAction2DAMA_acm.scale_x = FXM_FX32_TO_FLOAT(scale.Value.x);
			objDrawAction2DAMA_acm.scale_y = FXM_FX32_TO_FLOAT(scale.Value.y);
		}
		objDrawAction2DAMA_acm.color = obj_2d.color;
		objDrawAction2DAMA_acm.fade = obj_2d.fade;
		AoActAcmPush(objDrawAction2DAMA_acm);
		if ((num & 0x1000) == 0)
		{
			float frame = obj_2d.speed * FX_FX32_TO_F32(g_obj.speed) * GmMainGetDrawMotionSpeed();
			if (obj_2d.act.frame == obj_2d.frame)
			{
				AoActUpdate(obj_2d.act, frame);
				obj_2d.frame = obj_2d.act.frame;
			}
			else
			{
				AoActSetFrame(obj_2d.act, obj_2d.frame);
				AoActUpdate(obj_2d.act, 0f);
			}
			if ((num & 4) != 0)
			{
				if (AoActIsEnd(obj_2d.act))
				{
					obj_2d.frame = 0f;
					num |= 8;
				}
			}
			else if (AoActIsEnd(obj_2d.act))
			{
				num |= 8;
			}
		}
		if ((num & 0x20) == 0)
		{
			AoActSortRegAction(obj_2d.act);
		}
		AoActAcmPop(1u);
		p_disp_flag |= num & 8;
	}

	public static void ObjDrawAction2DAMADrawStart()
