	public static void objDrawStart_DT(AMS_TCB tcb)
	{
		nnSetAmbientColor(g_obj.ambient_color.r, g_obj.ambient_color.g, g_obj.ambient_color.b);
		for (int i = 0; i < NNE_LIGHT_MAX; i++)
		{
			if ((g_obj.def_user_light_flag & (1 << i)) != 0)
			{
				nnSetLight(i, g_obj.light[i].light_param, g_obj.light[i].light_type);
				nnSetLightSwitch(i, 1);
			}
			else
			{
				nnSetLightSwitch(i, 0);
			}
		}
		nnPutLightSettings();
		for (int i = 0; (long)i < 18L; i++)
		{
			if (obj_draw_3dnn_command_state_tbl[i] != uint.MaxValue)
			{
				amDrawExecCommand(obj_draw_3dnn_command_state_tbl[i], g_obj.drawflag);
				if (obj_draw_3dnn_command_state_exe_end_scene_tbl[i])
				{
					amDrawEndScene();
				}
			}
		}
	}

	public static void objDraw3DNNSetCamera(OBS_CAMERA obj_camera, int proj_type, uint command_state)
	{
		OBS_DRAW_PARAM_3DNN_SET_CAMERA oBS_DRAW_PARAM_3DNN_SET_CAMERA = _objDraw3DNNSetCamera_Pool.Alloc();
		oBS_DRAW_PARAM_3DNN_SET_CAMERA.proj_type = proj_type;
		if (obj_camera != null)
		{
			switch (proj_type)
			{
			default:
				oBS_DRAW_PARAM_3DNN_SET_CAMERA.prj_mtx.Assign(obj_camera.prj_pers_mtx);
				break;
			case 1:
				oBS_DRAW_PARAM_3DNN_SET_CAMERA.prj_mtx.Assign(obj_camera.prj_ortho_mtx);
				break;
			}
			oBS_DRAW_PARAM_3DNN_SET_CAMERA.view_mtx.Assign(obj_camera.view_mtx);
		}
		else
		{
			NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
			NNS_MATRIX nNS_MATRIX2 = GlobalPool<NNS_MATRIX>.Alloc();
			NNS_CAMERAPTR nNS_CAMERAPTR = new NNS_CAMERAPTR();
			NNS_CAMERA_TARGET_ROLL nNS_CAMERA_TARGET_ROLL = new NNS_CAMERA_TARGET_ROLL();
			NNS_VECTOR vec = new NNS_VECTOR(0f, 0f, 0f);
			nNS_CAMERAPTR.fType = 255u;
			nNS_CAMERAPTR.pCamera = nNS_CAMERA_TARGET_ROLL;
			nNS_CAMERA_TARGET_ROLL.Target.Assign(vec);
			nNS_CAMERA_TARGET_ROLL.Position.Assign(nNS_CAMERA_TARGET_ROLL.Target);
			nNS_CAMERA_TARGET_ROLL.Position.z += 50f;
			nNS_CAMERA_TARGET_ROLL.Position.x += 0f;
			nNS_CAMERA_TARGET_ROLL.Roll = NNM_DEGtoA32(0f);
			nNS_CAMERA_TARGET_ROLL.Fovy = NNM_DEGtoA32(45f);
			nNS_CAMERA_TARGET_ROLL.Aspect = AMD_SCREEN_ASPECT;
			nNS_CAMERA_TARGET_ROLL.ZNear = 1f;
			nNS_CAMERA_TARGET_ROLL.ZFar = 60000f;
			switch (proj_type)
			{
			default:
				nnMakePerspectiveMatrix(nNS_MATRIX2, nNS_CAMERA_TARGET_ROLL.Fovy, nNS_CAMERA_TARGET_ROLL.Aspect, nNS_CAMERA_TARGET_ROLL.ZNear, nNS_CAMERA_TARGET_ROLL.ZFar);
				oBS_DRAW_PARAM_3DNN_SET_CAMERA.prj_mtx.Assign(nNS_MATRIX2);
				break;
			case 1:
			{
				float num = 5f / 64f * CAMERA_ZOOM;
				float num2 = g_obj.disp_height * num * 0.5f;
				float num3 = num2 * nNS_CAMERA_TARGET_ROLL.Aspect;
				nnMakeOrthoMatrix(nNS_MATRIX2, 0f - num2, num2, 0f - num3, num3, nNS_CAMERA_TARGET_ROLL.ZNear, nNS_CAMERA_TARGET_ROLL.ZFar);
				oBS_DRAW_PARAM_3DNN_SET_CAMERA.prj_mtx.Assign(nNS_MATRIX2);
				break;
			}
			}
			nnMakeTargetRollCameraViewMatrix(nNS_MATRIX, nNS_CAMERA_TARGET_ROLL);
			oBS_DRAW_PARAM_3DNN_SET_CAMERA.view_mtx.Assign(nNS_MATRIX);
		}
		amEffectSetWorldViewMatrix(oBS_DRAW_PARAM_3DNN_SET_CAMERA.view_mtx);
		amDrawRegistCommand(command_state, OBD_DRAW_USER_COMMAND_3DNN_SET_CAMERA, oBS_DRAW_PARAM_3DNN_SET_CAMERA);
	}

	public static void objDraw3DNNModel_DT(AMS_COMMAND_HEADER command, uint drawflag)
	{
		NNS_MATRIX nNS_MATRIX = amDrawAlloc_NNS_MATRIX();
		amMatrixPush();
		OBS_DRAW_PARAM_3DNN_MODEL oBS_DRAW_PARAM_3DNN_MODEL = ((!(command.param is AMS_PARAM_DRAW_OBJECT)) ? ((OBS_DRAW_PARAM_3DNN_MODEL)command.param) : ((OBS_DRAW_PARAM_3DNN_MODEL)(AMS_PARAM_DRAW_OBJECT)command.param));
		uint alternativeLighting = oBS_DRAW_PARAM_3DNN_MODEL.use_light_flag & 0x18000;
		if ((g_obj.def_user_light_flag ^ oBS_DRAW_PARAM_3DNN_MODEL.use_light_flag) != 0)
		{
			objDrawSetDrawLight(oBS_DRAW_PARAM_3DNN_MODEL.use_light_flag);
		}
		if (oBS_DRAW_PARAM_3DNN_MODEL.user_func != null)
		{
			oBS_DRAW_PARAM_3DNN_MODEL.user_func(oBS_DRAW_PARAM_3DNN_MODEL.user_param);
		}
		AMS_PARAM_DRAW_OBJECT param = oBS_DRAW_PARAM_3DNN_MODEL.param;
		int nNode = param._object.nNode;
		OBS_DRAW_PARAM_3DNN_SORT_MODEL_Pool.Alloc();
		if (_objDraw3DNNModel_DT.plt_mtx == null || _objDraw3DNNModel_DT.plt_mtx.Length < nNode)
		{
			_objDraw3DNNModel_DT.plt_mtx = new NNS_MATRIX[nNode];
			for (int i = 0; i < nNode; i++)
			{
				_objDraw3DNNModel_DT.plt_mtx[i] = GlobalPool<NNS_MATRIX>.Alloc();
			}
		}
		NNS_MATRIX[] plt_mtx = _objDraw3DNNModel_DT.plt_mtx;
		if (_objDraw3DNNModel_DT.nstat == null || _objDraw3DNNModel_DT.nstat.Length < ((nNode + 3) & -4))
		{
			_objDraw3DNNModel_DT.nstat = new uint[(nNode + 3) & -4];
		}
		uint[] nstat = _objDraw3DNNModel_DT.nstat;
		if (param.mtx != null)
		{
			nnMultiplyMatrix(nNS_MATRIX, amMatrixGetCurrent(), param.mtx);
			nnMultiplyMatrix(nNS_MATRIX, _am_draw_world_view_matrix, nNS_MATRIX);
		}
		else
		{
			nnMultiplyMatrix(nNS_MATRIX, _am_draw_world_view_matrix, amMatrixGetCurrent());
		}
		nnSetUpNodeStatusList(nstat, nNode, 0u);
		nnCalcMatrixPalette(plt_mtx, nstat, param._object, nNS_MATRIX, _am_default_stack, 1u);
		if (param.texlist != null)
		{
			nnSetTextureList(param.texlist);
		}
		if (oBS_DRAW_PARAM_3DNN_MODEL.state != null)
		{
			amDrawPushState();
			amDrawSetState(oBS_DRAW_PARAM_3DNN_MODEL.state);
		}
		if (oBS_DRAW_PARAM_3DNN_MODEL.material_cb_func != null)
		{
			objDraw3DNNSetMaterialCallback(oBS_DRAW_PARAM_3DNN_MODEL.material_cb_func, oBS_DRAW_PARAM_3DNN_MODEL.material_cb_param);
		}
		if (command.command_id == OBD_DRAW_USER_COMMAND_3DNN_MODEL)
		{
			nnDrawObject(param._object, plt_mtx, nstat, param.sub_obj_type | 0x100 | 0x200 | 7, param.flag | drawflag | amDrawGetState().drawflag, alternativeLighting);
		}
		else
		{
			nnDrawMaterialMotionObject(param._object, plt_mtx, nstat, param.sub_obj_type | 0x100 | 0x200 | 7, param.flag | drawflag | amDrawGetState().drawflag);
		}
		if (oBS_DRAW_PARAM_3DNN_MODEL.material_cb_func != null)
		{
			objDraw3DNNSetMaterialCallback(null, null);
		}
		if (oBS_DRAW_PARAM_3DNN_MODEL.state != null)
		{
			amDrawPopState();
		}
		if ((g_obj.def_user_light_flag ^ oBS_DRAW_PARAM_3DNN_MODEL.use_light_flag) != 0)
		{
			objDrawSetDefaultLight();
		}
		amMatrixPop();
	}

