			if ((use_light_flag & (1 << i)) != 0)
			{
				nnSetLight(i, g_obj.light[i].light_param, g_obj.light[i].light_type);
				nnSetLightSwitch(i, 1);
			}
			else
			{
				nnSetLightSwitch(i, 0);
			}
		}
		nnPutLightSettings();
	}

