	public static void nnMultiplyQuaternion(ref NNS_QUATERNION dst, ref NNS_QUATERNION quat1, ref NNS_QUATERNION quat2)
	{
		float x = quat1.x;
		float y = quat1.y;
		float z = quat1.z;
		float w = quat1.w;
		float x2 = quat2.x;
		float y2 = quat2.y;
		float z2 = quat2.z;
		float w2 = quat2.w;
		dst.x = w * x2 + x * w2 + y * z2 - z * y2;
		dst.y = w * y2 - x * z2 + y * w2 + z * x2;
		dst.z = w * z2 + x * y2 - y * x2 + z * w2;
		dst.w = w * w2 - x * x2 - y * y2 - z * z2;
	}

	public static int nnNormalizeQuaternion(ref NNS_QUATERNION dst, ref NNS_QUATERNION src)
	{
		float num = src.x * src.x + src.y * src.y + src.z * src.z + src.w * src.w;
		if (num == 0f)
		{
			dst.x = 0f;
			dst.y = 0f;
			dst.z = 0f;
			dst.w = 0f;
			return 0;
		}
		num = nnInvertSqrt(num);
		dst.x = src.x * num;
		dst.y = src.y * num;
		dst.z = src.z * num;
		dst.w = src.w * num;
		return 1;
	}

	public static int nnInvertQuaternion(ref NNS_QUATERNION dst, ref NNS_QUATERNION src)
	{
		float num = src.x * src.x + src.y * src.y + src.z * src.z + src.w * src.w;
		if (num == 0f)
		{
			dst.x = 0f;
			dst.y = 0f;
			dst.z = 0f;
			dst.w = 0f;
			return 0;
		}
		float num2 = 1f / num;
		dst.x = (0f - src.x) * num2;
		dst.y = (0f - src.y) * num2;
		dst.z = (0f - src.z) * num2;
		dst.w = src.w * num2;
		return 1;
	}

	private static void nnLogQuaternion(ref NNS_QUATERNION dst, ref NNS_QUATERNION src)
	{
