			dst.y = NNM_A32toRAD(num) * src.y * num3;
			dst.z = NNM_A32toRAD(num) * src.z * num3;
			dst.w = 0f;
		}
		else
		{
			dst.x = 0f;
			dst.y = 0f;
			dst.z = 0f;
			dst.w = 0f;
		}
	}

	public static void nnExpQuaternion(ref NNS_QUATERNION dst, ref NNS_QUATERNION src)
	{
