	private static void nnSplineQuaternion(ref NNS_QUATERNION dst, ref NNS_QUATERNION quatprev, ref NNS_QUATERNION quat, ref NNS_QUATERNION quatnext)
	{
		NNS_QUATERNION dst2 = default(NNS_QUATERNION);
		NNS_QUATERNION dst3 = default(NNS_QUATERNION);
