		dst2.y = (dst4.y + dst5.y) / -4f;
		dst2.z = (dst4.z + dst5.z) / -4f;
		dst2.w = (dst4.w + dst5.w) / -4f;
		nnExpQuaternion(ref dst2, ref dst2);
		nnMultiplyQuaternion(ref dst, ref quat, ref dst2);
	}

	private static void nnLerpQuaternion(ref NNS_QUATERNION dst, ref NNS_QUATERNION quat1, ref NNS_QUATERNION quat2, float t)
	{
