			src.y = quat1.y * num + quat2.y * t;
			src.z = quat1.z * num + quat2.z * t;
			src.w = quat1.w * num + quat2.w * t;
		}
		else
		{
			src.x = quat1.x * num - quat2.x * t;
			src.y = quat1.y * num - quat2.y * t;
			src.z = quat1.z * num - quat2.z * t;
			src.w = quat1.w * num - quat2.w * t;
		}
