		float num2 = 1f - t;
		float num3 = quat1.x * quat2.x + quat1.y * quat2.y + quat1.z * quat2.z + quat1.w * quat2.w;
		if (num3 < 0f)
		{
			num3 = 0f - num3;
			num = 0f - num;
