		float num6;
		float num7;
		if (num3 < 0.99999f)
		{
			float num4 = 2f - 2.828427f * nnInvertSqrt(1f + num3);
			float num5 = num4 * t;
			num6 = num2 * (1f - num5);
			num7 = (0f - num5) * num2 + t;
			float num8 = nnInvertSqrt(num6 * num6 + num7 * num7 + 2f * num6 * num7 * num3);
			num6 *= num8;
			num7 *= num8 * num;
		}
		else
		{
			num6 = num2;
			num7 = t * num;
		}
		dst.x = quat1.x * num6 + quat2.x * num7;
		dst.y = quat1.y * num6 + quat2.y * num7;
		dst.z = quat1.z * num6 + quat2.z * num7;
		dst.w = quat1.w * num6 + quat2.w * num7;
	}

	private void nnSlerpNoInvQuaternion(ref NNS_QUATERNION dst, ref NNS_QUATERNION q1, ref NNS_QUATERNION q2, float t)
	{
		float num = q1.x * q2.x + q1.y * q2.y + q1.z * q2.z + q1.w * q2.w;
		float num5;
		float num6;
		if (num >= -0.98f && num <= 0.98f)
		{
			int num2 = nnArcCos(num);
			float num3 = nnSin(num2);
			float num4 = 1f / num3;
			num5 = nnSin((int)((float)num2 * (1f - t))) * num4;
			num6 = nnSin((int)((float)num2 * t)) * num4;
		}
		else
		{
			num5 = 1f - t;
			num6 = t;
		}
		dst.x = q1.x * num5 + q2.x * num6;
		dst.y = q1.y * num5 + q2.y * num6;
		dst.z = q1.z * num5 + q2.z * num6;
		dst.w = q1.w * num5 + q2.w * num6;
