	private static void nnSquadQuaternion(ref NNS_QUATERNION dst, ref NNS_QUATERNION quat1, ref NNS_QUATERNION quata, ref NNS_QUATERNION quatb, ref NNS_QUATERNION quat2, float t)
	{
