			{
				for (OBS_OBJECT_WORK oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, num2); oBS_OBJECT_WORK != null; oBS_OBJECT_WORK = ObjObjectSearchRegistObject(oBS_OBJECT_WORK, num2))
