	private static void gmGmkUpBumperStart(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_UPBUMPER_WORK gMS_GMK_UPBUMPER_WORK = (GMS_GMK_UPBUMPER_WORK)obj_work;
		gMS_GMK_UPBUMPER_WORK.gmk_work.ene_com.rect_work[0].flag &= 4294967291u;
		gMS_GMK_UPBUMPER_WORK.gmk_work.ene_com.rect_work[1].flag &= 4294967291u;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_GMK_UPBUMPER_WORK.gmk_work.ene_com.rect_work[2];
		oBS_RECT_WORK.ppDef = gmGmkUpBumperHit;
		oBS_RECT_WORK.ppHit = null;
		ObjRectAtkSet(oBS_RECT_WORK, 0, 0);
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		ObjRectWorkSet(oBS_RECT_WORK, GmkUpBumperData.tbl_gm_gmk_upbumper_rect[gMS_GMK_UPBUMPER_WORK.obj_type][0], GmkUpBumperData.tbl_gm_gmk_upbumper_rect[gMS_GMK_UPBUMPER_WORK.obj_type][1], GmkUpBumperData.tbl_gm_gmk_upbumper_rect[gMS_GMK_UPBUMPER_WORK.obj_type][2], GmkUpBumperData.tbl_gm_gmk_upbumper_rect[gMS_GMK_UPBUMPER_WORK.obj_type][3]);
		obj_work.flag &= 4294967293u;
		obj_work.ppFunc = gmGmkUpBumperStay;
	}

	private static void gmGmkUpBumperStay(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_UPBUMPER_WORK gMS_GMK_UPBUMPER_WORK = (GMS_GMK_UPBUMPER_WORK)obj_work;
		if (gMS_GMK_UPBUMPER_WORK.player_spd_keep_timer_mine <= 0)
		{
			return;
		}
		if (gMS_GMK_UPBUMPER_WORK.player_spd_keep_timer_mine > player_spd_keep_timer)
		{
			gMS_GMK_UPBUMPER_WORK.player_spd_keep_timer_mine = player_spd_keep_timer;
			player_spd_keep_timer--;
			if (player_spd_keep_timer <= 0)
			{
				gMS_GMK_UPBUMPER_WORK.player_spd_keep_timer_mine = 0;
				player_spd_keep_timer = 0;
				player_spd_x = (player_spd_y = 0);
			}
		}
		else
		{
			gMS_GMK_UPBUMPER_WORK.player_spd_keep_timer_mine = 0;
		}
	}

	private static void gmGmkUpBumperHit(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_GMK_UPBUMPER_WORK gMS_GMK_UPBUMPER_WORK = (GMS_GMK_UPBUMPER_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_PLAYER_WORK == g_gm_main_system.ply_work[0])
		{
			int spd_y = 0;
			int num;
			if (player_spd_keep_timer <= 0)
			{
				num = 0;
				for (uint num2 = 0u; num2 < GMD_GMK_UPBUMPER_REBOUND_DATA_NUM; num2++)
				{
					if (gMS_PLAYER_WORK.act_state == tbl_upbmper_rebound_data[num2].act_state)
					{
						num = tbl_upbmper_rebound_data[num2].spd_x;
						spd_y = tbl_upbmper_rebound_data[num2].spd_y;
						player_spd_x = num;
						player_spd_y = spd_y;
						player_spd_keep_timer = 60;
						gMS_GMK_UPBUMPER_WORK.player_spd_keep_timer_mine = (short)(player_spd_keep_timer + 1);
						break;
					}
				}
				if (num == 0)
				{
					num = MTM_MATH_ABS(gMS_PLAYER_WORK.obj_work.spd.x);
					num += num >> 3;
					if (num > 32768)
					{
						num = 32768;
					}
					if (num < 16384)
					{
						num = 16384;
					}
					spd_y = -16384;
				}
			}
			else
			{
				num = player_spd_x;
				spd_y = player_spd_y;
				player_spd_keep_timer = 60;
				gMS_GMK_UPBUMPER_WORK.player_spd_keep_timer_mine = (short)(player_spd_keep_timer + 1);
			}
			if (gMS_GMK_UPBUMPER_WORK.obj_type == 1)
			{
				num = -num;
			}
			GmPlySeqGmkInitUpBumper(gMS_PLAYER_WORK, num, spd_y);
			GMM_PAD_VIB_SMALL();
		}
		mine_rect.flag &= 4294573823u;
	}

