		if ((eve_rec.flag & 1) != 0)
		{
			int index = 0;
			if (eve_rec.id == 293)
			{
				index = 1;
			}
			GmDecoSetFrameMotion(0, index);
			eve_rec.pos_x = byte.MaxValue;
			eve_rec.byte_param[1] = 1;
			return null;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gmGmkDecoFrameMgrLoadObjNoModel(eve_rec, pos_x, pos_y, type);
