	private static void gmGmkDecoFrameMgrInit(OBS_OBJECT_WORK obj_work)
	{
		obj_work.disp_flag |= 32u;
		obj_work.move_flag |= 8448u;
		obj_work.flag |= 16u;
		obj_work.ppFunc = gmGmkDecoFrameMgrMainFunc;
		obj_work.ppOut = null;
		obj_work.ppMove = null;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		obj_work.user_timer = gMS_ENEMY_3D_WORK.ene_com.eve_rec.byte_param[1] * 2;
	}

	private static void gmGmkDecoFrameMgrMainFunc(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.user_timer >= 510)
		{
			obj_work.flag |= 4u;
			return;
		}
		obj_work.user_timer++;
		int index = 0;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if (gMS_ENEMY_3D_WORK.ene_com.eve_rec.id == 293)
		{
			index = 1;
		}
		GmDecoSetFrameMotion(obj_work.user_timer, index);
		gMS_ENEMY_3D_WORK.ene_com.eve_rec.byte_param[1] = (byte)(obj_work.user_timer / 2);
	}

	public static void GmDecoGlareSetData(AMS_AMB_HEADER amb_header)
	{
		pIF.Clear();
		string sPath;
