		TXB_HEADER txb = readTXBfile(amBindGet(pIF.amb_header, 0));
		pIF.tex_buf = amTxbGetTexFileList(txb);
		mppAssertNotImpl();
		nnSetUpTexlist(out pIF.texlist, pIF.tex_buf.nTex, ref pIF.texlistbuf);
		pIF.regId = amTextureLoad(pIF.texlist, pIF.tex_buf, null, pIF.amb_header);
		pIF.drawFlag = 1;
		pIF.texId = 0;
	}

	public static void GmDecoGlareDraw(OBS_OBJECT_WORK obj_work)
	{
		int user_work = (int)obj_work.user_work;
		if (user_work < 14)
		{
			return;
		}
		GMS_DECOGLARE_PARAM gMS_DECOGLARE_PARAM;
		switch (user_work)
		{
		default:
			return;
		case 14:
		case 109:
			gMS_DECOGLARE_PARAM = _gm_decoGlare_param[0];
			break;
		case 15:
			gMS_DECOGLARE_PARAM = _gm_decoGlare_param[1];
			break;
		case 16:
		case 110:
			gMS_DECOGLARE_PARAM = _gm_decoGlare_param[2];
			break;
		case 54:
			gMS_DECOGLARE_PARAM = _gm_decoGlare_param[3];
			break;
		}
		if (amDrawIsRegistComplete(pIF.regId) && pIF.drawFlag == 1 && (obj_work.disp_flag & 0x20) == 0)
		{
			VecFx32 vecFx = new VecFx32(obj_work.pos);
			float num = vecFx.x >> 12;
			float num2 = 0f - (float)(vecFx.y >> 12);
			float z = 256f;
			AMS_PARAM_DRAW_PRIMITIVE aMS_PARAM_DRAW_PRIMITIVE = GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Alloc();
			aMS_PARAM_DRAW_PRIMITIVE.aTest = 0;
			aMS_PARAM_DRAW_PRIMITIVE.zMask = 0;
			aMS_PARAM_DRAW_PRIMITIVE.zTest = 1;
			aMS_PARAM_DRAW_PRIMITIVE.ablend = 1;
			switch (gMS_DECOGLARE_PARAM.ablend)
			{
			case 0:
				amDrawGetPrimBlendParam(0, aMS_PARAM_DRAW_PRIMITIVE);
				break;
			case 1:
				amDrawGetPrimBlendParam(1, aMS_PARAM_DRAW_PRIMITIVE);
				break;
			}
			NNS_PRIM3D_PCT_ARRAY nNS_PRIM3D_PCT_ARRAY = amDrawAlloc_NNS_PRIM3D_PCT(6);
			NNS_PRIM3D_PCT[] buffer = nNS_PRIM3D_PCT_ARRAY.buffer;
			int offset = nNS_PRIM3D_PCT_ARRAY.offset;
			float num3 = gMS_DECOGLARE_PARAM.size * 0.5f;
			float num4 = gMS_DECOGLARE_PARAM.size * 0.5f;
			num += 10f;
			num2 -= 10f;
			buffer[offset].Pos.Assign(num - num3, num2 + num4, z);
			buffer[offset + 1].Pos.Assign(num + num3, num2 + num4, z);
			buffer[offset + 2].Pos.Assign(num - num3, num2 - num4, z);
			buffer[offset + 5].Pos.Assign(num + num3, num2 - num4, z);
			buffer[offset].Col = gMS_DECOGLARE_PARAM.color;
			buffer[offset + 1].Col = gMS_DECOGLARE_PARAM.color;
			buffer[offset + 2].Col = gMS_DECOGLARE_PARAM.color;
			buffer[offset + 5].Col = gMS_DECOGLARE_PARAM.color;
			buffer[offset].Tex.u = 0f;
			buffer[offset].Tex.v = 0f;
			buffer[offset + 1].Tex.u = 1f;
			buffer[offset + 1].Tex.v = 0f;
			buffer[offset + 2].Tex.u = 0f;
			buffer[offset + 2].Tex.v = 1f;
			buffer[offset + 5].Tex.u = 1f;
			buffer[offset + 5].Tex.v = 1f;
			buffer[offset + 3] = buffer[offset + 1];
			buffer[offset + 4] = buffer[offset + 2];
			aMS_PARAM_DRAW_PRIMITIVE.format3D = 4;
			aMS_PARAM_DRAW_PRIMITIVE.type = 0;
			aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D = nNS_PRIM3D_PCT_ARRAY;
			aMS_PARAM_DRAW_PRIMITIVE.texlist = pIF.texlist;
			aMS_PARAM_DRAW_PRIMITIVE.texId = pIF.texId;
			aMS_PARAM_DRAW_PRIMITIVE.count = 6;
			aMS_PARAM_DRAW_PRIMITIVE.sortZ = gMS_DECOGLARE_PARAM.sort_z;
			amDrawPrimitive3D(4u, aMS_PARAM_DRAW_PRIMITIVE);
			GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Release(aMS_PARAM_DRAW_PRIMITIVE);
		}
	}

