	private static int gmBoss5LandGetPlacementInfo(GMS_BOSS5_LAND_PLACEMENT_INFO place_info)
	{
		GMS_EVE_RECORD_EVENT gMS_EVE_RECORD_EVENT = null;
		OBS_OBJECT_WORK oBS_OBJECT_WORK;
		for (oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, 3); oBS_OBJECT_WORK != null; oBS_OBJECT_WORK = ObjObjectSearchRegistObject(oBS_OBJECT_WORK, 3))
		{
			GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)oBS_OBJECT_WORK;
			if (gMS_ENEMY_COM_WORK.eve_rec != null && gMS_ENEMY_COM_WORK.eve_rec.id == 282)
			{
				gMS_EVE_RECORD_EVENT = gMS_ENEMY_COM_WORK.eve_rec;
				break;
			}
		}
		if (oBS_OBJECT_WORK == null)
		{
			mppAssertNotImpl();
			return 0;
		}
		place_info.pos_x = oBS_OBJECT_WORK.pos.x;
		place_info.pos_y = oBS_OBJECT_WORK.pos.y;
		int num = gMS_EVE_RECORD_EVENT.left + gMS_EVE_RECORD_EVENT.width;
		num <<= 3;
		place_info.part_num = (int)(num / GMD_BOSS5_LAND_LDPART_WIDTH_INT);
		return 1;
	}

	private static void gmBoss5LandSetObjCollisionRect(GMS_BOSS5_LAND_WORK land_work, int part_num)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(land_work);
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)land_work;
		gMS_ENEMY_COM_WORK.col_work.obj_col.obj = GMM_BS_OBJ(land_work);
		gMS_ENEMY_COM_WORK.col_work.obj_col.width = (ushort)(part_num * GMD_BOSS5_LAND_LDPART_WIDTH_INT);
		gMS_ENEMY_COM_WORK.col_work.obj_col.height = GMD_BOSS5_LAND_LDPART_HEIGHT_INT;
		gMS_ENEMY_COM_WORK.col_work.obj_col.ofst_x = 0;
		gMS_ENEMY_COM_WORK.col_work.obj_col.ofst_y = 0;
		oBS_OBJECT_WORK.view_out_ofst_plus[0] = (short)(gMS_ENEMY_COM_WORK.col_work.obj_col.ofst_x - (short)gMS_ENEMY_COM_WORK.col_work.obj_col.width);
		oBS_OBJECT_WORK.view_out_ofst_plus[2] = (short)(gMS_ENEMY_COM_WORK.col_work.obj_col.ofst_x + (short)gMS_ENEMY_COM_WORK.col_work.obj_col.width);
	}

	private static void gmBoss5LandDisableObjCollision(GMS_BOSS5_LAND_WORK land_work)
	{
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)land_work;
		gMS_ENEMY_COM_WORK.col_work.obj_col.obj = null;
