	private static void gmBoss5LandMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS5_LAND_WORK gMS_BOSS5_LAND_WORK = (GMS_BOSS5_LAND_WORK)obj_work;
		if (gMS_BOSS5_LAND_WORK.proc_update != null)
		{
			gMS_BOSS5_LAND_WORK.proc_update(gMS_BOSS5_LAND_WORK);
		}
	}

	private static void gmBoss5LandProcInit(GMS_BOSS5_LAND_WORK land_work)
	{
		land_work.proc_update = gmBoss5LandProcUpdateIdle;
	}

	private static void gmBoss5LandProcUpdateIdle(GMS_BOSS5_LAND_WORK land_work)
	{
		if ((land_work.mgr_work.flag & 0x20000000) != 0)
		{
			land_work.flag |= GMD_BOSS5_LAND_FLAG_SHAKE_ACTIVE;
			land_work.proc_update = gmBoss5LandProcUpdateShake;
		}
	}

	private static void gmBoss5LandProcUpdateShake(GMS_BOSS5_LAND_WORK land_work)
	{
		if ((land_work.mgr_work.flag & 0x40000000) != 0)
		{
			land_work.flag |= GMD_BOSS5_LAND_FLAG_BREAK_ACTIVE;
			gmBoss5LandDisableObjCollision(land_work);
			land_work.proc_update = null;
		}
	}

	private static GMS_BOSS5_LDPART_WORK gmBoss5LandCreateLdPart(GMS_BOSS5_LAND_WORK land_work, int land_type, int part_index)
	{
		OBS_OBJECT_WORK parent_obj = GMM_BS_OBJ(land_work);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_BOSS5_LDPART_WORK(), parent_obj, 0, "BOSS5_LAND_PART");
		GMS_EFFECT_3DNN_WORK gMS_EFFECT_3DNN_WORK = (GMS_EFFECT_3DNN_WORK)oBS_OBJECT_WORK;
		GMS_BOSS5_LDPART_WORK gMS_BOSS5_LDPART_WORK = (GMS_BOSS5_LDPART_WORK)oBS_OBJECT_WORK;
		gMS_BOSS5_LDPART_WORK.part_index = part_index;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, GmBoss5GetObject3dList()[gm_boss5_land_mdl_amb_idx_tbl[land_type]], gMS_EFFECT_3DNN_WORK.obj_3d);
		oBS_OBJECT_WORK.obj_3d.drawflag = (uint)(oBS_OBJECT_WORK.obj_3d.drawflag & -1);
		ObjObjectAction3dNNMaterialMotionLoad(oBS_OBJECT_WORK, 0, ObjDataGet(gm_boss5_land_mat_mtn_dwork_no_tbl[land_type]), null, gm_boss5_land_mat_mtn_data_tbl[land_type], null);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 2u;
		oBS_OBJECT_WORK.flag |= 1024u;
		oBS_OBJECT_WORK.flag |= 18u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		oBS_OBJECT_WORK.move_flag &= 4294967167u;
		oBS_OBJECT_WORK.parent_ofst.x = GMD_BOSS5_LAND_LDPART_WIDTH_FX / 2 + part_index * GMD_BOSS5_LAND_LDPART_WIDTH_FX + GMD_BOSS5_LAND_LDPART_CENTER_OFST_X_FX;
		oBS_OBJECT_WORK.parent_ofst.y = GMD_BOSS5_LAND_LDPART_HEIGHT_FX / 2 + GMD_BOSS5_LAND_LDPART_CENTER_OFST_Y_FX;
		oBS_OBJECT_WORK.parent_ofst.z = 0;
		gMS_BOSS5_LDPART_WORK.pivot_parent_ofst[0] = oBS_OBJECT_WORK.parent_ofst.x;
		gMS_BOSS5_LDPART_WORK.pivot_parent_ofst[1] = oBS_OBJECT_WORK.parent_ofst.y;
		oBS_OBJECT_WORK.ppFunc = gmBoss5LdPartMain;
		gmBoss5LdPartProcInit(gMS_BOSS5_LDPART_WORK);
		return gMS_BOSS5_LDPART_WORK;
	}

	private static void gmBoss5LdPartInitSpin(GMS_BOSS5_LDPART_WORK ldpart_work)
	{
		nnMakeUnitQuaternion(ref ldpart_work.cur_rot_quat);
		nnMakeUnitQuaternion(ref ldpart_work.rot_diff_quat);
		for (int i = 0; i < GMD_BOSS5_LAND_LDPART_SPIN_ROT_AXIS_NUM; i++)
		{
			NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
			float a = FX_FX32_TO_F32(AkMathRandFx()) * 2f - 1f;
			a = MTM_MATH_CLIP(a, -1f, 1f);
			short rand_angle = AKM_DEGtoA16(360f * FX_FX32_TO_F32(AkMathRandFx()));
			AkMathGetRandomUnitVector(nNS_VECTOR, a, rand_angle);
			NNS_QUATERNION dst;
			nnMakeRotateAxisQuaternion(out dst, nNS_VECTOR.x, nNS_VECTOR.y, nNS_VECTOR.z, GMD_BOSS5_LAND_LDPART_SPIN_ROT_SPD_DEG);
			nnMultiplyQuaternion(ref ldpart_work.rot_diff_quat, ref dst, ref ldpart_work.rot_diff_quat);
		}
	}

	private static void gmBoss5LdPartUpdateSpin(GMS_BOSS5_LDPART_WORK ldpart_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(ldpart_work);
		nnMultiplyQuaternion(ref ldpart_work.cur_rot_quat, ref ldpart_work.rot_diff_quat, ref ldpart_work.cur_rot_quat);
		nnMakeQuaternionMatrix(oBS_OBJECT_WORK.obj_3d.user_obj_mtx_r, ref ldpart_work.cur_rot_quat);
		oBS_OBJECT_WORK.disp_flag |= 16777216u;
	}

	private static void gmBoss5LdPartInitFall(GMS_BOSS5_LDPART_WORK ldpart_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(ldpart_work);
		int num = mtMathRand() % GMD_BOSS5_LAND_LDPART_FALL_XY_DIR_RANGE_DEG;
		int ang = AKM_DEGtoA32(num + (270 - GMD_BOSS5_LAND_LDPART_FALL_XY_DIR_RANGE_DEG / 2));
		int z = FX_Mul(AkMathRandFx(), GMD_BOSS5_LAND_LDPART_FALL_Z_SPD_MAX * 2) - GMD_BOSS5_LAND_LDPART_FALL_Z_SPD_MAX;
		oBS_OBJECT_WORK.spd.y = (int)(4096f * GMD_BOSS5_LAND_LDPART_FALL_XY_SPD_FL * nnSin(ang));
		oBS_OBJECT_WORK.spd.x = (int)(4096f * GMD_BOSS5_LAND_LDPART_FALL_XY_SPD_FL * nnCos(ang));
		oBS_OBJECT_WORK.spd.z = z;
		oBS_OBJECT_WORK.flag &= 4294966271u;
		oBS_OBJECT_WORK.move_flag |= 128u;
	}

	private static void gmBoss5LdPartInitVib(GMS_BOSS5_LDPART_WORK ldpart_work)
	{
		ldpart_work.vib_cnt = mtMathRand() % 40;
		ldpart_work.vib_ofst[0] = (ldpart_work.vib_ofst[1] = 0);
	}

	private static void gmBoss5LdPartUpdateVib(GMS_BOSS5_LDPART_WORK ldpart_work)
	{
		ldpart_work.vib_ofst[0] = FX_Mul(gm_boss5_land_vib_tbl[ldpart_work.vib_cnt][0], GMD_BOSS5_LAND_LDPART_VIB_AMPLITUDE);
		ldpart_work.vib_ofst[1] = FX_Mul(gm_boss5_land_vib_tbl[ldpart_work.vib_cnt][1], GMD_BOSS5_LAND_LDPART_VIB_AMPLITUDE);
		ldpart_work.vib_cnt++;
		if (ldpart_work.vib_cnt >= 40)
		{
			ldpart_work.vib_cnt = 0;
		}
	}

	private static void gmBoss5LdPartClearVib(GMS_BOSS5_LDPART_WORK ldpart_work)
	{
		ldpart_work.vib_cnt = 0;
		ldpart_work.vib_ofst[0] = (ldpart_work.vib_ofst[1] = 0);
	}

	private static void gmBoss5LdPartMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS5_LDPART_WORK gMS_BOSS5_LDPART_WORK = (GMS_BOSS5_LDPART_WORK)obj_work;
		obj_work.parent_ofst.x = gMS_BOSS5_LDPART_WORK.pivot_parent_ofst[0] + gMS_BOSS5_LDPART_WORK.vib_ofst[0];
		obj_work.parent_ofst.y = gMS_BOSS5_LDPART_WORK.pivot_parent_ofst[1] + gMS_BOSS5_LDPART_WORK.vib_ofst[1];
		if (gMS_BOSS5_LDPART_WORK.proc_update != null)
		{
			gMS_BOSS5_LDPART_WORK.proc_update(gMS_BOSS5_LDPART_WORK);
		}
	}

	private static void gmBoss5LdPartProcInit(GMS_BOSS5_LDPART_WORK ldpart_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(ldpart_work);
		ObjDrawObjectActionSet3DNNMaterial(oBS_OBJECT_WORK, 0);
		oBS_OBJECT_WORK.disp_flag |= 4u;
		ldpart_work.proc_update = gmBoss5LdPartProcUpdateIdle;
	}

	private static void gmBoss5LdPartProcUpdateIdle(GMS_BOSS5_LDPART_WORK ldpart_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(ldpart_work);
		GMS_BOSS5_LAND_WORK gMS_BOSS5_LAND_WORK = (GMS_BOSS5_LAND_WORK)oBS_OBJECT_WORK.parent_obj;
		if ((gMS_BOSS5_LAND_WORK.flag & GMD_BOSS5_LAND_FLAG_SHAKE_ACTIVE) != 0)
		{
			gmBoss5LdPartInitVib(ldpart_work);
			ldpart_work.proc_update = gmBoss5LdPartProcUpdateShake;
		}
	}

	private static void gmBoss5LdPartProcUpdateShake(GMS_BOSS5_LDPART_WORK ldpart_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(ldpart_work);
		GMS_BOSS5_LAND_WORK gMS_BOSS5_LAND_WORK = (GMS_BOSS5_LAND_WORK)oBS_OBJECT_WORK.parent_obj;
		gmBoss5LdPartUpdateVib(ldpart_work);
		if ((gMS_BOSS5_LAND_WORK.flag & GMD_BOSS5_LAND_FLAG_BREAK_ACTIVE) != 0)
		{
			gmBoss5LdPartClearVib(ldpart_work);
			gmBoss5LdPartInitSpin(ldpart_work);
			gmBoss5LdPartInitFall(ldpart_work);
			ldpart_work.wait_timer = (uint)(ldpart_work.part_index & 1);
			ldpart_work.proc_update = gmBoss5LdPartProcUpdateFall;
		}
	}

	private static void gmBoss5LdPartProcUpdateFall(GMS_BOSS5_LDPART_WORK ldpart_work)
	{
		if (ldpart_work.wait_timer != 0)
		{
			ldpart_work.wait_timer--;
		}
		else if (ldpart_work.brk_glass_cnt == 0)
		{
			GmBoss5EfctCreateBreakingGlass(GMM_BS_OBJ(ldpart_work));
			ldpart_work.brk_glass_cnt++;
		}
		gmBoss5LdPartUpdateSpin(ldpart_work);
	}

	private static void GmBoss5LandSetLight()
	{
