	private static void GmTvxSetModel(TVX_FILE model_tvx, NNS_TEXLIST model_tex, ref VecFx32 pos, ref VecFx32 scale, uint flag, short rotate_z)
	{
		GMS_TVX_EX_WORK ex_work = new GMS_TVX_EX_WORK
		{
			u_wrap = 1,
			v_wrap = 1,
			coord = 
			{
				u = 0f,
				v = 0f
			},
			color = uint.MaxValue
		};
		GmTvxSetModelEx(model_tvx, model_tex, ref pos, ref scale, flag, rotate_z, ref ex_work);
	}

	private static void GmTvxSetModelEx(TVX_FILE model_tvx, NNS_TEXLIST model_tex, ref VecFx32 pos, ref VecFx32 scale, uint flag, short rotate_z, ref GMS_TVX_EX_WORK ex_work)
	{
		if (!GmMainIsDrawEnable())
		{
			return;
		}
		GMS_TVX_DRAW_WORK[] array = gm_tvx_draw_work;
		GMS_TVX_DRAW_STACK gMS_TVX_DRAW_STACK = null;
		uint num = AoTvxGetTextureNum(model_tvx);
		for (uint num2 = 0u; num2 < num; num2++)
		{
			uint num3 = AoTvxGetVertexNum(model_tvx, num2);
			int num4 = AoTvxGetTextureId(model_tvx, num2);
			for (int i = 0; i < GMD_TVX_DRAW_WORK_NUM; i++)
			{
				if ((array[i].tex == null && array[i].tex_id == -1) || (array[i].tex == model_tex && array[i].tex_id == num4 && array[i].u_wrap == ex_work.u_wrap && array[i].v_wrap == ex_work.v_wrap))
				{
					if (array[i].stack_num >= GMD_TVX_DRAW_STACK_NUM)
					{
						return;
					}
					array[i].tex = model_tex;
					array[i].tex_id = num4;
					array[i].u_wrap = ex_work.u_wrap;
					array[i].v_wrap = ex_work.v_wrap;
					array[i].all_vtx_num += num3;
					gMS_TVX_DRAW_STACK = array[i].stack[array[i].stack_num];
					gMS_TVX_DRAW_STACK.vtx = AoTvxGetVertex(model_tvx, num2);
					gMS_TVX_DRAW_STACK.vtx_num = num3;
					gMS_TVX_DRAW_STACK.pos = pos;
					gMS_TVX_DRAW_STACK.scale = scale;
					gMS_TVX_DRAW_STACK.disp_flag = flag;
