	private static float gmGmkTarzanRopeCalcFlame(OBS_OBJECT_WORK obj_work, int angle)
	{
		OBS_ACTION3D_NN_WORK obj_3d = obj_work.obj_3d;
		int num = 16384;
		int num2 = -16384;
		if (angle > num)
		{
			angle = num;
