		float num3 = amMotionGetStartFrame(obj_3d.motion, obj_3d.act_id[0]);
		float num4 = amMotionGetEndFrame(obj_3d.motion, obj_3d.act_id[0]);
		float num5 = (num4 - num3) / 2f;
		float num6 = (float)angle / (float)num;
		return num5 - num6 * (num4 - num3) / 4f;
	}

