		switch (num)
		{
		case 0:
		{
			ushort num3 = (ushort)((parent_obj.pos.y >> 12) - 32);
			ushort num4 = (ushort)(parent_obj2.pos.y >> 12);
			gMS_ENEMY_3D_WORK.ene_com.enemy_flag &= 4294901760u;
			if (num4 > num3)
			{
