	private static int gmGmkTarzanRopeUpdateAngleCurrent(OBS_OBJECT_WORK obj_work, int angle_target, int angle_current)
	{
		int num = MTM_MATH_ABS(angle_target);
		int num2 = MTM_MATH_ABS(angle_current);
		int num3 = 1920;
		float num4 = (float)(num - num2) / 20480f;
		if (num4 > 0.55f)
		{
			num4 = 0.55f;
		}
		else if (num4 < -0.55f)
		{
			num4 = -0.55f;
		}
		num3 = (int)((float)num3 * (MTM_MATH_ABS(num4) + 0.05f));
		if (angle_target < angle_current)
		{
			num3 = -num3;
		}
		return gmGmkTarzanRopeAddUserTimerCurrentAngle(obj_work, num3);
	}

	private static int gmGmkTarzanRopeUpdateAngleTarget(OBS_OBJECT_WORK obj_work, int angle_target, int angle_current, bool flag_motion_change)
	{
		if (angle_target > 0)
		{
			angle_target = gmGmkTarzanRopeAddUserWorkTargetAngle(obj_work, -48);
			if (angle_target > 16384)
			{
				angle_target = 16384;
			}
			else if (angle_target < 0)
			{
				angle_target = 0;
			}
			if (angle_current >= angle_target)
			{
				angle_target = -angle_target;
				gmGmkTarzanRopeSetUserWorkTargetAngle(obj_work, angle_target);
				if (flag_motion_change)
				{
					gmGmkTarzanRopeChangeDirMotion(obj_work, angle_current);
				}
			}
		}
		else if (angle_target < 0)
		{
			angle_target = gmGmkTarzanRopeAddUserWorkTargetAngle(obj_work, 48);
			if (angle_target < -16384)
			{
				angle_target = -16384;
			}
			else if (angle_target > 0)
			{
				angle_target = 0;
			}
			if (angle_current <= angle_target)
			{
				angle_target = -angle_target;
				gmGmkTarzanRopeSetUserWorkTargetAngle(obj_work, angle_target);
				if (flag_motion_change)
				{
					gmGmkTarzanRopeChangeDirMotion(obj_work, angle_current);
				}
			}
		}
		return angle_target;
	}

	private static void gmGmkTarzanRopeChangeDirMotion(OBS_OBJECT_WORK obj_work, int angle_current)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		OBS_OBJECT_WORK obj_work2 = gMS_PLAYER_WORK.obj_work;
		OBS_ACTION3D_NN_WORK obj_3d = obj_work2.obj_3d;
		float num = amMotionGetStartFrame(obj_3d.motion, obj_3d.act_id[0]);
		float num2 = 34f;
		if ((obj_work2.disp_flag & 1) != 0)
		{
			if (angle_current < 0)
			{
				obj_3d.frame[0] = num;
			}
			else if (angle_current > 0)
			{
				obj_3d.frame[0] = num2;
			}
		}
		else if (angle_current < 0)
		{
			obj_3d.frame[0] = num2;
		}
		else if (angle_current > 0)
		{
			obj_3d.frame[0] = num;
		}
		obj_work2.disp_flag &= 4294967279u;
	}

	private static void gmGmkTarzanRopeUpdatePlayerMotion(OBS_OBJECT_WORK obj_work, int angle_target, int angle_current)
	{
		UNREFERENCED_PARAMETER(obj_work);
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		OBS_OBJECT_WORK obj_work2 = gMS_PLAYER_WORK.obj_work;
		OBS_ACTION3D_NN_WORK obj_3d = obj_work2.obj_3d;
		float num = 34f;
		int num2 = MTM_MATH_ABS(angle_target);
		int num3 = MTM_MATH_ABS(angle_current);
		if (num2 < 1792 && num3 < 1792)
		{
			int a = gmGmkTarzanRopeGetGimmickRotZ(gMS_PLAYER_WORK);
			if (gMS_PLAYER_WORK.act_state != 64 && MTM_MATH_ABS(a) < 208)
			{
				GmPlayerActionChange(gMS_PLAYER_WORK, 64);
				obj_work2.disp_flag |= 4u;
			}
		}
		else if (gMS_PLAYER_WORK.act_state == 64)
		{
			GmPlayerActionChange(gMS_PLAYER_WORK, 63);
			obj_work2.disp_flag |= 4u;
		}
		else if ((obj_work2.disp_flag & 1) != 0)
		{
			if (angle_target > 0 && angle_current > 0)
			{
				if (obj_3d.frame[0] > num)
				{
					obj_work2.disp_flag |= 16u;
				}
			}
			else if (angle_target < 0 && angle_current < 0 && obj_3d.frame[0] < num)
			{
				obj_work2.disp_flag |= 16u;
			}
		}
		else if (angle_target > 0 && angle_current > 0)
		{
			if (obj_3d.frame[0] < num)
			{
				obj_work2.disp_flag |= 16u;
			}
		}
		else if (angle_target < 0 && angle_current < 0 && obj_3d.frame[0] > num)
		{
			obj_work2.disp_flag |= 16u;
		}
	}

