		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_OBJECT_WORK target_obj = gMS_ENEMY_3D_WORK.ene_com.target_obj;
		GMS_PLAYER_WORK ply_work = (GMS_PLAYER_WORK)target_obj;
		int num = MTM_MATH_ABS(angle_target);
		int num2 = MTM_MATH_ABS(angle_current);
		int num3 = gmGmkTarzanRopeGetGimmickRotZ(ply_work);
		if (num < 1792 && num2 < 1792)
		{
			if (num3 < 0)
			{
				angle_target = gmGmkTarzanRopeAddUserWorkTargetAngle(obj_work, -1792);
			}
		}
		else if (angle_target < 0)
		{
			if (num3 < 0)
			{
				angle_target = gmGmkTarzanRopeAddUserWorkTargetAngle(obj_work, -132);
			}
			else if (num3 > 0)
			{
				angle_target = gmGmkTarzanRopeAddUserWorkTargetAngle(obj_work, 31);
			}
		}
		return angle_target;
	}

