	private static bool gmGmkTarzanRopeCheckPlayerJump(OBS_OBJECT_WORK obj_work, int angle_target, int angle_current)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_OBJECT_WORK target_obj = gMS_ENEMY_3D_WORK.ene_com.target_obj;
		GMS_PLAYER_WORK ply_work = (GMS_PLAYER_WORK)target_obj;
		if (gmGmkTarzanRopeGetCatchWait(obj_work) != 0)
		{
			return false;
		}
		if (GmPlayerKeyCheckJumpKeyPush(ply_work))
		{
			target_obj.disp_flag &= 4294967279u;
			target_obj.spd_m = 0;
			target_obj.spd.x = 0;
			target_obj.spd.y = 0;
			target_obj.dir.z = 0;
			target_obj.spd_add.x = 0;
			target_obj.spd_add.y = 0;
			target_obj.spd_add.z = 0;
			float num = 1f + (float)gMS_ENEMY_3D_WORK.ene_com.eve_rec.left / 10000f;
			int num2 = (int)((float)angle_target * 0.8f * num);
			int num3 = (int)((float)MTM_MATH_ABS(angle_current) * 2.3f * num);
			if (angle_target == 0 && angle_current == 0)
			{
				num2 = 0;
				num3 = 16384;
			}
			else if ((angle_target < 0 && 0 < angle_current) || (0 < angle_target && angle_current < 0))
			{
				if (MTM_MATH_ABS(angle_target + angle_current) < 1792)
				{
					num2 = -num2;
				}
				else
				{
					num2 = 0;
					num3 = 16384;
				}
			}
			GmPlySeqGmkInitGmkJump(ply_work, num2, -num3);
			GmPlySeqChangeSequenceState(ply_work, 17);
			obj_work.ppFunc = gmGmkTarzanRopeMainEnd;
			gMS_ENEMY_3D_WORK.ene_com.target_obj = null;
			return true;
		}
		return false;
	}

	private static void gmGmkTarzanRopeUpdatePlayerPos(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_OBJECT_WORK target_obj = gMS_ENEMY_3D_WORK.ene_com.target_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)target_obj;
		NNS_MATRIX nNS_MATRIX = new NNS_MATRIX();
		nnMakeUnitMatrix(nNS_MATRIX);
		nNS_MATRIX.M11 = g_gm_gmk_tarzan_rope_active_matrix.M11;
		nNS_MATRIX.M22 = g_gm_gmk_tarzan_rope_active_matrix.M00;
		nNS_MATRIX.M21 = g_gm_gmk_tarzan_rope_active_matrix.M01;
		nNS_MATRIX.M12 = g_gm_gmk_tarzan_rope_active_matrix.M10;
		nNS_MATRIX.M03 = -5f;
		AkMathNormalizeMtx(gMS_PLAYER_WORK.ex_obj_mtx_r, nNS_MATRIX);
		if ((target_obj.disp_flag & 1) != 0)
		{
			gMS_PLAYER_WORK.ex_obj_mtx_r.M21 = 0f - gMS_PLAYER_WORK.ex_obj_mtx_r.M21;
			gMS_PLAYER_WORK.ex_obj_mtx_r.M12 = 0f - gMS_PLAYER_WORK.ex_obj_mtx_r.M12;
			nNS_MATRIX.M03 = 0f - nNS_MATRIX.M03;
		}
		int num = (int)((gMS_ENEMY_3D_WORK.ene_com.enemy_flag & 0xFFFF) << 12);
		num += 24576;
		if (num > 393216)
		{
			num = 393216;
		}
		gMS_ENEMY_3D_WORK.ene_com.enemy_flag &= 4294901760u;
		gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= (uint)(num >> 12);
		float num2 = (float)num / 393216f;
		num2 = (0f - num2) * 20f;
		num2 += 15f;
		NNS_VECTOR nNS_VECTOR = new NNS_VECTOR(0f, num2, 0f);
		nnTransformVector(nNS_VECTOR, nNS_MATRIX, nNS_VECTOR);
		target_obj.pos.x = FX_F32_TO_FX32(g_gm_gmk_tarzan_rope_active_matrix.M03 + nNS_VECTOR.z);
		target_obj.pos.y = -FX_F32_TO_FX32(g_gm_gmk_tarzan_rope_active_matrix.M13 + nNS_VECTOR.y);
		target_obj.pos.z = FX_F32_TO_FX32(g_gm_gmk_tarzan_rope_active_matrix.M23 + nNS_VECTOR.x);
		gMS_PLAYER_WORK.gmk_flag |= 32768u;
	}

	private static void gmGmkTarzanRopeMainWait(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0 || gMS_PLAYER_WORK.seq_state == 22)
		{
			obj_work.ppFunc = gmGmkTarzanRopeMainEnd;
			gMS_ENEMY_3D_WORK.ene_com.target_obj = null;
			gMS_PLAYER_WORK.gmk_flag &= 4294934527u;
			return;
		}
		int angle_target = gmGmkTarzanRopeGetUserWorkTargetAngle(obj_work);
		int angle_current = gmGmkTarzanRopeGetUserTimerCurrentAngle(obj_work);
		gmGmkTarzanRopeInitCatchWait(obj_work);
		if (!gmGmkTarzanRopeCheckPlayerJump(obj_work, angle_target, angle_current))
		{
			angle_current = gmGmkTarzanRopeUpdateAngleCurrent(obj_work, angle_target, angle_current);
			angle_target = gmGmkTarzanRopeUpdateAngleTarget(obj_work, angle_target, angle_current, true);
			gmGmkTarzanRopeCheckStop(obj_work, angle_target, angle_current);
			gmGmkTarzanRopeUpdatePlayerPos(obj_work);
			obj_work.ppFunc = gmGmkTarzanRopeMainKey;
		}
	}

	private static void gmGmkTarzanRopeMainKey(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0 || gMS_PLAYER_WORK.seq_state == 22)
		{
			obj_work.ppFunc = gmGmkTarzanRopeMainEnd;
			gMS_ENEMY_3D_WORK.ene_com.target_obj = null;
			gMS_PLAYER_WORK.gmk_flag &= 4294934527u;
			return;
		}
		int num = gmGmkTarzanRopeGetUserWorkTargetAngle(obj_work);
		int angle_current = gmGmkTarzanRopeGetUserTimerCurrentAngle(obj_work);
		gmGmkTarzanRopeUpdateCatchWait(obj_work);
		if (!gmGmkTarzanRopeCheckPlayerJump(obj_work, num, angle_current))
		{
			if (num <= 0)
			{
				num = gmGmkTarzanRopeApplyKeyLeft(obj_work, num, angle_current);
			}
			if (num >= 0)
			{
				num = gmGmkTarzanRopeApplyKeyRight(obj_work, num, angle_current);
			}
			angle_current = gmGmkTarzanRopeUpdateAngleCurrent(obj_work, num, angle_current);
			num = gmGmkTarzanRopeUpdateAngleTarget(obj_work, num, angle_current, true);
			gmGmkTarzanRopeUpdatePlayerMotion(obj_work, num, angle_current);
			gmGmkTarzanRopeCheckStop(obj_work, num, angle_current);
			gmGmkTarzanRopeUpdatePlayerPos(obj_work);
		}
	}

	private static void gmGmkTarzanRopeMainEnd(OBS_OBJECT_WORK obj_work)
	{
		int angle_target = gmGmkTarzanRopeGetUserWorkTargetAngle(obj_work);
		int angle_current = gmGmkTarzanRopeGetUserTimerCurrentAngle(obj_work);
		gmGmkTarzanRopeUpdateAngleCurrent(obj_work, angle_target, angle_current);
		gmGmkTarzanRopeUpdateAngleTarget(obj_work, angle_target, angle_current, false);
		gmGmkTarzanRopeCheckStop(obj_work, angle_target, angle_current);
	}

