	private static uint gmGmkSpearSyncTimeGet(GMS_GMK_SPEAR_WORK pwork)
	{
		uint sync_time = g_gm_main_system.sync_time;
		uint num = (uint)((pwork.timer_set_move + (pwork.stroke_spd - 1)) / pwork.stroke_spd);
		uint num2 = num * 2;
		num2 += (uint)pwork.timer_set_wait_upper;
		num2 += (uint)pwork.timer_set_wait_lower;
		return sync_time % num2;
	}

	private static void gmGmkSpearStart(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SPEAR_WORK gMS_GMK_SPEAR_WORK = (GMS_GMK_SPEAR_WORK)obj_work;
		gMS_GMK_SPEAR_WORK.gmk_work.ene_com.rect_work[2].flag &= 4294967291u;
		gMS_GMK_SPEAR_WORK.gmk_work.ene_com.rect_work[0].flag &= 4294967291u;
		gMS_GMK_SPEAR_WORK.gmk_work.ene_com.rect_work[1].flag |= 4u;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_GMK_SPEAR_WORK.gmk_work.ene_com.rect_work[1];
		ObjRectWorkZSet(oBS_RECT_WORK, tbl_gm_gmk_spear_rect[gMS_GMK_SPEAR_WORK.obj_type][0], tbl_gm_gmk_spear_rect[gMS_GMK_SPEAR_WORK.obj_type][1], -500, tbl_gm_gmk_spear_rect[gMS_GMK_SPEAR_WORK.obj_type][2], tbl_gm_gmk_spear_rect[gMS_GMK_SPEAR_WORK.obj_type][3], 500);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK.flag |= 1024u;
		obj_work.flag &= 4294967293u;
		uint sync_time = g_gm_main_system.sync_time;
		uint num = (uint)((gMS_GMK_SPEAR_WORK.timer_set_move + (gMS_GMK_SPEAR_WORK.stroke_spd - 1)) / gMS_GMK_SPEAR_WORK.stroke_spd);
		uint num2 = num * 2;
		num2 += (uint)gMS_GMK_SPEAR_WORK.timer_set_wait_upper;
		num2 += (uint)gMS_GMK_SPEAR_WORK.timer_set_wait_lower;
		if (sync_time <= (uint)gMS_GMK_SPEAR_WORK.timer_dec)
		{
			gMS_GMK_SPEAR_WORK.timer_dec -= (int)(sync_time - 1);
			gMS_GMK_SPEAR_WORK.timer_dec += gMS_GMK_SPEAR_WORK.timer_set_wait_lower;
			gmGmkSpearStay(obj_work);
			return;
		}
		sync_time -= (uint)gMS_GMK_SPEAR_WORK.timer_dec;
		sync_time %= num2;
		if (sync_time <= (uint)gMS_GMK_SPEAR_WORK.timer_set_wait_lower)
		{
			gMS_GMK_SPEAR_WORK.timer_dec = (int)(gMS_GMK_SPEAR_WORK.timer_set_wait_lower - (sync_time - 1));
			gmGmkSpearStay(obj_work);
			return;
		}
		sync_time -= (uint)gMS_GMK_SPEAR_WORK.timer_set_wait_lower;
		int num3 = mtMathCos(gMS_GMK_SPEAR_WORK.vect);
		int num4 = mtMathSin(gMS_GMK_SPEAR_WORK.vect);
		num3 = num3 * gMS_GMK_SPEAR_WORK.stroke_spd >> 12;
		num4 = num4 * gMS_GMK_SPEAR_WORK.stroke_spd >> 12;
		if (sync_time < num)
		{
			gMS_GMK_SPEAR_WORK.timer_dec = gMS_GMK_SPEAR_WORK.timer_set_move;
			while (sync_time > 1)
			{
				gMS_GMK_SPEAR_WORK.timer_dec -= gMS_GMK_SPEAR_WORK.stroke_spd;
				obj_work.pos.x += num3;
				obj_work.pos.y += num4;
				sync_time--;
			}
			obj_work.spd.x = num3;
			obj_work.spd.y = num4;
			gmGmkSpearStroke(obj_work);
			return;
		}
		sync_time -= num;
		int num5 = mtMathCos(gMS_GMK_SPEAR_WORK.vect) * gMS_GMK_SPEAR_WORK.timer_set_move >> 12;
		int num6 = mtMathSin(gMS_GMK_SPEAR_WORK.vect) * gMS_GMK_SPEAR_WORK.timer_set_move >> 12;
		obj_work.pos.x += num5;
		obj_work.pos.y += num6;
		if (sync_time <= (uint)gMS_GMK_SPEAR_WORK.timer_set_wait_upper)
		{
			gMS_GMK_SPEAR_WORK.timer_dec = (int)(gMS_GMK_SPEAR_WORK.timer_set_wait_upper - (sync_time - 1));
			gmGmkSpearWait(obj_work);
			return;
		}
		sync_time -= (uint)gMS_GMK_SPEAR_WORK.timer_set_wait_upper;
		gMS_GMK_SPEAR_WORK.timer_dec = gMS_GMK_SPEAR_WORK.timer_set_move;
		while (sync_time > 1)
		{
			gMS_GMK_SPEAR_WORK.timer_dec -= gMS_GMK_SPEAR_WORK.stroke_spd;
			obj_work.pos.x -= num3;
			obj_work.pos.y -= num4;
			sync_time--;
		}
		obj_work.spd.x = -num3;
		obj_work.spd.y = -num4;
		gmGmkSpearShrink(obj_work);
	}

