			break;
		case 1u:
			gMS_GMK_SPEARPARTS_WORK.connect = gMS_GMK_SPEARPARTS_WORK.parent_connect.pos.y;
			break;
		case 2u:
			gMS_GMK_SPEARPARTS_WORK.connect = gMS_GMK_SPEARPARTS_WORK.parent_connect.pos.x;
