		oBS_OBJECT_WORK.move_flag |= 256u;
		oBS_OBJECT_WORK.disp_flag &= 4294967039u;
		oBS_OBJECT_WORK.flag |= 2u;
		oBS_OBJECT_WORK.ppFunc = null;
		oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_GMK_SPEARPARTS_WORK(), null, 0, "Gmk_SpearRod");
		gMS_GMK_SPEARPARTS_WORK = (GMS_GMK_SPEARPARTS_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_spear_obj_3d_list[1], gMS_GMK_SPEARPARTS_WORK.eff_work.obj_3d);
