	private static OBS_OBJECT_WORK gmGmkSpearInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		GMS_GMK_SPEAR_WORK gMS_GMK_SPEAR_WORK = (GMS_GMK_SPEAR_WORK)GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_SPEAR_WORK(), "Gmk_Spear");
		OBS_OBJECT_WORK obj_work = gMS_GMK_SPEAR_WORK.gmk_work.ene_com.obj_work;
		GMS_ENEMY_3D_WORK gmk_work = gMS_GMK_SPEAR_WORK.gmk_work;
		ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_spear_obj_3d_list[0], gmk_work.obj_3d);
		obj_work.pos.z = 0;
		obj_work.move_flag |= 256u;
		gMS_GMK_SPEAR_WORK.timer_set_move = 196608;
		gMS_GMK_SPEAR_WORK.stroke_spd = 32768;
		gMS_GMK_SPEAR_WORK.timer_set_wait_upper = 120;
		gMS_GMK_SPEAR_WORK.timer_set_wait_lower = 120;
		gMS_GMK_SPEAR_WORK.timer_dec = eve_rec.height;
		if ((eve_rec.flag & 0x1F) != 0)
		{
			int num;
			if ((eve_rec.flag & 0x10) == 0)
			{
				num = (eve_rec.flag & 0xF) << 10;
			}
			else
			{
				num = -(eve_rec.flag & 0xF) << 10;
				if (num == 0)
				{
					num = -16384;
				}
			}
			gMS_GMK_SPEAR_WORK.stroke_spd += num;
		}
		return obj_work;
	}

