	public static void gmGmkLandMoveInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		obj_work.prev_pos.x = (obj_work.pos.x >> 12) + gMS_ENEMY_3D_WORK.ene_com.eve_rec.left + (gMS_ENEMY_3D_WORK.ene_com.eve_rec.width >> 1);
		obj_work.prev_pos.y = (obj_work.pos.y >> 12) + gMS_ENEMY_3D_WORK.ene_com.eve_rec.top + (gMS_ENEMY_3D_WORK.ene_com.eve_rec.height >> 1);
		obj_work.ppFunc = gmGmkLandMain;
		if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.width | gMS_ENEMY_3D_WORK.ene_com.eve_rec.height) == 0)
		{
			return;
		}
		if (gMS_ENEMY_3D_WORK.ene_com.eve_rec.id != 128)
		{
			int num;
			int num2;
			int num3;
			if (gMS_ENEMY_3D_WORK.ene_com.eve_rec.height < gMS_ENEMY_3D_WORK.ene_com.eve_rec.width)
			{
				num = gMS_ENEMY_3D_WORK.ene_com.eve_rec.width >> 1;
				num2 = obj_work.pos.x >> 12;
				num3 = obj_work.prev_pos.x;
			}
			else
			{
				num = gMS_ENEMY_3D_WORK.ene_com.eve_rec.height >> 1;
				num2 = obj_work.pos.y >> 12;
				num3 = obj_work.prev_pos.y;
			}
			if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 4) == 0)
			{
				ushort num4;
				for (num4 = 768; num4 > 256; num4 -= 4)
				{
					int num5 = num3 + (num * mtMathSin((ushort)(num4 << 6)) >> 12);
					if (num5 > num2)
					{
						break;
					}
				}
				obj_work.user_timer = num4;
			}
			else
			{
				obj_work.user_timer = 0;
				obj_work.user_flag = 0u;
			}
			short num6 = (short)((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 0x30) >> 4 << 8);
			obj_work.user_timer -= num6;
			obj_work.user_timer &= 16383;
		}
		else
		{
			short num7 = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.left * 2);
			short num8 = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.top * 2);
			short num9 = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.width * 2);
			short num10 = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.height * 2);
			int num11 = num9 * 2 + num10 * 2;
			if (num8 == 0)
			{
				obj_work.user_timer = MTM_MATH_ABS(num7) * 4096 / num11;
			}
			else if (num7 == 0)
			{
				obj_work.user_timer = (num11 - MTM_MATH_ABS(num8)) * 4096 / num11;
			}
			else if (num7 + num9 == 0)
			{
				obj_work.user_timer = (num9 + MTM_MATH_ABS(num8)) * 4096 / num11;
			}
			else
			{
				obj_work.user_timer = (num11 - num10 - MTM_MATH_ABS(num7)) * 4096 / num11;
			}
			obj_work.view_out_ofst += 256;
		}
	}

	public static void gmGmkLandMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_COLLISION_OBJ obj_col = obj_work.col_work.obj_col;
		if (obj_work.user_work < 30)
		{
			gmGmkLandMove(obj_work);
		}
		if (obj_col.rider_obj != null && obj_col.rider_obj.ride_obj == obj_work)
		{
			gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 1u;
			if ((obj_work.disp_flag & 2) != 0)
			{
				obj_work.ofst.y = -4096;
			}
			else
			{
				obj_work.ofst.y = 4096;
			}
		}
		if ((gMS_ENEMY_3D_WORK.ene_com.enemy_flag & 1) == 0)
		{
			return;
		}
		if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 0x40) != 0)
		{
			obj_work.user_work++;
			if (obj_work.user_work == 30)
			{
				obj_work.move_flag &= 4294959103u;
				obj_work.move_flag |= 128u;
				obj_work.prev_pos.x = obj_work.pos.x;
				obj_work.prev_pos.y = obj_work.pos.y;
				obj_work.spd_fall_max = 30720;
				if (gMS_ENEMY_3D_WORK.ene_com.eve_rec.id == 83)
				{
					obj_work.move_flag &= 4294967039u;
					obj_work.move_flag |= 1024u;
					obj_work.ppFunc = _gmGmkLandColFall;
				}
				else
				{
					obj_work.ppFunc = null;
				}
			}
		}
		if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 4) != 0)
		{
			obj_work.user_flag |= 65536u;
		}
	}

	public static void gmGmkLandMove(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		byte b = gm_gmk_land_spd_tbl[(byte)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 3)];
		ushort num = (ushort)obj_work.user_timer;
		int num4;
		int num5;
		if (gMS_ENEMY_3D_WORK.ene_com.eve_rec.id != 128)
		{
			int x = obj_work.prev_pos.x;
			int y = obj_work.prev_pos.y;
			short num2 = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.width >> 1);
			short num3 = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.height >> 1);
			if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 4) == 0)
			{
				num = (ushort)((g_gm_main_system.sync_time * b + num) & 0x3FF);
			}
			else if (obj_work.user_flag == 0)
			{
				num = (ushort)(obj_work.user_timer & 0x3FF);
			}
			else
			{
				num = (ushort)((b * (obj_work.user_flag & 0x3FF) + num) & 0x3FF);
				obj_work.user_flag = (obj_work.user_flag & 0x10000) | ((obj_work.user_flag + 1) & 0x3FF);
			}
			if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 8) != 0)
			{
				num4 = (x << 12) + num2 * mtMathSin((ushort)((num << 6) + 32768));
				num5 = (y << 12) + num3 * mtMathSin((ushort)(num << 6));
			}
			else
			{
				num4 = (x << 12) + num2 * mtMathSin((ushort)(num << 6));
				num5 = (y << 12) + num3 * mtMathSin((ushort)(num << 6));
			}
		}
		else
		{
			short num6 = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.left * 2);
			short num7 = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.top * 2);
			short num8 = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.width * 2);
			short num9 = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.height * 2);
			int num10 = num8 * 2 + num9 * 2;
			num = ((b == 0) ? ((ushort)(((g_gm_main_system.sync_time + (num >> 2)) & 0x3FF) << 2)) : ((ushort)((g_gm_main_system.sync_time * b + num) & 0xFFF)));
			int num11 = num10 * num / 4096;
			if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 8) == 0)
			{
				if (num11 <= num8)
				{
					num4 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x + (num6 + (short)num11 << 12);
					num5 = gMS_ENEMY_3D_WORK.ene_com.born_pos_y + (num7 << 12);
				}
				else if (num11 <= num8 + num9)
				{
					num4 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x + (num6 + num8 << 12);
					num5 = gMS_ENEMY_3D_WORK.ene_com.born_pos_y + (num7 + (short)num11 - num8 << 12);
				}
				else if (num11 <= num8 * 2 + num9)
				{
					num4 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x + (num6 + num8 - ((short)num11 - num8 - num9) << 12);
					num5 = gMS_ENEMY_3D_WORK.ene_com.born_pos_y + (num7 + num9 << 12);
				}
				else
				{
					num4 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x + (num6 << 12);
					num5 = gMS_ENEMY_3D_WORK.ene_com.born_pos_y + (num7 + (num9 - ((short)num11 - num8 * 2 - num9)) << 12);
				}
			}
			else if (num11 <= num8)
			{
				num4 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x + (num6 + num8 - (short)num11 << 12);
				num5 = gMS_ENEMY_3D_WORK.ene_com.born_pos_y + (num7 << 12);
			}
			else if (num11 <= num8 + num9)
			{
				num4 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x + (num6 << 12);
				num5 = gMS_ENEMY_3D_WORK.ene_com.born_pos_y + (num7 + (short)num11 - num8 << 12);
			}
			else if (num11 <= num8 * 2 + num9)
			{
				num4 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x + (num6 + ((short)num11 - num8 - num9) << 12);
				num5 = gMS_ENEMY_3D_WORK.ene_com.born_pos_y + (num7 + num9 << 12);
			}
			else
			{
				num4 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x + (num6 + num8 << 12);
				num5 = gMS_ENEMY_3D_WORK.ene_com.born_pos_y + (num7 + (num9 - ((short)num11 - num8 * 2 - num9)) << 12);
			}
		}
		obj_work.move.x = num4 - obj_work.pos.x;
		obj_work.move.y = num5 - obj_work.pos.y;
		obj_work.pos.x = num4;
		obj_work.pos.y = num5;
	}

