	public static void GmGmkGearSetLight()
	{
		NNS_RGBA col = new NNS_RGBA(1f, 1f, 1f, 1f);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		nNS_VECTOR.x = -0.35f;
		nNS_VECTOR.y = 2.25f;
		nNS_VECTOR.z = -0.9f;
		nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
		ObjDrawSetParallelLight(intensity: (g_gs_main_sys_info.stage_id != 14) ? 1f : 0.9f, light_no: NNE_LIGHT_1, col: ref col, vec: nNS_VECTOR);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	public static void GmGmkGearBuild()
	{
		AMS_AMB_HEADER header = GmGameDatGetGimmickData(887);
		for (int i = 0; i < 19; i++)
		{
			gm_gmk_gear_add_data[i] = (AmbChunk)amBindGet(header, i);
		}
		gm_gmk_gear_obj_3d_list = GmGameDBuildRegBuildModel(GmGameDatGetGimmickData(888), GmGameDatGetGimmickData(889), 0u);
		gm_gmk_gear_move_obj_3d_list = GmGameDBuildRegBuildModel(GmGameDatGetGimmickData(890), GmGameDatGetGimmickData(889), 0u);
		gm_gmk_gear_sw_obj_3d_list = GmGameDBuildRegBuildModel(GmGameDatGetGimmickData(890), GmGameDatGetGimmickData(889), 0u, readTXBfile(gm_gmk_gear_add_data[18]));
		gm_gmk_gear_opt_obj_3d_list = GmGameDBuildRegBuildModel(GmGameDatGetGimmickData(891), GmGameDatGetGimmickData(889), 0u);
	}

	public static void GmGmkGearFlush()
	{
		AMS_AMB_HEADER aMS_AMB_HEADER = GmGameDatGetGimmickData(888);
		GmGameDBuildRegFlushModel(gm_gmk_gear_obj_3d_list, aMS_AMB_HEADER.file_num);
		aMS_AMB_HEADER = GmGameDatGetGimmickData(890);
		GmGameDBuildRegFlushModel(gm_gmk_gear_move_obj_3d_list, aMS_AMB_HEADER.file_num);
		GmGameDBuildRegFlushModel(gm_gmk_gear_sw_obj_3d_list, aMS_AMB_HEADER.file_num);
		aMS_AMB_HEADER = GmGameDatGetGimmickData(891);
		GmGameDBuildRegFlushModel(gm_gmk_gear_opt_obj_3d_list, aMS_AMB_HEADER.file_num);
		for (int i = 0; i < gm_gmk_gear_add_data.Length; i++)
		{
			gm_gmk_gear_add_data[i] = null;
		}
	}

	private static void gmGmkGearInFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_GEAR_WORK gMS_GMK_GEAR_WORK = (GMS_GMK_GEAR_WORK)obj_work;
		GmEnemyDefaultInFunc(obj_work);
		if (gMS_GMK_GEAR_WORK.gear_end_obj != null && (gMS_GMK_GEAR_WORK.gear_end_obj.flag & 0xC) != 0)
		{
			gMS_GMK_GEAR_WORK.gear_end_obj = null;
		}
		if (gMS_GMK_GEAR_WORK.move_gear_obj != null && (gMS_GMK_GEAR_WORK.move_gear_obj.flag & 0xC) != 0)
		{
			gMS_GMK_GEAR_WORK.move_gear_obj = null;
		}
		if (gMS_GMK_GEAR_WORK.sw_gear_obj != null && (gMS_GMK_GEAR_WORK.sw_gear_obj.flag & 0xC) != 0)
		{
			gMS_GMK_GEAR_WORK.sw_gear_obj = null;
		}
	}

	private static void gmGmkGearDest(MTS_TASK_TCB tcb)
	{
		GMS_GMK_GEAR_WORK gMS_GMK_GEAR_WORK = (GMS_GMK_GEAR_WORK)mtTaskGetTcbWork(tcb);
		if (gMS_GMK_GEAR_WORK.h_snd_gear != null)
		{
			GmSoundStopSE(gMS_GMK_GEAR_WORK.h_snd_gear);
			GsSoundFreeSeHandle(gMS_GMK_GEAR_WORK.h_snd_gear);
			gMS_GMK_GEAR_WORK.h_snd_gear = null;
		}
		GmEnemyDefaultExit(tcb);
	}

	private static void gmGmkGearFwInit(OBS_OBJECT_WORK obj_work)
	{
		obj_work.ppFunc = gmGmkGearFwMain;
	}

	private static void gmGmkGearFwMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_GEAR_WORK gMS_GMK_GEAR_WORK = (GMS_GMK_GEAR_WORK)obj_work;
		gMS_GMK_GEAR_WORK.dir_temp += gMS_GMK_GEAR_WORK.dir_speed;
		if (gMS_GMK_GEAR_WORK.dir_temp < -65536f)
		{
			gMS_GMK_GEAR_WORK.dir_temp += 65536f;
		}
		else if (gMS_GMK_GEAR_WORK.dir_temp > 65536f)
		{
			gMS_GMK_GEAR_WORK.dir_temp -= 65536f;
		}
		gMS_GMK_GEAR_WORK.prev_dir = obj_work.dir.z;
		if (gMS_GMK_GEAR_WORK.dir_speed > 0f)
		{
			obj_work.dir.z = (ushort)((int)nnRoundOff(gMS_GMK_GEAR_WORK.dir_temp) / 1024 * 1024);
		}
		else
		{
			obj_work.dir.z = (ushort)(((int)nnRoundOff(gMS_GMK_GEAR_WORK.dir_temp) + 1023) / 1024 * 1024);
		}
		gMS_GMK_GEAR_WORK.col_type = (uint)(obj_work.dir.z / 1024 % 8);
		gmGmkGearChangeCol(gMS_GMK_GEAR_WORK);
		if (gMS_GMK_GEAR_WORK.prev_dir != obj_work.dir.z && obj_work.col_work.obj_col.rider_obj != null && obj_work.col_work.obj_col.rider_obj.obj_type == 1)
		{
			OBS_OBJECT_WORK rider_obj = obj_work.col_work.obj_col.rider_obj;
			float num = FXM_FX32_TO_FLOAT(rider_obj.pos.x - obj_work.pos.x);
			float num2 = 0f - FXM_FX32_TO_FLOAT(rider_obj.pos.y - obj_work.pos.y);
			int ang = obj_work.dir.z - gMS_GMK_GEAR_WORK.prev_dir;
			float num3 = nnCos(ang) * num + nnSin(ang) * num2;
			float num4 = (0f - nnSin(ang)) * num + nnCos(ang) * num2;
			rider_obj.prev_pos.x = rider_obj.pos.x;
			rider_obj.prev_pos.y = rider_obj.pos.y;
			rider_obj.pos.x += FXM_FLOAT_TO_FX32(num3 - num);
			rider_obj.pos.y += -FXM_FLOAT_TO_FX32(num4 - num2);
			rider_obj.move.x = rider_obj.pos.x - rider_obj.prev_pos.x;
			rider_obj.move.y = rider_obj.pos.y - rider_obj.prev_pos.y;
		}
	}

	private static void gmGmkGearChangeCol(GMS_GMK_GEAR_WORK gear_work)
	{
		byte[] array;
		if (gm_gmk_gear_add_data[gear_work.col_type * 2] is AmbChunk)
		{
			AmbChunk ambChunk = (AmbChunk)gm_gmk_gear_add_data[gear_work.col_type * 2];
			array = new byte[ambChunk.length];
			Buffer.BlockCopy(ambChunk.array, ambChunk.offset, array, 0, ambChunk.length);
			gm_gmk_gear_add_data[gear_work.col_type * 2] = array;
		}
		else
		{
			array = (byte[])gm_gmk_gear_add_data[gear_work.col_type * 2];
		}
		gear_work.gmk_work.ene_com.col_work.obj_col.diff_data = array;
	}

	private static void gmGmkMoveGearFwInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_GEAR_WORK gMS_GMK_GEAR_WORK = (GMS_GMK_GEAR_WORK)obj_work;
		if (gMS_GMK_GEAR_WORK.rect_ret_timer == 0)
		{
			gMS_GMK_GEAR_WORK.gmk_work.ene_com.rect_work[2].flag &= 4294965247u;
			gMS_GMK_GEAR_WORK.gmk_work.ene_com.rect_work[0].flag &= 4294965247u;
		}
		obj_work.flag &= 4294967279u;
		obj_work.spd_m = 0;
		obj_work.spd.x = (obj_work.spd.y = 0);
		obj_work.spd_add.x = (obj_work.spd_add.y = 0);
		gMS_GMK_GEAR_WORK.vib_end = false;
		obj_work.ppFunc = gmGmkMoveGearFwMain;
	}

	private static void gmGmkMoveGearFwMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_GEAR_WORK gMS_GMK_GEAR_WORK = (GMS_GMK_GEAR_WORK)obj_work;
		if (gMS_GMK_GEAR_WORK.rect_ret_timer != 0)
		{
			gMS_GMK_GEAR_WORK.rect_ret_timer = ObjTimeCountDown(gMS_GMK_GEAR_WORK.rect_ret_timer);
			if (gMS_GMK_GEAR_WORK.rect_ret_timer == 0)
			{
				gMS_GMK_GEAR_WORK.gmk_work.ene_com.rect_work[2].flag &= 4294965247u;
				gMS_GMK_GEAR_WORK.gmk_work.ene_com.rect_work[0].flag &= 4294965247u;
			}
