	private static void gmGmkMoveGearMoveInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_GEAR_WORK gMS_GMK_GEAR_WORK = (GMS_GMK_GEAR_WORK)obj_work;
		obj_work.user_flag &= 4294967294u;
		gMS_GMK_GEAR_WORK.gmk_work.ene_com.rect_work[2].flag |= 2048u;
		gMS_GMK_GEAR_WORK.gmk_work.ene_com.rect_work[0].flag &= 4294965247u;
		obj_work.flag |= 16u;
		obj_work.move_flag &= 4294959103u;
		gMS_GMK_GEAR_WORK.stop_timer = 737280;
		obj_work.ppFunc = gmGmkMoveGearMoveMain;
	}

	private static void gmGmkMoveGearMoveMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_GEAR_WORK gMS_GMK_GEAR_WORK = (GMS_GMK_GEAR_WORK)obj_work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)gMS_GMK_GEAR_WORK.gmk_work.ene_com.target_obj;
		if (gMS_PLAYER_WORK == null || gMS_PLAYER_WORK.gmk_obj != obj_work)
		{
			gMS_GMK_GEAR_WORK.gmk_work.ene_com.target_obj = null;
			gmGmkMoveGearRetWaitInit(obj_work);
			return;
		}
		gmGmkMoveGearSetSpd(obj_work, -gMS_PLAYER_WORK.obj_work.spd_m);
		if (obj_work.spd_m != 0 && !gMS_GMK_GEAR_WORK.vib_end)
		{
			GMM_PAD_VIB_SMALL_TIME(60f);
			gMS_GMK_GEAR_WORK.vib_end = true;
		}
		if (gMS_PLAYER_WORK.obj_work.spd_m == 0)
		{
			gMS_GMK_GEAR_WORK.stop_timer = ObjTimeCountDown(gMS_GMK_GEAR_WORK.stop_timer);
		}
		else
		{
			gMS_GMK_GEAR_WORK.stop_timer = 737280;
		}
		if (gMS_GMK_GEAR_WORK.stop_timer == 0)
		{
			gMS_GMK_GEAR_WORK.gmk_work.ene_com.enemy_flag |= 1u;
			gMS_GMK_GEAR_WORK.gmk_work.ene_com.target_obj = null;
			gmGmkMoveGearRetInit(obj_work);
		}
