	private static void gmGmkGearSetRotFlow(OBS_OBJECT_WORK gear_obj, GMS_PLAYER_WORK ply_work, int move_dir)
	{
		int num = ply_work.obj_work.pos.x - gear_obj.pos.x;
		int num2 = ply_work.obj_work.pos.y - gear_obj.pos.y;
		float num3 = FXM_FX32_TO_FLOAT(num);
		float num4 = FXM_FX32_TO_FLOAT(num2);
		int num5 = nnArcTan2(0f - num4, num3);
		float num6 = nnSqrt(num3 * num3 + num4 * num4);
		int ang = num5 + move_dir;
		int num7 = FXM_FLOAT_TO_FX32(nnCos(ang) * num6);
		int num8 = -FXM_FLOAT_TO_FX32(nnSin(ang) * num6);
		int num9 = FX_Mul(num7 - num, 5120);
		if (MTM_MATH_ABS(num9) < 4096)
		{
			num9 = ((num9 <= 0 && gear_obj.spd_m <= 0) ? (-4096) : 4096);
		}
		if (ply_work.obj_work.ride_obj == gear_obj)
		{
			ply_work.obj_work.flow.x += num9;
			ply_work.obj_work.flow.y += num8 - num2;
		}
		else if (ply_work.obj_work.ride_obj == null && ply_work.obj_work.touch_obj == gear_obj)
		{
			if ((move_dir > 0 && ply_work.obj_work.spd_m < -32768 && ply_work.obj_work.pos.y > gear_obj.pos.y) || (move_dir < 0 && ply_work.obj_work.spd_m > 32768 && ply_work.obj_work.pos.y < gear_obj.pos.y))
			{
				ply_work.obj_work.move_flag &= 4294967294u;
			}
			else if ((ply_work.obj_work.move_flag & 1) != 0 && ((move_dir < 0 && ply_work.obj_work.spd_m >= 0 && ply_work.obj_work.pos.x > gear_obj.pos.x) || (move_dir > 0 && ply_work.obj_work.spd_m <= 0 && ply_work.obj_work.pos.x < gear_obj.pos.x)))
			{
				ply_work.obj_work.flow.x += (num9 + gear_obj.move.x) * 2;
				ply_work.obj_work.flow.y += num8 - num2;
				ply_work.obj_work.move_flag &= 4294967294u;
			}
		}
	}

