	public static void gmDataLoadMain(MTS_TASK_TCB tcb)
	{
		GMS_GAMEDAT_LOAD_WORK gMS_GAMEDAT_LOAD_WORK = (GMS_GAMEDAT_LOAD_WORK)tcb.work;
		GME_GAMEDAT_LOAD_STATE gME_GAMEDAT_LOAD_STATE = ((gMS_GAMEDAT_LOAD_WORK.proc_type == 1) ? GME_GAMEDAT_LOAD_STATE.GMD_GAMEDAT_LOAD_STATE_LOADFINISH : GME_GAMEDAT_LOAD_STATE.GMD_GAMEDAT_LOAD_STATE_COMPLETE);
		for (int i = 0; i < gMS_GAMEDAT_LOAD_WORK.context_num; i++)
		{
			GME_GAMEDAT_LOAD_STATE gME_GAMEDAT_LOAD_STATE2 = gmGameDatLoad(gMS_GAMEDAT_LOAD_WORK.context[i]);
			if (gME_GAMEDAT_LOAD_STATE2 < gME_GAMEDAT_LOAD_STATE)
			{
				return;
			}
		}
		gMS_GAMEDAT_LOAD_WORK.load_finish = true;
		if (gMS_GAMEDAT_LOAD_WORK.proc_type == 1)
		{
			mtTaskChangeTcbProcedure(tcb, gmDataLoadMainPostWait);
			return;
		}
		gMS_GAMEDAT_LOAD_WORK.post_finish = true;
		mtTaskChangeTcbProcedure(tcb, null);
	}

	public static void gmDataLoadMainPostWait(MTS_TASK_TCB tcb)
	{
		GMS_GAMEDAT_LOAD_WORK gMS_GAMEDAT_LOAD_WORK = (GMS_GAMEDAT_LOAD_WORK)tcb.work;
		if (gMS_GAMEDAT_LOAD_WORK.proc_type == 0)
		{
			mtTaskChangeTcbProcedure(tcb, gmDataLoadMain);
			gmDataLoadMain(tcb);
		}
	}

