	public static GME_GAMEDAT_LOAD_STATE gmGameDatLoad(GMS_GAMEDAT_LOAD_CONTEXT context)
	{
		return gmGameDatLoadFileReq(context);
	}

	public static GME_GAMEDAT_LOAD_STATE gmGameDatLoadFileReq(GMS_GAMEDAT_LOAD_CONTEXT context)
	{
		if (context.state == GME_GAMEDAT_LOAD_STATE.GMD_GAMEDAT_LOAD_STATE_COMPLETE || context.state == GME_GAMEDAT_LOAD_STATE.GMD_GAMEDAT_LOAD_STATE_ERROR)
		{
			return context.state;
		}
		GMS_GAMEDAT_LOAD_DATA load_data = context.load_data;
		if (context.fs_req == null)
		{
			context.file_path = load_data.path;
			if (load_data.proc_pre != null)
			{
				load_data.proc_pre(context);
			}
			int stage_id = context.stage_id;
			if ((7 == stage_id && "G_ZONE2/BOSS/BOSS02.AMB" == context.file_path) || (11 == stage_id && "G_ZONE3/BOSS/BOSS03.AMB" == context.file_path) || (15 == stage_id && "G_ZONEF/BOSS/BOSS04.AMB" == context.file_path) || (16 == stage_id && "G_ZONEF/BOSS/BOSS05.AMB" == context.file_path))
			{
				context.fs_req = amFsReadBackground(context.file_path, 8192);
			}
			else
			{
				context.fs_req = amFsReadBackground(context.file_path, 65536);
			}
			context.state = GME_GAMEDAT_LOAD_STATE.GMD_GAMEDAT_LOAD_STATE_LOADING;
		}
		else if (amFsIsComplete(context.fs_req))
		{
			context.state = GME_GAMEDAT_LOAD_STATE.GMD_GAMEDAT_LOAD_STATE_COMPLETE;
			if (gm_gamedat_load_work.proc_type != 1 && context.fs_req != null)
			{
				if (load_data.proc_post != null)
				{
					load_data.proc_post(context);
				}
				amFsClearRequest(context.fs_req);
				context.fs_req = null;
			}
		}
		return context.state;
	}

