	public static void gmGameDatLoadProcPostMap(GMS_GAMEDAT_LOAD_CONTEXT context)
	{
		g_gm_gamedat_map[context.data_no] = readAMBFile(context.fs_req);
		switch (context.data_no)
		{
		default:
			return;
		case 0:
		{
			AMS_AMB_HEADER aMS_AMB_HEADER2 = readAMBFile(context.fs_req);
			for (int j = 0; j < 9 && j < aMS_AMB_HEADER2.file_num; j++)
			{
				switch (j)
				{
				case 0:
				case 1:
				case 4:
				case 5:
					g_gm_gamedat_map_set[j] = readMPFile((AmbChunk)amBindGet(aMS_AMB_HEADER2, j));
					break;
				case 2:
				case 3:
					g_gm_gamedat_map_set[j] = readMDFile((AmbChunk)amBindGet(aMS_AMB_HEADER2, j));
					break;
				default:
					g_gm_gamedat_map_set[j] = amBindGet(aMS_AMB_HEADER2, j);
					break;
				}
			}
			for (int j = 0; j < 10; j += 2)
			{
				if (aMS_AMB_HEADER2.file_num >= 11 + j)
				{
					g_gm_gamedat_map_set_add[j] = readMPFile((AmbChunk)amBindGet(aMS_AMB_HEADER2, 9 + j));
					g_gm_gamedat_map_set_add[j + 1] = readMDFile((AmbChunk)amBindGet(aMS_AMB_HEADER2, 9 + j + 1));
				}
				else
				{
					g_gm_gamedat_map_set_add[j] = null;
					g_gm_gamedat_map_set_add[j + 1] = null;
				}
			}
			break;
		}
		case 1:
		{
			AMS_AMB_HEADER aMS_AMB_HEADER3 = (AMS_AMB_HEADER)g_gm_gamedat_map[context.data_no];
			TVX_FILE[] array = new TVX_FILE[aMS_AMB_HEADER3.file_num];
			for (int k = 0; k < aMS_AMB_HEADER3.file_num; k++)
			{
				array[k] = new TVX_FILE((AmbChunk)amBindGet(aMS_AMB_HEADER3, k));
			}
			if (g_gs_main_sys_info.stage_id >= 0 && g_gs_main_sys_info.stage_id <= 3)
			{
				for (int l = 0; l < aMS_AMB_HEADER3.file_num; l++)
				{
					float num = array[l].vertexes[0][0].x;
					float num2 = array[l].vertexes[0][0].x;
					float num3 = array[l].vertexes[0][0].y;
					float num4 = array[l].vertexes[0][0].y;
					for (int m = 1; m < array[l].vertexes[0].Length; m++)
					{
						num = Math.Min(num, array[l].vertexes[0][m].x);
						num2 = Math.Max(num2, array[l].vertexes[0][m].x);
						num3 = Math.Min(num3, array[l].vertexes[0][m].y);
						num4 = Math.Max(num4, array[l].vertexes[0][m].y);
					}
					for (int n = 0; n < array[l].vertexes[0].Length; n++)
					{
						if (array[l].vertexes[0][n].x == num)
						{
							array[l].vertexes[0][n].x -= 0.5f;
						}
						else if (array[l].vertexes[0][n].x == num2)
						{
							array[l].vertexes[0][n].x += 0.5f;
						}
						if (array[l].vertexes[0][n].y == num3)
						{
							array[l].vertexes[0][n].y -= 0.5f;
						}
						else if (array[l].vertexes[0][n].y == num4)
						{
							array[l].vertexes[0][n].y += 0.5f;
						}
					}
				}
				if (g_gs_main_sys_info.stage_id == 2)
				{
					array[103].vertexes[0][1].x = 63.5f;
					array[103].vertexes[0][3].x = 63.5f;
				}
			}
			if (g_gs_main_sys_info.stage_id >= 4 && g_gs_main_sys_info.stage_id <= 7)
			{
				array[201].vertexes[1][1].x = 64f;
				array[201].vertexes[1][3].x = 64f;
			}
			if (g_gs_main_sys_info.stage_id >= 8 && g_gs_main_sys_info.stage_id <= 11)
			{
				for (int num5 = 59; num5 <= 62; num5++)
				{
					array[num5].vertexes[0][0].x = 64.5f;
					array[num5].vertexes[0][2].x = 64.5f;
					array[num5].vertexes[0][0].y = 64.5f;
					array[num5].vertexes[0][1].y = 64.5f;
					array[num5].vertexes[0][1].x = -0.5f;
					array[num5].vertexes[0][3].x = -0.5f;
					array[num5].vertexes[0][2].y = -0.5f;
					array[num5].vertexes[0][3].y = -0.5f;
				}
			}
			g_gm_gamedat_map[context.data_no] = array;
			break;
		}
		case 3:
		{
			AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile(context.fs_req);
			for (int i = 0; i < 3 && i < aMS_AMB_HEADER.file_num; i++)
			{
				g_gm_gamedat_map_attr_set[i] = amBindGet(aMS_AMB_HEADER, i);
			}
			break;
		}
		case 2:
			break;
		}
		context.fs_req = null;
	}

