	private static void GmComEfctSetDispOffset(GMS_EFFECT_3DES_WORK efct_work, int ofst_x, int ofst_y, int ofst_z)
	{
		if ((efct_work.efct_com.obj_work.disp_flag & 0x400000) != 0)
		{
			GmEffect3DESSetDispOffset(efct_work, FXM_FX32_TO_FLOAT(ofst_x), FXM_FX32_TO_FLOAT(-ofst_y), FXM_FX32_TO_FLOAT(ofst_z));
		}
		else
		{
			GmEffect3DESSetDispOffset(efct_work, FXM_FX32_TO_FLOAT(-ofst_z), FXM_FX32_TO_FLOAT(-ofst_y), FXM_FX32_TO_FLOAT(ofst_x));
		}
	}

