	private static void GmBoss4EggmanBuild()
	{
		ObjDataLoadAmbIndex(ObjDataGet(731), 3, GMD_BOSS4_ARC);
	}

	private static void GmBoss4EggmanFlush()
	{
		ObjDataRelease(ObjDataGet(731));
	}

	private static OBS_OBJECT_WORK GmBoss4EggInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BOSS4_EGG_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_BOSS4_EGG_WORK(), "Boss4_EGG");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_BOSS4_EGG_WORK gMS_BOSS4_EGG_WORK = (GMS_BOSS4_EGG_WORK)oBS_OBJECT_WORK;
		gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 32768u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, GmBoss4GetObj3D(1), gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(731), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.obj_3d.blend_spd = 0.125f;
		oBS_OBJECT_WORK.disp_flag |= 134217728u;
		oBS_OBJECT_WORK.ppFunc = gmBoss4EggWaitLoad;
		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.disp_flag |= 4u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		gMS_BOSS4_EGG_WORK.dir_work.direction = 0;
		GmBoss4UtilInitTurnGently(gMS_BOSS4_EGG_WORK.dir_work, 0, 1, false);
		GmBoss4UtilUpdateTurnGently(gMS_BOSS4_EGG_WORK.dir_work);
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmBoss4EggExit);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

	private static void gmBoss4EggExit(MTS_TASK_TCB tcb)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(tcb);
		GMS_BOSS4_EGG_WORK gMS_BOSS4_EGG_WORK = (GMS_BOSS4_EGG_WORK)oBS_OBJECT_WORK;
		GmBoss4DecObjCreateCount();
		GmBoss4UtilExitNodeMatrix(gMS_BOSS4_EGG_WORK.node_work);
		GmEnemyDefaultExit(tcb);
	}

	private static void gmBoss4EggSetActionIndependent(GMS_BOSS4_EGG_WORK egg_work, int act_id)
	{
		gmBoss4EggSetActionIndependent(egg_work, act_id, false);
	}

	private static void gmBoss4EggSetActionIndependent(GMS_BOSS4_EGG_WORK egg_work, int act_id, bool force_change)
	{
		GMS_BOSS4_PART_ACT_INFO gMS_BOSS4_PART_ACT_INFO = gm_boss4_egg_act_id_tbl[act_id];
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		if ((gMS_BOSS4_BODY_WORK.flag[0] & 2) == 0 && (force_change || (egg_work.flag & 1) == 0 || egg_work.egg_act_id != act_id))
		{
			egg_work.egg_act_id = act_id;
			egg_work.flag |= 1u;
			if (gMS_BOSS4_PART_ACT_INFO.is_maintain == 0)
			{
				GmBsCmnSetAction(oBS_OBJECT_WORK, gMS_BOSS4_PART_ACT_INFO.act_id, gMS_BOSS4_PART_ACT_INFO.is_repeat, gMS_BOSS4_PART_ACT_INFO.is_blend);
			}
			else if (gMS_BOSS4_PART_ACT_INFO.is_repeat != 0)
			{
				GMM_BS_OBJ(egg_work).disp_flag |= 4u;
			}
			oBS_OBJECT_WORK.obj_3d.speed[0] = gMS_BOSS4_PART_ACT_INFO.mtn_spd;
			oBS_OBJECT_WORK.obj_3d.blend_spd = gMS_BOSS4_PART_ACT_INFO.blend_spd;
		}
	}

	private static void gmBoss4EggRevertActionIndependent(GMS_BOSS4_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		MTM_ASSERT(egg_work.flag & 1);
		egg_work.flag &= 4294967294u;
		GmBsCmnSetAction(oBS_OBJECT_WORK, GmBoss4GetActInfo(gMS_BOSS4_BODY_WORK.egg_revert_mtn_id, 1).act_id, GmBoss4GetActInfo(gMS_BOSS4_BODY_WORK.egg_revert_mtn_id, 1).is_repeat, 1);
		oBS_OBJECT_WORK.obj_3d.frame[0] = GMM_BS_OBJ(gMS_BOSS4_BODY_WORK).obj_3d.frame[0];
	}

	private static void gmBoss4EggWaitLoad(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_BODY_WORK work = (GMS_BOSS4_BODY_WORK)obj_work.parent_obj;
		GMS_BOSS4_EGG_WORK gMS_BOSS4_EGG_WORK = (GMS_BOSS4_EGG_WORK)obj_work;
		if ((GMM_BOSS4_MGR(work).flag & 1) != 0)
		{
			obj_work.ppFunc = gmBoss4EggMain;
			gmBoss4EggProcIdleInit(gMS_BOSS4_EGG_WORK);
			GmBoss4UtilInitNodeMatrix(gMS_BOSS4_EGG_WORK.node_work, obj_work, 4);
		}
	}

	private static void gmBoss4EggMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)obj_work.parent_obj;
		GMS_BOSS4_EGG_WORK gMS_BOSS4_EGG_WORK = (GMS_BOSS4_EGG_WORK)obj_work;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gMS_BOSS4_BODY_WORK;
		NNS_MATRIX nNS_MATRIX = GmBoss4UtilGetNodeMatrix(gMS_BOSS4_BODY_WORK.node_work, 2);
		NNS_MATRIX nNS_MATRIX2 = GmBoss4UtilGetNodeMatrix(gMS_BOSS4_BODY_WORK.node_work, 2);
		NNS_MATRIX nNS_MATRIX3 = GlobalPool<NNS_MATRIX>.Alloc();
		nnCopyMatrix(nNS_MATRIX3, nNS_MATRIX);
		nNS_MATRIX3.M03 = nNS_MATRIX.M03 - nNS_MATRIX2.M03 + (float)oBS_OBJECT_WORK.pos.x / 4096f;
		GmBoss4UtilSetMatrixNN(obj_work, nNS_MATRIX3);
		GmBoss4UtilUpdateTurnGently(gMS_BOSS4_EGG_WORK.dir_work);
		GmBoss4UtilUpdateDirection(gMS_BOSS4_EGG_WORK.dir_work, obj_work);
		if (gMS_BOSS4_EGG_WORK.proc_update != null)
		{
			gMS_BOSS4_EGG_WORK.proc_update(gMS_BOSS4_EGG_WORK);
		}
		if ((gMS_BOSS4_BODY_WORK.flag[0] & 0x800000) != 0)
		{
			gMS_BOSS4_BODY_WORK.flag[0] &= 4286578687u;
			gmBoss4EggProcEscapeInit(gMS_BOSS4_EGG_WORK);
		}
		if ((gMS_BOSS4_BODY_WORK.flag[0] & 0x200000) != 0)
		{
			gMS_BOSS4_BODY_WORK.flag[0] &= 4292870143u;
			gmBoss4EggProcThrowInit(gMS_BOSS4_EGG_WORK);
		}
		if ((gMS_BOSS4_BODY_WORK.flag[0] & 0x400000) != 0)
		{
			gMS_BOSS4_BODY_WORK.flag[0] &= 4290772991u;
			gmBoss4EggProcThrowLeftInit(gMS_BOSS4_EGG_WORK);
		}
		if ((gMS_BOSS4_BODY_WORK.flag[0] & 0x20000000) != 0)
		{
