	private static void dmStfrlMdlCtrlSonicProcWaitMtnEnd(OBS_OBJECT_WORK obj_work)
	{
		DMS_STFRL_SONIC_WORK dMS_STFRL_SONIC_WORK = (DMS_STFRL_SONIC_WORK)obj_work;
		dMS_STFRL_SONIC_WORK.timer++;
		if (obj_work.spd_m <= 25292)
		{
			obj_work.spd_m += 512;
		}
		if ((obj_work.disp_flag & 8) != 0)
		{
