	private static int nnCalcMotionNodeHide(NNS_SUBMOTION submot, float frame)
	{
		int val = 0;
		NNS_MOTION_KEY_Class11[] vk = (NNS_MOTION_KEY_Class11[])submot.pKeyList;
		int nKeyFrame = submot.nKeyFrame;
		uint num = submot.fIPType & 0xE77;
		if (num == 4)
		{
			nnInterpolateConstantS32_1(vk, nKeyFrame, frame, out val);
		}
		return val;
	}

	private static void nnCalcNodeHideMotion(ArrayPointer<uint> nodestatlist, NNS_MOTION mot, float frame)
	{
		float dstframe;
		if ((mot.fType & 1) == 0 || nnCalcMotionFrame(out dstframe, mot.fType, mot.StartFrame, mot.EndFrame, frame) == 0)
		{
			return;
		}
		ArrayPointer<NNS_SUBMOTION> arrayPointer = new ArrayPointer<NNS_SUBMOTION>(mot.pSubmotion);
		for (int i = 0; i < mot.nSubmotion; i++)
		{
			NNS_SUBMOTION nNS_SUBMOTION = arrayPointer + i;
			if ((nNS_SUBMOTION.fType & 0x100000) != 0 && nNS_SUBMOTION.StartFrame <= dstframe && dstframe <= nNS_SUBMOTION.EndFrame)
			{
				uint fType = nNS_SUBMOTION.fIPType;
				if ((mot.fType & 0x20000) != 0 && dstframe == nNS_SUBMOTION.EndFrame)
				{
					fType = 131072u;
				}
				float dstframe2;
				if (nnCalcMotionFrame(out dstframe2, fType, nNS_SUBMOTION.StartKeyFrame, nNS_SUBMOTION.EndKeyFrame, dstframe) != 0 && nnCalcMotionNodeHide(nNS_SUBMOTION, dstframe2) != 0)
				{
					(nodestatlist + nNS_SUBMOTION.Id).SetPrimitive((nodestatlist + nNS_SUBMOTION.Id)[0] | 1);
				}
			}
		}
	}

