	private static void gmGmkWaterSliderDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		OBS_ACTION3D_NN_WORK obj_3d = obj_work.obj_3d;
		if (obj_3d.motion != null)
		{
			float num = amMotionMaterialGetStartFrame(obj_3d.motion, obj_3d.mat_act_id);
			float num2 = amMotionMaterialGetEndFrame(obj_3d.motion, obj_3d.mat_act_id);
			float num3 = num2 - num;
			float num4 = gmGmkWaterSlidereGameSystemGetSyncTime();
			obj_3d.mat_frame = num4 % num3;
		}
		ObjDrawActionSummary(obj_work);
		uint disp_flag = obj_work.disp_flag;
		disp_flag |= 4;
		disp_flag &= 0xFFFFFFEFu;
		if (ObjObjectPauseCheck(0u) != 0)
		{
			disp_flag |= 0x1000;
		}
		GMS_GMK_WATER_SLIDER_WORK gMS_GMK_WATER_SLIDER_WORK = (GMS_GMK_WATER_SLIDER_WORK)obj_work;
		VecFx32 pos = obj_work.pos;
		pos.z += 131072;
		ObjDrawAction3DNN(gMS_GMK_WATER_SLIDER_WORK.obj_3d_parts, pos, obj_work.dir, obj_work.scale, ref disp_flag);
	}

	private static void gmGmkWaterSliderDefFunc(OBS_RECT_WORK gimmick_rect, OBS_RECT_WORK player_rect)
	{
		OBS_OBJECT_WORK parent_obj = gimmick_rect.parent_obj;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)parent_obj;
		OBS_OBJECT_WORK parent_obj2 = player_rect.parent_obj;
		if (parent_obj2.obj_type != 1)
		{
			return;
		}
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)parent_obj2;
		if (gMS_PLAYER_WORK.seq_state == 36)
		{
			gMS_PLAYER_WORK.gmk_obj = parent_obj;
		}
		else if ((parent_obj2.move_flag & 1) != 0)
		{
			uint type = gmGmkWaterSliderGetUserWorkSlideType(parent_obj);
			if (gmGmkWaterSliderCheckHFlip(type))
			{
				parent_obj2.disp_flag &= 4294967294u;
			}
			else
			{
				parent_obj2.disp_flag |= 1u;
			}
			parent_obj2.spd_m = gmGmkWaterSliderGetUserTimerSlideSpeed(parent_obj);
			parent_obj2.spd.x = 0;
			parent_obj2.spd.y = 0;
			parent_obj2.spd_add.x = 0;
			parent_obj2.spd_add.y = 0;
			GmPlySeqInitWaterSlider(gMS_PLAYER_WORK, gMS_ENEMY_3D_WORK.ene_com);
			gMS_ENEMY_3D_WORK.ene_com.target_obj = parent_obj2;
			gimmick_rect.flag |= 1024u;
			parent_obj.ppFunc = gmGmkWaterSliderMainActive;
			GmGmkWaterSliderCreateEffect();
			nnMakeUnitMatrix(gMS_PLAYER_WORK.ex_obj_mtx_r);
			int num = -6144;
			if ((parent_obj2.disp_flag & 1) != 0)
			{
				num = -num;
			}
			nnRotateYMatrix(gMS_PLAYER_WORK.ex_obj_mtx_r, gMS_PLAYER_WORK.ex_obj_mtx_r, num);
			gMS_PLAYER_WORK.ex_obj_mtx_r.M13 = -2f;
			gMS_PLAYER_WORK.gmk_flag |= 32768u;
		}
	}

