		int x = FX_Mul(vec.x, vec.x) + FX_Mul(vec.y, vec.y);
		x = FX_Sqrt(x);
		if (x == 0)
		{
			result.x = 4096;
			result.y = 0;
		}
		else
		{
			int v = FX_Div(4096, x);
			result.x = FX_Mul(vec.x, v);
			result.y = FX_Mul(vec.y, v);
		}
		result.z = 0;
		return result;
	}

