	private static int gmGmkEnBmprCheckGroupBonus(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		int num = gmGmkEnBmperGetUserWorkLife(obj_work);
		if (num > 0)
		{
			return 0;
		}
		sbyte top = gMS_ENEMY_3D_WORK.ene_com.eve_rec.top;
		if (top == 0)
		{
			return 0;
		}
		for (OBS_OBJECT_WORK oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, 3); oBS_OBJECT_WORK != null; oBS_OBJECT_WORK = ObjObjectSearchRegistObject(oBS_OBJECT_WORK, 3))
		{
			GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)oBS_OBJECT_WORK;
			if (oBS_OBJECT_WORK != obj_work && (gMS_ENEMY_COM_WORK.eve_rec.id == 164 || gMS_ENEMY_COM_WORK.eve_rec.id == 165 || gMS_ENEMY_COM_WORK.eve_rec.id == 166 || gMS_ENEMY_COM_WORK.eve_rec.id == 167) && gMS_ENEMY_COM_WORK.eve_rec.top == top && (Convert.ToInt32(oBS_OBJECT_WORK.user_flag) & 1) != 0)
			{
				return 0;
			}
		}
		return 1;
	}

