	private static OBS_OBJECT_WORK GmGmkCamScrLimitInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_CAM_SCR_LIMIT_WORK(), "GMK_CAM_SCRLMT");
		GMS_GMK_CAM_SCR_LIMIT_WORK gMS_GMK_CAM_SCR_LIMIT_WORK = (GMS_GMK_CAM_SCR_LIMIT_WORK)oBS_OBJECT_WORK;
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)oBS_OBJECT_WORK;
		gMS_ENEMY_COM_WORK.enemy_flag |= 65536u;
		oBS_OBJECT_WORK.user_flag = eve_rec.flag;
		oBS_OBJECT_WORK.move_flag |= 8480u;
		oBS_OBJECT_WORK.flag |= 16u;
		GMS_GMK_CAM_SCR_LIMIT_SETTING limit_setting = gMS_GMK_CAM_SCR_LIMIT_WORK.limit_setting;
		limit_setting.limit_rect[0] = (oBS_OBJECT_WORK.pos.x >> 12) + eve_rec.left * 2;
		limit_setting.limit_rect[2] = (oBS_OBJECT_WORK.pos.x >> 12) + eve_rec.left * 2 + eve_rec.width * 2;
		limit_setting.limit_rect[1] = (oBS_OBJECT_WORK.pos.y >> 12) + eve_rec.top * 2;
		limit_setting.limit_rect[3] = (oBS_OBJECT_WORK.pos.y >> 12) + eve_rec.top * 2 + eve_rec.height * 2;
		if (eve_rec.id == 302)
		{
			oBS_OBJECT_WORK.ppFunc = gmGmkCamScrLimitSetting;
			g_gm_main_system.game_flag |= 32768u;
		}
		else
		{
			oBS_OBJECT_WORK.ppFunc = gmGmkCamScrLimitMain;
		}
		return oBS_OBJECT_WORK;
	}

