	private static void GmFixBuildDataInit()
	{
		for (int i = 0; i < 3; i++)
		{
			gm_fix_textures[i].Clear();
		}
		for (int j = 0; j < 3; j++)
		{
			gm_fix_texamb_list[j] = ObjDataLoadAmbIndex(null, gm_fix_tex_amb_idx_tbl[GsEnvGetLanguage()][j], GmGameDatGetCockpitData());
			AoTexBuild(gm_fix_textures[j], (AMS_AMB_HEADER)gm_fix_texamb_list[j]);
			AoTexLoad(gm_fix_textures[j]);
		}
	}

	private static bool GmFixBuildDataLoop()
	{
		bool result = true;
		for (int i = 0; i < 3; i++)
		{
			if (!AoTexIsLoaded(gm_fix_textures[i]))
			{
				result = false;
			}
		}
		return result;
	}

	private static void GmFixFlushDataInit()
	{
		for (int i = 0; i < 3; i++)
		{
			AoTexRelease(gm_fix_textures[i]);
		}
	}

	private static bool GmFixFlushDataLoop()
	{
		bool result = true;
		for (int i = 0; i < 3; i++)
		{
			if (gm_fix_texamb_list[i] != null)
			{
				if (!AoTexIsReleased(gm_fix_textures[i]))
				{
					result = false;
					continue;
				}
				gm_fix_texamb_list[i] = null;
				gm_fix_textures[i].Clear();
			}
		}
		return result;
	}

	private static void GmFixInit()
	{
		gm_fix_tcb = MTM_TASK_MAKE_TCB(gmFixProcMain, gmFixDest, 0u, 0, 18432u, 5, () => new GMS_FIX_MGR_WORK(), "GM_FIX_MGR");
		GMS_FIX_MGR_WORK gMS_FIX_MGR_WORK = (GMS_FIX_MGR_WORK)gm_fix_tcb.work;
		gMS_FIX_MGR_WORK.Clear();
		GMF_FIX_PART_INIT_FUNC[] array;
		if (!gmFixIsSpecialStage())
		{
			array = ((!gmFixIsTimeAttack()) ? gm_fix_part_init_func_tbl : ((!gmFixIsStage22()) ? gm_fix_ta_part_init_func_tbl : gm_fix_ta_s22_part_init_func_tbl));
		}
		else
		{
			array = gm_fix_ss_part_init_func_tbl;
			gMS_FIX_MGR_WORK.flag |= 4u;
		}
		for (int num = 0; num < 5; num++)
		{
			if (array[num] != null)
			{
				array[num](gMS_FIX_MGR_WORK);
			}
		}
		gMS_FIX_MGR_WORK.proc_update = null;
	}

	private static void GmFixExit()
	{
		if (gm_fix_tcb != null)
		{
			mtTaskClearTcb(gm_fix_tcb);
			gm_fix_tcb = null;
		}
	}

	private static void GmFixSetDisp(bool enable)
	{
		GmFixSetDispEx(enable, enable, enable, enable, enable);
	}

	private static void GmFixSetDispEx(bool enable, bool enable_ss, bool enable_pause, bool enable_action, bool enable_move)
	{
		if (gm_fix_tcb != null)
		{
			GMS_FIX_MGR_WORK gMS_FIX_MGR_WORK = (GMS_FIX_MGR_WORK)gm_fix_tcb.work;
			if (gMS_FIX_MGR_WORK != null)
			{
				int num = (enable ? 2 : 0) | (enable_ss ? 512 : 0) | (enable_pause ? 1024 : 0) | (enable_action ? 2048 : 0) | (enable_move ? 4096 : 0);
				int num2 = ((!enable) ? 2 : 0) | ((!enable_ss) ? 512 : 0) | ((!enable_pause) ? 1024 : 0) | ((!enable_action) ? 2048 : 0) | ((!enable_move) ? 4096 : 0);
				gMS_FIX_MGR_WORK.flag &= (uint)(~num);
				gMS_FIX_MGR_WORK.flag |= (uint)num2;
			}
		}
	}

	private static bool GmFixIsDisp()
	{
		if (gm_fix_tcb != null)
		{
			GMS_FIX_MGR_WORK gMS_FIX_MGR_WORK = (GMS_FIX_MGR_WORK)gm_fix_tcb.work;
			if (gMS_FIX_MGR_WORK != null && (gMS_FIX_MGR_WORK.flag & 2) == 0)
			{
				return true;
			}
		}
		return false;
	}

	private static void GmFixRequestTimerFlash()
	{
		if (gm_fix_tcb != null)
		{
			GMS_FIX_MGR_WORK gMS_FIX_MGR_WORK = (GMS_FIX_MGR_WORK)gm_fix_tcb.work;
			if (gMS_FIX_MGR_WORK != null)
			{
				gMS_FIX_MGR_WORK.req_flag |= 1u;
			}
		}
	}

	private static void gmFixSubpartOutFunc(OBS_OBJECT_WORK obj_work)
	{
		if (gm_fix_tcb != null)
		{
			GMS_FIX_MGR_WORK gMS_FIX_MGR_WORK = (GMS_FIX_MGR_WORK)gm_fix_tcb.work;
			if ((gMS_FIX_MGR_WORK.flag & 2) == 0)
			{
				// El HUD se dibuja en su propia capa, sin el zoom del escenario.
				// El HUD usa la proyección del editor (tamaño y posición). Si el dibujo falla, se restaura el estado.
				bool prevHud = amHudEnqueue;
				amHudEnqueue = true;
				try
				{
					ObjDrawActionSummary(obj_work);
				}
				catch (Exception)
				{
				}
				finally
				{
					amHudEnqueue = prevHud;
				}
			}
		}
	}

	private static void gmFixSetFrameStatic(OBS_OBJECT_WORK obj_work, float frame)
	{
		obj_work.obj_2d.frame = frame;
		obj_work.obj_2d.speed = 0f;
	}

	private static void gmFixUpdatePart(GMS_FIX_PART_WORK part_work)
	{
		if ((part_work.flag & 1) == 0)
		{
			return;
		}
		if (gmFixCheckClear(part_work))
		{
			gmFixUnregisterPart(part_work);
			return;
		}
		if (part_work.proc_update != null)
		{
			part_work.proc_update(part_work);
		}
		if (part_work.proc_disp != null && (part_work.flag & 2) == 0)
		{
			part_work.proc_disp(part_work);
		}
	}

	private static bool gmFixCheckClear(GMS_FIX_PART_WORK part_work)
	{
		if (gm_fix_tcb == null)
		{
			return true;
		}
		if (part_work.parent_mgr == null)
		{
			return true;
		}
		if ((part_work.parent_mgr.flag & 1) != 0)
		{
			return true;
		}
		return false;
	}

	private static bool gmFixIsSpecialStage()
	{
		switch (GsGetMainSysInfo().stage_id)
		{
		case 21:
		case 22:
		case 23:
		case 24:
		case 25:
		case 26:
		case 27:
			return true;
		default:
			return false;
		}
	}

	private static bool gmFixIsTimeAttack()
	{
		if (GsGetMainSysInfo().game_mode == 1)
		{
			return true;
		}
		return false;
	}

	private static bool gmFixIsStage22()
	{
		ushort stage_id = GsGetMainSysInfo().stage_id;
		if (stage_id == 5)
		{
			return true;
		}
		return false;
	}

	private static bool gmFixIsStageTruck()
	{
		ushort stage_id = GsGetMainSysInfo().stage_id;
		if (stage_id == 9)
		{
			return true;
		}
		return false;
	}

	private static int gmFixGetPlan()
	{
		int result = 0;
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		if (gmFixIsStageTruck())
		{
			if ((0x200 & gSS_MAIN_SYS_INFO.game_flag) != 0)
			{
				result = 1;
			}
		}
		else if (gmFixIsSpecialStage())
		{
			if ((0x200 & gSS_MAIN_SYS_INFO.game_flag) != 0)
			{
				result = 1;
			}
		}
		else if ((1 & gSS_MAIN_SYS_INFO.game_flag) != 0)
		{
			result = 2;
		}
		return result;
	}

	private static short gmFixGetRingNum()
	{
		if (g_gm_main_system.ply_work[0] != null)
		{
			return g_gm_main_system.ply_work[0].ring_num;
		}
		return 0;
	}

	private static uint gmFixGetScore()
	{
		if (g_gm_main_system.ply_work[0] != null)
		{
			return g_gm_main_system.ply_work[0].score;
		}
		return 0u;
	}

	private static uint gmFixGetGameTime()
	{
		if (g_gm_main_system.game_time >= 35999)
		{
			return 35999u;
		}
		return g_gm_main_system.game_time;
	}

	private static uint gmFixGetChallengeNum()
	{
		uint a = 0u;
		if (g_gm_main_system.player_rest_num[0] != 0)
		{
			a = g_gm_main_system.player_rest_num[0] - 1;
		}
		return (uint)MTM_MATH_CLIP((int)a, 0, 999);
	}

	private static void gmFixInitBlink(GMS_FIX_PART_WORK part_work, uint on_time, uint off_time)
	{
		part_work.blink_timer = on_time + off_time;
		part_work.blink_on_time = on_time;
		part_work.blink_off_time = off_time;
	}

	private static bool gmFixUpdateBlink(GMS_FIX_PART_WORK part_work)
	{
		bool flag = false;
		if (part_work.blink_timer != 0)
		{
			part_work.blink_timer--;
		}
		flag = ((part_work.blink_timer >= part_work.blink_off_time) ? true : false);
		if (part_work.blink_timer == 0)
		{
			part_work.blink_timer = part_work.blink_on_time + part_work.blink_off_time;
		}
		return flag;
	}

	private static void gmFixDest(MTS_TASK_TCB tcb)
	{
	}

	private static void gmFixProcMain(MTS_TASK_TCB tcb)
	{
		GMS_FIX_MGR_WORK gMS_FIX_MGR_WORK = (GMS_FIX_MGR_WORK)tcb.work;
		if (gMS_FIX_MGR_WORK.proc_update != null)
		{
			mppAssertNotImpl();
		}
		for (int i = 0; i < 5; i++)
		{
			if (gMS_FIX_MGR_WORK.part_work[i] != null)
			{
				gmFixUpdatePart(gMS_FIX_MGR_WORK.part_work[i]);
			}
		}
	}

	private static void gmFixRegisterPart(GMS_FIX_MGR_WORK mgr_work, GMS_FIX_PART_WORK part_work, int part_type)
	{
		mgr_work.part_work[part_type] = part_work;
		part_work.part_type = part_type;
		part_work.parent_mgr = mgr_work;
		part_work.flag |= 1u;
	}

	private static void gmFixUnregisterPart(GMS_FIX_PART_WORK part_work)
	{
		GMS_FIX_MGR_WORK parent_mgr = part_work.parent_mgr;
		if (parent_mgr != null)
		{
			parent_mgr.part_work[part_work.part_type] = null;
		}
		part_work.part_type = -1;
		part_work.parent_mgr = null;
		part_work.flag &= 4294967294u;
	}

	private static bool gmFixProcessRequest(GMS_FIX_MGR_WORK mgr_work, uint req_flag_bit)
	{
		if ((mgr_work.req_flag & req_flag_bit) != 0)
		{
			mgr_work.req_flag &= ~req_flag_bit;
			return true;
		}
		return false;
	}

	private static void gmFixRingCountPartInit(GMS_FIX_MGR_WORK mgr_work)
	{
		GMS_FIX_PART_WORK gMS_FIX_PART_WORK = (GMS_FIX_PART_WORK)mgr_work.part_ringcount;
		gmFixRegisterPart(mgr_work, gMS_FIX_PART_WORK, 0);
		gMS_FIX_PART_WORK.proc_update = gmFixRingCountPartProcUpdateMain;
		gMS_FIX_PART_WORK.proc_disp = gmFixRingCountPartProcDispMain;
		for (int i = 0; i < 4; i++)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_COCKPIT_CREATE_WORK(() => new GMS_COCKPIT_2D_WORK(), null, 0, "FIX_RING");
			GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK = (GMS_COCKPIT_2D_WORK)oBS_OBJECT_WORK;
			oBS_OBJECT_WORK.ppOut = gmFixSubpartOutFunc;
			ObjObjectAction2dAMALoadSetTexlist(oBS_OBJECT_WORK, gMS_COCKPIT_2D_WORK.obj_2d, null, null, gm_fix_ama_amb_idx_tbl[GsEnvGetLanguage()][0], GmGameDatGetCockpitData(), AoTexGetTexList(gm_fix_textures[0]), (uint)gm_fix_ringcount_act_id_tbl[i], 0);
			gmFixSetFrameStatic(oBS_OBJECT_WORK, 0f);
			if (i != 0)
			{
				oBS_OBJECT_WORK.pos.y += FX_F32_TO_FX32(5f);
			}
			((GMS_FIX_PART_RINGCOUNT)gMS_FIX_PART_WORK).sub_parts[i] = (GMS_COCKPIT_2D_WORK)oBS_OBJECT_WORK;
		}
	}

	private static void gmFixRingCountPartProcUpdateMain(GMS_FIX_PART_WORK part_work)
	{
		GMS_FIX_PART_RINGCOUNT part_ringcount = (GMS_FIX_PART_RINGCOUNT)part_work;
		gmFixRingCountPartUpdateDigitList(part_ringcount);
		if (gmFixGetRingNum() == 0)
		{
			if ((part_work.flag & 4) == 0)
			{
				part_work.flag |= 4u;
				gmFixInitBlink(part_work, 10u, 10u);
			}
		}
		else
		{
			part_work.flag &= 4294967291u;
		}
	}

	private static void gmFixRingCountPartProcDispMain(GMS_FIX_PART_WORK part_work)
	{
		GMS_FIX_PART_RINGCOUNT part_ringcount = (GMS_FIX_PART_RINGCOUNT)part_work;
		if ((part_work.flag & 4) != 0)
		{
			if (gmFixUpdateBlink(part_work))
			{
				part_work.flag &= 4294967287u;
			}
			else
			{
				part_work.flag |= 8u;
			}
		}
		else
		{
			part_work.flag &= 4294967287u;
		}
		if ((part_work.flag & 8) != 0)
		{
			gmFixRingCountPartSetDispDigits(part_ringcount, false);
		}
		else
		{
			gmFixRingCountPartSetDispDigits(part_ringcount, true);
		}
		gmFixRingCountPartUpdateActionDigitsType(part_ringcount);
	}

	private static void gmFixRingCountPartUpdateDigitList(GMS_FIX_PART_RINGCOUNT part_ringcount)
	{
		int num = gmFixGetRingNum();
		AkUtilNumValueToDigits(num, part_ringcount.digit_list, 3);
		if (num == 0)
		{
			for (int i = 0; i < 3; i++)
			{
				part_ringcount.digit_list[i] = 10;
			}
		}
	}

	private static void gmFixRingCountPartUpdateActionDigitsType(GMS_FIX_PART_RINGCOUNT part_ringcount)
	{
		for (int i = 0; i < 3; i++)
		{
			GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK = part_ringcount.sub_parts[gm_fix_part_ring_count_digit_subpart_idx_tbl[i]];
			gmFixSetFrameStatic((OBS_OBJECT_WORK)gMS_COCKPIT_2D_WORK, gm_fix_part_ring_count_digit_type_frame_tbl[part_ringcount.digit_list[i]]);
		}
	}

	private static void gmFixRingCountPartSetDispDigits(GMS_FIX_PART_RINGCOUNT part_ringcount, bool enable)
	{
		for (int i = 0; i < 4; i++)
		{
			if (i != 0)
			{
				if (enable)
				{
					((OBS_OBJECT_WORK)part_ringcount.sub_parts[i]).disp_flag &= 4294967263u;
				}
				else
				{
					((OBS_OBJECT_WORK)part_ringcount.sub_parts[i]).disp_flag |= 32u;
				}
			}
		}
	}

