			oBS_OBJECT_WORK.ppOut = gmFixSubpartOutFunc;
			ObjObjectAction2dAMALoadSetTexlist(oBS_OBJECT_WORK, gMS_COCKPIT_2D_WORK.obj_2d, null, null, gm_fix_ama_amb_idx_tbl[GsEnvGetLanguage()][0], GmGameDatGetCockpitData(), AoTexGetTexList(gm_fix_textures[0]), (uint)act_id_tblgmFixScorePartInit[i], 0);
			gmFixSetFrameStatic(oBS_OBJECT_WORK, 0f);
