			if (i != 0)
			{
				oBS_OBJECT_WORK.pos.y += FX_F32_TO_FX32(2f);
			}
			((GMS_FIX_PART_SCORE)gMS_FIX_PART_WORK).sub_parts[i] = (GMS_COCKPIT_2D_WORK)oBS_OBJECT_WORK;
		}
	}

