	private static void gmFixTimerPartProcUpdateMain(GMS_FIX_PART_WORK part_work)
	{
		GMS_FIX_PART_TIMER gMS_FIX_PART_TIMER = (GMS_FIX_PART_TIMER)part_work;
		gmFixTimerPartUpdateDigitList(gMS_FIX_PART_TIMER);
		if (gmFixProcessRequest(part_work.parent_mgr, 1u))
		{
			gmFixTimerPartInitFlashAction(gMS_FIX_PART_TIMER);
		}
		else
		{
			gmFixTimerPartUpdateFlashAction(gMS_FIX_PART_TIMER);
		}
		if (gmFixTimerPartIsTimeRunningOut(part_work.parent_mgr))
		{
			ushort? sec = 0;
			ushort? min = null;
			AkUtilFrame60ToTime(gmFixGetGameTime(), ref min, ref sec, ref min);
			if ((part_work.flag & 4) == 0)
			{
				part_work.flag |= 4u;
				gmFixInitBlink(part_work, 10u, 10u);
				gMS_FIX_PART_TIMER.cur_sec = (ushort)(sec - 1).Value;
			}
			if (gMS_FIX_PART_TIMER.cur_sec != sec)
			{
				gMS_FIX_PART_TIMER.cur_sec = sec.Value;
				GmSoundPlaySE("Countdown");
			}
		}
		else
		{
			part_work.flag &= 4294967291u;
		}
	}

	private static void gmFixTimerPartProcDispMain(GMS_FIX_PART_WORK part_work)
	{
		GMS_FIX_PART_TIMER part_timer = (GMS_FIX_PART_TIMER)part_work;
		if ((part_work.flag & 4) != 0)
		{
			gmFixTimerPartSetDigitsRed(part_timer, true);
			if (gmFixUpdateBlink(part_work))
			{
				part_work.flag &= 4294967287u;
			}
			else
			{
				part_work.flag |= 8u;
			}
		}
		else
		{
			gmFixTimerPartSetDigitsRed(part_timer, false);
			part_work.flag &= 4294967287u;
		}
		if ((part_work.flag & 8) != 0)
		{
			gmFixTimerPartSetDispDigits(part_timer, false);
		}
		else
		{
			gmFixTimerPartSetDispDigits(part_timer, true);
		}
		gmFixTimerPartUpdateActionDigitsType(part_timer);
	}

	private static void gmFixTimerPartUpdateDigitList(GMS_FIX_PART_TIMER part_timer)
	{
		ushort msec = 0;
		ushort sec = 0;
		ushort min = 0;
		AkUtilFrame60ToTime(gmFixGetGameTime(), ref min, ref sec, ref msec);
		int num = 0;
		AkUtilNumValueToDigits(msec, new ArrayPointer<int>(part_timer.digit_list, num), digit_num_listgmFixTimerPartUpdateDigitList[0]);
		num += digit_num_listgmFixTimerPartUpdateDigitList[0];
		AkUtilNumValueToDigits(sec, new ArrayPointer<int>(part_timer.digit_list, num), digit_num_listgmFixTimerPartUpdateDigitList[1]);
		num += digit_num_listgmFixTimerPartUpdateDigitList[1];
		AkUtilNumValueToDigits(min, new ArrayPointer<int>(part_timer.digit_list, num), digit_num_listgmFixTimerPartUpdateDigitList[2]);
		num += digit_num_listgmFixTimerPartUpdateDigitList[2];
	}

	private static void gmFixTimerPartUpdateActionDigitsType(GMS_FIX_PART_TIMER part_timer)
	{
		for (int i = 0; (long)i < 5L; i++)
		{
			GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK = part_timer.sub_parts[gm_fix_part_timer_digit_subpart_idx_tbl[i]];
			gmFixSetFrameStatic((OBS_OBJECT_WORK)gMS_COCKPIT_2D_WORK, gm_fix_part_common_digit_type_frame_tbl[part_timer.digit_list[i]] + part_timer.digit_frame_ofst);
		}
		for (int j = 0; (long)j < 2L; j++)
		{
			GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK2 = part_timer.sub_parts[gm_fix_part_timer_deco_char_subpart_idx_tbl[j]];
			gmFixSetFrameStatic((OBS_OBJECT_WORK)gMS_COCKPIT_2D_WORK2, 0f + part_timer.deco_char_frame_ofst);
		}
	}

	private static void gmFixTimerPartSetDispDigits(GMS_FIX_PART_TIMER part_timer, bool enable)
	{
		for (int i = 0; i < 8; i++)
		{
			if (i != 0)
			{
				if (enable)
				{
					((OBS_OBJECT_WORK)part_timer.sub_parts[i]).disp_flag &= 4294967263u;
				}
				else
				{
					((OBS_OBJECT_WORK)part_timer.sub_parts[i]).disp_flag |= 32u;
				}
			}
		}
	}

