	private static bool gmFixTimerPartIsTimeRunningOut(GMS_FIX_MGR_WORK mgr_work)
	{
		ushort min = 0;
		ushort sec = 0;
		AkUtilFrame60ToTime(gmFixGetGameTime(), ref min, ref sec);
		if ((mgr_work.flag & 4) != 0)
		{
			if (min <= 0 && (uint)sec < 20u)
			{
				return true;
			}
			return false;
		}
		if (min >= 9 && (uint)(sec + 20) >= 60u)
		{
			return true;
		}
		return false;
	}

	private static void gmFixTimerPartInitFlashAction(GMS_FIX_PART_TIMER part_timer)
	{
		part_timer.flag |= 2u;
		part_timer.fade_ratio = 0f;
		part_timer.scale_ratio = 0f;
		part_timer.flash_act_phase = 0u;
	}

	private static void gmFixTimerPartUpdateFlashAction(GMS_FIX_PART_TIMER part_timer)
	{
		bool flag = false;
		if ((part_timer.flag & 2) == 0)
		{
			return;
		}
		switch (part_timer.flash_act_phase)
		{
		case 0u:
			part_timer.fade_ratio += 0.5f;
			part_timer.scale_ratio += 0.25f;
			part_timer.fade_ratio = MTM_MATH_CLIP(part_timer.fade_ratio, 0f, 1f);
			part_timer.scale_ratio = MTM_MATH_CLIP(part_timer.fade_ratio, 0f, 1f);
			if (part_timer.scale_ratio >= 1f)
			{
				part_timer.flash_act_phase++;
			}
			break;
		case 1u:
			part_timer.fade_ratio -= 0.02f;
			part_timer.scale_ratio -= 0.05f;
			part_timer.fade_ratio = MTM_MATH_CLIP(part_timer.fade_ratio, 0f, 1f);
			part_timer.scale_ratio = MTM_MATH_CLIP(part_timer.scale_ratio, 0f, 1f);
			if (part_timer.fade_ratio <= 0f)
			{
				part_timer.flash_act_phase++;
			}
			break;
		default:
			flag = true;
			break;
		}
		uint[] array = new uint[7] { 1u, 2u, 3u, 4u, 5u, 6u, 7u };
		uint num = (uint)array.Length;
		if (!flag)
		{
			int y = 4096 + (int)(part_timer.scale_ratio * 2048f);
			byte a = (byte)MTM_MATH_CLIP(255f * part_timer.fade_ratio, 0f, 255f);
			for (uint num2 = 0u; num2 < num; num2++)
			{
				OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)part_timer.sub_parts[array[num2]];
				oBS_OBJECT_WORK.scale.x = (oBS_OBJECT_WORK.scale.y = y);
				oBS_OBJECT_WORK.obj_2d.fade.b = (oBS_OBJECT_WORK.obj_2d.fade.g = (oBS_OBJECT_WORK.obj_2d.fade.r = byte.MaxValue));
				oBS_OBJECT_WORK.obj_2d.fade.a = a;
			}
			return;
		}
		part_timer.fade_ratio = 0f;
		part_timer.scale_ratio = 0f;
		part_timer.flash_act_phase = 0u;
		for (uint num3 = 0u; num3 < num; num3++)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK2 = (OBS_OBJECT_WORK)part_timer.sub_parts[array[num3]];
			oBS_OBJECT_WORK2.scale.x = (oBS_OBJECT_WORK2.scale.y = 4096);
			oBS_OBJECT_WORK2.obj_2d.fade.a = (oBS_OBJECT_WORK2.obj_2d.fade.b = (oBS_OBJECT_WORK2.obj_2d.fade.g = (oBS_OBJECT_WORK2.obj_2d.fade.r = 0)));
		}
		part_timer.flag &= 4294967293u;
	}

