	private static void gmFixVirtualPadPartInit(GMS_FIX_MGR_WORK mgr_work)
	{
		MPP_VOID_OBS_OBJECT_WORK[] array = new MPP_VOID_OBS_OBJECT_WORK[4]
		{
			gmFixVirtualPadOutClassGMD_FIX_MGR_FLAG_HIDE_VIRTUAL_PAD_PART_SUPER_SONIC.OutFunc,
			gmFixVirtualPadOutClassGMD_FIX_MGR_FLAG_HIDE_VIRTUAL_PAD_PART_PAUSE.OutFunc,
			gmFixVirtualPadOutClassGMD_FIX_MGR_FLAG_HIDE_VIRTUAL_PAD_PART_ACTION.OutFunc,
			gmFixVirtualPadOutClassGMD_FIX_MGR_FLAG_HIDE_VIRTUAL_PAD_PART_MOVE_PAD.OutFunc
		};
		GMS_FIX_PART_WORK gMS_FIX_PART_WORK = (GMS_FIX_PART_WORK)mgr_work.part_virtual_pad;
		gmFixRegisterPart(mgr_work, gMS_FIX_PART_WORK, 4);
		gMS_FIX_PART_WORK.proc_update = gmFixVirtualPadPartProcUpdateMain;
		gMS_FIX_PART_WORK.proc_disp = gmFixVirtualPadPartProcDispMain;
		int i = 0;
		for (int num = 4; i < num; i++)
		{
			if (gm_fix_virtual_pad_act_id_tbl[gmFixGetPlan()][i] < 0)
			{
				((GMS_FIX_PART_VIRTUAL_PAD)gMS_FIX_PART_WORK).sub_parts[i] = null;
				continue;
			}
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_COCKPIT_CREATE_WORK(() => new GMS_COCKPIT_2D_WORK(), null, 0, "FIX_VIRTUAL_PAD");
			GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK = (GMS_COCKPIT_2D_WORK)oBS_OBJECT_WORK;
			oBS_OBJECT_WORK.ppOut = array[i];
			ObjObjectAction2dAMALoadSetTexlist(oBS_OBJECT_WORK, gMS_COCKPIT_2D_WORK.obj_2d, null, null, gm_fix_ama_amb_idx_tbl[GsEnvGetLanguage()][0], GmGameDatGetCockpitData(), AoTexGetTexList(gm_fix_textures[0]), (uint)gm_fix_virtual_pad_act_id_tbl[gmFixGetPlan()][i], 0);
			amFlagOff(ref oBS_OBJECT_WORK.disp_flag, 32u);
			gmFixSetFrameStatic(oBS_OBJECT_WORK, 0f);
			if (1 == i)
			{
				if (gmFixIsSpecialStage())
				{
					oBS_OBJECT_WORK.pos.x += FX_F32_TO_FX32(400f);
				}
				else if (gmFixIsTimeAttack())
				{
					oBS_OBJECT_WORK.pos.x += FX_F32_TO_FX32(200f);
				}
			}
			((GMS_FIX_PART_VIRTUAL_PAD)gMS_FIX_PART_WORK).sub_parts[i] = (GMS_COCKPIT_2D_WORK)oBS_OBJECT_WORK;
		}
		switch (GsEnvGetLanguage())
		{
		case 3:
		case 5:
			((GMS_FIX_PART_VIRTUAL_PAD)gMS_FIX_PART_WORK).pause_icon_frame[0] = 2f;
			((GMS_FIX_PART_VIRTUAL_PAD)gMS_FIX_PART_WORK).pause_icon_frame[1] = 3f;
			break;
		default:
			((GMS_FIX_PART_VIRTUAL_PAD)gMS_FIX_PART_WORK).pause_icon_frame[0] = 0f;
			((GMS_FIX_PART_VIRTUAL_PAD)gMS_FIX_PART_WORK).pause_icon_frame[1] = 1f;
			break;
		}
		amFlagOff(ref gMS_FIX_PART_WORK.flag, 2u);
	}

	private static void gmFixVirtualPadPartProcUpdateMain(GMS_FIX_PART_WORK part_work)
	{
		GMS_FIX_PART_VIRTUAL_PAD gMS_FIX_PART_VIRTUAL_PAD = (GMS_FIX_PART_VIRTUAL_PAD)part_work;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gMS_FIX_PART_VIRTUAL_PAD.sub_parts[0];
		if (gmFixVirtualPadPartIsDispSuperSonicIcon(gMS_FIX_PART_VIRTUAL_PAD))
		{
			amFlagOff(ref oBS_OBJECT_WORK.disp_flag, 32u);
		}
		else
		{
			amFlagOn(ref oBS_OBJECT_WORK.disp_flag, 32u);
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = (OBS_OBJECT_WORK)gMS_FIX_PART_VIRTUAL_PAD.sub_parts[1];
		if (gmFixVirtualPadPartIsDispPauseIcon(gMS_FIX_PART_VIRTUAL_PAD))
		{
			amFlagOff(ref oBS_OBJECT_WORK2.disp_flag, 32u);
			if (gmFixVirtualPadPartIsOnPauseIcon(gMS_FIX_PART_VIRTUAL_PAD))
			{
				gmFixSetFrameStatic(oBS_OBJECT_WORK2, gMS_FIX_PART_VIRTUAL_PAD.pause_icon_frame[1]);
			}
			else
			{
				gmFixSetFrameStatic(oBS_OBJECT_WORK2, gMS_FIX_PART_VIRTUAL_PAD.pause_icon_frame[0]);
			}
		}
		else
		{
			amFlagOn(ref oBS_OBJECT_WORK2.disp_flag, 32u);
		}
		switch (gmFixGetPlan())
		{
		default:
			return;
		case 2:
		{
			OBS_OBJECT_WORK obj_work = (OBS_OBJECT_WORK)gMS_FIX_PART_VIRTUAL_PAD.sub_parts[3];
			float frame = gmFixVirtualPadPartGetMovePadFrame(gMS_FIX_PART_VIRTUAL_PAD);
			gmFixSetFrameStatic(obj_work, frame);
			break;
		}
		case 1:
			break;
		case 0:
			return;
		}
		OBS_OBJECT_WORK obj_work2 = (OBS_OBJECT_WORK)gMS_FIX_PART_VIRTUAL_PAD.sub_parts[2];
		if (gmFixVirtualPadPartIsOnActionIcon(gMS_FIX_PART_VIRTUAL_PAD))
		{
			gmFixSetFrameStatic(obj_work2, 1f);
		}
		else
		{
			gmFixSetFrameStatic(obj_work2, 0f);
		}
	}

