	private static bool gmFixVirtualPadPartIsOnPauseIcon(GMS_FIX_PART_VIRTUAL_PAD pArg)
	{
		bool result = false;
		if ((GmPauseCheckExecutable() || (g_gm_main_system.game_flag & 0xC0) != 0) && 0 <= GmMainKeyCheckPauseKeyOn())
		{
			result = true;
		}
		return result;
