	private static float gmFixVirtualPadPartGetMovePadFrame(GMS_FIX_PART_VIRTUAL_PAD pArg)
	{
		CPadVirtualPad cPadVirtualPad = CPadVirtualPad.CreateInstance();
		ushort value = cPadVirtualPad.GetValue();
		float result = 0f;
		for (int i = 0; i < c_key_to_frame_table.Length; i++)
		{
			SKeyToFrame sKeyToFrame = c_key_to_frame_table[i];
			if ((sKeyToFrame.key & value) != 0)
			{
				result = sKeyToFrame.frame;
				break;
			}
		}
		return result;
	}

