	{
		MTM_ASSERT(obj_work);
		MTM_ASSERT(obj_work.obj_3d);
		NNS_MATRIX user_obj_mtx_r = obj_work.obj_3d.user_obj_mtx_r;
		obj_work.pos.x = FX_F32_TO_FX32(w_mtx.M03);
		obj_work.pos.y = -FX_F32_TO_FX32(w_mtx.M13);
