	private static void GmBoss4UtilInitTurn(GMS_BOSS4_DIRECTION _work, int turn_amount, int turn_spd)
	{
		MTM_ASSERT(0 == (int.MinValue & (turn_amount ^ turn_spd)));
		_work.orig_angle = _work.cur_angle;
		_work.turn_angle = 0;
		_work.turn_amount = turn_amount;
		_work.turn_spd = turn_spd;
		GmBoss4UtilSetDirection(_work, (short)(_work.orig_angle + _work.turn_angle));
	}

	private static void GmBoss4UtilInitTurn(GMS_BOSS4_DIRECTION _work, short dest_angle, int frame, bool is_positive)
	{
		MTM_ASSERT(frame > 0);
		int num2;
		if (is_positive)
		{
			ushort num = (ushort)(dest_angle - _work.cur_angle);
			num2 = num;
		}
		else
		{
			ushort num = (ushort)(dest_angle - AKM_DEGtoA32(360) - (_work.cur_angle - AKM_DEGtoA32(360)));
			num2 = num - AKM_DEGtoA32(360);
		}
		int turn_spd = num2 / frame;
		GmBoss4UtilInitTurn(_work, num2, turn_spd);
	}

	private static bool GmBoss4UtilUpdateTurn(GMS_BOSS4_DIRECTION _work, float spd_rate)
	{
		bool flag = false;
		MTM_ASSERT(spd_rate >= 0f);
		float num = spd_rate * (float)_work.turn_spd;
		MTM_ASSERT(MTM_MATH_ABS(num) <= 2.1474836E+09f);
		_work.turn_angle += (int)num;
		if (_work.turn_spd > 0)
		{
			if (_work.turn_angle >= _work.turn_amount)
			{
				flag = true;
			}
		}
		else if (_work.turn_spd < 0 && _work.turn_angle <= _work.turn_amount)
		{
			flag = true;
		}
		if (flag)
		{
			_work.turn_angle = _work.turn_amount;
		}
		GmBoss4UtilSetDirection(_work, (short)(_work.orig_angle + _work.turn_angle));
		return flag;
	}

	private static void GmBoss4UtilInitTurnGently(GMS_BOSS4_DIRECTION _work, short dest_angle, int frame, bool is_positive)
	{
		MTM_ASSERT(frame > 0);
		_work.orig_angle = _work.cur_angle;
		_work.turn_angle = 0;
		_work.turn_spd = 0;
		if (is_positive)
		{
			ushort turn_amount = (ushort)(dest_angle - _work.cur_angle);
			_work.turn_amount = turn_amount;
		}
		else
		{
			ushort turn_amount = (ushort)(dest_angle - AKM_DEGtoA32(360) - (_work.cur_angle - AKM_DEGtoA32(360)));
			_work.turn_amount = turn_amount - AKM_DEGtoA32(360);
		}
		_work.turn_gen_var = 0;
		float num = 180f / (float)frame;
		MTM_ASSERT(MTM_MATH_ABS(num) <= 2.1474836E+09f);
		_work.turn_gen_factor = AKM_DEGtoA32(num);
		GmBoss4UtilSetDirection(_work, (short)(_work.orig_angle + _work.turn_angle));
	}

	private static bool GmBoss4UtilUpdateTurnGently(GMS_BOSS4_DIRECTION _work)
	{
		bool flag = false;
		MTM_ASSERT(_work.turn_gen_factor > 0);
		_work.turn_gen_var += _work.turn_gen_factor;
		if (_work.turn_gen_var >= AKM_DEGtoA32(180))
		{
			_work.turn_gen_var = AKM_DEGtoA32(180);
			flag = true;
		}
		float num = (float)_work.turn_amount * 0.5f * (1f - nnCos(_work.turn_gen_var));
		MTM_ASSERT(MTM_MATH_ABS(num) <= 2.1474836E+09f);
		_work.turn_angle = (int)num;
		if (flag)
		{
			_work.turn_angle = _work.turn_amount;
		}
		GmBoss4UtilSetDirection(_work, (short)(_work.orig_angle + _work.turn_angle));
		return flag;
	}

	private static bool GmBoss4UtilLookAtPlayer(GMS_BOSS4_DIRECTION _work, OBS_OBJECT_WORK obj_work, int time)
	{
