		}
		else if (_work.direction != 0)
		{
			_work.direction = 0;
			GmBoss4UtilInitTurnGently(_work, GMD_BOSS4_RIGHTWARD_ANGLE, time, true);
		}
		return GmBoss4UtilUpdateTurnGently(_work);
