	private static void GmBoss4UtilInitFlicker(OBS_OBJECT_WORK obj_work, GMS_BOSS4_FLICKER_WORK flk_work)
	{
		GmBoss4UtilInitFlicker(obj_work, flk_work, 3, 0, 4, 0, gm_boss4_color_white);
	}

	private static void GmBoss4UtilInitFlicker(OBS_OBJECT_WORK obj_work, GMS_BOSS4_FLICKER_WORK flk_work, int times, int start, int spd, int interval, NNS_RGB rgb)
	{
		int add_timer = AKM_DEGtoA32(360f / (float)(spd + 1));
		MTM_ASSERT(obj_work);
		MTM_ASSERT(obj_work.obj_3d);
		MTM_ASSERT(flk_work);
		flk_work.is_active = true;
		flk_work.cycles = (uint)times;
		flk_work.interval_timer = (uint)start;
		flk_work.cur_angle = 0;
		flk_work.add_timer = add_timer;
		flk_work.interval_flk = (uint)interval;
		flk_work.color.r = rgb.r;
		flk_work.color.g = rgb.g;
		flk_work.color.b = rgb.b;
		GmBsCmnClearObject3DNNFadedColor(obj_work);
	}

	private static bool GmBoss4UtilUpdateFlicker(OBS_OBJECT_WORK obj_work, GMS_BOSS4_FLICKER_WORK flk_work)
	{
		MTM_ASSERT(obj_work);
		MTM_ASSERT(obj_work.obj_3d);
		MTM_ASSERT(flk_work);
		if (!flk_work.is_active)
		{
			return true;
		}
		if (flk_work.cycles != 0)
		{
			if (flk_work.interval_timer != 0)
			{
				flk_work.interval_timer--;
			}
			else
			{
				flk_work.cur_angle += flk_work.add_timer;
				if (flk_work.cur_angle >= AKM_DEGtoA32(360f))
				{
					flk_work.cur_angle = 0;
					flk_work.cycles--;
					flk_work.interval_timer = flk_work.interval_flk;
				}
			}
			GmBsCmnSetObject3DNNFadedColor(obj_work, flk_work.color, (1f - nnCos(flk_work.cur_angle)) / 2f);
			return false;
		}
		if (flk_work.is_active)
		{
			GmBoss4UtilEndFlicker(obj_work, flk_work);
		}
		return true;
	}

	private static void GmBoss4UtilEndFlicker(OBS_OBJECT_WORK obj_work, GMS_BOSS4_FLICKER_WORK flk_work)
	{
		MTM_ASSERT(obj_work);
		MTM_ASSERT(obj_work.obj_3d);
		MTM_ASSERT(flk_work);
		flk_work.Clear();
		GmBsCmnClearObject3DNNFadedColor(obj_work);
	}

	private static void GmBoss4UtilRotateVecFx32(ref VecFx32 f, int angle)
	{
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		nNS_MATRIX.M00 = 1f;
		nNS_MATRIX.M10 = 0f;
		nNS_MATRIX.M20 = 0f;
		nNS_MATRIX.M30 = 0f;
		nNS_MATRIX.M01 = 0f;
		nNS_MATRIX.M11 = 1f;
		nNS_MATRIX.M21 = 0f;
		nNS_MATRIX.M31 = 0f;
		nNS_MATRIX.M02 = 0f;
		nNS_MATRIX.M12 = 0f;
		nNS_MATRIX.M22 = 1f;
		nNS_MATRIX.M32 = 0f;
		nNS_MATRIX.M03 = 0f;
		nNS_MATRIX.M13 = 0f;
		nNS_MATRIX.M23 = 0f;
		nNS_MATRIX.M33 = 1f;
		nnMakeRotateZMatrix(nNS_MATRIX, angle);
		nnTranslateMatrix(nNS_MATRIX, nNS_MATRIX, FX_FX32_TO_F32(f.x), FX_FX32_TO_F32(f.y), FX_FX32_TO_F32(f.z));
		f.x = FX_F32_TO_FX32(nNS_MATRIX.M03);
		f.y = FX_F32_TO_FX32(nNS_MATRIX.M13);
		f.z = FX_F32_TO_FX32(nNS_MATRIX.M23);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
	}

