	private static void GmBoss4UtilSetPlayerAttackReaction(OBS_OBJECT_WORK player, OBS_OBJECT_WORK enemy)
	{
		UNREFERENCED_PARAMETER(enemy);
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)player;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GmBoss4GetBodyWork();
		if ((gMS_PLAYER_WORK.obj_work.move_flag & 0x10) != 0)
		{
			GmPlySeqAtkReactionInit(gMS_PLAYER_WORK);
			GmPlySeqSetJumpState(gMS_PLAYER_WORK, 0, 5u);
			gMS_PLAYER_WORK.obj_work.spd_m = 0;
			if (oBS_OBJECT_WORK != null)
			{
				if (gMS_PLAYER_WORK.obj_work.pos.x < oBS_OBJECT_WORK.pos.x)
				{
					gMS_PLAYER_WORK.obj_work.spd.x = -FX_F32_TO_FX32(5f);
					if (GmBoss4GetScrollOffset() != 0)
					{
						gMS_PLAYER_WORK.obj_work.spd.x = FX_F32_TO_FX32(3f);
					}
				}
				else
				{
					gMS_PLAYER_WORK.obj_work.spd.x = FX_F32_TO_FX32(5f);
				}
			}
			else
			{
				if (gMS_PLAYER_WORK.obj_work.move.x >= 0)
				{
					gMS_PLAYER_WORK.obj_work.spd.x = -FX_F32_TO_FX32(5f);
					if (GmBoss4GetScrollOffset() != 0)
					{
						gMS_PLAYER_WORK.obj_work.spd.x = FX_F32_TO_FX32(3f);
					}
				}
				else
				{
					gMS_PLAYER_WORK.obj_work.spd.x = FX_F32_TO_FX32(5f);
				}
				int seq_state = gMS_PLAYER_WORK.seq_state;
				int num2 = 20;
			}
			gMS_PLAYER_WORK.obj_work.spd.y = -FX_F32_TO_FX32(4f);
			GmPlySeqSetNoJumpMoveTime(gMS_PLAYER_WORK, 102400);
			return;
		}
		gMS_PLAYER_WORK.obj_work.disp_flag ^= 1u;
		GmPlySeqChangeSequence(gMS_PLAYER_WORK, 10);
		if (gMS_PLAYER_WORK.obj_work.spd_m != 0)
		{
			gMS_PLAYER_WORK.obj_work.spd_m = -gMS_PLAYER_WORK.obj_work.spd_m;
			return;
		}
		int num = 0;
		if (oBS_OBJECT_WORK != null)
		{
			num = oBS_OBJECT_WORK.pos.x;
		}
		if (num > gMS_PLAYER_WORK.obj_work.pos.x)
		{
			gMS_PLAYER_WORK.obj_work.spd_m = -49152;
			gMS_PLAYER_WORK.obj_work.disp_flag |= 1u;
		}
		else
		{
			gMS_PLAYER_WORK.obj_work.spd_m = 49152;
			gMS_PLAYER_WORK.obj_work.disp_flag &= 4294967294u;
		}
	}

