	private static OBS_OBJECT_WORK GmBoss4CapsuleInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, int type)
	{
		_cap_kill_flag = 0;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_BOSS4_CAP_WORK(), "BOSS4_CAP");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_BOSS4_CAP_WORK gMS_BOSS4_CAP_WORK = (GMS_BOSS4_CAP_WORK)oBS_OBJECT_WORK;
		gMS_BOSS4_CAP_WORK.cap_no = _cap_no++ % 6;
		gMS_BOSS4_CAP_WORK.type = type;
		oBS_OBJECT_WORK.move_flag |= 256u;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, GmBoss4GetObj3D(2), gMS_ENEMY_3D_WORK.obj_3d);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.disp_flag |= 134217728u;
		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		ObjRectWorkSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[0], -14, -30, 14, -2);
		gMS_ENEMY_3D_WORK.ene_com.rect_work[0].ppDef = gmBoss4CapsuleDamageDefFunc;
		ObjRectWorkSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[1], -1, -9, 1, -7);
		gMS_ENEMY_3D_WORK.ene_com.rect_work[1].ppHit = gmBoss4CapsuleAtkHitFunc;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[1].flag |= 4u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 32768u;
		T_FUNC(gmBoss4CapsuleWaitLoad, oBS_OBJECT_WORK);
		if (gMS_BOSS4_CAP_WORK.chibi_type == 4)
		{
			oBS_OBJECT_WORK.disp_flag |= 32u;
		}
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmBoss4CapsuleExit);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

	private static void GmBoss4CapsuleUpdateRol(float spd)
	{
		_cap_rot_y += AKM_DEGtoA32(spd);
		_cap_rot_y %= AKM_DEGtoA32(360);
		if (_cap_rot_z_flag != 0)
		{
			_cap_rot_z += AKM_DEGtoA32(1f);
			if (_cap_rot_z >= AKM_DEGtoA32(45f))
			{
				_cap_rot_z_flag = 0;
			}
		}
		else
		{
			_cap_rot_z -= AKM_DEGtoA32(1f);
			if (_cap_rot_z <= AKM_DEGtoA32(-45f))
			{
				_cap_rot_z_flag = 1;
			}
		}
		if (_cap_rot_x_flag != 0)
		{
			_cap_rot_x += AKM_DEGtoA32(0.5f);
			if (_cap_rot_x >= AKM_DEGtoA32(60f))
			{
				_cap_rot_x_flag = 0;
			}
		}
		else
		{
			_cap_rot_x -= AKM_DEGtoA32(0.5f);
			if (_cap_rot_x <= AKM_DEGtoA32(-60f))
			{
				_cap_rot_x_flag = 1;
			}
		}
		if (_cap_len_time > 0f)
		{
			_cap_len_time -= 1f;
		}
		else if (0f != _cap_len_flag)
		{
			_cap_len += 2f;
			if (_cap_len >= 100f)
			{
				_cap_len_flag = 0f;
			}
		}
		else
		{
			_cap_len -= 2f;
			if (_cap_len <= 65f)
			{
				_cap_len_flag = 1f;
				_cap_len_time = (float)GMD_BOSS4_CAP_ZOOM_TIME + (float)GMD_BOSS4_CAP_ZOOM_TIME_RAND * ((float)(random.Next() % 256) / 256f);
			}
		}
		if (_cap_inv_flag > 900)
		{
			_cap_inv_flag = 0;
		}
		if (_cap_inv_flag > 0)
		{
			_cap_inv_flag--;
		}
		else
		{
			_cap_inv_flag = 0;
		}
	}

	private static void gmBoss4CapsuleWaitLoad(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_CAP_WORK gMS_BOSS4_CAP_WORK = (GMS_BOSS4_CAP_WORK)obj_work;
		if (!GmBoss4IsBuilded())
		{
			return;
		}
		if (gMS_BOSS4_CAP_WORK.type == 0)
		{
			T_FUNC(gmBoss4CapsuleMain, obj_work);
		}
		else
		{
			obj_work.move_flag &= 4294963199u;
			obj_work.move_flag |= 128u;
			ObjObjectFieldRectSet(obj_work, -20, -40, 20, 0);
			obj_work.dir.y = 0;
			gMS_BOSS4_CAP_WORK.chibi_type = gmBoss4ChibiGetAttackType(GmBoss4GetLife());
			T_FUNC(gmBoss4CapsuleMain2nd, obj_work);
			if (gMS_BOSS4_CAP_WORK.chibi_type == 4)
			{
				OBS_OBJECT_WORK oBS_OBJECT_WORK = GmEventMgrLocalEventBirth(329, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
				oBS_OBJECT_WORK.spd.x = FX_F32_TO_FX32(2f);
				oBS_OBJECT_WORK.spd.y = FX_F32_TO_FX32(-3f);
				GmBoss4IncObjCreateCount();
				oBS_OBJECT_WORK.parent_obj = obj_work.parent_obj;
				GMM_BS_OBJ(gMS_BOSS4_CAP_WORK).flag |= 8u;
			}
		}
		_cap_count++;
		gMS_BOSS4_CAP_WORK.wait = 0;
	}

	private static void gmBoss4CapsuleExit(MTS_TASK_TCB tcb)
	{
		GmBoss4DecObjCreateCount();
		GmEnemyDefaultExit(tcb);
	}

	private static void gmBoss4CapsuleMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)obj_work.parent_obj;
		GMS_BOSS4_CAP_WORK gMS_BOSS4_CAP_WORK = (GMS_BOSS4_CAP_WORK)obj_work;
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		NNS_MATRIX nNS_MATRIX2 = GlobalPool<NNS_MATRIX>.Alloc();
		NNS_MATRIX nNS_MATRIX3 = GlobalPool<NNS_MATRIX>.Alloc();
		if (gMS_BOSS4_CAP_WORK.wait > 0)
		{
			obj_work.pos.z = 131072;
			GmBoss4UtilUpdateFlicker(obj_work, gMS_BOSS4_CAP_WORK.flk_work);
			if (GmBoss4UtilUpdate1ShotTimer(gMS_BOSS4_CAP_WORK.timer))
			{
				VecFx32 pos = obj_work.pos;
				pos.z = 135168;
				GmBoss4EffCommonInit(735, pos);
				T_FUNC(gmBoss4CapsuleBomb, obj_work);
			}
		}
		else
		{
			GmBsCmnUpdateObject3DNNStuckWithNode(obj_work, gMS_BOSS4_BODY_WORK.node_work.snm_work, gMS_BOSS4_BODY_WORK.node_work.work[2], 0);
			obj_work.pos.y += FX_F32_TO_FX32(20f);
			int cap_rot_y = _cap_rot_y;
			cap_rot_y += AKM_DEGtoA32(360) / 6 * gMS_BOSS4_CAP_WORK.cap_no;
			cap_rot_y %= AKM_DEGtoA32(360);
			nnMakeRotateXMatrix(nNS_MATRIX, _cap_rot_x);
			nnRotateZMatrix(nNS_MATRIX, nNS_MATRIX, _cap_rot_z);
			nnRotateYMatrix(nNS_MATRIX, nNS_MATRIX, cap_rot_y);
			nnMakeTranslateMatrix(nNS_MATRIX2, _cap_len, 0f, 0f);
			nnMultiplyMatrix(nNS_MATRIX3, nNS_MATRIX, nNS_MATRIX2);
			NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
			nnCopyMatrixTranslationVector(nNS_VECTOR, nNS_MATRIX3);
			obj_work.pos.x += FX_F32_TO_FX32(nNS_VECTOR.x);
			obj_work.pos.y += FX_F32_TO_FX32(nNS_VECTOR.y);
			obj_work.pos.z += FX_F32_TO_FX32(nNS_VECTOR.z);
			GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		}
		if (_cap_kill_flag != 0)
		{
			VecFx32 pos2 = obj_work.pos;
			pos2.z = 135168;
			GmBoss4EffCommonInit(735, pos2);
			gMS_BOSS4_CAP_WORK.wait = 30;
			T_FUNC(gmBoss4CapsuleBomb, obj_work);
			GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX3);
			GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX2);
			GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
			return;
		}
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if (_cap_inv_flag != 0)
		{
			if (!_cap_inv_hit)
			{
				gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag |= 2048u;
				gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag &= 4294967291u;
			}
			gMS_ENEMY_3D_WORK.ene_com.rect_work[1].flag |= 2048u;
		}
		else
		{
			gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag &= 4294965247u;
			gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag |= 4u;
			gMS_ENEMY_3D_WORK.ene_com.rect_work[1].flag &= 4294965247u;
		}
		if (IS_FLAG(1073741824u, gMS_BOSS4_CAP_WORK))
		{
			_cap_count--;
			gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag &= 4294967291u;
			gMS_ENEMY_3D_WORK.ene_com.rect_work[1].flag &= 4294967291u;
			gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
			RESET_FLAG(1073741824u, gMS_BOSS4_CAP_WORK);
			GmBoss4UtilInitFlicker(obj_work, gMS_BOSS4_CAP_WORK.flk_work);
			GmBoss4UtilInit1ShotTimer(gMS_BOSS4_CAP_WORK.timer, 20u);
			gMS_BOSS4_CAP_WORK.wait = 60;
		}
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX3);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX2);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
	}

	private static void gmBoss4CapsuleMain2nd(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_CAP_WORK gMS_BOSS4_CAP_WORK = (GMS_BOSS4_CAP_WORK)obj_work;
		obj_work.move_flag &= 4294443007u;
		obj_work.spd_fall = FX_F32_TO_FX32(0.2f);
		obj_work.move_flag |= 128u;
		obj_work.pos.x += GmBoss4GetScrollOffset();
		if ((obj_work.move_flag & 1) != 0)
		{
			VecFx32 pos = obj_work.pos;
			pos.z = 135168;
			GmBoss4EffCommonInit(735, pos);
			gMS_BOSS4_CAP_WORK.wait = 30;
			obj_work.spd.x = FX_F32_TO_FX32(0f);
			obj_work.spd.y = FX_F32_TO_FX32(-1f);
			obj_work.move_flag &= 4294967294u;
			obj_work.move_flag |= 256u;
			ushort num = 326;
			switch (gMS_BOSS4_CAP_WORK.chibi_type)
			{
			default:
				num = 326;
				break;
			case 2:
				num = 327;
				break;
			case 3:
				num = 328;
				break;
			case 4:
				num = 329;
				break;
			}
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GmEventMgrLocalEventBirth(num, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
			oBS_OBJECT_WORK.parent_obj = obj_work.parent_obj;
			GmBoss4IncObjCreateCount();
			oBS_OBJECT_WORK.spd.y = FX_F32_TO_FX32(-4f);
			oBS_OBJECT_WORK.spd.x = FX_F32_TO_FX32(-1f);
			T_FUNC(gmBoss4CapsuleBomb2nd, obj_work);
		}
	}

	private static void gmBoss4CapsuleAtkHitFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)my_rect.parent_obj.parent_obj;
