	private static void gmBoss4CapsuleDamageDefFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		OBS_OBJECT_WORK parent_obj = my_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = your_rect.parent_obj;
		GMS_BOSS4_CAP_WORK w = (GMS_BOSS4_CAP_WORK)parent_obj;
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)parent_obj.parent_obj;
		if (parent_obj2 == null || 1 != parent_obj2.obj_type || _cap_inv_flag > 0)
		{
			return;
		}
		GmBoss4UtilSetPlayerAttackReaction(parent_obj2, parent_obj);
		GmSoundPlaySE("Enemy");
		GmBoss4CapsuleSetInvincible(30);
		GmBoss4UtilInitNoHitTimer(gMS_BOSS4_BODY_WORK.nohit_work, (GMS_ENEMY_COM_WORK)gMS_BOSS4_BODY_WORK, 25);
		if (!IS_FLAG(4u, w))
		{
			SET_FLAG(1073741824u, w);
			if ((gMS_BOSS4_BODY_WORK.flag[0] & 0x1000) == 0)
			{
				gMS_BOSS4_BODY_WORK.flag[0] |= 2048u;
				gMS_BOSS4_BODY_WORK.avoid_timer = 90;
			}
		}
	}

	private static void gmBoss4CapsuleBomb(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_CAP_WORK gMS_BOSS4_CAP_WORK = (GMS_BOSS4_CAP_WORK)obj_work;
		obj_work.disp_flag |= 32u;
		if (gMS_BOSS4_CAP_WORK.wait > 0)
		{
			gMS_BOSS4_CAP_WORK.wait--;
			if (gMS_BOSS4_CAP_WORK.wait == 30 && _cap_kill_flag == 0)
			{
				OBS_OBJECT_WORK oBS_OBJECT_WORK = GmEventMgrLocalEventBirth(325, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
				GmBoss4IncObjCreateCount();
				oBS_OBJECT_WORK.parent_obj = obj_work.parent_obj;
			}
		}
		else
		{
			GMM_BS_OBJ(gMS_BOSS4_CAP_WORK).flag |= 8u;
		}
	}

	private static void gmBoss4CapsuleBomb2nd(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_CAP_WORK gMS_BOSS4_CAP_WORK = (GMS_BOSS4_CAP_WORK)obj_work;
		obj_work.disp_flag &= 4294963199u;
		if ((g_obj.flag & 1) != 0)
		{
			obj_work.disp_flag |= 4096u;
		}
		else
		{
			obj_work.pos.x += GmBoss4GetScrollOffset();
		}
		if (gMS_BOSS4_CAP_WORK.wait > 0)
		{
			gMS_BOSS4_CAP_WORK.wait--;
			if (gMS_BOSS4_CAP_WORK.wait < 36)
			{
				obj_work.disp_flag |= 32u;
			}
		}
		else
		{
			GMM_BS_OBJ(gMS_BOSS4_CAP_WORK).flag |= 8u;
		}
	}

