	private static object amBindGet(AMS_AMB_HEADER header, int index)
	{
		string sPath;
		AmbChunk ambChunk = amBindGet(header, index, out sPath);
		if (header.files[index].IndexOf(".amb", StringComparison.OrdinalIgnoreCase) != -1)
		{
			AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile(ambChunk);
			aMS_AMB_HEADER.dir = sPath;
			return aMS_AMB_HEADER;
		}
		return ambChunk;
	}

	private static AmbChunk amBindGet(AMS_AMB_HEADER header, int index, out string sPath)
	{
		sPath = null;
		AmbChunk result = null;
		if (index < header.file_num)
		{
			result = new AmbChunk(header.data, header.offsets[index], header.lengths[index], header);
		}
		else
		{
			mppAssertNotImpl();
		}
		return result;
	}

	private static AmbChunk amBindGet(AMS_FS header, int index)
	{
		string sPath;
		return amBindGet(header, index, out sPath);
	}

	private static AmbChunk amBindGet(AMS_FS header, int index, out string sPath)
	{
		sPath = null;
		byte[] array = null;
		int offset = -1;
		int length = 0;
		if (index < header.count)
		{
			array = header.data;
			offset = header.offsets[index];
			length = header.lengths[index];
		}
		return new AmbChunk(array, offset, length, header.amb_header);
	}

	public static AmbChunk amBindSearch(AMS_AMB_HEADER header, string filename)
	{
		for (int i = 0; i < header.file_num; i++)
		{
			if (header.files[i] == filename)
			{
				return new AmbChunk(header.data, header.offsets[i], header.lengths[i], header);
			}
		}
		return null;
	}

	private static AmbChunk amBindSearchEx(AMS_AMB_HEADER header, string exname)
	{
		AmbChunk result = null;
		for (int i = 0; i < header.file_num; i++)
		{
			if (header.files[i].IndexOf(exname, 0, StringComparison.OrdinalIgnoreCase) != -1)
			{
				result = new AmbChunk(header.data, header.offsets[i], header.lengths[i], header);
				break;
			}
		}
		return result;
	}

