			if (wall_type == 2)
			{
				col_work.obj_col.ofst_y = (short)((-size >> 13) - (col_work.obj_col.height - (draw_size >> 12)));
			}
			else
			{
				col_work.obj_col.ofst_y = (short)((size >> 1) - draw_size >> 12);
			}
			gmGmkSwWallSetColDir(col_work.obj_col.dir_data, col_work.obj_col.width + 7 >> 3, col_work.obj_col.height + 7 >> 3, true);
		}
	}

	public static void gmGmkSwWallSetColDir(byte[] buf, int width, int height, bool wall)
	{
		if (g_gs_main_sys_info.stage_id != 9 || width <= 0 || height <= 0)
		{
			return;
		}
		int num = width >> 1;
		int num2 = height >> 1;
		ArrayPointer<byte> arrayPointer;
		int num3;
		if (wall)
		{
			arrayPointer = buf;
			num3 = 0;
			while (num3 < height)
			{
				ArrayPointer<byte> arrayPointer2 = arrayPointer;
				int num4 = 0;
				while (num4 < num)
				{
					arrayPointer2.SetPrimitive(192);
					num4++;
					++arrayPointer2;
				}
				while (num4 < width)
				{
					arrayPointer2.SetPrimitive(64);
