				}
				num3++;
				arrayPointer += width;
			}
			arrayPointer = new ArrayPointer<byte>(buf, 1);
			num3 = 1;
			while (num3 < width - 1)
			{
				arrayPointer.SetPrimitive(0);
				num3++;
				++arrayPointer;
			}
			if (height > 1)
			{
				arrayPointer = new ArrayPointer<byte>(buf, (height - 1) * width + 1);
				num3 = 1;
				while (num3 < width - 1)
				{
					arrayPointer.SetPrimitive(128);
					num3++;
					++arrayPointer;
				}
			}
			return;
		}
		arrayPointer = buf;
		for (num3 = 0; num3 < num2; num3++)
		{
			int num4 = 0;
			while (num4 < width)
			{
				arrayPointer.SetPrimitive(0);
				num4++;
				++arrayPointer;
			}
		}
		for (; num3 < height; num3++)
		{
			int num4 = 0;
			while (num4 < width)
			{
				arrayPointer.SetPrimitive(128);
				num4++;
				++arrayPointer;
			}
		}
		arrayPointer = new ArrayPointer<byte>(buf, width);
		num3 = 1;
		while (num3 < height - 1)
		{
			arrayPointer.SetPrimitive(192);
			num3++;
			arrayPointer += width;
		}
		if (width > 1)
		{
			arrayPointer = new ArrayPointer<byte>(buf, width + (width - 1));
			num3 = 1;
			while (num3 < height - 1)
			{
				arrayPointer.SetPrimitive(64);
				num3++;
				arrayPointer += width;
			}
		}
	}

	public static void gmGmkSwWallCheckColOff(GMS_GMK_SWWALL_WORK swwall_work)
	{
		if (g_gs_main_sys_info.stage_id != 9)
		{
			return;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)swwall_work;
		GMS_EVE_RECORD_EVENT eve_rec = swwall_work.gmk_work.ene_com.eve_rec;
		if (eve_rec.id == 248 || eve_rec.id == 249 || eve_rec.id == 252 || eve_rec.id == 253)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK2 = (OBS_OBJECT_WORK)g_gm_main_system.ply_work[0];
			int num = oBS_OBJECT_WORK2.pos.x >> 12;
			int num2 = oBS_OBJECT_WORK2.pos.y >> 12;
			int num3 = oBS_OBJECT_WORK.pos.x >> 12;
			int num4 = oBS_OBJECT_WORK.pos.y >> 12;
			int num5 = swwall_work.wall_size >> 12;
			if (num3 - (num5 >> 1) < num + oBS_OBJECT_WORK2.field_rect[2] && num3 + (num5 >> 1) > num + oBS_OBJECT_WORK2.field_rect[0] && num4 + oBS_OBJECT_WORK.col_work.obj_col.ofst_y + 8 <= num2 + oBS_OBJECT_WORK2.field_rect[3] && num4 + oBS_OBJECT_WORK.col_work.obj_col.ofst_y + oBS_OBJECT_WORK.col_work.obj_col.height > num2 + oBS_OBJECT_WORK2.field_rect[1])
			{
				oBS_OBJECT_WORK.col_work.obj_col.obj = null;
			}
			else
			{
				oBS_OBJECT_WORK.col_work.obj_col.obj = oBS_OBJECT_WORK;
			}
		}
	}

