	private static OBS_OBJECT_WORK GmGmkSwitchInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_SW_WORK(), "GMK_SWITCH");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_GMK_SW_WORK gMS_GMK_SW_WORK = (GMS_GMK_SW_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_switch_obj_3d_list[1], gMS_ENEMY_3D_WORK.obj_3d);
		if (GMM_MAIN_GET_ZONE_TYPE() == 2)
		{
			ObjAction3dNNMaterialMotionLoad(gMS_ENEMY_3D_WORK.obj_3d, 0, ObjDataGet(933), null, 0, null, 1, 1);
			ObjDrawAction3dActionSet3DNNMaterial(gMS_ENEMY_3D_WORK.obj_3d, 0);
			oBS_OBJECT_WORK.disp_flag |= 4u;
		}
		ObjCopyAction3dNNModel(gm_gmk_switch_obj_3d_list[0], gMS_GMK_SW_WORK.obj_3d_base);
		oBS_OBJECT_WORK.pos.z = -262144;
		oBS_OBJECT_WORK.ppOut = gmGmkSwDispFunc;
		OBS_COLLISION_WORK col_work = gMS_ENEMY_3D_WORK.ene_com.col_work;
		col_work.obj_col.obj = oBS_OBJECT_WORK;
		col_work.obj_col.width = 32;
		col_work.obj_col.height = 24;
		col_work.obj_col.ofst_x = -16;
		col_work.obj_col.ofst_y = -14;
		if (g_gs_main_sys_info.stage_id == 9)
		{
			col_work.obj_col.obj = null;
			OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
			oBS_RECT_WORK.ppDef = gmGmkSwitchDefFunc;
			oBS_RECT_WORK.ppHit = null;
			ObjRectAtkSet(oBS_RECT_WORK, 0, 0);
			ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
			ObjRectWorkSet(oBS_RECT_WORK, -16, -20, 16, -4);
			oBS_RECT_WORK.flag |= 132u;
		}
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 16384u;
		gMS_GMK_SW_WORK.id = (uint)MTM_MATH_CLIP(eve_rec.left, 0, 64);
		gMS_GMK_SW_WORK.time = eve_rec.width * 60 * 4096 + eve_rec.top * 4096;
		if (gMS_GMK_SW_WORK.time != 0 && gMS_GMK_SW_WORK.time < 12288)
		{
			gMS_GMK_SW_WORK.time = 12288;
		}
		if (gm_gmk_switch_state[gMS_GMK_SW_WORK.id].sw)
		{
			gMS_GMK_SW_WORK.top_pos_y = -10;
			gmGmkSwOnInit(oBS_OBJECT_WORK, false);
		}
		else
		{
			gMS_GMK_SW_WORK.top_pos_y = -14;
			gmGmkSwOffInit(oBS_OBJECT_WORK);
		}
		gmGmkSwSetCol(gMS_GMK_SW_WORK.gmk_work.ene_com.col_work, gMS_GMK_SW_WORK.top_pos_y);
		return oBS_OBJECT_WORK;
	}

