	private static void gmGmkSwOffInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SW_WORK gMS_GMK_SW_WORK = (GMS_GMK_SW_WORK)obj_work;
		gm_gmk_switch_state[gMS_GMK_SW_WORK.id].sw = false;
		gm_gmk_switch_state[gMS_GMK_SW_WORK.id].time = 0;
		obj_work.flag &= 4294967279u;
		if (gMS_GMK_SW_WORK.top_pos_y < -14)
		{
			gMS_GMK_SW_WORK.top_pos_y = -14;
		}
		obj_work.ppFunc = gmGmkSwOffMain;
	}

	private static void gmGmkSwOffMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SW_WORK gMS_GMK_SW_WORK = (GMS_GMK_SW_WORK)obj_work;
		if (gMS_GMK_SW_WORK.top_pos_y > -14)
		{
			gMS_GMK_SW_WORK.top_pos_y += -2;
			if (gMS_GMK_SW_WORK.top_pos_y < -14)
			{
				gMS_GMK_SW_WORK.top_pos_y = -14;
			}
			gmGmkSwSetCol(gMS_GMK_SW_WORK.gmk_work.ene_com.col_work, gMS_GMK_SW_WORK.top_pos_y);
		}
		if ((gMS_GMK_SW_WORK.gmk_work.ene_com.col_work.obj_col.rider_obj != null && gMS_GMK_SW_WORK.gmk_work.ene_com.col_work.obj_col.rider_obj.obj_type == 1) || (gMS_GMK_SW_WORK.gmk_work.ene_com.enemy_flag & 1) != 0)
		{
			gmGmkSwOnInit(obj_work, true);
		}
		gMS_GMK_SW_WORK.gmk_work.ene_com.enemy_flag &= 4294967294u;
	}

	private static void gmGmkSwOnInit(OBS_OBJECT_WORK obj_work, bool now_on)
	{
		GMS_GMK_SW_WORK gMS_GMK_SW_WORK = (GMS_GMK_SW_WORK)obj_work;
		gm_gmk_switch_state[gMS_GMK_SW_WORK.id].sw = true;
		gm_gmk_switch_state[gMS_GMK_SW_WORK.id].time = gMS_GMK_SW_WORK.time;
		if (gMS_GMK_SW_WORK.time != 0)
		{
			obj_work.flag |= 16u;
		}
		if (gMS_GMK_SW_WORK.top_pos_y > -10)
		{
			gMS_GMK_SW_WORK.top_pos_y = -10;
		}
		if (now_on)
		{
			GmSoundPlaySE("Switch");
			GMM_PAD_VIB_SMALL();
			GmComEfctCreateSpring(obj_work, 0, -32768, -obj_work.pos.z);
		}
		obj_work.ppFunc = gmGmkSwOnMain;
	}

	private static void gmGmkSwOnMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SW_WORK gMS_GMK_SW_WORK = (GMS_GMK_SW_WORK)obj_work;
		if (gMS_GMK_SW_WORK.top_pos_y < -10)
		{
			gMS_GMK_SW_WORK.top_pos_y += 2;
			if (gMS_GMK_SW_WORK.top_pos_y > -10)
			{
				gMS_GMK_SW_WORK.top_pos_y = -10;
			}
			gmGmkSwSetCol(gMS_GMK_SW_WORK.gmk_work.ene_com.col_work, gMS_GMK_SW_WORK.top_pos_y);
		}
		gMS_GMK_SW_WORK.gmk_work.ene_com.enemy_flag &= 4294967294u;
		if ((gMS_GMK_SW_WORK.gmk_work.ene_com.col_work.obj_col.rider_obj != null && gMS_GMK_SW_WORK.gmk_work.ene_com.col_work.obj_col.rider_obj.obj_type == 1) || (gMS_GMK_SW_WORK.gmk_work.ene_com.enemy_flag & 1) != 0)
		{
			gm_gmk_switch_state[gMS_GMK_SW_WORK.id].time = gMS_GMK_SW_WORK.time;
		}
		else if (gm_gmk_switch_state[gMS_GMK_SW_WORK.id].time != 0)
		{
			gm_gmk_switch_state[gMS_GMK_SW_WORK.id].time = ObjTimeCountDown(gm_gmk_switch_state[gMS_GMK_SW_WORK.id].time);
			if (gm_gmk_switch_state[gMS_GMK_SW_WORK.id].time == 0)
			{
				gmGmkSwOffInit(obj_work);
			}
		}
		gMS_GMK_SW_WORK.gmk_work.ene_com.enemy_flag &= 4294967294u;
	}

	private static void gmGmkSwitchDefFunc(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_ENEMY_COM_WORK != null && gMS_PLAYER_WORK != null && gMS_PLAYER_WORK.obj_work.obj_type == 1)
		{
			gMS_ENEMY_COM_WORK.enemy_flag |= 1u;
		}
	}

	private static void gmGmkSwDispFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SW_WORK gMS_GMK_SW_WORK = (GMS_GMK_SW_WORK)obj_work;
		VecFx32 value = default(VecFx32);
		uint p_disp_flag = obj_work.disp_flag;
		value.Assign(obj_work.pos);
		value.y += gMS_GMK_SW_WORK.top_pos_y << 12;
		ObjDrawAction3DNN(obj_work.obj_3d, value, obj_work.dir, obj_work.scale, ref obj_work.disp_flag);
		ObjDrawAction3DNN(gMS_GMK_SW_WORK.obj_3d_base, obj_work.pos, obj_work.dir, obj_work.scale, ref p_disp_flag);
	}

