	{
		if (g_gs_main_sys_info.stage_id != 9)
		{
			col_work.obj_col.ofst_y = (short)top_pos_y;
		}
	}

	private static OBS_OBJECT_WORK GmGmkSsEnduranceInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_SS_ENDURANCE");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.view_out_ofst -= 128;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_ss_endurance_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		oBS_OBJECT_WORK.pos.z = -131072;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 2u;
		oBS_OBJECT_WORK.user_flag = (uint)((~eve_rec.flag & 3) + 1 - eve_rec.byte_param[1]);
		oBS_OBJECT_WORK.user_work = gmGmkSsEnduranceColorSet(oBS_OBJECT_WORK.user_flag);
		gmGmkSsEnduranceScaleSet(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.ppFunc = gmGmkSsEnduranceWait;
		oBS_OBJECT_WORK.user_timer = 0;
		oBS_OBJECT_WORK.ppOut = gmGmkSsEnduranceDrawFunc;
		OBS_COLLISION_WORK col_work = gMS_ENEMY_3D_WORK.ene_com.col_work;
		col_work.obj_col.obj = oBS_OBJECT_WORK;
		col_work.obj_col.diff_data = g_gm_default_col;
		col_work.obj_col.width = 24;
		col_work.obj_col.height = 24;
		col_work.obj_col.ofst_x = (short)(-(col_work.obj_col.width / 2));
		col_work.obj_col.ofst_y = (short)(-(col_work.obj_col.height / 2));
		col_work.obj_col.attr = 2;
		col_work.obj_col.flag |= 134217760u;
		return oBS_OBJECT_WORK;
	}

