	private static void gmGmkSsEnduranceWait(OBS_OBJECT_WORK obj_work)
	{
		OBS_COLLISION_OBJ obj_col = obj_work.col_work.obj_col;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((GmSplStageGetWork().flag & 4) != 0)
		{
			obj_work.flag |= 4u;
			return;
		}
		if (obj_col.toucher_obj == gMS_PLAYER_WORK.obj_work)
		{
			obj_work.ppFunc = gmGmkSsEnduranceDamage;
			obj_work.user_timer |= 30;
			GmSoundPlaySE("Special3");
		}
		gmGmkSsEnduranceUpdateUVTimer(obj_work);
		GmGmkSsSquareBounce(obj_work);
	}

	private static void gmGmkSsEnduranceDamage(OBS_OBJECT_WORK obj_work)
	{
		if ((GmSplStageGetWork().flag & 4) != 0)
		{
			obj_work.flag |= 4u;
			return;
		}
		uint num = (uint)(obj_work.user_timer & 0xFF);
		num--;
		obj_work.user_timer = (int)((obj_work.user_timer & 0xFFFFFF00u) | (num & 0xFF));
		if (num == 0)
		{
			obj_work.user_flag--;
			((GMS_ENEMY_3D_WORK)obj_work).ene_com.eve_rec.byte_param[1]++;
			if ((obj_work.user_flag & 0x7FFFFFFF) != 0)
			{
				gmGmkSsEnduranceScaleSet(obj_work);
				obj_work.user_work = gmGmkSsEnduranceColorSet(obj_work.user_flag & 0x7FFFFFFF);
				obj_work.ppFunc = gmGmkSsEnduranceWait;
			}
			else
			{
				obj_work.flag |= 4u;
				((GMS_ENEMY_3D_WORK)obj_work).ene_com.enemy_flag |= 65536u;
				GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctZoneEsCreate(obj_work, 5, 8);
				gMS_EFFECT_3DES_WORK.efct_com.obj_work.flag |= 512u;
			}
		}
		else
		{
			uint color_num = (uint)(((obj_work.user_timer & 0xC) >> 2) + 1);
			obj_work.user_work = gmGmkSsEnduranceColorSet(color_num);
		}
		gmGmkSsEnduranceUpdateUVTimer(obj_work);
		GmGmkSsSquareBounce(obj_work);
	}

	private static void gmGmkSsEnduranceDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		OBS_ACTION3D_NN_WORK obj_3d = obj_work.obj_3d;
		if (GmMainIsDrawEnable() && (obj_work.disp_flag & 0x20) == 0)
		{
			TVX_FILE tVX_FILE;
			if (gm_gmk_ss_endurance_obj_tvx_list.buf[0] == null)
			{
				tVX_FILE = new TVX_FILE((AmbChunk)amBindGet(gm_gmk_ss_endurance_obj_tvx_list, 0));
				gm_gmk_ss_endurance_obj_tvx_list.buf[0] = tVX_FILE;
			}
			else
			{
				tVX_FILE = (TVX_FILE)gm_gmk_ss_endurance_obj_tvx_list.buf[0];
			}
			NNS_TEXLIST texlist = obj_work.obj_3d.texlist;
			GMS_TVX_EX_WORK ex_work = default(GMS_TVX_EX_WORK);
			uint num = ((uint)obj_work.user_timer >> 10) & 0x1F;
			ex_work.u_wrap = 1;
			ex_work.v_wrap = 1;
			ex_work.coord.u = 0.125f * (float)(gm_gmk_ss_endurance_uv_parameter[num] % 4) + gm_gmk_ss_endurance_mat_color[obj_work.user_work].u;
			ex_work.coord.v = 0.125f * (float)(gm_gmk_ss_endurance_uv_parameter[num] / 4) + gm_gmk_ss_endurance_mat_color[obj_work.user_work].v;
			ex_work.color = uint.MaxValue;
			GmTvxSetModelEx(tVX_FILE, texlist, ref obj_work.pos, ref obj_work.scale, GMD_TVX_DISP_SCALE | GMD_TVX_DISP_LIGHT_DISABLE, 0, ref ex_work);
		}
	}

	private static void gmGmkSsEnduranceUpdateUVTimer(OBS_OBJECT_WORK obj_work)
	{
		uint num = ((uint)obj_work.user_timer >> 8) & 0x7F;
		num++;
		if (num >= 120)
		{
			num = 0u;
		}
		obj_work.user_timer = (int)((obj_work.user_timer & 0xFF) | (num << 8));
	}

	private static uint gmGmkSsEnduranceColorSet(uint color_num)
	{
		return gm_gmk_ss_endurance_color[color_num];
	}

	private static void gmGmkSsEnduranceScaleSet(OBS_OBJECT_WORK obj_work)
	{
		int z = 4096;
		switch (obj_work.user_flag & 0x7FFFFFFF)
		{
		case 1u:
			z = 2867;
			break;
		case 2u:
			z = 3276;
			break;
		case 3u:
			z = 3686;
			break;
		}
		obj_work.scale.x = (obj_work.scale.y = (obj_work.scale.z = z));
	}

