		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 2u;
		oBS_OBJECT_WORK.user_flag = 0u;
		if (eve_rec.id == 194)
		{
			oBS_OBJECT_WORK.ppFunc = gmGmkSsOnewayMain;
			oBS_OBJECT_WORK.disp_flag |= 134217728u;
			oBS_OBJECT_WORK.obj_3d.drawflag |= 8388608u;
			oBS_OBJECT_WORK.obj_3d.draw_state.alpha.alpha = 0.5f;
		}
		else
		{
			oBS_OBJECT_WORK.ppFunc = gmGmkSsCircleMain;
			OBS_COLLISION_WORK col_work = gMS_ENEMY_3D_WORK.ene_com.col_work;
			col_work.obj_col.obj = oBS_OBJECT_WORK;
			col_work.obj_col.diff_data = g_gm_default_col;
			col_work.obj_col.width = 24;
			col_work.obj_col.height = 24;
			col_work.obj_col.ofst_x = (short)(-(col_work.obj_col.width / 2));
			col_work.obj_col.ofst_y = (short)(-(col_work.obj_col.height / 2));
			col_work.obj_col.attr = 2;
			col_work.obj_col.flag |= 134217760u;
		}
		oBS_OBJECT_WORK.ppOut = gmGmkSsCircleDrawFunc;
		return oBS_OBJECT_WORK;
	}

	private static void GmGmkSsOnewayThrough(uint sw_no)
	{
		GmSplStageSwSet(sw_no);
	}

	private static void gmGmkSsCircleMain(OBS_OBJECT_WORK obj_work)
	{
		if ((GmSplStageGetWork().flag & 4) != 0)
		{
			obj_work.flag |= 4u;
			return;
		}
		if ((g_gm_main_system.sync_time & 0xF) == 0)
		{
			obj_work.dir.z += 8192;
		}
		GmGmkSsSquareBounce(obj_work);
	}

	private static void gmGmkSsOnewayMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if ((GmSplStageGetWork().flag & 4) != 0)
		{
			obj_work.flag |= 4u;
			return;
		}
		if (GmSplStageSwCheck(gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag))
		{
			obj_work.ppFunc = gmGmkSsCircleMain;
			OBS_COLLISION_WORK col_work = gMS_ENEMY_3D_WORK.ene_com.col_work;
			col_work.obj_col.obj = obj_work;
			col_work.obj_col.diff_data = g_gm_default_col;
			col_work.obj_col.width = 24;
			col_work.obj_col.height = 24;
			col_work.obj_col.ofst_x = (short)(-(col_work.obj_col.width / 2));
			col_work.obj_col.ofst_y = (short)(-(col_work.obj_col.height / 2));
			col_work.obj_col.attr = 2;
			col_work.obj_col.flag |= 134217760u;
			obj_work.disp_flag &= 4160749567u;
			obj_work.obj_3d.drawflag &= 4286578687u;
			obj_work.obj_3d.draw_state.alpha.alpha = 1f;
		}
		GmGmkSsSquareBounce(obj_work);
	}

	private static void gmGmkSsCircleDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		if (GmMainIsDrawEnable() && (obj_work.disp_flag & 0x20) == 0)
		{
			TVX_FILE tVX_FILE;
			if (gm_gmk_ss_circle_obj_tvx_list.buf[0] == null)
			{
				tVX_FILE = new TVX_FILE((AmbChunk)amBindGet(gm_gmk_ss_circle_obj_tvx_list, 0));
				gm_gmk_ss_circle_obj_tvx_list.buf[0] = tVX_FILE;
			}
			else
			{
				tVX_FILE = (TVX_FILE)gm_gmk_ss_circle_obj_tvx_list.buf[0];
			}
			NNS_TEXLIST texlist = obj_work.obj_3d.texlist;
			uint num = GMD_TVX_DISP_LIGHT_DISABLE | GMD_TVX_DISP_ROTATE;
			GMS_TVX_EX_WORK ex_work = new GMS_TVX_EX_WORK
			{
				u_wrap = 1,
				v_wrap = 1,
				coord = 
				{
					u = 0f,
					v = 0f
				},
				color = uint.MaxValue
			};
			if (obj_work.obj_3d.draw_state.alpha.alpha == 0.5f)
			{
				ex_work.color = 4294967176u;
				num |= GMD_TVX_DISP_BLEND;
			}
			GmTvxSetModelEx(tVX_FILE, texlist, ref obj_work.pos, ref obj_work.scale, num, (short)(-obj_work.dir.z), ref ex_work);
		}
	}

