	private static bool gmGmkBoss3RouteCheckHit(OBS_OBJECT_WORK target_obj_work, OBS_OBJECT_WORK gimmick_obj_work)
	{
		int num = target_obj_work.pos.x - gimmick_obj_work.pos.x;
		int num2 = target_obj_work.pos.y - gimmick_obj_work.pos.y;
		if (MTM_MATH_ABS(num) > 262144 || MTM_MATH_ABS(num2) > 262144)
		{
			return false;
		}
		int num3 = FX_Mul(num, num) + FX_Mul(num2, num2);
		int num4 = FX_Mul(262144, 262144);
		if (num3 > num4)
		{
			return false;
		}
		return true;
	}

	private static bool gmGmkBoss3RouteSetMoveParam(OBS_OBJECT_WORK target_obj_work, OBS_OBJECT_WORK gimmick_obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)gimmick_obj_work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		float num = (float)(int)gMS_ENEMY_3D_WORK.ene_com.eve_rec.width / 10f;
		if (gMS_PLAYER_WORK.obj_work.pos.y >= target_obj_work.pos.y && (gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 1) != 0 && ObjViewOutCheck(target_obj_work.pos.x, target_obj_work.pos.y, 96, 0, 0, 0, 0) != 0)
		{
			target_obj_work.spd.x = 0;
			target_obj_work.spd.y = 0;
			return false;
		}
		int x = gimmick_obj_work.pos.x + gMS_ENEMY_3D_WORK.ene_com.eve_rec.left * 64 * 4096;
		int x2 = gimmick_obj_work.pos.y + gMS_ENEMY_3D_WORK.ene_com.eve_rec.top * 64 * 4096;
		float num2 = FX_FX32_TO_F32(x);
		float num3 = FX_FX32_TO_F32(x2);
		float num4 = FX_FX32_TO_F32(target_obj_work.pos.x);
		float num5 = FX_FX32_TO_F32(target_obj_work.pos.y);
		float num6 = num2 - num4;
		float num7 = num3 - num5;
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		amVectorSet(nNS_VECTOR, num6, num7, 0f);
		float num8 = 1f / nnLengthVector(nNS_VECTOR);
		float x3 = num6 * num8 * num;
		float x4 = num7 * num8 * num;
		target_obj_work.spd.x = FX_F32_TO_FX32(x3);
		target_obj_work.spd.y = FX_F32_TO_FX32(x4);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		return true;
	}

	private static void gmGmkBoss3RouteMainFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		for (OBS_OBJECT_WORK oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, 2); oBS_OBJECT_WORK != null; oBS_OBJECT_WORK = ObjObjectSearchRegistObject(oBS_OBJECT_WORK, 2))
		{
			GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)oBS_OBJECT_WORK;
			if (gMS_ENEMY_COM_WORK.eve_rec.id == 319)
			{
				if (gmGmkBoss3RouteCheckHit(oBS_OBJECT_WORK, obj_work))
				{
					if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 2) != 0)
					{
						oBS_OBJECT_WORK.spd.x = 0;
						oBS_OBJECT_WORK.spd.y = 0;
						oBS_OBJECT_WORK.user_flag = 1u;
						obj_work.flag |= 4u;
						obj_work.ppFunc = null;
						gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 65536u;
					}
					else if (gmGmkBoss3RouteSetMoveParam(oBS_OBJECT_WORK, obj_work))
					{
						obj_work.flag |= 4u;
						obj_work.ppFunc = null;
						gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 65536u;
					}
				}
				break;
			}
		}
	}

