		GMS_ENE_T_STAR_WORK gMS_ENE_T_STAR_WORK = (GMS_ENE_T_STAR_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_t_star_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(682), null, 0, null);
		OBS_DATA_WORK data_work = ObjDataGet(683);
		ObjObjectAction3dNNMaterialMotionLoad(oBS_OBJECT_WORK, 0, data_work, null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.z = 655360;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -16, -16, 16, 16);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		ObjRectWorkSet(oBS_RECT_WORK, -10, -10, 10, 10);
		oBS_RECT_WORK.flag |= 4u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, -20, -20, 20, 20);
		oBS_RECT_WORK.flag &= 4294967291u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.move_flag &= 4294967167u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		if ((eve_rec.flag & 7) == 0)
		{
			gMS_ENE_T_STAR_WORK.fSpd = 1f;
		}
		else
		{
			gMS_ENE_T_STAR_WORK.fSpd = 0f;
			if ((eve_rec.flag & 1) != 0)
			{
				gMS_ENE_T_STAR_WORK.fSpd += 0.5f;
			}
			if ((eve_rec.flag & 2) != 0)
			{
				gMS_ENE_T_STAR_WORK.fSpd += 0.25f;
			}
			if ((eve_rec.flag & 4) != 0)
			{
				gMS_ENE_T_STAR_WORK.fSpd += 0.125f;
			}
		}
		oBS_OBJECT_WORK.user_work = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left << 12));
		oBS_OBJECT_WORK.user_flag = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left + eve_rec.width << 12));
		gmEneTStarWaitInit(oBS_OBJECT_WORK);
		GmEneUtilInitNodeMatrix(gMS_ENE_T_STAR_WORK.node_work, oBS_OBJECT_WORK, 10);
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmEneTStarExit);
		GmEneUtilGetNodeMatrix(gMS_ENE_T_STAR_WORK.node_work, 4);
		GmEneUtilGetNodeMatrix(gMS_ENE_T_STAR_WORK.node_work, 5);
		GmEneUtilGetNodeMatrix(gMS_ENE_T_STAR_WORK.node_work, 6);
		GmEneUtilGetNodeMatrix(gMS_ENE_T_STAR_WORK.node_work, 7);
		GmEneUtilGetNodeMatrix(gMS_ENE_T_STAR_WORK.node_work, 8);
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK2 = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		gMS_ENEMY_3D_WORK2.ene_com.enemy_flag |= 32768u;
		oBS_OBJECT_WORK.scale.x = FX_F32_TO_FX32(1.25f);
		oBS_OBJECT_WORK.scale.y = FX_F32_TO_FX32(1.25f);
		oBS_OBJECT_WORK.scale.z = FX_F32_TO_FX32(1.25f);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

