	public static int gmEneTStarGetLength2N(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
		{
			return int.MaxValue;
		}
		int x = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
		int x2 = gMS_PLAYER_WORK.obj_work.pos.y - obj_work.pos.y;
		float num = FX_FX32_TO_F32(x);
		float num2 = FX_FX32_TO_F32(x2);
		return (int)(num * num + num2 * num2);
	}

	public static VecFx32 gmEneTStarGetPlayerVectorFx(OBS_OBJECT_WORK obj_work)
	{
		VecFx32 result = default(VecFx32);
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		int num = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
		int num2 = gMS_PLAYER_WORK.obj_work.pos.y - obj_work.pos.y;
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
		{
			num = 2965504;
			num2 = 2965504;
		}
		int x = FX_Mul(num, num) + FX_Mul(num2, num2);
		x = FX_Sqrt(x);
		if (x == 0)
		{
			result.x = 0;
			result.y = 0;
		}
		else
		{
			int v = FX_Div(4096, x);
			result.x = FX_Mul(num, v);
			result.y = FX_Mul(num2, v);
		}
		result.z = 0;
		return result;
	}

	public static void gmEneTStarWaitInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneTStarWaitMain;
		obj_work.move_flag &= 4294967291u;
		obj_work.spd.x = 0;
		obj_work.spd.y = 0;
	}

	public static void gmEneTStarWaitMain(OBS_OBJECT_WORK obj_work)
	{
		if (gmEneTStarGetLength2N(obj_work) < 16384)
		{
			obj_work.ppFunc = gmEneTStarWalkInit;
		}
	}

	public static void gmEneTStarWalkInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_ENE_T_STAR_WORK gMS_ENE_T_STAR_WORK = (GMS_ENE_T_STAR_WORK)obj_work;
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneTStarWalkMain;
		obj_work.move_flag &= 4294967291u;
		VecFx32 vecFx = gmEneTStarGetPlayerVectorFx(obj_work);
		obj_work.spd.x = (int)((float)vecFx.x * 0.5f * gMS_ENE_T_STAR_WORK.fSpd);
		obj_work.spd.y = (int)((float)vecFx.y * 0.5f * gMS_ENE_T_STAR_WORK.fSpd);
		gMS_ENE_T_STAR_WORK.timer = 120;
		ObjDrawObjectActionSet3DNNMaterial(obj_work, 0);
		gMS_ENE_T_STAR_WORK.rotate = 0;
	}

	public static void gmEneTStarWalkMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_T_STAR_WORK gMS_ENE_T_STAR_WORK = (GMS_ENE_T_STAR_WORK)obj_work;
		obj_work.disp_flag |= 4u;
		if (gMS_ENE_T_STAR_WORK.rotate > 0)
		{
			obj_work.dir.z += (ushort)AKM_DEGtoA16(10);
			gMS_ENE_T_STAR_WORK.rotate--;
			if (gMS_ENE_T_STAR_WORK.rotate == 0)
			{
				obj_work.dir.z = 0;
			}
		}
		if (gMS_ENE_T_STAR_WORK.timer > 0)
		{
			gMS_ENE_T_STAR_WORK.timer--;
			if (gMS_ENE_T_STAR_WORK.timer == 60)
			{
				gMS_ENE_T_STAR_WORK.rotate = 36;
			}
		}
		else
		{
			obj_work.spd.x = 0;
			obj_work.spd.y = 0;
			gMS_ENE_T_STAR_WORK.timer = 15;
			obj_work.ppFunc = gmEneTStarStopMain;
		}
	}

	public static void gmEneTStarStopMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_T_STAR_WORK gMS_ENE_T_STAR_WORK = (GMS_ENE_T_STAR_WORK)obj_work;
		obj_work.disp_flag |= 4u;
		if (gMS_ENE_T_STAR_WORK.timer > 0)
		{
			gMS_ENE_T_STAR_WORK.timer--;
			return;
		}
		obj_work.ppFunc = gmEneTStarAttackInit;
		GmEfctEneEsCreate(obj_work, 11);
	}

	public static void gmEneTStarAttackInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_T_STAR_WORK gMS_ENE_T_STAR_WORK = (GMS_ENE_T_STAR_WORK)obj_work;
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		NNS_MATRIX nNS_MATRIX2 = GlobalPool<NNS_MATRIX>.Alloc();
		nnMakeUnitMatrix(nNS_MATRIX);
		nnMakeUnitMatrix(nNS_MATRIX2);
		nnMakeRotateZMatrix(nNS_MATRIX2, AKM_DEGtoA32(72));
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		for (int i = 0; i < 5; i++)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GmEventMgrLocalEventBirth(308, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
			oBS_OBJECT_WORK.parent_obj = obj_work;
			oBS_OBJECT_WORK.dir.y = 49152;
			oBS_OBJECT_WORK.dir.z = (ushort)AKM_DEGtoA16(-72 * i);
			nNS_VECTOR.x = nNS_MATRIX.M01;
			nNS_VECTOR.y = nNS_MATRIX.M11;
			nNS_VECTOR.z = 0f;
			oBS_OBJECT_WORK.spd.x = FX_F32_TO_FX32(nNS_VECTOR.x * 4f);
			oBS_OBJECT_WORK.spd.y = -FX_F32_TO_FX32(nNS_VECTOR.y * 4f);
			oBS_OBJECT_WORK.pos.x += FX_F32_TO_FX32(nNS_VECTOR.x * 10f);
			oBS_OBJECT_WORK.pos.y += -FX_F32_TO_FX32(nNS_VECTOR.y * 10f);
			nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX, nNS_MATRIX2);
			GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
			gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 32768u;
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctEneEsCreate(oBS_OBJECT_WORK, 10);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.dir.z = (ushort)AKM_DEGtoA16(-72 * i);
		}
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		obj_work.disp_flag |= 32u;
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneTStarAttackMain;
		obj_work.move_flag &= 4294967291u;
		obj_work.spd.x = 0;
		obj_work.spd.y = 0;
		gMS_ENE_T_STAR_WORK.timer = 300;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK2 = (GMS_ENEMY_3D_WORK)obj_work;
		gMS_ENEMY_3D_WORK2.ene_com.rect_work[1].flag &= 4294967291u;
		gMS_ENEMY_3D_WORK2.ene_com.rect_work[0].flag &= 4294967291u;
		gMS_ENEMY_3D_WORK2.ene_com.rect_work[2].flag &= 4294967291u;
		GmSoundPlaySE("Boss2_03");
		gMS_ENEMY_3D_WORK2.ene_com.enemy_flag |= 65536u;
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX2);
	}

	public static void gmEneTStarAttackMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_T_STAR_WORK gMS_ENE_T_STAR_WORK = (GMS_ENE_T_STAR_WORK)obj_work;
		if (gMS_ENE_T_STAR_WORK.timer > 0)
		{
			gMS_ENE_T_STAR_WORK.timer--;
		}
		else
		{
			obj_work.flag |= 8u;
		}
	}

