	public static void gmBoss5CtpltProcIdle(GMS_BOSS5_CTPLT_WORK ctplt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(ctplt_work);
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		GMS_BOSS5_MGR_WORK mgr_work = gMS_BOSS5_BODY_WORK.mgr_work;
		if ((mgr_work.flag & 0x800000) != 0)
		{
			oBS_OBJECT_WORK.spd_add.y = GMD_BOSS5_CTPLT_MOVE_DOWN_ACC;
			ctplt_work.proc_update = gmBoss5CtpltProcMoveDown;
		}
	}

	public static void gmBoss5CtpltProcMoveDown(GMS_BOSS5_CTPLT_WORK ctplt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(ctplt_work);
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		GMS_BOSS5_MGR_WORK mgr_work = gMS_BOSS5_BODY_WORK.mgr_work;
		if (oBS_OBJECT_WORK.pos.y > gMS_BOSS5_BODY_WORK.ground_v_pos + GMD_BOSS5_CTPLT_MOVE_DOWN_HIDE_HEIGHT)
		{
			mgr_work.flag |= 16777216u;
			oBS_OBJECT_WORK.flag |= 4u;
		}
	}

	private void DmLogoSegaInit(object arg)
	{
		AoAccountClearCurrentId();
		if (DmLogoSegaBuildCheck())
		{
			dmLogoSegaStart();
			return;
		}
		MTM_TASK_MAKE_TCB(dmLogoSegaLoadWait, null, 0u, ushort.MaxValue, 4096u, 0, null, "DM_LSEGA_LW");
		DmLogoSegaLoad();
	}

	private void DmLogoSegaLoad()
	{
		GSE_REGION gSE_REGION = GsEnvGetRegion();
		DmLogoComLoadFileCreate(dm_logo_sega_load_tcb);
		DmLogoComLoadFileReg(dm_logo_sega_load_tcb, dm_logo_sega_com_fileinfo_list, dm_logo_sega_com_file_num);
		DmLogoComLoadFileReg(dm_logo_sega_load_tcb, dm_logo_sega_localize_fileinfo_list_tbl[(int)gSE_REGION], dm_logo_sega_localize_file_num);
		DmLogoComLoadFileStart(dm_logo_sega_load_tcb);
	}

	private bool DmLogoSegaLoadCheck()
	{
		if (dm_logo_sega_load_tcb.Target == null && dm_logo_sega_data[0] != null)
		{
			return true;
		}
		return false;
	}

	private void DmLogoSegaBuild()
	{
		AMS_AMB_HEADER[] array = new AMS_AMB_HEADER[2];
		dm_logo_sega_build_tcb = MTM_TASK_MAKE_TCB(dmLogoSegaDataBuildMain, dmLogoSegaDataBuildDest, 0u, ushort.MaxValue, 4096u, 0, null, "DM_LSEGA_BUILD");
		g_obj.def_user_light_flag = 1u;
		GmGameDBuildModelBuildInit();
		dm_logo_sega_obj_3d_list = GmGameDBuildRegBuildModel(dm_logo_sega_data[0], dm_logo_sega_data[1], 0u);
		dm_logo_sega_aos_tex = New<AOS_TEXTURE>(2);
		string sPath;
		array[0] = readAMBFile(amBindGet(dm_logo_sega_data[4], 1, out sPath));
		array[0].dir = sPath;
		array[1] = readAMBFile(amBindGet(dm_logo_sega_data[3], 105, out sPath));
		array[1].dir = sPath;
		AOS_TEXTURE[] array2 = dm_logo_sega_aos_tex;
		for (int i = 0; i < 2; i++)
		{
			if (array[i] != null)
			{
				AoTexBuild(array2[i], array[i]);
				AoTexLoad(array2[i]);
			}
		}
		for (int i = 0; i < 2; i++)
		{
			dm_logo_sega_efct_mdl_state[i] = ObjAction3dESModelLoadToDwork(dm_logo_sega_efct_mdl_data_work[i], (AmbChunk)amBindGet(dm_logo_sega_data[3], dm_logo_sega_efct_mdl_id_tbl[i]), 0u);
		}
	}

	private bool DmLogoSegaBuildCheck()
	{
		if (dm_logo_sega_build_state)
		{
			return true;
		}
		return false;
	}

	private void DmLogoSegaFlush()
	{
		dm_logo_sega_flush_tcb = MTM_TASK_MAKE_TCB(dmLogoSegaDataFlushMain, dmLogoSegaDataFlushDest, 0u, ushort.MaxValue, 4096u, 0, null, "DM_TOP_FLUSH");
		GmGameDBuildModelFlushInit();
		AMS_AMB_HEADER aMS_AMB_HEADER = dm_logo_sega_data[0];
		GmGameDBuildRegFlushModel(dm_logo_sega_obj_3d_list, aMS_AMB_HEADER.file_num);
		ArrayPointer<AOS_TEXTURE> arrayPointer = dm_logo_sega_aos_tex;
		int num = 0;
		while (num < 2)
		{
			AoTexRelease(arrayPointer);
			num++;
			++arrayPointer;
		}
		for (num = 0; num < 2; num++)
		{
			dm_logo_sega_efct_mdl_state[num] = ObjAction3dESModelReleaseDwork(dm_logo_sega_efct_mdl_data_work[num]);
		}
	}

	private bool DmLogoSegaFlushCheck()
	{
		if (!dm_logo_sega_build_state)
		{
			return true;
		}
		return false;
	}

	private void DmLogoSegaRelease()
	{
		for (int i = 0; i < 5; i++)
		{
			AMS_AMB_HEADER aMS_AMB_HEADER = dm_logo_sega_data[i];
			dm_logo_sega_data[i] = null;
		}
	}

	private bool DmLogoSegaReleaseCheck()
	{
		if (dm_logo_sega_load_tcb.Target == null && dm_logo_sega_data[0] == null)
		{
			return true;
		}
		return false;
	}

	private void dmLogoSegaStart()
	{
		NNS_RGBA diffuse = new NNS_RGBA(1f, 1f, 1f, 1f);
		NNS_RGB ambient = new NNS_RGB(1f, 1f, 1f);
		dmLogoSegaObjSysytemInit();
		GsSoundReset();
		GsSoundBegin(3, 32767u, 0);
		MTS_TASK_TCB mTS_TASK_TCB = MTM_TASK_MAKE_TCB(dmLogoSegaMainFunc, null, 0u, 0, 4096u, 0, () => new DMS_LOGO_SEGA_WORK(), "DM_LSEGA_MAIN");
		DMS_LOGO_SEGA_WORK dMS_LOGO_SEGA_WORK = (DMS_LOGO_SEGA_WORK)mTS_TASK_TCB.work;
		nnSetPrimitive3DMaterial(ref diffuse, ref ambient, 1f);
		AoActSysSetDrawStateEnable(false);
		dmLogoSegaActionCreate(dMS_LOGO_SEGA_WORK);
		dMS_LOGO_SEGA_WORK.ply_obj = dmLogoSegaCreatePlayer();
		dMS_LOGO_SEGA_WORK.timer = 0;
		dMS_LOGO_SEGA_WORK.func = dmLogoSegaStartWaitFunc;
		dMS_LOGO_SEGA_WORK.h_se = GsSoundAllocSeHandle();
	}

	private void dmLogoSegaObjSysytemInit()
	{
		NNS_RGBA col = new NNS_RGBA(1f, 1f, 1f, 1f);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR pos = new NNS_VECTOR(0f, 0f, 50f);
		ObjInit(4, 61435, 0, GMD_OBJ_LCD_X, GMD_OBJ_LCD_Y, GSD_DISP_WIDTH, GSD_DISP_HEIGHT);
		ObjDataAlloc(10);
		ObjDrawESEffectSystemInit(0, 20480u, 0u);
		ObjDrawSetNNCommandStateTbl(0u, 0u, true);
		AoActSysClearPeak();
		g_obj.flag = 4259848u;
		g_obj.ppPre = null;
		g_obj.ppPost = null;
		g_obj.ppCollision = null;
		g_obj.ppObjPre = null;
		g_obj.ppObjPost = null;
		g_obj.ppRegRecAuto = null;
		g_obj.draw_scale.x = (g_obj.draw_scale.y = (g_obj.draw_scale.z = 29127));
		g_obj.inv_draw_scale.x = (g_obj.inv_draw_scale.y = (g_obj.inv_draw_scale.z = FX_Div(4096, g_obj.draw_scale.x)));
		g_obj.depth = 128;
		g_obj.ambient_color.r = 0.8f;
		g_obj.ambient_color.g = 0.8f;
		g_obj.ambient_color.b = 0.8f;
		nNS_VECTOR.x = -1f;
		nNS_VECTOR.y = -1f;
		nNS_VECTOR.z = -1f;
		nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
		ObjDrawSetParallelLight(NNE_LIGHT_0, ref col, 1f, nNS_VECTOR);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		ObjCameraInit(0, pos, 0, 0, 6144);
		ObjCamera3dInit(0);
		g_obj.glb_camera_id = 0;
		g_obj.glb_camera_type = 1;
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
		oBS_CAMERA.user_func = dmLogoSegaCamera;
		oBS_CAMERA.command_state = 0u;
		oBS_CAMERA.scale = 0.9f;
		oBS_CAMERA.ofst.z = 1000f;
		amTrailEFInitialize();
	}

	private void dmLogoSegaPreEnd(DMS_LOGO_SEGA_WORK logo_work)
	{
		amTrailEFDeleteGroup(1);
		for (OBS_OBJECT_WORK oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, ushort.MaxValue); oBS_OBJECT_WORK != null; oBS_OBJECT_WORK = ObjObjectSearchRegistObject(oBS_OBJECT_WORK, ushort.MaxValue))
		{
			oBS_OBJECT_WORK.ppOut = null;
		}
	}

	private void dmLogoSegaEnd(DMS_LOGO_SEGA_WORK logo_work)
	{
		dmLogoSegaActionDelete(logo_work);
		g_obj.ppPre = null;
		ObjObjectClearAllObject();
		ObjPreExit();
		ObjDrawESEffectSystemExit();
		ObjExit();
		GsSoundStopSeHandle(logo_work.h_se);
		GsSoundFreeSeHandle(logo_work.h_se);
		GsSoundHalt();
		GsSoundEnd();
		GsSoundReset();
	}

	private void dmLogoSegaMainFunc(MTS_TASK_TCB tcb)
	{
		DMS_LOGO_SEGA_WORK dMS_LOGO_SEGA_WORK = (DMS_LOGO_SEGA_WORK)tcb.work;
		if (GsSystemBgmIsPlay())
		{
			dMS_LOGO_SEGA_WORK.h_se.snd_ctrl_param.volume = 0f;
		}
		else
		{
			dMS_LOGO_SEGA_WORK.h_se.snd_ctrl_param.volume = 1f;
		}
		if (AoSysIsShowPlatformUI())
		{
			if (IzFadeIsExe())
			{
				IzFadeSetStopUpdate1Frame(null);
			}
		}
		else
		{
			if (dMS_LOGO_SEGA_WORK.func != null)
			{
				dMS_LOGO_SEGA_WORK.func(dMS_LOGO_SEGA_WORK);
			}
			if ((dMS_LOGO_SEGA_WORK.flag & 1) != 0)
			{
				dmLogoSegaPreEnd(dMS_LOGO_SEGA_WORK);
				mtTaskChangeTcbProcedure(tcb, gmLogoSegaPreEndWaitFunc);
				dMS_LOGO_SEGA_WORK.timer = 0;
				return;
			}
		}
		float frame = 0f;
		if (!AoSysIsShowPlatformUI() && (dMS_LOGO_SEGA_WORK.flag & 2) != 0)
		{
			frame = 1f;
		}
		AoActSysSetDrawTaskPrio();
		for (int i = 0; i < 8; i++)
		{
			AoActSetTexture(AoTexGetTexList(dm_logo_sega_aos_tex[dm_logo_sega_tex_id_tbl[i]]));
			AoActUpdate(dMS_LOGO_SEGA_WORK.act[i], frame);
			AoActDraw(dMS_LOGO_SEGA_WORK.act[i]);
		}
		NNS_RGBA diffuse = new NNS_RGBA(1f, 1f, 1f, 1f);
		NNS_RGB ambient = new NNS_RGB(1f, 1f, 1f);
		if (!AoSysIsShowPlatformUI())
		{
			amTrailEFUpdate(1);
		}
		if (g_obj.glb_camera_id != -1)
		{
			SNNS_VECTOR disp_pos = default(SNNS_VECTOR);
			SNNS_VECTOR pDst = default(SNNS_VECTOR);
			SNNS_MATRIX dst = default(SNNS_MATRIX);
			nnMakeUnitMatrix(ref dst);
			ObjDraw3DNNSetCameraEx(g_obj.glb_camera_id, g_obj.glb_camera_type, 0u);
			ObjCameraDispPosGet(g_obj.glb_camera_id, out disp_pos);
			amVectorSet(ref pDst, 0f - dst.M03, 0f - dst.M13, 0f - dst.M23);
			nnAddVector(ref disp_pos, ref pDst, ref disp_pos);
			amEffectSetCameraPos(ref disp_pos);
		}
		nnSetPrimitive3DMaterial(ref diffuse, ref ambient, 1f);
		NNS_TEXLIST texlist = dm_logo_sega_aos_tex[0].texlist;
		amTrailEFDraw(1, texlist, 0u);
	}

	private void gmLogoSegaPreEndWaitFunc(MTS_TASK_TCB tcb)
	{
		DMS_LOGO_SEGA_WORK dMS_LOGO_SEGA_WORK = (DMS_LOGO_SEGA_WORK)tcb.work;
		dMS_LOGO_SEGA_WORK.timer++;
		if (dMS_LOGO_SEGA_WORK.timer > 2)
		{
			dmLogoSegaEnd(dMS_LOGO_SEGA_WORK);
			mtTaskChangeTcbProcedure(tcb, gmLogoSegaEndWaitFunc);
		}
	}

	private void gmLogoSegaEndWaitFunc(MTS_TASK_TCB tcb)
	{
		if (ObjObjectCheckClearAllObject() && !ObjIsExitWait())
		{
			DmLogoSegaFlush();
			mtTaskChangeTcbProcedure(tcb, gmLogoSegaFlushWaitFunc);
		}
	}

	private void gmLogoSegaFlushWaitFunc(MTS_TASK_TCB tcb)
	{
		if (DmLogoSegaFlushCheck())
		{
			DmLogoSegaRelease();
			mtTaskChangeTcbProcedure(tcb, gmLogoSegaRelesehWaitFunc);
		}
	}

	private void gmLogoSegaRelesehWaitFunc(MTS_TASK_TCB tcb)
	{
		if (DmLogoSegaReleaseCheck())
		{
			mtTaskClearTcb(tcb);
			SyChangeNextEvt();
		}
	}

	public static bool mppSountInitializationDelayExpired()
	{
		return true;
	}

	private void dmLogoSegaStartWaitFunc(DMS_LOGO_SEGA_WORK logo_work)
	{
		bool flag = true;
		logo_work.timer++;
		if (!mppSountInitializationDelayExpired())
		{
			flag = false;
		}
		if (logo_work.timer >= 0 && flag)
		{
			IzFadeExit();
			logo_work.timer = 4;
			logo_work.func = dmLogoSegaRunLeftFunc;
			dmLogoSegaPlayerInitSeqRunLeft(logo_work.ply_obj);
			logo_work.flag |= 2u;
			logo_work.efct_obj = dmLogoSegaCreateDashEffect(logo_work.ply_obj, 0);
		}
	}

	private void dmLogoSegaRunLeftFunc(DMS_LOGO_SEGA_WORK logo_work)
	{
		logo_work.timer++;
		if (logo_work.timer > 10)
		{
			logo_work.timer = 0;
			logo_work.func = dmLogoSegaRunRightWaitFunc;
			logo_work.efct_obj.flag |= 8u;
			logo_work.efct_obj = null;
		}
	}

	private void dmLogoSegaRunRightWaitFunc(DMS_LOGO_SEGA_WORK logo_work)
	{
		logo_work.timer++;
		if (logo_work.timer > 25)
		{
			logo_work.timer = 0;
			logo_work.func = dmLogoSegaRunRightFunc;
			dmLogoSegaPlayerInitSeqRunRight(logo_work.ply_obj);
			logo_work.efct_obj = dmLogoSegaCreateDashEffect(logo_work.ply_obj, 1);
		}
	}

	private void dmLogoSegaRunRightFunc(DMS_LOGO_SEGA_WORK logo_work)
	{
		logo_work.timer++;
		if (logo_work.timer > 10)
		{
			logo_work.timer = 0;
			logo_work.func = dmLogoSegaDispWaitFunc;
			GsSoundPlaySe("Sega_Logo", logo_work.h_se);
			if (GsSystemBgmIsPlay())
			{
				logo_work.h_se.snd_ctrl_param.volume = 0f;
			}
		}
	}

	private void dmLogoSegaDispWaitFunc(DMS_LOGO_SEGA_WORK logo_work)
	{
		logo_work.timer++;
		if (logo_work.timer >= 180)
		{
			logo_work.func = dmLogoSegaFadeOutWaitFunc;
			IzFadeInitEasy(0u, 3u, 60f, true);
		}
	}

	private void dmLogoSegaFadeOutWaitFunc(DMS_LOGO_SEGA_WORK logo_work)
	{
		if (IzFadeIsEnd())
		{
			logo_work.flag |= 1u;
		}
	}

