	private OBS_OBJECT_WORK dmLogoSegaCreateDashEffect(OBS_OBJECT_WORK parent_obj, int type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = OBM_OBJECT_TASK_DETAIL_INIT(12288, 0, 0, 0, () => new DMS_LOGO_SEGA_OBJ_ES_WORK(), "DM_LSEGA_EFCT");
		DMS_LOGO_SEGA_OBJ_ES_WORK dMS_LOGO_SEGA_OBJ_ES_WORK = (DMS_LOGO_SEGA_OBJ_ES_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.obj_type = 2;
		oBS_OBJECT_WORK.ppOut = ObjDrawActionSummary;
		oBS_OBJECT_WORK.ppOutSub = null;
		oBS_OBJECT_WORK.ppIn = null;
		oBS_OBJECT_WORK.ppMove = null;
		oBS_OBJECT_WORK.ppActCall = null;
		oBS_OBJECT_WORK.ppRec = null;
		oBS_OBJECT_WORK.ppLast = null;
		oBS_OBJECT_WORK.ppFunc = dmLogoSegaEffectMain;
		oBS_OBJECT_WORK.parent_obj = parent_obj;
		oBS_OBJECT_WORK.pos.Assign(parent_obj.pos);
		int index = ((type != 1) ? 52 : 53);
		ObjObjectAction3dESEffectLoad(oBS_OBJECT_WORK, dMS_LOGO_SEGA_OBJ_ES_WORK.obj_3des, null, null, index, dm_logo_sega_data[3], 0, 0);
		dMS_LOGO_SEGA_OBJ_ES_WORK.obj_3des.command_state = 0u;
		ObjDataSet(dMS_LOGO_SEGA_OBJ_ES_WORK.data_work_texamb, amBindGet(dm_logo_sega_data[3], 97));
		dMS_LOGO_SEGA_OBJ_ES_WORK.data_work_texamb.num |= 32768;
		ObjDataSet(dMS_LOGO_SEGA_OBJ_ES_WORK.data_work_texlist, dm_logo_sega_aos_tex[1].texlist);
		dMS_LOGO_SEGA_OBJ_ES_WORK.data_work_texlist.num |= 32768;
		ObjObjectAction3dESTextureLoad(oBS_OBJECT_WORK, dMS_LOGO_SEGA_OBJ_ES_WORK.obj_3des, dMS_LOGO_SEGA_OBJ_ES_WORK.data_work_texamb, null, 0, null, false);
		ObjObjectAction3dESTextureSetByDwork(oBS_OBJECT_WORK, dMS_LOGO_SEGA_OBJ_ES_WORK.data_work_texlist);
		ObjDataSet(dMS_LOGO_SEGA_OBJ_ES_WORK.data_work_model, amBindGet(dm_logo_sega_data[3], dm_logo_sega_efct_mdl_id_tbl[type]));
		dMS_LOGO_SEGA_OBJ_ES_WORK.data_work_texlist.num |= 32768;
		ObjObjectAction3dESModelLoad(oBS_OBJECT_WORK, dMS_LOGO_SEGA_OBJ_ES_WORK.obj_3des, dMS_LOGO_SEGA_OBJ_ES_WORK.data_work_model, null, 0, null, 0u, false);
		ObjObjectAction3dESModelSetByDwork(oBS_OBJECT_WORK, dm_logo_sega_efct_mdl_data_work[type]);
		dMS_LOGO_SEGA_OBJ_ES_WORK.obj_3des.disp_rot.x = 0;
		dMS_LOGO_SEGA_OBJ_ES_WORK.obj_3des.disp_rot.y = 0;
		dMS_LOGO_SEGA_OBJ_ES_WORK.obj_3des.disp_rot.z = 0;
		oBS_OBJECT_WORK.scale.x = FX_Mul(parent_obj.scale.x, g_obj.draw_scale.x);
		oBS_OBJECT_WORK.scale.y = FX_Mul(parent_obj.scale.y, g_obj.draw_scale.y);
		oBS_OBJECT_WORK.scale.z = FX_Mul(parent_obj.scale.z, g_obj.draw_scale.z);
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		dMS_LOGO_SEGA_OBJ_ES_WORK.obj_3des.flag |= 8u;
		return oBS_OBJECT_WORK;
	}

	private void dmLogoSegaEffectMain(OBS_OBJECT_WORK obj_work)
	{
		OBS_OBJECT_WORK parent_obj = obj_work.parent_obj;
		if (AoSysIsShowPlatformUI())
		{
			obj_work.disp_flag |= 4096u;
			return;
		}
		obj_work.disp_flag &= 4294963199u;
		obj_work.pos.Assign(parent_obj.pos);
		if ((obj_work.parent_obj.disp_flag & 1) != 0)
		{
			obj_work.pos.x -= -81920;
		}
		else
		{
			obj_work.pos.x += -81920;
		}
		obj_work.pos.y += 409600;
		obj_work.pos.z += 409600;
		obj_work.disp_flag &= 4294967294u;
		obj_work.disp_flag |= parent_obj.disp_flag & 1;
	}

