		aMS_TRAIL_PARAM.endColor.b = 1f;
		aMS_TRAIL_PARAM.endColor.a = 0f;
		aMS_TRAIL_PARAM.startSize = 88f;
		aMS_TRAIL_PARAM.endSize = 88f;
		aMS_TRAIL_PARAM.life = 35f;
		aMS_TRAIL_PARAM.vanish_time = 10f;
