	private void dmLogoSegaDataBuildMain(MTS_TASK_TCB tcb)
	{
		bool flag = true;
		if (!GmGameDBuildCheckBuildModel())
		{
			flag = false;
		}
		ArrayPointer<AOS_TEXTURE> arrayPointer = dm_logo_sega_aos_tex;
		int num = 0;
		while (num < 2)
		{
			if (!AoTexIsLoaded(arrayPointer))
			{
				flag = false;
			}
			num++;
			++arrayPointer;
		}
		for (num = 0; num < 2; num++)
		{
			if (dm_logo_sega_efct_mdl_state[num] != -1 && !amDrawIsRegistComplete(dm_logo_sega_efct_mdl_state[num]))
			{
				flag = false;
				dm_logo_sega_efct_mdl_state[num] = -1;
			}
		}
		if (flag)
		{
			mtTaskClearTcb(tcb);
			dm_logo_sega_build_state = true;
		}
	}

	private void dmLogoSegaDataBuildDest(MTS_TASK_TCB tcb)
	{
		dm_logo_sega_build_tcb = null;
	}

	private void dmLogoSegaDataFlushMain(MTS_TASK_TCB tcb)
	{
		bool flag = true;
		if (!GmGameDBuildCheckFlushModel())
		{
			flag = false;
		}
		ArrayPointer<AOS_TEXTURE> arrayPointer = dm_logo_sega_aos_tex;
		int num = 0;
		while (num < 2)
		{
			if (!AoTexIsReleased(arrayPointer))
			{
				flag = false;
			}
			num++;
			++arrayPointer;
		}
		for (num = 0; num < 2; num++)
		{
			if (dm_logo_sega_efct_mdl_state[num] != -1)
			{
				if (ObjAction3dESModelReleaseDworkCheck(dm_logo_sega_efct_mdl_data_work[num], dm_logo_sega_efct_mdl_state[num]))
				{
					dm_logo_sega_efct_mdl_state[num] = -1;
				}
				else
				{
					flag = false;
				}
			}
		}
		if (flag)
		{
			dm_logo_sega_aos_tex = null;
			dm_logo_sega_obj_3d_list = null;
			mtTaskClearTcb(tcb);
			dm_logo_sega_build_state = false;
		}
	}

	private void dmLogoSegaDataFlushDest(MTS_TASK_TCB tcb)
	{
		dm_logo_sega_flush_tcb = null;
	}

	private void dmLogoSegaLoadWait(MTS_TASK_TCB tcb)
	{
		if (DmLogoSegaLoadCheck())
		{
			DmLogoSegaBuild();
			mtTaskChangeTcbProcedure(tcb, dmLogoSegaBuildWait);
		}
	}

	private void dmLogoSegaBuildWait(MTS_TASK_TCB tcb)
	{
		if (DmLogoSegaBuildCheck())
		{
			mtTaskClearTcb(tcb);
			dmLogoSegaStart();
		}
	}

