	private static void AoStorageSaveStart(byte[] data, uint size, bool is_first, bool is_new)
	{
		AOS_STORAGE aOS_STORAGE = aoStorageGetGlobal();
		if (aOS_STORAGE.state != 0)
		{
			aoStorageSetError(5);
			return;
		}
		aOS_STORAGE.state = 1;
		aOS_STORAGE.save_success = false;
		aOS_STORAGE.save_buf = data;
		aOS_STORAGE.save_size = size;
		aoStorageSaveThread();
		aOS_STORAGE.tcb = amTaskMake(aoStorageSaveTaskProcedure, null, 0u, 0u, 0u, "aoStorage::Save");
		amTaskStart(aOS_STORAGE.tcb);
	}

