	{
		return true;
	}

	private static bool AoStorageSaveIsFinished()
	{
		AOS_STORAGE aOS_STORAGE = aoStorageGetGlobal();
		if (aOS_STORAGE.state == 1)
		{
			return false;
		}
		return true;
	}

	private static bool AoStorageSaveIsSuccessed()
	{
		return aoStorageGetGlobal().save_success;
