	private static void AoStorageLoadStart(byte[] data)
	{
		uint load_size = (uint)data.Length;
		AOS_STORAGE aOS_STORAGE = aoStorageGetGlobal();
		if (aOS_STORAGE.state != 0)
		{
			aoStorageSetError(5);
			return;
		}
		aOS_STORAGE.state = 2;
		aOS_STORAGE.load_success = false;
		aOS_STORAGE.load_buf = data;
		aOS_STORAGE.load_size = load_size;
		aoStorageLoadThread();
		aOS_STORAGE.tcb = amTaskMake(aoStorageLoadTaskProcedure, null, 0u, 0u, 0u, "aoStorage::Load");
		amTaskStart(aOS_STORAGE.tcb);
	}

