	private static void AoStorageDeleteStart()
	{
		AOS_STORAGE aOS_STORAGE = aoStorageGetGlobal();
		if (aOS_STORAGE.state != 0)
		{
			aoStorageSetError(5);
			return;
		}
		AoStorageClearError();
		string text = aoStorageAllocSaveFilePath();
		try
		{
			if (!store.FileExists(text))
			{
				aOS_STORAGE.del_success = false;
			}
			else
			{
				store.DeleteFile(text);
				aOS_STORAGE.del_success = true;
			}
		}
		catch (Exception)
		{
			aOS_STORAGE.del_success = false;
		}
		aoStorageFreeSaveFilePath(text);
		aOS_STORAGE.state = 0;
	}

	private static bool AoStorageDeleteIsFinished()
	{
		AOS_STORAGE aOS_STORAGE = aoStorageGetGlobal();
		if (aOS_STORAGE.state == 3)
		{
			return false;
		}
		return true;
	}

	private static bool AoStorageDeleteIsSuccessed()
	{
		return aoStorageGetGlobal().del_success;
	}

