	private static uint AoStorageSaveMm(string path, byte[] data, int size)
	{
		try
		{
			using (IsolatedStorageFileStream isolatedStorageFileStream = store.OpenFile(path, FileMode.OpenOrCreate))
			{
				isolatedStorageFileStream.Write(data, 0, size);
			}
			return 0u;
		}
		catch (Exception)
		{
		}
		return 1u;
	}

	private static void aoStorageSaveThread()
	{
		AOS_STORAGE aOS_STORAGE = aoStorageGetGlobal();
		string path = aoStorageAllocSaveFilePath();
		uint num = AoStorageSaveMm(path, aOS_STORAGE.save_buf, (int)aOS_STORAGE.save_size);
		aoStorageFreeSaveFilePath(path);
		if (num == 0)
		{
			aOS_STORAGE.save_success = true;
		}
		else
		{
			aoStorageSetError(2);
		}
	}

	private static void aoStorageSaveTaskProcedure(AMS_TCB tcb)
	{
		AOS_STORAGE aOS_STORAGE = aoStorageGetGlobal();
		amTaskDelete(tcb);
		aOS_STORAGE.save_buf = null;
		aOS_STORAGE.save_size = 0u;
		aOS_STORAGE.state = 0;
		aOS_STORAGE.tcb = null;
	}

	private static uint AoStorageLoadMm(string path, byte[] data, uint size)
	{
		try
		{
			if (store.FileExists(path))
			{
				using (IsolatedStorageFileStream isolatedStorageFileStream = store.OpenFile(path, FileMode.Open))
				{
					byte[] array = new byte[32768];
					int length = 0;
					using (MemoryStream memoryStream = new MemoryStream())
					{
						while (true)
						{
							int num = isolatedStorageFileStream.Read(array, 0, array.Length);
							if (num <= 0)
							{
								break;
							}
							length = num;
							memoryStream.Write(array, 0, num);
						}
						Array.Copy(memoryStream.ToArray(), data, length);
					}
				}
				return 0u;
			}
			return 1u;
		}
		catch (Exception)
		{
		}
		return 1u;
	}

	private static void aoStorageLoadThread()
	{
		AOS_STORAGE aOS_STORAGE = aoStorageGetGlobal();
		string path = aoStorageAllocSaveFilePath();
		uint num = AoStorageLoadMm(path, aOS_STORAGE.load_buf, aOS_STORAGE.load_size);
		aoStorageFreeSaveFilePath(path);
		if (num == 0)
		{
			aOS_STORAGE.load_success = true;
		}
		else
		{
			aoStorageSetError(1);
		}
	}

