	private void nnInitCircumsphere()
	{
		ArrayPointer<NNS_VECTOR> arrayPointer = new ArrayPointer<NNS_VECTOR>(nngCircumPoint);
		float num = 0f;
		float num2 = 0f;
		float num3 = 0f;
		float s;
		float c;
		float s2;
		float c2;
		for (int i = 0; i < 2; i++)
		{
			nnSinCos(NNM_DEGtoA32((int)((float)i * 360f / 4f)), out s, out c);
			nnSinCos(0, out s2, out c2);
			for (int j = 0; j < 20; j++)
			{
				(~arrayPointer).x = c2 * c + num;
				(~arrayPointer).y = s2 + num2;
				(~arrayPointer).z = c2 * s + num3;
				++arrayPointer;
				nnSinCos(NNM_DEGtoA32((int)((float)(j + 1) * 360f / 20f)), out s2, out c2);
				(~arrayPointer).x = c2 * c + num;
				(~arrayPointer).y = s2 + num2;
				(~arrayPointer).z = c2 * s + num3;
				++arrayPointer;
			}
		}
		for (int i = 0; i < 1; i++)
		{
			nnSinCos(NNM_DEGtoA32(180), out s, out c);
			nnSinCos(0, out s2, out c2);
			for (int j = 0; j < 20; j++)
			{
				(~arrayPointer).x = c * c2 + num;
				(~arrayPointer).y = s + num2;
				(~arrayPointer).z = c * s2 + num3;
				++arrayPointer;
				nnSinCos(NNM_DEGtoA32((int)((float)(j + 1) * 360f / 20f)), out s2, out c2);
				(~arrayPointer).x = c * c2 + num;
				(~arrayPointer).y = s + num2;
				(~arrayPointer).z = c * s2 + num3;
				++arrayPointer;
			}
		}
	}

