	private void nnCalcTRS(NNS_TRS trs, NNS_OBJECT obj, int nodeidx)
	{
		uint fType = obj.pNodeList[nodeidx].fType;
		trs.Translation.x = obj.pNodeList[nodeidx].Translation.x;
		trs.Translation.y = obj.pNodeList[nodeidx].Translation.y;
		trs.Translation.z = obj.pNodeList[nodeidx].Translation.z;
		if ((fType & 2) != 0)
		{
			trs.Rotation.x = 0f;
			trs.Rotation.y = 0f;
			trs.Rotation.z = 0f;
			trs.Rotation.w = 1f;
		}
		else
		{
			int x = obj.pNodeList[nodeidx].Rotation.x;
			int ry;
			int rz;
			if ((fType & 0x1C000) != 0)
			{
				ry = 0;
				rz = 0;
			}
			else
			{
				ry = obj.pNodeList[nodeidx].Rotation.y;
				rz = obj.pNodeList[nodeidx].Rotation.z;
			}
			switch (fType & 0xF00)
			{
			case 256u:
				nnMakeRotateXZYQuaternion(out trs.Rotation, x, ry, rz);
				break;
			case 1024u:
				nnMakeRotateZXYQuaternion(out trs.Rotation, x, ry, rz);
				break;
			default:
				nnMakeRotateXYZQuaternion(out trs.Rotation, x, ry, rz);
				break;
			}
		}
		trs.Scaling.x = obj.pNodeList[nodeidx].Scaling.x;
		trs.Scaling.y = obj.pNodeList[nodeidx].Scaling.y;
		trs.Scaling.z = obj.pNodeList[nodeidx].Scaling.z;
	}

	public static void nnCalcTRSList(NNS_TRS[] trslist, int offset, NNS_OBJECT obj)
	{
		for (int i = 0; i < obj.nNode; i++)
		{
			uint fType = obj.pNodeList[i].fType;
			uint num = fType & 0xF00;
			int num2 = i + offset;
			trslist[num2].Translation.x = obj.pNodeList[i].Translation.x;
			trslist[num2].Translation.y = obj.pNodeList[i].Translation.y;
			trslist[num2].Translation.z = obj.pNodeList[i].Translation.z;
			if ((fType & 2) != 0)
			{
				trslist[num2].Rotation.x = 0f;
				trslist[num2].Rotation.y = 0f;
				trslist[num2].Rotation.z = 0f;
				trslist[num2].Rotation.w = 1f;
			}
			else
			{
				int x = obj.pNodeList[i].Rotation.x;
				int ry;
				int rz;
				if ((fType & 0x1C000) != 0)
				{
					ry = 0;
					rz = 0;
				}
				else
				{
					ry = obj.pNodeList[i].Rotation.y;
					rz = obj.pNodeList[i].Rotation.z;
				}
				switch (num)
				{
				case 256u:
					nnMakeRotateXZYQuaternion(out trslist[num2].Rotation, x, ry, rz);
					break;
				case 1024u:
					nnMakeRotateZXYQuaternion(out trslist[num2].Rotation, x, ry, rz);
					break;
				default:
					nnMakeRotateXYZQuaternion(out trslist[num2].Rotation, x, ry, rz);
					break;
				}
			}
			trslist[num2].Scaling.x = obj.pNodeList[i].Scaling.x;
			trslist[num2].Scaling.y = obj.pNodeList[i].Scaling.y;
			trslist[num2].Scaling.z = obj.pNodeList[i].Scaling.z;
		}
	}

	private static int nnCalcNodeMotionTRSCore(out int tflag, out int rflag, out int sflag, NNS_VECTOR tv, NNS_VECTOR sv, ref NNS_QUATERNION rq, ref NNS_QUATERNION invrq, bool need_invrq, NNS_NODE pNode, int NodeIdx, NNS_MOTION pMot, int SubMotIdx, float frame)
	{
		NNS_ROTATE_A32 rv = default(NNS_ROTATE_A32);
		uint fType = pNode.fType;
		uint num = fType & 0xF00;
		tv.Assign(pNode.Translation);
		sv.Assign(pNode.Scaling);
		if ((fType & 2) != 0)
		{
			rv.x = (rv.y = (rv.z = 0));
			rq.x = 0f;
			rq.y = 0f;
			rq.z = 0f;
			rq.w = 1f;
			if (need_invrq)
			{
				invrq.x = 0f;
				invrq.y = 0f;
				invrq.z = 0f;
				invrq.w = 1f;
			}
		}
		else
		{
			rv.x = pNode.Rotation.x;
			if ((fType & 0x1C000) != 0)
			{
				rv.y = 0;
				rv.z = 0;
			}
			else
			{
				rv.y = pNode.Rotation.y;
				rv.z = pNode.Rotation.z;
			}
			switch (num)
			{
			case 256u:
				nnMakeRotateXZYQuaternion(out rq, rv.x, rv.y, rv.z);
				break;
			case 1024u:
				nnMakeRotateZXYQuaternion(out rq, rv.x, rv.y, rv.z);
				break;
			default:
				nnMakeRotateXYZQuaternion(out rq, rv.x, rv.y, rv.z);
				break;
			}
			if (need_invrq)
			{
				nnInvertQuaternion(ref invrq, ref rq);
			}
		}
		tflag = 0;
		rflag = 0;
		sflag = 0;
		for (int i = SubMotIdx; i < pMot.nSubmotion; i++)
		{
			NNS_SUBMOTION nNS_SUBMOTION = pMot.pSubmotion[i];
			if (NodeIdx < nNS_SUBMOTION.Id)
			{
				SubMotIdx = i;
				break;
			}
			float dstframe;
			if (nNS_SUBMOTION.Id == NodeIdx && nNS_SUBMOTION.fType != 0 && nNS_SUBMOTION.StartFrame <= frame && frame <= nNS_SUBMOTION.EndFrame && nnCalcMotionFrame(out dstframe, nNS_SUBMOTION.fIPType, nNS_SUBMOTION.StartKeyFrame, nNS_SUBMOTION.EndKeyFrame, frame) != 0)
			{
				if ((nNS_SUBMOTION.fType & 0x7800) != 0)
				{
					rflag |= nnCalcMotionRotate(nNS_SUBMOTION, dstframe, ref rv, rq, num);
				}
				else if ((nNS_SUBMOTION.fType & 0x700) != 0)
				{
					tflag |= nnCalcMotionTranslate(nNS_SUBMOTION, dstframe, tv);
				}
				else if ((nNS_SUBMOTION.fType & 0x38000) != 0)
				{
					sflag |= nnCalcMotionScale(nNS_SUBMOTION, dstframe, sv);
				}
				else if ((nNS_SUBMOTION.fType & 0xC0000) != 0)
				{
					nnCallbackMotionUserData(nncalctrsmotion.nnsObj, pMot, i, NodeIdx, dstframe, frame);
				}
			}
		}
		if (rflag == 1)
		{
			switch (num)
			{
			case 256u:
				nnMakeRotateXZYQuaternion(out rq, rv.x, rv.y, rv.z);
				break;
			case 1024u:
				nnMakeRotateZXYQuaternion(out rq, rv.x, rv.y, rv.z);
				break;
			default:
				nnMakeRotateXYZQuaternion(out rq, rv.x, rv.y, rv.z);
				break;
			}
		}
		return SubMotIdx;
	}

	private void nnCalcTRSMotion(NNS_TRS trs, NNS_OBJECT obj, int nodeidx, NNS_MOTION mot, float frame)
	{
		NNS_QUATERNION rq = default(NNS_QUATERNION);
		if ((mot.fType & 1) != 0)
		{
			nncalctrsmotion.nnsObj = obj;
			if (nnCalcMotionFrame(out frame, mot.fType, mot.StartFrame, mot.EndFrame, frame) == 0)
			{
				nnCalcTRS(trs, obj, nodeidx);
				return;
			}
			NNS_NODE pNode = obj.pNodeList[nodeidx];
			NNS_VECTOR nNS_VECTOR = nnCalcTRSMotion_tv;
			nNS_VECTOR.Clear();
			NNS_VECTOR nNS_VECTOR2 = nnCalcTRSMotion_sv;
			nNS_VECTOR2.Clear();
			NNS_QUATERNION invrq = default(NNS_QUATERNION);
			int tflag;
			int rflag;
			int sflag;
			nnCalcNodeMotionTRSCore(out tflag, out rflag, out sflag, nNS_VECTOR, nNS_VECTOR2, ref rq, ref invrq, false, pNode, nodeidx, mot, 0, frame);
			trs.Translation.x = nNS_VECTOR.x;
			trs.Translation.y = nNS_VECTOR.y;
			trs.Translation.z = nNS_VECTOR.z;
			trs.Rotation = rq;
			trs.Scaling.x = nNS_VECTOR2.x;
			trs.Scaling.y = nNS_VECTOR2.y;
			trs.Scaling.z = nNS_VECTOR2.z;
		}
	}

	public static void nnCalcTRSListMotion(NNS_TRS[] trslist, int offset, NNS_OBJECT obj, NNS_MOTION mot, float frame)
	{
		NNS_QUATERNION rq = default(NNS_QUATERNION);
		if ((mot.fType & 1) == 0)
		{
			return;
		}
		if (nnCalcMotionFrame(out frame, mot.fType, mot.StartFrame, mot.EndFrame, frame) == 0)
		{
			nnCalcTRSList(trslist, offset, obj);
			return;
		}
		nncalctrsmotion.nnsObj = obj;
		NNS_QUATERNION invrq = default(NNS_QUATERNION);
		NNS_VECTOR nNS_VECTOR = nnCalcTRSMotion_tv;
		nNS_VECTOR.Clear();
		NNS_VECTOR nNS_VECTOR2 = nnCalcTRSMotion_sv;
		nNS_VECTOR2.Clear();
		int subMotIdx = 0;
		for (int i = 0; i < obj.nNode; i++)
		{
			NNS_NODE pNode = obj.pNodeList[i];
			int tflag;
			int rflag;
			int sflag;
			subMotIdx = nnCalcNodeMotionTRSCore(out tflag, out rflag, out sflag, nNS_VECTOR, nNS_VECTOR2, ref rq, ref invrq, false, pNode, i, mot, subMotIdx, frame);
			int num = i + offset;
			trslist[num].Translation.x = nNS_VECTOR.x;
			trslist[num].Translation.y = nNS_VECTOR.y;
			trslist[num].Translation.z = nNS_VECTOR.z;
			trslist[num].Rotation = rq;
			trslist[num].Scaling.x = nNS_VECTOR2.x;
			trslist[num].Scaling.y = nNS_VECTOR2.y;
			trslist[num].Scaling.z = nNS_VECTOR2.z;
		}
	}

	private static void nnCalcMatrixPaletteTRSListNode(int nodeIdx)
	{
		NNS_NODE nNS_NODE;
		do
		{
			nNS_NODE = nncalctrsmotion.nnsNodeList[nodeIdx];
			NNS_TRS nNS_TRS = nncalctrsmotion.nnsTrsList[nodeIdx];
			NNS_MATRIX nNS_MATRIX;
			if ((nNS_NODE.fType & 0x8000000) != 0)
			{
				if ((nNS_NODE.fType & 0x6000000) != 0)
				{
					nnPushMatrix(nncalctrsmotion.nnsMstk, null);
					nNS_MATRIX = nnGetCurrentMatrix(nncalctrsmotion.nnsMstk);
					nnTranslateMatrix(nNS_MATRIX, nNS_MATRIX, nNS_TRS.Translation.x, nNS_TRS.Translation.y, nNS_TRS.Translation.z);
					if ((nNS_NODE.fType & 0x1000) != 0)
					{
						nnCopyMatrix33(nNS_MATRIX, nncalctrsmotion.nnsBaseMtx);
					}
					else if ((nNS_NODE.fType & 0x1C0000) != 0)
					{
						if ((nNS_NODE.fType & 0x40000) != 0)
						{
							nnNormalizeColumn0(nNS_MATRIX);
						}
						if ((nNS_NODE.fType & 0x80000) != 0)
						{
							nnNormalizeColumn1(nNS_MATRIX);
						}
						if ((nNS_NODE.fType & 0x100000) != 0)
						{
							nnNormalizeColumn2(nNS_MATRIX);
						}
					}
					nnQuaternionMatrix(nNS_MATRIX, nNS_MATRIX, ref nNS_TRS.Rotation);
					nnScaleMatrix(nNS_MATRIX, nNS_MATRIX, nNS_TRS.Scaling.x, nNS_TRS.Scaling.y, nNS_TRS.Scaling.z);
					if ((nNS_NODE.fType & 0x2000000) != 0)
					{
						nnCalcMatrixPaletteTRSListNode1BoneXSIIK(nodeIdx);
					}
					else if ((nNS_NODE.fType & 0x4000000) != 0)
					{
						nnCalcMatrixPaletteTRSListNode2BoneXSIIK(nodeIdx);
					}
					nnPopMatrix(nncalctrsmotion.nnsMstk);
					nodeIdx = nNS_NODE.iSibling;
					continue;
				}
			}
			else
			{
				if ((nNS_NODE.fType & 0x4000) != 0)
				{
					nnPushMatrix(nncalctrsmotion.nnsMstk, null);
					nnCalcMatrixPaletteTRSListNode1BoneSIIK(nodeIdx);
					nnPopMatrix(nncalctrsmotion.nnsMstk);
					break;
				}
				if ((nNS_NODE.fType & 0x8000) != 0)
				{
					nnPushMatrix(nncalctrsmotion.nnsMstk, null);
					nnCalcMatrixPaletteTRSListNode2BoneSIIK(nodeIdx);
					nnPopMatrix(nncalctrsmotion.nnsMstk);
					break;
				}
			}
			nnPushMatrix(nncalctrsmotion.nnsMstk, null);
			nNS_MATRIX = nnGetCurrentMatrix(nncalctrsmotion.nnsMstk);
			nnTranslateMatrix(nNS_MATRIX, nNS_MATRIX, nNS_TRS.Translation.x, nNS_TRS.Translation.y, nNS_TRS.Translation.z);
			if ((nNS_NODE.fType & 0x1000) != 0)
			{
				nnCopyMatrix33(nNS_MATRIX, nncalctrsmotion.nnsBaseMtx);
			}
			else if ((nNS_NODE.fType & 0x1C0000) != 0)
			{
				if ((nNS_NODE.fType & 0x40000) != 0)
				{
					nnNormalizeColumn0(nNS_MATRIX);
				}
				if ((nNS_NODE.fType & 0x80000) != 0)
				{
					nnNormalizeColumn1(nNS_MATRIX);
				}
				if ((nNS_NODE.fType & 0x100000) != 0)
				{
					nnNormalizeColumn2(nNS_MATRIX);
				}
			}
			nnQuaternionMatrix(nNS_MATRIX, nNS_MATRIX, ref nNS_TRS.Rotation);
			nnScaleMatrix(nNS_MATRIX, nNS_MATRIX, nNS_TRS.Scaling.x, nNS_TRS.Scaling.y, nNS_TRS.Scaling.z);
			if (nNS_NODE.iMatrix != -1)
			{
				if ((nNS_NODE.fType & 8) != 0)
				{
					nnCopyMatrix(nncalctrsmotion.nnsMtxPal[nNS_NODE.iMatrix], nNS_MATRIX);
				}
				else
				{
					nnMultiplyMatrix(nncalctrsmotion.nnsMtxPal[nNS_NODE.iMatrix], nNS_MATRIX, nNS_NODE.InvInitMtx);
				}
			}
			if (nncalctrsmotion.nnsNodeStatList != null)
			{
				if (nodeIdx == 0 && nncalctrsmotion.nnsNSFlag != 0)
				{
					nncalctrsmotion.nnsRootScale = nnEstimateMatrixScaling(nNS_MATRIX);
				}
				nnCalcClipSetNodeStatus(nncalctrsmotion.nnsNodeStatList, nncalctrsmotion.nnsNodeList, nodeIdx, nNS_MATRIX, nncalctrsmotion.nnsRootScale, nncalctrsmotion.nnsNSFlag);
			}
			if (nNS_NODE.iChild != -1)
			{
				nnCalcMatrixPaletteTRSListNode(nNS_NODE.iChild);
			}
			nnPopMatrix(nncalctrsmotion.nnsMstk);
			nodeIdx = nNS_NODE.iSibling;
		}
		while (nNS_NODE.iSibling != -1);
	}

	private static void nnCalcMatrixPaletteTRSList(NNS_MATRIX[] mtxpal, uint[] nodestatlist, NNS_OBJECT obj, NNS_TRS[] trslist, ref SNNS_MATRIX basemtx, NNS_MATRIXSTACK mstk, uint flag)
	{
		nncalctrsmotion.nnsBaseMtx.Assign(ref basemtx);
		nnSetCurrentMatrix(mstk, nncalctrsmotion.nnsBaseMtx);
		nncalctrsmotion.nnsMtxPal = mtxpal;
		nncalctrsmotion.nnsNodeStatList = nodestatlist;
		nncalctrsmotion.nnsNSFlag = flag;
		nncalctrsmotion.nnsTrsList = trslist;
		nncalctrsmotion.nnsNodeList = obj.pNodeList;
		nncalctrsmotion.nnsMstk = mstk;
		nnCalcMatrixPaletteTRSListNode(0);
	}

	private static void nnCalcMatrixPaletteTRSList(NNS_MATRIX[] mtxpal, uint[] nodestatlist, NNS_OBJECT obj, NNS_TRS[] trslist, NNS_MATRIX basemtx, NNS_MATRIXSTACK mstk, uint flag)
	{
		if (basemtx != null)
		{
			nncalctrsmotion.nnsBaseMtx.Assign(basemtx);
		}
		else
		{
			nncalctrsmotion.nnsBaseMtx.Assign(nngUnitMatrix);
		}
		nnSetCurrentMatrix(mstk, nncalctrsmotion.nnsBaseMtx);
		nncalctrsmotion.nnsMtxPal = mtxpal;
		nncalctrsmotion.nnsNodeStatList = nodestatlist;
		nncalctrsmotion.nnsNSFlag = flag;
		nncalctrsmotion.nnsTrsList = trslist;
		nncalctrsmotion.nnsNodeList = obj.pNodeList;
		nncalctrsmotion.nnsMstk = mstk;
		nnCalcMatrixPaletteTRSListNode(0);
	}

	public static void nnLinkMotion(ArrayPointer<NNS_TRS> dstpose, ArrayPointer<NNS_TRS> pose0, ArrayPointer<NNS_TRS> pose1, int nnode, float ratio)
	{
		for (int i = 0; i < nnode; i++)
		{
			NNS_TRS nNS_TRS = dstpose.array[dstpose.offset + i];
			NNS_TRS nNS_TRS2 = pose0.array[pose0.offset + i];
			NNS_TRS nNS_TRS3 = pose1.array[pose1.offset + i];
			nNS_TRS.Translation.x = nNS_TRS2.Translation.x + (nNS_TRS3.Translation.x - nNS_TRS2.Translation.x) * ratio;
			nNS_TRS.Translation.y = nNS_TRS2.Translation.y + (nNS_TRS3.Translation.y - nNS_TRS2.Translation.y) * ratio;
			nNS_TRS.Translation.z = nNS_TRS2.Translation.z + (nNS_TRS3.Translation.z - nNS_TRS2.Translation.z) * ratio;
			nNS_TRS.Scaling.x = nNS_TRS2.Scaling.x + (nNS_TRS3.Scaling.x - nNS_TRS2.Scaling.x) * ratio;
			nNS_TRS.Scaling.y = nNS_TRS2.Scaling.y + (nNS_TRS3.Scaling.y - nNS_TRS2.Scaling.y) * ratio;
			nNS_TRS.Scaling.z = nNS_TRS2.Scaling.z + (nNS_TRS3.Scaling.z - nNS_TRS2.Scaling.z) * ratio;
			nnSlerpQuaternion(out nNS_TRS.Rotation, ref nNS_TRS2.Rotation, ref nNS_TRS3.Rotation, ratio);
		}
	}

	private void nnBlendMotion(ArrayPointer<NNS_TRS> _dstpose, ArrayPointer<NNS_TRS> _srcpose, NNS_OBJECT obj, NNS_MOTION mot, float frame, NNE_MOTIONBLEND blendmode)
	{
		if ((mot.fType & 1) == 0)
		{
			return;
		}
		NNS_QUATERNION rq = default(NNS_QUATERNION);
		NNS_QUATERNION invrq = default(NNS_QUATERNION);
		ArrayPointer<NNS_TRS> arrayPointer = _dstpose.Clone();
		ArrayPointer<NNS_TRS> arrayPointer2 = _srcpose.Clone();
		if (nnCalcMotionFrame(out frame, mot.fType, mot.StartFrame, mot.EndFrame, frame) == 0)
		{
			if (~arrayPointer != ~arrayPointer2)
			{
				for (int i = 0; i < obj.nNode; i++)
				{
					arrayPointer[i].Assign(arrayPointer2);
				}
			}
			return;
		}
		int subMotIdx = 0;
		ArrayPointer<NNS_NODE> arrayPointer3 = obj.pNodeList;
		NNS_VECTOR nNS_VECTOR = nnCalcTRSMotion_tv;
		nNS_VECTOR.Clear();
		NNS_VECTOR nNS_VECTOR2 = nnCalcTRSMotion_sv;
		nNS_VECTOR2.Clear();
		for (int j = 0; j < obj.nNode; j++)
		{
			int tflag;
			int rflag;
			int sflag;
			subMotIdx = nnCalcNodeMotionTRSCore(out tflag, out rflag, out sflag, nNS_VECTOR, nNS_VECTOR2, ref rq, ref invrq, true, arrayPointer3, j, mot, subMotIdx, frame);
			switch (blendmode)
			{
			case NNE_MOTIONBLEND.NNE_MOTIONBLEND_REPLACE_ALL:
				if (tflag != 0 || rflag != 0 || sflag != 0)
				{
					(~arrayPointer).Translation.x = nNS_VECTOR.x;
					(~arrayPointer).Translation.y = nNS_VECTOR.y;
					(~arrayPointer).Translation.z = nNS_VECTOR.z;
					(~arrayPointer).Rotation = rq;
					(~arrayPointer).Scaling.x = nNS_VECTOR2.x;
					(~arrayPointer).Scaling.y = nNS_VECTOR2.y;
					(~arrayPointer).Scaling.z = nNS_VECTOR2.z;
				}
				else
				{
					(~arrayPointer).Assign(~arrayPointer2);
				}
				break;
			case NNE_MOTIONBLEND.NNE_MOTIONBLEND_ADD_TRANSLATION:
				if (tflag != 0 || rflag != 0 || sflag != 0)
				{
					(~arrayPointer).Translation.x = (~arrayPointer2).Translation.x + nNS_VECTOR.x - (~arrayPointer3).Translation.x;
					(~arrayPointer).Translation.y = (~arrayPointer2).Translation.y + nNS_VECTOR.y - (~arrayPointer3).Translation.y;
					(~arrayPointer).Translation.z = (~arrayPointer2).Translation.z + nNS_VECTOR.z - (~arrayPointer3).Translation.z;
					(~arrayPointer).Rotation = rq;
					(~arrayPointer).Scaling.x = nNS_VECTOR2.x;
					(~arrayPointer).Scaling.y = nNS_VECTOR2.y;
					(~arrayPointer).Scaling.z = nNS_VECTOR2.z;
				}
				else
				{
					(~arrayPointer).Assign(~arrayPointer2);
				}
				break;
			case NNE_MOTIONBLEND.NNE_MOTIONBLEND_ADD_ALL:
				if (tflag != 0)
				{
					(~arrayPointer).Translation.x = (~arrayPointer2).Translation.x + nNS_VECTOR.x - (~arrayPointer3).Translation.x;
					(~arrayPointer).Translation.y = (~arrayPointer2).Translation.y + nNS_VECTOR.y - (~arrayPointer3).Translation.y;
					(~arrayPointer).Translation.z = (~arrayPointer2).Translation.z + nNS_VECTOR.z - (~arrayPointer3).Translation.z;
				}
				else
				{
					(~arrayPointer).Translation.x = (~arrayPointer2).Translation.x;
					(~arrayPointer).Translation.y = (~arrayPointer2).Translation.y;
					(~arrayPointer).Translation.z = (~arrayPointer2).Translation.z;
				}
				if (rflag != 0)
				{
					nnMultiplyQuaternion(ref (~arrayPointer).Rotation, ref (~arrayPointer2).Rotation, ref invrq);
					nnMultiplyQuaternion(ref (~arrayPointer).Rotation, ref (~arrayPointer).Rotation, ref rq);
				}
				else
				{
					(~arrayPointer).Rotation = (~arrayPointer2).Rotation;
				}
				if (sflag != 0)
				{
					(~arrayPointer).Scaling.x = (~arrayPointer2).Scaling.x * nNS_VECTOR2.x / (~arrayPointer3).Scaling.x;
					(~arrayPointer).Scaling.y = (~arrayPointer2).Scaling.y * nNS_VECTOR2.y / (~arrayPointer3).Scaling.y;
					(~arrayPointer).Scaling.z = (~arrayPointer2).Scaling.z * nNS_VECTOR2.z / (~arrayPointer3).Scaling.z;
				}
				else
				{
					(~arrayPointer).Scaling.x = (~arrayPointer2).Scaling.x;
					(~arrayPointer).Scaling.y = (~arrayPointer2).Scaling.y;
					(~arrayPointer).Scaling.z = (~arrayPointer2).Scaling.z;
				}
				break;
			}
			++arrayPointer3;
			++arrayPointer;
			++arrayPointer2;
		}
	}

	private void nnBlendMotionNode(NNS_TRS dsttrs, NNS_TRS srctrs, NNS_OBJECT obj, int inode, NNS_MOTION mot, float frame, NNE_MOTIONBLEND blendmode)
	{
		if ((mot.fType & 1) == 0)
		{
			return;
		}
		if (nnCalcMotionFrame(out frame, mot.fType, mot.StartFrame, mot.EndFrame, frame) == 0)
		{
			if (dsttrs != srctrs)
			{
				dsttrs.Assign(srctrs);
			}
			return;
		}
		NNS_QUATERNION rq = default(NNS_QUATERNION);
		NNS_QUATERNION invrq = default(NNS_QUATERNION);
		NNS_VECTOR nNS_VECTOR = nnCalcTRSMotion_tv;
		nNS_VECTOR.Clear();
		NNS_VECTOR nNS_VECTOR2 = nnCalcTRSMotion_sv;
		nNS_VECTOR2.Clear();
		NNS_NODE nNS_NODE = obj.pNodeList[inode];
		int tflag;
		int rflag;
		int sflag;
		nnCalcNodeMotionTRSCore(out tflag, out rflag, out sflag, nNS_VECTOR, nNS_VECTOR2, ref rq, ref invrq, true, nNS_NODE, inode, mot, 0, frame);
		switch (blendmode)
		{
		case NNE_MOTIONBLEND.NNE_MOTIONBLEND_REPLACE_ALL:
			if (tflag != 0 || rflag != 0 || sflag != 0)
			{
				dsttrs.Translation.x = nNS_VECTOR.x;
				dsttrs.Translation.y = nNS_VECTOR.y;
				dsttrs.Translation.z = nNS_VECTOR.z;
				dsttrs.Rotation = rq;
				dsttrs.Scaling.x = nNS_VECTOR2.x;
				dsttrs.Scaling.y = nNS_VECTOR2.y;
				dsttrs.Scaling.z = nNS_VECTOR2.z;
			}
			else
			{
				dsttrs.Assign(srctrs);
			}
			break;
		case NNE_MOTIONBLEND.NNE_MOTIONBLEND_ADD_TRANSLATION:
			if (tflag != 0 || rflag != 0 || sflag != 0)
			{
				dsttrs.Translation.x = srctrs.Translation.x + nNS_VECTOR.x - nNS_NODE.Translation.x;
				dsttrs.Translation.y = srctrs.Translation.y + nNS_VECTOR.y - nNS_NODE.Translation.y;
				dsttrs.Translation.z = srctrs.Translation.z + nNS_VECTOR.z - nNS_NODE.Translation.z;
				dsttrs.Rotation = rq;
				dsttrs.Scaling.x = nNS_VECTOR2.x;
				dsttrs.Scaling.y = nNS_VECTOR2.y;
				dsttrs.Scaling.z = nNS_VECTOR2.z;
			}
			else
			{
				dsttrs.Assign(srctrs);
			}
			break;
		case NNE_MOTIONBLEND.NNE_MOTIONBLEND_ADD_ALL:
			if (tflag != 0)
			{
				dsttrs.Translation.x = srctrs.Translation.x + nNS_VECTOR.x - nNS_NODE.Translation.x;
				dsttrs.Translation.y = srctrs.Translation.y + nNS_VECTOR.y - nNS_NODE.Translation.y;
				dsttrs.Translation.z = srctrs.Translation.z + nNS_VECTOR.z - nNS_NODE.Translation.z;
			}
			else
			{
				dsttrs.Translation.x = srctrs.Translation.x;
				dsttrs.Translation.y = srctrs.Translation.y;
				dsttrs.Translation.z = srctrs.Translation.z;
			}
			if (rflag != 0)
			{
				nnMultiplyQuaternion(ref dsttrs.Rotation, ref srctrs.Rotation, ref invrq);
				nnMultiplyQuaternion(ref dsttrs.Rotation, ref dsttrs.Rotation, ref rq);
			}
			else
			{
				dsttrs.Rotation = srctrs.Rotation;
			}
			if (sflag != 0)
			{
				dsttrs.Scaling.x = srctrs.Scaling.x * nNS_VECTOR2.x / nNS_NODE.Scaling.x;
				dsttrs.Scaling.y = srctrs.Scaling.y * nNS_VECTOR2.y / nNS_NODE.Scaling.y;
				dsttrs.Scaling.z = srctrs.Scaling.z * nNS_VECTOR2.z / nNS_NODE.Scaling.z;
			}
			else
			{
				dsttrs.Scaling.x = srctrs.Scaling.x;
				dsttrs.Scaling.y = srctrs.Scaling.y;
				dsttrs.Scaling.z = srctrs.Scaling.z;
			}
			break;
		}
	}

