	private void nnCalcMatrixPaletteLinkMotionNode(int nodeIdx)
	{
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR2 = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR3 = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR4 = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_QUATERNION rq = default(NNS_QUATERNION);
		NNS_QUATERNION rq2 = default(NNS_QUATERNION);
		NNS_TRS nNS_TRS = new NNS_TRS();
		NNS_NODE nNS_NODE;
		do
		{
			nNS_NODE = nncalctrsmotion.nnsNodeList[nodeIdx];
			NNS_QUATERNION invrq = default(NNS_QUATERNION);
			int tflag;
			int rflag;
			int sflag;
			nncalctrsmotion.nnsSubMotIdx0 = nnCalcNodeMotionTRSCore(out tflag, out rflag, out sflag, nNS_VECTOR, nNS_VECTOR2, ref rq, ref invrq, false, nNS_NODE, nodeIdx, nncalctrsmotion.nnsMot0, nncalctrsmotion.nnsSubMotIdx0, nncalctrsmotion.nnsFrame0);
			int tflag2;
			int rflag2;
			int sflag2;
			nncalctrsmotion.nnsSubMotIdx1 = nnCalcNodeMotionTRSCore(out tflag2, out rflag2, out sflag2, nNS_VECTOR3, nNS_VECTOR4, ref rq2, ref invrq, false, nNS_NODE, nodeIdx, nncalctrsmotion.nnsMot1, nncalctrsmotion.nnsSubMotIdx1, nncalctrsmotion.nnsFrame1);
			float num = 1f - nncalctrsmotion.nnsRatio;
			nnPushMatrix(nncalctrsmotion.nnsMstk, null);
			NNS_MATRIX nNS_MATRIX = nnGetCurrentMatrix(nncalctrsmotion.nnsMstk);
			if ((tflag | tflag2) != 0)
			{
				nNS_TRS.Translation.x = nNS_VECTOR.x * num + nNS_VECTOR3.x * nncalctrsmotion.nnsRatio;
				nNS_TRS.Translation.y = nNS_VECTOR.y * num + nNS_VECTOR3.y * nncalctrsmotion.nnsRatio;
				nNS_TRS.Translation.z = nNS_VECTOR.z * num + nNS_VECTOR3.z * nncalctrsmotion.nnsRatio;
				nnTranslateMatrixFast(nNS_MATRIX, nNS_TRS.Translation.x, nNS_TRS.Translation.y, nNS_TRS.Translation.z);
			}
			else
			{
				nnTranslateMatrixFast(nNS_MATRIX, nNS_VECTOR.x, nNS_VECTOR.y, nNS_VECTOR.z);
			}
			if ((nNS_NODE.fType & 0x1000) != 0)
			{
				nnCopyMatrix33(nNS_MATRIX, nncalctrsmotion.nnsBaseMtx);
			}
			else if ((nNS_NODE.fType & 0x1C0000) != 0)
			{
				if ((nNS_NODE.fType & 0x40000) != 0)
				{
					nnNormalizeColumn0(nNS_MATRIX);
				}
				if ((nNS_NODE.fType & 0x80000) != 0)
				{
					nnNormalizeColumn1(nNS_MATRIX);
				}
				if ((nNS_NODE.fType & 0x100000) != 0)
				{
					nnNormalizeColumn2(nNS_MATRIX);
				}
			}
			if ((rflag | rflag2) != 0)
			{
				nnSlerpQuaternion(out nNS_TRS.Rotation, ref rq, ref rq2, nncalctrsmotion.nnsRatio);
			}
			else
			{
				nNS_TRS.Rotation = rq;
			}
			nnQuaternionMatrix(nNS_MATRIX, nNS_MATRIX, ref nNS_TRS.Rotation);
			if ((sflag | sflag2) != 0)
			{
				nNS_TRS.Scaling.x = nNS_VECTOR2.x * num + nNS_VECTOR4.x * nncalctrsmotion.nnsRatio;
				nNS_TRS.Scaling.y = nNS_VECTOR2.y * num + nNS_VECTOR4.y * nncalctrsmotion.nnsRatio;
				nNS_TRS.Scaling.z = nNS_VECTOR2.z * num + nNS_VECTOR4.z * nncalctrsmotion.nnsRatio;
				nnScaleMatrix(nNS_MATRIX, nNS_MATRIX, nNS_TRS.Scaling.x, nNS_TRS.Scaling.y, nNS_TRS.Scaling.z);
			}
			else
			{
				nnScaleMatrixFast(nNS_MATRIX, nNS_VECTOR2.x, nNS_VECTOR2.y, nNS_VECTOR2.z);
			}
			if (nNS_NODE.iMatrix != -1)
			{
				if ((nNS_NODE.fType & 8) != 0)
				{
					nnCopyMatrix(nncalctrsmotion.nnsMtxPal[nNS_NODE.iMatrix], nNS_MATRIX);
				}
				else
				{
					nnMultiplyMatrix(nncalctrsmotion.nnsMtxPal[nNS_NODE.iMatrix], nNS_MATRIX, nNS_NODE.InvInitMtx);
				}
			}
			if (nncalctrsmotion.nnsNodeStatList != null)
			{
				if (nodeIdx == 0 && nncalctrsmotion.nnsNSFlag != 0)
				{
					nncalctrsmotion.nnsRootScale = nnEstimateMatrixScaling(nNS_MATRIX);
				}
				nnCalcClipSetNodeStatus(nncalctrsmotion.nnsNodeStatList, nncalctrsmotion.nnsNodeList, nodeIdx, nNS_MATRIX, nncalctrsmotion.nnsRootScale, nncalctrsmotion.nnsNSFlag);
			}
			if (nNS_NODE.iChild != -1)
			{
				nnCalcMatrixPaletteLinkMotionNode(nNS_NODE.iChild);
			}
			nnPopMatrix(nncalctrsmotion.nnsMstk);
			nodeIdx = nNS_NODE.iSibling;
		}
		while (nNS_NODE.iSibling != -1);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR2);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR3);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR4);
	}

	private void nnCalcMatrixTRSList1BoneXSIIK(NNS_MATRIX[] mtxlist, NNS_OBJECT obj, NNS_TRS[] trslist, NNS_MATRIX basemtx, int rootidx)
	{
		int num = -1;
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		int num2 = -1;
		NNS_VECTORFAST dst = default(NNS_VECTORFAST);
		NNS_NODE[] pNodeList = obj.pNodeList;
		NNS_NODE nNS_NODE = pNodeList[rootidx];
		NNS_MATRIX src = mtxlist[rootidx];
		int num3 = nNS_NODE.iChild;
		while (num3 != -1)
		{
			NNS_NODE nNS_NODE2 = pNodeList[num3];
			if ((nNS_NODE2.fType & 0x4000) != 0)
			{
				num = num3;
			}
			if ((nNS_NODE2.fType & 0x2000) != 0)
			{
				num2 = num3;
			}
			num3 = nNS_NODE2.iSibling;
		}
		NNM_ASSERT(num != -1, "XSIIK 1Bone Joint1 not Found");
		NNM_ASSERT(num2 != -1, "XSIIK 1Bone Effector not Found");
		NNS_MATRIX nNS_MATRIX2 = nNS_MATRIX;
		NNS_NODE nNS_NODE3 = pNodeList[num];
		NNS_TRS nNS_TRS = trslist[num];
		NNS_MATRIX nNS_MATRIX3 = mtxlist[num];
		NNS_NODE nNS_NODE4 = pNodeList[num2];
		NNS_TRS nNS_TRS2 = trslist[num2];
		NNS_MATRIX nNS_MATRIX4 = mtxlist[num2];
		float sIIKBoneLength = nNS_NODE3.SIIKBoneLength;
		nnMakeQuaternionMatrix(nNS_MATRIX2, ref nNS_TRS.Rotation);
		nnScaleMatrix(nNS_MATRIX2, nNS_MATRIX2, nNS_TRS.Scaling.x, 1f, 1f);
		nnMakeUnitMatrix(nNS_MATRIX4);
		nnTransformVectorFast(out dst, basemtx, nNS_TRS2.Translation);
		nnCopyVectorFastMatrixTranslation(nNS_MATRIX4, ref dst);
		nnCopyMatrix(nNS_MATRIX3, src);
		nnCalc1BoneSIIK(nNS_MATRIX3, nNS_MATRIX2, nNS_MATRIX4, sIIKBoneLength);
		if ((nNS_NODE4.fType & 0x1000) == 0)
		{
			nnCopyMatrix33(nNS_MATRIX4, src);
		}
		nnQuaternionMatrix(nNS_MATRIX4, nNS_MATRIX4, ref nNS_TRS2.Rotation);
	}

	private void nnCalcMatrixTRSList2BoneXSIIK(NNS_MATRIX[] mtxlist, NNS_OBJECT obj, NNS_TRS[] trslist, NNS_MATRIX basemtx, int rootidx)
	{
		int num = -1;
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		int num2 = -1;
		NNS_MATRIX nNS_MATRIX2 = GlobalPool<NNS_MATRIX>.Alloc();
