		NNM_ASSERT(num2 != -1, "XSIIK 1Bone Effector not Found");
		NNS_NODE nNS_NODE3 = nncalctrsmotion.nnsNodeList[num];
		NNS_TRS nNS_TRS = nncalctrsmotion.nnsTrsList[num];
		NNS_MATRIX nNS_MATRIX7 = nNS_MATRIX2;
		NNS_MATRIX nNS_MATRIX8 = nNS_MATRIX3;
		NNS_NODE nNS_NODE4 = nncalctrsmotion.nnsNodeList[num2];
		NNS_MATRIX nNS_MATRIX9 = nNS_MATRIX4;
		NNS_TRS nNS_TRS2 = nncalctrsmotion.nnsTrsList[num2];
		float sIIKBoneLength = nNS_NODE3.SIIKBoneLength;
		nnCopyMatrix(nNS_MATRIX7, nNS_MATRIX6);
		nnMakeQuaternionMatrix(nNS_MATRIX8, ref nNS_TRS.Rotation);
		nnScaleMatrix(nNS_MATRIX8, nNS_MATRIX8, nNS_TRS.Scaling.x, 1f, 1f);
