		nnTransformVectorFast(out dst, nncalctrsmotion.nnsBaseMtx, nNS_TRS2.Translation);
		nnCopyVectorFastMatrixTranslation(nNS_MATRIX9, ref dst);
		nnCalc1BoneSIIK(nNS_MATRIX7, nNS_MATRIX8, nNS_MATRIX9, sIIKBoneLength);
		if ((nNS_NODE4.fType & 0x1000) == 0)
		{
			nnCopyMatrix33(nNS_MATRIX9, nNS_MATRIX6);
		}
		nnMultiplyMatrix(nNS_MATRIX9, nNS_MATRIX9, nNS_MATRIX5);
		if (nNS_NODE.iMatrix != -1)
		{
			nnMultiplyMatrix(nncalctrsmotion.nnsMtxPal[nNS_NODE.iMatrix], nNS_MATRIX6, nNS_NODE.InvInitMtx);
		}
		if (nNS_NODE3.iMatrix != -1)
		{
			nnMultiplyMatrix(nncalctrsmotion.nnsMtxPal[nNS_NODE3.iMatrix], nNS_MATRIX7, nNS_NODE3.InvInitMtx);
		}
		if (nNS_NODE4.iMatrix != -1)
		{
			nnMultiplyMatrix(nncalctrsmotion.nnsMtxPal[nNS_NODE4.iMatrix], nNS_MATRIX9, nNS_NODE4.InvInitMtx);
		}
