			nnCalcClipSetNodeStatus(nncalctrsmotion.nnsNodeStatList, nncalctrsmotion.nnsNodeList, num, nNS_MATRIX7, nncalctrsmotion.nnsRootScale, nncalctrsmotion.nnsNSFlag);
			nnCalcClipSetNodeStatus(nncalctrsmotion.nnsNodeStatList, nncalctrsmotion.nnsNodeList, num2, nNS_MATRIX9, nncalctrsmotion.nnsRootScale, nncalctrsmotion.nnsNSFlag);
