	private static void GmSoundPlayJingleObore()
	{
		if (GsSoundIsBgmStop(gm_sound_jingle_bgm_scb) && (gm_sound_flag & 1) == 0)
		{
			if (!GsSoundIsBgmPause(gm_sound_bgm_scb))
			{
				GmSoundPauseStageBGM(0);
			}
			GmSoundPlayBGMJingle(6u, 0);
			if ((gm_sound_flag & 0x20) != 0)
			{
				gmSoundSetBGMFadeEnd(gm_sound_jingle_bgm_scb);
				GsSoundScbSetVolume(gm_sound_jingle_bgm_scb, 0f);
				GsSoundScbSetSeqMute(gm_sound_jingle_bgm_scb, true);
			}
			gm_sound_flag |= 1u;
		}
	}

	private static void GmSoundStopJingleObore()
	{
		if ((gm_sound_flag & 1) != 0)
		{
			if (!GsSoundIsBgmPause(gm_sound_jingle_bgm_scb) && (gm_sound_flag & 0x20) == 0)
			{
				GmSoundStopBGMJingle(15);
			}
			else
			{
				GmSoundStopBGMJingle(0);
			}
			if ((gm_sound_flag & 0x80000000u) == 0)
			{
				GmSoundResumeStageBGM(0);
			}
			gm_sound_flag &= 4294967294u;
		}
	}

	private static void GmSoundPlayJingleInvincible()
	{
		if ((gm_sound_flag & 4) == 0)
		{
			if (!GsSoundIsBgmPause(gm_sound_bgm_scb))
			{
				GmSoundPauseStageBGM(0);
			}
			GmSoundPlayBGMJingle(4u, 0);
			if ((gm_sound_flag & 0x20) != 0)
			{
				gmSoundSetBGMFadeEnd(gm_sound_jingle_bgm_scb);
				GsSoundScbSetVolume(gm_sound_jingle_bgm_scb, 0f);
				GsSoundScbSetSeqMute(gm_sound_jingle_bgm_scb, true);
			}
			gm_sound_flag |= 4u;
			gm_sound_flag &= 4294967294u;
		}
	}

	private static void GmSoundStopJingleInvincible()
	{
		if ((gm_sound_flag & 4) != 0)
		{
			if (!GsSoundIsBgmPause(gm_sound_jingle_bgm_scb) && (gm_sound_flag & 0x20) == 0)
			{
				GmSoundStopBGMJingle(0);
			}
			else
			{
				GmSoundStopBGMJingle(0);
			}
			if ((gm_sound_flag & 0x80000000u) == 0)
			{
				GmSoundResumeStageBGM(0);
			}
			gm_sound_flag &= 4294967291u;
		}
	}

	private static bool GmBGMIsAlreadyPlaying()
	{
		AMS_CRIAUDIO_INTERFACE aMS_CRIAUDIO_INTERFACE = amCriAudioGetGlobal();
		if (aMS_CRIAUDIO_INTERFACE.auply[gm_sound_bgm_scb.auply_no] != null && aMS_CRIAUDIO_INTERFACE.auply[gm_sound_bgm_scb.auply_no].se_name == gm_sound_bgm_name_list[g_gs_main_sys_info.stage_id] && !aMS_CRIAUDIO_INTERFACE.auply[gm_sound_bgm_scb.auply_no].IsPaused())
		{
			return true;
		}
		return false;
	}

