	private static void GmSoundAllPause()
	{
		gm_sound_flag &= 4043309055u;
		if (!GsSoundIsBgmStop(gm_sound_jingle_scb) && !GsSoundIsBgmPause(gm_sound_jingle_scb))
		{
			GsSoundPauseBgm(gm_sound_jingle_scb, 0);
			gm_sound_flag |= 67108864u;
		}
		if (!GsSoundIsBgmStop(gm_sound_jingle_bgm_scb) && !GsSoundIsBgmPause(gm_sound_jingle_bgm_scb))
		{
			GsSoundPauseBgm(gm_sound_jingle_bgm_scb, 0);
			gm_sound_flag |= 33554432u;
		}
		if (!GsSoundIsBgmStop(gm_sound_bgm_scb) && !GsSoundIsBgmPause(gm_sound_bgm_scb))
		{
			GsSoundPauseBgm(gm_sound_bgm_scb, 0);
			gm_sound_flag |= 16777216u;
		}
		GsSoundStopBgm(gm_sound_bgm_sub_scb, 0);
		GsSoundPauseSe(128u);
		gm_sound_flag |= 134217728u;
	}

	private static void GmSoundAllResume()
	{
		if ((gm_sound_flag & 0x4000000) != 0)
		{
			GsSoundResumeBgm(gm_sound_jingle_scb, 0);
		}
		else if ((gm_sound_flag & 0x2000000) != 0)
		{
			GsSoundResumeBgm(gm_sound_jingle_bgm_scb, 0);
		}
		else if ((gm_sound_flag & 0x1000000) != 0)
		{
			GsSoundResumeBgm(gm_sound_bgm_scb, 0);
		}
		GsSoundResumeSe(128u);
		gm_sound_flag &= 4043309055u;
	}

	private static void gmSoundPlay1ShotJingle(uint jngl_idx, int jingle_fade_in_frame, int bgm_fade_out_frame, int bgm_fade_in_frame)
	{
		gm_sound_flag |= 2147483648u;
		if (!GsSoundIsBgmStop(gm_sound_bgm_scb) && !GsSoundIsBgmPause(gm_sound_bgm_scb))
		{
			GmSoundPauseStageBGM(bgm_fade_out_frame);
		}
		if (!GsSoundIsBgmStop(gm_sound_jingle_bgm_scb) && !GsSoundIsBgmPause(gm_sound_jingle_bgm_scb))
		{
			GmSoundPauseBGMJingle(bgm_fade_out_frame);
		}
		if (gm_sound_1shot_tcb != null)
		{
			GmSoundStopJingle(0);
		}
		else
		{
			gm_sound_1shot_tcb = MTM_TASK_MAKE_TCB(gmSound1ShotJingleFunc, gmSound1ShotJingleDest, 0u, 0, 32767u, 5, () => new GMS_SOUND_1SHOT_JINGLE_WORK(), "GM_SOUND_1SH");
		}
		GMS_SOUND_1SHOT_JINGLE_WORK gMS_SOUND_1SHOT_JINGLE_WORK = (GMS_SOUND_1SHOT_JINGLE_WORK)gm_sound_1shot_tcb.work;
		gMS_SOUND_1SHOT_JINGLE_WORK.Clear();
		GmSoundPlayJingle(jngl_idx, jingle_fade_in_frame);
		gMS_SOUND_1SHOT_JINGLE_WORK.bgm_fade_in_frame = bgm_fade_in_frame;
	}

	private static void gmSound1ShotJingleFunc(MTS_TASK_TCB tcb)
	{
		if ((gm_sound_flag & 0x8000000) != 0)
		{
			return;
		}
		GMS_SOUND_1SHOT_JINGLE_WORK gMS_SOUND_1SHOT_JINGLE_WORK = (GMS_SOUND_1SHOT_JINGLE_WORK)gm_sound_1shot_tcb.work;
		bool timeout = false;
		if (gm_sound_1shot_timeout > 0 && --gm_sound_1shot_timeout == 0)
		{
			timeout = true;
		}
		if (timeout || GsSoundIsBgmStop(gm_sound_jingle_scb))
		{
			GmSoundStopJingle(0);
			gm_sound_flag &= 2147483647u;
			if (!GsSoundIsBgmStop(gm_sound_jingle_bgm_scb) && GsSoundIsBgmPause(gm_sound_jingle_bgm_scb))
			{
				GmSoundResumeBGMJingle(gMS_SOUND_1SHOT_JINGLE_WORK.bgm_fade_in_frame);
			}
			else if (!GsSoundIsBgmStop(gm_sound_bgm_scb) && GsSoundIsBgmPause(gm_sound_bgm_scb))
			{
				GmSoundResumeStageBGM(gMS_SOUND_1SHOT_JINGLE_WORK.bgm_fade_in_frame);
			}
			else if (timeout)
			{
				GmSoundResumeStageBGM(gMS_SOUND_1SHOT_JINGLE_WORK.bgm_fade_in_frame);
			}
			mtTaskClearTcb(tcb);
		}
	}

	private static void gmSound1ShotJingleDest(MTS_TASK_TCB tcb)
	{
		gm_sound_1shot_tcb = null;
	}

	private static void gmSoundSetBGMFade(GSS_SND_SCB snd_scb, float start_vol, float end_vol, int frame)
	{
		if (GsSoundIsBgmStop(gm_sound_bgm_scb) || GsSoundIsBgmPause(gm_sound_bgm_scb))
		{
			return;
		}
		gmSoundSetBGMFadeEnd(snd_scb);
		if (frame <= 0)
		{
			frame = 1;
		}
		GMS_SOUND_BGM_FADE_MGR_WORK gMS_SOUND_BGM_FADE_MGR_WORK;
		if (gm_sound_bgm_fade_tcb == null)
		{
			gm_sound_bgm_fade_tcb = MTM_TASK_MAKE_TCB(gmSoundBGMFadeFunc, gmSoundBGMFadeDest, 0u, 0, 32767u, 5, () => new GMS_SOUND_BGM_FADE_MGR_WORK(), "GM_SOUND_BFADE");
			gMS_SOUND_BGM_FADE_MGR_WORK = (GMS_SOUND_BGM_FADE_MGR_WORK)gm_sound_bgm_fade_tcb.work;
			gMS_SOUND_BGM_FADE_MGR_WORK.Clear();
		}
		gMS_SOUND_BGM_FADE_MGR_WORK = (GMS_SOUND_BGM_FADE_MGR_WORK)gm_sound_bgm_fade_tcb.work;
		GMS_SOUND_BGM_FADE_WORK gMS_SOUND_BGM_FADE_WORK = new GMS_SOUND_BGM_FADE_WORK();
		gMS_SOUND_BGM_FADE_WORK.snd_scb = snd_scb;
		gMS_SOUND_BGM_FADE_WORK.start_vol = start_vol;
		gMS_SOUND_BGM_FADE_WORK.end_vol = end_vol;
		gMS_SOUND_BGM_FADE_WORK.frame = frame;
		gMS_SOUND_BGM_FADE_WORK.fade_spd = (end_vol - start_vol) / (float)frame;
		gMS_SOUND_BGM_FADE_WORK.now_vol = start_vol;
		gmSoundBGMFadeAttachList(gMS_SOUND_BGM_FADE_MGR_WORK, gMS_SOUND_BGM_FADE_WORK);
	}

	private static void gmSoundSetBGMFadeEnd(GSS_SND_SCB snd_scb)
	{
		if (gm_sound_bgm_fade_tcb == null)
		{
			return;
		}
		GMS_SOUND_BGM_FADE_MGR_WORK gMS_SOUND_BGM_FADE_MGR_WORK = (GMS_SOUND_BGM_FADE_MGR_WORK)gm_sound_bgm_fade_tcb.work;
		GMS_SOUND_BGM_FADE_WORK gMS_SOUND_BGM_FADE_WORK = gMS_SOUND_BGM_FADE_MGR_WORK.head;
		while (gMS_SOUND_BGM_FADE_WORK != null)
		{
			GMS_SOUND_BGM_FADE_WORK next = gMS_SOUND_BGM_FADE_WORK.next;
			if (gMS_SOUND_BGM_FADE_WORK.snd_scb == snd_scb)
			{
				gmSoundBGMFadeDetachList(gMS_SOUND_BGM_FADE_MGR_WORK, gMS_SOUND_BGM_FADE_WORK);
				gMS_SOUND_BGM_FADE_WORK = null;
			}
			gMS_SOUND_BGM_FADE_WORK = next;
		}
		if (gMS_SOUND_BGM_FADE_MGR_WORK.num <= 0)
		{
			mtTaskClearTcb(gm_sound_bgm_fade_tcb);
		}
	}

	private static void gmSoundBGMFadeFunc(MTS_TASK_TCB tcb)
	{
		GMS_SOUND_BGM_FADE_MGR_WORK gMS_SOUND_BGM_FADE_MGR_WORK = (GMS_SOUND_BGM_FADE_MGR_WORK)tcb.work;
		GMS_SOUND_BGM_FADE_WORK gMS_SOUND_BGM_FADE_WORK = gMS_SOUND_BGM_FADE_MGR_WORK.head;
		while (gMS_SOUND_BGM_FADE_WORK != null)
		{
			GMS_SOUND_BGM_FADE_WORK next = gMS_SOUND_BGM_FADE_WORK.next;
			gMS_SOUND_BGM_FADE_WORK.now_vol += gMS_SOUND_BGM_FADE_WORK.fade_spd;
			gMS_SOUND_BGM_FADE_WORK.frame--;
			if (gMS_SOUND_BGM_FADE_WORK.frame <= 0)
			{
				gMS_SOUND_BGM_FADE_WORK.now_vol = gMS_SOUND_BGM_FADE_WORK.end_vol;
			}
			GsSoundScbSetVolume(gMS_SOUND_BGM_FADE_WORK.snd_scb, gMS_SOUND_BGM_FADE_WORK.now_vol);
			if (gMS_SOUND_BGM_FADE_WORK.frame <= 0 || GsSoundIsBgmStop(gMS_SOUND_BGM_FADE_WORK.snd_scb))
			{
				if (gMS_SOUND_BGM_FADE_WORK.now_vol > 0f)
				{
					GsSoundScbSetSeqMute(gMS_SOUND_BGM_FADE_WORK.snd_scb, false);
				}
				else
				{
					GsSoundScbSetSeqMute(gMS_SOUND_BGM_FADE_WORK.snd_scb, true);
				}
				gmSoundBGMFadeDetachList(gMS_SOUND_BGM_FADE_MGR_WORK, gMS_SOUND_BGM_FADE_WORK);
				gMS_SOUND_BGM_FADE_WORK = null;
			}
			gMS_SOUND_BGM_FADE_WORK = next;
		}
		if (gMS_SOUND_BGM_FADE_MGR_WORK.num <= 0)
		{
			mtTaskClearTcb(tcb);
		}
	}

	private static void gmSoundBGMFadeDest(MTS_TASK_TCB tcb)
	{
		GMS_SOUND_BGM_FADE_MGR_WORK gMS_SOUND_BGM_FADE_MGR_WORK = (GMS_SOUND_BGM_FADE_MGR_WORK)tcb.work;
		GMS_SOUND_BGM_FADE_WORK gMS_SOUND_BGM_FADE_WORK = gMS_SOUND_BGM_FADE_MGR_WORK.head;
		while (gMS_SOUND_BGM_FADE_WORK != null)
		{
			GMS_SOUND_BGM_FADE_WORK next = gMS_SOUND_BGM_FADE_WORK.next;
			gmSoundBGMFadeDetachList(gMS_SOUND_BGM_FADE_MGR_WORK, gMS_SOUND_BGM_FADE_WORK);
			gMS_SOUND_BGM_FADE_WORK = null;
			gMS_SOUND_BGM_FADE_WORK = next;
		}
		if (gm_sound_bgm_fade_tcb == tcb)
		{
			gm_sound_bgm_fade_tcb = null;
		}
	}

	private static void gmSoundBGMFadeAttachList(GMS_SOUND_BGM_FADE_MGR_WORK mgr_work, GMS_SOUND_BGM_FADE_WORK fade_work)
	{
		if (mgr_work.tail != null)
		{
			fade_work.prev = mgr_work.tail;
			mgr_work.tail.next = fade_work;
			mgr_work.tail = fade_work;
		}
		else
		{
			mgr_work.head = fade_work;
			mgr_work.tail = fade_work;
		}
		mgr_work.num++;
	}

	private static void gmSoundBGMFadeDetachList(GMS_SOUND_BGM_FADE_MGR_WORK mgr_work, GMS_SOUND_BGM_FADE_WORK fade_work)
	{
		if (fade_work.prev != null)
		{
			fade_work.prev.next = fade_work.next;
		}
		else
		{
			mgr_work.head = fade_work.next;
		}
		if (fade_work.next != null)
		{
			fade_work.next.prev = fade_work.prev;
		}
		else
		{
			mgr_work.tail = fade_work.prev;
		}
		mgr_work.num--;
	}

	private static void gmSoundBGMWinBossFunc(MTS_TASK_TCB tcb)
	{
		GMS_SOUND_BGM_WIN_BOSS_MGR_WORK gMS_SOUND_BGM_WIN_BOSS_MGR_WORK = (GMS_SOUND_BGM_WIN_BOSS_MGR_WORK)tcb.work;
		if ((gm_sound_flag & 0x8000000) != 0)
		{
			return;
		}
		gMS_SOUND_BGM_WIN_BOSS_MGR_WORK.timer--;
		if (gMS_SOUND_BGM_WIN_BOSS_MGR_WORK.timer <= 0)
		{
			bool flag = false;
			bool flag2 = false;
			GsSoundStopBgm(gm_sound_bgm_sub_scb, 0);
			if (GsSoundIsBgmPause(gm_sound_bgm_scb))
			{
				flag = true;
			}
			if ((gm_sound_flag & 0x50) != 0)
			{
				flag2 = true;
			}
			if (flag || flag2)
			{
				GmSoundStopStageBGM(0);
			}
			else
			{
				GmSoundStopStageBGM(30);
			}
			GSS_SND_SCB gSS_SND_SCB = gm_sound_bgm_scb;
			gm_sound_bgm_scb = gm_sound_bgm_sub_scb;
			gm_sound_bgm_sub_scb = gSS_SND_SCB;
			GsSoundScbSetVolume(gm_sound_bgm_scb, 1f);
			GsSoundScbSetSeqMute(gm_sound_bgm_scb, false);
			GsSoundPlayBgm(gm_sound_bgm_scb, gm_sound_bgm_win_boss_name_list[GMM_MAIN_GET_ZONE_TYPE()], 30);
			gm_sound_bgm_scb.flag |= 2147483648u;
			if (flag)
			{
				GmSoundPauseStageBGM(0);
			}
			if (flag2)
			{
				gmSoundSetBGMFadeEnd(gm_sound_bgm_scb);
				GsSoundScbSetVolume(gm_sound_bgm_scb, 0f);
				GsSoundScbSetSeqMute(gm_sound_bgm_scb, true);
			}
			mtTaskClearTcb(tcb);
		}
	}

	private static void gmSoundBGMWinBossDest(MTS_TASK_TCB tcb)
	{
		if (tcb == gm_sound_bgm_win_boss_tcb)
		{
			gm_sound_bgm_win_boss_tcb = null;
		}
	}

	public static void GmScoreCreateScore(int score, int pos_x, int pos_y, int scale, int vib_level)
	{
		int[] array = new int[5];
		int[] array2 = new int[5] { 10000, 1000, 100, 10, 1 };
		if (score <= 0)
		{
			return;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = OBM_OBJECT_TASK_DETAIL_INIT(18432, 5, 0, 0, () => new GMS_SCORE_DISP_WORK(), null);
		GMS_SCORE_DISP_WORK gMS_SCORE_DISP_WORK = (GMS_SCORE_DISP_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.pos.x = pos_x;
		oBS_OBJECT_WORK.pos.y = pos_y + -65536;
		oBS_OBJECT_WORK.pos.z = 1179648;
		oBS_OBJECT_WORK.flag |= 18u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		oBS_OBJECT_WORK.ppFunc = gmScoreMainFunc;
		gMS_SCORE_DISP_WORK.vib_level = vib_level;
		gMS_SCORE_DISP_WORK.base_pos.Assign(oBS_OBJECT_WORK.pos);
		gMS_SCORE_DISP_WORK.scale = scale;
		gMS_SCORE_DISP_WORK.rise_dist = -131072 + -8 * (scale - 4096);
		gMS_SCORE_DISP_WORK.rise_spd = gMS_SCORE_DISP_WORK.rise_dist * 2 / 30;
		gMS_SCORE_DISP_WORK.rise_dec = -gMS_SCORE_DISP_WORK.rise_spd / 30;
		gMS_SCORE_DISP_WORK.timer = 184320;
		if (score > 99999)
		{
			score = 99999;
		}
		int num = score;
		bool flag = false;
		int num2 = 0;
		int num3;
		for (num3 = 0; num3 < 5; num3++)
		{
			array[4 - num3] = num / array2[num3];
			num -= array[4 - num3] * array2[num3];
			if (!flag)
			{
				if (array[4 - num3] == 0)
				{
					array[4 - num3] = -1;
					continue;
				}
				flag = true;
				num2++;
			}
			else
			{
				num2++;
			}
		}
		int num4 = ((num2 * 11 + (num2 - 1)) * 4096 >> 1) - 22528;
		int num5 = -49152;
		num3 = 0;
		while (num3 < 5 && array[num3] != -1)
		{
			gMS_SCORE_DISP_WORK.efct_work[num3] = GmEfctCmnEsCreate(oBS_OBJECT_WORK, 56 + array[num3]);
			gMS_SCORE_DISP_WORK.efct_work[num3].efct_com.obj_work.scale.x = (gMS_SCORE_DISP_WORK.efct_work[num3].efct_com.obj_work.scale.y = (gMS_SCORE_DISP_WORK.efct_work[num3].efct_com.obj_work.scale.z = scale));
			gMS_SCORE_DISP_WORK.efct_work[num3].obj_3des.command_state = 10u;
			GmComEfctSetDispOffset(gMS_SCORE_DISP_WORK.efct_work[num3], num4, 0, 0);
			num3++;
			num4 += num5;
		}
	}

	public static void gmScoreMainFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_SCORE_DISP_WORK gMS_SCORE_DISP_WORK = (GMS_SCORE_DISP_WORK)obj_work;
		gMS_SCORE_DISP_WORK.base_pos.y += gMS_SCORE_DISP_WORK.rise_spd;
		gMS_SCORE_DISP_WORK.rise_spd += gMS_SCORE_DISP_WORK.rise_dec;
		if (gMS_SCORE_DISP_WORK.rise_spd > 0)
		{
			gMS_SCORE_DISP_WORK.rise_spd = 0;
		}
		obj_work.pos.Assign(gMS_SCORE_DISP_WORK.base_pos);
		if (gMS_SCORE_DISP_WORK.rise_spd != 0)
		{
			gMS_SCORE_DISP_WORK.vib_timer = ObjTimeCountUp(gMS_SCORE_DISP_WORK.vib_timer);
			int num = (gMS_SCORE_DISP_WORK.vib_timer >> 12) & 7;
			obj_work.pos.x += FX_Mul(gm_score_vib_tbl[num][0], gm_score_vib_scale_tbl[gMS_SCORE_DISP_WORK.vib_level]);
			obj_work.pos.y += FX_Mul(gm_score_vib_tbl[num][1], gm_score_vib_scale_tbl[gMS_SCORE_DISP_WORK.vib_level]);
		}
		gMS_SCORE_DISP_WORK.timer = ObjTimeCountDown(gMS_SCORE_DISP_WORK.timer);
		if (gMS_SCORE_DISP_WORK.timer > 0)
		{
			return;
		}
		for (int i = 0; i < 5; i++)
		{
			if (gMS_SCORE_DISP_WORK.efct_work[i] != null)
			{
				gMS_SCORE_DISP_WORK.efct_work[i].efct_com.obj_work.flag |= 8u;
			}
		}
		obj_work.flag |= 4u;
	}

	private static void GmPlySeqInitSpringJump(GMS_PLAYER_WORK ply_work, int spd_x, int spd_y, bool spd_clear, int no_jump_move_time, int fall_dir, bool t_cam_slow)
	{
		bool set_act = true;
		GmPlySeqChangeSequenceState(ply_work, 29);
		if (spd_clear)
		{
			ply_work.obj_work.spd.x = (ply_work.obj_work.spd.y = 0);
			ply_work.obj_work.spd_add.x = (ply_work.obj_work.spd_add.y = 0);
			ply_work.obj_work.spd_m = 0;
		}
		if ((ply_work.player_flag & 0x40000) != 0)
		{
			if (fall_dir != -1)
			{
				ply_work.jump_pseudofall_dir = (ushort)fall_dir;
				int num = fall_dir - ply_work.ply_pseudofall_dir;
				if ((ushort)MTM_MATH_ABS(num) > 32768)
				{
					if (num < 0)
					{
						ply_work.ply_pseudofall_dir += 65536 + num;
					}
					else
					{
						ply_work.ply_pseudofall_dir += num - 65536;
					}
				}
				else
				{
					ply_work.ply_pseudofall_dir = fall_dir;
				}
				g_gm_main_system.pseudofall_dir = (ushort)ply_work.ply_pseudofall_dir;
			}
			GmPlayerSetAtk(ply_work);
			set_act = false;
			GmPlayerActionChange(ply_work, 40);
			ply_work.obj_work.disp_flag |= 4u;
		}
		GmPlySeqGmkInitGmkJump(ply_work, spd_x, spd_y, set_act);
		if ((ply_work.player_flag & 0x40000) != 0 && fall_dir != -1)
		{
			ply_work.gmk_flag2 |= 256u;
		}
		if ((ply_work.player_flag & 0x40000) != 0)
		{
			ply_work.obj_work.disp_flag &= 4294967294u;
			if (t_cam_slow)
			{
				ply_work.gmk_flag2 |= 32u;
			}
		}
		if ((ply_work.player_flag & 0x40000) != 0 && fall_dir != -1)
		{
			ply_work.gmk_flag |= 16777216u;
		}
		if (no_jump_move_time > 0)
		{
			GmPlySeqSetNoJumpMoveTime(ply_work, no_jump_move_time);
		}
		if ((ply_work.player_flag & 0x40000) != 0)
		{
			GmSoundPlaySE("Lorry5");
		}
		else
		{
			GmSoundPlaySE("Spring");
		}
		GMM_PAD_VIB_SMALL();
	}

