			OBS_OBJECT_WORK gmk_obj = ply_work.gmk_obj;
			GmPlayerActionChange(ply_work, 17);
			obj_work.spd_m = 0;
			obj_work.spd.x = 0;
			obj_work.spd.y = 0;
			obj_work.spd.z = 0;
			obj_work.spd_add.x = 0;
			obj_work.spd_add.y = 0;
			obj_work.spd_add.z = 0;
			if (obj_work.pos.x < gmk_obj.pos.x)
			{
				obj_work.disp_flag &= 4294967294u;
			}
