	private static void GmPlySeqInitRockRide(GMS_PLAYER_WORK ply_work, GMS_ENEMY_COM_WORK com_work)
	{
		OBS_OBJECT_WORK gmk_obj = ply_work.gmk_obj;
		if (gmk_obj != (OBS_OBJECT_WORK)com_work)
		{
			GmPlySeqChangeSequenceState(ply_work, 31);
			GmPlySeqGmkInitGimmickDependInit(ply_work, com_work.obj_work, 0, 0, 0);
			ply_work.gmk_obj = com_work.obj_work;
			com_work.target_dp_dist = 229376;
			ply_work.player_flag |= 12u;
			ply_work.obj_work.move_flag |= 256u;
			OBS_OBJECT_WORK obj_work = ply_work.obj_work;
			gmk_obj = ply_work.gmk_obj;
			if (obj_work.pos.y > gmk_obj.pos.y)
			{
				GmPlySeqChangeSequence(ply_work, 16);
				ply_work.seq_func = gmPlySeqGmkMainGimmickRockRideStop;
			}
			else
			{
				ply_work.seq_func = gmPlySeqGmkMainGimmickRockRide;
				GmPlayerCameraOffsetSet(ply_work, 0, -48);
				GmCameraAllowSet(10f, 30f, 0f);
			}
			GmPlayerActionChange(ply_work, 60);
			obj_work.disp_flag |= 4u;
			ply_work.gmk_flag |= 16384u;
			int v = FX_Div(gmk_obj.pos.x - obj_work.pos.x, 229376);
			obj_work.spd_m = FX_Mul(v, 15360) + gmk_obj.spd_m;
			if (gmk_obj.spd_m > 0)
			{
				obj_work.disp_flag &= 4294967294u;
			}
			else
			{
				obj_work.disp_flag |= 1u;
			}
		}
	}

