	private static OBS_OBJECT_WORK GmGmkRockRideInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = gmGmkRockRideLoadObj(eve_rec, pos_x, pos_y, type);
		OBS_OBJECT_WORK obj_work = gMS_ENEMY_3D_WORK.ene_com.obj_work;
