	public static void GmGmkRockRideBuild()
	{
		AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile(GmGameDatGetGimmickData(817));
		TXB_HEADER txb = readTXBfile(amBindGet(aMS_AMB_HEADER, 0));
		g_gm_gmk_rock_ride_obj_3d_list = GmGameDBuildRegBuildModel(readAMBFile(GmGameDatGetGimmickData(816)), aMS_AMB_HEADER, 0u, txb);
	}

	public static void GmGmkRockRideFlush()
	{
		AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile(GmGameDatGetGimmickData(816));
		GmGameDBuildRegFlushModel(g_gm_gmk_rock_ride_obj_3d_list, aMS_AMB_HEADER.file_num);
		g_gm_gmk_rock_ride_obj_3d_list = null;
	}

	private static GMS_ENEMY_3D_WORK gmGmkRockRideLoadObj(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		GMS_GMK_ROCK_WORK gMS_GMK_ROCK_WORK = (GMS_GMK_ROCK_WORK)GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_ROCK_WORK(), "GMK_ROCK_RIDE");
		GMS_ENEMY_3D_WORK enemy_work = gMS_GMK_ROCK_WORK.enemy_work;
		OBS_OBJECT_WORK obj_work = gMS_GMK_ROCK_WORK.enemy_work.ene_com.obj_work;
		enemy_work.ene_com.rect_work[0].flag &= 4294967291u;
		enemy_work.ene_com.rect_work[1].flag &= 4294967291u;
		ObjObjectCopyAction3dNNModel(obj_work, g_gm_gmk_rock_ride_obj_3d_list[0], enemy_work.obj_3d);
		obj_work.obj_3d.use_light_flag &= 4294967294u;
		obj_work.obj_3d.use_light_flag |= 64u;
		return enemy_work;
	}

