	private static void gmGmkRockRideDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		VecU16 vecU = new VecU16(obj_work.dir);
		ushort z = gmGmkRockRideGetUserTimerAngleZ(obj_work);
