		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		gmGmkRockRideWaitSetRect(gMS_ENEMY_3D_WORK);
		obj_work.flag |= 1u;
		obj_work.move_flag |= 8448u;
		obj_work.disp_flag |= 4194304u;
		obj_work.spd_m = 0;
		gMS_ENEMY_3D_WORK.ene_com.target_obj = g_gm_main_system.ply_work[0].obj_work;
		ushort angle_z = mtMathRand();
		gmGmkRockRideSetUserTimerAngleZ(obj_work, angle_z);
		obj_work.user_work = mtMathRand();
		GMS_GMK_ROCK_WORK gMS_GMK_ROCK_WORK = (GMS_GMK_ROCK_WORK)obj_work;
		gMS_GMK_ROCK_WORK.se_handle = GsSoundAllocSeHandle();
		obj_work.ppFunc = gmGmkRockRideWaitMain;
		obj_work.ppMove = null;
		obj_work.ppOut = gmGmkRockRideDrawFunc;
		mtTaskChangeTcbDestructor(obj_work.tcb, gmGmkRockRideTcbDest);
	}

	private static void gmGmkRockRideWaitMain(OBS_OBJECT_WORK obj_work)
	{
	}

	private static void gmGmkRockRideWaitDefFunc(OBS_RECT_WORK own_rect, OBS_RECT_WORK target_rect)
	{
		OBS_OBJECT_WORK parent_obj = own_rect.parent_obj;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)parent_obj;
		GMS_ENEMY_COM_WORK ene_com = gMS_ENEMY_3D_WORK.ene_com;
		OBS_OBJECT_WORK parent_obj2 = target_rect.parent_obj;
		if (parent_obj2.obj_type != 1)
		{
			return;
		}
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)parent_obj2;
		if ((parent_obj2.move_flag & 1) != 0)
		{
			if (gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag != 0)
			{
				if (parent_obj.pos.x >= parent_obj2.pos.x)
				{
					return;
				}
			}
			else if (parent_obj.pos.x <= parent_obj2.pos.x)
			{
				return;
			}
			GmPlySeqInitRockRideStart(gMS_PLAYER_WORK, ene_com);
			gmGmkRockRideStartInit(parent_obj);
			return;
		}
		int num = parent_obj.pos.x - parent_obj2.pos.x;
		int num2 = parent_obj.pos.y - parent_obj2.pos.y;
		int num3 = FX_Mul(num, num) + FX_Mul(num2, num2);
		if (num3 <= 12845056 && (gMS_PLAYER_WORK.seq_state == 17 || gMS_PLAYER_WORK.seq_state == 21 || gMS_PLAYER_WORK.seq_state == 16 || gMS_PLAYER_WORK.seq_state == 29))
		{
			int num4 = -(229376 - MTM_MATH_ABS(num)) / 30;
			int spd_y = 0;
			if (parent_obj.pos.x < parent_obj2.pos.x)
			{
				num4 = -num4;
			}
			GmPlySeqInitPinballAir(gMS_PLAYER_WORK, num4, spd_y, 60, 1, 0);
		}
	}

