	{
		OBS_RECT_WORK oBS_RECT_WORK = gimmick_work.ene_com.rect_work[2];
		ObjRectWorkZSet(oBS_RECT_WORK, -48, -56, -500, 48, 56, 500);
		oBS_RECT_WORK.flag &= 4294966271u;
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		oBS_RECT_WORK.ppDef = gmGmkRockRideWaitDefFunc;
	}

	private static void gmGmkRockRideStartInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gimmick_work = (GMS_ENEMY_3D_WORK)obj_work;
		gmGmkRockRideStartSetRect(gimmick_work);
		ObjObjectFieldRectSet(obj_work, -16, -16, 16, 16);
		obj_work.flag &= 4294967294u;
		obj_work.move_flag &= 4294958847u;
		obj_work.move_flag |= 192u;
		obj_work.move_flag &= 4294836223u;
		obj_work.spd_m = 0;
		GMS_GMK_ROCK_WORK gMS_GMK_ROCK_WORK = (GMS_GMK_ROCK_WORK)obj_work;
		GmSoundPlaySE("BigRock3", gMS_GMK_ROCK_WORK.se_handle);
		obj_work.ppFunc = gmGmkRockRideStartMain;
		obj_work.ppMove = gmGmkRockRideMoveFunc;
		obj_work.ppOut = gmGmkRockRideDrawFunc;
	}

	private static void gmGmkRockRideStartMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_OBJECT_WORK target_obj = gMS_ENEMY_3D_WORK.ene_com.target_obj;
		gmGmkRockRideAddUserTimerAngleZ(obj_work, (short)(obj_work.spd_m >> 4));
		int num = 224;
		if (obj_work.pos.x < target_obj.pos.x)
		{
			num = -num;
		}
		obj_work.spd_m += num;
		if ((long)MTM_MATH_ABS(obj_work.spd_m) > 12288L)
		{
			gmGmkRockRideRollInit(obj_work);
		}
		float num2 = FX_FX32_TO_F32(FX_Div(MTM_MATH_ABS(obj_work.spd_m), 6));
		if (num2 > 1f)
		{
			num2 = 1f;
		}
		GMS_GMK_ROCK_WORK gMS_GMK_ROCK_WORK = (GMS_GMK_ROCK_WORK)obj_work;
		if (gMS_GMK_ROCK_WORK.se_handle != null)
		{
			gMS_GMK_ROCK_WORK.se_handle.au_player.SetAisac("Speed", num2);
		}
	}

	private static void gmGmkRockRideStartSetRect(GMS_ENEMY_3D_WORK gimmick_work)
	{
		OBS_RECT_WORK oBS_RECT_WORK = gimmick_work.ene_com.rect_work[2];
		ObjRectDefSet(oBS_RECT_WORK, ushort.MaxValue, 3);
		oBS_RECT_WORK.ppDef = null;
	}

	private static void gmGmkRockRideRollInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gimmick_work = (GMS_ENEMY_3D_WORK)obj_work;
		gmGmkRockRideRollSetRect(gimmick_work);
		ObjObjectFieldRectSet(obj_work, -16, -16, 16, 16);
		obj_work.flag &= 4294967294u;
		obj_work.move_flag &= 4294958847u;
		obj_work.move_flag |= 131264u;
		obj_work.spd_slope = 192;
		obj_work.spd_slope_max = 61440;
		obj_work.pos.z = 131072;
		obj_work.ppFunc = gmGmkRockRideRollMainNoPlayer;
		obj_work.ppMove = gmGmkRockRideMoveFunc;
		obj_work.ppOut = gmGmkRockRideDrawFunc;
		GMS_GMK_ROCK_WORK gMS_GMK_ROCK_WORK = (GMS_GMK_ROCK_WORK)obj_work;
		if (gMS_GMK_ROCK_WORK.effect_work == null)
		{
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctZoneEsCreate(obj_work, 2, 18);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = null;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.parent_ofst.z = 98304;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.parent_ofst.y = 131072;
			gMS_GMK_ROCK_WORK.effect_work = gMS_EFFECT_3DES_WORK;
		}
	}

	private static void gmGmkRockRideRollMain(OBS_OBJECT_WORK obj_work)
	{
		gmGmkRockRideAddUserTimerAngleZ(obj_work, (short)(obj_work.spd_m >> 4));
		float num = FX_FX32_TO_F32(FX_Div(MTM_MATH_ABS(obj_work.spd_m), 6));
		if (num > 1f)
		{
			num = 1f;
		}
		GMS_GMK_ROCK_WORK gMS_GMK_ROCK_WORK = (GMS_GMK_ROCK_WORK)obj_work;
		if (gMS_GMK_ROCK_WORK.se_handle != null)
		{
			gMS_GMK_ROCK_WORK.se_handle.au_player.SetAisac("Speed", num);
		}
		if ((obj_work.move_flag & 4) != 0 || (obj_work.move_flag & 8) != 0)
		{
			gmGmkRockRideStopInit(obj_work);
		}
		if (gMS_GMK_ROCK_WORK.vib_timer % 30 == 0)
		{
			GMM_PAD_VIB_SMALL_TIME(10f);
		}
		gMS_GMK_ROCK_WORK.vib_timer++;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (gMS_PLAYER_WORK.seq_state != 31)
		{
			obj_work.ppFunc = gmGmkRockRideRollMainNoPlayer;
			GMM_PAD_VIB_STOP();
			gMS_GMK_ROCK_WORK.vib_timer = 0;
			obj_work.pos.z = -262144;
		}
	}

	private static void gmGmkRockRideRollMainNoPlayer(OBS_OBJECT_WORK obj_work)
	{
		gmGmkRockRideAddUserTimerAngleZ(obj_work, (short)(obj_work.spd_m >> 4));
		float num = FX_FX32_TO_F32(FX_Div(MTM_MATH_ABS(obj_work.spd_m), 6));
		if (num > 1f)
		{
			num = 1f;
		}
		GMS_GMK_ROCK_WORK gMS_GMK_ROCK_WORK = (GMS_GMK_ROCK_WORK)obj_work;
		if (gMS_GMK_ROCK_WORK.se_handle != null)
		{
			gMS_GMK_ROCK_WORK.se_handle.au_player.SetAisac("Speed", num);
		}
		if ((obj_work.move_flag & 4) != 0 || (obj_work.move_flag & 8) != 0)
		{
			gmGmkRockRideStopInit(obj_work);
		}
	}

	private static void gmGmkRockRideRollDefFunc(OBS_RECT_WORK own_rect, OBS_RECT_WORK target_rect)
	{
		OBS_OBJECT_WORK parent_obj = own_rect.parent_obj;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)parent_obj;
		GMS_ENEMY_COM_WORK ene_com = gMS_ENEMY_3D_WORK.ene_com;
		OBS_OBJECT_WORK parent_obj2 = target_rect.parent_obj;
		if (parent_obj2.obj_type == 1)
		{
			GMS_PLAYER_WORK ply_work = (GMS_PLAYER_WORK)parent_obj2;
			GmPlySeqInitRockRide(ply_work, ene_com);
			own_rect.ppDef = gmGmkRockRideRollDefFunc;
			parent_obj.ppFunc = gmGmkRockRideRollMain;
			parent_obj.pos.z = 131072;
		}
	}

