	private static void gmGmkNeedleFwMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_GMK_NEEDLE_WORK gMS_GMK_NEEDLE_WORK = (GMS_GMK_NEEDLE_WORK)gMS_ENEMY_3D_WORK;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		if (gMS_GMK_NEEDLE_WORK.needle_type != 0)
		{
			return;
		}
		OBS_OBJECT_WORK rider_obj = gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.rider_obj;
		if (rider_obj != null && rider_obj.ride_obj == (OBS_OBJECT_WORK)gMS_ENEMY_3D_WORK)
		{
			if (rider_obj.obj_type == 1)
			{
				oBS_RECT_WORK.flag |= 4u;
			}
		}
		else
		{
			oBS_RECT_WORK.flag &= 4294967291u;
		}
	}

	private static void gmGmkActNeedleFwInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_GMK_NEEDLE_WORK gMS_GMK_NEEDLE_WORK = (GMS_GMK_NEEDLE_WORK)gMS_ENEMY_3D_WORK;
		if (gMS_GMK_NEEDLE_WORK.state == 0)
		{
			amFlagOff(ref gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.flag, 256u);
		}
		else
		{
			amFlagOn(ref obj_work.flag, 2u);
		}
		obj_work.ppFunc = gmGmkActNeedleFwMain;
	}

	private static void gmGmkActNeedleFwMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_GMK_NEEDLE_WORK gMS_GMK_NEEDLE_WORK = (GMS_GMK_NEEDLE_WORK)gMS_ENEMY_3D_WORK;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		if (gMS_GMK_NEEDLE_WORK.needle_type == 4)
		{
			OBS_OBJECT_WORK rider_obj = gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.rider_obj;
			if (rider_obj != null && rider_obj.ride_obj == (OBS_OBJECT_WORK)gMS_ENEMY_3D_WORK)
			{
				if (rider_obj.obj_type == 1)
				{
					amFlagOff(ref obj_work.flag, 2u);
				}
			}
			else
			{
				amFlagOn(ref obj_work.flag, 2u);
			}
		}
		if (gMS_GMK_NEEDLE_WORK.timer >= 60)
		{
			gMS_GMK_NEEDLE_WORK.timer = 0;
			gmGmkActNeedleScalingInit(obj_work);
		}
		else
		{
			gMS_GMK_NEEDLE_WORK.timer++;
		}
		if ((gMS_GMK_NEEDLE_WORK.scale_flag & 1) != 0)
		{
			gmGmkActNeedleSetScaleColRect(obj_work);
		}
	}

	private static void gmGmkActNeedleScalingInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_GMK_NEEDLE_WORK gMS_GMK_NEEDLE_WORK = (GMS_GMK_NEEDLE_WORK)gMS_ENEMY_3D_WORK;
		if (gMS_GMK_NEEDLE_WORK.state == 1)
		{
			amFlagOn(ref obj_work.flag, 2u);
			amFlagOn(ref gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.flag, 256u);
			gMS_GMK_NEEDLE_WORK.scale_flag |= 1u;
			gMS_GMK_NEEDLE_WORK.scale_flag |= 4u;
		}
		else if (gMS_GMK_NEEDLE_WORK.is_first_disp == 0)
		{
			obj_work.scale.y = 256;
			gMS_GMK_NEEDLE_WORK.scale_flag |= 1u;
			gMS_GMK_NEEDLE_WORK.scale_flag |= 2u;
		}
		else
		{
			gMS_GMK_NEEDLE_WORK.scale_flag |= 1u;
			gMS_GMK_NEEDLE_WORK.scale_flag |= 4u;
		}
		if (gMS_GMK_NEEDLE_WORK.is_first_disp != 0)
		{
			amFlagOn(ref obj_work.flag, 2u);
			amFlagOn(ref gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.flag, 256u);
			gMS_GMK_NEEDLE_WORK.state = 1u;
			gMS_GMK_NEEDLE_WORK.is_first_disp = 0;
		}
		amFlagOff(ref gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.flag, 256u);
		if (gMS_GMK_NEEDLE_WORK.needle_type == 4)
		{
			OBS_OBJECT_WORK rider_obj = gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.rider_obj;
			if (rider_obj != null && rider_obj.ride_obj == (OBS_OBJECT_WORK)gMS_ENEMY_3D_WORK)
			{
				if (rider_obj.obj_type == 1)
				{
					amFlagOff(ref obj_work.flag, 2u);
				}
			}
			else
			{
				amFlagOn(ref obj_work.flag, 2u);
			}
		}
		obj_work.ppFunc = gmGmkActNeedleScalingMain;
	}

	private static void gmGmkActNeedleScalingMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_GMK_NEEDLE_WORK gMS_GMK_NEEDLE_WORK = (GMS_GMK_NEEDLE_WORK)gMS_ENEMY_3D_WORK;
		if (gMS_GMK_NEEDLE_WORK.timer >= 6)
		{
			gMS_GMK_NEEDLE_WORK.timer = 0;
			gmGmkActNeedleRectWaitInit(obj_work);
			return;
		}
		amFlagOn(ref obj_work.flag, 2u);
		if (gMS_GMK_NEEDLE_WORK.state == 0)
		{
			obj_work.scale.y = obj_work.scale.y + 682;
		}
		else
		{
			obj_work.scale.y = obj_work.scale.y - 682;
		}
		if (obj_work.scale.y > 4096)
		{
			obj_work.scale.y = 4096;
		}
		else if (obj_work.scale.y <= 0)
		{
			obj_work.scale.y = 0;
		}
		amFlagOff(ref gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.flag, 256u);
		obj_work.scale.y = MTM_MATH_CLIP(obj_work.scale.y, 0, 4096);
		if ((gMS_GMK_NEEDLE_WORK.scale_flag & 1) != 0)
		{
			gmGmkActNeedleSetScaleColRect(obj_work);
		}
		if (gMS_GMK_NEEDLE_WORK.needle_type == 4)
		{
			OBS_OBJECT_WORK rider_obj = gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.rider_obj;
			if (rider_obj != null && rider_obj.ride_obj == (OBS_OBJECT_WORK)gMS_ENEMY_3D_WORK)
			{
				if (rider_obj.obj_type == 1)
				{
					amFlagOff(ref obj_work.flag, 2u);
				}
			}
			else
			{
				amFlagOn(ref obj_work.flag, 2u);
			}
		}
		gMS_GMK_NEEDLE_WORK.timer++;
	}

	private static void gmGmkActNeedleRectWaitInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_GMK_NEEDLE_WORK gMS_GMK_NEEDLE_WORK = (GMS_GMK_NEEDLE_WORK)gMS_ENEMY_3D_WORK;
		obj_work.ppFunc = gmGmkActNeedleRectWaitMain;
	}

	private static void gmGmkActNeedleRectWaitMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_GMK_NEEDLE_WORK gMS_GMK_NEEDLE_WORK = (GMS_GMK_NEEDLE_WORK)gMS_ENEMY_3D_WORK;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		amFlagOff(ref gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.flag, 256u);
		gmGmkActNeedleFwInit(obj_work);
		gMS_GMK_NEEDLE_WORK.state ^= 1u;
		if (gMS_GMK_NEEDLE_WORK.state == 1)
		{
			GmSoundPlaySE("Spine");
		}
		if ((gMS_GMK_NEEDLE_WORK.scale_flag & 1) != 0)
		{
			gmGmkActNeedleSetScaleColRect(obj_work);
		}
	}

	private static ushort GmGmkNeedleGetType(ushort type)
	{
		ushort num = 0;
		ushort num2 = 0;
		if (type < 97)
		{
			num = (ushort)(type - 91);
			return (ushort)gm_gmk_ndl_type_tbl[num];
		}
		num = (ushort)(type - 97);
		num = (ushort)(4 + num);
		return (ushort)gm_gmk_ndl_type_tbl[num];
	}

	private static void gmGmkActNeedleSetScaleColRect(OBS_OBJECT_WORK obj_work)
	{
		int num = 0;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_GMK_NEEDLE_WORK gMS_GMK_NEEDLE_WORK = (GMS_GMK_NEEDLE_WORK)gMS_ENEMY_3D_WORK;
		gMS_GMK_NEEDLE_WORK.scale_timer++;
		if ((gMS_GMK_NEEDLE_WORK.scale_flag & 4) != 0)
		{
			num = gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.height - 3;
			if (num < 0)
			{
				num = 0;
				gMS_GMK_NEEDLE_WORK.scale_timer = 0;
				gMS_GMK_NEEDLE_WORK.scale_flag &= 4294967294u;
				gMS_GMK_NEEDLE_WORK.scale_flag &= 4294967291u;
			}
			gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.height = (ushort)num;
			gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.ofst_y = (short)(-1 * gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.height);
		}
		else if ((gMS_GMK_NEEDLE_WORK.scale_flag & 2) != 0)
		{
			num = gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.height + 4;
			if (num > 32)
			{
				num = 32;
				gMS_GMK_NEEDLE_WORK.scale_timer = 0;
				gMS_GMK_NEEDLE_WORK.scale_flag &= 4294967294u;
				gMS_GMK_NEEDLE_WORK.scale_flag &= 4294967293u;
			}
			gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.height = (ushort)num;
			gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.ofst_y = (short)(-1 * gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.height);
		}
	}

	private static void gmGmkNeedleDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		if (!GmMainIsDrawEnable())
		{
			return;
		}
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_GMK_NEEDLE_WORK gMS_GMK_NEEDLE_WORK = (GMS_GMK_NEEDLE_WORK)gMS_ENEMY_3D_WORK;
		if ((obj_work.disp_flag & 0x20) != 0)
		{
			return;
		}
		VecFx32 pos = default(VecFx32);
		VecFx32 scale = new VecFx32(4096, 4096, 4096);
		short num = 0;
		NNS_TEXLIST texlist = obj_work.obj_3d.texlist;
		GMS_TVX_EX_WORK ex_work = default(GMS_TVX_EX_WORK);
		num = (short)(-49152 * gMS_GMK_NEEDLE_WORK.needle_type);
		if (gMS_GMK_NEEDLE_WORK.needle_type == 5)
		{
			num = short.MinValue;
		}
		obj_work.dir.z = (ushort)(-num);
		ex_work.u_wrap = 1;
		ex_work.v_wrap = 1;
		ex_work.coord.u = 0f;
		ex_work.coord.v = 0f;
		ex_work.color = gMS_GMK_NEEDLE_WORK.color;
		for (int i = 0; i < 5; i++)
		{
			pos.z = obj_work.pos.z;
			if (i >= 3)
			{
				pos.z -= 8192;
			}
			switch (gMS_GMK_NEEDLE_WORK.needle_type)
			{
			case 0:
			case 4:
				pos.x = obj_work.pos.x + gm_gmk_disp_ofst_tbl_u[i][0];
				pos.y = obj_work.pos.y + gm_gmk_disp_ofst_tbl_u[i][1];
				break;
			case 1:
			case 5:
				pos.x = obj_work.pos.x + gm_gmk_disp_ofst_tbl_l[i][0];
				pos.y = obj_work.pos.y + gm_gmk_disp_ofst_tbl_l[i][1];
				break;
			case 2:
				pos.x = obj_work.pos.x + gm_gmk_disp_ofst_tbl_d[i][0];
				pos.y = obj_work.pos.y + gm_gmk_disp_ofst_tbl_d[i][1];
				break;
			case 3:
				pos.x = obj_work.pos.x + gm_gmk_disp_ofst_tbl_r[i][0];
				pos.y = obj_work.pos.y + gm_gmk_disp_ofst_tbl_r[i][1];
				break;
			}
			GmTvxSetModelEx(tvx_needle, texlist, ref pos, ref obj_work.scale, GMD_TVX_DISP_ROTATE | GMD_TVX_DISP_SCALE | GMD_TVX_DISP_LIGHT_DISABLE, num, ref ex_work);
			GmTvxSetModel(tvx_stand, texlist, ref pos, ref scale, GMD_TVX_DISP_ROTATE | GMD_TVX_DISP_SCALE, num);
		}
	}

	public static void GmGmkNeedleSetLight()
	{
		NNS_RGBA col = new NNS_RGBA(1f, 1f, 1f, 1f);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		if (g_gs_main_sys_info.stage_id == 14)
		{
			nNS_VECTOR.x = -0.1f;
			nNS_VECTOR.y = -0.09f;
			nNS_VECTOR.z = -0.93f;
		}
		else
		{
			nNS_VECTOR.x = -1f;
			nNS_VECTOR.y = -1f;
			nNS_VECTOR.z = -1f;
		}
		col.r = 1f;
		col.g = 1f;
		col.b = 1f;
		nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
		ObjDrawSetParallelLight(intensity: (g_gs_main_sys_info.stage_id != 14) ? 1f : 0.8f, light_no: NNE_LIGHT_2, col: ref col, vec: nNS_VECTOR);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	private static OBS_OBJECT_WORK GmGmkGoalPanelInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_GOAL_PANEL");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 65536u;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_goal_panel_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		oBS_OBJECT_WORK.pos.z = -131072;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.dir.y = 32768;
		gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.flag |= 134217728u;
		oBS_OBJECT_WORK.ppFunc = gmGmkGoalPanelMain;
		GmGmkSplRingMake(pos_x + 393216, pos_y - 393216);
		return oBS_OBJECT_WORK;
	}

	public static void GmGmkGoalPanelBuild()
	{
		gm_gmk_goal_panel_obj_3d_list = GmGameDBuildRegBuildModel(GmGameDatGetGimmickData(836), GmGameDatGetGimmickData(837), 0u);
	}

	public static void GmGmkGoalPanelFlush()
	{
		AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile(GmGameDatGetGimmickData(836));
		GmGameDBuildRegFlushModel(gm_gmk_goal_panel_obj_3d_list, aMS_AMB_HEADER.file_num);
	}

	private static void gmGmkGoalPanelMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (obj_work.pos.x < gMS_PLAYER_WORK.obj_work.pos.x)
		{
			SaveState.deleteSave();
			if ((gMS_PLAYER_WORK.player_flag & 0x4000) != 0)
			{
				g_gm_main_system.game_flag |= 33554432u;
			}
			else
			{
				g_gm_main_system.game_flag &= 4261412863u;
			}
			HgTrophyTryAcquisition(1);
			GmPlayerSetGoalState(gMS_PLAYER_WORK);
			g_gm_main_system.game_flag &= 4294966271u;
			g_gm_main_system.game_flag |= 1048576u;
			obj_work.user_work = 4096u;
			obj_work.user_timer = 120;
			obj_work.ppFunc = gmGmkGoalPanelPass;
			GMS_EVE_RECORD_EVENT gMS_EVE_RECORD_EVENT = new GMS_EVE_RECORD_EVENT();
			gMS_EVE_RECORD_EVENT.flag = 5;
			gMS_EVE_RECORD_EVENT.left = -96;
			gMS_EVE_RECORD_EVENT.top = -104;
			gMS_EVE_RECORD_EVENT.width = 192;
			gMS_EVE_RECORD_EVENT.height = 112;
			GmGmkCamScrLimitSet(gMS_EVE_RECORD_EVENT, obj_work.pos.x, obj_work.pos.y);
			gm_gmk_goal_panel_effct = GmEfctCmnEsCreate(obj_work, 32);
			GmEffect3DESSetDispOffset(gm_gmk_goal_panel_effct, 0f, 30f, 15f);
			GmEffect3DESSetDispRotation(gm_gmk_goal_panel_effct, 0, 0, 0);
			GMM_PAD_VIB_SMALL();
			GmSoundPlaySE("GoalPanel");
		}
	}

	private static OBS_OBJECT_WORK GmGmkCamScrLimitSet(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y)
	{
		return GmEventMgrLocalEventBirth(302, pos_x, pos_y, eve_rec.flag, eve_rec.left, eve_rec.top, eve_rec.width, eve_rec.height, 0);
	}

	private static void gmGmkGoalPanelPass(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_timer--;
		if (obj_work.user_timer <= 0)
		{
			obj_work.user_timer = 0;
			obj_work.user_work = 0u;
			obj_work.dir.y = 0;
			obj_work.user_timer = 120;
			obj_work.ppFunc = gmGmkGoalPanelWait;
			gmGmkGoalPanelEfctKill();
			GmPlySeqChangeActGoal(g_gm_main_system.ply_work[0]);
		}
		obj_work.dir.y += (ushort)obj_work.user_work;
	}

	private static void gmGmkGoalPanelWait(OBS_OBJECT_WORK obj_work)
	{
		if (--obj_work.user_timer <= 0)
		{
			g_gm_main_system.game_flag |= 4u;
			obj_work.ppFunc = null;
			gmGmkGoalPanelEfctKill();
		}
	}

	private static void gmGmkGoalPanelEfctKill()
	{
		if (gm_gmk_goal_panel_effct != null)
		{
			ObjDrawKillAction3DES((OBS_OBJECT_WORK)gm_gmk_goal_panel_effct);
			gm_gmk_goal_panel_effct = null;
		}
	}

