	public static OBS_OBJECT_WORK GmGmkBridgeInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_BRIDGE");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_bridge_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		if ((eve_rec.flag & 1) != 0)
		{
			oBS_OBJECT_WORK.user_work = 3u;
		}
		else
		{
			oBS_OBJECT_WORK.user_work = 2u;
		}
		oBS_OBJECT_WORK.user_flag = 0u;
		oBS_OBJECT_WORK.user_timer = 0;
		oBS_OBJECT_WORK.pos.z = -131072;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.ppFunc = gmGmkBridgeMain;
		oBS_OBJECT_WORK.ppOut = gmGmkBridgeDrawFunc;
		OBS_COLLISION_WORK col_work = gMS_ENEMY_3D_WORK.ene_com.col_work;
		col_work.obj_col.obj = oBS_OBJECT_WORK;
		col_work.obj_col.diff_data = g_gm_default_col;
		col_work.obj_col.flag |= 134217728u;
		col_work.obj_col.width = (ushort)(oBS_OBJECT_WORK.user_work * 64);
		col_work.obj_col.height = 16;
		col_work.obj_col.ofst_x = -96;
		col_work.obj_col.ofst_y = 0;
		col_work.obj_col.attr = 1;
