	public static void gmGmkBridgeMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if (gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.rider_obj == gMS_PLAYER_WORK.obj_work)
		{
			if (obj_work.user_timer < 16)
			{
				obj_work.user_timer++;
			}
			obj_work.user_flag = (uint)gMS_PLAYER_WORK.obj_work.pos.x;
		}
		else if (obj_work.user_timer != 0)
		{
			obj_work.user_timer--;
		}
		if (obj_work.user_timer != 0)
		{
			int num = (int)(obj_work.user_work * 53248 * 5);
			num >>= 1;
			int numer = (int)obj_work.user_flag - (obj_work.pos.x + -393216 + num);
			int a = FX_Div(numer, num);
			a = MTM_MATH_CLIP(a, -4096, 4096);
			a <<= 2;
			int a2 = mtMathCos(a) * 8 * obj_work.user_timer / 16;
			gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.ofst_y = (short)(MTM_MATH_ABS(a2) >> 12);
		}
		else
		{
			gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.ofst_y = 0;
		}
	}

	public static void gmGmkBridgeDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		int num = (int)(obj_work.user_work * 53248 * 5);
		int num2 = (int)obj_work.user_flag - (obj_work.pos.x + -393216);
		int denom = num2;
		int denom2 = num - num2;
		int v = gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.ofst_y << 12;
		obj_work.ofst.x = -366592;
		obj_work.ofst.y = 26624;
		if ((obj_work.disp_flag & 0x20) != 0)
		{
			return;
		}
		uint col = GmMainGetLightColor();
		NNS_TEXLIST texlist = obj_work.obj_3d.texlist;
		VecFx32 vecFx = new VecFx32
		{
			x = obj_work.pos.x + obj_work.ofst.x,
			y = -(obj_work.pos.y + obj_work.ofst.y),
			z = obj_work.pos.z + obj_work.ofst.z
		};
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		nnMakeUnitMatrix(nNS_MATRIX);
		nnTranslateMatrix(nNS_MATRIX, nNS_MATRIX, FX_FX32_TO_F32(vecFx.x), FX_FX32_TO_F32(vecFx.y), FX_FX32_TO_F32(vecFx.z));
		AMS_PARAM_DRAW_PRIMITIVE aMS_PARAM_DRAW_PRIMITIVE = GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Alloc();
		aMS_PARAM_DRAW_PRIMITIVE.type = 0;
		aMS_PARAM_DRAW_PRIMITIVE.count = (int)(30 * obj_work.user_work);
		aMS_PARAM_DRAW_PRIMITIVE.ablend = 0;
		aMS_PARAM_DRAW_PRIMITIVE.bldSrc = 770;
		aMS_PARAM_DRAW_PRIMITIVE.bldDst = 771;
		aMS_PARAM_DRAW_PRIMITIVE.bldMode = 32774;
		aMS_PARAM_DRAW_PRIMITIVE.aTest = 1;
		aMS_PARAM_DRAW_PRIMITIVE.zMask = 0;
		aMS_PARAM_DRAW_PRIMITIVE.zTest = 1;
		aMS_PARAM_DRAW_PRIMITIVE.noSort = 1;
		aMS_PARAM_DRAW_PRIMITIVE.uwrap = 1;
		aMS_PARAM_DRAW_PRIMITIVE.vwrap = 1;
		aMS_PARAM_DRAW_PRIMITIVE.texlist = texlist;
		aMS_PARAM_DRAW_PRIMITIVE.texId = 0;
		aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D = amDrawAlloc_NNS_PRIM3D_PCT(aMS_PARAM_DRAW_PRIMITIVE.count);
		NNS_PRIM3D_PCT[] buffer = aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D.buffer;
		int offset = aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D.offset;
		aMS_PARAM_DRAW_PRIMITIVE.format3D = 4;
		for (int i = 0; i < (short)obj_work.user_work; i++)
		{
			for (int j = 0; j < 5; j++)
			{
				if (obj_work.user_timer != 0)
				{
					int num3 = i * 53248 * 5 + j * 53248;
					int v2;
					if (num3 < num2)
					{
						v2 = FX_Div(num3, denom);
					}
					else if (num3 > num2)
					{
						num3 = num - num3;
						v2 = FX_Div(num3, denom2);
					}
					else
					{
						v2 = 4096;
					}
					obj_work.ofst.y = 26624 + FX_Mul(v, v2) * obj_work.user_timer / 16;
				}
				int num4 = j + 5 * i;
				float num5 = FX_FX32_TO_F32(53248 * num4);
				float num6 = FX_FX32_TO_F32(obj_work.ofst.y);
				int num7 = offset + num4 * 6;
				buffer[num7].Tex.u = (buffer[num7 + 1].Tex.u = 0.1f);
				buffer[num7 + 2].Tex.u = (buffer[num7 + 3].Tex.u = 0.9f);
				buffer[num7].Tex.v = (buffer[num7 + 2].Tex.v = 0.1f);
				buffer[num7 + 1].Tex.v = (buffer[num7 + 3].Tex.v = 0.9f);
				buffer[num7].Col = col;
				buffer[num7 + 1].Col = (buffer[num7 + 2].Col = (buffer[num7 + 3].Col = buffer[num7].Col));
				buffer[num7].Pos.x = (buffer[num7 + 1].Pos.x = 6.5f + num5);
				buffer[num7 + 2].Pos.x = (buffer[num7 + 3].Pos.x = -6.5f + num5);
				buffer[num7].Pos.y = (buffer[num7 + 2].Pos.y = 13f - num6);
				buffer[num7 + 1].Pos.y = (buffer[num7 + 3].Pos.y = -0f - num6);
				buffer[num7].Pos.z = (buffer[num7 + 1].Pos.z = (buffer[num7 + 2].Pos.z = (buffer[num7 + 3].Pos.z = -1f)));
				buffer[num7 + 4] = buffer[num7 + 2];
				buffer[num7 + 5] = buffer[num7 + 3];
				buffer[num7 + 3] = buffer[num7 + 1];
			}
		}
		amMatrixPush(nNS_MATRIX);
		ObjDraw3DNNDrawPrimitive(aMS_PARAM_DRAW_PRIMITIVE);
		amMatrixPop();
		GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Release(aMS_PARAM_DRAW_PRIMITIVE);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
	}

	public static void gmGmkBridgeDecoDrawFunc(OBS_OBJECT_WORK obj_work)
	{
