		gMS_GMK_BOBJ_WORK.gmk_work.ene_com.col_work.obj_col.height = (ushort)tbl_gm_gmk_bobj_col_rect[gMS_GMK_BOBJ_WORK.zone_type][1];
		gMS_GMK_BOBJ_WORK.gmk_work.ene_com.col_work.obj_col.ofst_x = tbl_gm_gmk_bobj_col_rect[gMS_GMK_BOBJ_WORK.zone_type][2];
		gMS_GMK_BOBJ_WORK.gmk_work.ene_com.col_work.obj_col.ofst_y = tbl_gm_gmk_bobj_col_rect[gMS_GMK_BOBJ_WORK.zone_type][3];
		gMS_GMK_BOBJ_WORK.gmk_work.ene_com.col_work.obj_col.dir = 0;
		gMS_GMK_BOBJ_WORK.breakrect_left = (short)(gMS_GMK_BOBJ_WORK.gmk_work.ene_com.col_work.obj_col.ofst_x - 4);
		gMS_GMK_BOBJ_WORK.breakrect_right = (short)(gMS_GMK_BOBJ_WORK.breakrect_left + gMS_GMK_BOBJ_WORK.gmk_work.ene_com.col_work.obj_col.width + 4);
		gMS_GMK_BOBJ_WORK.breakrect_top = (short)(gMS_GMK_BOBJ_WORK.gmk_work.ene_com.col_work.obj_col.ofst_y - 4);
		gMS_GMK_BOBJ_WORK.gmk_work.ene_com.rect_work[1].flag &= 4294967291u;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_GMK_BOBJ_WORK.gmk_work.ene_com.rect_work[0];
		oBS_RECT_WORK.ppDef = gmGmkBreakObjHit;
		oBS_RECT_WORK.ppHit = null;
		ObjRectAtkSet(oBS_RECT_WORK, 0, 0);
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		ObjRectWorkSet(oBS_RECT_WORK, tbl_gm_gmk_bobj_col_rect[gMS_GMK_BOBJ_WORK.zone_type][4], tbl_gm_gmk_bobj_col_rect[gMS_GMK_BOBJ_WORK.zone_type][5], tbl_gm_gmk_bobj_col_rect[gMS_GMK_BOBJ_WORK.zone_type][6], tbl_gm_gmk_bobj_col_rect[gMS_GMK_BOBJ_WORK.zone_type][7]);
		oBS_RECT_WORK = gMS_GMK_BOBJ_WORK.gmk_work.ene_com.rect_work[2];
		oBS_RECT_WORK.ppDef = null;
		oBS_RECT_WORK.ppHit = null;
		ObjRectAtkSet(oBS_RECT_WORK, 0, 0);
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		ObjRectWorkSet(oBS_RECT_WORK, gMS_GMK_BOBJ_WORK.breakrect_left, gMS_GMK_BOBJ_WORK.breakrect_top, gMS_GMK_BOBJ_WORK.breakrect_right, 0);
		gMS_GMK_BOBJ_WORK.hitpass = false;
		gMS_GMK_BOBJ_WORK.hitcheck = 0;
		obj_work.ppFunc = gmGmkBreakObjStay;
