	public static void gmGmkBreakObjStay(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_BOBJ_WORK gMS_GMK_BOBJ_WORK = (GMS_GMK_BOBJ_WORK)obj_work;
		if (!gMS_GMK_BOBJ_WORK.hitpass && gMS_GMK_BOBJ_WORK.hitcheck != 0)
		{
