		gMS_GMK_BOBJ_WORK.hitpass = false;
	}

	private static void gmGmkBreakObjHit(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		OBS_OBJECT_WORK parent_obj = mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_PLAYER_WORK != g_gm_main_system.ply_work[0])
		{
			return;
		}
		GMS_GMK_BOBJ_WORK gMS_GMK_BOBJ_WORK = (GMS_GMK_BOBJ_WORK)parent_obj;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_GMK_BOBJ_WORK.gmk_work.ene_com.obj_work.rect_work[0];
		if (gMS_PLAYER_WORK.act_state != 39 && gMS_PLAYER_WORK.act_state != 31 && (gMS_PLAYER_WORK.player_flag & 0x40000) == 0)
		{
			return;
		}
		short num2;
		short num3;
		short num = (num2 = (num3 = 0));
		ushort vect = 0;
		if (parent_obj.pos.x >= gMS_PLAYER_WORK.obj_work.pos.x)
		{
			num = (short)((parent_obj.pos.x >> 12) + oBS_RECT_WORK.rect.left - match_rect.rect.right);
			num = (short)((gMS_PLAYER_WORK.obj_work.pos.x >> 12) - num);
			gMS_GMK_BOBJ_WORK.hitcheck = 1;
		}
		else
		{
			num2 = (short)((parent_obj.pos.x >> 12) + oBS_RECT_WORK.rect.right - match_rect.rect.left - (gMS_PLAYER_WORK.obj_work.pos.x >> 12));
			gMS_GMK_BOBJ_WORK.hitcheck = 1;
			vect = 32768;
		}
		if (parent_obj.pos.y >= gMS_PLAYER_WORK.obj_work.pos.y)
		{
			num3 = (short)((parent_obj.pos.y >> 12) + oBS_RECT_WORK.rect.top - match_rect.rect.bottom);
			num3 = (short)((gMS_PLAYER_WORK.obj_work.pos.y >> 12) - num3);
			gMS_GMK_BOBJ_WORK.hitcheck = 1;
		}
		if (oBS_RECT_WORK.rect.right > gMS_GMK_BOBJ_WORK.breakrect_right)
		{
			oBS_RECT_WORK.rect.right -= num2;
			if (oBS_RECT_WORK.rect.right < gMS_GMK_BOBJ_WORK.breakrect_right)
			{
				oBS_RECT_WORK.rect.right = gMS_GMK_BOBJ_WORK.breakrect_right;
			}
		}
		if (oBS_RECT_WORK.rect.left < gMS_GMK_BOBJ_WORK.breakrect_left)
		{
			oBS_RECT_WORK.rect.left += num;
			if (oBS_RECT_WORK.rect.left > gMS_GMK_BOBJ_WORK.breakrect_left)
			{
				oBS_RECT_WORK.rect.left = gMS_GMK_BOBJ_WORK.breakrect_left;
			}
		}
		if (oBS_RECT_WORK.rect.top < gMS_GMK_BOBJ_WORK.breakrect_top)
		{
			oBS_RECT_WORK.rect.top += num3;
			if (oBS_RECT_WORK.rect.top > gMS_GMK_BOBJ_WORK.breakrect_top)
			{
				oBS_RECT_WORK.rect.top = gMS_GMK_BOBJ_WORK.breakrect_top;
			}
		}
		gMS_GMK_BOBJ_WORK.hitpass = true;
		short num4 = (short)(gMS_PLAYER_WORK.obj_work.spd.x >> 12);
		short num5 = (short)(gMS_PLAYER_WORK.obj_work.spd.y >> 12);
		if ((oBS_RECT_WORK.rect.right + num4 > gMS_GMK_BOBJ_WORK.breakrect_right && oBS_RECT_WORK.rect.left + num4 < gMS_GMK_BOBJ_WORK.breakrect_left) || oBS_RECT_WORK.rect.top + num5 < gMS_GMK_BOBJ_WORK.breakrect_top)
		{
			return;
		}
		ushort efct_zone_idx = tbl_gmk_breakobj_effect[gMS_GMK_BOBJ_WORK.zone_type];
		switch (gMS_GMK_BOBJ_WORK.zone_type)
		{
		case 0:
			if (g_gs_main_sys_info.stage_id == 2)
			{
				efct_zone_idx = 3;
			}
			break;
		case 2:
			if (g_gm_main_system.water_level != ushort.MaxValue && g_gm_main_system.water_level < (parent_obj.pos.y >> 12) + gMS_GMK_BOBJ_WORK.breakrect_top)
			{
				efct_zone_idx = 11;
			}
			break;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)GmEfctZoneEsCreate(null, gMS_GMK_BOBJ_WORK.zone_type, efct_zone_idx);
		oBS_OBJECT_WORK.pos.x = parent_obj.pos.x;
		oBS_OBJECT_WORK.pos.y = parent_obj.pos.y;
		oBS_OBJECT_WORK.pos.z = parent_obj.pos.z;
		gmGmkBreakObj_CreateParts(parent_obj, gMS_GMK_BOBJ_WORK.zone_type, vect);
		gMS_GMK_BOBJ_WORK.gmk_work.ene_com.obj_work.col_work.obj_col.obj = null;
		GmEnemyDefaultDefFunc(mine_rect, match_rect);
		GmSoundPlaySE("BreakOBJ");
		GmPlayerAddScore(gMS_PLAYER_WORK, 100, parent_obj.pos.x, parent_obj.pos.y);
	}

	public static void gmGmkBreakObj_CreateParts(OBS_OBJECT_WORK parent_obj, int type, ushort vect)
	{
		int num = 0;
		for (int i = 0; i < GMS_GMK_BOBJ_PARTS_PARAM_TABLE[type].num; i++)
		{
			ushort[] array = GMS_GMK_BOBJ_PARTS_PARAM_TABLE[type].Params[num];
			GMS_GMK_BOBJ_PARTS gMS_GMK_BOBJ_PARTS = (GMS_GMK_BOBJ_PARTS)GMM_EFFECT_CREATE_WORK(() => new GMS_GMK_BOBJ_PARTS(), null, 0, "BreakObj_Parts");
			OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gMS_GMK_BOBJ_PARTS;
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_breakobj_obj_3d_list[array[0]], gMS_GMK_BOBJ_PARTS.eff_work.obj_3d);
			((NNS_MATERIAL_GLES11_DESC)oBS_OBJECT_WORK.obj_3d._object.pMatPtrList[0].pMaterial).fFlag = 2u;
			oBS_OBJECT_WORK.pos.x = parent_obj.pos.x + (short)array[1] * 4096;
			oBS_OBJECT_WORK.pos.y = parent_obj.pos.y - (short)array[2] * 4096;
			oBS_OBJECT_WORK.pos.z = parent_obj.pos.z + 1;
			vect = array[3];
			int num2 = -array[4];
			oBS_OBJECT_WORK.spd.x = mtMathCos(vect) * num2 >> 12;
			oBS_OBJECT_WORK.spd.y = -(mtMathSin(vect) * num2 >> 12);
			oBS_OBJECT_WORK.spd_add.y = 1024;
			oBS_OBJECT_WORK.dir.x = 0;
			oBS_OBJECT_WORK.dir.y = 0;
			oBS_OBJECT_WORK.dir.z = vect;
			oBS_OBJECT_WORK.move_flag |= 256u;
			oBS_OBJECT_WORK.disp_flag |= 4194304u;
			oBS_OBJECT_WORK.disp_flag &= 4294967039u;
			oBS_OBJECT_WORK.flag |= 2u;
			gMS_GMK_BOBJ_PARTS.falltimer = 60;
			num++;
			oBS_OBJECT_WORK.ppFunc = gmGmkBreakObjParts_Main;
		}
	}

	public static void gmGmkBreakObjParts_Main(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_BOBJ_PARTS gMS_GMK_BOBJ_PARTS = (GMS_GMK_BOBJ_PARTS)obj_work;
		obj_work.dir.z += 512;
		gMS_GMK_BOBJ_PARTS.falltimer--;
		if (gMS_GMK_BOBJ_PARTS.falltimer <= 0)
		{
			obj_work.flag |= 8u;
		}
	}

