	private static OBS_ACTION3D_NN_WORK[] GmGameDBuildRegBuildModel(AMS_AMB_HEADER mdl_amb, AMS_AMB_HEADER tex_amb, uint draw_flag, TXB_HEADER txb)
	{
		GMS_GDBUILD_BUILD_MDL_WORK gMS_GDBUILD_BUILD_MDL_WORK = gm_obj_build_model_work_buf[gm_obj_build_model_work_reg_num];
		gm_obj_build_model_work_reg_num++;
		gMS_GDBUILD_BUILD_MDL_WORK.num = mdl_amb.file_num;
		gMS_GDBUILD_BUILD_MDL_WORK.obj_3d_list = New<OBS_ACTION3D_NN_WORK>(gMS_GDBUILD_BUILD_MDL_WORK.num);
		gMS_GDBUILD_BUILD_MDL_WORK.mdl_amb = mdl_amb;
		gMS_GDBUILD_BUILD_MDL_WORK.tex_amb = tex_amb;
		gMS_GDBUILD_BUILD_MDL_WORK.draw_flag = draw_flag;
		gMS_GDBUILD_BUILD_MDL_WORK.txb = txb;
		gMS_GDBUILD_BUILD_MDL_WORK.build_state = GME_GAME_DBUILD_MDL_STATE.GME_GAME_DBUILD_MDL_STATE_REG_WAIT;
		return gMS_GDBUILD_BUILD_MDL_WORK.obj_3d_list;
	}

	private static bool GmGameDBuildCheckBuildModel()
	{
		ArrayPointer<GMS_GDBUILD_BUILD_MDL_WORK> arrayPointer = null;
		ArrayPointer<OBS_ACTION3D_NN_WORK> arrayPointer2 = null;
		bool result = true;
		if (gm_obj_build_model_work_reg_num != 0)
		{
			int num = gm_obj_build_model_work_reg_num - 1;
			arrayPointer = new ArrayPointer<GMS_GDBUILD_BUILD_MDL_WORK>(gm_obj_build_model_work_buf, num);
			while (num >= 0)
			{
				if ((~arrayPointer).build_state == (GME_GAME_DBUILD_MDL_STATE)GME_GAME_DBUILD_MDL_STATE_REG_WAIT)
				{
					int num2 = (~arrayPointer).reg_num;
					arrayPointer2 = new ArrayPointer<OBS_ACTION3D_NN_WORK>((~arrayPointer).obj_3d_list, num2);
					if ((~arrayPointer).txb == null)
					{
						while (GsMainSysGetDisplayListRegistNum() <= 188 && num2 < (~arrayPointer).num)
						{
							ObjAction3dNNModelLoad(~arrayPointer2, null, null, num2, (~arrayPointer).mdl_amb, null, (~arrayPointer).tex_amb, (~arrayPointer).draw_flag);
							num2++;
							++arrayPointer2;
						}
						if (num2 == (~arrayPointer).reg_num)
						{
							return false;
						}
						(~arrayPointer).reg_num = num2;
						if ((~arrayPointer).reg_num == (~arrayPointer).num)
						{
							(~arrayPointer).build_state = GME_GAME_DBUILD_MDL_STATE.GME_GAME_DBUILD_MDL_STATE_BUILD_WAIT;
						}
					}
					else
					{
						while (GsMainSysGetDisplayListRegistNum() <= 188 && num2 < (~arrayPointer).num)
						{
							ObjAction3dNNModelLoadTxb(arrayPointer2, null, null, num2, (~arrayPointer).mdl_amb, null, (~arrayPointer).tex_amb, (~arrayPointer).draw_flag, (~arrayPointer).txb);
							num2++;
							++arrayPointer2;
						}
						if (num2 == (~arrayPointer).reg_num)
						{
							return false;
						}
						(~arrayPointer).reg_num = num2;
						if ((~arrayPointer).reg_num == (~arrayPointer).num)
						{
							(~arrayPointer).build_state = GME_GAME_DBUILD_MDL_STATE.GME_GAME_DBUILD_MDL_STATE_BUILD_WAIT;
						}
					}
					result = false;
				}
				else if ((~arrayPointer).build_state == (GME_GAME_DBUILD_MDL_STATE)GME_GAME_DBUILD_MDL_STATE_BUILD_WAIT)
				{
					arrayPointer2 = new ArrayPointer<OBS_ACTION3D_NN_WORK>((~arrayPointer).obj_3d_list);
					int num2 = 0;
					while (num2 < (~arrayPointer).num)
					{
						if (!ObjAction3dNNModelLoadCheck(~arrayPointer2))
						{
							result = false;
							break;
						}
						num2++;
						++arrayPointer2;
					}
					if (num2 >= (~arrayPointer).num && num == gm_obj_build_model_work_reg_num - 1)
					{
						gm_obj_build_model_work_reg_num--;
					}
				}
				num--;
				--arrayPointer;
			}
		}
		return result;
	}

