	}

	private static OBS_OBJECT_WORK GmEneKamaInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENE_KAMA_WORK(), "ENE_KAMA");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_kama_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(701), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.z = 0;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -11, -24, 11, 0);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -32, 19, 0);
		oBS_RECT_WORK.flag |= 4u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -32, 19, 0);
		oBS_RECT_WORK.flag &= 4294967291u;
		ObjObjectFieldRectSet(oBS_OBJECT_WORK, -4, -8, 4, 0);
		oBS_OBJECT_WORK.move_flag |= 128u;
		if ((eve_rec.flag & 1) == 0)
		{
			oBS_OBJECT_WORK.disp_flag |= 1u;
		}
		if ((eve_rec.flag & 2) != 0)
		{
			oBS_OBJECT_WORK.disp_flag |= 2u;
			oBS_OBJECT_WORK.move_flag &= 4294967167u;
			oBS_OBJECT_WORK.dir.z = (ushort)AKM_DEGtoA16(180);
			oBS_OBJECT_WORK.disp_flag ^= 1u;
		}
		gMS_ENE_KAMA_WORK.atk_wait = 0;
		if ((eve_rec.flag & 4) != 0)
		{
			gMS_ENE_KAMA_WORK.atk_wait += 10;
		}
		if ((eve_rec.flag & 8) != 0)
		{
			gMS_ENE_KAMA_WORK.atk_wait += 20;
		}
		if ((eve_rec.flag & 0x10) != 0)
		{
			gMS_ENE_KAMA_WORK.atk_wait += 30;
		}
		gMS_ENE_KAMA_WORK.walk_s = 0;
		if ((eve_rec.flag & 0x20) != 0)
		{
			gMS_ENE_KAMA_WORK.walk_s = 1;
		}
		oBS_OBJECT_WORK.user_work = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left << 12));
		oBS_OBJECT_WORK.user_flag = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left + eve_rec.width << 12));
		gMS_ENE_KAMA_WORK.spd_dec = 102;
		gMS_ENE_KAMA_WORK.spd_dec_dist = 20480;
		gmEneKamaWalkInit(oBS_OBJECT_WORK);
		gMS_ENE_KAMA_WORK.attack = 0;
		GmEneUtilInitNodeMatrix(gMS_ENE_KAMA_WORK.node_work, oBS_OBJECT_WORK, 32);
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmEneKamaExit);
		GmEneUtilGetNodeMatrix(gMS_ENE_KAMA_WORK.node_work, 9);
		GmEneUtilGetNodeMatrix(gMS_ENE_KAMA_WORK.node_work, 6);
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GmEventMgrLocalEventBirth(311, oBS_OBJECT_WORK.pos.x, oBS_OBJECT_WORK.pos.y, 0, 0, 0, 0, 0, 0);
		oBS_OBJECT_WORK2.parent_obj = oBS_OBJECT_WORK;
		oBS_OBJECT_WORK2 = GmEventMgrLocalEventBirth(312, oBS_OBJECT_WORK.pos.x, oBS_OBJECT_WORK.pos.y, 0, 0, 0, 0, 0, 0);
		oBS_OBJECT_WORK2.parent_obj = oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		oBS_OBJECT_WORK.flag |= 1073741824u;
		return oBS_OBJECT_WORK;
	}

	private static OBS_OBJECT_WORK GmEneKamaLeftHandInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		return gmEneKamaHandInit(eve_rec, pos_x, pos_y, 1);
	}

	private static OBS_OBJECT_WORK GmEneKamaRightHandInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		return gmEneKamaHandInit(eve_rec, pos_x, pos_y, 0);
	}

	private static int gmEneKamaGetLength2N(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
		{
			return int.MaxValue;
		}
		int x = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
		int x2 = gMS_PLAYER_WORK.obj_work.pos.y - obj_work.pos.y;
		float num = FX_FX32_TO_F32(x);
		float num2 = FX_FX32_TO_F32(x2);
		return (int)(num * num + num2 * num2);
	}

	private static int gmEneKamaIsPlayerFront(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((obj_work.disp_flag & 2) != 0)
		{
			if ((obj_work.disp_flag & 1) == 0)
			{
				if (obj_work.pos.x > gMS_PLAYER_WORK.obj_work.pos.x)
				{
					return 1;
				}
			}
			else if (obj_work.pos.x < gMS_PLAYER_WORK.obj_work.pos.x)
			{
				return 1;
			}
			return 0;
		}
		if ((obj_work.disp_flag & 1) != 0)
		{
			if (obj_work.pos.x > gMS_PLAYER_WORK.obj_work.pos.x)
			{
				return 1;
			}
		}
		else if (obj_work.pos.x < gMS_PLAYER_WORK.obj_work.pos.x)
		{
			return 1;
		}
		return 0;
	}

	private static VecFx32 gmEneKamaGetPlayerVectorFx(OBS_OBJECT_WORK obj_work)
	{
		VecFx32 result = default(VecFx32);
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		int num = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
		int num2 = gMS_PLAYER_WORK.obj_work.pos.y - obj_work.pos.y;
		if (num > FX_F32_TO_FX32(1000f) || num < FX_F32_TO_FX32(-1000f))
		{
			num = 1000;
		}
		if (num2 > FX_F32_TO_FX32(1000f) || num2 < FX_F32_TO_FX32(-1000f))
		{
			num2 = 1000;
		}
		int x = FX_Mul(num, num) + FX_Mul(num2, num2);
		x = FX_Sqrt(x);
		if (x == 0)
		{
			result.x = 0;
			result.y = 0;
		}
		else
		{
			int v = FX_Div(4096, x);
			result.x = FX_Mul(num, v);
			result.y = FX_Mul(num2, v);
		}
		result.z = 0;
		return result;
	}

	private static VecFx32 gmEneKamaGetParentVectorFx(OBS_OBJECT_WORK obj_work)
	{
		VecFx32 result = default(VecFx32);
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work.parent_obj;
		int num;
		int num2;
		if (gMS_ENE_KAMA_WORK == null)
		{
			num = 1000;
			num2 = 1000;
		}
		else
		{
			num = gMS_ENE_KAMA_WORK.ene_3d_work.ene_com.obj_work.pos.x - obj_work.pos.x;
			num2 = gMS_ENE_KAMA_WORK.ene_3d_work.ene_com.obj_work.pos.y - obj_work.pos.y;
		}
		if (num > FX_F32_TO_FX32(1000f) || num < FX_F32_TO_FX32(-1000f))
		{
			num = 1000;
		}
		if (num2 > FX_F32_TO_FX32(1000f) || num2 < FX_F32_TO_FX32(-1000f))
		{
			num2 = 1000;
		}
		int num3 = FX_F32_TO_FX32(Math.Sqrt(FX_FX32_TO_F32(num) * FX_FX32_TO_F32(num) + FX_FX32_TO_F32(num2) + FX_FX32_TO_F32(num2)));
		if (num3 == 0)
		{
			result.x = 0;
			result.y = 0;
		}
		else
		{
			int v = FX_Div(4096, num3);
			result.x = FX_Mul(num, v);
			result.y = FX_Mul(num2, v);
		}
		result.z = 0;
		return result;
	}

	private static OBS_OBJECT_WORK gmEneKamaHandInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, int type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENE_KAMA_WORK(), "ENE_KAMA");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)oBS_OBJECT_WORK;
		if (type == 1)
		{
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_kama_obj_3d_list[1], gMS_ENEMY_3D_WORK.obj_3d);
		}
		else
		{
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_kama_obj_3d_list[2], gMS_ENEMY_3D_WORK.obj_3d);
		}
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.z = 0;
		gMS_ENE_KAMA_WORK.ene_3d_work.ene_com.enemy_flag |= 32768u;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -11, -24, 11, 0);
		oBS_RECT_WORK.flag &= 4294967291u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -32, 19, 0);
		oBS_RECT_WORK.flag &= 4294967291u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -32, 19, 0);
		oBS_RECT_WORK.flag &= 4294967291u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		oBS_OBJECT_WORK.move_flag &= 4294967167u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		gMS_ENE_KAMA_WORK.hand = type;
		gmEneKamaHandWaitInit(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

	private static void gmEneKamaExit(MTS_TASK_TCB tcb)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(tcb);
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)oBS_OBJECT_WORK;
		GmEneUtilExitNodeMatrix(gMS_ENE_KAMA_WORK.node_work);
		GmEnemyDefaultExit(tcb);
	}

	private static void gmEneKamaWalkInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GmEneComActionSetDependHFlip(obj_work, 6, 7);
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneKamaWalkMain;
		obj_work.move_flag &= 4294967291u;
		if ((obj_work.disp_flag & 1) != 0)
		{
			obj_work.spd.x = -2048;
		}
		else
		{
			obj_work.spd.x = 2048;
		}
		if (obj_work.user_flag == obj_work.user_work)
		{
			obj_work.spd.x = 0;
			GmEneComActionSetDependHFlip(obj_work, 8, 9);
			obj_work.disp_flag |= 4u;
		}
	}

	private static void gmEneKamaWalkMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK kama_work = (GMS_ENE_KAMA_WORK)obj_work;
		if (gmEneKamaIsPlayerFront(obj_work) != 0 && gmEneKamaGetLength2N(obj_work) <= 12544)
		{
			obj_work.ppFunc = gmEneKamaAttackInit;
			return;
		}
		if ((obj_work.disp_flag & 2) != 0)
		{
			obj_work.move_flag &= 4294967167u;
			if ((obj_work.move_flag & 1) == 0)
			{
				obj_work.spd.y -= obj_work.spd_fall;
			}
			else
			{
				obj_work.spd.y = 0;
			}
		}
		if (obj_work.user_flag != obj_work.user_work && gmEneKamaSetWalkSpeed(kama_work) != 0)
		{
			gmEneKamaFlipInit(obj_work);
		}
	}

	private static void gmEneKamaFwMain(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_timer = ObjTimeCountDown(obj_work.user_timer);
		if (obj_work.user_timer <= 0)
		{
			gmEneKamaFlipInit(obj_work);
		}
	}

	private static void gmEneKamaFlipInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		obj_work.obj_3d.blend_spd = 0.1f;
		GmEneComActionSet3DNNBlendDependHFlip(obj_work, 4, 5);
		obj_work.ppFunc = gmEneKamaFlipMain;
		obj_work.spd.x = 0;
	}

	private static void gmEneKamaFlipMain(OBS_OBJECT_WORK obj_work)
	{
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.disp_flag ^= 1u;
			obj_work.obj_3d.blend_spd = 1f;
			gmEneKamaSetWalkSpeed((GMS_ENE_KAMA_WORK)obj_work);
			gmEneKamaWalkInit(obj_work);
		}
	}

	private static void gmEneKamaAttackInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work;
		GmEneComActionSetDependHFlip(obj_work, 2, 3);
		obj_work.disp_flag &= 4294967291u;
		obj_work.ppFunc = gmEneKamaAttackPreMain;
		obj_work.move_flag &= 4294967291u;
		obj_work.spd.x = 0;
		gMS_ENE_KAMA_WORK.timer = gMS_ENE_KAMA_WORK.atk_wait;
	}

	private static void gmEneKamaAttackPreMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work;
		if ((obj_work.disp_flag & 8) != 0)
		{
			if (gMS_ENE_KAMA_WORK.timer > 0)
			{
				gMS_ENE_KAMA_WORK.timer--;
				return;
			}
			GmEneComActionSetDependHFlip(obj_work, 0, 1);
			obj_work.disp_flag &= 4294967291u;
			obj_work.ppFunc = gmEneKamaAttackMain;
			obj_work.move_flag &= 4294967291u;
			obj_work.spd.x = 0;
			gMS_ENE_KAMA_WORK.timer = 7;
		}
	}

	private static void gmEneKamaAttackMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work;
		if (gMS_ENE_KAMA_WORK.timer > 0)
		{
			gMS_ENE_KAMA_WORK.timer--;
			return;
		}
		gMS_ENE_KAMA_WORK.attack = 1;
		obj_work.ppFunc = gmEneKamaAttackWait;
	}

	private static void gmEneKamaAttackWait(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work;
		if (gMS_ENE_KAMA_WORK.ata_futa == 0)
		{
			return;
		}
		if (gMS_ENE_KAMA_WORK.timer > 0)
		{
			gMS_ENE_KAMA_WORK.timer--;
			return;
		}
		if (gmEneKamaGetLength2N(obj_work) <= 12544)
		{
			obj_work.ppFunc = gmEneKamaFlashInit;
			return;
		}
		obj_work.obj_3d.speed[0] = 2f;
		GmEneComActionSet3DNNBlendDependHFlip(obj_work, 4, 5);
		obj_work.disp_flag &= 4294967291u;
		obj_work.ppFunc = gmEneKamaFlipAtafuta;
		obj_work.spd.x = 0;
		if (gMS_ENE_KAMA_WORK.walk_s != 0)
		{
			gMS_ENE_KAMA_WORK.timer = 15;
		}
		else
		{
			gMS_ENE_KAMA_WORK.timer = 10 + mtMathRand() % 20;
		}
	}

	private static void gmEneKamaFlipAtafuta(OBS_OBJECT_WORK obj_work)
	{
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.disp_flag ^= 1u;
			gmEneKamaSetWalkSpeed((GMS_ENE_KAMA_WORK)obj_work);
			GmEneComActionSetDependHFlip(obj_work, 6, 7);
			obj_work.disp_flag |= 4u;
			if ((obj_work.disp_flag & 1) != 0)
			{
				obj_work.spd.x = -2048;
			}
			else
			{
				obj_work.spd.x = 2048;
			}
			obj_work.ppFunc = gmEneKamaAttackWait;
		}
	}

	private static void gmEneKamaFlashInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work;
		obj_work.spd.x = 0;
		obj_work.obj_3d.speed[0] = 1f;
		GmBsCmnClearObject3DNNFadedColor(obj_work);
		obj_work.disp_flag |= 134217728u;
		gmEneKamaFadeAnimeSet(gMS_ENE_KAMA_WORK, gm_ene_kama_blink_anime);
		obj_work.obj_3d.blend_spd = 0.125f;
		GmEneComActionSet3DNNBlendDependHFlip(obj_work, 10, 11);
		obj_work.disp_flag |= 4u;
		gMS_ENE_KAMA_WORK.timer = 180;
		obj_work.ppFunc = gmEneKamaFlashMain;
	}

	private static void gmEneKamaFlashMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work;
		gmEneKamaFadeAnimeUpdate((GMS_ENE_KAMA_WORK)obj_work, 4096, 1);
		if (gMS_ENE_KAMA_WORK.timer-- < 0)
		{
			GMS_EFFECT_3DES_WORK efct_work = GmEfctCmnEsCreate(obj_work, 9);
			if ((obj_work.disp_flag & 2) != 0)
			{
				GmComEfctSetDispOffsetF(efct_work, 0f, 20f, 0f);
			}
			else
			{
				GmComEfctSetDispOffsetF(efct_work, 0f, -20f, 0f);
			}
			gMS_ENE_KAMA_WORK.ene_3d_work.ene_com.enemy_flag |= 65536u;
			gMS_ENE_KAMA_WORK.timer = 180;
			GmSoundPlaySE("Boss2_03");
			obj_work.disp_flag |= 32u;
			obj_work.ppFunc = gmEneKamaFlashEnd;
			OBS_RECT_WORK oBS_RECT_WORK = gMS_ENE_KAMA_WORK.ene_3d_work.ene_com.rect_work[1];
			ObjRectWorkSet(oBS_RECT_WORK, -30, -30, 30, 10);
			oBS_RECT_WORK.flag |= 4u;
			GmGmkAnimalInit(obj_work, 0, 0, 0, 0, 0, 0);
			oBS_RECT_WORK = gMS_ENE_KAMA_WORK.ene_3d_work.ene_com.rect_work[0];
			oBS_RECT_WORK.flag &= 4294967291u;
			oBS_RECT_WORK = gMS_ENE_KAMA_WORK.ene_3d_work.ene_com.rect_work[2];
			oBS_RECT_WORK.flag &= 4294967291u;
		}
	}

	private static void gmEneKamaFlashEnd(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENE_KAMA_WORK.ene_3d_work.ene_com.rect_work[1];
		oBS_RECT_WORK.flag &= 4294967291u;
		if (gMS_ENE_KAMA_WORK.timer-- < 0)
		{
			obj_work.flag |= 8u;
		}
	}

	private static int gmEneKamaSetWalkSpeed(GMS_ENE_KAMA_WORK kama_work)
	{
		int result = 0;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)kama_work;
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			if (oBS_OBJECT_WORK.obj_3d.act_id[0] == 5 && oBS_OBJECT_WORK.obj_3d.frame[0] >= 20f)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, kama_work.spd_dec, 2048);
			}
			else if (oBS_OBJECT_WORK.pos.x <= (int)oBS_OBJECT_WORK.user_work + kama_work.spd_dec_dist)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdDownSet(oBS_OBJECT_WORK.spd.x, kama_work.spd_dec);
				result = 1;
				if (oBS_OBJECT_WORK.spd.x == 0 && oBS_OBJECT_WORK.pos.x > (int)oBS_OBJECT_WORK.user_work)
				{
					oBS_OBJECT_WORK.spd.x = (int)oBS_OBJECT_WORK.user_work - oBS_OBJECT_WORK.pos.x;
					if (oBS_OBJECT_WORK.spd.x < -kama_work.spd_dec)
					{
						oBS_OBJECT_WORK.spd.x = -kama_work.spd_dec;
					}
				}
			}
			else if (oBS_OBJECT_WORK.spd.x > -2048)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, -kama_work.spd_dec, 2048);
			}
		}
		else if (oBS_OBJECT_WORK.obj_3d.act_id[0] == 4 && oBS_OBJECT_WORK.obj_3d.frame[0] >= 20f)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, -kama_work.spd_dec, 2048);
		}
		else if (oBS_OBJECT_WORK.pos.x >= (int)oBS_OBJECT_WORK.user_flag - kama_work.spd_dec_dist)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdDownSet(oBS_OBJECT_WORK.spd.x, kama_work.spd_dec);
			result = 1;
			if (oBS_OBJECT_WORK.spd.x == 0 && oBS_OBJECT_WORK.pos.x < (int)oBS_OBJECT_WORK.user_flag)
			{
				oBS_OBJECT_WORK.spd.x = (int)oBS_OBJECT_WORK.user_flag - oBS_OBJECT_WORK.pos.x;
				if (oBS_OBJECT_WORK.spd.x > kama_work.spd_dec)
				{
					oBS_OBJECT_WORK.spd.x = kama_work.spd_dec;
				}
			}
		}
		else if (oBS_OBJECT_WORK.spd.x < 2048)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, kama_work.spd_dec, 2048);
		}
		return result;
	}

	private static void gmEneKamaHandWaitInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work;
		gMS_ENE_KAMA_WORK.rot_z = 0;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENE_KAMA_WORK.ene_3d_work.ene_com.rect_work[1];
		oBS_RECT_WORK.flag &= 4294967291u;
		obj_work.ofst.x = 0;
		obj_work.ofst.y = 0;
		obj_work.dir.z = 0;
		obj_work.flag &= 4294966783u;
		obj_work.ppFunc = gmEneKamaHandWaitMain;
	}

	private static void gmEneKamaHandWaitMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work;
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK2 = (GMS_ENE_KAMA_WORK)obj_work.parent_obj;
		NNS_MATRIX nNS_MATRIX = gmEneKamaHandWaitMain_msm;
		if (obj_work.parent_obj == null)
		{
			obj_work.spd.x = 0;
			obj_work.spd_fall = FX_F32_TO_FX32(0.2f);
			obj_work.move_flag |= 128u;
			return;
		}
		NNS_MATRIX nNS_MATRIX2 = ((gMS_ENE_KAMA_WORK.hand != 1) ? GmEneUtilGetNodeMatrix(gMS_ENE_KAMA_WORK2.node_work, 6) : GmEneUtilGetNodeMatrix(gMS_ENE_KAMA_WORK2.node_work, 9));
		if (nNS_MATRIX2.M03 != 0f || nNS_MATRIX2.M13 != 0f)
		{
			nnMakeScaleMatrix(nNS_MATRIX, 1f, 1f, 1f);
			nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX2, nNS_MATRIX);
			GmEneUtilSetMatrixNN(obj_work, nNS_MATRIX);
			if (gMS_ENE_KAMA_WORK2.attack != 0)
			{
				obj_work.ppFunc = gmEneKamaHandAttackInit;
			}
		}
	}

	private static void gmEneKamaHandAttackInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work;
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK2 = (GMS_ENE_KAMA_WORK)obj_work.parent_obj;
		VecFx32 vecFx = gmEneKamaGetPlayerVectorFx(obj_work);
		obj_work.spd.x = (int)((float)vecFx.x * 1.75f);
		obj_work.spd.y = (int)((float)vecFx.y * 1.75f);
		obj_work.ppFunc = gmEneKamaHandAttackMain;
		gMS_ENE_KAMA_WORK.timer = 120;
		if ((gMS_ENE_KAMA_WORK2.ene_3d_work.ene_com.obj_work.disp_flag & 2) != 0)
		{
			obj_work.disp_flag |= 2u;
		}
		if ((gMS_ENE_KAMA_WORK2.ene_3d_work.ene_com.obj_work.disp_flag & 1) != 0)
		{
			gMS_ENE_KAMA_WORK.rot_z_add = -AKM_DEGtoA32(15);
		}
		else
		{
			gMS_ENE_KAMA_WORK.rot_z_add = AKM_DEGtoA32(15);
		}
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENE_KAMA_WORK.ene_3d_work.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -8, -8, 8, 8);
		oBS_RECT_WORK.flag |= 4u;
		obj_work.flag |= 512u;
		obj_work.pos.z = 655360;
		GmSoundPlaySE("Kama");
	}

	private static void gmEneKamaHandAttackMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK = (GMS_ENE_KAMA_WORK)obj_work;
		gMS_ENE_KAMA_WORK.rot_z += gMS_ENE_KAMA_WORK.rot_z_add;
		NNS_MATRIX nNS_MATRIX = gmEneKamaHandAttackMain_rmat;
		NNS_MATRIX nNS_MATRIX2 = gmEneKamaHandAttackMain_tmat;
		NNS_MATRIX nNS_MATRIX3 = gmEneKamaHandAttackMain_mat;
		nnMakeRotateZMatrix(nNS_MATRIX, gMS_ENE_KAMA_WORK.rot_z);
		if ((obj_work.disp_flag & 2) != 0)
		{
			nnMakeTranslateMatrix(nNS_MATRIX2, 10f, 10f, 0f);
		}
		else
		{
			nnMakeTranslateMatrix(nNS_MATRIX2, 10f, -10f, 0f);
		}
		nnMultiplyMatrix(nNS_MATRIX3, nNS_MATRIX, nNS_MATRIX2);
		obj_work.ofst.x = FX_F32_TO_FX32(nNS_MATRIX3.M03);
		obj_work.ofst.y = FX_F32_TO_FX32(nNS_MATRIX3.M13);
		obj_work.dir.z = (ushort)gMS_ENE_KAMA_WORK.rot_z;
		if (gMS_ENE_KAMA_WORK.timer > 0)
		{
			VecFx32 vecFx = gmEneKamaGetPlayerVectorFx(obj_work);
			int v = (int)((float)obj_work.spd.x / 1.75f);
			int v2 = (int)((float)obj_work.spd.y / 1.75f);
			int num = FX_Mul(vecFx.x, v2) - FX_Mul(vecFx.y, v);
			if (num < 0)
			{
				v = FX_Mul(FX_Cos((short)AKM_DEGtoA32(1f)), v) - FX_Mul(FX_Sin((short)AKM_DEGtoA32(1f)), v2);
				v2 = FX_Mul(FX_Sin((short)AKM_DEGtoA32(1f)), v) + FX_Mul(FX_Cos((short)AKM_DEGtoA32(1f)), v2);
			}
			else
			{
				v = FX_Mul(FX_Cos((short)AKM_DEGtoA32(-1f)), v) - FX_Mul(FX_Sin((short)AKM_DEGtoA32(-1f)), v2);
				v2 = FX_Mul(FX_Sin((short)AKM_DEGtoA32(-1f)), v) + FX_Mul(FX_Cos((short)AKM_DEGtoA32(-1f)), v2);
			}
			obj_work.spd.x = (int)((float)v * 1.75f);
			obj_work.spd.y = (int)((float)v2 * 1.75f);
			gMS_ENE_KAMA_WORK.timer--;
		}
		else
		{
			obj_work.spd.x = 0;
			obj_work.spd_fall = FX_F32_TO_FX32(0.2f);
			obj_work.move_flag |= 128u;
			GMS_ENE_KAMA_WORK gMS_ENE_KAMA_WORK2 = (GMS_ENE_KAMA_WORK)obj_work.parent_obj;
			if (gMS_ENE_KAMA_WORK2 != null)
			{
				gMS_ENE_KAMA_WORK2.ata_futa = 1;
			}
		}
	}

	private static void gmEneKamaFadeAnimeSet(GMS_ENE_KAMA_WORK kama_work, GMS_ENE_KAMA_FADE_ANIME anime_data)
	{
		kama_work.anime_data = anime_data;
		kama_work.anime_pat_no = 0u;
		kama_work.anime_frame = 0;
	}

	private static void gmEneKamaFadeAnimeUpdate(GMS_ENE_KAMA_WORK kama_work, int speed, int repeat)
	{
		GMS_ENE_KAMA_FADE_ANIME anime_data = kama_work.anime_data;
		GMS_ENE_KAMA_FADE_ANIME_PAT gMS_ENE_KAMA_FADE_ANIME_PAT = anime_data.anime_pat[kama_work.anime_pat_no];
		kama_work.anime_frame += speed;
		while (kama_work.anime_frame >= gMS_ENE_KAMA_FADE_ANIME_PAT.frame)
		{
			kama_work.anime_frame -= gMS_ENE_KAMA_FADE_ANIME_PAT.frame;
			kama_work.anime_pat_no++;
			if (kama_work.anime_pat_no < anime_data.pat_num)
			{
				gMS_ENE_KAMA_FADE_ANIME_PAT = anime_data.anime_pat[kama_work.anime_pat_no];
			}
			else if (repeat != 0)
			{
				kama_work.anime_pat_no = 0u;
				gMS_ENE_KAMA_FADE_ANIME_PAT = anime_data.anime_pat[kama_work.anime_pat_no];
			}
			else
			{
				kama_work.anime_pat_no = anime_data.pat_num - 1;
				kama_work.anime_frame = gMS_ENE_KAMA_FADE_ANIME_PAT.frame - 1;
			}
		}
		GmBsCmnSetObject3DNNFadedColor((OBS_OBJECT_WORK)kama_work, gMS_ENE_KAMA_FADE_ANIME_PAT.col, gMS_ENE_KAMA_FADE_ANIME_PAT.intensity);
	}

