	private static OBS_OBJECT_WORK GmEneGabuInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "ENE_GABU");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_gabu_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(666), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.z = 0;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -11, -16, 11, 16);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -24, 19, 24);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -24, 19, 24);
		oBS_RECT_WORK.flag &= 4294967291u;
		oBS_OBJECT_WORK.move_flag |= 384u;
		oBS_OBJECT_WORK.view_out_ofst_plus[1] = -256;
		int num = -eve_rec.top << 13;
		if (num <= 0)
		{
			num = 393216;
		}
		int num2 = eve_rec.flag & 7;
		if (num2 <= 3)
		{
			oBS_OBJECT_WORK.user_timer = -24576 + -1024 * num2;
		}
		else
		{
			oBS_OBJECT_WORK.user_timer = -24576 - -1024 * (num2 - 3);
		}
		int denom = FX_Div(num * 2, -oBS_OBJECT_WORK.user_timer);
		oBS_OBJECT_WORK.spd_fall = FX_Div(-oBS_OBJECT_WORK.user_timer, denom);
		oBS_OBJECT_WORK.user_work = (uint)oBS_OBJECT_WORK.pos.y;
		ObjDrawObjectActionSet(oBS_OBJECT_WORK, 1);
		oBS_OBJECT_WORK.disp_flag |= 4u;
		gmEneGabuJumpInit(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

	private static void gmEneGabuJumpInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if (obj_work.obj_3d.act_id[0] != 1)
		{
			ObjDrawObjectActionSet3DNNBlend(obj_work, 1);
			obj_work.disp_flag |= 4u;
		}
		obj_work.ppFunc = gmEneGabuJumpMain;
		obj_work.spd.y = obj_work.user_timer;
	}

	private static void gmEneGabuJumpMain(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.obj_3d.act_id[0] != 2 && obj_work.spd.y < 0 && -obj_work.spd.y / obj_work.spd_fall <= 20)
		{
			ObjDrawObjectActionSet(obj_work, 2);
		}
		if (obj_work.obj_3d.act_id[0] == 2 && (obj_work.disp_flag & 8) != 0)
		{
			ObjDrawObjectActionSet3DNNBlend(obj_work, 0);
			obj_work.disp_flag |= 4u;
		}
		if (obj_work.pos.y >= (int)obj_work.user_work)
		{
			if ((((GMS_ENEMY_COM_WORK)obj_work).eve_rec.flag & 0x80) != 0)
			{
				gmEneGabuJumpWaitInit(obj_work);
			}
			else
			{
				gmEneGabuJumpInit(obj_work);
			}
		}
	}

	private static void gmEneGabuJumpWaitInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		ObjDrawObjectActionSet3DNNBlend(obj_work, 1);
		obj_work.disp_flag |= 4u;
		obj_work.user_flag = 61440u;
		obj_work.ppFunc = gmEneGabuJumpWaitMain;
		obj_work.spd.y = 0;
		obj_work.move_flag &= 4294967167u;
	}

	private static void gmEneGabuJumpWaitMain(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_flag = (uint)ObjTimeCountDown((int)obj_work.user_flag);
		if (obj_work.user_flag == 0)
		{
			obj_work.move_flag |= 128u;
			gmEneGabuJumpInit(obj_work);
		}
	}

