	public static bool GmEfctBossCmnFlushDataLoop()
	{
		bool flag = true;
		int num = 0;
		if (gm_efct_boss_cmn_model_reg_num != 0)
		{
			for (int i = 0; i < 6; i++)
			{
				GMS_EFCT_BOSS_CMN_CREATE_PARAM gMS_EFCT_BOSS_CMN_CREATE_PARAM = gm_efct_boss_cmn_create_param_tbl[i];
				if (gMS_EFCT_BOSS_CMN_CREATE_PARAM.create_param.model_idx == -1)
				{
					continue;
				}
				if (gm_efct_boss_cmn_model_reg_id_list[num] != -1)
				{
					int index = gmEfctBossCmnGetObjectDworkNo(i);
					if (ObjAction3dESModelReleaseDworkCheck(ObjDataGet(index), gm_efct_boss_cmn_model_reg_id_list[num]))
					{
						gm_efct_boss_cmn_model_reg_id_list[num] = -1;
					}
					else
					{
						flag = false;
					}
				}
				if (gm_efct_boss_cmn_mdl_tex_reg_id_list[num] != -1)
				{
					if (ObjAction3dESTextureReleaseDworkCheck(ObjDataGet(gmEfctBossCmnGetMdlTexlistDworkNo(i)), gm_efct_boss_cmn_mdl_tex_reg_id_list[num]))
					{
						gm_efct_boss_cmn_mdl_tex_reg_id_list[num] = -1;
					}
					else
					{
						flag = false;
					}
				}
				num++;
			}
		}
		if (gm_efct_boss_cmn_tex_reg_id != -1)
		{
			if (ObjAction3dESTextureReleaseDworkCheck(ObjDataGet(622), gm_efct_boss_cmn_tex_reg_id))
			{
				gm_efct_boss_cmn_tex_reg_id = -1;
			}
			else
			{
				flag = false;
			}
		}
		if (flag)
		{
			if (gm_efct_boss_cmn_mdl_tex_reg_id_list != null)
			{
				gm_efct_boss_cmn_mdl_tex_reg_id_list = null;
			}
