		for (int i = 0; i < gm_efct_boss_single_reg_num; i++)
		{
			GMS_EFCT_BOSS_SINGLE_BUILD_WORK gMS_EFCT_BOSS_SINGLE_BUILD_WORK = gm_efct_boss_single_build_list[i];
			if (gMS_EFCT_BOSS_SINGLE_BUILD_WORK.model_reg_id != -1)
			{
				if (ObjAction3dESModelReleaseDworkCheck(gMS_EFCT_BOSS_SINGLE_BUILD_WORK.object_dwork, gMS_EFCT_BOSS_SINGLE_BUILD_WORK.model_reg_id))
				{
					gMS_EFCT_BOSS_SINGLE_BUILD_WORK.model_reg_id = -1;
					gMS_EFCT_BOSS_SINGLE_BUILD_WORK.object_dwork = null;
				}
				else
				{
					flag = false;
				}
			}
			if (gMS_EFCT_BOSS_SINGLE_BUILD_WORK.tex_reg_id != -1)
			{
				if (ObjAction3dESTextureReleaseDworkCheck(gMS_EFCT_BOSS_SINGLE_BUILD_WORK.texlist_dwork, gMS_EFCT_BOSS_SINGLE_BUILD_WORK.tex_reg_id))
				{
					gMS_EFCT_BOSS_SINGLE_BUILD_WORK.tex_reg_id = -1;
					gMS_EFCT_BOSS_SINGLE_BUILD_WORK.texlist_dwork = null;
				}
				else
				{
					flag = false;
				}
			}
		}
		if (flag)
		{
			gm_efct_boss_single_reg_num = 0;
		}
		return flag;
	}

	public static GMS_EFFECT_3DES_WORK GmEfctBossCmnEsCreate(OBS_OBJECT_WORK parent_obj, uint efct_bscmn_idx)
	{
		GMS_EFCT_BOSS_CMN_CREATE_PARAM gMS_EFCT_BOSS_CMN_CREATE_PARAM = gm_efct_boss_cmn_create_param_tbl[efct_bscmn_idx];
		OBS_DATA_WORK model_dwork;
		OBS_DATA_WORK object_dwork;
		OBS_DATA_WORK oBS_DATA_WORK;
		OBS_DATA_WORK texlist_dwork;
		if (gMS_EFCT_BOSS_CMN_CREATE_PARAM.create_param.model_idx != -1)
		{
			int ame_idx = gMS_EFCT_BOSS_CMN_CREATE_PARAM.create_param.ame_idx;
			model_dwork = ObjDataGet(gmEfctBossCmnGetModelDworkNo(ame_idx));
			object_dwork = ObjDataGet(gmEfctBossCmnGetObjectDworkNo(ame_idx));
			oBS_DATA_WORK = ObjDataGet(gmEfctBossCmnGetMdlAmbtexDworkNo(ame_idx));
			texlist_dwork = ObjDataGet(gmEfctBossCmnGetMdlTexlistDworkNo(ame_idx));
		}
		else
		{
			model_dwork = null;
			object_dwork = null;
			oBS_DATA_WORK = ObjDataGet(621);
			texlist_dwork = ObjDataGet(622);
		}
		return GmEffect3dESCreateByParam(gMS_EFCT_BOSS_CMN_CREATE_PARAM.create_param, parent_obj, ObjDataGet(15).pData, ObjDataGet(gmEfctBossCmnGetAmeDworkNo(gMS_EFCT_BOSS_CMN_CREATE_PARAM.create_param.ame_idx)), oBS_DATA_WORK, texlist_dwork, model_dwork, object_dwork);
	}

