	public static OBS_OBJECT_WORK GmBoss5EggInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_BOSS5_EGG_WORK(), "BOSS5_EGG");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_BOSS5_EGG_WORK gMS_BOSS5_EGG_WORK = (GMS_BOSS5_EGG_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.pos.z = GMD_BOSS5_BG_FARSIDE_POS_Z;
		ObjObjectFieldRectSet(oBS_OBJECT_WORK, -16, -16, 16, 0);
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, GmBoss5GetObject3dList()[2], gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(746), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.obj_3d.blend_spd = GMD_BOSS5_DEFAULT_BLEND_SPD;
		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.disp_flag &= 4290772991u;
		oBS_OBJECT_WORK.disp_flag &= 4294967294u;
		oBS_OBJECT_WORK.move_flag |= 1152u;
		oBS_OBJECT_WORK.move_flag &= 4294967039u;
		gMS_BOSS5_EGG_WORK.ene_3d.ene_com.enemy_flag |= 32768u;
		oBS_OBJECT_WORK.ppFunc = gmBoss5EggMain;
		gmBoss5EggProcInit(gMS_BOSS5_EGG_WORK);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

	public static GMS_BOSS5_EGG_WORK GmBoss5EggCreate(GMS_BOSS5_BODY_WORK body_work, int pos_x, int pos_y)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GmEventMgrLocalEventBirth(334, pos_x, pos_y, 0, 0, 0, 0, 0, 0);
		oBS_OBJECT_WORK.parent_obj = GMM_BS_OBJ(body_work);
		return (GMS_BOSS5_EGG_WORK)oBS_OBJECT_WORK;
	}

	public static void gmBoss5EggInitEscapeRun(GMS_BOSS5_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.x = GmBsCmnGetPlayerObj().pos.x + (OBD_OBJ_CLIP_LCD_X << 12);
	}

	public static void gmBoss5EggUpdateEscapeRun(GMS_BOSS5_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		if (ObjViewOutCheck(oBS_OBJECT_WORK.pos.x, oBS_OBJECT_WORK.pos.y, 0, GMD_BOSS5_EGG_ESCAPE_RUN_VIEWOUT_OFST_LEFT, 0, GMD_BOSS5_EGG_ESCAPE_RUN_VIEWOUT_OFST_RIGHT, 0) == 0)
		{
			int num = oBS_OBJECT_WORK.pos.x - GmBsCmnGetPlayerObj().pos.x;
			int a = FX_Div(GMD_BOSS5_EGG_ESCAPE_RUN_DISTANCE_SLOWEST - num, GMD_BOSS5_EGG_ESCAPE_RUN_DISTANCE_SLOWEST - GMD_BOSS5_EGG_ESCAPE_RUN_DISTANCE_FASTEST);
			a = MTM_MATH_CLIP(a, 0, 4096);
			oBS_OBJECT_WORK.spd.x = FX_Mul(a, GmBsCmnGetPlayerObj().spd_m) + FX_Mul(4096 - a, GMD_BOSS5_EGG_ESCAPE_RUN_SLOWEST_SPD);
		}
	}

	public static void gmBoss5EggInitJump(GMS_BOSS5_EGG_WORK egg_work, int dest_pos_x)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		VEC_Set(ref oBS_OBJECT_WORK.spd_add, 0, 0, 0);
		oBS_OBJECT_WORK.spd.x = GMD_BOSS5_EGG_JUMP_INIT_SPD_X;
		oBS_OBJECT_WORK.spd.y = GMD_BOSS5_EGG_JUMP_INIT_SPD_Y;
		oBS_OBJECT_WORK.spd_add.y = -2 * FX_Mul(FX_Div(oBS_OBJECT_WORK.spd.x, dest_pos_x - oBS_OBJECT_WORK.pos.x), oBS_OBJECT_WORK.spd.y);
		egg_work.jump_dest_pos_x = dest_pos_x;
		oBS_OBJECT_WORK.move_flag |= 272u;
		oBS_OBJECT_WORK.move_flag &= 4294967167u;
	}

	public static int gmBoss5EggUpdateJump(GMS_BOSS5_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		if (oBS_OBJECT_WORK.pos.x >= egg_work.jump_dest_pos_x)
		{
			oBS_OBJECT_WORK.spd.x = 0;
		}
		if (oBS_OBJECT_WORK.pos.y > gMS_BOSS5_BODY_WORK.ground_v_pos + GMD_BOSS5_EGG_HIDE_HIGHT)
		{
			GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
			return 1;
		}
		return 0;
	}

	public static void gmBoss5EggGetBodyNodePos(GMS_BOSS5_EGG_WORK egg_work, out VecFx32 pos_out)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		NNS_MATRIX nNS_MATRIX = GmBsCmnGetSNMMtx(gMS_BOSS5_BODY_WORK.snm_work, gMS_BOSS5_BODY_WORK.body_snm_reg_id);
		pos_out = new VecFx32(FX_F32_TO_FX32(nNS_MATRIX.M03), -FX_F32_TO_FX32(nNS_MATRIX.M13), FX_F32_TO_FX32(nNS_MATRIX.M23));
	}

	public static void gmBoss5EggMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS5_EGG_WORK gMS_BOSS5_EGG_WORK = (GMS_BOSS5_EGG_WORK)obj_work;
		if (gMS_BOSS5_EGG_WORK.proc_update != null)
		{
			gMS_BOSS5_EGG_WORK.proc_update(gMS_BOSS5_EGG_WORK);
		}
	}

	public static void gmBoss5EggProcInit(GMS_BOSS5_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK obj_work = GMM_BS_OBJ(egg_work);
		GmBsCmnSetAction(obj_work, 0, 1, 0);
		GmBoss5EfctStartEggSweat(egg_work);
		egg_work.proc_update = gmBoss5EggProcUpdateStandby;
	}

	public static void gmBoss5EggProcUpdateStandby(GMS_BOSS5_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		GMS_BOSS5_MGR_WORK mgr_work = ((GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj).mgr_work;
		if ((mgr_work.flag & 0x400000) != 0)
		{
			gmBoss5EggInitEscapeRun(egg_work);
			egg_work.proc_update = gmBoss5EggProcUpdateRun;
		}
	}

	public static void gmBoss5EggProcUpdateRun(GMS_BOSS5_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		VecFx32 pos_out;
		gmBoss5EggGetBodyNodePos(egg_work, out pos_out);
		gmBoss5EggUpdateEscapeRun(egg_work);
		if (oBS_OBJECT_WORK.pos.x >= pos_out.x + GMD_BOSS5_EGG_JUMP_START_OFST_POS_X)
		{
			oBS_OBJECT_WORK.spd.x = GMD_BOSS5_EGG_JUMP_RUNUP_SPD_X;
			GmBsCmnSetAction(oBS_OBJECT_WORK, 1, 0, 1);
			egg_work.proc_update = gmBoss5EggProcUpdateStartJump;
		}
	}

	public static void gmBoss5EggProcUpdateStartJump(GMS_BOSS5_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		if (GmBsCmnIsActionEnd(oBS_OBJECT_WORK) != 0)
		{
			GMS_BOSS5_MGR_WORK mgr_work = ((GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj).mgr_work;
			mgr_work.flag |= 524288u;
			GmBoss5EfctEndEggSweat(egg_work);
			VecFx32 pos_out;
			gmBoss5EggGetBodyNodePos(egg_work, out pos_out);
			gmBoss5EggInitJump(egg_work, pos_out.x);
			GmBsCmnSetAction(oBS_OBJECT_WORK, 2, 0, 0);
			egg_work.proc_update = gmBoss5EggProcUpdateJump;
		}
	}

	public static void gmBoss5EggProcUpdateJump(GMS_BOSS5_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		gmBoss5EggUpdateJump(egg_work);
		if (oBS_OBJECT_WORK.spd.y > 0)
		{
			GmBsCmnSetAction(oBS_OBJECT_WORK, 3, 0, 0);
			egg_work.proc_update = gmBoss5EggProcUpdateFall;
		}
	}

	public static void gmBoss5EggProcUpdateFall(GMS_BOSS5_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		if (gmBoss5EggUpdateJump(egg_work) != 0)
		{
			VecFx32 pos_out;
			gmBoss5EggGetBodyNodePos(egg_work, out pos_out);
			oBS_OBJECT_WORK.pos.Assign(pos_out);
			GmBsCmnSetAction(oBS_OBJECT_WORK, 4, 0, 0);
			oBS_OBJECT_WORK.disp_flag |= 1u;
			egg_work.proc_update = gmBoss5EggProcUpdateAnger;
		}
	}

	public static void gmBoss5EggProcUpdateAnger(GMS_BOSS5_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		if (GmBsCmnIsActionEnd(oBS_OBJECT_WORK) != 0)
		{
			gMS_BOSS5_BODY_WORK.flag |= 16777216u;
			oBS_OBJECT_WORK.flag |= 4u;
		}
	}

	public static void DmSaveStart(uint disp_flag, bool is_first_save, bool is_task_draw)
	{
		short num = 0;
		num = SyGetEvtInfo().cur_evt_id;
		if (num != 6 && num != 11 && num != 9 && ((disp_flag & 4) == 0 || !GsTrialIsTrial()))
		{
			dm_save_mgr.Clear();
			dm_save_mgr_p = dm_save_mgr;
			dm_save_msg_flag = disp_flag;
			dm_save_first_save = is_first_save;
			dm_save_is_task_draw = is_task_draw;
			dm_save_is_snd_build = false;
			dmSaveInit();
		}
	}

	private static void DmSaveAttenMsgStart()
	{
		short cur_evt_id = SyGetEvtInfo().cur_evt_id;
		dm_save_mgr.Clear();
		dm_save_mgr_p = dm_save_mgr;
		dm_save_msg_flag = 2u;
		dm_save_first_save = false;
		dm_save_is_task_draw = false;
		dm_save_is_snd_build = true;
		dmSaveInit();
	}

	private static void DmSaveMenuStart(bool is_task_draw, bool is_snd_build)
	{
		short num = 0;
		num = SyGetEvtInfo().cur_evt_id;
		if (num != 6 && num != 11 && num != 9 && AoAccountIsCurrentEnable())
		{
			dmSaveSetSysDataForBackup();
			if (!GsTrialIsTrial() && !dmSaveIsSaveNecessary())
			{
				dm_save_mgr.Clear();
				dm_save_mgr_p = dm_save_mgr;
				dm_save_msg_flag = 4u;
				dm_save_first_save = false;
				dm_save_is_task_draw = is_task_draw;
				dm_save_is_snd_build = is_snd_build;
				dmSaveInit();
			}
		}
	}

	public static bool DmSaveIsExit()
	{
		if (dm_save_mgr_p != null)
		{
			if (dm_save_mgr_p.tcb == null)
			{
				return true;
			}
			return false;
		}
		return true;
	}

	private static bool DmSaveIsDraw()
	{
		return dm_save_draw_reserve;
	}

	private static void dmSaveInit()
	{
		dm_save_mgr_p.tcb = MTM_TASK_MAKE_TCB(dmSaveProcMain, dmSaveDest, 0u, 32767, 8192u, 0, () => new DMS_SAVE_MAIN_WORK(), "SAVE_TASK");
		DMS_SAVE_MAIN_WORK dMS_SAVE_MAIN_WORK = (DMS_SAVE_MAIN_WORK)dm_save_mgr_p.tcb.work;
		dm_save_disp_flag = 0u;
		dm_save_is_draw_state = 0u;
		dm_save_win_mode = 0;
		dm_save_draw_reserve = false;
		for (int num = 0; num < 2; num++)
		{
			dm_save_win_size_rate[num] = 0f;
			dm_save_cmn_tex[num] = null;
		}
		for (int num2 = 0; num2 < 6; num2++)
		{
			dm_save_act[num2] = null;
		}
		dMS_SAVE_MAIN_WORK.announce_flag = dm_save_msg_flag;
		dMS_SAVE_MAIN_WORK.draw_state = (AoActSysGetDrawStateEnable() ? 1u : 0u);
		if (dMS_SAVE_MAIN_WORK.draw_state != 0)
		{
			dm_save_draw_state = AoActSysGetDrawState();
		}
		else
		{
			dm_save_draw_state = 0u;
		}
		for (int num3 = 0; num3 < 2; num3++)
		{
			dm_save_cmn_tex[num3] = null;
		}
		dm_save_is_draw_state = dMS_SAVE_MAIN_WORK.draw_state;
		dMS_SAVE_MAIN_WORK.proc_menu_update = dmSaveLoadFontData;
	}

	private static void dmSaveSetSysDataForBackup()
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		SSystem sSystem = SSystem.CreateInstance();
		sSystem.SetKilled(gSS_MAIN_SYS_INFO.ene_kill_count);
		sSystem.SetPlayerStock(gSS_MAIN_SYS_INFO.rest_player_num);
	}

	private static bool dmSaveIsSaveNecessary()
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		if (gSS_MAIN_SYS_INFO.is_save_run == 0)
		{
			return true;
		}
		SSystem sSystem = SSystem.CreateInstance();
		SStage sStage = SStage.CreateInstance();
		SSpecial sSpecial = SSpecial.CreateInstance();
		SOption sOption = SOption.CreateInstance();
		SSystem system = gSS_MAIN_SYS_INFO.cmp_backup.GetSystem();
		SStage sStage2 = gSS_MAIN_SYS_INFO.cmp_backup.GetStage();
		SSpecial special = gSS_MAIN_SYS_INFO.cmp_backup.GetSpecial();
		SOption option = gSS_MAIN_SYS_INFO.cmp_backup.GetOption();
		if (sSystem.GetPlayerStock() != system.GetPlayerStock())
		{
			return false;
		}
		if (sSystem.GetKilled() != system.GetKilled())
		{
			return false;
		}
		if (sSystem.GetClearCount() != system.GetClearCount())
		{
			return false;
		}
		for (int i = 0; i < 7; i++)
		{
			SSystem.EAnnounce eAnnounce = SSystem.EAnnounce.OpenZoneSelect;
			eAnnounce = (SSystem.EAnnounce)i;
			if (sSystem.IsAnnounce(eAnnounce) != system.IsAnnounce(eAnnounce))
			{
				return false;
			}
		}
		if (memcmp(sStage2.getData(), sStage.getData()) != 0)
		{
			return false;
		}
		if (memcmp(special.getData(), sSpecial.getData()) != 0)
		{
			return false;
		}
		if (memcmp(option.getData(), sOption.getData()) != 0)
		{
			return false;
		}
		return true;
	}

	private static void dmSaveProcMain(MTS_TASK_TCB tcb)
	{
		DMS_SAVE_MAIN_WORK dMS_SAVE_MAIN_WORK = (DMS_SAVE_MAIN_WORK)tcb.work;
		if ((dMS_SAVE_MAIN_WORK.flag & 1) != 0)
		{
			mtTaskClearTcb(tcb);
			dm_save_disp_flag = 0u;
			dm_save_is_draw_state = 0u;
			dm_save_win_mode = 0;
			dm_save_is_task_draw = false;
			for (int i = 0; i < 2; i++)
			{
				dm_save_win_size_rate[i] = 0f;
			}
			dm_save_mgr_p = null;
		}
		if ((dMS_SAVE_MAIN_WORK.flag & 0x80000000u) != 0 && !AoAccountIsCurrentEnable())
		{
			dMS_SAVE_MAIN_WORK.proc_menu_update = dmSaveProcStopDraw;
			dMS_SAVE_MAIN_WORK.proc_input = null;
			dMS_SAVE_MAIN_WORK.proc_draw = null;
			dm_save_draw_reserve = false;
			dMS_SAVE_MAIN_WORK.flag &= 2147483647u;
			return;
		}
		if (dMS_SAVE_MAIN_WORK.proc_menu_update != null)
		{
			dMS_SAVE_MAIN_WORK.proc_menu_update(dMS_SAVE_MAIN_WORK);
		}
		if (dMS_SAVE_MAIN_WORK.proc_draw != null && !AoSysMsgIsShow())
		{
			dMS_SAVE_MAIN_WORK.proc_draw();
		}
	}

	private static void dmSaveDest(MTS_TASK_TCB tcb)
	{
	}

	private static void dmSaveLoadFontData(DMS_SAVE_MAIN_WORK main_work)
	{
		short cur_evt_id = SyGetEvtInfo().cur_evt_id;
		if (cur_evt_id == 10)
		{
			GsFontBuild(false);
		}
		else
		{
			GsFontBuild();
		}
		main_work.proc_menu_update = dmSaveIsLoadFontData;
	}

	private static void dmSaveIsLoadFontData(DMS_SAVE_MAIN_WORK main_work)
	{
		if (GsFontIsBuilded())
		{
			main_work.proc_menu_update = dmSaveLoadRequest;
		}
	}

	private static void dmSaveLoadRequest(DMS_SAVE_MAIN_WORK main_work)
	{
		main_work.arc_cmn_amb_fs[0] = amFsReadBackground("DEMO/CMN/D_CMN_WIN.AMB");
		main_work.arc_cmn_amb_fs[1] = amFsReadBackground(dm_save_menu_cmn_lng_amb_name_tbl[GsEnvGetLanguage()]);
		main_work.proc_menu_update = dmSaveProcLoadWait;
	}

	private static void dmSaveProcLoadWait(DMS_SAVE_MAIN_WORK main_work)
	{
		if (dmSaveIsDataLoad(main_work) != 0)
		{
			for (int i = 0; i < 2; i++)
			{
				main_work.arc_cmn_amb[i] = readAMBFile(main_work.arc_cmn_amb_fs[i]);
				main_work.arc_cmn_amb_fs[i] = null;
				main_work.cmn_ama[i] = readAMAFile(amBindGet(main_work.arc_cmn_amb[i], 0));
				string sPath;
				main_work.cmn_amb[i] = readAMBFile(amBindGet(main_work.arc_cmn_amb[i], 1, out sPath));
				main_work.cmn_amb[i].dir = sPath;
				amFsClearRequest(main_work.arc_cmn_amb_fs[i]);
				main_work.arc_cmn_amb_fs[i] = null;
				AoTexBuild(main_work.cmn_tex[i], main_work.cmn_amb[i]);
				AoTexLoad(main_work.cmn_tex[i]);
			}
			if (dm_save_is_snd_build)
			{
				DmSoundBuild();
			}
			main_work.proc_menu_update = dmSaveProcTexBuildWait;
		}
	}

	private static void dmSaveProcTexBuildWait(DMS_SAVE_MAIN_WORK main_work)
	{
		if (dmSaveIsTexLoad(main_work) == 1)
		{
			for (int i = 0; i < 2; i++)
			{
				dm_save_cmn_tex[i] = main_work.cmn_tex[i];
			}
			main_work.proc_menu_update = dmSaveProcCreateAct;
		}
	}

	private static void dmSaveProcCreateAct(DMS_SAVE_MAIN_WORK main_work)
	{
		uint num = 0u;
		while (true)
		{
			A2S_AMA_HEADER ama;
			AOS_TEXTURE tex;
			switch (num)
			{
			case 1u:
			case 2u:
			case 3u:
			case 4u:
			case 5u:
				ama = main_work.cmn_ama[1];
				tex = main_work.cmn_tex[1];
				break;
			case 0u:
				ama = main_work.cmn_ama[0];
				tex = main_work.cmn_tex[0];
				break;
			default:
				if ((dm_save_msg_flag & 4) != 0)
				{
					main_work.flag |= 2147483648u;
				}
				main_work.proc_menu_update = dmSaveProcWindowNodispIdle;
				return;
			}
			AoActSetTexture(AoTexGetTexList(tex));
			main_work.act[num] = AoActCreate(ama, g_dm_act_id_tbl[num]);
			dm_save_act[num] = main_work.act[num];
			num++;
		}
	}

	private static void dmSaveProcWindowNodispIdle(DMS_SAVE_MAIN_WORK main_work)
	{
		if ((main_work.flag & 8) != 0 || main_work.announce_flag != 0)
		{
			main_work.win_timer = 0;
			for (uint num = 0u; num < 4; num++)
			{
				if ((main_work.announce_flag & (uint)(1 << (int)num)) != 0)
				{
					dm_save_win_mode = (main_work.win_mode = (int)num);
					break;
				}
			}
			if (main_work.win_mode == 0)
			{
				DmCmnBackupLoad();
				main_work.proc_input = null;
				main_work.proc_menu_update = dmSaveProcWindowOpenWaitLoadIdle;
			}
			else if (main_work.win_mode == 1)
			{
				main_work.proc_input = dmSaveInputProcWindow;
				main_work.proc_menu_update = dmSaveProcWindowOpenEfct;
				main_work.proc_draw = DmSaveWinSelectDraw;
				dm_save_draw_reserve = true;
				DmSoundPlaySE("Window");
			}
			else if (main_work.win_mode == 2)
			{
				DmCmnBackupSave(dm_save_first_save, false, false);
				main_work.proc_input = null;
				main_work.proc_menu_update = dmSaveProcWindowOpenWaitIdle;
				main_work.proc_draw = null;
				dm_save_draw_reserve = false;
			}
			else if (main_work.win_mode == 3)
			{
				DmCmnBackupSave(dm_save_first_save, true, false);
				main_work.proc_input = null;
				main_work.proc_menu_update = dmSaveProcWindowOpenWaitIdle;
				main_work.proc_draw = null;
				dm_save_draw_reserve = false;
			}
			main_work.flag &= 4294967287u;
		}
		else
		{
			main_work.proc_menu_update = dmSaveProcStopDraw;
			dm_save_draw_reserve = false;
		}
	}

	private static void dmSaveProcWindowOpenWaitLoadIdle(DMS_SAVE_MAIN_WORK main_work)
	{
		if (AoStorageIsExecuteReal())
		{
			main_work.proc_menu_update = dmSaveProcWindowOpenEfct;
			main_work.proc_draw = DmSaveWinSelectDraw;
			DmSoundPlaySE("Window");
			dm_save_draw_reserve = true;
		}
	}

	private static void dmSaveProcWindowOpenWaitIdle(DMS_SAVE_MAIN_WORK main_work)
	{
		if (AoStorageSaveFreeSpaceIsEnough())
		{
			main_work.proc_menu_update = dmSaveProcWindowOpenEfct;
			main_work.proc_draw = DmSaveWinSelectDraw;
			DmSoundPlaySE("Window");
			dm_save_draw_reserve = true;
		}
	}

	private static void dmSaveProcWindowOpenEfct(DMS_SAVE_MAIN_WORK main_work)
	{
		if ((main_work.flag & 0x10) != 0)
		{
			main_work.proc_menu_update = dmSaveProcWindowAnnounceIdle;
			main_work.disp_flag |= 1u;
			dm_save_disp_flag = main_work.disp_flag;
			main_work.flag &= 4294967279u;
		}
		else
		{
			dmSaveSetWinOpenEfct(main_work);
		}
	}

	private static void dmSaveProcWindowAnnounceIdle(DMS_SAVE_MAIN_WORK main_work)
	{
		if (main_work.proc_input != null)
		{
			main_work.proc_input(main_work);
		}
		if (main_work.win_mode == 0)
		{
			if (DmCmnBackupIsLoadFinished())
			{
				main_work.win_timer = 8;
				if (main_work.timer >= 60)
				{
					main_work.disp_flag &= 4294967294u;
					dm_save_disp_flag = main_work.disp_flag;
					main_work.proc_menu_update = dmSaveProcWindowCloseEfct;
					main_work.timer = 0;
				}
			}
			else if (AoSysMsgIsShow())
			{
				main_work.win_timer = 8;
				main_work.disp_flag &= 4294967294u;
				dm_save_disp_flag = main_work.disp_flag;
				main_work.proc_menu_update = dmSaveProcWindowCloseEfct;
				main_work.timer = 0;
			}
			else if (!AoStorageIsExecuteReal())
			{
				main_work.timer = 0;
			}
		}
		else if (main_work.win_mode == 1)
		{
			if ((main_work.flag & 4) != 0)
			{
				main_work.proc_input = null;
				main_work.proc_menu_update = dmSaveProcWindowCloseEfct;
				main_work.win_timer = 8;
				main_work.disp_flag &= 4294967294u;
				DmSoundPlaySE("Ok");
				main_work.flag &= 4294967291u;
				main_work.timer = 0;
			}
		}
		else if (main_work.win_mode == 2)
		{
			if (DmCmnBackupIsSaveFinished())
			{
				main_work.win_timer = 8;
				if (main_work.timer >= 60)
				{
					main_work.proc_input = null;
					main_work.disp_flag &= 4294967294u;
					main_work.proc_menu_update = dmSaveProcWindowCloseEfct;
					main_work.timer = 0;
				}
			}
			else if (!AoStorageIsExecuteReal())
			{
				main_work.timer = 0;
			}
		}
		else if (main_work.win_mode == 3)
		{
			if (DmCmnBackupIsSaveFinished())
			{
				main_work.win_timer = 8;
				if (main_work.timer >= 60)
				{
					main_work.proc_input = null;
					main_work.disp_flag &= 4294967294u;
					main_work.proc_menu_update = dmSaveProcWindowCloseEfct;
					main_work.timer = 0;
				}
			}
			else if (!AoStorageIsExecuteReal())
			{
				main_work.timer = 0;
			}
		}
		else
		{
			main_work.proc_menu_update = dmSaveProcWindowCloseEfct;
			main_work.disp_flag &= 4294967294u;
		}
		dm_save_disp_flag = main_work.disp_flag;
		main_work.timer++;
	}

	private static void dmSaveProcWindowCloseEfct(DMS_SAVE_MAIN_WORK main_work)
	{
		if ((main_work.flag & 0x10) != 0)
		{
			if (main_work.win_mode == 1)
			{
				main_work.proc_menu_update = dmSaveProcWaitSeStop;
			}
			else if (main_work.win_mode == 0)
			{
				main_work.proc_menu_update = dmSaveProcWaitLoadEnd;
			}
			else
			{
				main_work.proc_menu_update = dmSaveProcWindowNodispIdle;
			}
			main_work.announce_flag &= (uint)(~(1 << main_work.win_mode));
			main_work.flag &= 4294967279u;
			main_work.proc_draw = null;
			dm_save_draw_reserve = false;
		}
		dmSaveSetWinCloseEfct(main_work);
	}

	private static void dmSaveProcWaitSeStop(DMS_SAVE_MAIN_WORK main_work)
	{
		if (main_work.timer > 60)
		{
			main_work.proc_menu_update = dmSaveProcWindowNodispIdle;
			main_work.timer = 0;
		}
		else
		{
			main_work.timer++;
		}
	}

	private static void dmSaveProcWaitLoadEnd(DMS_SAVE_MAIN_WORK main_work)
	{
		if (DmCmnBackupIsLoadFinished())
		{
			main_work.proc_menu_update = dmSaveProcWindowNodispIdle;
			main_work.timer = 0;
		}
	}

	private static void dmSaveProcStopDraw(DMS_SAVE_MAIN_WORK main_work)
	{
		main_work.proc_menu_update = dmSaveProcDataRelease;
	}

	private static void dmSaveProcDataRelease(DMS_SAVE_MAIN_WORK main_work)
	{
		for (int i = 0; i < 2; i++)
		{
			AoTexRelease(main_work.cmn_tex[i]);
		}
		if (dm_save_is_snd_build)
		{
			DmSoundExit();
			DmSoundFlush();
		}
		main_work.proc_menu_update = dmSaveProcFinish;
	}

	private static void dmSaveProcFinish(DMS_SAVE_MAIN_WORK main_work)
	{
		if (dmSaveIsTexRelease(main_work) != 1)
		{
			return;
		}
		for (int i = 0; i < 2; i++)
		{
			dm_save_cmn_tex[i] = null;
		}
		for (int j = 0; j < 6; j++)
		{
			if (main_work.act[j] != null)
			{
				AoActDelete(main_work.act[j]);
				main_work.act[j] = null;
			}
			dm_save_act[j] = null;
		}
		for (int k = 0; k < 2; k++)
		{
			if (main_work.arc_cmn_amb[k] != null)
			{
				main_work.arc_cmn_amb[k] = null;
			}
		}
		main_work.flag |= 1u;
		main_work.proc_menu_update = null;
	}

	private static void dmSaveInputProcWindow(DMS_SAVE_MAIN_WORK main_work)
	{
		if (AoAccountGetCurrentId() < 0)
		{
			if (AoPadSomeoneStand((ushort)GSD_KEY_DECIDE) >= 0)
			{
				main_work.flag |= 4u;
			}
		}
		else if ((AoPadStand() & GSD_KEY_DECIDE) != 0)
		{
			main_work.flag |= 4u;
		}
	}

	private static void DmSaveWinSelectDraw()
	{
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		uint num4 = 0u;
		AoActSysSetDrawTaskPrio(61439u);
		if ((dm_save_msg_flag & 2) != 0)
		{
			num = 749;
			num2 = (int)((180f + (float)dm_save_win_size_y_tbl[GsEnvGetLanguage()]) * 1.6875f);
		}
		else
		{
			if (!AoStorageIsExecuteReal())
			{
				return;
			}
			if (GsEnvGetLanguage() == 4)
			{
				num = 749;
				num2 = 303;
			}
			else
			{
				num = 641;
				num2 = 303;
			}
		}
		num4 = (dm_save_is_task_draw ? 1u : (((dm_save_msg_flag & 2) != 0) ? 1u : 0u));
		if (dm_save_is_draw_state != 0)
		{
			AoWinSysDrawState(0, AoTexGetTexList(dm_save_cmn_tex[0]), num4, 480f, 356f, (float)num * dm_save_win_size_rate[0], (float)num2 * dm_save_win_size_rate[1], dm_save_draw_state);
		}
		else
		{
			AoWinSysDrawTask(0, AoTexGetTexList(dm_save_cmn_tex[0]), num4, 480f, 356f, (float)num * dm_save_win_size_rate[0], (float)num2 * dm_save_win_size_rate[1] * 0.9f, 61439);
		}
		if ((dm_save_disp_flag & 1) != 0)
		{
			switch (dm_save_win_mode)
			{
			case 0:
				AoActSetTexture(AoTexGetTexList(dm_save_cmn_tex[1]));
				AoActSortRegAction(dm_save_act[2]);
				break;
			case 1:
				AoActSetTexture(AoTexGetTexList(dm_save_cmn_tex[1]));
				AoActSortRegAction(dm_save_act[3]);
				AoActSortRegAction(dm_save_act[5]);
				break;
			case 2:
				AoActSetTexture(AoTexGetTexList(dm_save_cmn_tex[1]));
				AoActSortRegAction(dm_save_act[4]);
				break;
			case 3:
				AoActSetTexture(AoTexGetTexList(dm_save_cmn_tex[1]));
				AoActSortRegAction(dm_save_act[4]);
				break;
			}
			AoActAcmPush();
			num3 = ((GsEnvGetLanguage() != 0) ? (dm_save_win_size_y_tbl[GsEnvGetLanguage()] / 2) : 0);
			for (int i = 0; i < 6; i++)
			{
				AOS_TEXTURE tex = ((i < 1) ? dm_save_cmn_tex[0] : dm_save_cmn_tex[1]);
				AoActAcmInit();
				AoActAcmApplyTrans(dm_save_win_act_pos_tbl[i][0], dm_save_win_act_pos_tbl[i][1], 0f);
				if ((dm_save_msg_flag & 2) != 0)
				{
					switch (i)
					{
					case 5:
						AoActAcmApplyTrans(0f, 16f + (float)num3, 0f);
						break;
					case 0:
					case 1:
						AoActAcmApplyTrans(-32f, num3 * -1, 0f);
						break;
					}
				}
				AoActAcmApplyScale(1.6875f, 1.6875f);
				AoActSetTexture(AoTexGetTexList(tex));
				AoActUpdate(dm_save_act[i], 0f);
			}
			AoActAcmPop();
			AoActSortExecute();
			AoActSortDraw();
			AoActSortUnregAll();
		}
		if (dm_save_is_draw_state != 0 && dm_save_is_task_draw)
		{
			amDrawMakeTask(dmSaveTaskDraw, 61439, 0u);
		}
	}

	private static void dmSaveTaskDraw(AMS_TCB tcb)
	{
		AoActDrawPre();
		amDrawExecCommand(dm_save_draw_state);
		amDrawEndScene();
	}

	private static int dmSaveIsDataLoad(DMS_SAVE_MAIN_WORK main_work)
	{
		for (int i = 0; i < 2; i++)
		{
			if (!amFsIsComplete(main_work.arc_cmn_amb_fs[i]))
			{
				return 0;
			}
		}
		return 1;
	}

	private static int dmSaveIsTexLoad(DMS_SAVE_MAIN_WORK main_work)
	{
		for (int i = 0; i < 2; i++)
		{
			if (!AoTexIsLoaded(main_work.cmn_tex[i]))
			{
				return 0;
			}
		}
		if (dm_save_is_snd_build && !DmSoundBuildCheck())
		{
			return 0;
		}
		return 1;
	}

	private static int dmSaveIsTexRelease(DMS_SAVE_MAIN_WORK main_work)
	{
		for (int i = 0; i < 2; i++)
		{
			if (!AoTexIsReleased(main_work.cmn_tex[i]))
			{
				return 0;
			}
		}
		return 1;
	}

	private static void dmSaveSetWinOpenEfct(DMS_SAVE_MAIN_WORK main_work)
	{
		if (main_work.win_timer > 8)
		{
			main_work.flag |= 16u;
			main_work.win_timer = 0;
			for (uint num = 0u; num < 2; num++)
			{
				main_work.win_size_rate[num] = 1f;
			}
		}
		else
		{
			main_work.win_timer++;
		}
		for (uint num2 = 0u; num2 < 2; num2++)
		{
			if (main_work.win_timer != 0)
			{
				main_work.win_size_rate[num2] = (float)main_work.win_timer / 8f;
			}
			else
			{
				main_work.win_size_rate[num2] = 1f;
			}
			if (main_work.win_size_rate[num2] > 1f)
			{
				main_work.win_size_rate[num2] = 1f;
			}
			dm_save_win_size_rate[num2] = main_work.win_size_rate[num2];
		}
	}

	private static void dmSaveSetWinCloseEfct(DMS_SAVE_MAIN_WORK main_work)
	{
		for (uint num = 0u; num < 2; num++)
		{
			if (main_work.win_timer != 0)
			{
				main_work.win_size_rate[num] = (float)main_work.win_timer / 8f;
			}
			else
			{
				main_work.win_size_rate[num] = 0f;
			}
			dm_save_win_size_rate[num] = main_work.win_size_rate[num];
		}
		if (main_work.win_timer < 0)
		{
			main_work.flag |= 16u;
			main_work.win_timer = 0;
			for (uint num2 = 0u; num2 < 2; num2++)
			{
				main_work.win_size_rate[num2] = 0f;
				dm_save_win_size_rate[num2] = main_work.win_size_rate[num2];
			}
		}
		else
		{
			main_work.win_timer--;
		}
	}

	public void DmLogoSonicInit(object arg)
	{
		if (DmLogoSonicBuildCheck())
		{
			dmLogoSonicStart();
			return;
		}
		MTM_TASK_MAKE_TCB(dmLogoSonicLoadWait, null, 0u, ushort.MaxValue, 4096u, 0, null, "DM_LSONT_LW");
		DmLogoSonicLoad();
	}

	public void DmLogoSonicLoad()
	{
		DmLogoComLoadFileCreate(dm_logo_sonic_load_tcb);
		DmLogoComLoadFileReg(dm_logo_sonic_load_tcb, dm_logo_sonic_com_fileinfo_list, dm_logo_sonic_com_file_num);
		DmLogoComLoadFileStart(dm_logo_sonic_load_tcb);
	}

	public bool DmLogoSonicLoadCheck()
	{
		if (dm_logo_sonic_load_tcb.Target == null && dm_logo_sonic_data[0] != null)
		{
			return true;
		}
		return false;
	}

	public void DmLogoSonicBuild()
	{
		AMS_AMB_HEADER[] array = new AMS_AMB_HEADER[1];
		dm_logo_sonic_build_tcb = MTM_TASK_MAKE_TCB(dmLogoSonicDataBuildMain, dmLogoSonicDataBuildDest, 0u, ushort.MaxValue, 4096u, 0, null, "DM_LSONT_BUILD");
		dm_logo_sonic_aos_tex = New<AOS_TEXTURE>(1);
		string sPath;
		array[0] = readAMBFile(amBindGet(dm_logo_sonic_data[0], 1, out sPath));
		array[0].dir = sPath;
		AOS_TEXTURE[] array2 = dm_logo_sonic_aos_tex;
		for (int i = 0; i < 1; i++)
		{
			AoTexBuild(array2[i], array[i]);
			AoTexLoad(array2[i]);
		}
	}

	public bool DmLogoSonicBuildCheck()
	{
		if (dm_logo_sonic_build_state)
		{
			return true;
		}
		return false;
	}

	public void DmLogoSonicFlush()
	{
		dm_logo_sonic_flush_tcb = MTM_TASK_MAKE_TCB(dmLogoSonicDataFlushMain, dmLogoSonicDataFlushDest, 0u, ushort.MaxValue, 4096u, 0, null, "DM_LSONT_FLUSH");
		AOS_TEXTURE[] array = dm_logo_sonic_aos_tex;
		for (int i = 0; i < 1; i++)
		{
			AoTexRelease(array[i]);
		}
	}

	public bool DmLogoSonicFlushCheck()
	{
		if (!dm_logo_sonic_build_state)
		{
			return true;
		}
		return false;
	}

	public void DmLogoSonicRelease()
	{
		for (int i = 0; i < 1; i++)
		{
			dm_logo_sonic_data[i] = null;
		}
	}

	public bool DmLogoSonicReleaseCheck()
	{
		if (dm_logo_sonic_load_tcb.Target == null && dm_logo_sonic_data[0] == null)
		{
			return true;
		}
		return false;
	}

	public void dmLogoSonicLoadWait(MTS_TASK_TCB tcb)
	{
		if (DmLogoSonicLoadCheck())
		{
			DmLogoSonicBuild();
			mtTaskChangeTcbProcedure(tcb, dmLogoSonicBuildWait);
		}
	}

	public void dmLogoSonicBuildWait(MTS_TASK_TCB tcb)
	{
		if (DmLogoSonicBuildCheck())
		{
			mtTaskClearTcb(tcb);
			dmLogoSonicStart();
		}
	}

	public void dmLogoSonicActionCreate(DMS_LOGO_SONIC_WORK logo_work)
	{
		A2S_AMA_HEADER ama = readAMAFile(amBindGet(dm_logo_sonic_data[0], 0));
		for (uint num = 0u; num < 2; num++)
		{
			AoActSetTexture(AoTexGetTexList(dm_logo_sonic_aos_tex[dm_logo_sonic_tex_id_tbl[num]]));
			logo_work.act[num] = AoActCreate(ama, num);
		}
	}

	public void dmLogoSonicActionDelete(DMS_LOGO_SONIC_WORK logo_work)
	{
		for (int i = 0; i < 2; i++)
		{
			AoActDelete(logo_work.act[i]);
		}
	}

	public void dmLogoSonicStart()
	{
		NNS_RGBA diffuse = new NNS_RGBA(1f, 1f, 1f, 1f);
		NNS_RGB ambient = new NNS_RGB(1f, 1f, 1f);
		MTS_TASK_TCB mTS_TASK_TCB = MTM_TASK_MAKE_TCB(dmLogoSonicMainFunc, null, 0u, 0, 4096u, 0, () => new DMS_LOGO_SONIC_WORK(), "DM_LSONT_MAIN");
		DMS_LOGO_SONIC_WORK dMS_LOGO_SONIC_WORK = (DMS_LOGO_SONIC_WORK)mTS_TASK_TCB.work;
		nnSetPrimitive3DMaterial(ref diffuse, ref ambient, 1f);
		AoActSysSetDrawStateEnable(false);
		dmLogoSonicActionCreate(dMS_LOGO_SONIC_WORK);
		IzFadeInitEasy(0u, 2u, 60f, true);
		dMS_LOGO_SONIC_WORK.func = dmLogoSonicFadeInWaitFunc;
	}

	public void dmLogoSonicMainFunc(MTS_TASK_TCB tcb)
	{
		DMS_LOGO_SONIC_WORK dMS_LOGO_SONIC_WORK = (DMS_LOGO_SONIC_WORK)tcb.work;
		if (AoSysIsShowPlatformUI())
		{
			if (IzFadeIsExe())
			{
				IzFadeSetStopUpdate1Frame(null);
			}
		}
		else
		{
			if (dMS_LOGO_SONIC_WORK.func != null)
			{
				dMS_LOGO_SONIC_WORK.func(dMS_LOGO_SONIC_WORK);
			}
			if ((dMS_LOGO_SONIC_WORK.flag & 1) != 0 && (dMS_LOGO_SONIC_WORK.flag & 2) == 0 && (amTpIsTouchPush(0) || isBackKeyPressed()))
			{
				setBackKeyRequest(false);
				dMS_LOGO_SONIC_WORK.flag |= 2u;
				if (IzFadeIsEnd())
				{
					IzFadeInitEasy(0u, 3u, 10f, true);
				}
				dMS_LOGO_SONIC_WORK.func = dmLogoSonicFadeOutWaitFunc;
			}
			if ((dMS_LOGO_SONIC_WORK.flag & 4) != 0)
			{
				mtTaskChangeTcbProcedure(tcb, dmLogoSonicPreEndWait);
				dMS_LOGO_SONIC_WORK.timer = 0;
				return;
			}
		}
		float frame = 0f;
		if (!AoSysIsShowPlatformUI())
		{
			frame = 1f;
		}
		AoActSysSetDrawTaskPrio();
		for (int i = 0; i < 2; i++)
		{
			AoActSetTexture(AoTexGetTexList(dm_logo_sonic_aos_tex[dm_logo_sonic_tex_id_tbl[i]]));
			AoActUpdate(dMS_LOGO_SONIC_WORK.act[i], frame);
			AoActDraw(dMS_LOGO_SONIC_WORK.act[i]);
		}
	}

	public void dmLogoSonicFadeInWaitFunc(DMS_LOGO_SONIC_WORK logo_work)
	{
		if (IzFadeIsEnd())
		{
			logo_work.func = dmLogoSonicDispWaitFunc;
			logo_work.timer = 0;
		}
	}

	public void dmLogoSonicDispWaitFunc(DMS_LOGO_SONIC_WORK logo_work)
	{
		logo_work.timer++;
		if (logo_work.timer >= 120)
		{
			logo_work.func = dmLogoSonicFadeOutWaitFunc;
			IzFadeInitEasy(0u, 3u, 60f, true);
			logo_work.flag &= 4294967294u;
		}
		else if (logo_work.timer == 30)
		{
			logo_work.flag |= 1u;
		}
	}

	public void dmLogoSonicFadeOutWaitFunc(DMS_LOGO_SONIC_WORK logo_work)
	{
		if (IzFadeIsEnd())
		{
			logo_work.flag |= 4u;
		}
	}

	public void dmLogoSonicPreEndWait(MTS_TASK_TCB tcb)
	{
		DMS_LOGO_SONIC_WORK dMS_LOGO_SONIC_WORK = (DMS_LOGO_SONIC_WORK)tcb.work;
		dMS_LOGO_SONIC_WORK.timer++;
		if (dMS_LOGO_SONIC_WORK.timer > 2)
		{
			dmLogoSonicActionDelete(dMS_LOGO_SONIC_WORK);
			DmLogoSonicFlush();
			mtTaskChangeTcbProcedure(tcb, dmLogoSonicFlushWaitFunc);
		}
	}

	public void dmLogoSonicFlushWaitFunc(MTS_TASK_TCB tcb)
	{
		if (DmLogoSonicFlushCheck())
		{
			DmLogoSonicRelease();
			mtTaskChangeTcbProcedure(tcb, dmLogoSonicRelesehWaitFunc);
		}
	}

	public void dmLogoSonicRelesehWaitFunc(MTS_TASK_TCB tcb)
	{
		if (DmLogoSonicReleaseCheck())
		{
			mtTaskClearTcb(tcb);
			SyChangeNextEvt();
		}
	}

	public static void dmLogoSonicLoadPostFunc(DMS_LOGO_COM_LOAD_CONTEXT context)
	{
		dm_logo_sonic_data[context.no] = readAMBFile(context.fs_req);
	}

	public void dmLogoSonicDataBuildMain(MTS_TASK_TCB tcb)
	{
		bool flag = true;
		AOS_TEXTURE[] array = dm_logo_sonic_aos_tex;
		for (int i = 0; i < 1; i++)
		{
			if (!AoTexIsLoaded(array[i]))
			{
				flag = false;
			}
		}
		if (flag)
		{
			mtTaskClearTcb(tcb);
			dm_logo_sonic_build_state = true;
		}
	}

	public void dmLogoSonicDataBuildDest(MTS_TASK_TCB tcb)
	{
		dm_logo_sonic_build_tcb = null;
	}

	public void dmLogoSonicDataFlushMain(MTS_TASK_TCB tcb)
	{
		bool flag = true;
		AOS_TEXTURE[] array = dm_logo_sonic_aos_tex;
		for (int i = 0; i < 1; i++)
		{
			if (!AoTexIsReleased(array[i]))
			{
				flag = false;
			}
		}
		if (flag)
		{
			dm_logo_sonic_aos_tex = null;
			mtTaskClearTcb(tcb);
			dm_logo_sonic_build_state = false;
		}
	}

	public void dmLogoSonicDataFlushDest(MTS_TASK_TCB tcb)
	{
		dm_logo_sonic_flush_tcb = null;
	}

	private static void DmLoadingBuild(AMS_FS arc_amb)
	{
		int num = 0;
		dm_loading_mgr_p = new DMS_LOADING_MGR();
		dm_loading_tex = new AOS_TEXTURE[1];
		for (num = 0; num < 1; num++)
		{
			dm_loading_tex[num] = new AOS_TEXTURE();
		}
		for (num = 0; num < 1; num++)
		{
			string sPath = null;
			dm_loading_ama[num] = readAMAFile(amBindGet(arc_amb, 0, out sPath));
			sPath = null;
			dm_loading_amb[num] = readAMBFile(amBindGet(arc_amb, 1, out sPath));
			dm_loading_amb[num].dir = sPath;
		}
		for (num = 0; num < 1; num++)
		{
			AoTexBuild(dm_loading_tex[num], dm_loading_amb[num]);
			AoTexLoad(dm_loading_tex[num]);
		}
	}

	private static bool DmLoadingBuildCheck()
	{
		if (dmLoadingIsTexLoad() != 0)
		{
			return true;
		}
		return false;
	}

	private static void DmLoadingFlush()
	{
		for (int i = 0; i < 1; i++)
		{
			AoTexRelease(dm_loading_tex[i]);
		}
	}

	private static bool DmLoadingFlushCheck()
	{
		if (dmLoadingIsTexRelease() != 0)
		{
			if (dm_loading_mgr_p != null)
			{
				dm_loading_mgr_p = null;
			}
			return true;
		}
		return false;
	}

	private static void DmLoadingStart()
	{
		dmLoadingInit();
	}

	private static bool DmLoadingIsExit()
	{
		if (dm_loading_mgr_p != null)
		{
			if (dm_loading_mgr_p.tcb == null)
			{
				return true;
			}
			return false;
		}
		return true;
	}

	private static void DmLoadingExit()
	{
		if (dm_loading_mgr_p.tcb != null)
		{
			mtTaskClearTcb(dm_loading_mgr_p.tcb);
			dm_loading_mgr_p.tcb = null;
		}
	}

	private static void DmLoadingSetLoadComplete()
	{
		dm_loading_check_load_comp = true;
	}

	private static void dmLoadingInit()
	{
		dm_loading_mgr_p.tcb = mtTaskMake(dmLoadingProcMain, dmLoadingDest, 0u, 32767, 8192u, 10, () => new DMS_LOADING_MAIN_WORK(), "LOADING_MAIN");
		dm_loading_active = true;
		DMS_LOADING_MAIN_WORK dMS_LOADING_MAIN_WORK = (DMS_LOADING_MAIN_WORK)dm_loading_mgr_p.tcb.work;
		dMS_LOADING_MAIN_WORK.draw_state = (AoActSysGetDrawStateEnable() ? 1u : 0u);
		AoActSysSetDrawStateEnable(dMS_LOADING_MAIN_WORK.draw_state == 1);
		if (dMS_LOADING_MAIN_WORK.draw_state != 0)
		{
			dm_loading_draw_state = AoActSysGetDrawState();
		}
		dmLoadingSetInitData(dMS_LOADING_MAIN_WORK);
		dMS_LOADING_MAIN_WORK.proc_update = dmLoadingProcInit;
	}

	private static void dmLoadingSetInitData(DMS_LOADING_MAIN_WORK main_work)
	{
		short num = 0;
		dm_loading_check_load_comp = false;
		num = SyGetEvtInfo().cur_evt_id;
		if (num == 6 || num == 9 || num == 11)
		{
			main_work.is_maingame_load = true;
			main_work.sonic_pos_x = 0f;
		}
		else
		{
			main_work.is_maingame_load = false;
			main_work.sonic_pos_x = 0f;
		}
		main_work.lang_id = GsEnvGetLanguage();
	}

	private static void dmLoadingProcMain(MTS_TASK_TCB tcb)
	{
		DMS_LOADING_MAIN_WORK dMS_LOADING_MAIN_WORK = (DMS_LOADING_MAIN_WORK)tcb.work;
		if ((dMS_LOADING_MAIN_WORK.flag & 1) != 0)
		{
			DmLoadingExit();
		}
		if (dMS_LOADING_MAIN_WORK.proc_update != null)
		{
			dMS_LOADING_MAIN_WORK.proc_update(dMS_LOADING_MAIN_WORK);
		}
		if (dMS_LOADING_MAIN_WORK.proc_draw != null)
		{
			dMS_LOADING_MAIN_WORK.proc_draw(dMS_LOADING_MAIN_WORK);
		}
	}

	private static void dmLoadingDest(MTS_TASK_TCB tcb)
	{
		dm_loading_active = false;
	}

	private static void dmLoadingProcInit(DMS_LOADING_MAIN_WORK main_work)
	{
		main_work.proc_update = dmLoadingProcCreateAct;
	}

	private static void dmLoadingProcCreateAct(DMS_LOADING_MAIN_WORK main_work)
	{
		for (uint num = 0u; num < 8; num++)
		{
			A2S_AMA_HEADER ama = dm_loading_ama[0];
			AOS_TEXTURE tex = dm_loading_tex[0];
			AoActSetTexture(AoTexGetTexList(tex));
			main_work.act[num] = AoActCreate(ama, g_dm_act_id_tbl_loading[num]);
		}
		main_work.proc_update = dmLoadingProcFadeIn;
		main_work.proc_draw = dmLoadingProcActDraw;
		if (main_work.is_maingame_load)
		{
			IzFadeInitEasy(0u, 0u, 32f);
		}
		else
		{
			IzFadeInitEasy(0u, 0u, 32f);
		}
	}

	private static void dmLoadingProcFadeIn(DMS_LOADING_MAIN_WORK main_work)
	{
		if (IzFadeIsEnd())
		{
			IzFadeExit();
			main_work.proc_update = dmLoadingProcNowLoading;
		}
	}

	private static void dmLoadingProcNowLoading(DMS_LOADING_MAIN_WORK main_work)
	{
		if (dm_loading_check_load_comp && main_work.timer > 60f)
		{
			main_work.proc_update = dmLoadingProcAlreadyLoaded;
			main_work.timer = 0f;
			if (main_work.is_maingame_load)
			{
				IzFadeInitEasyColor(0, 32767, 61439, 18u, 0u, 3u, 32f, true);
			}
			else
			{
				IzFadeInitEasy(0u, 3u, 32f);
			}
		}
		if (main_work.sonic_set_frame >= 12f)
		{
			main_work.sonic_set_frame = 0f;
		}
		main_work.sonic_set_frame += 1f;
		main_work.timer += 1f;
	}

	private static void dmLoadingProcAlreadyLoaded(DMS_LOADING_MAIN_WORK main_work)
	{
		if (main_work.timer > 32f)
		{
			main_work.proc_update = dmLoadingProcFadeOut;
			main_work.timer = 0f;
		}
		if (main_work.sonic_set_frame >= 12f)
		{
			main_work.sonic_set_frame = 0f;
		}
		main_work.sonic_pos_x += 50f;
		main_work.sonic_set_frame += 1f;
		main_work.timer += 1f;
	}

	private static void dmLoadingProcFadeOut(DMS_LOADING_MAIN_WORK main_work)
	{
		if (IzFadeIsEnd())
		{
			main_work.proc_update = dmLoadingProcStopDraw;
			main_work.proc_draw = null;
		}
	}

	private static void dmLoadingProcStopDraw(DMS_LOADING_MAIN_WORK main_work)
	{
		for (int i = 0; i < 8; i++)
		{
			if (main_work.act[i] != null)
			{
				AoActDelete(main_work.act[i]);
				main_work.act[i] = null;
			}
		}
		main_work.proc_update = null;
		main_work.flag |= 1u;
	}

	private static void dmLoadingProcActDraw(DMS_LOADING_MAIN_WORK main_work)
	{
		dmLoadingCommonDraw(main_work);
		if (main_work.draw_state != 0)
		{
			amDrawMakeTask(dmLoadingTaskDraw, 32768, null);
		}
	}

	private static void dmLoadingTaskDraw(AMS_TCB tcb)
	{
		AoActDrawPre();
		amDrawExecCommand(dm_loading_draw_state);
		amDrawEndScene();
	}

	private static void dmLoadingCommonDraw(DMS_LOADING_MAIN_WORK main_work)
	{
		AoActSysSetDrawTaskPrio(8192u);
		AoActSetTexture(AoTexGetTexList(dm_loading_tex[0]));
		for (int i = 0; i < 8; i++)
		{
			AoActSortRegAction(main_work.act[i]);
		}
		AoActSetFrame(main_work.act[3], main_work.sonic_set_frame);
		AoActSetFrame(main_work.act[7], main_work.lang_id);
		AoActSetTexture(AoTexGetTexList(dm_loading_tex[0]));
		for (int j = 0; j <= 2; j++)
		{
			AoActUpdate(main_work.act[j], 0f);
		}
		AoActAcmPush();
		AoActAcmInit();
		AoActAcmApplyTrans(main_work.sonic_pos_x, -10f, 0f);
		AoActUpdate(main_work.act[3], 0f);
		AoActAcmPop();
		for (int k = 4; k <= 6; k++)
		{
			AoActUpdate(main_work.act[k], 1f);
		}
		AoActUpdate(main_work.act[7], 0f);
		if (main_work.lang_id >= 6)
		{
			main_work.act[7].sprite.tex_id = 9 + main_work.lang_id - 6;
		}
		AoActSortExecute();
		AoActSortDraw();
		AoActSortUnregAll();
	}

	private static short dmLoadingIsTexLoad()
	{
		for (int i = 0; i < 1; i++)
		{
			if (!AoTexIsLoaded(dm_loading_tex[i]))
			{
				return 0;
			}
		}
		return 1;
	}

	private static short dmLoadingIsTexRelease()
	{
		for (int i = 0; i < 1; i++)
		{
			if (!AoTexIsReleased(dm_loading_tex[i]))
			{
				return 0;
			}
		}
		return 1;
	}

	private static void DmCmnBackupLoad()
	{
		SBackup sBackup = SBackup.CreateInstance();
		AoStorageClearError();
		byte[] data = sBackup.getData();
		AoStorageLoadStart(data);
		sBackup.setData(data);
	}

	private static bool DmCmnBackupIsLoadFinished()
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		if (AoStorageLoadIsFinished())
		{
			gSS_MAIN_SYS_INFO.cmp_backup.setData(gSS_MAIN_SYS_INFO.backup.getData());
			return true;
		}
		return false;
	}

	private static bool DmCmnBackupIsLoadSuccessed()
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		bool flag = false;
		if (AoStorageLoadIsSuccessed())
		{
			gSS_MAIN_SYS_INFO.is_save_run = 1u;
			return true;
		}
		return false;
	}

	private static void DmCmnBackupSave(bool is_first, bool is_new, bool is_del)
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		SBackup sBackup = SBackup.CreateInstance();
		byte[] data = sBackup.getData();
		uint size = (uint)data.Length;
		bool flag = false;
		AoStorageClearError();
		if (is_first)
		{
			AoStorageSaveStart(data, size, true, false);
			gSS_MAIN_SYS_INFO.cmp_backup.setData(gSS_MAIN_SYS_INFO.backup.getData());
		}
		else if (is_new)
		{
			AoStorageSaveStart(data, size, false, true);
			gSS_MAIN_SYS_INFO.cmp_backup.setData(gSS_MAIN_SYS_INFO.backup.getData());
		}
		else if (gSS_MAIN_SYS_INFO.is_save_run != 0 && dmCmnBackupIsCmpSaveData())
		{
			AoStorageSaveStart(data, size, false, false);
			gSS_MAIN_SYS_INFO.cmp_backup.setData(gSS_MAIN_SYS_INFO.backup.getData());
		}
	}

	private static bool DmCmnBackupIsSaveFinished()
	{
		if (AoStorageSaveIsFinished())
		{
			return true;
		}
		return false;
	}

	private static bool DmCmnBackupIsSaveSuccessed()
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		int num = 0;
		bool flag = false;
		if (AoStorageSaveIsSuccessed())
		{
			gSS_MAIN_SYS_INFO.is_save_run = 1u;
			return true;
		}
		num = AoStorageGetError();
		if (num == 2)
		{
			gSS_MAIN_SYS_INFO.is_save_run = 0u;
			return true;
		}
		return false;
	}

	private static bool dmCmnBackupIsCmpSaveData()
	{
		bool flag = false;
		if (dmCmnBackupMathCompare())
		{
			return false;
		}
		return true;
	}

	private static bool dmCmnBackupMathCompare()
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		if (gSS_MAIN_SYS_INFO.is_save_run == 0)
		{
			return true;
		}
		SSystem sSystem = SSystem.CreateInstance();
		SStage sStage = SStage.CreateInstance();
		SSpecial sSpecial = SSpecial.CreateInstance();
		SOption sOption = SOption.CreateInstance();
		SSystem system = gSS_MAIN_SYS_INFO.cmp_backup.GetSystem();
		SStage sStage2 = gSS_MAIN_SYS_INFO.cmp_backup.GetStage();
		SSpecial special = gSS_MAIN_SYS_INFO.cmp_backup.GetSpecial();
		SOption option = gSS_MAIN_SYS_INFO.cmp_backup.GetOption();
		if (sSystem.GetPlayerStock() != system.GetPlayerStock())
		{
			return false;
		}
		if (sSystem.GetKilled() != system.GetKilled())
		{
			return false;
		}
		if (sSystem.GetClearCount() != system.GetClearCount())
		{
			return false;
		}
		for (int i = 0; i < 7; i++)
		{
			SSystem.EAnnounce eAnnounce = SSystem.EAnnounce.OpenZoneSelect;
			eAnnounce = (SSystem.EAnnounce)i;
			if (sSystem.IsAnnounce(eAnnounce) != system.IsAnnounce(eAnnounce))
			{
				return false;
			}
		}
		if (memcmp(sStage2.getData(), sStage.getData()) != 0)
		{
			return false;
		}
		if (memcmp(special.getData(), sSpecial.getData()) != 0)
		{
			return false;
		}
		if (memcmp(option.getData(), sOption.getData()) != 0)
		{
			return false;
		}
		return true;
	}

	public static int memcmp(byte[] block1, byte[] block2)
	{
		if (block1.Length != block2.Length)
		{
			return block1.Length - block2.Length;
		}
		int num = block2.Length;
		for (int i = 0; i < num; i++)
		{
			if (block1[i] != block2[i])
			{
				return block1[i] - block2[i];
			}
		}
		return 0;
	}

	public AppMain(Game game, GraphicsDeviceManager graphics, GraphicsDevice graphicsDevice)
	{
		m_game = game;
		m_graphics = graphics;
		m_graphicsDevice = graphicsDevice;
		m_manager = game.Content;
		_instance = this;
		SYS_EVT_DATA[] array = new SYS_EVT_DATA[15];
		short[] ar = new short[8];
		array[0] = new SYS_EVT_DATA(null, null, null, null, null, ar, 0u);
		array[1] = new SYS_EVT_DATA(GsMainSysSystemInitEvent, null, null, null, null, new short[8] { 2, 2, 3, 0, 0, 0, 0, 0 }, 0u);
		array[2] = new SYS_EVT_DATA(DmLogoSegaInit, null, null, null, null, new short[8] { 13, 0, 0, 0, 0, 0, 0, 0 }, 0u);
		array[3] = new SYS_EVT_DATA(DmTitleStart, null, null, null, null, new short[8] { 6, 5, 8, 7, 2, 3, 0, 0 }, 0u);
		array[4] = new SYS_EVT_DATA(DmMainMenuStart, null, null, null, null, new short[8] { 6, 5, 8, 7, 2, 3, 0, 0 }, 0u);
		array[5] = new SYS_EVT_DATA(DmStgSlctStart, null, null, null, null, new short[8] { 6, 11, 7, 4, 3, 0, 0, 0 }, 0u);
		array[6] = new SYS_EVT_DATA(GmMainInit, null, null, null, null, new short[9] { 5, 6, 9, 11, 4, 3, 14, 0, 0 }, 0u);
		array[7] = new SYS_EVT_DATA(DbgDummyInitResult, null, null, null, null, new short[8] { 2, 0, 0, 0, 0, 0, 0, 0 }, 0u);
		array[8] = new SYS_EVT_DATA(DmOptionStart, null, null, null, null, new short[8] { 10, 3, 0, 0, 0, 0, 0, 0 }, 0u);
		array[9] = new SYS_EVT_DATA(GmMainInit, null, null, null, null, new short[8] { 10, 3, 10, 10, 4, 3, 10, 0 }, 0u);
