	public int AppInit(string pDocPath)
	{
		store = IsolatedStorageFile.GetUserStoreForApplication();
		PresentationParameters presentationParameter = m_graphicsDevice.PresentationParameters;
		amIPhoneInitNN();
		init(pDocPath);
		nnCalcSinCosTable();
		return 0;
	}

	public int AppMainLoop()
	{
		int result = 0;
		int am_sample_count = _am_sample_count;
		AOS_SPRITE_Pool.ReleaseUsedObjects();
		objDrawResetCache();
		amDrawResetCache();
		amFsExecuteBackgroundRead();
		amDrawBeginScene();
		if (amDrawBegin())
		{
			if (!_am_sample_is_suspended && _am_sample_suspended_count > 0)
			{
				_am_sample_suspended_count--;
			}
			if (_am_sample_suspended_count <= 0)
			{
				GsMainSysSetSuspendedFlag(_am_sample_end_suspended);
				if (_am_sample_end_suspended)
				{
					_am_sample_end_suspended = false;
				}
				int num = am_sample_count - 1;
				if (num < 0)
				{
					num = 0;
				}
				for (int i = 0; i < am_sample_count; i++)
				{
					if (i == num)
					{
						_am_sample_draw_enable = true;
					}
					else
					{
						_am_sample_draw_enable = false;
					}
					amKeyGetData();
					amPadGetData();
					amTpExecute();
					amTaskExecute();
					amDrawCloseDisplayList();
				}
				amDrawCloseDisplayList();
				amDrawGetDisplayList();
			}
			else
			{
				_am_sample_end_suspended = true;
			}
			amDrawExecRegist();
			amDrawExecCommand(16777216u);
			amDrawExecute();
			amDrawDisplay();
			setBackKeyRequest(false);
			OpenGL.glDepthMask(true);
			amDrawEnd();
			OpenGL.glFlush();
			XBOXLive.showUpdateMB();
		}
		return result;
	}

