	private void cri_proc(int arg)
	{
		AMS_ALARM alarm = null;
		amAlarmCreateTimer(alarm);
		amAlarmSetTimer(alarm, 16666u);
		while (amThreadCheckExit(_am_cri_thread) == 0)
		{
			amAlarmWaitTimer(ref alarm);
		}
		amAlarmDelete(alarm);
		amThreadQuit(_am_cri_thread);
	}

