	private static void gsInitTaskProcedure(AMS_TCB tcb)
	{
		GSS_INIT_WORK gSS_INIT_WORK = (GSS_INIT_WORK)amTaskGetWork(tcb);
		if (gSS_INIT_WORK.proc == null)
		{
			amTaskDelete(tcb);
			return;
		}
		Delegate proc = gSS_INIT_WORK.proc;
		gSS_INIT_WORK.proc(gSS_INIT_WORK);
		if ((object)gSS_INIT_WORK.proc != proc)
		{
			gSS_INIT_WORK.count = 0;
		}
		else if (gSS_INIT_WORK.count < -1)
		{
			gSS_INIT_WORK.count++;
		}
	}

	private static void gsInitTaskDestructor(AMS_TCB tcb)
	{
		g_gs_init_tcb = null;
	}

