	private static void nnBindBufferVertexDescGL(NNS_VTXLIST_GL_DESC pVtxDesc, uint flag)
	{
		OpenGL.glGenBuffer(out pVtxDesc.BufferName);
		OpenGL.glBindBuffer(34962u, pVtxDesc.BufferName);
		if ((flag & 2) != 0 && (pVtxDesc.Type & 0x10000) == 0)
		{
			NNS_VTXARRAY_GL nNS_VTXARRAY_GL = pVtxDesc.pArray[0];
			int num = nNS_VTXARRAY_GL.Stride * pVtxDesc.nVertex;
			ByteBuffer pointer = nNS_VTXARRAY_GL.Pointer;
			ByteBuffer byteBuffer = nNS_VTXARRAY_GL.Pointer + num;
			for (int i = 1; i < pVtxDesc.nArray; i++)
			{
				nNS_VTXARRAY_GL = pVtxDesc.pArray[i];
				num = nNS_VTXARRAY_GL.Stride * pVtxDesc.nVertex;
				if (pointer > nNS_VTXARRAY_GL.Pointer)
				{
					pointer = nNS_VTXARRAY_GL.Pointer;
				}
				if (byteBuffer < nNS_VTXARRAY_GL.Pointer + num)
				{
					byteBuffer = nNS_VTXARRAY_GL.Pointer + num;
				}
			}
			pVtxDesc.pVertexBuffer = pointer;
			pVtxDesc.VertexBufferSize = byteBuffer - pointer;
			OpenGL.glBufferVertexData(new GLVertexBuffer_(pVtxDesc));
			for (int i = 0; i < pVtxDesc.nArray; i++)
			{
				NNS_VTXARRAY_GL nNS_VTXARRAY_GL3 = pVtxDesc.pArray[i];
			}
		}
		else
		{
			OpenGL.glBufferVertexData(new GLVertexBuffer_(pVtxDesc));
			for (int i = 0; i < pVtxDesc.nArray; i++)
			{
				NNS_VTXARRAY_GL nNS_VTXARRAY_GL2 = pVtxDesc.pArray[i];
				nNS_VTXARRAY_GL2.Pointer.Offset = nNS_VTXARRAY_GL2.Pointer - pVtxDesc.pVertexBuffer;
			}
		}
	}

	private static void nnBindBufferPrimitiveDescGL(NNS_PRIMLIST_GL_DESC pPrimDesc, uint flag)
	{
		OpenGL.glGenBuffer(out pPrimDesc.BufferName);
		OpenGL.glBindBuffer(34963u, pPrimDesc.BufferName);
		OpenGL.glBufferIndexData(new GLIndexBuffer_ByteBuffer(pPrimDesc.pIndexBuffer, pPrimDesc.IndexBufferSize));
		for (int i = 0; i < pPrimDesc.nPrim; i++)
		{
			pPrimDesc.pIndices[i].Offset = pPrimDesc.pIndices[i] - pPrimDesc.pIndexBuffer;
		}
	}

	private static uint nnBindBufferVertexListGL(NNS_VTXLISTPTR[] dstvlist, NNS_VTXLISTPTR[] srcvlist, int nVtxList, uint flag)
	{
		for (int i = 0; i < nVtxList; i++)
		{
			if ((srcvlist[i].fType & 1) != 0)
			{
				NNS_VTXLIST_GL_DESC nNS_VTXLIST_GL_DESC = (NNS_VTXLIST_GL_DESC)srcvlist[i].pVtxList;
				NNS_VTXLIST_GL_DESC nNS_VTXLIST_GL_DESC2 = null;
				if (dstvlist != null)
				{
					dstvlist[i].fType = srcvlist[0].fType;
					nNS_VTXLIST_GL_DESC2 = (NNS_VTXLIST_GL_DESC)(dstvlist[i].pVtxList = new NNS_VTXLIST_GL_DESC());
					nNS_VTXLIST_GL_DESC2.Assign(nNS_VTXLIST_GL_DESC);
				}
				if (dstvlist != null)
				{
					nNS_VTXLIST_GL_DESC2.pArray = new NNS_VTXARRAY_GL[nNS_VTXLIST_GL_DESC.nArray];
					for (int j = 0; j < nNS_VTXLIST_GL_DESC2.nArray; j++)
					{
						nNS_VTXLIST_GL_DESC2.pArray[j] = new NNS_VTXARRAY_GL(nNS_VTXLIST_GL_DESC.pArray[j]);
					}
				}
				if ((flag & 1) != 0 && (nNS_VTXLIST_GL_DESC.Type & 6) != 0)
				{
					if ((flag & 2) != 0 && (nNS_VTXLIST_GL_DESC.Type & 0x10000) == 0)
					{
						if (dstvlist != null)
						{
							byte[] array = new byte[nNS_VTXLIST_GL_DESC.VertexBufferSize];
							Array.Copy(nNS_VTXLIST_GL_DESC.pVertexBuffer.Data, array, nNS_VTXLIST_GL_DESC.VertexBufferSize);
							nNS_VTXLIST_GL_DESC2.pVertexBuffer = ByteBuffer.Wrap(array);
							for (int k = 0; k < nNS_VTXLIST_GL_DESC.nArray; k++)
							{
								nNS_VTXLIST_GL_DESC2.pArray[k].Pointer = nNS_VTXLIST_GL_DESC2.pVertexBuffer + nNS_VTXLIST_GL_DESC.pArray[k].Pointer.Offset;
							}
							nNS_VTXLIST_GL_DESC2.VertexBufferSize = nNS_VTXLIST_GL_DESC.VertexBufferSize;
						}
						else
						{
							for (int k = 0; k < nNS_VTXLIST_GL_DESC.nArray; k++)
							{
							}
						}
					}
					else if (dstvlist != null)
					{
						byte[] array2 = new byte[nNS_VTXLIST_GL_DESC.VertexBufferSize];
						Array.Copy(nNS_VTXLIST_GL_DESC.pVertexBuffer.Data, array2, nNS_VTXLIST_GL_DESC.VertexBufferSize);
						nNS_VTXLIST_GL_DESC2.pVertexBuffer = ByteBuffer.Wrap(array2);
						for (int k = 0; k < nNS_VTXLIST_GL_DESC.nArray; k++)
						{
							nNS_VTXLIST_GL_DESC2.pArray[k].Pointer = nNS_VTXLIST_GL_DESC2.pVertexBuffer + nNS_VTXLIST_GL_DESC.pArray[k].Pointer.Offset;
						}
					}
				}
				else if (dstvlist != null)
				{
					nnBindBufferVertexDescGL(nNS_VTXLIST_GL_DESC2, flag);
					dstvlist[i].fType |= 16u;
				}
				if (nNS_VTXLIST_GL_DESC.nMatrix > 0 && dstvlist != null)
				{
					nNS_VTXLIST_GL_DESC2.pMatrixIndices = new ushort[nNS_VTXLIST_GL_DESC.nMatrix];
					Array.Copy(nNS_VTXLIST_GL_DESC.pMatrixIndices, nNS_VTXLIST_GL_DESC2.pMatrixIndices, nNS_VTXLIST_GL_DESC.nMatrix);
				}
			}
			else
			{
				NNM_ASSERT(0, "Unknown vertex foramt.\n");
			}
		}
		return 0u;
	}

	private static uint nnBindBufferPrimitiveListGL(NNS_PRIMLISTPTR[] dstplist, NNS_PRIMLISTPTR[] srcplist, int nPrimList, uint flag)
	{
		for (int i = 0; i < nPrimList; i++)
		{
			if (dstplist != null)
			{
				dstplist[i].fType = srcplist[0].fType | 2;
			}
			if ((srcplist[i].fType & 1) != 0)
			{
				NNS_PRIMLIST_GL_DESC nNS_PRIMLIST_GL_DESC = (NNS_PRIMLIST_GL_DESC)srcplist[i].pPrimList;
				NNS_PRIMLIST_GL_DESC nNS_PRIMLIST_GL_DESC2 = null;
				if (dstplist != null)
				{
					nNS_PRIMLIST_GL_DESC2 = (NNS_PRIMLIST_GL_DESC)(dstplist[i].pPrimList = new NNS_PRIMLIST_GL_DESC());
					nNS_PRIMLIST_GL_DESC2.Assign(nNS_PRIMLIST_GL_DESC);
				}
				if (dstplist != null)
				{
					nNS_PRIMLIST_GL_DESC2.pCounts = new int[nNS_PRIMLIST_GL_DESC.nPrim];
					Array.Copy(nNS_PRIMLIST_GL_DESC.pCounts, nNS_PRIMLIST_GL_DESC2.pCounts, nNS_PRIMLIST_GL_DESC.nPrim);
				}
				if (dstplist != null)
				{
					nNS_PRIMLIST_GL_DESC2.pIndices = new UShortBuffer[nNS_PRIMLIST_GL_DESC.nPrim];
					Array.Copy(nNS_PRIMLIST_GL_DESC.pIndices, nNS_PRIMLIST_GL_DESC2.pIndices, nNS_PRIMLIST_GL_DESC.nPrim);
					nnBindBufferPrimitiveDescGL(nNS_PRIMLIST_GL_DESC2, flag);
				}
			}
			else
			{
				NNM_ASSERT(0, "Unknown primitive foramt.\n");
			}
		}
		return 0u;
	}

	private static uint nnBindBufferObjectGL(NNS_OBJECT dstobj, NNS_OBJECT srcobj, uint flag)
	{
		if ((srcobj.fType & 0x10000) != 0)
		{
			NNM_ASSERT(0, "You can not bind-buffer the common-vertex-format object.\n");
			return nnCopyObject(dstobj, srcobj, 0u);
		}
		if ((srcobj.fType & 0x40) != 0 && (srcobj.fType & 0x80) == 0)
		{
			flag |= 2;
		}
		if (dstobj != null)
		{
			dstobj.Assign(srcobj);
			dstobj.fType |= 16777344u;
		}
		if (dstobj != null)
		{
			dstobj.pMatPtrList = New<NNS_MATERIALPTR>(srcobj.nMaterial);
			nnCopyMaterialList(dstobj.pMatPtrList, srcobj.pMatPtrList, srcobj.nMaterial, 0u);
		}
		else
		{
			nnCopyMaterialList(null, srcobj.pMatPtrList, srcobj.nMaterial, 0u);
		}
		if (dstobj != null)
		{
			dstobj.pVtxListPtrList = New<NNS_VTXLISTPTR>(srcobj.nVtxList);
			nnBindBufferVertexListGL(dstobj.pVtxListPtrList, srcobj.pVtxListPtrList, srcobj.nVtxList, flag);
		}
		else
		{
			nnBindBufferVertexListGL(null, srcobj.pVtxListPtrList, srcobj.nVtxList, flag);
		}
		if (dstobj != null)
		{
			dstobj.pPrimListPtrList = New<NNS_PRIMLISTPTR>(srcobj.nPrimList);
			nnBindBufferPrimitiveListGL(dstobj.pPrimListPtrList, srcobj.pPrimListPtrList, srcobj.nPrimList, flag);
		}
		else
		{
			nnBindBufferPrimitiveListGL(null, srcobj.pPrimListPtrList, srcobj.nPrimList, flag);
		}
		if (dstobj != null)
		{
			dstobj.pNodeList = new NNS_NODE[srcobj.nNode];
			for (int i = 0; i < srcobj.nNode; i++)
			{
				dstobj.pNodeList[i] = new NNS_NODE(srcobj.pNodeList[i]);
			}
		}
		if (dstobj != null)
		{
			dstobj.pSubobjList = New<NNS_SUBOBJ>(srcobj.nSubobj);
			nnCopySubobjList(dstobj.pSubobjList, srcobj.pSubobjList, srcobj.nSubobj, flag);
		}
		else
		{
			nnCopySubobjList(null, srcobj.pSubobjList, srcobj.nSubobj, flag);
		}
		return 0u;
	}

	private void nnBindBufferObjectDirectGL(NNS_OBJECT obj, uint flag)
	{
		if ((obj.fType & 0x10000) != 0)
		{
			NNM_ASSERT(0, "You can not bind-buffer the common-vertex-format object.\n");
			return;
		}
		if ((obj.fType & 0x40) != 0 && (obj.fType & 0x80) == 0)
		{
			flag |= 2;
		}
		for (int i = 0; i < obj.nVtxList; i++)
		{
			NNS_VTXLISTPTR nNS_VTXLISTPTR = obj.pVtxListPtrList[i];
			if ((nNS_VTXLISTPTR.fType & 1) != 0)
			{
				nnBindBufferVertexDescGL((NNS_VTXLIST_GL_DESC)nNS_VTXLISTPTR.pVtxList, flag);
				nNS_VTXLISTPTR.fType |= 16u;
			}
			else
			{
				NNM_ASSERT(0, "Unknown vertex foramt.\n");
			}
		}
		for (int i = 0; i < obj.nPrimList; i++)
		{
			NNS_PRIMLISTPTR nNS_PRIMLISTPTR = obj.pPrimListPtrList[i];
			if ((nNS_PRIMLISTPTR.fType & 1) != 0)
			{
				nnBindBufferPrimitiveDescGL((NNS_PRIMLIST_GL_DESC)nNS_PRIMLISTPTR.pPrimList, flag);
				nNS_PRIMLISTPTR.fType |= 2u;
			}
			else
			{
				NNM_ASSERT(0, "Unknown primitive foramt.\n");
			}
		}
		obj.fType |= 16777216u;
	}

	private static void nnDeleteBufferObjectGL(NNS_OBJECT obj)
	{
		for (int i = 0; i < obj.nVtxList; i++)
		{
			NNS_VTXLISTPTR nNS_VTXLISTPTR = obj.pVtxListPtrList[i];
			if ((nNS_VTXLISTPTR.fType & 0x10) != 0)
			{
				NNS_VTXLIST_GL_DESC nNS_VTXLIST_GL_DESC = (NNS_VTXLIST_GL_DESC)nNS_VTXLISTPTR.pVtxList;
				OpenGL.glDeleteBuffers(1, new uint[1] { nNS_VTXLIST_GL_DESC.BufferName });
			}
		}
		for (int i = 0; i < obj.nPrimList; i++)
		{
			NNS_PRIMLISTPTR nNS_PRIMLISTPTR = obj.pPrimListPtrList[i];
			if ((nNS_PRIMLISTPTR.fType & 2) != 0)
			{
				NNS_PRIMLIST_GL_DESC nNS_PRIMLIST_GL_DESC = (NNS_PRIMLIST_GL_DESC)nNS_PRIMLISTPTR.pPrimList;
				OpenGL.glDeleteBuffers(1, new uint[1] { nNS_PRIMLIST_GL_DESC.BufferName });
			}
		}
	}

	public static void nnSetUpMatrixStack(ref NNS_MATRIXSTACK mstk, uint size)
	{
		mstk = new NNS_MATRIXSTACK(size);
		NNS_MATRIX matrix = NNS_MATRIX.CreateIdentity();
		mstk.push(matrix);
	}

	public static void nnClearMatrixStack(NNS_MATRIXSTACK mstk)
	{
		mstk.clear();
		NNS_MATRIX matrix = NNS_MATRIX.CreateIdentity();
		mstk.push(matrix);
	}

	public static NNS_MATRIX nnGetCurrentMatrix(NNS_MATRIXSTACK mstk)
	{
		return mstk.get();
	}

	public static void nnSetCurrentMatrix(NNS_MATRIXSTACK mstk, NNS_MATRIX mtx)
	{
		mstk.set(mtx);
	}

	public static void nnPushMatrix(NNS_MATRIXSTACK mstk, ref SNNS_MATRIX mtx)
	{
		NNS_MATRIX nNS_MATRIX = nnmatrixstack_mtx_pool.Alloc();
		nnCopyMatrix(nNS_MATRIX, ref mtx);
		mstk.push(nNS_MATRIX);
	}

	public static void nnPushMatrix(NNS_MATRIXSTACK mstk, NNS_MATRIX mtx)
	{
		NNS_MATRIX nNS_MATRIX = nnmatrixstack_mtx_pool.Alloc();
		if (mtx == null)
		{
			nNS_MATRIX.Assign(mstk.get());
		}
		else
		{
			nNS_MATRIX.Assign(mtx);
		}
		mstk.push(nNS_MATRIX);
	}

	public static void nnPushMatrix(NNS_MATRIXSTACK mstk)
	{
		nnPushMatrix(mstk, null);
	}

	public static void nnPopMatrix(NNS_MATRIXSTACK mstk)
	{
		nnmatrixstack_mtx_pool.Release(mstk.pop());
	}

