	private static void nnSetLightRotation(int no, int rottype, int rotx, int roty, int rotz)
	{
		if (no < NNE_LIGHT_MAX)
		{
			NNS_GL_LIGHT_DATA nNS_GL_LIGHT_DATA = nnlight.nngLight.LightData[no];
			nNS_GL_LIGHT_DATA.RotType = rottype;
			nNS_GL_LIGHT_DATA.Rotation.x = rotx;
			nNS_GL_LIGHT_DATA.Rotation.y = roty;
			nNS_GL_LIGHT_DATA.Rotation.z = rotz;
			float s;
			float c;
			nnSinCos(rotx, out s, out c);
			float s2;
			float c2;
			nnSinCos(roty, out s2, out c2);
			float s3;
			float c3;
			nnSinCos(rotz, out s3, out c3);
			switch (rottype)
			{
			case 1:
				nNS_GL_LIGHT_DATA.Direction.x = (0f - c2) * s3 * s - s2 * c;
				nNS_GL_LIGHT_DATA.Direction.y = c3 * s;
				nNS_GL_LIGHT_DATA.Direction.z = s2 * s3 * s - c2 * c;
				break;
			case 4:
				nNS_GL_LIGHT_DATA.Direction.x = (0f - s2) * c;
				nNS_GL_LIGHT_DATA.Direction.y = s;
				nNS_GL_LIGHT_DATA.Direction.z = (0f - c2) * c;
				break;
			default:
				nNS_GL_LIGHT_DATA.Direction.x = (0f - c3) * s2 * c - s3 * s;
				nNS_GL_LIGHT_DATA.Direction.y = (0f - s3) * s2 * c + c3 * s;
				nNS_GL_LIGHT_DATA.Direction.z = (0f - c2) * c;
				break;
			}
		}
	}

