	private static void nnSetLight(int no, object light, uint type)
	{
		if (no < NNE_LIGHT_MAX)
		{
			NNS_GL_LIGHT_DATA nNS_GL_LIGHT_DATum = nnlight.nngLight.LightData[no];
			nnSetLightType(no, type);
			switch (type & 0x1003F)
			{
			case 1u:
			{
				NNS_LIGHT_PARALLEL nNS_LIGHT_PARALLEL = (NNS_LIGHT_PARALLEL)(NNS_LIGHT_TARGET_DIRECTIONAL)light;
				nnSetLightColor(no, nNS_LIGHT_PARALLEL.Color.r, nNS_LIGHT_PARALLEL.Color.g, nNS_LIGHT_PARALLEL.Color.b);
				nnSetLightIntensity(no, nNS_LIGHT_PARALLEL.Intensity);
				nnSetLightDirection(no, nNS_LIGHT_PARALLEL.Direction.x, nNS_LIGHT_PARALLEL.Direction.y, nNS_LIGHT_PARALLEL.Direction.z);
				nnSetLightAmbientGL(no, 0f, 0f, 0f);
				break;
			}
			case 2u:
			{
				NNS_LIGHT_POINT nNS_LIGHT_POINT = (NNS_LIGHT_POINT)(NNS_LIGHT_TARGET_DIRECTIONAL)light;
				nnSetLightColor(no, nNS_LIGHT_POINT.Color.r, nNS_LIGHT_POINT.Color.g, nNS_LIGHT_POINT.Color.b);
				nnSetLightIntensity(no, nNS_LIGHT_POINT.Intensity);
				nnSetLightPosition(no, nNS_LIGHT_POINT.Position.x, nNS_LIGHT_POINT.Position.y, nNS_LIGHT_POINT.Position.z);
				nnSetLightFallOff(no, nNS_LIGHT_POINT.FallOffStart, nNS_LIGHT_POINT.FallOffEnd);
				nnSetLightAmbientGL(no, 0f, 0f, 0f);
				break;
			}
			case 4u:
			{
				NNS_LIGHT_TARGET_SPOT nNS_LIGHT_TARGET_SPOT = (NNS_LIGHT_TARGET_SPOT)(NNS_LIGHT_TARGET_DIRECTIONAL)light;
				nnSetLightColor(no, nNS_LIGHT_TARGET_SPOT.Color.r, nNS_LIGHT_TARGET_SPOT.Color.g, nNS_LIGHT_TARGET_SPOT.Color.b);
				nnSetLightIntensity(no, nNS_LIGHT_TARGET_SPOT.Intensity);
				nnSetLightPosition(no, nNS_LIGHT_TARGET_SPOT.Position.x, nNS_LIGHT_TARGET_SPOT.Position.y, nNS_LIGHT_TARGET_SPOT.Position.z);
				nnSetLightTarget(no, nNS_LIGHT_TARGET_SPOT.Target.x, nNS_LIGHT_TARGET_SPOT.Target.y, nNS_LIGHT_TARGET_SPOT.Target.z);
				nnSetLightAngle(no, nNS_LIGHT_TARGET_SPOT.InnerAngle, nNS_LIGHT_TARGET_SPOT.OuterAngle);
				nnSetLightFallOff(no, nNS_LIGHT_TARGET_SPOT.FallOffStart, nNS_LIGHT_TARGET_SPOT.FallOffEnd);
				nnSetLightAmbientGL(no, 0f, 0f, 0f);
				break;
			}
			case 8u:
			{
				NNS_LIGHT_ROTATION_SPOT nNS_LIGHT_ROTATION_SPOT = (NNS_LIGHT_ROTATION_SPOT)(NNS_LIGHT_TARGET_DIRECTIONAL)light;
				nnSetLightColor(no, nNS_LIGHT_ROTATION_SPOT.Color.r, nNS_LIGHT_ROTATION_SPOT.Color.g, nNS_LIGHT_ROTATION_SPOT.Color.b);
				nnSetLightIntensity(no, nNS_LIGHT_ROTATION_SPOT.Intensity);
				nnSetLightPosition(no, nNS_LIGHT_ROTATION_SPOT.Position.x, nNS_LIGHT_ROTATION_SPOT.Position.y, nNS_LIGHT_ROTATION_SPOT.Position.z);
				nnSetLightRotation(no, nNS_LIGHT_ROTATION_SPOT.RotType, nNS_LIGHT_ROTATION_SPOT.Rotation.x, nNS_LIGHT_ROTATION_SPOT.Rotation.y, nNS_LIGHT_ROTATION_SPOT.Rotation.z);
				nnSetLightAngle(no, nNS_LIGHT_ROTATION_SPOT.InnerAngle, nNS_LIGHT_ROTATION_SPOT.OuterAngle);
				nnSetLightFallOff(no, nNS_LIGHT_ROTATION_SPOT.FallOffStart, nNS_LIGHT_ROTATION_SPOT.FallOffEnd);
				nnSetLightAmbientGL(no, 0f, 0f, 0f);
				break;
			}
			case 16u:
				mppAssertNotImpl();
				break;
			case 32u:
				mppAssertNotImpl();
				break;
			case 65536u:
				mppAssertNotImpl();
				break;
			}
		}
	}

	private static void nnPutLightSettings()
	{
		OpenGL.glMatrixMode(5888u);
		Matrix matrix = (Matrix)nnlight.nngLightMtx;
		OpenGL.glLoadMatrixf(ref matrix);
		OpenGL.glArray4f param = default(OpenGL.glArray4f);
		param.f0 = nnlight.nngLight.AmbientColor.r;
		param.f1 = nnlight.nngLight.AmbientColor.g;
		param.f2 = nnlight.nngLight.AmbientColor.b;
		param.f3 = nnlight.nngLight.AmbientColor.a;
		OpenGL.glLightModelfv(2899u, param);
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		int i = 0;
		int num4 = 0;
		for (; i < NNE_LIGHT_MAX; i++)
		{
			NNS_GL_LIGHT_DATA nNS_GL_LIGHT_DATA = nnlight.nngLight.LightData[i];
			if (nNS_GL_LIGHT_DATA.bEnable == 0)
			{
				continue;
			}
			switch (nNS_GL_LIGHT_DATA.fType)
			{
			case 1u:
			case 16u:
			case 32u:
				if (num < 4)
				{
					num++;
				}
				else
				{
					nNS_GL_LIGHT_DATA.bEnable = 0;
				}
				break;
			case 2u:
				if (num2 < 4)
				{
					num2++;
				}
				else
				{
					nNS_GL_LIGHT_DATA.bEnable = 0;
				}
				break;
			case 4u:
			case 8u:
				if (num3 < 4)
				{
					num3++;
				}
				else
				{
					nNS_GL_LIGHT_DATA.bEnable = 0;
				}
				break;
			}
		}
		nnlight.nngNumParallelLight = num;
		nnlight.nngNumPointLight = num2;
		nnlight.nngNumSpotLight = num3;
		int num5 = -1;
		int num6 = -1;
		int num7 = -1;
		int num8 = -1;
		i = 0;
		num4 = 0;
		OpenGL.glArray4f param2 = default(OpenGL.glArray4f);
		OpenGL.glArray4f param3 = default(OpenGL.glArray4f);
		OpenGL.glArray4f param5 = default(OpenGL.glArray4f);
		OpenGL.glArray4f dst = default(OpenGL.glArray4f);
		OpenGL.glArray4f param4 = default(OpenGL.glArray4f);
		OpenGL.glArray4f dst2 = default(OpenGL.glArray4f);
		OpenGL.glArray4f param6 = default(OpenGL.glArray4f);
		for (; i < NNE_LIGHT_MAX; i++)
		{
			NNS_GL_LIGHT_DATA nNS_GL_LIGHT_DATA2 = nnlight.nngLight.LightData[i];
			if (1 == nNS_GL_LIGHT_DATA2.bEnable)
