	public static bool amTpIsTouchOn(int index)
	{
		return (_am_tp_touch[index].flag & 1) != 0;
	}

	public static bool amTpIsTouchPush(int index)
	{
		return (_am_tp_touch[index].flag & 4) != 0;
	}

	public static bool amTpIsTouchPull(int index)
	{
		return (_am_tp_touch[index].flag & 8) != 0;
	}

	public static void AMM_TP_BIT_SET16(ref ushort val, int shift, bool b)
	{
		byte b2 = (byte)(b ? 1u : 0u);
		val = (ushort)((val & ~(1 << shift)) | (b2 << shift));
	}

	private void amTpInit()
	{
		for (int i = 0; i < 4; i++)
		{
			_am_tp_touch[i] = new AMS_TP_TOUCH_STATUS();
		}
	}

	private void amTpExecute()
	{
		_amTpUpdateTouch_req();
		for (int i = 0; i < 4; i++)
		{
			amTpUpdateStatus(_am_tp_touch[i], _am_tp_touch[i].core);
		}
	}

	private void amTpUpdateStatus(AMS_TP_TOUCH_STATUS status, AMS_TP_TOUCH_CORE core)
	{
		bool flag = (((core.sampling_flag & 1) != 0) ? true : false);
		bool flag2 = (status.flag & 1) != 0;
		bool flag3 = flag ^ flag2;
		AMM_TP_BIT_SET16(ref status.flag, 7, ((core.sampling_flag & 0x80) != 0) ? true : false);
		AMM_TP_BIT_SET16(ref status.flag, 1, flag2);
		AMM_TP_BIT_SET16(ref status.flag, 0, flag);
		AMM_TP_BIT_SET16(ref status.flag, 2, flag3 && flag);
		AMM_TP_BIT_SET16(ref status.flag, 3, flag3 && flag2);
		status.prev[0] = status.on[0];
		status.prev[1] = status.on[1];
		ushort[] sampling_buf = core.sampling_buf;
		status.on[0] = sampling_buf[0];
		status.on[1] = sampling_buf[1];
		if ((status.flag & 4) != 0)
		{
			status.push[0] = status.on[0];
			status.push[1] = status.on[1];
		}
		else if ((status.flag & 8) != 0)
		{
			status.pull[0] = status.prev[0];
			status.pull[1] = status.prev[1];
		}
		if (status.core != core)
		{
			status.core = core;
		}
	}

	private void _amTpUpdateTouch_req()
	{
		AMS_IPHONE_TP_DATA amTpUpdateTouch_req_DispData = _amTpUpdateTouch_req_DispData;
		for (int i = 0; i < 4; i++)
		{
			AMS_TP_TOUCH_CORE core = _am_tp_touch[i].core;
			amIPhoneRequestTouch(amTpUpdateTouch_req_DispData, i);
			if (amTpUpdateTouch_req_DispData.touch == 1)
			{
				if (amTpUpdateTouch_req_DispData.validity == 1)
				{
					core.sampling_buf[0] = amTpUpdateTouch_req_DispData.x;
					core.sampling_buf[1] = amTpUpdateTouch_req_DispData.y;
					core.sampling_flag |= 1;
					core.sampling_flag &= 127;
				}
				else
				{
					core.sampling_flag |= 128;
				}
			}
			else
			{
				core.sampling_flag &= 126;
			}
		}
	}

