	private static AMS_TCB amTaskMake(AMS_TASK taskp, TaskProc proc, TaskProc dest, uint prio, uint user, uint attr, string name, uint stall, int group, uint run)
	{
		AMS_TCB aMS_TCB = GlobalPool<AMS_TCB>.Alloc();
		aMS_TCB.name = name;
		AMS_TCB_FOOTER aMS_TCB_FOOTER = amTaskGetTcbFooter(aMS_TCB);
		aMS_TCB_FOOTER.cpu_cnt = 0u;
		aMS_TCB_FOOTER.cpu_cnt_max = 0u;
		aMS_TCB.priority = prio;
		aMS_TCB.priority = prio;
		aMS_TCB.user_id = user;
		aMS_TCB.attribute = attr;
		amTaskSetProcedure(aMS_TCB, proc);
		amTaskSetDestructor(aMS_TCB, dest);
		AMS_TCB next = taskp.tcb_head.next;
		while (next != taskp.tcb_tail && next.priority <= prio)
		{
			next = next.next;
		}
		next.prev.next = aMS_TCB;
		aMS_TCB.prev = next.prev;
		next.prev = aMS_TCB;
		aMS_TCB.next = next;
		return aMS_TCB;
	}

