	{
		mppAssertNotImpl();
		if (user == 0)
		{
			user = uint.MaxValue;
		}
		AMS_TCB next = taskp.tcb_head.next;
		switch (flag)
		{
		default:
			return;
		case 0u:
			while (next != taskp.tcb_tail)
			{
				if ((next.user_id & user) != 0 && (next.attribute & attr) != 0)
				{
					amTaskWakeup(next);
				}
				next = next.next;
			}
			return;
		case 1u:
			while (next != taskp.tcb_tail)
			{
				if ((next.user_id & user) != 0 && (next.attribute & attr) == attr)
				{
					amTaskWakeup(next);
				}
				next = next.next;
			}
			return;
		case 2u:
			while (next != taskp.tcb_tail)
			{
				if ((next.user_id & user) != 0 && (next.attribute & attr) == 0)
				{
					amTaskWakeup(next);
				}
				next = next.next;
			}
			return;
		case 3u:
			break;
		}
		while (next != taskp.tcb_tail)
		{
			if ((next.user_id & user) != 0 && (next.attribute & attr) != attr)
			{
				amTaskWakeup(next);
			}
			next = next.next;
		}
	}

	public static void amTaskWakeupPriority(AMS_TASK taskp, uint prio_begin, uint prio_end, uint user)
	{
		mppAssertNotImpl();
		AMS_TCB next = taskp.tcb_head.next;
		while (next != taskp.tcb_tail && next.priority < prio_begin)
		{
			next = next.next;
		}
		while (next != taskp.tcb_tail && next.priority <= prio_end)
		{
			if (user == 0 || (next.user_id & user) != 0)
			{
				amTaskWakeup(next);
			}
			next = next.next;
		}
	}

