	public static void GmStartMsgInit()
	{
		int num = GsEnvGetLanguage();
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		g_gm_main_system.game_flag |= 16777216u;
		gm_start_msg_end_state = false;
		gm_start_msg_tcb = MTM_TASK_MAKE_TCB(gmStartMsgMain, gmStartMsgDest, 0u, 3, 18502u, 5, () => new GMS_SMSG_MGR_WORK(), "GM_S_MSG_MGR");
		GMS_SMSG_MGR_WORK gMS_SMSG_MGR_WORK = (GMS_SMSG_MGR_WORK)gm_start_msg_tcb.work;
		gMS_SMSG_MGR_WORK.Clear();
		ObjDrawSetNNCommandStateTbl(16u, 13u, true);
		ObjDrawSetNNCommandStateTbl(17u, 14u, true);
		g_obj.ppPost = gmStartMsgObjPost;
		switch (g_gs_main_sys_info.stage_id)
		{
		default:
			gMS_SMSG_MGR_WORK.msg_type = 0;
			break;
		case 9:
			gMS_SMSG_MGR_WORK.msg_type = 1;
			break;
		case 21:
		case 22:
		case 23:
		case 24:
		case 25:
		case 26:
		case 27:
			gMS_SMSG_MGR_WORK.msg_type = 2;
			break;
		}
		AMS_AMB_HEADER aMS_AMB_HEADER = GmGameDatGetGimmickData(991);
		NNS_TEXLIST texlist = AoTexGetTexList(gm_start_msg_aos_tex[0]);
		for (int num2 = 0; num2 < gm_start_msg_ama_act_num_tbl[gMS_SMSG_MGR_WORK.msg_type]; num2++)
		{
			gMS_SMSG_MGR_WORK.ama_2d_work[num2] = (GMS_SMSG_2D_OBJ_WORK)OBM_OBJECT_TASK_DETAIL_INIT(18512, 5, 0, 3, () => new GMS_SMSG_2D_OBJ_WORK(), "GM_SMSG");
			uint num3 = (uint)num2;
			if ((0x200 & gSS_MAIN_SYS_INFO.game_flag) != 0)
			{
				switch (gMS_SMSG_MGR_WORK.msg_type)
				{
				case 1:
					if (num3 == 0)
					{
						num3 = 2u;
					}
					break;
				case 2:
					if (num3 == 0)
					{
						num3 = 2u;
					}
					break;
				}
			}
			ObjObjectAction2dAMALoadSetTexlist(gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_work, gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_2d, null, null, num * 2, aMS_AMB_HEADER, texlist, num3, 0);
			gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_work.ppOut = null;
			gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_work.ppFunc = gmStartMsgObjMain;
			gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_work.disp_flag |= 32u;
			gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_work.flag |= 18u;
			gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_work.move_flag |= 8448u;
			gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_work.disp_flag |= 1048960u;
			gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_work.pos.x = gm_start_msg_ama_act_pos_tbl[gMS_SMSG_MGR_WORK.msg_type][num][num2][0];
			gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_work.pos.y = gm_start_msg_ama_act_pos_tbl[gMS_SMSG_MGR_WORK.msg_type][num][num2][1];
			if (num2 == 0)
			{
				gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_work.scale.x = GMD_SMSG_ACT_SCALE;
				gMS_SMSG_MGR_WORK.ama_2d_work[num2].obj_work.scale.y = GMD_SMSG_ACT_SCALE;
			}
		}
		for (int num2 = 0; num2 < GMD_SMSG_AMA_ACT_ACTION_MAX; num2++)
		{
			int num4 = gm_start_msg_body_act_id_table[gMS_SMSG_MGR_WORK.msg_type][num2];
			if ((0x200 & gSS_MAIN_SYS_INFO.game_flag) == 0)
			{
				switch (num4)
				{
				case 7:
					num4 = 0;
					break;
				default:
					num4 = -1;
					break;
				case -1:
				case 4:
				case 5:
					break;
				}
			}
			if (num4 < 0)
			{
				gMS_SMSG_MGR_WORK.ama_2d_work_act[num2] = null;
				continue;
			}
			gMS_SMSG_MGR_WORK.ama_2d_work_act[num2] = (GMS_SMSG_2D_OBJ_WORK)OBM_OBJECT_TASK_DETAIL_INIT(18512, 5, 0, 3, () => new GMS_SMSG_2D_OBJ_WORK(), "GM_SMSG");
			texlist = AoTexGetTexList(gm_start_msg_aos_tex[2]);
			ObjObjectAction2dAMALoadSetTexlist(gMS_SMSG_MGR_WORK.ama_2d_work_act[num2].obj_work, gMS_SMSG_MGR_WORK.ama_2d_work_act[num2].obj_2d, null, null, aMS_AMB_HEADER.file_num - 2, aMS_AMB_HEADER, texlist, (uint)num4, 0);
			gMS_SMSG_MGR_WORK.ama_2d_work_act[num2].obj_work.ppOut = null;
			gMS_SMSG_MGR_WORK.ama_2d_work_act[num2].obj_work.ppFunc = gmStartMsgObjMain;
			gMS_SMSG_MGR_WORK.ama_2d_work_act[num2].obj_work.disp_flag |= 32u;
			gMS_SMSG_MGR_WORK.ama_2d_work_act[num2].obj_work.flag |= 18u;
			gMS_SMSG_MGR_WORK.ama_2d_work_act[num2].obj_work.move_flag |= 8448u;
			gMS_SMSG_MGR_WORK.ama_2d_work_act[num2].obj_work.disp_flag |= 1048960u;
		}
		gMS_SMSG_MGR_WORK.func = gmStartMsgMain_StartWait;
		gmStartMsgMain_StartWait(gMS_SMSG_MGR_WORK);
	}

	public static void gmStartMsgDest(MTS_TASK_TCB tcb)
	{
		UNREFERENCED_PARAMETER(tcb);
		gm_start_msg_end_state = true;
	}

	public static void gmStartMsgMain_StartWait(GMS_SMSG_MGR_WORK mgr_work)
	{
		if ((g_gm_main_system.game_flag & 0x1000) == 0)
		{
			mgr_work.flag |= GMD_SMSG_FLAG_WIN_DISP;
			ObjObjectPause(2);
			g_gm_main_system.game_flag &= 4294964223u;
			mgr_work.win_per = 0f;
			GmSoundPlaySE("Window");
			mgr_work.timer = 0;
			mgr_work.func = gmStartMsgMain_WindowOpen;
		}
	}

	public static void gmStartMsgMain_WindowOpen(GMS_SMSG_MGR_WORK mgr_work)
	{
		mgr_work.timer++;
		if (mgr_work.timer >= 8)
		{
			mgr_work.win_per = 1f;
			for (int i = 0; i < gm_start_msg_ama_act_num_tbl[mgr_work.msg_type]; i++)
			{
				mgr_work.ama_2d_work[i].obj_work.disp_flag &= 4294967263u;
			}
			for (int i = 0; i < GMD_SMSG_AMA_ACT_ACTION_MAX; i++)
			{
				if (mgr_work.ama_2d_work_act[i] != null)
				{
					mgr_work.ama_2d_work_act[i].obj_work.disp_flag &= 4294967263u;
				}
			}
			mgr_work.timer = GMD_SMSG_KEY_WAIT;
			mgr_work.func = gmStartMsgMain_KeyWait;
		}
		else
		{
			mgr_work.win_per = (float)mgr_work.timer / 8f;
		}
	}

	public static void gmStartMsgMain_KeyWait(GMS_SMSG_MGR_WORK mgr_work)
	{
		if (mgr_work.timer != 0)
		{
			mgr_work.timer--;
		}
		else
		{
			if (!amTpIsTouchOn(0))
			{
				return;
			}
			for (int i = 0; i < gm_start_msg_ama_act_num_tbl[mgr_work.msg_type]; i++)
			{
				mgr_work.ama_2d_work[i].obj_work.disp_flag |= 32u;
			}
			for (int i = 0; i < GMD_SMSG_AMA_ACT_ACTION_MAX; i++)
			{
				if (mgr_work.ama_2d_work_act[i] != null)
				{
					mgr_work.ama_2d_work_act[i].obj_work.disp_flag |= 32u;
				}
			}
			mgr_work.timer = 8;
			mgr_work.func = gmStartMsgMain_WindowClose;
		}
	}

	public static void gmStartMsgMain_WindowClose(GMS_SMSG_MGR_WORK mgr_work)
	{
		mgr_work.timer--;
		if (mgr_work.timer <= 0)
		{
			mgr_work.win_per = 0f;
			mgr_work.func = null;
			mgr_work.flag |= GMD_SMSG_FLAG_END;
		}
		else
		{
			mgr_work.win_per = (float)mgr_work.timer / 8f;
		}
	}

	public static bool GMM_PLAYER_IS_TOUCH_SUPER_SONIC_REGION(int x, int y)
	{
		if (x > 390 && x < 475)
		{
			if (y > 5)
			{
				return y < 85;
			}
			return false;
		}
		return false;
	}

	public static void GMD_PLAYER_WATER_SET(ref int fSpd)
	{
		fSpd >>= 1;
	}

	public static void GMD_PLAYER_WATERJUMP_SET(ref int fSpd)
	{
		fSpd = (fSpd >> 1) + (fSpd >> 2);
	}

	public static int GMD_PLAYER_WATER_GET(int fSpd)
	{
		return fSpd >> 1;
	}

	public static int GMD_PLAYER_WATERJUMP_GET(int fSpd)
	{
		return (fSpd >> 1) + (fSpd >> 2);
	}

	private static void GmPlayerBuild()
	{
		AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile((AMS_FS)g_gm_player_data_work[0][0].pData);
		AMS_AMB_HEADER amb_tex = readAMBFile((AMS_FS)g_gm_player_data_work[0][1].pData);
		g_gm_ply_son_obj_3d_list = New<OBS_ACTION3D_NN_WORK>(aMS_AMB_HEADER.file_num);
		ArrayPointer<OBS_ACTION3D_NN_WORK> arrayPointer = new ArrayPointer<OBS_ACTION3D_NN_WORK>(g_gm_ply_son_obj_3d_list);
		int num = 0;
		while (num < aMS_AMB_HEADER.file_num)
		{
			ObjAction3dNNModelLoad(arrayPointer, null, null, num, aMS_AMB_HEADER, null, amb_tex, 0u);
			num++;
			++arrayPointer;
		}
		aMS_AMB_HEADER = readAMBFile((AMS_FS)g_gm_player_data_work[0][2].pData);
		amb_tex = readAMBFile((AMS_FS)g_gm_player_data_work[0][3].pData);
		g_gm_ply_sson_obj_3d_list = New<OBS_ACTION3D_NN_WORK>(aMS_AMB_HEADER.file_num);
		arrayPointer = new ArrayPointer<OBS_ACTION3D_NN_WORK>(g_gm_ply_sson_obj_3d_list);
		num = 0;
		while (num < aMS_AMB_HEADER.file_num)
		{
			ObjAction3dNNModelLoad(arrayPointer, null, null, num, aMS_AMB_HEADER, null, amb_tex, 0u);
			num++;
			++arrayPointer;
		}
		gm_ply_obj_3d_list_tbl = new OBS_ACTION3D_NN_WORK[7][][]
		{
			new OBS_ACTION3D_NN_WORK[2][] { g_gm_ply_son_obj_3d_list, g_gm_ply_sson_obj_3d_list },
			new OBS_ACTION3D_NN_WORK[2][] { g_gm_ply_son_obj_3d_list, g_gm_ply_sson_obj_3d_list },
			new OBS_ACTION3D_NN_WORK[2][] { g_gm_ply_son_obj_3d_list, g_gm_ply_sson_obj_3d_list },
			new OBS_ACTION3D_NN_WORK[2][] { g_gm_ply_son_obj_3d_list, g_gm_ply_sson_obj_3d_list },
			new OBS_ACTION3D_NN_WORK[2][] { g_gm_ply_son_obj_3d_list, g_gm_ply_sson_obj_3d_list },
			new OBS_ACTION3D_NN_WORK[2][] { g_gm_ply_son_obj_3d_list, g_gm_ply_sson_obj_3d_list },
			new OBS_ACTION3D_NN_WORK[2][] { g_gm_ply_son_obj_3d_list, g_gm_ply_sson_obj_3d_list }
		};
	}

	private static void GmPlayerFlush()
	{
		AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile((AMS_FS)g_gm_player_data_work[0][0].pData);
		ArrayPointer<OBS_ACTION3D_NN_WORK> arrayPointer = new ArrayPointer<OBS_ACTION3D_NN_WORK>(g_gm_ply_son_obj_3d_list);
		int num = 0;
		while (num < aMS_AMB_HEADER.file_num)
		{
			ObjAction3dNNModelRelease(arrayPointer);
			num++;
			++arrayPointer;
		}
		aMS_AMB_HEADER = readAMBFile((AMS_FS)g_gm_player_data_work[0][2].pData);
		arrayPointer = new ArrayPointer<OBS_ACTION3D_NN_WORK>(g_gm_ply_sson_obj_3d_list);
		num = 0;
		while (num < aMS_AMB_HEADER.file_num)
		{
			ObjAction3dNNModelRelease(~arrayPointer);
			num++;
			++arrayPointer;
		}
	}

	private static bool GmPlayerBuildCheck()
	{
		AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile((AMS_FS)g_gm_player_data_work[0][0].pData);
		ArrayPointer<OBS_ACTION3D_NN_WORK> arrayPointer = new ArrayPointer<OBS_ACTION3D_NN_WORK>(g_gm_ply_son_obj_3d_list);
		int num = 0;
		while (num < aMS_AMB_HEADER.file_num)
		{
			if (!ObjAction3dNNModelLoadCheck(arrayPointer))
			{
				return false;
			}
			num++;
			++arrayPointer;
		}
		aMS_AMB_HEADER = readAMBFile((AMS_FS)g_gm_player_data_work[0][2].pData);
		arrayPointer = new ArrayPointer<OBS_ACTION3D_NN_WORK>(g_gm_ply_sson_obj_3d_list);
		num = 0;
		while (num < aMS_AMB_HEADER.file_num)
		{
			if (!ObjAction3dNNModelLoadCheck(arrayPointer))
			{
				return false;
			}
			num++;
			++arrayPointer;
		}
		return true;
	}

	private static bool GmPlayerFlushCheck()
	{
		if (g_gm_ply_son_obj_3d_list != null)
		{
			AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile((AMS_FS)g_gm_player_data_work[0][0].pData);
			ArrayPointer<OBS_ACTION3D_NN_WORK> arrayPointer = new ArrayPointer<OBS_ACTION3D_NN_WORK>(g_gm_ply_son_obj_3d_list);
			int num = 0;
			while (num < aMS_AMB_HEADER.file_num)
			{
				if (!ObjAction3dNNModelReleaseCheck(arrayPointer))
				{
					return false;
				}
				num++;
				++arrayPointer;
			}
			g_gm_ply_son_obj_3d_list = null;
		}
		if (g_gm_ply_sson_obj_3d_list != null)
		{
			AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile((AMS_FS)g_gm_player_data_work[0][2].pData);
			ArrayPointer<OBS_ACTION3D_NN_WORK> arrayPointer = new ArrayPointer<OBS_ACTION3D_NN_WORK>(g_gm_ply_sson_obj_3d_list);
			int num = 0;
			while (num < aMS_AMB_HEADER.file_num)
			{
				if (!ObjAction3dNNModelReleaseCheck(arrayPointer))
				{
					return false;
				}
				num++;
				++arrayPointer;
			}
			g_gm_ply_sson_obj_3d_list = null;
		}
		return true;
	}

	private static void GmPlayerRelease()
	{
		for (int i = 0; (long)i < 1L; i++)
		{
			for (int j = 0; j < 5; j++)
			{
				ObjDataRelease(g_gm_player_data_work[i][j]);
			}
		}
	}

	private static GMS_PLAYER_WORK GmPlayerInit(int char_id, ushort ctrl_id, ushort player_id, ushort camera_id)
	{
		ushort[] array = new ushort[3] { 0, 6, 1 };
		ushort[] array2 = new ushort[3] { 65533, 65535, 65534 };
		if (char_id >= 7)
		{
			char_id = 0;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = OBM_OBJECT_TASK_DETAIL_INIT(4352, 1, 0, 0, () => new GMS_PLAYER_WORK(), "PLAYER OBJ");
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmPlayerExit);
		oBS_OBJECT_WORK.ppUserRelease = gmPlayerObjRelease;
		oBS_OBJECT_WORK.ppUserReleaseWait = gmPlayerObjReleaseWait;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)oBS_OBJECT_WORK;
		gMS_PLAYER_WORK.player_id = (byte)player_id;
		gMS_PLAYER_WORK.camera_no = (byte)camera_id;
		gMS_PLAYER_WORK.ctrl_id = (byte)ctrl_id;
		gMS_PLAYER_WORK.char_id = (byte)char_id;
		gMS_PLAYER_WORK.act_state = -1;
		gMS_PLAYER_WORK.prev_act_state = -1;
		nnMakeUnitMatrix(gMS_PLAYER_WORK.ex_obj_mtx_r);
		GmPlayerInitModel(gMS_PLAYER_WORK);
		gMS_PLAYER_WORK.key_map[0] = 1;
		gMS_PLAYER_WORK.key_map[1] = 2;
		gMS_PLAYER_WORK.key_map[2] = 4;
		gMS_PLAYER_WORK.key_map[3] = 8;
		gMS_PLAYER_WORK.key_map[4] = 32;
		gMS_PLAYER_WORK.key_map[5] = 128;
		gMS_PLAYER_WORK.key_map[6] = 64;
		gMS_PLAYER_WORK.key_map[7] = 16;
		oBS_OBJECT_WORK.obj_type = 1;
		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.flag |= 1u;
		oBS_OBJECT_WORK.ppOut = gmPlayerDispFunc;
		if (!GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			oBS_OBJECT_WORK.ppIn = gmPlayerDefaultInFunc;
		}
		else
		{
			oBS_OBJECT_WORK.ppIn = gmPlayerSplStgInFunc;
		}
		oBS_OBJECT_WORK.ppLast = gmPlayerDefaultLastFunc;
		oBS_OBJECT_WORK.ppMove = GmPlySeqMoveFunc;
		oBS_OBJECT_WORK.disp_flag |= 2048u;
		GmPlySeqSetSeqState(gMS_PLAYER_WORK);
		GmPlayerStateInit(gMS_PLAYER_WORK);
		ObjObjectFieldRectSet(oBS_OBJECT_WORK, -6, -12, 6, 13);
		ObjObjectGetRectBuf(oBS_OBJECT_WORK, gMS_PLAYER_WORK.rect_work, 3);
		for (int num = 0; num < 3; num++)
		{
			ObjRectGroupSet(gMS_PLAYER_WORK.rect_work[num], 0, 2);
			ObjRectAtkSet(gMS_PLAYER_WORK.rect_work[num], array[num], 1);
			ObjRectDefSet(gMS_PLAYER_WORK.rect_work[num], array2[num], 0);
			gMS_PLAYER_WORK.rect_work[num].parent_obj = oBS_OBJECT_WORK;
			gMS_PLAYER_WORK.rect_work[num].flag &= 4294967291u;
			gMS_PLAYER_WORK.rect_work[num].rect.back = -16;
			gMS_PLAYER_WORK.rect_work[num].rect.front = 16;
		}
		gMS_PLAYER_WORK.rect_work[0].ppDef = gmPlayerDefFunc;
		gMS_PLAYER_WORK.rect_work[1].ppHit = gmPlayerAtkFunc;
		gMS_PLAYER_WORK.rect_work[0].flag |= 128u;
		gMS_PLAYER_WORK.rect_work[1].flag |= 32u;
		gMS_PLAYER_WORK.rect_work[2].flag |= 224u;
		if (GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			ObjObjectFieldRectSet(oBS_OBJECT_WORK, -7, -8, 7, 10);
			ObjRectWorkZSet(gMS_PLAYER_WORK.rect_work[2], -11, -11, -500, 11, 11, 500);
			ObjRectWorkZSet(gMS_PLAYER_WORK.rect_work[0], -12, -12, -500, 12, 12, 500);
			ObjRectWorkZSet(gMS_PLAYER_WORK.rect_work[1], -13, -13, -500, 13, 13, 500);
		}
		else
		{
			ObjRectWorkZSet(gMS_PLAYER_WORK.rect_work[2], -8, -19, -500, 8, 13, 500);
			ObjRectWorkZSet(gMS_PLAYER_WORK.rect_work[0], -8, -19, -500, 8, 13, 500);
			ObjRectWorkZSet(gMS_PLAYER_WORK.rect_work[1], -16, -19, -500, 16, 13, 500);
		}
		gMS_PLAYER_WORK.rect_work[1].flag &= 4294967291u;
		ObjRectWorkZSet(gm_ply_touch_rect[0], -16, -51, -500, 64, 37, 500);
		ObjRectWorkZSet(gm_ply_touch_rect[1], -64, -51, -500, -16, 37, 500);
		gMS_PLAYER_WORK.calc_accel.x = 0f;
		gMS_PLAYER_WORK.calc_accel.y = 0f;
		gMS_PLAYER_WORK.calc_accel.z = 0f;
		gMS_PLAYER_WORK.control_type = 2;
		gMS_PLAYER_WORK.jump_rect = gm_player_push_jump_key_rect[2];
		gMS_PLAYER_WORK.ssonic_rect = gm_player_push_ssonic_key_rect[2];
		if ((g_gs_main_sys_info.game_flag & 1) != 0)
		{
			gMS_PLAYER_WORK.control_type = 0;
			gMS_PLAYER_WORK.jump_rect = gm_player_push_jump_key_rect[0];
			gMS_PLAYER_WORK.ssonic_rect = gm_player_push_ssonic_key_rect[0];
		}
		gMS_PLAYER_WORK.accel_counter = 0;
		gMS_PLAYER_WORK.dir_vec_add = 0;
		gMS_PLAYER_WORK.spin_se_timer = 0;
		gMS_PLAYER_WORK.spin_back_se_timer = 0;
		gMS_PLAYER_WORK.safe_timer = 0;
		gMS_PLAYER_WORK.safe_jump_timer = 0;
		gMS_PLAYER_WORK.safe_spin_timer = 0;
		if (gMS_PLAYER_WORK.player_id == 0)
		{
			gm_pos_x = gMS_PLAYER_WORK.obj_work.pos.x >> 12;
			gm_pos_y = gMS_PLAYER_WORK.obj_work.pos.y >> 12;
			gm_pos_z = gMS_PLAYER_WORK.obj_work.pos.z >> 12;
		}
		oBS_OBJECT_WORK.ppFunc = gmPlayerMain;
		GmPlySeqChangeFw(gMS_PLAYER_WORK);
		if (!SaveState.resumePlayer_2(gMS_PLAYER_WORK))
		{
			gMS_PLAYER_WORK.obj_work.pos.x = g_gm_main_system.resume_pos_x;
			gMS_PLAYER_WORK.obj_work.pos.y = g_gm_main_system.resume_pos_y;
		}
		if (g_gs_main_sys_info.stage_id == 5)
		{
			GmPlayerSetPinballSonic(gMS_PLAYER_WORK);
		}
		else if (GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			GmPlayerSetSplStgSonic(gMS_PLAYER_WORK);
		}
		return gMS_PLAYER_WORK;
	}

	private static void GmPlayerResetInit(GMS_PLAYER_WORK ply_work)
	{
		ply_work.player_flag &= 4290772991u;
		g_obj.flag &= 4294966271u;
		g_obj.scroll[0] = (g_obj.scroll[1] = 0);
		ply_work.player_flag &= 4290766847u;
		ply_work.gmk_flag &= 3556759567u;
		ply_work.graind_id = 0;
		ply_work.graind_prev_ride = 0;
		ply_work.gmk_flag &= 4294967291u;
		ply_work.spd_pool = 0;
		ply_work.obj_work.scale.x = (ply_work.obj_work.scale.y = (ply_work.obj_work.scale.z = 4096));
		GmPlayerStateInit(ply_work);
		GmPlayerStateGimmickInit(ply_work);
	}

	private static void GmPlayerInitModel(GMS_PLAYER_WORK ply_work)
	{
		OBS_OBJECT_WORK obj_work = ply_work.obj_work;
		ArrayPointer<OBS_ACTION3D_NN_WORK> arrayPointer = new ArrayPointer<OBS_ACTION3D_NN_WORK>(ply_work.obj_3d_work);
		for (int i = 0; i < 2; i++)
		{
			OBS_ACTION3D_NN_WORK[] array = gm_ply_obj_3d_list_tbl[ply_work.char_id][i];
			int num = 0;
			while (num < 4)
			{
				ObjCopyAction3dNNModel(array[num], arrayPointer);
				(~arrayPointer).blend_spd = 0.25f;
				ObjDrawSetToon(arrayPointer);
				(~arrayPointer).use_light_flag &= 4294967294u;
				(~arrayPointer).use_light_flag |= 64u;
				num++;
				++arrayPointer;
			}
		}
		obj_work.obj_3d = ply_work.obj_3d_work[0];
		obj_work.flag |= 536870912u;
		ObjObjectAction3dNNMotionLoad(obj_work, 0, true, g_gm_player_data_work[ply_work.player_id][4], null, 0, null, 136, 16);
		obj_work.disp_flag |= 16777728u;
		for (int i = 1; i < 8; i++)
		{
			ply_work.obj_3d_work[i].motion = ply_work.obj_3d_work[0].motion;
		}
		GmPlayerSetModel(ply_work, 0);
	}

	private static void GmPlayerSetModel(GMS_PLAYER_WORK ply_work, int model_set)
	{
		ply_work.obj_3d[0] = ply_work.obj_3d_work[model_set * 4];
		ply_work.obj_3d[1] = ply_work.obj_3d_work[model_set * 4 + 1];
		ply_work.obj_3d[2] = ply_work.obj_3d_work[model_set * 4 + 2];
		ply_work.obj_3d[3] = ply_work.obj_3d_work[model_set * 4 + 3];
		int num = ply_work.act_state;
		if (num == -1)
		{
			num = 0;
		}
		ply_work.obj_work.obj_3d = ply_work.obj_3d[g_gm_player_model_tbl[ply_work.char_id][num]];
	}

