	private static void GmPlayerSpdParameterSet(GMS_PLAYER_WORK ply_work)
	{
		ply_work.spd_add = g_gm_player_parameter[ply_work.char_id].spd_add;
		ply_work.spd_max = g_gm_player_parameter[ply_work.char_id].spd_max;
		ply_work.spd1 = (int)((double)ply_work.spd_max * 0.15);
		ply_work.spd2 = (int)((double)ply_work.spd_max * 0.3);
		ply_work.spd3 = (int)((double)ply_work.spd_max * 0.5);
		ply_work.spd4 = (int)((double)ply_work.spd_max * 0.7);
		ply_work.spd5 = (int)((double)ply_work.spd_max * 0.9);
		ply_work.spd_dec = g_gm_player_parameter[ply_work.char_id].spd_dec;
		ply_work.spd_spin = g_gm_player_parameter[ply_work.char_id].spd_spin;
		ply_work.spd_add_spin = g_gm_player_parameter[ply_work.char_id].spd_add_spin;
		ply_work.spd_max_spin = g_gm_player_parameter[ply_work.char_id].spd_max_spin;
		ply_work.spd_dec_spin = g_gm_player_parameter[ply_work.char_id].spd_dec_spin;
		ply_work.spd_max_add_slope = g_gm_player_parameter[ply_work.char_id].spd_max_add_slope;
		ply_work.spd_jump = g_gm_player_parameter[ply_work.char_id].spd_jump;
		ply_work.time_air = g_gm_player_parameter[ply_work.char_id].time_air << 12;
		ply_work.time_damage = g_gm_player_parameter[ply_work.char_id].time_damage << 12;
		ply_work.fall_timer = g_gm_player_parameter[ply_work.char_id].fall_wait_time << 12;
		ply_work.spd_jump_add = g_gm_player_parameter[ply_work.char_id].spd_jump_add;
		ply_work.spd_jump_max = g_gm_player_parameter[ply_work.char_id].spd_jump_max;
		ply_work.spd_jump_dec = g_gm_player_parameter[ply_work.char_id].spd_jump_dec;
		ply_work.spd_add_spin_pinball = g_gm_player_parameter[ply_work.char_id].spd_add_spin_pinball;
		ply_work.spd_max_spin_pinball = g_gm_player_parameter[ply_work.char_id].spd_max_spin_pinball;
		ply_work.spd_dec_spin_pinball = g_gm_player_parameter[ply_work.char_id].spd_dec_spin_pinball;
		ply_work.spd_max_add_slope_spin_pinball = g_gm_player_parameter[ply_work.char_id].spd_max_add_slope_spin_pinball;
		if (!GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			if ((ply_work.player_flag & 0x40000) != 0)
			{
				ply_work.obj_work.dir_slope = 512;
			}
			else
			{
				ply_work.obj_work.dir_slope = 192;
			}
		}
		else
		{
			ply_work.obj_work.dir_slope = 1;
		}
		ply_work.obj_work.spd_slope = g_gm_player_parameter[ply_work.char_id].spd_slope;
		ply_work.obj_work.spd_slope_max = g_gm_player_parameter[ply_work.char_id].spd_slope_max;
		ply_work.obj_work.spd_fall = g_gm_player_parameter[ply_work.char_id].spd_fall;
		ply_work.obj_work.spd_fall_max = g_gm_player_parameter[ply_work.char_id].spd_fall_max;
		ply_work.obj_work.push_max = g_gm_player_parameter[ply_work.char_id].push_max;
		if ((ply_work.player_flag & 0x4000000) != 0)
		{
			GMD_PLAYER_WATERJUMP_SET(ref ply_work.spd_jump);
			GMD_PLAYER_WATER_SET(ref ply_work.obj_work.spd_fall);
		}
		if (ply_work.hi_speed_timer != 0)
		{
			ply_work.spd_add <<= 1;
			if (ply_work.spd_add > 61440)
			{
				ply_work.spd_add = 61440;
			}
			ply_work.spd_max <<= 1;
			if (ply_work.spd_max > 61440)
			{
				ply_work.spd_max = 61440;
			}
			ply_work.spd_dec <<= 1;
			ply_work.spd_spin <<= 1;
			ply_work.spd_add_spin <<= 1;
			ply_work.spd_max_spin <<= 1;
			if (ply_work.spd_max_spin > 61440)
			{
				ply_work.spd_max_spin = 61440;
			}
			ply_work.spd_dec_spin <<= 1;
			ply_work.spd_max_add_slope <<= 1;
			ply_work.spd_jump_add <<= 1;
			ply_work.spd_jump_max <<= 1;
			if (ply_work.spd_jump_max > 61440)
			{
				ply_work.spd_jump_max = 61440;
			}
			ply_work.spd_jump_dec <<= 1;
		}
	}

