	private static void GmPlayerSetTruckRide(GMS_PLAYER_WORK ply_work, OBS_OBJECT_WORK truck_obj, short field_left, short field_top, short field_right, short field_bottom)
	{
		bool flag = false;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)ply_work;
		if ((ply_work.player_flag & 0x4000) != 0)
		{
			ply_work.char_id = 6;
		}
		else
		{
			ply_work.char_id = 5;
		}
		ply_work.player_flag |= 262144u;
		ply_work.obj_work.move_flag &= 4294705151u;
		ply_work.gmk_flag2 &= 4294967294u;
		ply_work.truck_obj = truck_obj;
		ply_work.obj_work.ppRec = gmPlayerRectTruckFunc;
		ply_work.obj_work.ppCol = gmPlayerTruckCollisionFunc;
		ArrayPointer<OBS_ACTION3D_NN_WORK> arrayPointer = new ArrayPointer<OBS_ACTION3D_NN_WORK>(ply_work.obj_3d_work);
		int num = 0;
		while (num < 8)
		{
			(~arrayPointer).mtn_cb_func = gmGmkPlayerMotionCallbackTruck;
			(~arrayPointer).mtn_cb_param = ply_work;
			num++;
			++arrayPointer;
		}
		nnMakeUnitMatrix(ply_work.truck_mtx_ply_mtn_pos);
		GmPlySeqSetSeqState(ply_work);
		GmPlayerSpdParameterSet(ply_work);
		ObjObjectFieldRectSet(oBS_OBJECT_WORK, field_left, field_top, field_right, field_bottom);
		oBS_OBJECT_WORK.field_ajst_w_db_f = 3;
		oBS_OBJECT_WORK.field_ajst_w_db_b = 4;
		oBS_OBJECT_WORK.field_ajst_w_dl_f = 3;
		oBS_OBJECT_WORK.field_ajst_w_dl_b = 4;
		oBS_OBJECT_WORK.field_ajst_w_dt_f = 3;
		oBS_OBJECT_WORK.field_ajst_w_dt_b = 4;
		oBS_OBJECT_WORK.field_ajst_w_dr_f = 3;
		oBS_OBJECT_WORK.field_ajst_w_dr_b = 4;
		oBS_OBJECT_WORK.field_ajst_h_db_r = 3;
		oBS_OBJECT_WORK.field_ajst_h_db_l = 3;
		oBS_OBJECT_WORK.field_ajst_h_dl_r = 3;
		oBS_OBJECT_WORK.field_ajst_h_dl_l = 3;
		oBS_OBJECT_WORK.field_ajst_h_dt_r = 3;
		oBS_OBJECT_WORK.field_ajst_h_dt_l = 3;
		oBS_OBJECT_WORK.field_ajst_h_dr_r = 3;
		oBS_OBJECT_WORK.field_ajst_h_dr_l = 3;
		ObjRectWorkSet(ply_work.rect_work[2], -8, (short)(-32 + field_bottom), 8, field_bottom);
		ObjRectWorkSet(ply_work.rect_work[0], -8, (short)(-48 + field_bottom), 8, (short)(-16 + field_bottom));
		ObjRectWorkSet(ply_work.rect_work[1], -16, (short)(-48 + field_bottom), 16, (short)(-16 + field_bottom));
		ply_work.rect_work[1].flag &= 4294967291u;
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(g_obj.glb_camera_id);
		oBS_CAMERA.user_func = GmCameraTruckFunc;
		if ((ply_work.obj_work.disp_flag & 1) != 0)
		{
			GmPlayerSetReverse(ply_work);
		}
		if (ply_work.seq_state == 39)
		{
			flag = true;
		}
		GmPlySeqChangeFw(ply_work);
		if (flag)
		{
			GmPlySeqInitDemoFw(ply_work);
		}
	}

