	private static void GmPlayerResetAction(GMS_PLAYER_WORK ply_work, GMS_PLAYER_RESET_ACT_WORK reset_act_work)
	{
		int[] array = New<int>(2);
		float[] array2 = new float[2];
		array[0] = ply_work.act_state;
		array[1] = ply_work.prev_act_state;
		uint disp_flag = ply_work.obj_work.disp_flag;
		GmPlayerActionChange(ply_work, array[1]);
		GmPlayerActionChange(ply_work, array[0]);
		ply_work.obj_work.obj_3d.frame[0] = reset_act_work.frame[0];
		ply_work.obj_work.obj_3d.frame[1] = reset_act_work.frame[1];
		ply_work.obj_work.obj_3d.blend_spd = reset_act_work.blend_spd;
		ply_work.obj_work.obj_3d.marge = reset_act_work.marge;
		ply_work.obj_work.obj_3d.flag &= 4294967294u;
		ply_work.obj_work.obj_3d.flag |= reset_act_work.obj_3d_flag & 1;
		ply_work.obj_work.disp_flag |= disp_flag & 0xC;
		for (int i = 0; i < 2; i++)
		{
			array2[i] = amMotionGetEndFrame(ply_work.obj_work.obj_3d.motion, ply_work.obj_work.obj_3d.act_id[i]) - amMotionGetStartFrame(ply_work.obj_work.obj_3d.motion, ply_work.obj_work.obj_3d.act_id[i]);
			if (ply_work.obj_work.obj_3d.frame[i] >= array2[i])
			{
				ply_work.obj_work.obj_3d.frame[i] = 0f;
			}
		}
	}

	private static void GmPlayerWalkActionSet(GMS_PLAYER_WORK ply_work)
