	private static void GmPlayerSpdSet(GMS_PLAYER_WORK ply_work, int spd_x, int spd_y)
	{
		ply_work.no_spddown_timer = 524288;
		if (spd_x < 0)
		{
			ply_work.obj_work.disp_flag |= 1u;
		}
		else
		{
			ply_work.obj_work.disp_flag &= 4294967294u;
		}
		if ((ply_work.obj_work.move_flag & 0x10) != 0)
		{
			if (((ply_work.obj_work.disp_flag & 1) != 0 && ply_work.obj_work.spd.x > spd_x) || ((ply_work.obj_work.disp_flag & 1) == 0 && ply_work.obj_work.spd.x < spd_x))
			{
				ply_work.obj_work.spd.x = spd_x;
			}
			if (MTM_MATH_ABS(ply_work.obj_work.spd.y) < MTM_MATH_ABS(spd_y))
			{
				ply_work.obj_work.spd.y = spd_y;
			}
			return;
		}
		switch (((ply_work.obj_work.dir.z + 8192) & 0xC000) >> 6)
		{
		case 0:
		case 2:
			if (((ply_work.obj_work.disp_flag & 1) != 0 && ply_work.obj_work.spd_m > spd_x) || ((ply_work.obj_work.disp_flag & 1) == 0 && ply_work.obj_work.spd_m < spd_x))
			{
				ply_work.obj_work.spd_m = spd_x;
			}
			if (MTM_MATH_ABS(ply_work.obj_work.spd.y) < MTM_MATH_ABS(spd_y))
			{
				ply_work.obj_work.spd.y = spd_y;
				if (ply_work.obj_work.spd.y < 0)
				{
					ply_work.obj_work.move_flag |= 16u;
				}
			}
			break;
		case 1:
			if (((ply_work.obj_work.disp_flag & 1) != 0 && ply_work.obj_work.spd_m > spd_y) || ((ply_work.obj_work.disp_flag & 1) == 0 && ply_work.obj_work.spd_m < spd_y))
			{
				ply_work.obj_work.spd_m = spd_y;
			}
			if (MTM_MATH_ABS(ply_work.obj_work.spd.x) < MTM_MATH_ABS(spd_x))
			{
				ply_work.obj_work.spd.x = spd_x;
			}
			break;
		case 3:
			if (((ply_work.obj_work.disp_flag & 1) != 0 && ply_work.obj_work.spd_m > -spd_y) || ((ply_work.obj_work.disp_flag & 1) == 0 && ply_work.obj_work.spd_m < -spd_y))
			{
				ply_work.obj_work.spd_m = -spd_y;
			}
			if (MTM_MATH_ABS(ply_work.obj_work.spd.x) < MTM_MATH_ABS(spd_x))
			{
				ply_work.obj_work.spd.x = spd_x;
			}
			break;
		}
	}

