			num |= ply_work.key_map[4];
		}
		if ((0x80 & key) != 0)
		{
			num |= ply_work.key_map[5];
		}
		if ((0x40 & key) != 0)
		{
			num |= ply_work.key_map[6];
		}
		if ((0x10 & key) != 0)
		{
			num |= ply_work.key_map[7];
		}
		return num;
	}

	private static int gmPlayerKeyGetRotZ(GMS_PLAYER_WORK ply_work)
	{
		int num = 0;
		ply_work.is_nudge = false;
		int stage_id = g_gs_main_sys_info.stage_id;
		if (GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			NNS_VECTOR core = _am_iphone_accel_data.core;
			NNS_VECTOR calc_accel = ply_work.calc_accel;
			calc_accel.x = core.x * 0.1f + calc_accel.x * 0.9f;
			calc_accel.y = core.y * 0.1f + calc_accel.y * 0.9f;
			calc_accel.y = core.y * 0.1f + calc_accel.y * 0.9f;
			float num2 = core.x - calc_accel.x;
			float num3 = core.y - calc_accel.y;
			float num4 = core.z - calc_accel.z;
			float num5 = nnSqrt(num2 * num2 + num3 * num3 + num4 * num4);
			if (num5 >= 2f)
			{
				ply_work.is_nudge = true;
			}
		}
		if (!SPSTAGE_FORCE_TILT && GSM_MAIN_STAGE_IS_SPSTAGE() && (g_gs_main_sys_info.game_flag & 0x200) != 0)
		{
			num = g_gm_main_system.polar_diff;
		}
		else if (stage_id == 9 && (g_gs_main_sys_info.game_flag & 0x200) != 0)
		{
			num = g_gm_main_system.polar_diff;
		}
		else
		{
			num = (int)(_am_iphone_accel_data.sensor.x * 16384f);
			if (num < 2048 && num > -2048)
			{
				num = 0;
			}
			else
			{
				num *= 3;
				if (num > 32768)
				{
					num = 32768;
				}
				else if (num < -32768)
				{
					num = -32768;
				}
			}
		}
		return num;
	}

	private static ushort gmPlayerRemapKeyIPhone(GMS_PLAYER_WORK ply_work)
	{
		ushort num = 0;
		if (GmMainKeyCheckPauseKeyPush() != -1)
		{
			return num;
		}
		int seq_state = ply_work.seq_state;
		if (ply_work.safe_timer > 0)
		{
			ply_work.safe_timer--;
			if (amTpIsTouchPull(0))
			{
				ply_work.safe_timer = 0;
				ply_work.safe_jump_timer = 10;
			}
			else if (ply_work.safe_timer == 0)
			{
				ply_work.safe_spin_timer = 3;
			}
		}
		else if (ply_work.safe_jump_timer > 0)
		{
			ply_work.safe_jump_timer--;
			num |= 0x20;
		}
		else if (ply_work.safe_spin_timer != 0)
		{
			ushort num2 = 0;
			uint num3 = ply_work.obj_work.disp_flag & 1;
			if (amTpIsTouchPull(0))
			{
				ply_work.safe_spin_timer = 0;
			}
			switch (ply_work.safe_spin_timer)
			{
			case 3:
				if (ObjTouchCheck(ply_work.obj_work, gm_ply_touch_rect[1]) != 0)
				{
					num2 = (ushort)((num3 == 0) ? 4 : 8);
					ply_work.safe_spin_timer = 2;
				}
				else
				{
					num2 = 2;
					ply_work.safe_spin_timer = 1;
				}
				num |= num2;
				break;
			case 2:
				if (seq_state != 2)
				{
					ply_work.safe_spin_timer = 1;
				}
				num |= 2;
				break;
			case 1:
				num |= 2;
				if (!amTpIsTouchPull(0) && (seq_state == 6 || seq_state == 7 || seq_state == 8))
				{
					num |= 0x20;
				}
				break;
			}
		}
		else
		{
			bool flag = amTpIsTouchOn(0);
			bool flag2 = amTpIsTouchPush(0);
			if (GmPlayerIsTransformSuperSonic(ply_work) && flag && GMM_PLAYER_IS_TOUCH_SUPER_SONIC_REGION(_am_tp_touch[0].on[0], _am_tp_touch[0].on[1]))
			{
				num |= 0x50;
			}
			if ((num & 0x50) == 0)
			{
				ushort num4 = 0;
				uint num5 = ply_work.obj_work.disp_flag & 1;
				ushort num6 = ObjTouchCheck(ply_work.obj_work, gm_ply_touch_rect[0]);
				if (num6 == 0 && ObjTouchCheck(ply_work.obj_work, gm_ply_touch_rect[1]) != 0)
				{
					num6 = 1;
					num4 = (ushort)((num5 == 0) ? 4 : 8);
				}
				if (num6 != 0)
				{
					if (_am_tp_touch[0].on[0] < 80 || _am_tp_touch[0].on[0] > 400)
					{
						ply_work.safe_timer = 25;
					}
					else if (seq_state == 2)
					{
						if (flag2 || flag)
						{
							num |= 2;
						}
					}
					else if (seq_state == 12 || seq_state == 11)
					{
						if (flag2 || flag)
						{
							num |= 2;
						}
					}
					else if (seq_state == 0 || seq_state == 9)
					{
						if (num4 != 0)
						{
							num |= num4;
						}
						else if (flag2 || flag)
						{
							num |= 2;
						}
					}
					else if (seq_state == 6 || seq_state == 7 || seq_state == 8)
					{
						if (flag2 || flag)
						{
							num |= 0x22;
						}
					}
					else if (seq_state == 1 || ply_work.spin_state == 3)
					{
						if (flag2 || flag)
						{
							ply_work.spin_state = 3;
							num |= 2;
						}
					}
					else if (flag2 || flag)
					{
						ply_work.spin_state = 0;
						num |= 0x20;
					}
				}
				else
				{
					ply_work.spin_state = 0;
					if (flag2 || flag)
					{
						num |= 0x20;
					}
				}
			}
		}
		return num;
	}

	private static ushort gmPlayerRemapKeyIPhoneZone32SS(GMS_PLAYER_WORK ply_work)
	{
		ushort num = 0;
		if (GmMainKeyCheckPauseKeyPush() != -1)
		{
			return num;
		}
		for (int i = 0; i < 4; i++)
		{
			bool flag = amTpIsTouchOn(i);
			bool flag2 = amTpIsTouchPush(i);
			if (GmPlayerIsTransformSuperSonic(ply_work) && flag && GMM_PLAYER_IS_TOUCH_SUPER_SONIC_REGION(_am_tp_touch[i].on[0], _am_tp_touch[i].on[1]))
			{
				num |= 0x50;
			}
			if ((num & 0x50) == 0 && (flag2 || flag))
			{
				num |= 0x20;
			}
			if (num != 0)
			{
				break;
			}
		}
		return num;
	}

	private static bool gmPlayerIsInputDPadJumpKey(GMS_PLAYER_WORK ply_work, int ignore_key)
	{
		int control_type = ply_work.control_type;
		if (control_type == 2)
		{
			return false;
		}
		if (ply_work.jump_rect == null)
		{
			mppAssertNotImpl();
			return false;
		}
		bool result = false;
		for (int i = 0; i < 4; i++)
		{
			if ((i != ignore_key || amTpIsTouchPush(i)) && amTpIsTouchOn(i))
			{
				short num = (short)_am_tp_touch[i].on[0];
				short num2 = (short)_am_tp_touch[i].on[1];
				if (ply_work.jump_rect[0] <= num && num <= ply_work.jump_rect[2] && ply_work.jump_rect[1] <= num2 && num2 <= ply_work.jump_rect[3])
				{
					result = true;
					break;
				}
			}
		}
		return result;
	}

