	private static void gmPlayerCameraOffset(GMS_PLAYER_WORK ply_work)
	{
		byte b = 4;
		if (ply_work.player_id == 0 && !GSM_MAIN_STAGE_IS_SPSTAGE_NOT_RETRY())
		{
			if (ply_work.gmk_obj == null)
			{
				ply_work.gmk_flag &= 4227858431u;
				ply_work.gmk_camera_gmk_center_ofst_x = 0;
				ply_work.gmk_camera_gmk_center_ofst_y = 0;
			}
			short num = 0;
			short num2 = 0;
			if ((ply_work.player_flag & 0x2000) != 0)
			{
				ply_work.camera_ofst_x -= ply_work.camera_ofst_x >> 2;
				ply_work.camera_ofst_y -= ply_work.camera_ofst_y >> 2;
			}
			else if ((ply_work.gmk_flag & 0x4000000) != 0)
			{
				ply_work.camera_ofst_x += ply_work.camera_ofst_tag_x - ply_work.camera_ofst_x + (ply_work.gmk_camera_center_ofst_x + ply_work.gmk_camera_gmk_center_ofst_x << 12) >> (int)b;
				ply_work.camera_ofst_y += ply_work.camera_ofst_tag_y - ply_work.camera_ofst_y + (ply_work.gmk_camera_center_ofst_y + ply_work.gmk_camera_gmk_center_ofst_y << 12) >> (int)b;
			}
			else
			{
				ply_work.camera_ofst_x += ply_work.camera_ofst_tag_x - ply_work.camera_ofst_x + (ply_work.gmk_camera_center_ofst_x << 12) >> (int)b;
				ply_work.camera_ofst_y += ply_work.camera_ofst_tag_y - ply_work.camera_ofst_y + (ply_work.gmk_camera_center_ofst_y << 12) >> (int)b;
			}
			OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
			oBS_CAMERA.ofst.x = FXM_FX32_TO_FLOAT((num << 12) + ply_work.camera_ofst_x);
			oBS_CAMERA.ofst.y = FXM_FX32_TO_FLOAT((num2 << 12) + ply_work.camera_ofst_y);
		}
	}

	public static void gmGmkPlayerMotionCallbackTruck(AMS_MOTION motion, NNS_OBJECT _object, object param)
	{
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		NNS_MATRIX nNS_MATRIX2 = GlobalPool<NNS_MATRIX>.Alloc();
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)param;
		nnMakeUnitMatrix(nNS_MATRIX2);
		nnMultiplyMatrix(nNS_MATRIX2, nNS_MATRIX2, amMatrixGetCurrent());
		nnCalcNodeMatrixTRSList(nNS_MATRIX, _object, GMD_PLAYER_NODE_ID_TRUCK_CENTER, motion.data, nNS_MATRIX2);
		nNS_MATRIX.Assign(gMS_PLAYER_WORK.truck_mtx_ply_mtn_pos);
	}

	private static void GmOverBuildDataInit()
	{
		for (int i = 0; i < 2; i++)
		{
			gm_over_textures[i].Clear();
			gm_over_texamb_list[i] = (AMS_AMB_HEADER)ObjDataLoadAmbIndex(null, gm_over_tex_amb_idx_tbl[GsEnvGetLanguage()][i], GmGameDatGetCockpitData());
			AoTexBuild(gm_over_textures[i], gm_over_texamb_list[i]);
			AoTexLoad(gm_over_textures[i]);
		}
	}

	private static bool GmOverBuildDataLoop()
	{
		bool result = true;
		for (int i = 0; i < 2; i++)
		{
			if (!AoTexIsLoaded(gm_over_textures[i]))
			{
				result = false;
			}
		}
		return result;
	}

	private static void GmOverFlushDataInit()
	{
		for (int i = 0; i < 2; i++)
		{
			AoTexRelease(gm_over_textures[i]);
		}
	}

	private static bool GmOverFlushDataLoop()
	{
		bool result = true;
		for (int i = 0; i < 2; i++)
		{
			if (gm_over_texamb_list[i] != null)
			{
				if (!AoTexIsReleased(gm_over_textures[i]))
				{
					result = false;
					continue;
				}
				gm_over_texamb_list[i] = null;
				gm_over_textures[i].Clear();
			}
		}
		return result;
	}

	private static void GmOverStart(int type)
	{
		SaveState.deleteSave();
		gm_over_tcb = MTM_TASK_MAKE_TCB(gmOverMain, gmOverDest, 0u, 0, 18464u, 5, () => new GMS_OVER_MGR_WORK(), "GM_OVER_MGR");
		GMS_OVER_MGR_WORK gMS_OVER_MGR_WORK = (GMS_OVER_MGR_WORK)gm_over_tcb.work;
		gMS_OVER_MGR_WORK.Clear();
		for (int num = 0; num < 4; num++)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_COCKPIT_CREATE_WORK(() => new GMS_COCKPIT_2D_WORK(), null, 0, "GAME_OVER");
			GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK = (GMS_COCKPIT_2D_WORK)oBS_OBJECT_WORK;
			ObjObjectAction2dAMALoadSetTexlist(oBS_OBJECT_WORK, gMS_COCKPIT_2D_WORK.obj_2d, null, null, gm_over_ama_amb_idx_tbl[GsEnvGetLanguage()][1], GmGameDatGetCockpitData(), AoTexGetTexList(gm_over_textures[1]), gm_over_string_act_id_tbl[GsEnvGetLanguage()][num], 0);
			gMS_OVER_MGR_WORK.string_sub_parts[num] = gMS_COCKPIT_2D_WORK;
			gmOverSetActionHide(gMS_COCKPIT_2D_WORK);
		}
		for (int num2 = 0; num2 < 2; num2++)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GMM_COCKPIT_CREATE_WORK(() => new GMS_COCKPIT_2D_WORK(), null, 0, "GAME_OVER");
			GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK2 = (GMS_COCKPIT_2D_WORK)oBS_OBJECT_WORK2;
			ObjObjectAction2dAMALoadSetTexlist(oBS_OBJECT_WORK2, gMS_COCKPIT_2D_WORK2.obj_2d, null, null, gm_over_ama_amb_idx_tbl[GsEnvGetLanguage()][0], GmGameDatGetCockpitData(), AoTexGetTexList(gm_over_textures[0]), gm_over_fadeout_act_id_tbl[num2], 0);
			gMS_OVER_MGR_WORK.fadeout_sub_parts[num2] = gMS_COCKPIT_2D_WORK2;
			oBS_OBJECT_WORK2.pos.z = -65536;
			oBS_OBJECT_WORK2.disp_flag &= 4294967291u;
			gmOverSetActionHide(gMS_COCKPIT_2D_WORK2);
		}
		switch (type)
		{
		case 0:
			gmOverProcUpdateGOInit(gMS_OVER_MGR_WORK);
			break;
		case 1:
			gmOverProcUpdateTOInit(gMS_OVER_MGR_WORK);
			break;
		}
		gMS_OVER_MGR_WORK.proc_disp = gmOverProcDispLoop;
	}

	private static void GmOverExit()
	{
		if (gm_over_tcb != null)
		{
			mtTaskClearTcb(gm_over_tcb);
			gm_over_tcb = null;
		}
	}

