	private static OBS_OBJECT_WORK GmGmkSsRingGateInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_SS_RINGGATE");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.user_work = GmSplStageRingGateNumGet((ushort)eve_rec.left);
		oBS_OBJECT_WORK.user_flag = (uint)(eve_rec.flag & 1);
		oBS_OBJECT_WORK.user_timer = 20;
		if ((ushort)oBS_OBJECT_WORK.user_work > g_gm_main_system.ply_work[0].ring_num)
		{
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_ss_ringgate_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
			uint num = g_gm_main_system.sync_time % 128;
			gMS_ENEMY_3D_WORK.obj_3d.mat_frame = num;
			oBS_OBJECT_WORK.ppOut = gmGmkSsRingGateDrawFunc;
			oBS_OBJECT_WORK.user_flag = (oBS_OBJECT_WORK.user_flag & 1) | ((num & 0x7F) << 8);
		}
		else
		{
