	private static void gmGmkSsRingGateMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		uint num = (obj_work.user_flag >> 8) & 0x7F;
		num++;
		obj_work.user_flag = (obj_work.user_flag & 1) | ((num & 0x7F) << 8);
		if ((ushort)obj_work.user_work <= gMS_PLAYER_WORK.ring_num)
		{
			GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
			gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
			gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.obj = null;
			obj_work.ppFunc = gmGmkSsRingGateVanish;
			obj_work.disp_flag |= 134217728u;
			obj_work.obj_3d.drawflag |= 8388608u;
			obj_work.obj_3d.draw_state.alpha.alpha = 1f;
			obj_work.user_timer = 20;
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctZoneEsCreate(obj_work, 5, 9);
			GmEffect3DESSetDispOffset(gMS_EFFECT_3DES_WORK, 0f, 0f, 8f);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.dir.z = obj_work.dir.z;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.flag |= 512u;
		}
	}

	private static void gmGmkSsRingGateVanish(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_timer--;
		if (obj_work.user_timer == 8)
		{
			obj_work.ppOut = ObjDrawActionSummary;
			ObjObjectAction3dNNModelReleaseCopy(obj_work);
			ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_ss_ringgate_obj_3d_list[1], ((GMS_ENEMY_3D_WORK)obj_work).obj_3d);
		}
		if ((float)obj_work.user_timer > 4f)
		{
			obj_work.obj_3d.draw_state.alpha.alpha = (float)obj_work.user_timer / 20f;
			return;
		}
		obj_work.obj_3d.draw_state.alpha.alpha = 0.2f;
		obj_work.ppFunc = null;
	}

	private static void gmGmkSsRingGateDefFunc(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_ENEMY_COM_WORK != null && gMS_PLAYER_WORK != null && gMS_PLAYER_WORK.obj_work.obj_type == 1 && gMS_PLAYER_WORK.gmk_obj != (OBS_OBJECT_WORK)gMS_ENEMY_COM_WORK)
		{
			int v = FX_Mul(gMS_PLAYER_WORK.obj_work.spd.x, 5120);
			int num = FX_Mul(gMS_PLAYER_WORK.obj_work.spd.y, 5120);
			short num2 = (short)GmMainGetObjectRotation();
			if ((gMS_ENEMY_COM_WORK.obj_work.user_flag & 1) != 0)
			{
				num2 = ((num2 <= 0) ? ((short)(num2 + 16384)) : ((short)(num2 - 16384)));
			}
			num2 *= 2;
			num = -num;
			int num3 = FX_Mul(v, mtMathCos(num2));
			num3 += FX_Mul(num, mtMathSin(num2));
			int num4 = FX_Mul(num, mtMathCos(num2));
			num4 -= FX_Mul(v, mtMathSin(num2));
			gMS_PLAYER_WORK.obj_work.spd.x = num3;
			gMS_PLAYER_WORK.obj_work.spd.y = num4;
			gMS_PLAYER_WORK.obj_work.spd_m = FX_Mul(-gMS_PLAYER_WORK.obj_work.spd_m, 5120);
			GMM_PAD_VIB_MID_TIME(60f);
			gMS_PLAYER_WORK.player_flag &= 4294967280u;
			gMS_PLAYER_WORK.player_flag |= 1u;
		}
	}

	private static void gmGmkSsRingGateNumMain(OBS_OBJECT_WORK obj_work)
	{
		OBS_OBJECT_WORK parent_obj = obj_work.parent_obj;
		GMS_EFFECT_3DNN_WORK gMS_EFFECT_3DNN_WORK = (GMS_EFFECT_3DNN_WORK)obj_work;
		if (parent_obj.user_timer < 8)
		{
			obj_work.flag |= 4u;
			return;
		}
		int a = (int)(parent_obj.user_work - g_gm_main_system.ply_work[0].ring_num);
		a = MTM_MATH_CLIP(a, 0, 99);
		if (obj_work.user_work == 1 && a < 10)
		{
			obj_work.disp_flag |= 32u;
			return;
		}
		bool flag = false;
		switch (obj_work.user_work)
		{
		case 2u:
			if (obj_work.user_timer != a % 10)
			{
				obj_work.user_timer = a % 10;
				flag = true;
			}
			break;
		case 1u:
			if (obj_work.user_timer != a / 10)
			{
				obj_work.user_timer = a / 10;
				flag = true;
			}
			break;
		}
		if (flag)
		{
			ObjAction3dNNMotionRelease(obj_work.obj_3d);
			ObjObjectAction3dNNModelReleaseCopy(obj_work);
			ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_ss_ringgate_obj_3d_list[2 + obj_work.user_timer], gMS_EFFECT_3DNN_WORK.obj_3d);
		}
		obj_work.dir.z = GmMainGetObjectRotation();
		obj_work.disp_flag |= parent_obj.disp_flag & 0x8000000;
		obj_work.obj_3d.drawflag |= parent_obj.obj_3d.drawflag & 0x800000;
		obj_work.obj_3d.draw_state.alpha.alpha = parent_obj.obj_3d.draw_state.alpha.alpha;
		int num = parent_obj.pos.x;
		int num2 = parent_obj.pos.y;
		switch (obj_work.user_work)
		{
		case 2u:
			num += FX_Mul(36864, mtMathCos(obj_work.dir.z));
			num2 += FX_Mul(36864, mtMathSin(obj_work.dir.z));
			break;
		case 0u:
			num += FX_Mul(-36864, mtMathCos(obj_work.dir.z));
			num2 += FX_Mul(-36864, mtMathSin(obj_work.dir.z));
			break;
		}
		obj_work.pos.x = num;
		obj_work.pos.y = num2;
	}

	private static void gmGmkSsRingGateDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		if (GmMainIsDrawEnable() && (obj_work.disp_flag & 0x20) == 0)
		{
			TVX_FILE tVX_FILE;
			if (gm_gmk_ss_ringgate_obj_tvx_list.buf[0] == null)
			{
				tVX_FILE = new TVX_FILE((AmbChunk)amBindGet(gm_gmk_ss_ringgate_obj_tvx_list, 0));
				gm_gmk_ss_ringgate_obj_tvx_list.buf[0] = tVX_FILE;
			}
			else
			{
				tVX_FILE = (TVX_FILE)gm_gmk_ss_ringgate_obj_tvx_list.buf[0];
			}
			NNS_TEXLIST texlist = obj_work.obj_3d.texlist;
			uint num = GMD_TVX_DISP_LIGHT_DISABLE;
			uint num2 = 0u;
			if (obj_work.dir.z != 0)
			{
				num |= GMD_TVX_DISP_ROTATE;
				num2 = obj_work.dir.z;
			}
			GMS_TVX_EX_WORK ex_work = default(GMS_TVX_EX_WORK);
			uint num3 = (obj_work.user_flag >> 13) & 3;
			ex_work.u_wrap = 0;
			ex_work.v_wrap = 0;
			ex_work.coord.u = -0.25f * (float)num3;
			ex_work.coord.v = 0f;
			ex_work.color = uint.MaxValue;
			GmTvxSetModelEx(tVX_FILE, texlist, ref obj_work.pos, ref obj_work.scale, num, (short)num2, ref ex_work);
		}
	}

