	private static void gmGmkSplRingWait(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (gMS_PLAYER_WORK != null && g_gs_main_sys_info.game_mode == 0 && !GsTrialIsTrial() && gMS_PLAYER_WORK.obj_work.pos.x >= obj_work.pos.x - FXM_FLOAT_TO_FX32(AMD_SCREEN_2D_WIDTH) && !GsMainSysIsSpecialStageClearedAct(g_gs_main_sys_info.stage_id) && !GsMainSysIsStageClear(27))
		{
			if (g_gm_main_system.ply_work[0].ring_num < 50)
			{
				obj_work.disp_flag |= 32u;
				obj_work.flag |= 2u;
			}
			else
			{
				obj_work.disp_flag &= 4294967263u;
				obj_work.flag &= 4294967293u;
			}
			uint p_disp_flag = 4u;
			ObjDrawAction3DNNMaterialUpdate(obj_work.obj_3d, ref p_disp_flag);
		}
	}

	private static void gmGmkSplRingVanishReady(OBS_OBJECT_WORK obj_work)
	{
		obj_work.obj_3d.mat_frame = 1f;
		uint p_disp_flag = 16u;
		ObjDrawAction3DNNMaterialUpdate(obj_work.obj_3d, ref p_disp_flag);
		if ((obj_work.dir.y & 0x7FFF) == 0)
		{
			obj_work.ppFunc = gmGmkSplRingVanish;
			GMS_EFFECT_3DES_WORK efct_3des = GmEfctCmnEsCreate(obj_work, 78);
			GmEffect3DESSetDispOffset(efct_3des, 0f, 0f, 50f);
			GmEfctCmnEsCreate(obj_work, 79);
		}
	}

	private static void gmGmkSplRingVanish(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		obj_work.dir.y -= 4096;
		if ((obj_work.dir.y & 0x7FFF) == 0)
		{
			obj_work.ppFunc = null;
			obj_work.disp_flag |= 32u;
			gMS_PLAYER_WORK.obj_work.disp_flag |= 32u;
			gMS_PLAYER_WORK.obj_work.move_flag |= 8192u;
		}
	}

	private static void gmGmkSplRingDefFunc(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_ENEMY_COM_WORK != null && gMS_PLAYER_WORK != null && gMS_PLAYER_WORK.obj_work.obj_type == 1)
		{
			if ((gMS_PLAYER_WORK.player_flag & 0x40000) != 0)
			{
				GmPlayerSetEndTruckRide(gMS_PLAYER_WORK);
			}
			GmPlySeqInitSplIn(gMS_PLAYER_WORK, gMS_ENEMY_COM_WORK.obj_work.pos);
			gMS_PLAYER_WORK.gmk_flag2 |= 6u;
			((OBS_OBJECT_WORK)gMS_ENEMY_COM_WORK).ppFunc = gmGmkSplRingVanishReady;
			gMS_ENEMY_COM_WORK.obj_work.dir.y = (ushort)(gMS_ENEMY_COM_WORK.obj_work.dir.y & 0xE000);
			gMS_ENEMY_COM_WORK.obj_work.flag |= 2u;
			GMM_PAD_VIB_SMALL();
			GmSoundPlaySE("Special1");
		}
	}

	private static OBS_OBJECT_WORK GmGmkPointMarkerInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		if (g_gs_main_sys_info.game_mode == 1)
		{
			eve_rec.pos_x = byte.MaxValue;
			return null;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_PMARKER_WORK(), "GMK_POINT_MARKER");
		GMS_GMK_PMARKER_WORK gMS_GMK_PMARKER_WORK = (GMS_GMK_PMARKER_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.pos.y += 4096;
		if (g_gs_main_sys_info.stage_id == 9)
		{
			oBS_OBJECT_WORK.pos.z = -131072;
		}
		else
		{
			oBS_OBJECT_WORK.pos.z = -65536;
		}
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		gMS_GMK_PMARKER_WORK.marker_prty = (ushort)eve_rec.left;
		gmGmkPointMarkerStart(oBS_OBJECT_WORK);
		return oBS_OBJECT_WORK;
	}

