	private static void gmGmkPointMarkerHit(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_GMK_PMARKER_WORK gMS_GMK_PMARKER_WORK = (GMS_GMK_PMARKER_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		gMS_GMK_PMARKER_WORK.markerdist = gMS_GMK_PMARKER_WORK.OBJWORK.pos.x - gMS_PLAYER_WORK.obj_work.pos.x;
		if ((gMS_GMK_PMARKER_WORK.markerdist <= 16384 && gMS_GMK_PMARKER_WORK.markerdist >= -16384) || (gMS_GMK_PMARKER_WORK.markerdist < 16384 && gMS_GMK_PMARKER_WORK.markerdistlast >= 16384) || (gMS_GMK_PMARKER_WORK.markerdist > -16384 && gMS_GMK_PMARKER_WORK.markerdistlast <= -16384))
		{
			if (g_gm_main_system.marker_pri < gMS_GMK_PMARKER_WORK.marker_prty)
			{
				GmPlayerSetMarkerPoint(gMS_PLAYER_WORK, gMS_GMK_PMARKER_WORK.OBJWORK.pos.x, gMS_GMK_PMARKER_WORK.OBJWORK.pos.y);
				g_gm_main_system.marker_pri = gMS_GMK_PMARKER_WORK.marker_prty;
				gMS_GMK_PMARKER_WORK.marker_prty = 0;
				gMS_GMK_PMARKER_WORK.hitcounter = 2;
				SaveState.saveCurrentState(1);
			}
			gMS_GMK_PMARKER_WORK.OBJWORK.flag |= 2u;
		}
		else
		{
			mine_rect.flag &= 4294573823u;
		}
	}

	private static void gmGmkPointMarkerStay(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_PMARKER_WORK gMS_GMK_PMARKER_WORK = (GMS_GMK_PMARKER_WORK)obj_work;
		ObjDrawObjectActionSet(obj_work, 0);
		gMS_GMK_PMARKER_WORK.markerdist = 0;
		gMS_GMK_PMARKER_WORK.hitcounter = 0;
		obj_work.ppFunc = gmGmkPointMarkerStay_100;
	}

	private static void gmGmkPointMarkerStay_100(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_PMARKER_WORK gMS_GMK_PMARKER_WORK = (GMS_GMK_PMARKER_WORK)obj_work;
		gMS_GMK_PMARKER_WORK.markerdistlast = gMS_GMK_PMARKER_WORK.markerdist;
		gMS_GMK_PMARKER_WORK.markerdist = 0;
		if (gMS_GMK_PMARKER_WORK.hitcounter > 0)
		{
			GmSoundPlaySE("Marker");
			gmGmkPointMarkerStay_200(obj_work);
		}
		else if (g_gm_main_system.marker_pri >= gMS_GMK_PMARKER_WORK.marker_prty)
		{
			gMS_GMK_PMARKER_WORK.marker_prty = 0;
			gmGmkPointMarkerStay_400(obj_work);
		}
	}

	private static void gmGmkPointMarkerStay_200(OBS_OBJECT_WORK obj_work)
	{
		ObjDrawObjectActionSet(obj_work, 1);
		obj_work.ppFunc = gmGmkPointMarkerStay_210;
	}

	private static void gmGmkPointMarkerStay_210(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_PMARKER_WORK gMS_GMK_PMARKER_WORK = (GMS_GMK_PMARKER_WORK)obj_work;
		if ((obj_work.disp_flag & 8) != 0)
		{
			gMS_GMK_PMARKER_WORK.hitcounter--;
			if (gMS_GMK_PMARKER_WORK.hitcounter == 0)
			{
				ObjDrawObjectActionSet(obj_work, 0);
				obj_work.ppFunc = gmGmkPointMarkerStay_300;
			}
			else
			{
				gmGmkPointMarkerStay_200(obj_work);
			}
		}
	}

	private static void gmGmkPointMarkerStay_300(OBS_OBJECT_WORK obj_work)
	{
		if ((obj_work.disp_flag & 8) != 0)
		{
			gmGmkPointMarkerStay_400(obj_work);
		}
	}

	private static void gmGmkPointMarkerStay_400(OBS_OBJECT_WORK obj_work)
	{
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctCmnEsCreate(obj_work, 49);
		GmEffect3DESAddDispOffset(gMS_EFFECT_3DES_WORK, 0f, 34f, 0f);
		if (g_gs_main_sys_info.stage_id == 9)
		{
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.z = obj_work.pos.z + 40960;
		}
		else
		{
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.z = obj_work.pos.z + 65536;
		}
		ObjAction3dNNMaterialMotionLoad(obj_work.obj_3d, 0, null, null, 0, (AMS_AMB_HEADER)ObjDataGet(841).pData);
		ObjDrawObjectActionSet3DNNMaterial(obj_work, 0);
		obj_work.obj_3d.mat_speed = 1f;
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = null;
	}

	private static void gmGmkPointMarkerStart(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_PMARKER_WORK gMS_GMK_PMARKER_WORK = (GMS_GMK_PMARKER_WORK)obj_work;
		ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_pmarker_obj_3d_list[0], gMS_GMK_PMARKER_WORK.OBJ_3D);
		ObjObjectAction3dNNMotionLoad(obj_work, 0, false, ObjDataGet(840), null, 0, null);
		ObjDrawObjectActionSet(obj_work, 0);
		if (g_gm_main_system.marker_pri < gMS_GMK_PMARKER_WORK.marker_prty)
		{
			gMS_GMK_PMARKER_WORK.COMWORK.rect_work[0].flag &= 4294967291u;
			gMS_GMK_PMARKER_WORK.COMWORK.rect_work[1].flag &= 4294967291u;
			OBS_RECT_WORK oBS_RECT_WORK = gMS_GMK_PMARKER_WORK.COMWORK.rect_work[2];
			oBS_RECT_WORK.ppDef = gmGmkPointMarkerHit;
			oBS_RECT_WORK.ppHit = null;
			ObjRectAtkSet(oBS_RECT_WORK, 0, 0);
			ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
			ObjRectWorkSet(oBS_RECT_WORK, -16, -64, 16, 0);
		}
		else
		{
			gMS_GMK_PMARKER_WORK.marker_prty = 0;
		}
		gmGmkPointMarkerStay(obj_work);
	}

