	private static void GmBoss5ScatterSetFlyParam(OBS_OBJECT_WORK obj_work)
	{
		int num = mtMathRand() % 90;
		int ang = ((obj_work.pos.x > obj_work.parent_obj.pos.x) ? AKM_DEGtoA32(num - 45) : AKM_DEGtoA32(num + 90 + 45));
		float gMD_BOSS5_SCT_NDC_FLY_SPD_FLOAT = GMD_BOSS5_SCT_NDC_FLY_SPD_FLOAT;
		obj_work.spd.y = (int)(4096f * gMD_BOSS5_SCT_NDC_FLY_SPD_FLOAT * nnSin(ang));
		obj_work.spd.x = (int)(4096f * gMD_BOSS5_SCT_NDC_FLY_SPD_FLOAT * nnCos(ang));
		obj_work.move_flag |= 128u;
	}

	private static void GmBoss5Init1ShotTimer(GMS_BOSS5_1SHOT_TIMER one_shot_timer, uint frame)
	{
		one_shot_timer.timer = frame;
		one_shot_timer.is_active = 1;
	}

	private static int GmBoss5Update1ShotTimer(GMS_BOSS5_1SHOT_TIMER one_shot_timer)
	{
		if (one_shot_timer.is_active == 0)
		{
			return 0;
		}
		if (one_shot_timer.timer != 0)
		{
			one_shot_timer.timer--;
			return 0;
		}
		one_shot_timer.is_active = 0;
		return 1;
	}

	private static int GmBoss5UpdateVib(int phase_cnt, int scale, ref int pos_x, ref int pos_y)
	{
		int num = phase_cnt;
		if (num >= 40)
		{
			num %= 40;
		}
		pos_x = FX_Mul(scale, gm_boss5_vib_tbl[phase_cnt][0]);
		pos_y = FX_Mul(scale, gm_boss5_vib_tbl[phase_cnt][1]);
		int num2 = num + 1;
		if (num2 >= 40)
		{
			num2 = 0;
		}
		return num2;
	}

	private static void gmBoss5InitExplCreate(GMS_BOSS5_EXPL_WORK expl_work, int expl_type, OBS_OBJECT_WORK parent_obj, int ofst_pos_x, int ofst_pos_y, int width, int height, uint interval_min, uint interval_max, float se_freq)
	{
		expl_work.parent_obj = parent_obj;
		expl_work.expl_type = expl_type;
		expl_work.interval_timer = 0u;
		expl_work.interval_min = interval_min;
		expl_work.interval_max = interval_max;
		expl_work.se_frequency = se_freq;
		expl_work.se_freq_cnt = 0f;
		expl_work.ofst_pos[0] = ofst_pos_x;
		expl_work.ofst_pos[1] = ofst_pos_y;
		expl_work.area[0] = width;
		expl_work.area[1] = height;
	}

	public static void gmBoss5UpdateExplCreate(GMS_BOSS5_EXPL_WORK expl_work)
	{
		if (expl_work.interval_timer != 0)
		{
			expl_work.interval_timer--;
			return;
		}
		int num = expl_work.area[0];
		int num2 = expl_work.area[1];
		VecFx32 vecFx = new VecFx32(expl_work.parent_obj.pos);
		int num3 = 0;
		int num4 = FX_Mul(AkMathRandFx(), num);
		int num5 = FX_Mul(AkMathRandFx(), num2);
		if (expl_work.se_freq_cnt < 1f)
		{
			expl_work.se_freq_cnt += expl_work.se_frequency;
		}
		if (expl_work.se_freq_cnt >= 1f)
		{
			expl_work.se_freq_cnt -= 1f;
			num3 = 1;
		}
		switch (expl_work.expl_type)
		{
		case 0:
			GmBoss5EfctCreateSmallExplosion(vecFx.x + expl_work.ofst_pos[0] - (num >> 1) + num4, vecFx.y + expl_work.ofst_pos[1] - (num2 >> 1) + num5, vecFx.z + GMD_BOSS5_EXPL_OFST_Z);
			if (num3 != 0)
			{
				GmSoundPlaySE("Boss0_02");
			}
			break;
		case 1:
			GmBoss5EfctCreateSmallExplosion(vecFx.x + expl_work.ofst_pos[0] - (num >> 1) + num4, vecFx.y + expl_work.ofst_pos[1] - (num2 >> 1) + num5, vecFx.z + GMD_BOSS5_EXPL_OFST_Z);
			GmBoss5EfctCreateFragments(vecFx.x + expl_work.ofst_pos[0] - (num >> 1) + num4, vecFx.y + expl_work.ofst_pos[1] - (num2 >> 1) + num5, vecFx.z + GMD_BOSS5_EXPL_OFST_Z);
			if (num3 != 0)
			{
				GmSoundPlaySE("Boss0_02");
			}
			break;
		case 2:
			GmBoss5EfctCreateBigExplosion(vecFx.x + expl_work.ofst_pos[0] - (num >> 1) + num4, vecFx.y + expl_work.ofst_pos[1] - (num2 >> 1) + num5, vecFx.z + GMD_BOSS5_EXPL_OFST_Z);
			if (num3 != 0)
			{
				GmSoundPlaySE("Boss0_03");
			}
			break;
		default:
			mppAssertNotImpl();
			return;
		}
		uint num6 = (uint)(AkMathRandFx() * (expl_work.interval_max - expl_work.interval_min) >> 12);
		expl_work.interval_timer = expl_work.interval_min + num6;
	}

	private static void gmBoss5SetCameraLift(GMS_BOSS5_MGR_WORK mgr_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)GmBsCmnGetPlayerObj();
		if ((mgr_work.flag & 0x10) == 0)
		{
			mgr_work.flag |= 16u;
			mgr_work.save_camera_offset[0] = gMS_PLAYER_WORK.gmk_camera_center_ofst_x;
			mgr_work.save_camera_offset[1] = gMS_PLAYER_WORK.gmk_camera_center_ofst_y;
		}
		GmCameraScaleSet(0.85f, 0.0024999997f);
		GmPlayerCameraOffsetSet((GMS_PLAYER_WORK)GmBsCmnGetPlayerObj(), 0, GMD_BOSS5_CAMERA_LIFT_OFFSET_POS_Y);
	}

	private static void gmBoss5RestoreCameraLift(GMS_BOSS5_MGR_WORK mgr_work)
