	private static void gmBoss5CamScrLimitReleaseGently()
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_EFFECT_COM_WORK(), null, 0, "scr_lim_rel_gently");
		oBS_OBJECT_WORK.disp_flag |= 4128u;
		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.user_timer = GMD_BOSS5_CAM_SCR_LIMIT_RELEASE_GNTL_SPD_X_INIT;
		oBS_OBJECT_WORK.ppFunc = gmBoss5CamScrLimitReleaseGentlyProcMain;
	}

	private static void gmBoss5CamScrLimitReleaseGentlyProcMain(OBS_OBJECT_WORK obj_work)
	{
		int num = g_gm_main_system.map_fcol.map_block_num_x * 64 << 12;
		int num2 = g_gm_main_system.map_fcol.right << 12;
		int num3 = 0;
		obj_work.user_timer += GMD_BOSS5_CAM_SCR_LIMIT_RELEASE_GNTL_ACC_X;
		obj_work.user_timer = MTM_MATH_CLIP(obj_work.user_timer, 0, int.MaxValue);
		int num4 = num2 + obj_work.user_timer;
		if (num4 >= num)
		{
			num4 = num;
			num3 = 1;
		}
		GMS_EVE_RECORD_EVENT gMS_EVE_RECORD_EVENT = new GMS_EVE_RECORD_EVENT();
		gMS_EVE_RECORD_EVENT.flag = 4;
		gMS_EVE_RECORD_EVENT.left = 0;
		gMS_EVE_RECORD_EVENT.top = 0;
		gMS_EVE_RECORD_EVENT.width = 0;
		gMS_EVE_RECORD_EVENT.height = 0;
		GmCamScrLimitSetDirect(gMS_EVE_RECORD_EVENT, num4, 0);
		if (num3 != 0)
		{
			obj_work.flag |= 4u;
		}
	}

