	private static void gmBoss5Vibration(int vib_idx)
	{
		GmCameraVibrationSet(gm_boss5_vib_param_tbl[vib_idx][0], gm_boss5_vib_param_tbl[vib_idx][1], gm_boss5_vib_param_tbl[vib_idx][2]);
	}

	private static void gmBoss5DelayedVibration(int vib_idx, uint delay)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_EFFECT_COM_WORK(), null, 0, "boss5_delay_vib");
		oBS_OBJECT_WORK.disp_flag |= 4128u;
		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.user_work = (uint)vib_idx;
		oBS_OBJECT_WORK.user_timer = (int)delay;
		oBS_OBJECT_WORK.ppFunc = gmBoss5DelayedVibrationProcMain;
	}

	private static void gmBoss5DelayedVibrationProcMain(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.user_timer != 0)
		{
			obj_work.user_timer--;
			return;
		}
		gmBoss5Vibration((int)obj_work.user_work);
		obj_work.flag |= 4u;
	}

	private static void gmBoss5DelayedSePlayback(string cue_name, uint delay)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_EFFECT_COM_WORK(), null, 0, "boss5_delay_se");
		oBS_OBJECT_WORK.disp_flag |= 4128u;
		oBS_OBJECT_WORK.flag |= 16u;
		amCriAudioGetGlobal();
		oBS_OBJECT_WORK.user_work = CriAuPlayer.GetCueId(cue_name);
		if (oBS_OBJECT_WORK.user_work != -1)
		{
			oBS_OBJECT_WORK.user_timer = (int)delay;
			oBS_OBJECT_WORK.ppFunc = gmBoss5DelayedSePlaybackProcMain;
		}
	}

	private static void gmBoss5DelayedSePlaybackProcMain(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.user_timer != 0)
		{
			obj_work.user_timer--;
			return;
		}
		GsSoundPlaySeById(obj_work.user_work);
		obj_work.flag |= 4u;
	}

