	private static void gmBoss5InitChasingExpl(GMS_BOSS5_MGR_WORK mgr_work)
	{
		gmBoss5InitExplCreate(mgr_work.small_expl_work, 0, GmBsCmnGetPlayerObj(), GMD_BOSS5_EXPL_CHASE_SMALL_OFST_X, GMD_BOSS5_EXPL_CHASE_SMALL_OFST_Y, GMD_BOSS5_EXPL_CHASE_SMALL_WIDTH, GMD_BOSS5_EXPL_CHASE_SMALL_HEIGHT, GMD_BOSS5_EXPL_CHASE_SMALL_INTERVAL_MIN, GMD_BOSS5_EXPL_CHASE_SMALL_INTERVAL_MAX, GMD_BOSS5_EXPL_CHASE_SMALL_SE_FREQUENCY);
		gmBoss5InitExplCreate(mgr_work.big_expl_work, 2, GmBsCmnGetPlayerObj(), GMD_BOSS5_EXPL_CHASE_BIG_OFST_X + GMD_BOSS5_EXPL_CHASE_BIG_DELAY_OFST_X, GMD_BOSS5_EXPL_CHASE_BIG_OFST_Y, GMD_BOSS5_EXPL_CHASE_BIG_WIDTH, GMD_BOSS5_EXPL_CHASE_BIG_HEIGHT, GMD_BOSS5_EXPL_CHASE_BIG_INTERVAL_MIN, GMD_BOSS5_EXPL_CHASE_BIG_INTERVAL_MAX, GMD_BOSS5_EXPL_CHASE_BIG_SE_FREQUENCY);
	}

	private static void gmBoss5UpdateChasingExpl(GMS_BOSS5_MGR_WORK mgr_work)
	{
		GMS_BOSS5_EXPL_WORK small_expl_work = mgr_work.small_expl_work;
		GMS_BOSS5_EXPL_WORK big_expl_work = mgr_work.big_expl_work;
		small_expl_work.ofst_pos[0] += GMD_BOSS5_EXPL_CHASE_SMALL_CHASE_SPD_X;
		if (small_expl_work.ofst_pos[0] >= GMD_BOSS5_EXPL_CHASE_SMALL_CHASE_OFST_X_MAX)
		{
			small_expl_work.ofst_pos[0] = GMD_BOSS5_EXPL_CHASE_SMALL_CHASE_OFST_X_MAX;
		}
		big_expl_work.ofst_pos[0] += GMD_BOSS5_EXPL_CHASE_BIG_CHASE_SPD_X;
		if (big_expl_work.ofst_pos[0] >= GMD_BOSS5_EXPL_CHASE_BIG_CHASE_OFST_X_MAX + GMD_BOSS5_EXPL_CHASE_BIG_DELAY_OFST_X)
		{
			big_expl_work.ofst_pos[0] = GMD_BOSS5_EXPL_CHASE_BIG_CHASE_OFST_X_MAX + GMD_BOSS5_EXPL_CHASE_BIG_DELAY_OFST_X;
		}
		gmBoss5UpdateExplCreate(mgr_work.small_expl_work);
		gmBoss5UpdateExplCreate(mgr_work.big_expl_work);
	}

	private static void gmBoss5MgrWaitLoad(OBS_OBJECT_WORK obj_work)
	{
		int num = 0;
		if (g_gs_main_sys_info.stage_id != 16 || GmMainDatLoadBossBattleLoadCheck(4))
		{
			num = 1;
		}
		if (num != 0)
		{
			GMS_BOSS5_MGR_WORK gMS_BOSS5_MGR_WORK = (GMS_BOSS5_MGR_WORK)obj_work;
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GmEventMgrLocalEventBirth(330, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
			OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GmEventMgrLocalEventBirth(331, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
			GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (gMS_BOSS5_MGR_WORK.body_work = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK);
			gMS_BOSS5_BODY_WORK.mgr_work = gMS_BOSS5_MGR_WORK;
			oBS_OBJECT_WORK.parent_obj = obj_work;
			oBS_OBJECT_WORK2.parent_obj = oBS_OBJECT_WORK;
			gMS_BOSS5_BODY_WORK.parts_objs[0] = oBS_OBJECT_WORK;
			gMS_BOSS5_BODY_WORK.part_obj_core = oBS_OBJECT_WORK2;
			obj_work.ppFunc = gmBoss5MgrWaitSetup;
		}
	}

	private static void gmBoss5MgrWaitSetup(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS5_MGR_WORK gMS_BOSS5_MGR_WORK = (GMS_BOSS5_MGR_WORK)obj_work;
		GMS_BOSS5_BODY_WORK body_work = gMS_BOSS5_MGR_WORK.body_work;
		int num = 1;
		for (int i = 0; i < 1; i++)
		{
			if (body_work.parts_objs[i] == null)
			{
				num = 0;
			}
		}
		if (body_work.part_obj_core == null)
		{
			num = 0;
		}
		if (num != 0)
		{
			gMS_BOSS5_MGR_WORK.flag |= 1u;
			obj_work.ppFunc = gmBoss5MgrMain;
			gmBoss5MgrProcInit(gMS_BOSS5_MGR_WORK);
		}
	}

	private static void gmBoss5MgrMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS5_MGR_WORK gMS_BOSS5_MGR_WORK = (GMS_BOSS5_MGR_WORK)obj_work;
		if ((gMS_BOSS5_MGR_WORK.flag & 2) != 0 && gMS_BOSS5_MGR_WORK.body_work != null)
		{
			GMM_BS_OBJ(gMS_BOSS5_MGR_WORK.body_work).flag |= 8u;
			gMS_BOSS5_MGR_WORK.body_work = null;
		}
		if (gMS_BOSS5_MGR_WORK.proc_update != null)
		{
			gMS_BOSS5_MGR_WORK.proc_update(gMS_BOSS5_MGR_WORK);
		}
	}

	private static void gmBoss5MgrProcInit(GMS_BOSS5_MGR_WORK mgr_work)
	{
		mgr_work.proc_update = gmBoss5MgrProcUpdateWaitOpeningDemoBegin;
	}

	private static void gmBoss5MgrProcUpdateWaitOpeningDemoBegin(GMS_BOSS5_MGR_WORK mgr_work)
	{
		if ((mgr_work.flag & 0x200000) != 0 && (mgr_work.flag & 0x400000) != 0)
		{
			GMS_PLAYER_WORK ply_work = (GMS_PLAYER_WORK)GmBsCmnGetPlayerObj();
			g_gm_main_system.game_flag &= 4294966271u;
			GmSoundChangeFinalBossBGM();
			GmPlySeqChangeBoss5Demo(ply_work, mgr_work.ply_demo_run_dest_x, false);
			mgr_work.proc_update = gmBoss5MgrProcUpdateOpeningDemo;
			GmMapSetMapDrawSize(8);
		}
	}

	private static void gmBoss5MgrProcUpdateOpeningDemo(GMS_BOSS5_MGR_WORK mgr_work)
	{
		if ((mgr_work.flag & 0x2000000) != 0)
		{
			GMS_PLAYER_WORK ply_work = (GMS_PLAYER_WORK)GmBsCmnGetPlayerObj();
			g_gm_main_system.game_flag |= 1024u;
			GmPlySeqChangeBoss5DemoEnd(ply_work);
			mgr_work.proc_update = gmBoss5MgrProcUpdateIdle;
		}
	}

	private static void gmBoss5MgrProcUpdateIdle(GMS_BOSS5_MGR_WORK mgr_work)
	{
		if ((mgr_work.flag & 0x4000000) != 0)
		{
			GmBoss5LandCreate(mgr_work);
			gmBoss5TransferPlayerToASide();
			gmBoss5HideMapBSide();
			mgr_work.proc_update = gmBoss5MgrProcUpdateWaitDefeat;
		}
	}

	private static void gmBoss5MgrProcUpdateWaitDefeat(GMS_BOSS5_MGR_WORK mgr_work)
	{
		if ((mgr_work.flag & 0x8000000) != 0)
		{
			g_gm_main_system.game_flag &= 4294966271u;
			g_gm_main_system.game_flag |= 1048576u;
			mgr_work.wait_timer = GMD_BOSS5_MGR_WAIT_EXPLODE_TIME;
			GmPadVibSet(1, -1f, 16384, 16384, -1f, 0f, 0f, 32768u);
			mgr_work.proc_update = gmBoss5MgrProcUpdateWaitExplode;
		}
	}

	private static void gmBoss5MgrProcUpdateWaitExplode(GMS_BOSS5_MGR_WORK mgr_work)
	{
		if (mgr_work.wait_timer != 0)
		{
			mgr_work.wait_timer--;
			return;
		}
		mgr_work.wait_timer = GMD_BOSS5_MGR_CLOSING_DEMO_WAIT_BEGIN_TIME_MAX;
		gmBoss5CamScrLimitReleaseGently();
		mgr_work.proc_update = gmBoss5MgrProcUpdateWaitClosingDemoBegin;
	}

	private static void gmBoss5MgrProcUpdateWaitClosingDemoBegin(GMS_BOSS5_MGR_WORK mgr_work)
	{
		if (mgr_work.wait_timer != 0)
		{
			mgr_work.wait_timer--;
		}
		if ((GmBsCmnGetPlayerObj().move_flag & 1) != 0 || mgr_work.wait_timer == 0)
		{
			GMS_PLAYER_WORK ply_work = (GMS_PLAYER_WORK)GmBsCmnGetPlayerObj();
			GmPlySeqChangeBoss5Demo(ply_work, g_gm_main_system.map_size[0] << 12, true);
			mgr_work.proc_update = gmBoss5MgrProcUpdateClosingDemoLeaveBody;
		}
	}

	private static void gmBoss5MgrProcUpdateClosingDemoLeaveBody(GMS_BOSS5_MGR_WORK mgr_work)
	{
		if ((mgr_work.flag & 0x10000000) != 0)
		{
			gmBoss5InitChasingExpl(mgr_work);
			mgr_work.wait_timer = GMD_BOSS5_MGR_CLOSING_DEMO_DURATION_TIME;
			mgr_work.proc_update = gmBoss5MgrProcUpdateClosingDemoEscape;
		}
	}

	private static void gmBoss5MgrProcUpdateClosingDemoEscape(GMS_BOSS5_MGR_WORK mgr_work)
	{
		gmBoss5UpdateChasingExpl(mgr_work);
		if (mgr_work.wait_timer != 0)
		{
			mgr_work.wait_timer--;
			return;
		}
		gmBoss5InitLastFadeOut(mgr_work);
		mgr_work.proc_update = gmBoss5MgrProcUpdateClosingDemoWaitFadeEnd;
	}

	private static void gmBoss5MgrProcUpdateClosingDemoWaitFadeEnd(GMS_BOSS5_MGR_WORK mgr_work)
	{
		gmBoss5UpdateChasingExpl(mgr_work);
		if ((mgr_work.flag & 0x80000000u) != 0)
		{
			GMM_PAD_VIB_STOP();
			mgr_work.wait_timer = GMD_BOSS5_MGR_CLOSING_DEMO_WHITEOUT_TIME;
			mgr_work.proc_update = gmBoss5MgrProcUpdateClosingDemoWaitFinish;
		}
	}

	private static void gmBoss5MgrProcUpdateClosingDemoWaitFinish(GMS_BOSS5_MGR_WORK mgr_work)
	{
		if (mgr_work.wait_timer != 0)
		{
			mgr_work.wait_timer--;
			return;
		}
		g_gm_main_system.game_flag |= 4u;
		mgr_work.proc_update = null;
	}

	private static void gmBoss5BodyExit(MTS_TASK_TCB tcb)
	{
		GMS_BOSS5_BODY_WORK body_work = (GMS_BOSS5_BODY_WORK)mtTaskGetTcbWork(tcb);
		gmBoss5BodyReleaseCallbacks(body_work);
		gmBoss5BodyFreeSeHandles(body_work);
		GmEnemyDefaultExit(tcb);
	}

	private static void gmBoss5BodySetActionWhole(GMS_BOSS5_BODY_WORK body_work, int act_id)
	{
		gmBoss5BodySetActionWhole(body_work, act_id, 0);
	}

	private static void gmBoss5BodySetActionWhole(GMS_BOSS5_BODY_WORK body_work, int act_id, int force_change)
	{
		GMS_BOSS5_PART_ACT_INFO[] array = gm_boss5_act_id_tbl[act_id];
		if (force_change == 0 && body_work.whole_act_id == act_id)
		{
			return;
		}
		body_work.whole_act_id = act_id;
		for (int i = 0; i < 1; i++)
		{
			if (body_work.parts_objs[i] != null)
			{
				if (array[i].is_maintain == 0)
				{
					GmBsCmnSetAction(body_work.parts_objs[i], array[i].act_id, array[i].is_repeat, array[i].is_blend);
				}
				else if (array[i].is_repeat != 0)
				{
					GMM_BS_OBJ(body_work).disp_flag |= 4u;
				}
				body_work.parts_objs[i].obj_3d.speed[0] = array[i].mtn_spd;
				body_work.parts_objs[i].obj_3d.blend_spd = array[i].blend_spd;
			}
		}
	}

	private static void gmBoss5BodySetDirection(GMS_BOSS5_BODY_WORK body_work, int dir_type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		switch (dir_type)
		{
		case 0:
			oBS_OBJECT_WORK.dir.y = (ushort)AKM_DEGtoA16(-90);
			oBS_OBJECT_WORK.disp_flag |= 1u;
			break;
		case 1:
			oBS_OBJECT_WORK.dir.y = (ushort)AKM_DEGtoA16(90);
			oBS_OBJECT_WORK.disp_flag &= 4294967294u;
			break;
		case 2:
			oBS_OBJECT_WORK.dir.y = 0;
			oBS_OBJECT_WORK.disp_flag &= 4294967294u;
			break;
		default:
			oBS_OBJECT_WORK.dir.y = (ushort)AKM_DEGtoA16(-90);
			oBS_OBJECT_WORK.disp_flag |= 1u;
			break;
		}
	}

	private static int gmBoss5BodyIsPlayerBehind(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GmBsCmnGetPlayerObj();
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GMM_BS_OBJ(body_work);
		OBS_OBJECT_WORK part_obj_core = body_work.part_obj_core;
		if ((oBS_OBJECT_WORK2.disp_flag & 1) != 0)
		{
			if (part_obj_core.pos.x < oBS_OBJECT_WORK.pos.x)
			{
				return 1;
			}
		}
		else if (oBS_OBJECT_WORK.pos.x < part_obj_core.pos.x)
		{
			return 1;
		}
		return 0;
	}

	private static void gmBoss5BodySetNoHitTime(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_RECT_WORK[][] array = new OBS_RECT_WORK[3][]
		{
			body_work.sub_rect_work[0],
			body_work.sub_rect_work[1],
			((GMS_ENEMY_COM_WORK)body_work).rect_work
		};
		body_work.no_hit_timer = (uint)GMD_BOSS5_BODY_DMG_NO_HIT_TIME;
		body_work.flag |= 32u;
		for (int i = 0; i < 3; i++)
		{
			array[i][0].flag |= 2048u;
			array[i][0].flag &= 4294967291u;
		}
	}

	private static void gmBoss5BodyUpdateNoHitTime(GMS_BOSS5_BODY_WORK body_work)
	{
		if (body_work.no_hit_timer != 0)
		{
			body_work.no_hit_timer--;
			return;
		}
		OBS_RECT_WORK[][] array = new OBS_RECT_WORK[3][]
		{
			body_work.sub_rect_work[0],
			body_work.sub_rect_work[1],
			((GMS_ENEMY_COM_WORK)body_work).rect_work
		};
		body_work.flag &= 4294967263u;
		for (int i = 0; i < 3; i++)
		{
			if ((body_work.def_rect_req_flag & (1 << i)) != 0)
			{
				array[i][0].flag &= 4294965247u;
				array[i][0].flag |= 4u;
			}
			else
			{
				array[i][0].flag |= 2048u;
				array[i][0].flag &= 4294967291u;
			}
		}
	}

	private static void gmBoss5BodySetPokeTriggerLimitTime(GMS_BOSS5_BODY_WORK body_work)
	{
		body_work.poke_trg_limit_timer = 120u;
		body_work.flag |= 128u;
	}

	private static void gmBoss5BodyUpdatePokeTriggerLimitTime(GMS_BOSS5_BODY_WORK body_work)
	{
		if (body_work.poke_trg_limit_timer != 0)
		{
			body_work.poke_trg_limit_timer--;
		}
		else
		{
			body_work.flag &= 4294967167u;
		}
	}

	private static int gmBoss5BodyIsWithinPokeTriggerLimitTime(GMS_BOSS5_BODY_WORK body_work)
	{
		if ((body_work.flag & 0x80) != 0)
		{
			return 1;
		}
		return 0;
	}

	private static void gmBoss5BodyClearPokeTriggerLimitTime(GMS_BOSS5_BODY_WORK body_work)
	{
		body_work.poke_trg_limit_timer = 0u;
