	}

	private static void gmBoss5BodyExecDamageRoutine(GMS_BOSS5_BODY_WORK body_work)
	{
		GMS_BOSS5_MGR_WORK mgr_work = body_work.mgr_work;
		if (mgr_work.life != 0)
		{
			mgr_work.life--;
		}
		if (0 < mgr_work.life)
		{
			body_work.flag |= 2147483648u;
			if (body_work.state == 2)
			{
				if (gmBoss5BodyIsWithinPokeTriggerLimitTime(body_work) != 0)
				{
					if (gmBoss5BodyIsPoking(body_work) == 0)
					{
						body_work.flag |= 8388608u;
					}
				}
				else
				{
					gmBoss5BodySetPokeTriggerLimitTime(body_work);
				}
			}
			gmBoss5BodyTryStartTurret(body_work);
		}
		else if ((body_work.flag & 0x10000) == 0)
		{
			mgr_work.life = 1;
		}
		else
		{
			body_work.flag |= 4194304u;
			GMM_BS_OBJ(body_work).flag |= 2u;
			mgr_work.life = 0;
		}
		gmBoss5BodySeqTryRequestEnableStr(body_work);
	}

	private static void gmBoss5BodyUpdateMainRectPosition(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		OBS_OBJECT_WORK part_obj_core = body_work.part_obj_core;
		int x = part_obj_core.pos.x - oBS_OBJECT_WORK.pos.x;
		int y = part_obj_core.pos.y - oBS_OBJECT_WORK.pos.y;
		for (int i = 0; i < 3; i++)
		{
			VEC_Set(ref body_work.ene_3d.ene_com.rect_work[i].rect.pos, x, y, 0);
		}
	}

	private static void gmBoss5BodyUpdateSubRectPosition(GMS_BOSS5_BODY_WORK body_work)
	{
		snm_reg_id_tbl[0] = body_work.leg_snm_reg_ids[0];
		snm_reg_id_tbl[1] = body_work.leg_snm_reg_ids[1];
		for (int i = 0; i < 2; i++)
		{
			NNS_MATRIX nNS_MATRIX = GmBsCmnGetSNMMtx(body_work.snm_work, snm_reg_id_tbl[i]);
			int x = FX_F32_TO_FX32(nNS_MATRIX.M03) - body_work.pivot_prev_pos.x;
			int y = -FX_F32_TO_FX32(nNS_MATRIX.M13) - body_work.pivot_prev_pos.y;
			for (int j = 0; j < 3; j++)
			{
				VEC_Set(ref body_work.sub_rect_work[i][j].rect.pos, x, y, 0);
			}
		}
	}

	private static void gmBoss5BodySetupRect(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK parent_obj = GMM_BS_OBJ(body_work);
		OBS_RECT_WORK[][] array = new OBS_RECT_WORK[3][]
		{
			body_work.sub_rect_work[0],
			body_work.sub_rect_work[1],
			((GMS_ENEMY_COM_WORK)body_work).rect_work
		};
		ushort[] array2 = new ushort[3] { 0, 2, 1 };
		ushort[] array3 = new ushort[3] { 65533, 65535, 65534 };
		for (int i = 0; i < 2; i++)
		{
			for (int j = 0; j < 3; j++)
			{
				ObjRectGroupSet(body_work.sub_rect_work[i][j], 1, 1);
				ObjRectAtkSet(body_work.sub_rect_work[i][j], array2[j], 1);
				ObjRectDefSet(body_work.sub_rect_work[i][j], array3[j], 0);
				body_work.sub_rect_work[i][j].parent_obj = parent_obj;
				body_work.sub_rect_work[i][j].flag &= 4294967291u;
			}
			body_work.sub_rect_work[i][0].ppDef = GmEnemyDefaultDefFunc;
			body_work.sub_rect_work[i][1].ppHit = GmEnemyDefaultAtkFunc;
			body_work.sub_rect_work[i][2].flag |= 1048800u;
		}
		for (int k = 0; k < 3; k++)
		{
			array[k][0].ppDef = gmBoss5BodyDamageDefFunc;
		}
		gmBoss5BodyChangeRectSetting(body_work, 0);
	}

	private static void gmBoss5BodyChangeRectSetting(GMS_BOSS5_BODY_WORK body_work, int rect_setting)
	{
		OBS_RECT_WORK[][] array = new OBS_RECT_WORK[3][]
		{
			body_work.sub_rect_work[0],
			body_work.sub_rect_work[1],
			((GMS_ENEMY_COM_WORK)body_work).rect_work
		};
		GMS_BOSS5_BODY_RECT_SETTING_INFO gMS_BOSS5_BODY_RECT_SETTING_INFO = gm_boss5_body_rect_setting_info_tbl[rect_setting];
		if (gMS_BOSS5_BODY_RECT_SETTING_INFO.is_invincible != 0)
		{
			body_work.flag |= 1u;
		}
		else
		{
			body_work.flag &= 4294967294u;
		}
		if (gMS_BOSS5_BODY_RECT_SETTING_INFO.is_leakage != 0)
		{
			body_work.flag |= 4096u;
		}
		else
		{
			body_work.flag &= 4294963199u;
		}
		for (int i = 0; i < 3; i++)
		{
			GMS_BOSS5_RECTPOINT_SETTING_INFO gMS_BOSS5_RECTPOINT_SETTING_INFO = gMS_BOSS5_BODY_RECT_SETTING_INFO.point_setting_info[i];
			for (int j = 0; j < 3; j++)
			{
				ObjRectWorkSet(array[i][j], gMS_BOSS5_RECTPOINT_SETTING_INFO.rect_size[j][0], gMS_BOSS5_RECTPOINT_SETTING_INFO.rect_size[j][1], gMS_BOSS5_RECTPOINT_SETTING_INFO.rect_size[j][2], gMS_BOSS5_RECTPOINT_SETTING_INFO.rect_size[j][3]);
				if (((1 << j) & gMS_BOSS5_RECTPOINT_SETTING_INFO.enable_bit_flag) != 0)
				{
					if (j == 0)
					{
						body_work.def_rect_req_flag |= (uint)(1 << i);
						if ((body_work.flag & 0x20) == 0)
						{
							array[i][j].flag &= 4294965247u;
							array[i][j].flag |= 4u;
						}
					}
					else
					{
						array[i][j].flag &= 4294965247u;
						array[i][j].flag |= 4u;
					}
				}
				else
				{
					array[i][j].flag |= 2048u;
					array[i][j].flag &= 4294967291u;
					if (j == 0)
					{
						body_work.def_rect_req_flag &= (uint)(~(1 << i));
					}
				}
			}
		}
	}

	private static void gmBoss5BodyChangeRectSettingDefault(GMS_BOSS5_BODY_WORK body_work)
	{
		if (gmBoss5BodySeqIsStr(body_work) != 0)
