	}

	private static void gmBoss5BodyUpdatePlayTargetSe(GMS_BOSS5_BODY_WORK body_work)
	{
		if (body_work.targ_se_cur_interval >= 0f)
		{
			body_work.targ_se_cur_interval -= GMD_BOSS5_BODY_SE_TARGET_INTERVAL_DEC_SPD;
		}
		else
		{
			body_work.targ_se_cur_interval = 0f;
		}
		if (GmBoss5Update1ShotTimer(body_work.targ_se_timer) != 0)
		{
			uint num = (uint)body_work.targ_se_cur_interval;
			if (num <= GMD_BOSS5_BODY_SE_TARGET_INTERVAL_MIN)
			{
				num = (uint)GMD_BOSS5_BODY_SE_TARGET_INTERVAL_MIN;
			}
			GmSoundPlaySE("FinalBoss05");
			GmBoss5Init1ShotTimer(body_work.targ_se_timer, num);
		}
	}

