	private static int gmBoss5BodyGetStompFallDirectionType(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (oBS_OBJECT_WORK.pos.x <= GMM_BOSS5_AREA_LEFT() + GMD_BOSS5_BODY_STOMP_WALL_BEHIND_WALL_DISTANCE)
		{
			return 1;
		}
		if (oBS_OBJECT_WORK.pos.x >= GMM_BOSS5_AREA_RIGHT() - GMD_BOSS5_BODY_STOMP_WALL_BEHIND_WALL_DISTANCE)
		{
			return 0;
		}
		if (oBS_OBJECT_WORK.pos.x < GmBsCmnGetPlayerObj().pos.x)
		{
			return 1;
		}
		if (oBS_OBJECT_WORK.pos.x > GmBsCmnGetPlayerObj().pos.x)
		{
			return 0;
		}
		if ((GmBsCmnGetPlayerObj().disp_flag & 1) != 0)
		{
			return 0;
		}
		return 1;
	}

