	private static void gmBoss5BodyRecordGapAdjustmentDest(GMS_BOSS5_BODY_WORK body_work)
	{
		int[] array = new int[2] { body_work.lfoot_snm_reg_id, body_work.rfoot_snm_reg_id };
		for (int i = 0; i < 2; i++)
		{
			NNS_MATRIX nNS_MATRIX = GmBsCmnGetSNMMtx(body_work.snm_work, array[i]);
			int x = body_work.grdmv_pivot_pos.x;
			int num = FX_F32_TO_FX32(nNS_MATRIX.M03);
			body_work.foot_ofst_record_dest[i] = num - x;
			if ((GMM_BS_OBJ(body_work).disp_flag & 1) != 0)
			{
				body_work.foot_ofst_record_dest[i] = -body_work.foot_ofst_record_dest[i];
			}
		}
	}

