			int x = body_work.grdmv_pivot_pos.x;
			int num = FX_F32_TO_FX32(nNS_MATRIX.M03);
			body_work.foot_ofst_record_src[i] = num - x;
			if ((GMM_BS_OBJ(body_work).disp_flag & 1) != 0)
