	private static void gmBoss5BodyUpdateAdjustMtnBlendHGap(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (body_work.adj_hgap_is_active != 0)
		{
			int num = body_work.foot_ofst_record_dest[body_work.adj_hgap_leg_type] - body_work.foot_ofst_record_src[body_work.adj_hgap_leg_type];
			num = (int)((float)num * gm_boss5_act_id_tbl[body_work.adj_hgap_act_id][0].blend_spd);
			if ((GMM_BS_OBJ(body_work).disp_flag & 1) != 0)
			{
				oBS_OBJECT_WORK.pos.x += num;
			}
			else
			{
				oBS_OBJECT_WORK.pos.x -= num;
			}
		}
	}

