	private static void gmBoss5BodyInitGroundingMove(GMS_BOSS5_BODY_WORK body_work, int ref_snm_reg_id)
	{
		GMS_BOSS5_GRD_MOVE_WORK grdmv_work = body_work.grdmv_work;
		grdmv_work.cur_diff_x = 0;
		grdmv_work.prev_diff_x = 0;
		grdmv_work.ref_snm_reg_id = ref_snm_reg_id;
		grdmv_work.is_first_updated = 0;
	}

	private static void gmBoss5BodyUpdateGroundingMove(GMS_BOSS5_BODY_WORK body_work)
	{
		GMS_BOSS5_GRD_MOVE_WORK grdmv_work = body_work.grdmv_work;
		if (grdmv_work.ref_snm_reg_id != -1)
		{
			NNS_MATRIX nNS_MATRIX = GmBsCmnGetSNMMtx(body_work.snm_work, grdmv_work.ref_snm_reg_id);
			int x = body_work.grdmv_pivot_pos.x;
			int num = FX_F32_TO_FX32(nNS_MATRIX.M03);
			grdmv_work.prev_diff_x = grdmv_work.cur_diff_x;
			grdmv_work.cur_diff_x = num - x;
			if (grdmv_work.is_first_updated == 0)
			{
				grdmv_work.is_first_updated = 1;
			}
			else
			{
				GMM_BS_OBJ(body_work).pos.x -= grdmv_work.cur_diff_x - grdmv_work.prev_diff_x;
			}
		}
	}

