		{
			if (gm_boss5_body_walk_move_info_tbl[num2].switching_frame <= num)
			{
				if (gm_boss5_body_walk_move_info_tbl[num2].move_phase_type != body_work.cur_move_phase_type)
				{
					gmBoss5BodyChangeMovePhase(body_work, gm_boss5_body_walk_move_info_tbl[num2].move_phase_type);
