	}

	private static int _gmBoss5BodyUpdateMonitoringWalkEnd(GMS_BOSS5_BODY_WORK body_work, ref int leg_type, bool ltAvailable)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		float num = oBS_OBJECT_WORK.obj_3d.frame[0];
		int num2 = 0;
		if (gmBoss5BodyIsPlayerBehind(body_work) != 0)
		{
			body_work.is_player_behind = 1;
		}
		int num3;
		for (num3 = 4; num3 >= 0; num3--)
		{
			if (gm_boss5_body_walk_ground_timing_info_tbl[num3].grounding_frame <= num)
			{
				if (num3 != body_work.walk_end_monitor_phase_cnt)
				{
					num2 = 1;
					body_work.walk_end_monitor_phase_cnt = num3;
				}
				break;
			}
		}
		if (ltAvailable)
		{
			if (num3 >= 0)
			{
				leg_type = gm_boss5_body_walk_ground_timing_info_tbl[num3].leg_type;
			}
			else
			{
				leg_type = 0;
			}
		}
		if (num3 >= 4)
		{
			return 0;
		}
		if (num2 != 0)
		{
			if (body_work.is_player_behind != 0)
			{
				return 1;
			}
			if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
			{
				if (oBS_OBJECT_WORK.pos.x <= GMM_BOSS5_AREA_LEFT() + GMD_BOSS5_BODY_WALK_WALK_END_WALL_DISTANCE)
				{
					return 1;
				}
			}
			else if (oBS_OBJECT_WORK.pos.x >= GMM_BOSS5_AREA_RIGHT() - GMD_BOSS5_BODY_WALK_WALK_END_WALL_DISTANCE)
			{
				return 1;
			}
		}
		return 0;
	}

