				GmBoss5EfctCreateRunStepSmoke(body_work, 0);
				break;
			case 1:
				GmBoss5EfctCreateRunStepSmoke(body_work, 1);
				break;
			}
			gmBoss5Vibration(1);
			GmSoundPlaySE("FinalBoss03");
			return 1;
		}
		return 1;
	}

