	private static void gmBoss5BodyInitBerserkTurn(GMS_BOSS5_BODY_WORK body_work, int turn_type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		float num;
		switch (turn_type)
		{
		case 0:
			num = GMD_BOSS5_BODY_BERSERK_TURN_FRONT_DEG_F;
			break;
		case 1:
			num = GMD_BOSS5_BODY_BERSERK_TURN_RETURN_DEG_F;
			break;
		default:
			num = 0f;
			break;
		}
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			num = 0f - num;
		}
		body_work.turn_src_dir = (int)(0xFFFFL & (long)(int)oBS_OBJECT_WORK.dir.y);
		int num2 = (int)(0xFFFFL & (long)AKM_DEGtoA32(num));
		body_work.turn_tgt_ofst_dir = (int)(0xFFFFL & (long)(num2 - body_work.turn_src_dir));
		if (body_work.turn_tgt_ofst_dir > AKM_DEGtoA32(180))
		{
			body_work.turn_tgt_ofst_dir = (int)((long)body_work.turn_tgt_ofst_dir - 65536L);
		}
		body_work.turn_ratio = 0f;
	}

	private static int gmBoss5BodyUpdateBerserkTurn(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		int result = 0;
		body_work.turn_ratio += GMD_BOSS5_BODY_BERSERK_TURN_RATIO_SPD;
		if (body_work.turn_ratio >= 1f)
		{
			body_work.turn_ratio = 1f;
			result = 1;
		}
		int num = (int)((float)body_work.turn_tgt_ofst_dir * body_work.turn_ratio);
		oBS_OBJECT_WORK.dir.y = (ushort)(0xFFFFuL & (ulong)(body_work.turn_src_dir + num));
		return result;
	}

	private static void gmBoss5BodyClearBerserkTurn(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			gmBoss5BodySetDirection(body_work, 0);
		}
		else
		{
			gmBoss5BodySetDirection(body_work, 1);
		}
		body_work.turn_src_dir = 0;
		body_work.turn_tgt_ofst_dir = 0;
		body_work.turn_ratio = 0f;
	}

