	}

	private static int gmBoss5BodyIsPoking(GMS_BOSS5_BODY_WORK body_work)
	{
		if ((body_work.flag & 0x40) != 0)
		{
			return 1;
		}
		return 0;
	}

	private static void gmBoss5BodyInitArmAnim(GMS_BOSS5_BODY_WORK body_work, GMS_BOSS5_ARM_ANIM_INFO anim_info)
	{
		if (anim_info.wait_time != 0)
		{
			body_work.arm_anim_work.is_anim = 0;
			body_work.arm_anim_work.anim_wait_timer = anim_info.wait_time;
			body_work.arm_anim_work.cur_rate = 0f;
			body_work.arm_anim_work.rate_add = 0f;
			for (int i = 0; i < 3; i++)
			{
				nnMakeRotateXYZQuaternion(out body_work.arm_anim_work.start_quat[i], anim_info.part_anim_info[i].start_rot.x, anim_info.part_anim_info[i].start_rot.y, anim_info.part_anim_info[i].start_rot.z);
				nnMakeUnitQuaternion(ref body_work.arm_anim_work.end_quat[i]);
			}
		}
		else
		{
			body_work.arm_anim_work.is_anim = 1;
			body_work.arm_anim_work.anim_wait_timer = 0u;
			body_work.arm_anim_work.cur_rate = 0f;
			body_work.arm_anim_work.rate_add = anim_info.slerp_inc_rate;
			for (int j = 0; j < 3; j++)
			{
				nnMakeRotateXYZQuaternion(out body_work.arm_anim_work.start_quat[j], anim_info.part_anim_info[j].start_rot.x, anim_info.part_anim_info[j].start_rot.y, anim_info.part_anim_info[j].start_rot.z);
				nnMakeRotateXYZQuaternion(out body_work.arm_anim_work.end_quat[j], anim_info.part_anim_info[j].end_rot.x, anim_info.part_anim_info[j].end_rot.y, anim_info.part_anim_info[j].end_rot.z);
			}
		}
		for (int k = 0; k < 3; k++)
		{
			gmBoss5BodySetArmPoseParam(body_work, 0, k, ref body_work.arm_anim_work.start_quat[k]);
			NNS_QUATERNION dst_quat;
			AkMathInvertYZQuaternion(out dst_quat, ref body_work.arm_anim_work.start_quat[k]);
			gmBoss5BodySetArmPoseParam(body_work, 1, k, ref dst_quat);
		}
		gmBoss5BodyApplyArmPose(body_work);
	}

	private static int gmBoss5BodyUpdateArmAnim(GMS_BOSS5_BODY_WORK body_work)
	{
		int result = 0;
		if (body_work.arm_anim_work.is_anim != 0)
		{
			body_work.arm_anim_work.cur_rate += body_work.arm_anim_work.rate_add;
			if (body_work.arm_anim_work.cur_rate >= 1f)
			{
				body_work.arm_anim_work.cur_rate = 1f;
				result = 1;
			}
			for (int i = 0; i < 3; i++)
			{
				NNS_QUATERNION dst;
				nnSlerpQuaternion(out dst, ref body_work.arm_anim_work.start_quat[i], ref body_work.arm_anim_work.end_quat[i], body_work.arm_anim_work.cur_rate);
				gmBoss5BodySetArmPoseParam(body_work, 0, i, ref dst);
				NNS_QUATERNION dst_quat;
				AkMathInvertYZQuaternion(out dst_quat, ref dst);
				gmBoss5BodySetArmPoseParam(body_work, 1, i, ref dst_quat);
			}
		}
		else if (body_work.arm_anim_work.anim_wait_timer != 0)
		{
			body_work.arm_anim_work.anim_wait_timer--;
		}
		else
		{
			result = 1;
		}
		gmBoss5BodyApplyArmPose(body_work);
		return result;
	}

	private static void gmBoss5BodyInitCloseCanopy(GMS_BOSS5_BODY_WORK body_work)
	{
		nnMakeRotateXYZQuaternion(out body_work.cnpy_close_init_quat, GMD_BOSS5_BODY_CANOPY_CLOSE_START_ANGLE_X, 0, 0);
		nnMakeRotateXYZQuaternion(out body_work.cnpy_close_dest_quat, 0, 0, 0);
		body_work.cnpy_close_ratio = 0f;
		body_work.cnpy_close_ratio_spd = 0f;
	}

	private static int gmBoss5BodyUpdateCloseCanopy(GMS_BOSS5_BODY_WORK body_work, int is_update)
	{
		NNS_QUATERNION dst = default(NNS_QUATERNION);
		int result = 0;
		if (is_update != 0)
		{
			body_work.cnpy_close_ratio_spd += GMD_BOSS5_BODY_CANOPY_CLOSE_RATIO_SPD_ACC;
		}
		if (body_work.cnpy_close_ratio_spd >= GMD_BOSS5_BODY_CANOPY_CLOSE_RATIO_SPD_MAX)
		{
			body_work.cnpy_close_ratio_spd = GMD_BOSS5_BODY_CANOPY_CLOSE_RATIO_SPD_MAX;
		}
		if (is_update != 0)
		{
			body_work.cnpy_close_ratio += body_work.cnpy_close_ratio_spd;
		}
		if (body_work.cnpy_close_ratio >= 1f)
		{
			body_work.cnpy_close_ratio = 1f;
			result = 1;
		}
		nnSlerpQuaternion(out dst, ref body_work.cnpy_close_init_quat, ref body_work.cnpy_close_dest_quat, body_work.cnpy_close_ratio);
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		nnMakeQuaternionMatrix(nNS_MATRIX, ref dst);
		GmBsCmnSetCNMMtx(body_work.cnm_mgr_work, nNS_MATRIX, body_work.head_cnm_reg_id);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
		NNS_MATRIX nNS_MATRIX2 = GlobalPool<NNS_MATRIX>.Alloc();
		nnMakeScaleMatrix(nNS_MATRIX2, 0f, 0f, 0f);
		GmBsCmnSetCNMMtx(body_work.cnm_mgr_work, nNS_MATRIX2, body_work.pole_cnm_reg_id);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX2);
		return result;
	}

	private static void gmBoss5BodyInitScatterFall(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		oBS_OBJECT_WORK.move_flag |= 144u;
		oBS_OBJECT_WORK.move_flag &= 4294967294u;
		ObjObjectFieldRectSet(oBS_OBJECT_WORK, GMD_BOSS5_BODY_SCT_FIEELD_RECT_SIZE_LEFT, GMD_BOSS5_BODY_SCT_FIEELD_RECT_SIZE_TOP, GMD_BOSS5_BODY_SCT_FIEELD_RECT_SIZE_RIGHT, GMD_BOSS5_BODY_SCT_FIEELD_RECT_SIZE_BOTTOM);
		body_work.sct_land_vib_timer = GMD_BOSS5_BODY_DEFEAT_SCT_FALL_LAND_VIB_TIME;
	}

	private static int gmBoss5BodyUpdateScatterFall(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (body_work.sct_land_vib_timer != 0)
		{
			if ((oBS_OBJECT_WORK.move_flag & 1) == 0)
			{
				int num = (int)((float)GMD_BOSS5_BODY_DEFEAT_SCT_FALL_LAND_VIB_AMP * ((float)body_work.sct_land_vib_timer / (float)GMD_BOSS5_BODY_DEFEAT_SCT_FALL_LAND_VIB_TIME));
				oBS_OBJECT_WORK.ofst.y = (int)((float)num * nnSin((int)((GMD_BOSS5_BODY_DEFEAT_SCT_FALL_LAND_VIB_TIME - body_work.sct_land_vib_timer) * GMD_BOSS5_BODY_DEFEAT_SCT_FALL_LAND_VIB_DEG_SPD)));
				body_work.sct_land_vib_timer--;
			}
			return 0;
		}
		return 1;
	}

	private static void gmBoss5BodyInitShakeAccelerate(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		body_work.bsk_shake_acc_ratio = 0f;
		body_work.bsk_shake_acc_ratio_spd = 0f;
		body_work.bsk_shake_init_spd = oBS_OBJECT_WORK.obj_3d.speed[0];
	}

	private static int gmBoss5BodyUpdateShakeAccelerate(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		int result = 0;
		body_work.bsk_shake_acc_ratio_spd += GMD_BOSS5_BODY_BERSERK_SHAKE_MOTION_SPD_RATIO_ACC;
		body_work.bsk_shake_acc_ratio += body_work.bsk_shake_acc_ratio_spd;
		if (body_work.bsk_shake_acc_ratio >= 1f)
		{
			body_work.bsk_shake_acc_ratio = 1f;
			body_work.bsk_shake_acc_ratio_spd = 0f;
			result = 1;
		}
		oBS_OBJECT_WORK.obj_3d.speed[0] = body_work.bsk_shake_acc_ratio * GMD_BOSS5_BODY_BERSERK_SHAKE_MOTION_SPD_DEST + (1f - body_work.bsk_shake_acc_ratio) * body_work.bsk_shake_init_spd;
		return result;
	}

	private static void gmBoss5BodyInitCrashStrikeVib(GMS_BOSS5_BODY_WORK body_work, uint delay)
	{
		body_work.crash_strike_vib_delay_timer = delay;
		body_work.crash_strike_vib_phase = 0;
		body_work.crash_strike_vib_ratio = 0f;
	}

	private static int gmBoss5BodyUpdateCrashStrikeVib(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		int result = 0;
		if (body_work.crash_strike_vib_delay_timer != 0)
		{
			body_work.crash_strike_vib_delay_timer--;
			return 0;
		}
		body_work.crash_strike_vib_ratio += GMD_BOSS5_BODY_CRASH_STRIKE_BODY_VIB_RATIO_ADD;
		if (body_work.crash_strike_vib_ratio >= 1f)
		{
			body_work.crash_strike_vib_ratio = 1f;
			result = 1;
		}
		int scale = (int)((float)GMD_BOSS5_BODY_CRASH_STRIKE_BODY_VIB_SCALE * (1f - body_work.crash_strike_vib_ratio));
		body_work.crash_strike_vib_phase = GmBoss5UpdateVib(body_work.crash_strike_vib_phase, scale, ref oBS_OBJECT_WORK.ofst.x, ref oBS_OBJECT_WORK.ofst.y);
		return result;
	}

	private static void gmBoss5BodyInitStartRiseVib(GMS_BOSS5_BODY_WORK body_work)
	{
		body_work.start_rise_vib_int_timer = 0u;
	}

	private static void gmBoss5BodyUpdateStartRiseVib(GMS_BOSS5_BODY_WORK body_work)
	{
		if (body_work.start_rise_vib_int_timer != 0)
		{
			body_work.start_rise_vib_int_timer--;
			return;
		}
		float num = FX_FX32_TO_F32(FX_Div(GMM_BS_OBJ(body_work).pos.y - body_work.ground_v_pos, GMD_BOSS5_BODY_START_BURY_HEIGHT));
		GmCameraVibrationSet((int)((float)GMD_BOSS5_BODY_START_RISE_VIB_AMP_MAX * nnSin(AKM_DEGtoA32(180f * num))), 0, 0);
		body_work.start_rise_vib_int_timer = GMD_BOSS5_BODY_START_RISE_VIB_INTERVAL;
	}

	private static void gmBoss5BodyInitArmPose(GMS_BOSS5_BODY_WORK body_work)
	{
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		nnMakeUnitMatrix(nNS_MATRIX);
		for (int i = 0; i < 2; i++)
		{
			for (int j = 0; j < 3; j++)
			{
				GmBsCmnChangeCNMModeNode(body_work.cnm_mgr_work, body_work.arm_cnm_reg_id[i][j], 1u);
				GmBsCmnEnableCNMLocalCoordinate(body_work.cnm_mgr_work, body_work.arm_cnm_reg_id[i][j], 1);
				GmBsCmnEnableCNMMtxNode(body_work.cnm_mgr_work, body_work.arm_cnm_reg_id[i][j], 1);
				GmBsCmnSetCNMMtx(body_work.cnm_mgr_work, nNS_MATRIX, body_work.arm_cnm_reg_id[i][j]);
				nnMakeUnitQuaternion(ref body_work.arm_part_rot_quat[i][j]);
			}
			nnMakeUnitMatrix(body_work.rkt_ofst_mtx[i]);
		}
		body_work.flag |= 16u;
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
	}

	private static void gmBoss5BodyEndArmPose(GMS_BOSS5_BODY_WORK body_work)
	{
		body_work.flag &= 4294967279u;
		for (int i = 0; i < 2; i++)
		{
			for (int j = 0; j < 3; j++)
			{
				GmBsCmnEnableCNMMtxNode(body_work.cnm_mgr_work, body_work.arm_cnm_reg_id[i][j], 0);
			}
		}
	}

	private static void gmBoss5BodySetArmPoseParam(GMS_BOSS5_BODY_WORK body_work, int arm_type, int arm_part_idx, ref NNS_QUATERNION quat)
	{
		body_work.arm_part_rot_quat[arm_type][arm_part_idx] = quat;
	}

	private static void gmBoss5BodyApplyArmPose(GMS_BOSS5_BODY_WORK body_work)
	{
		NNS_MATRIX[][] array = New<NNS_MATRIX>(2, 3);
		for (int i = 0; i < 2; i++)
		{
			for (int j = 0; j < 3; j++)
			{
				nnMakeQuaternionMatrix(array[i][j], ref body_work.arm_part_rot_quat[i][j]);
				GmBsCmnSetCNMMtx(body_work.cnm_mgr_work, array[i][j], body_work.arm_cnm_reg_id[i][j]);
			}
		}
		for (int k = 0; k < 2; k++)
		{
			NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
			NNS_MATRIX nNS_MATRIX2 = GlobalPool<NNS_MATRIX>.Alloc();
			NNS_MATRIX nNS_MATRIX3 = GlobalPool<NNS_MATRIX>.Alloc();
			NNS_MATRIX nNS_MATRIX4 = GlobalPool<NNS_MATRIX>.Alloc();
			NNS_MATRIX nNS_MATRIX5 = GmBsCmnGetSNMMtx(body_work.snm_work, body_work.armpt_snm_reg_ids[k][0]);
			NNS_MATRIX nNS_MATRIX6 = GmBsCmnGetSNMMtx(body_work.snm_work, body_work.armpt_snm_reg_ids[k][1]);
			NNS_MATRIX nNS_MATRIX7 = GmBsCmnGetSNMMtx(body_work.snm_work, body_work.armpt_snm_reg_ids[k][2]);
			nnInvertMatrix(nNS_MATRIX, nNS_MATRIX5);
			nnInvertMatrix(nNS_MATRIX2, nNS_MATRIX6);
			nnInvertMatrix(nNS_MATRIX3, nNS_MATRIX7);
			nnMultiplyMatrix(nNS_MATRIX4, nNS_MATRIX3, nNS_MATRIX5);
			nnMultiplyMatrix(nNS_MATRIX4, nNS_MATRIX4, array[k][0]);
			nnMultiplyMatrix(nNS_MATRIX4, nNS_MATRIX4, nNS_MATRIX);
			nnMultiplyMatrix(nNS_MATRIX4, nNS_MATRIX4, nNS_MATRIX6);
			nnMultiplyMatrix(nNS_MATRIX4, nNS_MATRIX4, array[k][1]);
			nnMultiplyMatrix(nNS_MATRIX4, nNS_MATRIX4, nNS_MATRIX2);
			nnMultiplyMatrix(nNS_MATRIX4, nNS_MATRIX4, nNS_MATRIX7);
			nnMultiplyMatrix(nNS_MATRIX4, nNS_MATRIX4, array[k][2]);
			nnCopyMatrix(body_work.rkt_ofst_mtx[k], nNS_MATRIX4);
			GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
			GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX2);
			GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX3);
			GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX4);
		}
	}

	private static void gmBoss5BodyInitCanopyPartsPose(GMS_BOSS5_BODY_WORK body_work)
	{
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		int[] array = new int[4] { body_work.head_cnm_reg_id, body_work.neck_cnm_reg_id, body_work.cover_cnm_reg_id, body_work.pole_cnm_reg_id };
		int num = array.Length;
		nnMakeUnitMatrix(nNS_MATRIX);
		for (int i = 0; i < num; i++)
		{
			GmBsCmnChangeCNMModeNode(body_work.cnm_mgr_work, array[i], 1u);
			GmBsCmnEnableCNMLocalCoordinate(body_work.cnm_mgr_work, array[i], 1);
			GmBsCmnEnableCNMMtxNode(body_work.cnm_mgr_work, array[i], 1);
			GmBsCmnSetCNMMtx(body_work.cnm_mgr_work, nNS_MATRIX, array[i]);
		}
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
	}

	private static void gmBoss5BodyEndCanopyPartsPose(GMS_BOSS5_BODY_WORK body_work)
	{
		int[] array = new int[4] { body_work.head_cnm_reg_id, body_work.neck_cnm_reg_id, body_work.cover_cnm_reg_id, body_work.pole_cnm_reg_id };
		int num = array.Length;
		for (int i = 0; i < num; i++)
		{
			GmBsCmnEnableCNMMtxNode(body_work.cnm_mgr_work, array[i], 0);
		}
	}

	private static int gmBoss5BodyTryTransitCrashWall(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (body_work.sub_seq == -1)
		{
			if (body_work.state == 3)
			{
				if ((oBS_OBJECT_WORK.move_flag & 4) != 0)
				{
					gmBoss5BodyStartSubsequence(body_work, 0);
					return 1;
				}
			}
			else if (body_work.state == 4 && (oBS_OBJECT_WORK.move_flag & 8) != 0)
			{
				gmBoss5BodyStartSubsequence(body_work, 1);
				return 1;
			}
		}
		return 0;
	}

	private static void gmBoss5BodyResumeMoveFast(GMS_BOSS5_BODY_WORK body_work)
	{
		if (body_work.sub_seq == 0)
		{
			gmBoss5BodyChangeState(body_work, 4, body_work.strat_state, 1);
		}
		else
		{
			gmBoss5BodyChangeState(body_work, 3, body_work.strat_state, 1);
		}
	}

	private static int gmBoss5BodyReceiveSignalRocketReturned(GMS_BOSS5_BODY_WORK body_work)
	{
		if ((body_work.flag & 0x4000000) != 0)
		{
			body_work.flag &= 4227858431u;
			return 1;
		}
		if ((body_work.flag & 0x2000000) != 0)
		{
			body_work.flag &= 4261412863u;
			return 1;
		}
		return 0;
	}

	private static void gmBoss5BodyInitCallbacks(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		GmBsCmnInitBossMotionCBSystem(oBS_OBJECT_WORK, body_work.bmcb_mgr);
		GmBsCmnCreateSNMWork(body_work.snm_work, oBS_OBJECT_WORK.obj_3d._object, (ushort)GMD_BOSS5_BODY_NODE_SNM_NUM);
		GmBsCmnAppendBossMotionCallback(body_work.bmcb_mgr, body_work.snm_work.bmcb_link);
		body_work.body_snm_reg_id = GmBsCmnRegisterSNMNode(body_work.snm_work, GMD_BOSS5_BODY_NODE_IDX_BODY);
		body_work.lfoot_snm_reg_id = GmBsCmnRegisterSNMNode(body_work.snm_work, GMD_BOSS5_BODY_NODE_IDX_FOOT_L);
		body_work.rfoot_snm_reg_id = GmBsCmnRegisterSNMNode(body_work.snm_work, GMD_BOSS5_BODY_NODE_IDX_FOOT_R);
		body_work.leg_snm_reg_ids[0] = GmBsCmnRegisterSNMNode(body_work.snm_work, GMD_BOSS5_BODY_NODE_IDX_LEG_L);
		body_work.leg_snm_reg_ids[1] = GmBsCmnRegisterSNMNode(body_work.snm_work, GMD_BOSS5_BODY_NODE_IDX_LEG_R);
		body_work.pole_snm_reg_id = GmBsCmnRegisterSNMNode(body_work.snm_work, GMD_BOSS5_BODY_NODE_IDX_POLE);
		body_work.groin_snm_reg_ids[0] = GmBsCmnRegisterSNMNode(body_work.snm_work, GMD_BOSS5_BODY_NODE_IDX_GROIN_L);
		body_work.groin_snm_reg_ids[1] = GmBsCmnRegisterSNMNode(body_work.snm_work, GMD_BOSS5_BODY_NODE_IDX_GROIN_R);
		body_work.nozzle_snm_reg_ids[0] = GmBsCmnRegisterSNMNode(body_work.snm_work, GMD_BOSS5_BODY_NODE_IDX_NOZZLE_L);
		body_work.nozzle_snm_reg_ids[1] = GmBsCmnRegisterSNMNode(body_work.snm_work, GMD_BOSS5_BODY_NODE_IDX_NOZZLE_R);
		for (int i = 0; i < 2; i++)
		{
			for (int j = 0; j < 3; j++)
			{
				body_work.armpt_snm_reg_ids[i][j] = GmBsCmnRegisterSNMNode(body_work.snm_work, arm_part_node_ids[i][j]);
			}
		}
		GmBsCmnCreateCNMMgrWork(body_work.cnm_mgr_work, oBS_OBJECT_WORK.obj_3d._object, (ushort)GMD_BOSS5_BODY_NODE_CNM_NUM);
		GmBsCmnInitCNMCb(oBS_OBJECT_WORK, body_work.cnm_mgr_work);
		for (int k = 0; k < 2; k++)
		{
			for (int l = 0; l < 3; l++)
			{
				body_work.arm_cnm_reg_id[k][l] = GmBsCmnRegisterCNMNode(body_work.cnm_mgr_work, arm_part_node_ids[k][l]);
			}
		}
		body_work.head_cnm_reg_id = GmBsCmnRegisterCNMNode(body_work.cnm_mgr_work, GMD_BOSS5_BODY_NODE_IDX_HEAD);
		body_work.neck_cnm_reg_id = GmBsCmnRegisterCNMNode(body_work.cnm_mgr_work, GMD_BOSS5_BODY_NODE_IDX_NECK);
		body_work.cover_cnm_reg_id = GmBsCmnRegisterCNMNode(body_work.cnm_mgr_work, GMD_BOSS5_BODY_NODE_IDX_COVER);
		body_work.pole_cnm_reg_id = GmBsCmnRegisterCNMNode(body_work.cnm_mgr_work, GMD_BOSS5_BODY_NODE_IDX_POLE);
	}

	private static void gmBoss5BodyReleaseCallbacks(GMS_BOSS5_BODY_WORK body_work)
