	{
		for (int i = 0; i < 22; i++)
		{
			body_work.scatter_cnm_reg_ids[i] = GmBsCmnRegisterCNMNode(body_work.cnm_mgr_work, gm_boss5_body_scatter_parts_cnm_node_id_tbl[i]);
		}
	}

	private static void gmBoss5BodyDamageDefFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		OBS_OBJECT_WORK parent_obj = my_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = your_rect.parent_obj;
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)parent_obj;
		int num = 0;
		int num2 = 0;
		if (parent_obj2 != null)
		{
			if (1 == parent_obj2.obj_type)
			{
				num = 1;
			}
			else if (2 == parent_obj2.obj_type)
			{
				GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)parent_obj2;
				if (gMS_ENEMY_COM_WORK.eve_rec.id == 332)
				{
					num2 = 1;
				}
			}
		}
		if (num != 0 || num2 != 0)
		{
			if (num != 0)
			{
				GMS_PLAYER_WORK ply_work = (GMS_PLAYER_WORK)parent_obj2;
				gmBoss5BodySetPlyRebound(ply_work, gMS_BOSS5_BODY_WORK);
				GMM_PAD_VIB_SMALL_TIME(30f);
			}
			else
			{
				gmBoss5BodyStartSubsequence(gMS_BOSS5_BODY_WORK, 2);
				GMM_PAD_VIB_SMALL();
				GmSoundPlaySE("FinalBoss15");
			}
			gmBoss5BodySetNoHitTime(gMS_BOSS5_BODY_WORK);
			GmSoundPlaySE("Boss0_01");
			GmBoss5EfctCreateDamage(gMS_BOSS5_BODY_WORK);
			if ((gMS_BOSS5_BODY_WORK.flag & 1) == 0 || num2 != 0)
			{
				gmBoss5BodyExecDamageRoutine(gMS_BOSS5_BODY_WORK);
			}
		}
	}

	private static void gmBoss5BodyOutFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)obj_work;
		GmBsCmnUpdateCNMParam(obj_work, gMS_BOSS5_BODY_WORK.cnm_mgr_work);
		ObjDrawActionSummary(obj_work);
		gMS_BOSS5_BODY_WORK.grdmv_pivot_pos.Assign(obj_work.pos);
		gMS_BOSS5_BODY_WORK.pivot_prev_pos.Assign(obj_work.pos);
	}

