	{
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)obj_work;
		for (int i = 0; i < 2; i++)
		{
			for (int j = 0; j < 3; j++)
			{
				ObjObjectRectRegist(obj_work, gMS_BOSS5_BODY_WORK.sub_rect_work[i][j]);
			}
		}
	}

	private static void gmBoss5BodyChangeState(GMS_BOSS5_BODY_WORK body_work, int state, int strat_state)
	{
		gmBoss5BodyChangeState(body_work, state, strat_state, 0);
	}

	private static void gmBoss5BodyChangeState(GMS_BOSS5_BODY_WORK body_work, int state, int strat_state, int is_wrapped)
	{
		UNREFERENCED_PARAMETER(is_wrapped);
		MPP_VOID_GMS_BOSS5_BODY_WORK mPP_VOID_GMS_BOSS5_BODY_WORK = gm_boss5_body_state_leave_func_tbl[body_work.state];
		if (mPP_VOID_GMS_BOSS5_BODY_WORK != null)
		{
			mPP_VOID_GMS_BOSS5_BODY_WORK(body_work);
		}
		body_work.prev_state = body_work.state;
		body_work.state = state;
		body_work.sub_seq = -1;
		body_work.strat_state = strat_state;
		GMS_BOSS5_BODY_STATE_ENTER_INFO gMS_BOSS5_BODY_STATE_ENTER_INFO = gm_boss5_body_state_enter_info_tbl[body_work.state];
		if (gMS_BOSS5_BODY_STATE_ENTER_INFO.enter_func != null)
		{
			gMS_BOSS5_BODY_STATE_ENTER_INFO.enter_func(body_work);
		}
	}

