		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		oBS_OBJECT_WORK.move_flag &= 4294967023u;
		oBS_OBJECT_WORK.move_flag |= 128u;
		GmBoss5EfctEndJetSmoke(body_work);
		GmBoss5EfctEndJet(body_work);
		gmBoss5BodyChangeRectSettingDefault(body_work);
	}

