	{
		gmBoss5BodySetActionWhole(body_work, 32);
		gmBoss5BodyChangeRectSettingDefault(body_work);
		body_work.proc_update = gmBoss5BodyStateUpdateRpcWithPrep;
	}

	private static void gmBoss5BodyStateLeaveRpc(GMS_BOSS5_BODY_WORK body_work)
	{
		body_work.flag &= 2281701375u;
		body_work.flag &= 4294967283u;
		gmBoss5BodyChangeRectSettingDefault(body_work);
	}

	private static void gmBoss5BodyStateUpdateRpcWithPrep(GMS_BOSS5_BODY_WORK body_work)
	{
		if (GmBsCmnIsActionEnd(GMM_BS_OBJ(body_work)) != 0)
		{
			body_work.flag |= 4u;
			if (body_work.state == 9)
			{
				GmBoss5RocketLaunchStrong(body_work, 0);
			}
			else
			{
				GmBoss5RocketLaunchNormal(body_work, 0);
			}
			if (body_work.state == 9)
			{
				body_work.wait_timer = gmBoss5BodySeqGetRpcStrSearchTime(body_work);
			}
			else
			{
				body_work.wait_timer = gmBoss5BodySeqGetRpcNmlSearchTime(body_work);
			}
			body_work.proc_update = gmBoss5BodyStateUpdateRpcWithSearch;
		}
	}

	private static void gmBoss5BodyStateUpdateRpcWithSearch(GMS_BOSS5_BODY_WORK body_work)
	{
		if (body_work.wait_timer != 0)
		{
			body_work.wait_timer--;
			return;
		}
		gmBoss5BodySetActionWhole(body_work, 33);
		body_work.proc_update = gmBoss5BodyStateUpdateRpcWithLaunchFirst;
	}

	private static void gmBoss5BodyStateUpdateRpcWithLaunchFirst(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (oBS_OBJECT_WORK.obj_3d.frame[0] >= GMD_BOSS5_BODY_RPUNCH_LAUNCH_TIMING_DELAY)
		{
			body_work.flag |= 268435456u;
			body_work.proc_update = gmBoss5BodyStateUpdateRpcWithWaitReturnFirst;
		}
	}

	private static void gmBoss5BodyStateUpdateRpcWithWaitReturnFirst(GMS_BOSS5_BODY_WORK body_work)
	{
		int num = 0;
		if (GmBsCmnIsActionEnd(GMM_BS_OBJ(body_work)) != 0)
		{
			num = 1;
		}
		if ((body_work.flag & 0x4000000) != 0)
		{
			body_work.flag &= 4227858431u;
			num = 1;
			body_work.flag &= 4294967291u;
			gmBoss5BodySetActionWhole(body_work, 34);
			body_work.proc_update = gmBoss5BodyStateUpdateRpcWithLaunchSecond;
		}
		if (num != 0 && (body_work.flag & 8) == 0)
		{
			body_work.flag |= 8u;
			if (body_work.state == 9)
			{
				GmBoss5RocketLaunchStrong(body_work, 1);
			}
			else
			{
				GmBoss5RocketLaunchNormal(body_work, 1);
			}
		}
	}

	private static void gmBoss5BodyStateUpdateRpcWithLaunchSecond(GMS_BOSS5_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (oBS_OBJECT_WORK.obj_3d.frame[0] >= GMD_BOSS5_BODY_RPUNCH_LAUNCH_TIMING_DELAY)
		{
			body_work.flag |= 134217728u;
			body_work.proc_update = gmBoss5BodyStateUpdateRpcWithWaitReturnSecond;
		}
	}

	private static void gmBoss5BodyStateUpdateRpcWithWaitReturnSecond(GMS_BOSS5_BODY_WORK body_work)
	{
		if ((body_work.flag & 0x2000000) != 0)
		{
			body_work.flag &= 4261412863u;
			body_work.flag &= 4294967287u;
			gmBoss5BodySetActionWhole(body_work, 35);
			body_work.proc_update = gmBoss5BodyStateUpdateRpcWithRecover;
		}
	}

	private static void gmBoss5BodyStateUpdateRpcWithRecover(GMS_BOSS5_BODY_WORK body_work)
	{
		if (GmBsCmnIsActionEnd(GMM_BS_OBJ(body_work)) != 0)
		{
			if (body_work.state == 9)
			{
				gmBoss5BodyProceedToNextSeqStr(body_work);
			}
			else
			{
				gmBoss5BodyProceedToNextSeqNml(body_work);
			}
		}
	}

