		gmBoss5BodySetActionWhole(body_work, 40);
		gmBoss5BodyInitShakeAccelerate(body_work);
		GmBoss5EfctStartPrelimLeakage(body_work);
		body_work.wait_timer = GMD_BOSS5_BODY_BERSERK_SHAKE_STAY_TIME;
