			gmBoss5InitAlarmFade(body_work.mgr_work);
			gmBoss5MgrSetAlarmLevel(body_work.mgr_work, 0);
			GmDecoStartEffectFinalBossLight();
			gmBoss5BodySetActionWhole(body_work, 41);
