			gmBoss5BodyInitBerserkTurn(body_work, 0);
			GmBoss5EfctEndPrelimLeakage(body_work);
			gmBoss5BodyChangeRectSettingDefault(body_work);
			body_work.proc_update = gmBoss5BodyStateUpdateBerserkWithTurnFront;
		}
