		if ((oBS_OBJECT_WORK.move_flag & 1) != 0 && GmBsCmnIsActionEnd(oBS_OBJECT_WORK) != 0)
		{
			gmBoss5BodyResumeMoveFast(body_work);
		}
	}

	private static void gmBoss5BodySubSeqEnterRpcStrDmg(GMS_BOSS5_BODY_WORK body_work)
