	}

	private static void gmBoss5BodySubSeqUpdateRpcStrDmgWithWaitReturn(GMS_BOSS5_BODY_WORK body_work)
	{
		if (gmBoss5BodyReceiveSignalRocketReturned(body_work) != 0)
		{
