		}
	}

	private static void gmBoss5InitAlarmFade(GMS_BOSS5_MGR_WORK mgr_work)
	{
		if ((mgr_work.flag & 0x20) == 0)
		{
			mgr_work.flag |= 32u;
			GMS_BOSS5_ALARM_FADE_WORK gMS_BOSS5_ALARM_FADE_WORK = (GMS_BOSS5_ALARM_FADE_WORK)GmFadeCreateFadeObj(6656, 3, 0, () => new GMS_BOSS5_ALARM_FADE_WORK(), 61439, 0u);
			OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gMS_BOSS5_ALARM_FADE_WORK;
			oBS_OBJECT_WORK.parent_obj = GMM_BS_OBJ(mgr_work);
			gMS_BOSS5_ALARM_FADE_WORK.mgr_work = mgr_work;
			GmFadeSetFade(gMS_BOSS5_ALARM_FADE_WORK.fade_obj, 0u, 0, 0, 0, 0, 0, 0, 0, 0, 1f, 0, 0);
			oBS_OBJECT_WORK.ppFunc = gmBoss5AlarmFadeMain;
			gmBoss5AlarmFadeProcInit(gMS_BOSS5_ALARM_FADE_WORK);
		}
	}

	private static void gmBoss5RequestClearAlarmFade(GMS_BOSS5_MGR_WORK mgr_work)
	{
		mgr_work.flag &= 4294967263u;
	}

	private static void gmBoss5AlarmFadeInitFade(GMS_BOSS5_ALARM_FADE_WORK alarm_fade, int alarm_level)
	{
		alarm_fade.cur_phase = 0;
		alarm_fade.cur_level = alarm_level;
		alarm_fade.wait_timer = 0u;
		gmBoss5AlarmFadeUpdateFade(alarm_fade);
	}

	private static int gmBoss5AlarmFadeUpdateFade(GMS_BOSS5_ALARM_FADE_WORK alarm_fade)
	{
		if (alarm_fade.wait_timer != 0)
		{
			alarm_fade.wait_timer--;
		}
		else
		{
			if (GmFadeIsEnd(alarm_fade.fade_obj) == 0)
			{
				return 0;
			}
			GMS_BOSS5_ALARM_FADE_INFO gMS_BOSS5_ALARM_FADE_INFO = gm_boss5_alarm_fade_info[alarm_fade.cur_level];
			switch (alarm_fade.cur_phase)
			{
			case 0:
				GmFadeSetFade(alarm_fade.fade_obj, 0u, byte.MaxValue, 0, 0, 0, GMD_BOSS5_ALARM_FADE_DEST_RED, GMD_BOSS5_ALARM_FADE_DEST_GREEN, GMD_BOSS5_ALARM_FADE_DEST_BLUE, GMD_BOSS5_ALARM_FADE_DEST_ALPHA, gMS_BOSS5_ALARM_FADE_INFO.fo_frame, 0, 0);
				alarm_fade.cur_phase = 1;
				break;
			case 1:
				alarm_fade.wait_timer = gMS_BOSS5_ALARM_FADE_INFO.on_frame;
				alarm_fade.cur_phase = 2;
				break;
			case 2:
				GmFadeSetFade(alarm_fade.fade_obj, 0u, GMD_BOSS5_ALARM_FADE_DEST_RED, GMD_BOSS5_ALARM_FADE_DEST_GREEN, GMD_BOSS5_ALARM_FADE_DEST_BLUE, GMD_BOSS5_ALARM_FADE_DEST_ALPHA, byte.MaxValue, 0, 0, 0, gMS_BOSS5_ALARM_FADE_INFO.fi_frame, 0, 1);
				alarm_fade.cur_phase = 3;
				break;
			case 3:
				alarm_fade.wait_timer = gMS_BOSS5_ALARM_FADE_INFO.off_frame;
				alarm_fade.cur_phase = 4;
				break;
			case 4:
				return 1;
			default:
				alarm_fade.cur_phase = 0;
				break;
			}
		}
		return 0;
	}

	private static void gmBoss5AlarmFadeInitAlertSe(GMS_BOSS5_ALARM_FADE_WORK alarm_fade)
	{
		GMS_BOSS5_MGR_WORK mgr_work = alarm_fade.mgr_work;
		alarm_fade.alert_se_ref_level = mgr_work.alarm_level;
		GmBoss5Init1ShotTimer(alarm_fade.alert_se_timer, gm_boss5_alarm_se_interval_time_tbl[alarm_fade.alert_se_ref_level]);
		GmSoundPlaySE("FinalBoss10");
	}

	private static void gmBoss5AlarmFadeUpdateAlertSe(GMS_BOSS5_ALARM_FADE_WORK alarm_fade)
	{
		GMS_BOSS5_MGR_WORK mgr_work = alarm_fade.mgr_work;
		if (GmBoss5Update1ShotTimer(alarm_fade.alert_se_timer) != 0 || alarm_fade.alert_se_ref_level != mgr_work.alarm_level)
		{
			GmSoundPlaySE("FinalBoss10");
			alarm_fade.alert_se_ref_level = mgr_work.alarm_level;
			GmBoss5Init1ShotTimer(alarm_fade.alert_se_timer, gm_boss5_alarm_se_interval_time_tbl[alarm_fade.alert_se_ref_level]);
		}
	}

	private static void gmBoss5AlarmFadeMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS5_ALARM_FADE_WORK gMS_BOSS5_ALARM_FADE_WORK = (GMS_BOSS5_ALARM_FADE_WORK)obj_work;
		GMS_BOSS5_MGR_WORK mgr_work = gMS_BOSS5_ALARM_FADE_WORK.mgr_work;
		if ((mgr_work.flag & 0x20) == 0)
		{
			obj_work.flag |= 4u;
		}
		else if (gMS_BOSS5_ALARM_FADE_WORK.proc_update != null)
		{
			gMS_BOSS5_ALARM_FADE_WORK.proc_update(gMS_BOSS5_ALARM_FADE_WORK);
		}
	}

	private static void gmBoss5AlarmFadeProcInit(GMS_BOSS5_ALARM_FADE_WORK alarm_fade)
	{
		GMS_BOSS5_MGR_WORK mgr_work = alarm_fade.mgr_work;
		gmBoss5AlarmFadeInitFade(alarm_fade, mgr_work.alarm_level);
		gmBoss5AlarmFadeInitAlertSe(alarm_fade);
		alarm_fade.proc_update = gmBoss5AlarmFadeProcUpdateLoop;
	}

	private static void gmBoss5AlarmFadeProcUpdateLoop(GMS_BOSS5_ALARM_FADE_WORK alarm_fade)
	{
		GMS_BOSS5_MGR_WORK mgr_work = alarm_fade.mgr_work;
		gmBoss5AlarmFadeUpdateAlertSe(alarm_fade);
		if (gmBoss5AlarmFadeUpdateFade(alarm_fade) != 0)
		{
			gmBoss5AlarmFadeInitFade(alarm_fade, mgr_work.alarm_level);
		}
	}

	private static void gmBoss5InitFlashScreen()
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_BOSS5_FLASH_SCREEN_WORK(), null, 0, "boss5_flash_scr");
		GMS_BOSS5_FLASH_SCREEN_WORK gMS_BOSS5_FLASH_SCREEN_WORK = (GMS_BOSS5_FLASH_SCREEN_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.disp_flag |= 4128u;
		oBS_OBJECT_WORK.flag |= 16u;
		GmBsCmnInitFlashScreen(gMS_BOSS5_FLASH_SCREEN_WORK.flash_work, GMD_BOSS5_FLASH_SCREEN_FADEOUT_TIME, 5f, 30f);
		oBS_OBJECT_WORK.ppFunc = gmBoss5FlashScreenMain;
	}

