	{
		GMS_BOSS5_FLASH_SCREEN_WORK gMS_BOSS5_FLASH_SCREEN_WORK = (GMS_BOSS5_FLASH_SCREEN_WORK)obj_work;
		if (GmBsCmnUpdateFlashScreen(gMS_BOSS5_FLASH_SCREEN_WORK.flash_work) != 0)
		{
			GmBsCmnClearFlashScreen(gMS_BOSS5_FLASH_SCREEN_WORK.flash_work);
