		oBS_OBJECT_WORK.parent_obj = GMM_BS_OBJ(mgr_work);
		GmFadeSetFade(gMS_FADE_OBJ_WORK, 0u, 0, 0, 0, 0, byte.MaxValue, byte.MaxValue, byte.MaxValue, byte.MaxValue, 300f, 0, 0);
