	{
		GMS_FADE_OBJ_WORK gMS_FADE_OBJ_WORK = (GMS_FADE_OBJ_WORK)obj_work;
		GMS_BOSS5_MGR_WORK gMS_BOSS5_MGR_WORK = (GMS_BOSS5_MGR_WORK)obj_work.parent_obj;
		gMS_BOSS5_MGR_WORK.flag |= 2147483648u;
		gMS_FADE_OBJ_WORK.fade_work.draw_state = 0u;
		obj_work.ppFunc = null;
	}

	private static void gmBoss5InitScatter(GMS_BOSS5_BODY_WORK body_work)
	{
		int[] array = new int[6]
		{
			body_work.armpt_snm_reg_ids[0][2],
			body_work.armpt_snm_reg_ids[1][2],
			body_work.groin_snm_reg_ids[0],
			body_work.groin_snm_reg_ids[1],
			body_work.leg_snm_reg_ids[0],
			body_work.leg_snm_reg_ids[1]
		};
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		nnMakeUnitMatrix(nNS_MATRIX);
		for (int i = 0; i < 22; i++)
		{
			GMS_BOSS5_SCT_PART_INFO gMS_BOSS5_SCT_PART_INFO = gm_boss5_scatter_parts_info_tbl[i];
			GmBsCmnChangeCNMModeNode(body_work.cnm_mgr_work, body_work.scatter_cnm_reg_ids[i], (uint)gMS_BOSS5_SCT_PART_INFO.cnm_mode);
			GmBsCmnEnableCNMLocalCoordinate(body_work.cnm_mgr_work, body_work.scatter_cnm_reg_ids[i], gMS_BOSS5_SCT_PART_INFO.is_local_coord);
			GmBsCmnEnableCNMInheritNodeScale(body_work.cnm_mgr_work, body_work.scatter_cnm_reg_ids[i], gMS_BOSS5_SCT_PART_INFO.is_inherit_scale);
			GmBsCmnSetCNMMtx(body_work.cnm_mgr_work, nNS_MATRIX, body_work.scatter_cnm_reg_ids[i], 1);
		}
		for (int j = 0; j < 6; j++)
		{
			GMS_BOSS5_SCT_NDC_INFO gMS_BOSS5_SCT_NDC_INFO = gm_boss5_scatter_ndc_info_tbl[j];
			int part_idx = gMS_BOSS5_SCT_NDC_INFO.part_idx;
			GmBsCmnEnableCNMMtxNode(body_work.cnm_mgr_work, body_work.scatter_cnm_reg_ids[part_idx], 0);
			GMS_BS_CMN_NODE_CTRL_OBJECT gMS_BS_CMN_NODE_CTRL_OBJECT = GmBsCmnCreateNodeControlObjectBySize(GMM_BS_OBJ(body_work), body_work.cnm_mgr_work, body_work.scatter_cnm_reg_ids[part_idx], body_work.snm_work, array[j], () => new GMS_BOSS5_SCT_PART_NDC_WORK());
			GMS_BOSS5_SCT_PART_NDC_WORK sct_part_ndc = (GMS_BOSS5_SCT_PART_NDC_WORK)gMS_BS_CMN_NODE_CTRL_OBJECT;
			gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer = gMS_BOSS5_SCT_NDC_INFO.delay_time;
			gMS_BS_CMN_NODE_CTRL_OBJECT.is_enable = 0;
			gmBoss5ScatterSetPartParam(sct_part_ndc);
			GMM_BS_OBJ(gMS_BS_CMN_NODE_CTRL_OBJECT).move_flag |= 4608u;
			nnMakeUnitQuaternion(ref gMS_BS_CMN_NODE_CTRL_OBJECT.user_quat);
			gMS_BS_CMN_NODE_CTRL_OBJECT.proc_update = gmBoss5ScatterProcWait;
		}
		body_work.flag |= 262144u;
	}

	private static void gmBoss5ScatterSetPartParam(GMS_BOSS5_SCT_PART_NDC_WORK sct_part_ndc)
	{
		nnMakeUnitQuaternion(ref sct_part_ndc.spin_quat);
		for (int i = 0; i < 2; i++)
		{
			NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
			float a = FX_FX32_TO_F32(AkMathRandFx()) * 2f - 1f;
			a = MTM_MATH_CLIP(a, -1f, 1f);
			short rand_angle = AKM_DEGtoA16(360f * FX_FX32_TO_F32(AkMathRandFx()));
			AkMathGetRandomUnitVector(nNS_VECTOR, a, rand_angle);
			NNS_QUATERNION dst;
			nnMakeRotateAxisQuaternion(out dst, nNS_VECTOR.x, nNS_VECTOR.y, nNS_VECTOR.z, GMD_BOSS5_SCT_SPIN_SPD_ANGLE);
			nnMultiplyQuaternion(ref sct_part_ndc.spin_quat, ref dst, ref sct_part_ndc.spin_quat);
			GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		}
	}

	private static void gmBoss5ScatterProcWait(OBS_OBJECT_WORK obj_work)
	{
		GMS_BS_CMN_NODE_CTRL_OBJECT gMS_BS_CMN_NODE_CTRL_OBJECT = (GMS_BS_CMN_NODE_CTRL_OBJECT)obj_work;
		if (gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer != 0)
		{
			gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer--;
			return;
		}
		GmBsCmnAttachNCObjectToSNMNode(gMS_BS_CMN_NODE_CTRL_OBJECT);
		GmBoss5ScatterSetFlyParam(obj_work);
		gMS_BS_CMN_NODE_CTRL_OBJECT.is_enable = 1;
		gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer = 180u;
		GmBoss5EfctCreateSmallExplosion(obj_work.pos.x, obj_work.pos.y, obj_work.pos.z + GMD_BOSS5_EXPL_OFST_Z);
		gMS_BS_CMN_NODE_CTRL_OBJECT.proc_update = gmBoss5ScatterProcFly;
	}

	private static void gmBoss5ScatterProcFly(OBS_OBJECT_WORK obj_work)
	{
		GMS_BS_CMN_NODE_CTRL_OBJECT gMS_BS_CMN_NODE_CTRL_OBJECT = (GMS_BS_CMN_NODE_CTRL_OBJECT)obj_work;
		GMS_BOSS5_SCT_PART_NDC_WORK gMS_BOSS5_SCT_PART_NDC_WORK = (GMS_BOSS5_SCT_PART_NDC_WORK)gMS_BS_CMN_NODE_CTRL_OBJECT;
		nnMultiplyQuaternion(ref gMS_BS_CMN_NODE_CTRL_OBJECT.user_quat, ref gMS_BOSS5_SCT_PART_NDC_WORK.spin_quat, ref gMS_BS_CMN_NODE_CTRL_OBJECT.user_quat);
		GmBsCmnSetWorldMtxFromNCObjectPosture(gMS_BS_CMN_NODE_CTRL_OBJECT);
		if (gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer != 0)
		{
			gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer--;
		}
		else
		{
			obj_work.flag |= 4u;
		}
	}

	private static void gmBoss5BodySeqTryRequestEnableStr(GMS_BOSS5_BODY_WORK body_work)
	{
		if (body_work.mgr_work.life <= GMD_BOSS5_STRONG_MODE_THRESHOLD_LIFE)
		{
			body_work.mgr_work.flag |= 4u;
		}
	}

	private static void gmBoss5BodySeqTryEnableStr(GMS_BOSS5_BODY_WORK body_work)
	{
		if ((body_work.mgr_work.flag & 4) != 0)
		{
			body_work.mgr_work.flag |= 8u;
		}
	}

	private static int gmBoss5BodySeqIsStr(GMS_BOSS5_BODY_WORK body_work)
	{
		if ((body_work.mgr_work.flag & 8) != 0)
		{
			return 1;
		}
		return 0;
	}

	private static int gmBoss5BodySeqIsNearDeath(GMS_BOSS5_BODY_WORK body_work)
	{
		if (body_work.mgr_work.life <= 1)
		{
			return 1;
		}
		return 0;
	}

	private static int gmBoss5BodySeqLotStrat(int strat_branch)
	{
		return gmBoss5BodySeqLotStrat(strat_branch, 0);
	}

	private static int gmBoss5BodySeqLotStrat(int strat_branch, int b_no_rkt)
	{
		GMS_BOSS5_STRAT_PROB_INFO[] array = gm_boss5_body_seq_strat_branch_prob_tbl[strat_branch];
		int num = 0;
		int num2 = 0;
		int num3 = AkMathRandFx();
		if (b_no_rkt != 0)
		{
			int num4 = 4096;
			for (int i = 0; (long)i < 3L; i++)
			{
				if (array[i].is_rkt != 0)
				{
					num4 -= array[i].probability;
					num4 = MTM_MATH_CLIP(num4, 0, 4096);
				}
			}
			num3 = FX_Mul(num3, num4);
			num3 = MTM_MATH_CLIP(num3, 0, num4);
		}
		for (int j = 0; (long)j < 3L; j++)
		{
			int probability = array[j].probability;
			if ((b_no_rkt == 0 || array[j].is_rkt == 0) && probability > 0)
			{
				num = j;
				num2 += probability;
				if (num3 <= num2)
				{
					return array[j].strat_state;
				}
			}
		}
		return array[num].strat_state;
	}

	private static void gmBoss5BodyProceedToNextSeqNml(GMS_BOSS5_BODY_WORK body_work)
	{
		int state = body_work.state;
		int num = 0;
		gmBoss5BodySeqTryEnableStr(body_work);
		if (gmBoss5BodySeqIsStr(body_work) != 0)
		{
			num = 8;
		}
		else
		{
			int b_no_rkt = 0;
			if (gmBoss5BodyIsPlayerBehind(body_work) != 0)
			{
				b_no_rkt = 1;
			}
			switch (body_work.strat_state)
			{
			case 1:
				num = 2;
				break;
			case 2:
			case 3:
			case 4:
				num = 5;
				break;
			case 5:
				num = gmBoss5BodySeqLotStrat(0, b_no_rkt);
				break;
			case 6:
				num = 5;
				break;
			case 7:
				num = gmBoss5BodySeqLotStrat(1, b_no_rkt);
				break;
			}
		}
		state = gm_boss5_body_state_strat_tbl[num];
		gmBoss5BodyChangeState(body_work, state, num, 1);
	}

	private static void gmBoss5BodyProceedToNextSeqStr(GMS_BOSS5_BODY_WORK body_work)
	{
		int state = body_work.state;
		int num = 0;
		if (gmBoss5BodySeqIsNearDeath(body_work) != 0)
		{
			num = 16;
		}
		else
		{
			int num2 = 0;
			if (gmBoss5BodyIsPlayerBehind(body_work) != 0)
			{
				num2 = 1;
			}
			switch (body_work.strat_state)
			{
			case 8:
				num = 9;
				break;
			case 9:
				num = 12;
				break;
			case 10:
			case 13:
				num = ((num2 == 0) ? 15 : 12);
				break;
			case 11:
				num = 12;
				break;
			case 12:
				num = gmBoss5BodySeqLotStrat(2, num2);
				break;
			case 14:
				num = gmBoss5BodySeqLotStrat(3, num2);
				break;
			case 15:
				num = 12;
				break;
			}
		}
		state = gm_boss5_body_state_strat_tbl[num];
		if (state == 3)
		{
			gmBoss5BodySetMoveFastTime(body_work, 360u);
		}
		else
		{
			gmBoss5BodySetMoveFastTime(body_work, 0u);
		}
		gmBoss5BodyChangeState(body_work, state, num, 1);
	}

	private static void gmBoss5BodyProceedToDefeatState(GMS_BOSS5_BODY_WORK body_work)
	{
		gmBoss5BodyChangeState(body_work, 11, 0, 1);
	}

	private static uint gmBoss5BodySeqGetRpcNmlSearchTime(GMS_BOSS5_BODY_WORK body_work)
	{
		UNREFERENCED_PARAMETER(body_work);
		if (AkMathRandFx() < GMD_BOSS5_BODY_SEQ_RPUNCH_NML_FASTSHOT_PROB)
		{
			return GMD_BOSS5_BODY_SEQ_RPUNCH_NML_SEARCH_TIME_SHORT;
		}
		return GMD_BOSS5_BODY_SEQ_RPUNCH_NML_SEARCH_TIME_NORMAL;
	}

	private static uint gmBoss5BodySeqGetRpcStrSearchTime(GMS_BOSS5_BODY_WORK body_work)
	{
		UNREFERENCED_PARAMETER(body_work);
		if (AkMathRandFx() < GMD_BOSS5_BODY_SEQ_RPUNCH_STR_FASTSHOT_PROB)
		{
			return GMD_BOSS5_BODY_SEQ_RPUNCH_STR_SEARCH_TIME_SHORT;
		}
		return GMD_BOSS5_BODY_SEQ_RPUNCH_STR_SEARCH_TIME_NORMAL;
	}

	public static int FX_MUL(int v1, int v2)
	{
		return FX32_CAST((long)v1 * (long)v2 + 2048 >> 12);
	}

	public static int FX_MUL32x64C(int v1, long v2)
	{
		return FX32_CAST(v2 * v1 + 2147483648u >> 32);
	}

	public static float FX_FX32_TO_F32(int x)
	{
		return (float)x / 4096f;
	}

	public static int FX_F32_TO_FX32(double x)
	{
		return (int)((x > 0.0) ? (x * 4096.0 + 0.5) : (x * 4096.0 - 0.5));
	}

	public static int FX_F32_TO_FX32(float x)
	{
		return (int)((x > 0f) ? (x * 4096f + 0.5f) : (x * 4096f - 0.5f));
	}

	public static int FX32_CONST(float x)
	{
		return FX_F32_TO_FX32(x);
	}

	public static float FX_FX64_TO_F32(long x)
	{
		return (float)x / 4096f;
	}

	public static long FX_F32_TO_FX64(float x)
	{
		return (long)((x > 0f) ? (x * 4096f + 0.5f) : (x * 4096f - 0.5f));
	}

	public static long FX64_CONST(float x)
	{
		return FX_F32_TO_FX64(x);
	}

	public static float FX_FX64C_TO_F32(long x)
	{
		return (float)x / 4.2949673E+09f;
	}

	public static long FX_F32_TO_FX64C(float x)
	{
		return (long)((x > 0f) ? (x * 4.2949673E+09f + 0.5f) : (x * 4.2949673E+09f - 0.5f));
	}

	public static long FX64C_CONST(float x)
	{
		return FX_F32_TO_FX64C(x);
	}

	public static float FX_FX16_TO_F32(short x)
	{
		return (float)x / 4096f;
	}

	public static short FX_F32_TO_FX16(float x)
	{
		if (!(x > 0f))
		{
			return (short)(x * 4096f - 0.5f);
		}
		return (short)(x * 4096f + 0.5f);
	}

	public static short FX16_CONST(float x)
	{
		return FX_F32_TO_FX16(x);
	}

	public static float FXM_FX32_TO_FLOAT(int a)
	{
		return (float)a / 4096f;
	}

	public static int FXM_FLOAT_TO_FX32(float a)
	{
		return (int)(a * 4096f);
	}

	public static void VEC_Set(ref VecFx32 a, int x, int y, int z)
	{
		a.x = x;
		a.y = y;
		a.z = z;
	}

	public static int FX32_CAST(long res)
	{
		return (int)res;
	}

	public static int FX_Mul(int v1, int v2)
	{
		return FX32_CAST((long)v1 * (long)v2 + 2048 >> 12);
	}

	public static int FX_Mul32x64c(int v32, long v64c)
	{
		long num = v64c * v32 + 2147483648u;
		return FX32_CAST(num >> 32);
	}

	public static int FX_Div(int numer, int denom)
	{
		return (int)(((long)numer << 32) / denom + 524288 >> 20);
	}

	public static int FX_DivS32(int numer, int denom)
	{
		return numer / denom;
	}

	public static long FX_DivFx64c(int numer, int denom)
	{
		return (int)(((long)numer << 32) / denom);
	}

	public static int FX_Mod(int numer, int denom)
	{
		return (int)(((long)numer << 32) % denom + 524288) >> 20;
	}

	public static int FX_ModS32(int numer, int denom)
	{
		return numer % denom;
	}

	public static int FX_Inv(int denom)
	{
		return FX_Div(4096, denom);
	}

	public static long FX_InvFx64c(int denom)
	{
		return FX_DivFx64c(4096, denom);
	}

	public static int FX_Sqrt(int x)
	{
		float a = nnSqrt(FXM_FX32_TO_FLOAT(x));
		return FXM_FLOAT_TO_FX32(a);
	}

	public static int FX_Sin(int angle)
	{
		float a = nnSin(angle);
		return FXM_FLOAT_TO_FX32(a);
	}

	public static int FX_Cos(int angle)
	{
		float a = nnCos(angle);
		return FXM_FLOAT_TO_FX32(a);
	}

	private void DmTitleStart(object arg)
	{
		dm_title_is_title_start = true;
		short old_evt_id = SyGetEvtInfo().old_evt_id;
		if (dm_title_is_title_start)
		{
			SBackup sBackup = SBackup.CreateInstance();
			sBackup.Init();
		}
		dmTitleInit();
	}

	private void DmMainMenuStart(object arg)
	{
		dm_title_is_title_start = false;
		dmTitleInit();
	}

	private void dmTitleInit()
	{
		GC.Collect();
		AoActSysSetDrawStateEnable(true);
		AoActSysSetDrawState(10u);
		MTS_TASK_TCB mTS_TASK_TCB = MTM_TASK_MAKE_TCB(dmTitleProcMain, dmTitleDest, 0u, 0, 8192u, 10, () => new DMS_TITLE_MAIN_WORK(), "TITLE_MAIN");
		DMS_TITLE_MAIN_WORK dMS_TITLE_MAIN_WORK = (DMS_TITLE_MAIN_WORK)mTS_TASK_TCB.work;
		dmTitleSetInitDispData(dMS_TITLE_MAIN_WORK);
		if (dm_title_is_title_start)
		{
			AoAccountClearCurrentId();
		}
		if (GeEnvGetDecideKey() == GSE_DECIDE_KEY.GSD_DECIDE_KEY_O)
		{
			dMS_TITLE_MAIN_WORK.is_jp_region = true;
		}
		else
		{
			dMS_TITLE_MAIN_WORK.is_jp_region = false;
		}
		dMS_TITLE_MAIN_WORK.proc_update = dmTitleLoadFontData;
	}

	private void dmTitleSetInitDispData(DMS_TITLE_MAIN_WORK main_work)
	{
		short num = 0;
		switch ((GSE_EVT_ID)SyGetEvtInfo().old_evt_id)
		{
		case GSE_EVT_ID.GSD_EVT_ID_MAINGAME:
			main_work.cur_slct_menu = 0;
			break;
		case GSE_EVT_ID.GSD_EVT_ID_MAP:
			main_work.cur_slct_menu = 1;
			break;
		case GSE_EVT_ID.GSD_EVT_ID_OPTION:
			if (!GsMainSysIsStageClear(0) || GsTrialIsTrial())
			{
				main_work.cur_slct_menu = 1;
			}
			else
			{
				main_work.cur_slct_menu = 2;
			}
			break;
		case GSE_EVT_ID.GSD_EVT_ID_STAFFROLL:
			main_work.cur_slct_menu = 1;
			break;
		default:
			main_work.cur_slct_menu = 0;
			break;
		}
		main_work.disp_flag |= 2u;
		if (GsTrialIsTrial())
		{
			main_work.cur_crsr_pos_y = dm_title_crsr_trial_pos_y_tbl[main_work.cur_slct_menu];
		}
		else
		{
			main_work.cur_crsr_pos_y = (float)main_work.cur_slct_menu * dm_title_crsr_pos_y_tbl[1] + dm_title_crsr_pos_y_tbl[0];
		}
	}

	private void dmTitleProcMain(MTS_TASK_TCB tcb)
	{
		DMS_TITLE_MAIN_WORK dMS_TITLE_MAIN_WORK = (DMS_TITLE_MAIN_WORK)tcb.work;
		dMS_TITLE_MAIN_WORK.flag_prev = dMS_TITLE_MAIN_WORK.flag;
		if ((dMS_TITLE_MAIN_WORK.flag & 1) != 0)
		{
			mtTaskClearTcb(tcb);
			dmTitleSetNextEvent(dMS_TITLE_MAIN_WORK);
		}
		if ((dMS_TITLE_MAIN_WORK.flag & 0x80000000u) != 0 && event_after_buy)
		{
			dMS_TITLE_MAIN_WORK.is_init_play = true;
			dMS_TITLE_MAIN_WORK.is_no_save_data = true;
			event_after_buy = false;
			dMS_TITLE_MAIN_WORK.proc_update = dmTitleProcFadeOut;
			dMS_TITLE_MAIN_WORK.flag &= 2147483647u;
			dMS_TITLE_MAIN_WORK.flag |= 1073741824u;
			IzFadeInitEasy(1u, 1u, 32f);
			DmSndBgmPlayerExit();
			dMS_TITLE_MAIN_WORK.flag |= 524288u;
			dMS_TITLE_MAIN_WORK.flag &= 4294967291u;
			dMS_TITLE_MAIN_WORK.flag &= 4294967293u;
			dMS_TITLE_MAIN_WORK.proc_input = null;
			dMS_TITLE_MAIN_WORK.proc_win_input = null;
			dMS_TITLE_MAIN_WORK.win_timer = 0f;
			dMS_TITLE_MAIN_WORK.win_cur_slct = 0;
			dMS_TITLE_MAIN_WORK.win_mode = 0;
		}
		if (dMS_TITLE_MAIN_WORK.proc_win_update != null)
		{
			dMS_TITLE_MAIN_WORK.proc_win_update(dMS_TITLE_MAIN_WORK);
		}
		if (dMS_TITLE_MAIN_WORK.proc_update != null)
		{
			dMS_TITLE_MAIN_WORK.proc_update(dMS_TITLE_MAIN_WORK);
		}
		if (dMS_TITLE_MAIN_WORK.proc_draw != null)
		{
			dMS_TITLE_MAIN_WORK.proc_draw(dMS_TITLE_MAIN_WORK);
		}
	}

	private void dmTitleDest(MTS_TASK_TCB tcb)
	{
	}

	private void dmTitleSetNextEvent(DMS_TITLE_MAIN_WORK main_work)
	{
		short evt_case = 0;
		int num = 0;
		if ((main_work.flag & 0x40000000) != 0)
		{
			evt_case = 5;
			main_work.flag &= 3221225471u;
			SyDecideEvtCase(evt_case);
			SyChangeNextEvt();
			return;
		}
		if ((main_work.flag & 0x100000) != 0)
		{
			evt_case = 4;
			main_work.flag &= 4293918719u;
			SyDecideEvtCase(evt_case);
			SyChangeNextEvt();
			return;
		}
		switch (main_work.cur_slct_menu)
		{
		case 0:
			evt_case = 0;
			dmTitleSetFirstPlayData(main_work);
			nextDemoLevel = 0;
			g_gs_main_sys_info.stage_id = 0;
			g_gs_main_sys_info.char_id[0] = 0;
			g_gs_main_sys_info.game_mode = 0;
			if (GsTrialIsTrial())
			{
				g_gs_main_sys_info.rest_player_num = 3u;
			}
			g_gs_main_sys_info.game_flag &= 4294967167u;
			GmMainGSInit();
			break;
		case 1:
			if (!GsMainSysIsStageClear(0) || main_work.is_init_play)
			{
				evt_case = 0;
				g_gs_main_sys_info.stage_id = 0;
				g_gs_main_sys_info.char_id[0] = 0;
				g_gs_main_sys_info.game_mode = 0;
				g_gs_main_sys_info.game_flag &= 4294967167u;
				GmMainGSInit();
			}
			else
			{
				evt_case = 1;
			}
			break;
		case 2:
			evt_case = 2;
			dm_opt_show_xboxlive = false;
			break;
		case 3:
			evt_case = 2;
			LiveFeature.getInstance().ShowAchievements();
			dm_opt_show_xboxlive = true;
			break;
		case 4:
			evt_case = 2;
			LiveFeature.getInstance().ShowLeaderboards();
			dm_opt_show_xboxlive = true;
			break;
		}
		SyDecideEvtCase(evt_case);
		SyChangeNextEvt();
	}

	private void dmTitleLoadFontData(DMS_TITLE_MAIN_WORK main_work)
	{
		GsFontBuild();
		main_work.proc_update = dmTitleIsLoadFontData;
	}

	private void dmTitleIsLoadFontData(DMS_TITLE_MAIN_WORK main_work)
	{
		if (GsFontIsBuilded())
		{
			main_work.proc_update = dmTitleLoadRequest;
		}
	}

	private void dmTitleLoadRequest(DMS_TITLE_MAIN_WORK main_work)
	{
		main_work.arc_amb_fs[0] = amFsReadBackground("DEMO/TITLE/D_TITLE.AMB");
		main_work.arc_amb_fs[1] = amFsReadBackground(dm_title_file_lng_amb_name_tbl[GsEnvGetLanguage()]);
		for (int i = 0; i < 3; i++)
		{
			main_work.arc_cmn_amb_fs[i] = amFsReadBackground(dm_title_menu_cmn_amb_name_tbl[i]);
		}
		main_work.arc_cmn_amb_fs[3] = amFsReadBackground(dm_title_menu_cmn_lng_amb_name_tbl[GsEnvGetLanguage()]);
		DmTitleOpLoad();
		main_work.proc_update = dmTitleProcLoadWait;
	}

	private void dmTitleProcLoadWait(DMS_TITLE_MAIN_WORK main_work)
	{
		if (!dmTitleIsDataLoad(main_work))
		{
			return;
		}
		for (int i = 0; i < 2; i++)
		{
			main_work.arc_amb[i] = readAMBFile(main_work.arc_amb_fs[i]);
			main_work.ama[i] = readAMAFile(amBindGet(main_work.arc_amb[i], 0));
			if (i == 0)
			{
				main_work.ama[i].act_tbl[0].ofst.top = 50f;
				main_work.ama[i].act_tbl[0].ofst.bottom = -50f;
				main_work.ama[i].act_tbl[1].ofst.top = 50f;
				main_work.ama[i].act_tbl[1].ofst.bottom = -50f;
				main_work.ama[i].act_tbl[1].hit.hit_tbl[0].rect.top = -50f;
				main_work.ama[i].act_tbl[1].hit.hit_tbl[0].rect.bottom = 50f;
				main_work.ama[i].act_tbl[2].ofst.top = 50f;
				main_work.ama[i].act_tbl[2].ofst.bottom = -50f;
			}
			if (i == 1)
			{
				main_work.ama[i].act_num += 2u;
				A2S_AMA_ACT[] array = new A2S_AMA_ACT[main_work.ama[i].act_num];
				Array.Copy(main_work.ama[i].act_tbl, array, (int)(main_work.ama[i].act_num - 2));
				uint num = main_work.ama[i].act_num - 2;
				array[num] = new A2S_AMA_ACT();
				array[num].Assign(array[0]);
				array[num + 1] = new A2S_AMA_ACT();
				array[num + 1].Assign(array[1]);
				array[num].anm.anm_tbl[0].tex_id = 9;
				array[num + 1].anm.anm_tbl[0].tex_id = 10;
				main_work.ama[i].act_tbl = array;
			}
			string sPath;
			main_work.amb[i] = readAMBFile(amBindGet(main_work.arc_amb[i], 1, out sPath));
			main_work.amb[i].dir = sPath;
			amFsClearRequest(main_work.arc_amb_fs[i]);
			main_work.arc_amb_fs[i] = null;
			AoTexBuild(main_work.tex[i], main_work.amb[i]);
			if (i == 1)
			{
				main_work.tex[i].txb.texfilelist.nTex += 2;
				NNS_TEXFILE[] array2 = New<NNS_TEXFILE>(main_work.tex[i].txb.texfilelist.nTex);
				for (int j = 0; j < main_work.tex[i].txb.texfilelist.nTex; j++)
				{
					int num2 = ((j < main_work.tex[i].txb.texfilelist.nTex - 2) ? j : (main_work.tex[i].txb.texfilelist.nTex - 2 - 1));
					array2[j].Bank = main_work.tex[i].txb.texfilelist.pTexFileList[num2].Bank;
					array2[j].fType = main_work.tex[i].txb.texfilelist.pTexFileList[num2].fType;
					array2[j].Filename = main_work.tex[i].txb.texfilelist.pTexFileList[num2].Filename;
					array2[j].MinFilter = main_work.tex[i].txb.texfilelist.pTexFileList[num2].MinFilter;
					array2[j].MagFilter = main_work.tex[i].txb.texfilelist.pTexFileList[num2].MagFilter;
					array2[j].GlobalIndex = main_work.tex[i].txb.texfilelist.pTexFileList[num2].GlobalIndex;
				}
				switch (GsEnvGetLanguage())
				{
				case 0:
					array2[main_work.tex[i].txb.texfilelist.nTex - 2].Filename = "D_TITLE_TEX_TROPHY_JP.PNG";
					array2[main_work.tex[i].txb.texfilelist.nTex - 1].Filename = "D_TITLE_TEX_LB_JP.PNG";
					break;
				case 2:
					array2[main_work.tex[i].txb.texfilelist.nTex - 2].Filename = "D_TITLE_TEX_TROPHY_FR.PNG";
