			main_work.cmn_amb[k].dir = sPath2;
			amFsClearRequest(main_work.arc_cmn_amb_fs[k]);
			main_work.arc_cmn_amb_fs[k] = null;
			AoTexBuild(main_work.cmn_tex[k], main_work.cmn_amb[k]);
			AoTexLoad(main_work.cmn_tex[k]);
		}
		DmTitleOpBuild();
		DmSndBgmPlayerInit();
		main_work.proc_update = dmTitleProcTexBuildWait;
	}

