			{
				a2S_AMA_HEADER = main_work.cmn_ama[0];
				aOS_TEXTURE = main_work.cmn_tex[0];
			}
			else if (i < 19)
			{
				a2S_AMA_HEADER = main_work.ama[0];
				aOS_TEXTURE = main_work.tex[0];
			}
			else
			{
				a2S_AMA_HEADER = main_work.ama[1];
				aOS_TEXTURE = main_work.tex[1];
				switch (i)
