				case 20:
					a2S_AMA_HEADER.act_tbl[dm_title_g_dm_act_id_tbl[i]].mtn.trs_tbl[0].trs_y = 90f;
					break;
				case 21:
					a2S_AMA_HEADER.act_tbl[dm_title_g_dm_act_id_tbl[i]].mtn.trs_tbl[0].trs_y = 200f;
					break;
				case 22:
					a2S_AMA_HEADER.act_tbl[dm_title_g_dm_act_id_tbl[i]].mtn.trs_tbl[0].trs_y = 310f;
					break;
				case 24:
					a2S_AMA_HEADER.act_tbl[dm_title_g_dm_act_id_tbl[i]].mtn.trs_tbl[0].trs_y = 420f;
					break;
				case 25:
					a2S_AMA_HEADER.act_tbl[dm_title_g_dm_act_id_tbl[i]].mtn.trs_tbl[0].trs_y = 530f;
					break;
				}
			}
			AoActSetTexture(AoTexGetTexList(aOS_TEXTURE));
			main_work.act[i] = AoActCreate(a2S_AMA_HEADER, dm_title_g_dm_act_id_tbl[i]);
		}
		int[] array = new int[5] { 1, 4, 7, 10, 13 };
