	}

	private void dmTitleProcMainMenuDecideEfct(DMS_TITLE_MAIN_WORK main_work)
	{
		int num = 0;
		if ((main_work.flag & 0x100) != 0)
		{
			dmTitleSetCtrlFocusChangeEfct(main_work);
			if (dmTitleIsCtrlFocusChangeEfctEnd(main_work))
			{
				main_work.flag &= 4294967039u;
			}
		}
		num = main_work.cur_slct_menu;
		if (main_work.timer > 15f)
		{
			if (num == 4 && (GsTrialIsTrial() || XBOXLive.signinStatus == XBOXLive.SigninStatus.UpdateNeeded || XBOXLive.signinStatus == XBOXLive.SigninStatus.Local))
			{
				for (int i = 0; i < 5; i++)
				{
					main_work.decide_menu_frm[i] = 0f;
				}
				main_work.flag &= 4294967291u;
				main_work.proc_update = dmTitleProcMainMenuIdle;
				main_work.proc_input = dmTitleInputProcMainMenu;
				if (!Guide.IsVisible)
				{
					if (XBOXLive.signinStatus == XBOXLive.SigninStatus.UpdateNeeded)
					{
						XBOXLive.displayTitleUpdateMessage = true;
						return;
					}
					List<string> list = new List<string>();
					list.Add(Strings.ID_OK);
					string text = "";
					text = (GsTrialIsTrial() ? Strings.ID_LB_BUY : ((XBOXLive.signinStatus != XBOXLive.SigninStatus.Local) ? Strings.ID_LB_UPDATE : Strings.ID_LB_OFFLINE));
					g_ao_sys_global.is_show_ui = true;
					Guide.BeginShowMessageBox(" ", text, list, 0, MessageBoxIcon.Alert, TitleMBResult, null);
				}
				return;
			}
			if (num == 0 && SaveState.shouldResume())
			{
				main_work.proc_update = dmTitleProcFadeOut;
			}
			else
			{
				if (num == 0 && !main_work.is_init_play && !GsTrialIsTrial())
				{
					if (dmTitleIsSaveRunning())
					{
						main_work.proc_update = dmTitleProcMainMenuDelSaveWin;
						main_work.announce_flag |= 1u;
						main_work.flag &= 4292869119u;
					}
					else
					{
						main_work.proc_update = dmTitleProcFadeOut;
					}
					return;
				}
				if (GsTrialIsTrial() && num == 1)
				{
					main_work.proc_update = dmTitleProcMainMenuCompBuyFadeOut;
					main_work.proc_input = null;
					main_work.timer = 0f;
					IzFadeInitEasy(0u, 1u, 32f);
					DmSndBgmPlayerBgmStop();
					return;
				}
				main_work.proc_update = dmTitleProcFadeOut;
			}
			main_work.timer = 0f;
			for (int j = 0; j < 5; j++)
			{
				main_work.decide_menu_frm[j] = 0f;
			}
			IzFadeInitEasy(0u, 1u, 32f);
			if (num == 0)
			{
				DmSndBgmPlayerExit();
				main_work.flag |= 524288u;
			}
		}
		else
		{
			main_work.decide_menu_frm[num] += 1f;
			main_work.timer += 1f;
		}
	}

