			main_work.flag &= 4294959103u;
			for (int i = 0; i < 5; i++)
			{
				main_work.decide_menu_frm[i] = 0f;
			}
			main_work.flag |= 2098176u;
		}
		else if ((main_work.flag & 0x4000) != 0)
