	private void dmTitleProcWindowNodispIdle(DMS_TITLE_MAIN_WORK main_work)
	{
		if (main_work.proc_win_input != null)
		{
			main_work.proc_win_input(main_work);
		}
		if (main_work.announce_flag == 0)
		{
			return;
		}
		main_work.proc_win_update = dmTitleProcWindowOpenEfct;
		main_work.proc_input = null;
		main_work.proc_win_input = null;
		main_work.win_timer = 0f;
		for (int i = 0; i < 5; i++)
		{
			if ((main_work.announce_flag & (1 << i)) != 0)
			{
				main_work.win_mode = i;
				break;
			}
		}
		main_work.win_cur_slct = 1;
		DmSoundPlaySE("Window");
		main_work.flag |= 131072u;
	}

	private void dmTitleProcWindowOpenEfct(DMS_TITLE_MAIN_WORK main_work)
	{
		if ((main_work.flag & 0x10000) != 0)
		{
			main_work.proc_win_update = dmTitleProcWindowAnnounceIdle;
			main_work.proc_win_input = dmTitleInputProcWindow;
			main_work.disp_flag |= 1u;
			main_work.flag &= 4294901759u;
		}
		else
		{
			dmTitleSetWinOpenEfct(main_work);
		}
	}

	private void dmTitleProcWindowAnnounceIdle(DMS_TITLE_MAIN_WORK main_work)
	{
		if (main_work.proc_win_input != null)
		{
			main_work.proc_win_input(main_work);
		}
		if (main_work.win_mode == 0)
		{
			if ((main_work.flag & 4) != 0 && main_work.win_cur_slct == 0)
			{
				main_work.proc_input = null;
				main_work.proc_win_input = null;
				main_work.win_timer = 8f;
				main_work.disp_flag &= 4294967294u;
				main_work.proc_win_update = dmTitleProcWindowCloseEfct;
				DmSoundPlaySE("Ok");
				main_work.flag &= 4294967291u;
				main_work.flag &= 4294967293u;
			}
			else if ((main_work.flag & 2) != 0 || (main_work.win_cur_slct == 1 && (main_work.flag & 4) != 0))
			{
				main_work.proc_input = null;
				main_work.proc_win_input = null;
				main_work.win_timer = 8f;
				main_work.disp_flag &= 4294967294u;
				main_work.proc_win_update = dmTitleProcWindowCloseEfct;
				DmSoundPlaySE("Cancel");
				main_work.flag |= 2u;
				main_work.flag &= 4294967291u;
			}
		}
		else if (main_work.win_mode == 1)
		{
			if ((main_work.flag & 4) != 0 && main_work.win_cur_slct == 0)
			{
				main_work.proc_input = null;
				main_work.proc_win_input = null;
				main_work.win_timer = 8f;
				main_work.disp_flag &= 4294967294u;
				main_work.proc_win_update = dmTitleProcWindowCloseEfct;
				DmSoundPlaySE("Ok");
				main_work.flag &= 4294967291u;
				main_work.flag &= 4294967293u;
			}
			else if ((main_work.flag & 2) != 0 || (main_work.win_cur_slct == 1 && (main_work.flag & 4) != 0))
			{
				main_work.proc_input = null;
				main_work.proc_win_input = null;
				main_work.win_timer = 8f;
				main_work.disp_flag &= 4294967294u;
				main_work.proc_win_update = dmTitleProcWindowCloseEfct;
				DmSoundPlaySE("Cancel");
				main_work.flag |= 2u;
				main_work.flag &= 4294967291u;
			}
		}
	}

	private void dmTitleProcWindowCloseEfct(DMS_TITLE_MAIN_WORK main_work)
	{
		if ((main_work.flag & 0x10000) != 0)
		{
			main_work.proc_win_update = dmTitleProcWindowNodispIdle;
			main_work.announce_flag &= (uint)(~(1 << main_work.win_mode));
			if (main_work.win_mode == 0 || main_work.win_mode == 1)
			{
				if ((main_work.flag & 2) != 0)
				{
					main_work.flag |= 8192u;
					main_work.flag &= 4294967293u;
				}
				else if (main_work.win_mode == 0)
				{
					main_work.announce_flag |= 2u;
				}
				else if (main_work.win_mode == 1)
				{
					main_work.flag |= 16384u;
				}
			}
			else if ((main_work.flag & 2) != 0)
			{
				main_work.flag |= 16777216u;
				main_work.flag &= 4294967293u;
			}
			else if (main_work.win_mode == 2)
			{
				main_work.flag |= 8388608u;
			}
			else if (main_work.win_mode == 3)
			{
				main_work.flag |= 33554432u;
			}
			else
			{
				main_work.flag |= 67108864u;
			}
			main_work.flag &= 4294836223u;
			main_work.flag &= 4294901759u;
		}
		dmTitleSetWinCloseEfct(main_work);
	}

	private void dmTitleProcDataRelease(DMS_TITLE_MAIN_WORK main_work)
	{
		if (DmTitleOpExitEndCheck())
		{
			for (int i = 0; i < 2; i++)
			{
				AoTexRelease(main_work.tex[i]);
			}
			for (int j = 0; j < 4; j++)
			{
				AoTexRelease(main_work.cmn_tex[j]);
			}
			DmTitleOpFlush();
			main_work.proc_update = dmTitleProcFinish;
		}
	}

	private void dmTitleProcFinish(DMS_TITLE_MAIN_WORK main_work)
	{
		if (!dmTitleIsTexRelease(main_work))
		{
			return;
		}
		int num = main_work.trg_slct.Length;
		for (int i = 0; i < num; i++)
		{
			main_work.trg_slct[i].Release();
		}
		int num2 = main_work.trg_answer.Length;
		for (int j = 0; j < num2; j++)
		{
			main_work.trg_answer[j].Release();
		}
		main_work.trg_return.Release();
		main_work.trg_game.Release();
		for (int k = 0; k < 41; k++)
		{
			if (main_work.act[k] != null)
			{
				AoActDelete(main_work.act[k]);
				main_work.act[k] = null;
			}
		}
		for (int l = 0; l < 2; l++)
		{
			if (main_work.arc_amb[l] != null)
			{
				main_work.arc_amb[l] = null;
			}
		}
		for (int m = 0; m < 4; m++)
		{
			if (main_work.arc_cmn_amb[m] != null)
			{
				main_work.arc_cmn_amb[m] = null;
			}
		}
		DmTitleOpRelease();
		main_work.proc_update = dmTitleProcWaitFinished;
	}

	private void dmTitleProcWaitFinished(DMS_TITLE_MAIN_WORK main_work)
	{
		if (!DmTitleOpReleaseCheck())
		{
			return;
		}
		if ((main_work.flag & 0x80000) != 0)
		{
			if (!DmSndBgmPlayerIsTaskExit())
			{
				return;
			}
			main_work.flag &= 4294443007u;
		}
		main_work.flag |= 1u;
		main_work.proc_update = null;
	}

