	private void dmTitleInputProcMainMenu(DMS_TITLE_MAIN_WORK main_work)
	{
		int num = main_work.trg_slct.Length;
		if (!LiveFeature.isInterrupted())
		{
			for (int i = 0; i < num; i++)
			{
				CTrgAoAction cTrgAoAction = main_work.trg_slct[i];
				if (cTrgAoAction.GetState(0u)[10] && cTrgAoAction.GetState(0u)[1])
				{
					main_work.cur_slct_menu = i;
					main_work.flag |= 4u;
					break;
				}
			}
		}
		if ((4 & main_work.flag) != 0)
		{
			return;
		}
		CTrgAoAction trg_return = main_work.trg_return;
		if ((trg_return.GetState(0u)[10] && trg_return.GetState(0u)[1]) || isBackKeyPressed())
		{
			setBackKeyRequest(false);
			if (LiveFeature.isInterrupted())
			{
				LiveFeature.endInterrupt();
			}
			else
			{
				main_work.flag |= 2u;
			}
		}
		CTrgAoAction trg_game = main_work.trg_game;
		if (trg_game.GetState(0u)[10] && trg_game.GetState(0u)[1])
		{
			int num2 = GsEnvGetLanguage();
			string url = ((num2 != 0) ? "http://sega.com/apps" : "http://sega.jp/kt/microsoft/smart/");
			DmSoundPlaySE("Ok");
			erWeb.StartWeb(url);
		}
	}

	private void dmTitleInputProcWindow(DMS_TITLE_MAIN_WORK main_work)
	{
		CTrgAoAction[] trg_answer = main_work.trg_answer;
		if ((trg_answer[0].GetState(0u)[10] && trg_answer[0].GetState(0u)[1]) || isBackKeyPressed())
		{
			setBackKeyRequest(false);
			main_work.win_cur_slct = 1;
			main_work.flag |= 4u;
		}
		if (trg_answer[1].GetState(0u)[10] && trg_answer[1].GetState(0u)[1])
		{
			main_work.win_cur_slct = 0;
			main_work.flag |= 4u;
		}
	}

