	private void dmTitleDrawProcTitle(DMS_TITLE_MAIN_WORK main_work)
	{
		AoActSysSetDrawTaskPrio(33792u);
		AoActSetTexture(AoTexGetTexList(main_work.tex[1]));
		if ((main_work.flag & 8) != 0)
		{
			AoActSortRegAction(main_work.act[19]);
		}
		if ((main_work.flag & 0x10) != 0)
		{
			if (main_work.disp_timer >= 4f)
			{
				main_work.disp_timer = 0f;
				main_work.flag ^= 8u;
			}
			else
			{
				main_work.disp_timer += 1f;
			}
		}
		else if (main_work.disp_timer >= (float)main_work.disp_change_time)
		{
			main_work.flag ^= 8u;
			if ((main_work.flag & 8) != 0)
			{
				main_work.disp_change_time = 40;
			}
			else
			{
				main_work.disp_change_time = 30;
			}
			main_work.disp_timer = 0f;
		}
		else
		{
			main_work.disp_timer += 1f;
		}
		if (GeEnvGetDecideKey() == GSE_DECIDE_KEY.GSD_DECIDE_KEY_O)
		{
			AoActSetFrame(main_work.act[19], 0f);
		}
		else
		{
			AoActSetFrame(main_work.act[19], 1f);
		}
		AoActSetTexture(AoTexGetTexList(main_work.tex[1]));
		AoActUpdate(main_work.act[19], 0f);
		AoActSortExecute();
		AoActSortDraw();
		AoActSortUnregAll();
	}

