	private bool dmTitleIsDataLoad(DMS_TITLE_MAIN_WORK main_work)
	{
		for (int i = 0; i < 2; i++)
		{
			if (!amFsIsComplete(main_work.arc_amb_fs[i]))
			{
				return false;
			}
		}
		for (int j = 0; j < 4; j++)
		{
			if (!amFsIsComplete(main_work.arc_cmn_amb_fs[j]))
			{
				return false;
			}
		}
		if (!DmTitleOpLoadCheck())
		{
			return false;
		}
		return true;
	}

	private bool dmTitleIsTexLoad(DMS_TITLE_MAIN_WORK main_work)
	{
		for (int i = 0; i < 2; i++)
		{
			if (!AoTexIsLoaded(main_work.tex[i]))
			{
				return false;
			}
		}
		for (int j = 0; j < 4; j++)
		{
			if (!AoTexIsLoaded(main_work.cmn_tex[j]))
			{
				return false;
			}
		}
		if (!GsFontIsBuilded())
		{
			return false;
		}
		if (!DmTitleOpBuildCheck())
		{
			return false;
		}
		return true;
	}

	private bool dmTitleIsTexRelease(DMS_TITLE_MAIN_WORK main_work)
	{
		for (int i = 0; i < 2; i++)
		{
			if (!AoTexIsReleased(main_work.tex[i]))
			{
				return false;
			}
		}
		for (int j = 0; j < 4; j++)
		{
			if (!AoTexIsReleased(main_work.cmn_tex[j]))
			{
				return false;
			}
		}
		if (!DmTitleOpFlushCheck())
		{
			return false;
		}
		return true;
	}

