			main_work.prev_slct_menu = main_work.cur_slct_menu;
			main_work.cur_slct_menu = dmTitleGetRevisedMenuFocus(main_work.cur_slct_menu, -1, main_work.slct_menu_num);
			main_work.src_crsr_pos_y = main_work.cur_crsr_pos_y;
			if (GsTrialIsTrial())
			{
				main_work.dst_crsr_pos_y = dm_title_crsr_trial_pos_y_tbl[main_work.cur_slct_menu];
			}
			else
			{
				main_work.dst_crsr_pos_y = dm_title_crsr_pos_y_tbl[0] + (float)main_work.cur_slct_menu * dm_title_crsr_pos_y_tbl[1];
			}
