	private bool dmTitleIsCtrlFocusChangeEfctEnd(DMS_TITLE_MAIN_WORK main_work)
	{
		float num = 0f;
		num = main_work.dst_crsr_pos_y - main_work.src_crsr_pos_y;
		if (main_work.cur_crsr_pos_y >= main_work.dst_crsr_pos_y && num >= 0f)
		{
			main_work.cur_crsr_pos_y = main_work.dst_crsr_pos_y;
			main_work.timer = 0f;
			return true;
		}
		if (main_work.cur_crsr_pos_y <= main_work.dst_crsr_pos_y && num <= 0f)
		{
			main_work.cur_crsr_pos_y = main_work.dst_crsr_pos_y;
			main_work.timer = 0f;
			return true;
		}
		main_work.timer += 1f;
		return false;
	}

	private void dmTitleSetLoadSysData(DMS_TITLE_MAIN_WORK main_work)
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		int num = 0;
		int num2 = 0;
		uint num3 = 0u;
		SOption sOption = SOption.CreateInstance();
		num2 = (int)sOption.GetVolumeBgm();
		num = (int)sOption.GetVolumeSe();
		gSS_MAIN_SYS_INFO.bgm_volume = num2 / 10;
		gSS_MAIN_SYS_INFO.se_volume = num / 10;
		DmSoundSetVolumeBGM(gSS_MAIN_SYS_INFO.bgm_volume);
		DmSoundSetVolumeSE(gSS_MAIN_SYS_INFO.se_volume);
		gSS_MAIN_SYS_INFO.game_flag |= 64u;
		SSpecial sSpecial = SSpecial.CreateInstance();
		for (int i = 0; i < 7; i++)
		{
			if (sSpecial[(ushort)i].IsGetEmerald())
			{
				num3 |= (uint)(1 << i);
			}
		}
		if (num3 == 127)
		{
			gSS_MAIN_SYS_INFO.game_flag |= 32u;
		}
		else
		{
			gSS_MAIN_SYS_INFO.game_flag &= 4294967263u;
		}
		SSystem sSystem = SSystem.CreateInstance();
		gSS_MAIN_SYS_INFO.rest_player_num = sSystem.GetPlayerStock();
		gSS_MAIN_SYS_INFO.ene_kill_count = sSystem.GetKilled();
		gSS_MAIN_SYS_INFO.final_clear_count = sSystem.GetClearCount();
		switch (SOption.CreateInstance().GetControl())
		{
		case SOption.EControl.Type.VirtualPadDown:
			gSS_MAIN_SYS_INFO.game_flag &= 4294966783u;
			gSS_MAIN_SYS_INFO.game_flag |= 1u;
			break;
		case SOption.EControl.Type.VirtualPadUp:
			gSS_MAIN_SYS_INFO.game_flag |= 512u;
			gSS_MAIN_SYS_INFO.game_flag |= 1u;
			break;
		default:
			gSS_MAIN_SYS_INFO.game_flag &= 4294966783u;
			gSS_MAIN_SYS_INFO.game_flag &= 4294967294u;
			break;
		}
		gSS_MAIN_SYS_INFO.is_spe_clear = false;
		gSS_MAIN_SYS_INFO.is_first_play = false;
	}

	private void dmTitleSetInitSysData(DMS_TITLE_MAIN_WORK main_work)
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		int num = 0;
		int num2 = 0;
		SOption sOption = SOption.CreateInstance();
		num2 = (int)sOption.GetVolumeBgm();
		num = (int)sOption.GetVolumeSe();
		gSS_MAIN_SYS_INFO.bgm_volume = (float)num2 / 10f;
		gSS_MAIN_SYS_INFO.se_volume = (float)num / 10f;
		DmSoundSetVolumeBGM(gSS_MAIN_SYS_INFO.bgm_volume);
		DmSoundSetVolumeSE(gSS_MAIN_SYS_INFO.se_volume);
		sOption.IsVibration();
		gSS_MAIN_SYS_INFO.game_flag |= 64u;
		gSS_MAIN_SYS_INFO.game_flag &= 4294967263u;
		gSS_MAIN_SYS_INFO.rest_player_num = 3u;
		gSS_MAIN_SYS_INFO.is_spe_clear = false;
		gSS_MAIN_SYS_INFO.is_first_play = false;
	}

	private void dmTitleSetMenuInfo(DMS_TITLE_MAIN_WORK main_work)
	{
		if (GsTrialIsTrial())
		{
			main_work.slct_menu_num = 3;
			main_work.is_init_play = true;
		}
		else if (!GsMainSysIsStageClear(0))
		{
			main_work.slct_menu_num = 3;
			main_work.is_init_play = true;
		}
		else
		{
			main_work.slct_menu_num = 3;
			main_work.is_init_play = false;
		}
	}

	private void dmTitleSetFirstPlayData(DMS_TITLE_MAIN_WORK main_work)
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		SSystem sSystem = SSystem.CreateInstance();
