		sSystem.SetPlayerStock(gSS_MAIN_SYS_INFO.rest_player_num);
		dmTitleSetLoadSysData(main_work);
	}

	private void dmTitleSetInitSaveData(DMS_TITLE_MAIN_WORK main_work)
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		GSS_BACKUP backup = gSS_MAIN_SYS_INFO.backup;
