		dmSndBgmPlayerInit();
	}

	public static void DmSndBgmPlayerExit()
	{
		dm_snd_bgm_player_flag |= 4u;
	}

	public static void DmSndBgmPlayerBgmStop()
	{
		dm_snd_bgm_player_flag |= 8u;
	}

	private static bool DmSndBgmPlayerIsTaskExit()
	{
		if (dm_snd_bgm_player_tcb != null)
		{
			return false;
		}
		return true;
	}

	private static bool DmSndBgmPlayerIsSndSysBuild()
	{
		if (DmSoundBuildCheck())
		{
			return true;
		}
		return false;
	}

	public static void DmSndBgmPlayerPlayBgm(int idx)
	{
		if (dm_snd_bgm_player_tcb == null)
		{
			dmSndBgmPlayerInit();
		}
		switch (idx)
		{
		case 0:
			if ((dm_snd_bgm_player_flag & 0x10) != 0)
			{
				dm_snd_bgm_player_flag |= 128u;
			}
			else if ((dm_snd_bgm_player_flag & 0x20) == 0)
			{
				dm_snd_bgm_player_flag |= 32u;
			}
			break;
		case 1:
			if ((dm_snd_bgm_player_flag & 0x20) != 0)
			{
				dm_snd_bgm_player_flag |= 64u;
			}
			else if ((dm_snd_bgm_player_flag & 0x10) == 0)
			{
				dm_snd_bgm_player_flag |= 16u;
			}
			break;
		}
	}

	private static void dmSndBgmPlayerInit()
	{
		if (dm_snd_bgm_player_tcb == null)
		{
			dm_snd_bgm_player_tcb = MTM_TASK_MAKE_TCB(dmSndBgmPlayerProcMain, dmSndBgmPlayerDest, 0u, 0, 4096u, 0, () => new DMS_SND_BGM_PLAYER_MAIN_WORK(), "DM_SND_BGM_PLAYER_MAIN");
			DMS_SND_BGM_PLAYER_MAIN_WORK dMS_SND_BGM_PLAYER_MAIN_WORK = (DMS_SND_BGM_PLAYER_MAIN_WORK)dm_snd_bgm_player_tcb.work;
			dm_snd_bgm_player_flag = 0u;
			dMS_SND_BGM_PLAYER_MAIN_WORK.proc_update = dmSndBgmPlayerProcInit;
		}
	}

	private static void dmSndBgmPlayerProcMain(MTS_TASK_TCB tcb)
	{
		DMS_SND_BGM_PLAYER_MAIN_WORK dMS_SND_BGM_PLAYER_MAIN_WORK = (DMS_SND_BGM_PLAYER_MAIN_WORK)tcb.work;
		if ((dm_snd_bgm_player_flag & 1) != 0)
		{
			mtTaskClearTcb(tcb);
			dm_snd_bgm_player_flag = 0u;
			dm_snd_bgm_player_tcb = null;
		}
		if (dMS_SND_BGM_PLAYER_MAIN_WORK.proc_update != null)
		{
			dMS_SND_BGM_PLAYER_MAIN_WORK.proc_update(dMS_SND_BGM_PLAYER_MAIN_WORK);
		}
	}

	private static void dmSndBgmPlayerDest(MTS_TASK_TCB tcb)
	{
	}

	private static void dmSndBgmPlayerProcInit(DMS_SND_BGM_PLAYER_MAIN_WORK main_work)
	{
		DmSoundBuild();
		main_work.proc_update = dmSndBgmPlayerProcBuildIdle;
	}

	private static void dmSndBgmPlayerProcBuildIdle(DMS_SND_BGM_PLAYER_MAIN_WORK main_work)
	{
		if (DmSoundBuildCheck())
		{
			DmSoundInit();
			main_work.proc_update = dmSndBgmPlayerProcWaitSetBgm;
			main_work.end_timer = 0;
		}
	}

	private static void dmSndBgmPlayerProcWaitSetBgm(DMS_SND_BGM_PLAYER_MAIN_WORK main_work)
	{
		GsGetMainSysInfo();
		if ((dm_snd_bgm_player_flag & 8) != 0 || (dm_snd_bgm_player_flag & 4) != 0)
		{
			DmSoundStopJingle(24);
			DmSoundStopBGM(24);
			main_work.proc_update = dmSndBgmPlayerProcStopIdle;
		}
		else if ((dm_snd_bgm_player_flag & 0x10) != 0 || (dm_snd_bgm_player_flag & 0x20) != 0)
		{
			if ((dm_snd_bgm_player_flag & 0x10) != 0)
			{
				DmSoundPlayJingle(0, 0);
				dm_snd_bgm_player_flag &= 4294967263u;
			}
			else
			{
				DmSoundPlayMenuBGM(0, 32);
				dm_snd_bgm_player_flag &= 4294967279u;
			}
			main_work.proc_update = dmSndBgmPlayerProcPlayIdle;
			main_work.end_timer = 0;
		}
		else if ((dm_snd_bgm_player_flag & 0x40) != 0)
		{
			DmSoundStopBGM(0);
			main_work.proc_update = dmSndBgmPlayerProcStopIdle;
		}
		else if ((dm_snd_bgm_player_flag & 0x80) != 0)
		{
			DmSoundStopJingle(24);
			main_work.proc_update = dmSndBgmPlayerProcStopIdle;
		}
	}

	private static void dmSndBgmPlayerProcPlayIdle(DMS_SND_BGM_PLAYER_MAIN_WORK main_work)
	{
		if ((dm_snd_bgm_player_flag & 8) != 0 || (dm_snd_bgm_player_flag & 4) != 0)
		{
			DmSoundStopJingle(24);
			DmSoundStopBGM(24);
			main_work.proc_update = dmSndBgmPlayerProcStopIdle;
		}
		else if ((dm_snd_bgm_player_flag & 0x40) != 0)
		{
			DmSoundStopBGM(0);
			main_work.proc_update = dmSndBgmPlayerProcStopIdle;
		}
		else if ((dm_snd_bgm_player_flag & 0x80) != 0)
		{
			DmSoundStopJingle(24);
			main_work.proc_update = dmSndBgmPlayerProcStopIdle;
		}
	}

	private static void dmSndBgmPlayerProcStopIdle(DMS_SND_BGM_PLAYER_MAIN_WORK main_work)
	{
		if (!DmSoundIsStopStageBGM() || !DmSoundIsStopJingle())
		{
			return;
		}
		if ((dm_snd_bgm_player_flag & 4) != 0)
		{
			dm_snd_bgm_player_flag &= 4294967291u;
			main_work.proc_update = dmSndBgmPlayerProcSndRelease;
			return;
		}
		if ((dm_snd_bgm_player_flag & 0x40) != 0)
		{
			dm_snd_bgm_player_flag |= 16u;
			dm_snd_bgm_player_flag &= 4294967231u;
		}
		else if ((dm_snd_bgm_player_flag & 0x40) == 0 && (dm_snd_bgm_player_flag & 0x80) == 0 && (dm_snd_bgm_player_flag & 8) == 0)
		{
			dm_snd_bgm_player_flag |= 16u;
		}
		else if ((dm_snd_bgm_player_flag & 8) != 0)
		{
			dm_snd_bgm_player_flag &= 4294967279u;
			dm_snd_bgm_player_flag &= 4294967263u;
			dm_snd_bgm_player_flag &= 4294967287u;
		}
		else
		{
			dm_snd_bgm_player_flag |= 32u;
			dm_snd_bgm_player_flag &= 4294967167u;
		}
		main_work.proc_update = dmSndBgmPlayerProcWaitSetBgm;
	}

	private static void dmSndBgmPlayerProcSndRelease(DMS_SND_BGM_PLAYER_MAIN_WORK main_work)
	{
		DmSoundExit();
		DmSoundFlush();
		main_work.proc_update = dmSndBgmPlayerProcSndFinish;
	}

	private static void dmSndBgmPlayerProcSndFinish(DMS_SND_BGM_PLAYER_MAIN_WORK main_work)
	{
		main_work.proc_update = null;
		dm_snd_bgm_player_flag |= 1u;
	}

	private static void DmOptionStart(object arg)
	{
		short num = 0;
		dm_opt_mgr.Clear();
		dm_opt_mgr_p = dm_opt_mgr;
		dm_opt_win_tex.Clear();
		num = SyGetEvtInfo().cur_evt_id;
		if (num == 6 || num == 11)
		{
			dm_opt_is_pause_maingame = true;
			mtTaskStartPause(2);
		}
		else
		{
			dm_opt_is_pause_maingame = false;
		}
		dm_xbox_show_progress = 0;
		dmOptInit();
	}

	private static bool DmOptionIsExit()
	{
		if (dm_opt_mgr_p != null)
		{
			if (dm_opt_mgr_p.tcb == null)
			{
				return true;
			}
			return false;
		}
		return true;
	}

	private static void dmOptInit()
	{
		dm_opt_mgr_p.tcb = MTM_TASK_MAKE_TCB(dmOptProcMain, dmOptDest, 0u, 32767, 8192u, 10, () => new DMS_OPT_MAIN_WORK(), "OPT_MAIN");
		DMS_OPT_MAIN_WORK dMS_OPT_MAIN_WORK = (DMS_OPT_MAIN_WORK)dm_opt_mgr_p.tcb.work;
		if (dm_opt_is_pause_maingame)
		{
			dMS_OPT_MAIN_WORK.draw_state = (AoActSysGetDrawStateEnable() ? 1u : 0u);
			if (dMS_OPT_MAIN_WORK.draw_state != 0)
			{
				dm_opt_draw_state = AoActSysGetDrawState();
			}
		}
		else
		{
			dMS_OPT_MAIN_WORK.draw_state = 1u;
			dm_opt_draw_state = 0u;
		}
		AoActSysSetDrawStateEnable(dMS_OPT_MAIN_WORK.draw_state != 0);
		if (dMS_OPT_MAIN_WORK.draw_state != 0)
		{
			dm_opt_draw_state = AoActSysGetDrawState();
		}
		dmOptSetInitDispOptionData(dMS_OPT_MAIN_WORK);
		dMS_OPT_MAIN_WORK.proc_update = dmOptLoadFontData;
	}

	private static void dmOptSetSaveOptionData(DMS_OPT_MAIN_WORK main_work)
	{
		int num = 0;
		int num2 = 0;
		SOption sOption = SOption.CreateInstance();
		num = (int)sOption.GetVolumeBgm();
		num2 = (int)sOption.GetVolumeSe();
		if (num != 0)
		{
			main_work.volume_data[0] = num / 10;
		}
		else
		{
			main_work.volume_data[0] = 0;
		}
		if (num2 != 0)
		{
			main_work.volume_data[1] = num2 / 10;
		}
		else
		{
			main_work.volume_data[1] = 0;
		}
		sOption.SetVolumeBgm((uint)(main_work.volume_data[0] * 10));
		sOption.SetVolumeSe((uint)(main_work.volume_data[1] * 10));
	}

	private static void dmOptSetInitDispOptionData(DMS_OPT_MAIN_WORK main_work)
	{
		if (GeEnvGetDecideKey() == GSE_DECIDE_KEY.GSD_DECIDE_KEY_O)
		{
			main_work.is_jp_region = true;
		}
		else
		{
			main_work.is_jp_region = false;
		}
		main_work.vol_icon_col.r = byte.MaxValue;
		main_work.vol_icon_col.g = byte.MaxValue;
		main_work.vol_icon_col.b = 0;
		main_work.vol_icon_col.a = byte.MaxValue;
		main_work.win_col.r = 0;
		main_work.win_col.g = 0;
		main_work.win_col.b = 0;
		main_work.win_col.a = byte.MaxValue;
		main_work.win_size_rate[0] = 0f;
		main_work.win_size_rate[1] = 0f;
		main_work.ctrl_tab_pos_x[0] = dm_opt_ctrl_nrml_disp_pos_tbl[main_work.ctrl_mode][0];
		main_work.ctrl_tab_pos_y[0] = dm_opt_ctrl_nrml_disp_pos_tbl[main_work.ctrl_mode][1];
		main_work.ctrl_tab_pos_x[1] = dm_opt_ctrl_clsc_disp_pos_tbl[main_work.ctrl_mode][0];
		main_work.ctrl_tab_pos_y[1] = dm_opt_ctrl_clsc_disp_pos_tbl[main_work.ctrl_mode][1];
		main_work.decide_menu_col.r = byte.MaxValue;
		main_work.decide_menu_col.g = byte.MaxValue;
		main_work.decide_menu_col.b = byte.MaxValue;
		main_work.decide_menu_col.a = 0;
		main_work.prev_nrml_disp_type = 2;
		main_work.top_crsr_pos_y = 250f;
		main_work.frm_update_time = 1f;
		main_work.obi_tex_pos[0] = 0f;
		main_work.obi_tex_pos[1] = 1120f;
	}

	private static void dmOptProcMain(MTS_TASK_TCB tcb)
	{
		DMS_OPT_MAIN_WORK dMS_OPT_MAIN_WORK = (DMS_OPT_MAIN_WORK)tcb.work;
		if ((dMS_OPT_MAIN_WORK.flag & 1) != 0)
		{
			mtTaskClearTcb(tcb);
			dm_opt_mgr_p = null;
			if (dm_opt_is_pause_maingame)
			{
				mtTaskEndPause();
			}
			dmOptSetNextEvt(dMS_OPT_MAIN_WORK);
		}
		if ((dMS_OPT_MAIN_WORK.flag & 0x80000000u) != 0 && !AoAccountIsCurrentEnable())
		{
			dMS_OPT_MAIN_WORK.proc_update = dmOptProcFadeOut;
			dMS_OPT_MAIN_WORK.flag &= 2147483647u;
			dMS_OPT_MAIN_WORK.next_evt = 1;
			if (dm_opt_is_pause_maingame)
			{
				IzFadeInitEasyColor(0, 32767, 61439, 18u, 1u, 1u, 32f, true);
			}
			else
			{
				IzFadeInitEasy(1u, 1u, 32f);
			}
			DmSndBgmPlayerExit();
			dMS_OPT_MAIN_WORK.flag |= 1048576u;
			dMS_OPT_MAIN_WORK.flag &= 4294967291u;
			dMS_OPT_MAIN_WORK.flag &= 4294967293u;
			dMS_OPT_MAIN_WORK.proc_input = null;
			dMS_OPT_MAIN_WORK.win_timer = 0f;
		}
		if (dMS_OPT_MAIN_WORK.proc_update != null)
		{
			dMS_OPT_MAIN_WORK.proc_update(dMS_OPT_MAIN_WORK);
		}
		if (dMS_OPT_MAIN_WORK.proc_draw != null)
		{
			dMS_OPT_MAIN_WORK.proc_draw(dMS_OPT_MAIN_WORK);
		}
	}

	private static void dmOptDest(MTS_TASK_TCB tcb)
	{
	}

	private static void dmOptSetNextEvt(DMS_OPT_MAIN_WORK main_work)
	{
		short num = 0;
		if ((main_work.flag & 0x80000) != 0)
		{
			num = 10;
			dm_opt_prev_evt = SyGetEvtInfo().old_evt_id;
			main_work.flag &= 4294443007u;
		}
		else
		{
			num = SyGetEvtInfo().old_evt_id;
			if (num == 10)
			{
				num = dm_opt_prev_evt;
			}
		}
		if (num == 3)
		{
			num = 4;
		}
		if (main_work.next_evt == 1)
		{
			num = 3;
		}
		if (!dm_opt_is_pause_maingame)
		{
			SyDecideEvt(num);
			SyChangeNextEvt();
		}
	}

	private static void dmOptLoadFontData(DMS_OPT_MAIN_WORK main_work)
	{
		GsFontBuild();
		main_work.proc_update = dmOptIsLoadFontData;
	}

	private static void dmOptIsLoadFontData(DMS_OPT_MAIN_WORK main_work)
	{
		if (GsFontIsBuilded())
		{
			main_work.proc_update = dmOptLoadRequest;
		}
	}

	private static void dmOptLoadRequest(DMS_OPT_MAIN_WORK main_work)
	{
		main_work.arc_amb_fs[0] = amFsReadBackground("DEMO/OPTION/D_OPTION.AMB");
		main_work.arc_amb_fs[1] = amFsReadBackground(dm_opt_main_lng_amb_name_tbl[GsEnvGetLanguage()]);
		for (int i = 0; i < 4; i++)
		{
			main_work.arc_cmn_amb_fs[i] = amFsReadBackground(dm_opt_menu_cmn_amb_name_tbl[i]);
		}
		main_work.arc_cmn_amb_fs[4] = amFsReadBackground(dm_opt_menu_cmn_lng_amb_name_tbl[GsEnvGetLanguage()]);
		main_work.manual_arc_amb_fs[0] = amFsReadBackground("DEMO/MANUAL/D_MANUAL.AMB");
		main_work.manual_arc_amb_fs[1] = amFsReadBackground(dm_opt_manual_file_lng_amb_name_tbl[GsEnvGetLanguage()]);
		main_work.proc_update = dmOptProcLoadWait;
	}

	private static void dmOptProcLoadWait(DMS_OPT_MAIN_WORK main_work)
	{
		if (dmOptIsDataLoad(main_work) > 0)
		{
			for (int i = 0; i < 2; i++)
			{
				main_work.arc_amb[i] = readAMBFile(main_work.arc_amb_fs[i]);
				main_work.ama[i] = readAMAFile(amBindGet(main_work.arc_amb[i], 0));
				string sPath;
				main_work.amb[i] = readAMBFile(amBindGet(main_work.arc_amb[i], 1, out sPath));
				main_work.amb[i].dir = sPath;
				amFsClearRequest(main_work.arc_amb_fs[i]);
				main_work.arc_amb_fs[i] = null;
				AoTexBuild(main_work.tex[i], main_work.amb[i]);
				AoTexLoad(main_work.tex[i]);
			}
			for (int j = 0; j < 5; j++)
			{
				main_work.arc_cmn_amb[j] = readAMBFile(main_work.arc_cmn_amb_fs[j]);
				main_work.cmn_ama[j] = readAMAFile(amBindGet(main_work.arc_cmn_amb[j], 0));
				string sPath2;
				main_work.cmn_amb[j] = readAMBFile(amBindGet(main_work.arc_cmn_amb[j], 1, out sPath2));
				main_work.cmn_amb[j].dir = sPath2;
				amFsClearRequest(main_work.arc_cmn_amb_fs[j]);
				main_work.arc_cmn_amb_fs[j] = null;
				AoTexBuild(main_work.cmn_tex[j], main_work.cmn_amb[j]);
				AoTexLoad(main_work.cmn_tex[j]);
			}
			if (!dm_opt_is_pause_maingame)
			{
				GsFontBuild();
				DmSndBgmPlayerInit();
			}
			main_work.proc_update = dmOptProcLoadWait2;
		}
	}

	private static void dmOptProcLoadWait2(DMS_OPT_MAIN_WORK main_work)
	{
		if (dmOptIsTexLoad(main_work) == 1)
		{
			for (int i = 0; i < 2; i++)
			{
				main_work.manual_arc_amb[i] = readAMBFile(main_work.manual_arc_amb_fs[i]);
				amFsClearRequest(main_work.manual_arc_amb_fs[i]);
				main_work.manual_arc_amb_fs[i] = null;
			}
			DmManualBuild(main_work.manual_arc_amb);
			main_work.proc_update = dmOptProcTexBuildWait;
		}
	}

	private static void dmOptProcTexBuildWait(DMS_OPT_MAIN_WORK main_work)
	{
		if (dmOptIsTexLoad2(main_work) == 1)
		{
			main_work.proc_update = dmOptProcCheckLoadingEnd;
			if (dm_opt_is_pause_maingame)
			{
				main_work.bgm_scb = GsSoundAssignScb(0);
				main_work.bgm_scb.flag |= 2147483648u;
				main_work.se_handle = GsSoundAllocSeHandle();
			}
		}
	}

	private static void dmOptProcCheckLoadingEnd(DMS_OPT_MAIN_WORK main_work)
	{
		main_work.proc_update = dmOptProcCreateAct;
		if (dm_opt_is_pause_maingame)
		{
			IzFadeInitEasyColor(0, 32767, 61439, 18u, 0u, 0u, 32f, true);
		}
		else
		{
			IzFadeInitEasy(0u, 0u, 32f);
		}
	}

