			{
				AoActSetFrame(main_work.act[55], 0f);
			}
		}
		AoActSetTexture(AoTexGetTexList(main_work.tex[1]));
		for (int j = 88; j <= 96; j++)
		{
			if (j == 92)
			{
				if ((g_gs_main_sys_info.game_flag & 0x20) != 0 && main_work.act[j] != null)
				{
					AoActSortRegAction(main_work.act[j]);
				}
			}
			else if (main_work.act[j] != null)
			{
				AoActSortRegAction(main_work.act[j]);
			}
		}
