	private static void dmOptSetTopMenuDecideEfctData(DMS_OPT_MAIN_WORK main_work)
	{
		main_work.flag |= 16u;
	}

	private static void dmOptSetTopMenuTabDecideEfct(DMS_OPT_MAIN_WORK main_work)
	{
		float num = 0f;
		float num2 = 0f;
		num2 = (int)main_work.decide_menu_col.a;
		if (main_work.timer <= 8f)
		{
			num = 31.875f;
			num2 += num;
			if (num2 >= 255f)
			{
				num2 = 255f;
			}
		}
		else if (main_work.timer <= 16f)
		{
			num = 31.875f;
			num2 -= num;
			if (num2 < 0f)
			{
				num2 = 0f;
			}
		}
		main_work.decide_menu_col.a = (byte)num2;
	}

	private static bool dmOptIsTopMenuTabDecideEfctEnd(DMS_OPT_MAIN_WORK main_work)
	{
		if (main_work.timer > 28f)
		{
			main_work.flag &= 4294967279u;
			main_work.decide_menu_col.a = 0;
			main_work.timer = 0f;
			return true;
		}
		return false;
	}

	private static void dmOptSetCtrlFocusChangeEfct(DMS_OPT_MAIN_WORK main_work)
	{
		float num = 0f;
		float num2 = 0f;
		num2 = main_work.dst_crsr_pos_y - main_work.src_crsr_pos_y;
		num = num2 / 8f;
		main_work.top_crsr_pos_y += num;
	}

	private static bool dmOptIsCtrlFocusChangeEfctEnd(DMS_OPT_MAIN_WORK main_work)
	{
		float num = 0f;
		num = main_work.dst_crsr_pos_y - main_work.src_crsr_pos_y;
		if (main_work.top_crsr_pos_y >= main_work.dst_crsr_pos_y && num >= 0f)
		{
			main_work.top_crsr_pos_y = main_work.dst_crsr_pos_y;
			return true;
		}
		if (main_work.top_crsr_pos_y <= main_work.dst_crsr_pos_y && num <= 0f)
		{
			main_work.top_crsr_pos_y = main_work.dst_crsr_pos_y;
			return true;
		}
		return false;
	}

	private static void dmOptSetVolPushEfct(DMS_OPT_MAIN_WORK main_work)
	{
		for (int i = 0; i < 4; i++)
		{
			if (main_work.push_efct_timer[i] > 0f)
			{
				main_work.push_efct_timer[i] -= 1f;
			}
			else
			{
				main_work.push_efct_timer[i] = 0f;
			}
		}
	}

	private static void dmOptSetDfltPushEfct(DMS_OPT_MAIN_WORK main_work)
	{
		if (main_work.efct_timer > 10f)
		{
			main_work.flag &= 4294966271u;
			main_work.efct_timer = 0f;
		}
		main_work.efct_timer += 1f;
	}

	private static void dmOptSetWinOpenEfct(DMS_OPT_MAIN_WORK main_work)
	{
		if (main_work.win_timer > 8f)
		{
			main_work.flag |= 2048u;
			main_work.win_timer = 0f;
			for (uint num = 0u; num < 2; num++)
			{
				main_work.win_size_rate[num] = 1f;
			}
		}
		else
		{
			main_work.win_timer += 1f;
		}
		for (uint num2 = 0u; num2 < 2; num2++)
		{
			if (main_work.win_timer != 0f)
			{
				main_work.win_size_rate[num2] = main_work.win_timer / 8f;
			}
			else
			{
				main_work.win_size_rate[num2] = 1f;
			}
			if (main_work.win_size_rate[num2] > 1f)
			{
				main_work.win_size_rate[num2] = 1f;
			}
		}
	}

	private static void dmOptSetWinCloseEfct(DMS_OPT_MAIN_WORK main_work)
	{
		for (uint num = 0u; num < 2; num++)
		{
			if (main_work.win_timer > 0f)
			{
				main_work.win_size_rate[num] = main_work.win_timer / 8f;
			}
			else
			{
				main_work.win_size_rate[num] = 0f;
			}
			if (main_work.win_size_rate[num] < 0f)
			{
				main_work.win_size_rate[num] = 0f;
			}
		}
		if (main_work.win_timer < 0f)
		{
			main_work.flag |= 2048u;
			main_work.win_timer = 0f;
			for (uint num2 = 0u; num2 < 2; num2++)
			{
				main_work.win_size_rate[num2] = 0f;
			}
		}
		else
		{
			main_work.win_timer -= 1f;
		}
	}

	private static void dmOptSetChngFocusCrsrData(DMS_OPT_MAIN_WORK main_work)
	{
		main_work.src_crsr_pos_y = main_work.top_crsr_pos_y;
		main_work.dst_crsr_pos_y = 250f + (float)main_work.cur_slct_top * 220f;
		main_work.flag |= 262144u;
	}

	private static int dmOptIsDataLoad(DMS_OPT_MAIN_WORK main_work)
	{
		for (int i = 0; i < 2; i++)
		{
			if (!amFsIsComplete(main_work.arc_amb_fs[i]))
			{
				return 0;
			}
		}
		for (int j = 0; j < 5; j++)
		{
			if (!amFsIsComplete(main_work.arc_cmn_amb_fs[j]))
			{
				return 0;
			}
		}
		for (int k = 0; k < 2; k++)
		{
			if (!amFsIsComplete(main_work.manual_arc_amb_fs[k]))
			{
				return 0;
			}
		}
		return 1;
	}

	private static int dmOptIsTexLoad(DMS_OPT_MAIN_WORK main_work)
	{
		for (int i = 0; i < 2; i++)
		{
			if (!AoTexIsLoaded(main_work.tex[i]))
			{
				return 0;
			}
		}
		for (int j = 0; j < 5; j++)
		{
			if (!AoTexIsLoaded(main_work.cmn_tex[j]))
			{
				return 0;
			}
		}
		if (!GsFontIsBuilded())
		{
			return 0;
		}
		if (!dm_opt_is_pause_maingame && !DmSndBgmPlayerIsSndSysBuild())
		{
			return 0;
		}
		return 1;
	}

	private static int dmOptIsTexLoad2(DMS_OPT_MAIN_WORK main_work)
	{
		if (!DmManualBuildCheck())
		{
			return 0;
		}
		return 1;
	}

	private static int dmOptIsTexRelease(DMS_OPT_MAIN_WORK main_work)
	{
		for (int i = 0; i < 2; i++)
		{
			if (!AoTexIsReleased(main_work.tex[i]))
			{
				return 0;
			}
		}
		for (int j = 0; j < 5; j++)
		{
			if (!AoTexIsReleased(main_work.cmn_tex[j]))
			{
				return 0;
			}
		}
		if (!DmManualFlushCheck())
		{
			return 0;
		}
		return 1;
	}

