		{
			num = (uint)(stage_id - 21);
			SSpecial sSpecial = SSpecial.CreateInstance();
			if (sSpecial[(int)num].GetHighScore() != 1000000000 && sSpecial[(int)num].IsGetEmerald())
			{
				return true;
