	private static void GmStartDemoBuild()
	{
		gmStartDemoDataInit();
		GMS_START_DEMO_DATA gMS_START_DEMO_DATA = gmStartDemoDataGetInfo();
		for (int i = 0; 2 > i; i++)
		{
			int num = GsEnvGetLanguage();
			gMS_START_DEMO_DATA.demo_amb[i] = ObjDataLoadAmbIndex(null, g_gm_start_demo_data_amb_id[num][i], GmGameDatGetCockpitData());
		}
		gMS_START_DEMO_DATA.flag_regist = false;
	}

	private static bool GmStartDemoBuildCheck()
	{
		GMS_START_DEMO_DATA gMS_START_DEMO_DATA = gmStartDemoDataGetInfo();
		if (!gMS_START_DEMO_DATA.flag_regist)
		{
			if (GsMainSysGetDisplayListRegistNum() >= 192)
			{
				return false;
			}
			for (int i = 0; 2 > i; i++)
			{
				AoTexBuild(gMS_START_DEMO_DATA.aos_texture[i], (AMS_AMB_HEADER)gMS_START_DEMO_DATA.demo_amb[i]);
				AoTexLoad(gMS_START_DEMO_DATA.aos_texture[i]);
			}
			gMS_START_DEMO_DATA.flag_regist = true;
		}
		return gmStartDemoDataCheckLoading();
	}

	private static void GmStartDemoFlush()
	{
		GMS_START_DEMO_DATA gMS_START_DEMO_DATA = gmStartDemoDataGetInfo();
		for (int i = 0; 2 > i; i++)
		{
			AoTexRelease(gMS_START_DEMO_DATA.aos_texture[i]);
		}
	}

	private static bool GmStartDemoFlushCheck()
	{
		if (!gmStartDemoDataCheckRelease())
		{
			return false;
		}
		gmStartDemoDataFlush();
		return true;
	}

