	private static void gmStartDemoInit()
	{
		g_start_demo_mgr_real.Clear();
		g_start_demo_mgr = g_start_demo_mgr_real;
		g_start_demo_mgr.main_tcb = MTM_TASK_MAKE_TCB(gmStartDemoProcMain, null, 0u, 0, 18448u, 5, () => new GMS_START_DEMO_WORK(), "START_DEMO_MAIN");
		GMS_START_DEMO_WORK gMS_START_DEMO_WORK = (GMS_START_DEMO_WORK)g_start_demo_mgr.main_tcb.work;
		gMS_START_DEMO_WORK.counter = 0u;
		gMS_START_DEMO_WORK.update = gmStartDemoProcFade;
		gmStartDemo2DActionCreate(gMS_START_DEMO_WORK);
		GMS_PLAYER_WORK ply_work = g_gm_main_system.ply_work[0];
		GmPlySeqInitDemoFw(ply_work);
		IzFadeInitEasy(1u, 2u, 30f);
