	private static void gmStartDemoRequestExit()
	{
		GMS_START_DEMO_MGR gMS_START_DEMO_MGR = gmStartDemoMgrGetInfo();
		if (gMS_START_DEMO_MGR != null)
		{
			if (gMS_START_DEMO_MGR.main_tcb != null)
			{
				mtTaskClearTcb(gMS_START_DEMO_MGR.main_tcb);
				gMS_START_DEMO_MGR.main_tcb = null;
			}
			gmStartDemoClearGameFlag(4096u);
		}
	}

	private static void gmStartDemoExit()
	{
		if (g_start_demo_mgr != null)
		{
			gmStartDemoRequestExit();
			g_start_demo_mgr = null;
		}
	}

	private static void gmStartDemoProcMain(MTS_TASK_TCB tcb)
	{
		GMS_START_DEMO_WORK gMS_START_DEMO_WORK = (GMS_START_DEMO_WORK)tcb.work;
		if ((gMS_START_DEMO_WORK.flag & 1) != 0)
		{
			gmStartDemoRequestExit();
			return;
		}
		if (gMS_START_DEMO_WORK.update != null)
		{
			gMS_START_DEMO_WORK.update(gMS_START_DEMO_WORK);
		}
		gMS_START_DEMO_WORK.counter++;
	}

