				GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK3 = gmStartDemo2DActionCreate(g_gm_start_demo_action_name_act[k], gMS_START_DEMO_DATA.aos_texture[num6], g_gm_start_demo_data_ama_id[num][num6], g_gm_start_demo_action_id_act[num5][k], g_gm_start_demo_action_node_flag_act[k]);
				if (gMS_COCKPIT_2D_WORK3 != null)
				{
					gMS_COCKPIT_2D_WORK3.obj_2d.speed = 0f;
				}
				work.action_obj_work_act[k] = gMS_COCKPIT_2D_WORK3;
			}
		}
		int num7 = 1;
		GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK4 = gmStartDemo2DActionCreate(g_gm_start_demo_action_name_message, gMS_START_DEMO_DATA.aos_texture[num7], g_gm_start_demo_data_ama_id[num][num7], g_gm_start_demo_action_id_message[num3][num5], 1);
		if (gMS_COCKPIT_2D_WORK4 != null)
