	private static GMS_COCKPIT_2D_WORK gmStartDemo2DActionCreate(string tcb_name, AOS_TEXTURE aos_texture, int ama_id, int action_id, int node_flag)
	{
		if (action_id == -1)
		{
			return null;
		}
		GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK = (GMS_COCKPIT_2D_WORK)GMM_COCKPIT_CREATE_WORK(() => new GMS_COCKPIT_2D_WORK(), null, 0, tcb_name);
		gMS_COCKPIT_2D_WORK.cpit_com.obj_work.disp_flag |= (uint)node_flag;
		ObjObjectAction2dAMALoadSetTexlist(gMS_COCKPIT_2D_WORK.cpit_com.obj_work, gMS_COCKPIT_2D_WORK.obj_2d, null, null, ama_id, GmGameDatGetCockpitData(), AoTexGetTexList(aos_texture), (uint)action_id, node_flag);
		((OBS_OBJECT_WORK)gMS_COCKPIT_2D_WORK).pos.z -= FX_F32_TO_FX32(10f);
		return gMS_COCKPIT_2D_WORK;
	}

