	public static bool GmStartMsgIsExe()
	{
		bool flag = false;
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		if ((g_gs_main_sys_info.game_flag & 4) == 0)
		{
			SSystem sSystem = SSystem.CreateInstance();
			switch (gSS_MAIN_SYS_INFO.stage_id)
			{
			case 5:
				flag = !GsMainSysIsStageClear(5);
				break;
			case 9:
				if (!GsMainSysIsStageClear(9))
				{
					flag = true;
				}
				else if ((0x200 & gSS_MAIN_SYS_INFO.game_flag) != 0)
				{
					if (!sSystem.IsAnnounce(SSystem.EAnnounce.TruckFlick))
					{
						flag = true;
					}
				}
				else if (!sSystem.IsAnnounce(SSystem.EAnnounce.TruckTilt))
				{
					flag = true;
				}
				if (flag)
				{
					if ((0x200 & gSS_MAIN_SYS_INFO.game_flag) != 0)
					{
						sSystem.SetAnnounce(SSystem.EAnnounce.TruckFlick, true);
					}
					else
					{
						sSystem.SetAnnounce(SSystem.EAnnounce.TruckTilt, true);
					}
				}
				break;
			case 21:
				if (!GsMainSysIsStageClear(21))
				{
					flag = true;
				}
				goto case 22;
			case 22:
			case 23:
			case 24:
			case 25:
			case 26:
			case 27:
				if (!flag)
				{
					if ((0x200 & gSS_MAIN_SYS_INFO.game_flag) != 0)
					{
						if (!sSystem.IsAnnounce(SSystem.EAnnounce.SpecialStageFlick))
						{
							flag = true;
						}
					}
					else if (!sSystem.IsAnnounce(SSystem.EAnnounce.SpecialStageTilt))
					{
						flag = true;
					}
				}
				if (flag)
				{
					if ((0x200 & gSS_MAIN_SYS_INFO.game_flag) != 0)
					{
						sSystem.SetAnnounce(SSystem.EAnnounce.SpecialStageFlick, true);
					}
					else
					{
						sSystem.SetAnnounce(SSystem.EAnnounce.SpecialStageTilt, true);
					}
				}
				break;
			}
		}
		if (flag)
		{
			GmMainClearSuspendedPause();
		}
		return flag;
	}

	private static void gmStartDemoProcWait(GMS_START_DEMO_WORK work)
	{
		if (work.counter < 160)
		{
			return;
		}
		work.update = gmStartDemoProcOut;
		if (GmStartMsgIsExe())
		{
			GmStartMsgInit();
		}
		else
		{
			GMS_PLAYER_WORK ply_work = g_gm_main_system.ply_work[0];
			GmPlySeqChangeSequence(ply_work, 0);
			gmStartDemoSetGameFlag(1024u);
		}
		for (int i = 0; 4 > i; i++)
		{
			GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK = work.action_obj_work_cmn[i];
			if (gMS_COCKPIT_2D_WORK != null)
			{
				gMS_COCKPIT_2D_WORK.obj_2d.speed = 1f;
			}
		}
		for (int j = 0; 1 > j; j++)
		{
			GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK2 = work.action_obj_work_zone[j];
			if (gMS_COCKPIT_2D_WORK2 != null)
			{
				gMS_COCKPIT_2D_WORK2.obj_2d.speed = 1f;
			}
		}
		for (int k = 0; 2 > k; k++)
		{
			GMS_COCKPIT_2D_WORK gMS_COCKPIT_2D_WORK3 = work.action_obj_work_act[k];
			if (gMS_COCKPIT_2D_WORK3 != null)
			{
				gMS_COCKPIT_2D_WORK3.obj_2d.speed = 1f;
			}
		}
		GMS_COCKPIT_2D_WORK action_obj_work_message = work.action_obj_work_message;
		if (action_obj_work_message != null)
		{
			action_obj_work_message.obj_2d.speed = 1f;
		}
	}

