	private static void GmSplStageStart()
	{
		ushort num = (ushort)(g_gs_main_sys_info.stage_id - 21);
		gm_spl_tcb = MTM_TASK_MAKE_TCB(gmSplStageFadeInWait, null, 0u, 0, 4176u, 5, () => new GMS_SPL_STG_WORK(), "SPL_STG_CTRL");
		GMS_SPL_STG_WORK gMS_SPL_STG_WORK = (GMS_SPL_STG_WORK)gm_spl_tcb.work;
		gMS_SPL_STG_WORK.counter = 0u;
		gMS_SPL_STG_WORK.light_vec.x = -1f;
		gMS_SPL_STG_WORK.light_vec.y = -1f;
		gMS_SPL_STG_WORK.light_vec.z = -1f;
		gMS_SPL_STG_WORK.get_ring = 0;
		g_gm_main_system.game_flag &= 4294508543u;
		IzFadeInitEasy(1u, 3u, 8f);
		g_gm_main_system.game_time = gm_spl_stage_init_time[num];
		g_gm_main_system.game_flag |= 4096u;
		Array.Clear(gm_gmk_ss_switch, 0, gm_gmk_ss_switch.Length);
	}

