	private static void gmSplStageFadeInWait(MTS_TASK_TCB tcb)
	{
		GMS_SPL_STG_WORK gMS_SPL_STG_WORK = (GMS_SPL_STG_WORK)tcb.work;
		gMS_SPL_STG_WORK.counter++;
		if (gMS_SPL_STG_WORK.counter > 30)
		{
			gMS_SPL_STG_WORK.counter = 0u;
			mtTaskChangeTcbProcedure(tcb, gmSplStageFadeInWait2);
			IzFadeInitEasy(0u, 2u, 30f);
		}
	}

	private static void gmSplStageFadeInWait2(MTS_TASK_TCB tcb)
	{
		if (ObjObjectPauseCheck(0u) == 0 && IzFadeIsEnd())
		{
			IzFadeExit();
			GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
			gMS_PLAYER_WORK.obj_work.move_flag &= 4294958847u;
			gMS_PLAYER_WORK.nudge_di_timer = 0;
			gMS_PLAYER_WORK.nudge_timer = 0;
			gMS_PLAYER_WORK.nudge_ofst_x = 0;
			g_gm_main_system.game_flag |= 1024u;
			g_gm_main_system.game_flag &= 4294963199u;
			if (GmStartMsgIsExe())
			{
				GmStartMsgInit();
			}
			mtTaskChangeTcbProcedure(tcb, gmSplStagePlayEndChk);
		}
	}

	private static void gmSplStagePlayEndChk(MTS_TASK_TCB tcb)
	{
		GMS_SPL_STG_WORK gMS_SPL_STG_WORK = (GMS_SPL_STG_WORK)tcb.work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
		if (ObjObjectPauseCheck(0u) != 0)
		{
			return;
		}
		gmSplStageLightCtrl(gMS_SPL_STG_WORK);
		gMS_SPL_STG_WORK.flag &= 4294967294u;
		gmSplStageNudgeCtrl();
		gmSplStageRingGateChk(gMS_SPL_STG_WORK);
		if ((g_gm_main_system.game_flag & 0x70000) != 0)
		{
			g_gm_main_system.game_flag &= 4294966271u;
			gMS_PLAYER_WORK.obj_work.flag |= 130u;
			gMS_PLAYER_WORK.obj_work.move_flag |= 8448u;
			gMS_PLAYER_WORK.obj_work.disp_flag &= 4294967294u;
			gMS_PLAYER_WORK.player_flag |= 4194304u;
			if ((g_gm_main_system.game_flag & 0x60000) != 0)
			{
				GMM_PAD_VIB_MID_TIME(90f);
			}
			gMS_SPL_STG_WORK.roll = oBS_CAMERA.roll;
			gMS_SPL_STG_WORK.roll_spd = 256;
			gMS_SPL_STG_WORK.counter = 0u;
			mtTaskChangeTcbProcedure(tcb, gmSplStageRolling);
		}
	}

	private static void gmSplStageRolling(MTS_TASK_TCB tcb)
	{
		GMS_SPL_STG_WORK gMS_SPL_STG_WORK = (GMS_SPL_STG_WORK)tcb.work;
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
		if (ObjObjectPauseCheck(0u) == 0 && oBS_CAMERA != null)
		{
			gMS_SPL_STG_WORK.roll_spd += 56;
			gMS_SPL_STG_WORK.roll += gMS_SPL_STG_WORK.roll_spd;
			oBS_CAMERA.roll = gMS_SPL_STG_WORK.roll;
			gMS_SPL_STG_WORK.counter++;
			if (gMS_SPL_STG_WORK.counter == 90)
			{
				IzFadeInitEasy(0u, 3u, 30f);
			}
			if (gMS_SPL_STG_WORK.counter > 90 && IzFadeIsEnd())
			{
				IzFadeExit();
				IzFadeRestoreDrawSetting();
				GmObjSetAllObjectNoDisp();
				GmRingGetWork().flag |= 1u;
				GmFixSetDisp(false);
				gMS_SPL_STG_WORK.flag |= 4u;
				gMS_SPL_STG_WORK.counter = 1u;
				mtTaskChangeTcbProcedure(tcb, gmSplStageGotoEnd);
				oBS_CAMERA.roll = 0;
				g_gm_main_system.pseudofall_dir = 0;
			}
		}
	}

	private static void gmSplStageGotoEnd(MTS_TASK_TCB tcb)
	{
		GMS_SPL_STG_WORK gMS_SPL_STG_WORK = (GMS_SPL_STG_WORK)tcb.work;
		if (gMS_SPL_STG_WORK.counter != 0)
		{
			gMS_SPL_STG_WORK.counter--;
			return;
		}
		g_gm_main_system.game_flag |= 4u;
		mtTaskChangeTcbProcedure(tcb, gmSplStageEnd);
	}

	private static void gmSplStageEnd(MTS_TASK_TCB tcb)
	{
		UNREFERENCED_PARAMETER(tcb);
	}

	private static void gmSplStageLightCtrl(GMS_SPL_STG_WORK tcb_work)
	{
		NNS_RGBA col = new NNS_RGBA(1f, 1f, 1f, 1f);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		UNREFERENCED_PARAMETER(tcb_work);
		nNS_VECTOR = gmSplStageLightRot(-1f, -1f, -1f);
		nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
		ObjDrawSetParallelLight(NNE_LIGHT_0, ref col, 1f, nNS_VECTOR);
		nNS_VECTOR = gmSplStageLightRot(-0.4f, -0.4f, -1f);
		nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
		ObjDrawSetParallelLight(NNE_LIGHT_1, ref col, 1f, nNS_VECTOR);
	}

	private static NNS_VECTOR gmSplStageLightRot(float pos_x, float pos_y, float pos_z)
	{
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		float num = pos_x * nnSin(-g_gm_main_system.pseudofall_dir);
		float num2 = pos_x * nnCos(-g_gm_main_system.pseudofall_dir);
		float num3 = pos_y * nnSin(-g_gm_main_system.pseudofall_dir);
		float num4 = pos_y * nnCos(-g_gm_main_system.pseudofall_dir);
		nNS_VECTOR.x = num2 - num3;
		nNS_VECTOR.y = num + num4;
		nNS_VECTOR.z = pos_z;
		return nNS_VECTOR;
	}

	private static void gmSplStageNudgeCtrl()
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
		if (gMS_PLAYER_WORK.nudge_timer != 0)
		{
			int dest_x = (gMS_PLAYER_WORK.nudge_timer * 8 << 12) / 30;
			if ((gMS_PLAYER_WORK.nudge_timer & 2) != 0)
			{
				dest_x = -dest_x;
			}
			int dest_y = 0;
			GmObjGetRotPosXY(dest_x, dest_y, ref gMS_PLAYER_WORK.obj_work.ofst.x, ref gMS_PLAYER_WORK.obj_work.ofst.y, g_gm_main_system.pseudofall_dir);
			GmObjGetRotPosXY(dest_x, dest_y, ref dest_x, ref dest_y, (ushort)(-g_gm_main_system.pseudofall_dir));
			oBS_CAMERA.ofst.x = FXM_FX32_TO_FLOAT(dest_x);
			oBS_CAMERA.ofst.y = FXM_FX32_TO_FLOAT(dest_y);
			gMS_PLAYER_WORK.nudge_timer--;
		}
		else
		{
			oBS_CAMERA.ofst.x = 0f;
			oBS_CAMERA.ofst.y = 0f;
			gMS_PLAYER_WORK.obj_work.ofst.x = 0;
			gMS_PLAYER_WORK.obj_work.ofst.y = 0;
			gMS_PLAYER_WORK.nudge_ofst_x = 0;
		}
	}

	private static void gmSplStageRingGateChk(GMS_SPL_STG_WORK tcb_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		ushort get_ring = tcb_work.get_ring;
		for (ushort num = 0; num < 9; num++)
		{
			if ((tcb_work.get_ring & (1 << (int)num)) == 0)
			{
				ushort num2 = GmSplStageRingGateNumGet(num);
				if (num2 == 255)
				{
					break;
				}
				if (num2 <= (ushort)gMS_PLAYER_WORK.ring_num)
				{
					tcb_work.get_ring |= (ushort)(1 << (int)num);
				}
			}
		}
		if (get_ring != tcb_work.get_ring)
		{
			GmSoundPlaySE("Special7");
		}
	}

