	public static GMS_RING_WORK GmRingCreate(GMS_EVE_RECORD_RING eve_rec, int pos_x, int pos_y, int pos_z)
	{
		if (gm_ring_sys_work == null)
		{
			return null;
		}
		GMS_RING_WORK gMS_RING_WORK = gmRingAllocRingWork();
		if (gMS_RING_WORK == null)
		{
			return null;
		}
		gMS_RING_WORK.pos.x = pos_x;
		gMS_RING_WORK.pos.y = pos_y;
		gMS_RING_WORK.pos.z = pos_z;
		gMS_RING_WORK.spd_x = 0;
		gMS_RING_WORK.spd_y = 0;
		gMS_RING_WORK.scale.x = (gMS_RING_WORK.scale.y = (gMS_RING_WORK.scale.z = gm_ring_scale));
		gMS_RING_WORK.timer = 0;
		gMS_RING_WORK.flag = 0;
		if (eve_rec != null)
		{
			eve_rec.pos_x = byte.MaxValue;
		}
		gMS_RING_WORK.eve_rec = eve_rec;
		gMS_RING_WORK.duct_obj = null;
		gmRingAttachRingList(gMS_RING_WORK);
		return gMS_RING_WORK;
	}

	public static GMS_RING_WORK gmRingAllocRingWork()
	{
		if (gm_ring_sys_work.ring_list_cnt >= 96)
		{
			return null;
		}
		GMS_RING_WORK result = gm_ring_sys_work.ring_list[gm_ring_sys_work.ring_list_cnt];
		gm_ring_sys_work.ring_list_cnt++;
		return result;
	}

	public static void gmRingAttachRingList(GMS_RING_WORK ring_work)
	{
		if (gm_ring_sys_work.ring_list_end != null)
		{
			gm_ring_sys_work.ring_list_end.post_ring = ring_work;
			ring_work.pre_ring = gm_ring_sys_work.ring_list_end;
			ring_work.post_ring = null;
			gm_ring_sys_work.ring_list_end = ring_work;
		}
		else
		{
			gm_ring_sys_work.ring_list_start = (gm_ring_sys_work.ring_list_end = ring_work);
			ring_work.pre_ring = (ring_work.post_ring = null);
		}
	}

	public static void GmRingInit()
	{
		MTS_TASK_TCB mTS_TASK_TCB = MTM_TASK_MAKE_TCB(gmRingMain, gmRingDest, 0u, 0, 7680u, 5, () => new GMS_RING_SYS_WORK(), "GM RING MAIN");
		if (mTS_TASK_TCB != null)
		{
			gm_ring_tcb = mTS_TASK_TCB;
			gm_ring_sys_work = (GMS_RING_SYS_WORK)mTS_TASK_TCB.work;
			gm_ring_sys_work.Clear();
			gm_ring_sys_work.h_snd_ring[0] = GsSoundAllocSeHandle();
			gm_ring_sys_work.h_snd_ring[1] = GsSoundAllocSeHandle();
			gm_ring_sys_work.h_snd_ring[0].flag |= 2147483648u;
			gm_ring_sys_work.h_snd_ring[1].flag |= 2147483648u;
			gm_ring_sys_work.player_num = 1;
			for (int num = 0; num < 96; num++)
			{
				GMS_RING_WORK gMS_RING_WORK = gm_ring_sys_work.ring_list_buf[num];
				gm_ring_sys_work.ring_list[num] = gMS_RING_WORK;
			}
			gm_ring_scale = 4096;
			gm_ring_fall_acc_x = 0;
			gm_ring_fall_acc_y = 288;
			if (21 <= g_gs_main_sys_info.stage_id && g_gs_main_sys_info.stage_id <= 27)
			{
				g_gm_ring_size = (short)((double)(OBD_LCD_X - OBD_LCD_Y) * 1.4 + 20.0);
				gm_ring_die_offset = (short)((double)(OBD_LCD_X - OBD_LCD_Y) * 1.4 + 72.0);
			}
			else
			{
				g_gm_ring_size = 20;
				gm_ring_die_offset = 72;
			}
			gm_ring_sys_work.rec_func = gmRingHitFuncNormal;
			gm_ring_sys_work.col_func = gmRingMoveCollsion;
			gm_ring_sys_work.ref_spd_base = 8192;
			gm_ring_sys_work.ring_draw_func = gmRingDrawFuncRing3D;
			gm_ring_sys_work.se_wait = 0;
			gm_ring_sys_work.color = uint.MaxValue;
			if (g_gs_main_sys_info.stage_id == 2 || g_gs_main_sys_info.stage_id == 3)
			{
				gm_ring_sys_work.color = 4292927743u;
			}
			else if (g_gs_main_sys_info.stage_id == 14)
			{
				gm_ring_sys_work.color = 3233857791u;
			}
			gm_ring_sys_work.dir = 49152;
			ObjDrawAction3dActionSet3DNNMaterial(gm_ring_obj_3d, 0);
		}
	}

	private static void gmRingMain(MTS_TASK_TCB tcb)
	{
		if ((gm_ring_sys_work.flag & 1) != 0)
		{
			gm_ring_sys_work.ring_se_cnt = 0;
			return;
		}
		if (g_obj.glb_camera_id >= 0)
		{
			ObjDraw3DNNSetCamera(g_obj.glb_camera_id, g_obj.glb_camera_type);
		}
		if (gm_ring_sys_work.se_wait > 0)
		{
			gm_ring_sys_work.se_wait--;
		}
		gmRingDrawBegin();
		GMS_RING_WORK gMS_RING_WORK;
		if (ObjObjectPauseCheck(0u) != 0)
		{
			gMS_RING_WORK = gm_ring_sys_work.ring_list_start;
			while (gMS_RING_WORK != null)
			{
				GMS_RING_WORK gMS_RING_WORK2 = gMS_RING_WORK;
				gMS_RING_WORK = gMS_RING_WORK2.post_ring;
				gm_ring_sys_work.ring_draw_func(gMS_RING_WORK2);
			}
			gMS_RING_WORK = gm_ring_sys_work.damage_ring_list_start;
			while (gMS_RING_WORK != null)
			{
				GMS_RING_WORK gMS_RING_WORK2 = gMS_RING_WORK;
				gMS_RING_WORK = gMS_RING_WORK2.post_ring;
				if (gMS_RING_WORK2.timer > 32 || (gMS_RING_WORK2.timer & 2) != 0)
				{
					gm_ring_sys_work.ring_draw_func(gMS_RING_WORK2);
				}
			}
			gMS_RING_WORK = gm_ring_sys_work.slot_ring_list_start;
			while (gMS_RING_WORK != null)
			{
				GMS_RING_WORK gMS_RING_WORK2 = gMS_RING_WORK;
				gMS_RING_WORK = gMS_RING_WORK2.post_ring;
				gm_ring_sys_work.ring_draw_func(gMS_RING_WORK2);
			}
			gmRingDrawEnd();
			gm_ring_sys_work.ring_se_cnt = 0;
			return;
		}
		for (int i = 0; i < gm_ring_sys_work.player_num; i++)
		{
			GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[i];
			OBS_RECT_WORK oBS_RECT_WORK = gMS_PLAYER_WORK.rect_work[2];
			ply_rect[i].pos.x = gMS_PLAYER_WORK.obj_work.pos.x;
			ply_rect[i].pos.y = gMS_PLAYER_WORK.obj_work.pos.y;
			ply_rect[i].pos.z = gMS_PLAYER_WORK.obj_work.pos.z;
			short num;
			short num2;
			if (((gMS_PLAYER_WORK.obj_work.disp_flag & 1) ^ (oBS_RECT_WORK.flag & 1)) != 0)
			{
				num = (short)(-oBS_RECT_WORK.rect.right);
				num2 = (short)(-oBS_RECT_WORK.rect.left);
			}
			else
			{
				num = oBS_RECT_WORK.rect.left;
				num2 = oBS_RECT_WORK.rect.right;
			}
			if (gMS_PLAYER_WORK.obj_work.scale.x != 4096)
			{
				num = (short)FX_Mul(num, gMS_PLAYER_WORK.obj_work.scale.x);
				num2 = (short)FX_Mul(num2, gMS_PLAYER_WORK.obj_work.scale.x);
			}
			ply_rect[i].left = num;
			ply_rect[i].right = num2;
			if (((gMS_PLAYER_WORK.obj_work.disp_flag & 2) ^ (oBS_RECT_WORK.flag & 2)) != 0)
			{
				num = (short)(-oBS_RECT_WORK.rect.bottom);
				num2 = (short)(-oBS_RECT_WORK.rect.top);
			}
			else
			{
				num = oBS_RECT_WORK.rect.top;
				num2 = oBS_RECT_WORK.rect.bottom;
			}
			if (gMS_PLAYER_WORK.obj_work.scale.y != 4096)
			{
				num = (short)FX_Mul(num, gMS_PLAYER_WORK.obj_work.scale.y);
				num2 = (short)FX_Mul(num2, gMS_PLAYER_WORK.obj_work.scale.y);
			}
			ply_rect[i].top = num;
			ply_rect[i].bottom = num2;
			ply_rect[i].back = 0;
			ply_rect[i].front = 0;
		}
		ring_rect.left = -9;
		ring_rect.top = -9;
		ring_rect.right = 9;
		ring_rect.bottom = 9;
		ring_rect.back = -8;
		ring_rect.front = 8;
		if (++gm_ring_sys_work.draw_ring_uv_frame >= 64)
		{
			gm_ring_sys_work.draw_ring_uv_frame = 0;
		}
		if ((g_gm_main_system.ply_work[0].player_flag & 0x40000) != 0)
		{
			gm_ring_fall_acc_x = (short)FX_Mul(-288, mtMathSin(g_gm_main_system.ply_work[0].obj_work.dir_fall));
			gm_ring_fall_acc_y = (short)FX_Mul(288, mtMathCos(g_gm_main_system.ply_work[0].obj_work.dir_fall));
		}
		if (gm_ring_sys_work.wait_slot_ring_num != 0)
		{
			gm_ring_sys_work.slot_ring_timer--;
			if (gm_ring_sys_work.slot_ring_timer <= 0)
			{
				if (gm_ring_sys_work.wait_slot_ring_num >= 2)
				{
					GmRingCreateSlotRing(gm_ring_sys_work.slot_target_obj, 1048576, gm_ring_sys_work.slot_ring_create_dir);
					GmRingCreateSlotRing(gm_ring_sys_work.slot_target_obj, 1048576, (ushort)(gm_ring_sys_work.slot_ring_create_dir + 32768 - 2048));
					gm_ring_sys_work.wait_slot_ring_num -= 2;
				}
				else
				{
					GmRingCreateSlotRing(gm_ring_sys_work.slot_target_obj, 1048576, gm_ring_sys_work.slot_ring_create_dir);
					gm_ring_sys_work.wait_slot_ring_num--;
				}
				gm_ring_sys_work.slot_ring_create_dir -= 2048;
				gm_ring_sys_work.slot_ring_timer = 4;
			}
		}
		gMS_RING_WORK = gm_ring_sys_work.ring_list_start;
		while (gMS_RING_WORK != null)
		{
			GMS_RING_WORK gMS_RING_WORK2 = gMS_RING_WORK;
			gMS_RING_WORK = gMS_RING_WORK2.post_ring;
			if (ObjViewOutCheck(gMS_RING_WORK2.pos.x, gMS_RING_WORK2.pos.y, gm_ring_die_offset, 0, 0, 0, 0) != 0)
			{
				if (gMS_RING_WORK2.eve_rec != null)
				{
					gMS_RING_WORK2.eve_rec.pos_x = (byte)((gMS_RING_WORK2.pos.x >> 12) & 0xFF);
				}
				gmRingDetachRingList(gMS_RING_WORK2);
				gmRingFreeRingWork(gMS_RING_WORK2);
				continue;
			}
			gm_ring_sys_work.ring_draw_func(gMS_RING_WORK2);
			ring_rect.pos.z = 0;
			int i = 0;
			int num3 = 0;
			for (; i < gm_ring_sys_work.player_num; i++)
			{
				GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[i];
				if ((gMS_PLAYER_WORK.player_flag & 0x400) == 0)
				{
					ring_rect.pos.x = gMS_RING_WORK2.pos.x;
					ring_rect.pos.y = gMS_RING_WORK2.pos.y;
					if (gm_ring_sys_work.rec_func(ply_rect[i], ring_rect) != 0)
					{
						num3 = 1;
						GmPlayerRingGet(gMS_PLAYER_WORK, 1);
						GmComEfctCreateRing(ring_rect.pos.x, ring_rect.pos.y);
					}
				}
			}
			if (num3 != 0)
			{
				gMS_RING_WORK2.timer = 0;
				gmRingDetachRingList(gMS_RING_WORK2);
				gmRingFreeRingWork(gMS_RING_WORK2);
			}
		}
		gMS_RING_WORK = gm_ring_sys_work.damage_ring_list_start;
		while (gMS_RING_WORK != null)
		{
			GMS_RING_WORK gMS_RING_WORK2 = gMS_RING_WORK;
			gMS_RING_WORK = gMS_RING_WORK2.post_ring;
			if (ObjViewOutCheck(gMS_RING_WORK2.pos.x, gMS_RING_WORK2.pos.y, 196, 0, 0, 0, 0) != 0)
			{
				gmRingDetachDamageRingList(gMS_RING_WORK2);
				gmRingFreeRingWork(gMS_RING_WORK2);
				continue;
			}
			gMS_RING_WORK2.pos.x += gMS_RING_WORK2.spd_x;
			if ((gMS_RING_WORK2.flag & 4) != 0)
			{
				gMS_RING_WORK2.pos.y -= gMS_RING_WORK2.spd_y;
			}
			else
			{
				gMS_RING_WORK2.pos.y += gMS_RING_WORK2.spd_y;
			}
			gMS_RING_WORK2.spd_x += gm_ring_fall_acc_x;
			gMS_RING_WORK2.spd_y += gm_ring_fall_acc_y;
			gm_ring_sys_work.col_func(gMS_RING_WORK2);
			gMS_RING_WORK2.timer--;
			if (gMS_RING_WORK2.timer == 0)
			{
				gmRingDetachDamageRingList(gMS_RING_WORK2);
				gmRingFreeRingWork(gMS_RING_WORK2);
				continue;
			}
			if (gMS_RING_WORK2.timer <= 216)
			{
				ring_rect.pos.z = 0;
				int i = 0;
				int num3 = 0;
				for (; i < gm_ring_sys_work.player_num; i++)
				{
					GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[i];
					if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
					{
						continue;
					}
					ring_rect.pos.x = gMS_RING_WORK2.pos.x;
					ring_rect.pos.y = gMS_RING_WORK2.pos.y;
					if (gm_ring_sys_work.rec_func(ply_rect[i], ring_rect) != 0)
					{
						num3 = 1;
						short ring_stage_num = gMS_PLAYER_WORK.ring_stage_num;
						GmPlayerRingGet(gMS_PLAYER_WORK, 1);
						if (ring_stage_num < 999)
						{
							gMS_PLAYER_WORK.ring_stage_num--;
						}
						GmComEfctCreateRing(ring_rect.pos.x, ring_rect.pos.y);
						if ((gm_ring_sys_work.flag & (uint)(16777216 << i)) != 0)
						{
							gm_ring_sys_work.flag &= (uint)(~(16777216 << i));
						}
					}
				}
				if (num3 != 0)
				{
					gMS_RING_WORK2.timer = 0;
					gmRingDetachDamageRingList(gMS_RING_WORK2);
					gmRingFreeRingWork(gMS_RING_WORK2);
				}
			}
			if (gMS_RING_WORK2.timer > 32 || (gMS_RING_WORK2.timer & 2) != 0)
			{
				gm_ring_sys_work.ring_draw_func(gMS_RING_WORK2);
			}
		}
		if (gm_ring_sys_work.damage_ring_list_start == null)
		{
			for (int i = 0; i < gm_ring_sys_work.player_num; i++)
			{
				if ((gm_ring_sys_work.flag & (uint)(16777216 << i)) != 0)
				{
					gm_ring_sys_work.damage_num[i] = 0;
					gm_ring_sys_work.flag &= (uint)(~(16777216 << i));
				}
			}
		}
		gMS_RING_WORK = gm_ring_sys_work.slot_ring_list_start;
		while (gMS_RING_WORK != null)
		{
			GMS_RING_WORK gMS_RING_WORK2 = gMS_RING_WORK;
			gMS_RING_WORK = gMS_RING_WORK2.post_ring;
			if (ObjViewOutCheck(gMS_RING_WORK2.pos.x, gMS_RING_WORK2.pos.y, 512, 0, 0, 0, 0) != 0)
			{
				gmRingDetachSlotRingList(gMS_RING_WORK2);
				gmRingFreeRingWork(gMS_RING_WORK2);
				continue;
			}
			gMS_RING_WORK2.pos.x += gMS_RING_WORK2.spd_x;
			gMS_RING_WORK2.pos.y += gMS_RING_WORK2.spd_y;
			gm_ring_sys_work.ring_draw_func(gMS_RING_WORK2);
			ring_rect.pos.z = 0;
			int i = 0;
			int num3 = 0;
			for (; i < gm_ring_sys_work.player_num; i++)
			{
				GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[i];
				if ((gMS_PLAYER_WORK.player_flag & 0x400) == 0)
				{
					ring_rect.pos.x = gMS_RING_WORK2.pos.x;
					ring_rect.pos.y = gMS_RING_WORK2.pos.y;
					if (gm_ring_sys_work.rec_func(ply_rect[i], ring_rect) != 0)
					{
						num3 = 1;
						GmPlayerRingGet(gMS_PLAYER_WORK, 1);
						GmComEfctCreateRing(ring_rect.pos.x, ring_rect.pos.y);
					}
				}
			}
			if (num3 != 0)
			{
				gMS_RING_WORK2.timer = 0;
				gmRingDetachSlotRingList(gMS_RING_WORK2);
				gmRingFreeRingWork(gMS_RING_WORK2);
			}
		}
		gmRingDrawEnd();
		gm_ring_sys_work.ring_se_cnt = 0;
	}

