	private static void gmRingDrawBegin()
	{
		gm_ring_sys_work.draw_ring_count = 0;
	}

	private static void gmRingDrawEnd()
	{
		if (gm_ring_sys_work.draw_ring_count <= 0 || !GmMainIsDrawEnable())
		{
			return;
		}
		VecU16 vecU = new VecU16
		{
			x = 0,
			y = gm_ring_sys_work.dir,
			z = GmMainGetObjectRotation()
		};
		GMS_RING_SYS_WORK gMS_RING_SYS_WORK = gm_ring_sys_work;
		uint draw_ring_count = gm_ring_sys_work.draw_ring_count;
		SNNS_VECTOR disp_pos;
		ObjCameraDispPosGet(0, out disp_pos);
		float s;
		float c;
		nnSinCos(vecU.z + -8192, out s, out c);
		s *= 13.576385f;
		c *= 13.576385f;
		float s2;
		float c2;
		nnSinCos(vecU.z + -24576, out s2, out c2);
		s2 *= 13.576385f;
		c2 *= 13.576385f;
		VecFx32 vecFx = new VecFx32(gMS_RING_SYS_WORK.draw_ring_pos[0]);
		SNNS_MATRIX dst = default(SNNS_MATRIX);
		nnMakeUnitMatrix(ref dst);
		nnTranslateMatrix(ref dst, ref dst, FX_FX32_TO_F32(vecFx.x), 0f - FX_FX32_TO_F32(vecFx.y), FX_FX32_TO_F32(vecFx.z));
		_AMS_PARAM_DRAW_PRIMITIVE.type = 1;
		_AMS_PARAM_DRAW_PRIMITIVE.count = (int)(6 * draw_ring_count - 2);
		_AMS_PARAM_DRAW_PRIMITIVE.ablend = 0;
		_AMS_PARAM_DRAW_PRIMITIVE.bldSrc = 768;
		_AMS_PARAM_DRAW_PRIMITIVE.bldDst = 774;
		_AMS_PARAM_DRAW_PRIMITIVE.bldMode = 32774;
		_AMS_PARAM_DRAW_PRIMITIVE.aTest = 1;
		_AMS_PARAM_DRAW_PRIMITIVE.zMask = 0;
		_AMS_PARAM_DRAW_PRIMITIVE.zTest = 1;
		_AMS_PARAM_DRAW_PRIMITIVE.noSort = 1;
		_AMS_PARAM_DRAW_PRIMITIVE.texlist = gm_ring_obj_3d.texlist;
		_AMS_PARAM_DRAW_PRIMITIVE.texId = 0;
		_AMS_PARAM_DRAW_PRIMITIVE.uwrap = 1;
		_AMS_PARAM_DRAW_PRIMITIVE.vwrap = 1;
		uint color = gm_ring_sys_work.color;
		_AMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D = amDrawAlloc_NNS_PRIM3D_PCT(_AMS_PARAM_DRAW_PRIMITIVE.count);
		NNS_PRIM3D_PCT[] buffer = _AMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D.buffer;
		int offset = _AMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D.offset;
		_AMS_PARAM_DRAW_PRIMITIVE.format3D = 4;
		for (int i = 0; i < draw_ring_count; i++)
		{
			int num = offset + 6 * i;
			ushort num2 = (ushort)(gm_ring_sys_work.draw_ring_uv_frame / 4);
			buffer[num].Tex.u = (buffer[num + 1].Tex.u = gm_ring_roll_uv[0][num2]);
			buffer[num + 2].Tex.u = (buffer[num + 3].Tex.u = gm_ring_roll_uv[0][num2] + 0.25f);
			buffer[num].Tex.v = (buffer[num + 2].Tex.v = gm_ring_roll_uv[1][num2]);
			buffer[num + 1].Tex.v = (buffer[num + 3].Tex.v = gm_ring_roll_uv[1][num2] + 0.25f);
			buffer[num].Col = color;
			buffer[num + 1].Col = (buffer[num + 2].Col = (buffer[num + 3].Col = buffer[num].Col));
			buffer[num].Pos.x = s + FX_FX32_TO_F32(gMS_RING_SYS_WORK.draw_ring_pos[i].x - vecFx.x);
			buffer[num + 1].Pos.x = s2 + FX_FX32_TO_F32(gMS_RING_SYS_WORK.draw_ring_pos[i].x - vecFx.x);
			buffer[num + 2].Pos.x = 0f - s2 + FX_FX32_TO_F32(gMS_RING_SYS_WORK.draw_ring_pos[i].x - vecFx.x);
			buffer[num + 3].Pos.x = 0f - s + FX_FX32_TO_F32(gMS_RING_SYS_WORK.draw_ring_pos[i].x - vecFx.x);
			buffer[num].Pos.y = c - FX_FX32_TO_F32(gMS_RING_SYS_WORK.draw_ring_pos[i].y - vecFx.y);
			buffer[num + 1].Pos.y = c2 - FX_FX32_TO_F32(gMS_RING_SYS_WORK.draw_ring_pos[i].y - vecFx.y);
			buffer[num + 2].Pos.y = 0f - c2 - FX_FX32_TO_F32(gMS_RING_SYS_WORK.draw_ring_pos[i].y - vecFx.y);
			buffer[num + 3].Pos.y = 0f - c - FX_FX32_TO_F32(gMS_RING_SYS_WORK.draw_ring_pos[i].y - vecFx.y);
			buffer[num].Pos.z = (buffer[num + 1].Pos.z = (buffer[num + 2].Pos.z = (buffer[num + 3].Pos.z = -1f + FX_FX32_TO_F32(gMS_RING_SYS_WORK.draw_ring_pos[i].z - vecFx.z))));
			if (i != 0)
			{
				buffer[num - 1] = buffer[num];
			}
			if (i + 1 < draw_ring_count)
			{
				buffer[num + 4] = buffer[num + 3];
			}
		}
		_AMS_PARAM_DRAW_PRIMITIVE.sortZ = nnDistanceVector(ref buffer[offset].Pos, ref disp_pos);
		amMatrixPush(ref dst);
		ObjDraw3DNNDrawPrimitive(_AMS_PARAM_DRAW_PRIMITIVE);
		amMatrixPop();
	}

	private static void gmRingDest(MTS_TASK_TCB tcb)
	{
		for (GMS_RING_WORK gMS_RING_WORK = gm_ring_sys_work.ring_list_start; gMS_RING_WORK != null; gMS_RING_WORK = gMS_RING_WORK.post_ring)
		{
			if (gMS_RING_WORK.eve_rec != null)
			{
				gMS_RING_WORK.eve_rec.pos_x = (byte)((gMS_RING_WORK.pos.x >> 12) & 0xFF);
			}
		}
		for (int i = 0; i < 2; i++)
		{
			if (gm_ring_sys_work.h_snd_ring[i] != null)
			{
				GmSoundStopSE(gm_ring_sys_work.h_snd_ring[i]);
				GsSoundFreeSeHandle(gm_ring_sys_work.h_snd_ring[i]);
				gm_ring_sys_work.h_snd_ring[i] = null;
			}
		}
		gm_ring_tcb = null;
		gm_ring_sys_work = null;
	}

	private static void gmRingMoveCollsion(GMS_RING_WORK ring_work)
	{
		int num = 0;
		int spd_y = ring_work.spd_y;
		OBS_COL_CHK_DATA oBS_COL_CHK_DATA = GlobalPool<OBS_COL_CHK_DATA>.Alloc();
		if ((ring_work.flag & 4) != 0)
		{
			spd_y = -spd_y;
		}
		if ((ring_work.flag & 2) != 0)
		{
			oBS_COL_CHK_DATA.flag = 1;
		}
		else
		{
			oBS_COL_CHK_DATA.flag = 0;
		}
		oBS_COL_CHK_DATA.dir = null;
		oBS_COL_CHK_DATA.attr = null;
		oBS_COL_CHK_DATA.pos_x = ring_work.pos.x >> 12;
		oBS_COL_CHK_DATA.pos_y = ring_work.pos.y >> 12;
		if (ring_work.spd_y > 0)
		{
			oBS_COL_CHK_DATA.pos_y += 9;
			oBS_COL_CHK_DATA.vec = 2;
			num = ObjDiffCollisionFast(oBS_COL_CHK_DATA);
			if (num < 0)
			{
				if ((ring_work.flag & 4) != 0)
				{
					ring_work.pos.y -= num << 12;
				}
				else
				{
					ring_work.pos.y += num << 12;
				}
			}
		}
		else if (ring_work.spd_y < 0)
		{
			oBS_COL_CHK_DATA.pos_y += -9;
			oBS_COL_CHK_DATA.vec = 3;
			num = ObjDiffCollisionFast(oBS_COL_CHK_DATA);
			if (num < 0)
			{
				if ((ring_work.flag & 4) != 0)
				{
					ring_work.pos.y += num << 12;
				}
				else
				{
					ring_work.pos.y -= num << 12;
				}
			}
		}
		if (num < 0)
		{
			ring_work.spd_y -= ring_work.spd_y >> 2;
			ring_work.spd_y = -ring_work.spd_y;
		}
		num = 0;
		oBS_COL_CHK_DATA.pos_y = ring_work.pos.y >> 12;
		if (ring_work.spd_x > 0)
		{
			oBS_COL_CHK_DATA.pos_x += 9;
			oBS_COL_CHK_DATA.vec = 0;
			num = ObjDiffCollisionFast(oBS_COL_CHK_DATA);
			if (num < 0)
			{
				ring_work.pos.x += num << 12;
			}
		}
		else if (ring_work.spd_x < 0)
		{
			oBS_COL_CHK_DATA.pos_x += -9;
			oBS_COL_CHK_DATA.vec = 1;
			num = ObjDiffCollisionFast(oBS_COL_CHK_DATA);
			if (num < 0)
			{
				ring_work.pos.x -= num << 12;
			}
		}
		if (num < 0)
		{
			ring_work.spd_x -= ring_work.spd_x >> 2;
			ring_work.spd_x = -ring_work.spd_x;
		}
		GlobalPool<OBS_COL_CHK_DATA>.Release(oBS_COL_CHK_DATA);
	}

	private static void gmRingDetachSlotRingList(GMS_RING_WORK ring_work)
	{
		if (ring_work.pre_ring == null)
		{
			gm_ring_sys_work.slot_ring_list_start = ring_work.post_ring;
