	private static GMS_RING_WORK GmRingCreateSlotRing(OBS_OBJECT_WORK target_obj, int dist, ushort dir)
	{
		if (gm_ring_sys_work == null)
		{
			return null;
		}
		GMS_RING_WORK gMS_RING_WORK = gmRingAllocRingWork();
		if (gMS_RING_WORK == null)
		{
			return null;
		}
		gMS_RING_WORK.pos.x = target_obj.pos.x + FX_Mul(dist, mtMathCos(dir));
		gMS_RING_WORK.pos.y = target_obj.pos.y + FX_Mul(-dist, mtMathSin(dir));
		gMS_RING_WORK.pos.z = target_obj.pos.z;
		gMS_RING_WORK.spd_x = FX_Mul(24576, mtMathCos((ushort)(dir + 32768)));
		gMS_RING_WORK.spd_y = FX_Mul(-24576, mtMathSin((ushort)(dir + 32768)));
		gMS_RING_WORK.scale.x = (gMS_RING_WORK.scale.y = (gMS_RING_WORK.scale.z = 4096));
		gMS_RING_WORK.timer = 0;
		gMS_RING_WORK.flag = 0;
		gMS_RING_WORK.eve_rec = null;
		gMS_RING_WORK.duct_obj = null;
		gmRingAttachSlotRingList(gMS_RING_WORK);
		return gMS_RING_WORK;
	}

	private static void gmRingDetachDamageRingList(GMS_RING_WORK ring_work)
	{
		if (ring_work.pre_ring == null)
		{
			gm_ring_sys_work.damage_ring_list_start = ring_work.post_ring;
		}
		else
		{
			ring_work.pre_ring.post_ring = ring_work.post_ring;
		}
		if (ring_work.post_ring == null)
		{
			gm_ring_sys_work.damage_ring_list_end = ring_work.pre_ring;
		}
		else
		{
			ring_work.post_ring.pre_ring = ring_work.pre_ring;
		}
	}

	private static void gmRingAttachSlotRingList(GMS_RING_WORK ring_work)
	{
		if (gm_ring_sys_work.slot_ring_list_end != null)
		{
			gm_ring_sys_work.slot_ring_list_end.post_ring = ring_work;
			ring_work.pre_ring = gm_ring_sys_work.slot_ring_list_end;
			ring_work.post_ring = null;
			gm_ring_sys_work.slot_ring_list_end = ring_work;
		}
		else
		{
			gm_ring_sys_work.slot_ring_list_start = (gm_ring_sys_work.slot_ring_list_end = ring_work);
			ring_work.pre_ring = (ring_work.post_ring = null);
		}
	}

	private static void gmRingDrawFuncRing3D(GMS_RING_WORK ring_work)
	{
		VecU16 vecU = new VecU16
		{
			x = 0,
			y = gm_ring_sys_work.dir
		};
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(g_obj.glb_camera_id);
		vecU.z = (ushort)(-oBS_CAMERA.roll);
		int draw_ring_count = gm_ring_sys_work.draw_ring_count;
		gm_ring_sys_work.draw_ring_pos[draw_ring_count].x = ring_work.pos.x;
		gm_ring_sys_work.draw_ring_pos[draw_ring_count].y = ring_work.pos.y;
		gm_ring_sys_work.draw_ring_pos[draw_ring_count].z = ring_work.pos.z;
		gm_ring_sys_work.draw_ring_count++;
	}

	private static void GmRingGetSE()
	{
		bool flag = true;
		if (gm_ring_sys_work.ring_se_cnt >= 1 || gm_ring_sys_work.se_wait > 0)
		{
			return;
		}
		if (gm_ring_sys_work != null)
		{
			if ((gm_ring_sys_work.flag & 8) != 0)
			{
				flag = false;
			}
			gm_ring_sys_work.flag ^= 8u;
			gm_ring_sys_work.se_wait = 3;
		}
		if (flag)
		{
			GmSoundPlaySE("Ring1L", gm_ring_sys_work.h_snd_ring[0]);
		}
		else
		{
			GmSoundPlaySE("Ring1R", gm_ring_sys_work.h_snd_ring[1]);
		}
		gm_ring_sys_work.ring_se_cnt++;
	}

	private static void GmRingDamageSet(GMS_PLAYER_WORK ply_obj)
	{
		GmRingDamageSetNum(ply_obj, ply_obj.ring_num);
	}

	private static void GmRingDamageSetNum(GMS_PLAYER_WORK ply_work, short ring_num)
	{
		int num = 0;
		int spd_y = 0;
		int num2 = 1160;
		byte player_id = ply_work.player_id;
		ushort num3 = (ushort)(8 | ((player_id << 4) & 0x10));
		if (gm_ring_sys_work == null)
		{
			return;
		}
		if (ring_num > ply_work.ring_num)
		{
			ring_num = ply_work.ring_num;
		}
		else if (ring_num < 0)
		{
			mppAssertNotImpl();
			return;
		}
		ply_work.ring_num -= ring_num;
		if (ring_num > 32)
		{
			ring_num = 32;
		}
		gm_ring_sys_work.flag |= (uint)(16777216 << (int)player_id);
		if ((ply_work.obj_work.flag & 1) != 0)
		{
			num3 |= 2;
		}
		num2 += gm_ring_sys_work.damage_num[player_id] << 8;
		ushort dir_fall = ply_work.obj_work.dir_fall;
		for (int i = 0; i < ring_num; i++)
		{
			if (num2 >= 0)
			{
				int num4 = num2 >> 8;
				num4 = ((num4 >= 6) ? (-num4 + 9) : num4);
				num = mtMathSin((ushort)(((num2 + dir_fall) & 0xFF) << 8)) << 4 >> num4;
				spd_y = mtMathCos((ushort)(((num2 + dir_fall) & 0xFF) << 8)) << 4 >> num4;
				num -= num >> 2;
				spd_y -= spd_y >> 2;
				num2 += 16;
				num2 |= 0x80;
			}
			if (GmRingCreateDamageRing(ply_work.obj_work.pos.x, ply_work.obj_work.pos.y, 0, num, spd_y, num3) == null)
			{
				break;
			}
			num2 = -num2;
			num = -num;
		}
		if (gm_ring_sys_work.damage_num[player_id] < gm_ring_damege_num_tbl[g_gs_main_sys_info.level])
		{
			gm_ring_sys_work.damage_num[player_id]++;
		}
	}

	private static GMS_RING_WORK GmRingCreateDamageRing(int pos_x, int pos_y, int pos_z, int spd_x, int spd_y, ushort flag)
	{
		if (gm_ring_sys_work == null)
		{
			return null;
		}
		GMS_RING_WORK gMS_RING_WORK = gmRingAllocRingWork();
		if (gMS_RING_WORK == null)
		{
			return null;
		}
		gMS_RING_WORK.pos.x = pos_x;
		gMS_RING_WORK.pos.y = pos_y;
		gMS_RING_WORK.pos.z = pos_z;
		gMS_RING_WORK.spd_x = spd_x;
		gMS_RING_WORK.spd_y = spd_y;
		gMS_RING_WORK.scale.x = (gMS_RING_WORK.scale.y = (gMS_RING_WORK.scale.z = 4096));
		gMS_RING_WORK.timer = (short)(256 + (mtMathRand() & 0x1F));
		gMS_RING_WORK.flag = flag;
		gMS_RING_WORK.eve_rec = null;
		gMS_RING_WORK.duct_obj = null;
		gmRingAttachDamageRingList(gMS_RING_WORK);
		return gMS_RING_WORK;
	}

	private static void gmRingAttachDamageRingList(GMS_RING_WORK ring_work)
	{
		if (gm_ring_sys_work.damage_ring_list_end != null)
		{
			gm_ring_sys_work.damage_ring_list_end.post_ring = ring_work;
			ring_work.pre_ring = gm_ring_sys_work.damage_ring_list_end;
			ring_work.post_ring = null;
			gm_ring_sys_work.damage_ring_list_end = ring_work;
		}
		else
		{
			gm_ring_sys_work.damage_ring_list_start = (gm_ring_sys_work.damage_ring_list_end = ring_work);
			ring_work.pre_ring = (ring_work.post_ring = null);
		}
	}

