		return 0;
	}

	private static void gmGmkSteamGateHit(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		OBS_OBJECT_WORK parent_obj = mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_PLAYER_WORK == g_gm_main_system.ply_work[0] && (gMS_PLAYER_WORK.player_flag & 0x400) == 0)
		{
			GMS_GMK_STEAMP_WORK gMS_GMK_STEAMP_WORK = (GMS_GMK_STEAMP_WORK)parent_obj;
			gMS_PLAYER_WORK.obj_work.pos.y = parent_obj.pos.y;
			GmPlySeqInitSteamPipeIn(gMS_PLAYER_WORK);
			gMS_GMK_STEAMP_WORK.status = 1;
			gMS_GMK_STEAMP_WORK.ply_work = gMS_PLAYER_WORK;
			parent_obj.flag |= 2u;
			GMM_PAD_VIB_SMALL_TIME(60f);
		}
		mine_rect.flag &= 4294573823u;
	}

	private static void gmGmkSteamExitHit(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		OBS_OBJECT_WORK parent_obj = mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_PLAYER_WORK == g_gm_main_system.ply_work[0] && gMS_PLAYER_WORK.seq_state == 57 && (gMS_PLAYER_WORK.player_flag & 0x400) == 0)
		{
			GMS_GMK_STEAMP_WORK gMS_GMK_STEAMP_WORK = (GMS_GMK_STEAMP_WORK)parent_obj;
			gMS_PLAYER_WORK.obj_work.spd.x = (gMS_PLAYER_WORK.obj_work.spd.y = 0);
			gMS_GMK_STEAMP_WORK.status = 1;
			gMS_GMK_STEAMP_WORK.ply_work = gMS_PLAYER_WORK;
			parent_obj.flag |= 2u;
		}
	}

	private static void gmGmkSteamCrankCheck(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (gMS_PLAYER_WORK.obj_work.pos.x < obj_work.pos.x + 65536 && gMS_PLAYER_WORK.obj_work.pos.x > obj_work.pos.x - 65536 && gMS_PLAYER_WORK.obj_work.pos.y < obj_work.pos.y + 65536 && gMS_PLAYER_WORK.obj_work.pos.y > obj_work.pos.y - 65536)
		{
			if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0 || gMS_PLAYER_WORK.seq_state != 57 || obj_work.user_flag != 0)
			{
				return;
			}
			GMS_GMK_STEAMP_WORK gMS_GMK_STEAMP_WORK = (GMS_GMK_STEAMP_WORK)obj_work;
			int x;
			int num;
			if (gMS_PLAYER_WORK.obj_work.spd.x != 0)
			{
				x = gMS_PLAYER_WORK.obj_work.spd.x;
				num = gMS_PLAYER_WORK.obj_work.pos.x - x;
				if ((x > 0 && (tbl_gmk_pipe_vect[gMS_GMK_STEAMP_WORK.obj_type] & 2) != 0 && num <= obj_work.pos.x && obj_work.pos.x <= gMS_PLAYER_WORK.obj_work.pos.x) || (x < 0 && (tbl_gmk_pipe_vect[gMS_GMK_STEAMP_WORK.obj_type] & 1) != 0 && gMS_PLAYER_WORK.obj_work.pos.x <= obj_work.pos.x && obj_work.pos.x <= num))
				{
					num = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
					gMS_PLAYER_WORK.obj_work.pos.x = obj_work.pos.x;
					gMS_PLAYER_WORK.obj_work.spd.x = 0;
					gMS_PLAYER_WORK.obj_work.pos.y = obj_work.pos.y;
					if ((tbl_gmk_pipe_vect[gMS_GMK_STEAMP_WORK.obj_type] & 8) == 0)
					{
						gMS_PLAYER_WORK.obj_work.spd.y = -61440;
						gMS_PLAYER_WORK.obj_work.pos.y -= MTM_MATH_ABS(num);
					}
					else
					{
						gMS_PLAYER_WORK.obj_work.spd.y = 61440;
						gMS_PLAYER_WORK.obj_work.pos.y += MTM_MATH_ABS(num);
					}
					obj_work.flag |= 2u;
					GmSoundPlaySE("PipeMoving");
					obj_work.user_flag = 1u;
				}
				return;
			}
			x = gMS_PLAYER_WORK.obj_work.spd.y;
			num = gMS_PLAYER_WORK.obj_work.pos.y - x;
			if ((x > 0 && (tbl_gmk_pipe_vect[gMS_GMK_STEAMP_WORK.obj_type] & 4) != 0 && num <= obj_work.pos.y && obj_work.pos.y <= gMS_PLAYER_WORK.obj_work.pos.y) || (x < 0 && (tbl_gmk_pipe_vect[gMS_GMK_STEAMP_WORK.obj_type] & 8) != 0 && gMS_PLAYER_WORK.obj_work.pos.y <= obj_work.pos.y && obj_work.pos.y <= num))
			{
				num = gMS_PLAYER_WORK.obj_work.pos.y - obj_work.pos.y;
				gMS_PLAYER_WORK.obj_work.pos.y = obj_work.pos.y;
				gMS_PLAYER_WORK.obj_work.spd.y = 0;
				gMS_PLAYER_WORK.obj_work.pos.x = obj_work.pos.x;
				if ((tbl_gmk_pipe_vect[gMS_GMK_STEAMP_WORK.obj_type] & 2) == 0)
				{
					gMS_PLAYER_WORK.obj_work.spd.x = 61440;
					gMS_PLAYER_WORK.obj_work.pos.x += MTM_MATH_ABS(num);
				}
				else
				{
					gMS_PLAYER_WORK.obj_work.spd.x = -61440;
					gMS_PLAYER_WORK.obj_work.pos.x -= MTM_MATH_ABS(num);
				}
				obj_work.flag |= 2u;
				GmSoundPlaySE("PipeMoving");
				obj_work.user_flag = 1u;
			}
		}
		else
		{
			obj_work.user_flag = 0u;
		}
	}

	private static void gmGmkSteamPipeStay(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STEAMP_WORK gMS_GMK_STEAMP_WORK = (GMS_GMK_STEAMP_WORK)obj_work;
		switch (gMS_GMK_STEAMP_WORK.obj_type)
		{
		case 4:
		case 5:
			obj_work.ppFunc = gmGmkSteamPipeStay_100;
			break;
		case 6:
		case 7:
			obj_work.ppFunc = gmGmkSteamPipeStay_Exit;
			break;
		case 0:
		case 1:
		case 2:
		case 3:
			gmGmkSteamCrankCheck(obj_work);
			break;
		default:
			obj_work.ppFunc = null;
			break;
		}
	}

	private static void gmGmkSteamPipeStay_100(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STEAMP_WORK gMS_GMK_STEAMP_WORK = (GMS_GMK_STEAMP_WORK)obj_work;
		if (gMS_GMK_STEAMP_WORK.status != 0)
		{
			switch (gMS_GMK_STEAMP_WORK.obj_type)
			{
			case 4:
			case 5:
				gMS_GMK_STEAMP_WORK.timer = 60;
				obj_work.ppFunc = gmGmkSteamPipe_GateIn;
				GmSoundPlaySE("PipeIn");
				break;
			case 6:
			case 7:
				gMS_GMK_STEAMP_WORK.timer = 0;
				gmGmkSteamPipe_GateOutColClear(obj_work);
				obj_work.ppFunc = gmGmkSteamPipe_GateOut;
				break;
			case 0:
			case 1:
			case 2:
			case 3:
			case 8:
			case 9:
			case 10:
				break;
			}
		}
	}

	private static void gmGmkSteamPipeStay_Exit(OBS_OBJECT_WORK obj_work)
	{
		gmGmkSteamPipeStay_100(obj_work);
	}

	private static void gmGmkSteamPipe_GateIn(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STEAMP_WORK gMS_GMK_STEAMP_WORK = (GMS_GMK_STEAMP_WORK)obj_work;
		gMS_GMK_STEAMP_WORK.timer--;
		if (gMS_GMK_STEAMP_WORK.timer <= 0)
		{
			int spd_x = ((gMS_GMK_STEAMP_WORK.obj_type != 4) ? (-61440) : 61440);
			gMS_GMK_STEAMP_WORK.ply_work.obj_work.move_flag |= 16u;
			GmPlySeqGmkSpdSet(gMS_GMK_STEAMP_WORK.ply_work, spd_x, 0);
			gMS_GMK_STEAMP_WORK.ply_work.gmk_flag2 |= 6u;
			GmSoundPlaySE("PipeMoving");
			obj_work.ppFunc = null;
		}
	}

	private static void gmGmkSteamPipe_GateOut(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STEAMP_WORK gMS_GMK_STEAMP_WORK = (GMS_GMK_STEAMP_WORK)obj_work;
		gMS_GMK_STEAMP_WORK.timer--;
		if (gMS_GMK_STEAMP_WORK.timer <= 0)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)GmEfctCmnEsCreate(obj_work, 92);
			oBS_OBJECT_WORK.pos.x = obj_work.pos.x;
			oBS_OBJECT_WORK.pos.y = obj_work.pos.y;
			int spd_x;
			if ((obj_work.user_flag & 1) == 0)
			{
				spd_x = 61440;
				oBS_OBJECT_WORK.dir.z = 16384;
				oBS_OBJECT_WORK.pos.x += 229376;
			}
			else
			{
				spd_x = -61440;
				oBS_OBJECT_WORK.dir.z = 49152;
				oBS_OBJECT_WORK.pos.x -= 229376;
			}
			GmPlySeqInitSteamPipeOut(gMS_GMK_STEAMP_WORK.ply_work, spd_x);
			GmSoundPlaySE("PipeOut");
			gMS_GMK_STEAMP_WORK.timer = 8;
			obj_work.ppFunc = gmGmkSteamPipe_GateOut_100;
		}
	}

	private static void gmGmkSteamPipe_GateOut_100(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STEAMP_WORK gMS_GMK_STEAMP_WORK = (GMS_GMK_STEAMP_WORK)obj_work;
		gMS_GMK_STEAMP_WORK.timer--;
		if (gMS_GMK_STEAMP_WORK.timer <= 0)
		{
			gmGmkSteamPipe_GateOutColSet(obj_work);
			gMS_GMK_STEAMP_WORK.status = 0;
			obj_work.ppFunc = gmGmkSteamPipeStay_Exit;
		}
	}

	private static void gmGmkSteamPipe_GateOutColSet(OBS_OBJECT_WORK obj_work)
	{
		if ((((GMS_ENEMY_COM_WORK)obj_work).eve_rec.flag & 2) == 0)
		{
			GMS_GMK_STEAMP_WORK gMS_GMK_STEAMP_WORK = (GMS_GMK_STEAMP_WORK)obj_work;
			gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.obj = obj_work;
			gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.width = 64;
			gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.height = 64;
			gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.ofst_x = 0;
			gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.ofst_y = -32;
			gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.dir = 0;
		}
	}

	private static void gmGmkSteamPipe_GateOutColClear(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_STEAMP_WORK gMS_GMK_STEAMP_WORK = (GMS_GMK_STEAMP_WORK)obj_work;
		gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.obj = null;
	}

	private static void gmGmkSteamPipeStart(OBS_OBJECT_WORK obj_work, int type)
	{
		GMS_GMK_STEAMP_WORK gMS_GMK_STEAMP_WORK = (GMS_GMK_STEAMP_WORK)obj_work;
		if (type >= 4 && type < 8)
		{
			gMS_GMK_STEAMP_WORK.gmk_work.ene_com.rect_work[0].flag &= 4294967291u;
			gMS_GMK_STEAMP_WORK.gmk_work.ene_com.rect_work[1].flag &= 4294967291u;
			OBS_RECT_WORK oBS_RECT_WORK = gMS_GMK_STEAMP_WORK.gmk_work.ene_com.rect_work[2];
			oBS_RECT_WORK.ppHit = null;
			if (type < 6)
			{
				oBS_RECT_WORK.ppDef = gmGmkSteamGateHit;
				gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.obj = obj_work;
				gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.width = 32;
				gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.height = 16;
				gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.ofst_x = -14;
				gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.ofst_y = -34;
				gMS_GMK_STEAMP_WORK.gmk_work.ene_com.col_work.obj_col.dir = 0;
			}
			else
			{
				oBS_RECT_WORK.ppDef = gmGmkSteamExitHit;
			}
			ObjRectAtkSet(oBS_RECT_WORK, 0, 0);
			ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
			ObjRectWorkSet(oBS_RECT_WORK, tbl_gm_gmk_steampipe_rect[type][0], tbl_gm_gmk_steampipe_rect[type][1], tbl_gm_gmk_steampipe_rect[type][2], tbl_gm_gmk_steampipe_rect[type][3]);
			oBS_RECT_WORK.flag |= 4u;
			obj_work.flag &= 4294967293u;
		}
		gMS_GMK_STEAMP_WORK.obj_type = type;
		gMS_GMK_STEAMP_WORK.status = 0;
		obj_work.ppFunc = gmGmkSteamPipeStay;
	}

	public static OBS_OBJECT_WORK gmGmkSteamPipeInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type, ushort model)
	{
		UNREFERENCED_PARAMETER(type);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_STEAMP_WORK(), "Gmk_SteamPipe");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_steampipe_obj_3d_list[model], gMS_ENEMY_3D_WORK.obj_3d);
		oBS_OBJECT_WORK.pos.z = eve_rec.left * 8 * 4096;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.flag |= 2u;
		return oBS_OBJECT_WORK;
