	public static OBS_OBJECT_WORK GmGmkSteamPipeA1Init(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		ushort model = 4;
		if (GMM_MAIN_GET_ZONE_TYPE() == 4)
		{
			model = 4;
		}
