	private static OBS_OBJECT_WORK GmGmkSsSquareInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_SS_SQUARE");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.view_out_ofst -= 128;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_ss_square_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		oBS_OBJECT_WORK.pos.z = -131072;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 2u;
		uint user_flag = (oBS_OBJECT_WORK.user_work = (uint)((eve_rec.flag & 3) + 1));
		oBS_OBJECT_WORK.user_flag = user_flag;
		oBS_OBJECT_WORK.user_timer = MTM_MATH_CLIP(eve_rec.left, 0, 8);
		oBS_OBJECT_WORK.ppFunc = gmGmkSsSquareMain;
		oBS_OBJECT_WORK.ppOut = gmGmkSsSquareDrawFunc;
		OBS_COLLISION_WORK col_work = gMS_ENEMY_3D_WORK.ene_com.col_work;
		col_work.obj_col.obj = oBS_OBJECT_WORK;
		col_work.obj_col.diff_data = g_gm_default_col;
		col_work.obj_col.width = 24;
		col_work.obj_col.height = 24;
		col_work.obj_col.ofst_x = (short)(-(col_work.obj_col.width / 2));
		col_work.obj_col.ofst_y = (short)(-(col_work.obj_col.height / 2));
		col_work.obj_col.attr = 2;
		col_work.obj_col.flag |= 134217760u;
		return oBS_OBJECT_WORK;
	}

	private static void GmGmkSsSquareBounce(OBS_OBJECT_WORK obj_work)
	{
		OBS_COLLISION_OBJ obj_col = obj_work.col_work.obj_col;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		GMS_SPL_STG_WORK gMS_SPL_STG_WORK = GmSplStageGetWork();
		if (obj_col.toucher_obj == gMS_PLAYER_WORK.obj_work)
		{
			if (gMS_PLAYER_WORK.nudge_timer != 0 && (gMS_SPL_STG_WORK.flag & 2) == 0)
			{
				GmPlySeqInitPinballAir(gMS_PLAYER_WORK, 0, -17408, 5, false);
				gMS_SPL_STG_WORK.flag |= 1u;
				gMS_SPL_STG_WORK.flag |= 2u;
			}
			else if ((obj_work.user_flag & 0x80000000u) == 0 && (gMS_SPL_STG_WORK.flag & 1) == 0 && (MTM_MATH_ABS(gMS_PLAYER_WORK.obj_work.spd.x) > 4096 || MTM_MATH_ABS(gMS_PLAYER_WORK.obj_work.spd.y) > 4096))
			{
				OBS_OBJECT_WORK obj_work2 = gMS_PLAYER_WORK.obj_work;
				VecFx32 vecFx = gmGmkSsSquareNormalizeVectorXY(new VecFx32
				{
					x = obj_work2.prev_pos.x - obj_work.pos.x,
					y = obj_work2.prev_pos.y - obj_work.pos.y,
					z = 0
				});
				obj_work2.dir.z = 0;
				int num = MTM_MATH_ABS(obj_work2.spd.x);
				int num2 = MTM_MATH_ABS(obj_work2.spd.y);
				int num3 = FX_Sqrt(FX_Mul(num, num) + FX_Mul(num2, num2));
				num3 /= 2;
				num = FX_Mul(vecFx.x, num3);
				num2 = FX_Mul(vecFx.y, num3);
				GmPlySeqInitPinballAir(gMS_PLAYER_WORK, num, num2, 5, false);
				gMS_SPL_STG_WORK.flag |= 1u;
			}
			obj_work.user_flag |= 2147483648u;
		}
		else
		{
			obj_work.user_flag &= 2147483647u;
		}
	}

	private static void gmGmkSsSquareMain(OBS_OBJECT_WORK obj_work)
	{
		if ((GmSplStageGetWork().flag & 4) != 0)
		{
			obj_work.flag |= 4u;
			return;
		}
		uint num = (uint)(((obj_work.user_timer >> 3) & 0x7F) + 1);
		if (num >= 120)
		{
			num = 0u;
		}
		obj_work.user_timer = (int)((long)(obj_work.user_timer & 7) | (long)(((ulong)num & 0x7FuL) << 3));
		if (obj_work.user_timer != 0)
		{
			uint num2 = (uint)((obj_work.user_timer - 1) & 7);
			uint num3 = (num2 + 2) & 7;
			uint num4 = (g_gm_main_system.sync_time >> 3) & 7;
			if (num2 == num4 || num3 == num4)
			{
				obj_work.user_work = ((obj_work.user_flag - 2) & 3) + 1;
			}
			else
			{
				obj_work.user_work = obj_work.user_flag & 7;
			}
		}
		GmGmkSsSquareBounce(obj_work);
	}

	private static VecFx32 gmGmkSsSquareNormalizeVectorXY(VecFx32 vec)
	{
		VecFx32 result = default(VecFx32);
		int x = FX_Mul(vec.x, vec.x) + FX_Mul(vec.y, vec.y);
		x = FX_Sqrt(x);
		if (x == 0)
		{
			result.x = 4096;
			result.y = 0;
		}
		else
		{
			int v = FX_Div(4096, x);
			result.x = FX_Mul(vec.x, v);
			result.y = FX_Mul(vec.y, v);
		}
		result.z = 0;
		int dest_x = 0;
		int dest_y = 0;
		ObjUtilGetRotPosXY(result.x, result.y, ref dest_x, ref dest_y, (ushort)(-g_gm_main_system.pseudofall_dir));
		result.x = dest_x;
		result.y = dest_y;
		return result;
	}

	private static void gmGmkSsSquareDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		if (GmMainIsDrawEnable() && (obj_work.disp_flag & 0x20) == 0)
		{
			TVX_FILE tVX_FILE;
			if (gm_gmk_ss_square_obj_tvx_list.buf[0] == null)
			{
				tVX_FILE = new TVX_FILE((AmbChunk)amBindGet(gm_gmk_ss_square_obj_tvx_list, 0));
				gm_gmk_ss_square_obj_tvx_list.buf[0] = tVX_FILE;
			}
			else
			{
				tVX_FILE = (TVX_FILE)gm_gmk_ss_square_obj_tvx_list.buf[0];
			}
			NNS_TEXLIST texlist = obj_work.obj_3d.texlist;
			GMS_TVX_EX_WORK ex_work = default(GMS_TVX_EX_WORK);
			uint num = (uint)((obj_work.user_timer >> 5) & 0x1F);
			ex_work.u_wrap = 1;
			ex_work.v_wrap = 1;
			ex_work.coord.u = 0.125f * (float)(gm_gmk_ss_square_uv_parameter[num] % 4) + gm_gmk_ss_square_mat_color[obj_work.user_work - 1].u;
			ex_work.coord.v = 0.125f * (float)(gm_gmk_ss_square_uv_parameter[num] / 4) + gm_gmk_ss_square_mat_color[obj_work.user_work - 1].v;
			ex_work.color = uint.MaxValue;
			GmTvxSetModelEx(tVX_FILE, texlist, ref obj_work.pos, ref obj_work.scale, GMD_TVX_DISP_LIGHT_DISABLE, 0, ref ex_work);
		}
	}

	private static OBS_OBJECT_WORK GmGmkSsArrowInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_SS_ARROW");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.view_out_ofst -= 128;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_ss_arrow_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		oBS_OBJECT_WORK.pos.z = -131072;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 2u;
		oBS_OBJECT_WORK.ppFunc = gmGmkSsArrowMain;
		ObjAction3dNNMaterialMotionLoad(gMS_ENEMY_3D_WORK.obj_3d, 0, null, null, 0, readAMBFile(ObjDataGet(986).pData));
		ObjDrawObjectActionSet3DNNMaterial(oBS_OBJECT_WORK, 0);
		oBS_OBJECT_WORK.dir.z = (ushort)(eve_rec.width << 8);
		int num = (int)(g_gm_main_system.sync_time % 24);
		int num2 = MTM_MATH_CLIP(eve_rec.left, 0, 3) << 3;
		num -= num2;
		if (num < 0)
		{
			num += 24;
		}
		oBS_OBJECT_WORK.user_timer = num;
		gMS_ENEMY_3D_WORK.obj_3d.mat_frame = num;
		return oBS_OBJECT_WORK;
	}

