		{
			TVX_FILE tVX_FILE;
			if (g_gm_gmk_needle_neon_obj_tvx_list.buf[1] == null)
			{
				tVX_FILE = new TVX_FILE((AmbChunk)amBindGet(g_gm_gmk_needle_neon_obj_tvx_list, 1));
