	private static void gmGmkNeedleNeonTvxDrawFunc(TVX_FILE tvx, NNS_TEXLIST texlist, VecFx32 base_pos)
	{
		VecFx32 scale = new VecFx32(4096, 4096, 4096);
		VecFx32 pos = default(VecFx32);
		for (int i = 0; 5 > i; i++)
		{
			pos.x = base_pos.x + g_gm_gmk_disp_offset[i].x;
			pos.y = base_pos.y + g_gm_gmk_disp_offset[i].y;
			pos.z = base_pos.z + g_gm_gmk_disp_offset[i].z;
			GmTvxSetModel(tvx, texlist, ref pos, ref scale, 0u, 0);
		}
	}

