		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_unides_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(692), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.z = 655360;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -8, 0, 8, 16);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		ObjRectWorkSet(oBS_RECT_WORK, -16, -8, 16, 16);
		oBS_RECT_WORK.flag |= 4u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -16, 19, 16);
		oBS_RECT_WORK.flag &= 4294967291u;
		oBS_OBJECT_WORK.move_flag &= 4294967167u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		if ((eve_rec.flag & 1) == 0)
		{
			oBS_OBJECT_WORK.disp_flag |= 1u;
			oBS_OBJECT_WORK.dir.y = (ushort)AKM_DEGtoA16(45);
		}
		else
		{
			oBS_OBJECT_WORK.dir.y = (ushort)AKM_DEGtoA16(-45);
		}
		oBS_OBJECT_WORK.user_work = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left << 12));
		oBS_OBJECT_WORK.user_flag = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left + eve_rec.width << 12));
		gMS_ENE_UNIDES_WORK.spd_dec = 76;
		gMS_ENE_UNIDES_WORK.spd_dec_dist = 15360;
		gMS_ENE_UNIDES_WORK.len = 17.5f;
		gMS_ENE_UNIDES_WORK.rot_x = AKM_DEGtoA32(90f);
		gMS_ENE_UNIDES_WORK.rot_y = AKM_DEGtoA32(0f);
		gMS_ENE_UNIDES_WORK.rot_z = AKM_DEGtoA32(0f);
		gMS_ENE_UNIDES_WORK.num = 0;
		gmEneUnidesWaitInit(oBS_OBJECT_WORK);
		for (int num = 0; num < 4; num++)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GmEventMgrLocalEventBirth(309, pos_x, pos_y, 0, 0, 0, 0, 0, 0);
			oBS_OBJECT_WORK2.parent_obj = oBS_OBJECT_WORK;
			GMS_ENE_UNIDES_WORK gMS_ENE_UNIDES_WORK2 = (GMS_ENE_UNIDES_WORK)oBS_OBJECT_WORK2;
			gMS_ENE_UNIDES_WORK2.num = num;
			gMS_ENE_UNIDES_WORK.num++;
		}
		gMS_ENE_UNIDES_WORK.attack = 0;
		gMS_ENE_UNIDES_WORK.attack_first = 0;
		gMS_ENE_UNIDES_WORK.zoom_now = 0;
		gMS_ENE_UNIDES_WORK.zoom = 1f;
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

