	private static int gmEneUnidesGetLength2N(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
		{
			return int.MaxValue;
		}
		int x = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
		int x2 = gMS_PLAYER_WORK.obj_work.pos.y - obj_work.pos.y;
		float num = FX_FX32_TO_F32(x);
		float num2 = FX_FX32_TO_F32(x2);
		return (int)(num * num + num2 * num2);
	}

	private static void gmEneUnidesWaitInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneUnidesWaitMain;
		obj_work.move_flag &= 4294967291u;
		obj_work.spd.x = 0;
		obj_work.spd.y = 0;
	}

	private static void gmEneUnidesWaitMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_UNIDES_WORK gMS_ENE_UNIDES_WORK = (GMS_ENE_UNIDES_WORK)obj_work;
		if (gmEneUnidesGetLength2N(obj_work) < 9216)
		{
			obj_work.ppFunc = gmEneUnidesAttackInit;
		}
		if ((obj_work.disp_flag & 1) != 0)
		{
			gMS_ENE_UNIDES_WORK.rot_y += AKM_DEGtoA32(1);
		}
		else
		{
			gMS_ENE_UNIDES_WORK.rot_y += AKM_DEGtoA32(-1);
		}
	}

