	}

	private static void gmEneUnidesWalkMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_UNIDES_WORK gMS_ENE_UNIDES_WORK = (GMS_ENE_UNIDES_WORK)obj_work;
		if (gMS_ENE_UNIDES_WORK.timer > 0)
		{
			gMS_ENE_UNIDES_WORK.timer--;
		}
		else if ((obj_work.disp_flag & 1) != 0)
		{
			obj_work.spd.x = -1536;
		}
		else
		{
			obj_work.spd.x = 1536;
		}
	}

