	private static void gmEneUnidesNeedleWaitMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_UNIDES_WORK gMS_ENE_UNIDES_WORK = (GMS_ENE_UNIDES_WORK)obj_work;
		GMS_ENE_UNIDES_WORK gMS_ENE_UNIDES_WORK2 = (GMS_ENE_UNIDES_WORK)obj_work.parent_obj;
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		NNS_MATRIX nNS_MATRIX2 = GlobalPool<NNS_MATRIX>.Alloc();
		NNS_MATRIX nNS_MATRIX3 = GlobalPool<NNS_MATRIX>.Alloc();
		int rot_y = gMS_ENE_UNIDES_WORK2.rot_y;
		int rot_x = gMS_ENE_UNIDES_WORK2.rot_x;
		int rot_z = gMS_ENE_UNIDES_WORK2.rot_z;
		float len = gMS_ENE_UNIDES_WORK2.len;
		rot_y += AKM_DEGtoA32(360) / 4 * gMS_ENE_UNIDES_WORK.num;
		rot_y %= AKM_DEGtoA32(360);
		nnMakeRotateXMatrix(nNS_MATRIX, rot_x);
		nnRotateZMatrix(nNS_MATRIX, nNS_MATRIX, rot_z);
		nnRotateYMatrix(nNS_MATRIX, nNS_MATRIX, rot_y);
		nnMakeTranslateMatrix(nNS_MATRIX2, len, 0f, 0f);
		nnMultiplyMatrix(nNS_MATRIX3, nNS_MATRIX, nNS_MATRIX2);
		SNNS_VECTOR dst;
		nnCopyMatrixTranslationVector(out dst, nNS_MATRIX3);
		obj_work.pos.x = FX_F32_TO_FX32(dst.x) + gMS_ENE_UNIDES_WORK2.ene_3d_work.ene_com.obj_work.pos.x;
		obj_work.pos.y = FX_F32_TO_FX32(dst.y) + gMS_ENE_UNIDES_WORK2.ene_3d_work.ene_com.obj_work.pos.y;
		obj_work.pos.z = 655360;
		if (gMS_ENE_UNIDES_WORK2.attack != 0 && (double)dst.y >= (double)len * 0.98 && gMS_ENE_UNIDES_WORK2.stop == 0)
		{
			if (gMS_ENE_UNIDES_WORK2.attack_first != 0)
			{
				obj_work.ppFunc = gmEneUnidesNeedleAttackInit;
			}
			else
			{
				gMS_ENE_UNIDES_WORK2.zoom_now = 1;
				gMS_ENE_UNIDES_WORK2.attack_first = 1;
				gMS_ENE_UNIDES_WORK2.stop = 1;
			}
		}
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX2);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX3);
	}

	private static void gmEneUnidesNeedleAttackInit(OBS_OBJECT_WORK obj_work)
