		GMS_ENE_UNIDES_WORK gMS_ENE_UNIDES_WORK = (GMS_ENE_UNIDES_WORK)obj_work.parent_obj;
		gMS_ENE_UNIDES_WORK.num--;
		if ((gMS_ENE_UNIDES_WORK.ene_3d_work.ene_com.obj_work.disp_flag & 1) != 0)
		{
			obj_work.spd.x = -FX_F32_TO_FX32(1f);
		}
		else
		{
			obj_work.spd.x = FX_F32_TO_FX32(1f);
		}
		obj_work.parent_obj = null;
		obj_work.ppFunc = gmEneUnidesNeedleAttackMain;
	}

