	public static OBS_OBJECT_WORK GmEneKaniInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENE_KANI_WORK(), "ENE_KANI");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_ENE_KANI_WORK gMS_ENE_KANI_WORK = (GMS_ENE_KANI_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_kani_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(686), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.z = 0;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -11, -24, 11, 0);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -32, 19, 0);
		oBS_RECT_WORK.flag |= 4u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -32, 19, 0);
		oBS_RECT_WORK.flag &= 4294967291u;
		ObjObjectFieldRectSet(oBS_OBJECT_WORK, -4, -8, 4, -2);
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.move_flag |= 128u;
		gMS_ENE_KANI_WORK.walk_s = 0;
		if ((eve_rec.flag & 1) != 0)
		{
			gMS_ENE_KANI_WORK.walk_s = 1;
		}
		oBS_OBJECT_WORK.user_work = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left << 12));
		oBS_OBJECT_WORK.user_flag = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left + eve_rec.width << 12));
		gMS_ENE_KANI_WORK.spd_dec = 102;
		gMS_ENE_KANI_WORK.spd_dec_dist = 20480;
		gmEneKaniWalkInit(oBS_OBJECT_WORK);
		GmEneUtilInitNodeMatrix(gMS_ENE_KANI_WORK.node_work, oBS_OBJECT_WORK, 3);
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmEneExit);
		GmEneUtilGetNodeMatrix(gMS_ENE_KANI_WORK.node_work, 16);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		oBS_OBJECT_WORK.flag |= 1073741824u;
		gMS_ENE_KANI_WORK.ata_futa = 0;
		return oBS_OBJECT_WORK;
	}

	public static int gmEneKaniGetLength2N(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
		{
			return int.MaxValue;
		}
		int x = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
		int x2 = gMS_PLAYER_WORK.obj_work.pos.y - obj_work.pos.y;
		float num = FX_FX32_TO_F32(x);
		float num2 = FX_FX32_TO_F32(x2);
		return (int)(num * num + num2 * num2);
	}

	public static int gmEneKaniIsPlayerLeft(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		return GmEneComTargetIsLeft(obj_work, gMS_PLAYER_WORK.obj_work);
	}

	public static void gmEneKaniWalkInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GmEneComActionSetDependHFlip(obj_work, 2, 2);
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneKaniWalkMain;
		obj_work.move_flag &= 4294967291u;
		if ((obj_work.disp_flag & 1) != 0)
		{
			obj_work.spd.x = -2048;
		}
		else
		{
			obj_work.spd.x = 2048;
		}
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -11, -24, 11, 0);
		oBS_RECT_WORK.flag |= 4u;
		GMS_ENE_KANI_WORK gMS_ENE_KANI_WORK = (GMS_ENE_KANI_WORK)obj_work;
		if (gMS_ENE_KANI_WORK.walk_s != 0)
		{
			gMS_ENE_KANI_WORK.timer = 15;
		}
		else
		{
			gMS_ENE_KANI_WORK.timer = 10 + mtMathRand() % 20;
		}
	}

	public static void gmEneKaniWalkMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_KANI_WORK gMS_ENE_KANI_WORK = (GMS_ENE_KANI_WORK)obj_work;
		if (gMS_ENE_KANI_WORK.ata_futa != 0)
		{
			if (gMS_ENE_KANI_WORK.timer > 0)
			{
				gMS_ENE_KANI_WORK.timer--;
				return;
			}
			obj_work.obj_3d.speed[0] = 2f;
			obj_work.disp_flag ^= 1u;
			if ((obj_work.disp_flag & 1) != 0)
			{
				obj_work.spd.x = -2048;
			}
			else
			{
				obj_work.spd.x = 2048;
			}
			obj_work.ppFunc = gmEneKaniWalkMain;
			if (gMS_ENE_KANI_WORK.walk_s != 0)
			{
				gMS_ENE_KANI_WORK.timer = 15;
			}
			else
			{
				gMS_ENE_KANI_WORK.timer = 10 + mtMathRand() % 20;
			}
		}
		else
		{
			obj_work.obj_3d.speed[0] = 1f;
			if ((obj_work.move_flag & 4) != 0 || GmEneComCheckMoveLimit(obj_work, (int)obj_work.user_work, (int)obj_work.user_flag) == 0)
			{
				gmEneKaniFlipInit(obj_work);
				gMS_ENE_KANI_WORK.timer = 0;
			}
		}
		if (gmEneKaniIsPlayerLeft(obj_work) != 0)
		{
			gMS_ENE_KANI_WORK.ata_futa = 0;
			if (gmEneKaniGetLength2N(obj_work) < 8464)
			{
				obj_work.ppFunc = gmEneKaniAttackInit;
			}
		}
		else
		{
			gMS_ENE_KANI_WORK.ata_futa = 1;
		}
	}

	public static void gmEneKaniAttackInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		ObjDrawObjectActionSet(obj_work, 0);
		obj_work.disp_flag &= 4294967291u;
		obj_work.ppFunc = gmEneKaniAttackMain;
		obj_work.spd.x = 0;
		GmSoundPlaySE("Kani");
	}

	public static void gmEneKaniAttackMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		GMS_ENE_KANI_WORK gMS_ENE_KANI_WORK = (GMS_ENE_KANI_WORK)obj_work;
		NNS_MATRIX nNS_MATRIX = GmEneUtilGetNodeMatrix(gMS_ENE_KANI_WORK.node_work, 16);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		nNS_VECTOR.x = nNS_MATRIX.M03 - FX_FX32_TO_F32(obj_work.pos.x);
		nNS_VECTOR.y = nNS_MATRIX.M13 - FX_FX32_TO_F32(-obj_work.pos.y);
		nNS_VECTOR.z = nNS_MATRIX.M23 - FX_FX32_TO_F32(obj_work.pos.z);
		if ((obj_work.disp_flag & 1) != 0)
		{
			nNS_VECTOR.x = 0f - nNS_VECTOR.x;
		}
		ObjRectWorkSet(oBS_RECT_WORK, (short)(-11 + (short)nNS_VECTOR.x), (short)(-24 - (short)nNS_VECTOR.y), (short)(11 + (short)nNS_VECTOR.x), (short)(-(short)nNS_VECTOR.y));
		oBS_RECT_WORK.flag |= 4u;
		if (GmBsCmnIsActionEnd(obj_work) != 0)
		{
			obj_work.ppFunc = gmEneKaniAttackEnd;
			ObjDrawObjectActionSet(obj_work, 1);
		}
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	public static void gmEneKaniAttackEnd(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		GMS_ENE_KANI_WORK gMS_ENE_KANI_WORK = (GMS_ENE_KANI_WORK)obj_work;
		NNS_MATRIX nNS_MATRIX = GmEneUtilGetNodeMatrix(gMS_ENE_KANI_WORK.node_work, 16);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		nNS_VECTOR.x = nNS_MATRIX.M03 - FX_FX32_TO_F32(obj_work.pos.x);
		nNS_VECTOR.y = nNS_MATRIX.M13 - FX_FX32_TO_F32(-obj_work.pos.y);
		nNS_VECTOR.z = nNS_MATRIX.M23 - FX_FX32_TO_F32(obj_work.pos.z);
		if ((obj_work.disp_flag & 1) != 0)
		{
			nNS_VECTOR.x = 0f - nNS_VECTOR.x;
		}
		ObjRectWorkSet(oBS_RECT_WORK, (short)(-11 + (short)nNS_VECTOR.x), (short)(-24 - (short)nNS_VECTOR.y), (short)(11 + (short)nNS_VECTOR.x), (short)(-(short)nNS_VECTOR.y));
		oBS_RECT_WORK.flag |= 4u;
		if (GmBsCmnIsActionEnd(obj_work) != 0)
		{
			obj_work.ppFunc = gmEneKaniWalkInit;
		}
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	public static void gmEneKaniFwMain(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_timer = ObjTimeCountDown(obj_work.user_timer);
