	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(tcb);
		GMS_ENE_KANI_WORK gMS_ENE_KANI_WORK = (GMS_ENE_KANI_WORK)oBS_OBJECT_WORK;
