	{
		if (gmClearDemoIsTexLoad())
		{
			return true;
		}
		return false;
	}

	private static void GmClearDemoFlush()
	{
		for (int i = 0; i < 2; i++)
		{
			AoTexRelease(gm_clrdm_tex[i]);
		}
	}

	private static bool GmClearDemoFlushCheck()
	{
