	private static void GmClearDemoRetryStart()
	{
		gmClearDemoRetryInit();
	}

	private static void gmClearDemoInit()
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		MTS_TASK_TCB mTS_TASK_TCB = MTM_TASK_MAKE_TCB(gmClearDemoProcMain, gmClearDemoDest, 0u, 0, 18448u, 5, () => new GMS_CLRDM_MAIN_WORK(), "CLRDM_MAIN");
		gm_clrdm_mgr_p.tcb = mTS_TASK_TCB;
		GMS_CLRDM_MAIN_WORK gMS_CLRDM_MAIN_WORK = (GMS_CLRDM_MAIN_WORK)mTS_TASK_TCB.work;
		for (int num = 0; num < 2; num++)
		{
			gMS_CLRDM_MAIN_WORK.tex[num] = gm_clrdm_tex[num];
		}
		gMS_CLRDM_MAIN_WORK.trg_retry.Constructor();
		gMS_CLRDM_MAIN_WORK.trg_back.Constructor();
		gMS_CLRDM_MAIN_WORK.count = 1;
		gMS_CLRDM_MAIN_WORK.stage_id = gSS_MAIN_SYS_INFO.stage_id;
		gMS_CLRDM_MAIN_WORK.game_mode = gSS_MAIN_SYS_INFO.game_mode;
		if (gMS_CLRDM_MAIN_WORK.stage_id <= 20)
		{
			gMS_CLRDM_MAIN_WORK.is_clear_spe_stg = false;
			gmClearDemoSetPlayGameScore(gMS_CLRDM_MAIN_WORK);
		}
		else
		{
			gMS_CLRDM_MAIN_WORK.is_clear_spe_stg = true;
			gmClearDemoSetSpecialStageScore(gMS_CLRDM_MAIN_WORK);
			gmClearDemoSetSpecialStageClearInfo(gMS_CLRDM_MAIN_WORK);
		}
		gmClearDemoSetSaveScoreData(gMS_CLRDM_MAIN_WORK);
		if (gMS_CLRDM_MAIN_WORK.stage_id >= 21 && gMS_CLRDM_MAIN_WORK.stage_id < 29)
		{
			if (gMS_CLRDM_MAIN_WORK.game_mode == 0)
			{
				gmClearDemoCreateObjSpeScore(gMS_CLRDM_MAIN_WORK);
				gmClearDemoCreateObjSpecialScoreAtk(gMS_CLRDM_MAIN_WORK);
				gmClearDemoSetInitDispAct(gMS_CLRDM_MAIN_WORK);
			}
			else
			{
				gmClearDemoCreateObjSpeTime(gMS_CLRDM_MAIN_WORK);
				gmClearDemoCreateObjSpecialTimeAtk(gMS_CLRDM_MAIN_WORK);
			}
		}
		else if (gMS_CLRDM_MAIN_WORK.game_mode == 0)
		{
			gmClearDemoCreateObjActScore(gMS_CLRDM_MAIN_WORK);
			gmClearDemoCreateObjAct(gMS_CLRDM_MAIN_WORK);
			gmClearDemoSetInitDispAct(gMS_CLRDM_MAIN_WORK);
		}
		else
		{
			gmClearDemoCreateObjActTime(gMS_CLRDM_MAIN_WORK);
			gmClearDemoCreateObjNormalTimeAtk(gMS_CLRDM_MAIN_WORK);
		}
		if (gSS_MAIN_SYS_INFO.stage_id >= 16 && gSS_MAIN_SYS_INFO.stage_id <= 20)
		{
			GmSoundPlayClearFinal();
		}
		else
		{
			GmSoundPlayClear();
		}
		gmClearDemoSetMainUpdateProc(gMS_CLRDM_MAIN_WORK);
	}

	private static void gmClearDemoRetryInit()
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		MTS_TASK_TCB mTS_TASK_TCB = MTM_TASK_MAKE_TCB(gmClearDemoProcMain, gmClearDemoDest, 0u, 0, 18448u, 5, () => new GMS_CLRDM_MAIN_WORK(), "CLRDM_MAIN");
		gm_clrdm_mgr_p.tcb = mTS_TASK_TCB;
		GMS_CLRDM_MAIN_WORK gMS_CLRDM_MAIN_WORK = (GMS_CLRDM_MAIN_WORK)mTS_TASK_TCB.work;
		for (int num = 0; num < 2; num++)
		{
			gMS_CLRDM_MAIN_WORK.tex[num] = gm_clrdm_tex[num];
		}
		gMS_CLRDM_MAIN_WORK.trg_retry.Constructor();
		gMS_CLRDM_MAIN_WORK.trg_back.Constructor();
		gMS_CLRDM_MAIN_WORK.count = 1;
		gMS_CLRDM_MAIN_WORK.stage_id = gSS_MAIN_SYS_INFO.stage_id;
		if (gMS_CLRDM_MAIN_WORK.stage_id >= 21)
		{
			gMS_CLRDM_MAIN_WORK.is_clear_spe_stg = true;
		}
		else
		{
			gMS_CLRDM_MAIN_WORK.is_clear_spe_stg = false;
		}
		gMS_CLRDM_MAIN_WORK.game_mode = gSS_MAIN_SYS_INFO.game_mode;
		gmClearDemoCreateObjActTime(gMS_CLRDM_MAIN_WORK);
		gmClearDemoCreateObjNormalTimeAtk(gMS_CLRDM_MAIN_WORK);
		gmClearDemoSetRetryInitAct(gMS_CLRDM_MAIN_WORK);
		gMS_CLRDM_MAIN_WORK.proc_update = gmClearDemoProcRetryStart;
	}

	private static void gmClearDemoSetMainUpdateProc(GMS_CLRDM_MAIN_WORK main_work)
