		}
		else
		{
			main_work.proc_update = gmClearDemoProcTimeMoveEfct;
			gmClearDemoSetClearTimeRecord(main_work);
			gmClearDemoSetSortBufTimeAct(main_work);
			main_work.tex_new_record_act.obj_2d.speed = 0f;
		}
	}

