		{
			SSpecial sSpecial = SSpecial.CreateInstance();
			num = (uint)(main_work.stage_id - 21);
			GMM_MAIN_GOAL_AS_SUPER_SONIC();
			if (gSS_MAIN_SYS_INFO.game_mode == 0)
			{
				num2 = ((main_work.total_score[0] >= 10) ? main_work.total_score[0] : 0u);
				if ((g_gm_main_system.game_flag & 0x10000) != 0 && !main_work.is_first_spe_clear)
				{
					GmPlayerStockGet(g_gm_main_system.ply_work[0], 1);
				}
				int index = main_work.stage_id - 4;
				bool flag2 = LiveFeature.getInstance().saveLeaderBoardScore(index, (int)num2);
				sSpecial[(int)num].SetHighScoreUploaded(flag2);
				if (flag2 && !sSpecial[(int)num].IsScoreUploadedOnce())
				{
					sSpecial[(int)num].SetScoreUploadedOnce(true);
				}
				if ((sSpecial[(int)num].GetHighScore() < num2 || sSpecial[(int)num].GetHighScore() == 1000000000) && (g_gm_main_system.game_flag & 0x10000) != 0)
				{
					sSpecial[(int)num].SetHighScore(num2);
					main_work.flag |= 32768u;
				}
			}
			else if (gSS_MAIN_SYS_INFO.game_mode == 1)
			{
				if ((g_gm_main_system.game_flag & 0x10000) != 0 && !main_work.is_first_spe_clear)
				{
					GmPlayerStockGet(g_gm_main_system.ply_work[0], 1);
				}
				bool flag3 = false;
				if ((g_gm_main_system.game_flag & 0x10000) != 0)
				{
