				}
				if ((sSpecial[(int)num].GetFastTime() < (uint)gSS_MAIN_SYS_INFO.clear_time || sSpecial[(int)num].GetFastTime() == 36000) && (g_gm_main_system.game_flag & 0x10000) != 0)
				{
					sSpecial[(int)num].SetFastTime((uint)gSS_MAIN_SYS_INFO.clear_time);
					main_work.flag |= 4096u;
				}
			}
		}
		else
		{
			SStage sStage = SStage.CreateInstance();
			num = main_work.stage_id;
			if (num > 16 && num <= 20)
			{
				num = 16u;
			}
			flag = (GMM_MAIN_USE_SUPER_SONIC() ? true : false);
			if (GMM_MAIN_GOAL_AS_SUPER_SONIC())
			{
				sStage[(int)num].SetUseSuperSonicOnce(true);
			}
			if (gSS_MAIN_SYS_INFO.game_mode == 0)
			{
				num2 = ((main_work.total_score[0] >= 10) ? main_work.total_score[0] : 0u);
				if (sStage[(int)num].GetHighScore(false) == 1000000000)
				{
					g_gs_main_sys_info.is_first_play = true;
				}
				else
				{
					g_gs_main_sys_info.is_first_play = false;
				}
				if (sStage[(int)num].GetHighScore(flag) < num2 || sStage[(int)num].GetHighScore(flag) == 1000000000)
				{
					sStage[(int)num].SetHighScore(num2, flag);
				}
				int index3 = (int)num;
				bool flag4 = LiveFeature.getInstance().saveLeaderBoardScore(index3, (int)num2);
				sStage[(int)num].SetHighScoreUploaded(flag, flag4);
				if (flag4 && !sStage[(int)num].IsScoreUploadedOnce())
				{
					sStage[(int)num].SetScoreUploadedOnce(true);
				}
				if ((g_gm_main_system.game_flag & 0x4000) != 0)
				{
					g_gs_main_sys_info.prev_stage_id = g_gs_main_sys_info.stage_id;
				}
				else
				{
					g_gs_main_sys_info.prev_stage_id = ushort.MaxValue;
				}
			}
			else if (gSS_MAIN_SYS_INFO.game_mode == 1 && (sStage[(int)num].GetFastTime(flag) > (uint)gSS_MAIN_SYS_INFO.clear_time || sStage[(int)num].GetFastTime(flag) == 36000))
			{
				if (flag)
				{
					if (sStage[(int)num].GetFastTime(false) > (uint)gSS_MAIN_SYS_INFO.clear_time || sStage[(int)num].GetFastTime(false) == 36000)
					{
						main_work.flag |= 4096u;
					}
				}
				else if (sStage[(int)num].GetFastTime(true) > (uint)gSS_MAIN_SYS_INFO.clear_time || sStage[(int)num].GetFastTime(true) == 36000)
				{
					main_work.flag |= 4096u;
				}
				sStage[(int)num].SetFastTime((uint)gSS_MAIN_SYS_INFO.clear_time, flag);
				int index4 = (int)(num + 24);
				bool flag5 = LiveFeature.getInstance().saveLeaderBoardScore(index4, gSS_MAIN_SYS_INFO.clear_time);
				sStage[(int)num].SetFastTimeUploaded(flag, flag5);
				if (flag5 && !sStage[(int)num].IsTimeUploadedOnce())
				{
					sStage[(int)num].SetTimeUploadedOnce(true);
				}
			}
		}
		sSystem.SetKilled(gSS_MAIN_SYS_INFO.ene_kill_count);
		sSystem.SetPlayerStock(gSS_MAIN_SYS_INFO.rest_player_num);
		if (gSS_MAIN_SYS_INFO.stage_id >= 16 && gSS_MAIN_SYS_INFO.stage_id <= 20)
		{
			HgTrophyIncFinalClearCount();
			sSystem.SetClearCount(gSS_MAIN_SYS_INFO.final_clear_count);
		}
		HgTrophyTryAcquisition(4);
	}

