	private static uint gmClearDemoGetTimeScore(int clear_time)
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		uint result = 0u;
		ushort min = 0;
		ushort sec = 0;
		ushort msec = 0;
		int num = 0;
		int num2 = 0;
		AkUtilFrame60ToTime((uint)clear_time, ref min, ref sec, ref msec);
		num2 = min * 60 + sec;
		for (num = 0; num < 9; num++)
		{
			if (num2 < dm_clrdm_clear_time_sec_tbl[gSS_MAIN_SYS_INFO.stage_id][num])
			{
				result = dm_clrdm_clear_time_score_tbl[num];
				break;
			}
		}
		if ((g_gs_main_sys_info.game_flag & 8) != 0)
		{
			result = 0u;
		}
		return result;
	}

