	private static void gmClearDemoSetRetryInput(GMS_CLRDM_MAIN_WORK main_work)
	{
		if (isBackKeyPressed())
		{
			main_work.flag |= 2u;
			setBackKeyRequest(false);
			GmSoundPlaySE("Ok");
			return;
		}
		CTrgAoAction trg_retry = main_work.trg_retry;
		trg_retry.Update();
		if (trg_retry.GetState(0u)[10] && trg_retry.GetState(0u)[1])
		{
			main_work.flag |= 4u;
			int i = 0;
			for (int num = arrayof(main_work.btn_retry); i < num; i++)
			{
				main_work.btn_retry[i].obj_2d.frame = 2f;
				main_work.btn_retry[i].obj_2d.speed = 1f;
			}
			GmSoundPlaySE("Ok");
		}
		else if (trg_retry.GetState(0u)[0])
		{
			int j = 0;
			for (int num2 = arrayof(main_work.btn_retry); j < num2; j++)
			{
				main_work.btn_retry[j].obj_2d.frame = 1f;
			}
		}
		else if (trg_retry.GetState(0u)[13])
		{
			int k = 0;
			for (int num3 = arrayof(main_work.btn_retry); k < num3; k++)
			{
				main_work.btn_retry[k].obj_2d.frame = 0f;
			}
		}
		CTrgAoAction trg_back = main_work.trg_back;
		trg_back.Update();
		if (trg_back.GetState(0u)[10] && trg_back.GetState(0u)[1])
		{
			main_work.flag |= 2u;
			int l = 0;
			for (int num4 = arrayof(main_work.btn_back); l < num4; l++)
			{
				main_work.btn_back[l].obj_2d.frame = 2f;
				main_work.btn_back[l].obj_2d.speed = 1f;
			}
			GmSoundPlaySE("Ok");
		}
		else if (trg_back.GetState(0u)[2])
		{
			int m = 0;
			for (int num5 = arrayof(main_work.btn_back); m < num5; m++)
			{
				main_work.btn_back[m].obj_2d.frame = 1f;
			}
		}
		else if (trg_back.GetState(0u)[13])
		{
			int n = 0;
			for (int num6 = arrayof(main_work.btn_back); n < num6; n++)
			{
				main_work.btn_back[n].obj_2d.frame = 0f;
			}
		}
	}

