	private static void gmClearDemoSetSortBufScoreAct(GMS_COCKPIT_2D_WORK[] score_act, uint score, uint digits)
	{
		int num = 0;
		int num2 = 0;
		int num3 = 1;
		if (score < 10)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK;
			for (num = 0; num < (int)(digits - 1); num++)
			{
				oBS_OBJECT_WORK = (OBS_OBJECT_WORK)score_act[num];
				oBS_OBJECT_WORK.disp_flag |= 32u;
			}
			oBS_OBJECT_WORK = (OBS_OBJECT_WORK)score_act[digits - 1];
			oBS_OBJECT_WORK.disp_flag &= 4294967263u;
		}
		else
		{
			if (score < 10)
			{
				return;
			}
			for (num = 0; num < (int)digits; num++)
			{
				for (num2 = 0; num2 < (int)(digits - num - 1); num2++)
				{
					num3 *= 10;
				}
				if (score < (uint)num3)
				{
					OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)score_act[num];
					oBS_OBJECT_WORK.disp_flag |= 32u;
				}
				else
				{
					OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)score_act[num];
					oBS_OBJECT_WORK.disp_flag &= 4294967263u;
				}
				num3 = 1;
			}
		}
	}

