		{
			main_work.proc_calc_score = null;
			amFlagOn(ref main_work.flag, 8u);
			return;
		}
		if (main_work.time_score[1] != 0)
		{
			main_work.time_score[1] -= 100u;
			main_work.total_score[1] += 100u;
		}
		if (main_work.ring_score[1] != 0)
		{
