	private static void gmClearDemoSetDispScore(GMS_COCKPIT_2D_WORK[] score_act, uint score, uint digits)
	{
		int num = 0;
		int num2 = 0;
		float num3 = 0f;
		int num4 = 1;
		for (num = 0; num < 1; num++)
		{
			score_act[digits - 1 - num].obj_2d.frame = 0f;
			score_act[digits - 1 - num].obj_2d.speed = 0f;
		}
		for (num = 1; num < (int)digits; num++)
		{
			for (num2 = 0; num2 < num; num2++)
			{
				num4 *= 10;
			}
			if (score >= (uint)num4)
			{
				num3 = score / num4;
				num3 = (int)num3 % 10;
				score_act[digits - 1 - num].obj_2d.frame = num3;
				score_act[digits - 1 - num].obj_2d.speed = 0f;
			}
			else
			{
				score_act[digits - 1 - num].obj_2d.frame = 0f;
				score_act[digits - 1 - num].obj_2d.speed = 0f;
			}
			num4 = 1;
		}
	}

	private static void gmClearDemoSetFlashSonic(GMS_CLRDM_MAIN_WORK main_work)
	{
		if ((main_work.flag & 0x40) != 0)
		{
			if (main_work.flash_timer >= 30f)
			{
				amFlagOff(ref main_work.flag, 64u);
				main_work.flash_timer = 0f;
			}
		}
		else if (main_work.flash_timer >= 10f)
		{
			amFlagOn(ref main_work.flag, 64u);
			main_work.flash_timer = 0f;
		}
		main_work.flash_timer += main_work.count;
	}

