	public static OBS_OBJECT_WORK GmBoss5TurretInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		UNREFERENCED_PARAMETER(type);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_BOSS5_TURRET_WORK(), "BOSS5_TRT");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_BOSS5_TURRET_WORK trt_work = (GMS_BOSS5_TURRET_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, GmBoss5GetObject3dList()[0], gMS_ENEMY_3D_WORK.obj_3d);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.obj_3d.blend_spd = GMD_BOSS5_DEFAULT_BLEND_SPD;
		oBS_OBJECT_WORK.flag |= 18u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 32768u;
		gmBoss5TurretInitDispRot(trt_work);
		oBS_OBJECT_WORK.ppFunc = gmBoss5TurretMain;
		gmBoss5TurretProcInit(trt_work);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

