	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GmEventMgrLocalEventBirth(333, oBS_OBJECT_WORK.pos.x, oBS_OBJECT_WORK.pos.y, 0, 0, 0, 0, 0, 0);
		oBS_OBJECT_WORK2.parent_obj = oBS_OBJECT_WORK;
		return (GMS_BOSS5_TURRET_WORK)oBS_OBJECT_WORK2;
	}

	public static void gmBoss5TurretGetDispRotatedOfstPos(GMS_BOSS5_TURRET_WORK trt_work, ref VecFx32 src_ofst_pos, out VecFx32 dest_ofst_pos)
	{
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		amVectorSet(nNS_VECTOR, FX_FX32_TO_F32(src_ofst_pos.x), FX_FX32_TO_F32(-src_ofst_pos.y), FX_FX32_TO_F32(src_ofst_pos.z));
		nnMakeQuaternionMatrix(nNS_MATRIX, ref trt_work.disp_quat);
		nnTransformVector(nNS_VECTOR, nNS_MATRIX, nNS_VECTOR);
		dest_ofst_pos = new VecFx32(FX_F32_TO_FX32(nNS_VECTOR.x), FX_F32_TO_FX32(0f - nNS_VECTOR.y), FX_F32_TO_FX32(nNS_VECTOR.z));
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
	}

	public static void gmBoss5TurretGetVulcanFirePos(GMS_BOSS5_TURRET_WORK trt_work, ref VecFx32 out_pos)
	{
		VecFx32 src_ofst_pos = new VecFx32(0, 0, GMD_BOSS5_TURRET_VULCAN_FIRE_OFST_FORWARD);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(trt_work);
		VecFx32 dest_ofst_pos;
		gmBoss5TurretGetDispRotatedOfstPos(trt_work, ref src_ofst_pos, out dest_ofst_pos);
		VEC_Set(ref out_pos, oBS_OBJECT_WORK.pos.x + dest_ofst_pos.x, oBS_OBJECT_WORK.pos.y + dest_ofst_pos.y, oBS_OBJECT_WORK.pos.z + GMD_BOSS5_TURRET_VULCAN_FIRE_OFST_Z);
	}

	public static void gmBoss5TurretGetVulcanBulletPos(GMS_BOSS5_TURRET_WORK trt_work, ref VecFx32 out_pos)
	{
		VecFx32 src_ofst_pos = new VecFx32(0, 0, GMD_BOSS5_TURRET_VULCAN_BULLET_OFST_FORWARD);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(trt_work);
		VecFx32 dest_ofst_pos;
		gmBoss5TurretGetDispRotatedOfstPos(trt_work, ref src_ofst_pos, out dest_ofst_pos);
		VEC_Set(ref out_pos, oBS_OBJECT_WORK.pos.x + dest_ofst_pos.x, oBS_OBJECT_WORK.pos.y + dest_ofst_pos.y, oBS_OBJECT_WORK.pos.z + GMD_BOSS5_TURRET_VULCAN_BULLET_OFST_Z);
	}

	public static void gmBoss5TurretInitDispRot(GMS_BOSS5_TURRET_WORK trt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(trt_work);
		oBS_OBJECT_WORK.disp_flag &= 4278190079u;
		nnMakeUnitQuaternion(ref trt_work.disp_quat);
		nnMakeUnitMatrix(oBS_OBJECT_WORK.obj_3d.user_obj_mtx_r);
	}

	public static void gmBoss5TurretUpdateDispRot(GMS_BOSS5_TURRET_WORK trt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(trt_work);
		oBS_OBJECT_WORK.disp_flag |= 16777216u;
		nnMakeQuaternionMatrix(oBS_OBJECT_WORK.obj_3d.user_obj_mtx_r, ref trt_work.disp_quat);
	}

	public static void gmBoss5TurretUpdateDirFollowingPos(GMS_BOSS5_TURRET_WORK trt_work, ref VecFx32 targ_pos, float deg)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(trt_work);
		int num = (int)(0xFFFFL & (long)nnArcTan2(FX_FX32_TO_F32(targ_pos.y - oBS_OBJECT_WORK.pos.y), FX_FX32_TO_F32(targ_pos.x - oBS_OBJECT_WORK.pos.x)));
		int num2 = (int)(0xFFFFL & (long)(num - trt_work.fire_dir_z));
		int num3;
		if (num2 >= AKM_DEGtoA32(180))
		{
			num2 = -(AKM_DEGtoA32(360) - num2);
			num3 = AKM_DEGtoA32(0f - deg);
		}
		else
		{
			num3 = AKM_DEGtoA32(deg);
		}
		if (MTM_MATH_ABS(num2) <= MTM_MATH_ABS(num3))
		{
			num3 = num2;
		}
		trt_work.fire_dir_z = (short)(0xFFFFL & (long)(trt_work.fire_dir_z + num3));
	}

	public static void gmBoss5TurretSetRoundFaceRot(GMS_BOSS5_TURRET_WORK trt_work, int dir_z_angle, int tilt_near_angle)
	{
		int rz = (int)(0xFFFFL & (long)(-dir_z_angle));
		nnMakeRotateXZYQuaternion(out trt_work.disp_quat, AKM_DEGtoA32(90), -tilt_near_angle, AKM_DEGtoA32(90));
		NNS_QUATERNION dst;
		nnMakeRotateXYZQuaternion(out dst, 0, 0, rz);
		nnMultiplyQuaternion(ref trt_work.disp_quat, ref dst, ref trt_work.disp_quat);
	}

	public static void gmBoss5TurretUpdateDirFacePly(GMS_BOSS5_TURRET_WORK trt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GmBsCmnGetPlayerObj();
		gmBoss5TurretUpdateDirFollowingPos(trt_work, ref oBS_OBJECT_WORK.pos, GMD_BOSS5_TURRET_FACE_PLY_SPD_DEG);
		float num = nnSin(trt_work.fire_dir_z);
		if (num < 0f)
		{
			num = 0f;
		}
		int tilt_near_angle = (int)(num * (float)(0xFFFFL & (long)GMD_BOSS5_TURRET_TILT_NEAR_ANGLE));
		gmBoss5TurretSetRoundFaceRot(trt_work, trt_work.fire_dir_z, tilt_near_angle);
	}

	public static void gmBoss5TurretInitVulcanBurstShot(GMS_BOSS5_TURRET_WORK trt_work, int shot_num)
	{
		trt_work.vul_shot_remain = shot_num;
		trt_work.vul_burst_timer = GMD_BOSS5_TURRET_VULCAN_SHOT_INTERVAL;
		trt_work.vul_shot_angle = trt_work.fire_dir_z;
		gmBoss5TurretGetVulcanFirePos(trt_work, ref trt_work.vul_fire_pos);
		gmBoss5TurretGetVulcanBulletPos(trt_work, ref trt_work.vul_bullet_pos);
	}

	public static int gmBoss5TurretUpdateVulcanBurstShot(GMS_BOSS5_TURRET_WORK trt_work)
	{
		if (trt_work.vul_shot_remain != 0)
		{
			if (trt_work.vul_burst_timer != 0)
			{
				trt_work.vul_burst_timer--;
			}
			else
			{
				gmBoss5TurretGetVulcanFirePos(trt_work, ref trt_work.vul_fire_pos);
				gmBoss5TurretGetVulcanBulletPos(trt_work, ref trt_work.vul_bullet_pos);
				GmBoss5EfctCreateVulcanFire(trt_work, trt_work.vul_fire_pos, trt_work.vul_shot_angle);
				GmBoss5EfctCreateVulcanBullet(trt_work, trt_work.vul_bullet_pos, trt_work.vul_shot_angle, GMD_BOSS5_TURRET_VULCAN_BULLET_SPD);
				trt_work.vul_shot_remain--;
				trt_work.vul_burst_timer = GMD_BOSS5_TURRET_VULCAN_SHOT_INTERVAL;
			}
			return 0;
		}
		return 1;
	}

	public static void gmBoss5TurretClearVulcanBurstShot(GMS_BOSS5_TURRET_WORK trt_work)
	{
		trt_work.vul_shot_remain = 0;
		trt_work.vul_burst_timer = 0;
	}

	public static void gmBoss5TurretInitPartsPose(GMS_BOSS5_TURRET_WORK trt_work)
	{
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)GMM_BS_OBJ(trt_work).parent_obj;
		int[] array = new int[2] { gMS_BOSS5_BODY_WORK.pole_cnm_reg_id, gMS_BOSS5_BODY_WORK.cover_cnm_reg_id };
		int num = 2;
		nnMakeUnitMatrix(nNS_MATRIX);
		for (int i = 0; i < num; i++)
		{
			GmBsCmnChangeCNMModeNode(gMS_BOSS5_BODY_WORK.cnm_mgr_work, array[i], 1u);
			GmBsCmnEnableCNMLocalCoordinate(gMS_BOSS5_BODY_WORK.cnm_mgr_work, array[i], 1);
			GmBsCmnEnableCNMMtxNode(gMS_BOSS5_BODY_WORK.cnm_mgr_work, array[i], 1);
			GmBsCmnSetCNMMtx(gMS_BOSS5_BODY_WORK.cnm_mgr_work, nNS_MATRIX, array[i]);
		}
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
	}

	public static void gmBoss5TurretEndPartsPose(GMS_BOSS5_TURRET_WORK trt_work)
	{
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)GMM_BS_OBJ(trt_work).parent_obj;
		int[] array = new int[2] { gMS_BOSS5_BODY_WORK.pole_cnm_reg_id, gMS_BOSS5_BODY_WORK.cover_cnm_reg_id };
