	}

	public static void gmBoss5TurretInitSlideTurret(GMS_BOSS5_TURRET_WORK trt_work, int slide_type)
	{
		trt_work.trt_slide_type = slide_type;
		if (slide_type == 0)
		{
			trt_work.trt_slide_length = 0f;
		}
		else
		{
			trt_work.trt_slide_length = GMD_BOSS5_TURRET_SLIDE_LENGTH_MAX;
		}
	}

	public static int gmBoss5TurretUpdateSlideTurret(GMS_BOSS5_TURRET_WORK trt_work)
	{
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)GMM_BS_OBJ(trt_work).parent_obj;
		int result;
		if (trt_work.trt_slide_type == 0)
		{
			if (trt_work.trt_slide_length < GMD_BOSS5_TURRET_SLIDE_LENGTH_MAX)
			{
				trt_work.trt_slide_length += GMD_BOSS5_TURRET_SLIDE_RAISE_SPD_F;
				result = 0;
			}
			else
			{
				trt_work.trt_slide_length = GMD_BOSS5_TURRET_SLIDE_LENGTH_MAX;
				result = 1;
			}
		}
		else if (trt_work.trt_slide_length > 0f)
		{
			trt_work.trt_slide_length -= GMD_BOSS5_TURRET_SLIDE_LOWER_SPD_F;
			result = 0;
		}
		else
		{
			trt_work.trt_slide_length = 0f;
			result = 1;
		}
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		nnMakeTranslateMatrix(nNS_MATRIX, 0f, trt_work.trt_slide_length + GMD_BOSS5_TURRET_SLIDE_POLE_DISP_OFST_Y, 0f);
		GmBsCmnSetCNMMtx(gMS_BOSS5_BODY_WORK.cnm_mgr_work, nNS_MATRIX, gMS_BOSS5_BODY_WORK.pole_cnm_reg_id);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
		return result;
	}

	public static void gmBoss5TurretInitSlideCover(GMS_BOSS5_TURRET_WORK trt_work, int slide_type)
	{
		trt_work.cvr_slide_type = slide_type;
		if (slide_type == 0)
		{
			trt_work.cvr_slide_ratio = 0f;
		}
		else
		{
			trt_work.cvr_slide_ratio = 1f;
		}
	}

	public static int gmBoss5TurretUpdateSlideCover(GMS_BOSS5_TURRET_WORK trt_work)
	{
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)GMM_BS_OBJ(trt_work).parent_obj;
		int result;
		if (trt_work.cvr_slide_type == 0)
		{
			if (trt_work.cvr_slide_ratio < 1f)
			{
				trt_work.cvr_slide_ratio += GMD_BOSS5_TURRET_COVER_SLIDE_OPEN_RATIO_SPD_F;
				result = 0;
			}
			else
			{
				trt_work.cvr_slide_ratio = 1f;
				result = 1;
			}
		}
		else if (trt_work.cvr_slide_ratio > 0f)
		{
			trt_work.cvr_slide_ratio -= GMD_BOSS5_TURRET_COVER_SLIDE_CLOSE_RATIO_SPD_F;
			result = 0;
		}
		else
		{
			trt_work.cvr_slide_ratio = 0f;
			result = 1;
		}
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		float num = 1f + trt_work.cvr_slide_ratio * (GMD_BOSS5_TURRET_COVER_SLIDE_SCALE_MAX - 1f);
		nnMakeRotateXMatrix(nNS_MATRIX, AKM_DEGtoA32(trt_work.cvr_slide_ratio * GMD_BOSS5_TURRET_COVER_SLIDE_DEG_MAX));
		nnScaleMatrix(nNS_MATRIX, nNS_MATRIX, num, num, num);
		GmBsCmnSetCNMMtx(gMS_BOSS5_BODY_WORK.cnm_mgr_work, nNS_MATRIX, gMS_BOSS5_BODY_WORK.cover_cnm_reg_id);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
		return result;
	}

	public static void gmBoss5TurretMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS5_TURRET_WORK gMS_BOSS5_TURRET_WORK = (GMS_BOSS5_TURRET_WORK)obj_work;
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)obj_work.parent_obj;
		NNS_MATRIX nNS_MATRIX = gmBoss5TurretMain_trt_ofst;
		if (gMS_BOSS5_TURRET_WORK.proc_update != null)
		{
			gMS_BOSS5_TURRET_WORK.proc_update(gMS_BOSS5_TURRET_WORK);
		}
		nnMakeTranslateMatrix(nNS_MATRIX, 0f, gMS_BOSS5_TURRET_WORK.trt_slide_length, 0f);
		GmBsCmnUpdateObject3DNNStuckWithNodeRelative(obj_work, gMS_BOSS5_BODY_WORK.snm_work, gMS_BOSS5_BODY_WORK.pole_snm_reg_id, 0, obj_work.parent_obj.pos, gMS_BOSS5_BODY_WORK.pivot_prev_pos, nNS_MATRIX);
		gmBoss5TurretUpdateDispRot(gMS_BOSS5_TURRET_WORK);
	}

	public static void gmBoss5TurretProcInit(GMS_BOSS5_TURRET_WORK trt_work)
	{
		trt_work.proc_update = gmBoss5TurretProcUpdateStandby;
	}

	public static void gmBoss5TurretProcUpdateStandby(GMS_BOSS5_TURRET_WORK trt_work)
	{
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)GMM_BS_OBJ(trt_work).parent_obj;
		if ((gMS_BOSS5_BODY_WORK.flag & 0x200) == 0 && gmBoss5TurretSeqGetVulcanShotNum(trt_work) > 0)
		{
			if (trt_work.wait_timer != 0)
			{
				trt_work.wait_timer--;
				return;
			}
			gmBoss5TurretInitPartsPose(trt_work);
			gmBoss5TurretInitSlideCover(trt_work, 0);
			gmBoss5TurretUpdateDirFollowingPos(trt_work, ref GmBsCmnGetPlayerObj().pos, 360f);
			trt_work.proc_update = gmBoss5TurretProcUpdateOpen;
		}
	}

	public static void gmBoss5TurretProcUpdateOpen(GMS_BOSS5_TURRET_WORK trt_work)
	{
		if (gmBoss5TurretUpdateSlideCover(trt_work) != 0)
		{
			gmBoss5TurretInitSlideTurret(trt_work, 0);
			trt_work.proc_update = gmBoss5TurretProcUpdateAppear;
		}
	}

	public static void gmBoss5TurretProcUpdateAppear(GMS_BOSS5_TURRET_WORK trt_work)
	{
		gmBoss5TurretUpdateDirFacePly(trt_work);
		if (gmBoss5TurretUpdateSlideTurret(trt_work) != 0)
		{
			trt_work.wait_timer = GMD_BOSS5_TURRET_FACE_TIME;
			trt_work.proc_update = gmBoss5TurretProcUpdateFace;
		}
	}

	public static void gmBoss5TurretProcUpdateFace(GMS_BOSS5_TURRET_WORK trt_work)
	{
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)GMM_BS_OBJ(trt_work).parent_obj;
		gmBoss5TurretUpdateDirFacePly(trt_work);
		if ((gMS_BOSS5_BODY_WORK.flag & 0x200) != 0)
		{
			trt_work.wait_timer = 0u;
			trt_work.proc_update = gmBoss5TurretProcUpdateDisappear;
		}
		else if (trt_work.wait_timer != 0)
		{
			trt_work.wait_timer--;
		}
		else
		{
			gmBoss5TurretInitVulcanBurstShot(trt_work, gmBoss5TurretSeqGetVulcanShotNum(trt_work));
			trt_work.proc_update = gmBoss5TurretProcUpdateFire;
		}
	}

	public static void gmBoss5TurretProcUpdateFire(GMS_BOSS5_TURRET_WORK trt_work)
	{
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)GMM_BS_OBJ(trt_work).parent_obj;
		if (gmBoss5TurretUpdateVulcanBurstShot(trt_work) != 0 || (gMS_BOSS5_BODY_WORK.flag & 0x200) != 0)
		{
			gmBoss5TurretClearVulcanBurstShot(trt_work);
			gmBoss5TurretInitSlideTurret(trt_work, 1);
			trt_work.proc_update = gmBoss5TurretProcUpdateDisappear;
		}
	}

	public static void gmBoss5TurretProcUpdateDisappear(GMS_BOSS5_TURRET_WORK trt_work)
	{
		if (gmBoss5TurretUpdateSlideTurret(trt_work) != 0)
		{
			trt_work.wait_timer = gmBoss5TurretSeqGetVulcanWaitTime(trt_work);
			gmBoss5TurretInitSlideCover(trt_work, 1);
			trt_work.proc_update = gmBoss5TurretProcUpdateClose;
		}
	}

	public static void gmBoss5TurretProcUpdateClose(GMS_BOSS5_TURRET_WORK trt_work)
	{
		if (gmBoss5TurretUpdateSlideCover(trt_work) != 0)
		{
			gmBoss5TurretEndPartsPose(trt_work);
			trt_work.proc_update = gmBoss5TurretProcUpdateStandby;
		}
	}

	public static uint gmBoss5TurretSeqGetVulcanWaitTime(GMS_BOSS5_TURRET_WORK trt_work)
	{
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)GMM_BS_OBJ(trt_work).parent_obj;
		int life = gMS_BOSS5_BODY_WORK.mgr_work.life;
		GMS_BOSS5_TURRET_SEQ_VUL_SHOT_INFO gMS_BOSS5_TURRET_SEQ_VUL_SHOT_INFO = null;
		for (int i = 0; i < 5; i++)
		{
			if (life <= gm_boss5_trt_seq_vul_shot_info_tbl[i].life_threshold)
			{
				gMS_BOSS5_TURRET_SEQ_VUL_SHOT_INFO = gm_boss5_trt_seq_vul_shot_info_tbl[i];
				break;
			}
		}
		if (gMS_BOSS5_TURRET_SEQ_VUL_SHOT_INFO == null)
		{
			return 0u;
		}
		return gMS_BOSS5_TURRET_SEQ_VUL_SHOT_INFO.wait_time;
	}

	public static int gmBoss5TurretSeqGetVulcanShotNum(GMS_BOSS5_TURRET_WORK trt_work)
	{
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)GMM_BS_OBJ(trt_work).parent_obj;
		int life = gMS_BOSS5_BODY_WORK.mgr_work.life;
		GMS_BOSS5_TURRET_SEQ_VUL_SHOT_INFO gMS_BOSS5_TURRET_SEQ_VUL_SHOT_INFO = null;
		for (int i = 0; i < 5; i++)
		{
			if (life <= gm_boss5_trt_seq_vul_shot_info_tbl[i].life_threshold)
			{
				gMS_BOSS5_TURRET_SEQ_VUL_SHOT_INFO = gm_boss5_trt_seq_vul_shot_info_tbl[i];
				break;
			}
		}
		if (gMS_BOSS5_TURRET_SEQ_VUL_SHOT_INFO == null)
		{
			return 0;
		}
		return gMS_BOSS5_TURRET_SEQ_VUL_SHOT_INFO.shot_num;
	}

	public static void SET_FLAG(uint f, GMS_BOSS4_CHIBI_WORK w)
	{
		w.flag |= f;
	}

	public static void RESET_FLAG(uint f, GMS_BOSS4_CHIBI_WORK w)
	{
		w.flag &= ~f;
	}

	public static bool IS_FLAG(uint f, GMS_BOSS4_CHIBI_WORK w)
	{
		return 0 != (w.flag & f);
	}

	private static int gmBoss4ChibiGetAttackType(int life)
	{
		UNREFERENCED_PARAMETER(life);
		int num = 0;
		gmBoss4ChibiGetAttackTypeStatics._index %= 20;
		if (GmBoss4GetLife() < GME_BOSS4_LIFE_H)
		{
			num = (GmBoss4CheckBossRush() ? ((GmBoss4GetLife() >= GME_BOSS4_LIFE_H || GmBoss4GetLife() <= GME_BOSS4_LIFE_L) ? gmBoss4ChibiGetAttackTypeStatics.life1_tbl_f[gmBoss4ChibiGetAttackTypeStatics._index] : gmBoss4ChibiGetAttackTypeStatics.life2_tbl_f[gmBoss4ChibiGetAttackTypeStatics._index]) : ((GmBoss4GetLife() >= GME_BOSS4_LIFE_H || GmBoss4GetLife() <= GME_BOSS4_LIFE_L) ? gmBoss4ChibiGetAttackTypeStatics.life1_tbl[gmBoss4ChibiGetAttackTypeStatics._index] : gmBoss4ChibiGetAttackTypeStatics.life2_tbl[gmBoss4ChibiGetAttackTypeStatics._index]));
		}
		else
		{
			if (!GmBoss4CheckBossRush())
			{
				return 1;
			}
			num = gmBoss4ChibiGetAttackTypeStatics.life3_tbl_f[gmBoss4ChibiGetAttackTypeStatics._index];
		}
		gmBoss4ChibiGetAttackTypeStatics._index++;
		switch (num)
		{
		default:
			return 1;
		case 1:
			return 2;
		case 2:
			return 3;
		case 3:
			return 4;
		}
	}

	private static int gmBoss4ChibiGetThrowType()
	{
		return gmBoss4ChibiGetThrowType(1);
	}

	private static int gmBoss4ChibiGetThrowType(int t)
	{
		gmBoss4ChibiGetThrowTypeStatics._index %= 20;
		int result = gmBoss4ChibiGetThrowTypeStatics._tbl[gmBoss4ChibiGetThrowTypeStatics._index];
		gmBoss4ChibiGetThrowTypeStatics._index++;
		return result;
	}

