	private static OBS_OBJECT_WORK GmBoss4ChibiInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, int type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_BOSS4_CHIBI_WORK(), "BOSS4_C.E");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_BOSS4_CHIBI_WORK gMS_BOSS4_CHIBI_WORK = (GMS_BOSS4_CHIBI_WORK)oBS_OBJECT_WORK;
		gMS_BOSS4_CHIBI_WORK.type = type;
		switch (gMS_BOSS4_CHIBI_WORK.type)
		{
		default:
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, GmBoss4GetObj3D(3), gMS_ENEMY_3D_WORK.obj_3d);
			break;
		case 2:
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, GmBoss4GetObj3D(4), gMS_ENEMY_3D_WORK.obj_3d);
			break;
		case 3:
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, GmBoss4GetObj3D(5), gMS_ENEMY_3D_WORK.obj_3d);
			break;
		case 4:
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, GmBoss4GetObj3D(6), gMS_ENEMY_3D_WORK.obj_3d);
			break;
		}
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(732), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.disp_flag |= 134217728u;
		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.move_flag &= 4294963199u;
		oBS_OBJECT_WORK.move_flag |= 128u;
		gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 32768u;
		ObjObjectFieldRectSet(oBS_OBJECT_WORK, -20, -44, 20, -4);
		T_FUNC(gmBoss4ChibiWaitLoad, oBS_OBJECT_WORK);
		gm_chibi_exp_flag = false;
		RESET_FLAG(536870912u, gMS_BOSS4_CHIBI_WORK);
		if (gMS_BOSS4_CHIBI_WORK.type != 0)
		{
			SET_FLAG(536870912u, gMS_BOSS4_CHIBI_WORK);
		}
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmBoss4ChibiExit);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

	private static void gmBoss4ChibiAtkHitFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)my_rect.parent_obj.parent_obj;
		GMS_BOSS4_CHIBI_WORK gMS_BOSS4_CHIBI_WORK = (GMS_BOSS4_CHIBI_WORK)my_rect.parent_obj;
		gMS_BOSS4_BODY_WORK.flag[0] |= 268435456u;
		GmEnemyDefaultAtkFunc(my_rect, your_rect);
		if (gMS_BOSS4_CHIBI_WORK.type != 0)
		{
			GMS_PLAYER_WORK ply_work = (GMS_PLAYER_WORK)GmBsCmnGetPlayerObj();
			if (GmPlayerKeyCheckWalkLeft(ply_work))
			{
				GmPlayerSetReverse(ply_work);
			}
		}
		SET_FLAG(1073741824u, gMS_BOSS4_CHIBI_WORK);
	}

	private static void gmBoss4ChibiDefHitFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		GMS_BOSS4_CHIBI_WORK gMS_BOSS4_CHIBI_WORK = (GMS_BOSS4_CHIBI_WORK)my_rect.parent_obj;
		GMS_BOSS4_CHIBI_WORK gMS_BOSS4_CHIBI_WORK2 = (GMS_BOSS4_CHIBI_WORK)your_rect.parent_obj;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gMS_BOSS4_CHIBI_WORK;
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = (OBS_OBJECT_WORK)gMS_BOSS4_CHIBI_WORK2;
		if (!IS_FLAG(536870912u, gMS_BOSS4_CHIBI_WORK) || !IS_FLAG(536870912u, gMS_BOSS4_CHIBI_WORK2))
		{
			return;
		}
		if (oBS_OBJECT_WORK.pos.x > oBS_OBJECT_WORK2.pos.x)
		{
			oBS_OBJECT_WORK.pos.x += FX_F32_TO_FX32(4f);
			oBS_OBJECT_WORK.spd.x += FX_F32_TO_FX32(GMD_BOSS4_CHIBI_HIT_CHIBI_ADDSPD);
		}
		if (oBS_OBJECT_WORK.pos.x < oBS_OBJECT_WORK2.pos.x)
		{
			oBS_OBJECT_WORK.pos.x -= FX_F32_TO_FX32(4f);
			oBS_OBJECT_WORK.spd.x -= FX_F32_TO_FX32(GMD_BOSS4_CHIBI_HIT_CHIBI_ADDSPD);
		}
		if (oBS_OBJECT_WORK.pos.x == oBS_OBJECT_WORK2.pos.x)
		{
			if (oBS_OBJECT_WORK.pos.y < oBS_OBJECT_WORK.pos.y)
			{
				oBS_OBJECT_WORK.pos.x += FX_F32_TO_FX32(4f);
				oBS_OBJECT_WORK.spd.x += FX_F32_TO_FX32(GMD_BOSS4_CHIBI_HIT_CHIBI_ADDSPD);
			}
			else
			{
				oBS_OBJECT_WORK.pos.x -= FX_F32_TO_FX32(4f);
				oBS_OBJECT_WORK.spd.x -= FX_F32_TO_FX32(GMD_BOSS4_CHIBI_HIT_CHIBI_ADDSPD);
			}
		}
		if (oBS_OBJECT_WORK.spd.x > FX_F32_TO_FX32(GMD_BOSS4_CHIBI_SPD_LIMIT))
		{
			oBS_OBJECT_WORK.spd.x = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_SPD_LIMIT);
		}
		if (oBS_OBJECT_WORK.spd.x < -FX_F32_TO_FX32(GMD_BOSS4_CHIBI_SPD_LIMIT))
		{
			oBS_OBJECT_WORK.spd.x = -FX_F32_TO_FX32(GMD_BOSS4_CHIBI_SPD_LIMIT);
		}
	}

	private static void gmBoss4ChibiWaitLoad(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_CHIBI_WORK gMS_BOSS4_CHIBI_WORK = (GMS_BOSS4_CHIBI_WORK)obj_work;
		if (GmBoss4IsBuilded())
		{
			T_FUNC(gmBoss4ChibiMain, obj_work);
			GmBoss4UtilInit1ShotTimer(gMS_BOSS4_CHIBI_WORK.timer, GMD_BOSS4_CHIBI_LIFE_TIME);
			GmBoss4UtilInitFlicker(obj_work, gMS_BOSS4_CHIBI_WORK.flk_work, 1, 180, 4, (int)(gMS_BOSS4_CHIBI_WORK.timer.timer / 20 * 3), gm_boss4_color_red);
			gMS_BOSS4_CHIBI_WORK.count = -1;
			switch (gMS_BOSS4_CHIBI_WORK.type)
			{
			default:
				GmBsCmnSetAction(obj_work, 0, 0);
				obj_work.spd.y = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_Y_NORMAL);
				break;
			case 1:
				GmBsCmnSetAction(obj_work, 0, 0);
				obj_work.spd.y = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_Y_BOUND);
				break;
			case 2:
				GmBsCmnSetAction(obj_work, 0, 0);
				obj_work.spd.y = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_Y_SPEED);
				break;
			case 3:
				GmBsCmnSetAction(obj_work, 0, 0);
				obj_work.spd.y = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_Y_BIG);
				break;
			case 4:
				GmBsCmnSetAction(obj_work, 0, 0);
				obj_work.spd.y = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_Y_IRON);
				break;
			}
			obj_work.spd_fall = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_FALL_SPD_NORMAL);
			obj_work.pos.z = 131072;
			gMS_BOSS4_CHIBI_WORK.bound = 0;
			GmBoss4UtilInitNodeMatrix(gMS_BOSS4_CHIBI_WORK.node_work, obj_work, 1);
			GmBoss4UtilGetNodeMatrix(gMS_BOSS4_CHIBI_WORK.node_work, 0);
			gmBoss4ChibiBoosterCreate(gMS_BOSS4_CHIBI_WORK);
			GmSoundPlaySE("Boss4_01");
		}
	}

	private static void gmBoss4ChibiExit(MTS_TASK_TCB tcb)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(tcb);
		GMS_BOSS4_CHIBI_WORK gMS_BOSS4_CHIBI_WORK = (GMS_BOSS4_CHIBI_WORK)oBS_OBJECT_WORK;
		GmBoss4DecObjCreateCount();
		GmBoss4UtilExitNodeMatrix(gMS_BOSS4_CHIBI_WORK.node_work);
		GmEnemyDefaultExit(tcb);
	}

	private static void gmBoss4ChibiMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_CHIBI_WORK gMS_BOSS4_CHIBI_WORK = (GMS_BOSS4_CHIBI_WORK)obj_work;
		if (GmBsCmnIsActionEnd(obj_work) != 0)
		{
			GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
			ObjRectWorkSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[1], -10, -22, 10, -2);
			gMS_ENEMY_3D_WORK.ene_com.rect_work[1].ppHit = gmBoss4ChibiAtkHitFunc;
			gMS_ENEMY_3D_WORK.ene_com.rect_work[1].flag |= 33554432u;
			ObjRectWorkSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[2], -14, -26, 18, 2);
			gMS_ENEMY_3D_WORK.ene_com.rect_work[2].ppHit = gmBoss4ChibiDefHitFunc;
			ObjRectGroupSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[2], 2, 4);
			gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294965247u;
			gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag |= 4u;
			switch (gMS_BOSS4_CHIBI_WORK.type)
			{
			case 3:
				ObjRectWorkSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[1], -30, -60, 30, 0);
				ObjRectWorkSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[2], -44, -64, 44, 4);
				break;
			}
		}
		switch (gMS_BOSS4_CHIBI_WORK.type)
		{
		default:
			obj_work.spd_fall = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_FALL_SPD_NORMAL);
			break;
		case 1:
			obj_work.move_flag &= 4294443007u;
			obj_work.spd_fall = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_FALL_SPD_BOUND);
			obj_work.pos.x += GmBoss4GetScrollOffset();
			break;
		case 2:
			obj_work.move_flag &= 4294443007u;
			obj_work.spd_fall = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_FALL_SPD_SPEED);
			obj_work.pos.x += GmBoss4GetScrollOffset();
			if (gMS_BOSS4_CHIBI_WORK.bound == 0)
			{
				obj_work.pos.y += obj_work.spd.y;
			}
			break;
		case 3:
			obj_work.move_flag &= 4294443007u;
			obj_work.spd_fall = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_FALL_SPD_BIG);
			obj_work.pos.x += GmBoss4GetScrollOffset();
			break;
		case 4:
			obj_work.move_flag &= 4294443007u;
			obj_work.spd_fall = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_FALL_SPD_IRON);
			obj_work.pos.x += GmBoss4GetScrollOffset();
			obj_work.pos.x -= FX_F32_TO_FX32(4f);
			break;
		}
		if (obj_work.scale.y < FX_F32_TO_FX32(1f))
		{
			obj_work.scale.y = (int)((float)obj_work.scale.y * GMD_BOSS4_CHIBI_BOUND_OUT_Y);
			if (obj_work.scale.y > FX_F32_TO_FX32(1f))
			{
				obj_work.scale.y = FX_F32_TO_FX32(1f);
			}
		}
		if (obj_work.scale.x > FX_F32_TO_FX32(1f))
		{
			obj_work.scale.x = (int)((float)obj_work.scale.x * GMD_BOSS4_CHIBI_BOUND_OUT_X);
			if (obj_work.scale.x < FX_F32_TO_FX32(1f))
			{
				obj_work.scale.x = FX_F32_TO_FX32(1f);
			}
		}
		if (gm_chibi_exp_flag)
		{
			SET_FLAG(1073741824u, gMS_BOSS4_CHIBI_WORK);
		}
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK2 = (GMS_ENEMY_3D_WORK)obj_work;
		if (gm_chibi_inv_flag)
		{
			gMS_ENEMY_3D_WORK2.ene_com.rect_work[1].flag |= 2048u;
		}
		else
		{
			gMS_ENEMY_3D_WORK2.ene_com.rect_work[1].flag &= 4294965247u;
		}
		if ((obj_work.move_flag & 1) != 0)
		{
			SET_FLAG(536870912u, gMS_BOSS4_CHIBI_WORK);
			obj_work.move_flag &= 4294967294u;
			obj_work.move_flag &= 4294967167u;
			obj_work.move_flag |= 256u;
			gMS_BOSS4_CHIBI_WORK.bnd_xspd = obj_work.spd.x;
			obj_work.spd.y = 0;
			obj_work.spd.x = 0;
			obj_work.spd_fall = 0;
			if (gMS_BOSS4_CHIBI_WORK.type == 4)
			{
				gMS_BOSS4_CHIBI_WORK.bound = 1000;
			}
			else
			{
				gMS_BOSS4_CHIBI_WORK.bound = GMD_BOSS4_CHIBI_BOUND_FRAME;
			}
			if (gMS_BOSS4_CHIBI_WORK.type == 3)
			{
				GmSoundPlaySE("Boss4_03");
			}
			else if (gMS_BOSS4_CHIBI_WORK.type != 4)
			{
				GmSoundPlaySE("Boss4_02");
			}
		}
		if (gMS_BOSS4_CHIBI_WORK.bound > 0)
		{
			if (--gMS_BOSS4_CHIBI_WORK.bound == 0)
			{
				obj_work.pos.y += FX_F32_TO_FX32(-4f);
				obj_work.move_flag |= 128u;
				obj_work.move_flag &= 4294967039u;
				obj_work.move_flag &= 4294967294u;
				obj_work.spd.x = gMS_BOSS4_CHIBI_WORK.bnd_xspd;
				switch (gMS_BOSS4_CHIBI_WORK.type)
				{
				default:
					obj_work.spd.y = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_Y_NORMAL);
					if (GmBsCmnGetPlayerObj().pos.x < obj_work.pos.x)
					{
						obj_work.spd.x = (int)((float)obj_work.spd.x * GMD_BOSS4_CHIBI_BOUND_MULTI_SPD_X) - FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_ADD_SPD_X);
					}
					else
					{
						obj_work.spd.x = (int)((float)obj_work.spd.x * GMD_BOSS4_CHIBI_BOUND_MULTI_SPD_X) + FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_ADD_SPD_X);
					}
					if (obj_work.spd.x > FX_F32_TO_FX32(GMD_BOSS4_CHIBI_SPD_LIMIT))
					{
						obj_work.spd.x = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_SPD_LIMIT);
					}
					if (obj_work.spd.x < -FX_F32_TO_FX32(GMD_BOSS4_CHIBI_SPD_LIMIT))
					{
						obj_work.spd.x = -FX_F32_TO_FX32(GMD_BOSS4_CHIBI_SPD_LIMIT);
					}
					break;
				case 1:
					obj_work.spd.x = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_X_BOUND);
					obj_work.spd.y = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_Y_BOUND);
					break;
				case 2:
					obj_work.spd.x = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_X_SPEED);
					obj_work.spd.y = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_Y_SPEED);
					break;
				case 3:
					obj_work.spd.x = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_X_BIG);
					obj_work.spd.y = FX_F32_TO_FX32(GMD_BOSS4_CHIBI_BOUND_SPD_Y_BIG);
					break;
				case 4:
					obj_work.spd.x = FX_F32_TO_FX32(0.0);
					obj_work.spd.y = FX_F32_TO_FX32(0.0);
					break;
				}
			}
			else if (gMS_BOSS4_CHIBI_WORK.type != 4)
			{
				obj_work.scale.y = (int)((float)obj_work.scale.y * GMD_BOSS4_CHIBI_BOUND_IN_Y);
				obj_work.scale.x = (int)((float)obj_work.scale.x * GMD_BOSS4_CHIBI_BOUND_IN_X);
				obj_work.spd_fall = 0;
				if (obj_work.scale.y < FX_F32_TO_FX32(0.6f))
				{
					obj_work.scale.y = FX_F32_TO_FX32(0.6f);
				}
				if (obj_work.scale.x > FX_F32_TO_FX32(1.5f))
				{
					obj_work.scale.x = FX_F32_TO_FX32(1.5f);
				}
			}
		}
		if (gMS_BOSS4_CHIBI_WORK.type != 4)
		{
			GmBoss4UtilLookAtPlayer(gMS_BOSS4_CHIBI_WORK.dir, obj_work, 5);
		}
		if (GmBoss4UtilUpdate1ShotTimer(gMS_BOSS4_CHIBI_WORK.timer))
		{
			SET_FLAG(1073741824u, gMS_BOSS4_CHIBI_WORK);
		}
		if (gMS_BOSS4_CHIBI_WORK.type == 0 && GmBoss4UtilUpdateFlicker(obj_work, gMS_BOSS4_CHIBI_WORK.flk_work))
		{
			int start = (int)(gMS_BOSS4_CHIBI_WORK.timer.timer / 20 * 3);
			GmBoss4UtilInitFlicker(obj_work, gMS_BOSS4_CHIBI_WORK.flk_work, 1, start, 2, 0, gm_boss4_color_red);
		}
		if (IS_FLAG(1073741824u, gMS_BOSS4_CHIBI_WORK))
		{
			RESET_FLAG(1073741824u, gMS_BOSS4_CHIBI_WORK);
			int num = 736;
			switch (gMS_BOSS4_CHIBI_WORK.type)
			{
			default:
				num = 736;
				break;
			case 2:
				num = 737;
				break;
			case 3:
				num = 738;
				break;
			}
			VecFx32 pos = obj_work.pos;
			pos.y += FX_F32_TO_FX32(-16f);
			pos.z = 135168;
			GmBoss4EffCommonInit(num, pos);
			GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK3 = (GMS_ENEMY_3D_WORK)obj_work;
			gMS_ENEMY_3D_WORK3.ene_com.rect_work[1].flag &= 4294967291u;
			gMS_ENEMY_3D_WORK3.ene_com.rect_work[2].flag &= 4294967291u;
			obj_work.spd_fall = 0;
			obj_work.spd.x = 0;
			obj_work.spd.y = 0;
			obj_work.move_flag &= 4294967294u;
			obj_work.move_flag |= 256u;
			obj_work.move_flag |= 256u;
			gMS_BOSS4_CHIBI_WORK.wait = 0;
			T_FUNC(gmBoss4ChibiBomb, obj_work);
			GmSoundPlaySE("Boss4_04");
		}
		GmBoss4UtilUpdateDirection(gMS_BOSS4_CHIBI_WORK.dir, obj_work, true);
	}

	private static void gmBoss4ChibiBomb(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_CHIBI_WORK gMS_BOSS4_CHIBI_WORK = (GMS_BOSS4_CHIBI_WORK)obj_work;
		obj_work.pos.x += GmBoss4GetScrollOffset();
		gMS_BOSS4_CHIBI_WORK.wait++;
		if (gMS_BOSS4_CHIBI_WORK.wait >= 2)
		{
			obj_work.disp_flag |= 32u;
		}
		if (gMS_BOSS4_CHIBI_WORK.wait >= 60)
		{
			GMM_BS_OBJ(gMS_BOSS4_CHIBI_WORK).flag |= 8u;
		}
	}

	private static void gmBoss4ChibiFuncBoost(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_CHIBI_WORK gMS_BOSS4_CHIBI_WORK = (GMS_BOSS4_CHIBI_WORK)obj_work.parent_obj;
		OBS_OBJECT_WORK parent_obj = obj_work.parent_obj;
		MTM_ASSERT(gMS_BOSS4_CHIBI_WORK.node_work.snm_work.reg_node_max);
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.flag |= 4u;
		}
		if ((parent_obj.disp_flag & 0x20) != 0)
		{
			gmBoss4ChibiBoosterDelete(gMS_BOSS4_CHIBI_WORK);
		}
		obj_work.disp_flag &= 4294967263u;
		if (gMS_BOSS4_CHIBI_WORK.dir.cur_angle < AKM_DEGtoA16(50) && gMS_BOSS4_CHIBI_WORK.dir.cur_angle > AKM_DEGtoA16(-50))
		{
			obj_work.disp_flag |= 32u;
		}
		GmBsCmnUpdateObject3DESStuckWithNode(obj_work, gMS_BOSS4_CHIBI_WORK.node_work.snm_work, gMS_BOSS4_CHIBI_WORK.node_work.work[0], 1);
		obj_work.disp_flag &= 4294963199u;
		if ((g_obj.flag & 1) != 0)
		{
			obj_work.disp_flag |= 4096u;
			return;
		}
		obj_work.pos.x += parent_obj.spd.x;
		obj_work.pos.y += parent_obj.spd.y;
		obj_work.pos.x += GmBoss4GetScrollOffset();
	}

	private static void gmBoss4ChibiBoosterCreate(GMS_BOSS4_CHIBI_WORK chibi)
	{
	}

	private static void gmBoss4ChibiBoosterDelete(GMS_BOSS4_CHIBI_WORK chibi)
	{
		if (chibi.boost != null)
		{
			ObjDrawKillAction3DES((OBS_OBJECT_WORK)chibi.boost);
			chibi.boost = null;
		}
	}

