	private static void GmBoss4Build()
	{
		object obj = ObjDataLoadAmbIndex(null, 0, GMD_BOSS4_ARC);
		object obj2 = ObjDataLoadAmbIndex(null, 1, GMD_BOSS4_ARC);
		gm_boss4_obj_3d_list = GmGameDBuildRegBuildModel((AMS_AMB_HEADER)obj, (AMS_AMB_HEADER)obj2, 0u);
		GmBoss4BodyBuild();
		GmBoss4EggmanBuild();
		GmBoss4CapsuleBuild();
		GmBoss4ChibiBuild();
		GmBoss4EffectBuild();
	}

	private static void GmBoss4Flush()
	{
		GmBoss4EffectFlush();
		GmBoss4ChibiFlush();
		GmBoss4CapsuleFlush();
		GmBoss4EggmanFlush();
		GmBoss4BodyFlush();
		AMS_AMB_HEADER aMS_AMB_HEADER = (AMS_AMB_HEADER)ObjDataLoadAmbIndex(null, 0, GMD_BOSS4_ARC);
		GmGameDBuildRegFlushModel(gm_boss4_obj_3d_list, aMS_AMB_HEADER.file_num);
		gm_boss4_obj_3d_list = null;
		gm_boss4_mgr_work = null;
	}

	private static bool GmBoss4IsBuilded()
	{
		MTM_ASSERT(gm_boss4_mgr_work);
		return 0 != (gm_boss4_mgr_work.flag & 1);
	}

	private static OBS_OBJECT_WORK GmBoss4Init(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		UNREFERENCED_PARAMETER(type);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BOSS4_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_BOSS4_MGR_WORK(), "Boss4_MGR");
		GMS_BOSS4_MGR_WORK gMS_BOSS4_MGR_WORK = (gm_boss4_mgr_work = (GMS_BOSS4_MGR_WORK)oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.disp_flag |= 32u;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		gMS_BOSS4_MGR_WORK.life = GMD_BOSS4_LIFE;
		oBS_OBJECT_WORK.pos.x = pos_x;
		oBS_OBJECT_WORK.pos.y = pos_y;
		oBS_OBJECT_WORK.ppFunc = gmBoss4MgrWaitLoad;
		GmBoss4ScrollOff();
		gm_boss4_is_2nd = false;
		if (g_gs_main_sys_info.stage_id != 16)
		{
			GmMapSetAddMapScrlScaleMagX(2, 1);
			GmMapSetAddMapScrlScaleMagX(3, 1);
			GmMapSetAddMapScrlScaleMagX(4, 1);
			GmMapSetAddMapXLoop();
			GmMapEnableAddMapUserScrlX();
		}
		gm_boss4_n_scroll_start = GMD_BOSS4_SCROLL_START_X;
		gm_boss4_n_scroll_end = GMD_BOSS4_SCROLL_END_X;
		return oBS_OBJECT_WORK;
	}

	private static int GmBoss4GetScrollOffset()
	{
		return FX_F32_TO_FX32(gm_boss4_n_offset_x);
	}

	private static void gmBoss4SetPartTextureBurnt(OBS_OBJECT_WORK obj_work)
	{
		gmBoss4SetPartTextureBurnt(obj_work, true);
	}

	private static void gmBoss4SetPartTextureBurnt(OBS_OBJECT_WORK obj_work, bool burn)
	{
		MTM_ASSERT(obj_work);
		MTM_ASSERT(obj_work.obj_3d);
		MTM_ASSERT(obj_work.disp_flag & 0x8000000);
		obj_work.obj_3d.drawflag |= 268435456u;
		obj_work.obj_3d.draw_state.texoffset[0].mode = 2;
		if (burn)
		{
			obj_work.obj_3d.draw_state.texoffset[0].u = 0.5f;
		}
		else
		{
			obj_work.obj_3d.draw_state.texoffset[0].u = 0f;
		}
	}

	private static bool gmBoss4IsScrollLockBusy()
	{
		if ((g_gm_main_system.game_flag & 0x8000) != 0)
		{
			return true;
		}
		return false;
	}

	private static void gmBoss4MgrWaitLoad(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_MGR_WORK gMS_BOSS4_MGR_WORK = (GMS_BOSS4_MGR_WORK)obj_work;
		bool flag = false;
		int x = obj_work.pos.x;
		int y = obj_work.pos.y;
		if (GmBsCmnIsFinalZoneType(obj_work) != 0)
		{
			if (GmMainDatLoadBossBattleLoadCheck(3))
			{
				flag = true;
			}
		}
		else
		{
			flag = true;
		}
		if (flag)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GmEventMgrLocalEventBirth(321, x, y, 0, 0, 0, 0, 0, 0);
			GmBoss4IncObjCreateCount();
			OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GmEventMgrLocalEventBirth(322, x, y, 0, 0, 0, 0, 0, 0);
			GmBoss4IncObjCreateCount();
			GmBoss4CapsuleClear();
			for (int i = 0; i < 6; i++)
			{
				OBS_OBJECT_WORK oBS_OBJECT_WORK3 = GmEventMgrLocalEventBirth(323, x, y, 0, 0, 0, 0, 0, 0);
				oBS_OBJECT_WORK3.parent_obj = oBS_OBJECT_WORK;
				GmBoss4IncObjCreateCount();
			}
			GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (gMS_BOSS4_MGR_WORK.body_work = (GMS_BOSS4_BODY_WORK)oBS_OBJECT_WORK);
			gMS_BOSS4_BODY_WORK.mgr_work = gMS_BOSS4_MGR_WORK;
			oBS_OBJECT_WORK.parent_obj = obj_work;
			oBS_OBJECT_WORK2.parent_obj = oBS_OBJECT_WORK;
			gMS_BOSS4_BODY_WORK.parts_objs[0] = oBS_OBJECT_WORK;
