		ObjObjectCameraSet(FXM_FLOAT_TO_FX32(obj_cam.disp_pos.x - (float)(OBD_LCD_X / 2)), FXM_FLOAT_TO_FX32(0f - obj_cam.disp_pos.y - (float)(OBD_LCD_Y / 2)), FXM_FLOAT_TO_FX32(obj_cam.disp_pos.x - (float)(OBD_LCD_X / 2)), FXM_FLOAT_TO_FX32(0f - obj_cam.disp_pos.y - (float)(OBD_LCD_Y / 2)));
