		g_gm_main_system.map_fcol.right = gm_boss4_n_scroll_pt_x + (int)(AMD_SCREEN_2D_WIDTH / 2f * 0.67438334f);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
