	public static bool OBM_LINE_AND_LINE(int x0, int w0, int x1, int w1)
	{
		if (x0 > x1 || x0 + w0 < x1)
		{
			if (x0 >= x1)
			{
				return x1 + w1 >= x0;
			}
			return false;
		}
		return true;
	}

	public static bool OBM_POINT_IN_LINE(int x0, int w0, int x1)
	{
		if (x0 <= x1)
		{
			return x0 + w0 >= x1;
		}
		return false;
	}

	public static OBS_RECT ObjRectSet(OBS_RECT pRec, short cLeft, short cTop, short cRight, short cBottom)
	{
		pRec.left = cLeft;
		pRec.top = cTop;
		pRec.right = cRight;
		pRec.bottom = cBottom;
		pRec.back = -16;
		pRec.front = 16;
		if (pRec.right < pRec.left)
		{
			MTM_MATH_SWAP(ref pRec.left, ref pRec.right);
		}
		if (pRec.bottom < pRec.top)
		{
			MTM_MATH_SWAP(ref pRec.top, ref pRec.bottom);
		}
		VEC_Set(ref pRec.pos, 0, 0, 0);
		return pRec;
	}

	public static OBS_RECT ObjRectZSet(OBS_RECT pRec, short cLeft, short cTop, short cBack, short cRight, short cBottom, short cFront)
	{
		pRec.left = cLeft;
		pRec.top = cTop;
		pRec.right = cRight;
		pRec.bottom = cBottom;
		pRec.back = cBack;
		pRec.front = cFront;
		if (pRec.right < pRec.left)
		{
			MTM_MATH_SWAP(ref pRec.left, ref pRec.right);
		}
		if (pRec.bottom < pRec.top)
		{
			MTM_MATH_SWAP(ref pRec.top, ref pRec.bottom);
		}
		if (pRec.front < pRec.back)
		{
			MTM_MATH_SWAP(ref pRec.back, ref pRec.front);
		}
		VEC_Set(ref pRec.pos, 0, 0, 0);
		return pRec;
	}

	public static OBS_RECT ObjRectAllSet(OBS_RECT pRec, VecFx32 pos, short cLeft, short cTop, short cBack, short cRight, short cBottom, short cFront)
	{
		pRec.pos.Assign(pos);
		pRec.left = cLeft;
		pRec.top = cTop;
		pRec.right = cRight;
		pRec.bottom = cBottom;
		pRec.back = cBack;
		pRec.front = cFront;
		if (pRec.right < pRec.left)
		{
			MTM_MATH_SWAP(ref pRec.left, ref pRec.right);
		}
		if (pRec.bottom < pRec.top)
		{
			MTM_MATH_SWAP(ref pRec.top, ref pRec.bottom);
		}
		if (pRec.front < pRec.back)
		{
			MTM_MATH_SWAP(ref pRec.back, ref pRec.front);
		}
		return pRec;
	}

