			_obj_user_flag_nx[pObj.group_no] |= pObj.target_g_flag;
			_obj_user_resist_num_nx[pObj.group_no]++;
			_obj_user_resist_all_num_nx++;
		}
	}

	private static void ObjRectCheckAllGroup()
	{
		if ((g_obj.flag & 0x20000) != 0)
		{
			objRectCheckOut();
		}
		_obj_ulFlagBackA = 0u;
		_obj_ulFlagBackD = 0u;
		_obj_ucNoHit = 0;
		for (ushort num = 0; num < _obj_user_resist_all_num; num++)
		{
			if (_obj_user_resist[num] != null && (_obj_user_resist[num].flag & 0x400) != 0)
			{
				_obj_user_resist[num].flag &= 4294836223u;
			}
		}
		ushort num2 = 0;
		for (ushort num = 0; num < 8; num++)
		{
			ushort num3 = 0;
			for (byte b = 0; b < 8; b++)
			{
				if (_obj_user_resist_num[b] != 0 && (_obj_user_flag[num] & (1 << (int)b)) != 0)
				{
					objRectCheckGroup(new ArrayPointer<OBS_RECT_WORK>(_obj_user_resist, num2), new ArrayPointer<OBS_RECT_WORK>(_obj_user_resist, num3), _obj_user_resist_num[num], _obj_user_resist_num[b], b);
				}
				num3 += _obj_user_resist_num[b];
			}
			num2 += _obj_user_resist_num[num];
		}
		for (ushort num = 0; num < _obj_user_resist_all_num; num++)
		{
			if (_obj_user_resist[num] != null)
			{
				if ((_obj_user_resist[num].flag & 0x10000) != 0)
				{
					_obj_user_resist[num].flag |= 512u;
					_obj_user_resist[num].flag &= 4294901759u;
				}
				if ((_obj_user_resist[num].flag & 0x400) != 0 && (_obj_user_resist[num].flag & 0x20000) == 0)
				{
					_obj_user_resist[num].flag &= 4294705151u;
				}
			}
		}
		if ((g_obj.flag & 0x20000) == 0)
		{
			objRectCheckOut();
		}
	}

