	private static void objRectCheckGroup(ArrayPointer<OBS_RECT_WORK> GroupA, ArrayPointer<OBS_RECT_WORK> GroupD, byte GroupNumA, byte GroupNumD, byte Index)
	{
		int lLeft = 0;
		int lTop = 0;
		int lLeft2 = 0;
		int lTop2 = 0;
		int lBack = 0;
		int lBack2 = 0;
		ushort usWidth = 0;
		ushort usHeight = 0;
		ushort usWidth2 = 0;
		ushort usHeight2 = 0;
		ushort usDepth = 0;
		ushort usDepth2 = 0;
		for (ushort num = 0; num < GroupNumA; num++)
		{
			OBS_RECT_WORK oBS_RECT_WORK = GroupA[num];
			if (oBS_RECT_WORK != null && (oBS_RECT_WORK.flag & 0x800) == 0 && (oBS_RECT_WORK.flag & 4) != 0 && (oBS_RECT_WORK.target_g_flag & (1 << (int)Index)) != 0 && (oBS_RECT_WORK.parent_obj == null || (oBS_RECT_WORK.parent_obj.flag & 6) == 0))
			{
				ObjRectLTBSet(oBS_RECT_WORK, ref lLeft, ref lTop, ref lBack);
				ObjRectWHDSet(oBS_RECT_WORK, ref usWidth, ref usHeight, ref usDepth);
				for (ushort num2 = 0; num2 < GroupNumD; num2++)
				{
					OBS_RECT_WORK oBS_RECT_WORK2 = GroupD[num2];
					if (GroupA[num] == null)
					{
						break;
					}
					if (oBS_RECT_WORK2 != null && oBS_RECT_WORK2 != oBS_RECT_WORK && (oBS_RECT_WORK2.parent_obj != oBS_RECT_WORK.parent_obj || oBS_RECT_WORK2.parent_obj == null) && ((oBS_RECT_WORK2.flag | oBS_RECT_WORK.flag) & 0x800) == 0 && (oBS_RECT_WORK2.flag & 4) != 0 && (oBS_RECT_WORK2.parent_obj == null || (oBS_RECT_WORK2.parent_obj.flag & 6) == 0))
					{
						ObjRectLTBSet(oBS_RECT_WORK2, ref lLeft2, ref lTop2, ref lBack2);
						ObjRectWHDSet(oBS_RECT_WORK2, ref usWidth2, ref usHeight2, ref usDepth2);
						if (((oBS_RECT_WORK2.flag | oBS_RECT_WORK.flag) & 0x80000) != 0 || (OBM_LINE_AND_LINE(lLeft, usWidth, lLeft2, usWidth2) && OBM_LINE_AND_LINE(lTop, usHeight, lTop2, usHeight2)))
						{
							ushort num3 = objRectCheckFuncCall(oBS_RECT_WORK, oBS_RECT_WORK2);
							if ((num3 & 1) != 0)
							{
								if ((oBS_RECT_WORK.flag & 0x10000) != 0)
								{
									oBS_RECT_WORK.flag |= 512u;
									oBS_RECT_WORK.flag &= 4294901759u;
								}
								GroupA.SetPrimitive(num, null);
							}
							if ((num3 & 2) != 0)
							{
								if ((oBS_RECT_WORK2.flag & 0x10000) != 0)
								{
									oBS_RECT_WORK2.flag |= 512u;
									oBS_RECT_WORK2.flag &= 4294901759u;
								}
								GroupD.SetPrimitive(num2, null);
							}
						}
					}
				}
			}
		}
	}

