	private static void _ObjRectLTBSet(OBS_RECT_WORK pRec, ref int lLeft, ref int lTop, ref int lBack, bool lLeftValid, bool lTopValid, bool lBackValid)
	{
		int num = 0;
		if (pRec.parent_obj != null && (pRec.flag & 0x1000) == 0)
		{
			if (lLeftValid)
			{
				num = ((((pRec.parent_obj.disp_flag & 1) ^ (pRec.flag & 1)) == 0) ? pRec.rect.left : (-pRec.rect.right));
				if (pRec.parent_obj.scale.x != 4096)
				{
					num = FX_Mul(num, pRec.parent_obj.scale.x);
				}
				if (_g_obj.draw_scale.x != 4096 && (pRec.parent_obj.disp_flag & 0x100000) == 0 && (_g_obj.flag & 0x400000) == 0)
				{
					num = FX_Mul(num, _g_obj.draw_scale.x);
				}
				lLeft = (pRec.parent_obj.pos.x + pRec.rect.pos.x >> 12) + num;
			}
			if (lTopValid)
			{
				num = ((((pRec.parent_obj.disp_flag & 2) ^ (pRec.flag & 2)) == 0) ? pRec.rect.top : (-pRec.rect.bottom));
				if (pRec.parent_obj.scale.y != 4096)
				{
					num = FX_Mul(num, pRec.parent_obj.scale.y);
				}
				if (_g_obj.draw_scale.y != 4096 && (pRec.parent_obj.disp_flag & 0x100000) == 0 && (_g_obj.flag & 0x400000) == 0)
				{
					num = FX_Mul(num, _g_obj.draw_scale.y);
				}
				lTop = (pRec.parent_obj.pos.y + pRec.rect.pos.y >> 12) + num;
			}
			if (lBackValid)
			{
				num = pRec.rect.back;
				if (pRec.parent_obj.scale.z != 4096)
				{
					num = FX_Mul(num, pRec.parent_obj.scale.z);
				}
				if (_g_obj.draw_scale.z != 4096 && (pRec.parent_obj.disp_flag & 0x100000) == 0 && (g_obj.flag & 0x400000) == 0)
				{
					num = FX_Mul(num, g_obj.draw_scale.z);
				}
				lBack = (pRec.parent_obj.pos.z + pRec.rect.pos.z >> 12) + num;
			}
		}
		else
		{
			if (lLeftValid)
			{
				num = (((pRec.flag & 1) == 0) ? pRec.rect.left : (-pRec.rect.right));
				lLeft = (pRec.rect.pos.x >> 12) + num;
			}
			if (lTopValid)
			{
				num = (((pRec.flag & 2) == 0) ? pRec.rect.top : (-pRec.rect.bottom));
				lTop = (pRec.rect.pos.y >> 12) + num;
			}
			if (lBackValid)
			{
				lBack = (pRec.rect.pos.z >> 12) + pRec.rect.back;
			}
		}
	}

