	private static void ObjRectWHDSet(OBS_RECT_WORK pRec, ref ushort usWidth, ref ushort usHeight, ref ushort usDepth, bool usWidthValid, bool usHeightValid, bool usDepthValid)
	{
		if (pRec.parent_obj != null && (pRec.flag & 0x1000) == 0)
		{
			if (usWidthValid)
			{
				usWidth = (ushort)(pRec.rect.right - pRec.rect.left);
				int num = 4096;
				if (pRec.parent_obj.scale.x != 4096)
				{
					num = pRec.parent_obj.scale.x;
				}
				if (_g_obj.draw_scale.x != 4096 && (pRec.parent_obj.disp_flag & 0x100000) == 0 && (_g_obj.flag & 0x400000) == 0)
				{
					num = FX_Mul(num, _g_obj.draw_scale.x);
				}
				if (num != 4096)
				{
					usWidth = (ushort)FX_Mul(usWidth, num);
