			for (int i = 0; i < nSubobj; i++)
			{
				pSubobjListDst[i].Assign(pSubobjListSrc[i]);
			}
		}
		for (int j = 0; j < nSubobj; j++)
		{
			NNS_SUBOBJ nNS_SUBOBJ = pSubobjListSrc[j];
			NNS_SUBOBJ nNS_SUBOBJ2 = null;
			if (pSubobjListDst != null)
			{
				nNS_SUBOBJ2 = pSubobjListDst[j];
				nNS_SUBOBJ2.pMeshsetList = new NNS_MESHSET[nNS_SUBOBJ.nMeshset];
				for (int k = 0; k < nNS_SUBOBJ.nMeshset; k++)
				{
					nNS_SUBOBJ2.pMeshsetList[k] = new NNS_MESHSET(nNS_SUBOBJ.pMeshsetList[k]);
				}
			}
			if (pSubobjListDst != null && nNS_SUBOBJ.nTex != 0)
			{
				nNS_SUBOBJ2.pTexNumList = new int[nNS_SUBOBJ.nTex];
				Array.Copy(nNS_SUBOBJ.pTexNumList, nNS_SUBOBJ2.pTexNumList, nNS_SUBOBJ.nTex);
			}
		}
		return 0u;
	}

	private static uint nnCopyObject(NNS_OBJECT dstobj, NNS_OBJECT srcobj, uint flag)
	{
		if (dstobj != null)
		{
			dstobj.Assign(srcobj);
			dstobj.fType |= 128u;
		}
		if (dstobj != null)
		{
			dstobj.pMatPtrList = New<NNS_MATERIALPTR>(srcobj.pMatPtrList.Length);
			nnCopyMaterialList(dstobj.pMatPtrList, srcobj.pMatPtrList, srcobj.nMaterial, flag);
		}
		else
		{
			nnCopyMaterialList(null, srcobj.pMatPtrList, srcobj.nMaterial, flag);
		}
		if (dstobj != null)
		{
			dstobj.pVtxListPtrList = New<NNS_VTXLISTPTR>(srcobj.pVtxListPtrList.Length);
			nnCopyVertexList(dstobj.pVtxListPtrList, srcobj.pVtxListPtrList, srcobj.nVtxList, flag);
		}
		else
		{
			nnCopyVertexList(null, srcobj.pVtxListPtrList, srcobj.nVtxList, flag);
		}
		if (dstobj != null)
		{
			dstobj.pPrimListPtrList = New<NNS_PRIMLISTPTR>(srcobj.pPrimListPtrList.Length);
			nnCopyPrimitiveList(dstobj.pPrimListPtrList, srcobj.pPrimListPtrList, srcobj.nPrimList, flag);
		}
		else
		{
			nnCopyPrimitiveList(null, srcobj.pPrimListPtrList, srcobj.nPrimList, flag);
		}
		if (dstobj != null)
		{
			dstobj.pNodeList = New<NNS_NODE>(srcobj.nNode);
			for (int i = 0; i < srcobj.nNode; i++)
			{
				dstobj.pNodeList[i].Assign(srcobj.pNodeList[i]);
			}
		}
		if (dstobj != null)
		{
			dstobj.pSubobjList = New<NNS_SUBOBJ>(srcobj.pSubobjList.Length);
			nnCopySubobjList(dstobj.pSubobjList, srcobj.pSubobjList, srcobj.nSubobj, flag);
		}
		else
		{
			nnCopySubobjList(null, srcobj.pSubobjList, srcobj.nSubobj, flag);
		}
		return 0u;
	}

