	private static void nnMakeQuaternionMatrix(out SNNS_MATRIX dst, ref NNS_QUATERNION quat)
	{
		float x = quat.x;
		float y = quat.y;
		float z = quat.z;
		float w = quat.w;
		float num = x * x;
		float num2 = y * y;
		float num3 = z * z;
		float num4 = w * w;
		float num5 = x * y;
		float num6 = y * z;
		float num7 = x * z;
		float num8 = x * w;
		float num9 = y * w;
		float num10 = z * w;
		float num11 = num4 - num;
		float num12 = num2 - num3;
		dst.M00 = num4 + num - num2 - num3;
		dst.M01 = 2f * (num5 - num10);
		dst.M02 = 2f * (num7 + num9);
		dst.M10 = 2f * (num5 + num10);
		dst.M11 = num11 + num12;
		dst.M12 = 2f * (num6 - num8);
		dst.M20 = 2f * (num7 - num9);
		dst.M21 = 2f * (num6 + num8);
		dst.M22 = num11 - num12;
		dst.M03 = 0f;
		dst.M13 = 0f;
		dst.M23 = 0f;
		dst.M30 = 0f;
		dst.M31 = 0f;
		dst.M32 = 0f;
		dst.M33 = 1f;
	}

	private static void nnMakeQuaternionMatrix(NNS_MATRIX dst, ref NNS_QUATERNION quat)
	{
		float x = quat.x;
		float y = quat.y;
		float z = quat.z;
		float w = quat.w;
		float num = x * x;
		float num2 = y * y;
		float num3 = z * z;
		float num4 = w * w;
		float num5 = x * y;
		float num6 = y * z;
		float num7 = x * z;
		float num8 = x * w;
		float num9 = y * w;
		float num10 = z * w;
		float num11 = num4 - num;
		float num12 = num2 - num3;
		dst.M00 = num4 + num - num2 - num3;
		dst.M01 = 2f * (num5 - num10);
		dst.M02 = 2f * (num7 + num9);
		dst.M10 = 2f * (num5 + num10);
		dst.M11 = num11 + num12;
		dst.M12 = 2f * (num6 - num8);
		dst.M20 = 2f * (num7 - num9);
		dst.M21 = 2f * (num6 + num8);
		dst.M22 = num11 - num12;
		dst.M03 = 0f;
		dst.M13 = 0f;
		dst.M23 = 0f;
		dst.M30 = 0f;
		dst.M31 = 0f;
		dst.M32 = 0f;
		dst.M33 = 1f;
	}

