	public static void nnMakePerspectiveMatrix(NNS_MATRIX mtx, int fovy, float aspect, float znear, float zfar)
	{
		int ang = fovy >> 1;
		double num = 1.0 / (double)nnTan(ang);
		mtx.M00 = (float)(num / (double)aspect);
		mtx.M01 = 0f;
		mtx.M02 = 0f;
		mtx.M03 = 0f;
		mtx.M10 = 0f;
		mtx.M11 = (float)num;
		mtx.M12 = 0f;
		mtx.M13 = 0f;
		mtx.M20 = 0f;
		mtx.M21 = 0f;
		mtx.M22 = (float)((0.0 - (double)znear) / (double)(zfar - znear));
		mtx.M23 = (float)((0.0 - (double)zfar * (double)znear) / (double)(zfar - znear));
		mtx.M30 = 0f;
		mtx.M31 = 0f;
		mtx.M32 = -1f;
		mtx.M33 = 0f;
	}

	public static void nnMakePerspectiveOffCenterMatrix(NNS_MATRIX mtx, float left, float right, float bottom, float top, float znear, float zfar)
	{
		mtx.M00 = (float)(2.0 * (double)znear / ((double)right - (double)left));
		mtx.M01 = 0f;
		mtx.M02 = (float)(((double)right + (double)left) / ((double)right - (double)left));
		mtx.M03 = 0f;
		mtx.M10 = 0f;
		mtx.M11 = (float)(2.0 * (double)znear / ((double)top - (double)bottom));
		mtx.M12 = (float)(((double)top + (double)bottom) / ((double)top - (double)bottom));
		mtx.M13 = 0f;
		mtx.M20 = 0f;
		mtx.M21 = 0f;
		mtx.M22 = (float)((0.0 - (double)znear) / (double)(zfar - znear));
		mtx.M23 = (float)((0.0 - (double)zfar * (double)znear) / (double)(zfar - znear));
		mtx.M30 = 0f;
		mtx.M31 = 0f;
		mtx.M32 = -1f;
		mtx.M33 = 0f;
	}

	public static void nnMakeOrthoMatrix(NNS_MATRIX mtx, float left, float right, float bottom, float top, float znear, float zfar)
	{
		mtx.M00 = (float)(2.0 / (double)(right - left));
		mtx.M01 = 0f;
		mtx.M02 = 0f;
		mtx.M03 = (float)((double)(0f - (right + left)) / (double)(right - left));
		mtx.M10 = 0f;
		mtx.M11 = (float)(2.0 / (double)(top - bottom));
		mtx.M12 = 0f;
		mtx.M13 = (float)((double)(0f - (top + bottom)) / (double)(top - bottom));
		mtx.M20 = 0f;
		mtx.M21 = 0f;
		mtx.M22 = (float)(-1.0 / (double)(zfar - znear));
		mtx.M23 = (float)((double)(0f - zfar) / (double)(zfar - znear));
		mtx.M30 = 0f;
		mtx.M31 = 0f;
		mtx.M32 = 0f;
		mtx.M33 = 1f;
	}

