	public void amQuatToEulerXYZ(out float rx, out float ry, out float rz, ref NNS_QUATERNION pQuat)
	{
		rx = (ry = (rz = 0f));
		NNS_QUATERNION pDst = default(NNS_QUATERNION);
		amQuatUnit(ref pDst, ref pQuat);
		float num = pDst.x * pDst.x;
		float num2 = pDst.x * pDst.y;
		float num3 = pDst.x * pDst.z;
		float num4 = pDst.x * pDst.w;
		float num5 = pDst.y * pDst.y;
		float num6 = pDst.y * pDst.z;
		float num7 = pDst.y * pDst.w;
		float num8 = pDst.z * pDst.z;
		float num9 = pDst.z * pDst.w;
		float num10 = 1f - 2f * (num5 + num8);
		float num11 = 2f * (num2 + num9);
		float num12 = 2f * (num3 - num7);
		float num13 = 1f - amPow2(num12);
		ry = (float)Math.Atan2(0f - num12, (num13 > 0f) ? Math.Sqrt(num13) : 0.0);
		num13 = (float)Math.Sqrt(amPow2(num10) + amPow2(num11));
		float num14;
		float num15;
		if (amIsZerof(num13))
		{
			num14 = 0f;
			num15 = 1f;
		}
		else
		{
			num14 = num11 / num13;
			num15 = num10 / num13;
		}
		float num16 = 2f * (num2 - num9);
		float num17 = 2f * (num3 + num7);
		float num18 = 1f - 2f * (num + num8);
		float num19 = 2f * (num6 - num4);
		float num20 = num17 * num14 - num19 * num15;
		float num21 = num18 * num15 - num16 * num14;
		rx = (float)Math.Atan2(num20, num21);
		rz = (float)Math.Atan2(num14, num15);
	}

	public void amQuatToEulerXYZ(out int ax, out int ay, out int az, ref NNS_QUATERNION pQuat)
	{
		float rx;
		float ry;
		float rz;
		amQuatToEulerXYZ(out rx, out ry, out rz, ref pQuat);
		ax = NNM_RADtoA32(rx);
		ay = NNM_RADtoA32(ry);
		az = NNM_RADtoA32(rz);
	}

	public void amQuatVectorToQuat(ref NNS_QUATERNION pQuat, NNS_VECTOR4D pV1, NNS_VECTOR4D pV2)
	{
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR2 = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR3 = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR4 = GlobalPool<NNS_VECTOR>.Alloc();
		VEC3_COPY(nNS_VECTOR, pV1);
		VEC3_COPY(nNS_VECTOR2, pV2);
		nnAddVector(nNS_VECTOR4, nNS_VECTOR, nNS_VECTOR2);
		float num = nnDotProductVector(nNS_VECTOR4, nNS_VECTOR4);
		num = (float)(1.0 / Math.Sqrt(num));
		nnScaleVector(nNS_VECTOR2, nNS_VECTOR4, num);
		nnCrossProductVector(nNS_VECTOR3, nNS_VECTOR, nNS_VECTOR2);
		VEC3_COPY(pQuat, nNS_VECTOR3);
		pQuat.w = nnDotProductVector(nNS_VECTOR, nNS_VECTOR2);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR2);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR3);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR4);
	}

	public static void amQuatRotAxisToQuat(ref NNS_QUATERNION pQuat, NNS_VECTOR4D pVec, float radian)
	{
		radian *= 0.5f;
		float pSn;
		float pCs;
		amSinCos(radian, out pSn, out pCs);
		pQuat.x = pVec.x * pSn;
		pQuat.y = pVec.y * pSn;
		pQuat.z = pVec.z * pSn;
		pQuat.w = pCs;
	}

	public static void amQuatToMatrix(NNS_MATRIX pMtx, ref NNS_QUATERNION pQuat, NNS_VECTOR4D pVec)
	{
		if (pMtx == null)
		{
			NNS_MATRIX dst = amMatrixGetCurrent();
			nnMakeQuaternionMatrix(out tempSNNS_MATRIX0, ref pQuat);
			if (pVec != null)
			{
				nnCopyVectorMatrixTranslation(ref tempSNNS_MATRIX0, (NNS_VECTOR)pVec);
			}
			nnCopyMatrix(dst, ref tempSNNS_MATRIX0);
		}
		else
		{
			nnMakeQuaternionMatrix(pMtx, ref pQuat);
			if (pVec != null)
			{
				nnCopyVectorMatrixTranslation(ref tempSNNS_MATRIX0, (NNS_VECTOR)pVec);
			}
		}
	}

