	public static void amQuatMultiVector(NNS_VECTOR4D pDst, NNS_VECTOR4D pSrc, ref NNS_QUATERNION pQuat, NNS_VECTOR4D pVec)
	{
		NNS_QUATERNION dst = default(NNS_QUATERNION);
		NNS_QUATERNION quat = default(NNS_QUATERNION);
		NNS_QUATERNION dst2 = default(NNS_QUATERNION);
		NNS_QUATERNION d_vec = default(NNS_QUATERNION);
		VEC4_COPY(ref d_vec, pSrc);
		quat.x = 0f - pQuat.x;
		quat.y = 0f - pQuat.y;
		quat.z = 0f - pQuat.z;
		quat.w = pQuat.w;
		nnMultiplyQuaternion(ref dst2, ref pQuat, ref d_vec);
		nnMultiplyQuaternion(ref dst, ref dst2, ref quat);
		if (pVec == null)
		{
			VEC4_COPY(pDst, ref dst);
			return;
		}
		NNS_VECTOR4D nNS_VECTOR4D = GlobalPool<NNS_VECTOR4D>.Alloc();
		NNS_VECTOR4D nNS_VECTOR4D2 = GlobalPool<NNS_VECTOR4D>.Alloc();
		VEC4_COPY(nNS_VECTOR4D, ref dst);
		VEC4_COPY(nNS_VECTOR4D2, pVec);
		amVectorAdd(pDst, nNS_VECTOR4D, nNS_VECTOR4D2);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D2);
	}

	public static void amQuatMultiVector(ref SNNS_VECTOR4D pDst, NNS_VECTOR4D pSrc, ref NNS_QUATERNION pQuat, NNS_VECTOR4D pVec)
	{
		NNS_QUATERNION dst = default(NNS_QUATERNION);
		NNS_QUATERNION quat = default(NNS_QUATERNION);
		NNS_QUATERNION dst2 = default(NNS_QUATERNION);
		NNS_QUATERNION d_vec = default(NNS_QUATERNION);
		VEC4_COPY(ref d_vec, pSrc);
		quat.x = 0f - pQuat.x;
		quat.y = 0f - pQuat.y;
		quat.z = 0f - pQuat.z;
		quat.w = pQuat.w;
		nnMultiplyQuaternion(ref dst2, ref pQuat, ref d_vec);
		nnMultiplyQuaternion(ref dst, ref dst2, ref quat);
		if (pVec == null)
		{
			VEC4_COPY(ref pDst, ref dst);
			return;
		}
		SNNS_VECTOR4D d_vec2 = default(SNNS_VECTOR4D);
		SNNS_VECTOR4D d_vec3 = default(SNNS_VECTOR4D);
		VEC4_COPY(ref d_vec2, ref dst);
		VEC4_COPY(ref d_vec3, pVec);
		amVectorAdd(ref pDst, ref d_vec2, ref d_vec3);
	}

	public static void amQuatMultiVector(ref SNNS_VECTOR4D pDst, ref SNNS_VECTOR4D pSrc, ref NNS_QUATERNION pQuat, NNS_VECTOR4D pVec)
	{
		NNS_QUATERNION dst = default(NNS_QUATERNION);
