		quat.w = pQuat.w;
		nnMultiplyQuaternion(ref dst2, ref pQuat, ref d_vec);
		nnMultiplyQuaternion(ref dst, ref dst2, ref quat);
		if (pVec == null)
		{
			VEC4_COPY(ref pDst, ref dst);
