	private static void HgTrophyTryAcquisition(int timing)
	{
		HGS_TROPHY_CHECK_TIMING_INFO hGS_TROPHY_CHECK_TIMING_INFO = hg_trophy_check_timing_info_tbl[timing];
		if (GsTrialIsTrial() || hgTrophyIsPlayDemo())
		{
			return;
		}
		for (int i = 0; i < hGS_TROPHY_CHECK_TIMING_INFO.num; i++)
		{
			HGS_TROPHY_CHECK_INFO hGS_TROPHY_CHECK_INFO = hGS_TROPHY_CHECK_TIMING_INFO.check_info_tbl[i];
			if (hGS_TROPHY_CHECK_INFO.trophy_type == 0)
			{
				hgTrophyTryAcquisitionNormal(hGS_TROPHY_CHECK_INFO);
			}
			else
			{
				MTM_ASSERT(false);
			}
		}
	}

	private static void HgTrophyIncEnemyKillCount(OBS_OBJECT_WORK ene_obj)
	{
		GSS_MAIN_SYS_INFO gSS_MAIN_SYS_INFO = GsGetMainSysInfo();
		if (hgTrophyIsPlayDemo() || ene_obj.obj_type != 2)
		{
			return;
		}
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)ene_obj;
		if (gMS_ENEMY_COM_WORK.eve_rec != null && (gMS_ENEMY_COM_WORK.eve_rec.id == 0 || gMS_ENEMY_COM_WORK.eve_rec.id > 0) && gMS_ENEMY_COM_WORK.eve_rec.id < 39)
		{
			if (gSS_MAIN_SYS_INFO.ene_kill_count < 1000)
			{
				gSS_MAIN_SYS_INFO.ene_kill_count++;
			}
			else
			{
				gSS_MAIN_SYS_INFO.ene_kill_count = 1000u;
			}
			HgTrophyTryAcquisition(2);
		}
	}

