	private static bool hgTrophyCheckAcquireSsonicInAllAct()
	{
		bool result = true;
		MTM_ASSERT(SyGetEvtInfo().cur_evt_id == 6);
		if (g_gm_gamedat_stage_type_tbl[g_gs_main_sys_info.stage_id] != GSE_MAIN_STAGE_TYPE.GSD_MAIN_STAGE_TYPE_ACT || g_gs_main_sys_info.stage_id == 28 || !GMM_MAIN_GOAL_AS_SUPER_SONIC())
		{
			return false;
		}
		uint num = 0u;
		while (true)
		{
			switch (num)
			{
			case 0u:
			case 1u:
			case 2u:
			case 3u:
			case 4u:
			case 5u:
			case 6u:
			case 7u:
			case 8u:
			case 9u:
			case 10u:
			case 11u:
			case 12u:
			case 13u:
			case 14u:
			case 15u:
			case 16u:
			case 17u:
			case 18u:
			case 19u:
			case 20u:
			case 21u:
			case 22u:
			case 23u:
			case 24u:
			case 25u:
			case 26u:
			case 27u:
				if (g_gm_gamedat_stage_type_tbl[num] != GSE_MAIN_STAGE_TYPE.GSD_MAIN_STAGE_TYPE_ACT)
				{
					break;
				}
				MTM_ASSERT(num < 16);
				if (num == g_gs_main_sys_info.stage_id)
				{
					if (!GMM_MAIN_GOAL_AS_SUPER_SONIC())
					{
						result = false;
					}
				}
				else if (!GsMainSysIsStageGoalAsSuperSonic((int)num))
				{
					result = false;
				}
				break;
			case 28u:
				break;
			default:
				return result;
			}
			num++;
		}
	}

