	private static OBS_OBJECT_WORK GmGmkSpringInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_SPRING");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		int num = ((eve_rec.id > 79) ? (eve_rec.id - 70 + 1 - 21) : (eve_rec.id - 70));
		if (eve_rec.id == 71 || eve_rec.id == 73 || eve_rec.id == 75 || eve_rec.id == 77)
		{
			if (eve_rec.id == 71 || eve_rec.id == 75)
			{
				ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_spring_obj_3d_list[1], gMS_ENEMY_3D_WORK.obj_3d);
			}
			else
			{
				ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_spring_obj_3d_list[2], gMS_ENEMY_3D_WORK.obj_3d);
			}
			ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, false, ObjDataGet(793), null, 0, null);
			oBS_OBJECT_WORK.user_timer = 2;
			oBS_OBJECT_WORK.user_work = 3u;
		}
		else
		{
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_spring_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
			ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, false, ObjDataGet(793), null, 0, null);
			oBS_OBJECT_WORK.user_timer = 0;
			oBS_OBJECT_WORK.user_work = 1u;
		}
		if (eve_rec.id == 78 || eve_rec.id == 79)
		{
			oBS_OBJECT_WORK.pos.z = -655360;
		}
		else
		{
			oBS_OBJECT_WORK.pos.z = -131072;
		}
		gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag &= 4294967291u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[1].flag &= 4294967291u;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		oBS_RECT_WORK.ppDef = gmGmkSpringDefFunc;
		oBS_RECT_WORK.ppHit = null;
		ObjRectAtkSet(oBS_RECT_WORK, 0, 0);
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		ObjRectWorkSet(oBS_RECT_WORK, gm_gmk_spring_rect[num][0], gm_gmk_spring_rect[num][1], gm_gmk_spring_rect[num][2], gm_gmk_spring_rect[num][3]);
		oBS_RECT_WORK.flag |= 1024u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, gm_gmk_spring_rect[num][0], gm_gmk_spring_rect[num][1], gm_gmk_spring_rect[num][2], gm_gmk_spring_rect[num][3]);
		oBS_RECT_WORK.flag &= 4294967291u;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.dir.z = gm_gmk_spring_dir[num];
		if ((eve_rec.flag & 0x10) != 0)
		{
			if (eve_rec.width >= 64)
			{
				eve_rec.width = 0;
			}
			if (!GmGmkSwitchIsOn(eve_rec.width))
			{
				gmGmkSpringSwitchOffInit(oBS_OBJECT_WORK);
			}
			else
			{
				gmGmkSpringFwInit(oBS_OBJECT_WORK);
			}
		}
		else
		{
			gmGmkSpringFwInit(oBS_OBJECT_WORK);
		}
		if (GsGetMainSysInfo().stage_id == 14)
		{
			oBS_OBJECT_WORK.obj_3d.use_light_flag = 0u;
			oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		}
		else
		{
			int nMaterial = oBS_OBJECT_WORK.obj_3d._object.nMaterial;
			if (nMaterial == 1)
			{
				NNS_MATERIAL_GLES11_DESC nNS_MATERIAL_GLES11_DESC = (NNS_MATERIAL_GLES11_DESC)oBS_OBJECT_WORK.obj_3d._object.pMatPtrList[0].pMaterial;
				nNS_MATERIAL_GLES11_DESC.fFlag |= 3u;
			}
			else
			{
				NNS_MATERIAL_GLES11_DESC[] array = (NNS_MATERIAL_GLES11_DESC[])oBS_OBJECT_WORK.obj_3d._object.pMatPtrList[0].pMaterial;
				for (int num2 = 0; num2 < nMaterial; num2++)
				{
					array[num2].fFlag |= 3u;
				}
			}
		}
		oBS_OBJECT_WORK.flag |= 1073741824u;
		return oBS_OBJECT_WORK;
	}

