	private static void gmGmkSpringFwInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		ObjDrawObjectActionSet(obj_work, obj_work.user_timer);
		if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 0x10) != 0)
		{
			obj_work.ppFunc = gmGmkSpringSwitchOnMain;
		}
		else
		{
			obj_work.ppFunc = gmGmkSpringFwMain;
		}
		if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 5) != 0)
		{
			obj_work.disp_flag |= 32u;
		}
	}

	private static void gmGmkSpringFwMain(OBS_OBJECT_WORK obj_work)
	{
	}

	private static void gmGmkSpringActInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		ObjDrawObjectActionSet(obj_work, (int)obj_work.user_work);
		obj_work.ppFunc = gmGmkSpringActMain;
		if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 4) != 0)
		{
			obj_work.disp_flag |= 32u;
		}
		else
		{
			obj_work.disp_flag &= 4294967263u;
		}
	}

	private static void gmGmkSpringActMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if ((obj_work.disp_flag & 8) != 0)
		{
			gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294573823u;
			gmGmkSpringFwInit(obj_work);
		}
	}

	private static void gmGmkSpringDefFunc(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		int fall_dir = -1;
		if (gMS_ENEMY_COM_WORK != null && gMS_PLAYER_WORK != null && gMS_PLAYER_WORK.obj_work.obj_type == 1)
		{
			gmGmkSpringActInit((OBS_OBJECT_WORK)gMS_ENEMY_COM_WORK);
			int num = MTM_MATH_CLIP(gMS_ENEMY_COM_WORK.eve_rec.left, 0, 7);
			if (gMS_ENEMY_COM_WORK.eve_rec.id == 76 || gMS_ENEMY_COM_WORK.eve_rec.id == 72)
			{
				num = MTM_MATH_CLIP(num, 0, 5);
			}
			int num2 = 30720;
			num2 += 6144 * num;
			int num3 = -num2;
			if (gMS_ENEMY_COM_WORK.eve_rec.id == 74 || gMS_ENEMY_COM_WORK.eve_rec.id == 70)
			{
				num2 = 0;
			}
			else if (gMS_ENEMY_COM_WORK.eve_rec.id == 72 || gMS_ENEMY_COM_WORK.eve_rec.id == 76)
			{
				num3 = 0;
			}
			else
			{
				num2 = num2 * 181 >> 8;
				num3 = num3 * 181 >> 8;
			}
			if (73 <= gMS_ENEMY_COM_WORK.eve_rec.id && gMS_ENEMY_COM_WORK.eve_rec.id <= 75)
			{
				num3 = -num3;
			}
			if ((75 <= gMS_ENEMY_COM_WORK.eve_rec.id && gMS_ENEMY_COM_WORK.eve_rec.id <= 77) || gMS_ENEMY_COM_WORK.eve_rec.id == 79 || gMS_ENEMY_COM_WORK.eve_rec.id == 101)
			{
				num2 = -num2;
			}
			if ((gMS_ENEMY_COM_WORK.eve_rec.id == 76 || gMS_ENEMY_COM_WORK.eve_rec.id == 72) && (gMS_ENEMY_COM_WORK.eve_rec.flag & 2) == 0)
			{
				gMS_PLAYER_WORK.obj_work.pos.y = gMS_PLAYER_WORK.obj_work.pos.y + 8192;
			}
			if (1 <= gMS_ENEMY_COM_WORK.eve_rec.height && gMS_ENEMY_COM_WORK.eve_rec.height <= 4)
			{
				fall_dir = (gMS_ENEMY_COM_WORK.eve_rec.height - 1) * 16384;
			}
			GmPlySeqInitSpringJump(gMS_PLAYER_WORK, num2, num3, (gMS_ENEMY_COM_WORK.eve_rec.flag & 8) != 0, (gMS_ENEMY_COM_WORK.eve_rec.top >= 0) ? (gMS_ENEMY_COM_WORK.eve_rec.top * 4096) : 0, fall_dir, (gMS_ENEMY_COM_WORK.eve_rec.flag & 0x20) != 0);
			GmComEfctCreateSpring(gMS_ENEMY_COM_WORK.obj_work, (mine_rect.rect.left + mine_rect.rect.right) * 4096 / 2, (mine_rect.rect.top + mine_rect.rect.bottom) * 4096 / 2);
			if ((gMS_ENEMY_COM_WORK.eve_rec.flag & 0x40) != 0 && (g_gs_main_sys_info.game_flag & 0x200) != 0)
			{
				gMS_PLAYER_WORK.gmk_flag2 |= 512u;
			}
		}
	}

	private static void gmGmkSpringSwitchOffInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		ObjDrawObjectActionSet(obj_work, obj_work.user_timer);
		obj_work.ppFunc = gmGmkSpringSwitchOffMain;
		obj_work.disp_flag |= 32u;
		obj_work.flag |= 2u;
	}

	private static void gmGmkSpringSwitchOffMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if (GmGmkSwitchIsOn(gMS_ENEMY_3D_WORK.ene_com.eve_rec.width))
		{
			obj_work.disp_flag &= 4294967263u;
			obj_work.flag &= 4294967293u;
			GmComEfctCreateSpring(obj_work, (gMS_ENEMY_3D_WORK.ene_com.rect_work[2].rect.left + gMS_ENEMY_3D_WORK.ene_com.rect_work[2].rect.right) * 4096 / 2, (gMS_ENEMY_3D_WORK.ene_com.rect_work[2].rect.top + gMS_ENEMY_3D_WORK.ene_com.rect_work[2].rect.bottom) * 4096 / 2);
			gmGmkSpringFwInit(obj_work);
		}
	}

	private static void gmGmkSpringSwitchOnMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if (!GmGmkSwitchIsOn(gMS_ENEMY_3D_WORK.ene_com.eve_rec.width))
		{
			gmGmkSpringSwitchOffInit(obj_work);
		}
	}

