	private static GMS_ENEMY_3D_WORK gmGmkShutterLoadObj(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		int num = g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id];
		int num2;
		switch (num)
		{
		case 1:
			num2 = 0;
			break;
		case 4:
			num2 = 0;
			break;
		default:
			return null;
		}
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = gmGmkShutterLoadObjNoModel(eve_rec, pos_x, pos_y, type);
		OBS_OBJECT_WORK obj_work = gMS_ENEMY_3D_WORK.ene_com.obj_work;
		ObjObjectCopyAction3dNNModel(obj_work, g_gm_gmk_shutter_obj_3d_list[num2], gMS_ENEMY_3D_WORK.obj_3d);
		if (num == 4)
		{
			GMS_GMK_SHUTTER_WORK gMS_GMK_SHUTTER_WORK = (GMS_GMK_SHUTTER_WORK)obj_work;
			int num3 = 2;
			ObjCopyAction3dNNModel(g_gm_gmk_shutter_obj_3d_list[num3], gMS_GMK_SHUTTER_WORK.obj_3d_parts);
			ObjAction3dNNMaterialMotionLoad(gMS_GMK_SHUTTER_WORK.obj_3d_parts, 0, null, null, 1, (AMS_AMB_HEADER)ObjDataGet(940).pData);
		}
		return gMS_ENEMY_3D_WORK;
	}

