	private static void gmGmkShutterInInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.obj = gMS_ENEMY_3D_WORK.ene_com.obj_work;
		gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.width = 64;
		gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.height = 64;
		gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.ofst_x = (short)(-gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.width / 2);
		gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.ofst_y = (short)(-gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.height / 2);
		obj_work.move_flag |= 256u;
		obj_work.disp_flag |= 4194336u;
		obj_work.flag |= 16u;
		gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 16384u;
		obj_work.pos.z = -655360;
		obj_work.user_work = (uint)(obj_work.pos.y - 262144);
		obj_work.ppFunc = gmGmkShutterInMainWaitClose;
		int num = g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id];
		if (num == 4)
		{
			obj_work.ppOut = gmGmkShutterInOutFuncForFinalZone;
			mtTaskChangeTcbDestructor(obj_work.tcb, gmGmkShutterDestFuncForFinaleZone);
		}
	}

	private static void gmGmkShutterInOutFuncForFinalZone(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SHUTTER_WORK gMS_GMK_SHUTTER_WORK = (GMS_GMK_SHUTTER_WORK)obj_work;
		obj_work.ofst.x = gm_gmk_shutter_disp_offset_for_final_zone[0] * 4096;
		obj_work.ofst.y = gm_gmk_shutter_disp_offset_for_final_zone[1] * 4096;
		ObjDrawActionSummary(obj_work);
		VecFx32 pos = obj_work.pos;
		pos.x += obj_work.ofst.x;
		pos.y += obj_work.ofst.y;
		uint p_disp_flag = obj_work.disp_flag | 4;
		if (ObjObjectPauseCheck(0u) == 0)
		{
			ObjDrawAction3DNNMaterialUpdate(gMS_GMK_SHUTTER_WORK.obj_3d_parts, ref p_disp_flag);
		}
		ObjDrawAction3DNN(gMS_GMK_SHUTTER_WORK.obj_3d_parts, pos, obj_work.dir, obj_work.scale, ref p_disp_flag);
	}

	private static void gmGmkShutterInMainWaitClose(OBS_OBJECT_WORK obj_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)g_gm_main_system.ply_work[0];
		if (oBS_OBJECT_WORK.pos.x - obj_work.pos.x >= 262144)
		{
			GmGmkShutterInChangeModeClose(obj_work);
		}
	}

	private static void gmGmkShutterInMainClose(OBS_OBJECT_WORK obj_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)g_gm_main_system.ply_work[0];
		int a = (int)(obj_work.user_work - obj_work.pos.y);
		if (MTM_MATH_ABS(oBS_OBJECT_WORK.pos.x - obj_work.pos.x) < 131072 && oBS_OBJECT_WORK.pos.y <= obj_work.pos.y && MTM_MATH_ABS(a) < 262144)
		{
			int num = g_gm_main_system.map_fcol.left + (g_gm_main_system.map_fcol.right - g_gm_main_system.map_fcol.left) / 2;
			if ((oBS_OBJECT_WORK.move_flag & 1) != 0)
			{
				int num2 = 16384;
				if (num * 4096 < oBS_OBJECT_WORK.pos.x)
				{
					num2 *= -1;
				}
				oBS_OBJECT_WORK.flow.x += num2;
			}
			else
			{
				int num3 = 4096;
				if (num * 4096 < oBS_OBJECT_WORK.pos.x)
				{
					num3 *= -1;
				}
				GmPlySeqGmkInitGmkJump((GMS_PLAYER_WORK)oBS_OBJECT_WORK, num3, 0);
				GmPlySeqChangeSequenceState((GMS_PLAYER_WORK)oBS_OBJECT_WORK, 17);
			}
		}
		if (obj_work.pos.y <= (int)obj_work.user_work)
		{
			obj_work.pos.y = (int)obj_work.user_work;
			obj_work.spd.y = 0;
			obj_work.ppFunc = null;
			obj_work.ppMove = null;
			GMS_GMK_SHUTTER_WORK gMS_GMK_SHUTTER_WORK = (GMS_GMK_SHUTTER_WORK)obj_work;
			if (gMS_GMK_SHUTTER_WORK.effect_work != null)
			{
				ObjDrawKillAction3DES((OBS_OBJECT_WORK)gMS_GMK_SHUTTER_WORK.effect_work);
				gMS_GMK_SHUTTER_WORK.effect_work = null;
			}
		}
	}

