		gmGmkRockFallMgrSetInterval(gMS_GMK_ROCK_FALL_MGR_WORK, eve_rec.left * 60);
		gmGmkRockFallMgrSetUserTimer(obj_work, eve_rec.left * 60);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GmEventMgrLocalEventBirth(306, obj_work.pos.x, obj_work.pos.y - eve_rec.top * 2 * 4096 + 262144, eve_rec.flag, eve_rec.left, eve_rec.top, eve_rec.width, eve_rec.height, 0);
