	private static void gmGmkRockFallDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		VecU16 vecU = new VecU16(obj_work.dir);
		GMS_GMK_ROCK_FALL_WORK gMS_GMK_ROCK_FALL_WORK = (GMS_GMK_ROCK_FALL_WORK)obj_work;
		ushort roll = gMS_GMK_ROCK_FALL_WORK.roll;
		obj_work.dir.y = roll;
		ushort z = (ushort)obj_work.user_work;
		obj_work.dir.z = z;
		obj_work.dir.z += roll;
		ObjDrawActionSummary(obj_work);
		ObjDrawActionSummary(obj_work);
		obj_work.dir.Assign(vecU);
	}

	private static void gmGmkRockChaseDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_ROCK_CHASE_WORK gMS_GMK_ROCK_CHASE_WORK = (GMS_GMK_ROCK_CHASE_WORK)obj_work;
		VecU16 vecU = new VecU16(obj_work.dir);
		ushort z = gmGmkRockChaseGetAngleZ(gMS_GMK_ROCK_CHASE_WORK);
		if (obj_work.spd_m < 0)
		{
			obj_work.dir.z = z;
		}
		else
		{
			obj_work.dir.z = z;
		}
		ushort x = (ushort)obj_work.user_work;
		obj_work.dir.x = x;
		obj_work.pos.y += gMS_GMK_ROCK_CHASE_WORK.current_bound;
		ObjDrawActionSummary(obj_work);
		ObjDrawActionSummary(obj_work);
		obj_work.dir.Assign(vecU);
		obj_work.pos.y -= gMS_GMK_ROCK_CHASE_WORK.current_bound;
	}

	private static void gmGmkRockChaseTcbDest(MTS_TASK_TCB tcb)
	{
		GMS_GMK_ROCK_CHASE_WORK gMS_GMK_ROCK_CHASE_WORK = (GMS_GMK_ROCK_CHASE_WORK)mtTaskGetTcbWork(tcb);
		if (gMS_GMK_ROCK_CHASE_WORK.se_handle != null)
		{
			GmSoundStopSE(gMS_GMK_ROCK_CHASE_WORK.se_handle);
			GsSoundFreeSeHandle(gMS_GMK_ROCK_CHASE_WORK.se_handle);
			gMS_GMK_ROCK_CHASE_WORK.se_handle = null;
		}
		GmEnemyDefaultExit(tcb);
	}

