	private static void gmGmkRockChaseMainFall(OBS_OBJECT_WORK obj_work)
	{
		if ((obj_work.move_flag & 1) != 0)
		{
			GmSoundPlaySE("BigRock1");
			GmCameraVibrationSet(0, 12288, 0);
			gmGmkRockChaseChangeModeChase(obj_work);
			return;
		}
		OBS_OBJECT_WORK obj_work2 = g_gm_main_system.ply_work[0].obj_work;
		if (obj_work2.pos.y < obj_work.pos.y - 2097152)
		{
			gmGmkRockChaseChangeModeEnd(obj_work);
		}
	}

	private static void gmGmkRockChaseMainChase(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_ROCK_CHASE_WORK gMS_GMK_ROCK_CHASE_WORK = (GMS_GMK_ROCK_CHASE_WORK)obj_work;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_OBJECT_WORK target_obj = gMS_ENEMY_3D_WORK.ene_com.target_obj;
		int num = 0;
		int num2 = 0;
		int num3 = target_obj.pos.x - obj_work.pos.x;
		uint num4 = gmGmkRockChaseGetDirType(gMS_GMK_ROCK_CHASE_WORK);
		if (num4 == 0)
		{
			num4 = ((obj_work.dir.z <= NNM_DEGtoA16(180f)) ? 1u : 2u);
			gmGmkRockChaseSetDirType(gMS_GMK_ROCK_CHASE_WORK, num4);
		}
		if ((num4 == 1 && num3 < 0) || (num4 == 2 && num3 >= 0))
		{
			num2 = 768;
			num = 32768;
			if (gMS_GMK_ROCK_CHASE_WORK.flag_vib)
			{
				GMM_PAD_VIB_STOP();
				gMS_GMK_ROCK_CHASE_WORK.flag_vib = false;
			}
		}
		else
		{
			int num5 = MTM_MATH_ABS(target_obj.spd_m);
			if (num5 < gmGmkRockChaseGetSpeed(gMS_GMK_ROCK_CHASE_WORK))
			{
				num2 = 512;
				num = 65536;
			}
			else
			{
				int num6 = MTM_MATH_ABS(num3);
				int num7 = gmGmkRockChaseGetLength(gMS_GMK_ROCK_CHASE_WORK);
				int num8 = FX_Mul(num7, 8192);
				if (num8 < 1228800)
				{
					num8 = 1228800;
				}
				if (num6 > num8)
				{
					num2 = 3840;
					num = (int)((long)num5 + 32768L);
					if (gMS_GMK_ROCK_CHASE_WORK.flag_vib)
					{
						GMM_PAD_VIB_STOP();
						gMS_GMK_ROCK_CHASE_WORK.flag_vib = false;
					}
				}
				else if (num6 > num7)
				{
					num2 = 768;
					num = (int)((long)num5 + 10240L);
					if (!gMS_GMK_ROCK_CHASE_WORK.flag_vib)
					{
						GMM_PAD_VIB_MID_NOEND();
						gMS_GMK_ROCK_CHASE_WORK.flag_vib = true;
					}
				}
				else
				{
					num2 = -768;
					num = (int)((long)num5 + -6144L);
					if (!gMS_GMK_ROCK_CHASE_WORK.flag_vib)
					{
						GMM_PAD_VIB_MID_NOEND();
						gMS_GMK_ROCK_CHASE_WORK.flag_vib = true;
					}
				}
			}
		}
		if (num4 == 1)
		{
			obj_work.spd_m += num2;
			gmGmkRockChaseAddAngleZ(gMS_GMK_ROCK_CHASE_WORK, 1000);
			if (obj_work.spd_m > num)
			{
				obj_work.spd_m = num;
			}
		}
		else
		{
			num2 = -num2;
			num = -num;
			obj_work.spd_m += num2;
			gmGmkRockChaseAddAngleZ(gMS_GMK_ROCK_CHASE_WORK, -1000);
			if (obj_work.spd_m < num)
			{
				obj_work.spd_m = num;
			}
		}
		if ((obj_work.move_flag & 1) == 0)
		{
			gmGmkRockChaseChangeModeFall(obj_work);
		}
		else if (gMS_GMK_ROCK_CHASE_WORK.current_bound >= 0)
		{
			gMS_GMK_ROCK_CHASE_WORK.current_bound = 0;
			if (mtMathRand() % 10 == 0)
			{
				int num9 = 32 + mtMathRand() % 16;
				gMS_GMK_ROCK_CHASE_WORK.target_bound = -num9 * 4096;
				gMS_GMK_ROCK_CHASE_WORK.current_bound -= 8192;
				if (gMS_GMK_ROCK_CHASE_WORK.se_handle != null)
				{
					GmSoundStopSE(gMS_GMK_ROCK_CHASE_WORK.se_handle);
				}
			}
		}
		else if (gMS_GMK_ROCK_CHASE_WORK.target_bound > gMS_GMK_ROCK_CHASE_WORK.current_bound)
		{
			gMS_GMK_ROCK_CHASE_WORK.target_bound = 0;
			gMS_GMK_ROCK_CHASE_WORK.current_bound += 8192;
			if (gMS_GMK_ROCK_CHASE_WORK.current_bound >= 0)
			{
				GmSoundPlaySE("BigRock1");
				GmSoundPlaySE("BigRock2", gMS_GMK_ROCK_CHASE_WORK.se_handle);
				GmCameraVibrationSet(0, 12288, 0);
			}
		}
		else
		{
			gMS_GMK_ROCK_CHASE_WORK.current_bound -= 8192;
		}
	}

