	private static void gmGmkRockManagerMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_ROCK_FALL_MGR_WORK gMS_GMK_ROCK_FALL_MGR_WORK = (GMS_GMK_ROCK_FALL_MGR_WORK)obj_work;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		int num = gmGmkRockFallMgrGetInterval(gMS_GMK_ROCK_FALL_MGR_WORK);
		int num2 = gmGmkRockFallMgrGetUserTimer(obj_work);
		if (num2 >= num)
		{
			gmGmkRockFallMgrSetUserTimer(obj_work, 0);
			byte type = 0;
			if (num >= 120)
			{
				type = 1;
			}
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GmEventMgrLocalEventBirth(300, obj_work.pos.x, obj_work.pos.y - gMS_ENEMY_3D_WORK.ene_com.eve_rec.top * 2 * 4096, gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag, gMS_ENEMY_3D_WORK.ene_com.eve_rec.left, gMS_ENEMY_3D_WORK.ene_com.eve_rec.top, gMS_ENEMY_3D_WORK.ene_com.eve_rec.width, gMS_ENEMY_3D_WORK.ene_com.eve_rec.height, type);
			oBS_OBJECT_WORK.spd_fall = 336;
			oBS_OBJECT_WORK.spd_fall_max = 32768;
			GMS_GMK_ROCK_FALL_WORK gMS_GMK_ROCK_FALL_WORK = (GMS_GMK_ROCK_FALL_WORK)oBS_OBJECT_WORK;
			gMS_GMK_ROCK_FALL_WORK.hook_work = gMS_GMK_ROCK_FALL_MGR_WORK.hook_work;
		}
		gmGmkRockFallMgrAddUserTimer(obj_work, 1);
	}

	private static void gmGmkRockFallInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gimmick_work = (GMS_ENEMY_3D_WORK)obj_work;
		gmGmkRockSetRectActive(gimmick_work);
		obj_work.move_flag |= 384u;
		obj_work.disp_flag |= 4194304u;
		obj_work.pos.z = -131072;
		obj_work.user_work = mtMathRand();
		GMS_GMK_ROCK_FALL_WORK gMS_GMK_ROCK_FALL_WORK = (GMS_GMK_ROCK_FALL_WORK)obj_work;
		gMS_GMK_ROCK_FALL_WORK.roll = mtMathRand();
		gMS_GMK_ROCK_FALL_WORK.roll_d = 128;
		if (gMS_GMK_ROCK_FALL_WORK.roll % 2 != 0)
		{
			gMS_GMK_ROCK_FALL_WORK.roll_d = (ushort)(-gMS_GMK_ROCK_FALL_WORK.roll_d);
		}
		obj_work.ppFunc = gmGmkRockFallMainStart;
		obj_work.ppMove = gmGmkRockMoveFunc;
		obj_work.ppOut = gmGmkRockFallDrawFunc;
	}

	private static void gmGmkRockFallMainStart(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_ROCK_FALL_WORK gMS_GMK_ROCK_FALL_WORK = (GMS_GMK_ROCK_FALL_WORK)obj_work;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gMS_GMK_ROCK_FALL_WORK.hook_work;
		if (oBS_OBJECT_WORK.pos.y + 98304 <= obj_work.pos.y)
		{
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctZoneEsCreate(obj_work, 2, 17);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.z = 131072;
			GmSoundPlaySE("BigRock4");
			obj_work.pos.y = oBS_OBJECT_WORK.pos.y + 98304;
			GmCameraVibrationSet(0, 4096, 0);
			obj_work.move_flag &= 4294967167u;
			obj_work.spd.y = 0;
			obj_work.ppFunc = gmGmkRockFallMainWait;
		}
	}

	private static void gmGmkRockFallMainWait(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_ROCK_FALL_WORK gMS_GMK_ROCK_FALL_WORK = (GMS_GMK_ROCK_FALL_WORK)obj_work;
		OBS_OBJECT_WORK obj_work2 = (OBS_OBJECT_WORK)gMS_GMK_ROCK_FALL_WORK.hook_work;
		obj_work.user_timer++;
		if (obj_work.user_timer >= gMS_GMK_ROCK_FALL_WORK.wait_time)
		{
			obj_work.user_timer = 0;
			obj_work.move_flag |= 128u;
			gmGmkRockHookkChangeModeActive(obj_work2);
			gMS_GMK_ROCK_FALL_WORK.hook_work = null;
			GmSoundPlaySE("BigRock5");
			obj_work.ppFunc = gmGmkRockFallMainFallWaitEffect;
		}
	}

	private static void gmGmkRockFallMainFallWaitEffect(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_ROCK_FALL_WORK gMS_GMK_ROCK_FALL_WORK = (GMS_GMK_ROCK_FALL_WORK)obj_work;
		gMS_GMK_ROCK_FALL_WORK.roll += gMS_GMK_ROCK_FALL_WORK.roll_d;
		obj_work.user_timer++;
		if (obj_work.user_timer >= 30)
		{
			obj_work.user_timer = 0;
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctZoneEsCreate(obj_work, 2, 32);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = null;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.y -= 262144;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.z = 131072;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.parent_ofst.y = 204800;
			gMS_GMK_ROCK_FALL_WORK.effect_work = gMS_EFFECT_3DES_WORK;
			obj_work.ppFunc = gmGmkRockFallMainFall;
		}
	}

	private static void gmGmkRockFallMainFall(OBS_OBJECT_WORK obj_work)
