	private static void gmGmkCapsuleSwitchMain(OBS_OBJECT_WORK obj_work)
	{
		OBS_COLLISION_OBJ obj_col = obj_work.col_work.obj_col;
		if (obj_col.rider_obj != null)
		{
			obj_work.ofst.y = 24576;
			if ((obj_work.user_flag & 1) == 0)
			{
				g_gm_main_system.game_flag &= 4294966271u;
				g_gm_main_system.game_flag |= 1048576u;
				GMS_EFFECT_3DES_WORK efct_3des = GmEfctCmnEsCreate(obj_work, 23);
				GmEffect3DESSetDispOffset(efct_3des, 0f, 24f, 40f);
				gmGmkCapsuleAnimalMake(obj_work);
				obj_work.user_timer = 1;
				GMS_EVE_RECORD_EVENT gMS_EVE_RECORD_EVENT = new GMS_EVE_RECORD_EVENT();
				gMS_EVE_RECORD_EVENT.flag = 7;
				gMS_EVE_RECORD_EVENT.left = -96;
				gMS_EVE_RECORD_EVENT.top = -104;
				gMS_EVE_RECORD_EVENT.width = 192;
				gMS_EVE_RECORD_EVENT.height = 112;
				GmGmkCamScrLimitSet(gMS_EVE_RECORD_EVENT, obj_work.pos.x, obj_work.pos.y);
				GMM_PAD_VIB_SMALL();
				GmSoundPlaySE("Capsule");
				GmPlySeqChangeBossGoal(g_gm_main_system.ply_work[0], obj_work.pos.x, obj_work.pos.y);
			}
			obj_work.user_flag |= 1u;
		}
		else
		{
			obj_work.ofst.y = 0;
		}
		if (obj_work.user_timer != 0)
		{
			obj_work.user_timer++;
			if (obj_work.user_timer == 420)
			{
				g_gm_main_system.game_flag |= 4u;
			}
		}
	}

