			obj_work.move_flag &= 4294959103u;
			obj_work.move_flag |= 128u;
			obj_work.ppFunc = null;
			GMS_EFFECT_3DES_WORK efct_3des = GmEfctCmnEsCreate(obj_work, 21);
			GmEffect3DESSetDispOffset(efct_3des, 0f, 46f, 40f);
			efct_3des = GmEfctCmnEsCreate(obj_work, 22);
			GmEffect3DESSetDispOffset(efct_3des, 0f, 46f, 40f);
		}
	}

