	public static ushort gmGmkBubbleGameSystemGetWaterLevel()
	{
		return g_gm_main_system.water_level;
	}

	public static void gmGmkBubbleManagerInit(OBS_OBJECT_WORK obj_work)
	{
		obj_work.move_flag |= 8448u;
		gmGmkBubbleSetUserTimerCounter(obj_work, 0u);
		obj_work.ppFunc = gmGmkBubbleManagerMainWait;
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctZoneEsCreate(obj_work, 2, 4);
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = gmGmkBubbleManagerEffectMain;
	}

	public static void gmGmkBubbleManagerMainWait(OBS_OBJECT_WORK obj_work)
	{
		int num = gmGmkBubbleGameSystemGetWaterLevel() * 4096;
		if (num <= obj_work.pos.y)
		{
			GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
			uint num2 = gmGmkBubbleGetUserTimerCounter(obj_work);
			if ((uint)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.top * 60) < num2)
			{
				obj_work.ppFunc = gmGmkBubbleManagerMain;
			}
			gmGmkBubbleAddUserTimerCounter(obj_work, 1);
		}
	}

	public static void gmGmkBubbleManagerMain(OBS_OBJECT_WORK obj_work)
	{
		int num = gmGmkBubbleGameSystemGetWaterLevel() * 4096;
		if (num <= obj_work.pos.y)
		{
			uint num2 = gmGmkBubbleGetUserWorkIntervalNormal(obj_work);
			if (num2 == 0)
			{
				num2 = 60u;
			}
			uint num3 = gmGmkBubbleGetUserTimerCounter(obj_work);
			if (num3 % num2 == 0)
			{
				GMS_EFFECT_3DES_WORK effect_work = GmEfctZoneEsCreate(obj_work, 2, 1);
				gmGmkBubbleInit(effect_work);
			}
			gmGmkBubbleAddUserTimerCounter(obj_work, 1);
		}
	}

	public static void gmGmkBubbleManagerEffectMain(OBS_OBJECT_WORK obj_work)
	{
		int num = gmGmkBubbleGameSystemGetWaterLevel() * 4096;
		if (num > obj_work.pos.y)
		{
			obj_work.disp_flag |= 32u;
		}
		else
		{
			obj_work.disp_flag &= 4294967263u;
		}
	}

	public static void gmGmkBubbleInit(GMS_EFFECT_3DES_WORK effect_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)effect_work;
		oBS_OBJECT_WORK.flag &= 4294967293u;
		oBS_OBJECT_WORK.move_flag &= 4294958847u;
		oBS_OBJECT_WORK.move_flag |= 4608u;
		oBS_OBJECT_WORK.spd.y = (int)(-GMD_GMK_BUBBLE_SPEED_Y);
		oBS_OBJECT_WORK.pos.z = 1048576;
		OBS_RECT_WORK[] rect_work = effect_work.efct_com.rect_work;
		GmEffectRectInit(effect_work.efct_com, gm_gmk_bubble_table_atk, gm_gmk_bubble_table_def, 1, 1);
		ObjRectWorkSet(rect_work[0], -8, 7, 8, 8);
		rect_work[0].flag |= 1028u;
		rect_work[0].ppDef = gmGmkBubbleDefFunc;
		rect_work[1].flag |= 3072u;
		oBS_OBJECT_WORK.ppFunc = gmGmkBubbleMainMoveLeft;
	}

	public static void gmGmkBubbleDefFunc(OBS_RECT_WORK own_rect, OBS_RECT_WORK target_rect)
	{
		OBS_OBJECT_WORK parent_obj = own_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = target_rect.parent_obj;
		if (parent_obj2.obj_type == 1)
		{
			GMS_PLAYER_WORK ply_work = (GMS_PLAYER_WORK)parent_obj2;
			GmPlySeqInitBreathing(ply_work);
			GmPlayerBreathingSet(ply_work);
			parent_obj.flag |= 4u;
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctZoneEsCreate(null, 2, 3);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.x = parent_obj.pos.x;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.y = parent_obj.pos.y;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.z = parent_obj.pos.z;
			GMM_PAD_VIB_SMALL();
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = gmGmkBubbleMainHit;
		}
	}

	public static void gmGmkBubbleMainMoveLeft(OBS_OBJECT_WORK obj_work)
	{
		obj_work.spd.x = gmGmkBubbleAddUserWorkSpeedX(obj_work, (int)(-GMD_GMK_BUBBLE_SPEED_X_ADD));
		if (obj_work.spd.x < -GMD_GMK_BUBBLE_SPEED_X_MAX)
		{
			obj_work.ppFunc = gmGmkBubbleMainMoveRight;
		}
		int num = gmGmkBubbleGameSystemGetWaterLevel() * 4096;
		if (num > obj_work.pos.y)
		{
			obj_work.ppFunc = gmGmkBubbleMainEnd;
		}
	}

	public static void gmGmkBubbleMainMoveRight(OBS_OBJECT_WORK obj_work)
	{
		obj_work.spd.x = gmGmkBubbleAddUserWorkSpeedX(obj_work, (int)GMD_GMK_BUBBLE_SPEED_X_ADD);
		if (obj_work.spd.x > GMD_GMK_BUBBLE_SPEED_X_MAX)
		{
			obj_work.ppFunc = gmGmkBubbleMainMoveLeft;
		}
		int num = gmGmkBubbleGameSystemGetWaterLevel() * 4096;
		if (num > obj_work.pos.y)
		{
			obj_work.ppFunc = gmGmkBubbleMainEnd;
		}
	}

	public static void gmGmkBubbleMainHit(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_timer++;
		int num = GMD_GMK_BUBBLE_FRAME_HIT_DELETE - obj_work.user_timer;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (num < GMD_GMK_BUBBLE_HIT_EFFECT_NUM)
		{
			GmPlyEfctCreateBubble(gMS_PLAYER_WORK);
		}
		if (num > 0)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gMS_PLAYER_WORK;
			int num2 = oBS_OBJECT_WORK.pos.x - obj_work.pos.x;
			int num3 = oBS_OBJECT_WORK.pos.y - GMD_GMK_BUBBLE_OFFSET_Y * 4096 - obj_work.pos.y;
			num2 = (((oBS_OBJECT_WORK.disp_flag & 1) == 0) ? (num2 + GMD_GMK_BUBBLE_OFFSET_X * 4096) : (num2 - GMD_GMK_BUBBLE_OFFSET_X * 4096));
			obj_work.spd.x = num2 / num;
			obj_work.spd.y = num3 / num;
		}
		else
		{
			obj_work.user_timer = 0;
			obj_work.flag |= 4u;
		}
	}

	public static void gmGmkBubbleMainEnd(OBS_OBJECT_WORK obj_work)
	{
		obj_work.flag |= 4u;
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctZoneEsCreate(null, 2, 2);
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.x = obj_work.pos.x;
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.y = obj_work.pos.y;
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.z = obj_work.pos.z;
	}

	public static void gmGmkBubbleSetUserWorkIntervalNormal(OBS_OBJECT_WORK obj_work, ushort interval)
	{
		obj_work.user_work |= (uint)(interval << 16);
	}

	public static ushort gmGmkBubbleGetUserWorkIntervalNormal(OBS_OBJECT_WORK obj_work)
	{
		return (ushort)(obj_work.user_work >> 16);
	}

	public static void gmGmkBubbleSetUserTimerCounter(OBS_OBJECT_WORK obj_work, uint count)
	{
		obj_work.user_timer = (int)count;
	}

	public static void gmGmkBubbleAddUserTimerCounter(OBS_OBJECT_WORK obj_work, int count)
	{
		obj_work.user_timer += count;
	}

	public static uint gmGmkBubbleGetUserTimerCounter(OBS_OBJECT_WORK obj_work)
	{
		return (uint)obj_work.user_timer;
	}

	public static int gmGmkBubbleAddUserWorkSpeedX(OBS_OBJECT_WORK obj_work, int speed)
	{
		obj_work.user_work += (uint)speed;
		return (int)obj_work.user_work;
	}

