	private static void gmEneUniuniNeedleWaitInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneUniuniNeedleWaitMain;
		obj_work.move_flag &= 4294967291u;
		obj_work.spd.x = 0;
		obj_work.spd.y = 0;
	}

	private static void gmEneUniuniNeedleWaitMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_UNIUNI_WORK gMS_ENE_UNIUNI_WORK = (GMS_ENE_UNIUNI_WORK)obj_work;
		GMS_ENE_UNIUNI_WORK gMS_ENE_UNIUNI_WORK2 = (GMS_ENE_UNIUNI_WORK)obj_work.parent_obj;
		int rot_y = gMS_ENE_UNIUNI_WORK2.rot_y;
		int rot_x = gMS_ENE_UNIUNI_WORK2.rot_x;
		int rot_z = gMS_ENE_UNIUNI_WORK2.rot_z;
		float len = gMS_ENE_UNIUNI_WORK2.len;
		rot_y += AKM_DEGtoA32(360) / 4 * gMS_ENE_UNIUNI_WORK.num;
		rot_y %= AKM_DEGtoA32(360);
		SNNS_MATRIX dst;
		nnMakeRotateXMatrix(out dst, rot_x);
		nnRotateZMatrix(ref dst, ref dst, rot_z);
		nnRotateYMatrix(ref dst, ref dst, rot_y);
		SNNS_MATRIX dst2;
		nnMakeTranslateMatrix(out dst2, len, 0f, 0f);
		SNNS_MATRIX dst3;
		nnMultiplyMatrix(out dst3, ref dst, ref dst2);
		SNNS_VECTOR dst4;
		nnCopyMatrixTranslationVector(out dst4, ref dst3);
		obj_work.pos.x = FX_F32_TO_FX32(dst4.x) + gMS_ENE_UNIUNI_WORK2.ene_3d_work.ene_com.obj_work.pos.x;
		obj_work.pos.y = FX_F32_TO_FX32(dst4.y) + gMS_ENE_UNIUNI_WORK2.ene_3d_work.ene_com.obj_work.pos.y;
		obj_work.pos.z = 655360;
		if (gMS_ENE_UNIUNI_WORK2.attack != 0 && (double)dst4.y >= (double)len * 0.98)
		{
			obj_work.ppFunc = gmEneUniuniNeedleAttackInit;
		}
	}

	private static void gmEneUniuniNeedleAttackInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_UNIUNI_WORK gMS_ENE_UNIUNI_WORK = (GMS_ENE_UNIUNI_WORK)obj_work.parent_obj;
		gMS_ENE_UNIUNI_WORK.num--;
		if ((gMS_ENE_UNIUNI_WORK.ene_3d_work.ene_com.obj_work.disp_flag & 1) != 0)
		{
			obj_work.spd.x = -FX_F32_TO_FX32(1f);
		}
		else
		{
			obj_work.spd.x = FX_F32_TO_FX32(1f);
		}
		obj_work.parent_obj = null;
		obj_work.ppFunc = gmEneUniuniNeedleAttackMain;
	}

