	public static OBS_OBJECT_WORK GmEneMoguInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENE_MOGU_WORK(), "ENE_MOGU");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_ENE_MOGU_WORK gMS_ENE_MOGU_WORK = (GMS_ENE_MOGU_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_mogu_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(676), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.z = 0;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -11, -24, 11, 0);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -32, 19, 0);
		oBS_RECT_WORK.flag |= 4u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -32, 19, 0);
		oBS_RECT_WORK.flag &= 4294967291u;
		ObjObjectFieldRectSet(oBS_OBJECT_WORK, -4, -44, 4, -38);
		oBS_OBJECT_WORK.move_flag |= 128u;
		if ((eve_rec.flag & 1) == 0)
		{
			oBS_OBJECT_WORK.disp_flag |= 1u;
		}
		oBS_OBJECT_WORK.user_work = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left << 12));
		oBS_OBJECT_WORK.user_flag = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left + eve_rec.width << 12));
		gMS_ENE_MOGU_WORK.spd_dec = 102;
		gMS_ENE_MOGU_WORK.spd_dec_dist = 20480;
		gMS_ENE_MOGU_WORK.flag = 0u;
		gmEneMoguWaitInit(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

	public static int gmEneMoguCheckWater(GMS_ENE_MOGU_WORK mogu_work, short ofst)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)mogu_work;
		if (GmMainIsWaterLevel())
		{
			if ((oBS_OBJECT_WORK.pos.y >> 12) - ofst >= g_gm_main_system.water_level)
			{
				if ((mogu_work.flag & 1) == 0 && (mogu_work.flag & 2) != 0)
				{
					GmEfctCmnEsCreate(oBS_OBJECT_WORK, 76);
					GmSoundPlaySE("Spray");
				}
				mogu_work.flag |= 1u;
				return 1;
			}
			if ((mogu_work.flag & 1) != 0)
			{
				if ((mogu_work.flag & 2) != 0)
				{
					GmEfctCmnEsCreate(oBS_OBJECT_WORK, 76);
					GmSoundPlaySE("Spray");
				}
				mogu_work.flag &= 4294967294u;
				return 1;
			}
			return 0;
		}
		return 0;
	}

	public static void gmEneMoguWaitInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		ObjDrawObjectActionSet(obj_work, 4);
		obj_work.disp_flag |= 4u;
		obj_work.pos.z = -655360;
		obj_work.ppFunc = gmEneMoguWaitMain;
	}

	public static void gmEneMoguWaitMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_MOGU_WORK mogu_work = (GMS_ENE_MOGU_WORK)obj_work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		int num = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
		int num2 = gMS_PLAYER_WORK.obj_work.pos.y - obj_work.pos.y;
		int num3 = FX_Mul(num, num) + FX_Mul(num2, num2);
		if (num3 > FX_F32_TO_FX32(25600f))
		{
			return;
		}
		obj_work.ppFunc = gmEneMoguJumpInit;
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK;
		if (gmEneMoguCheckWater(mogu_work, 48) == 0)
		{
			gMS_EFFECT_3DES_WORK = GmEfctEneEsCreate(obj_work, 7);
			if (g_gs_main_sys_info.stage_id == 9)
			{
				gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.z = 393216;
			}
		}
		else
		{
			gMS_EFFECT_3DES_WORK = GmEfctEneEsCreate(obj_work, 8);
		}
		GmComEfctSetDispOffsetF(gMS_EFFECT_3DES_WORK, 0f, -30f, 0f);
	}

	public static void gmEneMoguJumpInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_MOGU_WORK gMS_ENE_MOGU_WORK = (GMS_ENE_MOGU_WORK)obj_work;
		ObjDrawObjectActionSet(obj_work, 4);
		obj_work.disp_flag |= 4u;
		obj_work.spd.y = FX_F32_TO_FX32(-6f);
		obj_work.spd_fall = FX_F32_TO_FX32(0.16f);
		obj_work.pos.y -= FX_F32_TO_FX32(4f);
		obj_work.move_flag |= 128u;
		obj_work.move_flag &= 4294967294u;
		obj_work.move_flag &= 4294967291u;
		obj_work.ppFunc = gmEneMoguJumpMain;
		if ((obj_work.disp_flag & 1) != 0)
		{
			obj_work.spd.x = -2048;
		}
		else
		{
			obj_work.spd.x = 2048;
		}
		gmEneMoguCheckWater(gMS_ENE_MOGU_WORK, 0);
		gMS_ENE_MOGU_WORK.jumpdown = 0;
	}

	public static void gmEneMoguJumpMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_MOGU_WORK gMS_ENE_MOGU_WORK = (GMS_ENE_MOGU_WORK)obj_work;
		if ((obj_work.disp_flag & 1) != 0)
		{
			obj_work.spd.x = -2048;
		}
		else
		{
			obj_work.spd.x = 2048;
		}
		if (obj_work.spd.y > 0)
		{
			if (gMS_ENE_MOGU_WORK.jumpdown == 0)
			{
				gMS_ENE_MOGU_WORK.jumpdown = 1;
				ObjDrawObjectActionSet(obj_work, 5);
				obj_work.disp_flag |= 4u;
				obj_work.move_flag &= 4294967039u;
				ObjObjectFieldRectSet(obj_work, -4, -8, 4, -2);
				obj_work.pos.z = 0;
				gMS_ENE_MOGU_WORK.flag |= 2u;
			}
			if ((obj_work.move_flag & 4) != 0)
			{
				if ((obj_work.disp_flag & 1) != 0)
				{
					obj_work.disp_flag &= 4294967294u;
				}
				else
				{
					obj_work.disp_flag |= 1u;
				}
			}
		}
		if ((obj_work.move_flag & 1) != 0)
		{
			GmEneComActionSetDependHFlip(obj_work, 0, 1);
			obj_work.ppFunc = gmEneMoguJumpEnd;
		}
		gmEneMoguCheckWater(gMS_ENE_MOGU_WORK, 0);
	}

	public static void gmEneMoguJumpEnd(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_MOGU_WORK mogu_work = (GMS_ENE_MOGU_WORK)obj_work;
		gmEneMoguCheckWater(mogu_work, 0);
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.ppFunc = gmEneMoguWalkInit;
		}
	}

