	public static void gmEneMoguWalkMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		GMS_ENE_MOGU_WORK gMS_ENE_MOGU_WORK = (GMS_ENE_MOGU_WORK)obj_work;
		gmEneMoguCheckWater(gMS_ENE_MOGU_WORK, 0);
		int num = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
		int num2 = gMS_PLAYER_WORK.obj_work.pos.y - obj_work.pos.y;
		int num3 = FX_Mul(num, num) + FX_Mul(num2, num2);
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)obj_work;
		if ((gMS_ENEMY_COM_WORK.eve_rec.flag & 2) != 0)
		{
			num3 = FX_F32_TO_FX32(6400f) + 1;
			gMS_ENE_MOGU_WORK.wait_time = 216000;
		}
		if (num3 > FX_F32_TO_FX32(6400f))
		{
			if (gMS_ENE_MOGU_WORK.wait_time > 0)
			{
				gMS_ENE_MOGU_WORK.wait_time--;
				if ((obj_work.move_flag & 4) != 0)
				{
					gmEneMoguJumpInit(obj_work);
				}
			}
			else
			{
				if (AkMathRandFx() > FX_F32_TO_FX32(0.5f))
				{
					gmEneMoguFlipInit(obj_work);
				}
				gMS_ENE_MOGU_WORK.wait_time = 216000;
			}
			return;
		}
		gMS_ENE_MOGU_WORK.wait_time = 0;
		if ((obj_work.disp_flag & 1) != 0)
		{
			if (GmEneComTargetIsLeft(obj_work, gMS_PLAYER_WORK.obj_work) == 0)
			{
				gmEneMoguFlipInit(obj_work);
			}
		}
		else if (GmEneComTargetIsLeft(obj_work, gMS_PLAYER_WORK.obj_work) != 0)
		{
			gmEneMoguFlipInit(obj_work);
		}
		if ((obj_work.move_flag & 4) != 0)
		{
			gmEneMoguJumpInit(obj_work);
		}
	}

