	public static int gmEneMoguSetWalkSpeed(GMS_ENE_MOGU_WORK mogu_work)
	{
		int result = 0;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)mogu_work;
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			if (oBS_OBJECT_WORK.obj_3d.act_id[0] == 3 && oBS_OBJECT_WORK.obj_3d.frame[0] >= 20f)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, mogu_work.spd_dec, 2048);
			}
			else if (oBS_OBJECT_WORK.pos.x <= (int)oBS_OBJECT_WORK.user_work + mogu_work.spd_dec_dist)
			{
