		}
		else if (oBS_OBJECT_WORK.pos.x >= (int)oBS_OBJECT_WORK.user_flag - mogu_work.spd_dec_dist)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdDownSet(oBS_OBJECT_WORK.spd.x, mogu_work.spd_dec);
			result = 1;
			if (oBS_OBJECT_WORK.spd.x == 0 && oBS_OBJECT_WORK.pos.x < (int)oBS_OBJECT_WORK.user_flag)
			{
