		OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
		oBS_CAMERA.scale = 0.67438334f;
		oBS_CAMERA.ofst.z = 1000f;
		gm_camera_vibration.x = 0f;
		gm_camera_vibration.y = 0f;
		gm_camera_vibration.z = 0f;
