			ObjCameraInit(1, pos, 4, 0, 8192);
			ObjCamera3dInit(1);
			ObjCameraSetUserFunc(1, gmCameraFuncMapFar);
			oBS_CAMERA = ObjCameraGet(1);
			oBS_CAMERA.command_state = 1u;
			if (2 == num)
			{
				oBS_CAMERA.fovy = NNM_DEGtoA32(45f);
			}
			else
			{
				oBS_CAMERA.fovy = NNM_DEGtoA32(45f);
			}
			oBS_CAMERA.znear = 0.1f;
			oBS_CAMERA.zfar = 32768f;
		}
		NNS_VECTOR pos2 = new NNS_VECTOR(177f, -15800f, 50f);
		int[] array = new int[4] { 2, 3, 4, 5 };
		int[] array2 = new int[4] { 0, 4, 6, 8 };
		uint[] array3 = new uint[4] { 7u, 0u, 0u, 0u };
		for (int i = 0; i < 4; i++)
		{
			if (g_gm_gamedat_map_set_add[array2[i]] != null)
			{
				ObjCameraInit(array[i], pos2, 4, 0, 8192);
				ObjCamera3dInit(array[i]);
				ObjCameraSetUserFunc(array[i], gmCameraFuncAddMap);
				OBS_CAMERA oBS_CAMERA2 = ObjCameraGet(array[i]);
				oBS_CAMERA2.scale = 0.67438334f;
				oBS_CAMERA2.ofst.z = 1000f;
				oBS_CAMERA2.command_state = array3[i];
			}
		}
		NNS_VECTOR pos3 = new NNS_VECTOR(nNS_VECTOR.x, nNS_VECTOR.y, nNS_VECTOR.z);
		ObjCameraInit(6, pos3, 4, 0, 8192);
		ObjCamera3dInit(6);
		ObjCameraSetUserFunc(6, gmCameraFuncWater);
		oBS_CAMERA = ObjCameraGet(6);
		oBS_CAMERA.command_state = 9u;
		oBS_CAMERA.scale = 0.67438334f;
		oBS_CAMERA.ofst.z = 1000f;
	}

