	private static void GmCameraTruckFunc(OBS_CAMERA obj_camera)
	{
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0 && (gMS_PLAYER_WORK.player_flag & 0x10000) == 0)
		{
			GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
			return;
		}
		nNS_VECTOR.x = FXM_FX32_TO_FLOAT(gMS_PLAYER_WORK.obj_work.pos.x);
		nNS_VECTOR.y = FXM_FX32_TO_FLOAT(-gMS_PLAYER_WORK.obj_work.pos.y + 24576);
		nNS_VECTOR.z = FXM_FX32_TO_FLOAT(gMS_PLAYER_WORK.obj_work.pos.z);
		obj_camera.work.x = nNS_VECTOR.x;
		obj_camera.work.y = nNS_VECTOR.y;
		obj_camera.work.z = nNS_VECTOR.z;
		obj_camera.prev_pos.x = obj_camera.pos.x;
		obj_camera.prev_pos.y = obj_camera.pos.y;
		obj_camera.prev_pos.z = obj_camera.pos.z;
		if ((obj_camera.flag & 1) != 0)
		{
			if (obj_camera.target_obj != null)
			{
				obj_camera.pos.x = nNS_VECTOR.x;
				obj_camera.pos.y = nNS_VECTOR.y;
				obj_camera.pos.z = nNS_VECTOR.z;
			}
			GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
			return;
		}
		if ((obj_camera.flag & 2) != 0)
		{
			obj_camera.pos.x = ObjShiftSetF(obj_camera.pos.x, nNS_VECTOR.x, obj_camera.shift, obj_camera.spd_max.x, obj_camera.spd_add.x);
			obj_camera.pos.y = ObjShiftSetF(obj_camera.pos.y, nNS_VECTOR.x, obj_camera.shift, obj_camera.spd_max.y, obj_camera.spd_add.y);
			obj_camera.pos.z = ObjShiftSetF(obj_camera.pos.z, nNS_VECTOR.x, obj_camera.shift, obj_camera.spd_max.z, obj_camera.spd_add.z);
		}
		else
		{
			obj_camera.allow.x = obj_camera.allow_limit.x;
			obj_camera.allow.z = obj_camera.allow_limit.z;
			if ((gMS_PLAYER_WORK.obj_work.move_flag & 0x10) != 0)
			{
				obj_camera.allow.y = obj_camera.allow_limit.y;
			}
			else
			{
				obj_camera.allow.y = Math.Max(obj_camera.allow.y - 4f, 0f);
			}
			if (nNS_VECTOR.x < obj_camera.pos.x - obj_camera.allow.x)
			{
				nNS_VECTOR.x += obj_camera.allow.x;
			}
			else if (nNS_VECTOR.x > obj_camera.pos.x + obj_camera.allow.x)
			{
				nNS_VECTOR.x -= obj_camera.allow.x;
			}
			else
			{
				nNS_VECTOR.x = obj_camera.pos.x;
			}
			if (nNS_VECTOR.y < obj_camera.pos.y - obj_camera.allow.y)
			{
				nNS_VECTOR.y += obj_camera.allow.y;
			}
			else if (nNS_VECTOR.y > obj_camera.pos.y + obj_camera.allow.y)
			{
				nNS_VECTOR.y -= obj_camera.allow.y;
			}
			else
			{
				nNS_VECTOR.y = obj_camera.pos.y;
			}
			if (nNS_VECTOR.x != obj_camera.pos.x)
			{
				obj_camera.spd.x = ObjSpdUpSetF(obj_camera.spd.x, obj_camera.spd_add.x, obj_camera.spd_max.x);
			}
			else
			{
				obj_camera.spd.x = ObjSpdDownSetF(obj_camera.spd.x, obj_camera.spd_add.x);
			}
			if (nNS_VECTOR.y != obj_camera.pos.y)
			{
				obj_camera.spd.y = ObjSpdUpSetF(obj_camera.spd.y, obj_camera.spd_add.y, obj_camera.spd_max.y);
			}
			else
			{
				obj_camera.spd.y = ObjSpdDownSetF(obj_camera.spd.y, obj_camera.spd_add.y);
			}
			if (nNS_VECTOR.z != obj_camera.pos.z)
			{
				obj_camera.spd.z = ObjSpdUpSetF(obj_camera.spd.z, obj_camera.spd_add.z, obj_camera.spd_max.z);
			}
			else
			{
				obj_camera.spd.z = ObjSpdDownSetF(obj_camera.spd.z, obj_camera.spd_add.z);
			}
			if (nNS_VECTOR.x > obj_camera.pos.x)
			{
				obj_camera.pos.x += obj_camera.spd.x;
				if (obj_camera.pos.x > nNS_VECTOR.x)
				{
					obj_camera.pos.x = nNS_VECTOR.x;
				}
			}
			else
			{
				obj_camera.pos.x -= obj_camera.spd.x;
				if (obj_camera.pos.x < nNS_VECTOR.x)
				{
					obj_camera.pos.x = nNS_VECTOR.x;
				}
			}
			if (nNS_VECTOR.y > obj_camera.pos.y)
			{
				obj_camera.pos.y += obj_camera.spd.y;
				if (obj_camera.pos.y > nNS_VECTOR.y)
				{
					obj_camera.pos.y = nNS_VECTOR.y;
				}
			}
			else
			{
				obj_camera.pos.y -= obj_camera.spd.y;
				if (obj_camera.pos.y < nNS_VECTOR.y)
				{
					obj_camera.pos.y = nNS_VECTOR.y;
				}
			}
			if (nNS_VECTOR.z > obj_camera.pos.z)
			{
				obj_camera.pos.z += obj_camera.spd.z;
				if (obj_camera.pos.z > nNS_VECTOR.z)
				{
					obj_camera.pos.z = nNS_VECTOR.z;
				}
			}
			else
			{
				obj_camera.pos.z -= obj_camera.spd.z;
				if (obj_camera.pos.z < nNS_VECTOR.z)
				{
					obj_camera.pos.z = nNS_VECTOR.z;
				}
			}
		}
		if (MTM_MATH_ABS(nNS_VECTOR.z - obj_camera.pos.z) > obj_camera.play_ofst_max.z)
		{
			if (nNS_VECTOR.z > obj_camera.pos.z)
			{
				obj_camera.pos.z = nNS_VECTOR.z - obj_camera.play_ofst_max.z;
			}
			else
			{
				obj_camera.pos.z = nNS_VECTOR.z + obj_camera.play_ofst_max.z;
			}
		}
		obj_camera.disp_ofst.x = gm_camera_vibration.x / 16f;
		obj_camera.disp_ofst.y = gm_camera_vibration.y / 16f;
		obj_camera.disp_ofst.z = gm_camera_vibration.z / 16f;
		gm_camera_vibration.x = gmCameraVibCheck(gm_camera_vibration.x);
		gm_camera_vibration.y = gmCameraVibCheck(gm_camera_vibration.y);
		gm_camera_vibration.z = gmCameraVibCheck(gm_camera_vibration.z);
		obj_camera.pos.z = 50f;
		NNS_VECTOR nNS_VECTOR2 = GlobalPool<NNS_VECTOR>.Alloc();
		nNS_VECTOR2.x = obj_camera.ofst.x;
		nNS_VECTOR2.y = obj_camera.ofst.y;
		nNS_VECTOR2.z = obj_camera.ofst.z;
		if (obj_camera.scale < 0.67438334f)
		{
			float num = obj_camera.scale - 0.33719167f;
			num /= 0.33719167f;
			nNS_VECTOR2.x *= num;
			nNS_VECTOR2.y *= num;
		}
		obj_camera.disp_pos.x = obj_camera.pos.x + nNS_VECTOR2.x;
		obj_camera.disp_pos.y = obj_camera.pos.y + nNS_VECTOR2.y;
		obj_camera.disp_pos.z = obj_camera.pos.z + nNS_VECTOR2.z;
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR2);
		gmCameraLookupCheck(obj_camera);
		float num2 = (float)g_gm_main_system.map_fcol.left + (float)(GSD_DISP_WIDTH / 2) * obj_camera.scale;
		float num3 = (float)g_gm_main_system.map_fcol.right - (float)(GSD_DISP_WIDTH / 2) * obj_camera.scale;
		float num4 = (float)g_gm_main_system.map_fcol.top + (float)(GSD_DISP_HEIGHT / 2) * obj_camera.scale;
		float num5 = (float)g_gm_main_system.map_fcol.bottom - (float)(GSD_DISP_HEIGHT / 2) * obj_camera.scale;
		if (obj_camera.disp_pos.x < num2)
		{
			obj_camera.disp_pos.x = num2;
		}
		if (obj_camera.disp_pos.x > num3)
		{
			obj_camera.disp_pos.x = num3;
		}
		if (obj_camera.disp_pos.y > 0f - num4)
		{
			obj_camera.disp_pos.y = 0f - num4;
		}
		if (obj_camera.disp_pos.y < 0f - num5)
		{
			obj_camera.disp_pos.y = 0f - num5;
		}
		obj_camera.target_pos.Assign(obj_camera.disp_pos);
		obj_camera.target_pos.z -= 50f;
		int num6 = 4608;
		if ((gMS_PLAYER_WORK.gmk_flag2 & 0x20) != 0)
		{
			num6 = 672;
		}
		int num7 = -gMS_PLAYER_WORK.ply_pseudofall_dir - obj_camera.roll;
		if (num7 > 32768)
		{
			num7 -= 65536;
		}
		else if (num7 < -32768)
		{
			num7 += 65536;
		}
		int num8;
		if (MTM_MATH_ABS(num7) < 128)
		{
			num8 = num7;
		}
		else
		{
			num8 = num7 >> 4;
			if (MTM_MATH_ABS(num8) > 3328)
			{
				num8 += num8 - 3328;
			}
			if (MTM_MATH_ABS(num8) > num6)
			{
				num8 = ((num8 < 0) ? (-num6) : num6);
			}
			else if (MTM_MATH_ABS(num8) < 128)
			{
				num8 = ((num8 < 0) ? (-128) : 128);
			}
		}
		obj_camera.roll += num8;
		if (obj_camera.roll > 65536)
		{
			obj_camera.roll -= 65536;
			gMS_PLAYER_WORK.ply_pseudofall_dir += 65536;
		}
		else if (obj_camera.roll < -65536)
		{
			obj_camera.roll += 65536;
			gMS_PLAYER_WORK.ply_pseudofall_dir -= 65536;
		}
		ObjObjectCameraSet(FXM_FLOAT_TO_FX32(obj_camera.disp_pos.x - (float)(OBD_LCD_X / 2)), FXM_FLOAT_TO_FX32(0f - obj_camera.disp_pos.y - (float)(OBD_LCD_Y / 2)), FXM_FLOAT_TO_FX32(obj_camera.disp_pos.x - (float)(OBD_LCD_X / 2)), FXM_FLOAT_TO_FX32(0f - obj_camera.disp_pos.y - (float)(OBD_LCD_Y / 2)));
		GmCameraSetClipCamera(obj_camera);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	private static float gmCameraVibCheck(float vib)
	{
		if (vib != 0f)
		{
			if (vib > 0f)
			{
				vib = 0f - (vib - 1f);
				if (vib > 0f)
				{
					vib = 0f;
				}
			}
			else
			{
				vib = 0f - (vib + 1f);
				if (vib < 0f)
				{
					vib = 0f;
				}
			}
		}
		return vib;
	}

	private static void gmCameraLookupCheck(OBS_CAMERA obj_camera)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		int num = 0;
		if (GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			return;
		}
		if (gMS_PLAYER_WORK.seq_state == 4 && (gMS_PLAYER_WORK.key_on & 1) != 0)
		{
			num = 1;
		}
		if (gMS_PLAYER_WORK.seq_state == 7 && (gMS_PLAYER_WORK.key_on & 2) != 0)
		{
			num = 2;
		}
		if ((gm_camera_work.flag & num) != 0 && gm_camera_work.timer > 90)
		{
			if ((gm_camera_work.flag & 1) != 0)
			{
				gm_camera_work.offset += 2;
			}
			else
			{
				gm_camera_work.offset -= 2;
			}
			int num2 = gMS_PLAYER_WORK.camera_ofst_y >> 12;
			gm_camera_work.offset = MTM_MATH_CLIP(gm_camera_work.offset, -96 - num2, 80 - num2);
		}
		else
		{
			if ((gm_camera_work.flag & num) != 0)
			{
				gm_camera_work.timer++;
			}
			else if (num != 0)
			{
				gm_camera_work.flag = num;
				gm_camera_work.timer = 1;
			}
			else
			{
				gm_camera_work.flag = 0;
				gm_camera_work.timer = 0;
			}
			if (gm_camera_work.offset > 0)
			{
				gm_camera_work.offset -= 2;
				if (gm_camera_work.offset < 0)
				{
					gm_camera_work.offset = 0;
				}
			}
			else if (gm_camera_work.offset < 0)
			{
				gm_camera_work.offset += 2;
				if (gm_camera_work.offset > 0)
				{
					gm_camera_work.offset = 0;
				}
			}
		}
		switch ((ushort)(obj_camera.roll + 8192 >> 14))
		{
		case 0:
			obj_camera.disp_pos.y += gm_camera_work.offset;
			break;
		case 1:
			obj_camera.disp_pos.x -= gm_camera_work.offset;
			break;
		case 2:
			obj_camera.disp_pos.y -= gm_camera_work.offset;
			break;
		case 3:
			obj_camera.disp_pos.x += gm_camera_work.offset;
			break;
		}
	}

	private static void gmCameraScaleChange(OBS_CAMERA obj_camera)
	{
		if (gm_camera_work.scale_now == gm_camera_work.scale_target)
		{
			return;
		}
		if (gm_camera_work.scale_now < gm_camera_work.scale_target)
		{
			gm_camera_work.scale_now += gm_camera_work.scale_spd;
			if (gm_camera_work.scale_now > gm_camera_work.scale_target)
			{
				gm_camera_work.scale_now = gm_camera_work.scale_target;
			}
		}
		else if (gm_camera_work.scale_now > gm_camera_work.scale_target)
		{
			gm_camera_work.scale_now -= gm_camera_work.scale_spd;
			if (gm_camera_work.scale_now < gm_camera_work.scale_target)
			{
				gm_camera_work.scale_now = gm_camera_work.scale_target;
			}
		}
		obj_camera.scale = 0.67438334f / gm_camera_work.scale_now;
	}

	public static OBS_OBJECT_WORK GmBoss5RocketInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_BOSS5_ROCKET_WORK(), "BOSS5_RKT");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_BOSS5_ROCKET_WORK rkt_work = (GMS_BOSS5_ROCKET_WORK)oBS_OBJECT_WORK;
		ObjObjectFieldRectSet(oBS_OBJECT_WORK, -16, -16, 16, 16);
		oBS_OBJECT_WORK.move_flag |= 256u;
		oBS_OBJECT_WORK.move_flag &= 4294443007u;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, GmBoss5GetObject3dList()[3], gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(747), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.obj_3d.blend_spd = GMD_BOSS5_DEFAULT_BLEND_SPD;
		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.move_flag |= 16u;
		gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 32768u;
		gmBoss5RocketSetRectSize(rkt_work, 1);
		gMS_ENEMY_3D_WORK.ene_com.rect_work[1].ppHit = gmBoss5RocketAtkPlyHitFunc;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[0].ppDef = gmBoss5RocketDamageDefFunc;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag |= 2048u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag |= 2048u;
		GmBsCmnSetAction(oBS_OBJECT_WORK, 0, 1, 0);
		gmBoss5RocketInitCallbacks(rkt_work);
		oBS_OBJECT_WORK.ppFunc = gmBoss5RocketMain;
		oBS_OBJECT_WORK.ppOut = gmBoss5RocketOutFunc;
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmBoss5RocketExit);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

