	public static GMS_BOSS5_ROCKET_WORK gmBoss5RocketCreate(GMS_BOSS5_BODY_WORK body_work, int rkt_type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GmEventMgrLocalEventBirth(332, oBS_OBJECT_WORK.pos.x, oBS_OBJECT_WORK.pos.y, 0, 0, 0, 0, 0, 0);
		GMS_BOSS5_ROCKET_WORK gMS_BOSS5_ROCKET_WORK = (GMS_BOSS5_ROCKET_WORK)oBS_OBJECT_WORK2;
		oBS_OBJECT_WORK2.parent_obj = oBS_OBJECT_WORK;
		gMS_BOSS5_ROCKET_WORK.rkt_type = rkt_type;
		if (1 == rkt_type)
		{
			gMS_BOSS5_ROCKET_WORK.arm_snm_id = body_work.armpt_snm_reg_ids[1][2];
		}
		else
		{
			gMS_BOSS5_ROCKET_WORK.arm_snm_id = body_work.armpt_snm_reg_ids[0][2];
		}
		oBS_OBJECT_WORK2.disp_flag |= 16777216u;
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			nnMakeRotateXMatrix(oBS_OBJECT_WORK2.obj_3d.user_obj_mtx_r, AKM_DEGtoA32(180));
			oBS_OBJECT_WORK2.disp_flag |= 1u;
		}
		else
		{
			nnMakeRotateXMatrix(oBS_OBJECT_WORK2.obj_3d.user_obj_mtx_r, AKM_DEGtoA32(0));
			oBS_OBJECT_WORK2.disp_flag &= 4294967294u;
		}
		return (GMS_BOSS5_ROCKET_WORK)oBS_OBJECT_WORK2;
	}

	public static void gmBoss5RocketSetAtkBodyRect(GMS_BOSS5_ROCKET_WORK rkt_work)
