		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_COM_WORK.rect_work[1];
		ObjRectGroupSet(oBS_RECT_WORK, 0, 2);
		ObjRectAtkSet(oBS_RECT_WORK, 2, 1);
		ObjRectDefSet(oBS_RECT_WORK, ushort.MaxValue, 0);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK.ppHit = gmBoss5RocketAtkBossHitFunc;
		oBS_RECT_WORK.ppDef = null;
