	public static void gmBoss5RocketUpdateNoHitTime(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		if (rkt_work.no_hit_timer != 0)
		{
			rkt_work.no_hit_timer--;
			return;
		}
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)rkt_work;
		gMS_ENEMY_COM_WORK.rect_work[0].flag &= 4294965247u;
		gMS_ENEMY_COM_WORK.rect_work[1].flag &= 4294965247u;
	}

