	public static int gmBoss5RocketSetPlyRebound(OBS_RECT_WORK rkt_rect, OBS_RECT_WORK ply_rect)
	{
		OBS_OBJECT_WORK parent_obj = ply_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = rkt_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)parent_obj;
		OBS_OBJECT_WORK parent_obj3 = parent_obj2.parent_obj;
		GmPlySeqAtkReactionInit(gMS_PLAYER_WORK);
		if (gMS_PLAYER_WORK.seq_state == 20)
		{
			GmPlySeqSetJumpState(gMS_PLAYER_WORK, 0, 5u);
			uint num = GmBsCmnCheckRectHitSideVFirst(rkt_rect, ply_rect);
			gMS_PLAYER_WORK.obj_work.spd_m = 0;
			if ((num & GMD_BS_CMN_RECT_HIT_SIDE_H_MASK) != 0)
			{
				if ((num & GMD_BS_CMN_RECT_HIT_SIDE_LEFT) != 0)
				{
					gMS_PLAYER_WORK.obj_work.spd.x = -16384;
				}
				else
				{
					gMS_PLAYER_WORK.obj_work.spd.x = 16384;
				}
			}
			else if (gMS_PLAYER_WORK.obj_work.move.x > 0)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = -16384;
			}
			else if (gMS_PLAYER_WORK.obj_work.move.x < 0)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = 16384;
			}
			else if (gMS_PLAYER_WORK.obj_work.pos.x < parent_obj3.pos.x)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = 16384;
			}
			else if (parent_obj3.pos.x < gMS_PLAYER_WORK.obj_work.pos.x)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = -16384;
			}
			else if ((gMS_PLAYER_WORK.obj_work.disp_flag & 1) != 0)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = 16384;
			}
			else
			{
				gMS_PLAYER_WORK.obj_work.spd.x = -16384;
			}
			gMS_PLAYER_WORK.obj_work.spd.y = -16384;
			GmPlySeqSetNoJumpMoveTime(gMS_PLAYER_WORK, 49152);
		}
		else
		{
			uint num2 = GmBsCmnCheckRectHitSideVFirst(rkt_rect, ply_rect);
			gMS_PLAYER_WORK.obj_work.spd_m = 0;
			if ((num2 & GMD_BS_CMN_RECT_HIT_SIDE_H_MASK) != 0)
			{
				if ((num2 & GMD_BS_CMN_RECT_HIT_SIDE_LEFT) != 0)
				{
					gMS_PLAYER_WORK.obj_work.spd.x = -12288;
				}
				else
				{
					gMS_PLAYER_WORK.obj_work.spd.x = 12288;
				}
			}
			else if (gMS_PLAYER_WORK.obj_work.move.x > 0)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = -12288;
			}
			else if (gMS_PLAYER_WORK.obj_work.move.x < 0)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = 12288;
			}
			else if (gMS_PLAYER_WORK.obj_work.pos.x < parent_obj3.pos.x)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = 12288;
			}
			else if (parent_obj3.pos.x < gMS_PLAYER_WORK.obj_work.pos.x)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = -12288;
			}
			else if ((gMS_PLAYER_WORK.obj_work.disp_flag & 1) != 0)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = 12288;
			}
			else
			{
				gMS_PLAYER_WORK.obj_work.spd.x = -12288;
			}
			gMS_PLAYER_WORK.obj_work.spd.y = -16384;
			GmPlySeqSetNoJumpMoveTime(gMS_PLAYER_WORK, 32768);
			gMS_PLAYER_WORK.homing_timer = 40960;
		}
		return 1;
	}

	public static void gmBoss5RocketUpdateRocketStuckWithArm(GMS_BOSS5_ROCKET_WORK rkt_work, int b_rotation)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		NNS_MATRIX ofst_mtx;
		if ((gMS_BOSS5_BODY_WORK.flag & 0x10) != 0)
		{
			int num = ((rkt_work.rkt_type == 1) ? 1 : 0);
			ofst_mtx = gMS_BOSS5_BODY_WORK.rkt_ofst_mtx[num];
		}
		else
		{
			ofst_mtx = null;
		}
		if (gMS_BOSS5_BODY_WORK.adj_hgap_is_active != 0)
		{
			GmBsCmnUpdateObject3DNNStuckWithNode(oBS_OBJECT_WORK, gMS_BOSS5_BODY_WORK.snm_work, rkt_work.arm_snm_id, b_rotation, ofst_mtx);
		}
		else
		{
			GmBsCmnUpdateObject3DNNStuckWithNodeRelative(oBS_OBJECT_WORK, gMS_BOSS5_BODY_WORK.snm_work, rkt_work.arm_snm_id, b_rotation, oBS_OBJECT_WORK.parent_obj.pos, gMS_BOSS5_BODY_WORK.pivot_prev_pos, ofst_mtx);
		}
		if (b_rotation != 0 && rkt_work.rkt_type == 1)
		{
			oBS_OBJECT_WORK.disp_flag |= 16777216u;
			nnRotateYMatrix(oBS_OBJECT_WORK.obj_3d.user_obj_mtx_r, oBS_OBJECT_WORK.obj_3d.user_obj_mtx_r, AKM_DEGtoA32(180));
		}
	}

	public static void gmBoss5RocketInitRocketStuckWithArmLerpRot(GMS_BOSS5_ROCKET_WORK rkt_work, float ratio_spd)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		NNS_MATRIX src_mtx = GmBsCmnGetSNMMtx(rkt_work.snm_work, rkt_work.drill_snm_reg_id);
		AkMathNormalizeMtx(nNS_MATRIX, src_mtx);
		nnMakeRotateMatrixQuaternion(out rkt_work.stuck_lerp_src_quat, nNS_MATRIX);
		gmBoss5RocketUpdateRocketStuckWithArm(rkt_work, 0);
		oBS_OBJECT_WORK.dir.x = (oBS_OBJECT_WORK.dir.y = (oBS_OBJECT_WORK.dir.z = 0));
		rkt_work.stuck_lerp_ratio = 0f;
		rkt_work.stuck_lerp_ratio_spd = ratio_spd;
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
	}

	public static int gmBoss5RocketUpdateRocketStuckWithArmLerpRot(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		int num = 0;
		rkt_work.stuck_lerp_ratio += rkt_work.stuck_lerp_ratio_spd;
		if (rkt_work.stuck_lerp_ratio >= 1f)
		{
			rkt_work.stuck_lerp_ratio = 1f;
			num = 1;
		}
		NNS_MATRIX src_mtx = GmBsCmnGetSNMMtx(gMS_BOSS5_BODY_WORK.snm_work, rkt_work.arm_snm_id);
		AkMathNormalizeMtx(nNS_MATRIX, src_mtx);
		NNS_QUATERNION dst;
		nnMakeRotateMatrixQuaternion(out dst, nNS_MATRIX);
		if (rkt_work.rkt_type == 1)
		{
			NNS_QUATERNION dst2;
			nnMakeRotateXYZQuaternion(out dst2, 0, AKM_DEGtoA32(180), 0);
			nnMultiplyQuaternion(ref dst, ref dst, ref dst2);
		}
		NNS_QUATERNION dst3;
		nnSlerpQuaternion(out dst3, ref rkt_work.stuck_lerp_src_quat, ref dst, rkt_work.stuck_lerp_ratio);
		gmBoss5RocketUpdateRocketStuckWithArm(rkt_work, 0);
		oBS_OBJECT_WORK.disp_flag |= 16777216u;
		nnQuaternionMatrix(oBS_OBJECT_WORK.obj_3d.user_obj_mtx_r, oBS_OBJECT_WORK.obj_3d.user_obj_mtx_r, ref dst3);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
		if (num != 0)
		{
			return 1;
		}
		return 0;
	}

	public static void gmBoss5RocketGetArmNodePosFx(GMS_BOSS5_ROCKET_WORK rkt_work, out VecFx32 pos_out)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		NNS_MATRIX nNS_MATRIX = GmBsCmnGetSNMMtx(gMS_BOSS5_BODY_WORK.snm_work, rkt_work.arm_snm_id);
		pos_out.x = FX_F32_TO_FX32(nNS_MATRIX.M03);
		pos_out.y = -FX_F32_TO_FX32(nNS_MATRIX.M13);
		pos_out.z = FX_F32_TO_FX32(nNS_MATRIX.M23);
	}

	public static void gmBoss5RocketSetDispOfst(GMS_BOSS5_ROCKET_WORK rkt_work, float disp_ofst, int b_pos_slide)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		oBS_OBJECT_WORK.disp_flag |= 16777216u;
		nnTranslateMatrix(oBS_OBJECT_WORK.obj_3d.user_obj_mtx_r, oBS_OBJECT_WORK.obj_3d.user_obj_mtx_r, disp_ofst, 0f, 0f);
		if (b_pos_slide != 0)
		{
			oBS_OBJECT_WORK.pos.x -= FX_Mul(FX_F32_TO_FX32(nnCos(oBS_OBJECT_WORK.dir.z) * disp_ofst), g_obj.draw_scale.x);
			oBS_OBJECT_WORK.pos.y -= FX_Mul(FX_F32_TO_FX32(nnSin(oBS_OBJECT_WORK.dir.z) * disp_ofst), g_obj.draw_scale.y);
		}
	}

	public static void gmBoss5RocketGetDispOfst(GMS_BOSS5_ROCKET_WORK rkt_work, ref VecFx32 ofst_pos_out)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		amVectorSet(nNS_VECTOR, 0f, 0f, 0f);
		nnMakeRotateXYZMatrix(nNS_MATRIX, (int)(0xFFFFL & (long)(-oBS_OBJECT_WORK.dir.x)), 0xFFFF & oBS_OBJECT_WORK.dir.y, (int)(0xFFFFL & (long)(-oBS_OBJECT_WORK.dir.z)));
		nnScaleMatrix(nNS_MATRIX, nNS_MATRIX, FX_FX32_TO_F32(g_obj.draw_scale.x), FX_FX32_TO_F32(g_obj.draw_scale.y), FX_FX32_TO_F32(g_obj.draw_scale.z));
		nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX, oBS_OBJECT_WORK.obj_3d.user_obj_mtx_r);
		nnTransformVector(nNS_VECTOR, nNS_MATRIX, nNS_VECTOR);
		VEC_Set(ref ofst_pos_out, FX_F32_TO_FX32(nNS_VECTOR.x), FX_F32_TO_FX32(0f - nNS_VECTOR.y), FX_F32_TO_FX32(nNS_VECTOR.z));
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
	}

	public static int gmBoss5RocketInitFlyDestPos(GMS_BOSS5_ROCKET_WORK rkt_work, int init_acc, int init_spd, int max_spd, VecFx32 launch_pos, ref VecFx32 dest_pos)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		rkt_work.acc = init_acc;
		rkt_work.max_spd = max_spd;
		int result = (rkt_work.move_dir = nnArcTan2(FX_FX32_TO_F32(dest_pos.y - launch_pos.y), FX_FX32_TO_F32(dest_pos.x - launch_pos.x)));
		int v = FX_F32_TO_FX32(nnCos(rkt_work.move_dir));
		int v2 = FX_F32_TO_FX32(nnSin(rkt_work.move_dir));
		oBS_OBJECT_WORK.spd_add.x = FX_Mul(rkt_work.acc, v);
		oBS_OBJECT_WORK.spd_add.y = FX_Mul(rkt_work.acc, v2);
		oBS_OBJECT_WORK.spd_add.z = 0;
		oBS_OBJECT_WORK.spd.x = FX_Mul(init_spd, v);
		oBS_OBJECT_WORK.spd.y = FX_Mul(init_spd, v2);
		rkt_work.launch_pos = launch_pos;
		rkt_work.dest_pos = dest_pos;
		return result;
	}

	public static void gmBoss5RocketInitFlyDestDistance(GMS_BOSS5_ROCKET_WORK rkt_work, int init_acc, int init_spd, int max_spd, ref VecFx32 launch_pos, int angle, int distance)
	{
		VecFx32 dest_pos = default(VecFx32);
		dest_pos.x = launch_pos.x + FX_Mul(distance, FX_F32_TO_FX32(nnCos(angle)));
		dest_pos.y = launch_pos.y + FX_Mul(distance, FX_F32_TO_FX32(nnSin(angle)));
		dest_pos.z = 0;
		gmBoss5RocketInitFlyDestPos(rkt_work, init_acc, init_spd, max_spd, launch_pos, ref dest_pos);
	}

	public static void gmBoss5RocketRedirectFlyDestPos(GMS_BOSS5_ROCKET_WORK rkt_work, int init_acc, ref VecFx32 dest_pos)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		VecFx32 spd = oBS_OBJECT_WORK.spd;
		gmBoss5RocketInitFlyDestPos(rkt_work, init_acc, 4096, rkt_work.max_spd, oBS_OBJECT_WORK.pos, ref dest_pos);
		oBS_OBJECT_WORK.spd.Assign(spd);
	}

	public static int gmBoss5RocketUpdateFlyDest(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		return gmBoss5RocketUpdateFlyDest(rkt_work, 0);
	}

	public static int gmBoss5RocketUpdateFlyDest(GMS_BOSS5_ROCKET_WORK rkt_work, int b_mdl_center)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR2 = GlobalPool<NNS_VECTOR>.Alloc();
		VecFx32 ofst_pos_out = default(VecFx32);
		int num = FX_Sqrt(FX_Mul(oBS_OBJECT_WORK.spd.x, oBS_OBJECT_WORK.spd.x) + FX_Mul(oBS_OBJECT_WORK.spd.y, oBS_OBJECT_WORK.spd.y));
		if (num >= rkt_work.max_spd)
		{
			oBS_OBJECT_WORK.spd_add.x = (oBS_OBJECT_WORK.spd_add.y = (oBS_OBJECT_WORK.spd_add.z = 0));
		}
		amVectorSet(nNS_VECTOR, FX_FX32_TO_F32(oBS_OBJECT_WORK.spd.x), FX_FX32_TO_F32(oBS_OBJECT_WORK.spd.y), 0f);
		if (b_mdl_center != 0)
		{
			gmBoss5RocketGetDispOfst(rkt_work, ref ofst_pos_out);
		}
		amVectorSet(nNS_VECTOR2, FX_FX32_TO_F32(rkt_work.dest_pos.x - (oBS_OBJECT_WORK.pos.x + ofst_pos_out.x)), FX_FX32_TO_F32(rkt_work.dest_pos.y - (oBS_OBJECT_WORK.pos.y + ofst_pos_out.y)), 0f);
		int result = ((nnDotProductVector(nNS_VECTOR, nNS_VECTOR2) <= 0f) ? 1 : 0);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR2);
		return result;
	}

	public static void gmBoss5RocketInitFlyReverse(GMS_BOSS5_ROCKET_WORK rkt_work, int acc_scalar)
	{
		gmBoss5RocketInitFlyReverse(rkt_work, acc_scalar, 0);
	}

	public static void gmBoss5RocketInitFlyReverse(GMS_BOSS5_ROCKET_WORK rkt_work, int acc_scalar, int is_add)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		amVectorSet(nNS_VECTOR, 0f - FX_FX32_TO_F32(oBS_OBJECT_WORK.spd.x), 0f - FX_FX32_TO_F32(oBS_OBJECT_WORK.spd.y), 0f);
		nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
		VecFx32 acc_vec = new VecFx32(FX_Mul(FX_F32_TO_FX32(nNS_VECTOR.x), acc_scalar), FX_Mul(FX_F32_TO_FX32(nNS_VECTOR.y), acc_scalar), 0);
		gmBoss5RocketInitFlyReverseVec(rkt_work, ref acc_vec, is_add);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	public static void gmBoss5RocketInitFlyReverseVec(GMS_BOSS5_ROCKET_WORK rkt_work, ref VecFx32 acc_vec)
	{
		gmBoss5RocketInitFlyReverseVec(rkt_work, ref acc_vec, 0);
	}

	public static void gmBoss5RocketInitFlyReverseVec(GMS_BOSS5_ROCKET_WORK rkt_work, ref VecFx32 acc_vec, int is_add)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		rkt_work.rvs_acc.x = acc_vec.x;
		rkt_work.rvs_acc.y = acc_vec.y;
		rkt_work.rvs_acc.z = 0;
		if (is_add != 0)
		{
			oBS_OBJECT_WORK.spd_add.x += rkt_work.rvs_acc.x;
			oBS_OBJECT_WORK.spd_add.y += rkt_work.rvs_acc.y;
			oBS_OBJECT_WORK.spd_add.z = 0;
		}
		else
		{
			oBS_OBJECT_WORK.spd_add.Assign(rkt_work.rvs_acc);
		}
	}

	public static int gmBoss5RocketUpdateFlyReverse(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR2 = GlobalPool<NNS_VECTOR>.Alloc();
		amVectorSet(nNS_VECTOR, FX_FX32_TO_F32(rkt_work.rvs_acc.x), FX_FX32_TO_F32(rkt_work.rvs_acc.y), 0f);
		amVectorSet(nNS_VECTOR2, FX_FX32_TO_F32(oBS_OBJECT_WORK.spd.x), FX_FX32_TO_F32(oBS_OBJECT_WORK.spd.y), 0f);
		int result = ((nnDotProductVector(nNS_VECTOR, nNS_VECTOR2) >= 0f) ? 1 : 0);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR2);
		return result;
	}

