	public static int gmBoss5RocketUpdateStuckLean(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		OBS_OBJECT_WORK parent_obj = oBS_OBJECT_WORK.parent_obj;
		float num = 0f;
		int result = 1;
		int num2 = 0;
		rkt_work.hit_vib_amp_deg -= 0.5f;
		if (rkt_work.hit_vib_amp_deg <= 0f)
		{
			rkt_work.hit_vib_amp_deg = 0f;
		}
		rkt_work.hit_vib_sin_angle = (int)(0xFFFFL & (long)(rkt_work.hit_vib_sin_angle + GMD_BOSS5_RKT_GRD_STUCK_LEAN_HIT_VIB_SIN_ANGLE_ADD));
		float num3 = nnSin(rkt_work.hit_vib_sin_angle) * rkt_work.hit_vib_amp_deg;
		if ((rkt_work.flag & 0x80) != 0)
		{
			float stuck_lean_ratio = rkt_work.stuck_lean_ratio;
			if (rkt_work.stuck_lean_ratio < 1f)
			{
				rkt_work.stuck_lean_ratio += 0.075f;
				result = 0;
			}
			rkt_work.stuck_lean_ratio = MTM_MATH_CLIP(rkt_work.stuck_lean_ratio, 0f, 1f);
			num = 180f * rkt_work.stuck_lean_ratio - num3;
			num2 = (int)(131072f * (rkt_work.stuck_lean_ratio - stuck_lean_ratio));
			ObjObjectFieldRectSet(oBS_OBJECT_WORK, -16, -16, 16, (short)(16 + (short)(rkt_work.stuck_lean_ratio * 8f)));
		}
		else
		{
			num = (float)(int)rkt_work.hit_count * -10f + num3;
		}
		if (oBS_OBJECT_WORK.pos.x < parent_obj.pos.x)
		{
			num = 0f - num;
			num2 = -num2;
		}
		oBS_OBJECT_WORK.dir.z = (ushort)(0xFFFFuL & (ulong)(rkt_work.stuck_dir + AKM_DEGtoA32(num)));
