	public static void gmBoss5RocketInitScatter(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		GmBoss5ScatterSetFlyParam(oBS_OBJECT_WORK);
		AkMathNormalizeMtx(nNS_MATRIX, oBS_OBJECT_WORK.obj_3d.user_obj_mtx_r);
		nnMakeRotateMatrixQuaternion(out rkt_work.sct_cur_quat, nNS_MATRIX);
		nnMakeUnitQuaternion(ref rkt_work.sct_spin_quat);
		for (int i = 0; i < 2; i++)
		{
			NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
			float a = FX_FX32_TO_F32(AkMathRandFx()) * 2f - 1f;
			a = MTM_MATH_CLIP(a, -1f, 1f);
			short rand_angle = AKM_DEGtoA16(360f * FX_FX32_TO_F32(AkMathRandFx()));
			AkMathGetRandomUnitVector(nNS_VECTOR, a, rand_angle);
			NNS_QUATERNION dst;
			nnMakeRotateAxisQuaternion(out dst, nNS_VECTOR.x, nNS_VECTOR.y, nNS_VECTOR.z, GMD_BOSS5_SCT_SPIN_SPD_ANGLE);
			nnMultiplyQuaternion(ref rkt_work.sct_spin_quat, ref dst, ref rkt_work.sct_spin_quat);
			GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		}
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
	}

