		OBS_OBJECT_WORK obj_work = GMM_BS_OBJ(rkt_work);
		GmBsCmnClearBossMotionCBSystem(obj_work);
		GmBsCmnDeleteSNMWork(rkt_work.snm_work);
	}

	public static void gmBoss5RocketAtkPlyHitFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		GMS_BOSS5_ROCKET_WORK gMS_BOSS5_ROCKET_WORK = (GMS_BOSS5_ROCKET_WORK)my_rect.parent_obj;
		gMS_BOSS5_ROCKET_WORK.flag |= 1u;
		GmEnemyDefaultAtkFunc(my_rect, your_rect);
	}

	public static void gmBoss5RocketAtkBossHitFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		OBS_OBJECT_WORK parent_obj = my_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = your_rect.parent_obj;
		GMS_BOSS5_ROCKET_WORK rkt_work = (GMS_BOSS5_ROCKET_WORK)parent_obj;
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)parent_obj2;
		if (gMS_ENEMY_COM_WORK.eve_rec.id == 330)
		{
			parent_obj.flag |= 2u;
			gmBoss5RocketBounceProcInit(rkt_work);
		}
		else
		{
			ObjRectFuncNoHit(my_rect, your_rect);
		}
	}

	public static void gmBoss5RocketDamageDefFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		GMS_BOSS5_ROCKET_WORK gMS_BOSS5_ROCKET_WORK = (GMS_BOSS5_ROCKET_WORK)my_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj = your_rect.parent_obj;
		if (parent_obj == null || 1 != parent_obj.obj_type)
		{
			return;
		}
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)parent_obj;
		if ((gMS_PLAYER_WORK.obj_work.move_flag & 1) != 0)
		{
			return;
		}
		int num = gmBoss5RocketSetPlyRebound(my_rect, your_rect);
		if ((gMS_BOSS5_ROCKET_WORK.flag & 2) != 0)
		{
			if (num != 0)
			{
				gMS_BOSS5_ROCKET_WORK.hit_count++;
				if (gMS_BOSS5_ROCKET_WORK.hit_count >= 3)
				{
					gmBoss5RocketClearLeakageFlicker(gMS_BOSS5_ROCKET_WORK);
					gmBoss5RocketBlowProcInit(gMS_BOSS5_ROCKET_WORK);
				}
				else
				{
					gmBoss5RocketSetNoHitTime(gMS_BOSS5_ROCKET_WORK);
					gmBoss5RocketSetStuckLeanHitVib(gMS_BOSS5_ROCKET_WORK);
				}
			}
			else
			{
				gmBoss5RocketSetDmgEnable(gMS_BOSS5_ROCKET_WORK, 0);
				GmBoss5EfctCreateRocketRollSpark(gMS_BOSS5_ROCKET_WORK);
				gMS_BOSS5_ROCKET_WORK.flag |= 128u;
			}
		}
		else
		{
			gmBoss5RocketClearLeakageFlicker(gMS_BOSS5_ROCKET_WORK);
			gmBoss5RocketBlowProcInit(gMS_BOSS5_ROCKET_WORK);
		}
		GmSoundPlaySE("Boss0_01");
	}

	public static void gmBoss5RocketOutFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS5_ROCKET_WORK gMS_BOSS5_ROCKET_WORK = (GMS_BOSS5_ROCKET_WORK)obj_work;
		ObjDrawActionSummary(obj_work);
		gMS_BOSS5_ROCKET_WORK.pivot_prev_pos.Assign(obj_work.pos);
	}

	public static void gmBoss5RocketMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS5_ROCKET_WORK gMS_BOSS5_ROCKET_WORK = (GMS_BOSS5_ROCKET_WORK)obj_work;
		if ((gMS_BOSS5_ROCKET_WORK.flag & 2) != 0 && (gMS_BOSS5_ROCKET_WORK.flag & 0x80) == 0)
		{
			gmBoss5RocketUpdateNoHitTime(gMS_BOSS5_ROCKET_WORK);
		}
		if (gMS_BOSS5_ROCKET_WORK.proc_update != null)
		{
			gMS_BOSS5_ROCKET_WORK.proc_update(gMS_BOSS5_ROCKET_WORK);
		}
		if ((gMS_BOSS5_ROCKET_WORK.flag & 8) != 0)
		{
			GmBoss5EfctTryStartRocketLeakage(gMS_BOSS5_ROCKET_WORK);
		}
		else
		{
			GmBoss5EfctEndRocketLeakage(gMS_BOSS5_ROCKET_WORK);
		}
		gmBoss5RocketUpdateMainRectPosition(gMS_BOSS5_ROCKET_WORK);
	}

	public static void gmBoss5RocketNmlProcInit(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		gmBoss5RocketSetInitialDir(rkt_work);
		gmBoss5RocketSetRectSize(rkt_work, 1);
		gmBoss5RocketSetAtkEnable(rkt_work, 0);
		gmBoss5RocketSetDmgEnable(rkt_work, 0);
		gmBoss5RocketInitPlySearch(rkt_work, 20);
		rkt_work.proc_update = gmBoss5RocketNmlProcUpdateFace;
	}

	public static void gmBoss5RocketNmlProcUpdateFace(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		gmBoss5RocketUpdateRocketStuckWithArm(rkt_work, 0);
		gmBoss5RocketUpdatePlySearch(rkt_work);
		VecFx32 pos;
		gmBoss5RocketGetPlySearchPos(rkt_work, out pos);
		gmBoss5RocketUpdateDirPlyLockOn(rkt_work, ref pos);
		if (gmBoss5RocketReceiveSignalLaunch(rkt_work) != 0)
		{
			gmBoss5RocketInitFlyDestDistance(rkt_work, 4096, 40960, 49152, ref oBS_OBJECT_WORK.pos, oBS_OBJECT_WORK.dir.z, 786432);
			gmBoss5RocketSetAtkEnable(rkt_work, 1);
			GmBoss5EfctCreateRocketLaunch(rkt_work);
			GmSoundPlaySE("FinalBoss07");
			GmBoss5EfctStartRocketJet(rkt_work);
			rkt_work.proc_update = gmBoss5RocketNmlProcUpdateFly;
		}
	}

	public static void gmBoss5RocketNmlProcUpdateFly(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		if (gmBoss5RocketUpdateFlyDest(rkt_work) != 0)
		{
			gmBoss5RocketInitFlyReverse(rkt_work, 4096, 0);
			GmBoss5EfctEndRocketJet(rkt_work);
			GmBoss5EfctStartRocketJetReverse(rkt_work);
			rkt_work.proc_update = gmBoss5RocketNmlProcUpdateWaitDecel;
		}
	}

	public static void gmBoss5RocketNmlProcUpdateWaitDecel(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		if (gmBoss5RocketUpdateFlyReverse(rkt_work) != 0)
		{
			GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
			VecFx32 pos_out;
			gmBoss5RocketGetArmNodePosFx(rkt_work, out pos_out);
			int num = gmBoss5RocketInitFlyDestPos(rkt_work, 2048, 0, 40960, oBS_OBJECT_WORK.pos, ref pos_out);
			oBS_OBJECT_WORK.dir.z = (ushort)(short)(0xFFFFuL & (ulong)(num + AKM_DEGtoA32(180)));
			rkt_work.proc_update = gmBoss5RocketNmlProcUpdateWaitReturn;
		}
	}

	public static void gmBoss5RocketNmlProcUpdateWaitReturn(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		if (gmBoss5RocketUpdateFlyDest(rkt_work, 1) != 0)
		{
			gmBoss5RocketDispatchSignalReturned(rkt_work);
			GmBoss5EfctEndRocketJet(rkt_work);
			GMS_BOSS5_BODY_WORK body_work = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
			GmBoss5EfctCreateRocketDock(body_work, rkt_work.rkt_type);
			gmBoss5RocketSetAtkEnable(rkt_work, 0);
			rkt_work.proc_update = gmBoss5RocketNmlProcUpdateFinalize;
		}
	}

	public static void gmBoss5RocketNmlProcUpdateFinalize(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.flag |= 4u;
	}

	public static void gmBoss5RocketStrProcInit(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		gmBoss5RocketSetInitialDir(rkt_work);
		gmBoss5RocketSetRectSize(rkt_work, 1);
		gmBoss5RocketSetAtkEnable(rkt_work, 0);
		gmBoss5RocketSetDmgEnable(rkt_work, 0);
		gmBoss5RocketInitPlySearch(rkt_work, 20);
		rkt_work.proc_update = gmBoss5RocketStrProcUpdateFace;
	}

	public static void gmBoss5RocketStrProcUpdateFace(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		gmBoss5RocketUpdateRocketStuckWithArm(rkt_work, 0);
		gmBoss5RocketUpdatePlySearch(rkt_work);
		VecFx32 pos;
		gmBoss5RocketGetPlySearchPos(rkt_work, out pos);
		gmBoss5RocketUpdateDirPlyLockOn(rkt_work, ref pos);
		if (gmBoss5RocketReceiveSignalReturn(rkt_work) != 0)
		{
			gmBoss5RocketInitRocketStuckWithArmLerpRot(rkt_work, 0.1f);
			gmBoss5RocketUpdateRocketStuckWithArmLerpRot(rkt_work);
			rkt_work.proc_update = gmBoss5RocketStrProcUpdateRecover;
		}
		else if (gmBoss5RocketReceiveSignalLaunch(rkt_work) != 0)
		{
			gmBoss5RocketSetDispOfst(rkt_work, -10f, 1);
			gmBoss5RocketInitFlyDestDistance(rkt_work, 6144, 40960, 61440, ref oBS_OBJECT_WORK.pos, oBS_OBJECT_WORK.dir.z, 786432);
			gmBoss5RocketSetAtkEnable(rkt_work, 1);
			GmBoss5EfctCreateRocketLaunch(rkt_work);
			GmSoundPlaySE("FinalBoss07");
			GmBoss5EfctStartRocketJet(rkt_work);
			rkt_work.proc_update = gmBoss5RocketStrProcUpdateFlyTarget;
		}
	}

	public static void gmBoss5RocketStrProcUpdateFlyTarget(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		if (gmBoss5RocketUpdateFlyDest(rkt_work) != 0)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
			VecFx32 dest_pos = new VecFx32(oBS_OBJECT_WORK.pos.x, GMM_BOSS5_AREA_TOP() - 196608, 0);
			VecFx32 acc_vec = new VecFx32(-2048, 0, 0);
			gmBoss5RocketRedirectFlyDestPos(rkt_work, 2048, ref dest_pos);
			if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
			{
				acc_vec.x = -acc_vec.x;
			}
			gmBoss5RocketInitFlyReverseVec(rkt_work, ref acc_vec, 1);
			rkt_work.proc_update = gmBoss5RocketStrProcUpdateFlyDecel;
		}
	}

	public static void gmBoss5RocketStrProcUpdateFlyDecel(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		gmBoss5RocketUpdateDirFollowingAccSpd(rkt_work, 5f, 0);
		if (gmBoss5RocketUpdateFlyReverse(rkt_work) != 0)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
			VecFx32 dest_pos = new VecFx32(oBS_OBJECT_WORK.pos.x, GMM_BOSS5_AREA_TOP() - 196608, 0);
			gmBoss5RocketInitFlyDestPos(rkt_work, 2048, MTM_MATH_ABS(oBS_OBJECT_WORK.spd.y), 61440, oBS_OBJECT_WORK.pos, ref dest_pos);
			rkt_work.proc_update = gmBoss5RocketStrProcUpdateFlyAbove;
		}
	}

	public static void gmBoss5RocketStrProcUpdateFlyAbove(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK obj_work = GMM_BS_OBJ(rkt_work);
		gmBoss5RocketUpdateDirFollowingAccSpd(rkt_work, 1f, 0);
		if (gmBoss5RocketUpdateFlyDest(rkt_work) != 0)
		{
			GmBsCmnSetObjSpdZero(obj_work);
			gmBoss5RocketSetAtkEnable(rkt_work, 0);
			rkt_work.wait_timer = gmBoss5RocketSeqGetWaitFallTime(rkt_work);
			GmBoss5EfctEndRocketJet(rkt_work);
			rkt_work.proc_update = gmBoss5RocketStrProcUpdateWaitFall;
		}
	}

	public static void gmBoss5RocketStrProcUpdateWaitFall(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		if (rkt_work.wait_timer >= 10)
		{
			oBS_OBJECT_WORK.pos.x = GmBsCmnGetPlayerObj().pos.x;
		}
		if (rkt_work.wait_timer != 0)
		{
			rkt_work.wait_timer--;
			return;
		}
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.spd.y = 8192;
		gmBoss5RocketSetRectSize(rkt_work, 1);
		gmBoss5RocketSetAtkEnable(rkt_work, 1);
		gmBoss5RocketSetDmgEnable(rkt_work, 1);
		gmBoss5RocketInitLeakageFlicker(rkt_work);
		GmBoss5EfctStartRocketSmoke(rkt_work);
		gmBoss5RocketInitDirFalling(rkt_work);
		gMS_ENEMY_COM_WORK.enemy_flag &= 4294934527u;
		rkt_work.flag &= 4294967294u;
		rkt_work.proc_update = gmBoss5RocketStrProcUpdateFall;
	}

	public static void gmBoss5RocketStrProcUpdateFall(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		gmBoss5RocketUpdateDirFalling(rkt_work);
		if (gmBoss5RocketUpdateLeakageFlicker(rkt_work) != 0)
		{
			gmBoss5RocketSetRectSize(rkt_work, 1);
		}
		else
		{
			gmBoss5RocketSetRectSize(rkt_work, 0);
		}
		if (oBS_OBJECT_WORK.pos.y >= GMM_BOSS5_AREA_TOP())
		{
			oBS_OBJECT_WORK.move_flag &= 4294967039u;
		}
		if ((oBS_OBJECT_WORK.move_flag & 1) != 0)
		{
			GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
			rkt_work.flag |= 2u;
			gmBoss5RocketSetRectSize(rkt_work, 0);
			gmBoss5RocketSetAtkEnable(rkt_work, 1);
			gmBoss5RocketSetDmgEnable(rkt_work, 1);
			if ((rkt_work.flag & 1) != 0)
			{
				rkt_work.wait_timer = 30u;
			}
			else
			{
				rkt_work.wait_timer = 300u;
			}
			gmBoss5RocketClearLeakageFlicker(rkt_work);
			GmBoss5EfctCreateRocketLandingShockwave(rkt_work);
			GmSoundPlaySE("FinalBoss13");
			gmBoss5RocketEndDirFalling(rkt_work);
			gmBoss5RocketInitStuckLean(rkt_work);
			rkt_work.proc_update = gmBoss5RocketStrProcUpdateStuck;
		}
	}

	public static void gmBoss5RocketStrProcUpdateStuck(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		int num = 0;
		num = gmBoss5RocketUpdateStuckLean(rkt_work);
		if (num != 0 && (rkt_work.flag & 0x80) != 0 && (rkt_work.flag & 0x100) == 0)
		{
			gmBoss5RocketSetStuckLeanHitVib(rkt_work);
			rkt_work.flag |= 256u;
		}
		if ((rkt_work.flag & 0x80) != 0)
		{
			rkt_work.flag |= 8u;
		}
		else
		{
			rkt_work.flag &= 4294967287u;
		}
		if (rkt_work.wait_timer != 0)
		{
			rkt_work.wait_timer--;
		}
		else if (num != 0)
		{
			GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)oBS_OBJECT_WORK;
			rkt_work.flag &= 4294967287u;
			GmBoss5EfctEndRocketSmoke(rkt_work);
			VecFx32 pos_out;
			gmBoss5RocketGetArmNodePosFx(rkt_work, out pos_out);
			gmBoss5RocketInitFlyDestPos(rkt_work, 1228, 0, 61440, oBS_OBJECT_WORK.pos, ref pos_out);
			rkt_work.flag &= 4294967293u;
			gmBoss5RocketSetRectSize(rkt_work, 1);
			gmBoss5RocketSetAtkEnable(rkt_work, 1);
			gmBoss5RocketSetDmgEnable(rkt_work, 0);
			gMS_ENEMY_COM_WORK.enemy_flag |= 32768u;
			rkt_work.proc_update = gmBoss5RocketStrProcUpdateReturn;
		}
	}

	public static void gmBoss5RocketStrProcUpdateReturn(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		if ((rkt_work.flag & 0x80) != 0)
		{
			gmBoss5RocketUpdateDirFollowingAccSpd(rkt_work, 5f, 1);
		}
		else
		{
			gmBoss5RocketUpdateDirFollowingAccSpd(rkt_work, 2f, 1);
		}
		if (gmBoss5RocketUpdateFlyDest(rkt_work, 1) != 0)
		{
			GMS_BOSS5_BODY_WORK body_work = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
			GmBoss5EfctCreateRocketDock(body_work, rkt_work.rkt_type);
			gmBoss5RocketDispatchSignalReturned(rkt_work);
			rkt_work.proc_update = gmBoss5RocketStrProcUpdateFinalize;
		}
	}

	public static void gmBoss5RocketStrProcUpdateFinalize(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.flag |= 4u;
	}

	public static void gmBoss5RocketStrProcUpdateRecover(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		gmBoss5RocketUpdateRocketStuckWithArmLerpRot(rkt_work);
		if ((rkt_work.rkt_type == 0 && (gMS_BOSS5_BODY_WORK.flag & 4) == 0) || (rkt_work.rkt_type == 1 && (gMS_BOSS5_BODY_WORK.flag & 4) == 0))
		{
			oBS_OBJECT_WORK.flag |= 4u;
		}
	}

	public static void gmBoss5RocketBlowProcInit(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)oBS_OBJECT_WORK;
		GmPlayerAddScore((GMS_PLAYER_WORK)GmBsCmnGetPlayerObj(), 100, oBS_OBJECT_WORK.pos.x, oBS_OBJECT_WORK.pos.y);
		GmBoss5EfctEndRocketSmoke(rkt_work);
		rkt_work.flag &= 4294967293u;
		oBS_OBJECT_WORK.move_flag |= 16u;
		oBS_OBJECT_WORK.move_flag &= 4294967294u;
		gMS_ENEMY_COM_WORK.enemy_flag |= 32768u;
		gmBoss5RocketSetAtkBodyRect(rkt_work);
		gmBoss5RocketSetRectSize(rkt_work, 1);
		gmBoss5RocketSetAtkEnable(rkt_work, 1);
		gmBoss5RocketSetDmgEnable(rkt_work, 0);
		gmBoss5RocketInitFlyBlow(rkt_work);
		rkt_work.proc_update = gmBoss5RocketBlowProcUpdateFly;
	}

	public static void gmBoss5RocketBlowProcUpdateFly(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		if (gmBoss5RocketUpdateFlyBlow(rkt_work) != 0)
		{
			rkt_work.proc_update = gmBoss5RocketBlowProcUpdateWaitHit;
		}
	}

	public static void gmBoss5RocketBlowProcUpdateWaitHit(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		gmBoss5RocketUpdateFlyBlow(rkt_work);
		oBS_OBJECT_WORK.pos.x = rkt_work.dest_pos.x;
		oBS_OBJECT_WORK.pos.y = rkt_work.dest_pos.y;
		GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
	}

	public static void gmBoss5RocketBounceProcInit(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.move_flag |= 16u;
		oBS_OBJECT_WORK.move_flag &= 4294967294u;
		gMS_ENEMY_COM_WORK.enemy_flag |= 32768u;
		gmBoss5RocketSetAtkEnable(rkt_work, 0);
		gmBoss5RocketSetDmgEnable(rkt_work, 0);
		gmBoss5RocketInitFlyBounce(rkt_work);
		rkt_work.proc_update = gmBoss5RocketBounceProcUpdateFlyUp;
	}

	public static void gmBoss5RocketBounceProcUpdateFlyUp(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK obj_work = GMM_BS_OBJ(rkt_work);
		if (gmBoss5RocketUpdateFlyBounce(rkt_work) != 0)
		{
			GmBsCmnSetObjSpdZero(obj_work);
			rkt_work.proc_update = gmBoss5RocketBounceProcUpdateWait;
		}
	}

	public static void gmBoss5RocketBounceProcUpdateWait(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		if (gmBoss5RocketReceiveSignalReturn(rkt_work) != 0)
		{
			VecFx32 pos_out;
			gmBoss5RocketGetArmNodePosFx(rkt_work, out pos_out);
			gmBoss5RocketInitFlyDestPos(rkt_work, 1228, 0, 61440, oBS_OBJECT_WORK.pos, ref pos_out);
			rkt_work.proc_update = gmBoss5RocketBounceProcUpdateReturn;
		}
	}

	public static void gmBoss5RocketBounceProcUpdateReturn(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		gmBoss5RocketUpdateDirFollowingAccSpd(rkt_work, 5f, 1);
		if (gmBoss5RocketUpdateFlyDest(rkt_work, 1) != 0)
		{
			GMS_BOSS5_BODY_WORK body_work = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
			GmBoss5EfctCreateRocketDock(body_work, rkt_work.rkt_type);
			gmBoss5RocketDispatchSignalReturned(rkt_work);
			rkt_work.proc_update = gmBoss5RocketBounceProcUpdateFinalize;
		}
	}

	public static void gmBoss5RocketBounceProcUpdateFinalize(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.flag |= 4u;
	}

	public static void gmBoss5RocketCnctProcInit(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		gmBoss5RocketUpdateRocketStuckWithArm(rkt_work, 1);
		gmBoss5RocketSetRectSize(rkt_work, 1);
		gmBoss5RocketSetAtkEnable(rkt_work, 0);
		gmBoss5RocketSetDmgEnable(rkt_work, 0);
		rkt_work.proc_update = gmBoss5RocketCnctProcUpdateIdle;
	}

	public static void gmBoss5RocketCnctProcUpdateIdle(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		gmBoss5RocketUpdateRocketStuckWithArm(rkt_work, 1);
		if ((rkt_work.rkt_type == 0 && (gMS_BOSS5_BODY_WORK.flag & 4) != 0) || (rkt_work.rkt_type == 1 && (gMS_BOSS5_BODY_WORK.flag & 8) != 0))
		{
			oBS_OBJECT_WORK.disp_flag |= 32u;
			gmBoss5RocketSetAtkEnable(rkt_work, 0);
			return;
		}
		oBS_OBJECT_WORK.disp_flag &= 4294967263u;
		if ((gMS_BOSS5_BODY_WORK.flag & 0x100) != 0)
		{
			gmBoss5RocketSetAtkEnable(rkt_work, 1);
		}
		else
		{
			gmBoss5RocketSetAtkEnable(rkt_work, 0);
		}
		if ((gMS_BOSS5_BODY_WORK.flag & 0x40000) != 0)
		{
			if (rkt_work.rkt_type == 0)
			{
				rkt_work.wait_timer = 10u;
			}
			else
			{
				rkt_work.wait_timer = 30u;
			}
			rkt_work.proc_update = gmBoss5RocketCnctProcUpdateWaitScatterStart;
		}
	}

	public static void gmBoss5RocketCnctProcUpdateWaitScatterStart(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		gmBoss5RocketUpdateRocketStuckWithArm(rkt_work, 1);
		if (rkt_work.wait_timer != 0)
		{
			rkt_work.wait_timer--;
			return;
		}
		gmBoss5RocketInitScatter(rkt_work);
		rkt_work.wait_timer = 180u;
		rkt_work.proc_update = gmBoss5RocketCnctProcUpdateScatter;
	}

	public static void gmBoss5RocketCnctProcUpdateScatter(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(rkt_work);
		gmBoss5RocketUpdateScatter(rkt_work);
		if (rkt_work.wait_timer != 0)
		{
			rkt_work.wait_timer--;
		}
		else
		{
			oBS_OBJECT_WORK.flag |= 4u;
		}
	}

	public static uint gmBoss5RocketSeqGetWaitFallTime(GMS_BOSS5_ROCKET_WORK rkt_work)
	{
		GMS_BOSS5_BODY_WORK gMS_BOSS5_BODY_WORK = (GMS_BOSS5_BODY_WORK)GMM_BS_OBJ(rkt_work).parent_obj;
		int life = gMS_BOSS5_BODY_WORK.mgr_work.life;
		GMS_BOSS5_RKT_SEQ_WAITFALL_INFO gMS_BOSS5_RKT_SEQ_WAITFALL_INFO = null;
		int num = 0;
		int num2 = 0;
		for (int i = 0; i < 3; i++)
		{
			if (life <= gm_boss5_rkt_seq_wait_fall_time_tbl[i].life_threshold)
			{
				gMS_BOSS5_RKT_SEQ_WAITFALL_INFO = gm_boss5_rkt_seq_wait_fall_time_tbl[i];
				break;
			}
		}
		if (gMS_BOSS5_RKT_SEQ_WAITFALL_INFO == null)
		{
			return 0u;
		}
		int num3 = AkMathRandFx();
		for (int j = 0; j < 3; j++)
		{
			int num4 = gMS_BOSS5_RKT_SEQ_WAITFALL_INFO.probability[j];
			if (num4 > 0)
			{
				num = j;
				num2 += num4;
				if (num3 <= num2)
				{
					return gMS_BOSS5_RKT_SEQ_WAITFALL_INFO.frame[j];
				}
			}
		}
		return gMS_BOSS5_RKT_SEQ_WAITFALL_INFO.frame[num];
	}

