		gm_boss3_obj_3d_list = GmGameDBuildRegBuildModel(mdl_amb, tex_amb, 0u);
		ObjDataLoadAmbIndex(ObjDataGet(728), 2, amb);
		ObjDataLoadAmbIndex(ObjDataGet(729), 3, amb);
