	private static void gmBoss3MgrMainFuncWaitLoad(OBS_OBJECT_WORK obj_work)
	{
		if (GmBsCmnIsFinalZoneType(obj_work) == 0 || GmMainDatLoadBossBattleLoadCheck(2))
		{
			GMS_BOSS3_MGR_WORK gMS_BOSS3_MGR_WORK = (GMS_BOSS3_MGR_WORK)obj_work;
			GMS_BOSS3_BODY_WORK gMS_BOSS3_BODY_WORK = (GMS_BOSS3_BODY_WORK)GmEventMgrLocalEventBirth(319, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
			OBS_OBJECT_WORK obj_work2 = gMS_BOSS3_BODY_WORK.ene_3d.ene_com.obj_work;
			obj_work2.parent_obj = obj_work;
			gMS_BOSS3_BODY_WORK.parts_objs[0] = obj_work2;
			gMS_BOSS3_MGR_WORK.body_work = gMS_BOSS3_BODY_WORK;
			gmBoss3MgrAddObject(gMS_BOSS3_MGR_WORK, obj_work2);
			mtTaskChangeTcbDestructor(obj_work2.tcb, gmBoss3BodyExit);
			GMS_BOSS3_EGG_WORK gMS_BOSS3_EGG_WORK = (GMS_BOSS3_EGG_WORK)GmEventMgrLocalEventBirth(320, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
			OBS_OBJECT_WORK obj_work3 = gMS_BOSS3_EGG_WORK.ene_3d.ene_com.obj_work;
			obj_work3.parent_obj = obj_work2;
			gmBoss3MgrAddObject(gMS_BOSS3_MGR_WORK, obj_work3);
			mtTaskChangeTcbDestructor(obj_work3.tcb, gmBoss3ExitFunc);
			gMS_BOSS3_BODY_WORK.parts_objs[1] = obj_work3;
			obj_work.ppFunc = gmBoss3MgrMainFuncWaitSetup;
		}
	}

	private static void gmBoss3MgrMainFuncWaitSetup(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS3_MGR_WORK gMS_BOSS3_MGR_WORK = (GMS_BOSS3_MGR_WORK)obj_work;
		GMS_BOSS3_BODY_WORK body_work = gMS_BOSS3_MGR_WORK.body_work;
		for (int i = 0; 2 > i; i++)
		{
			if (body_work.parts_objs[i] == null)
			{
				return;
			}
		}
		gMS_BOSS3_MGR_WORK.flag |= 1u;
		obj_work.ppFunc = gmBoss3MgrMainFunc;
	}

	private static void gmBoss3MgrMainFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS3_MGR_WORK gMS_BOSS3_MGR_WORK = (GMS_BOSS3_MGR_WORK)obj_work;
		if ((gMS_BOSS3_MGR_WORK.flag & 2) != 0)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(gMS_BOSS3_MGR_WORK.body_work);
			oBS_OBJECT_WORK.flag |= 8u;
			gMS_BOSS3_MGR_WORK.body_work = null;
			obj_work.ppFunc = gmBoss3MgrMainFuncWaitRelease;
		}
	}

	private static void gmBoss3MgrMainFuncWaitRelease(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS3_MGR_WORK gMS_BOSS3_MGR_WORK = (GMS_BOSS3_MGR_WORK)obj_work;
		if (GmBsCmnIsFinalZoneType(obj_work) != 0)
		{
			if (gMS_BOSS3_MGR_WORK.obj_create_count > 0)
			{
				return;
			}
			GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)obj_work;
			gMS_ENEMY_COM_WORK.enemy_flag |= 65536u;
			obj_work.flag |= 4u;
			GmGameDatReleaseBossBattleStart(2);
			GmGmkCamScrLimitRelease(14);
			OBS_OBJECT_WORK oBS_OBJECT_WORK = gmBoss3BodyBattleSearchPillar();
			if (oBS_OBJECT_WORK != null)
			{
				GmGmkBoss3PillarWallChangeModeReturn(oBS_OBJECT_WORK);
			}
		}
		obj_work.ppFunc = null;
	}

	private static void gmBoss3BodyExit(MTS_TASK_TCB tcb)
	{
		GMS_BOSS3_BODY_WORK gMS_BOSS3_BODY_WORK = (GMS_BOSS3_BODY_WORK)mtTaskGetTcbWork(tcb);
		OBS_OBJECT_WORK obj_work = gMS_BOSS3_BODY_WORK.ene_3d.ene_com.obj_work;
		GmBsCmnClearBossMotionCBSystem(obj_work);
		GmBsCmnDeleteSNMWork(gMS_BOSS3_BODY_WORK.snm_work);
		GmBsCmnClearCNMCb(obj_work);
		gmBoss3ExitFunc(tcb);
	}

	private static void gmBoss3BodyReactionPlayer(OBS_OBJECT_WORK obj_work_player, OBS_OBJECT_WORK obj_work_body)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)obj_work_player;
		GmPlySeqAtkReactionInit(gMS_PLAYER_WORK);
		GmPlySeqSetJumpState(gMS_PLAYER_WORK, 0, 5u);
		int num = 2048;
		int num2 = 1228;
		if (gMS_PLAYER_WORK.seq_state == 20)
		{
			num = 12288;
			num2 = 12288;
		}
		obj_work_player.spd_m = 0;
		if (obj_work_player.move.x >= 0)
		{
			obj_work_player.spd.x = -num;
		}
		else
		{
			obj_work_player.spd.x = num;
		}
		if (obj_work_player.pos.y <= obj_work_body.pos.y)
		{
			obj_work_player.spd.y = -num2;
		}
		else
		{
			obj_work_player.spd.y = num2;
		}
		GmPlySeqSetNoJumpMoveTime(gMS_PLAYER_WORK, 102400);
	}

