	{
		ObjRectWorkSet(body_work.ene_3d.ene_com.rect_work[1], -8, -8, 8, 8);
		body_work.ene_3d.ene_com.rect_work[0].flag |= 4u;
	}

	private static void gmBoss3BodySetActionAllParts(GMS_BOSS3_BODY_WORK body_work, int action_id)
	{
		gmBoss3BodySetActionAllParts(body_work, action_id, 0);
	}

	private static void gmBoss3BodySetActionAllParts(GMS_BOSS3_BODY_WORK body_work, int action_id, int force_change)
	{
		if (force_change == 0 && body_work.action_id == action_id)
		{
			return;
		}
		body_work.action_id = action_id;
		for (int i = 0; 2 > i; i++)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = body_work.parts_objs[i];
			if (oBS_OBJECT_WORK == null)
			{
				continue;
			}
			GMS_BOSS3_PART_ACT_INFO gMS_BOSS3_PART_ACT_INFO = gm_boss3_act_info_tbl[action_id][i];
			if (i == 1)
			{
				GMS_BOSS3_EGG_WORK gMS_BOSS3_EGG_WORK = (GMS_BOSS3_EGG_WORK)oBS_OBJECT_WORK;
				if ((gMS_BOSS3_EGG_WORK.flag & 1) != 0)
				{
					continue;
				}
			}
			if (gMS_BOSS3_PART_ACT_INFO.is_maintain != 0)
			{
				if (gMS_BOSS3_PART_ACT_INFO.is_repeat != 0)
				{
					oBS_OBJECT_WORK.disp_flag |= 4u;
				}
			}
			else
			{
				GmBsCmnSetAction(oBS_OBJECT_WORK, gMS_BOSS3_PART_ACT_INFO.mtn_id, gMS_BOSS3_PART_ACT_INFO.is_repeat, gMS_BOSS3_PART_ACT_INFO.is_blend);
			}
			oBS_OBJECT_WORK.obj_3d.speed[0] = gMS_BOSS3_PART_ACT_INFO.mtn_spd;
			oBS_OBJECT_WORK.obj_3d.blend_spd = gMS_BOSS3_PART_ACT_INFO.blend_spd;
		}
	}

