	}

	private static void gmBoss3BodyChaseMoveFunc(OBS_OBJECT_WORK obj_work)
	{
		int x = obj_work.spd.x;
		int y = obj_work.spd.y;
		GMS_BOSS3_BODY_WORK body_work = (GMS_BOSS3_BODY_WORK)obj_work;
		gmBoss3BodyChaseAdjustMoveSpeed(body_work);
		ObjObjectMove(obj_work);
		obj_work.spd.x = x;
		obj_work.spd.y = y;
	}

	private static void gmBoss3BodyDefFunc(OBS_RECT_WORK own_rect, OBS_RECT_WORK target_rect)
	{
		OBS_OBJECT_WORK parent_obj = target_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = own_rect.parent_obj;
		GMS_BOSS3_BODY_WORK body_work = (GMS_BOSS3_BODY_WORK)parent_obj2;
		if (parent_obj != null && 1 == parent_obj.obj_type)
		{
			gmBoss3BodyReactionPlayer(parent_obj, parent_obj2);
			gmBoss3BodySetNoHitTime(body_work, 10u);
			gmBoss3BodyDamage(body_work);
		}
	}

	private static void gmBoss3BodySetNoHitTime(GMS_BOSS3_BODY_WORK body_work, uint time)
	{
		GMS_ENEMY_COM_WORK ene_com = body_work.ene_3d.ene_com;
		body_work.counter_no_hit = time;
		ene_com.rect_work[0].flag |= 2048u;
	}

	private static void gmBoss3BodyUpdateNoHitTime(GMS_BOSS3_BODY_WORK body_work)
	{
		if (body_work.counter_no_hit != 0)
		{
			body_work.counter_no_hit--;
			return;
		}
		GMS_ENEMY_COM_WORK ene_com = body_work.ene_3d.ene_com;
		ene_com.rect_work[0].flag &= 4294965247u;
	}

	private static void gmBoss3BodySetInvincibleTime(GMS_BOSS3_BODY_WORK body_work, uint time)
	{
		body_work.counter_invincible = time;
		body_work.flag |= 1u;
	}

	private static void gmBoss3BodyUpdateInvincibleTime(GMS_BOSS3_BODY_WORK body_work)
	{
		if (body_work.counter_invincible != 0)
		{
			body_work.counter_invincible--;
		}
		else
		{
			body_work.flag &= 4294967294u;
		}
	}

	private static void gmBoss3BodySetDirection(GMS_BOSS3_BODY_WORK body_work, short deg)
	{
		body_work.angle_current = deg;
	}

	private static void gmBoss3BodySetDirectionNormal(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			gmBoss3BodySetDirection(body_work, GMD_BOSS3_ANGLE_LEFT);
		}
		else
		{
			gmBoss3BodySetDirection(body_work, GMD_BOSS3_ANGLE_RIGHT);
		}
	}

	private static void gmBoss3BodyUpdateDirection(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		oBS_OBJECT_WORK.dir.y = (ushort)body_work.angle_current;
	}

	private static float gmBoss3BodyCalcMoveXNormalFrame(GMS_BOSS3_BODY_WORK body_work, int x, int speed)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		int num = MTM_MATH_ABS(x - oBS_OBJECT_WORK.pos.x);
		return (float)num / (float)speed;
	}

	private static void gmBoss3BodyInitMoveNormal(GMS_BOSS3_BODY_WORK body_work, VecFx32 dest_pos, float frame)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		body_work.start_pos.x = oBS_OBJECT_WORK.pos.x;
		body_work.start_pos.y = oBS_OBJECT_WORK.pos.y;
		body_work.start_pos.z = oBS_OBJECT_WORK.pos.z;
		body_work.end_pos.x = dest_pos.x;
		body_work.end_pos.y = dest_pos.y;
		body_work.end_pos.z = body_work.start_pos.z;
		body_work.move_counter = 0f;
		if (frame > 0f)
		{
			body_work.move_frame = frame;
		}
		else
		{
			body_work.move_frame = 1f;
		}
	}

	private static float gmBoss3BodyUpdateMoveNormal(GMS_BOSS3_BODY_WORK body_work)
	{
		VecFx32 vecFx = default(VecFx32);
		body_work.move_counter += 1f;
		if (body_work.move_counter >= body_work.move_frame)
		{
			vecFx.x = body_work.end_pos.x;
			vecFx.y = body_work.end_pos.y;
			vecFx.z = body_work.end_pos.z;
		}
		else
		{
			float num = body_work.move_counter / body_work.move_frame;
			int ang = AKM_DEGtoA32(180f * num);
			float num2 = 0.5f * (1f - nnCos(ang));
			VecFx32 vecFx2 = new VecFx32
			{
				x = (int)((float)(body_work.end_pos.x - body_work.start_pos.x) * num2),
				y = (int)((float)(body_work.end_pos.y - body_work.start_pos.y) * num2),
				z = (int)((float)(body_work.end_pos.z - body_work.start_pos.z) * num2)
			};
			vecFx.x = body_work.start_pos.x + vecFx2.x;
			vecFx.y = body_work.start_pos.y + vecFx2.y;
			vecFx.z = body_work.start_pos.z + vecFx2.z;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		oBS_OBJECT_WORK.pos.x = vecFx.x;
		oBS_OBJECT_WORK.pos.y = vecFx.y;
		oBS_OBJECT_WORK.pos.z = vecFx.z;
		return body_work.move_frame - body_work.move_counter;
	}

	private static void gmBoss3BodyInitTurn(GMS_BOSS3_BODY_WORK body_work, short dest_angle, float frame, int flag_positive)
	{
		body_work.turn_counter = 0f;
		body_work.turn_frame = frame;
		body_work.turn_start = body_work.angle_current;
		ushort turn_amount = (ushort)(dest_angle - body_work.angle_current);
		body_work.turn_amount = turn_amount;
		if (flag_positive == 0)
		{
			ushort num = (ushort)(body_work.turn_amount - AKM_DEGtoA32(360));
			body_work.turn_amount = num - AKM_DEGtoA32(360);
		}
	}

	private static float gmBoss3BodyUpdateTurn(GMS_BOSS3_BODY_WORK body_work)
	{
		if (body_work.turn_frame < 1f)
		{
			return 0f;
		}
		body_work.turn_counter += 1f;
		short deg;
		if (body_work.turn_counter >= body_work.turn_frame)
		{
			deg = (short)(body_work.turn_start + body_work.turn_amount);
		}
		else
		{
			float num = body_work.turn_counter / body_work.turn_frame;
			int ang = AKM_DEGtoA32(180f * num);
			float num2 = (float)body_work.turn_amount * 0.5f * (1f - nnCos(ang));
			deg = (short)((float)body_work.turn_start + num2);
		}
		gmBoss3BodySetDirection(body_work, deg);
		return body_work.turn_frame - body_work.turn_counter;
	}

	private static int gmBoss3BodyChaseCheckTurn(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			if (oBS_OBJECT_WORK.spd.x < 0)
			{
				return 0;
			}
		}
		else if (oBS_OBJECT_WORK.spd.x > 0)
		{
			return 0;
		}
		return 1;
	}

	private static void gmBoss3BodyChaseAdjustMoveSpeed(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		GMS_BOSS3_MGR_WORK gMS_BOSS3_MGR_WORK = gmBoss3MgrGetMgrWork(oBS_OBJECT_WORK);
		int num = FX_F32_TO_FX32(1f + (float)(8 - gMS_BOSS3_MGR_WORK.life) * 0.2f);
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (gMS_PLAYER_WORK.obj_work.pos.y < oBS_OBJECT_WORK.pos.y)
		{
			if (oBS_OBJECT_WORK.spd.x > 0 && oBS_OBJECT_WORK.pos.x < gMS_PLAYER_WORK.obj_work.pos.x)
			{
				num = FX_Mul(num, 8192);
			}
			if (oBS_OBJECT_WORK.spd.x < 0 && gMS_PLAYER_WORK.obj_work.pos.x < oBS_OBJECT_WORK.pos.x)
			{
				num = FX_Mul(num, 8192);
			}
		}
		oBS_OBJECT_WORK.spd.x = FX_Mul(oBS_OBJECT_WORK.spd.x, num);
		oBS_OBJECT_WORK.spd.y = FX_Mul(oBS_OBJECT_WORK.spd.y, num);
		if (body_work.is_move == 0)
		{
			oBS_OBJECT_WORK.spd.x = 0;
			oBS_OBJECT_WORK.spd.y = 0;
		}
	}

	private static int gmBoss3BodyBattleCalcPattern(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK obj_work_parts = GMM_BS_OBJ(body_work);
		GMS_BOSS3_MGR_WORK gMS_BOSS3_MGR_WORK = gmBoss3MgrGetMgrWork(obj_work_parts);
		int num = mtMathRand() % 100;
		int num2 = 0;
		for (int i = 0; 7 > i; i++)
		{
			num2 += g_gm_boss3_battle_pattern_per[gMS_BOSS3_MGR_WORK.life - 1][i];
			if (num < num2)
			{
				return i;
			}
		}
		return 0;
	}

	private static int gmBoss3BodyBattleInitMovePattern(GMS_BOSS3_BODY_WORK body_work, int pattern_no, int pos_index, int move_speed)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (g_gm_boss3_battle_move_x[pattern_no][pos_index] == 0)
		{
			return 0;
		}
		VecFx32 dest_pos = new VecFx32(oBS_OBJECT_WORK.pos.x + g_gm_boss3_battle_move_x[pattern_no][pos_index] * 4096, oBS_OBJECT_WORK.pos.y, oBS_OBJECT_WORK.pos.z);
		float frame = gmBoss3BodyCalcMoveXNormalFrame(body_work, dest_pos.x, move_speed);
		gmBoss3BodyInitMoveNormal(body_work, dest_pos, frame);
		return 1;
	}

	private static int gmBoss3BodyBattleCheckTurn(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			if (body_work.end_pos.x <= body_work.start_pos.x)
			{
				return 0;
			}
		}
		else if (body_work.start_pos.x <= body_work.end_pos.x)
		{
			return 0;
		}
		return 1;
	}

	private static OBS_OBJECT_WORK gmBoss3BodyBattleSearchPillar()
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK;
		for (oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, 3); oBS_OBJECT_WORK != null; oBS_OBJECT_WORK = ObjObjectSearchRegistObject(oBS_OBJECT_WORK, 3))
		{
			GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
			if (gMS_ENEMY_3D_WORK.ene_com.eve_rec.id == 279)
			{
				break;
			}
		}
		return oBS_OBJECT_WORK;
	}

	private static void gmBoss3BodyDamage(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK obj_work_parts = GMM_BS_OBJ(body_work);
		if ((body_work.flag & 1) == 0)
		{
			GMS_BOSS3_MGR_WORK gMS_BOSS3_MGR_WORK = gmBoss3MgrGetMgrWork(obj_work_parts);
			gMS_BOSS3_MGR_WORK.life--;
			if (gMS_BOSS3_MGR_WORK.life > 0)
			{
				body_work.flag |= 1073741824u;
			}
			else
			{
				body_work.flag |= 2147483648u;
			}
			GmSoundPlaySE("Boss0_01");
			gmBoss3EffDamageInit(body_work);
			GmPadVibSet(1, 30f, 8192, 8192, 0f, 0f, 0f, 8191u);
			gmBoss3BodySetInvincibleTime(body_work, 120u);
		}
	}

	private static int gmBoss3BodyEscapeCheckScreenOut(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (oBS_OBJECT_WORK.pos.x >= (g_gm_main_system.map_fcol.right + 64) * 4096)
		{
			return 1;
		}
		return 0;
	}

	private static void gmBoss3BodyEscapeAddjustSpeed(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (MTM_MATH_ABS(oBS_OBJECT_WORK.spd.x) > -1228)
		{
			oBS_OBJECT_WORK.spd.x = 6144;
			oBS_OBJECT_WORK.spd.y = -1228;
			oBS_OBJECT_WORK.spd_add.x = 0;
			oBS_OBJECT_WORK.spd_add.y = 0;
		}
	}

	private static void gmBoss3BodyChangeState(GMS_BOSS3_BODY_WORK body_work, int state)
	{
		GMF_BOSS3_BODY_STATE_FUNC gMF_BOSS3_BODY_STATE_FUNC = gm_boss3_body_state_func_tbl_leave[body_work.state];
		if (gMF_BOSS3_BODY_STATE_FUNC != null)
		{
			gMF_BOSS3_BODY_STATE_FUNC(body_work);
		}
		body_work.prev_state = body_work.state;
		body_work.state = state;
		GMF_BOSS3_BODY_STATE_FUNC gMF_BOSS3_BODY_STATE_FUNC2 = gm_boss3_body_state_func_tbl_enter[body_work.state];
		if (gMF_BOSS3_BODY_STATE_FUNC2 != null)
		{
			gMF_BOSS3_BODY_STATE_FUNC2(body_work);
		}
	}

	private static void gmBoss3BodyStateStartEnter(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		oBS_OBJECT_WORK.flag |= 2u;
		gmBoss3BodySetActionAllParts(body_work, 0, 1);
		gmBoss3BodySetDirectionNormal(body_work);
		if (GmBsCmnIsFinalZoneType(oBS_OBJECT_WORK) != 0)
		{
			body_work.proc_update = gmBoss3BodyStateStartUpdateWait;
		}
		else
		{
			body_work.proc_update = gmBoss3BodyStateStartUpdateWaitScrLimit;
		}
		oBS_OBJECT_WORK.user_timer = 180;
		body_work.ene_3d.ene_com.enemy_flag |= 32768u;
	}

	private static void gmBoss3BodyStateStartLeave(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		oBS_OBJECT_WORK.flag &= 4294967293u;
		body_work.flag &= 4294967279u;
		body_work.ene_3d.ene_com.enemy_flag &= 4294934527u;
	}

	private static void gmBoss3BodyStateStartUpdateWaitScrLimit(GMS_BOSS3_BODY_WORK body_work)
	{
		if ((g_gm_main_system.game_flag & 0x8000) != 0)
		{
			body_work.proc_update = gmBoss3BodyStateStartUpdateWait;
		}
	}

	private static void gmBoss3BodyStateStartUpdateWait(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		gmBoss3BodySetDirectionNormal(body_work);
		if (oBS_OBJECT_WORK.user_timer > 0)
		{
			oBS_OBJECT_WORK.user_timer--;
			return;
		}
		gmBoss3BodySetActionAllParts(body_work, 1);
		body_work.is_move = 1;
		gmBoss3EffAfterburnerRequestCreate(body_work);
		oBS_OBJECT_WORK.disp_flag &= 4294967294u;
		gmBoss3BodyInitTurn(body_work, GMD_BOSS3_ANGLE_RIGHT, 60f, 1);
		body_work.proc_update = gmBoss3BodyStateStartUpdateEnd;
	}

	private static void gmBoss3BodyStateStartUpdateEnd(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		gmBoss3BodyUpdateTurn(body_work);
		if (ObjViewOutCheck(oBS_OBJECT_WORK.pos.x, oBS_OBJECT_WORK.pos.y, 64, 0, 0, 0, 0) != 0)
		{
			GmGmkCamScrLimitRelease(4);
			gmBoss3BodyChangeState(body_work, 2);
		}
	}

	private static void gmBoss3BodyStateChaseMoveEnter(GMS_BOSS3_BODY_WORK body_work)
	{
		gmBoss3BodySetActionAllParts(body_work, 1);
		body_work.proc_update = gmBoss3BodyStateChaseMoveUpdate;
		gmBoss3EffAfterburnerRequestCreate(body_work);
	}

	private static void gmBoss3BodyStateChaseMoveLeave(GMS_BOSS3_BODY_WORK body_work)
	{
		gmBoss3EffAfterburnerRequestDelete(body_work);
	}

	private static void gmBoss3BodyStateChaseMoveUpdate(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (gmBoss3BodyChaseCheckTurn(body_work) != 0)
		{
			short dest_angle;
			int flag_positive;
			if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
			{
				oBS_OBJECT_WORK.disp_flag &= 4294967294u;
				dest_angle = GMD_BOSS3_ANGLE_RIGHT;
				flag_positive = 1;
			}
			else
			{
				oBS_OBJECT_WORK.disp_flag |= 1u;
				dest_angle = GMD_BOSS3_ANGLE_LEFT;
				flag_positive = 0;
			}
			gmBoss3BodyInitTurn(body_work, dest_angle, 60f, flag_positive);
		}
		gmBoss3BodyUpdateTurn(body_work);
		if (oBS_OBJECT_WORK.user_flag != 0)
		{
			gmBoss3BodyChangeState(body_work, 3);
		}
	}

	private static void gmBoss3BodyStatePreBattleEnter(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		gmBoss3BodySetActionAllParts(body_work, 1);
		body_work.proc_update = gmBoss3BodyStatePreBattleUpdateStart;
		oBS_OBJECT_WORK.user_timer = 120;
		oBS_OBJECT_WORK.ppMove = ObjObjectMove;
		gmBoss3EffAfterburnerRequestDelete(body_work);
	}

	private static void gmBoss3BodyStatePreBattleLeave(GMS_BOSS3_BODY_WORK body_work)
	{
		gmBoss3EffAfterburnerRequestDelete(body_work);
	}

	private static void gmBoss3BodyStatePreBattleUpdateStart(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (ObjViewOutCheck(oBS_OBJECT_WORK.pos.x, oBS_OBJECT_WORK.pos.y, 0, 0, 0, 0, 0) != 0)
		{
			return;
		}
		if (oBS_OBJECT_WORK.user_timer > 0)
		{
			oBS_OBJECT_WORK.user_timer--;
			return;
		}
		if (_am_draw_video.wide_screen)
		{
			GmCameraScaleSet(0.85f, 0.0024999997f);
			GmMapSetDrawMarginMag();
		}
		oBS_OBJECT_WORK.disp_flag |= 1u;
		gmBoss3BodyInitTurn(body_work, GMD_BOSS3_ANGLE_LEFT, 60f, 0);
		gmBoss3BodySetActionAllParts(body_work, 1);
		body_work.proc_update = gmBoss3BodyStatePreBattleUpdateTurn;
		if (GmBsCmnIsFinalZoneType(oBS_OBJECT_WORK) == 0)
		{
			GmSoundChangeAngryBossBGM();
		}
	}

	private static void gmBoss3BodyStatePreBattleUpdateTurn(GMS_BOSS3_BODY_WORK body_work)
	{
		float num = gmBoss3BodyUpdateTurn(body_work);
		if (!(num > 0f))
		{
			gmBoss3BodySetActionAllParts(body_work, 2);
			body_work.proc_update = gmBoss3BodyStatePreBattleUpdateLaugh;
			OBS_OBJECT_WORK oBS_OBJECT_WORK = gmBoss3BodyBattleSearchPillar();
			if (oBS_OBJECT_WORK != null)
			{
				GmGmkBoss3PillarWallChangeModeActive(oBS_OBJECT_WORK);
			}
			GmMapSetMapDrawSize(5);
			GmWaterSurfaceSetFlagDraw(false);
		}
	}

	private static void gmBoss3BodyStatePreBattleUpdateLaugh(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK obj_work = GMM_BS_OBJ(body_work);
		if (GmBsCmnIsActionEnd(obj_work) != 0)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = gmBoss3BodyBattleSearchPillar();
			if (oBS_OBJECT_WORK != null)
			{
				GmGmkBoss3PillarWallClearFlagNoPressDie(oBS_OBJECT_WORK);
			}
			gmBoss3BodyChangeState(body_work, 4);
			GmCameraScaleSet(1f, 0.0024999997f);
			GmMapSetDrawMarginNormal();
		}
	}

	private static void gmBoss3BodyStateBattleEnter(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		gmBoss3BodySetActionAllParts(body_work, 1);
		int num = g_gm_main_system.map_fcol.right - g_gm_main_system.map_fcol.left;
		int x = (g_gm_main_system.map_fcol.left + num / 2) * 4096;
		VecFx32 dest_pos = new VecFx32(x, oBS_OBJECT_WORK.pos.y, oBS_OBJECT_WORK.pos.z);
		float frame = gmBoss3BodyCalcMoveXNormalFrame(body_work, dest_pos.x, 4096);
		gmBoss3BodyInitMoveNormal(body_work, dest_pos, frame);
		if (gmBoss3BodyBattleCheckTurn(body_work) != 0)
		{
			short dest_angle;
			int flag_positive;
			if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
			{
				oBS_OBJECT_WORK.disp_flag &= 4294967294u;
				dest_angle = GMD_BOSS3_ANGLE_RIGHT;
				flag_positive = 1;
			}
			else
			{
				oBS_OBJECT_WORK.disp_flag |= 1u;
				dest_angle = GMD_BOSS3_ANGLE_LEFT;
				flag_positive = 0;
			}
			gmBoss3BodyInitTurn(body_work, dest_angle, 60f, flag_positive);
		}
		body_work.proc_update = gmBoss3BodyStateBattleUpdateMoveCenter;
		gmBoss3EffAfterburnerRequestCreate(body_work);
	}

	private static void gmBoss3BodyStateBattleLeave(GMS_BOSS3_BODY_WORK body_work)
	{
		gmBoss3EffAfterburnerRequestDelete(body_work);
	}

	private static void gmBoss3BodyStateBattleUpdateMoveCenter(GMS_BOSS3_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		float num = gmBoss3BodyUpdateTurn(body_work);
		float num2 = gmBoss3BodyUpdateMoveNormal(body_work);
		if (!(num > 0f) && !(num2 > 0f))
		{
			if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
			{
				gmBoss3BodySetActionAllParts(body_work, 3);
			}
			else
			{
				gmBoss3BodySetActionAllParts(body_work, 4);
			}
