	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (oBS_OBJECT_WORK.user_timer > 0)
		{
			oBS_OBJECT_WORK.user_timer--;
			return;
		}
		int move_speed = 4096;
		GmBsCmnIsFinalZoneType(oBS_OBJECT_WORK);
		if (gmBoss3BodyBattleInitMovePattern(body_work, body_work.pattern_no, 1, move_speed) != 0)
		{
			if (gmBoss3BodyBattleCheckTurn(body_work) != 0)
			{
