			body_work.proc_update = gmBoss3BodyStateBattleUpdateMoveSecond;
			gmBoss3BodySetActionAllParts(body_work, 1);
		}
		else
		{
			body_work.proc_update = gmBoss3BodyStateBattleUpdateWaitActive;
			oBS_OBJECT_WORK.user_timer = GmGmkBoss3PillarGetActiveTime(body_work.pattern_no) - 240 + 120;
