	private static void gmBoss3BodyMainFuncWaitSetup(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS3_BODY_WORK gMS_BOSS3_BODY_WORK = (GMS_BOSS3_BODY_WORK)obj_work;
		GMS_BOSS3_MGR_WORK mgr_work = gmBoss3MgrGetMgrWork(obj_work);
		if (gmBoss3MgrCheckSetupComplete(mgr_work) != 0)
		{
			GmBsCmnInitBossMotionCBSystem(obj_work, gMS_BOSS3_BODY_WORK.bmcb_mgr);
			GmBsCmnCreateSNMWork(gMS_BOSS3_BODY_WORK.snm_work, obj_work.obj_3d._object, 1);
			GmBsCmnAppendBossMotionCallback(gMS_BOSS3_BODY_WORK.bmcb_mgr, gMS_BOSS3_BODY_WORK.snm_work.bmcb_link);
			for (int i = 0; 1 > i; i++)
			{
				gMS_BOSS3_BODY_WORK.snm_reg_id[i] = GmBsCmnRegisterSNMNode(gMS_BOSS3_BODY_WORK.snm_work, g_boss3_node_index_list[i]);
			}
			obj_work.ppFunc = gmBoss3BodyMainFunc;
			gmBoss3BodyChangeState(gMS_BOSS3_BODY_WORK, 1);
		}
	}

	private static void gmBoss3BodyMainFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS3_BODY_WORK gMS_BOSS3_BODY_WORK = (GMS_BOSS3_BODY_WORK)obj_work;
		gmBoss3BodyUpdateNoHitTime(gMS_BOSS3_BODY_WORK);
		gmBoss3BodyUpdateInvincibleTime(gMS_BOSS3_BODY_WORK);
		if (gMS_BOSS3_BODY_WORK.proc_update != null)
		{
			gMS_BOSS3_BODY_WORK.proc_update(gMS_BOSS3_BODY_WORK);
		}
		if ((gMS_BOSS3_BODY_WORK.flag & 0x2000000) != 0)
		{
			gmBoss3EffAfterburnerInit(gMS_BOSS3_BODY_WORK);
		}
		if ((gMS_BOSS3_BODY_WORK.flag & 0x80000000u) != 0)
		{
			gMS_BOSS3_BODY_WORK.flag &= 1073741823u;
			gmBoss3BodyChangeState(gMS_BOSS3_BODY_WORK, 5);
			return;
		}
		if ((gMS_BOSS3_BODY_WORK.flag & 0x40000000) != 0)
		{
			gMS_BOSS3_BODY_WORK.flag &= 3221225471u;
			gMS_BOSS3_BODY_WORK.flag |= 536870912u;
			GmBsCmnInitObject3DNNDamageFlicker(obj_work, gMS_BOSS3_BODY_WORK.flk_work, 32f);
		}
		GmBsCmnUpdateObject3DNNDamageFlicker(obj_work, gMS_BOSS3_BODY_WORK.flk_work);
		gmBoss3BodyUpdateDirection(gMS_BOSS3_BODY_WORK);
	}

	private static void gmBoss3EggChangeAction(GMS_BOSS3_EGG_WORK egg_work, int action_id)
	{
		gmBoss3EggChangeAction(egg_work, action_id, 0);
	}

	private static void gmBoss3EggChangeAction(GMS_BOSS3_EGG_WORK egg_work, int action_id, int force_change)
	{
		GMS_BOSS3_PART_ACT_INFO gMS_BOSS3_PART_ACT_INFO = gm_boss3_egg_act_info_tbl[action_id];
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		if (force_change == 0 && egg_work.egg_action_id == action_id && (egg_work.flag & 1) != 0)
		{
			return;
		}
		egg_work.egg_action_id = action_id;
		egg_work.flag |= 1u;
		if (gMS_BOSS3_PART_ACT_INFO.is_maintain != 0)
		{
			if (gMS_BOSS3_PART_ACT_INFO.is_repeat != 0)
			{
				oBS_OBJECT_WORK.disp_flag |= 4u;
			}
		}
		else
		{
			GmBsCmnSetAction(oBS_OBJECT_WORK, gMS_BOSS3_PART_ACT_INFO.mtn_id, gMS_BOSS3_PART_ACT_INFO.is_repeat, gMS_BOSS3_PART_ACT_INFO.is_blend);
		}
		oBS_OBJECT_WORK.obj_3d.speed[0] = gMS_BOSS3_PART_ACT_INFO.mtn_spd;
		oBS_OBJECT_WORK.obj_3d.blend_spd = gMS_BOSS3_PART_ACT_INFO.blend_spd;
	}

	private static void gmBoss3EggRevertAction(GMS_BOSS3_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		GMS_BOSS3_BODY_WORK gMS_BOSS3_BODY_WORK = (GMS_BOSS3_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GMM_BS_OBJ(gMS_BOSS3_BODY_WORK);
		egg_work.flag &= 4294967294u;
		GMS_BOSS3_PART_ACT_INFO gMS_BOSS3_PART_ACT_INFO = gm_boss3_act_info_tbl[gMS_BOSS3_BODY_WORK.action_id][1];
		GmBsCmnSetAction(oBS_OBJECT_WORK, gMS_BOSS3_PART_ACT_INFO.mtn_id, gMS_BOSS3_PART_ACT_INFO.is_repeat, 1);
		oBS_OBJECT_WORK.obj_3d.frame[0] = oBS_OBJECT_WORK2.obj_3d.frame[0];
	}

	private static void gmBoss3EggStateIdleInit(GMS_BOSS3_EGG_WORK egg_work)
	{
		egg_work.proc_update = gmBoss3EggStateIdleUpdate;
