	private static void gmBoss3EffBombsInit(GMS_BOSS3_EFF_BOMB_WORK bomb_work, OBS_OBJECT_WORK parent_obj, int pos_x, int pos_y, int width, int height, uint interval_min, uint interval_max)
	{
		bomb_work.parent_obj = parent_obj;
		bomb_work.interval_timer = 0u;
		bomb_work.interval_min = interval_min;
		bomb_work.interval_max = interval_max;
		bomb_work.pos[0] = pos_x;
		bomb_work.pos[1] = pos_y;
		bomb_work.area[0] = width;
		bomb_work.area[1] = height;
	}

	private static void gmBoss3EffBombsUpdate(GMS_BOSS3_EFF_BOMB_WORK bomb_work)
	{
		if (bomb_work.interval_timer != 0)
		{
			bomb_work.interval_timer--;
			return;
		}
		GmSoundPlaySE("Boss0_02");
		GMS_EFFECT_3DES_WORK obj = GmEfctCmnEsCreate(null, 7);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(obj);
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GMM_BS_OBJ(bomb_work.parent_obj);
		int num = bomb_work.area[0];
		int num2 = bomb_work.area[1];
		int num3 = FX_Mul(AkMathRandFx(), num);
		int num4 = FX_Mul(AkMathRandFx(), num2);
		oBS_OBJECT_WORK.pos.x = bomb_work.pos[0] - (num >> 1) + num3;
		oBS_OBJECT_WORK.pos.y = bomb_work.pos[1] - (num2 >> 1) + num4;
		oBS_OBJECT_WORK.pos.z = oBS_OBJECT_WORK2.pos.z + 131072;
		int num5 = (int)(bomb_work.interval_max - bomb_work.interval_min);
		int num6 = AkMathRandFx();
		uint num7 = (uint)(num6 * num5 >> 12);
		bomb_work.interval_timer = bomb_work.interval_min + num7;
	}

