	public static T[] New<T>(uint n) where T : new()
	{
		return New<T>((int)n);
	}

	public static T[][] New<T>(uint m, uint n) where T : new()
	{
		return New<T>((int)m, (int)n);
	}

	public static T[] New<T>(int n) where T : new()
	{
		T[] array = new T[n];
		if (!typeof(T).IsValueType)
		{
			for (int i = 0; i < n; i++)
			{
				array[i] = new T();
			}
		}
		return array;
	}

	public static T[][] New<T>(int m, int n) where T : new()
	{
		bool flag = !typeof(T).IsValueType;
		T[][] array = new T[m][];
		for (int i = 0; i < m; i++)
		{
			array[i] = new T[n];
			if (flag)
			{
				for (int j = 0; j < n; j++)
				{
					array[i][j] = new T();
				}
			}
		}
		return array;
	}

	public static void ClearArray<T>(T[] data) where T : IClearable
	{
		int index = 0;
		int length = data.Length;
		ClearArray(data, index, length);
	}

	public static void ClearArray<T>(T[] data, int index, int length) where T : IClearable
	{
		for (int i = index; i < length; i++)
		{
			if (data[i] != null)
			{
				data[i].Clear();
			}
		}
	}

	private static void nnCalcMatrixPaletteMotion(NNS_MATRIX[] mtxpal, uint[] nodestatlist, NNS_OBJECT obj, NNS_MOTION mot, float frame, NNS_MATRIX basemtx, NNS_MATRIXSTACK mstk, uint flag)
	{
		if ((mot.fType & 1) == 0)
		{
			return;
		}
		nncalcmatrixpalettemotion.nnsSubMotIdx = 0;
		float dstframe;
		int num = nnCalcMotionFrame(out dstframe, mot.fType, mot.StartFrame, mot.EndFrame, frame);
		nncalcmatrixpalettemotion.nnsMtxPal = mtxpal;
		nncalcmatrixpalettemotion.nnsNodeStatList = nodestatlist;
		nncalcmatrixpalettemotion.nnsNSFlag = flag;
		nncalcmatrixpalettemotion.nnsObj = obj;
		nncalcmatrixpalettemotion.nnsNodeList = obj.pNodeList;
		nncalcmatrixpalettemotion.nnsMstk = mstk;
		nncalcmatrixpalettemotion.nnsMot = mot;
		nncalcmatrixpalettemotion.nnsFrame = dstframe;
		if (num != 0)
		{
			if (basemtx != null)
			{
				nncalcmatrixpalettemotion.nnsBaseMtx = basemtx;
			}
			else
			{
				nncalcmatrixpalettemotion.nnsBaseMtx = nngUnitMatrix;
			}
			nnSetCurrentMatrix(mstk, nncalcmatrixpalettemotion.nnsBaseMtx);
			nnCalcMatrixPaletteMotionNode(0);
		}
		else
		{
			nnCalcMatrixPalette(mtxpal, nodestatlist, obj, basemtx, mstk, nncalcmatrixpalettemotion.nnsNSFlag);
		}
	}

	private static int nnCalcMotionFrame(out float dstframe, uint fType, float startframe, float endframe, float frame)
	{
		if ((fType & 0x40) != 0)
		{
			dstframe = frame;
			return 1;
		}
		switch (fType & 0x1F0040 & 0xFFFFFFBFu)
		{
		case 65536u:
			if (startframe <= frame && frame < endframe)
			{
				dstframe = frame;
				return 1;
			}
			dstframe = frame;
			return 0;
		case 262144u:
			if (startframe <= frame && frame < endframe)
			{
				dstframe = frame;
			}
			else
			{
				float num = frame - startframe;
				float num2 = endframe - startframe;
				float num3 = num / num2;
				int num4 = (int)num3;
				if (num3 < 0f)
				{
					num4--;
				}
				num3 = num4;
				dstframe = frame - num2 * num3;
			}
			return 1;
		case 131072u:
			if (startframe > frame)
			{
				dstframe = startframe;
			}
			else if (endframe <= frame)
			{
				dstframe = endframe;
			}
			else
			{
				dstframe = frame;
			}
			return 1;
		case 524288u:
		{
			float num = frame - startframe;
			float num2 = endframe - startframe;
			float num3 = num / num2;
			int num4 = (int)num3;
			if (num3 < 0f)
			{
				num4--;
			}
			num3 = num4;
			if ((num4 & 1) != 0)
			{
				dstframe = startframe - num + num2 * (num3 + 1f);
			}
			else
			{
				dstframe = frame - num2 * num3;
			}
			return 1;
		}
		default:
			dstframe = frame;
			return 0;
		}
	}

	private static void nnCalcMatrixPaletteMotionNode(int nodeIdx)
	{
		int? pHideFlag = 0;
		NNS_NODE nNS_NODE;
		do
		{
			nNS_NODE = nncalcmatrixpalettemotion.nnsNodeList[nodeIdx];
			if ((nNS_NODE.fType & 0x8000000) != 0)
			{
				if ((nNS_NODE.fType & 0x6000000) != 0)
				{
					nnPushMatrix(nncalcmatrixpalettemotion.nnsMstk, null);
					if ((nNS_NODE.fType & 0x2000000) != 0)
					{
						nnCalcMatrixPaletteMotionNode1BoneXSIIK(nodeIdx);
					}
					else if ((nNS_NODE.fType & 0x4000000) != 0)
					{
						nnCalcMatrixPaletteMotionNode2BoneXSIIK(nodeIdx);
					}
					nnPopMatrix(nncalcmatrixpalettemotion.nnsMstk);
					nodeIdx = nNS_NODE.iSibling;
					continue;
				}
			}
			else
			{
				if ((nNS_NODE.fType & 0x4000) != 0)
				{
					nnPushMatrix(nncalcmatrixpalettemotion.nnsMstk, null);
					nnCalcMatrixPaletteMotionNode1BoneSIIK(nodeIdx);
					nnPopMatrix(nncalcmatrixpalettemotion.nnsMstk);
					break;
				}
				if ((nNS_NODE.fType & 0x8000) != 0)
				{
					nnPushMatrix(nncalcmatrixpalettemotion.nnsMstk, null);
					nnCalcMatrixPaletteMotionNode2BoneSIIK(nodeIdx);
					nnPopMatrix(nncalcmatrixpalettemotion.nnsMstk);
					break;
				}
			}
			nnPushMatrix(nncalcmatrixpalettemotion.nnsMstk, null);
			NNS_MATRIX nNS_MATRIX = nnGetCurrentMatrix(nncalcmatrixpalettemotion.nnsMstk);
			nncalcmatrixpalettemotion.nnsSubMotIdx = nnCalcNodeMotionCore(nNS_MATRIX, ref pHideFlag, nncalcmatrixpalettemotion.nnsBaseMtx, nNS_NODE, nodeIdx, nncalcmatrixpalettemotion.nnsObj, nncalcmatrixpalettemotion.nnsMot, nncalcmatrixpalettemotion.nnsSubMotIdx, nncalcmatrixpalettemotion.nnsFrame);
			if (nNS_NODE.iMatrix != -1)
			{
				if ((nNS_NODE.fType & 8) != 0)
				{
					nnCopyMatrix(nncalcmatrixpalettemotion.nnsMtxPal[nNS_NODE.iMatrix], nNS_MATRIX);
				}
				else
				{
					nnMultiplyMatrix(nncalcmatrixpalettemotion.nnsMtxPal[nNS_NODE.iMatrix], nNS_MATRIX, nNS_NODE.InvInitMtx);
				}
			}
			if (nncalcmatrixpalettemotion.nnsNodeStatList != null)
			{
				if (nodeIdx == 0 && nncalcmatrixpalettemotion.nnsNSFlag != 0)
				{
					nncalcmatrixpalettemotion.nnsRootScale = nnEstimateMatrixScaling(nNS_MATRIX);
				}
				int? num = pHideFlag;
				if (num.GetValueOrDefault() != 0 || !num.HasValue)
				{
					nncalcmatrixpalettemotion.nnsNodeStatList[nodeIdx] |= 1u;
				}
				nnCalcClipSetNodeStatus(nncalcmatrixpalettemotion.nnsNodeStatList, nncalcmatrixpalettemotion.nnsNodeList, nodeIdx, nNS_MATRIX, nncalcmatrixpalettemotion.nnsRootScale, nncalcmatrixpalettemotion.nnsNSFlag);
			}
			if (nNS_NODE.iChild != -1)
			{
				nnCalcMatrixPaletteMotionNode(nNS_NODE.iChild);
			}
			nnPopMatrix(nncalcmatrixpalettemotion.nnsMstk);
			nodeIdx = nNS_NODE.iSibling;
		}
		while (nNS_NODE.iSibling != -1);
	}

	private static int nnCalcNodeMotionCore(NNS_MATRIX pNodeMtx, ref int? pHideFlag, NNS_MATRIX pBaseMtx, NNS_NODE pNode, int NodeIdx, NNS_OBJECT pObj, NNS_MOTION pMot, int SubMotIdx, float frame)
	{
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_ROTATE_A32 rv = default(NNS_ROTATE_A32);
		NNS_QUATERNION quat = default(NNS_QUATERNION);
		NNS_VECTOR nNS_VECTOR2 = GlobalPool<NNS_VECTOR>.Alloc();
		uint fType = pNode.fType;
		uint num = pNode.fType & 0xF00;
		nNS_VECTOR.Assign(pNode.Translation);
		nNS_VECTOR2.Assign(pNode.Scaling);
		if ((fType & 0x1C000) != 0)
		{
			rv.x = (rv.y = (rv.z = 0));
		}
		else
		{
			rv.x = pNode.Rotation.x;
			rv.y = pNode.Rotation.y;
			rv.z = pNode.Rotation.z;
		}
		int num2 = (((fType & 1) == 0) ? 1 : 0);
		int num3 = (((fType & 2) == 0) ? 1 : 0);
		int num4 = (((fType & 4) == 0) ? 1 : 0);
		if (pHideFlag.HasValue)
		{
			pHideFlag = 0;
		}
		for (int i = SubMotIdx; i < pMot.nSubmotion; i++)
		{
			NNS_SUBMOTION nNS_SUBMOTION = pMot.pSubmotion[i];
			if (NodeIdx < nNS_SUBMOTION.Id)
			{
				SubMotIdx = i;
				break;
			}
			if (NodeIdx != nNS_SUBMOTION.Id || nNS_SUBMOTION.fType == 0 || !(nNS_SUBMOTION.StartFrame <= frame) || !(frame <= nNS_SUBMOTION.EndFrame))
			{
				continue;
			}
			uint fType2 = nNS_SUBMOTION.fIPType;
			if ((pMot.fType & 0x20000) != 0 && frame == nNS_SUBMOTION.EndFrame)
			{
				fType2 = 131072u;
			}
			float dstframe;
			if (nnCalcMotionFrame(out dstframe, fType2, nNS_SUBMOTION.StartKeyFrame, nNS_SUBMOTION.EndKeyFrame, frame) != 0)
			{
				if ((nNS_SUBMOTION.fType & 0x7800) != 0)
				{
					num3 |= nnCalcMotionRotate(nNS_SUBMOTION, dstframe, ref rv, quat, num);
				}
				else if ((nNS_SUBMOTION.fType & 0x700) != 0)
				{
					num2 |= nnCalcMotionTranslate(nNS_SUBMOTION, dstframe, nNS_VECTOR);
				}
				else if ((nNS_SUBMOTION.fType & 0x38000) != 0)
				{
					num4 |= nnCalcMotionScale(nNS_SUBMOTION, dstframe, nNS_VECTOR2);
				}
				else if ((nNS_SUBMOTION.fType & 0xC0000) != 0)
				{
					nnCallbackMotionUserData(pObj, pMot, i, NodeIdx, dstframe, frame);
				}
				else if ((nNS_SUBMOTION.fType & 0x100000) != 0 && pHideFlag.HasValue)
				{
					pHideFlag = nnCalcMotionNodeHide(nNS_SUBMOTION, dstframe);
				}
			}
		}
		if (num2 == 1)
		{
			if ((pNode.fType & 0x2000) != 0)
			{
				NNS_VECTORFAST dst = default(NNS_VECTORFAST);
				nnmSetUpVectorFast(out dst, nNS_VECTOR.x, nNS_VECTOR.y, nNS_VECTOR.z);
				nnTransformVectorFast(out dst, pBaseMtx, dst);
				nnCopyVectorFastMatrixTranslation(pNodeMtx, ref dst);
			}
			else
			{
				nnTranslateMatrixFast(pNodeMtx, nNS_VECTOR.x, nNS_VECTOR.y, nNS_VECTOR.z);
			}
		}
		if ((pNode.fType & 0x1C1000) != 0)
		{
			if ((pNode.fType & 0x1000) != 0)
			{
				nnCopyMatrix33(pNodeMtx, pBaseMtx);
			}
			if ((pNode.fType & 0x40000) != 0)
			{
				nnNormalizeColumn0(pNodeMtx);
			}
			if ((pNode.fType & 0x80000) != 0)
			{
				nnNormalizeColumn1(pNodeMtx);
			}
			if ((pNode.fType & 0x100000) != 0)
			{
				nnNormalizeColumn2(pNodeMtx);
			}
		}
		if (num3 == 1)
		{
			switch (num)
