			}
		}
	}

	private static void nnPutColorNTexture(int nTexture)
	{
		float[][] array = new float[8][];
		float[] array2 = new float[3];
		array[0] = array2;
		array[1] = new float[3] { 0f, 0f, 1f };
		array[2] = new float[3] { 0f, 1f, 1f };
		array[3] = new float[3] { 0f, 1f, 0f };
		array[4] = new float[3] { 1f, 1f, 0f };
		array[5] = new float[3] { 1f, 0f, 0f };
		array[6] = new float[3] { 1f, 0f, 1f };
		array[7] = new float[3] { 1f, 1f, 1f };
		float[][] array3 = array;
		if (nTexture >= array3.Length)
		{
			nTexture = array3.Length - 1;
		}
		OpenGL.glColor3fv(array3[nTexture]);
	}

	public static void amObjectSetup(out NNS_OBJECT _object, out NNS_TEXFILELIST texfilelist, object _buf)
	{
		_object = null;
		texfilelist = null;
		AmbChunk ambChunk = (AmbChunk)_buf;
		using (MemoryStream input = new MemoryStream(ambChunk.array, ambChunk.offset, ambChunk.array.Length - ambChunk.offset))
		{
			BinaryReader binaryReader = new BinaryReader(input);
			NNS_BINCNK_FILEHEADER nNS_BINCNK_FILEHEADER = NNS_BINCNK_FILEHEADER.Read(binaryReader);
			long num;
			binaryReader.BaseStream.Seek(num = nNS_BINCNK_FILEHEADER.OfsData, SeekOrigin.Begin);
			NNS_BINCNK_DATAHEADER nNS_BINCNK_DATAHEADER = NNS_BINCNK_DATAHEADER.Read(binaryReader);
			long num2 = num;
			binaryReader.BaseStream.Seek(nNS_BINCNK_FILEHEADER.OfsNOF0, SeekOrigin.Begin);
			NNS_BINCNK_NOF0HEADER.Read(binaryReader);
			int num3 = nNS_BINCNK_FILEHEADER.nChunk;
			while (num3 > 0)
			{
				switch (nNS_BINCNK_DATAHEADER.Id)
				{
				case 1280592206u:
					binaryReader.BaseStream.Seek(num2 + nNS_BINCNK_DATAHEADER.OfsMainData, SeekOrigin.Begin);
					texfilelist = NNS_TEXFILELIST.Read(binaryReader, num2);
					break;
				case 1112492366u:
					binaryReader.BaseStream.Seek(num2 + nNS_BINCNK_DATAHEADER.OfsMainData, SeekOrigin.Begin);
					_object = NNS_OBJECT.Read(binaryReader, num2);
					break;
				case 1145980238u:
					return;
				}
				num3--;
				binaryReader.BaseStream.Seek(num += 8 + nNS_BINCNK_DATAHEADER.OfsNextId, SeekOrigin.Begin);
				nNS_BINCNK_DATAHEADER = NNS_BINCNK_DATAHEADER.Read(binaryReader);
			}
		}
	}

	public static int amObjectLoad(out NNS_OBJECT _object, NNS_OBJECT obj_file, uint drawflag)
	{
		AMS_PARAM_VERTEX_BUFFER_OBJECT aMS_PARAM_VERTEX_BUFFER_OBJECT = new AMS_PARAM_VERTEX_BUFFER_OBJECT();
		_object = new NNS_OBJECT();
		aMS_PARAM_VERTEX_BUFFER_OBJECT.obj = _object;
		aMS_PARAM_VERTEX_BUFFER_OBJECT.srcobj = obj_file;
		aMS_PARAM_VERTEX_BUFFER_OBJECT.bindflag = 0u;
		aMS_PARAM_VERTEX_BUFFER_OBJECT.drawflag = drawflag;
		return amDrawRegistCommand(3, aMS_PARAM_VERTEX_BUFFER_OBJECT);
	}

	public static int amObjectLoad(out NNS_OBJECT _object, out NNS_TEXLIST texlist, out object texlistbuf, object buf, uint drawflag, string filepath, AMS_AMB_HEADER amb)
	{
		NNS_OBJECT _object2;
		NNS_TEXFILELIST texfilelist;
		amObjectSetup(out _object2, out texfilelist, buf);
		int nTex = texfilelist.nTex;
		texlistbuf = null;
		nnSetUpTexlist(out texlist, nTex, ref texlistbuf);
		int result = amObjectLoad(out _object, _object2, drawflag);
		if (filepath != null || amb != null)
		{
			result = amTextureLoad(texlist, texfilelist, filepath, amb);
		}
		return result;
	}

