	public static AMS_AME_HEADER readAMEfile(string filename)
	{
		filename = string.Format("Content/{0}", filename);
		BinaryReader binaryReader = new BinaryReader(GameData.OpenStream(filename));
		AMS_AME_HEADER result = readAMEfile(binaryReader);
		binaryReader.Dispose();
		return result;
	}

	public static AMS_AME_HEADER readAMEfile(AmbChunk data)
	{
		AMS_AME_HEADER aMS_AME_HEADER = null;
		using (MemoryStream input = new MemoryStream(data.array, data.offset, data.array.Length - data.offset))
		{
			using (BinaryReader br = new BinaryReader(input))
			{
				return readAMEfile(br);
			}
		}
	}

	private static AMS_AME_TEX_ANIM readTexAnim(BinaryReader br)
	{
		AMS_AME_TEX_ANIM aMS_AME_TEX_ANIM = new AMS_AME_TEX_ANIM();
		aMS_AME_TEX_ANIM.time = br.ReadSingle();
		aMS_AME_TEX_ANIM.key_num = br.ReadInt32();
		aMS_AME_TEX_ANIM.key_buf = new AMS_AME_TEX_ANIM_KEY[aMS_AME_TEX_ANIM.key_num];
		for (int i = 0; i < aMS_AME_TEX_ANIM.key_num; i++)
		{
			aMS_AME_TEX_ANIM.key_buf[i].time = br.ReadSingle();
			aMS_AME_TEX_ANIM.key_buf[i].l = br.ReadSingle();
			aMS_AME_TEX_ANIM.key_buf[i].t = br.ReadSingle();
			aMS_AME_TEX_ANIM.key_buf[i].r = br.ReadSingle();
			aMS_AME_TEX_ANIM.key_buf[i].b = br.ReadSingle();
		}
		return aMS_AME_TEX_ANIM;
	}

	private static void fillAMENodeBegin(AMS_AME_NODE node, short id, short type, uint flag, char[] name, int child_offset, int sibling_offset, int parent_offset)
	{
		node.id = id;
		node.type = type;
		node.flag = flag;
		Array.Copy(name, 0, node.name, 0, 12);
		node.child_offset = child_offset;
		node.sibling_offset = sibling_offset;
		node.parent_offset = parent_offset;
	}

	private static void readVector4(BinaryReader br, NNS_VECTOR4D v)
	{
		v.x = br.ReadSingle();
		v.y = br.ReadSingle();
		v.z = br.ReadSingle();
		v.w = br.ReadSingle();
	}

	private static void readQuaternion(BinaryReader br, ref NNS_QUATERNION q)
	{
		q.x = br.ReadSingle();
		q.y = br.ReadSingle();
		q.z = br.ReadSingle();
		q.w = br.ReadSingle();
	}

	public static AMS_AME_HEADER readAMEfile(BinaryReader br)
	{
		AMS_AME_HEADER aMS_AME_HEADER = new AMS_AME_HEADER();
		aMS_AME_HEADER.file_id = br.ReadBytes(4);
		aMS_AME_HEADER.file_version = br.ReadInt32();
		aMS_AME_HEADER.node_num = br.ReadInt32();
		aMS_AME_HEADER.node_ofst = br.ReadUInt32();
		aMS_AME_HEADER.bounding.center.x = br.ReadSingle();
		aMS_AME_HEADER.bounding.center.y = br.ReadSingle();
		aMS_AME_HEADER.bounding.center.z = br.ReadSingle();
		aMS_AME_HEADER.bounding.center.w = br.ReadSingle();
		aMS_AME_HEADER.bounding.radius = br.ReadSingle();
		aMS_AME_HEADER.bounding.radius2 = br.ReadSingle();
		br.BaseStream.Seek(8L, SeekOrigin.Current);
		br.BaseStream.Seek(16L, SeekOrigin.Current);
		aMS_AME_HEADER.node = new AMS_AME_NODE[aMS_AME_HEADER.node_num];
		br.BaseStream.Seek(aMS_AME_HEADER.node_ofst, SeekOrigin.Begin);
		Dictionary<uint, AMS_AME_NODE> dictionary = new Dictionary<uint, AMS_AME_NODE>(aMS_AME_HEADER.node_num);
		for (int i = 0; i < aMS_AME_HEADER.node_num; i++)
		{
			uint num = (uint)br.BaseStream.Position;
			num += 15;
			num &= 0xFFFFFFF0u;
			if (num >= br.BaseStream.Length)
			{
				break;
			}
			br.BaseStream.Seek(num, SeekOrigin.Begin);
			short id = br.ReadInt16();
			AME_AME_NODE_TYPE aME_AME_NODE_TYPE = (AME_AME_NODE_TYPE)br.ReadInt16();
			uint flag = br.ReadUInt32();
			char[] name = br.ReadChars(12);
			int child_offset = br.ReadInt32();
			int sibling_offset = br.ReadInt32();
			int parent_offset = br.ReadInt32();
			switch (aME_AME_NODE_TYPE)
			{
			case AME_AME_NODE_TYPE.AME_AME_NODE_TYPE_CIRCLE:
