				fillAMENodeBegin(aMS_AME_NODE_DIRECTIONAL, id, (short)aME_AME_NODE_TYPE, flag, name, child_offset, sibling_offset, parent_offset);
				readVector4(br, aMS_AME_NODE_DIRECTIONAL.translate);
