	public static uint IZM_FADE_COL_PAC(uint r, uint g, uint b, uint a)
	{
		return ((r & 0xFF) << 24) | ((g & 0xFF) << 16) | ((b & 0xFF) << 8) | (a & 0xFF);
	}

