	private static void IzFadeInit(int group, ushort pause_level, ushort dt_prio, uint draw_state, uint fade_set_type, byte start_col_r, byte start_col_g, byte start_col_b, byte start_col_a, byte end_col_r, byte end_col_g, byte end_col_b, byte end_col_a, float time, bool draw_start)
	{
		bool conti_state = false;
		IZS_FADE_WORK fade_work;
		if (iz_fade_tcb == null)
		{
			iz_fade_tcb = MTM_TASK_MAKE_TCB(izFadeMain, izFadeDest, 2u, pause_level, 4096u, group, () => new IZS_FADE_WORK(), "IZ_FADE_SYS");
			fade_work = (IZS_FADE_WORK)iz_fade_tcb.work;
		}
		else
		{
			fade_work = (IZS_FADE_WORK)iz_fade_tcb.work;
			conti_state = true;
		}
		IzFadeSetWork(fade_work, dt_prio, draw_state, fade_set_type, start_col_r, start_col_g, start_col_b, start_col_a, end_col_r, end_col_g, end_col_b, end_col_a, time, draw_start, conti_state);
	}

	private static void IzFadeExit()
	{
		if (iz_fade_tcb != null)
		{
			IZS_FADE_WORK iZS_FADE_WORK = (IZS_FADE_WORK)iz_fade_tcb.work;
			mtTaskChangeTcbProcedure(iz_fade_tcb, izFadeEndWaitMain);
			iZS_FADE_WORK.count = 0f;
			iz_fade_tcb = null;
		}
	}

	private static bool IzFadeIsExe()
	{
		if (iz_fade_tcb != null)
		{
			return true;
		}
		return false;
	}

	private static bool IzFadeIsEnd()
	{
		if (iz_fade_tcb != null)
		{
			IZS_FADE_WORK iZS_FADE_WORK = (IZS_FADE_WORK)iz_fade_tcb.work;
			if (iZS_FADE_WORK.count >= iZS_FADE_WORK.time)
			{
				return true;
			}
			return false;
		}
		return true;
	}

