	private static void IzFadeSetWork(IZS_FADE_WORK fade_work, ushort dt_prio, uint draw_state, uint fade_set_type, byte start_col_r, byte start_col_g, byte start_col_b, byte start_col_a, byte end_col_r, byte end_col_g, byte end_col_b, byte end_col_a, float time, bool draw_start, bool conti_state)
	{
		NNS_RGBA start_col = default(NNS_RGBA);
		ushort vtx_no = 1;
		if (!conti_state)
		{
			fade_work.Clear();
			start_col.r = (int)start_col_r;
			start_col.g = (int)start_col_g;
			start_col.b = (int)start_col_b;
			start_col.a = (int)start_col_a;
		}
		else if (fade_set_type == 1)
		{
			start_col = fade_work.now_col;
			vtx_no = fade_work.vtx_no;
		}
		else
		{
			start_col.r = (int)start_col_r;
			start_col.g = (int)start_col_g;
			start_col.b = (int)start_col_b;
			start_col.a = (int)start_col_a;
		}
		fade_work.count = 0f;
		fade_work.start_col = start_col;
		fade_work.end_col.r = (int)end_col_r;
		fade_work.end_col.g = (int)end_col_g;
		fade_work.end_col.b = (int)end_col_b;
		fade_work.end_col.a = (int)end_col_a;
		fade_work.now_col = fade_work.start_col;
		fade_work.time = time;
		fade_work.speed = 1f;
		fade_work.dt_prio = dt_prio;
		fade_work.draw_state = draw_state;
		fade_work.vtx_no = vtx_no;
		nnMakeUnitMatrix(fade_work.mtx);
		fade_work.flag &= 4294967294u;
		if (draw_start)
		{
			fade_work.flag |= 1u;
		}
		AMS_PARAM_DRAW_PRIMITIVE prim_param = fade_work.prim_param;
		prim_param.vtxPC2D = fade_work.vtx[fade_work.vtx_no];
		prim_param.mtx = fade_work.mtx;
		prim_param.format2D = 1;
		prim_param.type = 1;
		prim_param.count = 4;
		prim_param.texlist = null;
		prim_param.texId = -1;
		prim_param.ablend = 1;
		prim_param.zOffset = -1f;
		amDrawGetPrimBlendParam(0, prim_param);
		prim_param.aTest = 0;
		prim_param.zMask = 1;
		prim_param.zTest = 0;
		for (int i = 0; i < 2; i++)
		{
			fade_work.vtx[i][0].Pos.x = 0f;
			fade_work.vtx[i][0].Pos.y = 0f;
			fade_work.vtx[i][1].Pos.x = 0f;
			fade_work.vtx[i][1].Pos.y = AMD_SCREEN_HEIGHT;
			fade_work.vtx[i][2].Pos.x = AMD_SCREEN_WIDTH;
			fade_work.vtx[i][2].Pos.y = 0f;
			fade_work.vtx[i][3].Pos.x = AMD_SCREEN_WIDTH;
			fade_work.vtx[i][3].Pos.y = AMD_SCREEN_HEIGHT;
		}
	}

	private static void IzFadeUpdate(IZS_FADE_WORK fade_work)
	{
		if ((fade_work.flag & 2) != 0)
		{
			fade_work.flag &= 4294967293u;
		}
		else
		{
			fade_work.count += fade_work.speed;
			if (fade_work.count > fade_work.time)
			{
				fade_work.count = fade_work.time;
			}
		}
		float num = fade_work.count / fade_work.time;
		fade_work.now_col.a = fade_work.start_col.a * (1f - num) + fade_work.end_col.a * num;
		fade_work.now_col.r = fade_work.start_col.r * (1f - num) + fade_work.end_col.r * num;
		fade_work.now_col.g = fade_work.start_col.g * (1f - num) + fade_work.end_col.g * num;
		fade_work.now_col.b = fade_work.start_col.b * (1f - num) + fade_work.end_col.b * num;
		byte r = (byte)nnRoundOff(fade_work.now_col.r + 0.5f);
		byte g = (byte)nnRoundOff(fade_work.now_col.g + 0.5f);
		byte b = (byte)nnRoundOff(fade_work.now_col.b + 0.5f);
		byte a = (byte)nnRoundOff(fade_work.now_col.a + 0.5f);
		fade_work.vtx_no++;
		if (fade_work.vtx_no >= 2)
		{
			fade_work.vtx_no = 0;
		}
		ArrayPointer<NNS_PRIM2D_PC> arrayPointer = new ArrayPointer<NNS_PRIM2D_PC>(fade_work.vtx[fade_work.vtx_no], 0);
		int num2 = 0;
		while (num2 < 4)
		{
			(~arrayPointer).Col = IZM_FADE_COL_PAC(r, g, b, a);
			num2++;
			++arrayPointer;
		}
	}

	private static void IzFadeDraw(IZS_FADE_WORK fade_work)
	{
		fade_work.prim_param.vtxPC2D = fade_work.vtx[fade_work.vtx_no];
		amDrawPrim2D(fade_work.draw_state, fade_work.prim_param);
		if ((fade_work.flag & 1) != 0)
		{
			IZS_FADE_DT_WORK iZS_FADE_DT_WORK = new IZS_FADE_DT_WORK();
			iZS_FADE_DT_WORK.draw_state = fade_work.draw_state;
			iZS_FADE_DT_WORK.drawflag = 0u;
			amDrawMakeTask(izFadeDrawStart_DT, fade_work.dt_prio, iZS_FADE_DT_WORK);
		}
	}

	private static void izFadeDest(MTS_TASK_TCB tcb)
