	}

	private static void izFadeMain(MTS_TASK_TCB tcb)
	{
		IZS_FADE_WORK fade_work = (IZS_FADE_WORK)tcb.work;
		IzFadeUpdate(fade_work);
		IzFadeDraw(fade_work);
	}

	private static void izFadeEndWaitMain(MTS_TASK_TCB tcb)
	{
		IZS_FADE_WORK iZS_FADE_WORK = (IZS_FADE_WORK)tcb.work;
		iZS_FADE_WORK.count += 1f;
		if (iZS_FADE_WORK.count > 1f)
		{
			mtTaskClearTcb(tcb);
		}
	}

