		IzFadeRestoreDrawSetting();
	}

	private static void GmWaterSurfaceInitData(AMS_AMB_HEADER amb)
	{
		gmWaterSurfaceDataInit();
		gmWaterSurfaceDataSetAmbHeader(amb);
	}

	private static void GmWaterSurfaceBuildData()
	{
		int stage_id = gmWaterSurfaceGameSystemGetStageId();
		int num = gmWaterSurfaceGameSystemGetZoneType(stage_id);
		if (num == 2)
		{
			dwaterInit();
			AMS_AMB_HEADER aMS_AMB_HEADER = gmWaterSurfaceDataGetAmbHeader();
			AoTexBuild(_dmap_water.tex_color, readAMBFile(amBindGet(aMS_AMB_HEADER, aMS_AMB_HEADER.file_num - 1)));
			AoTexLoad(_dmap_water.tex_color);
			dwaterSetObjectAMB(aMS_AMB_HEADER, aMS_AMB_HEADER);
			uint objflag = 0u;
			dwaterLoadObject(objflag);
		}
	}

	private static bool GmWaterSurfaceCheckLoading()
	{
		bool result = true;
		if (GsMainSysGetDisplayListRegistNum() >= 192)
		{
			return false;
		}
		int stage_id = gmWaterSurfaceGameSystemGetStageId();
		int num = gmWaterSurfaceGameSystemGetZoneType(stage_id);
		if (num == 2)
		{
			GMS_WATER_SURFACE_DATA gMS_WATER_SURFACE_DATA = gmWaterSurfaceDataGetInfo();
			if (!AoTexIsLoaded(_dmap_water.tex_color))
			{
				result = false;
			}
			else if (!gMS_WATER_SURFACE_DATA.flag_load_object)
			{
				uint objflag = 0u;
				if (dwaterLoadObject(objflag) == 0)
				{
					result = false;
					gMS_WATER_SURFACE_DATA.flag_load_object = false;
				}
				else
				{
					gMS_WATER_SURFACE_DATA.flag_load_object = true;
				}
			}
		}
		return result;
	}

	private static void GmWaterSurfaceInit()
	{
		gmWaterSurfaceGameSystemSetWaterLevel(ushort.MaxValue);
		int stage_id = gmWaterSurfaceGameSystemGetStageId();
		int num = gmWaterSurfaceGameSystemGetZoneType(stage_id);
		if (num == 2)
		{
			gmWaterSurfaceInitMgr();
			gmWaterSurfaceCreateTcb();
		}
	}

	private static void GmWaterSurfaceExit()
	{
		gmWaterSurfaceExitMgr();
	}

	private static void GmWaterSurfaceFlushData()
	{
		int stage_id = gmWaterSurfaceGameSystemGetStageId();
		int num = gmWaterSurfaceGameSystemGetZoneType(stage_id);
		if (num == 2)
		{
			AoTexRelease(_dmap_water.tex_color);
		}
	}

	private static void GmWaterSurfaceRelease()
	{
		int stage_id = gmWaterSurfaceGameSystemGetStageId();
		int num = gmWaterSurfaceGameSystemGetZoneType(stage_id);
		if (num == 2)
		{
			gmWaterSurfaceDataRelease();
		}
	}

	private static bool GmWaterSurfaceCheckFlush()
	{
		if (GsMainSysGetDisplayListRegistNum() >= 192)
		{
			return false;
		}
		bool result = true;
		int stage_id = gmWaterSurfaceGameSystemGetStageId();
		int num = gmWaterSurfaceGameSystemGetZoneType(stage_id);
		if (num == 2 && _dmap_water != null)
		{
			if (!AoTexIsReleased(_dmap_water.tex_color))
			{
				result = false;
			}
			else if (_dmap_water.regist_index == -1)
			{
				_dmap_water.regist_index = dwaterRelease();
				result = false;
			}
			else if (!amDrawIsRegistComplete(_dmap_water.regist_index))
			{
				result = false;
			}
			else
			{
				dwaterExit();
			}
		}
		return result;
	}

	private static void GmWaterSurfaceRequestChangeWaterLevel(ushort water_level, ushort time, bool flag_add_time)
	{
		int stage_id = gmWaterSurfaceGameSystemGetStageId();
		int num = gmWaterSurfaceGameSystemGetZoneType(stage_id);
		if (num != 2)
		{
			return;
		}
		GMS_WATER_SURFACE_MGR gMS_WATER_SURFACE_MGR = gmWaterSurfaceGetMgr();
		if (gMS_WATER_SURFACE_MGR != null)
		{
			GMS_WATER_SURFACE_INFO gMS_WATER_SURFACE_INFO = (GMS_WATER_SURFACE_INFO)gMS_WATER_SURFACE_MGR.tcb_water.work;
			if (flag_add_time)
			{
				gMS_WATER_SURFACE_INFO.water_time += time;
			}
			else
			{
				gMS_WATER_SURFACE_INFO.water_time = time;
				gMS_WATER_SURFACE_INFO.water_counter = 0;
			}
			gMS_WATER_SURFACE_INFO.next_water_level = (int)water_level;
			gMS_WATER_SURFACE_INFO.now_water_level = (int)gmWaterSurfaceGameSystemGetWaterLevel();
		}
	}

