	private static void gmWaterSurfaceProc(MTS_TASK_TCB tcb)
	{
		GMS_WATER_SURFACE_INFO gMS_WATER_SURFACE_INFO = (GMS_WATER_SURFACE_INFO)tcb.work;
		float speed = 0f;
		if (ObjObjectPauseCheck(0u) == 0)
		{
			float num = gMS_WATER_SURFACE_INFO.water_time - gMS_WATER_SURFACE_INFO.water_counter;
			if (num != 0f)
			{
				float num2 = (gMS_WATER_SURFACE_INFO.next_water_level - gMS_WATER_SURFACE_INFO.now_water_level) / num;
				gMS_WATER_SURFACE_INFO.now_water_level += num2;
				if (1 > (ushort)MTM_MATH_ABS(gMS_WATER_SURFACE_INFO.now_water_level - gMS_WATER_SURFACE_INFO.next_water_level))
				{
					gMS_WATER_SURFACE_INFO.water_time = 0;
					gMS_WATER_SURFACE_INFO.water_counter = 0;
				}
				else
				{
					gMS_WATER_SURFACE_INFO.water_counter++;
				}
			}
			else
			{
				gMS_WATER_SURFACE_INFO.now_water_level = gMS_WATER_SURFACE_INFO.next_water_level;
			}
			if (!gMS_WATER_SURFACE_INFO.flag_draw)
			{
				gmWaterSurfaceGameSystemSetWaterLevel(ushort.MaxValue);
				return;
			}
			gmWaterSurfaceGameSystemSetWaterLevel((ushort)gMS_WATER_SURFACE_INFO.now_water_level);
			speed = amSystemGetFrameRateMain();
		}
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(6);
		float x = oBS_CAMERA.disp_pos.x;
		float y = oBS_CAMERA.disp_pos.y;
		float num3 = 0f - gMS_WATER_SURFACE_INFO.now_water_level - y;
		if (num3 < (float)(-(OBD_LCD_Y / 2 + 32)))
		{
			GMS_WATER_SURFACE_MGR gMS_WATER_SURFACE_MGR = gmWaterSurfaceGetMgr();
			if (gMS_WATER_SURFACE_MGR != null)
			{
				gMS_WATER_SURFACE_MGR.render_target = null;
			}
			return;
		}
		bool flag = false;
		if (num3 > (float)OBD_LCD_Y * 0.8f)
		{
			y = oBS_CAMERA.disp_pos.y;
			num3 = (float)OBD_LCD_Y * 0.8f;
			flag = true;
		}
		int roll = oBS_CAMERA.roll;
		float scale = 1f / oBS_CAMERA.scale;
		dwaterUpdate(speed, x, y, num3, roll, scale);
		if (!GmMainIsDrawEnable())
		{
			return;
		}
		dwaterSetParam();
		uint drawflag = 0u;
		ObjDraw3DNNSetCameraEx(6, 1, 9u);
		if (gMS_WATER_SURFACE_INFO.flag_enable_ref && !flag)
		{
			dwaterDrawReflection(9u, drawflag);
		}
		ObjDraw3DNNUserFunc(_gmWaterSurfaceTcbProcPreDrawDT, null, 0, 9u);
		ObjDraw3DNNSetCameraEx(g_obj.glb_camera_id, 1, 9u);
		ObjDraw3DNNSetCameraEx(6, 1, 4u);
		AMS_PARAM_DRAW_PRIMITIVE aMS_PARAM_DRAW_PRIMITIVE = GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Alloc();
		aMS_PARAM_DRAW_PRIMITIVE.aTest = 0;
		aMS_PARAM_DRAW_PRIMITIVE.zMask = 1;
		aMS_PARAM_DRAW_PRIMITIVE.zTest = 1;
		aMS_PARAM_DRAW_PRIMITIVE.ablend = 1;
		aMS_PARAM_DRAW_PRIMITIVE.bldSrc = 770;
		aMS_PARAM_DRAW_PRIMITIVE.bldDst = 1;
		aMS_PARAM_DRAW_PRIMITIVE.bldMode = 32774;
		NNS_PRIM3D_PCT_ARRAY nNS_PRIM3D_PCT_ARRAY = amDrawAlloc_NNS_PRIM3D_PCT(18);
		NNS_PRIM3D_PCT[] buffer = nNS_PRIM3D_PCT_ARRAY.buffer;
		int offset = nNS_PRIM3D_PCT_ARRAY.offset;
		OBS_CAMERA oBS_CAMERA2 = ObjCameraGet(0);
		x = oBS_CAMERA2.disp_pos.x;
		y = 0f - gMS_WATER_SURFACE_INFO.now_water_level;
		float num4 = FX_FX32_TO_F32(1310720);
		float num5 = oBS_CAMERA2.znear + 1f;
		float num6 = 300f;
		num3 = y - (oBS_CAMERA2.disp_pos.y - 300f);
		uint col = AMD_RGBA8888(byte.MaxValue, byte.MaxValue, byte.MaxValue, 96);
		for (int i = 0; i < 3; i++)
		{
			float num7 = num5 * (float)(i + 1);
			int num8 = offset + i * 6;
			buffer[num8].Pos.Assign(x - num6, y, num4 - num7);
			buffer[1 + num8].Pos.Assign(x + num6, y, num4 - num7);
			buffer[2 + num8].Pos.Assign(x - num6, y - num3, num4 - num7);
			buffer[5 + num8].Pos.Assign(x + num6, y - num3, num4 - num7);
			buffer[num8].Col = col;
			buffer[1 + num8].Col = col;
			buffer[2 + num8].Col = col;
			buffer[5 + num8].Col = col;
			float num9 = 0f;
			float num10 = 0f;
			float num11 = 0f;
			float num12 = 0f;
			float s;
			float c;
			nnSinCos(NNM_DEGtoA32(_dmap_water.speed_surface * 360f), out s, out c);
			float num13 = num6 * 2f / 128f * 0.5f;
			switch (i)
			{
			case 0:
				num9 = x / 270f;
				num9 -= (float)(int)num9 - _dmap_water.speed_surface;
				num10 = num9 + num13;
				num11 = 0.3f;
				num12 = num11 + num3 / 128f * 0.5f + c / 5f;
				break;
			case 1:
				num10 = x / 270f;
				num10 -= (float)(int)num10 + _dmap_water.speed_surface * 2f;
				num9 = num10 - num13 * 0.75f;
				num11 = 1f;
				num12 = num11 - num3 * 0.75f / 128f * 0.5f + s / 5f;
				break;
			default:
				num9 = 11f / 64f;
				num10 = num9 + 1f / 128f;
				num11 = 0.5f;
				num12 = num11 + 1f / 128f;
				buffer[num8].Col = AMD_RGBA8888(32, 176, 64, 112);
				buffer[1 + num8].Col = buffer[num8].Col;
				buffer[2 + num8].Col = buffer[num8].Col;
				buffer[5 + num8].Col = buffer[num8].Col;
				break;
			}
			buffer[num8].Tex.u = num9;
			buffer[num8].Tex.v = num11;
			buffer[1 + num8].Tex.u = num10;
			buffer[1 + num8].Tex.v = num11;
			buffer[2 + num8].Tex.u = num9;
			buffer[2 + num8].Tex.v = num12;
			buffer[5 + num8].Tex.u = num10;
			buffer[5 + num8].Tex.v = num12;
			buffer[3 + num8] = buffer[1 + num8];
			buffer[4 + num8] = buffer[2 + num8];
		}
		aMS_PARAM_DRAW_PRIMITIVE.format3D = 4;
		aMS_PARAM_DRAW_PRIMITIVE.type = 0;
		aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D = nNS_PRIM3D_PCT_ARRAY;
		aMS_PARAM_DRAW_PRIMITIVE.count = 18;
		aMS_PARAM_DRAW_PRIMITIVE.sortZ = 0f - num5;
		aMS_PARAM_DRAW_PRIMITIVE.texId = 0;
		aMS_PARAM_DRAW_PRIMITIVE.texlist = _dmap_water.tex_color.texlist;
		aMS_PARAM_DRAW_PRIMITIVE.uwrap = 0;
		aMS_PARAM_DRAW_PRIMITIVE.vwrap = 0;
		gmWaterSurfaceMatrixPush(4u);
		ObjDraw3DNNDrawPrimitive(aMS_PARAM_DRAW_PRIMITIVE, 4u);
		gmWaterSurfaceMatrixPop(4u);
		if (!flag)
		{
			dwaterDrawSurface(4u, drawflag);
		}
		ObjDraw3DNNSetCameraEx(g_obj.glb_camera_id, 1, 4u);
		ObjDraw3DNNUserFunc(gmWaterSurfaceTcbProcPostDrawDT, null, 0, 8u);
		GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Release(aMS_PARAM_DRAW_PRIMITIVE);
	}

