	private static void dwaterUpdate(float speed, float pos_x, float pos_y, float dy, int rot_z, float scale)
	{
		float num = 1f / 150f;
		_dmap_water.speed_surface += 0.0005f;
		if (_dmap_water.speed_surface > 1f)
		{
			_dmap_water.speed_surface -= 1f;
		}
		_dmap_water.pos_x = pos_x;
		_dmap_water.pos_y = pos_y;
		_dmap_water.pos_dy = dy;
		_dmap_water.rot_z = rot_z;
		_dmap_water.scale = scale;
		float num2 = _dmap_water.ofst_u + _dmap_water.speed_u * speed;
		num2 = ((!(num2 >= 0f)) ? (1f - (0f - num2 - floorf(0f - num2))) : (num2 - floorf(num2)));
		_dmap_water.ofst_u = num2;
		num2 = _dmap_water.ofst_v + _dmap_water.speed_v * speed;
		num2 = ((!(num2 >= 0f)) ? (1f - (0f - num2 - floorf(0f - num2))) : (num2 - floorf(num2)));
		_dmap_water.ofst_v = num2;
		float num3 = num * _dmap_water.repeat_u / 1.15f;
		num2 = _dmap_water.ofst_u + pos_x * num3;
		num2 = ((!(num2 >= 0f)) ? (1f - (0f - num2 - floorf(0f - num2))) : (num2 - floorf(num2)));
		_dmap_water.draw_u = num2;
		_dmap_water.draw_v = _dmap_water.ofst_v;
		ArrayPointer<DMAP_WATER_OBJ> arrayPointer = new ArrayPointer<DMAP_WATER_OBJ>(_dmap_water._object);
		int num4 = 0;
		while (num4 < 2)
		{
			AMS_MOTION motion = (~arrayPointer).motion;
			num2 = (~arrayPointer).frame + speed;
			float num5 = amMotionMaterialGetStartFrame(motion, 0);
			float num6 = amMotionMaterialGetEndFrame(motion, 0);
			while (num2 >= num6)
			{
				num2 = num5 + (num2 - num6);
			}
			(~arrayPointer).frame = num2;
			num4++;
			++arrayPointer;
		}
	}

