	private static void dwaterDrawReflection(uint state, uint drawflag)
	{
		amMatrixPush();
		NNS_MATRIX nNS_MATRIX = amMatrixGetCurrent();
		DMAP_WATER_OBJ dMAP_WATER_OBJ = _dmap_water._object[1];
		AMS_MOTION motion = dMAP_WATER_OBJ.motion;
		amMotionMaterialSetFrame(motion, _dmap_water._object[1].frame);
		amMotionMaterialCalc(motion);
		float num = _dmap_water.pos_x / (_dmap_water.repeat_pos_x * _dmap_water.scale);
		num = floorf(num - 0.5f) * (_dmap_water.repeat_pos_x * _dmap_water.scale);
		float y = _dmap_water.pos_y + _dmap_water.pos_dy;
		for (int i = 0; i < 2; i++)
		{
			nnMakeTranslateMatrix(nNS_MATRIX, num, y, FX_FX32_TO_F32(-1179648));
			nnScaleMatrix(nNS_MATRIX, nNS_MATRIX, _dmap_water.scale, _dmap_water.scale, 1f);
			ObjDraw3DNNMotionMaterialMotion(motion, dMAP_WATER_OBJ.texlist, drawflag, 0u, null, null, state, null, null, null, null, null, 1u);
			num += _dmap_water.repeat_pos_x * _dmap_water.scale;
		}
		amMatrixPop();
	}

	private static void dwaterDrawSurface(uint state, uint drawflag)
	{
		amMatrixPush();
