		for (int i = 0; i < 2; i++)
		{
			nnMakeTranslateMatrix(nNS_MATRIX, num, y, FX_FX32_TO_F32(917504));
			nnScaleMatrix(nNS_MATRIX, nNS_MATRIX, _dmap_water.scale, _dmap_water.scale * 2f, 1f);
			ObjDraw3DNNMotionMaterialMotion(motion, dMAP_WATER_OBJ.texlist, drawflag, 0u, null, null, state, null, null, null, null, null, 1u);
