	private static GMS_MAP_FAR_OBJ_WORK gmMapFarDataLoadObj(GMD_MAP_FAR_OBJ_INDEX obj_index, OBS_ACTION3D_NN_WORK obj_3d_work, MPP_VOID_OBS_OBJECT_WORK main_func, MPP_VOID_OBS_OBJECT_WORK out_func)
	{
		GMS_MAP_FAR_OBJ_WORK gMS_MAP_FAR_OBJ_WORK = (GMS_MAP_FAR_OBJ_WORK)OBM_OBJECT_TASK_DETAIL_INIT(12544, 5, 0, 0, () => new GMS_MAP_FAR_OBJ_WORK(), "MAP FAR OBJ");
		OBS_OBJECT_WORK obj_work = gMS_MAP_FAR_OBJ_WORK.obj_work;
		ObjObjectCopyAction3dNNModel(obj_work, obj_3d_work, gMS_MAP_FAR_OBJ_WORK.obj_3d);
		obj_work.obj_type = 8;
		obj_work.flag |= 18u;
		obj_work.move_flag |= 768u;
		obj_work.user_flag = (uint)obj_index;
		obj_work.ppFunc = main_func;
		obj_work.ppOut = out_func;
		mtTaskChangeTcbDestructor(obj_work.tcb, ObjObjectExit);
		gmMapFarDataSetObjWork(obj_work, obj_index);
		return gMS_MAP_FAR_OBJ_WORK;
	}

