	private static int gmMapFarCameraGetScrollDistance(GMS_MAP_FAR_SCROLL[] scroll_list, uint scroll_info_num)
	{
		if (scroll_list == null)
		{
			return 0;
		}
		int num = 0;
		for (uint num2 = 0u; scroll_info_num > num2; num2++)
		{
			GMS_MAP_FAR_SCROLL gMS_MAP_FAR_SCROLL = scroll_list[num2];
			num += gMS_MAP_FAR_SCROLL.width * gMS_MAP_FAR_SCROLL.loop_num;
		}
		return num;
	}

	private static float gmMapFarCameraGetPos(float player_camera_pos, GMS_MAP_FAR_SCROLL[] scroll_list, uint scroll_info_num, float scroll_speed)
	{
		float num = scroll_speed * player_camera_pos;
		float result = num;
		if (scroll_list == null)
		{
			return num;
		}
		for (uint num2 = 0u; scroll_info_num > num2; num2++)
		{
			GMS_MAP_FAR_SCROLL gMS_MAP_FAR_SCROLL = scroll_list[num2];
			if (gMS_MAP_FAR_SCROLL.loop_num != 0)
			{
				int num3 = gMS_MAP_FAR_SCROLL.width * gMS_MAP_FAR_SCROLL.loop_num;
				if (!((float)num3 <= num))
				{
					int num4 = (int)num / gMS_MAP_FAR_SCROLL.width;
					num -= (float)(num4 * gMS_MAP_FAR_SCROLL.width);
					result = (float)gMS_MAP_FAR_SCROLL.pos + num;
					break;
				}
				num -= (float)num3;
				result = gMS_MAP_FAR_SCROLL.pos + gMS_MAP_FAR_SCROLL.width;
			}
		}
		return result;
	}

	private static NNS_VECTOR gmMapFarCameraGetPos(NNS_VECTOR player_camera_pos, GMS_MAP_FAR_SCROLL[] scroll_list_x, uint scroll_info_num_x, GMS_MAP_FAR_SCROLL[] scroll_list_y, uint scroll_info_num_y)
	{
		NNS_VECTOR nNS_VECTOR = gmMapFarCameraGetPos_result;
		float x = player_camera_pos.x;
		nNS_VECTOR.x = gmMapFarCameraGetPos(x, scroll_list_x, scroll_info_num_x, gmMapFarCameraGetSpeedX());
		float y = player_camera_pos.y;
		nNS_VECTOR.y = gmMapFarCameraGetPos(y, scroll_list_y, scroll_info_num_y, gmMapFarCameraGetSpeedY());
		nNS_VECTOR.z = 160f;
		return nNS_VECTOR;
	}

	private static void gmMapFarSceneLoadObj(GMD_MAP_FAR_OBJ_INDEX obj_index, OBS_ACTION3D_NN_WORK obj_3d_work, uint mat_motion_index, AMS_AMB_HEADER mat_amb_header, uint motion_index, AMS_AMB_HEADER mtn_amb_header, MPP_VOID_OBS_OBJECT_WORK main_func, MPP_VOID_OBS_OBJECT_WORK out_func, uint command_state)
	{
		GMS_MAP_FAR_OBJ_WORK gMS_MAP_FAR_OBJ_WORK = gmMapFarDataLoadObj(obj_index, obj_3d_work, main_func, out_func);
		gMS_MAP_FAR_OBJ_WORK.obj_3d.command_state = command_state;
		if (mat_amb_header != null)
		{
			ObjAction3dNNMaterialMotionLoad(gMS_MAP_FAR_OBJ_WORK.obj_3d, 0, null, null, (int)mat_motion_index, mat_amb_header);
			if (gmMapFarGetZoneType(gmMapFarGetStageId()) == 5)
			{
				AMS_MOTION motion = gMS_MAP_FAR_OBJ_WORK.obj_3d.motion;
				motion.mmtn[motion.mmotion_id].StartFrame = 2400f;
			}
		}
		if (mtn_amb_header != null)
		{
			ObjAction3dNNMotionLoad(gMS_MAP_FAR_OBJ_WORK.obj_3d, 0, false, null, null, (int)motion_index, mtn_amb_header, 8, 8);
		}
	}

