	private static NNS_VECTOR gmMapFarZone1GetCameraPos(NNS_VECTOR player_camera_pos)
	{
		MP_HEADER mP_HEADER = gmMapFarGetMapsetMpA();
		NNS_VECTOR nNS_VECTOR = gmMapFarZone1GetCameraPos_result;
		nNS_VECTOR.Assign(player_camera_pos);
		nNS_VECTOR.y += mP_HEADER.map_h * 64;
		nNS_VECTOR = gmMapFarCameraGetPos(nNS_VECTOR, g_map_far_zone_1_scroll_x, (uint)g_map_far_zone_1_scroll_num_x, g_map_far_zone_1_scroll_y, (uint)g_map_far_zone_1_scroll_num_y);
		float z = nNS_VECTOR.z;
		nNS_VECTOR.z = 0f - nNS_VECTOR.x;
		nNS_VECTOR.y = nNS_VECTOR.y;
		nNS_VECTOR.x = z;
		g_map_far_data.pos.Assign(nNS_VECTOR);
		return nNS_VECTOR;
	}

