	private static OBS_OBJECT_WORK GmGmkWaterAreaInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		ushort water_level = (ushort)(eve_rec.left * 100 + eve_rec.top);
		ushort num = 0;
		ushort num2 = eve_rec.flag;
		ushort num3 = 0;
		while (10 > num3)
		{
			if ((num2 & 1) != 0)
			{
				num += (ushort)(num3 + 1);
			}
			num2 >>= 1;
			num3++;
		}
		if (gmGmkWaterAreaGetType(eve_rec) == 0)
		{
			if (gmGmkWaterAreaCheckRestart(pos_x, pos_y))
			{
				GmWaterSurfaceRequestChangeWaterLevel(water_level, (ushort)(num * 60), false);
			}
			eve_rec.pos_x = byte.MaxValue;
			return null;
		}
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = gmGmkWaterAreaLoadObj(eve_rec, pos_x, pos_y, type);
		gmGmkWaterAreaInit(gMS_ENEMY_3D_WORK, water_level, num);
		return (OBS_OBJECT_WORK)gMS_ENEMY_3D_WORK;
	}

	private static GMS_ENEMY_3D_WORK gmGmkWaterAreaLoadObj(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_WATER_AREA");
		gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag &= 4294967291u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[1].flag &= 4294967291u;
		return gMS_ENEMY_3D_WORK;
	}

	private static void gmGmkWaterAreaInit(GMS_ENEMY_3D_WORK gimmick_work, ushort water_level, ushort time)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gimmick_work;
		GMS_EVE_RECORD_EVENT eve_rec = gimmick_work.ene_com.eve_rec;
		uint type = gmGmkWaterAreaGetType(eve_rec);
		byte width = eve_rec.width;
		byte height = eve_rec.height;
		gmGmkWaterAreaSetRect(gimmick_work, width, height, type);
		gimmick_work.ene_com.target_obj = g_gm_main_system.ply_work[0].obj_work;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 32u;
		gmGmkWaterAreaUserWorkSetLevel(oBS_OBJECT_WORK, water_level);
		gmGmkWaterAreaUserWorkSetTime(oBS_OBJECT_WORK, time);
	}

	private static bool gmGmkWaterAreaCheckRestart(int pos_x, int pos_y)
	{
		int num = MTM_MATH_ABS(g_gm_main_system.resume_pos_x - pos_x);
		int num2 = MTM_MATH_ABS(g_gm_main_system.resume_pos_y - pos_y);
		if (num2 > 524288 || num > 524288)
		{
			return false;
		}
		return true;
	}

	private static uint gmGmkWaterAreaGetType(GMS_EVE_RECORD_EVENT eve_rec)
	{
		uint result = uint.MaxValue;
		switch (eve_rec.id)
		{
		case 106:
			result = 0u;
			break;
		case 102:
			result = 1u;
			break;
		case 103:
			result = 2u;
			break;
		case 104:
			result = 3u;
			break;
		case 105:
			result = 4u;
			break;
		}
		return result;
	}

	private static void gmGmkWaterAreaRequestChangeWatarLevel(OBS_OBJECT_WORK obj_work)
	{
		ushort water_level = gmGmkWaterAreaUserWorkGetLevel(obj_work);
		ushort num = gmGmkWaterAreaUserWorkGetTime(obj_work);
		GmWaterSurfaceRequestChangeWaterLevel(water_level, (ushort)(num * 60), false);
	}

	private static void gmGmkWaterAreaSetRect(GMS_ENEMY_3D_WORK gimmick_work, byte width, byte height, uint type)
	{
		OBS_RECT_WORK oBS_RECT_WORK = gimmick_work.ene_com.rect_work[2];
		if (width < 34)
		{
			width = 34;
		}
		if (height < 34)
		{
			height = 34;
		}
		ObjRectWorkZSet(oBS_RECT_WORK, (short)(-width / 2), (short)(-height / 2), -500, (short)(width / 2), (short)(height / 2), 500);
		ObjRectAtkSet(oBS_RECT_WORK, 0, 0);
		oBS_RECT_WORK.ppHit = null;
		ObjRectDefSet(oBS_RECT_WORK, 0, 0);
		switch (type)
		{
		case 1u:
		case 2u:
		case 3u:
		case 4u:
			oBS_RECT_WORK.flag |= 1024u;
			oBS_RECT_WORK.ppDef = gmGmkWaterAreaDefFuncDelay;
			break;
		case 0u:
			break;
		}
	}

	private static bool gmGmkWaterAreaCheckDir(OBS_OBJECT_WORK gimmick_obj_work, OBS_OBJECT_WORK player_obj_work, uint type)
	{
		bool result = false;
		switch (type)
		{
		case 1u:
			if (player_obj_work.pos.x < gimmick_obj_work.pos.x)
			{
				result = true;
			}
			break;
		case 2u:
			if (gimmick_obj_work.pos.x < player_obj_work.pos.x)
			{
				result = true;
			}
			break;
		case 3u:
			if (player_obj_work.pos.y < gimmick_obj_work.pos.y)
			{
				result = true;
			}
			break;
		case 4u:
			if (gimmick_obj_work.pos.y < player_obj_work.pos.y)
			{
				result = true;
			}
			break;
		case 0u:
			result = true;
			break;
		}
		return result;
	}

	private static void gmGmkWaterAreaDefFuncDelay(OBS_RECT_WORK own_rect, OBS_RECT_WORK target_rect)
	{
		OBS_OBJECT_WORK parent_obj = own_rect.parent_obj;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)parent_obj;
		OBS_OBJECT_WORK parent_obj2 = target_rect.parent_obj;
		if (gmGmkWaterAreaModeCheckWait(parent_obj))
		{
			GMS_EVE_RECORD_EVENT eve_rec = gMS_ENEMY_3D_WORK.ene_com.eve_rec;
			uint type = gmGmkWaterAreaGetType(eve_rec);
			if (gmGmkWaterAreaCheckDir(parent_obj, parent_obj2, type))
			{
				gmGmkWaterAreaModeChangeLady(parent_obj);
			}
		}
	}

	private static bool gmGmkWaterAreaModeCheckWait(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.ppFunc != null)
		{
			return false;
		}
		return true;
	}

	private static void gmGmkWaterAreaModeChangeWait(OBS_OBJECT_WORK obj_work)
	{
		obj_work.flag &= 4294967279u;
		obj_work.ppFunc = null;
	}

	private static void gmGmkWaterAreaModeChangeLady(OBS_OBJECT_WORK obj_work)
	{
		obj_work.flag &= 4294967279u;
		obj_work.ppFunc = gmGmkWaterAreaMainLady;
	}

	private static void gmGmkWaterAreaModeChangeActive(OBS_OBJECT_WORK obj_work)
	{
		gmGmkWaterAreaRequestChangeWatarLevel(obj_work);
		obj_work.flag |= 16u;
		obj_work.ppFunc = gmGmkWaterAreaMainActive;
		gmGmkWaterAreaUserTimerSetCounter(obj_work, 0);
		gmGmkWaterAreaRequestChangeWatarLevel(obj_work);
		GmWaterSurfaceSetFlagDraw(true);
	}

	private static void gmGmkWaterAreaMainLady(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		if ((oBS_RECT_WORK.flag & 0x20000) == 0)
		{
			GMS_EVE_RECORD_EVENT eve_rec = gMS_ENEMY_3D_WORK.ene_com.eve_rec;
			uint type = gmGmkWaterAreaGetType(eve_rec);
			OBS_OBJECT_WORK target_obj = gMS_ENEMY_3D_WORK.ene_com.target_obj;
			if (gmGmkWaterAreaCheckDir(obj_work, target_obj, type))
			{
				gmGmkWaterAreaModeChangeWait(obj_work);
			}
			else
			{
				gmGmkWaterAreaModeChangeActive(obj_work);
			}
		}
	}

	private static void gmGmkWaterAreaMainActive(OBS_OBJECT_WORK obj_work)
	{
		int num = gmGmkWaterAreaUserWorkGetTime(obj_work);
		int num2 = gmGmkWaterAreaUserTimerGetCounter(obj_work);
		gmGmkWaterAreaUserTimerAddCounter(obj_work, 1);
		if (num2 >= num * 60)
		{
			gmGmkWaterAreaModeChangeWait(obj_work);
		}
	}

	private static void gmGmkWaterAreaUserWorkSetLevel(OBS_OBJECT_WORK obj_work, ushort level)
	{
