	private static OBS_OBJECT_WORK GmGmkSpipeInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_COM_WORK(), "GMK_S_PIPE");
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.move_flag |= 8480u;
		oBS_OBJECT_WORK.pos.z = -131072;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_COM_WORK.rect_work[2];
		ObjRectGroupSet(oBS_RECT_WORK, 1, 1);
		ObjRectAtkSet(oBS_RECT_WORK, 0, 1);
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		ObjRectSet(oBS_RECT_WORK.rect, (short)(eve_rec.left * 2), (short)(eve_rec.top * 2), (short)((ushort)(eve_rec.width * 2) + (short)(eve_rec.left * 2)), (short)((ushort)(eve_rec.height * 2) + (short)(eve_rec.top * 2)));
		oBS_RECT_WORK.ppDef = gmGmkSpipeDefFunc;
		oBS_RECT_WORK.parent_obj = oBS_OBJECT_WORK;
		oBS_RECT_WORK.flag |= 192u;
		return oBS_OBJECT_WORK;
	}

	private static void gmGmkSpipeDefFunc(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_ENEMY_COM_WORK != null && gMS_PLAYER_WORK != null && gMS_PLAYER_WORK.obj_work.obj_type == 1)
		{
			if (gMS_PLAYER_WORK.seq_state != 37)
			{
				GmPlySeqInitSpipe(gMS_PLAYER_WORK);
			}
			gMS_PLAYER_WORK.gmk_flag |= 65536u;
		}
	}

