	private static GMS_ENEMY_3D_WORK gmGmkDrainTankLoadObjNoModel(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, int type)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = null;
		if (type == 1)
		{
			GMS_GMK_DRAIN_TANK_OUT_WORK gMS_GMK_DRAIN_TANK_OUT_WORK = (GMS_GMK_DRAIN_TANK_OUT_WORK)GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_DRAIN_TANK_OUT_WORK(), "GMK_DRAIN_TANK");
			gMS_GMK_DRAIN_TANK_OUT_WORK.base_pos_x = pos_x + 262144;
			gMS_GMK_DRAIN_TANK_OUT_WORK.base_pos_y = pos_y;
			gMS_ENEMY_3D_WORK = gMS_GMK_DRAIN_TANK_OUT_WORK.enemy_work;
		}
		else
		{
			gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_DRAIN_TANK");
		}
		gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag &= 4294967291u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[1].flag &= 4294967291u;
		return gMS_ENEMY_3D_WORK;
	}

	private static GMS_ENEMY_3D_WORK gmGmkDrainTankLoadObj(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, int type, uint model_id)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = gmGmkDrainTankLoadObjNoModel(eve_rec, pos_x, pos_y, type);
		OBS_OBJECT_WORK obj_work = gMS_ENEMY_3D_WORK.ene_com.obj_work;
		ObjObjectCopyAction3dNNModel(obj_work, g_gm_gmk_drain_tank_obj_3d_list[model_id], gMS_ENEMY_3D_WORK.obj_3d);
		if (type == 2)
		{
			int index = 0;
			object pData = ObjDataGet(925).pData;
			ObjAction3dNNMaterialMotionLoad(gMS_ENEMY_3D_WORK.obj_3d, 0, null, null, index, (AMS_AMB_HEADER)pData);
		}
		return gMS_ENEMY_3D_WORK;
	}

