			GmWaterSurfaceDrawNoWaterField(num2, 0f - FX_FX32_TO_F32(gMS_GMK_DRAIN_TANK_OUT_WORK.base_pos_y) + (float)GMD_GMK_DRAIN_TANK_DRAW_WATER_HEIGHT, FX_FX32_TO_F32(gMS_GMK_DRAIN_TANK_OUT_WORK.base_pos_x) + (float)GMD_GMK_DRAIN_TANK_DRAW_WATER_WIDTH, num4);
			GmWaterSurfaceDrawNoWaterField(FX_FX32_TO_F32(gMS_GMK_DRAIN_TANK_OUT_WORK.base_pos_x) - (float)GMD_GMK_DRAIN_TANK_DRAW_WATER_WIDTH, num, FX_FX32_TO_F32(gMS_GMK_DRAIN_TANK_OUT_WORK.base_pos_x) + (float)GMD_GMK_DRAIN_TANK_DRAW_WATER_WIDTH, num - GMD_GMK_DRAIN_TANK_DRAW_WATER_HEIGHT);
			GmWaterSurfaceDrawNoWaterField(num3 - GMD_GMK_DRAIN_TANK_DRAW_WATER_WIDTH, 0f - FX_FX32_TO_F32(gMS_GMK_DRAIN_TANK_OUT_WORK.base_pos_y) + (float)GMD_GMK_DRAIN_TANK_DRAW_WATER_HEIGHT, num3, num);
			GmWaterSurfaceDrawNoWaterField(num5, num4, num5 + GMD_GMK_DRAIN_TANK_DRAW_WATER_WIDTH, num);
		}
		ObjDraw3DNNSetCameraEx(g_obj.glb_camera_id, 1, 8u);
