	private static bool gmGmkDrainTankInCheckDeleteTask(OBS_OBJECT_WORK obj_work, int cmp_x, int cmp_y)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		OBS_OBJECT_WORK obj_work2 = gMS_PLAYER_WORK.obj_work;
		int num = MTM_MATH_ABS(obj_work.pos.x - obj_work2.pos.x);
		int num2 = MTM_MATH_ABS(obj_work.pos.y - obj_work2.pos.y);
		if (num > cmp_x || num2 > cmp_y)
		{
			return true;
		}
		return false;
	}

	private static void gmGmkDrainTankInRequestDeleteTask(OBS_OBJECT_WORK obj_work)
	{
		obj_work.flag |= 4u;
	}

	private static void gmGmkDrainTankInMainReady(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
		{
			return;
		}
		if (gmGmkDrainTankInCheckDeleteTask(obj_work, 1843200, 1228800))
		{
			gmGmkDrainTankInRequestDeleteTask(obj_work);
			return;
		}
		OBS_OBJECT_WORK obj_work2 = gMS_PLAYER_WORK.obj_work;
		if (obj_work.pos.x + 65536 < obj_work2.pos.x)
		{
			obj_work.pos.y += 32768;
			obj_work.ppFunc = gmGmkDrainTankInMainWait;
			obj_work.move_flag |= 128u;
		}
	}

	private static void gmGmkDrainTankInMainWait(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((gMS_PLAYER_WORK.player_flag & 0x400) == 0 && gmGmkDrainTankInCheckDeleteTask(obj_work, 1843200, 1228800))
		{
			gmGmkDrainTankInRequestDeleteTask(obj_work);
		}
	}

	private static bool gmGmkDrainTankOutCheckDeleteTask(OBS_OBJECT_WORK obj_work, int cmp_x, int cmp_y)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		OBS_OBJECT_WORK obj_work2 = gMS_PLAYER_WORK.obj_work;
		GMS_GMK_DRAIN_TANK_OUT_WORK gMS_GMK_DRAIN_TANK_OUT_WORK = (GMS_GMK_DRAIN_TANK_OUT_WORK)obj_work;
		int num = MTM_MATH_ABS(gMS_GMK_DRAIN_TANK_OUT_WORK.base_pos_x - obj_work2.pos.x);
		int num2 = MTM_MATH_ABS(gMS_GMK_DRAIN_TANK_OUT_WORK.base_pos_y - obj_work2.pos.y);
		if (num > cmp_x || num2 > cmp_y)
		{
			return true;
		}
		return false;
	}

	private static void gmGmkDrainTankOutRequestDeleteTask(OBS_OBJECT_WORK obj_work)
	{
