	private static void gmGmkDrainTankOutChangeModeSplash(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_GMK_DRAIN_TANK_OUT_WORK gMS_GMK_DRAIN_TANK_OUT_WORK = (GMS_GMK_DRAIN_TANK_OUT_WORK)gMS_ENEMY_3D_WORK;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		OBS_OBJECT_WORK obj_work2 = gMS_PLAYER_WORK.obj_work;
		if (gMS_GMK_DRAIN_TANK_OUT_WORK.flag_dir_left)
		{
			obj_work2.spd.x = -65536;
		}
		else
		{
			obj_work2.spd.x = 65536;
		}
		obj_work2.pos.y = obj_work.pos.y;
		obj_work2.move_flag |= 256u;
		GmPlayerBreathingSet(gMS_PLAYER_WORK);
		obj_work.move_flag |= 256u;
		g_gm_main_system.game_flag |= 8192u;
		GmEventMgrLocalEventBirth(305, obj_work.pos.x, obj_work.pos.y + 65536, gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag, gMS_ENEMY_3D_WORK.ene_com.eve_rec.left, gMS_ENEMY_3D_WORK.ene_com.eve_rec.top, gMS_ENEMY_3D_WORK.ene_com.eve_rec.width, gMS_ENEMY_3D_WORK.ene_com.eve_rec.height, 0);
		GmSoundPlaySE("Fluid2");
		GMM_PAD_VIB_SMALL();
		GmPlayerCameraOffsetSet(gMS_PLAYER_WORK, 0, 0);
		GmCameraAllowReset();
		obj_work.ppFunc = gmGmkDrainTankOutMainSplash;
	}

