	}

	private static void gmGmkDrainTankOutMainReady(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		OBS_OBJECT_WORK obj_work2 = gMS_PLAYER_WORK.obj_work;
		GMS_GMK_DRAIN_TANK_OUT_WORK gMS_GMK_DRAIN_TANK_OUT_WORK = (GMS_GMK_DRAIN_TANK_OUT_WORK)obj_work;
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
		{
			gmGmkDrainTankOutUpdateDie(obj_work);
			int num = (int)FX_FX32_TO_F32(gMS_GMK_DRAIN_TANK_OUT_WORK.base_pos_x);
			num /= 64;
			num -= 3;
			num *= 262144;
			if (obj_work2.pos.x < num)
			{
				g_gm_main_system.game_flag |= 8192u;
			}
			obj_work.spd.x = 0;
			obj_work.spd.y = 0;
		}
		else if (gmGmkDrainTankOutCheckDeleteTask(obj_work, 1843200, 1228800))
		{
			gmGmkDrainTankOutRequestDeleteTask(obj_work);
		}
		else
		{
			int num2 = gmGmkDrainTankGameSystemGetWaterLevel() * 4096;
			if (num2 + 196608 < obj_work2.pos.y)
			{
				gmGmkDrainTankOutChangeModeWait(obj_work);
				gMS_GMK_DRAIN_TANK_OUT_WORK.flag_dir_left = gmGmkDrainTankOutCheckDirLeft(obj_work, obj_work2);
				int x = obj_work2.spd.x;
				GmPlySeqInitDrainTank(gMS_PLAYER_WORK);
				gMS_GMK_DRAIN_TANK_OUT_WORK.player_offset_x += x * 5;
				gmGmkDrainTankOutUpdateCameraOffset(gMS_PLAYER_WORK, gMS_GMK_DRAIN_TANK_OUT_WORK);
				GmCameraAllowSet(10f, 10f, 10f);
			}
		}
	}

	private static void gmGmkDrainTankOutMainWait(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
		{
			gmGmkDrainTankOutUpdateDie(obj_work);
			obj_work.spd.x = 0;
			obj_work.spd.y = 0;
			return;
		}
		if (gmGmkDrainTankOutCheckDeleteTask(obj_work, 1843200, 1228800))
		{
			gmGmkDrainTankOutRequestDeleteTask(obj_work);
			return;
		}
		OBS_OBJECT_WORK obj_work2 = gMS_PLAYER_WORK.obj_work;
		if (gMS_PLAYER_WORK.seq_state == 22)
		{
			gmGmkDrainTankOutChangeModeDamage(obj_work);
			return;
		}
		if ((obj_work.move_flag & 1) == 0)
		{
			gmGmkDrainTankOutChangeModeSplash(obj_work);
			return;
		}
		GMS_GMK_DRAIN_TANK_OUT_WORK gMS_GMK_DRAIN_TANK_OUT_WORK = (GMS_GMK_DRAIN_TANK_OUT_WORK)obj_work;
		int num = GmPlayerKeyGetGimmickRotZ(gMS_PLAYER_WORK);
		if (MTM_MATH_ABS(num) > 8192)
		{
			gMS_GMK_DRAIN_TANK_OUT_WORK.counter_roll_key++;
		}
		else
		{
			gMS_GMK_DRAIN_TANK_OUT_WORK.counter_roll_key = 0;
		}
		if (gMS_GMK_DRAIN_TANK_OUT_WORK.counter_roll_key >= 0)
		{
			gmGmkDrainTankOutUpdateCameraRoll(gMS_GMK_DRAIN_TANK_OUT_WORK, num);
			if (19 == gMS_GMK_DRAIN_TANK_OUT_WORK.counter_roll_key % 20 && MTM_MATH_ABS(gMS_GMK_DRAIN_TANK_OUT_WORK.camera_roll) < GMD_GMK_DRAIN_TANK_ROLL_ANGLE_MAX)
			{
				GmSoundPlaySE("Fluid1");
			}
		}
		if (gmGmkDrainTankOutCheckKeyDir(obj_work, gMS_GMK_DRAIN_TANK_OUT_WORK.camera_roll))
		{
			int x = gMS_GMK_DRAIN_TANK_OUT_WORK.camera_roll >> 3;
			obj_work.spd.x = x;
			float a = FX_FX32_TO_F32(gMS_GMK_DRAIN_TANK_OUT_WORK.camera_roll >> 4);
			a = MTM_MATH_ABS(a);
			GmWaterSurfaceRequestAddWatarLevel(MTM_MATH_ABS(a), 0, true);
		}
		gmGmkDrainTankOutAdjustPlayerOffsetBuoyancy(gMS_GMK_DRAIN_TANK_OUT_WORK);
		gmGmkDrainTankOutAdjustPlayerOffsetWave(gMS_GMK_DRAIN_TANK_OUT_WORK, obj_work2);
		gmGmkDrainTankOutApplyPlayerOffset(obj_work2, gMS_GMK_DRAIN_TANK_OUT_WORK);
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
		oBS_CAMERA.roll = gMS_GMK_DRAIN_TANK_OUT_WORK.camera_roll;
		gmGmkDrainTankOutUpdateCameraOffset(gMS_PLAYER_WORK, gMS_GMK_DRAIN_TANK_OUT_WORK);
	}

	private static void gmGmkDrainTankOutMainDamage(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
		{
			gmGmkDrainTankOutUpdateDie(obj_work);
			obj_work.spd.x = 0;
			obj_work.spd.y = 0;
			return;
		}
		if (gmGmkDrainTankOutCheckDeleteTask(obj_work, 1843200, 1228800))
		{
			gmGmkDrainTankOutRequestDeleteTask(obj_work);
			return;
		}
		GMS_GMK_DRAIN_TANK_OUT_WORK gMS_GMK_DRAIN_TANK_OUT_WORK = (GMS_GMK_DRAIN_TANK_OUT_WORK)obj_work;
		OBS_OBJECT_WORK obj_work2 = gMS_PLAYER_WORK.obj_work;
		gmGmkDrainTankOutUpdateCameraRollDamage(gMS_GMK_DRAIN_TANK_OUT_WORK);
		int num = (GMD_GMK_DRAIN_TANK_ROLL_ANGLE_MAX - MTM_MATH_ABS(gMS_GMK_DRAIN_TANK_OUT_WORK.camera_roll)) * 4;
		int num2 = num >> 3;
		if (gMS_GMK_DRAIN_TANK_OUT_WORK.flag_dir_left)
		{
			obj_work.spd.x = num2;
		}
		else
		{
			obj_work.spd.x = -num2;
		}
		float num3 = FX_FX32_TO_F32(num >> 4);
		GmWaterSurfaceRequestAddWatarLevel(0f - num3, 0, true);
		obj_work.user_timer++;
		if ((obj_work2.move_flag & 1) != 0)
		{
			obj_work.user_timer = 0;
			gmGmkDrainTankOutChangeModeWait(obj_work);
			GmPlySeqInitDrainTank(gMS_PLAYER_WORK);
		}
		else
		{
			OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
			oBS_CAMERA.roll = gMS_GMK_DRAIN_TANK_OUT_WORK.camera_roll;
			gmGmkDrainTankOutUpdateCameraOffset(gMS_PLAYER_WORK, gMS_GMK_DRAIN_TANK_OUT_WORK);
			gmGmkDrainTankOutSinkRing();
		}
	}

