	private static void gmGmkDrainTankOutUpdateDie(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_DRAIN_TANK_OUT_WORK gMS_GMK_DRAIN_TANK_OUT_WORK = (GMS_GMK_DRAIN_TANK_OUT_WORK)obj_work;
		gmGmkDrainTankOutUpdateCameraRollDie(gMS_GMK_DRAIN_TANK_OUT_WORK);
