	private static bool gmGmkDrainTankOutCheckDirLeft(OBS_OBJECT_WORK gimmick_obj_work, OBS_OBJECT_WORK player_obj_work)
	{
		if (player_obj_work.pos.x < gimmick_obj_work.pos.x)
		{
			return false;
		}
		return true;
	}

	private static void gmGmkDrainTankOutAdjustPlayerOffsetBuoyancy(GMS_GMK_DRAIN_TANK_OUT_WORK out_work)
	{
		int num = gmGmkDrainTankGameSystemGetWaterLevel() * 4096 + 131072;
		if (num > out_work.base_pos_y)
		{
			num = out_work.base_pos_y;
		}
		int num2 = num - (out_work.base_pos_y + out_work.player_offset_y);
		if (MTM_MATH_ABS(num2) > 2048)
		{
			num2 = ((num2 >= 0) ? 2048 : (-2048));
		}
		out_work.player_offset_y += num2;
	}

	private static void gmGmkDrainTankOutAdjustPlayerOffsetWave(GMS_GMK_DRAIN_TANK_OUT_WORK out_work, OBS_OBJECT_WORK player_obj_work)
	{
		int num = out_work.camera_roll >> 2;
		if ((player_obj_work.move_flag & 4) != 0)
		{
			if ((player_obj_work.disp_flag & 1) != 0)
			{
				out_work.player_offset_x += FX_F32_TO_FX32(0.4f);
			}
			else
			{
				out_work.player_offset_x -= FX_F32_TO_FX32(0.4f);
			}
			return;
		}
		if (out_work.camera_roll < 0)
		{
			player_obj_work.disp_flag |= 1u;
		}
		else if (out_work.camera_roll > 0)
		{
			player_obj_work.disp_flag &= 4294967294u;
		}
		out_work.player_offset_x += num;
	}

	private static void gmGmkDrainTankOutApplyPlayerOffset(OBS_OBJECT_WORK player_obj_work, GMS_GMK_DRAIN_TANK_OUT_WORK out_work)
	{
		int num = out_work.base_pos_x + out_work.player_offset_x;
		int num2 = out_work.base_pos_y + out_work.player_offset_y;
		player_obj_work.spd.x = num - player_obj_work.pos.x;
		player_obj_work.spd.y = num2 - player_obj_work.pos.y;
	}

	private static void gmGmkDrainTankOutUpdateCameraRoll(GMS_GMK_DRAIN_TANK_OUT_WORK out_work, int rot_z)
	{
		if (rot_z < -8192)
		{
			if (out_work.camera_roll <= -GMD_GMK_DRAIN_TANK_ROLL_ANGLE_MAX)
			{
				out_work.camera_roll = -GMD_GMK_DRAIN_TANK_ROLL_ANGLE_MAX;
			}
			else
			{
				out_work.camera_roll -= GMD_GMK_DRAIN_TANK_ROLL_ANGLE_SPEED;
			}
		}
		else if (rot_z > 8192)
		{
			if (out_work.camera_roll >= GMD_GMK_DRAIN_TANK_ROLL_ANGLE_MAX)
			{
				out_work.camera_roll = GMD_GMK_DRAIN_TANK_ROLL_ANGLE_MAX;
			}
			else
			{
				out_work.camera_roll += GMD_GMK_DRAIN_TANK_ROLL_ANGLE_SPEED;
			}
		}
	}

	private static void gmGmkDrainTankOutUpdateCameraRollDamage(GMS_GMK_DRAIN_TANK_OUT_WORK out_work)
	{
		int num = GMD_GMK_DRAIN_TANK_ROLL_ANGLE_SPEED * 4;
		if (out_work.flag_dir_left)
		{
			out_work.camera_roll += num;
			if (out_work.camera_roll < -GMD_GMK_DRAIN_TANK_ROLL_ANGLE_MAX)
			{
				out_work.camera_roll = -GMD_GMK_DRAIN_TANK_ROLL_ANGLE_MAX;
			}
		}
		else
		{
			out_work.camera_roll -= num;
			if (out_work.camera_roll > GMD_GMK_DRAIN_TANK_ROLL_ANGLE_MAX)
			{
				out_work.camera_roll = GMD_GMK_DRAIN_TANK_ROLL_ANGLE_MAX;
			}
		}
	}

	private static void gmGmkDrainTankOutUpdateCameraRollDie(GMS_GMK_DRAIN_TANK_OUT_WORK out_work)
	{
		out_work.camera_roll -= out_work.camera_roll / 5;
	}

	private static void gmGmkDrainTankOutUpdateCameraOffset(GMS_PLAYER_WORK player_work, GMS_GMK_DRAIN_TANK_OUT_WORK out_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)player_work;
		float num = FX_FX32_TO_F32(out_work.base_pos_x - 737280 - oBS_OBJECT_WORK.pos.x);
		GmPlayerCameraOffsetSet(player_work, (short)num, 0);
	}

	private static bool gmGmkDrainTankOutCheckKeyDir(OBS_OBJECT_WORK gimmick_obj_work, int camera_roll)
	{
		GMS_GMK_DRAIN_TANK_OUT_WORK gMS_GMK_DRAIN_TANK_OUT_WORK = (GMS_GMK_DRAIN_TANK_OUT_WORK)gimmick_obj_work;
		if (camera_roll < 0 && gMS_GMK_DRAIN_TANK_OUT_WORK.flag_dir_left)
		{
			return true;
		}
		if (camera_roll > 0 && !gMS_GMK_DRAIN_TANK_OUT_WORK.flag_dir_left)
		{
			return true;
		}
		return false;
	}

	private static void gmGmkDrainTankOutSinkRing()
	{
		GMS_RING_SYS_WORK gMS_RING_SYS_WORK = GmRingGetWork();
		for (GMS_RING_WORK gMS_RING_WORK = gMS_RING_SYS_WORK.damage_ring_list_start; gMS_RING_WORK != null; gMS_RING_WORK = gMS_RING_WORK.post_ring)
		{
			gMS_RING_WORK.spd_y = 4096;
			gMS_RING_WORK.spd_x /= 2;
		}
	}

	private static void gmGmkDrainTankSplashMainFunc(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_timer--;
		if (obj_work.user_timer > 0)
		{
			float alpha = (float)obj_work.user_timer / 60f;
			obj_work.obj_3d.draw_state.alpha.alpha = alpha;
		}
		else
		{
			obj_work.disp_flag |= 16u;
			obj_work.ppFunc = null;
		}
	}

	private static void gmGmkDrainTankSplashEffectMain(OBS_OBJECT_WORK obj_work)
	{
		obj_work.dir.z += 384;
	}

	private static OBS_OBJECT_WORK GmGmkCannonInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		GMS_GMK_CANNON_WORK gMS_GMK_CANNON_WORK = (GMS_GMK_CANNON_WORK)GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_CANNON_WORK(), "Gmk_Cannon");
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gMS_GMK_CANNON_WORK;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)gMS_GMK_CANNON_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_cannon_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		oBS_OBJECT_WORK.pos.z = 131072;
		oBS_OBJECT_WORK.pos.y -= 18432;
		oBS_OBJECT_WORK.dir.y = 32768;
		oBS_OBJECT_WORK.move_flag |= 256u;
		if (eve_rec.width != 0)
		{
			gMS_GMK_CANNON_WORK.cannon_power = eve_rec.width;
		}
		else
		{
			gMS_GMK_CANNON_WORK.cannon_power = 61440;
		}
		gmGmkCannon_CreateParts(gMS_GMK_CANNON_WORK);
		gmGmkCannonStart(oBS_OBJECT_WORK);
		return oBS_OBJECT_WORK;
	}

	private static void gmGmkCannonFieldColOn(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_CANNON_WORK gMS_GMK_CANNON_WORK = (GMS_GMK_CANNON_WORK)obj_work;
		gMS_GMK_CANNON_WORK.gmk_work.ene_com.col_work.obj_col.obj = obj_work;
		gMS_GMK_CANNON_WORK.gmk_work.ene_com.col_work.obj_col.diff_data = g_gm_default_col;
		gMS_GMK_CANNON_WORK.gmk_work.ene_com.col_work.obj_col.width = 24;
		gMS_GMK_CANNON_WORK.gmk_work.ene_com.col_work.obj_col.height = 56;
		gMS_GMK_CANNON_WORK.gmk_work.ene_com.col_work.obj_col.ofst_x = -12;
		gMS_GMK_CANNON_WORK.gmk_work.ene_com.col_work.obj_col.ofst_y = -30;
		gMS_GMK_CANNON_WORK.gmk_work.ene_com.col_work.obj_col.flag |= 134217824u;
	}

	private static void gmGmkCannonFieldColOff(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_CANNON_WORK gMS_GMK_CANNON_WORK = (GMS_GMK_CANNON_WORK)obj_work;
		gMS_GMK_CANNON_WORK.gmk_work.ene_com.col_work.obj_col.obj = null;
	}

	private static void gmGmkCannon_CannonTurn(GMS_GMK_CANNON_WORK pwork)
	{
		if (pwork.angle_set > pwork.angle_now)
		{
			pwork.angle_now += 342;
			if (pwork.angle_now > pwork.angle_set)
			{
				pwork.angle_now = pwork.angle_set;
			}
		}
		else
		{
			pwork.angle_now -= 342;
			if (pwork.angle_now < pwork.angle_set)
			{
				pwork.angle_now = pwork.angle_set;
			}
		}
	}

	private static void gmGmkCannonStart(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_CANNON_WORK gMS_GMK_CANNON_WORK = (GMS_GMK_CANNON_WORK)obj_work;
		gmGmkCannonFieldColOn(obj_work);
		gMS_GMK_CANNON_WORK.gmk_work.ene_com.rect_work[0].flag &= 4294967291u;
		gMS_GMK_CANNON_WORK.gmk_work.ene_com.rect_work[1].flag &= 4294967291u;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_GMK_CANNON_WORK.gmk_work.ene_com.rect_work[2];
		oBS_RECT_WORK.ppDef = gmGmkCannonHit;
		oBS_RECT_WORK.ppHit = null;
		ObjRectAtkSet(oBS_RECT_WORK, 0, 0);
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		ObjRectWorkSet(oBS_RECT_WORK, -12, -38, 12, -6);
		obj_work.flag &= 4294967293u;
		gMS_GMK_CANNON_WORK.ply_work = null;
		gMS_GMK_CANNON_WORK.angle_set = 0;
		gMS_GMK_CANNON_WORK.angle_now = 0;
		gMS_GMK_CANNON_WORK.gmk_work.ene_com.enemy_flag &= 4294934527u;
		obj_work.ppFunc = gmGmkCannonStay;
	}

	private static void gmGmkCannonStay(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_CANNON_WORK gMS_GMK_CANNON_WORK = (GMS_GMK_CANNON_WORK)obj_work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (gMS_GMK_CANNON_WORK.gmk_work.ene_com.col_work.obj_col.obj != null)
		{
			if (gMS_PLAYER_WORK.act_state == 31)
			{
				gmGmkCannonFieldColOff(obj_work);
			}
		}
		else if (gMS_PLAYER_WORK.act_state != 31)
		{
			gmGmkCannonFieldColOn(obj_work);
		}
		if (gMS_GMK_CANNON_WORK.ply_work != null)
		{
			OBS_RECT_WORK oBS_RECT_WORK = gMS_GMK_CANNON_WORK.gmk_work.ene_com.rect_work[2];
			oBS_RECT_WORK.flag &= 4294967291u;
			if (gMS_PLAYER_WORK.seq_state != 41)
			{
				gmGmkCannonStart(obj_work);
			}
			else if (obj_work.pos.y <= gMS_GMK_CANNON_WORK.ply_work.obj_work.pos.y)
			{
				obj_work.ppFunc = gmGmkCannonReady;
			}
		}
	}

	private static short gmGmkCannon_GetAngle(ushort key)
	{
		if ((key & 8) != 0)
		{
			return 2730;
		}
		if ((key & 4) != 0)
		{
			return -2730;
		}
		return 0;
	}

	private static void gmGmkCannonReady(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_CANNON_WORK gMS_GMK_CANNON_WORK = (GMS_GMK_CANNON_WORK)obj_work;
		short angle_set = gMS_GMK_CANNON_WORK.angle_set;
		short angle_now = gMS_GMK_CANNON_WORK.angle_now;
		if (gMS_GMK_CANNON_WORK.angle_set == gMS_GMK_CANNON_WORK.angle_now)
		{
			if ((g_gs_main_sys_info.game_flag & 1) == 0)
			{
				int num = (int)(_am_iphone_accel_data.sensor.x * 16384f) * 3;
				if (num > 32768)
				{
					num = 32768;
				}
				else if (num < -32768)
				{
					num = -32768;
				}
				num /= 2;
				num = ((num >= gMS_GMK_CANNON_WORK.angle_now + 2730) ? (gMS_GMK_CANNON_WORK.angle_now + 2730) : ((gMS_GMK_CANNON_WORK.angle_now == 13650 && num >= 16380) ? 16380 : ((num <= gMS_GMK_CANNON_WORK.angle_now - 2730) ? (gMS_GMK_CANNON_WORK.angle_now - 2730) : ((gMS_GMK_CANNON_WORK.angle_now != -13650 || num > -16380) ? gMS_GMK_CANNON_WORK.angle_now : (-16380)))));
				gMS_GMK_CANNON_WORK.angle_set = (short)num;
			}
			else
			{
				gMS_GMK_CANNON_WORK.angle_set += gmGmkCannon_GetAngle(gMS_GMK_CANNON_WORK.ply_work.key_on);
				if (gMS_GMK_CANNON_WORK.angle_set > 16380 && (ushort)gMS_GMK_CANNON_WORK.angle_set < 49156)
				{
					gMS_GMK_CANNON_WORK.angle_set = 16380;
				}
				if (gMS_GMK_CANNON_WORK.angle_set < -16380 && (ushort)gMS_GMK_CANNON_WORK.angle_set > 16380)
				{
					gMS_GMK_CANNON_WORK.angle_set = -16380;
				}
			}
			if (angle_set != gMS_GMK_CANNON_WORK.angle_set)
			{
				GmSoundPlaySE("Cannon1");
			}
		}
		if (gMS_GMK_CANNON_WORK.angle_set != gMS_GMK_CANNON_WORK.angle_now)
		{
			gmGmkCannon_CannonTurn(gMS_GMK_CANNON_WORK);
			obj_work.dir.z = (ushort)gMS_GMK_CANNON_WORK.angle_now;
		}
		if (gMS_GMK_CANNON_WORK.angle_set == gMS_GMK_CANNON_WORK.angle_now && angle_now == gMS_GMK_CANNON_WORK.angle_now && GmPlayerKeyCheckJumpKeyPush(gMS_GMK_CANNON_WORK.ply_work))
		{
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctCmnEsCreate(gMS_GMK_CANNON_WORK.ply_work.obj_work, 20);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.dir.z = obj_work.dir.z;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.x += mtMathSin(obj_work.dir.z) * 32;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.y -= mtMathCos(obj_work.dir.z) * 32;
			GmPlySeqInitCannonShoot(gMS_GMK_CANNON_WORK.ply_work, mtMathCos(obj_work.dir.z - 16384) * gMS_GMK_CANNON_WORK.cannon_power, mtMathSin(obj_work.dir.z - 16384) * gMS_GMK_CANNON_WORK.cannon_power);
			gmGmkCannonFieldColOff(obj_work);
			gMS_GMK_CANNON_WORK.gmk_work.ene_com.enemy_flag |= 32768u;
			gMS_GMK_CANNON_WORK.shoot_after = 0;
			obj_work.ppFunc = gmGmkCannonShoot;
			gmGmkCannonShoot(obj_work);
			GmSoundPlaySE("Cannon2");
			GMM_PAD_VIB_SMALL();
		}
	}

	private static void gmGmkCannonShoot(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_CANNON_WORK gMS_GMK_CANNON_WORK = (GMS_GMK_CANNON_WORK)obj_work;
		gMS_GMK_CANNON_WORK.shoot_after++;
		if (gMS_GMK_CANNON_WORK.shoot_after == 16)
		{
			gmGmkCannonFieldColOn(obj_work);
			if (gMS_GMK_CANNON_WORK.angle_now == 0)
			{
				gMS_GMK_CANNON_WORK.ply_work = null;
				gmGmkCannonStart(obj_work);
				return;
			}
		}
		if (gMS_GMK_CANNON_WORK.shoot_after > 32)
		{
			gMS_GMK_CANNON_WORK.ply_work = null;
			gMS_GMK_CANNON_WORK.angle_set = 0;
			obj_work.ppFunc = gmGmkCannonShootEnd;
		}
	}

	private static void gmGmkCannonShootEnd(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_CANNON_WORK gMS_GMK_CANNON_WORK = (GMS_GMK_CANNON_WORK)obj_work;
		gmGmkCannon_CannonTurn(gMS_GMK_CANNON_WORK);
		obj_work.dir.z = (ushort)gMS_GMK_CANNON_WORK.angle_now;
		if (gMS_GMK_CANNON_WORK.angle_now == gMS_GMK_CANNON_WORK.angle_set)
		{
			gmGmkCannonStart(obj_work);
		}
	}

	private static void gmGmkCannonHit(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		OBS_OBJECT_WORK parent_obj = mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		GMS_GMK_CANNON_WORK gMS_GMK_CANNON_WORK = (GMS_GMK_CANNON_WORK)parent_obj;
		gMS_GMK_CANNON_WORK.hitpass = false;
		if (gMS_PLAYER_WORK == g_gm_main_system.ply_work[0])
		{
			if (gMS_GMK_CANNON_WORK.ply_work != gMS_PLAYER_WORK)
			{
				short num = (short)((parent_obj.pos.y >> 12) + mine_rect.rect.top);
				if ((gMS_PLAYER_WORK.obj_work.pos.y >> 12 < num && gMS_PLAYER_WORK.obj_work.move.y >= 0) || gMS_PLAYER_WORK.act_state == 31)
				{
					short num2 = 1;
					short num3 = (short)(MTM_MATH_ABS(mine_rect.rect.left - match_rect.rect.left) + MTM_MATH_ABS(mine_rect.rect.right - match_rect.rect.right));
					short num4 = (short)MTM_MATH_ABS(gMS_PLAYER_WORK.obj_work.move.x >> 12);
					if (num4 != 0)
					{
						num2 = (short)(num4 / num3 + 1);
					}
					if (gMS_PLAYER_WORK.obj_work.move.x < 0)
					{
						num3 = (short)(-num3);
					}
					short num5 = (short)((parent_obj.pos.x >> 12) + mine_rect.rect.left - match_rect.rect.left);
					short num6 = (short)((parent_obj.pos.x >> 12) + mine_rect.rect.right - match_rect.rect.right);
					short num7 = (short)(gMS_PLAYER_WORK.obj_work.pos.x >> 12);
					while (num2 != 0)
					{
						if (num7 >= num5 && num7 <= num6)
						{
							gMS_GMK_CANNON_WORK.ply_work = gMS_PLAYER_WORK;
							GmPlySeqInitCannon(gMS_PLAYER_WORK, (GMS_ENEMY_COM_WORK)parent_obj);
							GmSoundPlaySE("Cannon3");
							break;
						}
						num7 += num3;
						num2--;
					}
				}
			}
			gMS_GMK_CANNON_WORK.hitpass = true;
		}
		mine_rect.flag &= 4294573823u;
	}

