	private static void gmEndingCtrl(MTS_TASK_TCB tcb)
	{
		GMS_ENDING_WORK gMS_ENDING_WORK = (GMS_ENDING_WORK)tcb.work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		switch (gMS_ENDING_WORK.step)
		{
		case 0:
			if (gMS_ENDING_WORK.timer != 0)
			{
				gMS_ENDING_WORK.timer--;
				break;
			}
			g_gm_main_system.game_flag |= 1024u;
			IzFadeInitEasy(1u, 2u, 60f);
			gMS_ENDING_WORK.step = 1;
			gMS_ENDING_WORK.flag = 2u;
			GmSoundPlayStageBGM(0);
			break;
		case 2:
			gMS_ENDING_WORK.flag |= 1u;
			gMS_PLAYER_WORK.spd_jump_add = gMS_PLAYER_WORK.spd_add;
			break;
		case 3:
			gMS_PLAYER_WORK.obj_work.disp_flag |= 1u;
			if ((gMS_PLAYER_WORK.obj_work.move_flag & 1) != 0 && gMS_PLAYER_WORK.obj_work.spd_m > -4096)
			{
				if (amTpIsTouchOn(0))
				{
					gMS_PLAYER_WORK.ring_num = (short)GmEventMgrGetRingNum();
					if (amTpIsTouchOn(1))
					{
						g_gs_main_sys_info.game_flag |= 32u;
					}
					else
					{
						g_gs_main_sys_info.game_flag &= 4294967263u;
					}
				}
				gMS_ENDING_WORK.get_ring = (uint)gMS_PLAYER_WORK.ring_num;
				if (gMS_ENDING_WORK.get_ring < GmEventMgrGetRingNum())
				{
					gMS_ENDING_WORK.step = 4;
					gMS_ENDING_WORK.type = 0;
				}
				else if ((g_gs_main_sys_info.game_flag & 0x20) != 0)
				{
					gMS_ENDING_WORK.step = 5;
					gMS_ENDING_WORK.type = 2;
				}
				else
				{
					gMS_ENDING_WORK.step = 4;
					gMS_ENDING_WORK.type = 1;
				}
				gMS_ENDING_WORK.flag &= 4294967291u;
				gmEndingLastPicInit();
			}
			else
			{
				gMS_ENDING_WORK.flag &= 4294967293u;
				gMS_ENDING_WORK.flag |= 4u;
			}
			break;
		case 4:
			if (g_gm_main_system.game_time > 720 && gMS_PLAYER_WORK.seq_state != 62)
			{
				GmPlySeqGmkInitEndingDemo1(gMS_PLAYER_WORK);
				gMS_ENDING_WORK.step = 6;
			}
			break;
		case 5:
			if (g_gm_main_system.game_time > 720 && gMS_PLAYER_WORK.seq_state != 24)
			{
				GmPlySeqChangeTransformSuper(gMS_PLAYER_WORK);
				gMS_ENDING_WORK.step = 6;
			}
			break;
		case 6:
			if (g_gm_main_system.game_time > 900 && gMS_PLAYER_WORK.seq_state != 63)
			{
				bool type = false;
				if (gMS_ENDING_WORK.type == 1)
				{
					type = true;
				}
				GmPlySeqGmkInitEndingDemo2(gMS_PLAYER_WORK, type);
				gMS_ENDING_WORK.step = 7;
			}
			break;
		case 7:
			if (g_gm_main_system.game_time > 1140)
			{
				IzFadeInitEasy(0u, 1u, 32f);
				gMS_ENDING_WORK.step = 8;
			}
			break;
		case 8:
			if (IzFadeIsEnd())
			{
				GmMainEnd();
				SyDecideEvtCase(0);
				SyChangeNextEvt();
			}
			break;
		case 1:
			break;
		}
	}

