		gMS_BOSS2_MGR_WORK.ene_3d.ene_com.enemy_flag |= 32768u;
		obj_work.ppFunc = gmBoss2MgrMainFuncWaitLoad;
		if (GmBsCmnIsFinalZoneType(obj_work) != 0)
