	}

	private static void gmBoss2MgrAddObject(GMS_BOSS2_MGR_WORK mgr_work, OBS_OBJECT_WORK obj_work_parts)
	{
		mgr_work.obj_create_count++;
		obj_work_parts.user_work_OBJECT = mgr_work;
	}

	private static void gmBoss2MgrDeleteObject(OBS_OBJECT_WORK obj_work_parts)
	{
		GMS_BOSS2_MGR_WORK gMS_BOSS2_MGR_WORK = gmBoss2MgrGetMgrWork(obj_work_parts);
		gMS_BOSS2_MGR_WORK.obj_create_count--;
		obj_work_parts.user_work = 0u;
	}

	private static void gmBoss2MgrMainFuncWaitLoad(OBS_OBJECT_WORK obj_work)
	{
		if (GmBsCmnIsFinalZoneType(obj_work) == 0 || GmMainDatLoadBossBattleLoadCheck(1))
		{
			GMS_BOSS2_MGR_WORK gMS_BOSS2_MGR_WORK = (GMS_BOSS2_MGR_WORK)obj_work;
			GMS_BOSS2_BODY_WORK gMS_BOSS2_BODY_WORK = (GMS_BOSS2_BODY_WORK)GmEventMgrLocalEventBirth(316, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
			OBS_OBJECT_WORK obj_work2 = gMS_BOSS2_BODY_WORK.ene_3d.ene_com.obj_work;
			obj_work2.parent_obj = obj_work;
			gMS_BOSS2_BODY_WORK.parts_objs[0] = obj_work2;
			gMS_BOSS2_MGR_WORK.body_work = gMS_BOSS2_BODY_WORK;
			gmBoss2MgrAddObject(gMS_BOSS2_MGR_WORK, obj_work2);
			mtTaskChangeTcbDestructor(obj_work2.tcb, gmBoss2BodyExit);
			GMS_BOSS2_EGG_WORK gMS_BOSS2_EGG_WORK = (GMS_BOSS2_EGG_WORK)GmEventMgrLocalEventBirth(317, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
			OBS_OBJECT_WORK obj_work3 = gMS_BOSS2_EGG_WORK.ene_3d.ene_com.obj_work;
			obj_work3.parent_obj = obj_work2;
			gmBoss2MgrAddObject(gMS_BOSS2_MGR_WORK, obj_work3);
			mtTaskChangeTcbDestructor(obj_work3.tcb, gmBoss2ExitFunc);
			gMS_BOSS2_BODY_WORK.parts_objs[1] = obj_work3;
			obj_work.ppFunc = gmBoss2MgrMainFuncWaitSetup;
		}
	}

	private static void gmBoss2MgrMainFuncWaitSetup(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS2_MGR_WORK gMS_BOSS2_MGR_WORK = (GMS_BOSS2_MGR_WORK)obj_work;
		GMS_BOSS2_BODY_WORK body_work = gMS_BOSS2_MGR_WORK.body_work;
		for (int i = 0; 2 > i; i++)
		{
			if (body_work.parts_objs[i] == null)
			{
				return;
			}
		}
		gMS_BOSS2_MGR_WORK.flag |= 1u;
		obj_work.ppFunc = gmBoss2MgrMainFunc;
	}

	private static void gmBoss2MgrMainFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS2_MGR_WORK gMS_BOSS2_MGR_WORK = (GMS_BOSS2_MGR_WORK)obj_work;
		if ((gMS_BOSS2_MGR_WORK.flag & 2) != 0)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(gMS_BOSS2_MGR_WORK.body_work);
			oBS_OBJECT_WORK.flag |= 8u;
			gMS_BOSS2_MGR_WORK.body_work = null;
			obj_work.ppFunc = gmBoss2MgrMainFuncWaitRelease;
		}
	}

	private static void gmBoss2MgrMainFuncWaitRelease(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS2_MGR_WORK gMS_BOSS2_MGR_WORK = (GMS_BOSS2_MGR_WORK)obj_work;
		if (GmBsCmnIsFinalZoneType(obj_work) != 0)
		{
			if (gMS_BOSS2_MGR_WORK.obj_create_count > 0)
			{
				return;
			}
			GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)obj_work;
			gMS_ENEMY_COM_WORK.enemy_flag |= 65536u;
			obj_work.flag |= 4u;
			GmGameDatReleaseBossBattleStart(1);
			GmGmkCamScrLimitRelease(14);
			OBS_OBJECT_WORK oBS_OBJECT_WORK = gmBoss2BodySearchShutterOut();
			if (oBS_OBJECT_WORK != null)
			{
				GmGmkShutterOutChangeModeOpen(oBS_OBJECT_WORK);
			}
		}
		obj_work.ppFunc = null;
	}

	private static void gmBoss2BodyExit(MTS_TASK_TCB tcb)
	{
		GMS_BOSS2_BODY_WORK gMS_BOSS2_BODY_WORK = (GMS_BOSS2_BODY_WORK)mtTaskGetTcbWork(tcb);
		OBS_OBJECT_WORK obj_work = gMS_BOSS2_BODY_WORK.ene_3d.ene_com.obj_work;
		GmBsCmnClearBossMotionCBSystem(obj_work);
		GmBsCmnDeleteSNMWork(gMS_BOSS2_BODY_WORK.snm_work);
		GmBsCmnClearCNMCb(obj_work);
		GmBsCmnDeleteCNMMgrWork(gMS_BOSS2_BODY_WORK.cnm_mgr_work);
		if (gMS_BOSS2_BODY_WORK.se_handle != null)
		{
			GmSoundStopSE(gMS_BOSS2_BODY_WORK.se_handle);
			GsSoundFreeSeHandle(gMS_BOSS2_BODY_WORK.se_handle);
			gMS_BOSS2_BODY_WORK.se_handle = null;
		}
		gmBoss2ExitFunc(tcb);
	}

	private static void gmBoss2BodyReactionPlayer(OBS_OBJECT_WORK obj_work_player, OBS_OBJECT_WORK obj_work_body)
	{
		GMS_PLAYER_WORK ply_work = (GMS_PLAYER_WORK)obj_work_player;
		GmPlySeqAtkReactionInit(ply_work);
		GmPlySeqSetJumpState(ply_work, 0, 5u);
		obj_work_player.spd_m = 0;
		if (obj_work_player.move.x >= 0)
		{
			obj_work_player.spd.x = -20480;
		}
		else
		{
			obj_work_player.spd.x = 20480;
		}
		if (obj_work_player.pos.y <= obj_work_body.pos.y)
		{
			obj_work_player.spd.y = -16384;
		}
		else
		{
			obj_work_player.spd.y = 16384;
		}
		GmPlySeqSetNoJumpMoveTime(ply_work, 102400);
	}

