	private static void gmBoss2BodySetActionAllParts(GMS_BOSS2_BODY_WORK body_work, int action_id)
	{
		gmBoss2BodySetActionAllParts(body_work, action_id, 0);
	}

	private static void gmBoss2BodySetActionAllParts(GMS_BOSS2_BODY_WORK body_work, int action_id, int force_change)
	{
		if (force_change == 0 && body_work.action_id == action_id)
		{
			return;
		}
		body_work.action_id = action_id;
		for (int i = 0; 2 > i; i++)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = body_work.parts_objs[i];
			if (oBS_OBJECT_WORK == null)
			{
				continue;
			}
			GMS_BOSS2_PART_ACT_INFO gMS_BOSS2_PART_ACT_INFO = gm_boss2_act_info_tbl[action_id][i];
			if (i == 1)
			{
				GMS_BOSS2_EGG_WORK gMS_BOSS2_EGG_WORK = (GMS_BOSS2_EGG_WORK)oBS_OBJECT_WORK;
				if ((gMS_BOSS2_EGG_WORK.flag & 1) != 0)
				{
					continue;
				}
			}
			if (gMS_BOSS2_PART_ACT_INFO.is_maintain != 0)
			{
				if (gMS_BOSS2_PART_ACT_INFO.is_repeat != 0)
				{
					oBS_OBJECT_WORK.disp_flag |= 4u;
				}
			}
			else
			{
				GmBsCmnSetAction(oBS_OBJECT_WORK, gMS_BOSS2_PART_ACT_INFO.mtn_id, gMS_BOSS2_PART_ACT_INFO.is_repeat, gMS_BOSS2_PART_ACT_INFO.is_blend);
			}
			oBS_OBJECT_WORK.obj_3d.speed[0] = gMS_BOSS2_PART_ACT_INFO.mtn_spd;
			oBS_OBJECT_WORK.obj_3d.blend_spd = gMS_BOSS2_PART_ACT_INFO.blend_spd;
		}
	}

	private static void gmBoss2BodyOutFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS2_BODY_WORK gMS_BOSS2_BODY_WORK = (GMS_BOSS2_BODY_WORK)obj_work;
		GmBsCmnUpdateCNMParam(obj_work, gMS_BOSS2_BODY_WORK.cnm_mgr_work);
		ObjDrawActionSummary(obj_work);
	}

	private static void gmBoss2BodyDefFunc(OBS_RECT_WORK own_rect, OBS_RECT_WORK target_rect)
	{
		OBS_OBJECT_WORK parent_obj = target_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = own_rect.parent_obj;
		GMS_BOSS2_BODY_WORK gMS_BOSS2_BODY_WORK = (GMS_BOSS2_BODY_WORK)parent_obj2;
		if (parent_obj != null && 1 == parent_obj.obj_type)
		{
			gmBoss2BodyReactionPlayer(parent_obj, parent_obj2);
			gmBoss2BodySetNoHitTime(gMS_BOSS2_BODY_WORK, 10u);
			OBS_RECT_WORK rect_work_arm = gMS_BOSS2_BODY_WORK.rect_work_arm;
			if ((rect_work_arm.flag & 4) == 0 || parent_obj2.pos.y >= parent_obj.pos.y)
			{
				gmBoss2BodyDamage(gMS_BOSS2_BODY_WORK);
			}
		}
	}

	private static void gmBoss2BodyHitFunc(OBS_RECT_WORK own_rect, OBS_RECT_WORK target_rect)
	{
		UNREFERENCED_PARAMETER(target_rect);
		OBS_OBJECT_WORK parent_obj = own_rect.parent_obj;
		GMS_BOSS2_BODY_WORK gMS_BOSS2_BODY_WORK = (GMS_BOSS2_BODY_WORK)parent_obj;
		gMS_BOSS2_BODY_WORK.flag |= 268435456u;
	}

	private static OBS_OBJECT_WORK gmBoss2BodySearchShutterIn()
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK;
		for (oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, 3); oBS_OBJECT_WORK != null; oBS_OBJECT_WORK = ObjObjectSearchRegistObject(oBS_OBJECT_WORK, 3))
		{
			GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
			if (gMS_ENEMY_3D_WORK.ene_com.eve_rec.id == 261)
			{
				break;
			}
		}
		return oBS_OBJECT_WORK;
	}

	private static OBS_OBJECT_WORK gmBoss2BodySearchShutterOut()
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK;
		for (oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, 3); oBS_OBJECT_WORK != null; oBS_OBJECT_WORK = ObjObjectSearchRegistObject(oBS_OBJECT_WORK, 3))
		{
			GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)oBS_OBJECT_WORK;
			if (gMS_ENEMY_COM_WORK.eve_rec.id == 262)
			{
				break;
			}
		}
