	private static void gmBoss2BodyInitMoveNormal(GMS_BOSS2_BODY_WORK body_work, VecFx32 dest_pos, float frame)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		body_work.start_pos.x = oBS_OBJECT_WORK.pos.x;
		body_work.start_pos.y = oBS_OBJECT_WORK.pos.y;
		body_work.start_pos.z = oBS_OBJECT_WORK.pos.z;
		body_work.end_pos.x = dest_pos.x;
		body_work.end_pos.y = dest_pos.y;
		body_work.end_pos.z = body_work.start_pos.z;
		body_work.move_counter = 0f;
		if (frame > 0f)
		{
			body_work.move_frame = frame;
		}
		else
		{
			body_work.move_frame = 1f;
		}
	}

	private static float gmBoss2BodyUpdateMoveNormal(GMS_BOSS2_BODY_WORK body_work)
	{
		VecFx32 vecFx = default(VecFx32);
		body_work.move_counter += 1f;
		if (body_work.move_counter >= body_work.move_frame)
		{
			vecFx.x = body_work.end_pos.x;
			vecFx.y = body_work.end_pos.y;
			vecFx.z = body_work.end_pos.z;
		}
		else
		{
			float num = body_work.move_counter / body_work.move_frame;
			int ang = AKM_DEGtoA32(180f * num);
			float num2 = 0.5f * (1f - nnCos(ang));
			VecFx32 vecFx2 = new VecFx32
			{
				x = (int)((float)(body_work.end_pos.x - body_work.start_pos.x) * num2),
				y = (int)((float)(body_work.end_pos.y - body_work.start_pos.y) * num2),
				z = (int)((float)(body_work.end_pos.z - body_work.start_pos.z) * num2)
			};
			vecFx.x = body_work.start_pos.x + vecFx2.x;
			vecFx.y = body_work.start_pos.y + vecFx2.y;
			vecFx.z = body_work.start_pos.z + vecFx2.z;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		oBS_OBJECT_WORK.pos.x = vecFx.x;
		oBS_OBJECT_WORK.pos.y = vecFx.y;
		oBS_OBJECT_WORK.pos.z = vecFx.z;
		return body_work.move_frame - body_work.move_counter;
	}

	private static void gmBoss2BodyInitMovePinBall(GMS_BOSS2_BODY_WORK body_work, VecFx32 dir_pos, int speed)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		VecFx32 vecFx = new VecFx32
		{
			x = dir_pos.x - oBS_OBJECT_WORK.pos.x,
			y = dir_pos.y - oBS_OBJECT_WORK.pos.y,
			z = 0
		};
		if (vecFx.x > 2048000)
		{
			vecFx.x = 2048000;
		}
		else if (vecFx.x < -2048000)
		{
			vecFx.x = -2048000;
		}
		if (vecFx.y > 2048000)
		{
			vecFx.y = 2048000;
		}
		else if (vecFx.y < -2048000)
		{
			vecFx.y = -2048000;
		}
		int num = FX_Sqrt(FX_Mul(vecFx.x, vecFx.x) + FX_Mul(vecFx.y, vecFx.y));
		if (num != 0)
		{
			oBS_OBJECT_WORK.spd.x = FX_Mul(FX_Div(vecFx.x, num), speed);
			oBS_OBJECT_WORK.spd.y = FX_Mul(FX_Div(vecFx.y, num), speed);
		}
	}

