	private static void gmBoss2BodyUpdateMovePinBall(GMS_BOSS2_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		int num = 0;
		int num2 = MTM_MATH_ABS(oBS_OBJECT_WORK.spd.x);
		int num3 = MTM_MATH_ABS(oBS_OBJECT_WORK.spd.y);
		if (gmBoss2BodyPinBallCheckFieldUnder(oBS_OBJECT_WORK) != 0)
		{
			oBS_OBJECT_WORK.spd.y = -num3;
			if ((long)MTM_MATH_ABS(oBS_OBJECT_WORK.spd.x) < 256L)
			{
				oBS_OBJECT_WORK.spd.x = 256;
			}
			oBS_OBJECT_WORK.move_flag |= 32784u;
			num = 1;
		}
		else if (gmBoss2BodyPinBallCheckFieldOver(oBS_OBJECT_WORK) != 0)
		{
			oBS_OBJECT_WORK.spd.y = num3;
			if ((long)MTM_MATH_ABS(oBS_OBJECT_WORK.spd.x) < 256L)
			{
				oBS_OBJECT_WORK.spd.x = 256;
			}
			oBS_OBJECT_WORK.move_flag |= 32784u;
			num = 1;
		}
		if (gmBoss2BodyPinBallCheckFieldFront(oBS_OBJECT_WORK) != 0 || gmBoss2BodyPinBallCheckFieldBack(oBS_OBJECT_WORK) != 0)
		{
			if (oBS_OBJECT_WORK.spd.x < 0)
			{
				oBS_OBJECT_WORK.spd.x = num2;
			}
			else
			{
				oBS_OBJECT_WORK.spd.x = -num2;
			}
			if ((long)MTM_MATH_ABS(oBS_OBJECT_WORK.spd.y) < 256L)
			{
				oBS_OBJECT_WORK.spd.y = 256;
			}
			oBS_OBJECT_WORK.move_flag |= 32784u;
			num = 1;
		}
		if (num != 0)
		{
			if ((body_work.flag & 0x80) == 0)
			{
				GmSoundPlaySE("Boss2_05");
				body_work.flag |= 128u;
			}
		}
		else
		{
			body_work.flag &= 4294967167u;
		}
	}

	private static void gmBoss2BodyInitTurn(GMS_BOSS2_BODY_WORK body_work, short dest_angle, float frame, int flag_positive)
	{
		body_work.turn_counter = 0f;
		body_work.turn_frame = frame;
		body_work.turn_start = body_work.angle_current;
		ushort turn_amount = (ushort)(dest_angle - body_work.angle_current);
		body_work.turn_amount = turn_amount;
		if (flag_positive == 0)
		{
			ushort num = (ushort)(body_work.turn_amount - AKM_DEGtoA32(360));
			body_work.turn_amount = num - AKM_DEGtoA32(360);
		}
	}

	private static float gmBoss2BodyUpdateTurn(GMS_BOSS2_BODY_WORK body_work)
	{
		if (body_work.turn_frame < 1f)
		{
			return 0f;
		}
		body_work.turn_counter += 1f;
		short deg;
		if (body_work.turn_counter >= body_work.turn_frame)
		{
			deg = (short)(body_work.turn_start + (short)body_work.turn_amount);
		}
		else
		{
			float num = body_work.turn_counter / body_work.turn_frame;
			int ang = AKM_DEGtoA32(180f * num);
			float num2 = (float)body_work.turn_amount * 0.5f * (1f - nnCos(ang));
			deg = (short)(body_work.turn_start + (short)num2);
		}
		gmBoss2BodySetDirection(body_work, deg);
		return body_work.turn_frame - body_work.turn_counter;
	}

