	private static void gmBoss2BodyCatchArmUpdateShakePlayer(GMS_BOSS2_BODY_WORK body_work, uint shake_count)
	{
		body_work.shake_pos += body_work.shake_speed;
		int num = MTM_MATH_ABS(body_work.shake_pos);
		int num2 = MTM_MATH_ABS(body_work.shake_speed);
		if (num > 5)
		{
			body_work.shake_speed = -body_work.shake_speed;
		}
		else if (num < num2)
		{
			body_work.shake_count++;
		}
		if (body_work.shake_count >= shake_count * 2)
		{
			body_work.shake_speed = 0;
			body_work.shake_pos = 0;
			body_work.shake_count = 0u;
		}
	}

	private static void gmBoss2BodyCatchSetArmLength(GMS_BOSS2_BODY_WORK body_work, float length)
	{
		NNS_MATRIX nNS_MATRIX = GmBsCmnGetSNMMtx(body_work.snm_work, body_work.snm_reg_id[2]);
		NNS_MATRIX dst_mtx = new NNS_MATRIX();
		AkMathExtractScaleMtx(dst_mtx, nNS_MATRIX);
		NNS_MATRIX nNS_MATRIX2 = new NNS_MATRIX();
		nnMakeTranslateMatrix(nNS_MATRIX2, 0f, length / nNS_MATRIX.M11, 0f);
		for (int i = 0; 13 > i; i++)
		{
			int cnm_reg_id = body_work.cnm_reg_id[i];
			GmBsCmnChangeCNMModeNode(body_work.cnm_mgr_work, cnm_reg_id, 1u);
			GmBsCmnSetCNMMtx(body_work.cnm_mgr_work, nNS_MATRIX2, cnm_reg_id);
			GmBsCmnEnableCNMLocalCoordinate(body_work.cnm_mgr_work, cnm_reg_id, 1);
			GmBsCmnEnableCNMMtxNode(body_work.cnm_mgr_work, cnm_reg_id, 1);
			nnMakeUnitMatrix(nNS_MATRIX2);
		}
	}

