	private static void gmBoss2BodyPinBallAdjustMoveSpeed(GMS_BOSS2_BODY_WORK body_work, int speed)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		VecFx32 vecFx = default(VecFx32);
		int x = FX_Mul(oBS_OBJECT_WORK.spd.x, oBS_OBJECT_WORK.spd.x) + FX_Mul(oBS_OBJECT_WORK.spd.y, oBS_OBJECT_WORK.spd.y);
		x = FX_Sqrt(x);
		if (x == 0)
		{
			vecFx.x = 4096;
			vecFx.y = 0;
		}
		else
		{
			vecFx.x = FX_Div(oBS_OBJECT_WORK.spd.x, x);
			vecFx.y = FX_Div(oBS_OBJECT_WORK.spd.y, x);
		}
		vecFx.z = 0;
		int num = (speed - x) / 10;
		oBS_OBJECT_WORK.spd.x = FX_Mul(vecFx.x, x + num);
		oBS_OBJECT_WORK.spd.y = FX_Mul(vecFx.y, x + num);
		oBS_OBJECT_WORK.spd.z = 0;
	}

