	private static void gmBoss2BodyEscapeAddjustSpeed(GMS_BOSS2_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (MTM_MATH_ABS(oBS_OBJECT_WORK.spd.x) > -3276)
		{
			oBS_OBJECT_WORK.spd.x = 0;
			oBS_OBJECT_WORK.spd.y = -3276;
			oBS_OBJECT_WORK.spd_add.x = 0;
