	private static void gmBoss2BodyMainFuncWaitSetup(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS2_BODY_WORK gMS_BOSS2_BODY_WORK = (GMS_BOSS2_BODY_WORK)obj_work;
		GMS_BOSS2_MGR_WORK mgr_work = gmBoss2MgrGetMgrWork(obj_work);
		if (gmBoss2MgrCheckSetupComplete(mgr_work) != 0)
		{
			GmBsCmnInitBossMotionCBSystem(obj_work, gMS_BOSS2_BODY_WORK.bmcb_mgr);
			GmBsCmnCreateSNMWork(gMS_BOSS2_BODY_WORK.snm_work, obj_work.obj_3d._object, 15);
			GmBsCmnAppendBossMotionCallback(gMS_BOSS2_BODY_WORK.bmcb_mgr, gMS_BOSS2_BODY_WORK.snm_work.bmcb_link);
			for (int i = 0; 15 > i; i++)
			{
				gMS_BOSS2_BODY_WORK.snm_reg_id[i] = GmBsCmnRegisterSNMNode(gMS_BOSS2_BODY_WORK.snm_work, g_boss2_node_index_list[i]);
			}
			GmBsCmnCreateCNMMgrWork(gMS_BOSS2_BODY_WORK.cnm_mgr_work, obj_work.obj_3d._object, 13);
			GmBsCmnInitCNMCb(obj_work, gMS_BOSS2_BODY_WORK.cnm_mgr_work);
			for (int j = 0; 13 > j; j++)
			{
				gMS_BOSS2_BODY_WORK.cnm_reg_id[j] = GmBsCmnRegisterCNMNode(gMS_BOSS2_BODY_WORK.cnm_mgr_work, g_boss2_node_index_list[2 + j]);
			}
			obj_work.ppFunc = gmBoss2BodyMainFunc;
			gmBoss2BodyChangeState(gMS_BOSS2_BODY_WORK, 1);
		}
	}

	private static void gmBoss2BodyMainFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS2_BODY_WORK gMS_BOSS2_BODY_WORK = (GMS_BOSS2_BODY_WORK)obj_work;
		gmBoss2BodyUpdateNoHitTime(gMS_BOSS2_BODY_WORK);
		gmBoss2BodyUpdateInvincibleTime(gMS_BOSS2_BODY_WORK);
		if (gMS_BOSS2_BODY_WORK.proc_update != null)
		{
			gMS_BOSS2_BODY_WORK.proc_update(gMS_BOSS2_BODY_WORK);
		}
		if ((gMS_BOSS2_BODY_WORK.flag & 0x2000000) != 0)
		{
			gmBoss2EffAfterburnerInit(gMS_BOSS2_BODY_WORK);
		}
		if ((gMS_BOSS2_BODY_WORK.flag & 0x80000000u) != 0)
		{
			gMS_BOSS2_BODY_WORK.flag &= 1073741823u;
			gmBoss2BodyChangeState(gMS_BOSS2_BODY_WORK, 11);
			return;
		}
		if ((gMS_BOSS2_BODY_WORK.flag & 0x40000000) != 0)
		{
			gMS_BOSS2_BODY_WORK.flag &= 3221225471u;
			gMS_BOSS2_BODY_WORK.flag |= 536870912u;
			GmBsCmnInitObject3DNNDamageFlicker(obj_work, gMS_BOSS2_BODY_WORK.flk_work, 32f);
		}
		GmBsCmnUpdateObject3DNNDamageFlicker(obj_work, gMS_BOSS2_BODY_WORK.flk_work);
		gmBoss2BodyUpdateDirection(gMS_BOSS2_BODY_WORK);
	}

	private static void gmBoss2EggChangeAction(GMS_BOSS2_EGG_WORK egg_work, int action_id)
	{
		gmBoss2EggChangeAction(egg_work, action_id, 0);
	}

	private static void gmBoss2EggChangeAction(GMS_BOSS2_EGG_WORK egg_work, int action_id, int force_change)
	{
		GMS_BOSS2_PART_ACT_INFO gMS_BOSS2_PART_ACT_INFO = gm_boss2_egg_act_info_tbl[action_id];
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		if (force_change == 0 && egg_work.egg_action_id == action_id && (egg_work.flag & 1) != 0)
		{
			return;
		}
		egg_work.egg_action_id = action_id;
		egg_work.flag |= 1u;
		if (gMS_BOSS2_PART_ACT_INFO.is_maintain != 0)
		{
			if (gMS_BOSS2_PART_ACT_INFO.is_repeat != 0)
			{
				oBS_OBJECT_WORK.disp_flag |= 4u;
			}
		}
		else
		{
			GmBsCmnSetAction(oBS_OBJECT_WORK, gMS_BOSS2_PART_ACT_INFO.mtn_id, gMS_BOSS2_PART_ACT_INFO.is_repeat, gMS_BOSS2_PART_ACT_INFO.is_blend);
		}
		oBS_OBJECT_WORK.obj_3d.speed[0] = gMS_BOSS2_PART_ACT_INFO.mtn_spd;
