	private static void gmBoss2EggmanMainFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS2_BODY_WORK gMS_BOSS2_BODY_WORK = (GMS_BOSS2_BODY_WORK)obj_work.parent_obj;
		GMS_BOSS2_EGG_WORK gMS_BOSS2_EGG_WORK = (GMS_BOSS2_EGG_WORK)obj_work;
		GmBsCmnUpdateObject3DNNStuckWithNode(obj_work, gMS_BOSS2_BODY_WORK.snm_work, gMS_BOSS2_BODY_WORK.snm_reg_id[0], 1);
		if (gMS_BOSS2_EGG_WORK.proc_update != null)
		{
			gMS_BOSS2_EGG_WORK.proc_update(gMS_BOSS2_EGG_WORK);
		}
		if ((gMS_BOSS2_BODY_WORK.flag & 0x800000) != 0)
		{
			gMS_BOSS2_BODY_WORK.flag &= 4286578687u;
			gmBoss2EggStateEscapeInit(gMS_BOSS2_EGG_WORK);
		}
		if ((gMS_BOSS2_BODY_WORK.flag & 0x20000000) != 0)
		{
			gMS_BOSS2_BODY_WORK.flag &= 3758096383u;
			gmBoss2EggStateDamageInit(gMS_BOSS2_EGG_WORK);
		}
		if ((gMS_BOSS2_BODY_WORK.flag & 0x1000000) != 0)
		{
			gMS_BOSS2_BODY_WORK.flag &= 4278190079u;
			gmBoss2ChangeTextureBurnt(obj_work);
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(gMS_BOSS2_BODY_WORK);
		if ((oBS_OBJECT_WORK.disp_flag & 0x10) != 0)
		{
			obj_work.disp_flag |= 16u;
		}
		else
		{
			obj_work.disp_flag &= 4294967279u;
		}
		if ((gMS_BOSS2_BODY_WORK.flag & 0x40) != 0)
		{
			obj_work.disp_flag |= 32u;
		}
		else
		{
			obj_work.disp_flag &= 4294967263u;
		}
	}

