	private static void gmBoss2BallUpdateWaitBomb(GMS_BOSS2_BALL_WORK ball_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(ball_work);
		oBS_OBJECT_WORK.user_timer++;
