			ball_work.proc_update = gmBoss2BallUpdateFlicker;
			GmBsCmnInitObject3DNNDamageFlicker(oBS_OBJECT_WORK, ball_work.flk_work, 16f);
			gmBoss2EffBallBombInit(oBS_OBJECT_WORK.pos, oBS_OBJECT_WORK);
