			gmBoss2EffBallBombPartInit(oBS_OBJECT_WORK.pos, parent_obj, 4096);
			gmBoss2EffBallBombPartInit(oBS_OBJECT_WORK.pos, parent_obj, -4096);
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctCmnEsCreate(null, 10);
			OBS_OBJECT_WORK oBS_OBJECT_WORK2 = (OBS_OBJECT_WORK)gMS_EFFECT_3DES_WORK;
			oBS_OBJECT_WORK2.pos.Assign(oBS_OBJECT_WORK.pos);
			oBS_OBJECT_WORK.flag |= 4u;
			GmSoundPlaySE("Boss2_03");
		}
	}

