	private static OBS_OBJECT_WORK gmBoss2EffInit(OBS_DATA_WORK data_work, int effect_type, OBS_OBJECT_WORK parent_obj_work, short rot_x, short rot_y, short rot_z, float offset_x, float offset_y, float offset_z, int flag_flip, int flag_data_rotate)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_EFFECT_3DES_WORK(), null, 0, "B02_effect");
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = (GMS_EFFECT_3DES_WORK)oBS_OBJECT_WORK;
		ObjObjectAction3dESEffectLoad(oBS_OBJECT_WORK, gMS_EFFECT_3DES_WORK.obj_3des, data_work, null, 0, null);
		ObjObjectAction3dESTextureLoad(oBS_OBJECT_WORK, gMS_EFFECT_3DES_WORK.obj_3des, ObjDataGet(722), null, 0, null, false);
		ObjObjectAction3dESTextureSetByDwork(oBS_OBJECT_WORK, ObjDataGet(723));
		uint num = 0u;
		if (parent_obj_work != null)
		{
			oBS_OBJECT_WORK.parent_obj = parent_obj_work;
			oBS_OBJECT_WORK.pos.x = parent_obj_work.pos.x;
			oBS_OBJECT_WORK.pos.y = parent_obj_work.pos.y;
			oBS_OBJECT_WORK.pos.z = parent_obj_work.pos.z;
			num |= 0x12;
		}
		GmEffect3DESSetDispRotation(gMS_EFFECT_3DES_WORK, rot_x, rot_y, rot_z);
		GmEffect3DESAddDispOffset(gMS_EFFECT_3DES_WORK, offset_x, offset_y, offset_z);
		if (flag_flip == 0)
		{
			num |= 1;
		}
		if (flag_data_rotate != 0)
		{
			num |= 0x40;
		}
		GmEffect3DESSetupBase(gMS_EFFECT_3DES_WORK, (uint)effect_type, num);
		return oBS_OBJECT_WORK;
	}

