	}

	private static OBS_OBJECT_WORK gmBoss2EffBallBombPartInit(VecFx32 create_pos, OBS_OBJECT_WORK body_obj_work, int spd_x)
	{
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = (GMS_EFFECT_3DES_WORK)gmBoss2EffInit(ObjDataGet(718), 2, null, 0, 0, 0, 0f, 0f, 0f, 0, 0);
		OBS_OBJECT_WORK obj_work = gMS_EFFECT_3DES_WORK.efct_com.obj_work;
		OBS_RECT_WORK[] rect_work = gMS_EFFECT_3DES_WORK.efct_com.rect_work;
		GmBsCmnSetEfctAtkVsPly(gMS_EFFECT_3DES_WORK.efct_com, 64);
		ObjRectWorkSet(rect_work[1], -8, -8, 8, 8);
		rect_work[1].ppHit = gmBoss2BallHitFunc;
		rect_work[1].flag |= 1028u;
		rect_work[0].flag |= 3072u;
		obj_work.pos.x = create_pos.x;
		obj_work.pos.y = create_pos.y;
		obj_work.pos.z = create_pos.z;
		obj_work.spd.x = spd_x;
		obj_work.spd.y = -16384;
		obj_work.move_flag |= 32912u;
		obj_work.flag |= 16u;
		obj_work.parent_obj = body_obj_work;
		obj_work.ppFunc = gmBoss2EffBallBombPartMainFunc;
