	private static void gmBoss2EffScatterInit(GMS_BOSS2_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK parent_obj = GMM_BS_OBJ(body_work);
		GMS_BOSS2_EFFECT_SCATTER_WORK gMS_BOSS2_EFFECT_SCATTER_WORK = null;
		for (int i = 3; 13 > i; i++)
		{
			GMS_BOSS2_EFFECT_SCATTER_WORK gMS_BOSS2_EFFECT_SCATTER_WORK2 = (GMS_BOSS2_EFFECT_SCATTER_WORK)GmBsCmnCreateNodeControlObjectBySize(parent_obj, body_work.cnm_mgr_work, body_work.cnm_reg_id[i], body_work.snm_work, body_work.snm_reg_id[2 + i], () => new GMS_BOSS2_EFFECT_SCATTER_WORK());
			GMS_BS_CMN_NODE_CTRL_OBJECT gMS_BS_CMN_NODE_CTRL_OBJECT = (GMS_BS_CMN_NODE_CTRL_OBJECT)gMS_BOSS2_EFFECT_SCATTER_WORK2;
			GmBsCmnChangeCNMModeNode(body_work.cnm_mgr_work, body_work.cnm_reg_id[i], 0u);
			GmBsCmnEnableCNMLocalCoordinate(body_work.cnm_mgr_work, body_work.cnm_reg_id[i], 0);
			GmBsCmnAttachNCObjectToSNMNode(gMS_BS_CMN_NODE_CTRL_OBJECT);
			gMS_BS_CMN_NODE_CTRL_OBJECT.is_enable = 1;
			gMS_BS_CMN_NODE_CTRL_OBJECT.proc_update = gmBoss2EffScatterMainFunc;
			OBS_OBJECT_WORK obj_work = gMS_BS_CMN_NODE_CTRL_OBJECT.efct_com.obj_work;
			obj_work.move_flag |= 128u;
			if (i == 4 || i == 5 || i == 7 || i == 8)
			{
				OBS_OBJECT_WORK obj_work2 = gMS_BOSS2_EFFECT_SCATTER_WORK.control_node_work.efct_com.obj_work;
				obj_work.spd.x = obj_work2.spd.x;
				obj_work.spd.y = obj_work2.spd.y;
			}
			else
			{
				int right_flag = 0;
				if (i % 2 != 0)
				{
					right_flag = 1;
				}
				gmBoss2EffScatterSetParamMove(obj_work, right_flag);
			}
			gMS_BOSS2_EFFECT_SCATTER_WORK = gMS_BOSS2_EFFECT_SCATTER_WORK2;
		}
	}

	private static void gmBoss2EffScatterMainFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_BS_CMN_NODE_CTRL_OBJECT ndc_obj = (GMS_BS_CMN_NODE_CTRL_OBJECT)obj_work;
		GmBsCmnSetWorldMtxFromNCObjectPosture(ndc_obj);
		obj_work.user_timer++;
		if (obj_work.user_timer >= 100)
		{
			obj_work.user_timer = 0;
			obj_work.flag |= 4u;
		}
	}

	private static void gmBoss2EffScatterSetParamMove(OBS_OBJECT_WORK obj_work, int right_flag)
	{
		int num = mtMathRand() % 30 + 45;
		if (right_flag != 0)
		{
			num = -num;
		}
		int ang = AKM_DEGtoA32(num + 90);
		obj_work.spd.y = -(int)(4096f * nnSin(ang));
		obj_work.spd.x = (int)(4096f * nnCos(ang));
	}

