	private void dmStgSlctSetClearInfo(DMS_STGSLCT_MAIN_WORK main_work)
	{
		uint num = 0u;
		uint num2 = 0u;
		uint num3 = 0u;
		SStage sStage = SStage.CreateInstance();
		for (num2 = 0u; num2 <= 16; num2++)
		{
			main_work.n_sonic_hi_score[num2] = (int)sStage[(int)num2].GetHighScore(false);
			main_work.s_sonic_hi_score[num2] = (int)sStage[(int)num2].GetHighScore(true);
			if (main_work.n_sonic_hi_score[num2] != 1000000000 && main_work.s_sonic_hi_score[num2] != 1000000000)
			{
				if (main_work.n_sonic_hi_score[num2] >= main_work.s_sonic_hi_score[num2])
				{
					main_work.hi_score[num2] = main_work.n_sonic_hi_score[num2];
				}
				else
				{
					main_work.hi_score[num2] = main_work.s_sonic_hi_score[num2];
				}
			}
			else if (main_work.n_sonic_hi_score[num2] == 1000000000 && main_work.s_sonic_hi_score[num2] == 1000000000)
			{
				main_work.hi_score[num2] = main_work.n_sonic_hi_score[num2];
			}
			else if (main_work.n_sonic_hi_score[num2] == 1000000000)
			{
				main_work.hi_score[num2] = main_work.s_sonic_hi_score[num2];
			}
			else if (main_work.s_sonic_hi_score[num2] == 1000000000)
			{
				main_work.hi_score[num2] = main_work.n_sonic_hi_score[num2];
			}
			else
			{
				main_work.hi_score[num2] = main_work.n_sonic_hi_score[num2];
			}
			if (main_work.hi_score[num2] > 1000000000)
			{
				main_work.hi_score[num2] = 999999999;
			}
			main_work.n_sonic_record_time[num2] = (int)sStage[(int)num2].GetFastTime(false);
			main_work.s_sonic_record_time[num2] = (int)sStage[(int)num2].GetFastTime(true);
			if (main_work.n_sonic_record_time[num2] != 36000 && main_work.s_sonic_record_time[num2] != 36000)
			{
				if (main_work.n_sonic_record_time[num2] <= main_work.s_sonic_record_time[num2])
				{
					main_work.record_time[num2] = main_work.n_sonic_record_time[num2];
				}
				else
				{
					main_work.record_time[num2] = main_work.s_sonic_record_time[num2];
				}
			}
			else if (main_work.n_sonic_record_time[num2] == 36000 && main_work.s_sonic_record_time[num2] == 36000)
			{
				main_work.record_time[num2] = main_work.n_sonic_record_time[num2];
			}
			else if (main_work.n_sonic_record_time[num2] == 36000)
			{
				main_work.record_time[num2] = main_work.s_sonic_record_time[num2];
			}
			else if (main_work.s_sonic_record_time[num2] == 36000)
			{
				main_work.record_time[num2] = main_work.n_sonic_record_time[num2];
			}
			else
			{
				main_work.record_time[num2] = main_work.n_sonic_record_time[num2];
			}
			if (main_work.record_time[num2] > 36000)
			{
				main_work.record_time[num2] = 35999;
			}
		}
		SSpecial sSpecial = SSpecial.CreateInstance();
		for (num2 = 0u; num2 < 7; num2++)
		{
