	private void dmStgSlctSetNextEvt(DMS_STGSLCT_MAIN_WORK main_work)
	{
		short num = 0;
		ushort num2 = 0;
		num2 = (ushort)main_work.cur_stage;
		switch (main_work.next_evt)
		{
		case 0:
			g_gs_main_sys_info.stage_id = num2;
