			if (main_work.cur_zone == 5)
			{
				g_gs_main_sys_info.stage_id = (ushort)(num2 + 4);
				g_gs_main_sys_info.prev_stage_id = ushort.MaxValue;
			}
			else
			{
				g_gs_main_sys_info.stage_id = num2;
				g_gs_main_sys_info.prev_stage_id = ushort.MaxValue;
			}
