	private void dmStgSlctInputProcStageSelectMove(DMS_STGSLCT_MAIN_WORK main_work)
	{
		uint num = 0u;
		uint num2 = 0u;
		uint num3 = 0u;
		num = dm_stgslct_zone_act_num_tbl[main_work.cur_zone][0];
		num2 = num + dm_stgslct_zone_act_num_tbl[main_work.cur_zone][1];
		num3 = dm_stgslct_zone_act_num_tbl[main_work.cur_zone][1] - 1;
		if ((AoPadStand() & GSD_KEY_CANCEL) != 0)
		{
			main_work.flag |= 2u;
			return;
		}
		if ((AoPadStand() & GSD_KEY_DECIDE) != 0)
		{
			main_work.flag |= 4u;
			return;
		}
		if ((AoPadStand() & 0x40) != 0)
		{
			main_work.cur_game_mode ^= 1u;
			main_work.mode_tex_frm = 1f;
			DmSoundPlaySE("Cursol");
			return;
		}
		dmStgSlctInputChangeEvtRanking(main_work);
		if ((AoPadMRepeat() & GSD_KEY_UP) != 0)
		{
			if (((AoPadMStand() & GSD_KEY_UP) == 0 && main_work.cur_stage == (int)num) || main_work.cur_zone == 4)
			{
				return;
			}
			if (main_work.crsr_idx == 0)
			{
				if (num3 > 3)
				{
					main_work.flag |= 64u;
				}
				else
				{
					main_work.flag |= 128u;
				}
			}
			else
			{
				main_work.flag |= 128u;
			}
			main_work.flag |= 2048u;
		}
		else
		{
			if ((AoPadMRepeat() & GSD_KEY_DOWN) == 0 || ((AoPadMStand() & GSD_KEY_DOWN) == 0 && main_work.cur_stage == (int)(num2 - 1)) || main_work.cur_zone == 4)
			{
				return;
			}
			if (main_work.crsr_idx == 3)
			{
				if (num3 > 3)
				{
					main_work.flag |= 64u;
				}
				else
				{
					main_work.flag |= 128u;
				}
			}
			else
			{
				main_work.flag |= 128u;
			}
			main_work.flag |= 4096u;
		}
	}

