	private void dmStgSlctInputProcWinDispIdle(DMS_STGSLCT_MAIN_WORK main_work)
	{
		if (main_work.win_mode == 1)
		{
			int i = 0;
			for (int num = 2; i < num; i++)
			{
				ArrayPointer<AOS_ACTION> arrayPointer = null;
				ArrayPointer<AOS_ACTION> arrayPointer2 = null;
				int win_cur_slct = 0;
				uint num2 = 0u;
				CTrgAoAction cTrgAoAction;
				switch (114 + i)
				{
				case 115:
					cTrgAoAction = main_work.trg_answer[0];
					arrayPointer = new ArrayPointer<AOS_ACTION>(main_work.act, 109);
					arrayPointer2 = new ArrayPointer<AOS_ACTION>(main_work.act, 112);
					win_cur_slct = 1;
					num2 = 2u;
					break;
				case 114:
					cTrgAoAction = main_work.trg_answer[1];
					arrayPointer = new ArrayPointer<AOS_ACTION>(main_work.act, 106);
					arrayPointer2 = new ArrayPointer<AOS_ACTION>(main_work.act, 109);
					win_cur_slct = 0;
					num2 = 4u;
					break;
				default:
					cTrgAoAction = null;
					break;
				}
				float frame;
				if (isBackKeyPressed())
				{
					setBackKeyRequest(false);
					win_cur_slct = 1;
					num2 = 2u;
					main_work.flag |= num2;
					main_work.win_cur_slct = win_cur_slct;
					frame = 2f;
				}
				else if (!cTrgAoAction.GetState(0u)[10] || !cTrgAoAction.GetState(0u)[1])
				{
					frame = (cTrgAoAction.GetState(0u)[0] ? 1f : ((!(2f <= (~arrayPointer).frame)) ? 0f : (~arrayPointer).frame));
				}
				else
				{
					frame = 2f;
					main_work.win_cur_slct = win_cur_slct;
					main_work.flag |= num2;
				}
				for (; arrayPointer != arrayPointer2; ++arrayPointer)
				{
					AoActSetFrame(arrayPointer, frame);
					AoActUpdate(arrayPointer, 0f);
				}
			}
		}
		else if (amTpIsTouchPush(0) || isBackKeyPressed())
		{
			setBackKeyRequest(false);
			main_work.flag |= 2u;
		}
	}

