	private void dmStgSlctSetSonicStockDispFrame(DMS_STGSLCT_MAIN_WORK main_work)
	{
		int num = 0;
		int[] array = new int[3];
		int[] array2 = array;
		int num2 = 1;
		num = (int)(main_work.player_stock - 1);
		if (num < 0)
		{
			num = 0;
		}
		if ((long)num > 999L)
		{
			num = 999;
		}
		for (uint num3 = 0u; num3 < 3; num3++)
		{
			for (uint num4 = 0u; num4 < 3 - num3 - 1; num4++)
			{
				num2 *= 10;
			}
			if (num >= num2)
			{
				array2[num3] = num / num2;
				num -= array2[num3] * num2;
			}
			else
			{
				array2[num3] = 0;
			}
			num2 = 1;
		}
		for (uint num5 = 0u; num5 < 3; num5++)
		{
			AoActSetFrame(main_work.act[6 + num5], array2[num5]);
		}
	}

