	private void dmStgSlctSetScoreDispFrame(DMS_STGSLCT_MAIN_WORK main_work, uint zone, uint act_no)
	{
		int num = 0;
		int[] array = dmStgSlctSetScoreDispFrame_tmp_digit;
		Array.Clear(array, 0, array.Length);
		int num2 = 1;
		ushort min = 0;
		ushort sec = 0;
		ushort msec = 0;
		int[] array2 = dmStgSlctSetScoreDispFrame_time_digit;
		Array.Clear(array2, 0, array2.Length);
		float num3 = 0f;
		bool flag = false;
		if (main_work.cur_game_mode == 0)
		{
			if (main_work.hi_score[act_no] != 1000000000)
			{
				num = main_work.hi_score[act_no];
				for (uint num4 = 0u; num4 < 9; num4++)
				{
					if (9 - num4 - 1 == 0)
					{
						num = 1;
					}
					else
					{
						for (uint num5 = 0u; num5 < 9 - num4 - 1; num5++)
						{
							num2 *= 10;
						}
					}
					if (num >= num2)
					{
						AoActSortRegAction(main_work.act[76 + num4]);
						if (num4 >= 8)
						{
							array[num4] = 0;
						}
						else
						{
							array[num4] = num / num2;
							num -= array[num4] * num2 - 1;
						}
						flag = true;
					}
					else
					{
						if (flag)
						{
							AoActSortRegAction(main_work.act[76 + num4]);
						}
						array[num4] = 0;
					}
					num2 = 1;
				}
				for (uint num6 = 0u; num6 < 9; num6++)
				{
					AoActSetFrame(main_work.act[76 + num6], array[num6]);
				}
			}
			else
			{
				for (uint num7 = 0u; num7 < 9; num7++)
				{
					AoActSortRegAction(main_work.act[76 + num7]);
					AoActSetFrame(main_work.act[76 + num7], 10f);
				}
			}
			return;
		}
		if (main_work.record_time[act_no] != 36000)
		{
			AkUtilFrame60ToTime((uint)main_work.record_time[act_no], ref min, ref sec, ref msec);
			num3 = (int)sec;
			if (num3 >= 10f)
			{
				array2[0] = (int)(num3 / 10f);
				num3 -= (float)array2[0] * 10f;
			}
			else
			{
				array2[0] = 0;
			}
			array2[1] = (int)num3;
			AoActSetFrame(main_work.act[76], (int)min);
			AoActSetFrame(main_work.act[77], 11f);
			AoActSetFrame(main_work.act[78], array2[0]);
			AoActSetFrame(main_work.act[79], array2[1]);
			AoActSetFrame(main_work.act[80], 11f);
			num3 = (int)msec;
			if (num3 >= 10f)
			{
				array2[0] = (int)(num3 / 10f);
				num3 -= (float)array2[0] * 10f;
			}
			else
			{
				array2[0] = 0;
			}
			array2[1] = (int)num3;
			AoActSetFrame(main_work.act[81], array2[0]);
			AoActSetFrame(main_work.act[82], array2[1]);
			return;
		}
		for (uint num8 = 0u; num8 < 7; num8++)
		{
			if (num8 == 1 || num8 == 4)
			{
				AoActSetFrame(main_work.act[76 + num8], 11f);
			}
			else
			{
				AoActSetFrame(main_work.act[76 + num8], 10f);
			}
		}
	}

