	private int dmStgSlctSetNextFocusAct(DMS_STGSLCT_MAIN_WORK main_work, int set_stage_id)
	{
		uint num = 0u;
		uint num2 = 0u;
		uint num3 = 0u;
		uint num4 = 0u;
		if (set_stage_id >= 21)
		{
			return (int)(dm_stgslct_zone_act_num_tbl[5][0] + (set_stage_id - 21));
		}
		if (set_stage_id >= 16)
		{
			return 16;
		}
		num = (uint)set_stage_id;
		if (!g_gs_main_sys_info.is_first_play)
		{
			return (int)num;
		}
		if (g_gs_main_sys_info.game_mode == 1)
		{
			return (int)num;
		}
		if ((main_work.flag & 0x1000000) != 0)
		{
			return (int)num;
		}
		uint num7 = dm_stgslct_act_zone_no_tbl[num];
		num2 = dm_stgslct_zone_array_act_tbl[num];
		for (uint num5 = num - num2; num5 < num - num2 + 4; num5++)
		{
			if (!GsMainSysIsStageClear((int)num5))
			{
				return (int)num5;
			}
		}
		for (uint num6 = 0u; num6 < 4; num6++)
		{
			num3 = num6;
			num4 = dm_stgslct_zone_act_num_tbl[num3][0];
			for (int i = 0; i < 4; i++)
			{
				if (!GsMainSysIsStageClear((int)(num4 + i)))
				{
					return (int)(num4 + i);
				}
			}
		}
		return 16;
	}

	private bool dmStgSlctIsBossFocus(DMS_STGSLCT_MAIN_WORK main_work)
	{
		bool result = false;
		switch (main_work.cur_zone)
		{
		default:
		{
			if (main_work.cur_game_mode != 0)
			{
				break;
			}
			uint num = dm_stgslct_zone_act_num_tbl[main_work.cur_zone][0];
			uint num2 = dm_stgslct_zone_act_num_tbl[main_work.cur_zone][1] + num;
			uint num3 = 0u;
			for (uint num4 = num; num4 < num2; num4++)
			{
				if (1 == main_work.is_clear_stage[num4])
				{
					num3++;
				}
			}
			if (3 == num3)
			{
				result = true;
			}
			break;
		}
		case 4u:
		case 5u:
			break;
		}
		return result;
	}

