	private void dmStgSlctStageSelectChngZoneSetInZoneScroll(DMS_STGSLCT_MAIN_WORK main_work, int stage)
	{
		uint num = dm_stgslct_zone_act_num_tbl[main_work.cur_zone][0];
		uint num2 = dm_stgslct_zone_act_num_tbl[main_work.cur_zone][1] + num;
		switch (main_work.cur_zone)
		{
		case 4u:
		{
			main_work.focus_disp_no = 0;
			for (uint num3 = num; num3 < num2; num3++)
			{
				main_work.act_top_pos_y[num3] = dm_stgslct_act_disp_y_pos_tbl[num3];
			}
			return;
		}
		case 5u:
		{
			int a = stage - 18;
			main_work.focus_disp_no = MTM_MATH_CLIP(a, 0, 4);
			for (uint num4 = num; num4 < num2; num4++)
			{
				main_work.act_top_pos_y[num4] = dm_stgslct_act_tab_disp_y_pos_tbl[main_work.focus_disp_no];
			}
			return;
		}
		}
		if (dmStgSlctIsBossFocus(main_work))
		{
			main_work.focus_disp_no = 1;
		}
		else
		{
			switch (stage)
			{
			case 3:
			case 7:
			case 11:
			case 15:
				main_work.focus_disp_no = 1;
				break;
			default:
				main_work.focus_disp_no = 0;
				break;
			}
		}
		for (uint num5 = num; num5 < num2; num5++)
		{
			main_work.act_top_pos_y[num5] = dm_stgslct_act_tab_disp_y_pos_tbl[main_work.focus_disp_no];
		}
	}

	private static void SyInitEvtSys(SYS_EVT_DATA[] evt_data, int evt_data_num, short start_evt_id, bool tcb_use, ushort pri, byte group)
	{
		if (tcb_use)
		{
			sy_evt_tcb = MTM_TASK_MAKE_TCB(syEvtSys, null, 3u, 0, pri, group, null, "SY_EVT_SYS");
		}
		sy_evt_info = new SYS_EVT_INFO();
		sy_evt_info.evt_data = evt_data;
		sy_evt_info.evt_data_num = evt_data_num;
		sy_evt_info.cur_evt_data = evt_data[0];
		sy_evt_info.next_evt_data = null;
		sy_evt_info.cur_evt_id = 0;
		sy_evt_info.req_evt_id = 0;
		sy_evt_info.flag = 0u;
		SyDecideEvt(start_evt_id);
		SyChangeNextEvt();
	}

	private static void SyExitEvtSys()
	{
		if (sy_evt_tcb != null)
		{
			mtTaskClearTcb(sy_evt_tcb);
			sy_evt_tcb = null;
		}
	}

	private static SYS_EVT_INFO SyGetEvtInfo()
	{
		return sy_evt_info;
	}

	public static void SyDecideEvtCase(short evt_case)
	{
		if (sy_evt_info.cur_evt_data.next_evt_id[evt_case] == 0)
		{
			evt_case = 0;
		}
		sy_evt_info.req_evt_case = evt_case;
		SyDecideEvt(sy_evt_info.cur_evt_data.next_evt_id[evt_case]);
	}

	private static void SyDecideEvtIdCase(short req_id)
	{
		int i;
		for (i = 0; i < 8 && sy_evt_info.cur_evt_data.next_evt_id[i] != 0 && sy_evt_info.cur_evt_data.next_evt_id[i] != req_id; i++)
		{
		}
		if (i >= 8 || sy_evt_info.cur_evt_data.next_evt_id[i] == 0)
		{
			req_id = sy_evt_info.cur_evt_data.next_evt_id[0];
		}
		SyDecideEvt(req_id);
	}

	private static void SyDecideEvt(short req_id)
	{
		if (req_id > 0 && sy_evt_info.evt_data_num > req_id)
		{
			sy_evt_info.req_evt_id = req_id;
			syDecideNextEvt();
		}
	}

	public static void SyChangeNextEvt()
	{
		SYS_EVT_DATA cur_evt_data = sy_evt_info.cur_evt_data;
		if (sy_evt_info.req_evt_id < 0)
		{
			sy_evt_info.req_evt_id = cur_evt_data.next_evt_id[0];
		}
		sy_evt_info.flag = 1u;
		sy_evt_info.arg_size = 0u;
		sy_evt_info.arg = new sbyte[8];
	}

	private static void SyChangeNextEvtArg(uint arg_size, sbyte[] arg_buf)
	{
		SyChangeNextEvt();
		if (arg_size > 8)
		{
			arg_size = 8u;
		}
		if (arg_size != 0)
		{
			Array.Copy(sy_evt_info.arg, arg_buf, (int)arg_size);
			arg_buf = new sbyte[arg_size];
			sy_evt_info.arg_size = arg_size;
		}
	}

	private static bool SYM_CHECK_EVT_DATA_BRUNCH(SYS_EVT_DATA _sy_evt_data)
	{
		if (0 >= _sy_evt_data.next_evt_id[1])
		{
			return false;
		}
		return true;
	}

	private static void syEvtSys(MTS_TASK_TCB tcb)
	{
		if (sy_evt_info.flag == 1)
		{
			SYS_EVT_DATA cur_evt_data = sy_evt_info.cur_evt_data;
			if (cur_evt_data.exit_func != null)
			{
				cur_evt_data.exit_func();
			}
			if (cur_evt_data.exit_sys_func != null)
			{
				cur_evt_data.exit_sys_func();
			}
			sy_evt_info.old_evt_id = sy_evt_info.cur_evt_id;
			sy_evt_info.cur_evt_id = sy_evt_info.req_evt_id;
			sy_evt_info.cur_evt_data = sy_evt_info.evt_data[sy_evt_info.cur_evt_id];
			cur_evt_data = sy_evt_info.cur_evt_data;
			sy_evt_info.req_evt_id = -1;
			if (!SYM_CHECK_EVT_DATA_BRUNCH(cur_evt_data))
			{
				sy_evt_info.req_evt_id = cur_evt_data.next_evt_id[0];
				syDecideNextEvt();
			}
			syEvtSysOvlCallBack();
		}
	}

	private static void syEvtSysOvlCallBack()
	{
		SYS_EVT_DATA cur_evt_data = sy_evt_info.cur_evt_data;
		sy_evt_info.flag = 0u;
		if (cur_evt_data.init_sys_func != null)
		{
			cur_evt_data.init_sys_func();
		}
		if (cur_evt_data.init_func != null)
		{
			sbyte[] obj = null;
			if (sy_evt_info.arg_size != 0)
			{
				obj = sy_evt_info.arg;
			}
			cur_evt_data.init_func(obj);
		}
	}

	private static void syDecideNextEvt()
	{
		if (sy_evt_info.req_evt_id < 0)
		{
			sy_evt_info.req_evt_id = sy_evt_info.cur_evt_data.next_evt_id[0];
		}
		sy_evt_info.next_evt_data = sy_evt_info.evt_data[sy_evt_info.req_evt_id];
	}

