	public static void AkMathGetRandomUnitVector(NNS_VECTOR dst_vec, float rand_z, short rand_angle)
	{
		dst_vec.x = nnSqrt(1f - rand_z * rand_z) * nnCos(rand_angle);
		dst_vec.y = nnSqrt(1f - rand_z * rand_z) * nnSin(rand_angle);
		dst_vec.z = rand_z;
	}

	public static void AkMathNormalizeMtx(NNS_MATRIX dst_mtx, NNS_MATRIX src_mtx)
	{
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR2 = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR3 = GlobalPool<NNS_VECTOR>.Alloc();
		amVectorSet(nNS_VECTOR, src_mtx.M00, src_mtx.M01, src_mtx.M02);
		amVectorSet(nNS_VECTOR2, src_mtx.M10, src_mtx.M11, src_mtx.M12);
		amVectorSet(nNS_VECTOR3, src_mtx.M20, src_mtx.M21, src_mtx.M22);
		nnMakeUnitMatrix(dst_mtx);
		float num = 1f / nnLengthVector(nNS_VECTOR);
		dst_mtx.M00 = nNS_VECTOR.x * num;
		dst_mtx.M01 = nNS_VECTOR.y * num;
		dst_mtx.M02 = nNS_VECTOR.z * num;
		num = 1f / nnLengthVector(nNS_VECTOR2);
		dst_mtx.M10 = nNS_VECTOR2.x * num;
		dst_mtx.M11 = nNS_VECTOR2.y * num;
		dst_mtx.M12 = nNS_VECTOR2.z * num;
		num = 1f / nnLengthVector(nNS_VECTOR3);
		dst_mtx.M20 = nNS_VECTOR3.x * num;
		dst_mtx.M21 = nNS_VECTOR3.y * num;
		dst_mtx.M22 = nNS_VECTOR3.z * num;
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR2);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR3);
	}

	private static void AkMathExtractScaleMtx(NNS_MATRIX dst_mtx, NNS_MATRIX src_mtx)
	{
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		amAssert(true);
		amVectorSet(nNS_VECTOR, src_mtx.M(0, 0), src_mtx.M(0, 1), src_mtx.M(0, 2));
		float x = nnLengthVector(nNS_VECTOR);
		amVectorSet(nNS_VECTOR, src_mtx.M(1, 0), src_mtx.M(1, 1), src_mtx.M(1, 2));
		float y = nnLengthVector(nNS_VECTOR);
		amVectorSet(nNS_VECTOR, src_mtx.M(2, 0), src_mtx.M(2, 1), src_mtx.M(2, 2));
		float z = nnLengthVector(nNS_VECTOR);
		nnMakeScaleMatrix(dst_mtx, x, y, z);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	public static void AkMathInvertYZQuaternion(out NNS_QUATERNION dst_quat, ref NNS_QUATERNION src_quat)
	{
		dst_quat = src_quat;
