		dst_quat.z = 0f - dst_quat.z;
	}

	public static void AkMathInvertXYQuaternion(out NNS_QUATERNION dst_quat, ref NNS_QUATERNION src_quat)
	{
		dst_quat = src_quat;
		dst_quat.x = 0f - dst_quat.x;
		dst_quat.y = 0f - dst_quat.y;
	}

	private static byte AkMathCountBitPopulation(uint bits)
	{
		bits -= (bits >> 1) & 0x55555555;
		bits = (bits & 0x33333333) + ((bits >> 2) & 0x33333333);
		bits = (bits + (bits >> 4)) & 0xF0F0F0F;
		bits += bits >> 8;
		bits += bits >> 16;
		return (byte)(bits & 0x3F);
	}

	private static OBS_OBJECT_WORK GmGmkPistonUpInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = gmGmkPistonInit(eve_rec, pos_x, pos_y, type);
		GMS_GMK_PISTON_WORK gMS_GMK_PISTON_WORK = (GMS_GMK_PISTON_WORK)oBS_OBJECT_WORK;
		gMS_GMK_PISTON_WORK.obj_type = 0u;
		gMS_GMK_PISTON_WORK.piston_vect = 32768;
		oBS_OBJECT_WORK.dir.z = 0;
		gMS_GMK_PISTON_WORK.gmk_work.ene_com.col_work.obj_col.flag |= 32u;
		if (eve_rec.top < 0)
		{
			gMS_GMK_PISTON_WORK.timer_set_move = -eve_rec.top * 2 << 12;
		}
		else if (eve_rec.top > 0)
		{
			gMS_GMK_PISTON_WORK.timer_set_move = eve_rec.top * 2 << 12;
		}
		oBS_OBJECT_WORK.ppFunc = gmGmkPistonStart;
		return oBS_OBJECT_WORK;
	}

	private static OBS_OBJECT_WORK GmGmkPistonDownInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = gmGmkPistonInit(eve_rec, pos_x, pos_y, type);
