		gMS_GMK_PISTON_WORK.gmk_work.ene_com.col_work.obj_col.ofst_x = GmkPistonData.tbl_gm_gmk_piston_col_rect[gMS_GMK_PISTON_WORK.obj_type][2];
		gMS_GMK_PISTON_WORK.gmk_work.ene_com.col_work.obj_col.ofst_y = GmkPistonData.tbl_gm_gmk_piston_col_rect[gMS_GMK_PISTON_WORK.obj_type][3];
		gMS_GMK_PISTON_WORK.gmk_work.ene_com.col_work.obj_col.dir = 0;
		gMS_GMK_PISTON_WORK.gmk_work.ene_com.col_work.obj_col.diff_data = g_gm_default_col;
		gMS_GMK_PISTON_WORK.gmk_work.ene_com.col_work.obj_col.flag |= 134217760u;
		gMS_GMK_PISTON_WORK.gmk_work.ene_com.rect_work[2].flag &= 4294967291u;
		gmGmkPistonRod_Create(obj_work);
		uint num = (uint)((gMS_GMK_PISTON_WORK.timer_set_move + (gMS_GMK_PISTON_WORK.stroke_spd - 1)) / gMS_GMK_PISTON_WORK.stroke_spd);
		uint num2 = gmGmkPistonSyncTimeGet(gMS_GMK_PISTON_WORK);
		if (num2 <= (uint)gMS_GMK_PISTON_WORK.timer_set_wait_lower)
		{
			gMS_GMK_PISTON_WORK.timer_dec = (int)(gMS_GMK_PISTON_WORK.timer_set_wait_lower - (num2 - 1));
			gmGmkPistonStay(obj_work);
			return;
		}
		num2 -= (uint)gMS_GMK_PISTON_WORK.timer_set_wait_lower;
		int num3 = ((gMS_GMK_PISTON_WORK.piston_vect == 0) ? gMS_GMK_PISTON_WORK.stroke_spd : (-gMS_GMK_PISTON_WORK.stroke_spd));
		if (num2 < num)
		{
			gMS_GMK_PISTON_WORK.timer_dec = gMS_GMK_PISTON_WORK.timer_set_move;
			while (num2 > 1)
			{
				gMS_GMK_PISTON_WORK.timer_dec -= gMS_GMK_PISTON_WORK.stroke_spd;
				obj_work.pos.y += num3;
				num2--;
			}
			gmGmkPistonStroke(obj_work);
			return;
		}
		num2 -= num;
		obj_work.pos.y += ((gMS_GMK_PISTON_WORK.piston_vect == 0) ? gMS_GMK_PISTON_WORK.timer_set_move : (-gMS_GMK_PISTON_WORK.timer_set_move));
		if (num2 <= (uint)gMS_GMK_PISTON_WORK.timer_set_wait_upper)
		{
			gMS_GMK_PISTON_WORK.timer_dec = (int)(gMS_GMK_PISTON_WORK.timer_set_wait_upper - (num2 - 1));
			gmGmkPistonTopDeadWait(obj_work);
			return;
		}
		num2 -= (uint)gMS_GMK_PISTON_WORK.timer_set_wait_upper;
		gMS_GMK_PISTON_WORK.timer_dec = gMS_GMK_PISTON_WORK.timer_set_move;
		while (num2 > 1)
		{
			gMS_GMK_PISTON_WORK.timer_dec -= gMS_GMK_PISTON_WORK.stroke_spd;
			obj_work.pos.y -= num3;
			num2--;
		}
		gmGmkPistonShrink(obj_work);
	}

