	private static void GmGmkBoss3PillarChangeModeActive(OBS_OBJECT_WORK obj_work, int pattern_no)
	{
		GMS_GMK_BOSS3_PILLAR_MANAGER_WORK gMS_GMK_BOSS3_PILLAR_MANAGER_WORK = (GMS_GMK_BOSS3_PILLAR_MANAGER_WORK)obj_work;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		float num = 80f;
		int num2 = g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id];
		if (num2 == 4)
		{
			num /= 1.5f;
		}
		for (int i = 0; 26 > i; i++)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = gMS_GMK_BOSS3_PILLAR_MANAGER_WORK.obj_work_pillar[i];
			int num3 = g_gm_gmk_boss3_pillar_move_distance[pattern_no][i] * 40;
			if (num3 == 0)
			{
				if (oBS_OBJECT_WORK != null)
				{
					oBS_OBJECT_WORK.flag |= 8u;
					GMS_GMK_BOSS3_PILLAR_MAIN_WORK gMS_GMK_BOSS3_PILLAR_MAIN_WORK = (GMS_GMK_BOSS3_PILLAR_MAIN_WORK)oBS_OBJECT_WORK;
					if (gMS_GMK_BOSS3_PILLAR_MAIN_WORK.effect_work != null)
					{
						ObjDrawKillAction3DES((OBS_OBJECT_WORK)gMS_GMK_BOSS3_PILLAR_MAIN_WORK.effect_work);
						gMS_GMK_BOSS3_PILLAR_MAIN_WORK.effect_work = null;
					}
					gMS_GMK_BOSS3_PILLAR_MANAGER_WORK.obj_work_pillar[i] = null;
				}
				continue;
			}
			if (oBS_OBJECT_WORK == null)
			{
				ushort id = (ushort)g_gm_gmk_boss3_pillar_event_id[i];
				oBS_OBJECT_WORK = GmEventMgrLocalEventBirth(id, obj_work.pos.x + g_gm_gmk_boss3_pillar_default_pos[i][0] * 40 * 4096, obj_work.pos.y + g_gm_gmk_boss3_pillar_default_pos[i][1] * 40 * 4096, gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag, gMS_ENEMY_3D_WORK.ene_com.eve_rec.left, gMS_ENEMY_3D_WORK.ene_com.eve_rec.top, gMS_ENEMY_3D_WORK.ene_com.eve_rec.width, gMS_ENEMY_3D_WORK.ene_com.eve_rec.height, 0);
				oBS_OBJECT_WORK.parent_obj = obj_work;
				gMS_GMK_BOSS3_PILLAR_MANAGER_WORK.obj_work_pillar[i] = oBS_OBJECT_WORK;
			}
			else
			{
				gmGmkBoss3PillarPartsChangeModeWait(oBS_OBJECT_WORK);
			}
			if (g_gm_gmk_boss3_pillar_flag_hit_effect[pattern_no][i] != 0)
			{
				oBS_OBJECT_WORK.user_flag |= 9u;
				gm_gmk_boss3_pillar_global_flag |= 8;
			}
			int wait_time = g_gm_gmk_boss3_pillar_wait_frame[pattern_no][i] * (int)num;
			gmGmkBoss3PillarPartsChangeModeNormal(oBS_OBJECT_WORK, (num3 + 16) * 4096, wait_time);
		}
		gMS_GMK_BOSS3_PILLAR_MANAGER_WORK.pattern_no = pattern_no;
		obj_work.user_timer = (int)((float)g_gm_gmk_boss3_pillar_frame_change_hurry[gMS_GMK_BOSS3_PILLAR_MANAGER_WORK.pattern_no] * num);
		obj_work.ppFunc = gmGmkBoss3PillarManagerMainFuncWaitHurry;
	}

	private static void GmGmkBoss3PillarChangeModeHurry(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_BOSS3_PILLAR_MANAGER_WORK gMS_GMK_BOSS3_PILLAR_MANAGER_WORK = (GMS_GMK_BOSS3_PILLAR_MANAGER_WORK)obj_work;
		for (int i = 0; 26 > i; i++)
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = gMS_GMK_BOSS3_PILLAR_MANAGER_WORK.obj_work_pillar[i];
			if (oBS_OBJECT_WORK != null)
