	private static void gmGmkBoss3PillarSetMoveTarget(OBS_OBJECT_WORK obj_work, uint pillar_type, int distance)
	{
		GMS_GMK_BOSS3_PILLAR_MAIN_WORK gMS_GMK_BOSS3_PILLAR_MAIN_WORK = (GMS_GMK_BOSS3_PILLAR_MAIN_WORK)obj_work;
		int num = FX_Mul(distance, g_gm_boss3_pillar_adjust_dir[pillar_type][0] * 4096);
		int num2 = FX_Mul(distance, g_gm_boss3_pillar_adjust_dir[pillar_type][1] * 4096);
		gMS_GMK_BOSS3_PILLAR_MAIN_WORK.target_pos.x = gMS_GMK_BOSS3_PILLAR_MAIN_WORK.default_pos.x + num;
		gMS_GMK_BOSS3_PILLAR_MAIN_WORK.target_pos.y = gMS_GMK_BOSS3_PILLAR_MAIN_WORK.default_pos.y + num2;
	}

	private static void gmGmkBoss3PillarSetMoveHurry(OBS_OBJECT_WORK obj_work, int frame)
	{
		GMS_GMK_BOSS3_PILLAR_MAIN_WORK gMS_GMK_BOSS3_PILLAR_MAIN_WORK = (GMS_GMK_BOSS3_PILLAR_MAIN_WORK)obj_work;
		if (frame <= 0)
		{
			obj_work.pos.Assign(gMS_GMK_BOSS3_PILLAR_MAIN_WORK.target_pos);
			obj_work.spd.x = 0;
			obj_work.spd.y = 0;
			return;
		}
		int numer = gMS_GMK_BOSS3_PILLAR_MAIN_WORK.target_pos.x - obj_work.pos.x;
		int numer2 = gMS_GMK_BOSS3_PILLAR_MAIN_WORK.target_pos.y - obj_work.pos.y;
		int x = FX_Div(numer, frame * 4096);
		int y = FX_Div(numer2, frame * 4096);
		obj_work.spd.x = x;
		obj_work.spd.y = y;
	}

	private static bool gmGmkBoss3PillarCheckMoveEnd(OBS_OBJECT_WORK obj_work, uint pillar_type)
	{
		UNREFERENCED_PARAMETER(pillar_type);
		GMS_GMK_BOSS3_PILLAR_MAIN_WORK gMS_GMK_BOSS3_PILLAR_MAIN_WORK = (GMS_GMK_BOSS3_PILLAR_MAIN_WORK)obj_work;
		bool result = false;
		int x = obj_work.spd.x;
		int y = obj_work.spd.y;
		if (x == 0 && y == 0)
		{
			result = true;
		}
		else
		{
			int num = gMS_GMK_BOSS3_PILLAR_MAIN_WORK.target_pos.x - obj_work.pos.x;
			int num2 = gMS_GMK_BOSS3_PILLAR_MAIN_WORK.target_pos.y - obj_work.pos.y;
			if ((x < 0 && num >= 0) || (x > 0 && num <= 0) || (y < 0 && num2 >= 0) || (y > 0 && num2 <= 0))
			{
				result = true;
			}
		}
		return result;
	}

	private static void gmBoss3PillarDestFunc(MTS_TASK_TCB tcb)
	{
		GMS_GMK_BOSS3_PILLAR_MAIN_WORK gMS_GMK_BOSS3_PILLAR_MAIN_WORK = (GMS_GMK_BOSS3_PILLAR_MAIN_WORK)mtTaskGetTcbWork(tcb);
