			gMS_GMK_BOSS3_PILLAR_MAIN_WORK.effect_work = null;
		}
		if (gMS_GMK_BOSS3_PILLAR_MAIN_WORK.se_handle != null)
		{
			GmSoundStopSE(gMS_GMK_BOSS3_PILLAR_MAIN_WORK.se_handle);
		}
		GMM_PAD_VIB_STOP();
		if (gMS_GMK_BOSS3_PILLAR_MAIN_WORK.se_handle != null)
