			GsSoundFreeSeHandle(gMS_GMK_BOSS3_PILLAR_MAIN_WORK.se_handle);
			gMS_GMK_BOSS3_PILLAR_MAIN_WORK.se_handle = null;
		}
		GmEnemyDefaultExit(tcb);
	}

	private static void gmBoss3PillarOutFunc(OBS_OBJECT_WORK obj_work)
	{
		if (GmMainIsDrawEnable() && (obj_work.disp_flag & 0x20) == 0)
		{
			GMS_GMK_BOSS3_PILLAR_MAIN_WORK gMS_GMK_BOSS3_PILLAR_MAIN_WORK = (GMS_GMK_BOSS3_PILLAR_MAIN_WORK)obj_work;
			GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
			uint num = gmGmkBoss3PillarCalcPillarType(gMS_ENEMY_3D_WORK.ene_com.eve_rec.id);
			int num2 = g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id];
			int num3 = 0;
			int[] array = null;
			int[] array2 = null;
			AMS_AMB_HEADER aMS_AMB_HEADER = g_gm_gmk_boss3_pillar_obj_tvx_list;
			switch (num2)
			{
			case 2:
				num3 = g_gm_gmk_boss3_pillar_parts_num[num];
				array = g_gm_boss3_pillar_parts_offset[num];
				array2 = g_gm_boss3_pillar_model_id[num];
				break;
			case 4:
			{
				num3 = g_gm_gmk_boss3_pillar_f_parts_num[num];
				array = g_gm_boss3_pillar_f_parts_offset[num];
				array2 = g_gm_boss3_pillar_f_model_id[num];
				int num6 = g_gm_boss3_pillar_f_sub_model_id[num];
				break;
			}
			}
			uint gMD_TVX_DISP_SCALE = GMD_TVX_DISP_SCALE;
			VecFx32 scale = default(VecFx32);
			scale.x = FX_F32_TO_FX32(1.25f);
			scale.y = FX_F32_TO_FX32(1.25f);
			scale.z = obj_work.scale.z;
			if ((obj_work.disp_flag & 1) != 0)
			{
				scale.x *= -1;
			}
			else if ((obj_work.disp_flag & 2) != 0)
			{
				scale.y *= -1;
			}
			TVX_FILE tVX_FILE;
			if (aMS_AMB_HEADER.buf[array2[0]] == null)
			{
				tVX_FILE = new TVX_FILE((AmbChunk)amBindGet(aMS_AMB_HEADER, array2[0]));
				aMS_AMB_HEADER.buf[array2[0]] = tVX_FILE;
			}
			else
			{
				tVX_FILE = (TVX_FILE)aMS_AMB_HEADER.buf[array2[0]];
			}
			GmTvxSetModel(tVX_FILE, obj_work.obj_3d.texlist, ref obj_work.pos, ref scale, gMD_TVX_DISP_SCALE, 0);
			for (int i = 1; num3 > i; i++)
			{
				int num4 = -array[i];
				int num5 = -array[i];
				num4 *= g_gm_boss3_pillar_adjust_dir[num][0] * 40;
				num5 *= g_gm_boss3_pillar_adjust_dir[num][1] * 40;
				VecFx32 pos = new VecFx32(obj_work.pos);
				pos.x += num4 * 4096;
				pos.y += num5 * 4096;
				tVX_FILE = new TVX_FILE((AmbChunk)amBindGet(aMS_AMB_HEADER, array2[i]));
				GmTvxSetModel(tVX_FILE, obj_work.obj_3d.texlist, ref pos, ref scale, gMD_TVX_DISP_SCALE, 0);
			}
		}
	}

	private static void gmGmkBoss3PillarPartsInitMain(OBS_OBJECT_WORK obj_work, uint pillar_type)
	{
		GMS_GMK_BOSS3_PILLAR_MAIN_WORK gMS_GMK_BOSS3_PILLAR_MAIN_WORK = (GMS_GMK_BOSS3_PILLAR_MAIN_WORK)obj_work;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col.obj = gMS_ENEMY_3D_WORK.ene_com.obj_work;
		gmGmkBoss3PillarSetFieldRect(gMS_ENEMY_3D_WORK.ene_com.col_work.obj_col, pillar_type);
		obj_work.disp_flag |= 67108864u;
		obj_work.flag |= 16u;
