	private static void gmGmkBoss3PillarPartsMainReady(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.user_timer > 0)
		{
			obj_work.user_timer--;
			return;
		}
		obj_work.move_flag &= 4294959103u;
		obj_work.ppFunc = gmGmkBoss3PillarPartsMainActive;
