			obj_work.user_flag &= 4294967291u;
			gm_gmk_boss3_pillar_global_flag = (int)(gm_gmk_boss3_pillar_global_flag & 0xFFFFFFFBu);
			GMM_PAD_VIB_SMALL_NOEND();
