		GMS_GMK_BOSS3_PILLAR_MAIN_WORK gMS_GMK_BOSS3_PILLAR_MAIN_WORK2 = (GMS_GMK_BOSS3_PILLAR_MAIN_WORK)obj_work;
		if (gMS_GMK_BOSS3_PILLAR_MAIN_WORK2.se_handle != null)
		{
			GmSoundStopSE(gMS_GMK_BOSS3_PILLAR_MAIN_WORK2.se_handle);
