			{
				GmSoundPlaySE("Boss3_02", gMS_GMK_BOSS3_PILLAR_MAIN_WORK2.se_handle);
				obj_work.user_flag &= 4294967287u;
				gm_gmk_boss3_pillar_global_flag = (int)(gm_gmk_boss3_pillar_global_flag & 0xFFFFFFF7u);
			}
		}
		gmGmkBoss3PillarPartsChangeModeWait(obj_work);
	}

