	private static void gmGmkBoss3PillarWallMainActive(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_BOSS3_PILLAR_WALL_WORK gMS_GMK_BOSS3_PILLAR_WALL_WORK = (GMS_GMK_BOSS3_PILLAR_WALL_WORK)obj_work;
		int num = gmGmkBoss3PillarWallCheckMoveEnd(gMS_GMK_BOSS3_PILLAR_WALL_WORK);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)g_gm_main_system.ply_work[0];
		if (obj_work.spd.y < 0 && MTM_MATH_ABS(oBS_OBJECT_WORK.pos.x - obj_work.pos.x) < 65536 && oBS_OBJECT_WORK.pos.y <= obj_work.pos.y && MTM_MATH_ABS(num) < 262144)
		{
			int num2 = g_gm_main_system.map_fcol.left + (g_gm_main_system.map_fcol.right - g_gm_main_system.map_fcol.left) / 2;
			if ((oBS_OBJECT_WORK.move_flag & 1) != 0)
			{
				int num3 = 16384;
				if (num2 * 4096 < oBS_OBJECT_WORK.pos.x)
				{
					num3 *= -1;
				}
				oBS_OBJECT_WORK.flow.x += num3;
			}
			else
			{
				int num4 = 4096;
				if (num2 * 4096 < oBS_OBJECT_WORK.pos.x)
				{
					num4 *= -1;
				}
				GmPlySeqGmkInitGmkJump((GMS_PLAYER_WORK)oBS_OBJECT_WORK, num4, 0);
				GmPlySeqChangeSequenceState((GMS_PLAYER_WORK)oBS_OBJECT_WORK, 17);
			}
		}
		if (num != 0)
		{
			return;
		}
		obj_work.pos.Assign(gMS_GMK_BOSS3_PILLAR_WALL_WORK.target_pos);
		gmGmkBoss3PillarWallChangeModeWait(obj_work);
		if ((obj_work.user_flag & 1) != 0)
		{
			gmGmkBoss3PillarEffectCreateWallHit(obj_work);
			obj_work.user_flag &= 4294967294u;
		}
		GMM_PAD_VIB_STOP();
		if ((obj_work.user_flag & 2) != 0)
		{
			GmCameraVibrationSet(0, 12288, 0);
			obj_work.user_flag &= 4294967293u;
		}
		if (gMS_GMK_BOSS3_PILLAR_WALL_WORK.se_handle != null)
		{
			GmSoundStopSE(gMS_GMK_BOSS3_PILLAR_WALL_WORK.se_handle);
			if ((obj_work.user_flag & 8) != 0)
			{
				GmSoundPlaySE("Boss3_02", gMS_GMK_BOSS3_PILLAR_WALL_WORK.se_handle);
				obj_work.user_flag &= 4294967287u;
			}
		}
	}

