		if (GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			obj_work.pos.z = -65536;
		}
		obj_work.ppFunc = null;
		obj_work.ppMove = null;
		obj_work.ppOut = gmGmkBobbinDrawFunc;
		gmGmkBobbinChangeModeWait(obj_work);
	}

	private static void gmGmkBobbinSetRect(GMS_ENEMY_3D_WORK gimmick_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gimmick_work;
		OBS_RECT_WORK oBS_RECT_WORK = gimmick_work.ene_com.rect_work[2];
		short cLeft = -24;
		short cRight = 24;
		short cTop = -24;
		short cBottom = 24;
		ObjRectWorkZSet(oBS_RECT_WORK, cLeft, cTop, -500, cRight, cBottom, 500);
		oBS_RECT_WORK.flag |= 1024u;
		ObjRectGroupSet(oBS_RECT_WORK, 1, 1);
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		oBS_RECT_WORK.ppDef = gmGmkBobbinDefFunc;
		if (GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			OBS_COLLISION_WORK col_work = ((GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK).ene_com.col_work;
			col_work.obj_col.obj = oBS_OBJECT_WORK;
			col_work.obj_col.diff_data = g_gm_default_col;
			col_work.obj_col.width = 16;
			col_work.obj_col.height = 16;
			col_work.obj_col.ofst_x = (short)(-(col_work.obj_col.width / 2));
			col_work.obj_col.ofst_y = (short)(-(col_work.obj_col.height / 2));
			col_work.obj_col.attr = 2;
			col_work.obj_col.flag |= 134217760u;
		}
	}

