	private static VecFx32 gmGmkBobbinNormalizeVectorXY(VecFx32 vec)
	{
		VecFx32 result = default(VecFx32);
		int num = FX_Mul(vec.x, vec.x) + FX_Mul(vec.y, vec.y);
		if (num == 0)
		{
			result.x = 4096;
			result.y = 0;
		}
		else
		{
			num = FX_Sqrt(num);
			int v = FX_Div(4096, num);
			result.x = FX_Mul(vec.x, v);
			result.y = FX_Mul(vec.y, v);
		}
		result.z = 0;
		if (GSM_MAIN_STAGE_IS_SPSTAGE())
		{
			int dest_x = 0;
			int dest_y = 0;
			ObjUtilGetRotPosXY(result.x, result.y, ref dest_x, ref dest_y, (ushort)(-g_gm_main_system.pseudofall_dir));
			result.x = dest_x;
			result.y = dest_y;
		}
		return result;
	}

	private static void gmGmkBobbinDefPlayer(GMS_ENEMY_3D_WORK gimmick_work, GMS_PLAYER_WORK player_work, int speed_x, int speed_y)
	{
		bool flag_no_recover_homing = false;
		if ((gimmick_work.ene_com.eve_rec.flag & 1) != 0)
		{
			flag_no_recover_homing = true;
		}
		GmPlySeqInitPinballAir(player_work, speed_x, speed_y, 5, flag_no_recover_homing);
		if (!GMM_MAIN_STAGE_IS_SS())
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gimmick_work;
			GmPlayerAddScore(player_work, 10, oBS_OBJECT_WORK.pos.x, oBS_OBJECT_WORK.pos.y);
		}
	}

	private static void gmGmkBobbinDefEnemy(OBS_OBJECT_WORK obj_work, int speed_x, int speed_y)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if (gMS_ENEMY_3D_WORK.ene_com.eve_rec.id == 316)
		{
			obj_work.spd.x = speed_x;
			obj_work.spd.y = speed_y;
			obj_work.spd_add.x = 0;
			obj_work.spd_add.y = 0;
			if ((long)MTM_MATH_ABS(obj_work.spd.x) < 256L)
			{
				obj_work.spd.x = 256;
			}
			else if ((long)MTM_MATH_ABS(obj_work.spd.y) < 256L)
			{
				obj_work.spd.y = 256;
			}
		}
	}

	private static void gmGmkBobbinDefFunc(OBS_RECT_WORK gimmick_rect, OBS_RECT_WORK player_rect)
	{
		OBS_OBJECT_WORK parent_obj = gimmick_rect.parent_obj;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)parent_obj;
		OBS_OBJECT_WORK parent_obj2 = player_rect.parent_obj;
		VecFx32 vec = new VecFx32
		{
			x = parent_obj2.prev_pos.x - parent_obj.pos.x,
			y = (int)((long)parent_obj2.prev_pos.y + -12288L - parent_obj.pos.y),
			z = 0
		};
		int num = FX_Mul(vec.x, vec.x) + FX_Mul(vec.y, vec.y);
		if (FX_Mul(114688, 114688) < num)
		{
			gimmick_rect.flag &= 4294966271u;
			return;
		}
		gimmick_rect.flag |= 1024u;
		vec = gmGmkBobbinNormalizeVectorXY(vec);
		parent_obj2.dir.z = 0;
		int v = FX_Mul(vec.x, 24576);
		int v2 = FX_Mul(vec.y, 24576);
		int num2 = FX_F32_TO_FX32((100f + (float)gMS_ENEMY_3D_WORK.ene_com.eve_rec.left) * 0.01f);
		if (num2 < 0)
		{
			num2 = 0;
		}
		int num3 = FX_F32_TO_FX32((100f + (float)gMS_ENEMY_3D_WORK.ene_com.eve_rec.top) * 0.01f);
		if (num3 < 0)
		{
			num3 = 0;
		}
		v = FX_Mul(v, num2);
		v2 = FX_Mul(v2, num3);
		if (parent_obj2.obj_type == 1)
		{
			gmGmkBobbinDefPlayer(gMS_ENEMY_3D_WORK, (GMS_PLAYER_WORK)parent_obj2, v, v2);
		}
		else if (parent_obj2.obj_type == 2)
		{
			gmGmkBobbinDefEnemy(parent_obj2, v, v2);
		}
		gmGmkBobbinChangeModeHit(parent_obj);
		GmSoundPlaySE("Casino1");
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctCmnEsCreate(parent_obj, 16);
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.x = parent_obj2.pos.x;
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.y = parent_obj2.pos.y;
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.z = 131072;
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.dir.z = (ushort)(nnArcTan2(FX_FX32_TO_F32(v2), FX_FX32_TO_F32(v)) - 16384);
		if (GSM_MAIN_STAGE_IS_SPSTAGE_NOT_RETRY())
		{
			OBS_CAMERA oBS_CAMERA = ObjCameraGet(g_obj.glb_camera_id);
			if (oBS_CAMERA != null)
			{
				gMS_EFFECT_3DES_WORK.efct_com.obj_work.dir.z -= (ushort)oBS_CAMERA.roll;
			}
		}
		GMM_PAD_VIB_SMALL();
	}

