	private static OBS_OBJECT_WORK GmEffectCreateWork(TaskWorkFactoryDelegate work_size, OBS_OBJECT_WORK parent_obj, ushort sort_prio)
	{
		if (work_size == null)
		{
			work_size = _GmEffectCreateWork_Delegate;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = OBM_OBJECT_TASK_DETAIL_INIT((ushort)(6656 + sort_prio), 3, 0, 0, work_size, null);
		if (oBS_OBJECT_WORK == null)
		{
			return null;
		}
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, _GmEffectDefaultExit);
		oBS_OBJECT_WORK.obj_type = 5;
		oBS_OBJECT_WORK.ppOut = _ObjDrawActionSummaryDelegate;
		oBS_OBJECT_WORK.ppOutSub = null;
		oBS_OBJECT_WORK.ppIn = null;
		oBS_OBJECT_WORK.ppMove = _ObjObjectMoveDelegate;
		oBS_OBJECT_WORK.ppActCall = null;
		oBS_OBJECT_WORK.ppRec = _gmEffectDefaultRecFuncDelegate;
		oBS_OBJECT_WORK.ppLast = null;
		oBS_OBJECT_WORK.spd_fall = 672;
		oBS_OBJECT_WORK.spd_fall_max = 61440;
		if (parent_obj != null)
		{
			oBS_OBJECT_WORK.parent_obj = parent_obj;
			oBS_OBJECT_WORK.pos.x = parent_obj.pos.x;
			oBS_OBJECT_WORK.pos.y = parent_obj.pos.y;
			oBS_OBJECT_WORK.pos.z = parent_obj.pos.z;
		}
		oBS_OBJECT_WORK.disp_flag |= 256u;
		oBS_OBJECT_WORK.flag |= 18u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		oBS_OBJECT_WORK.flag |= 1u;
		return oBS_OBJECT_WORK;
