	private static GMS_EFFECT_3DES_WORK GmEffect3dESCreateByParam(GMS_EFFECT_CREATE_PARAM create_param, OBS_OBJECT_WORK parent_obj, object arc, OBS_DATA_WORK ame_dwork, OBS_DATA_WORK ambtex_dwork, OBS_DATA_WORK texlist_dwork, OBS_DATA_WORK model_dwork, OBS_DATA_WORK object_dwork)
	{
		return GmEffect3dESCreateByParam(create_param, parent_obj, arc, ame_dwork, ambtex_dwork, texlist_dwork, model_dwork, object_dwork, _GmEffect3dESTaskDelegate);
