	private static GMS_EFFECT_3DES_WORK GmEffect3dESCreateByParam(GMS_EFFECT_CREATE_PARAM create_param, OBS_OBJECT_WORK parent_obj, object arc, OBS_DATA_WORK ame_dwork, OBS_DATA_WORK ambtex_dwork, OBS_DATA_WORK texlist_dwork, OBS_DATA_WORK model_dwork, OBS_DATA_WORK object_dwork, TaskWorkFactoryDelegate work_size)
	{
		if (work_size == null)
		{
			work_size = () => new GMS_EFFECT_3DES_WORK();
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(work_size, parent_obj, 0, "EF_3DES_CREATE_BY_PARAM");
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = (GMS_EFFECT_3DES_WORK)oBS_OBJECT_WORK;
		ObjObjectAction3dESEffectLoad(oBS_OBJECT_WORK, gMS_EFFECT_3DES_WORK.obj_3des, ame_dwork, null, create_param.ame_idx, (AMS_AMB_HEADER)arc);
		ObjObjectAction3dESTextureLoad(oBS_OBJECT_WORK, oBS_OBJECT_WORK.obj_3des, ambtex_dwork, null, 0, null, false);
		ObjObjectAction3dESTextureSetByDwork(oBS_OBJECT_WORK, texlist_dwork);
		if (model_dwork != null && create_param.model_idx != -1)
		{
			ObjObjectAction3dESModelLoad(oBS_OBJECT_WORK, oBS_OBJECT_WORK.obj_3des, model_dwork, null, 0, null, 0u, false);
			if (object_dwork != null)
			{
				ObjObjectAction3dESModelSetByDwork(oBS_OBJECT_WORK, object_dwork);
			}
		}
		GmEffect3DESSetupBase(gMS_EFFECT_3DES_WORK, create_param.pos_type, create_param.init_flag);
		GmEffect3DESSetDispOffset(gMS_EFFECT_3DES_WORK, create_param.disp_ofst.x, create_param.disp_ofst.y, create_param.disp_ofst.z);
		GmEffect3DESSetDispRotation(gMS_EFFECT_3DES_WORK, create_param.disp_rot.x, create_param.disp_rot.y, create_param.disp_rot.z);
		GmEffect3DESSetScale(gMS_EFFECT_3DES_WORK, create_param.scale);
		oBS_OBJECT_WORK.ppFunc = create_param.main_func;
		return gMS_EFFECT_3DES_WORK;
	}

	private static GMS_EFFECT_3DES_WORK GmEffect3dESCreateDummy(OBS_OBJECT_WORK parent_obj)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_EFFECT_3DES_WORK(), parent_obj, 0, "EF_3DES_DUMMY");
		oBS_OBJECT_WORK.disp_flag |= 8u;
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = (GMS_EFFECT_3DES_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.obj_3des = gMS_EFFECT_3DES_WORK.obj_3des;
		oBS_OBJECT_WORK.ppOut = null;
		oBS_OBJECT_WORK.ppFunc = GmEffectDefaultMainFuncDeleteAtEnd;
		return gMS_EFFECT_3DES_WORK;
	}

	private static void GmEffectRectInit(GMS_EFFECT_COM_WORK efct_com, ushort[] atk_flag_tbl, ushort[] def_flag_tbl, byte my_group, byte target_group_flag)
	{
		OBS_OBJECT_WORK obj_work = efct_com.obj_work;
		ObjObjectGetRectBuf(obj_work, efct_com.rect_work, 2);
		for (int i = 0; i < 2; i++)
		{
			ObjRectGroupSet(efct_com.rect_work[i], my_group, target_group_flag);
			ObjRectAtkSet(efct_com.rect_work[i], atk_flag_tbl[i], 1);
			ObjRectDefSet(efct_com.rect_work[i], def_flag_tbl[i], 0);
			efct_com.rect_work[i].parent_obj = obj_work;
			efct_com.rect_work[i].flag &= 4294967291u;
		}
		efct_com.rect_work[0].ppDef = GmEffectDefaultDefFunc;
		efct_com.rect_work[1].ppHit = GmEffectDefaultAtkFunc;
	}

