	private static void GmEffect3DESSetupBase(GMS_EFFECT_3DES_WORK efct_3des, uint pos_type, uint init_flag)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)efct_3des;
		OBS_ACTION3D_ES_WORK obj_3des = oBS_OBJECT_WORK.obj_3des;
		efct_3des.saved_pos_type = pos_type;
		efct_3des.saved_init_flag = init_flag;
		switch (pos_type)
		{
		case 0u:
			obj_3des.flag &= 4294967294u;
			obj_3des.flag &= 4294967293u;
			break;
		case 1u:
			obj_3des.flag |= 1u;
			obj_3des.flag &= 4294967293u;
			break;
		case 2u:
			obj_3des.flag |= 1u;
			obj_3des.flag |= 2u;
			break;
		default:
			mppAssertNotImpl();
			break;
		}
		if ((init_flag & 1) != 0)
		{
			oBS_OBJECT_WORK.disp_flag |= 4194304u;
		}
		else
		{
			oBS_OBJECT_WORK.disp_flag &= 4290772991u;
		}
		if ((init_flag & 2) != 0)
		{
			oBS_OBJECT_WORK.flag |= 1024u;
		}
		else
		{
			oBS_OBJECT_WORK.flag &= 4294966271u;
		}
		if ((init_flag & 4) != 0)
		{
			obj_3des.flag |= 8u;
		}
		else
		{
			obj_3des.flag &= 4294967287u;
		}
		if ((init_flag & 0x10) != 0)
		{
			oBS_OBJECT_WORK.disp_flag &= 4294967039u;
		}
		else
		{
			oBS_OBJECT_WORK.disp_flag |= 256u;
		}
		if ((init_flag & 0x40) != 0)
		{
			obj_3des.flag |= 16u;
		}
		else
		{
			obj_3des.flag &= 4294967279u;
		}
		if ((init_flag & 0x20) != 0)
		{
			oBS_OBJECT_WORK.flag &= 4294443007u;
		}
		else
		{
			oBS_OBJECT_WORK.flag |= 524288u;
		}
		oBS_OBJECT_WORK.ppFunc = _GmEffectDefaultMainFuncDeleteAtEnd;
	}

	private static void GmEffect3DESChangeBase(GMS_EFFECT_3DES_WORK efct_3des, uint pos_type, uint init_flag)
	{
		OBS_OBJECT_WORK obj_work = efct_3des.efct_com.obj_work;
		MPP_VOID_OBS_OBJECT_WORK ppFunc = obj_work.ppFunc;
		obj_work.ppFunc = null;
		GmEffect3DESSetupBase(efct_3des, pos_type, init_flag);
		obj_work.ppFunc = ppFunc;
	}

