	private static int GmBsCmnIsActionEndFlexibly(OBS_OBJECT_WORK obj_work, float allow_ratio)
	{
		OBS_ACTION3D_NN_WORK obj_3d = obj_work.obj_3d;
		float num = obj_3d.speed[0] * FX_FX32_TO_F32(g_obj.speed);
		float overrun_frame = 0f;
		if ((obj_work.disp_flag & 8) != 0)
		{
			return 1;
		}
		gmBsCmnCheckActionFrameOverrunOnNextUpdate(obj_work, ref overrun_frame);
		if (overrun_frame > num * allow_ratio)
		{
			return GmBsCmnIsActionEndPrecisely(obj_work);
		}
		return GmBsCmnIsActionEnd(obj_work);
	}

