	private static int GmBsCmnCheckRectMajorOverlapH(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect, ref int center_ofst_x)
	{
		int lLeft = 0;
		int num = 0;
		int num2 = 0;
		int lLeft2 = 0;
		int num3 = 0;
		int num4 = 0;
		ushort usWidth = 0;
		ushort usWidth2 = 0;
		int result = 0;
		ObjRectLTBSet(my_rect, ref lLeft, null, null);
		ObjRectWHDSet(my_rect, ref usWidth, null, null);
		num = lLeft + usWidth;
		num2 = lLeft + (usWidth >> 1);
		ObjRectLTBSet(your_rect, ref lLeft2, null, null);
		ObjRectWHDSet(your_rect, ref usWidth2, null, null);
		num3 = lLeft2 + usWidth2;
		num4 = lLeft2 + (usWidth2 >> 1);
		if (num2 < num4)
		{
			if (num >= num4 || num2 >= lLeft2)
			{
				result = 1;
			}
		}
		else if (num4 < num2)
		{
			if (num3 >= num2 || num4 >= lLeft)
			{
				result = 1;
			}
		}
		else
		{
			result = 1;
		}
		if (center_ofst_x != 0)
		{
			center_ofst_x = num4 - num2 << 12;
		}
		return result;
	}

	private static int GmBsCmnCheckRectMajorOverlapV(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect, ref int center_ofst_y)
	{
		int lTop = 0;
		int lTop2 = 0;
		ushort usHeight = 0;
		ushort num = 0;
		int result = 0;
		ObjRectLTBSet(my_rect, null, ref lTop, null);
		ObjRectWHDSet(my_rect, null, ref usHeight, null);
		int num2 = lTop + usHeight;
		int num3 = lTop + (usHeight >> 1);
		ObjRectLTBSet(your_rect, null, ref lTop2, null);
		ushort usHeight2 = 0;
		ObjRectWHDSet(your_rect, null, ref usHeight2, null);
		num = usHeight2;
		int num4 = lTop2 + num;
		int num5 = lTop2 + (num >> 1);
		if (num3 < num5)
		{
			if (num2 >= num5 || num3 >= lTop2)
			{
				result = 1;
			}
		}
		else if (num5 < num3)
		{
			if (num4 >= num3 || num5 >= lTop)
			{
				result = 1;
			}
		}
		else
		{
			result = 1;
		}
		if (center_ofst_y != 0)
		{
			center_ofst_y = num5 - num3 << 12;
		}
		return result;
	}

	private uint GmBsCmnCheckRectHitSideHFirst(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		int center_ofst_x = 0;
		int center_ofst_y = 0;
		int num = GmBsCmnCheckRectMajorOverlapH(my_rect, your_rect, ref center_ofst_x);
		GmBsCmnCheckRectMajorOverlapV(my_rect, your_rect, ref center_ofst_y);
		if (num != 0)
		{
			if (center_ofst_y < 0)
			{
				return GMD_BS_CMN_RECT_HIT_SIDE_LEFT;
			}
			return GMD_BS_CMN_RECT_HIT_SIDE_RIGHT;
		}
		if (center_ofst_x < 0)
		{
			return GMD_BS_CMN_RECT_HIT_SIDE_TOP;
		}
		return GMD_BS_CMN_RECT_HIT_SIDE_BOTTOM;
	}

	public static uint GmBsCmnCheckRectHitSideVFirst(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		int center_ofst_x = 0;
		int center_ofst_y = 0;
		int num = GmBsCmnCheckRectMajorOverlapV(my_rect, your_rect, ref center_ofst_y);
		GmBsCmnCheckRectMajorOverlapH(my_rect, your_rect, ref center_ofst_x);
		if (num != 0)
		{
			if (center_ofst_x < 0)
			{
				return GMD_BS_CMN_RECT_HIT_SIDE_LEFT;
			}
			return GMD_BS_CMN_RECT_HIT_SIDE_RIGHT;
		}
		if (center_ofst_y < 0)
		{
			return GMD_BS_CMN_RECT_HIT_SIDE_TOP;
		}
		return GMD_BS_CMN_RECT_HIT_SIDE_BOTTOM;
	}

	private static void GmBsCmnInitBossMotionCBSystem(OBS_OBJECT_WORK obj_work, GMS_BS_CMN_BMCB_MGR bmcb_mgr)
	{
		bmcb_mgr.Clear();
		bmcb_mgr.bmcb_head.next = bmcb_mgr.bmcb_tail;
		bmcb_mgr.bmcb_head.prev = null;
		bmcb_mgr.bmcb_tail.next = null;
		bmcb_mgr.bmcb_tail.prev = bmcb_mgr.bmcb_head;
		obj_work.obj_3d.mtn_cb_func = gmBsCmnBossMotionCallbackFunc;
		obj_work.obj_3d.mtn_cb_param = bmcb_mgr;
	}

	private static void GmBsCmnClearBossMotionCBSystem(OBS_OBJECT_WORK obj_work)
	{
		GMS_BS_CMN_BMCB_MGR gMS_BS_CMN_BMCB_MGR = (GMS_BS_CMN_BMCB_MGR)obj_work.obj_3d.mtn_cb_param;
		if (gMS_BS_CMN_BMCB_MGR == null)
		{
			return;
		}
		GMS_BS_CMN_BMCB_LINK gMS_BS_CMN_BMCB_LINK = gMS_BS_CMN_BMCB_MGR.bmcb_head.next;
		while (gMS_BS_CMN_BMCB_LINK != null)
		{
			GMS_BS_CMN_BMCB_LINK next = gMS_BS_CMN_BMCB_LINK.next;
			gMS_BS_CMN_BMCB_LINK.next = null;
			gMS_BS_CMN_BMCB_LINK.prev = null;
			if (gMS_BS_CMN_BMCB_LINK.bmcb_func == null)
			{
				break;
			}
			gMS_BS_CMN_BMCB_LINK = next;
		}
		gMS_BS_CMN_BMCB_MGR.bmcb_head.next = (gMS_BS_CMN_BMCB_MGR.bmcb_head.prev = null);
		gMS_BS_CMN_BMCB_MGR.bmcb_tail.next = (gMS_BS_CMN_BMCB_MGR.bmcb_tail.prev = null);
		gMS_BS_CMN_BMCB_MGR.Clear();
		obj_work.obj_3d.mtn_cb_func = null;
		obj_work.obj_3d.mtn_cb_param = null;
	}

	private static void GmBsCmnAppendBossMotionCallback(GMS_BS_CMN_BMCB_MGR bmcb_mgr, GMS_BS_CMN_BMCB_LINK bmcb_link)
	{
		bmcb_link.prev = bmcb_mgr.bmcb_tail.prev;
		bmcb_link.prev.next = bmcb_link;
		bmcb_link.next = bmcb_mgr.bmcb_tail;
		bmcb_mgr.bmcb_tail.prev = bmcb_link;
	}

