	private static void GmBsCmnUpdateObject3DNNStuckWithNode(OBS_OBJECT_WORK obj_work, GMS_BS_CMN_SNM_WORK snm_work, int snm_reg_id, int b_rotation, NNS_MATRIX ofst_mtx)
	{
		NNS_MATRIX user_obj_mtx_r = obj_work.obj_3d.user_obj_mtx_r;
		NNS_MATRIX nNS_MATRIX = GmBsCmnGetSNMMtx(snm_work, snm_reg_id);
		obj_work.pos.x = FX_F32_TO_FX32(nNS_MATRIX.M03);
		obj_work.pos.y = -FX_F32_TO_FX32(nNS_MATRIX.M13);
		obj_work.pos.z = FX_F32_TO_FX32(nNS_MATRIX.M23);
		if (b_rotation != 0)
		{
			obj_work.disp_flag |= 16777216u;
			AkMathNormalizeMtx(user_obj_mtx_r, nNS_MATRIX);
		}
		else
		{
			obj_work.disp_flag &= 4278190079u;
			nnMakeUnitMatrix(user_obj_mtx_r);
		}
		if (ofst_mtx != null)
		{
			NNS_MATRIX gmBsCmnUpdateObject3DNNStuckWithNode_rot_mtx = GmBsCmnUpdateObject3DNNStuckWithNode_rot_mtx;
			NNS_VECTOR nNS_VECTOR = new NNS_VECTOR();
			NNS_MATRIX gmBsCmnUpdateObject3DNNStuckWithNode_node_w_rot = GmBsCmnUpdateObject3DNNStuckWithNode_node_w_rot;
			nnCopyMatrix(gmBsCmnUpdateObject3DNNStuckWithNode_node_w_rot, nNS_MATRIX);
			gmBsCmnUpdateObject3DNNStuckWithNode_node_w_rot.M03 = (gmBsCmnUpdateObject3DNNStuckWithNode_node_w_rot.M13 = (gmBsCmnUpdateObject3DNNStuckWithNode_node_w_rot.M23 = 0f));
			nnMultiplyMatrix(gmBsCmnUpdateObject3DNNStuckWithNode_node_w_rot, gmBsCmnUpdateObject3DNNStuckWithNode_node_w_rot, ofst_mtx);
			nnCopyMatrixTranslationVector(nNS_VECTOR, gmBsCmnUpdateObject3DNNStuckWithNode_node_w_rot);
			VEC_Set(ref obj_work.pos, obj_work.pos.x + FX_F32_TO_FX32(nNS_VECTOR.x), obj_work.pos.y - FX_F32_TO_FX32(nNS_VECTOR.y), obj_work.pos.z + FX_F32_TO_FX32(nNS_VECTOR.z));
			nnCopyMatrix(gmBsCmnUpdateObject3DNNStuckWithNode_rot_mtx, ofst_mtx);
			gmBsCmnUpdateObject3DNNStuckWithNode_rot_mtx.M03 = (gmBsCmnUpdateObject3DNNStuckWithNode_rot_mtx.M13 = (gmBsCmnUpdateObject3DNNStuckWithNode_rot_mtx.M23 = 0f));
			obj_work.disp_flag |= 16777216u;
			nnMultiplyMatrix(user_obj_mtx_r, user_obj_mtx_r, gmBsCmnUpdateObject3DNNStuckWithNode_rot_mtx);
		}
	}

