	private static void GmBsCmnUpdateObject3DESStuckWithNode(OBS_OBJECT_WORK obj_work, GMS_BS_CMN_SNM_WORK snm_work, int snm_reg_id, int b_rotation, NNS_MATRIX ofst_mtx)
	{
		NNS_MATRIX gmBsCmnUpdateObject3DESStuckWithNode_nml_w_mtx = GmBsCmnUpdateObject3DESStuckWithNode_nml_w_mtx;
		NNS_QUATERNION dst = obj_work.obj_3des.user_dir_quat;
		NNS_MATRIX nNS_MATRIX = GmBsCmnGetSNMMtx(snm_work, snm_reg_id);
		obj_work.pos.x = FX_F32_TO_FX32(nNS_MATRIX.M03);
		obj_work.pos.y = -FX_F32_TO_FX32(nNS_MATRIX.M13);
		obj_work.pos.z = FX_F32_TO_FX32(nNS_MATRIX.M23);
		if (b_rotation != 0)
		{
			obj_work.obj_3des.flag |= 32u;
			AkMathNormalizeMtx(gmBsCmnUpdateObject3DESStuckWithNode_nml_w_mtx, nNS_MATRIX);
			nnMakeRotateMatrixQuaternion(out dst, gmBsCmnUpdateObject3DESStuckWithNode_nml_w_mtx);
		}
		else
		{
			obj_work.obj_3des.flag &= 4294967263u;
			nnMakeUnitQuaternion(ref dst);
			nnMakeUnitMatrix(gmBsCmnUpdateObject3DESStuckWithNode_nml_w_mtx);
		}
		if (ofst_mtx != null)
		{
			NNS_MATRIX gmBsCmnUpdateObject3DESStuckWithNode_rot_mtx = GmBsCmnUpdateObject3DESStuckWithNode_rot_mtx;
			NNS_QUATERNION dst2 = default(NNS_QUATERNION);
			NNS_VECTOR nNS_VECTOR = new NNS_VECTOR();
			NNS_MATRIX gmBsCmnUpdateObject3DESStuckWithNode_node_w_rot = GmBsCmnUpdateObject3DESStuckWithNode_node_w_rot;
			nnCopyMatrix(gmBsCmnUpdateObject3DESStuckWithNode_node_w_rot, nNS_MATRIX);
			gmBsCmnUpdateObject3DESStuckWithNode_node_w_rot.M03 = (gmBsCmnUpdateObject3DESStuckWithNode_node_w_rot.M13 = (gmBsCmnUpdateObject3DESStuckWithNode_node_w_rot.M23 = 0f));
			nnMultiplyMatrix(gmBsCmnUpdateObject3DESStuckWithNode_node_w_rot, gmBsCmnUpdateObject3DESStuckWithNode_node_w_rot, ofst_mtx);
			nnCopyMatrixTranslationVector(nNS_VECTOR, gmBsCmnUpdateObject3DESStuckWithNode_node_w_rot);
			VEC_Set(ref obj_work.pos, obj_work.pos.x + FX_F32_TO_FX32(nNS_VECTOR.x), obj_work.pos.y - FX_F32_TO_FX32(nNS_VECTOR.y), obj_work.pos.z + FX_F32_TO_FX32(nNS_VECTOR.z));
			AkMathNormalizeMtx(gmBsCmnUpdateObject3DESStuckWithNode_rot_mtx, ofst_mtx);
			nnMakeRotateMatrixQuaternion(out dst2, gmBsCmnUpdateObject3DESStuckWithNode_rot_mtx);
			obj_work.obj_3des.flag |= 32u;
			nnMultiplyQuaternion(ref dst, ref dst, ref dst2);
		}
		obj_work.obj_3des.user_dir_quat.Assign(dst);
	}

