	private static void GmBsCmnUpdateCNMParam(OBS_OBJECT_WORK obj_work, GMS_BS_CMN_CNM_MGR_WORK cnm_mgr_work)
	{
		if (obj_work.obj_3d.mplt_cb_func != null)
		{
			GMS_BS_CMN_CNM_PARAM gMS_BS_CMN_CNM_PARAM = amDrawAlloc_GMS_BS_CMN_CNM_PARAM();
			gMS_BS_CMN_CNM_PARAM.reg_node_cnt = cnm_mgr_work.reg_node_cnt;
			GMS_BS_CMN_CNM_NODE_INFO[] array = amDrawAlloc_GMS_BS_CMN_CNM_NODE_INFO(cnm_mgr_work.reg_node_max);
			for (int i = 0; i < cnm_mgr_work.reg_node_max; i++)
			{
				array[i] = amDrawAlloc_GMS_BS_CMN_CNM_NODE_INFO();
				array[i].Assign(cnm_mgr_work.node_info_list[i]);
			}
			OBS_ACTION3D_NN_WORK.CMPLT_Wrapper cMPLT_Wrapper = new OBS_ACTION3D_NN_WORK.CMPLT_Wrapper();
			cMPLT_Wrapper.m_pInfos = array;
			cMPLT_Wrapper.reg_node_cnt = cnm_mgr_work.reg_node_cnt;
			obj_work.obj_3d.mplt_cb_param = cMPLT_Wrapper;
		}
	}

