	private static GMS_BS_CMN_NODE_CTRL_OBJECT GmBsCmnCreateNodeControlObjectBySize(OBS_OBJECT_WORK parent_obj, GMS_BS_CMN_CNM_MGR_WORK cnm_mgr_work, int cnm_reg_id, GMS_BS_CMN_SNM_WORK snm_work, int snm_reg_id, TaskWorkFactoryDelegate work_size)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(work_size, parent_obj, 0, "bs_cmn_node_ctl_obj");
		GMS_BS_CMN_NODE_CTRL_OBJECT gMS_BS_CMN_NODE_CTRL_OBJECT = (GMS_BS_CMN_NODE_CTRL_OBJECT)oBS_OBJECT_WORK;
		gMS_BS_CMN_NODE_CTRL_OBJECT.cnm_mgr_work = cnm_mgr_work;
		gMS_BS_CMN_NODE_CTRL_OBJECT.cnm_reg_id = cnm_reg_id;
		gMS_BS_CMN_NODE_CTRL_OBJECT.snm_work = snm_work;
		gMS_BS_CMN_NODE_CTRL_OBJECT.snm_reg_id = snm_reg_id;
		gMS_BS_CMN_NODE_CTRL_OBJECT.is_enable = 0;
		nnMakeUnitMatrix(gMS_BS_CMN_NODE_CTRL_OBJECT.w_mtx);
		oBS_OBJECT_WORK.disp_flag |= 32u;
		oBS_OBJECT_WORK.ppOut = null;
		oBS_OBJECT_WORK.ppFunc = gmBsCmnNodeControlObjectMainFunc;
		return gMS_BS_CMN_NODE_CTRL_OBJECT;
	}

	private static void GmBsCmnAttachNCObjectToSNMNode(GMS_BS_CMN_NODE_CTRL_OBJECT ndc_obj)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)ndc_obj;
		NNS_VECTOR nNS_VECTOR = new NNS_VECTOR();
		NNS_MATRIX nNS_MATRIX = new NNS_MATRIX();
		NNS_MATRIX nNS_MATRIX2 = new NNS_MATRIX();
		NNS_MATRIX nNS_MATRIX3 = new NNS_MATRIX();
		nnCopyMatrix(nNS_MATRIX, GmBsCmnGetSNMMtx(ndc_obj.snm_work, ndc_obj.snm_reg_id));
		AkMathNormalizeMtx(nNS_MATRIX2, nNS_MATRIX);
		nnMakeRotateMatrixQuaternion(out ndc_obj.user_quat, nNS_MATRIX2);
		nnTransformVector(nNS_VECTOR, nNS_MATRIX2, ndc_obj.user_ofst);
		nnMakeTranslateMatrix(nNS_MATRIX3, 0f - nNS_VECTOR.x, 0f - nNS_VECTOR.y, 0f - nNS_VECTOR.z);
		nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX3, nNS_MATRIX);
		GmBsCmnEnableCNMInheritNodeScale(ndc_obj.cnm_mgr_work, ndc_obj.cnm_reg_id, 1);
		oBS_OBJECT_WORK.pos.x = FX_F32_TO_FX32(nNS_MATRIX.M03);
		oBS_OBJECT_WORK.pos.y = FX_F32_TO_FX32(0f - nNS_MATRIX.M13);
		oBS_OBJECT_WORK.pos.z = FX_F32_TO_FX32(nNS_MATRIX.M23);
	}

	private static void GmBsCmnSetWorldMtxFromNCObjectPosture(GMS_BS_CMN_NODE_CTRL_OBJECT ndc_obj)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)ndc_obj;
		nnMakeTranslateMatrix(ndc_obj.w_mtx, FX_FX32_TO_F32(oBS_OBJECT_WORK.pos.x), FX_FX32_TO_F32(-oBS_OBJECT_WORK.pos.y), FX_FX32_TO_F32(oBS_OBJECT_WORK.pos.z));
		nnQuaternionMatrix(ndc_obj.w_mtx, ndc_obj.w_mtx, ref ndc_obj.user_quat);
		nnTranslateMatrix(ndc_obj.w_mtx, ndc_obj.w_mtx, ndc_obj.user_ofst.x, ndc_obj.user_ofst.y, ndc_obj.user_ofst.z);
	}

	private static void GmBsCmnSetObject3DNNFadedColor(OBS_OBJECT_WORK obj_work, NNS_RGB color, float intensity)
	{
		GmBsCmnSetObject3DNNFadedColor(obj_work, color, intensity, 0f, 10000f);
	}

	private static void GmBsCmnSetObject3DNNFadedColor(OBS_OBJECT_WORK obj_work, NNS_RGB color, float intensity, float radius)
	{
		GmBsCmnSetObject3DNNFadedColor(obj_work, color, intensity, radius, 10000f);
	}

	private static void GmBsCmnSetObject3DNNFadedColor(OBS_OBJECT_WORK obj_work, NNS_RGB color, float intensity, float radius, float length)
	{
		SNNS_VECTOR disp_pos = default(SNNS_VECTOR);
		AMS_DRAWSTATE draw_state = obj_work.obj_3d.draw_state;
		draw_state.fog.flag = 1;
		draw_state.fog_color.r = color.r;
		draw_state.fog_color.g = color.g;
		draw_state.fog_color.b = color.b;
		ObjCameraDispPosGet(g_obj.glb_camera_id, out disp_pos);
		float num = FX_FX32_TO_F32(obj_work.pos.z);
		float num2 = nnAbs(disp_pos.z - num);
		float num3;
		float num4;
		if (length * intensity > num2)
		{
			num3 = 1.1754944E-38f;
			num4 = num3 + num2 / intensity;
		}
		else
		{
			num3 = num2 - length * intensity;
			if (num3 <= 0f)
			{
				num3 = 1.1754944E-38f;
			}
			num4 = num3 + length;
		}
		draw_state.fog_range.fnear = num3 + radius;
		draw_state.fog_range.ffar = num4 - radius;
	}

	private static void GmBsCmnClearObject3DNNFadedColor(OBS_OBJECT_WORK obj_work)
	{
		AMS_DRAWSTATE draw_state = obj_work.obj_3d.draw_state;
		draw_state.fog.flag = g_obj_draw_3dnn_draw_state.fog.flag;
		draw_state.fog_color.Assign(g_obj_draw_3dnn_draw_state.fog_color);
		draw_state.fog_range.Assign(g_obj_draw_3dnn_draw_state.fog_range);
	}

	private static int GmBsCmnIsSetSafeObject3DNNFadedColor(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.obj_3d.draw_state.fog.flag == 0)
		{
			return 1;
		}
		return 0;
	}

	private static void GmBsCmnInitObject3DNNDamageFlicker(OBS_OBJECT_WORK obj_work, GMS_BS_CMN_DMG_FLICKER_WORK flk_work, float radius)
	{
		flk_work.is_active = 1;
		flk_work.cycles = GMD_BS_CMN_DMG_FLICKER_DEFAULT_CYCLE;
		flk_work.interval_timer = 0u;
		flk_work.cur_angle = 0;
		flk_work.radius = radius;
		GmBsCmnClearObject3DNNFadedColor(obj_work);
	}

	private static int GmBsCmnUpdateObject3DNNDamageFlicker(OBS_OBJECT_WORK obj_work, GMS_BS_CMN_DMG_FLICKER_WORK flk_work)
	{
		if (flk_work.is_active == 0)
		{
			return 1;
		}
		if (flk_work.cycles != 0)
		{
			if (flk_work.interval_timer != 0)
			{
				flk_work.interval_timer--;
			}
			else
			{
				flk_work.cur_angle += AKM_DEGtoA32(45f);
				if (flk_work.cur_angle >= AKM_DEGtoA32(360f))
				{
					flk_work.cur_angle = 0;
					flk_work.cycles--;
				}
			}
			GmBsCmnSetObject3DNNFadedColor(obj_work, gm_bs_cmn_dmg_flicker_default_color, (1f - nnCos(flk_work.cur_angle)) / 2f);
			return 0;
		}
		if (flk_work.is_active != 0)
		{
			GmBsCmnEndObject3DNNDamageFlicker(obj_work, flk_work);
		}
		return 1;
	}

	private static void GmBsCmnEndObject3DNNDamageFlicker(OBS_OBJECT_WORK obj_work, GMS_BS_CMN_DMG_FLICKER_WORK flk_work)
	{
		flk_work.Clear();
		GmBsCmnClearObject3DNNFadedColor(obj_work);
	}

	private static GMS_FADE_OBJ_WORK GmBsCmnInitScreenFadingColor(NNS_RGBA_U8 start_color, NNS_RGBA_U8 end_color, float frame)
	{
		GMS_FADE_OBJ_WORK gMS_FADE_OBJ_WORK = GmFadeCreateFadeObj(6656, 3, 0, () => new GMS_FADE_OBJ_WORK(), 61439, 10u);
		GmFadeSetFade(gMS_FADE_OBJ_WORK, 0u, start_color.r, start_color.g, start_color.b, start_color.a, end_color.r, end_color.g, end_color.b, end_color.a, frame, 0, 0);
		return gMS_FADE_OBJ_WORK;
	}

	private static int GmBsCmnUpdateScreenFadingColor(GMS_FADE_OBJ_WORK fade_obj_work)
	{
		if (GmFadeIsEnd(fade_obj_work) != 0)
		{
			return 1;
		}
		return 0;
	}

	private static void GmBsCmnClearScreenFadingColor(GMS_FADE_OBJ_WORK fade_obj_work)
	{
		fade_obj_work.obj_work.flag |= 8u;
	}

	private static void GmBsCmnInitFlashScreen(GMS_CMN_FLASH_SCR_WORK flash_work, float fo_frame, float duration_frame, float fi_frame)
	{
		NNS_RGBA_U8 start_color = new NNS_RGBA_U8(0, 0, 0, 0);
		NNS_RGBA_U8 end_color = new NNS_RGBA_U8(byte.MaxValue, byte.MaxValue, byte.MaxValue, byte.MaxValue);
		flash_work.Clear();
		flash_work.active_flag |= 3u;
		flash_work.fi_frame = fi_frame;
		flash_work.duration_timer = duration_frame;
		flash_work.fade_obj_work = GmBsCmnInitScreenFadingColor(start_color, end_color, fo_frame);
	}

	private static int GmBsCmnUpdateFlashScreen(GMS_CMN_FLASH_SCR_WORK flash_work)
	{
		NNS_RGBA_U8 end_color = new NNS_RGBA_U8(0, 0, 0, 0);
		NNS_RGBA_U8 start_color = new NNS_RGBA_U8(byte.MaxValue, byte.MaxValue, byte.MaxValue, byte.MaxValue);
		if (flash_work.active_flag == 0)
		{
			return 1;
		}
		if (GmBsCmnUpdateScreenFadingColor(flash_work.fade_obj_work) != 0)
		{
			if ((flash_work.active_flag & 1) != 0)
			{
				if (flash_work.duration_timer > 0f)
				{
					flash_work.duration_timer -= 1f;
				}
				else
				{
					flash_work.active_flag &= 4294967294u;
					GmBsCmnClearScreenFadingColor(flash_work.fade_obj_work);
					flash_work.fade_obj_work = GmBsCmnInitScreenFadingColor(start_color, end_color, flash_work.fi_frame);
				}
			}
			else if ((flash_work.active_flag & 2) != 0)
			{
				GmBsCmnClearScreenFadingColor(flash_work.fade_obj_work);
				flash_work.fade_obj_work = null;
				flash_work.active_flag &= 4294967293u;
			}
		}
		return 0;
	}

	private static void GmBsCmnClearFlashScreen(GMS_CMN_FLASH_SCR_WORK flash_work)
	{
		if (flash_work.fade_obj_work != null)
		{
			GmBsCmnClearScreenFadingColor(flash_work.fade_obj_work);
			flash_work.fade_obj_work = null;
		}
		flash_work.Clear();
	}

	private static void GmBsCmnInitDelaySearch(GMS_BS_CMN_DELAY_SEARCH_WORK dsearch_work, OBS_OBJECT_WORK targ_obj, VecFx32[] pos_hist_buf, int hist_num)
	{
		dsearch_work.pos_hist_buf = pos_hist_buf;
		dsearch_work.cur_point = -1;
		dsearch_work.hist_num = hist_num;
		dsearch_work.targ_obj = targ_obj;
		dsearch_work.record_cnt = 0;
		GmBsCmnUpdateDelaySearch(dsearch_work);
	}

	private static void GmBsCmnUpdateDelaySearch(GMS_BS_CMN_DELAY_SEARCH_WORK dsearch_work)
	{
		dsearch_work.cur_point++;
		if (dsearch_work.cur_point >= dsearch_work.hist_num)
		{
			dsearch_work.cur_point = 0;
		}
		dsearch_work.record_cnt++;
		dsearch_work.pos_hist_buf[dsearch_work.cur_point].Assign(dsearch_work.targ_obj.pos);
	}

	private static void GmBsCmnGetDelaySearchPos(GMS_BS_CMN_DELAY_SEARCH_WORK dsearch_work, int delay_time, out VecFx32 pos)
	{
		int num;
		if (delay_time < dsearch_work.record_cnt)
		{
			num = dsearch_work.cur_point - delay_time;
			if (num < 0)
			{
				num = dsearch_work.hist_num + num;
			}
		}
		else
		{
			num = 0;
		}
		pos = dsearch_work.pos_hist_buf[num];
	}

	private static int gmBsCmnCheckActionFrameOverrunOnNextUpdate(OBS_OBJECT_WORK obj_work, ref float overrun_frame)
	{
		OBS_ACTION3D_NN_WORK obj_3d = obj_work.obj_3d;
		float num = obj_3d.speed[0] * FX_FX32_TO_F32(g_obj.speed);
		float num2 = amMotionGetEndFrame(obj_3d.motion, obj_3d.act_id[0]) - amMotionGetStartFrame(obj_3d.motion, obj_3d.act_id[0]);
		if (obj_3d.frame[0] + num > num2 - 1f)
		{
			overrun_frame = obj_3d.frame[0] + num - (num2 - 1f);
			return 1;
		}
		overrun_frame = 0f;
		return 0;
	}

	private static int gmBsCmnCheckActionFrameOverrunOnNextUpdate(OBS_OBJECT_WORK obj_work)
	{
		OBS_ACTION3D_NN_WORK obj_3d = obj_work.obj_3d;
		float num = obj_3d.speed[0] * FX_FX32_TO_F32(g_obj.speed);
		float num2 = amMotionGetEndFrame(obj_3d.motion, obj_3d.act_id[0]) - amMotionGetStartFrame(obj_3d.motion, obj_3d.act_id[0]);
		if (obj_3d.frame[0] + num > num2 - 1f)
		{
			return 1;
		}
		return 0;
	}

