	private static void gmBsCmnBossMotionCallbackFunc(AMS_MOTION motion, NNS_OBJECT _object, object mtn_cb_param)
	{
		GMS_BS_CMN_BMCB_MGR gMS_BS_CMN_BMCB_MGR = (GMS_BS_CMN_BMCB_MGR)mtn_cb_param;
		GMS_BS_CMN_BMCB_LINK next = gMS_BS_CMN_BMCB_MGR.bmcb_head.next;
		while (next != null && next.bmcb_func != null)
		{
			next.bmcb_func(motion, _object, next.bmcb_param);
			next = next.next;
		}
	}

	private static void gmBsCmnMotionCallbackStoreNodeMatrix(AMS_MOTION motion, NNS_OBJECT _object, object mtn_cb_param)
	{
		GMS_BS_CMN_SNM_WORK gMS_BS_CMN_SNM_WORK = (GMS_BS_CMN_SNM_WORK)mtn_cb_param;
		NNS_MATRIX nNS_MATRIX = gmBsCmnMotionCallbackStoreNodeMatrix_base_mtx;
		nnMakeUnitMatrix(nNS_MATRIX);
		nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX, amMatrixGetCurrent());
		for (int i = 0; i < gMS_BS_CMN_SNM_WORK.reg_node_cnt; i++)
		{
			int node_index = gMS_BS_CMN_SNM_WORK.node_info_list[i].node_index;
			NNS_MATRIX nNS_MATRIX2 = gmBsCmnMotionCallbackStoreNodeMatrix_node_mtx;
			nnCalcNodeMatrixTRSList(nNS_MATRIX2, _object, node_index, motion.data, nNS_MATRIX);
			gMS_BS_CMN_SNM_WORK.node_info_list[i].node_w_mtx.Assign(nNS_MATRIX2);
		}
	}

	private static void gmBsCmnMtxpltCallbackControlNodeMatrix(NNS_MATRIX[] mtx_plt, NNS_OBJECT _object, object mplt_cb_param)
	{
		if (mplt_cb_param == null)
		{
			return;
		}
		ushort reg_node_cnt = ((OBS_ACTION3D_NN_WORK.CMPLT_Wrapper)mplt_cb_param).reg_node_cnt;
		GMS_BS_CMN_CNM_NODE_INFO[] pInfos = ((OBS_ACTION3D_NN_WORK.CMPLT_Wrapper)mplt_cb_param).m_pInfos;
		NNS_MATRIX[] array = gmBsCmnMtxpltCallbackControlNodeMatrix_orig_mtx_plt;
		if (array == null || array.Length < _object.nMtxPal)
		{
			array = new NNS_MATRIX[_object.nMtxPal];
			for (int i = 0; i < _object.nMtxPal; i++)
			{
				array[i] = amDrawAlloc_NNS_MATRIX();
			}
		}
		for (int j = 0; j < _object.nMtxPal; j++)
		{
			array[j].Assign(mtx_plt[j]);
		}
		for (int k = 0; k < reg_node_cnt; k++)
		{
			GMS_BS_CMN_CNM_NODE_INFO gMS_BS_CMN_CNM_NODE_INFO = pInfos[k];
			if (gMS_BS_CMN_CNM_NODE_INFO.enable == 0)
			{
				continue;
			}
			int iMatrix = _object.pNodeList[gMS_BS_CMN_CNM_NODE_INFO.node_index].iMatrix;
			if (iMatrix == -1)
			{
				continue;
			}
			NNS_MATRIX nNS_MATRIX = gmBsCmnMtxpltCallbackControlNodeMatrix_candidate_mtx;
			NNS_MATRIX nNS_MATRIX2 = gmBsCmnMtxpltCallbackControlNodeMatrix_inv_view_mtx;
			NNS_MATRIX nNS_MATRIX3 = gmBsCmnMtxpltCallbackControlNodeMatrix_node_w_mtx;
			nnInvertMatrix(nNS_MATRIX2, amDrawGetWorldViewMatrix());
			nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX2, mtx_plt[iMatrix]);
			if ((gMS_BS_CMN_CNM_NODE_INFO.flag & GMD_BS_CMN_CNM_FLAG_LOCAL_COORDINATE) != 0)
			{
				NNS_MATRIX nNS_MATRIX4 = gmBsCmnMtxpltCallbackControlNodeMatrix_cur_mtx;
				NNS_MATRIX nNS_MATRIX5 = gmBsCmnMtxpltCallbackControlNodeMatrix_inv_cur_mtx;
				NNS_MATRIX nNS_MATRIX6 = gmBsCmnMtxpltCallbackControlNodeMatrix_init_mtx;
				int iParent = _object.pNodeList[gMS_BS_CMN_CNM_NODE_INFO.node_index].iParent;
				nnInvertMatrix(nNS_MATRIX6, _object.pNodeList[gMS_BS_CMN_CNM_NODE_INFO.node_index].InvInitMtx);
				if (gMS_BS_CMN_CNM_NODE_INFO.mode == 0)
				{
					NNS_MATRIX nNS_MATRIX7 = gmBsCmnMtxpltCallbackControlNodeMatrix_parent_mtx;
					NNS_MATRIX nNS_MATRIX8 = gmBsCmnMtxpltCallbackControlNodeMatrix_diff_mtx;
					NNS_MATRIX nNS_MATRIX9 = gmBsCmnMtxpltCallbackControlNodeMatrix_parent_init_mtx;
					nnMultiplyMatrix(nNS_MATRIX7, nNS_MATRIX2, mtx_plt[_object.pNodeList[iParent].iMatrix]);
					nnInvertMatrix(nNS_MATRIX9, _object.pNodeList[iParent].InvInitMtx);
					nnMultiplyMatrix(nNS_MATRIX7, nNS_MATRIX7, nNS_MATRIX9);
					nnMultiplyMatrix(nNS_MATRIX8, _object.pNodeList[iParent].InvInitMtx, nNS_MATRIX6);
					nnMultiplyMatrix(nNS_MATRIX4, nNS_MATRIX7, nNS_MATRIX8);
					nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX4, _object.pNodeList[gMS_BS_CMN_CNM_NODE_INFO.node_index].InvInitMtx);
					nnMultiplyMatrix(nNS_MATRIX3, nNS_MATRIX4, gMS_BS_CMN_CNM_NODE_INFO.node_w_mtx);
				}
				else
				{
					NNS_MATRIX nNS_MATRIX10 = gmBsCmnMtxpltCallbackControlNodeMatrix_parent_cur_mtx;
					NNS_MATRIX nNS_MATRIX11 = gmBsCmnMtxpltCallbackControlNodeMatrix_inv_parent_orig_mtx;
					nnCopyMatrix(nNS_MATRIX4, nNS_MATRIX);
					nnMultiplyMatrix(nNS_MATRIX4, nNS_MATRIX4, nNS_MATRIX6);
					gmBsCmnGetNodeInvWorldMtx(nNS_MATRIX11, _object.pNodeList[iParent], nNS_MATRIX2, array);
					gmBsCmnGetNodeWorldMtx(nNS_MATRIX10, _object.pNodeList[iParent], nNS_MATRIX2, mtx_plt);
					nnInvertMatrix(nNS_MATRIX5, nNS_MATRIX4);
					nnMultiplyMatrix(nNS_MATRIX3, gMS_BS_CMN_CNM_NODE_INFO.node_w_mtx, nNS_MATRIX5);
					nnMultiplyMatrix(nNS_MATRIX3, nNS_MATRIX4, nNS_MATRIX3);
					nnMultiplyMatrix(nNS_MATRIX3, nNS_MATRIX11, nNS_MATRIX3);
					nnMultiplyMatrix(nNS_MATRIX3, nNS_MATRIX10, nNS_MATRIX3);
				}
			}
			else
			{
				nnCopyMatrix(nNS_MATRIX3, gMS_BS_CMN_CNM_NODE_INFO.node_w_mtx);
			}
			if (gMS_BS_CMN_CNM_NODE_INFO.mode == 1)
			{
				nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX3, nNS_MATRIX);
			}
			else if (gMS_BS_CMN_CNM_NODE_INFO.mode == 2)
			{
				NNS_MATRIX nNS_MATRIX12 = gmBsCmnMtxpltCallbackControlNodeMatrix_init_mtx;
				nnInvertMatrix(nNS_MATRIX12, _object.pNodeList[gMS_BS_CMN_CNM_NODE_INFO.node_index].InvInitMtx);
				nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX, nNS_MATRIX12);
				nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX, nNS_MATRIX3);
			}
			else if ((gMS_BS_CMN_CNM_NODE_INFO.flag & GMD_BS_CMN_CNM_FLAG_INHERIT_SCALE) != 0 && (gMS_BS_CMN_CNM_NODE_INFO.flag & GMD_BS_CMN_CNM_FLAG_LOCAL_COORDINATE) == 0)
			{
				NNS_MATRIX nNS_MATRIX13 = gmBsCmnMtxpltCallbackControlNodeMatrix_init_mtx;
				nnInvertMatrix(nNS_MATRIX13, _object.pNodeList[gMS_BS_CMN_CNM_NODE_INFO.node_index].InvInitMtx);
				nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX, nNS_MATRIX13);
				AkMathExtractScaleMtx(nNS_MATRIX, nNS_MATRIX);
				nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX3, nNS_MATRIX);
			}
			else
			{
				nnCopyMatrix(nNS_MATRIX, nNS_MATRIX3);
			}
			if (gMS_BS_CMN_CNM_NODE_INFO.mode != 1)
			{
				nnMultiplyMatrix(nNS_MATRIX, nNS_MATRIX, _object.pNodeList[gMS_BS_CMN_CNM_NODE_INFO.node_index].InvInitMtx);
			}
			nnMultiplyMatrix(mtx_plt[iMatrix], amDrawGetWorldViewMatrix(), nNS_MATRIX);
		}
	}

	private static void gmBsCmnNodeControlObjectMainFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_BS_CMN_NODE_CTRL_OBJECT gMS_BS_CMN_NODE_CTRL_OBJECT = (GMS_BS_CMN_NODE_CTRL_OBJECT)obj_work;
		if (gMS_BS_CMN_NODE_CTRL_OBJECT.proc_update != null)
		{
			gMS_BS_CMN_NODE_CTRL_OBJECT.proc_update(obj_work);
		}
		else
		{
			nnMakeUnitMatrix(gMS_BS_CMN_NODE_CTRL_OBJECT.w_mtx);
		}
		GmBsCmnSetCNMMtx(gMS_BS_CMN_NODE_CTRL_OBJECT.cnm_mgr_work, gMS_BS_CMN_NODE_CTRL_OBJECT.w_mtx, gMS_BS_CMN_NODE_CTRL_OBJECT.cnm_reg_id);
		GmBsCmnEnableCNMMtxNode(gMS_BS_CMN_NODE_CTRL_OBJECT.cnm_mgr_work, gMS_BS_CMN_NODE_CTRL_OBJECT.cnm_reg_id, gMS_BS_CMN_NODE_CTRL_OBJECT.is_enable);
	}

	private static void gmBsCmnGetNodeWorldMtx(NNS_MATRIX dest_mtx, NNS_NODE node, NNS_MATRIX inv_view_mtx, NNS_MATRIX[] mtx_plt)
	{
		NNS_MATRIX nNS_MATRIX = gmBsCmnGetNodeWorldMtx_init_mtx;
		nnMultiplyMatrix(dest_mtx, inv_view_mtx, mtx_plt[node.iMatrix]);
		nnInvertMatrix(nNS_MATRIX, node.InvInitMtx);
		nnMultiplyMatrix(dest_mtx, dest_mtx, nNS_MATRIX);
	}

	private static void gmBsCmnGetNodeInvWorldMtx(NNS_MATRIX dest_mtx, NNS_NODE node, NNS_MATRIX inv_view_mtx, NNS_MATRIX[] mtx_plt)
	{
		nnMultiplyMatrix(dest_mtx, inv_view_mtx, mtx_plt[node.iMatrix]);
		nnInvertMatrix(dest_mtx, dest_mtx);
		nnMultiplyMatrix(dest_mtx, node.InvInitMtx, dest_mtx);
	}

