	private static bool gmBoss1IsScrollLockBusy()
	{
		if ((g_gm_main_system.game_flag & 0x8000) != 0)
		{
			return true;
		}
		return false;
	}

	private static void gmBoss1Init1ShotTimer(GMS_BOSS1_1SHOT_TIMER one_shot_timer, uint frame)
	{
		MTM_ASSERT(one_shot_timer);
		one_shot_timer.timer = frame;
		one_shot_timer.is_active = true;
	}

	private static bool gmBoss1Update1ShotTimer(GMS_BOSS1_1SHOT_TIMER one_shot_timer)
	{
		MTM_ASSERT(one_shot_timer);
		if (!one_shot_timer.is_active)
		{
			return false;
		}
		if (one_shot_timer.timer != 0)
		{
			one_shot_timer.timer--;
			return false;
		}
		one_shot_timer.is_active = false;
		return true;
	}

	private static void gmBoss1MgrIncObjCreateCount(GMS_BOSS1_MGR_WORK mgr_work)
	{
		MTM_ASSERT(mgr_work.obj_create_cnt >= 0);
		mgr_work.obj_create_cnt++;
	}

	private static void gmBoss1MgrDecObjCreateCount(GMS_BOSS1_MGR_WORK mgr_work)
	{
		MTM_ASSERT(mgr_work.obj_create_cnt > 0);
		mgr_work.obj_create_cnt--;
	}

	private static bool gmBoss1MgrIsAllCreatedObjDeleted(GMS_BOSS1_MGR_WORK mgr_work)
	{
		MTM_ASSERT(mgr_work.obj_create_cnt >= 0);
		if (mgr_work.obj_create_cnt <= 0)
		{
			return true;
		}
		return false;
	}

	private static void gmBoss1MgrWaitLoad(OBS_OBJECT_WORK obj_work)
	{
		bool flag = false;
		if (GmBsCmnIsFinalZoneType(obj_work) != 0)
		{
			if (GmMainDatLoadBossBattleLoadCheck(0))
			{
				flag = true;
			}
		}
		else
		{
			flag = true;
		}
		if (flag)
		{
			GMS_BOSS1_MGR_WORK gMS_BOSS1_MGR_WORK = (GMS_BOSS1_MGR_WORK)obj_work;
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GmEventMgrLocalEventBirth(313, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
			gmBoss1MgrIncObjCreateCount(gMS_BOSS1_MGR_WORK);
			OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GmEventMgrLocalEventBirth(314, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
			gmBoss1MgrIncObjCreateCount(gMS_BOSS1_MGR_WORK);
			OBS_OBJECT_WORK oBS_OBJECT_WORK3 = GmEventMgrLocalEventBirth(315, obj_work.pos.x, obj_work.pos.y, 0, 0, 0, 0, 0, 0);
			gmBoss1MgrIncObjCreateCount(gMS_BOSS1_MGR_WORK);
			GMS_BOSS1_BODY_WORK gMS_BOSS1_BODY_WORK = (GMS_BOSS1_BODY_WORK)oBS_OBJECT_WORK;
			GMS_BOSS1_CHAIN_WORK gMS_BOSS1_CHAIN_WORK = (GMS_BOSS1_CHAIN_WORK)oBS_OBJECT_WORK2;
			GMS_BOSS1_EGG_WORK gMS_BOSS1_EGG_WORK = (GMS_BOSS1_EGG_WORK)oBS_OBJECT_WORK3;
			gMS_BOSS1_MGR_WORK.body_work = gMS_BOSS1_BODY_WORK;
			gMS_BOSS1_BODY_WORK.mgr_work = gMS_BOSS1_MGR_WORK;
			gMS_BOSS1_CHAIN_WORK.mgr_work = gMS_BOSS1_MGR_WORK;
			gMS_BOSS1_EGG_WORK.mgr_work = gMS_BOSS1_MGR_WORK;
			oBS_OBJECT_WORK.parent_obj = obj_work;
			oBS_OBJECT_WORK2.parent_obj = oBS_OBJECT_WORK;
			oBS_OBJECT_WORK3.parent_obj = oBS_OBJECT_WORK;
			gMS_BOSS1_BODY_WORK.parts_objs[0] = oBS_OBJECT_WORK;
			gMS_BOSS1_BODY_WORK.parts_objs[1] = oBS_OBJECT_WORK2;
			gMS_BOSS1_BODY_WORK.parts_objs[2] = oBS_OBJECT_WORK3;
			obj_work.ppFunc = gmBoss1MgrWaitSetup;
		}
	}

	private static void gmBoss1MgrWaitSetup(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS1_MGR_WORK gMS_BOSS1_MGR_WORK = (GMS_BOSS1_MGR_WORK)obj_work;
		GMS_BOSS1_BODY_WORK body_work = gMS_BOSS1_MGR_WORK.body_work;
		bool flag = true;
		for (int i = 0; i < 3; i++)
		{
			if (body_work.parts_objs[i] == null)
			{
				flag = false;
			}
		}
		if (flag)
		{
			gMS_BOSS1_MGR_WORK.flag |= 1u;
			obj_work.ppFunc = gmBoss1MgrMain;
		}
	}

	private static void gmBoss1MgrMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS1_MGR_WORK gMS_BOSS1_MGR_WORK = (GMS_BOSS1_MGR_WORK)obj_work;
		if ((gMS_BOSS1_MGR_WORK.flag & 2) != 0)
		{
			if (gMS_BOSS1_MGR_WORK.body_work != null)
			{
				GMM_BS_OBJ(gMS_BOSS1_MGR_WORK.body_work).flag |= 8u;
				gMS_BOSS1_MGR_WORK.body_work = null;
			}
			if (GmBsCmnIsFinalZoneType(obj_work) != 0)
			{
				obj_work.ppFunc = gmBoss1MgrWaitRelease;
			}
		}
	}

	private static void gmBoss1MgrWaitRelease(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS1_MGR_WORK mgr_work = (GMS_BOSS1_MGR_WORK)obj_work;
		if (gmBoss1MgrIsAllCreatedObjDeleted(mgr_work))
		{
			GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)obj_work;
			gMS_ENEMY_COM_WORK.enemy_flag |= 65536u;
			obj_work.flag |= 4u;
			GmGameDatReleaseBossBattleStart(0);
			GmGmkCamScrLimitRelease(14);
		}
	}

	private static void gmBoss1BodyExit(MTS_TASK_TCB tcb)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(tcb);
		GMS_BOSS1_BODY_WORK gMS_BOSS1_BODY_WORK = (GMS_BOSS1_BODY_WORK)oBS_OBJECT_WORK;
		gmBoss1MgrDecObjCreateCount(gMS_BOSS1_BODY_WORK.mgr_work);
		GmBsCmnClearBossMotionCBSystem(oBS_OBJECT_WORK);
		GmBsCmnDeleteSNMWork(gMS_BOSS1_BODY_WORK.snm_work);
		GmBsCmnClearCNMCb(oBS_OBJECT_WORK);
		GmBsCmnDeleteCNMMgrWork(gMS_BOSS1_BODY_WORK.cnm_mgr_work);
		GmEnemyDefaultExit(tcb);
	}

	private static void gmBoss1BodySetActionWhole(GMS_BOSS1_BODY_WORK body_work, int act_id)
	{
		gmBoss1BodySetActionWhole(body_work, act_id, false);
	}

	private static void gmBoss1BodySetActionWhole(GMS_BOSS1_BODY_WORK body_work, int act_id, bool force_change)
	{
		GMS_BOSS1_PART_ACT_INFO[] array = gm_boss1_act_id_tbl[act_id];
		if (!force_change && body_work.whole_act_id == act_id)
		{
			return;
		}
		body_work.whole_act_id = act_id;
		for (int i = 0; i < 3; i++)
		{
			if (body_work.parts_objs[i] == null)
			{
				continue;
			}
			if (i == 2)
			{
				GMS_BOSS1_EGG_WORK gMS_BOSS1_EGG_WORK = (GMS_BOSS1_EGG_WORK)body_work.parts_objs[i];
				body_work.egg_revert_mtn_id = array[i].act_id;
				if ((gMS_BOSS1_EGG_WORK.flag & 1) != 0)
				{
					continue;
				}
			}
			if (array[i].is_maintain == 0)
			{
				GmBsCmnSetAction(body_work.parts_objs[i], array[i].act_id, array[i].is_repeat, array[i].is_blend ? 1 : 0);
			}
			else if (array[i].is_repeat != 0)
			{
				GMM_BS_OBJ(body_work).disp_flag |= 4u;
			}
			if (array[i].is_blend && array[i].is_merge_manual)
			{
				if (i == 1)
				{
					GMS_BOSS1_CHAIN_WORK gMS_BOSS1_CHAIN_WORK = (GMS_BOSS1_CHAIN_WORK)body_work.parts_objs[1];
					gMS_BOSS1_CHAIN_WORK.flag |= 1u;
					GMM_BS_OBJ(gMS_BOSS1_CHAIN_WORK).disp_flag |= 4u;
				}
				else
				{
					MTM_ASSERT(false);
				}
			}
			body_work.parts_objs[i].obj_3d.speed[0] = array[i].mtn_spd;
			body_work.parts_objs[i].obj_3d.blend_spd = array[i].blend_spd;
		}
	}

	private static void gmBoss1BodySetSuspendAction(GMS_BOSS1_BODY_WORK body_work, int part_idx, uint suspend_time)
	{
		OBS_ACTION3D_NN_WORK obj_3d = body_work.parts_objs[part_idx].obj_3d;
		MTM_ASSERT(part_idx == 1);
		obj_3d.speed[0] = 0f;
		body_work.mtn_suspend[part_idx].is_suspended = true;
		body_work.mtn_suspend[part_idx].suspend_timer = suspend_time;
	}

	private static void gmBoss1BodyUpdateSuspendAction(GMS_BOSS1_BODY_WORK body_work)
	{
		for (int i = 0; i < 3; i++)
		{
			GMS_BOSS1_MTN_SUSPEND_WORK gMS_BOSS1_MTN_SUSPEND_WORK = body_work.mtn_suspend[i];
			if (gMS_BOSS1_MTN_SUSPEND_WORK.is_suspended)
			{
				MTM_ASSERT(i == 1);
				if (gMS_BOSS1_MTN_SUSPEND_WORK.suspend_timer != 0)
				{
					gMS_BOSS1_MTN_SUSPEND_WORK.suspend_timer--;
					continue;
				}
				body_work.parts_objs[i].obj_3d.speed[0] = gm_boss1_act_id_tbl[body_work.whole_act_id][i].mtn_spd;
				gMS_BOSS1_MTN_SUSPEND_WORK.is_suspended = false;
			}
		}
	}

	private static bool gmBoss1BodyCheckChainMotionMergeEnd(GMS_BOSS1_BODY_WORK body_work)
	{
		GMS_BOSS1_CHAIN_WORK gMS_BOSS1_CHAIN_WORK = (GMS_BOSS1_CHAIN_WORK)body_work.parts_objs[1];
		if ((gMS_BOSS1_CHAIN_WORK.flag & 1) != 0)
		{
			return false;
		}
		return true;
	}

	private static void gmBoss1BodySetNoHitTime(GMS_BOSS1_BODY_WORK body_work)
	{
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)body_work;
