	}

	private static void gmBoss1BodyUpdateNoHitTime(GMS_BOSS1_BODY_WORK body_work)
	{
		if (body_work.no_hit_timer != 0)
		{
			body_work.no_hit_timer--;
			return;
		}
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)body_work;
		gMS_ENEMY_COM_WORK.rect_work[0].flag &= 4294965247u;
	}

	private static void gmBoss1BodyExecDamageRoutine(GMS_BOSS1_BODY_WORK body_work)
	{
		GMS_BOSS1_MGR_WORK mgr_work = body_work.mgr_work;
		MTM_ASSERT(mgr_work);
		if (mgr_work.life != 0)
		{
			mgr_work.life--;
		}
		if (0 < mgr_work.life)
		{
			body_work.flag |= 1073741824u;
			return;
		}
		body_work.flag |= 2147483648u;
		GMM_BS_OBJ(body_work).flag |= 2u;
	}

