	{
		body_work.cur_angle = deg;
	}

	private static void gmBoss1BodyInitTurnGently(GMS_BOSS1_BODY_WORK body_work, short dest_angle, int frame, bool is_positive)
	{
		MTM_ASSERT(frame > 0);
		body_work.orig_angle = body_work.cur_angle;
		body_work.turn_angle = 0;
		body_work.turn_spd = 0;
		if (is_positive)
		{
			ushort turn_amount = (ushort)(dest_angle - body_work.cur_angle);
			body_work.turn_amount = turn_amount;
		}
		else
		{
			ushort turn_amount = (ushort)(dest_angle - AKM_DEGtoA32(360) - (body_work.cur_angle - AKM_DEGtoA32(360)));
			body_work.turn_amount = turn_amount - AKM_DEGtoA32(360);
		}
		body_work.turn_gen_var = 0;
		float num = 180f / (float)frame;
		MTM_ASSERT(MTM_MATH_ABS(num) <= 2.1474836E+09f);
		body_work.turn_gen_factor = AKM_DEGtoA32(num);
		gmBoss1BodySetDirection(body_work, (short)(body_work.orig_angle + body_work.turn_angle));
	}

	private static bool gmBoss1BodyUpdateTurnGently(GMS_BOSS1_BODY_WORK body_work)
	{
		bool flag = false;
		MTM_ASSERT(body_work.turn_gen_factor > 0);
		body_work.turn_gen_var += body_work.turn_gen_factor;
		if (body_work.turn_gen_var >= AKM_DEGtoA32(180))
		{
			body_work.turn_gen_var = AKM_DEGtoA32(180);
			flag = true;
		}
		float num = (float)body_work.turn_amount * 0.5f * (1f - nnCos(body_work.turn_gen_var));
		MTM_ASSERT(MTM_MATH_ABS(num) <= 2.1474836E+09f);
		body_work.turn_angle = (int)num;
		if (flag)
		{
			body_work.turn_angle = body_work.turn_amount;
		}
		gmBoss1BodySetDirection(body_work, (short)(body_work.orig_angle + body_work.turn_angle));
		return flag;
	}

