	private static bool gmBoss1BodyUpdateAtkNmlMove(GMS_BOSS1_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		int num = GMM_BOSS1_AREA_LEFT() + 589824;
		int num2 = GMM_BOSS1_AREA_LEFT() + 983040;
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			int num3 = num;
			num = num2;
			num2 = num3;
		}
		if (body_work.move_cnt < body_work.move_time)
		{
			int gMD_BOSS1_BODY_ATKNML_MOVE_CURVE_ANGLE_WIDTH = GMD_BOSS1_BODY_ATKNML_MOVE_CURVE_ANGLE_WIDTH;
			int gMD_BOSS1_BODY_ATKNML_MOVE_CURVE_START_ANGLE = GMD_BOSS1_BODY_ATKNML_MOVE_CURVE_START_ANGLE;
			body_work.move_cnt++;
			int num4 = (int)((float)gMD_BOSS1_BODY_ATKNML_MOVE_CURVE_ANGLE_WIDTH / (float)body_work.move_time);
			float num5 = nnCos(gMD_BOSS1_BODY_ATKNML_MOVE_CURVE_START_ANGLE) - nnCos(gMD_BOSS1_BODY_ATKNML_MOVE_CURVE_START_ANGLE + gMD_BOSS1_BODY_ATKNML_MOVE_CURVE_ANGLE_WIDTH);
			float num6 = (nnCos(gMD_BOSS1_BODY_ATKNML_MOVE_CURVE_START_ANGLE) - nnCos(gMD_BOSS1_BODY_ATKNML_MOVE_CURVE_START_ANGLE + num4 * body_work.move_cnt)) / num5;
			oBS_OBJECT_WORK.pos.x = num + (int)((float)(num2 - num) * num6);
			return false;
		}
		oBS_OBJECT_WORK.pos.x = num2;
		return true;
	}

