		if ((oBS_OBJECT_WORK.disp_flag & 1) == 0)
		{
			num = -num;
		}
		oBS_OBJECT_WORK.pos.x = body_work.drift_pivot_x + num;
		return result;
	}

	private static void gmBoss1BodyInitRush(GMS_BOSS1_BODY_WORK body_work, bool is_left)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		if (is_left)
		{
			body_work.bash_targ_pos.x = GMM_BOSS1_AREA_LEFT() + 720896;
			body_work.bash_targ_pos.y = GMD_BOSS1_BODY_ATKBASH_TARG_Y;
			body_work.bash_targ_pos.z = 0;
		}
		else
		{
			body_work.bash_targ_pos.x = GMM_BOSS1_AREA_LEFT() + 851968;
			body_work.bash_targ_pos.y = GMD_BOSS1_BODY_ATKBASH_TARG_Y;
			body_work.bash_targ_pos.z = 0;
		}
		int num = (body_work.bash_targ_pos.x - oBS_OBJECT_WORK.pos.x) / 39;
		int num2 = (body_work.bash_targ_pos.y - oBS_OBJECT_WORK.pos.y) / 39;
		oBS_OBJECT_WORK.spd_add.x = (int)((float)num * (1f / 32f));
		oBS_OBJECT_WORK.spd_add.y = (int)((float)num2 * (1f / 32f));
		oBS_OBJECT_WORK.spd.x = 0;
		oBS_OBJECT_WORK.spd.y = 0;
	}

	private static bool gmBoss1BodyUpdateRush(GMS_BOSS1_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		NNS_VECTOR nNS_VECTOR2 = GlobalPool<NNS_VECTOR>.Alloc();
		amVectorSet(nNS_VECTOR, FX_FX32_TO_F32(body_work.bash_targ_pos.x) - FX_FX32_TO_F32(oBS_OBJECT_WORK.pos.x), FX_FX32_TO_F32(body_work.bash_targ_pos.y) - FX_FX32_TO_F32(oBS_OBJECT_WORK.pos.y), 0f);
		amVectorSet(nNS_VECTOR2, FX_FX32_TO_F32(oBS_OBJECT_WORK.spd.x), FX_FX32_TO_F32(oBS_OBJECT_WORK.spd.y), 0f);
		if (0f >= nnDotProductVector(nNS_VECTOR2, nNS_VECTOR))
		{
			GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
			VEC_Set(ref oBS_OBJECT_WORK.pos, body_work.bash_targ_pos.x, body_work.bash_targ_pos.y, body_work.bash_targ_pos.z);
			GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
			GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR2);
			return true;
		}
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR2);
		return false;
	}

