	private static bool gmBoss1BodyUpdateBashReturn(GMS_BOSS1_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		body_work.bash_homing_deg += AKM_DEGtoA32(3);
		if (body_work.bash_homing_deg >= AKM_DEGtoA32(180))
		{
			body_work.bash_homing_deg = AKM_DEGtoA32(180);
			oBS_OBJECT_WORK.pos.x = body_work.bash_ret_pos.x;
			oBS_OBJECT_WORK.pos.y = body_work.bash_ret_pos.y;
			return true;
		}
		oBS_OBJECT_WORK.pos.x = body_work.bash_orig_pos.x + FX_Mul(body_work.bash_ret_pos.x - body_work.bash_orig_pos.x, 4096 - mtMathCos(body_work.bash_homing_deg) >> 1);
		oBS_OBJECT_WORK.pos.y = body_work.bash_orig_pos.y + FX_Mul(body_work.bash_ret_pos.y - body_work.bash_orig_pos.y, 4096 - mtMathCos(body_work.bash_homing_deg) >> 1);
		return false;
	}

