	private static void gmBoss1BodyDamageDefFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		OBS_OBJECT_WORK parent_obj = my_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = your_rect.parent_obj;
		GMS_BOSS1_BODY_WORK gMS_BOSS1_BODY_WORK = (GMS_BOSS1_BODY_WORK)parent_obj;
		if (parent_obj2 == null || 1 != parent_obj2.obj_type)
		{
			return;
		}
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)parent_obj2;
		GmPlySeqAtkReactionInit(gMS_PLAYER_WORK);
		GmPlySeqSetJumpState(gMS_PLAYER_WORK, 0, 5u);
		if (gMS_PLAYER_WORK.seq_state == 20)
		{
			gMS_PLAYER_WORK.obj_work.spd_m = 0;
			if (gMS_PLAYER_WORK.obj_work.move.x >= 0)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = -20480;
			}
			else
			{
				gMS_PLAYER_WORK.obj_work.spd.x = 20480;
			}
			if (parent_obj2.pos.y <= parent_obj.pos.y)
			{
				gMS_PLAYER_WORK.obj_work.spd.y = -16384;
			}
			else
			{
				gMS_PLAYER_WORK.obj_work.spd.y = 16384;
			}
			GmPlySeqSetNoJumpMoveTime(gMS_PLAYER_WORK, 102400);
		}
		else
		{
			gMS_PLAYER_WORK.obj_work.spd_m = 0;
			if (gMS_PLAYER_WORK.obj_work.move.x >= 0)
			{
				gMS_PLAYER_WORK.obj_work.spd.x = -16384;
			}
			else
			{
				gMS_PLAYER_WORK.obj_work.spd.x = 16384;
			}
			if (parent_obj2.pos.y <= parent_obj.pos.y)
			{
				gMS_PLAYER_WORK.obj_work.spd.y = -12288;
			}
			else
			{
				gMS_PLAYER_WORK.obj_work.spd.y = 12288;
			}
			GmPlySeqSetNoJumpMoveTime(gMS_PLAYER_WORK, 102400);
		}
		gmBoss1BodySetNoHitTime(gMS_BOSS1_BODY_WORK);
		GmSoundPlaySE("Boss0_01");
		GMM_PAD_VIB_SMALL_TIME(30f);
		gmBoss1EffDamageInit(gMS_BOSS1_BODY_WORK);
		if ((gMS_BOSS1_BODY_WORK.flag & 4) == 0)
		{
			gmBoss1BodyExecDamageRoutine(gMS_BOSS1_BODY_WORK);
		}
	}

