		{
			GmBsCmnInitBossMotionCBSystem(obj_work, gMS_BOSS1_BODY_WORK.bmcb_mgr);
			GmBsCmnCreateSNMWork(gMS_BOSS1_BODY_WORK.snm_work, obj_work.obj_3d._object, 4);
			GmBsCmnAppendBossMotionCallback(gMS_BOSS1_BODY_WORK.bmcb_mgr, gMS_BOSS1_BODY_WORK.snm_work.bmcb_link);
			gMS_BOSS1_BODY_WORK.chain_snm_reg_id = GmBsCmnRegisterSNMNode(gMS_BOSS1_BODY_WORK.snm_work, 13);
			gMS_BOSS1_BODY_WORK.egg_snm_reg_id = GmBsCmnRegisterSNMNode(gMS_BOSS1_BODY_WORK.snm_work, 11);
			gMS_BOSS1_BODY_WORK.body_snm_reg_id = GmBsCmnRegisterSNMNode(gMS_BOSS1_BODY_WORK.snm_work, 2);
			gMS_BOSS1_BODY_WORK.chaintop_snm_reg_id = GmBsCmnRegisterSNMNode(gMS_BOSS1_BODY_WORK.snm_work, 9);
			GmBsCmnCreateCNMMgrWork(gMS_BOSS1_BODY_WORK.cnm_mgr_work, obj_work.obj_3d._object, 1);
			GmBsCmnInitCNMCb(obj_work, gMS_BOSS1_BODY_WORK.cnm_mgr_work);
			gMS_BOSS1_BODY_WORK.chaintop_cnm_reg_id = GmBsCmnRegisterCNMNode(gMS_BOSS1_BODY_WORK.cnm_mgr_work, 9);
			obj_work.ppFunc = gmBoss1BodyMain;
