	private static void gmBoss1BodyMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS1_BODY_WORK gMS_BOSS1_BODY_WORK = (GMS_BOSS1_BODY_WORK)obj_work;
		gmBoss1BodyUpdateNoHitTime(gMS_BOSS1_BODY_WORK);
		if ((gMS_BOSS1_BODY_WORK.flag & 0x80000000u) != 0)
		{
			gMS_BOSS1_BODY_WORK.flag &= 1073741823u;
			gmBoss1BodyInitDefeatState(gMS_BOSS1_BODY_WORK);
		}
		else if (gMS_BOSS1_BODY_WORK.proc_update != null)
		{
