	{
		if (body_work.wait_timer != 0)
		{
			body_work.wait_timer--;
			return;
		}
		gmBoss1EffBombInitCreate(body_work.bomb_work, 0, GMM_BS_OBJ(body_work), GMM_BS_OBJ(body_work).pos.x, GMM_BS_OBJ(body_work).pos.y, 327680, 327680, 10u, 10u);
