		oBS_OBJECT_WORK.pos.z = oBS_OBJECT_WORK.parent_obj.pos.z + 131072;
		body_work.wait_timer = 40u;
		GmPlayerAddScoreNoDisp((GMS_PLAYER_WORK)GmBsCmnGetPlayerObj(), 1000);
