		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		oBS_OBJECT_WORK.flag |= 2u;
		oBS_OBJECT_WORK.disp_flag &= 4294967279u;
		gmBoss1BodySetActionWhole(body_work, 12);
		body_work.flag |= 8388608u;
		gmBoss1BodyInitTurnGently(is_positive: gmBoss1BodyIsDirectionPositiveFromCurrent(body_work, GMD_BOSS1_RIGHTWARD_ANGLE) ? true : false, body_work: body_work, dest_angle: GMD_BOSS1_RIGHTWARD_ANGLE, frame: 90);
		body_work.proc_update = gmBoss1BodyStateUpdateEscapeWithTurn;
