	private static void gmBoss1BodyStateUpdateEscapeWithTurn(GMS_BOSS1_BODY_WORK body_work)
	{
		if (gmBoss1BodyUpdateTurnGently(body_work))
		{
			gmBoss1BodyInitEscapeMove(body_work);
			if (GmBsCmnIsFinalZoneType(GMM_BS_OBJ(GMM_BOSS1_MGR(body_work))) != 0)
			{
				body_work.proc_update = gmBoss1BodyStateUpdateEscapeWithMoveMoveFinalZone;
			}
			else
			{
				body_work.proc_update = gmBoss1BodyStateUpdateEscapeWithMoveLocked;
			}
		}
	}

	private static void gmBoss1BodyStateUpdateEscapeWithMoveLocked(GMS_BOSS1_BODY_WORK body_work)
	{
		gmBoss1BodyUpdateEscapeMove(body_work);
		if (gmBoss1BodyIsEscapeScrUnlock(body_work))
		{
			GmMapSetMapDrawSize(1);
			gmBoss1EffBodyDebrisInit(body_work);
			body_work.flag |= 256u;
			GmGmkCamScrLimitRelease(4);
			body_work.proc_update = gmBoss1BodyStateUpdateEscapeWithMoveUnlocked;
		}
	}

	private static void gmBoss1BodyStateUpdateEscapeWithMoveUnlocked(GMS_BOSS1_BODY_WORK body_work)
	{
		if (gmBoss1BodyUpdateEscapeMove(body_work))
		{
			GMM_BOSS1_MGR(body_work).flag |= 2u;
			body_work.proc_update = null;
		}
	}

	private static void gmBoss1BodyStateUpdateEscapeWithMoveMoveFinalZone(GMS_BOSS1_BODY_WORK body_work)
	{
		if ((body_work.flag & 0x100) == 0 && gmBoss1BodyIsEscapeScrUnlock(body_work))
		{
			gmBoss1EffBodyDebrisInit(body_work);
			body_work.flag |= 256u;
		}
		if (gmBoss1BodyUpdateEscapeMove(body_work) || gmBoss1BodyIsEscapeOutFinalZone(body_work))
		{
			GMM_BOSS1_MGR(body_work).flag |= 2u;
			body_work.proc_update = null;
		}
	}

	private static void gmBoss1ChainExit(MTS_TASK_TCB tcb)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(tcb);
