		gmBoss1MgrDecObjCreateCount(gMS_BOSS1_CHAIN_WORK.mgr_work);
		GmBsCmnClearBossMotionCBSystem(oBS_OBJECT_WORK);
		GmBsCmnDeleteSNMWork(gMS_BOSS1_CHAIN_WORK.snm_work);
		GmBsCmnClearCNMCb(oBS_OBJECT_WORK);
		GmBsCmnDeleteCNMMgrWork(gMS_BOSS1_CHAIN_WORK.cnm_mgr_work);
