	private static void gmBoss1ChainWaitSetup(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS1_CHAIN_WORK gMS_BOSS1_CHAIN_WORK = (GMS_BOSS1_CHAIN_WORK)obj_work;
		GMS_BOSS1_BODY_WORK work = (GMS_BOSS1_BODY_WORK)obj_work.parent_obj;
		if ((GMM_BOSS1_MGR(work).flag & 1) != 0)
		{
			GmBsCmnInitBossMotionCBSystem(obj_work, gMS_BOSS1_CHAIN_WORK.bmcb_mgr);
			GmBsCmnCreateSNMWork(gMS_BOSS1_CHAIN_WORK.snm_work, obj_work.obj_3d._object, 10);
			GmBsCmnAppendBossMotionCallback(gMS_BOSS1_CHAIN_WORK.bmcb_mgr, gMS_BOSS1_CHAIN_WORK.snm_work.bmcb_link);
			gMS_BOSS1_CHAIN_WORK.ball_snm_reg_id = GmBsCmnRegisterSNMNode(gMS_BOSS1_CHAIN_WORK.snm_work, 11);
			for (int i = 0; i < 9; i++)
			{
				gMS_BOSS1_CHAIN_WORK.sct_snm_reg_ids[i] = GmBsCmnRegisterSNMNode(gMS_BOSS1_CHAIN_WORK.snm_work, 2 + i);
			}
			GmBsCmnCreateCNMMgrWork(gMS_BOSS1_CHAIN_WORK.cnm_mgr_work, obj_work.obj_3d._object, 9);
			GmBsCmnInitCNMCb(obj_work, gMS_BOSS1_CHAIN_WORK.cnm_mgr_work);
			for (int j = 0; j < 9; j++)
			{
				gMS_BOSS1_CHAIN_WORK.sct_cnm_reg_ids[j] = GmBsCmnRegisterCNMNode(gMS_BOSS1_CHAIN_WORK.cnm_mgr_work, 2 + j);
			}
			obj_work.ppFunc = gmBoss1ChainMain;
		}
	}

	private static void gmBoss1ChainMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS1_CHAIN_WORK gMS_BOSS1_CHAIN_WORK = (GMS_BOSS1_CHAIN_WORK)obj_work;
		GMS_BOSS1_BODY_WORK gMS_BOSS1_BODY_WORK = (GMS_BOSS1_BODY_WORK)obj_work.parent_obj;
		bool flag = false;
		if ((gMS_BOSS1_BODY_WORK.flag & 1) != 0)
		{
			obj_work.disp_flag |= 4194304u;
			flag = true;
		}
		else
		{
			obj_work.disp_flag &= 4290772991u;
			flag = false;
		}
		if ((gMS_BOSS1_CHAIN_WORK.flag & 1) != 0)
		{
			obj_work.obj_3d.flag &= 4294967294u;
			if (obj_work.obj_3d.marge > 0f)
			{
				obj_work.obj_3d.marge -= obj_work.obj_3d.blend_spd;
			}
			else
			{
				gMS_BOSS1_CHAIN_WORK.flag &= 4294967294u;
				if (gm_boss1_act_id_tbl[gMS_BOSS1_BODY_WORK.whole_act_id][1].is_repeat != 0)
				{
					obj_work.disp_flag |= 4u;
				}
				else
				{
					obj_work.disp_flag &= 4294967291u;
				}
				obj_work.obj_3d.marge = 0f;
			}
		}
		if ((GMM_BS_OBJ(gMS_BOSS1_BODY_WORK).disp_flag & 0x10) != 0)
		{
			obj_work.disp_flag |= 16u;
		}
		else if ((gMS_BOSS1_BODY_WORK.flag & 0x80) == 0)
		{
			obj_work.disp_flag &= 4294967279u;
		}
		if ((gMS_BOSS1_BODY_WORK.flag & 0x20) != 0)
		{
			obj_work.disp_flag |= 32u;
		}
		else
		{
			obj_work.disp_flag &= 4294967263u;
		}
		if ((gMS_BOSS1_BODY_WORK.flag & 0x40) != 0)
		{
			obj_work.flag |= 2u;
		}
		else
		{
			obj_work.flag &= 4294967293u;
		}
		if ((gMS_BOSS1_BODY_WORK.flag & 8) != 0)
		{
			obj_work.disp_flag |= 16u;
			obj_work.flag |= 2u;
		}
		GmBsCmnUpdateObject3DNNStuckWithNode(obj_work, gMS_BOSS1_BODY_WORK.snm_work, gMS_BOSS1_BODY_WORK.chain_snm_reg_id, flag ? 1 : 0);
		if ((gMS_BOSS1_BODY_WORK.flag & 0x8000000) != 0)
		{
			gMS_BOSS1_BODY_WORK.flag &= 4160749567u;
			gmBoss1EffShockwaveInit(gMS_BOSS1_CHAIN_WORK);
		}
		if ((gMS_BOSS1_BODY_WORK.flag & 0x4000000) != 0)
		{
			gMS_BOSS1_BODY_WORK.flag &= 4227858431u;
			gmBoss1EffScatterInit(gMS_BOSS1_CHAIN_WORK);
		}
		gmBoss1ChainUpdateAtkRectPosition(gMS_BOSS1_CHAIN_WORK);
	}

