	private static void gmBoss1EggSetActionIndependent(GMS_BOSS1_EGG_WORK egg_work, int act_id)
	{
		gmBoss1EggSetActionIndependent(egg_work, act_id, false);
	}

	private static void gmBoss1EggSetActionIndependent(GMS_BOSS1_EGG_WORK egg_work, int act_id, bool force_change)
	{
		GMS_BOSS1_PART_ACT_INFO gMS_BOSS1_PART_ACT_INFO = gm_boss1_egg_act_id_tbl[act_id];
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		GMS_BOSS1_BODY_WORK gMS_BOSS1_BODY_WORK = (GMS_BOSS1_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		if ((gMS_BOSS1_BODY_WORK.flag & 2) == 0 && (force_change || (egg_work.flag & 1) == 0 || egg_work.egg_act_id != act_id))
		{
			egg_work.egg_act_id = act_id;
			egg_work.flag |= 1u;
			if (gMS_BOSS1_PART_ACT_INFO.is_maintain == 0)
			{
				GmBsCmnSetAction(oBS_OBJECT_WORK, gMS_BOSS1_PART_ACT_INFO.act_id, gMS_BOSS1_PART_ACT_INFO.is_repeat, gMS_BOSS1_PART_ACT_INFO.is_blend ? 1 : 0);
			}
			else if (gMS_BOSS1_PART_ACT_INFO.is_repeat != 0)
			{
				GMM_BS_OBJ(egg_work).disp_flag |= 4u;
			}
			oBS_OBJECT_WORK.obj_3d.speed[0] = gMS_BOSS1_PART_ACT_INFO.mtn_spd;
			oBS_OBJECT_WORK.obj_3d.blend_spd = gMS_BOSS1_PART_ACT_INFO.blend_spd;
		}
	}

	private static void gmBoss1EggRevertActionIndependent(GMS_BOSS1_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		GMS_BOSS1_BODY_WORK gMS_BOSS1_BODY_WORK = (GMS_BOSS1_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		MTM_ASSERT(egg_work.flag & 1);
		egg_work.flag &= 4294967294u;
		GmBsCmnSetAction(oBS_OBJECT_WORK, gMS_BOSS1_BODY_WORK.egg_revert_mtn_id, gm_boss1_act_id_tbl[gMS_BOSS1_BODY_WORK.whole_act_id][2].is_repeat, 1);
		oBS_OBJECT_WORK.obj_3d.frame[0] = GMM_BS_OBJ(gMS_BOSS1_BODY_WORK).obj_3d.frame[0];
	}

	private static void gmBoss1EggWaitSetup(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS1_BODY_WORK work = (GMS_BOSS1_BODY_WORK)obj_work.parent_obj;
		GMS_BOSS1_EGG_WORK egg_work = (GMS_BOSS1_EGG_WORK)obj_work;
		if ((GMM_BOSS1_MGR(work).flag & 1) != 0)
		{
			obj_work.ppFunc = gmBoss1EggMain;
			gmBoss1EggProcIdleInit(egg_work);
		}
	}

	private static void gmBoss1EggMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS1_BODY_WORK gMS_BOSS1_BODY_WORK = (GMS_BOSS1_BODY_WORK)obj_work.parent_obj;
		GMS_BOSS1_EGG_WORK gMS_BOSS1_EGG_WORK = (GMS_BOSS1_EGG_WORK)obj_work;
		GmBsCmnUpdateObject3DNNStuckWithNode(obj_work, gMS_BOSS1_BODY_WORK.snm_work, gMS_BOSS1_BODY_WORK.egg_snm_reg_id, 1);
		if (gMS_BOSS1_EGG_WORK.proc_update != null)
		{
			gMS_BOSS1_EGG_WORK.proc_update(gMS_BOSS1_EGG_WORK);
		}
		if ((gMS_BOSS1_BODY_WORK.flag & 0x800000) != 0)
		{
			gMS_BOSS1_BODY_WORK.flag &= 4286578687u;
			gmBoss1EggProcEscapeInit(gMS_BOSS1_EGG_WORK);
		}
		if ((gMS_BOSS1_BODY_WORK.flag & 0x20000000) != 0)
		{
			gMS_BOSS1_BODY_WORK.flag &= 3758096383u;
			gmBoss1EggProcDamageInit(gMS_BOSS1_EGG_WORK);
		}
		if ((gMS_BOSS1_BODY_WORK.flag & 0x1000000) != 0)
		{
			gMS_BOSS1_BODY_WORK.flag &= 4278190079u;
			gmBoss1SetPartTextureBurnt(obj_work);
		}
		if ((GMM_BS_OBJ(gMS_BOSS1_BODY_WORK).disp_flag & 0x10) != 0)
		{
			obj_work.disp_flag |= 16u;
		}
		else
		{
			obj_work.disp_flag &= 4294967279u;
		}
	}

	private static void gmBoss1EggProcIdleInit(GMS_BOSS1_EGG_WORK egg_work)
	{
		egg_work.proc_update = gmBoss1EggProcIdleUpdateLoop;
	}

	private static void gmBoss1EggProcIdleUpdateLoop(GMS_BOSS1_EGG_WORK egg_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(egg_work);
		GMS_BOSS1_BODY_WORK gMS_BOSS1_BODY_WORK = (GMS_BOSS1_BODY_WORK)oBS_OBJECT_WORK.parent_obj;
		if ((gMS_BOSS1_BODY_WORK.flag & 0x10000000) != 0)
		{
			gMS_BOSS1_BODY_WORK.flag &= 4026531839u;
			gmBoss1EggProcLaughInit(egg_work);
		}
	}

	private static void gmBoss1EggProcLaughInit(GMS_BOSS1_EGG_WORK egg_work)
	{
