	}

	private static GMS_EFFECT_3DES_WORK gmBoss1EffShockwaveInit(GMS_BOSS1_CHAIN_WORK chain_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_BOSS1_EFF_SHOCKWAVE_WORK(), GMM_BS_OBJ(chain_work), 0, "B01_ShockWave");
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = (GMS_EFFECT_3DES_WORK)oBS_OBJECT_WORK;
		GMS_BOSS1_EFF_SHOCKWAVE_WORK gMS_BOSS1_EFF_SHOCKWAVE_WORK = (GMS_BOSS1_EFF_SHOCKWAVE_WORK)gMS_EFFECT_3DES_WORK;
		gMS_BOSS1_EFF_SHOCKWAVE_WORK.mgr_work = chain_work.mgr_work;
		gmBoss1MgrIncObjCreateCount(gMS_BOSS1_EFF_SHOCKWAVE_WORK.mgr_work);
		ObjObjectAction3dESEffectLoad(data_work: ObjDataGet((GmBsCmnIsFinalZoneType(GMM_BS_OBJ(chain_work.mgr_work)) == 0) ? 706 : 708), obj_work: GMM_BS_OBJ(gMS_EFFECT_3DES_WORK), obj_3des: gMS_EFFECT_3DES_WORK.obj_3des, filename: null, index: 0, archive: null);
		ObjObjectAction3dESTextureLoad(GMM_BS_OBJ(gMS_EFFECT_3DES_WORK), gMS_EFFECT_3DES_WORK.obj_3des, ObjDataGet(709), null, 0, null, false);
		ObjObjectAction3dESTextureSetByDwork(oBS_OBJECT_WORK, ObjDataGet(710));
		GmEffect3DESSetupBase(gMS_EFFECT_3DES_WORK, 1u, 1u);
		NNS_MATRIX nNS_MATRIX = GmBsCmnGetSNMMtx(chain_work.snm_work, chain_work.ball_snm_reg_id);
		VEC_Set(ref oBS_OBJECT_WORK.pos, FX_F32_TO_FX32(nNS_MATRIX.M03), GMD_BOSS1_GROUND_POS_Y, 0);
		oBS_OBJECT_WORK.flag &= 4294967293u;
		GmEffectRectInit(gMS_EFFECT_3DES_WORK.efct_com, gm_boss1_eff_sw_atk_flag_tbl, gm_boss1_eff_sw_def_flag_tbl, 1, 1);
		ObjRectWorkSet(gMS_EFFECT_3DES_WORK.efct_com.rect_work[1], -64, -32, 64, 32);
		gMS_BOSS1_EFF_SHOCKWAVE_WORK.atk_rect_timer = 10u;
		oBS_OBJECT_WORK.ppFunc = gmBoss1EffShockwaveProcMain;
		gmBoss1EffShockwaveSubpartInit(gMS_BOSS1_EFF_SHOCKWAVE_WORK, 163840, true);
		gmBoss1EffShockwaveSubpartInit(gMS_BOSS1_EFF_SHOCKWAVE_WORK, 163840, false);
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmBoss1EffShockwaveExit);
		return gMS_EFFECT_3DES_WORK;
	}

