	private static void gmBoss1EffShockwaveProcMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS1_EFF_SHOCKWAVE_WORK gMS_BOSS1_EFF_SHOCKWAVE_WORK = (GMS_BOSS1_EFF_SHOCKWAVE_WORK)obj_work;
		if (gMS_BOSS1_EFF_SHOCKWAVE_WORK.atk_rect_timer != 0)
		{
			gMS_BOSS1_EFF_SHOCKWAVE_WORK.atk_rect_timer--;
		}
		else
		{
			obj_work.flag |= 2u;
		}
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.flag |= 4u;
		}
	}

	private static GMS_EFFECT_3DES_WORK gmBoss1EffShockwaveSubpartInit(GMS_BOSS1_EFF_SHOCKWAVE_WORK sw_work, int ofst_h, bool is_left)
	{
		MTM_ASSERT(ofst_h >= 0);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_BOSS1_EFF_SHOCKWAVE_SUB_WORK(), GMM_BS_OBJ(sw_work).parent_obj, 0, "B01_SW_Subpart");
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = (GMS_EFFECT_3DES_WORK)oBS_OBJECT_WORK;
		GMS_BOSS1_EFF_SHOCKWAVE_SUB_WORK gMS_BOSS1_EFF_SHOCKWAVE_SUB_WORK = (GMS_BOSS1_EFF_SHOCKWAVE_SUB_WORK)gMS_EFFECT_3DES_WORK;
		gMS_BOSS1_EFF_SHOCKWAVE_SUB_WORK.mgr_work = sw_work.mgr_work;
		gmBoss1MgrIncObjCreateCount(gMS_BOSS1_EFF_SHOCKWAVE_SUB_WORK.mgr_work);
		ObjObjectAction3dESEffectLoad(GMM_BS_OBJ(gMS_EFFECT_3DES_WORK), gMS_EFFECT_3DES_WORK.obj_3des, ObjDataGet(707), null, 0, null);
		ObjObjectAction3dESTextureLoad(GMM_BS_OBJ(gMS_EFFECT_3DES_WORK), gMS_EFFECT_3DES_WORK.obj_3des, ObjDataGet(709), null, 0, null, false);
		ObjObjectAction3dESTextureSetByDwork(oBS_OBJECT_WORK, ObjDataGet(710));
		GmEffect3DESSetupBase(gMS_EFFECT_3DES_WORK, 1u, 0u);
		GmEffect3DESSetDispRotation(gMS_EFFECT_3DES_WORK, (short)GMD_BOSS1_EFF_SHOCKWAVE_SUB_ROT_X, 0, 0);
		GmEffect3DESSetDispOffset(gMS_EFFECT_3DES_WORK, 0f, 0f - FX_FX32_TO_F32(-16384), FX_FX32_TO_F32(-ofst_h));
		oBS_OBJECT_WORK.pos.x = GMM_BS_OBJ(sw_work).pos.x;
		oBS_OBJECT_WORK.pos.y = GMM_BS_OBJ(sw_work).pos.y;
		oBS_OBJECT_WORK.pos.z = GMM_BS_OBJ(sw_work).pos.z;
		if (is_left)
		{
			oBS_OBJECT_WORK.disp_flag &= 4294967294u;
		}
		else
		{
			oBS_OBJECT_WORK.disp_flag |= 1u;
		}
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmBoss1EffShockwaveSubExit);
		return gMS_EFFECT_3DES_WORK;
	}

	private static void gmBoss1EffShockwaveSubExit(MTS_TASK_TCB tcb)
	{
		GMS_BOSS1_EFF_SHOCKWAVE_SUB_WORK gMS_BOSS1_EFF_SHOCKWAVE_SUB_WORK = (GMS_BOSS1_EFF_SHOCKWAVE_SUB_WORK)mtTaskGetTcbWork(tcb);
		gmBoss1MgrDecObjCreateCount(gMS_BOSS1_EFF_SHOCKWAVE_SUB_WORK.mgr_work);
		GmEffectDefaultExit(tcb);
	}

	private static void gmBoss1EffScatterInit(GMS_BOSS1_CHAIN_WORK chain_work)
	{
		for (int i = 0; i < 9; i++)
		{
			GMS_BS_CMN_NODE_CTRL_OBJECT gMS_BS_CMN_NODE_CTRL_OBJECT = GmBsCmnCreateNodeControlObjectBySize(GMM_BS_OBJ(chain_work), chain_work.cnm_mgr_work, chain_work.sct_cnm_reg_ids[i], chain_work.snm_work, chain_work.sct_snm_reg_ids[i], () => new GMS_BOSS1_EFF_SCT_PART_NDC_WORK());
			GMS_BOSS1_EFF_SCT_PART_NDC_WORK sct_part_ndc = (GMS_BOSS1_EFF_SCT_PART_NDC_WORK)gMS_BS_CMN_NODE_CTRL_OBJECT;
			gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer = (uint)(mtMathRand() % 20);
			gMS_BS_CMN_NODE_CTRL_OBJECT.is_enable = 0;
			gmBoss1EffScatterSetPartParam(sct_part_ndc, i == 8);
			GMM_BS_OBJ(gMS_BS_CMN_NODE_CTRL_OBJECT).move_flag |= 4608u;
			nnMakeUnitQuaternion(ref gMS_BS_CMN_NODE_CTRL_OBJECT.user_quat);
			gMS_BS_CMN_NODE_CTRL_OBJECT.proc_update = gmBoss1EffScatterProcWait;
		}
	}

	private static void gmBoss1EffScatterSetPartParam(GMS_BOSS1_EFF_SCT_PART_NDC_WORK sct_part_ndc, bool is_ironball)
	{
		GMS_BS_CMN_NODE_CTRL_OBJECT gMS_BS_CMN_NODE_CTRL_OBJECT = (GMS_BS_CMN_NODE_CTRL_OBJECT)sct_part_ndc;
		int ang;
		if (is_ironball)
		{
			sct_part_ndc.is_ironball = true;
			gMS_BS_CMN_NODE_CTRL_OBJECT.user_ofst.y = 32f;
			ang = GMD_BOSS1_EFF_SCT_PART_IBALL_SPIN_SPD_DEG;
		}
		else
		{
			sct_part_ndc.is_ironball = false;
			gMS_BS_CMN_NODE_CTRL_OBJECT.user_ofst.y = 8f;
			ang = GMD_BOSS1_EFF_SCT_PART_RING_SPIN_SPD_DEG;
		}
		nnMakeUnitQuaternion(ref sct_part_ndc.spin_quat);
		for (int i = 0; i < 2; i++)
		{
			NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
			NNS_QUATERNION dst = default(NNS_QUATERNION);
			float a = FX_FX32_TO_F32(AkMathRandFx()) * 2f - 1f;
			a = MTM_MATH_CLIP(a, -1f, 1f);
			short rand_angle = AKM_DEGtoA16(360f * FX_FX32_TO_F32(AkMathRandFx()));
			AkMathGetRandomUnitVector(nNS_VECTOR, a, rand_angle);
			nnMakeRotateAxisQuaternion(out dst, nNS_VECTOR.x, nNS_VECTOR.y, nNS_VECTOR.z, ang);
			nnMultiplyQuaternion(ref sct_part_ndc.spin_quat, ref dst, ref sct_part_ndc.spin_quat);
			GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		}
		if (is_ironball)
		{
			ObjObjectFieldRectSet(GMM_BS_OBJ(gMS_BS_CMN_NODE_CTRL_OBJECT), -24, -24, 24, 24);
		}
		else
		{
			ObjObjectFieldRectSet(GMM_BS_OBJ(gMS_BS_CMN_NODE_CTRL_OBJECT), -8, -8, 8, 8);
		}
	}

	private static void gmBoss1EffScatterSetFlyParam(GMS_BOSS1_EFF_SCT_PART_NDC_WORK sct_part_ndc)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(sct_part_ndc);
		int num = mtMathRand() % 180;
		int ang = AKM_DEGtoA32(num + ((num > 90) ? 45 : (-45)));
		float num2 = ((!sct_part_ndc.is_ironball) ? 5f : 3f);
		oBS_OBJECT_WORK.spd.y = (int)(4096f * num2 * nnSin(ang));
		oBS_OBJECT_WORK.spd.x = (int)(4096f * num2 * nnCos(ang));
		oBS_OBJECT_WORK.move_flag |= 128u;
	}

	private static void gmBoss1EffScatterProcWait(OBS_OBJECT_WORK obj_work)
	{
		GMS_BS_CMN_NODE_CTRL_OBJECT gMS_BS_CMN_NODE_CTRL_OBJECT = (GMS_BS_CMN_NODE_CTRL_OBJECT)obj_work;
		GMS_BOSS1_EFF_SCT_PART_NDC_WORK sct_part_ndc = (GMS_BOSS1_EFF_SCT_PART_NDC_WORK)gMS_BS_CMN_NODE_CTRL_OBJECT;
		if (gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer != 0)
		{
			gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer--;
			return;
		}
		GmBsCmnAttachNCObjectToSNMNode(gMS_BS_CMN_NODE_CTRL_OBJECT);
		gmBoss1EffScatterSetFlyParam(sct_part_ndc);
		gMS_BS_CMN_NODE_CTRL_OBJECT.is_enable = 1;
		gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer = 180u;
		gMS_BS_CMN_NODE_CTRL_OBJECT.proc_update = gmBoss1EffScatterProcFly;
	}

	private static void gmBoss1EffScatterProcFly(OBS_OBJECT_WORK obj_work)
	{
		GMS_BS_CMN_NODE_CTRL_OBJECT gMS_BS_CMN_NODE_CTRL_OBJECT = (GMS_BS_CMN_NODE_CTRL_OBJECT)obj_work;
		GMS_BOSS1_EFF_SCT_PART_NDC_WORK gMS_BOSS1_EFF_SCT_PART_NDC_WORK = (GMS_BOSS1_EFF_SCT_PART_NDC_WORK)gMS_BS_CMN_NODE_CTRL_OBJECT;
		nnMultiplyQuaternion(ref gMS_BS_CMN_NODE_CTRL_OBJECT.user_quat, ref gMS_BOSS1_EFF_SCT_PART_NDC_WORK.spin_quat, ref gMS_BS_CMN_NODE_CTRL_OBJECT.user_quat);
		GmBsCmnSetWorldMtxFromNCObjectPosture(gMS_BS_CMN_NODE_CTRL_OBJECT);
		if (gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer != 0)
		{
			gMS_BS_CMN_NODE_CTRL_OBJECT.user_timer--;
		}
		else
		{
			obj_work.flag |= 4u;
		}
	}

	private static void gmBoss1EffBombInitCreate(GMS_BOSS1_EFF_BOMB_WORK bomb_work, int bomb_type, OBS_OBJECT_WORK parent_obj, int pos_x, int pos_y, int width, int height, uint interval_min, uint interval_max)
	{
		MTM_ASSERT(bomb_work);
		MTM_ASSERT(parent_obj);
		bomb_work.parent_obj = parent_obj;
		bomb_work.bomb_type = bomb_type;
		bomb_work.interval_timer = 0u;
		bomb_work.interval_min = interval_min;
		bomb_work.interval_max = interval_max;
		bomb_work.pos[0] = pos_x;
		bomb_work.pos[1] = pos_y;
		bomb_work.area[0] = width;
		bomb_work.area[1] = height;
		bomb_work.interval_timer_sound = 0;
	}

	private static void gmBoss1EffBombUpdateCreate(GMS_BOSS1_EFF_BOMB_WORK bomb_work)
	{
		MTM_ASSERT(bomb_work.parent_obj);
		if (bomb_work.interval_timer != 0)
		{
			bomb_work.interval_timer--;
			return;
		}
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = null;
		int num = bomb_work.area[0];
		int num2 = bomb_work.area[1];
		int num3 = FX_Mul(AkMathRandFx(), num);
		int num4 = FX_Mul(AkMathRandFx(), num2);
		if (bomb_work.bomb_type == 0)
		{
			gMS_EFFECT_3DES_WORK = GmEfctCmnEsCreate(null, 7);
			if (--bomb_work.interval_timer_sound <= 0)
			{
				bomb_work.interval_timer_sound = 3;
				GmSoundPlaySE("Boss0_02");
			}
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(gMS_EFFECT_3DES_WORK);
			MTM_ASSERT(oBS_OBJECT_WORK);
			oBS_OBJECT_WORK.pos.x = bomb_work.pos[0] - (num >> 1) + num3;
			oBS_OBJECT_WORK.pos.y = bomb_work.pos[1] - (num2 >> 1) + num4;
			oBS_OBJECT_WORK.pos.z = GMM_BS_OBJ(bomb_work.parent_obj).pos.z + 131072;
			uint num5 = (uint)(AkMathRandFx() * (bomb_work.interval_max - bomb_work.interval_min) >> 12);
			bomb_work.interval_timer = bomb_work.interval_min + num5;
		}
		else
		{
			MTM_ASSERT(false);
		}
	}

