	private static bool AoYsdFileIsYsdFile(object file)
	{
		return file is YSDS_HEADER;
	}

	private static uint AoYsdFileGetPageNum(YSDS_HEADER file)
	{
		if (!AoYsdFileIsYsdFile(file))
		{
			return 0u;
		}
		return file.page_num;
	}

	private static uint AoYsdFileGetPageTime(YSDS_HEADER file, uint page_no)
	{
		if (page_no >= AoYsdFileGetPageNum(file))
		{
			return 0u;
		}
		return file.pages[page_no].time;
	}

	private static bool AoYsdFileIsPageShowImage(YSDS_HEADER file, uint page_no)
	{
		if (page_no >= AoYsdFileGetPageNum(file))
		{
			return false;
		}
		if (file.pages[page_no].show < 0)
		{
			return false;
		}
		return true;
	}

	private static uint AoYsdFileGetPageShowImageNo(YSDS_HEADER file, uint page_no)
	{
		if (!AoYsdFileIsPageShowImage(file, page_no))
		{
			return 0u;
		}
		return (uint)file.pages[page_no].show;
	}

	private static bool AoYsdFileIsPageHideImage(YSDS_HEADER file, uint page_no)
	{
		if (page_no >= AoYsdFileGetPageNum(file))
		{
			return false;
		}
		if (file.pages[page_no].hide < 0)
		{
			return false;
		}
		return true;
	}

	private static uint AoYsdFileGetPageOption(YSDS_HEADER file, uint page_no)
	{
		if (page_no >= AoYsdFileGetPageNum(file))
		{
			return 0u;
		}
		return file.pages[page_no].option;
	}

	private static uint AoYsdFileGetLineNum(YSDS_HEADER file, uint page_no)
	{
		return file.pages[page_no].line_num;
	}

	private static uint AoYsdFileGetLineId(YSDS_HEADER file, uint page_no, uint line_no)
	{
		return file.pages[page_no].lines[line_no].id;
	}

	private static string AoYsdFileGetLineString(YSDS_HEADER file, uint page_no, uint line_no)
	{
		return file.pages[page_no].lines[line_no].s;
	}

	public static void MTM_MATH_SWAP<T>(ref T a, ref T b)
	{
		T val = a;
		a = b;
		b = val;
	}

	public static uint MTM_MATH_MAX(uint a, uint b)
	{
		return Math.Max(a, b);
	}

	public static int MTM_MATH_MAX(int a, int b)
	{
		return Math.Max(a, b);
	}

	public static float MTM_MATH_CLIP(float a, float low, float high)
	{
		if (!(a < low))
		{
			if (!(a > high))
			{
				return a;
			}
			return high;
		}
		return low;
	}

	public static int MTM_MATH_CLIP(int a, int low, int high)
	{
		if (a >= low)
		{
			if (a <= high)
			{
				return a;
			}
			return high;
		}
		return low;
	}

	public static uint MTM_MATH_CLIP(uint a, uint low, uint high)
	{
		if (a >= low)
		{
			if (a <= high)
			{
				return a;
			}
			return high;
		}
		return low;
	}

	public static int MTM_MATH_ABS(int a)
	{
		if (a >= 0)
		{
			return a;
		}
		return -a;
	}

	public static float MTM_MATH_ABS(float a)
	{
		return (a < 0f) ? (0f - a) : a;
	}

