	private static void nnSetPrimitiveTexNum(NNS_TEXLIST texlist, int num)
	{
		if (texlist != null && num >= 0 && num < texlist.nTex)
		{
			NNS_TEXINFO[] pTexInfoList = texlist.pTexInfoList;
			nngDrawPrimTexName = pTexInfoList[num].TexName;
			nngDrawPrimTexture = 1;
		}
		else
		{
			nngDrawPrimTexture = 0;
		}
	}

	private static void nnSetPrimitiveTexState(int blend, int coord, int uwrap, int vwrap)
	{
		switch (blend)
		{
		default:
			nngDrawPrimTexBlend = 8448;
			break;
		case 1:
			nngDrawPrimTexBlend = 7681;
			break;
		}
		nngDrawPrimTexCoord = coord;
		switch (uwrap)
		{
		default:
			nngDrawPrimTexSWarp = 10497;
			break;
		case 1:
			nngDrawPrimTexSWarp = 33071;
			break;
		}
		switch (vwrap)
		{
		default:
			nngDrawPrimTexTWarp = 10497;
			break;
		case 1:
			nngDrawPrimTexTWarp = 33071;
			break;
		}
	}

	private static void nnPutPrimitiveTexParameter()
	{
		OpenGL.glClientActiveTexture(33985u);
		OpenGL.glDisableClientState(32888u);
		OpenGL.glClientActiveTexture(33986u);
		OpenGL.glDisableClientState(32888u);
		OpenGL.glClientActiveTexture(33987u);
		OpenGL.glDisableClientState(32888u);
		OpenGL.glActiveTexture(33985u);
		OpenGL.glDisable(3553u);
		OpenGL.glActiveTexture(33984u);
		OpenGL.glEnable(3553u);
		OpenGL.glBindTexture(3553u, nngDrawPrimTexName);
		OpenGL.glTexEnvi(8960u, 8704u, nngDrawPrimTexBlend);
		OpenGL.glTexParameteri(3553u, 10242u, nngDrawPrimTexSWarp);
		OpenGL.glTexParameteri(3553u, 10243u, nngDrawPrimTexTWarp);
	}

	private static void nnPutPrimitiveNoTexture()
	{
		OpenGL.glClientActiveTexture(33984u);
		OpenGL.glDisableClientState(32888u);
		OpenGL.glClientActiveTexture(33985u);
		OpenGL.glDisableClientState(32888u);
		OpenGL.glActiveTexture(33984u);
		OpenGL.glDisable(3553u);
		OpenGL.glActiveTexture(33985u);
		OpenGL.glDisable(3553u);
	}

	private static float NNM_TAYLOR_SIN(float f, float f2)
	{
		return f * (1f + f2 * (-1f / 6f - f2 * (-1f / 120f)));
	}

	private static float NNM_TAYLOR_COS(float f, float f2)
	{
		return 1f + f2 * (-0.5f + f2 * (1f / 24f + f2 * -0.0013888889f));
	}

	private static float nnSin(int ang)
	{
		float result = 0f;
		int num = ang & 0xFFFF;
		switch (ang & 0xE000)
		{
		case 0:
		{
			float num2 = NNM_A32toRAD(num);
			float f = num2 * num2;
			result = NNM_TAYLOR_SIN(num2, f);
			break;
		}
		case 8192:
		case 16384:
		{
			num -= 16384;
			float num2 = NNM_A32toRAD(num);
			float f = num2 * num2;
			result = NNM_TAYLOR_COS(num2, f);
			break;
		}
		case 24576:
		case 32768:
		{
			num -= 32768;
			float num2 = NNM_A32toRAD(num);
			float f = num2 * num2;
			result = 0f - NNM_TAYLOR_SIN(num2, f);
			break;
		}
		case 40960:
		case 49152:
		{
			num -= 49152;
			float num2 = NNM_A32toRAD(num);
			float f = num2 * num2;
			result = 0f - NNM_TAYLOR_COS(num2, f);
			break;
		}
		case 57344:
		{
			num -= 65536;
			float num2 = NNM_A32toRAD(num);
			float f = num2 * num2;
			result = NNM_TAYLOR_SIN(num2, f);
			break;
		}
		}
		return result;
	}

	private static float nnCos(int ang)
	{
		return nnSin(ang + 16384);
	}

	private static void nnCalcSinCosTable()
	{
		for (int i = 0; i < 36000; i++)
		{
			int ang = (int)((float)i * 1.8204443f);
			_nnSinCos(ang, out nnSinTable[i], out nnCosTable[i]);
		}
	}

	private static void nnSinCos(int ang, out float s, out float c)
	{
		int i;
		for (i = (int)Math.Round((float)ang * 0.5493164f); i > 35999; i -= 36000)
		{
		}
		for (; i < 0; i += 36000)
		{
		}
		s = nnSinTable[i];
		c = nnCosTable[i];
	}

	private static void _nnSinCos(int ang, out float s, out float c)
	{
		if (ang == 0)
		{
			s = 0f;
			c = 1f;
		}
		int num = ang & 0xFFFF;
		c = 0f;
		s = 0f;
		switch (ang & 0xE000)
		{
		case 0:
		{
			float num2 = NNM_A32toRAD(num);
			float f = num2 * num2;
			s = NNM_TAYLOR_SIN(num2, f);
			c = NNM_TAYLOR_COS(num2, f);
			break;
		}
		case 8192:
		case 16384:
		{
			num -= 16384;
			float num2 = NNM_A32toRAD(num);
			float f = num2 * num2;
			s = NNM_TAYLOR_COS(num2, f);
			c = 0f - NNM_TAYLOR_SIN(num2, f);
			break;
		}
		case 24576:
		case 32768:
		{
			num -= 32768;
			float num2 = NNM_A32toRAD(num);
			float f = num2 * num2;
			s = 0f - NNM_TAYLOR_SIN(num2, f);
			c = 0f - NNM_TAYLOR_COS(num2, f);
			break;
		}
		case 40960:
		case 49152:
		{
			num -= 49152;
			float num2 = NNM_A32toRAD(num);
			float f = num2 * num2;
			s = 0f - NNM_TAYLOR_COS(num2, f);
			c = NNM_TAYLOR_SIN(num2, f);
			break;
		}
		case 57344:
		{
			num -= 65536;
			float num2 = NNM_A32toRAD(num);
			float f = num2 * num2;
			s = NNM_TAYLOR_SIN(num2, f);
			c = NNM_TAYLOR_COS(num2, f);
			break;
		}
		}
	}

	public void amIPhoneInitNN()
	{
		OpenGL.init(m_game, m_graphicsDevice);
		// El viewport usa la resolución interna (RENDER_W x 288 multiplicado por RENDER_SCALE).
		OpenGL.glViewport(0, 0, Sonic4Ep1.RENDER_W * Sonic4Ep1.RENDER_SCALE, Sonic4Ep1.GAME_H * Sonic4Ep1.RENDER_SCALE);
		int num = 480;
		int num2 = Sonic4Ep1.GAME_H;
		// Aspecto ancho/alto, como espera el motor. La corrección 3D está en OpenGL.SetProjectionAspect.
		float projAspect = (float)Sonic4Ep1.RENDER_W / (float)Sonic4Ep1.GAME_H;
		OpenGL.SetProjectionAspect(projAspect);
		amRenderInit();
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		new NNS_VECTOR(0f, 0f, -1f);
		new NNS_RGBA(1f, 1f, 1f, 1f);
		NNS_CONFIG_GL config = default(NNS_CONFIG_GL);
		config.WindowWidth = num;
		config.WindowHeight = num2;
		nnConfigureSystemGL(config);
		nnMakePerspectiveMatrix(nNS_MATRIX, NNM_DEGtoA32(45f), projAspect, 1f, 10000f);
		_am_draw_video.draw_aspect = projAspect;
		nnSetProjection(nNS_MATRIX, 0);
		_am_draw_video.draw_width = num;
		_am_draw_video.draw_height = num2;
		_am_draw_video.disp_width = num;
		_am_draw_video.disp_height = num2;
		_am_draw_video.width_2d = num;
		_am_draw_video.height_2d = num2;
		_am_draw_video.scale_x_2d = 1f;
		_am_draw_video.scale_y_2d = 1f;
		_am_draw_video.base_x_2d = 0f;
		_am_draw_video.base_y_2d = 0f;
		_am_draw_video.wide_screen = true;
		_am_draw_video.refresh_rate = 60f;
		amRenderInit();
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
	}

