	public static void GmSpStageBranchInit(object arg)
	{
		UNREFERENCED_PARAMETER(arg);
		SYS_EVT_INFO sYS_EVT_INFO = SyGetEvtInfo();
		if (sYS_EVT_INFO.old_evt_id == 5)
		{
			if (g_gs_main_sys_info.stage_id < 21 || g_gs_main_sys_info.stage_id > 27)
			{
				g_gs_main_sys_info.stage_id = 21;
			}
		}
		else if (!GsMainSysIsStageClear(21))
		{
			g_gs_main_sys_info.stage_id = 21;
		}
		else if (!GsMainSysIsStageClear(22))
		{
			g_gs_main_sys_info.stage_id = 22;
		}
		else if (!GsMainSysIsStageClear(23))
		{
			g_gs_main_sys_info.stage_id = 23;
		}
		else if (!GsMainSysIsStageClear(24))
		{
			g_gs_main_sys_info.stage_id = 24;
		}
		else if (!GsMainSysIsStageClear(25))
		{
			g_gs_main_sys_info.stage_id = 25;
		}
		else if (!GsMainSysIsStageClear(26))
		{
			g_gs_main_sys_info.stage_id = 26;
		}
		else
		{
			g_gs_main_sys_info.stage_id = 27;
		}
		g_gs_main_sys_info.char_id[0] = 2;
		g_gs_main_sys_info.game_flag |= 128u;
		GmMainGSInit();
		SyChangeNextEvt();
	}

