	private static OBS_OBJECT_WORK GmGmkSsGoalInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		UNREFERENCED_PARAMETER(type);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_SS_GOAL");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.view_out_ofst -= 128;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_ss_goal_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		oBS_OBJECT_WORK.pos.z = -131072;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 2u;
		oBS_OBJECT_WORK.ppFunc = gmGmkSsGoalMain;
		oBS_OBJECT_WORK.ppOut = gmGmkSsGoalDrawFunc;
		OBS_COLLISION_WORK col_work = gMS_ENEMY_3D_WORK.ene_com.col_work;
		col_work.obj_col.obj = oBS_OBJECT_WORK;
		col_work.obj_col.diff_data = g_gm_default_col;
		col_work.obj_col.width = 24;
		col_work.obj_col.height = 24;
		col_work.obj_col.ofst_x = (short)(-(col_work.obj_col.width / 2));
		col_work.obj_col.ofst_y = (short)(-(col_work.obj_col.height / 2));
		col_work.obj_col.attr = 2;
		col_work.obj_col.flag |= 134217760u;
		return oBS_OBJECT_WORK;
	}

	public static void GmGmkSsGoalBuild()
	{
		gm_gmk_ss_goal_obj_3d_list = GmGameDBuildRegBuildModel(GmGameDatGetGimmickData(907), GmGameDatGetGimmickData(908), 0u);
		AMS_AMB_HEADER aMS_AMB_HEADER = GmGameDatGetGimmickData(909);
		gm_gmk_ss_goal_obj_tvx_list = aMS_AMB_HEADER;
	}

	public static void GmGmkSsGoalFlush()
	{
		AMS_AMB_HEADER aMS_AMB_HEADER = GmGameDatGetGimmickData(907);
		GmGameDBuildRegFlushModel(gm_gmk_ss_goal_obj_3d_list, aMS_AMB_HEADER.file_num);
		gm_gmk_ss_goal_obj_tvx_list = null;
	}

	private static void gmGmkSsGoalMain(OBS_OBJECT_WORK obj_work)
	{
		OBS_COLLISION_OBJ obj_col = obj_work.col_work.obj_col;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((GmSplStageGetWork().flag & 4) != 0)
		{
			obj_work.flag |= 4u;
			return;
		}
		obj_work.dir.z = GmMainGetObjectRotation();
		if (obj_col.toucher_obj == gMS_PLAYER_WORK.obj_work && obj_col.toucher_obj.touch_obj == obj_work && (g_gm_main_system.game_flag & 0x20000) == 0)
		{
			g_gm_main_system.game_flag |= 131072u;
			GmSoundPlaySE("Special4");
		}
	}

	private static void gmGmkSsGoalDrawFunc(OBS_OBJECT_WORK obj_work)
	{
		if (GmMainIsDrawEnable() && (obj_work.disp_flag & 0x20) == 0)
		{
			TVX_FILE tVX_FILE;
			if (gm_gmk_ss_goal_obj_tvx_list.buf[0] == null)
			{
				tVX_FILE = new TVX_FILE((AmbChunk)amBindGet(gm_gmk_ss_goal_obj_tvx_list, 0));
				gm_gmk_ss_goal_obj_tvx_list.buf[0] = tVX_FILE;
			}
			else
			{
				tVX_FILE = (TVX_FILE)gm_gmk_ss_goal_obj_tvx_list.buf[0];
			}
			NNS_TEXLIST texlist = obj_work.obj_3d.texlist;
			GmTvxSetModel(tVX_FILE, texlist, ref obj_work.pos, ref obj_work.scale, GMD_TVX_DISP_LIGHT_DISABLE | GMD_TVX_DISP_ROTATE, (short)(-obj_work.dir.z));
		}
	}

	private static OBS_OBJECT_WORK GmGmkLoopInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
