	private static GMS_ENEMY_3D_WORK gmGmkLoopLoadObjNoModel(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "GMK_LOOP");
		gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag &= 4294967291u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[1].flag &= 4294967291u;
