	}

	private static void gmGmkLoopInit(OBS_OBJECT_WORK obj_work)
	{
		gmGmkLoopSetRect(obj_work);
		obj_work.move_flag |= 8448u;
		obj_work.ppFunc = gmGmkLoopMainFunc;
	}

	private static void gmGmkLoopSetRect(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		short cLeft = (short)(-gMS_ENEMY_3D_WORK.ene_com.eve_rec.width * 64 / 2);
		short cRight = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.width * 64 / 2);
		short cTop = (short)(-gMS_ENEMY_3D_WORK.ene_com.eve_rec.height * 64 / 2);
		short cBottom = (short)(gMS_ENEMY_3D_WORK.ene_com.eve_rec.height * 64 / 2);
		ObjRectWorkZSet(oBS_RECT_WORK, cLeft, cTop, -500, cRight, cBottom, 500);
		oBS_RECT_WORK.flag |= 1024u;
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		oBS_RECT_WORK.ppDef = gmGmkLoopDefFunc;
	}

	private static void gmGmkLoopDefFunc(OBS_RECT_WORK own_rect, OBS_RECT_WORK target_rect)
	{
		UNREFERENCED_PARAMETER(target_rect);
		own_rect.parent_obj.user_flag |= 1u;
	}

	private static void gmGmkLoopMainFunc(OBS_OBJECT_WORK obj_work)
	{
		if ((obj_work.user_flag & 1) != 0)
		{
			gmGmkLoopExecute(obj_work);
			obj_work.user_flag &= 4294967294u;
		}
	}

	private static void gmGmkLoopExecute(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		int loop_x = gMS_ENEMY_3D_WORK.ene_com.eve_rec.left * 64 * 4096;
		int loop_y = gMS_ENEMY_3D_WORK.ene_com.eve_rec.top * 64 * 4096;
		gmGmkLoopExecuteObj(loop_x, loop_y, 1);
		gmGmkLoopExecuteObj(loop_x, loop_y, 2);
		gmGmkLoopExecuteEffect(loop_x, loop_y);
		gmGmkLoopExecuteRing(loop_x, loop_y);
		gmGmkLoopExecuteCamera(loop_x, loop_y);
		GmEveMgrCreateEventLcd(0u);
	}

	private static void gmGmkLoopExecuteObj(int loop_x, int loop_y, int obj_type)
	{
		for (OBS_OBJECT_WORK oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, (ushort)obj_type); oBS_OBJECT_WORK != null; oBS_OBJECT_WORK = ObjObjectSearchRegistObject(oBS_OBJECT_WORK, (ushort)obj_type))
		{
			oBS_OBJECT_WORK.pos.x += loop_x;
			oBS_OBJECT_WORK.pos.y += loop_y;
		}
	}

	private static void gmGmkLoopExecuteEffect(int loop_x, int loop_y)
	{
		for (OBS_OBJECT_WORK oBS_OBJECT_WORK = ObjObjectSearchRegistObject(null, 5); oBS_OBJECT_WORK != null; oBS_OBJECT_WORK = ObjObjectSearchRegistObject(oBS_OBJECT_WORK, 5))
		{
			oBS_OBJECT_WORK.pos.x += loop_x;
			oBS_OBJECT_WORK.pos.y += loop_y;
			if (oBS_OBJECT_WORK.obj_3des != null)
			{
				GmEffect3DESSetDuplicateDraw((GMS_EFFECT_3DES_WORK)oBS_OBJECT_WORK, FX_FX32_TO_F32(loop_x), FX_FX32_TO_F32(loop_y), 0f);
			}
		}
	}

	private static void gmGmkLoopExecuteRing(int loop_x, int loop_y)
	{
		GMS_RING_SYS_WORK gMS_RING_SYS_WORK = GmRingGetWork();
		for (GMS_RING_WORK gMS_RING_WORK = gMS_RING_SYS_WORK.damage_ring_list_start; gMS_RING_WORK != null; gMS_RING_WORK = gMS_RING_WORK.post_ring)
		{
			gMS_RING_WORK.pos.x += loop_x;
			gMS_RING_WORK.pos.y += loop_y;
		}
	}

	private static void gmGmkLoopExecuteCamera(int loop_x, int loop_y)
	{
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
		GmCameraPosSet(FX_F32_TO_FX32(oBS_CAMERA.pos.x) + loop_x, -FX_F32_TO_FX32(oBS_CAMERA.pos.y) + loop_y, FX_F32_TO_FX32(oBS_CAMERA.pos.z));
		ObjObjectCameraSet(FXM_FLOAT_TO_FX32(oBS_CAMERA.disp_pos.x - (float)(OBD_LCD_X / 2)), FXM_FLOAT_TO_FX32(0f - oBS_CAMERA.disp_pos.y - (float)(OBD_LCD_Y / 2)), FXM_FLOAT_TO_FX32(oBS_CAMERA.disp_pos.x - (float)(OBD_LCD_X / 2)), FXM_FLOAT_TO_FX32(0f - oBS_CAMERA.disp_pos.y - (float)(OBD_LCD_Y / 2)));
		GmCameraSetClipCamera(oBS_CAMERA);
	}

