	private static OBS_OBJECT_WORK GmGmkForceSpinResetInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		UNREFERENCED_PARAMETER(type);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_COM_WORK(), "GMK_FORCE_SPIN_RESET");
