			}
			num = FX_Mul(num, num5);
			num2 = FX_Mul(num2, num6);
			int flag_no_recover_homing = 0;
			if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 1) != 0)
			{
				flag_no_recover_homing = 1;
			}
			int no_spddown_timer = 0;
			if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 2) != 0)
			{
				no_spddown_timer = 30;
			}
			GmPlayerSetAtk(gMS_PLAYER_WORK);
			GmPlySeqInitPinballAir(gMS_PLAYER_WORK, num, num2, 5, flag_no_recover_homing, no_spddown_timer);
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctCmnEsCreate(obj_work, 16);
