	private static void gmGmkFlipperSetRideSpeed(OBS_OBJECT_WORK target_obj_work, OBS_OBJECT_WORK gimmick_obj_work, int flipper_type)
	{
		UNREFERENCED_PARAMETER(gimmick_obj_work);
		int num = FX_F32_TO_FX32(24f / 35f);
