		if (flipper_type == 1)
		{
			num = 0f - num;
		}
		float num2 = (float)(g_gmk_flipper_rect[flipper_type][3] - g_gmk_flipper_rect[flipper_type][1]) + -2f;
		return FX_Mul((int)(num2 / num * 4096f), x - gimmick_obj_work.pos.x);
	}

	private static int gmGmkFlipperUpdateAngle(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_timer++;
		ushort num = (ushort)obj_work.user_work;
		ushort num2 = (ushort)((num - obj_work.dir.z) / 6);
		obj_work.dir.z += num2;
		if (obj_work.user_timer < 6)
		{
			return 0;
