	public static int gmEneStingSetWalkSpeed(GMS_ENE_STING_WORK sting_work)
	{
		int result = 0;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)sting_work;
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			if (oBS_OBJECT_WORK.obj_3d.act_id[0] == 3 && oBS_OBJECT_WORK.obj_3d.frame[0] >= (float)(GMD_ENE_STING_TURN_FRAME / 2))
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, sting_work.spd_dec, GMD_ENE_STING_SPD_X);
			}
			else if (oBS_OBJECT_WORK.pos.x <= Convert.ToInt32(oBS_OBJECT_WORK.user_work) + sting_work.spd_dec_dist)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdDownSet(oBS_OBJECT_WORK.spd.x, sting_work.spd_dec);
				result = 1;
				if (oBS_OBJECT_WORK.spd.x == 0 && oBS_OBJECT_WORK.pos.x > (int)oBS_OBJECT_WORK.user_work)
				{
					oBS_OBJECT_WORK.spd.x = (int)oBS_OBJECT_WORK.user_work - oBS_OBJECT_WORK.pos.x;
					if (oBS_OBJECT_WORK.spd.x < -sting_work.spd_dec)
					{
						oBS_OBJECT_WORK.spd.x = -sting_work.spd_dec;
					}
				}
			}
			else if (oBS_OBJECT_WORK.spd.x > -GMD_ENE_STING_SPD_X)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, -sting_work.spd_dec, GMD_ENE_STING_SPD_X);
			}
		}
		else if (oBS_OBJECT_WORK.obj_3d.act_id[0] == 2 && oBS_OBJECT_WORK.obj_3d.frame[0] >= (float)(GMD_ENE_STING_TURN_FRAME / 2))
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, -sting_work.spd_dec, GMD_ENE_STING_SPD_X);
		}
		else if (oBS_OBJECT_WORK.pos.x >= Convert.ToUInt32(oBS_OBJECT_WORK.user_flag) - sting_work.spd_dec_dist)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdDownSet(oBS_OBJECT_WORK.spd.x, sting_work.spd_dec);
			result = 1;
			if (oBS_OBJECT_WORK.spd.x == 0 && oBS_OBJECT_WORK.pos.x < Convert.ToInt32(oBS_OBJECT_WORK.user_flag))
			{
				oBS_OBJECT_WORK.spd.x = Convert.ToInt32(oBS_OBJECT_WORK.user_flag) - oBS_OBJECT_WORK.pos.x;
				if (oBS_OBJECT_WORK.spd.x > sting_work.spd_dec)
				{
					oBS_OBJECT_WORK.spd.x = sting_work.spd_dec;
				}
			}
		}
		else if (oBS_OBJECT_WORK.spd.x < GMD_ENE_STING_SPD_X)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, sting_work.spd_dec, GMD_ENE_STING_SPD_X);
		}
		return result;
	}

