		gMS_EFFECT_COM_WORK.obj_work.spd.y = spd_y;
		gMS_EFFECT_COM_WORK.obj_work.view_out_ofst = 16;
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctCmnEsCreate(gMS_EFFECT_COM_WORK.obj_work, 15);
		GmComEfctSetDispRotationS(gMS_EFFECT_3DES_WORK, 0, 0, dir);
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.flag |= 1024u;
		gMS_EFFECT_3DES_WORK = GmEfctCmnEsCreate(parent_obj, 14);
		GmComEfctSetDispRotationS(gMS_EFFECT_3DES_WORK, 0, 0, (short)(dir - 32768));
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.parent_obj = null;
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.x += (((parent_obj.disp_flag & 1) != 0) ? (-ofst_flash_x) : ofst_flash_x);
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.y += ofst_flash_y;
		gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.z += ofst_flash_z;
	}

	public static void gmEneStingJetEfctMain(OBS_OBJECT_WORK obj_work)
	{
		NNS_MATRIX nNS_MATRIX = (NNS_MATRIX)obj_work.user_work_OBJECT;
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		if (obj_work.parent_obj == null)
		{
			obj_work.flag |= 4u;
			return;
		}
		nNS_VECTOR.x = nNS_MATRIX.M03 - FXM_FX32_TO_FLOAT(obj_work.parent_obj.pos.x);
		nNS_VECTOR.y = 0f - nNS_MATRIX.M13 - FXM_FX32_TO_FLOAT(obj_work.parent_obj.pos.y);
		nNS_VECTOR.z = nNS_MATRIX.M23 - FXM_FX32_TO_FLOAT(obj_work.parent_obj.pos.z);
		if ((obj_work.parent_obj.disp_flag & 1) != 0)
		{
			nNS_VECTOR.x = 0f - nNS_VECTOR.x;
			nNS_VECTOR.z = 0f - nNS_VECTOR.z;
		}
		nNS_VECTOR.x += -3f;
		GmComEfctSetDispOffsetF((GMS_EFFECT_3DES_WORK)obj_work, nNS_VECTOR.x, nNS_VECTOR.y, nNS_VECTOR.z);
		GmEffectDefaultMainFuncDeleteAtEndCopyDirZ(obj_work);
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	public static void gmEneStingWalkInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GmEneComActionSetDependHFlip(obj_work, 0, 1);
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneStingWalkMain;
