	public static void gmEneStingMotionCallback(AMS_MOTION motion, NNS_OBJECT _object, object param)
	{
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		NNS_MATRIX nNS_MATRIX2 = GlobalPool<NNS_MATRIX>.Alloc();
		GMS_ENE_STING_WORK gMS_ENE_STING_WORK = (GMS_ENE_STING_WORK)param;
		nnMakeUnitMatrix(nNS_MATRIX2);
		nnMultiplyMatrix(nNS_MATRIX2, nNS_MATRIX2, amMatrixGetCurrent());
		nnCalcNodeMatrixTRSList(nNS_MATRIX, _object, GMD_ENE_STING_NODE_ID_R_JET, motion.data, nNS_MATRIX2);
		gMS_ENE_STING_WORK.jet_r_mtx.Assign(nNS_MATRIX);
		nnCalcNodeMatrixTRSList(nNS_MATRIX, _object, GMD_ENE_STING_NODE_ID_L_JET, motion.data, nNS_MATRIX2);
		gMS_ENE_STING_WORK.jet_l_mtx.Assign(nNS_MATRIX);
		nnCalcNodeMatrixTRSList(nNS_MATRIX, _object, GMD_ENE_STING_NODE_ID_GUN, motion.data, nNS_MATRIX2);
		gMS_ENE_STING_WORK.gun_mtx.Assign(nNS_MATRIX);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX2);
	}

	public static void gmEneStingSearchDefFunc(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		if (match_rect.parent_obj.obj_type != 1)
		{
			return;
		}
		GMS_ENE_STING_WORK gMS_ENE_STING_WORK = (GMS_ENE_STING_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_PLAYER_WORK.rect_work[2];
		float num = FXM_FX32_TO_FLOAT(gMS_PLAYER_WORK.obj_work.pos.x) + (float)(oBS_RECT_WORK.rect.left + oBS_RECT_WORK.rect.right >> 1);
		float num2 = FXM_FX32_TO_FLOAT(gMS_PLAYER_WORK.obj_work.pos.y) + (float)(oBS_RECT_WORK.rect.top + oBS_RECT_WORK.rect.bottom >> 1);
		oBS_RECT_WORK = gMS_ENE_STING_WORK.ene_3d_work.ene_com.rect_work[2];
		float num3 = FXM_FX32_TO_FLOAT(gMS_ENE_STING_WORK.ene_3d_work.ene_com.obj_work.pos.x) + (float)(oBS_RECT_WORK.rect.left + oBS_RECT_WORK.rect.right >> 1);
		float num4 = FXM_FX32_TO_FLOAT(gMS_ENE_STING_WORK.ene_3d_work.ene_com.obj_work.pos.y + GMD_ENE_STING_GUN_OFST_Y) + (float)(oBS_RECT_WORK.rect.top + oBS_RECT_WORK.rect.bottom >> 1);
		int a;
		int b;
		if ((gMS_ENE_STING_WORK.ene_3d_work.ene_com.obj_work.disp_flag & 1) != 0)
		{
			a = 32768 - GMD_ENE_STING_SEARCH_DIR_START;
			b = 32768 - GMD_ENE_STING_SEARCH_DIR_END;
		}
		else
		{
			a = GMD_ENE_STING_SEARCH_DIR_START;
			b = GMD_ENE_STING_SEARCH_DIR_END;
		}
		if (b < a)
		{
			MTM_MATH_SWAP(ref a, ref b);
		}
		float num5 = num - num3;
		float num6 = num2 - num4;
		int num7 = nnArcTan2(num6, num5);
		if (num7 >= a && num7 <= b)
		{
			gMS_ENE_STING_WORK.bullet_spd_x = (int)((float)GMD_ENE_STING_BULLET_SPD * nnCos(num7));
			gMS_ENE_STING_WORK.bullet_spd_y = (int)((float)GMD_ENE_STING_BULLET_SPD * nnSin(num7));
			if ((gMS_ENE_STING_WORK.ene_3d_work.ene_com.obj_work.disp_flag & 1) != 0)
			{
				gMS_ENE_STING_WORK.bullet_dir = (short)(num7 - 32768);
			}
			else
			{
				gMS_ENE_STING_WORK.bullet_dir = (short)num7;
			}
			gmEneStingAtkInit((OBS_OBJECT_WORK)gMS_ENE_STING_WORK);
			gMS_ENE_STING_WORK.search_rect_work.flag &= 4294967291u;
		}
	}

	public static void gmEneStingRegRectFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_STING_WORK gMS_ENE_STING_WORK = (GMS_ENE_STING_WORK)obj_work;
		ObjObjectRectRegist(obj_work, gMS_ENE_STING_WORK.search_rect_work);
	}

	public static void gmEneStingAtkMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_STING_WORK gMS_ENE_STING_WORK = (GMS_ENE_STING_WORK)obj_work;
		if (obj_work.user_timer != 0)
		{
			obj_work.user_timer--;
			if (obj_work.user_timer != 0)
			{
				return;
			}
			if (obj_work.obj_3d.act_id[0] == 4 || obj_work.obj_3d.act_id[0] == 7)
			{
				GmEneStingCreateBullet(obj_work, GMD_ENE_STING_BULLET_FLASH_OFST_X, GMD_ENE_STING_BULLET_FLASH_OFST_Y, GMD_ENE_STING_BULLET_FLASH_OFST_Z, GMD_ENE_STING_BULLET_OFST_X, GMD_ENE_STING_BULLET_OFST_Y, GMD_ENE_STING_BULLET_OFST_Z, gMS_ENE_STING_WORK.bullet_spd_x, gMS_ENE_STING_WORK.bullet_spd_y, gMS_ENE_STING_WORK.bullet_dir);
				GmEneComActionSetDependHFlip(obj_work, 5, 8);
				GmSoundPlaySE("Sting");
			}
			else
			{
				GmEneComActionSetDependHFlip(obj_work, 6, 9);
			}
		}
		if ((obj_work.disp_flag & 8) != 0)
		{
			switch (obj_work.obj_3d.act_id[0])
			{
			case 4:
			case 7:
				obj_work.user_timer = GMD_ENE_STING_BULLET_WAIT;
				break;
			case 5:
			case 8:
				obj_work.user_timer = GMD_ENE_STING_BULLET_AFTER_WAIT;
				break;
			case 6:
			case 9:
				gmEneStingWalkInit(obj_work);
				break;
			}
		}
	}

