	private static OBS_OBJECT_WORK GmBoss4BodyInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		UNREFERENCED_PARAMETER(type);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_BOSS4_BODY_WORK(), "BOSS4_BODY");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.pos.y = FX_F32_TO_FX32(GMD_BOSS4_BODY_START_POS_Y);
		oBS_OBJECT_WORK.pos.z = -131072;
		gMS_BOSS4_BODY_WORK.atk_nml_alt = FX_F32_TO_FX32(GMD_BOSS4_BODY_END_POS_Y);
		oBS_OBJECT_WORK.flag |= 16u;
		oBS_OBJECT_WORK.disp_flag |= 4194309u;
		oBS_OBJECT_WORK.move_flag |= 4096u;
		oBS_OBJECT_WORK.move_flag &= 4294967167u;
		gMS_ENEMY_3D_WORK.ene_com.vit = 1;
		ObjRectWorkSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[0], -40, -16, 40, 2);
		gMS_ENEMY_3D_WORK.ene_com.rect_work[0].ppDef = gmBoss4BodyDamageDefFunc;
		ObjRectWorkSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[1], -32, -8, 32, 40);
		gMS_ENEMY_3D_WORK.ene_com.rect_work[1].ppHit = gmBoss4BodyAtkHitFunc;
		ObjRectWorkSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[2], -30, -18, 30, 40);
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].ppHit = gmBoss4BodyDefHitFunc;
		ObjRectGroupSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[2], 1, 1);
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294965247u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag |= 4u;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, GmBoss4GetObj3D(0), gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(730), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.disp_flag |= 134217728u;
		oBS_OBJECT_WORK.ppFunc = gmBoss4BodyWaitLoad;
		gmBoss4BodyChangeState(gMS_BOSS4_BODY_WORK, 0);
		oBS_OBJECT_WORK.ppOut = gmBoss4BodyOutFunc;
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmBoss4BodyExit);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

