	private static void gmBoss4BodySetActionWhole(GMS_BOSS4_BODY_WORK body_work, int act_id)
	{
		gmBoss4BodySetActionWhole(body_work, act_id, false);
	}

	private static void gmBoss4BodySetActionWhole(GMS_BOSS4_BODY_WORK body_work, int act_id, bool force_change)
	{
		GMS_BOSS4_PART_ACT_INFO[] array = gm_boss4_act_id_tbl[act_id];
		if (!force_change && body_work.whole_act_id == act_id)
		{
			return;
		}
		body_work.whole_act_id = act_id;
		for (int i = 0; i < 2; i++)
		{
			if (body_work.parts_objs[i] == null)
			{
				continue;
			}
			if (i == 1)
			{
				GMS_BOSS4_EGG_WORK gMS_BOSS4_EGG_WORK = (GMS_BOSS4_EGG_WORK)body_work.parts_objs[i];
				body_work.egg_revert_mtn_id = act_id;
				ushort act_id2 = GmBoss4GetActInfo(body_work.egg_revert_mtn_id, 1).act_id;
				if (act_id2 == 4)
				{
					if (GmBoss4Is2ndStage())
					{
						body_work.egg_revert_mtn_id = 5;
					}
					else
					{
						body_work.egg_revert_mtn_id = 3;
					}
				}
				if ((gMS_BOSS4_EGG_WORK.flag & 1) != 0)
				{
					continue;
				}
			}
			if (array[i].is_maintain == 0)
			{
				GmBsCmnSetAction(body_work.parts_objs[i], array[i].act_id, array[i].is_repeat, array[i].is_blend);
			}
			else if (array[i].is_repeat != 0)
			{
				GMM_BS_OBJ(body_work).disp_flag |= 4u;
			}
			body_work.parts_objs[i].obj_3d.speed[0] = array[i].mtn_spd;
			body_work.parts_objs[i].obj_3d.blend_spd = array[i].blend_spd;
		}
	}

