		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		bool flag = false;
		if (MTM_MATH_ABS(oBS_OBJECT_WORK.spd.x) >= FX_F32_TO_FX32(GMD_BOSS4_BODY_PRE_ATKNML_SPD_MAX_ABS))
		{
			oBS_OBJECT_WORK.spd.x = -FX_F32_TO_FX32(GMD_BOSS4_BODY_PRE_ATKNML_SPD_MAX_ABS);
			oBS_OBJECT_WORK.spd_add.x = 0;
		}
		if (oBS_OBJECT_WORK.pos.x <= GMM_BOSS4_AREA_LEFT() + FX_F32_TO_FX32(74f))
		{
			oBS_OBJECT_WORK.pos.x = GMM_BOSS4_AREA_LEFT() + FX_F32_TO_FX32(74f);
			flag = true;
		}
		if (flag)
		{
