	private static bool gmBoss4BodyUpdateAtkNmlMove(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		int num = GMM_BOSS4_AREA_LEFT() + FX_F32_TO_FX32(74f);
		int num2 = GMM_BOSS4_AREA_LEFT() + FX_F32_TO_FX32(310f);
		if (body_work.dir.direction == 1)
		{
			int num3 = num;
			num = num2;
			num2 = num3;
		}
		if (body_work.move_cnt < body_work.move_time)
		{
			int gMD_BOSS4_BODY_ATKNML_MOVE_CURVE_ANGLE_WIDTH = GMD_BOSS4_BODY_ATKNML_MOVE_CURVE_ANGLE_WIDTH;
			int gMD_BOSS4_BODY_ATKNML_MOVE_CURVE_START_ANGLE = GMD_BOSS4_BODY_ATKNML_MOVE_CURVE_START_ANGLE;
			body_work.move_cnt++;
			int num4 = (int)((float)gMD_BOSS4_BODY_ATKNML_MOVE_CURVE_ANGLE_WIDTH / (float)body_work.move_time);
			float num5 = nnCos(gMD_BOSS4_BODY_ATKNML_MOVE_CURVE_START_ANGLE) - nnCos(gMD_BOSS4_BODY_ATKNML_MOVE_CURVE_START_ANGLE + gMD_BOSS4_BODY_ATKNML_MOVE_CURVE_ANGLE_WIDTH);
			float num6 = (nnCos(gMD_BOSS4_BODY_ATKNML_MOVE_CURVE_START_ANGLE) - nnCos(gMD_BOSS4_BODY_ATKNML_MOVE_CURVE_START_ANGLE + num4 * body_work.move_cnt)) / num5;
			oBS_OBJECT_WORK.pos.x = num + (int)((float)(num2 - num) * num6);
			return false;
		}
		oBS_OBJECT_WORK.pos.x = num2;
		return true;
	}

	private static void gmBoss4BodySetFlipForAtkNmlMove(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		int num = GMM_BOSS4_AREA_CENTER_X();
		if (oBS_OBJECT_WORK.pos.x < num)
		{
			body_work.dir.direction = 0;
		}
		else
		{
			body_work.dir.direction = 1;
		}
	}

	private static void gmBoss4BodyInitAtkNmlFlipAndTurn(GMS_BOSS4_BODY_WORK body_work)
	{
		int gMD_BOSS4_BODY_ATKNML_TURN_FRAME = GMD_BOSS4_BODY_ATKNML_TURN_FRAME;
