	private static void gmBoss4BodyInitAtkNmlDrift(GMS_BOSS4_BODY_WORK body_work, int frame)
	{
		OBS_OBJECT_WORK obj_work = GMM_BS_OBJ(body_work);
		MTM_ASSERT(frame > 0);
		GmBsCmnSetObjSpdZero(obj_work);
		body_work.drift_angle = 0;
		body_work.drift_ang_spd = (int)nnRoundOff((float)AKM_DEGtoA32(180f) / (float)frame + 0.5f);
		body_work.drift_timer = frame;
		if (body_work.dir.direction == 1)
		{
			body_work.drift_pivot_x = GMM_BOSS4_AREA_LEFT() + FX_F32_TO_FX32(310f);
		}
		else
		{
			body_work.drift_pivot_x = GMM_BOSS4_AREA_LEFT() + FX_F32_TO_FX32(74f);
		}
		gmBoss4BodyUpdateAtkNmlDrift(body_work);
	}

	private static bool gmBoss4BodyUpdateAtkNmlDrift(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		int num;
		bool result;
		if (body_work.drift_timer != 0)
		{
			body_work.drift_timer--;
			body_work.drift_angle = (int)(0xFFFFL & (long)(body_work.drift_angle + body_work.drift_ang_spd));
			num = FX_Mul(FX_Sin(body_work.drift_angle), FX_F32_TO_FX32(16f));
			result = false;
		}
		else
		{
			num = 0;
			result = true;
		}
		if (body_work.dir.direction == 0)
		{
			num = -num;
		}
		oBS_OBJECT_WORK.pos.x = body_work.drift_pivot_x + num;
		return result;
	}

	private static void gmBoss4BodyInitEscapeMove(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		oBS_OBJECT_WORK.spd.x = 0;
		if (body_work.dir.direction == 1)
		{
			oBS_OBJECT_WORK.spd_add.x = -409;
		}
		else
		{
			oBS_OBJECT_WORK.spd_add.x = 409;
		}
		oBS_OBJECT_WORK.spd_add.y = 204;
	}

	private static bool gmBoss4BodyUpdateEscapeMove(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		bool flag = false;
		if (MTM_MATH_ABS(oBS_OBJECT_WORK.spd.x) >= 11264)
		{
			oBS_OBJECT_WORK.spd.x = 11264;
			oBS_OBJECT_WORK.spd.y = -1536;
			oBS_OBJECT_WORK.spd_add.x = 0;
			oBS_OBJECT_WORK.spd_add.y = 0;
		}
		float num = g_gm_main_system.map_fcol.right;
		if (oBS_OBJECT_WORK.pos.x > FX_F32_TO_FX32(num + 100f))
		{
			flag = true;
		}
		if (flag)
		{
			GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
		}
		return flag;
	}

	private static void gmBoss4BodyInitDefeatState(GMS_BOSS4_BODY_WORK body_work)
	{
		bool flag = false;
		if ((body_work.flag[0] & 1) != 0)
		{
			flag = true;
		}
		gmBoss4BodyChangeState(body_work, 7, true);
		if (flag)
		{
			body_work.flag[0] |= 1u;
		}
		else
		{
			body_work.flag[0] &= 4294967294u;
		}
		GmSoundChangeWinBossBGM();
	}

