	private static void gmBoss4BodyDamageDefFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		OBS_OBJECT_WORK parent_obj = my_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = your_rect.parent_obj;
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)parent_obj;
		if (parent_obj2 == null || 1 != parent_obj2.obj_type)
		{
			return;
		}
		GmBoss4UtilSetPlayerAttackReaction(parent_obj2, parent_obj);
		if (gMS_BOSS4_BODY_WORK.nohit_work.timer == 0)
		{
			GmSoundPlaySE("Boss0_01");
			gmBoss4EffDamageInit(gMS_BOSS4_BODY_WORK);
			gmBoss4BodyExecDamageRoutine(gMS_BOSS4_BODY_WORK);
			if (GmBoss4Is2ndStage())
			{
				GmBoss4ChibiExplosion();
				gMS_BOSS4_BODY_WORK.wait_timer = 60u;
				gMS_BOSS4_BODY_WORK.proc_update = gmBoss4BodyStateUpdate2nd;
			}
			GMM_PAD_VIB_SMALL_TIME(30f);
		}
		GmBoss4UtilInitNoHitTimer(gMS_BOSS4_BODY_WORK.nohit_work, (GMS_ENEMY_COM_WORK)parent_obj, 10);
	}

	private static void gmBoss4BodyDefHitFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		OBS_OBJECT_WORK parent_obj = my_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = your_rect.parent_obj;
		parent_obj2.pos.x = parent_obj2.pos.x - parent_obj2.move.x;
		if (parent_obj.pos.x > parent_obj2.pos.x)
		{
			parent_obj2.pos.x -= FX_F32_TO_FX32(2f);
			parent_obj2.spd.x = -MTM_MATH_ABS(parent_obj2.spd.x);
			parent_obj2.spd_m = -MTM_MATH_ABS(parent_obj2.spd_m);
		}
		if (parent_obj.pos.x < parent_obj2.pos.x)
		{
			parent_obj2.pos.x += FX_F32_TO_FX32(2f);
			parent_obj2.spd.x = MTM_MATH_ABS(parent_obj2.spd.x);
			parent_obj2.spd_m = MTM_MATH_ABS(parent_obj2.spd_m);
		}
	}

