	private static void gmBoss4BodyWaitLoad(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)obj_work;
		if (GmBoss4IsBuilded())
		{
			GmBoss4UtilInitNodeMatrix(gMS_BOSS4_BODY_WORK.node_work, obj_work, 6);
			GmBoss4UtilGetNodeMatrix(gMS_BOSS4_BODY_WORK.node_work, 2);
			GmBoss4UtilGetNodeMatrix(gMS_BOSS4_BODY_WORK.node_work, 2);
			GmBoss4UtilGetNodeMatrix(gMS_BOSS4_BODY_WORK.node_work, 9);
			GmBoss4UtilGetNodeMatrix(gMS_BOSS4_BODY_WORK.node_work, 10);
			GmBoss4UtilGetNodeMatrix(gMS_BOSS4_BODY_WORK.node_work, 5);
			GmBoss4UtilGetNodeMatrix(gMS_BOSS4_BODY_WORK.node_work, 8);
			GmBsCmnCreateCNMMgrWork(gMS_BOSS4_BODY_WORK.cnm_mgr_work, obj_work.obj_3d._object, 1);
			GmBsCmnInitCNMCb(obj_work, gMS_BOSS4_BODY_WORK.cnm_mgr_work);
			gMS_BOSS4_BODY_WORK.chaintop_cnm_reg_id = GmBsCmnRegisterCNMNode(gMS_BOSS4_BODY_WORK.cnm_mgr_work, 0);
			obj_work.ppFunc = gmBoss4BodyMain;
			gMS_BOSS4_BODY_WORK.damage_timer = 0;
			GmBoss4UtilInitNoHitTimer(gMS_BOSS4_BODY_WORK.nohit_work, (GMS_ENEMY_COM_WORK)gMS_BOSS4_BODY_WORK, 0);
			if (GmBoss4CheckBossRush())
			{
				gmBoss4BodyChangeState(gMS_BOSS4_BODY_WORK, 5);
			}
			else
			{
				gmBoss4BodyChangeState(gMS_BOSS4_BODY_WORK, 1);
			}
		}
	}

	private static void gmBoss4BodyMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)obj_work;
		GmBoss4UtilUpdateNoHitTimer(gMS_BOSS4_BODY_WORK.nohit_work);
		if (gMS_BOSS4_BODY_WORK.proc_update != null)
		{
			gMS_BOSS4_BODY_WORK.proc_update(gMS_BOSS4_BODY_WORK);
		}
		gmBoss4BodyUpdateSuspendAction(gMS_BOSS4_BODY_WORK);
		gmBoss4EffAfterburnerUpdateCreate(gMS_BOSS4_BODY_WORK);
		if ((gMS_BOSS4_BODY_WORK.flag[0] & 0x80000000u) != 0)
		{
			gMS_BOSS4_BODY_WORK.flag[0] &= 1073741823u;
			gmBoss4BodyInitDefeatState(gMS_BOSS4_BODY_WORK);
			return;
		}
		if (gMS_BOSS4_BODY_WORK.damage_timer > 0)
		{
			gMS_BOSS4_BODY_WORK.damage_timer--;
		}
		if ((gMS_BOSS4_BODY_WORK.flag[0] & 0x40000000) != 0)
		{
			gMS_BOSS4_BODY_WORK.flag[0] &= 3221225471u;
			gMS_BOSS4_BODY_WORK.flag[0] |= 536870912u;
			GmBsCmnInitObject3DNNDamageFlicker(obj_work, gMS_BOSS4_BODY_WORK.flk_work, 32f);
		}
		GmBsCmnUpdateObject3DNNDamageFlicker(obj_work, gMS_BOSS4_BODY_WORK.flk_work);
		GmBoss4UtilUpdateDirection(gMS_BOSS4_BODY_WORK.dir, obj_work);
		gmBoss4BodyUpdateChainTopDirection(gMS_BOSS4_BODY_WORK);
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)GmBsCmnGetPlayerObj();
		if (gMS_PLAYER_WORK.seq_state == 17 || gMS_PLAYER_WORK.seq_state == 19)
		{
			gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		}
		else
		{
			gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag |= 4u;
		}
	}

	private static void gmBoss4BodyStateEnterStart(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		oBS_OBJECT_WORK.flag |= 2u;
		body_work.flag[0] |= 64u;
		gmBoss4BodySetActionWhole(body_work, 0, true);
		body_work.flag[0] |= 32u;
		GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
		GmBoss4UtilSetDirectionNormal(body_work.dir);
		body_work.wait_timer = 120u;
		body_work.proc_update = gmBoss4BodyStateUpdateStartWithWait;
		gmBoss4EffBossLightSetEnable(body_work, true);
	}

