	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		gmBoss4EffAfterburnerSetEnable(body_work, 0);
		body_work.flag[0] &= 4294967231u;
		oBS_OBJECT_WORK.flag &= 4294967293u;
		body_work.flag[0] &= 4294967263u;
	}

	private static void gmBoss4BodyStateUpdateStartWithWait(GMS_BOSS4_BODY_WORK body_work)
	{
		if (gmBoss4IsScrollLockBusy())
		{
			body_work.proc_update = gmBoss4BodyStateUpdateStartWithWaitEnd;
		}
	}

	private static void gmBoss4BodyStateUpdateStartWithWaitEnd(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK obj_work = GMM_BS_OBJ(body_work);
		if (!gmBoss4IsScrollLockBusy())
		{
			GmBsCmnSetObjSpd(obj_work, 0, 4096, 0);
			body_work.proc_update = gmBoss4BodyStateUpdateStartWithFall;
			GmBoss4CapsuleSetInvincible(600, false);
			GmBoss4ChibiSetInvincible(false);
			body_work.wait_timer2 = 90u;
			body_work.flag[0] |= 268435456u;
			body_work.wait_timer = 120u;
			GmBoss4UtilLookAtPlayer(body_work.dir, obj_work, 1);
			GmBoss4UtilLookAt(body_work.dir);
			GmMapSetMapDrawSize(6);
		}
	}

	private static void gmBoss4BodyStateUpdateStartWithFall(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		gMS_ENEMY_3D_WORK.ene_com.enemy_flag |= 32768u;
		if (body_work.wait_timer2 != 0)
		{
			body_work.wait_timer2--;
			GmBoss4UtilLookAtPlayer(body_work.dir, oBS_OBJECT_WORK, 1);
		}
		if (--body_work.wait_timer == 0 && oBS_OBJECT_WORK.pos.y <= FX_F32_TO_FX32(235f))
		{
			body_work.flag[0] |= 268435456u;
			body_work.wait_timer = 120u;
		}
		if (oBS_OBJECT_WORK.pos.y >= body_work.atk_nml_alt)
		{
			GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
			oBS_OBJECT_WORK.pos.y = body_work.atk_nml_alt;
			GmBsCmnSetObjSpd(oBS_OBJECT_WORK, 0, 0, 0);
			body_work.wait_timer = 30u;
			body_work.proc_update = gmBoss4BodyStateUpdateStartWithFallWait;
			GmBoss4UtilLookAtPlayer(body_work.dir, oBS_OBJECT_WORK, 28);
		}
	}

	private static void gmBoss4BodyStateUpdateStartWithFallWait(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
		GmBoss4UtilLookAt(body_work.dir);
		if (--body_work.wait_timer == 0)
		{
			GmBoss4CapsuleSetInvincible(0);
			GmBsCmnSetObjSpdZero(oBS_OBJECT_WORK);
			oBS_OBJECT_WORK.pos.y = body_work.atk_nml_alt;
			GmBsCmnSetObjSpd(oBS_OBJECT_WORK, -4096, 0, 0);
			gmBoss4EffAfterburnerSetEnable(body_work, 1);
			gmBoss4BodyChangeState(body_work, 2);
			GMS_BOSS4_EGG_WORK gMS_BOSS4_EGG_WORK = (GMS_BOSS4_EGG_WORK)body_work.parts_objs[1];
			GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)gMS_BOSS4_EGG_WORK;
			gMS_ENEMY_3D_WORK.ene_com.enemy_flag &= 4294934527u;
		}
	}

