	private static void gmBoss4BodyStateUpdatePreAtkNmlWithMoveLeft(GMS_BOSS4_BODY_WORK body_work)
	{
		VecFx32 value = new VecFx32(FX_F32_TO_FX32(0f), FX_F32_TO_FX32(-30f), FX_F32_TO_FX32(0f));
		VecFx32 value2 = new VecFx32(FX_F32_TO_FX32(180f), FX_F32_TO_FX32(0f), FX_F32_TO_FX32(0f));
		if ((body_work.flag[0] & 0x800) != 0)
		{
			gmBoss4EffAfterburnerSetEnable(body_work, 0);
			if ((body_work.flag[0] & 0x400) == 0)
			{
				GmBoss4EffCommonInit(742, value, (OBS_OBJECT_WORK)body_work, 2u, 2u, body_work.node_work, 2, value2, body_work.flag, 1024u);
			}
			OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_BS_OBJ(body_work);
			oBS_OBJECT_WORK.spd.x = 0;
			oBS_OBJECT_WORK.spd_add.x = 0;
			if (body_work.ene_3d.ene_com.obj_work.pos.y > FX_F32_TO_FX32(240f))
			{
				body_work.avoid_yspd += FX_F32_TO_FX32(0.03f);
			}
			else
			{
				body_work.avoid_yspd -= FX_F32_TO_FX32(0.05f);
				if (body_work.avoid_yspd < FX_F32_TO_FX32(1f))
				{
					body_work.avoid_yspd = FX_F32_TO_FX32(1f);
				}
			}
			body_work.ene_3d.ene_com.obj_work.pos.y -= body_work.avoid_yspd;
			if (body_work.ene_3d.ene_com.obj_work.pos.y < FX_F32_TO_FX32(190f))
			{
