	private static void gmBoss4BodyStateEnter1stEnd(GMS_BOSS4_BODY_WORK body_work)
	{
		GmBoss4UtilInitNoHitTimer(body_work.nohit_work, (GMS_ENEMY_COM_WORK)body_work, 1200);
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)body_work;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag |= 2048u;
		GmBoss4CapsuleSetInvincible(600, false);
		GmBoss4ChibiSetInvincible(true);
		GmBoss4ChibiExplosion();
		GmBoss4UtilPlayerStop(true);
		GmBoss4UtilTimerStop(true);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)body_work;
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
		GmBoss4UtilInitMove(end: new VecFx32(FX_F32_TO_FX32(oBS_CAMERA.target_pos.x), FX_F32_TO_FX32(220f), 0), _work: body_work.move_work, start: oBS_OBJECT_WORK.pos, count: 180, type: 1);
		bool is_positive = GmBoss4UtilIsDirectionPositiveFromCurrent(body_work.dir, GMD_BOSS4_LEFTWARD_ANGLE);
		body_work.dir.direction = 1;
		GmBoss4UtilInitTurnGently(body_work.dir, GMD_BOSS4_LEFTWARD_ANGLE, 40, is_positive);
		body_work.proc_update = gmBoss4BodyStateUpdate1stEnd;
	}

	private static void gmBoss4BodyStateUpdate1stEnd(GMS_BOSS4_BODY_WORK body_work)
	{
		GmBoss4UtilPlayerStop(true);
		GmBoss4ChibiExplosion();
		OBS_OBJECT_WORK obj_work = (OBS_OBJECT_WORK)body_work;
		GmBoss4UtilUpdateTurnGently(body_work.dir);
		if (body_work.move_work.now_count == 30)
		{
			VecFx32 value = new VecFx32(FX_F32_TO_FX32(0f), FX_F32_TO_FX32(-30f), FX_F32_TO_FX32(0f));
			GmBoss4EffCommonInit(rot: new VecFx32(FX_F32_TO_FX32(180f), FX_F32_TO_FX32(0f), FX_F32_TO_FX32(0f)), id: 742, pos: value, parent_obj: (OBS_OBJECT_WORK)body_work, type: 2u, flag: 2u, mtx: body_work.node_work, link: 2, ctrl_flag: body_work.flag, mask: 1024u);
		}
		if (GmBoss4UtilUpdateMove(body_work.move_work))
		{
			if (GmBoss4CapsuleGetCount() > 0)
			{
				body_work.proc_update = gmBoss4BodyStateInit1stEndExplosion;
			}
			else
			{
				body_work.proc_update = gmBoss4BodyStateInit1stEndAngry;
			}
		}
		GmBoss4UtilUpdateMovePosition(body_work.move_work, obj_work);
	}

	private static void gmBoss4BodyStateInit1stEndExplosion(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)body_work;
		GmBoss4UtilPlayerStop(true);
		GmBoss4CapsuleExplosion();
		body_work.wait_timer = 180u;
		body_work.flag[0] |= 16777216u;
		GmBoss4UtilInitMove(end: new VecFx32(oBS_OBJECT_WORK.pos.x, oBS_OBJECT_WORK.pos.y + FX_F32_TO_FX32(20f), 0), _work: body_work.move_work, start: oBS_OBJECT_WORK.pos, count: 60, type: 1);
