	private static void gmBoss4BodyStateEnter2nd(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)body_work;
		GmBoss4UtilInitNoHitTimer(body_work.nohit_work, (GMS_ENEMY_COM_WORK)body_work, 0);
		GmBoss4CapsuleSetInvincible(0);
		GmBoss4ChibiSetInvincible(false);
		GmBoss4UtilPlayerStop(false);
		GmBoss4UtilTimerStop(false);
		if (!GmBoss4CheckBossRush())
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GmGmkCamScrLimitRelease(4);
			oBS_OBJECT_WORK2.user_work = 16u;
		}
		oBS_OBJECT_WORK.pos.x = FX_F32_TO_FX32(GMD_BOSS4_BODY_2ND_POS_X);
		oBS_OBJECT_WORK.pos.y = FX_F32_TO_FX32(GMD_BOSS4_BODY_2ND_POS_Y);
		oBS_OBJECT_WORK.pos.z = -131072;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)body_work;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag |= 2048u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[1].flag &= 4294967291u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[1].flag |= 2048u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag &= 4294965247u;
		ObjRectWorkSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[0], -38, -24, 38, 32);
		GMS_BOSS4_EGG_WORK gMS_BOSS4_EGG_WORK = (GMS_BOSS4_EGG_WORK)body_work.parts_objs[1];
		gmBoss4SetPartTextureBurnt((OBS_OBJECT_WORK)gMS_BOSS4_EGG_WORK, false);
		GmBoss4UtilInitTurnGently(body_work.dir, GMD_BOSS4_LEFTWARD_ANGLE, 1, false);
		GmBoss4UtilUpdateTurnGently(body_work.dir);
		gmBoss4BodySetActionWhole(body_work, 5);
		body_work.proc_update = gmBoss4BodyStateInit2nd;
		GmBoss4CapsuleExplosion();
		bool is_positive = GmBoss4UtilIsDirectionPositiveFromCurrent(body_work.dir, GMD_BOSS4_LEFTWARD_ANGLE);
		body_work.dir.direction = 1;
		GmBoss4UtilInitTurnGently(body_work.dir, GMD_BOSS4_LEFTWARD_ANGLE, 1, is_positive);
		GmBoss4UtilUpdateTurnGently(body_work.dir);
		gm_boss4_locking = 0;
	}

	private static void gmBoss4BodyStateInit2nd(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)body_work;
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GmBsCmnGetPlayerObj();
		int num = FX_F32_TO_FX32(GMD_BOSS4_SCROLL_INIT_X);
		if (oBS_OBJECT_WORK2.pos.x >= num)
		{
			body_work.proc_update = gmBoss4BodyStateUpdate2ndWaitBoss;
			GmBoss4ScrollInit(null, 0, 0, 0);
			body_work.wait_timer = GMD_BOSS4_BODY_SONIC_CTRL_TIME;
			if (GmBoss4CheckBossRush())
			{
				gmBoss4BodySetActionWhole(body_work, 5);
				gmBoss4EffAfterburnerSetEnable(body_work, 0);
				gmBoss4EffAfterburnerSetEnable(body_work, 2);
			}
			else
			{
				GmSoundChangeAngryBossBGM();
			}
			GmMapSetMapDrawSize(7);
		}
		oBS_OBJECT_WORK.pos.y = FX_F32_TO_FX32(GMD_BOSS4_BODY_2ND_POS_Y);
	}

	private static void gmBoss4BodyStateUpdate2ndWaitBoss(GMS_BOSS4_BODY_WORK body_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)GmBsCmnGetPlayerObj();
		if ((gMS_PLAYER_WORK.obj_work.move_flag & 1) != 0)
		{
			GmBoss4UtilPlayerStop(true);
		}
		float num = g_gm_main_system.map_fcol.right;
		if (((OBS_OBJECT_WORK)body_work).pos.x >= FX_F32_TO_FX32(num - 10f))
		{
			if (body_work.wait_timer != 0)
			{
				body_work.wait_timer--;
				return;
			}
			body_work.proc_update = gmBoss4BodyStateUpdate2nd;
			GmBoss4ScrollInit(null, 0, 0, 0);
			body_work.wait_timer = GMD_BOSS4_BODY_CREATE_CAP_FIRST_TIME;
			GmBoss4UtilPlayerStop(false);
		}
	}

	private static void gmBoss4BodyStateUpdate2nd(GMS_BOSS4_BODY_WORK body_work)
	{
		if (body_work.wait_timer != 0)
		{
			body_work.wait_timer--;
			return;
		}
		body_work.proc_update = gmBoss4BodyStateInit2ndAttack;
		body_work.wait_timer = 34u;
		body_work.flag[0] |= 2097152u;
		GMS_BOSS4_EGG_WORK gMS_BOSS4_EGG_WORK = (GMS_BOSS4_EGG_WORK)body_work.parts_objs[1];
		GmBoss4UtilGetNodeMatrix(gMS_BOSS4_EGG_WORK.node_work, 9);
		GmBoss4UtilGetNodeMatrix(gMS_BOSS4_EGG_WORK.node_work, 6);
	}

	private static void gmBoss4BodyStateInit2ndAttack(GMS_BOSS4_BODY_WORK body_work)
	{
		if (body_work.wait_timer != 0)
		{
			body_work.wait_timer--;
			return;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)body_work;
		GMS_BOSS4_EGG_WORK gMS_BOSS4_EGG_WORK = (GMS_BOSS4_EGG_WORK)body_work.parts_objs[1];
		NNS_MATRIX nNS_MATRIX = GmBoss4UtilGetNodeMatrix(gMS_BOSS4_EGG_WORK.node_work, 9);
		NNS_MATRIX nNS_MATRIX2 = GmBoss4UtilGetNodeMatrix(body_work.node_work, 2);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		nNS_VECTOR.x = nNS_MATRIX.M03 - nNS_MATRIX2.M03 + (float)oBS_OBJECT_WORK.pos.x / 4096f;
		nNS_VECTOR.y = nNS_MATRIX.M13;
		nNS_VECTOR.z = nNS_MATRIX.M23;
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = GmEventMgrLocalEventBirth(324, FX_F32_TO_FX32(nNS_VECTOR.x + 0f), -FX_F32_TO_FX32(nNS_VECTOR.y + -22f), 0, 0, 0, 0, 0, 0);
		oBS_OBJECT_WORK2.parent_obj = oBS_OBJECT_WORK;
		GmBoss4IncObjCreateCount();
		if (gmBoss4ChibiGetThrowType() != 0)
		{
			oBS_OBJECT_WORK2.spd.x = FX_F32_TO_FX32(GMD_BOSS4_BODY_CREATE_CAP_THROW_SPD_X_1);
			oBS_OBJECT_WORK2.spd.y = FX_F32_TO_FX32(GMD_BOSS4_BODY_CREATE_CAP_THROW_SPD_Y_1);
		}
		else
		{
			oBS_OBJECT_WORK2.spd.x = FX_F32_TO_FX32(GMD_BOSS4_BODY_CREATE_CAP_THROW_SPD_X_2);
			oBS_OBJECT_WORK2.spd.y = FX_F32_TO_FX32(GMD_BOSS4_BODY_CREATE_CAP_THROW_SPD_Y_2);
		}
		oBS_OBJECT_WORK2.pos.z = 0;
		if (GmBoss4GetLife() < GME_BOSS4_LIFE_H && GmBoss4GetLife() > GME_BOSS4_LIFE_L)
		{
			body_work.proc_update = gmBoss4BodyStateUpdate2ndAttackWait;
			body_work.wait_timer = GMD_BOSS4_BODY_CREATE_CAP_TIMING_LIFE_2_2;
		}
		else
		{
			body_work.proc_update = gmBoss4BodyStateUpdate2ndAttack;
		}
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	private static void gmBoss4BodyStateUpdate2ndAttackWait(GMS_BOSS4_BODY_WORK body_work)
	{
		if (body_work.wait_timer != 0)
		{
			body_work.wait_timer--;
			return;
		}
		body_work.proc_update = gmBoss4BodyStateInit2ndAttack2;
		body_work.wait_timer = 34u;
		body_work.flag[0] |= 4194304u;
	}

	private static void gmBoss4BodyStateInit2ndAttack2(GMS_BOSS4_BODY_WORK body_work)
	{
		if (body_work.wait_timer != 0)
		{
			body_work.wait_timer--;
			return;
		}
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)body_work;
		OBS_OBJECT_WORK oBS_OBJECT_WORK2 = null;
		GMS_BOSS4_EGG_WORK gMS_BOSS4_EGG_WORK = (GMS_BOSS4_EGG_WORK)body_work.parts_objs[1];
		NNS_MATRIX nNS_MATRIX = GmBoss4UtilGetNodeMatrix(gMS_BOSS4_EGG_WORK.node_work, 6);
		NNS_MATRIX nNS_MATRIX2 = GmBoss4UtilGetNodeMatrix(body_work.node_work, 2);
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		nNS_VECTOR.x = nNS_MATRIX.M03 - nNS_MATRIX2.M03 + (float)oBS_OBJECT_WORK.pos.x / 4096f;
		nNS_VECTOR.y = nNS_MATRIX.M13;
		nNS_VECTOR.z = nNS_MATRIX.M23;
		oBS_OBJECT_WORK2 = GmEventMgrLocalEventBirth(324, FX_F32_TO_FX32(nNS_VECTOR.x + 0f), -FX_F32_TO_FX32(nNS_VECTOR.y + -22f), 0, 0, 0, 0, 0, 0);
		oBS_OBJECT_WORK2.parent_obj = oBS_OBJECT_WORK;
		GmBoss4IncObjCreateCount();
		if (gmBoss4ChibiGetThrowType() != 0)
		{
			oBS_OBJECT_WORK2.spd.x = FX_F32_TO_FX32(GMD_BOSS4_BODY_CREATE_CAP_THROW_SPD_X_1);
			oBS_OBJECT_WORK2.spd.y = FX_F32_TO_FX32(GMD_BOSS4_BODY_CREATE_CAP_THROW_SPD_Y_1);
		}
		else
		{
			oBS_OBJECT_WORK2.spd.x = FX_F32_TO_FX32(GMD_BOSS4_BODY_CREATE_CAP_THROW_SPD_X_2);
			oBS_OBJECT_WORK2.spd.y = FX_F32_TO_FX32(GMD_BOSS4_BODY_CREATE_CAP_THROW_SPD_Y_2);
		}
		body_work.proc_update = gmBoss4BodyStateUpdate2ndAttack;
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
	}

	private static void gmBoss4BodyStateUpdate2ndAttack(GMS_BOSS4_BODY_WORK body_work)
	{
		body_work.wait_timer = GMD_BOSS4_BODY_CREATE_CAP_TIMING_LIFE_3;
		if (GmBoss4GetLife() == 1)
		{
			body_work.wait_timer = GMD_BOSS4_BODY_CREATE_CAP_TIMING_LIFE_1;
		}
		if (GmBoss4GetLife() == 2)
		{
			body_work.wait_timer = GMD_BOSS4_BODY_CREATE_CAP_TIMING_LIFE_2;
		}
		body_work.proc_update = gmBoss4BodyStateUpdate2nd;
	}

