	{
		UNREFERENCED_PARAMETER(body_work);
	}

	private static void gmBoss4BodyStateUpdateEscapeWithTurn(GMS_BOSS4_BODY_WORK body_work)
	{
		if (GmBoss4UtilUpdateTurnGently(body_work.dir))
		{
			gmBoss4BodyInitEscapeMove(body_work);
			body_work.proc_update = gmBoss4BodyStateUpdateEscapeWithMoveLocked;
		}
	}

	private static void gmBoss4BodyStateUpdateEscapeWithMoveLocked(GMS_BOSS4_BODY_WORK body_work)
	{
		gmBoss4BodyUpdateEscapeMove(body_work);
		body_work.proc_update = gmBoss4BodyStateUpdateEscapeWithMoveUnlocked;
	}

	private static void gmBoss4BodyStateUpdateEscapeWithMoveUnlocked(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)body_work;
		float num = g_gm_main_system.map_fcol.right;
		gmBoss4BodyUpdateEscapeMove(body_work);
		if (oBS_OBJECT_WORK.pos.x > FX_F32_TO_FX32(num - 100f))
		{
			GMS_EFFECT_3DES_WORK efct_work = GmEfctBossCmnEsCreate(oBS_OBJECT_WORK, 4u);
			GmBoss4EffChangeType(efct_work, 2u, 3u);
			body_work.proc_update = gmBoss4BodyStateUpdateEscapeWithMoveFinish;
			GmMapSetMapDrawSize(1);
		}
	}

	private static void gmBoss4BodyStateUpdateEscapeWithMoveFinish(GMS_BOSS4_BODY_WORK body_work)
	{
		if (gmBoss4BodyUpdateEscapeMove(body_work))
		{
			GMM_BOSS4_MGR(body_work).flag |= 2u;
			body_work.proc_update = null;
			GmBoss4ScrollNext();
		}
	}

	private static void gmBoss4EffAfterburnerSetEnable(GMS_BOSS4_BODY_WORK body_work, int type)
	{
		switch (type)
		{
		default:
			body_work.flag[0] &= 4294967279u;
			body_work.flag[0] &= 4261412863u;
			body_work.flag[0] &= 4294967039u;
			body_work.flag[0] &= 4293918719u;
			break;
		case 1:
			MTM_ASSERT(0 == (body_work.flag[0] & 0x10));
			MTM_ASSERT(0 == (body_work.flag[0] & 0x2000000));
			body_work.flag[0] &= 4294967039u;
			body_work.flag[0] &= 4293918719u;
			body_work.flag[0] |= 33554432u;
			break;
		case 2:
			MTM_ASSERT(0 == (body_work.flag[0] & 0x100));
			MTM_ASSERT(0 == (body_work.flag[0] & 0x100000));
			body_work.flag[0] &= 4294967279u;
			body_work.flag[0] &= 4261412863u;
			body_work.flag[0] |= 1048576u;
			body_work.flag[0] &= 4294966271u;
			break;
		}
	}

	private static void gmBoss4EffAfterburnerUpdateCreate(GMS_BOSS4_BODY_WORK body_work)
	{
		if ((body_work.flag[0] & 0x100000) != 0)
		{
			body_work.flag[0] &= 4261412863u;
			body_work.flag[0] &= 4293918719u;
			body_work.flag[0] |= 256u;
			gmBoss4EffAfterburnerExInit(body_work);
		}
		if ((body_work.flag[0] & 0x2000000) != 0)
		{
			body_work.flag[0] &= 4261412863u;
			body_work.flag[0] &= 4293918719u;
			body_work.flag[0] |= 16u;
			gmBoss4EffAfterburnerInit(body_work);
		}
	}

	private static void gmBoss4EffAfterburnerInit(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK parent_obj = GMM_BS_OBJ(body_work);
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctBossCmnEsCreate(parent_obj, 4u);
		GmEffect3DESAddDispOffset(gMS_EFFECT_3DES_WORK, 0f, -15f, -45f);
		GMM_BS_OBJ(gMS_EFFECT_3DES_WORK).ppFunc = gmBoss4EffAfterburnerProcMain;
		gMS_EFFECT_3DES_WORK = GmEfctBossCmnEsCreate(parent_obj, 4u);
		GmEffect3DESAddDispOffset(gMS_EFFECT_3DES_WORK, 0f, 5f, -45f);
		GMM_BS_OBJ(gMS_EFFECT_3DES_WORK).ppFunc = gmBoss4EffAfterburnerProcMain;
	}

	private static void gmBoss4EffAfterburnerProcMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)obj_work.parent_obj;
		MTM_ASSERT(gMS_BOSS4_BODY_WORK.node_work.snm_work.reg_node_max);
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.flag |= 4u;
		}
		if ((gMS_BOSS4_BODY_WORK.flag[0] & 0x10) == 0)
		{
			ObjDrawKillAction3DES(obj_work);
		}
		GmBsCmnUpdateObject3DESStuckWithNode(obj_work, gMS_BOSS4_BODY_WORK.node_work.snm_work, gMS_BOSS4_BODY_WORK.node_work.work[2], 1);
	}

	private static void gmBoss4EffAfterburnerExInit(GMS_BOSS4_BODY_WORK body_work)
	{
		OBS_OBJECT_WORK parent_obj = GMM_BS_OBJ(body_work);
		GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmBoss4EffCommonInit(741, null, parent_obj);
		GMM_BS_OBJ(gMS_EFFECT_3DES_WORK).ppFunc = null;
		GmEffect3DESSetupBase(gMS_EFFECT_3DES_WORK, 2u, 2u);
		GmEffect3DESSetDispRotation(gMS_EFFECT_3DES_WORK, (short)GMD_BOSS4_EFF_ABURNER3_DISP_ROT_X, 0, 0);
		GmEffect3DESAddDispOffset(gMS_EFFECT_3DES_WORK, -0f, -0f, 0f);
		GMM_BS_OBJ(gMS_EFFECT_3DES_WORK).ppFunc = gmBoss4EffAfterburnerExProcMainL;
		gMS_EFFECT_3DES_WORK = GmBoss4EffCommonInit(741, null, parent_obj);
		GMM_BS_OBJ(gMS_EFFECT_3DES_WORK).ppFunc = null;
		GmEffect3DESSetupBase(gMS_EFFECT_3DES_WORK, 2u, 2u);
		GmEffect3DESSetDispRotation(gMS_EFFECT_3DES_WORK, (short)GMD_BOSS4_EFF_ABURNER3_DISP_ROT_X, 0, 0);
		GmEffect3DESAddDispOffset(gMS_EFFECT_3DES_WORK, 0f, -0f, 0f);
		GMM_BS_OBJ(gMS_EFFECT_3DES_WORK).ppFunc = gmBoss4EffAfterburnerExProcMainR;
	}

	private static void gmBoss4EffAfterburnerExProcMainL(OBS_OBJECT_WORK obj_work)
	{
		GMS_BOSS4_BODY_WORK gMS_BOSS4_BODY_WORK = (GMS_BOSS4_BODY_WORK)obj_work.parent_obj;
		MTM_ASSERT(gMS_BOSS4_BODY_WORK.node_work.snm_work.reg_node_max);
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.flag |= 4u;
		}
		if ((gMS_BOSS4_BODY_WORK.flag[0] & 0x100) == 0)
		{
			ObjDrawKillAction3DES(obj_work);
		}
		NNS_MATRIX nNS_MATRIX = GmBoss4UtilGetNodeMatrix(gMS_BOSS4_BODY_WORK.node_work, 5);
		NNS_MATRIX nNS_MATRIX2 = GmBoss4UtilGetNodeMatrix(gMS_BOSS4_BODY_WORK.node_work, 2);
