	protected static void GetMBResult(IAsyncResult r)
	{
		try
		{
			int? num = Guide.EndShowMessageBox(r);
			int? num2 = num;
			if (num2.GetValueOrDefault() == 0 && num2.HasValue)
			{
				g_ao_sys_global.is_playing_device_bgm_music = false;
				try
				{
					MediaPlayer.Stop();
					return;
				}
				catch (Exception)
				{
					return;
				}
			}
		}
		finally
		{
			g_ao_sys_global.is_show_ui = false;
		}
	}

	private static void AoSysInit()
	{
		g_ao_sys_global.is_show_ui = false;
		g_ao_sys_global.is_signin_changed = false;
		if (!MediaPlayer.GameHasControl || MediaPlayer.State == MediaState.Playing)
		{
			g_ao_sys_global.is_playing_device_bgm_music = true;
			List<string> list = new List<string>();
			list.Add(Strings.ID_YES);
			list.Add(Strings.ID_NO);
			string iD_MUSIC_INTERRUPT_CAPTON = Strings.ID_MUSIC_INTERRUPT_CAPTON;
			string iD_MUSIC_INTERRUPT_TEXT = Strings.ID_MUSIC_INTERRUPT_TEXT;
			g_ao_sys_global.is_show_ui = true;
			Guide.BeginShowMessageBox(iD_MUSIC_INTERRUPT_CAPTON, iD_MUSIC_INTERRUPT_TEXT, list, 0, MessageBoxIcon.Warning, GetMBResult, null);
		}
		else
		{
			g_ao_sys_global.is_playing_device_bgm_music = false;
		}
		aoSysInit();
	}

