			if (act_buf_num == 0)
			{
				act_buf_num = 1u;
			}
			if (sort_buf_num == 0)
			{
				sort_buf_num = 1u;
			}
			if (acm_stack_num == 0)
			{
				acm_stack_num = 1u;
			}
			g_ao_act_spr_buf_size = spr_buf_num;
			if (spr_buf_num != 0)
			{
				g_ao_act_spr_buf = New<AOS_SPRITE>((int)spr_buf_num);
				g_ao_act_spr_ref = new AOS_SPRITE[spr_buf_num];
			}
			else
			{
				g_ao_act_spr_buf = null;
				g_ao_act_spr_ref = null;
			}
			g_ao_act_buf_size = act_buf_num;
			if (act_buf_num != 0)
			{
				g_ao_act_buf = New<AOS_ACTION>((int)act_buf_num);
				g_ao_act_ref = new AOS_ACTION[act_buf_num];
			}
			else
			{
				g_ao_act_buf = null;
				g_ao_act_ref = null;
			}
			g_ao_act_sort_buf_size = sort_buf_num;
			if (sort_buf_num != 0)
			{
				g_ao_act_sort_buf = New<AOS_ACT_SORT>((int)sort_buf_num);
			}
			else
			{
				g_ao_act_sort_buf = null;
			}
			g_ao_act_acm_buf_size = acm_stack_num;
			if (acm_stack_num != 0)
			{
				g_ao_act_acm_buf = New<AOS_ACT_ACM>((int)acm_stack_num);
			}
			else
			{
