	private static void AoActSysReset()
	{
		g_ao_act_sys_draw_prio = 4096u;
		g_ao_act_sys_frame_rate = 1f;
		g_ao_act_sys_adjust_x = 0f;
		g_ao_act_sys_adjust_y = 0f;
		if (g_ao_act_spr_buf_size != 0)
		{
			for (int i = 0; i < g_ao_act_spr_buf.Length; i++)
			{
				g_ao_act_spr_buf[i].Clear();
			}
			for (uint num = 0u; num < g_ao_act_spr_buf_size; num++)
			{
				g_ao_act_spr_ref[num] = g_ao_act_spr_buf[num];
			}
		}
		g_ao_act_spr_alloc = 0u;
		g_ao_act_spr_free = 0u;
		g_ao_act_spr_num = 0u;
		if (g_ao_act_buf_size != 0)
		{
			for (int j = 0; j < g_ao_act_buf.Length; j++)
			{
				g_ao_act_buf[j].Clear();
			}
			for (uint num2 = 0u; num2 < g_ao_act_buf_size; num2++)
			{
				g_ao_act_ref[num2] = g_ao_act_buf[num2];
			}
		}
		g_ao_act_alloc = 0u;
		g_ao_act_free = 0u;
		g_ao_act_num = 0u;
		if (g_ao_act_sort_buf_size != 0)
		{
			ArrayPointer<AOS_ACT_SORT> arrayPointer = g_ao_act_sort_buf;
			for (int k = 0; k < g_ao_act_sort_buf_size; k++)
			{
				(~arrayPointer).Clear();
				++arrayPointer;
			}
		}
		g_ao_act_sort_num = 0u;
		g_ao_act_acm_cur = g_ao_act_acm_buf;
		g_ao_act_acm_num = 1u;
		if (g_ao_act_acm_buf_size != 0)
		{
			ArrayPointer<AOS_ACT_ACM> arrayPointer2 = g_ao_act_acm_buf;
			for (int l = 0; l < g_ao_act_acm_buf_size; l++)
			{
				(~arrayPointer2).Clear();
				++arrayPointer2;
			}
			AoActAcmInit();
		}
		g_ao_act_acm_flag_cur = g_ao_act_acm_flag_buf;
		g_ao_act_acm_flag_num = 1u;
		if (g_ao_act_acm_flag_buf_size != 0)
		{
			ArrayPointer<uint> arrayPointer3 = g_ao_act_acm_flag_buf;
			for (int m = 0; m < g_ao_act_acm_flag_buf_size; m++)
			{
				arrayPointer3.SetPrimitive(0u);
				++arrayPointer3;
			}
			AoActAcmSetFlag();
		}
		AoActSysClearPeak();
		g_ao_act_texlist = null;
	}

