	public static AOS_SPRITE AoActSprCreate(A2S_AMA_HEADER ama, uint id, float frame)
	{
		AOS_SPRITE aOS_SPRITE = aoActAllocSprite();
		if (aOS_SPRITE == null)
		{
			return null;
		}
		AoActSprApply(aOS_SPRITE, ama, id, frame);
		return aOS_SPRITE;
	}

	public static void AoActSprDelete(AOS_SPRITE spr)
	{
		aoActFreeSprite(spr);
	}

	public static void AoActSprApply(AOS_SPRITE spr, A2S_AMA_HEADER ama, uint id, float frame)
	{
		A2S_AMA_ACT a2S_AMA_ACT = ama.act_tbl[id];
		while (a2S_AMA_ACT.next != null && !((float)a2S_AMA_ACT.frm_num > frame))
		{
			frame -= (float)a2S_AMA_ACT.frm_num;
			a2S_AMA_ACT = a2S_AMA_ACT.next;
		}
		float frame2 = frame;
		int key = -1;
		aoActSearchTrsKey(a2S_AMA_ACT, ref frame2, ref key);
		float frame3 = frame;
		int key2 = -1;
		aoActSearchMtnKey(a2S_AMA_ACT, ref frame3, ref key2);
		float frame4 = frame;
		int key3 = -1;
		aoActSearchAnmKey(a2S_AMA_ACT, ref frame4, ref key3);
		float frame5 = frame;
		int key4 = -1;
		aoActSearchMatKey(a2S_AMA_ACT, ref frame5, ref key4);
		float frame6 = frame;
		int key5 = -1;
		aoActSearchHitKey(a2S_AMA_ACT, ref frame6, ref key5);
		spr.flag = a2S_AMA_ACT.flag;
		spr.offset.left = a2S_AMA_ACT.ofst.left;
		spr.offset.right = a2S_AMA_ACT.ofst.right;
		spr.offset.top = a2S_AMA_ACT.ofst.top;
		spr.offset.bottom = a2S_AMA_ACT.ofst.bottom;
		float scale_x = 0f;
		float scale_y = 0f;
		if (a2S_AMA_ACT.mtn == null)
		{
			spr.center_x = 0f;
			spr.center_y = 0f;
			spr.prio = 0f;
			spr.rotate = 0f;
		}
		else
		{
			aoActMakeTrs(a2S_AMA_ACT.mtn.trs_key_num, a2S_AMA_ACT.mtn.trs_frm_num, a2S_AMA_ACT.mtn.trs_key_tbl, a2S_AMA_ACT.mtn.trs_tbl, key, frame2, ref spr.center_x, ref spr.center_y, ref spr.prio);
			aoActMakeMtn(a2S_AMA_ACT.mtn.mtn_key_num, a2S_AMA_ACT.mtn.mtn_frm_num, a2S_AMA_ACT.mtn.mtn_key_tbl, a2S_AMA_ACT.mtn.mtn_tbl, key2, frame3, out scale_x, out scale_y, out spr.rotate);
			spr.offset.left *= scale_x;
			spr.offset.right *= scale_x;
			spr.offset.top *= scale_y;
			spr.offset.bottom *= scale_y;
		}
		if (a2S_AMA_ACT.anm == null)
		{
			spr.tex_id = -1;
			spr.color.r = byte.MaxValue;
			spr.color.g = byte.MaxValue;
			spr.color.b = byte.MaxValue;
			spr.color.a = byte.MaxValue;
			spr.fade.r = 0;
			spr.fade.g = 0;
			spr.fade.b = 0;
			spr.fade.a = 0;
		}
		else
		{
			aoActMakeAnm(a2S_AMA_ACT.anm.anm_key_num, a2S_AMA_ACT.anm.anm_frm_num, a2S_AMA_ACT.anm.anm_key_tbl, a2S_AMA_ACT.anm.anm_tbl, key3, frame4, ref spr.tex_id, ref spr.uv, ref spr.clamp);
			aoActMakeMat(a2S_AMA_ACT.anm.mat_key_num, a2S_AMA_ACT.anm.mat_frm_num, a2S_AMA_ACT.anm.mat_key_tbl, a2S_AMA_ACT.anm.mat_tbl, key4, frame5, ref spr.color, ref spr.fade, out spr.blend);
		}
		if (a2S_AMA_ACT.hit == null)
		{
			spr.hit.type = AOE_ACT_HIT.AOD_ACT_HIT_NONE;
		}
		else
		{
			aoActMakeHit(a2S_AMA_ACT.hit.hit_key_num, a2S_AMA_ACT.hit.hit_frm_num, a2S_AMA_ACT.hit.hit_key_tbl, a2S_AMA_ACT.hit.hit_tbl, key5, frame6, spr.hit);
			spr.hit.scale_x = scale_x;
			spr.hit.scale_y = scale_y;
		}
		aoActAcmSprite(spr);
	}

