	public static AOS_ACTION AoActCreate(A2S_AMA_HEADER ama, uint id)
	{
		return AoActCreate(ama, id, 0f);
	}

	public static AOS_ACTION AoActCreate(A2S_AMA_HEADER ama, uint id, float frame)
	{
		if (id >= ama.act_num)
		{
			return null;
		}
		A2S_AMA_ACT data = ama.act_tbl[id];
		AOS_ACTION aOS_ACTION = aoActAllocAction();
		if (aOS_ACTION == null)
		{
			return null;
		}
		AoActAcmPush();
		AoActAcmFlagPush(0u, uint.MaxValue);
		aOS_ACTION.data = data;
		aOS_ACTION.flag = 0u;
		aOS_ACTION.state = 0u;
		aOS_ACTION.type = AOE_ACT_TYPE.AOD_ACT_TYPE_ACTION;
		aOS_ACTION.frame = frame;
		aOS_ACTION.last_key.trs = -1;
		aOS_ACTION.last_key.mtn = -1;
		aOS_ACTION.last_key.anm = -1;
		aOS_ACTION.last_key.mat = -1;
		aOS_ACTION.last_key.atrs = -1;
		aOS_ACTION.last_key.amtn = -1;
		aOS_ACTION.last_key.amat = -1;
		aOS_ACTION.last_key.usr = -1;
		aOS_ACTION.last_key.hit = -1;
		aOS_ACTION.child = null;
		aOS_ACTION.sibling = null;
		aOS_ACTION.sprite = AoActSprCreate(ama, id, frame);
		if (aOS_ACTION.sprite == null)
		{
			AoActDelete(aOS_ACTION);
			aOS_ACTION = null;
			AoActAcmFlagPop();
			AoActAcmPop();
			return null;
		}
		AoActAcmFlagPop();
		AoActAcmPop();
		return aOS_ACTION;
	}

	public static AOS_ACTION AoActCreateNode(A2S_AMA_HEADER ama, uint id, float frame)
	{
		return AoActCreateNodeSub(ama, id, frame, false);
	}

	public static AOS_ACTION AoActCreateNodeSub(A2S_AMA_HEADER ama, uint id, float frame, bool sib)
	{
		if (id >= ama.node_num)
		{
			return null;
		}
		A2S_AMA_NODE a2S_AMA_NODE = ama.node_tbl[id];
		AOS_ACTION aOS_ACTION = aoActAllocAction();
		if (aOS_ACTION == null)
		{
			return null;
		}
		AoActAcmPush();
		AoActAcmFlagPush(0u, uint.MaxValue);
		aOS_ACTION.data = a2S_AMA_NODE;
		aOS_ACTION.flag = 0u;
		aOS_ACTION.state = 0u;
		aOS_ACTION.type = AOE_ACT_TYPE.AOD_ACT_TYPE_NODE;
		aOS_ACTION.frame = frame;
		aOS_ACTION.last_key.trs = -1;
		aOS_ACTION.last_key.mtn = -1;
		aOS_ACTION.last_key.anm = -1;
		aOS_ACTION.last_key.mat = -1;
		aOS_ACTION.last_key.atrs = -1;
		aOS_ACTION.last_key.amtn = -1;
		aOS_ACTION.last_key.amat = -1;
		aOS_ACTION.last_key.usr = -1;
		aOS_ACTION.last_key.hit = -1;
		aOS_ACTION.child = null;
		aOS_ACTION.sibling = null;
		if (a2S_AMA_NODE.act_offset != 0)
		{
			aOS_ACTION.sprite = AoActSprCreate(ama, a2S_AMA_NODE.act.id, frame);
			if (aOS_ACTION.sprite == null)
			{
				AoActDelete(aOS_ACTION);
				aOS_ACTION = null;
				AoActAcmFlagPop();
				AoActAcmPop();
				return null;
			}
		}
		else
		{
			aOS_ACTION.sprite = null;
		}
		if (a2S_AMA_NODE.child_offset != 0)
		{
			aOS_ACTION.child = AoActCreateNodeSub(ama, a2S_AMA_NODE.child.id, frame, true);
			if (aOS_ACTION.child == null)
			{
				AoActAcmFlagPop();
				AoActAcmPop();
				return aOS_ACTION;
			}
		}
		AoActAcmFlagPop();
		AoActAcmPop();
		if (sib && a2S_AMA_NODE.sibling_offset != 0)
		{
			aOS_ACTION.sibling = AoActCreateNodeSub(ama, a2S_AMA_NODE.sibling.id, frame, true);
			if (aOS_ACTION.sibling == null)
			{
				return aOS_ACTION;
			}
		}
		return aOS_ACTION;
	}

	public static void AoActDelete(AOS_ACTION act)
	{
		if (act.sibling != null)
		{
			AoActDelete(act.sibling);
			act.sibling = null;
		}
		if (act.child != null)
		{
			AoActDelete(act.child);
			act.child = null;
		}
		if (act.sprite != null)
		{
			AoActSprDelete(act.sprite);
			act.sprite = null;
		}
		aoActFreeAction(act);
	}

	public static void AoActSetFrame(AOS_ACTION act, float frame)
	{
		do
		{
			act.frame = frame;
			act.flag |= 1u;
			if (act.child != null)
			{
				AoActSetFrame(act.child, frame);
			}
			act = act.sibling;
		}
		while (act != null);
	}

	public static void AoActUpdate(AOS_ACTION act)
	{
		AoActUpdate(act, 1f);
	}

	public static void AoActUpdate(AOS_ACTION act, float frame)
	{
		act.frame += g_ao_act_sys_frame_rate * frame;
		if (act.frame < 0f)
		{
			act.frame = 0f;
		}
		act.flag |= 1u;
		if (act.child != null)
		{
			AoActSetFrame(act.child, act.frame);
		}
		aoActApply(act);
		act.state = aoActGetAmaActState(aoActGetAmaAct(act), act.frame);
	}

	private static void AoActDraw(AOS_ACTION act)
	{
		AoActDraw(act, false);
	}

	private static void AoActDraw(AOS_ACTION act, bool sort)
	{
		if (g_ao_act_sort_num < g_ao_act_sort_buf_size)
		{
			ArrayPointer<AOS_ACT_SORT> arrayPointer = g_ao_act_sort_buf;
			uint num = g_ao_act_sort_buf_size;
			uint num2 = g_ao_act_sort_num;
			uint num3 = g_ao_act_sort_peak;
			g_ao_act_sort_buf += (int)g_ao_act_sort_num;
			g_ao_act_sort_buf_size -= g_ao_act_sort_num;
			g_ao_act_sort_num = 0u;
			g_ao_act_sort_peak = 0u;
			AoActSortRegAction(act);
			uint num4 = g_ao_act_sort_num;
			if (sort)
			{
				AoActSortExecute();
			}
			AoActSortDraw();
			AoActSortUnregAll();
			g_ao_act_sort_buf = arrayPointer;
			g_ao_act_sort_buf_size = num;
			g_ao_act_sort_num = num2;
			g_ao_act_sort_peak = num3;
			if (g_ao_act_sort_num + num4 > g_ao_act_sort_peak)
			{
				g_ao_act_sort_peak = g_ao_act_sort_num + num4;
			}
		}
	}

