	public static uint AoActGetHitNum(AOS_ACTION act)
	{
		uint num = 0u;
		if ((uint)AoActUtilGetSprFromAct(act).hit.type < 2u)
		{
			num++;
		}
		if (act.child != null)
		{
			num += AoActGetHitNum(act.child);
		}
		if (act.sibling != null)
		{
			num += AoActGetHitNum(act.sibling);
		}
		return num;
	}

	public static uint AoActGetHitTbl(ArrayPointer<AOS_ACT_HIT> hit_tbl, AOS_ACTION act)
	{
		return AoActGetHitTbl(hit_tbl, uint.MaxValue, act);
	}

	public static uint AoActGetHitTbl(ArrayPointer<AOS_ACT_HIT> hit_tbl, uint size, AOS_ACTION act)
	{
		uint num = 0u;
		if ((uint)AoActUtilGetSprFromAct(act).hit.type < 2u)
		{
			if (size < 1)
			{
				return num;
			}
			AoActGetHitSpr(hit_tbl[(int)num], AoActUtilGetSprFromAct(act));
			num++;
			size--;
		}
		if (act.child != null)
		{
			uint num2 = AoActGetHitTbl(hit_tbl + (int)num, size, act.child);
			num += num2;
			if (size <= num2)
			{
				return num;
			}
			size -= num2;
		}
		if (act.sibling != null)
		{
			uint num3 = AoActGetHitTbl(hit_tbl + (int)num, size, act.sibling);
			num += num3;
			if (size <= num3)
			{
				return num;
			}
			size -= num3;
		}
		return num;
	}

