		return AoActGetHitAct(new AOS_ACT_HIT[1] { hit }, aOS_ACTION);
	}

	public static bool AoActHitTest(AOS_ACT_HIT hit, float x, float y)
	{
		if ((uint)hit.type >= 2u)
		{
			return false;
		}
		x -= hit.center_x;
		y -= hit.center_y;
		float pSn = 0f;
		float pCs = 0f;
		float num = 0f;
		float num2 = 0f;
		amSinCos(NNM_DEGtoA32(0f - hit.rotate), out pSn, out pCs);
		num = x * pCs - y * pSn;
		num2 = x * pSn + y * pCs;
		x = num / hit.scale_x;
		y = num2 / hit.scale_y;
		switch (hit.type)
		{
		case AOE_ACT_HIT.AOD_ACT_HIT_RECT:
			if (x >= hit.rect.left && x <= hit.rect.right && y >= hit.rect.top && y <= hit.rect.bottom)
			{
				return true;
			}
			break;
		case AOE_ACT_HIT.AOD_ACT_HIT_CIRCLE:
			num = x - hit.circle.center_x;
			num2 = y - hit.circle.center_y;
			if (num * num + num2 * num2 <= hit.circle.radius * hit.circle.radius)
			{
				return true;
			}
			break;
		}
		return false;
	}

	public static bool AoActHitTestCorReverse(AOS_ACT_HIT hit, float x, float y)
	{
		AoActCorReverse(ref x, ref y);
		return AoActHitTest(hit, x, y);
	}

