		uint num = 1u;
		num += AoActUtilGetActNum(act.child);
		return num + AoActUtilGetActNum(act.sibling);
	}

	public static AOS_ACTION AoActUtilGetActFromId(AOS_ACTION act, uint id)
	{
		AOS_ACTION aOS_ACTION = null;
		A2S_AMA_ACT a2S_AMA_ACT = aoActGetAmaAct(act);
		if (a2S_AMA_ACT.id == id)
		{
			aOS_ACTION = act;
		}
		else
		{
			if (act.child != null)
			{
				aOS_ACTION = AoActUtilGetActFromId(act.child, id);
			}
			if (aOS_ACTION == null && act.sibling != null)
			{
				aOS_ACTION = AoActUtilGetActFromId(act.sibling, id);
			}
		}
		return aOS_ACTION;
	}

