	public static void AoActDrawCorWide(ArrayPointer<NNS_PRIM3D_PN> v, uint v_num, AOE_ACT_CORW type)
	{
		switch (type)
		{
		case AOE_ACT_CORW.AOD_ACT_CORW_NONE:
		{
			for (int j = 0; j < v_num; j++)
			{
				v[j].Pos.x *= 1.125f;
			}
			break;
		}
		case AOE_ACT_CORW.AOD_ACT_CORW_CENTER:
		{
			for (int l = 0; l < v_num; l++)
			{
				v[l].Pos.x += 60f;
			}
			break;
		}
		case AOE_ACT_CORW.AOD_ACT_CORW_RIGHT:
		{
			float num2 = 120f;
			for (int m = 0; m < v_num; m++)
			{
				v[m].Pos.x += num2;
			}
			break;
		}
		case AOE_ACT_CORW.AOD_ACT_CORW_LEFT_S:
		{
			for (int k = 0; k < v_num; k++)
			{
				v[k].Pos.x += g_ao_act_wide_shift;
			}
			break;
		}
		case AOE_ACT_CORW.AOD_ACT_CORW_RIGHT_S:
		{
			float num = 120f;
			num -= (float)g_ao_act_wide_shift;
			for (int i = 0; i < v_num; i++)
			{
				v[i].Pos.x += num;
			}
			break;
		}
		case AOE_ACT_CORW.AOD_ACT_CORW_LEFT:
			break;
		}
	}

