	public static bool AoActIsAma(byte[] file, int offset)
	{
		if (file[offset + 1] == AmaMagicId[1] && file[offset + 2] == AmaMagicId[2])
		{
			return file[offset + 3] == AmaMagicId[3];
		}
		return false;
	}

	// Ortho 2D: el eje de 1080 es el ancho de la pantalla. Se amplía de forma simétrica
	// para que el 2D no se estire en ultrawide: píxeles cuadrados y fondos que se extienden a los lados.
	// Con RENDER_W = 480 la ampliación es 0 y queda igual que antes.
	// true mientras se ENCOLAN las piezas del HUD (al crear el comando).
	public static bool amHudEnqueue;
	// true mientras se encolan piezas del menú de pausa (capa sin zoom, sin el ajuste del editor de HUD).
	public static bool amUiEnqueue;
	// true mientras se EJECUTA un comando de HUD: la proyección usa el tamaño y la posición del editor.
	private static bool hudProjActive;

	private static void AmMakeOrtho2D(NNS_MATRIX mtx)
	{
		float d = 1.125f * (Sonic4Ep1.RENDER_W - Sonic4Ep1.GAME_W);
		if (d < 0f)
		{
			d = 0f;
		}
		if (hudProjActive && Sonic4Ep1.pInstance != null)
		{
			// Ventana centrada: s = escala del usuario, z = zoom del escenario (lo compensa el HUD),
			// o = desplazamiento en unidades. Resultado en pantalla: s*(p-c)+o, sin cambiar el zoom del escenario.
			float s = Sonic4Ep1.pInstance.HudUserScale;
			float z = Sonic4Ep1.pInstance.HudZoomNow;
			float hx = (540f + d) * z / s;
			float hy = 360f * z / s;
			float cx = 540f - Sonic4Ep1.pInstance.HudOffsetUnitsX / s;
			float cy = 360f - Sonic4Ep1.pInstance.HudOffsetUnitsY / s;
			nnMakeOrthoMatrix(mtx, cy - hy, cy + hy, cx + hx, cx - hx, 1f, 3f);
			return;
		}
		nnMakeOrthoMatrix(mtx, 0f, 720f, 1080f + d, 0f - d, 1f, 3f);
	}

	public static void AoActDrawPre()
	{
		NNS_MATRIX aoActDrawPre_mtx = AoActDrawPre_mtx;
		aoActDrawPre_mtx.Clear();
		hudProjActive = false;
		AmMakeOrtho2D(aoActDrawPre_mtx);
		amDrawSetProjection(aoActDrawPre_mtx, 1);
		nnMakeUnitMatrix(aoActDrawPre_mtx);
		nnRotateZMatrix(aoActDrawPre_mtx, aoActDrawPre_mtx, NNM_DEGtoA32(90f));
		nnTranslateMatrix(aoActDrawPre_mtx, aoActDrawPre_mtx, 0f, -720f, 0f);
		amDrawSetWorldViewMatrix(aoActDrawPre_mtx);
		nnSetPrimitive3DMatrix(aoActDrawPre_mtx);
	}

	public static void aoActAcmSprite(AOS_SPRITE spr)
	{
		AOS_ACT_ACM aOS_ACT_ACM = ~g_ao_act_acm_cur;
		uint num = ~g_ao_act_acm_flag_cur;
		if ((num & 0x20) == 0)
		{
			spr.offset.left *= aOS_ACT_ACM.scale_x;
			spr.offset.right *= aOS_ACT_ACM.scale_x;
			spr.offset.top *= aOS_ACT_ACM.scale_y;
			spr.offset.bottom *= aOS_ACT_ACM.scale_y;
			if ((spr.hit.flag & 1) == 0)
			{
				spr.hit.scale_x *= aOS_ACT_ACM.scale_x;
				spr.hit.scale_y *= aOS_ACT_ACM.scale_y;
			}
			if (aOS_ACT_ACM.rotate != 0f)
			{
				float pSn;
				float pCs;
				amSinCos(NNM_DEGtoA32(aOS_ACT_ACM.rotate), out pSn, out pCs);
				float center_x = spr.center_x * pCs - spr.center_y * pSn;
				float center_y = spr.center_x * pSn + spr.center_y * pCs;
				spr.center_x = center_x;
				spr.center_y = center_y;
				spr.rotate += aOS_ACT_ACM.rotate;
			}
			spr.center_x *= aOS_ACT_ACM.trans_scale_x;
			spr.center_y *= aOS_ACT_ACM.trans_scale_y;
		}
		if ((num & 8) == 0)
		{
			spr.center_x += aOS_ACT_ACM.trans_x;
			spr.center_y += aOS_ACT_ACM.trans_y;
			spr.prio += aOS_ACT_ACM.trans_z;
		}
		if ((num & 0x10) == 0)
		{
			spr.color.r = (byte)((uint)(spr.color.r * aOS_ACT_ACM.color.r) >> 8);
			spr.color.g = (byte)((uint)(spr.color.g * aOS_ACT_ACM.color.g) >> 8);
			spr.color.b = (byte)((uint)(spr.color.b * aOS_ACT_ACM.color.b) >> 8);
			spr.color.a = (byte)((uint)(spr.color.a * aOS_ACT_ACM.color.a) >> 8);
			uint num2 = (uint)(spr.fade.r + aOS_ACT_ACM.fade.r);
			if (num2 > 255)
			{
				spr.fade.r = byte.MaxValue;
			}
			else
			{
				spr.fade.r = (byte)num2;
			}
			num2 = (uint)(spr.fade.g + aOS_ACT_ACM.fade.g);
			if (num2 > 255)
			{
				spr.fade.g = byte.MaxValue;
			}
			else
			{
				spr.fade.g = (byte)num2;
			}
			num2 = (uint)(spr.fade.b + aOS_ACT_ACM.fade.b);
			if (num2 > 255)
			{
				spr.fade.b = byte.MaxValue;
			}
			else
			{
				spr.fade.b = (byte)num2;
			}
			num2 = (uint)(spr.fade.a + aOS_ACT_ACM.fade.a);
			if (num2 > 255)
			{
				spr.fade.a = byte.MaxValue;
			}
			else
			{
				spr.fade.a = (byte)num2;
			}
		}
	}

	public static void aoActApply(AOS_ACTION act)
	{
		A2S_AMA_ACT a2S_AMA_ACT = aoActGetAmaAct(act);
		AoActAcmPush();
		if (a2S_AMA_ACT != null && (act.flag & 1) != 0)
		{
			float num = act.frame;
			while (a2S_AMA_ACT.next != null && !((float)a2S_AMA_ACT.frm_num > num))
			{
				num -= (float)a2S_AMA_ACT.frm_num;
				a2S_AMA_ACT = a2S_AMA_ACT.next;
			}
			float frame = num;
			aoActSearchTrsKey(a2S_AMA_ACT, ref frame, ref act.last_key.trs);
			float frame2 = num;
			aoActSearchMtnKey(a2S_AMA_ACT, ref frame2, ref act.last_key.mtn);
			float frame3 = num;
			aoActSearchAnmKey(a2S_AMA_ACT, ref frame3, ref act.last_key.anm);
			float frame4 = num;
			aoActSearchMatKey(a2S_AMA_ACT, ref frame4, ref act.last_key.mat);
			float frame5 = num;
			aoActSearchHitKey(a2S_AMA_ACT, ref frame5, ref act.last_key.hit);
			AOS_SPRITE sprite = act.sprite;
			sprite.flag = a2S_AMA_ACT.flag;
			sprite.offset.left = a2S_AMA_ACT.ofst.left;
			sprite.offset.right = a2S_AMA_ACT.ofst.right;
			sprite.offset.top = a2S_AMA_ACT.ofst.top;
			sprite.offset.bottom = a2S_AMA_ACT.ofst.bottom;
			float scale_x;
			float scale_y;
			if (a2S_AMA_ACT.mtn == null)
			{
				sprite.center_x = 0f;
				sprite.center_y = 0f;
				sprite.prio = 0f;
				scale_x = 1f;
				scale_y = 1f;
				sprite.rotate = 0f;
			}
			else
			{
				aoActMakeTrs(a2S_AMA_ACT.mtn.trs_key_num, a2S_AMA_ACT.mtn.trs_frm_num, a2S_AMA_ACT.mtn.trs_key_tbl, a2S_AMA_ACT.mtn.trs_tbl, act.last_key.trs, frame, ref sprite.center_x, ref sprite.center_y, ref sprite.prio);
				aoActMakeMtn(a2S_AMA_ACT.mtn.mtn_key_num, a2S_AMA_ACT.mtn.mtn_frm_num, a2S_AMA_ACT.mtn.mtn_key_tbl, a2S_AMA_ACT.mtn.mtn_tbl, act.last_key.mtn, frame2, out scale_x, out scale_y, out sprite.rotate);
				sprite.offset.left *= scale_x;
				sprite.offset.right *= scale_x;
				sprite.offset.top *= scale_y;
				sprite.offset.bottom *= scale_y;
			}
			if (a2S_AMA_ACT.anm == null)
			{
				sprite.tex_id = -1;
				sprite.color.r = byte.MaxValue;
				sprite.color.g = byte.MaxValue;
				sprite.color.b = byte.MaxValue;
				sprite.color.a = byte.MaxValue;
				sprite.fade.r = 0;
				sprite.fade.g = 0;
				sprite.fade.b = 0;
				sprite.fade.a = 0;
			}
			else
			{
				aoActMakeAnm(a2S_AMA_ACT.anm.anm_key_num, a2S_AMA_ACT.anm.anm_frm_num, a2S_AMA_ACT.anm.anm_key_tbl, a2S_AMA_ACT.anm.anm_tbl, act.last_key.anm, frame3, ref sprite.tex_id, ref sprite.uv, ref sprite.clamp);
				aoActMakeMat(a2S_AMA_ACT.anm.mat_key_num, a2S_AMA_ACT.anm.mat_frm_num, a2S_AMA_ACT.anm.mat_key_tbl, a2S_AMA_ACT.anm.mat_tbl, act.last_key.mat, frame4, ref sprite.color, ref sprite.fade, out sprite.blend);
			}
			if (a2S_AMA_ACT.hit == null)
			{
				sprite.hit.type = AOE_ACT_HIT.AOD_ACT_HIT_NONE;
			}
			else
			{
				aoActMakeHit(a2S_AMA_ACT.hit.hit_key_num, a2S_AMA_ACT.hit.hit_frm_num, a2S_AMA_ACT.hit.hit_key_tbl, a2S_AMA_ACT.hit.hit_tbl, act.last_key.hit, frame5, sprite.hit);
				sprite.hit.scale_x = scale_x;
				sprite.hit.scale_y = scale_y;
			}
			sprite.texlist = g_ao_act_texlist;
			aoActAcmSprite(sprite);
			if (a2S_AMA_ACT.acm != null)
			{
				float frame6 = num;
				aoActSearchAcmTrsKey(a2S_AMA_ACT, ref frame6, ref act.last_key.atrs);
				float frame7 = num;
				aoActSearchAcmMtnKey(a2S_AMA_ACT, ref frame7, ref act.last_key.amtn);
				float frame8 = num;
				aoActSearchAcmMatKey(a2S_AMA_ACT, ref frame8, ref act.last_key.amat);
				AOS_ACT_ACM aOS_ACT_ACM = new AOS_ACT_ACM();
				if ((a2S_AMA_ACT.acm.flag & 0x10) != 0)
				{
					aOS_ACT_ACM.trans_x = sprite.center_x;
					aOS_ACT_ACM.trans_y = sprite.center_y;
					aOS_ACT_ACM.trans_z = sprite.prio;
				}
				else
				{
					aoActMakeTrs(a2S_AMA_ACT.acm.trs_key_num, a2S_AMA_ACT.acm.trs_frm_num, a2S_AMA_ACT.acm.trs_key_tbl, a2S_AMA_ACT.acm.trs_tbl, act.last_key.atrs, frame6, ref aOS_ACT_ACM.trans_x, ref aOS_ACT_ACM.trans_y, ref aOS_ACT_ACM.trans_z);
				}
				if ((a2S_AMA_ACT.acm.flag & 8) != 0)
				{
					aOS_ACT_ACM.trans_scale_x = 1f;
					aOS_ACT_ACM.trans_scale_y = 1f;
					aOS_ACT_ACM.scale_x = scale_x;
					aOS_ACT_ACM.scale_y = scale_y;
					aOS_ACT_ACM.rotate = sprite.rotate;
				}
				else
				{
					aoActMakeAcm(a2S_AMA_ACT.acm.acm_key_num, a2S_AMA_ACT.acm.acm_frm_num, a2S_AMA_ACT.acm.acm_key_tbl, a2S_AMA_ACT.acm.acm_tbl, act.last_key.amtn, frame7, ref aOS_ACT_ACM.trans_scale_x, ref aOS_ACT_ACM.trans_scale_y, ref aOS_ACT_ACM.scale_x, ref aOS_ACT_ACM.scale_y, ref aOS_ACT_ACM.rotate);
				}
				if ((a2S_AMA_ACT.acm.flag & 0x20) != 0)
				{
					aOS_ACT_ACM.color = sprite.color;
					aOS_ACT_ACM.fade = sprite.fade;
				}
				else
				{
					uint blend;
					aoActMakeMat(a2S_AMA_ACT.acm.mat_key_num, a2S_AMA_ACT.acm.mat_frm_num, a2S_AMA_ACT.acm.mat_key_tbl, a2S_AMA_ACT.acm.mat_tbl, act.last_key.amat, frame8, ref aOS_ACT_ACM.color, ref aOS_ACT_ACM.fade, out blend);
				}
				AoActAcmApply(aOS_ACT_ACM);
			}
		}
		act.flag &= 4294967294u;
		if (act.child != null)
		{
			aoActApply(act.child);
		}
		AoActAcmPop();
		if (act.sibling != null)
		{
			aoActApply(act.sibling);
		}
	}

	public static void aoActSearchTrsKey(A2S_AMA_ACT act, ref float frame, ref int key)
	{
		if (act == null || act.mtn == null || act.mtn.trs_key_tbl == null || act.mtn.trs_frm_num == 0)
		{
			frame = 0f;
			key = -1;
			return;
		}
		A2S_AMA_MTN mtn = act.mtn;
		if ((mtn.flag & 2) != 0)
		{
			frame = aoActGetLoopFrame(frame, mtn.trs_frm_num);
		}
		else if (frame >= (float)mtn.trs_frm_num)
		{
			frame = mtn.trs_frm_num;
		}
		aoActSerachKey(mtn.trs_key_tbl, mtn.trs_key_num, ref frame, ref key);
	}

