	public static void aoActMakeTrs(uint key_num, uint frm_num, A2S_SUB_KEY[] key_tbl, A2S_SUB_TRS[] trs_tbl, int key, float frame, ref float trans_x, ref float trans_y, ref float trans_z)
	{
		if (key < 0 || key_num == 0)
		{
			trans_x = 0f;
			trans_y = 0f;
			trans_z = 0f;
			return;
		}
		uint key2 = 0u;
		float rate;
		if (!aoActGetInterpolInfo(key_tbl, key_num, frm_num, frame, (uint)key, ref key2, out rate))
		{
			A2S_SUB_TRS a2S_SUB_TRS = trs_tbl[key];
			trans_x = a2S_SUB_TRS.trs_x;
			trans_y = a2S_SUB_TRS.trs_y;
			trans_z = a2S_SUB_TRS.trs_z;
			return;
		}
		A2S_SUB_TRS a2S_SUB_TRS2 = trs_tbl[key];
		A2S_SUB_TRS a2S_SUB_TRS3 = trs_tbl[key2];
		rate = aoActGetAcceleRate(rate, a2S_SUB_TRS2.trs_accele);
		if (key_tbl[key].interpol == 2 && key_num >= 4)
		{
			int num = key - 1;
			if (num < 0)
			{
				num = (int)(key_num - 1);
			}
			int num2 = (int)(key2 + 1);
			if (num2 >= (int)key_num)
			{
				num2 = 0;
			}
			A2S_SUB_TRS t = trs_tbl[num];
			A2S_SUB_TRS t2 = trs_tbl[num2];
			aoActGetInterpolSpline(t, a2S_SUB_TRS2, a2S_SUB_TRS3, t2, rate, ref trans_x, ref trans_y, ref trans_z);
		}
		else
		{
			trans_x = aoActInterpolF32(a2S_SUB_TRS2.trs_x, a2S_SUB_TRS3.trs_x, rate);
			trans_y = aoActInterpolF32(a2S_SUB_TRS2.trs_y, a2S_SUB_TRS3.trs_y, rate);
			trans_z = aoActInterpolF32(a2S_SUB_TRS2.trs_z, a2S_SUB_TRS3.trs_z, rate);
		}
	}

	public static void aoActMakeMtn(uint key_num, uint frm_num, A2S_SUB_KEY[] key_tbl, A2S_SUB_MTN[] mtn_tbl, int key, float frame, out float scale_x, out float scale_y, out float rotate)
