			scale_x = aoActInterpolF32(a2S_SUB_MTN2.scl_x, a2S_SUB_MTN3.scl_x, rate2);
			scale_y = aoActInterpolF32(a2S_SUB_MTN2.scl_y, a2S_SUB_MTN3.scl_y, rate2);
