	public static void aoActMakeAnm(uint key_num, uint frm_num, A2S_SUB_KEY[] key_tbl, A2S_SUB_ANM[] anm_tbl, int key, float frame, ref int tex_id, ref AOS_ACT_RECT rect, ref uint clamp)
