			rect.top = aoActInterpolF32(a2S_SUB_ANM2.texel.top, a2S_SUB_ANM3.texel.top, rate);
			rect.right = aoActInterpolF32(a2S_SUB_ANM2.texel.right, a2S_SUB_ANM3.texel.right, rate);
			rect.bottom = aoActInterpolF32(a2S_SUB_ANM2.texel.bottom, a2S_SUB_ANM3.texel.bottom, rate);
			clamp = a2S_SUB_ANM2.clamp;
		}
	}

	public static void aoActMakeMat(uint key_num, uint frm_num, A2S_SUB_KEY[] key_tbl, A2S_SUB_MAT[] mat_tbl, int key, float frame, ref AOS_ACT_COL color, ref AOS_ACT_COL fade, out uint blend)
	{
		if (key < 0 || key_num == 0)
		{
			color.r = byte.MaxValue;
			color.g = byte.MaxValue;
			color.b = byte.MaxValue;
			color.a = byte.MaxValue;
			fade.r = 0;
			fade.g = 0;
			fade.b = 0;
			fade.a = 0;
			blend = 1u;
			return;
		}
		uint key2 = 0u;
		float rate;
		if (!aoActGetInterpolInfo(key_tbl, key_num, frm_num, frame, (uint)key, ref key2, out rate))
		{
			A2S_SUB_MAT a2S_SUB_MAT = mat_tbl[key];
			color.r = a2S_SUB_MAT.base_.r;
			color.g = a2S_SUB_MAT.base_.g;
			color.b = a2S_SUB_MAT.base_.b;
			color.a = a2S_SUB_MAT.base_.a;
			fade.r = a2S_SUB_MAT.fade.r;
			fade.g = a2S_SUB_MAT.fade.g;
			fade.b = a2S_SUB_MAT.fade.b;
			fade.a = a2S_SUB_MAT.fade.a;
			blend = a2S_SUB_MAT.blend;
		}
		else
		{
			A2S_SUB_MAT a2S_SUB_MAT2 = mat_tbl[key];
			A2S_SUB_MAT a2S_SUB_MAT3 = mat_tbl[key2];
			float rate2 = aoActGetAcceleRate(rate, a2S_SUB_MAT2.base_accele);
			float rate3 = aoActGetAcceleRate(rate, a2S_SUB_MAT2.fade_accele);
			color = aoActInterpolCol(a2S_SUB_MAT2.base_, a2S_SUB_MAT3.base_, rate2);
			fade = aoActInterpolCol(a2S_SUB_MAT2.fade, a2S_SUB_MAT3.fade, rate3);
			blend = a2S_SUB_MAT2.blend;
		}
	}

	public static void aoActMakeAcm(uint key_num, uint frm_num, A2S_SUB_KEY[] key_tbl, A2S_SUB_ACM[] acm_tbl, int key, float frame, ref float tscale_x, ref float tscale_y, ref float scale_x, ref float scale_y, ref float rotate)
	{
		if (key < 0 || key_num == 0)
		{
			tscale_x = 1f;
			tscale_y = 1f;
			scale_x = 1f;
			scale_y = 1f;
			rotate = 0f;
			return;
		}
		uint key2 = 0u;
		float rate;
		if (!aoActGetInterpolInfo(key_tbl, key_num, frm_num, frame, (uint)key, ref key2, out rate))
		{
			A2S_SUB_ACM a2S_SUB_ACM = acm_tbl[key];
			tscale_x = a2S_SUB_ACM.trs_scl_x;
			tscale_y = a2S_SUB_ACM.trs_scl_y;
			scale_x = a2S_SUB_ACM.scl_x;
			scale_y = a2S_SUB_ACM.scl_y;
			rotate = a2S_SUB_ACM.rot;
		}
		else
		{
			A2S_SUB_ACM a2S_SUB_ACM2 = acm_tbl[key];
			A2S_SUB_ACM a2S_SUB_ACM3 = acm_tbl[key2];
			float rate2 = aoActGetAcceleRate(rate, a2S_SUB_ACM2.trs_scl_accele);
			float rate3 = aoActGetAcceleRate(rate, a2S_SUB_ACM2.scl_accele);
			float rate4 = aoActGetAcceleRate(rate, a2S_SUB_ACM2.rot_accele);
			tscale_x = aoActInterpolF32(a2S_SUB_ACM2.trs_scl_x, a2S_SUB_ACM3.trs_scl_x, rate2);
			tscale_y = aoActInterpolF32(a2S_SUB_ACM2.trs_scl_y, a2S_SUB_ACM3.trs_scl_y, rate2);
			scale_x = aoActInterpolF32(a2S_SUB_ACM2.scl_x, a2S_SUB_ACM3.scl_x, rate3);
			scale_y = aoActInterpolF32(a2S_SUB_ACM2.scl_y, a2S_SUB_ACM3.scl_y, rate3);
			rotate = aoActInterpolF32(a2S_SUB_ACM2.rot, a2S_SUB_ACM3.rot, rate4);
		}
	}

	public static void aoActMakeHit(uint key_num, uint frm_num, A2S_SUB_KEY[] key_tbl, A2S_SUB_HIT[] hit_tbl, int key, float frame, AOS_ACT_HITP hit)
	{
		hit.scale_x = 1f;
		hit.scale_y = 1f;
		if (key < 0 || key_num == 0)
		{
			hit.type = AOE_ACT_HIT.AOD_ACT_HIT_NONE;
			return;
		}
		uint key2 = 0u;
		float rate;
		if (!aoActGetInterpolInfo(key_tbl, key_num, frm_num, frame, (uint)key, ref key2, out rate))
		{
			A2S_SUB_HIT a2S_SUB_HIT = hit_tbl[key];
			hit.flag = a2S_SUB_HIT.flag;
			switch (a2S_SUB_HIT.type)
			{
			case 1u:
				hit.type = AOE_ACT_HIT.AOD_ACT_HIT_RECT;
				hit.rect.Assign(ref a2S_SUB_HIT.rect);
				break;
			case 2u:
				hit.type = AOE_ACT_HIT.AOD_ACT_HIT_CIRCLE;
				hit.rect.Assign(ref a2S_SUB_HIT.rect);
				break;
			default:
				hit.type = AOE_ACT_HIT.AOD_ACT_HIT_NONE;
				break;
			}
			return;
		}
		A2S_SUB_HIT a2S_SUB_HIT2 = hit_tbl[key];
		A2S_SUB_HIT a2S_SUB_HIT3 = hit_tbl[key2];
		if (a2S_SUB_HIT2.type != a2S_SUB_HIT3.type)
		{
			hit.flag = a2S_SUB_HIT2.flag;
			switch (a2S_SUB_HIT2.type)
			{
			case 1u:
				hit.type = AOE_ACT_HIT.AOD_ACT_HIT_RECT;
				hit.rect.Assign(ref a2S_SUB_HIT2.rect);
				break;
			case 2u:
				hit.type = AOE_ACT_HIT.AOD_ACT_HIT_CIRCLE;
				hit.SetCircle(ref a2S_SUB_HIT2.circle);
				break;
			default:
				hit.type = AOE_ACT_HIT.AOD_ACT_HIT_NONE;
				break;
			}
			return;
		}
		rate = aoActGetAcceleRate(rate, a2S_SUB_HIT2.hit_accele);
		hit.flag = a2S_SUB_HIT2.flag;
		switch (a2S_SUB_HIT2.type)
		{
		case 1u:
			hit.type = AOE_ACT_HIT.AOD_ACT_HIT_RECT;
			hit.rect = new AOS_ACT_RECT
			{
				left = aoActInterpolF32(a2S_SUB_HIT2.rect.left, a2S_SUB_HIT3.rect.left, rate),
				top = aoActInterpolF32(a2S_SUB_HIT2.rect.top, a2S_SUB_HIT3.rect.top, rate),
				right = aoActInterpolF32(a2S_SUB_HIT2.rect.right, a2S_SUB_HIT3.rect.right, rate),
				bottom = aoActInterpolF32(a2S_SUB_HIT2.rect.bottom, a2S_SUB_HIT3.rect.bottom, rate)
			};
			break;
		case 2u:
		{
			hit.type = AOE_ACT_HIT.AOD_ACT_HIT_CIRCLE;
			AOS_ACT_CIRCLE circle = new AOS_ACT_CIRCLE
			{
				center_x = aoActInterpolF32(a2S_SUB_HIT2.circle.center_x, a2S_SUB_HIT3.circle.center_x, rate),
				center_y = aoActInterpolF32(a2S_SUB_HIT2.circle.center_y, a2S_SUB_HIT3.circle.center_y, rate),
				radius = aoActInterpolF32(a2S_SUB_HIT2.circle.radius, a2S_SUB_HIT3.circle.radius, rate)
			};
			hit.SetCircle(ref circle);
			break;
		}
		default:
			hit.type = AOE_ACT_HIT.AOD_ACT_HIT_NONE;
			break;
		}
	}

	public static void aoActSerachKey(A2S_SUB_KEY[] key, uint key_num, ref float frame, ref int last)
	{
		if (frame < 1f)
		{
			frame = 0f;
			last = 0;
			return;
		}
		uint num = (uint)frame;
		uint num2;
		if (last < 0)
		{
			num2 = key_num / 2;
			for (uint num3 = (key_num + 1) / 2; num3 > 1; num3 = (num3 + 1) / 2)
			{
				num2 = ((key[num2].frm > num) ? (num2 - num3 / 2) : (num2 + num3 / 2));
			}
			if (key[num2].frm > num)
			{
				num2--;
			}
		}
		else
		{
			num2 = (uint)last;
			while (true)
			{
				if (key[num2].frm <= num)
				{
					if (key[num2 + 1].frm > num)
					{
						break;
					}
					num2++;
				}
				else
				{
					num2--;
				}
				if (num2 == 0)
				{
					num2 = 0u;
					break;
				}
				if (num2 >= key_num - 1)
				{
					num2 = key_num - 1;
					break;
				}
			}
		}
		last = (int)num2;
		frame -= key[num2].frm;
	}

	public static float aoActGetLoopFrame(float frame, uint len)
	{
		uint num = (uint)frame % len;
		float num2 = frame - (float)(uint)frame;
		return (float)num + num2;
	}

	public static bool aoActGetInterpolInfo(A2S_SUB_KEY[] key_tbl, uint key_num, uint frm_num, float frame, uint key1, ref uint key2, out float rate)
	{
		A2S_SUB_KEY a2S_SUB_KEY = key_tbl[key1];
		if ((a2S_SUB_KEY.interpol != 1 && a2S_SUB_KEY.interpol != 2) || key_num <= 1)
		{
			rate = 0f;
			return false;
		}
		if (key1 + 1 < key_num)
		{
			key2 = key1 + 1;
			A2S_SUB_KEY a2S_SUB_KEY2 = key_tbl[key1 + 1];
			rate = frame / (float)(a2S_SUB_KEY2.frm - a2S_SUB_KEY.frm);
		}
		else
		{
			key2 = 0u;
			rate = frame / (float)(frm_num - a2S_SUB_KEY.frm);
		}
		return true;
	}

	public static void aoActGetInterpolSpline(A2S_SUB_TRS t0, A2S_SUB_TRS t1, A2S_SUB_TRS t2, A2S_SUB_TRS t3, float rate, ref float trans_x, ref float trans_y, ref float trans_z)
	{
		float num = rate * rate;
		float num2 = num * rate;
		float num3 = -0.5f * (num2 + rate) + num;
		float num4 = 1.5f * num2 - 2.5f * num + 1f;
		float num5 = -1.5f * num2 + 2f * num + 0.5f * rate;
		float num6 = 0.5f * (num2 - num);
		trans_x = t0.trs_x * num3 + t1.trs_x * num4 + t2.trs_x * num5 + t3.trs_x * num6;
		trans_y = t0.trs_y * num3 + t1.trs_y * num4 + t2.trs_y * num5 + t3.trs_y * num6;
		trans_z = t0.trs_z * num3 + t1.trs_z * num4 + t2.trs_z * num5 + t3.trs_z * num6;
	}

	public static float aoActGetAcceleRate(float rate, float accele)
	{
		return rate * accele + rate * rate * (1f - accele);
	}

	public static AOS_SPRITE aoActAllocSprite()
	{
		if (g_ao_act_spr_num >= g_ao_act_spr_buf_size)
		{
			return null;
		}
		AOS_SPRITE result = g_ao_act_spr_ref[g_ao_act_spr_alloc];
		g_ao_act_spr_alloc++;
		if (g_ao_act_spr_alloc >= g_ao_act_spr_buf_size)
		{
			g_ao_act_spr_alloc = 0u;
		}
		g_ao_act_spr_num++;
		if (g_ao_act_spr_num > g_ao_act_spr_peak)
		{
			g_ao_act_spr_peak = g_ao_act_spr_num;
		}
		return result;
	}

