	public static A2S_AMA_ACT aoActGetAmaAct(AOS_ACTION act)
	{
		A2S_AMA_ACT result = null;
		if (act == null)
		{
			return null;
		}
		switch (act.type)
		{
		case AOE_ACT_TYPE.AOD_ACT_TYPE_ACTION:
			result = (A2S_AMA_ACT)act.data;
			break;
		case AOE_ACT_TYPE.AOD_ACT_TYPE_NODE:
			result = ((A2S_AMA_NODE)act.data).act;
			break;
		}
		return result;
	}

	public static float aoActInterpolF32(float d1, float d2, float rate)
	{
		return d1 * (1f - rate) + d2 * rate;
	}

	public static AOS_ACT_COL aoActInterpolCol(A2S_SUB_COL d1, A2S_SUB_COL d2, float rate)
	{
		AOS_ACT_COL result = default(AOS_ACT_COL);
		int num = (int)(255f * rate);
		if (num < 0)
		{
			num = 0;
		}
		else if (num > 255)
		{
			num = 255;
		}
		int num2 = 255 - num;
		result.r = (byte)((d1.r * num2 + d2.r * num) / 255);
		result.g = (byte)((d1.g * num2 + d2.g * num) / 255);
		result.b = (byte)((d1.b * num2 + d2.b * num) / 255);
		result.a = (byte)((d1.a * num2 + d2.a * num) / 255);
		return result;
	}

	public static void aoActDrawTask(AMS_TCB tcb)
	{
		AOS_ACT_DRAW aOS_ACT_DRAW = (AOS_ACT_DRAW)amTaskGetWork(tcb);
		amDrawPushState();
		amDrawInitState();
		AoActDrawPre();
		nnSetPrimitive3DAlphaFuncGL(519u, 0.5f);
		nnSetPrimitive3DDepthMaskGL(false);
		nnSetPrimitive3DDepthFuncGL(519u);
		for (uint num = 0u; num < aOS_ACT_DRAW.count; num++)
		{
			AOS_SPRITE aOS_SPRITE = aOS_ACT_DRAW.sprite[num];
			uint blend = aOS_SPRITE.blend;
			if (blend == 2)
			{
				nnSetPrimitiveBlend(0);
			}
			else
			{
				nnSetPrimitiveBlend(1);
			}
			bool flag;
			if (aOS_SPRITE.fade.a > 0)
			{
				amDrawSetFogColor((float)(int)aOS_SPRITE.fade.r / 255f, (float)(int)aOS_SPRITE.fade.g / 255f, (float)(int)aOS_SPRITE.fade.b / 255f);
				float num2 = 2f - (float)(int)aOS_SPRITE.fade.a / 255f;
				amDrawSetFogRange(num2, num2 + 1f);
				amDrawSetFog(1);
				flag = true;
			}
			else
			{
				amDrawSetFog(0);
				flag = false;
			}
			if (aOS_SPRITE.tex_id >= 0 && aOS_SPRITE.texlist != null)
			{
				nnSetPrimitiveTexNum(aOS_SPRITE.texlist, aOS_SPRITE.tex_id);
				int uwrap = (((aOS_SPRITE.clamp & 2) != 0) ? 1 : 0);
				int vwrap = (((aOS_SPRITE.clamp & 1) != 0) ? 1 : 0);
				nnSetPrimitiveTexState(0, 0, uwrap, vwrap);
				int blend2 = ((aOS_SPRITE.blend != 0) ? 1 : 0);
				nnBeginDrawPrimitive3D(4, blend2, 0, 0);
				NNS_PRIM3D_PCT[] array = aoActDrawTask_pct;
				aoActDrawTask_pct_array.buffer = array;
				aoActDrawTask_pct_array.offset = 0;
				do
				{
					array[0].Tex.u = (array[1].Tex.u = aOS_SPRITE.uv.left);
					array[2].Tex.u = (array[3].Tex.u = aOS_SPRITE.uv.right);
					array[0].Tex.v = (array[2].Tex.v = aOS_SPRITE.uv.top);
					array[1].Tex.v = (array[3].Tex.v = aOS_SPRITE.uv.bottom);
					array[0].Col = (uint)((aOS_SPRITE.color.r << 24) | (aOS_SPRITE.color.g << 16) | (aOS_SPRITE.color.b << 8) | aOS_SPRITE.color.a);
					array[1].Col = (array[2].Col = (array[3].Col = array[0].Col));
					array[0].Pos.x = (array[1].Pos.x = aOS_SPRITE.offset.left);
					array[2].Pos.x = (array[3].Pos.x = aOS_SPRITE.offset.right);
					array[0].Pos.y = (array[2].Pos.y = aOS_SPRITE.offset.top);
					array[1].Pos.y = (array[3].Pos.y = aOS_SPRITE.offset.bottom);
					array[0].Pos.z = (array[1].Pos.z = (array[2].Pos.z = (array[3].Pos.z = -2f)));
					if (aOS_SPRITE.rotate != 0f)
					{
						float pSn;
						float pCs;
						amSinCos(NNM_RADtoA32(aOS_SPRITE.rotate), out pSn, out pCs);
						for (int i = 0; i < 4; i++)
						{
							float x = array[i].Pos.x * pCs - array[i].Pos.y * pSn;
							float y = array[i].Pos.x * pSn + array[i].Pos.y * pCs;
							array[i].Pos.x = x;
							array[i].Pos.y = y;
						}
					}
					array[0].Pos.x += aOS_SPRITE.center_x;
					array[1].Pos.x += aOS_SPRITE.center_x;
					array[2].Pos.x += aOS_SPRITE.center_x;
					array[3].Pos.x += aOS_SPRITE.center_x;
					array[0].Pos.y += aOS_SPRITE.center_y;
					array[1].Pos.y += aOS_SPRITE.center_y;
					array[2].Pos.y += aOS_SPRITE.center_y;
					array[3].Pos.y += aOS_SPRITE.center_y;
					if (SyGetEvtInfo().cur_evt_id >= 3)
					{
						float num3 = array[1].Pos.y - array[0].Pos.y;
						array[0].Pos.y *= 0.9f;
						array[0].Pos.y += 32f;
						array[2].Pos.y *= 0.9f;
						array[2].Pos.y += 32f;
						array[1].Pos.y = array[0].Pos.y + num3;
						array[3].Pos.y = array[2].Pos.y + num3;
					}
