	public static MTS_TASK_TCB MTM_TASK_MAKE_TCB(GSF_TASK_PROCEDURE proc, GSF_TASK_PROCEDURE dest, uint flag, ushort pause_level, uint prio, int group, TaskWorkFactoryDelegate work_size, string name)
	{
		return mtTaskMake(proc, dest, flag, pause_level, prio, group, work_size, name);
	}

	private static void mtTaskInitSystem()
	{
		if (gs_task_mt_system_tcb == null)
		{
			gs_task_mt_system_tcb = mtTaskMake(mtTaskSystemMain, mtTaskSystemDest, 2147483648u, ushort.MaxValue, 0u, 15, null, "GS_TASKMT_SYS");
			gs_task_mtsys = default(GSS_TASK_SYS);
			gs_task_mtsys.pause_level = -1;
			gs_task_mtsys.pause_level_set = -1;
		}
	}

	private static void mtTaskExitSystem()
	{
		mtTaskClearTcb(gs_task_mt_system_tcb);
	}

	public static MTS_TASK_TCB mtTaskMake(GSF_TASK_PROCEDURE proc, GSF_TASK_PROCEDURE dest, uint flag, ushort pause_level, uint prio, int group, TaskWorkFactoryDelegate work_size, string name)
	{
		if ((flag & 0x80000000u) == 0 && (uint)group >= 15u)
		{
			group = 14;
		}
		AMS_TCB aMS_TCB = amTaskMake(_mtTaskProcedure, _mtTaskDestructor, prio, (uint)(1 << group), 2u, name);
		aMS_TCB.work = new MTS_TASK_TCB();
		MTS_TASK_TCB mTS_TASK_TCB = (MTS_TASK_TCB)amTaskGetWork(aMS_TCB);
		mTS_TASK_TCB.am_tcb = aMS_TCB;
		mTS_TASK_TCB.proc = proc;
		mTS_TASK_TCB.dest = dest;
		mTS_TASK_TCB.pause_level = pause_level;
		if ((flag & 1) != 0)
		{
			mTS_TASK_TCB.pause_level = ushort.MaxValue;
		}
		mTS_TASK_TCB.work = null;
		if (work_size != null)
		{
			mTS_TASK_TCB.work = work_size();
		}
		amTaskStart(aMS_TCB);
		return mTS_TASK_TCB;
	}

	private static AMS_TCB mtTaskGetAmTcb(MTS_TASK_TCB tcb)
	{
		return tcb.am_tcb;
	}

	private static OBS_OBJECT_WORK mtTaskGetTcbWork(MTS_TASK_TCB tcb)
	{
		if (tcb.work is IOBS_OBJECT_WORK)
		{
			return ((IOBS_OBJECT_WORK)tcb.work).Cast();
		}
		return (OBS_OBJECT_WORK)tcb.work;
	}

	private static void mtTaskChangeTcbProcedure(MTS_TASK_TCB tcb, GSF_TASK_PROCEDURE proc)
	{
		tcb.proc = proc;
	}

	private static void mtTaskChangeTcbDestructor(MTS_TASK_TCB tcb, GSF_TASK_PROCEDURE dest)
	{
		tcb.dest = dest;
	}

	private static void mtTaskClearTcb(MTS_TASK_TCB tcb)
	{
		amTaskDelete(tcb.am_tcb);
	}

	private static void mtTaskClearTcbAll()
	{
		amTaskDeleteGroup(uint.MaxValue, 2u, 1u);
	}

	private static void mtTaskClearPriority(uint prio_begin, uint prio_end)
	{
		amTaskDeletePriority(prio_begin, prio_end, uint.MaxValue);
	}

	private static void mtTaskClearGroup(int group)
	{
		amTaskDeleteGroup((uint)(1 << group), 2u, 1u);
