	private static void mtTaskStartPause(ushort pause_level)
	{
		if (pause_level >= ushort.MaxValue)
		{
			pause_level = 65534;
		}
		gs_task_mtsys.pause_level_set = pause_level;
	}

	private static void mtTaskEndPause()
	{
		gs_task_mtsys.pause_level_set = -1;
	}

	private static bool mtTaskIsPaused(ref ushort pause_level)
	{
		if (pause_level != 0)
		{
			if (gs_task_mtsys.pause_level_set >= 0)
			{
				pause_level = (ushort)gs_task_mtsys.pause_level_set;
			}
			else
			{
				pause_level = 0;
			}
		}
		if (gs_task_mtsys.pause_level_set < 0)
		{
			return false;
		}
		return true;
	}

	private static void mtTaskSystemMain(MTS_TASK_TCB tcb)
	{
		gs_task_mtsys.pause_level = gs_task_mtsys.pause_level_set;
	}

	private static void mtTaskSystemDest(MTS_TASK_TCB tcb)
	{
		gs_task_mt_system_tcb = null;
		gs_task_mtsys = default(GSS_TASK_SYS);
	}

	public static void mtTaskProcedure(AMS_TCB am_tcb)
	{
		MTS_TASK_TCB mTS_TASK_TCB = (MTS_TASK_TCB)amTaskGetWork(am_tcb);
		if (mTS_TASK_TCB.pause_level > gs_task_mtsys.pause_level && mTS_TASK_TCB.proc != null)
		{
			mTS_TASK_TCB.proc(mTS_TASK_TCB);
		}
	}

	public static void mtTaskDestructor(AMS_TCB am_tcb)
	{
		MTS_TASK_TCB mTS_TASK_TCB = (MTS_TASK_TCB)amTaskGetWork(am_tcb);
		if (mTS_TASK_TCB.dest != null)
		{
			mTS_TASK_TCB.dest(mTS_TASK_TCB);
		}
		if (mTS_TASK_TCB.work != null && mTS_TASK_TCB.work is GMS_EFFECT_3DES_WORK)
		{
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = (GMS_EFFECT_3DES_WORK)mTS_TASK_TCB.work;
			gMS_EFFECT_3DES_WORK.Clear();
			GMS_EFFECT_3DES_WORK_Pool.Release(gMS_EFFECT_3DES_WORK);
		}
		mTS_TASK_TCB.work = null;
	}

