	public static bool nnInvertMatrix(NNS_MATRIX dst, NNS_MATRIX src)
	{
		float m = src.M00;
		float m2 = src.M01;
		float m3 = src.M02;
		float m4 = src.M03;
		float m5 = src.M10;
		float m6 = src.M11;
		float m7 = src.M12;
		float m8 = src.M13;
		float m9 = src.M20;
		float m10 = src.M21;
		float m11 = src.M22;
		float m12 = src.M23;
		float num = m6 * m11 - m7 * m10;
		float num2 = m7 * m9 - m5 * m11;
		float num3 = m5 * m10 - m6 * m9;
		float num4 = m * num + m2 * num2 + m3 * num3;
		if (num4 == 0f)
		{
			dst.Clear();
			return false;
		}
		float num5 = 1f / num4;
		dst.M00 = num * num5;
		dst.M01 = (0f - (m2 * m11 - m10 * m3)) * num5;
		dst.M02 = (m2 * m7 - m6 * m3) * num5;
		dst.M10 = num2 * num5;
		dst.M11 = (m * m11 - m9 * m3) * num5;
		dst.M12 = (0f - (m * m7 - m5 * m3)) * num5;
		dst.M20 = num3 * num5;
		dst.M21 = (0f - (m * m10 - m9 * m2)) * num5;
		dst.M22 = (m * m6 - m5 * m2) * num5;
		dst.M03 = (0f - dst.M00) * m4 - dst.M01 * m8 - dst.M02 * m12;
		dst.M13 = (0f - dst.M10) * m4 - dst.M11 * m8 - dst.M12 * m12;
		dst.M23 = (0f - dst.M20) * m4 - dst.M21 * m8 - dst.M22 * m12;
		dst.M30 = 0f;
		dst.M31 = 0f;
		dst.M32 = 0f;
		dst.M33 = 1f;
		return true;
	}

	public static void nnInvertOrthoMatrix(NNS_MATRIX dst, NNS_MATRIX src)
	{
		float m = src.M00;
		float m2 = src.M01;
		float m3 = src.M02;
		float m4 = src.M03;
		float m5 = src.M10;
		float m6 = src.M11;
		float m7 = src.M12;
		float m8 = src.M13;
		float m9 = src.M20;
		float m10 = src.M21;
		float m11 = src.M22;
		float m12 = src.M23;
		dst.M01 = m5;
		dst.M02 = m9;
		dst.M10 = m2;
		dst.M12 = m10;
		dst.M20 = m3;
		dst.M21 = m7;
		dst.M03 = 0f - (m * m4 + m5 * m8 + m9 * m12);
		dst.M13 = 0f - (m2 * m4 + m6 * m8 + m10 * m12);
		dst.M23 = 0f - (m3 * m4 + m7 * m8 + m11 * m12);
		if (src != dst)
		{
			dst.M00 = m;
			dst.M11 = m6;
			dst.M22 = m11;
		}
		dst.M30 = 0f;
		dst.M31 = 0f;
		dst.M32 = 0f;
		dst.M33 = 1f;
	}

