	public static void nnRotateXMatrix(NNS_MATRIX dst, NNS_MATRIX src, int ax)
	{
		if (ax == 0)
		{
			if (dst != src)
			{
				nnCopyMatrix(dst, src);
			}
			return;
		}
		float s;
		float c;
		nnSinCos(ax, out s, out c);
		float num = s;
		float num2 = c;
		float m = src.M01;
		float m2 = src.M02;
		dst.M01 = m * num2 + m2 * num;
		dst.M02 = m * (0f - num) + m2 * num2;
		float m3 = src.M11;
		float m4 = src.M12;
		dst.M11 = m3 * num2 + m4 * num;
		dst.M12 = m3 * (0f - num) + m4 * num2;
		m = src.M21;
		m2 = src.M22;
		dst.M21 = m * num2 + m2 * num;
		dst.M22 = m * (0f - num) + m2 * num2;
		if (dst != src)
		{
			dst.M00 = src.M00;
			dst.M03 = src.M03;
			dst.M10 = src.M10;
			dst.M13 = src.M13;
			dst.M20 = src.M20;
			dst.M23 = src.M23;
			dst.M30 = 0f;
			dst.M31 = 0f;
			dst.M32 = 0f;
			dst.M33 = 1f;
		}
	}

	public static void nnRotateYMatrix(NNS_MATRIX dst, NNS_MATRIX src, int ay)
	{
		if (ay == 0)
		{
			if (dst != src)
			{
				nnCopyMatrix(dst, src);
			}
			return;
		}
		float s;
		float c;
		nnSinCos(ay, out s, out c);
		float num = s;
		float num2 = c;
		float m = src.M00;
		float m2 = src.M02;
		dst.M00 = m * num2 + m2 * (0f - num);
		dst.M02 = m * num + m2 * num2;
		float m3 = src.M10;
		float m4 = src.M12;
		dst.M10 = m3 * num2 + m4 * (0f - num);
		dst.M12 = m3 * num + m4 * num2;
		m = src.M20;
		m2 = src.M22;
		dst.M20 = m * num2 + m2 * (0f - num);
		dst.M22 = m * num + m2 * num2;
		if (dst != src)
		{
			dst.M01 = src.M01;
			dst.M03 = src.M03;
			dst.M11 = src.M11;
			dst.M13 = src.M13;
			dst.M21 = src.M21;
			dst.M23 = src.M23;
			dst.M30 = 0f;
			dst.M31 = 0f;
			dst.M32 = 0f;
			dst.M33 = 1f;
		}
	}

	public static void nnRotateYMatrix(ref SNNS_MATRIX dst, ref SNNS_MATRIX src, int ay)
	{
		if (ay != 0)
		{
			float s;
			float c;
			nnSinCos(ay, out s, out c);
			float num = s;
			float num2 = c;
			float m = src.M00;
			float m2 = src.M02;
			dst.M00 = m * num2 + m2 * (0f - num);
			dst.M02 = m * num + m2 * num2;
			float m3 = src.M10;
			float m4 = src.M12;
			dst.M10 = m3 * num2 + m4 * (0f - num);
			dst.M12 = m3 * num + m4 * num2;
			m = src.M20;
			m2 = src.M22;
			dst.M20 = m * num2 + m2 * (0f - num);
			dst.M22 = m * num + m2 * num2;
			dst.M01 = src.M01;
			dst.M03 = src.M03;
			dst.M11 = src.M11;
			dst.M13 = src.M13;
			dst.M21 = src.M21;
			dst.M23 = src.M23;
			dst.M30 = 0f;
			dst.M31 = 0f;
			dst.M32 = 0f;
			dst.M33 = 1f;
		}
	}

	public static void nnRotateZMatrix(ref SNNS_MATRIX dst, ref SNNS_MATRIX src, int az)
	{
		if (az == 0)
		{
			dst = src;
			return;
		}
		float s;
		float c;
		nnSinCos(az, out s, out c);
		float num = s;
		float num2 = c;
		float m = src.M00;
		float m2 = src.M01;
		dst.M00 = m * num2 + m2 * num;
		dst.M01 = m * (0f - num) + m2 * num2;
		float m3 = src.M10;
		float m4 = src.M11;
		dst.M10 = m3 * num2 + m4 * num;
		dst.M11 = m3 * (0f - num) + m4 * num2;
		m = src.M20;
		m2 = src.M21;
		dst.M20 = m * num2 + m2 * num;
		dst.M21 = m * (0f - num) + m2 * num2;
		dst.M02 = src.M02;
		dst.M03 = src.M03;
		dst.M12 = src.M12;
		dst.M13 = src.M13;
		dst.M22 = src.M22;
		dst.M23 = src.M23;
		dst.M30 = 0f;
		dst.M31 = 0f;
		dst.M32 = 0f;
		dst.M33 = 1f;
	}

	public static void nnRotateZMatrix(NNS_MATRIX dst, NNS_MATRIX src, int az)
	{
		if (az == 0)
		{
			if (dst != src)
			{
				dst.Assign(src);
			}
			return;
		}
		float s;
		float c;
		nnSinCos(az, out s, out c);
		float num = s;
		float num2 = c;
		float m = src.M00;
		float m2 = src.M01;
		dst.M00 = m * num2 + m2 * num;
		dst.M01 = m * (0f - num) + m2 * num2;
		float m3 = src.M10;
		float m4 = src.M11;
		dst.M10 = m3 * num2 + m4 * num;
		dst.M11 = m3 * (0f - num) + m4 * num2;
		m = src.M20;
		m2 = src.M21;
		dst.M20 = m * num2 + m2 * num;
		dst.M21 = m * (0f - num) + m2 * num2;
		if (dst != src)
		{
			dst.M02 = src.M02;
			dst.M03 = src.M03;
			dst.M12 = src.M12;
			dst.M13 = src.M13;
			dst.M22 = src.M22;
			dst.M23 = src.M23;
			dst.M30 = 0f;
			dst.M31 = 0f;
			dst.M32 = 0f;
			dst.M33 = 1f;
		}
	}

	public static void nnRotateXYZMatrix(NNS_MATRIX dst, NNS_MATRIX src, int ax, int ay, int az)
	{
		if (az != 0 || dst != src)
		{
			nnRotateZMatrix(dst, src, az);
		}
		if (ay != 0)
		{
			nnRotateYMatrix(dst, dst, ay);
		}
		if (ax != 0)
		{
			nnRotateXMatrix(dst, dst, ax);
		}
	}

	public static void nnRotateXZYMatrix(NNS_MATRIX dst, NNS_MATRIX src, int ax, int ay, int az)
	{
		if (ay != 0 || dst != src)
		{
			nnRotateYMatrix(dst, src, ay);
		}
		if (az != 0)
		{
			nnRotateZMatrix(dst, dst, az);
		}
		if (ax != 0)
		{
			nnRotateXMatrix(dst, dst, ax);
		}
	}

	public static void nnRotateZXYMatrix(NNS_MATRIX dst, NNS_MATRIX src, int ax, int ay, int az)
	{
		if (ay != 0 || dst != src)
		{
			nnRotateYMatrix(dst, src, ay);
		}
		if (ax != 0)
		{
			nnRotateXMatrix(dst, dst, ax);
		}
		if (az != 0)
		{
			nnRotateZMatrix(dst, dst, az);
		}
	}

	public static void nnScaleMatrix(ref SNNS_MATRIX dst, ref SNNS_MATRIX src, float x, float y, float z)
	{
		dst.M03 = src.M03;
		dst.M13 = src.M13;
		dst.M23 = src.M23;
		dst.M33 = 1f;
		dst.M00 = src.M00 * x;
		dst.M10 = src.M10 * x;
		dst.M20 = src.M20 * x;
		dst.M30 = 0f;
		dst.M01 = src.M01 * y;
		dst.M11 = src.M11 * y;
		dst.M21 = src.M21 * y;
		dst.M31 = 0f;
		dst.M02 = src.M02 * z;
		dst.M12 = src.M12 * z;
		dst.M22 = src.M22 * z;
		dst.M32 = 0f;
	}

	public static void nnScaleMatrix(NNS_MATRIX dst, NNS_MATRIX src, float x, float y, float z)
	{
		if (dst != src)
		{
			dst.M03 = src.M03;
			dst.M13 = src.M13;
			dst.M23 = src.M23;
			dst.M33 = 1f;
		}
		dst.M00 = src.M00 * x;
		dst.M10 = src.M10 * x;
		dst.M20 = src.M20 * x;
		dst.M30 = 0f;
		dst.M01 = src.M01 * y;
		dst.M11 = src.M11 * y;
		dst.M21 = src.M21 * y;
		dst.M31 = 0f;
		dst.M02 = src.M02 * z;
		dst.M12 = src.M12 * z;
		dst.M22 = src.M22 * z;
		dst.M32 = 0f;
	}

	public static void nnTranslateMatrix(ref SNNS_MATRIX dst, ref SNNS_MATRIX src, float x, float y, float z)
	{
		nnCopyMatrix33(ref dst, ref src);
		dst.M30 = 0f;
		dst.M31 = 0f;
		dst.M32 = 0f;
		dst.M03 = src.M00 * x + src.M01 * y + src.M02 * z + src.M03;
		dst.M13 = src.M10 * x + src.M11 * y + src.M12 * z + src.M13;
		dst.M23 = src.M20 * x + src.M21 * y + src.M22 * z + src.M23;
		dst.M33 = 1f;
	}

	public static void nnTranslateMatrix(NNS_MATRIX dst, NNS_MATRIX src, float x, float y, float z)
	{
		if (dst != src)
		{
			nnCopyMatrix33(dst, src);
			dst.M30 = 0f;
			dst.M31 = 0f;
			dst.M32 = 0f;
		}
		dst.M03 = src.M00 * x + src.M01 * y + src.M02 * z + src.M03;
		dst.M13 = src.M10 * x + src.M11 * y + src.M12 * z + src.M13;
		dst.M23 = src.M20 * x + src.M21 * y + src.M22 * z + src.M23;
		dst.M33 = 1f;
	}

