	public static TXB_HEADER readTXBfile(object data)
	{
		AmbChunk ambChunk = (AmbChunk)data;
		return readTXBfile(ambChunk.array, ambChunk.offset);
	}

	public static TXB_HEADER readTXBfile(byte[] data, int offset)
	{
		return readTXBfile(data, offset, null);
	}

	public static TXB_HEADER readTXBfile(byte[] data, int offset, string sPath)
	{
		TXB_HEADER result = null;
		if (data != null)
		{
			using (MemoryStream input = new MemoryStream(data, offset, data.Length - offset))
			{
				using (BinaryReader br = new BinaryReader(input))
				{
					result = readTXBfile(br, sPath);
				}
			}
		}
		return result;
	}

	public static TXB_HEADER readTXBfile(BinaryReader br)
	{
		return readTXBfile(br, null);
	}

	public static TXB_HEADER readTXBfile(BinaryReader br, string sPath)
	{
		TXB_HEADER tXB_HEADER = new TXB_HEADER();
		tXB_HEADER.file_id = br.ReadBytes(4);
		tXB_HEADER.texfilelist_offset = _amConvertEndian(br.ReadInt32());
		tXB_HEADER.pad = br.ReadBytes(8);
		br.BaseStream.Position = tXB_HEADER.texfilelist_offset;
		tXB_HEADER.texfilelist.nTex = _amConvertEndian(br.ReadInt32());
		tXB_HEADER.texfilelist.tex_list_offset = _amConvertEndian(br.ReadInt32());
		if (tXB_HEADER.texfilelist.tex_list_offset != 0)
		{
			br.BaseStream.Position = tXB_HEADER.texfilelist.tex_list_offset;
			tXB_HEADER.texfilelist.pTexFileList = new TXB_TEXFILE[tXB_HEADER.texfilelist.nTex];
			for (int i = 0; i < tXB_HEADER.texfilelist.nTex; i++)
			{
				tXB_HEADER.texfilelist.pTexFileList[i] = new TXB_TEXFILE();
				tXB_HEADER.texfilelist.pTexFileList[i].fType = _amConvertEndian(br.ReadUInt32());
				((TXB_TEXFILE)tXB_HEADER.texfilelist.pTexFileList[i]).name_offset = _amConvertEndian(br.ReadInt32());
				tXB_HEADER.texfilelist.pTexFileList[i].MinFilter = _amConvertEndian(br.ReadUInt16());
				tXB_HEADER.texfilelist.pTexFileList[i].MagFilter = _amConvertEndian(br.ReadUInt16());
				tXB_HEADER.texfilelist.pTexFileList[i].GlobalIndex = _amConvertEndian(br.ReadUInt32());
				tXB_HEADER.texfilelist.pTexFileList[i].Bank = _amConvertEndian(br.ReadUInt32());
			}
			for (int j = 0; j < tXB_HEADER.texfilelist.nTex; j++)
			{
				br.BaseStream.Position = ((TXB_TEXFILE)tXB_HEADER.texfilelist.pTexFileList[j]).name_offset;
				tXB_HEADER.texfilelist.pTexFileList[j].Filename = readChars(br);
				string filename = tXB_HEADER.texfilelist.pTexFileList[j].Filename.Replace(".PVR", ".PNG");
				tXB_HEADER.texfilelist.pTexFileList[j].Filename = filename;
			}
		}
		return tXB_HEADER;
	}

	private static NNS_TEXFILELIST amTxbGetTexFileList(TXB_HEADER txb)
	{
		return txb.texfilelist;
	}

	private static uint amTxbGetCount(TXB_HEADER txb)
	{
		if (txb == null)
		{
			return 0u;
		}
		return (uint)txb.texfilelist.nTex;
	}

	private ushort amTxbGetMagFilter(TXB_HEADER txb, uint tex_no)
	{
		mppAssertNotImpl();
		if (tex_no >= amTxbGetCount(txb))
		{
