		}
		return txb.texfilelist.pTexFileList[tex_no].MinFilter;
	}

	private string amTxbGetName(TXB_HEADER txb, uint tex_no)
	{
		mppAssertNotImpl();
		if (tex_no >= amTxbGetCount(txb))
		{
			tex_no = 0u;
		}
		return txb.texfilelist.pTexFileList[tex_no].Filename;
