					ply_work.obj_work.user_work = 0u;
				}
			}
		}
		else if (ply_work.act_state == 5 && (ply_work.obj_work.disp_flag & 8) != 0)
		{
			int user_work3 = (int)(ply_work.obj_work.user_work + 1);
