		if (ply_work.act_state != 25 && (((ply_work.obj_work.disp_flag & 1) != 0 && !GmPlayerKeyCheckWalkRight(ply_work)) || ((ply_work.obj_work.disp_flag & 1) == 0 && !GmPlayerKeyCheckWalkLeft(ply_work))))
