			break;
		case 24:
			if ((ply_work.obj_work.spd_m <= 0 || !GmPlayerKeyCheckWalkLeft(ply_work)) && (ply_work.obj_work.spd_m >= 0 || !GmPlayerKeyCheckWalkRight(ply_work)))
			{
				GmPlySeqChangeSequence(ply_work, 2);
			}
			break;
		case 25:
			if ((ply_work.obj_work.disp_flag & 8) != 0)
			{
				if (ply_work.obj_work.spd_m != 0)
				{
					GmPlySeqChangeSequence(ply_work, 1);
				}
				else
				{
					GmPlySeqChangeSequence(ply_work, 0);
				}
			}
			break;
		}
