	private static void gmPlySeqTruckWalkMain(GMS_PLAYER_WORK ply_work)
	{
		bool flag = false;
		if (ply_work.obj_work.spd_m < 0 && ply_work.act_state == 71)
		{
			ply_work.truck_left_flip_timer = ObjTimeCountDown(ply_work.truck_left_flip_timer);
