			}
			else if (ply_work.obj_work.spd_m < 0)
			{
				ply_work.gmk_flag |= 1048576u;
				GmPlayerActionChange(ply_work, 72);
			}
			ply_work.obj_work.disp_flag |= 4u;
		}
