		ply_work.gmk_flag &= 1073479679u;
		ply_work.seq_func = gmPlySeqTruckJumpMain;
		ushort angle = (ushort)(ply_work.obj_work.dir.z + ply_work.obj_work.dir_fall - ply_work.jump_pseudofall_dir);
		ply_work.obj_work.spd.x = FX_Mul(ply_work.obj_work.spd_m, mtMathCos(angle));
		ply_work.obj_work.spd.y = FX_Mul(ply_work.obj_work.spd_m, mtMathSin(angle));
