		{
			GmPlySeqChangeSequence(ply_work, 0);
		}
		else if (ply_work.seq_state == 13)
		{
			ply_work.obj_work.user_timer += 1024;
			if (ply_work.obj_work.user_timer > 8192)
			{
				ply_work.obj_work.user_timer = 8192;
			}
		}
		else
		{
			ply_work.obj_work.user_timer -= 1024;
			if (ply_work.obj_work.user_timer < -8192)
			{
				ply_work.obj_work.user_timer = -8192;
			}
		}
	}

	private static void GmPlySeqLandingSet(GMS_PLAYER_WORK ply_work, ushort dir_z)
	{
		GmPlayerSpdParameterSet(ply_work);
		ply_work.obj_work.move_flag &= 4294934511u;
		ply_work.obj_work.move_flag |= 128u;
		ply_work.obj_work.disp_flag &= 4294967263u;
		ply_work.gmk_flag &= 4278190079u;
		ply_work.gmk_flag2 &= 4294967007u;
		ply_work.gmk_flag2 &= 4294966783u;
		ply_work.player_flag &= 4294967135u;
		ply_work.no_jump_move_timer = 0;
		ply_work.score_combo_cnt = 0u;
		if ((ply_work.gmk_flag & 1) == 0 && (ply_work.obj_work.col_flag & 1) != 0)
		{
			ply_work.obj_work.dir.z = 0;
		}
		if (dir_z > 0)
		{
			if ((ply_work.player_flag & 0x40000) != 0)
			{
				if ((ply_work.gmk_flag2 & 1) != 0)
				{
					ply_work.obj_work.spd_m += FX_Mul(FX_Mul(ply_work.obj_work.move.x, 2048), mtMathCos((ushort)(dir_z - g_gm_main_system.pseudofall_dir)));
					ply_work.obj_work.spd_m += FX_Mul(FX_Mul(ply_work.obj_work.move.y, 2048), mtMathSin((ushort)(dir_z - g_gm_main_system.pseudofall_dir)));
				}
				else
				{
					ply_work.obj_work.spd_m += FX_Mul(ply_work.obj_work.move.x, mtMathCos((ushort)(dir_z - g_gm_main_system.pseudofall_dir)));
					ply_work.obj_work.spd_m += FX_Mul(ply_work.obj_work.move.y, mtMathSin((ushort)(dir_z - g_gm_main_system.pseudofall_dir)));
				}
			}
			else
			{
				ply_work.obj_work.spd_m += FX_Mul(ply_work.obj_work.move.x, mtMathCos(dir_z));
				ply_work.obj_work.spd_m += FX_Mul(ply_work.obj_work.move.y, mtMathSin(dir_z));
				if (ObjObjectDirFallReverseCheck(ply_work.obj_work.dir_fall) != 0)
				{
					ply_work.obj_work.spd_m = -ply_work.obj_work.spd_m;
				}
			}
		}
		else if ((ply_work.player_flag & 0x40000) != 0)
		{
			if (MTM_MATH_ABS(ply_work.obj_work.spd_m) < MTM_MATH_ABS(ply_work.obj_work.spd.x))
			{
				ply_work.obj_work.spd_m = ply_work.obj_work.spd.x;
			}
			ply_work.obj_work.spd_m += FX_Mul(MTM_MATH_ABS(ply_work.obj_work.spd.x), mtMathSin((ushort)(ply_work.obj_work.dir.z + (ply_work.obj_work.dir_fall - g_gm_main_system.pseudofall_dir))));
		}
		else
		{
			if (MTM_MATH_ABS(ply_work.obj_work.spd_m) < MTM_MATH_ABS(ply_work.obj_work.spd.x))
			{
				ply_work.obj_work.spd_m = ply_work.obj_work.spd.x;
			}
			ply_work.obj_work.spd_m += FX_Mul(MTM_MATH_ABS(ply_work.obj_work.spd.x), mtMathSin(ply_work.obj_work.dir.z));
		}
		ply_work.gmk_flag2 &= 4294967294u;
		ply_work.spd_work_max = MTM_MATH_ABS(ply_work.obj_work.spd_m);
		if (ply_work.spd_work_max > ply_work.obj_work.spd_slope_max)
		{
			ply_work.spd_work_max = ply_work.obj_work.spd_slope_max;
		}
		ply_work.obj_work.spd.x = 0;
		ply_work.obj_work.spd.y = 0;
		if (dir_z != 0)
		{
			ply_work.obj_work.dir.z = dir_z;
		}
		if ((ply_work.gmk_flag & 0x1000) == 0)
		{
			ply_work.obj_work.dir.x = 0;
		}
		if ((ply_work.player_flag & 0x40000) != 0)
		{
			ply_work.obj_work.move_flag &= 4294950911u;
		}
	}

	private static void GmPlySeqMoveFunc(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)obj_work;
		GMS_PLY_SEQ_STATE_DATA[] seq_state_data_tbl = gMS_PLAYER_WORK.seq_state_data_tbl;
		if ((seq_state_data_tbl[gMS_PLAYER_WORK.seq_state].check_attr & 0x80000000u) != 0)
		{
			if ((gMS_PLAYER_WORK.player_flag & 0x8000) != 0)
			{
				GmPlySeqMoveWalkAutoRun(gMS_PLAYER_WORK);
			}
			else if ((gMS_PLAYER_WORK.player_flag & 0x40000) != 0)
			{
				GmPlySeqMoveWalkTruck(gMS_PLAYER_WORK);
			}
			else
			{
				GmPlySeqMoveWalk(gMS_PLAYER_WORK);
			}
		}
		if ((seq_state_data_tbl[gMS_PLAYER_WORK.seq_state].check_attr & 0x40000000) != 0 && (gMS_PLAYER_WORK.player_flag & 0x20) == 0)
		{
			if ((gMS_PLAYER_WORK.player_flag & 0x8000) != 0)
			{
				GmPlySeqMoveJumpAutoRun(gMS_PLAYER_WORK);
			}
			else if ((gMS_PLAYER_WORK.player_flag & 0x40000) != 0)
			{
				GmPlySeqMoveJumpTruck(gMS_PLAYER_WORK);
			}
			else
			{
				GmPlySeqMoveJump(gMS_PLAYER_WORK);
			}
		}
		if (gMS_PLAYER_WORK.no_jump_move_timer != 0)
		{
			gMS_PLAYER_WORK.no_jump_move_timer = ObjTimeCountDown(gMS_PLAYER_WORK.no_jump_move_timer);
			if (gMS_PLAYER_WORK.no_jump_move_timer == 0)
			{
				gMS_PLAYER_WORK.player_flag &= 4294967263u;
			}
		}
		if ((seq_state_data_tbl[gMS_PLAYER_WORK.seq_state].check_attr & 0x20000000) != 0)
		{
			GmPlySeqMoveSpin(gMS_PLAYER_WORK);
		}
		if ((seq_state_data_tbl[gMS_PLAYER_WORK.seq_state].check_attr & 0x8000000) != 0)
		{
			GmPlySeqMoveSpinNoDec(gMS_PLAYER_WORK);
		}
		if ((seq_state_data_tbl[gMS_PLAYER_WORK.seq_state].check_attr & 0x4000000) != 0)
		{
			GmPlySeqMoveSpinPinball(gMS_PLAYER_WORK);
		}
		if ((seq_state_data_tbl[gMS_PLAYER_WORK.seq_state].check_attr & 0x10000000) != 0)
		{
			if ((gMS_PLAYER_WORK.player_flag & 0x40000) != 0)
			{
				GmPlySeqTruckJumpDirec(gMS_PLAYER_WORK);
			}
			else if (GSM_MAIN_STAGE_IS_SPSTAGE_NOT_RETRY())
			{
				gmPlySeqSplJumpDirec(gMS_PLAYER_WORK);
			}
			else
			{
				GmPlySeqJumpDirec(gMS_PLAYER_WORK);
			}
		}
		if ((gMS_PLAYER_WORK.player_flag & 0x8000) != 0 && (gMS_PLAYER_WORK.player_flag & 0x400) == 0 && obj_work.pos.x <= g_obj.camera[0][0] + 65536 && obj_work.pos.x > g_obj.camera[0][0] + 65536 - 4194304)
		{
			if ((obj_work.move_flag & 0x10) != 0)
			{
				if (obj_work.spd.x < gMS_PLAYER_WORK.scroll_spd_x)
				{
					obj_work.spd.x = gMS_PLAYER_WORK.scroll_spd_x;
					if ((obj_work.disp_flag & 1) != 0)
					{
						GmPlySeqSetProgramTurn(gMS_PLAYER_WORK, 4096);
					}
				}
			}
			else if (obj_work.spd_m < gMS_PLAYER_WORK.scroll_spd_x)
			{
				obj_work.spd_m = gMS_PLAYER_WORK.scroll_spd_x;
				if (3 <= gMS_PLAYER_WORK.seq_state && gMS_PLAYER_WORK.seq_state <= 5)
				{
					GmPlySeqChangeSequence(gMS_PLAYER_WORK, 0);
				}
				if ((obj_work.disp_flag & 1) != 0)
				{
					if (gMS_PLAYER_WORK.seq_state == 10)
					{
						GmPlayerSetReverse(gMS_PLAYER_WORK);
						GmPlySeqChangeSequence(gMS_PLAYER_WORK, 0);
					}
					else if (6 <= gMS_PLAYER_WORK.seq_state && gMS_PLAYER_WORK.seq_state <= 8)
					{
						GmPlySeqSetProgramTurn(gMS_PLAYER_WORK, 4096);
					}
					else
					{
						GmPlySeqChangeSequence(gMS_PLAYER_WORK, 2);
					}
				}
			}
		}
		if ((gMS_PLAYER_WORK.player_flag & 0x40000) != 0)
		{
			if ((obj_work.move_flag & 1) == 0 || (gMS_PLAYER_WORK.gmk_flag & 0x40000) == 0)
			{
				gmPlySeqTruckMove(obj_work);
			}
		}
		else if (GSM_MAIN_STAGE_IS_SPSTAGE_NOT_RETRY())
		{
			gmPlySeqSplMove(obj_work);
		}
		else
		{
			ObjObjectMove(obj_work);
		}
	}

	private static void GmPlySeqMoveWalk(GMS_PLAYER_WORK ply_work)
	{
		int fSpd = ply_work.spd_add;
		int fSpd2 = ply_work.spd_dec;
		int num = ply_work.spd_max;
		if (GmPlayerKeyCheckWalkRight(ply_work) || GmPlayerKeyCheckWalkLeft(ply_work))
		{
			int num2 = MTM_MATH_ABS(ply_work.key_walk_rot_z);
			if (num2 > 24576)
			{
				num2 = 24576;
			}
			num = num * num2 / 24576;
		}
		if (num < ply_work.prev_walk_roll_spd_max)
		{
			num = ply_work.prev_walk_roll_spd_max - fSpd2;
			if (num < 0)
			{
				num = 0;
			}
		}
		ply_work.prev_walk_roll_spd_max = num;
		if (ply_work.obj_work.dir.z > 0)
		{
			int num3 = FX_Mul(ply_work.spd_max_add_slope, mtMathSin(ply_work.obj_work.dir.z));
			if (num3 > 0)
			{
				num += num3;
			}
		}
		if (ply_work.no_spddown_timer != 0)
		{
			fSpd2 = 0;
		}
		else
		{
			int v = 0;
			if (MTM_MATH_ABS(ply_work.obj_work.spd_m) > ply_work.spd3)
			{
				if (num - ply_work.spd3 != 0)
				{
					v = FX_Div(MTM_MATH_ABS(ply_work.obj_work.spd_m) - ply_work.spd3, num - ply_work.spd3);
					if (v > 4096)
					{
						v = 4096;
					}
				}
				else
				{
					v = 4096;
				}
				v = v * 3968 >> 12;
			}
			fSpd -= FX_Mul(fSpd, v);
		}
		if ((ply_work.player_flag & 0x4000000) != 0)
		{
			GMD_PLAYER_WATER_SET(ref fSpd);
			GMD_PLAYER_WATER_SET(ref fSpd2);
		}
		if (ply_work.spd_work_max >= num && MTM_MATH_ABS(ply_work.obj_work.spd_m) >= num)
		{
			if (ply_work.spd_work_max > ply_work.obj_work.spd_m)
			{
				ply_work.spd_work_max = MTM_MATH_ABS(ply_work.obj_work.spd_m);
			}
			num = ply_work.spd_work_max;
		}
		if ((ply_work.player_flag & 0x8000) != 0 && GmPlayerKeyCheckWalkRight(ply_work) && num > ply_work.scroll_spd_x + 8192)
		{
			num = ply_work.scroll_spd_x + 8192;
		}
		if (GmPlayerKeyCheckWalkLeft(ply_work) | GmPlayerKeyCheckWalkRight(ply_work))
		{
			if (GmPlayerKeyCheckWalkRight(ply_work))
			{
				if (ply_work.obj_work.spd_m < 0)
				{
					ply_work.obj_work.spd_m = ObjSpdDownSet(ply_work.obj_work.spd_m, fSpd2);
				}
				ply_work.obj_work.spd_m = ObjSpdUpSet(ply_work.obj_work.spd_m, fSpd, num);
			}
			else
			{
				if (ply_work.obj_work.spd_m > 0)
				{
					ply_work.obj_work.spd_m = ObjSpdDownSet(ply_work.obj_work.spd_m, fSpd2);
				}
				ply_work.obj_work.spd_m = ObjSpdUpSet(ply_work.obj_work.spd_m, -fSpd, num);
			}
			return;
		}
		ply_work.spd_pool = 0;
		ply_work.obj_work.spd.x = MTM_MATH_CLIP(ply_work.obj_work.spd.x, -num, num);
		ply_work.obj_work.spd_m = MTM_MATH_CLIP(ply_work.obj_work.spd_m, -num, num);
		if (((ply_work.obj_work.dir.z + 8192) & 0xFF00) > 16384)
		{
			return;
		}
		if ((ply_work.player_flag & 0x8000000) != 0)
		{
			ply_work.player_flag &= 4160749567u;
		}
		else if ((ply_work.player_flag & 0x8000) != 0)
		{
			if ((ply_work.obj_work.disp_flag & 1) == 0 && ply_work.seq_state == 1)
			{
				int num4 = ply_work.scroll_spd_x + -4096;
				if (num4 < 0)
				{
					num4 = 0;
				}
				ply_work.obj_work.spd_m = ObjSpdDownSet(ply_work.obj_work.spd_m, fSpd2);
				if (ply_work.obj_work.spd_m < num4)
				{
					ply_work.obj_work.spd_m = num4;
				}
			}
			else
			{
				ply_work.obj_work.spd_m = ObjSpdDownSet(ply_work.obj_work.spd_m, fSpd2);
			}
		}
		else
		{
			ply_work.obj_work.spd_m = ObjSpdDownSet(ply_work.obj_work.spd_m, fSpd2);
		}
	}

