		if (((g_gm_main_system.game_flag & 0x100000) != 0 || (ply_work.player_flag & 0x1000000) != 0) && (GmPlayerKeyCheckWalkLeft(ply_work) | GmPlayerKeyCheckWalkRight(ply_work)))
		{
			if (GmPlayerKeyCheckWalkRight(ply_work))
