			if (ply_work.obj_work.spd_m < ply_work.scroll_spd_x + FX_F32_TO_FX32(0.25f))
			{
				ply_work.obj_work.spd_m = ply_work.scroll_spd_x + FX_F32_TO_FX32(0.25f);
			}
