		if (spd_max < ply_work.prev_walk_roll_spd_max)
		{
			spd_max = ply_work.prev_walk_roll_spd_max - fSpd2;
			if (spd_max < 0)
			{
				spd_max = 0;
			}
		}
		ply_work.prev_walk_roll_spd_max = spd_max;
		if (ply_work.obj_work.dir.z != 0)
		{
			int num2 = FX_Mul(ply_work.spd_max_add_slope, mtMathSin(ply_work.obj_work.dir.z));
			if (num2 > 0)
			{
				spd_max += num2;
			}
		}
		if (ply_work.no_spddown_timer != 0)
		{
			fSpd2 = 0;
		}
		else
		{
			int v = 0;
			if (MTM_MATH_ABS(ply_work.obj_work.spd_m) > ply_work.spd3)
			{
				if (spd_max - ply_work.spd3 != 0)
				{
					v = FX_Div(MTM_MATH_ABS(ply_work.obj_work.spd_m) - ply_work.spd3, spd_max - ply_work.spd3);
					if (v > 4096)
