	private static void gmPlySeqSplStgRollCtrl(GMS_PLAYER_WORK ply_work)
	{
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
		if ((g_gm_main_system.game_flag & 0x1071218) != 0)
		{
			return;
		}
		int key_rot_z = ply_work.key_rot_z;
		if ((g_gs_main_sys_info.game_flag & 0x200) != 0)
		{
			key_rot_z = key_rot_z * 26 / 10;
			oBS_CAMERA.roll += key_rot_z;
		}
		else
		{
			int num = 66;
			ply_work.accel_counter--;
			if (ply_work.accel_counter <= 0)
			{
				ply_work.accel_counter = 0;
				int num2 = key_rot_z - ply_work.prev_key_rot_z;
				num2 = num2 * 3 / 4;
				if (MTM_MATH_ABS(num2) < 16384)
				{
					num2 = 0;
				}
				else if ((num2 < 0 && key_rot_z > 0) || (num2 > 0 && key_rot_z < 0))
				{
					num2 = 0;
				}
				else
				{
					num2 /= 64;
					ply_work.dir_vec_add = num2;
					ply_work.accel_counter = 8;
				}
			}
			key_rot_z /= num;
			key_rot_z += ply_work.dir_vec_add * ply_work.accel_counter;
			oBS_CAMERA.roll += key_rot_z;
		}
		if (ply_work.nudge_di_timer != 0)
		{
			ply_work.nudge_di_timer--;
			return;
		}
		bool flag = false;
		if ((ply_work.key_push & 0xA0) != 0)
		{
			flag = true;
		}
		if (flag)
		{
			GMS_SPL_STG_WORK gMS_SPL_STG_WORK = GmSplStageGetWork();
			ply_work.nudge_di_timer = 30;
			ply_work.nudge_timer = 30;
			gMS_SPL_STG_WORK.flag &= 4294967293u;
		}
	}

