	private static void gmGmkSeesawStay(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_SEESAW_WORK gMS_GMK_SEESAW_WORK = (GMS_GMK_SEESAW_WORK)obj_work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (lock_seesaw_id == gMS_GMK_SEESAW_WORK.seesaw_id)
		{
			gMS_GMK_SEESAW_WORK.tilt = seesaw_tilt[gMS_GMK_SEESAW_WORK.seesaw_id];
			obj_work.dir.z = (ushort)gMS_GMK_SEESAW_WORK.tilt;
			gMS_GMK_SEESAW_WORK.tilt_timer = 60;
		}
		else if (gMS_GMK_SEESAW_WORK.tilt != gMS_GMK_SEESAW_WORK.initial_tilt)
		{
			if (gMS_GMK_SEESAW_WORK.tilt_timer <= 0)
			{
				if (gMS_GMK_SEESAW_WORK.tilt > gMS_GMK_SEESAW_WORK.initial_tilt)
				{
					gMS_GMK_SEESAW_WORK.tilt -= 256;
					if (gMS_GMK_SEESAW_WORK.tilt < gMS_GMK_SEESAW_WORK.initial_tilt)
					{
						gMS_GMK_SEESAW_WORK.tilt = gMS_GMK_SEESAW_WORK.initial_tilt;
					}
				}
				else if (gMS_GMK_SEESAW_WORK.tilt < gMS_GMK_SEESAW_WORK.initial_tilt)
				{
					gMS_GMK_SEESAW_WORK.tilt += 256;
					if (gMS_GMK_SEESAW_WORK.tilt > gMS_GMK_SEESAW_WORK.initial_tilt)
					{
						gMS_GMK_SEESAW_WORK.tilt = gMS_GMK_SEESAW_WORK.initial_tilt;
					}
				}
			}
			else
			{
				gMS_GMK_SEESAW_WORK.tilt_timer--;
			}
		}
		obj_work.dir.z = (ushort)gMS_GMK_SEESAW_WORK.tilt;
		if (gMS_GMK_SEESAW_WORK.tilt == 0)
		{
			gMS_GMK_SEESAW_WORK.tilt = 0;
		}
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0 || (gMS_PLAYER_WORK.obj_work.flag & 2) != 0 || ((gMS_PLAYER_WORK.obj_work.move_flag & 0x10) != 0 && gMS_PLAYER_WORK.obj_work.spd.y < 0))
		{
			return;
		}
		int num = mtMathSin((ushort)gMS_GMK_SEESAW_WORK.tilt) * 29;
		int num2 = mtMathCos((ushort)gMS_GMK_SEESAW_WORK.tilt) * 29;
		int num3 = mtMathCos((ushort)gMS_GMK_SEESAW_WORK.tilt) * 112 / 2;
		int num4 = MTM_MATH_ABS(mtMathSin((ushort)gMS_GMK_SEESAW_WORK.tilt) * 112 / 2);
		int num5 = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
		if (num5 < -(num3 + 131072 - num) || num5 > num3 + 131072 + num)
		{
			return;
		}
		int num6 = 0;
		int num7 = 0;
		long num8;
		long num9;
		if (gMS_PLAYER_WORK.obj_work.move.x == 0)
		{
			if (gMS_PLAYER_WORK.obj_work.move.y == 0)
			{
				return;
			}
