		player_distance = gMS_GMK_SEESAW_WORK.player_distance - player_distance;
		gMS_GMK_SEESAW_WORK.player_speed += 256 * mtMathSin((ushort)gMS_GMK_SEESAW_WORK.tilt) >> 12;
