	private static void DmManualBuild(AMS_AMB_HEADER[] arc_amb)
	{
		int num = 0;
		dm_manual_mgr.Clear();
		dm_manual_mgr_p = dm_manual_mgr;
		for (num = 0; num < 2; num++)
		{
			dm_manual_tex[num].Clear();
		}
		for (num = 0; num < 2; num++)
		{
			dm_manual_ama[num] = readAMAFile(amBindGet(arc_amb[num], 0));
			string sPath;
			dm_manual_amb[num] = readAMBFile(amBindGet(arc_amb[num], 1, out sPath));
			dm_manual_amb[num].dir = sPath;
		}
		for (num = 0; num < 2; num++)
		{
			AoTexBuild(dm_manual_tex[num], dm_manual_amb[num]);
			AoTexLoad(dm_manual_tex[num]);
		}
	}

	private static bool DmManualBuildCheck()
	{
		if (dmManualIsTexLoad() != 0)
		{
			return true;
		}
		return false;
	}

	private static void DmManualFlush()
	{
		for (int i = 0; i < 2; i++)
		{
			AoTexRelease(dm_manual_tex[i]);
		}
	}

	private static bool DmManualFlushCheck()
	{
		if (dmManualIsTexRelease() != 0)
		{
			return true;
		}
		return false;
	}

	private static void DmManualStart()
	{
		dmManualInit();
	}

	private static bool DmManualIsExit()
	{
		if (dm_manual_mgr_p.tcb == null)
		{
			return true;
		}
		return false;
	}

	private static void DmManualExit()
	{
		if (dm_manual_mgr_p.tcb != null)
		{
			mtTaskClearTcb(dm_manual_mgr_p.tcb);
			dm_manual_mgr_p.tcb = null;
		}
	}

	private static void dmManualInit()
	{
		short num = 0;
		dm_manual_mgr_p.tcb = MTM_TASK_MAKE_TCB(dmManualProcMain, dmManualDest, 0u, 32767, 12288u, 10, () => new DMS_MANUAL_MAIN_WORK(), "MANUAL_MAIN");
		DMS_MANUAL_MAIN_WORK dMS_MANUAL_MAIN_WORK = (DMS_MANUAL_MAIN_WORK)dm_manual_mgr_p.tcb.work;
		dMS_MANUAL_MAIN_WORK.draw_state = (AoActSysGetDrawStateEnable() ? 1u : 0u);
		AoActSysSetDrawStateEnable(dMS_MANUAL_MAIN_WORK.draw_state != 0);
		if (dMS_MANUAL_MAIN_WORK.draw_state != 0)
		{
			dm_manual_draw_state = AoActSysGetDrawState();
			AoActSysSetDrawState(dm_manual_draw_state);
		}
		if (GeEnvGetDecideKey() == GSE_DECIDE_KEY.GSD_DECIDE_KEY_O)
		{
			dMS_MANUAL_MAIN_WORK.is_jp_region = true;
		}
		else
		{
			dMS_MANUAL_MAIN_WORK.is_jp_region = false;
		}
		dmManualSetInitData(dMS_MANUAL_MAIN_WORK);
		num = SyGetEvtInfo().cur_evt_id;
		if (num == 6 || num == 11)
		{
			dm_manual_is_pause_maingame = true;
			dMS_MANUAL_MAIN_WORK.se_handle = GsSoundAllocSeHandle();
		}
		dMS_MANUAL_MAIN_WORK.proc_update = dmManualProcInit;
	}

	private static void dmManualSetInitData(DMS_MANUAL_MAIN_WORK main_work)
	{
		main_work.cur_disp_page = 0;
		main_work.cur_disp_page_prev = -1;
	}

	private static void dmManualProcMain(MTS_TASK_TCB tcb)
	{
		DMS_MANUAL_MAIN_WORK dMS_MANUAL_MAIN_WORK = (DMS_MANUAL_MAIN_WORK)tcb.work;
		if ((dMS_MANUAL_MAIN_WORK.flag & 1) != 0)
		{
			DmManualExit();
		}
		if ((dMS_MANUAL_MAIN_WORK.flag & 0x80000000u) != 0 && !AoAccountIsCurrentEnable())
		{
			dMS_MANUAL_MAIN_WORK.proc_update = dmManualProcFadeOut;
			dMS_MANUAL_MAIN_WORK.flag &= 2147483647u;
			if (dm_manual_is_pause_maingame)
			{
				IzFadeInitEasyColor(0, 32767, 61439, 18u, 1u, 1u, 32f, true);
			}
			else
			{
				IzFadeInitEasy(1u, 1u, 32f);
			}
			dMS_MANUAL_MAIN_WORK.flag &= 4294967291u;
			dMS_MANUAL_MAIN_WORK.flag &= 4294967293u;
			dMS_MANUAL_MAIN_WORK.proc_input = null;
		}
		if (dMS_MANUAL_MAIN_WORK.proc_update != null)
		{
			dMS_MANUAL_MAIN_WORK.proc_update(dMS_MANUAL_MAIN_WORK);
		}
		if (dMS_MANUAL_MAIN_WORK.proc_draw != null)
		{
			dMS_MANUAL_MAIN_WORK.proc_draw(dMS_MANUAL_MAIN_WORK);
		}
	}

	private static void dmManualDest(MTS_TASK_TCB tcb)
	{
	}

	private static void dmManualProcInit(DMS_MANUAL_MAIN_WORK main_work)
	{
		main_work.proc_update = dmManualProcCreateAct;
		main_work.flag |= 2147483648u;
	}

	private static void dmManualProcCreateAct(DMS_MANUAL_MAIN_WORK main_work)
	{
		for (uint num = 0u; num <= 13; num++)
		{
			A2S_AMA_HEADER ama = dm_manual_ama[0];
			AOS_TEXTURE tex = dm_manual_tex[0];
			AoActSetTexture(AoTexGetTexList(tex));
			main_work.act[num] = AoActCreate(ama, g_dm_act_id_tbl_m[num]);
		}
		for (uint num2 = 10u; num2 <= 11; num2++)
		{
			main_work.trg_btn[num2 - 10].Create(main_work.act[num2]);
		}
		main_work.trg_return.Create(main_work.act[13]);
		for (uint num3 = 119u; num3 <= 120; num3++)
		{
			A2S_AMA_HEADER ama = dm_manual_ama[1];
			AOS_TEXTURE tex = dm_manual_tex[1];
			AoActSetTexture(AoTexGetTexList(tex));
			main_work.act[num3] = AoActCreate(ama, g_dm_act_id_tbl_m[num3]);
		}
		main_work.proc_update = dmManualProcFadeIn;
		main_work.proc_draw = dmManualProcActDraw;
		if (dm_manual_is_pause_maingame)
		{
			IzFadeInitEasyColor(0, 32767, 61439, 18u, 0u, 0u, 32f, true);
		}
		else
		{
			IzFadeInitEasy(0u, 0u, 32f);
		}
	}

	private static void dmManualProcFadeIn(DMS_MANUAL_MAIN_WORK main_work)
	{
		if (IzFadeIsEnd())
		{
			IzFadeExit();
			main_work.proc_update = dmManualProcWaitInput;
			main_work.proc_input = dmManualInputProcMain;
		}
	}

	private static void dmManualProcWaitInput(DMS_MANUAL_MAIN_WORK main_work)
	{
		if (main_work.proc_input != null)
		{
			main_work.proc_input(main_work);
		}
		int[] array = new int[3] { 12, 13, 119 };
		int i = 0;
		for (int num = array.Length; i < num; i++)
		{
			AOS_ACTION aOS_ACTION = main_work.act[array[i]];
			float frame = ((main_work.trg_return.GetState(0u)[10] && main_work.trg_return.GetState(0u)[1]) ? 2f : ((!main_work.trg_return.GetState(0u)[0]) ? ((!(2f <= aOS_ACTION.frame)) ? 0f : aOS_ACTION.frame) : 1f));
			AoActSetFrame(aOS_ACTION, frame);
		}
		if ((main_work.flag & 2) != 0)
		{
			main_work.proc_update = dmManualProcFadeOut;
			if (dm_manual_is_pause_maingame)
			{
				IzFadeInitEasyColor(0, 32767, 61439, 18u, 0u, 1u, 32f, true);
			}
			else
			{
				IzFadeInitEasy(0u, 1u, 32f);
			}
			if (!dm_manual_is_pause_maingame)
			{
				DmSoundPlaySE("Cancel");
			}
			else
			{
				GsSoundPlaySe("Cancel", main_work.se_handle);
			}
			main_work.flag &= 4294967291u;
			main_work.flag &= 4294967293u;
		}
		else if ((main_work.flag & 8) != 0)
		{
			main_work.cur_disp_page++;
			if (main_work.cur_disp_page > 14)
			{
				main_work.cur_disp_page = 14;
			}
			else if (!dm_manual_is_pause_maingame)
			{
				DmSoundPlaySE("Cursol");
			}
			else
			{
				GsSoundPlaySe("Cursol", main_work.se_handle);
			}
			main_work.flag &= 4294967287u;
		}
		else if ((main_work.flag & 0x10) != 0)
		{
			main_work.cur_disp_page--;
			if (main_work.cur_disp_page < 0)
			{
				main_work.cur_disp_page = 0;
			}
			else if (!dm_manual_is_pause_maingame)
			{
				DmSoundPlaySE("Cursol");
			}
			else
			{
				GsSoundPlaySe("Cursol", main_work.se_handle);
			}
			main_work.flag &= 4294967279u;
		}
	}

	private static void dmManualProcFadeOut(DMS_MANUAL_MAIN_WORK main_work)
	{
		if (IzFadeIsEnd())
		{
			main_work.proc_update = dmManualProcStopDraw;
			main_work.proc_draw = null;
			if (main_work.se_handle != null)
			{
				GsSoundFreeSeHandle(main_work.se_handle);
				main_work.se_handle = null;
			}
		}
	}

	private static void dmManualInputProcMain(DMS_MANUAL_MAIN_WORK main_work)
	{
		if ((main_work.trg_return.GetState(0u)[10] && main_work.trg_return.GetState(0u)[1]) || isBackKeyPressed())
		{
			setBackKeyRequest(false);
			main_work.flag |= 2u;
		}
		else if (main_work.trg_btn[1].GetState(0u)[7])
		{
			if (main_work.trg_btn[1].GetState(0u)[8] || main_work.cur_disp_page != 14)
			{
				main_work.flag |= 8u;
			}
		}
		else if (main_work.trg_btn[0].GetState(0u)[7] && (main_work.trg_btn[0].GetState(0u)[8] || main_work.cur_disp_page != 0))
		{
			main_work.flag |= 16u;
		}
	}

	private static void dmManualProcStopDraw(DMS_MANUAL_MAIN_WORK main_work)
	{
		for (int i = 0; i < 179; i++)
		{
			if (main_work.act[i] != null)
			{
				AoActDelete(main_work.act[i]);
				main_work.act[i] = null;
			}
		}
		for (int j = 0; j < main_work.trg_btn.Length; j++)
		{
			CTrgAoAction cTrgAoAction = main_work.trg_btn[j];
			cTrgAoAction.Release();
		}
		CTrgAoAction trg_return = main_work.trg_return;
		trg_return.Release();
		main_work.proc_update = null;
		main_work.flag |= 1u;
	}

	private static void dmManualProcActDraw(DMS_MANUAL_MAIN_WORK main_work)
	{
		dmManualCommonBgDraw(main_work);
		dmManualPageDraw(main_work);
		dmManualCommonDraw(main_work);
		if (main_work.draw_state != 0)
		{
			amDrawMakeTask(dmManualTaskDraw, 32768, 0u);
		}
	}

	private static void dmManualTaskDraw(AMS_TCB tcb)
	{
		AoActDrawPre();
		amDrawExecCommand(dm_manual_draw_state);
		amDrawEndScene();
	}

	private static void dmManualCommonBgDraw(DMS_MANUAL_MAIN_WORK main_work)
	{
		AoActSysSetDrawTaskPrio(6144u);
		AoActSetTexture(AoTexGetTexList(dm_manual_tex[0]));
		for (int i = 0; i <= 4; i++)
		{
			AoActSortRegAction(main_work.act[i]);
		}
		for (int j = 0; j <= 4; j++)
		{
			AoActUpdate(main_work.act[j], 0f);
			if (j == 3)
			{
				main_work.act[j].sprite.offset.top -= 1f;
				main_work.act[j].sprite.offset.left -= 2f;
			}
		}
		AoActSortExecute();
		AoActSortDraw();
		AoActSortUnregAll();
	}

	private static void dmManualCommonDraw(DMS_MANUAL_MAIN_WORK main_work)
	{
		float num = 0f;
		float num2 = 0f;
		AoActSysSetDrawTaskPrio(12288u);
		AoActSetTexture(AoTexGetTexList(dm_manual_tex[0]));
		for (int i = 5; i <= 11; i++)
		{
			switch (i)
			{
			case 5:
				if (main_work.cur_disp_page >= 9)
				{
					AoActSortRegAction(main_work.act[i]);
				}
				break;
			case 10:
				if (main_work.cur_disp_page != 0)
				{
					AoActSortRegAction(main_work.act[i]);
				}
				break;
			case 11:
				if (main_work.cur_disp_page != 14)
				{
					AoActSortRegAction(main_work.act[i]);
				}
				break;
			default:
				AoActSortRegAction(main_work.act[i]);
				break;
			}
		}
		AoActSetTexture(AoTexGetTexList(dm_manual_tex[1]));
		for (int j = 119; j < 120; j++)
		{
			AoActSortRegAction(main_work.act[j]);
		}
		if (main_work.cur_disp_page >= 1)
		{
			AoActSortRegAction(main_work.act[120]);
		}
		for (int k = 12; k <= 13; k++)
		{
			AoActSortRegAction(main_work.act[k]);
		}
		num = ((main_work.cur_disp_page == 0) ? 0f : ((float)(main_work.cur_disp_page / 10)));
		num2 = main_work.cur_disp_page % 10;
		if (main_work.cur_disp_page == 9)
		{
			AoActSetFrame(main_work.act[5], 0f);
			AoActSetFrame(main_work.act[6], 0f);
		}
		else if (main_work.cur_disp_page < 10)
		{
			AoActSetFrame(main_work.act[5], 0f);
			AoActSetFrame(main_work.act[6], (float)main_work.cur_disp_page + 1f);
		}
		else
		{
			AoActSetFrame(main_work.act[5], num);
			AoActSetFrame(main_work.act[6], num2 + 1f);
		}
		AoActSetFrame(main_work.act[8], 0f);
		AoActSetFrame(main_work.act[9], 0f);
		AoActSetTexture(AoTexGetTexList(dm_manual_tex[0]));
		for (int l = 5; l < 10; l++)
		{
			AoActUpdate(main_work.act[l], 0f);
		}
		for (int m = 10; m <= 11; m++)
		{
			AoActUpdate(main_work.act[m], 1f);
		}
		for (int n = 12; n <= 13; n++)
		{
			float frame = ((2f <= main_work.act[n].frame) ? 1f : 0f);
			AoActUpdate(main_work.act[n], frame);
		}
		for (int num3 = 0; num3 < main_work.trg_btn.Length; num3++)
		{
			main_work.trg_btn[num3].Update();
		}
		main_work.trg_return.Update();
		AoActSetTexture(AoTexGetTexList(dm_manual_tex[1]));
		for (int num4 = 119; num4 < 120; num4++)
		{
			float frame2 = ((2f <= main_work.act[num4].frame) ? 1f : 0f);
			AoActUpdate(main_work.act[num4], frame2);
		}
		for (int num5 = 120; num5 <= 120; num5++)
		{
			AoActUpdate(main_work.act[num5], 0f);
		}
		AoActSortExecute();
		AoActSortDraw();
		AoActSortUnregAll();
	}

