	private static int dmManualIsTexLoad()
	{
		for (int i = 0; i < 2; i++)
		{
			if (!AoTexIsLoaded(dm_manual_tex[i]))
			{
				return 0;
			}
		}
		return 1;
	}

	private static int dmManualIsTexRelease()
	{
		for (int i = 0; i < 2; i++)
		{
			if (!AoTexIsReleased(dm_manual_tex[i]))
			{
				return 0;
			}
		}
		return 1;
	}

