	private static int ObjSpdUpSet(int lSpd, int sSpd, int sMaxSpd)
	{
		lSpd += FX_Mul(sSpd, g_obj.speed);
		if (sMaxSpd == 0)
		{
			return lSpd;
		}
		if (sSpd >= 0)
		{
			if (lSpd > sMaxSpd)
			{
				lSpd = sMaxSpd;
			}
		}
		else if (lSpd < -sMaxSpd)
		{
			lSpd = -sMaxSpd;
		}
		return lSpd;
	}

	private static int ObjSpdDownSet(int lSpd, int sSpd)
	{
		if (lSpd > 0)
		{
			lSpd -= FX_Mul(sSpd, g_obj.speed);
			if (lSpd < 0)
			{
				lSpd = 0;
			}
		}
		else
		{
			lSpd += FX_Mul(sSpd, g_obj.speed);
			if (lSpd > 0)
			{
				lSpd = 0;
			}
		}
		return lSpd;
	}

	private static int ObjShiftSet(int lPos, int sTag, ushort usShift, int usMax, int usMin)
	{
		if (lPos == sTag)
		{
			return lPos;
		}
		if (usMin == 0)
		{
			usMin = 1;
		}
		int num = sTag - lPos >> (int)usShift;
		if (usMax != 0)
		{
			if (num > usMax)
			{
				num = usMax;
			}
			if (num < -usMax)
			{
				num = -usMax;
			}
		}
		if (usMin != 0)
		{
			if (num > 0)
			{
				if (num < usMin)
				{
					num = usMin;
				}
			}
			else if (num < 0)
			{
				if (num > -usMin)
				{
					num = -usMin;
				}
			}
			else
			{
				if (sTag - lPos > 0 && num < usMin)
				{
					num = usMin;
				}
				if (sTag - lPos < 0 && num > -usMin)
				{
					num = -usMin;
				}
			}
		}
		lPos += num;
		if (num > 0)
		{
			if (lPos > sTag)
			{
				lPos = sTag;
			}
		}
		else if (num < 0 && lPos < sTag)
		{
			lPos = sTag;
		}
		return lPos;
	}

	private static int ObjDiffSet(int lPos, int sTag, int sSrc, ushort usShift, int usMax, int usMin)
	{
		if (lPos == sTag)
		{
			return lPos;
		}
		if (usMin == 0)
		{
			usMin = 1;
		}
		int num = lPos - sSrc;
		num >>= (int)usShift;
		if (sTag > sSrc && num < 0)
		{
			num = 0;
		}
		if (sTag < sSrc && num > 0)
		{
			num = 0;
		}
		if (usMax != 0)
		{
			if (num > usMax)
			{
				num = usMax;
			}
			if (num < -usMax)
			{
				num = -usMax;
			}
		}
		if (usMin != 0)
		{
			if (num > 0)
			{
				if (num < usMin)
				{
					num = usMin;
				}
			}
			else if (num < 0)
			{
				if (num > -usMin)
				{
					num = -usMin;
				}
			}
			else
			{
				if (sTag - lPos > 0 && num < usMin)
				{
					num = usMin;
				}
				if (sTag - lPos < 0 && num > -usMin)
				{
					num = -usMin;
				}
			}
		}
		lPos += num;
		if (num > 0)
		{
			if (lPos > sTag)
			{
				lPos = sTag;
			}
		}
		else if (num < 0 && lPos < sTag)
		{
			lPos = sTag;
		}
		return lPos;
	}

	private static int ObjAlphaSet(int sTag, int sSrc, ushort usAlpha)
	{
		switch (usAlpha)
		{
		case 0:
			return sSrc;
		case 4096:
			return sTag;
		default:
		{
			int num = FX_Mul(sTag - sSrc, usAlpha);
			return sSrc + num;
		}
		}
	}

	private static byte ObjRoopMove8(byte ucDir, byte ucTag, sbyte cSpd)
	{
		if (ucTag == ucDir)
		{
			return ucTag;
		}
		byte b = (byte)Math.Abs(ucDir - ucTag);
		byte b2 = ((ucDir <= ucTag) ? ((byte)(256 - ucTag + ucDir)) : ((byte)(256 - ucDir + ucTag)));
		if (b <= b2)
		{
			if (ucDir > ucTag)
			{
				ucDir = ((ucTag <= ucDir - cSpd) ? ((byte)(ucDir - (byte)cSpd)) : ucTag);
			}
			else if (ucDir < ucTag)
			{
				ucDir = ((ucTag >= ucDir + cSpd) ? ((byte)(ucDir + (byte)cSpd)) : ucTag);
			}
		}
		else if (ucDir > ucTag)
		{
			ucDir = ((ucTag + 256 >= ucDir + cSpd) ? ((byte)(ucDir + (byte)cSpd)) : ucTag);
		}
		else if (ucDir < ucTag)
		{
			ucDir = ((ucTag <= ucDir - cSpd + 256) ? ((byte)(ucDir - (byte)cSpd)) : ucTag);
		}
		return ucDir;
	}

	private static ushort ObjRoopMove16(ushort ucDir, ushort ucTag, short cSpd)
	{
		if (ucTag == ucDir)
		{
			return ucTag;
		}
		ushort num = (ushort)Math.Abs(ucDir - ucTag);
		ushort num2 = ((ucDir <= ucTag) ? ((ushort)(65536 - ucTag + ucDir)) : ((ushort)(65536 - ucDir + ucTag)));
		if (num <= num2)
		{
			if (ucDir > ucTag)
			{
				ucDir = ((ucTag <= ucDir - cSpd) ? ((ushort)(ucDir - (ushort)cSpd)) : ucTag);
			}
			else if (ucDir < ucTag)
			{
				ucDir = ((ucTag >= ucDir + cSpd) ? ((ushort)(ucDir + (ushort)cSpd)) : ucTag);
			}
		}
		else if (ucDir > ucTag)
		{
			ucDir = ((ucTag + 65536 >= ucDir + cSpd) ? ((ushort)(ucDir + (ushort)cSpd)) : ucTag);
		}
		else if (ucDir < ucTag)
		{
			ucDir = ((ucTag <= ucDir - cSpd + 65536) ? ((ushort)(ucDir - (ushort)cSpd)) : ucTag);
		}
