	}

	private static short ObjRoopDiff16(ushort usDir1, ushort usDir2)
	{
		if (usDir2 == usDir1)
		{
			return 0;
		}
		short num = (short)(usDir1 - usDir2);
		short num2 = ((usDir1 <= usDir2) ? ((short)(65536 - usDir2 + usDir1)) : ((short)(65536 - usDir1 + usDir2)));
		if (Math.Abs(num) > Math.Abs(num2))
		{
			return num2;
		}
		return num;
	}

	private static int ObjSwingEndMove(OBS_OBJECT_WORK pWork, int lSwingWork, int sSpdAdd, int sSpdDow, int sSpdMax)
	{
		if (Math.Abs(lSwingWork) < 4096 && Math.Abs(pWork.spd_m) < 2048)
		{
			lSwingWork = 0;
			pWork.spd_m = 0;
		}
		else
		{
			if (lSwingWork < 0)
			{
				if (pWork.spd_m > 0)
				{
					pWork.spd_m = ObjSpdDownSet(pWork.spd_m, sSpdDow);
				}
				pWork.spd_m = ObjSpdUpSet(pWork.spd_m, -sSpdAdd, sSpdMax);
			}
			else
			{
				if (pWork.spd_m < 0)
				{
					pWork.spd_m = ObjSpdDownSet(pWork.spd_m, sSpdDow);
				}
				pWork.spd_m = ObjSpdUpSet(pWork.spd_m, sSpdAdd, sSpdMax);
			}
			lSwingWork -= pWork.spd_m;
			pWork.dir.z = (ushort)(lSwingWork & 0xFFFF);
		}
		return lSwingWork;
	}

	private static void ObjNumCodeSet(ref uint pNum, uint sNum, uint ulMax)
	{
		uint num = 0u;
		short num2 = 0;
		short num3 = 0;
		uint num4 = 0u;
		uint num5 = 0u;
		if (sNum >= ulMax)
		{
			sNum = ((ulMax != 0) ? (ulMax - 1) : 0u);
		}
		pNum = 0u;
		if (ulMax >= 100)
		{
			ulMax = (uint)FX_DivS32((int)ulMax, 10);
			num2 = 0;
			while (true)
			{
				if (sNum >= ulMax)
				{
					num = (uint)FX_DivS32((int)sNum, (int)ulMax);
					pNum |= num << (int)num2;
					sNum -= num * ulMax;
				}
				num2 += 4;
				if (ulMax <= 10)
				{
					break;
				}
				ulMax = (uint)FX_DivS32((int)ulMax, 10);
			}
		}
		pNum |= sNum << (int)num2;
		num3 = num2;
		while (num2 >= num3 >> 1)
		{
			num5 = 0u;
			num4 = (uint)((pNum & (15 << num3 - num2)) >> num3 - num2 << (int)num2);
			num5 = (uint)((pNum & (15 << (int)num2)) >> (int)num2 << num3 - num2);
			pNum &= (uint)(~((15 << num3 - num2) | (15 << (int)num2)));
			pNum |= num4 | num5;
			num2 -= 4;
		}
	}

