	private static ushort ObjTouchCheck(OBS_OBJECT_WORK pWork, OBS_RECT_WORK pRect)
	{
		if (amTpIsTouchOn(0))
		{
			pRect.parent_obj = pWork;
			int num;
			int num2;
			if (g_obj.camera[0][1] > g_obj.camera[1][1])
			{
				num = g_obj.camera[0][0] >> 12;
				num2 = g_obj.camera[0][1] >> 12;
			}
			else
			{
				num = g_obj.camera[1][0] >> 12;
				num2 = g_obj.camera[1][1] >> 12;
			}
			return ObjRectWorkPointCheck(pRect, (int)((float)(_am_tp_touch[0].on[0] * OBD_LCD_X) / AMD_DISPLAY_WIDTH + (float)num), (int)((float)(_am_tp_touch[0].on[1] * OBD_LCD_Y) / AMD_DISPLAY_HEIGHT + (float)num2), 0);
		}
		return 0;
	}

	private static ushort ObjTouchCheckPush(OBS_OBJECT_WORK pWork, OBS_RECT_WORK pRect)
	{
		if (amTpIsTouchPush(0))
		{
			pRect.parent_obj = pWork;
			int num;
			int num2;
			if (g_obj.camera[0][1] > g_obj.camera[1][1])
			{
				num = g_obj.camera[0][0] >> 12;
				num2 = g_obj.camera[0][1] >> 12;
			}
			else
			{
				num = g_obj.camera[1][0] >> 12;
				num2 = g_obj.camera[1][1] >> 12;
			}
			return ObjRectWorkPointCheck(pRect, (int)((float)(_am_tp_touch[0].on[0] * OBD_LCD_X) / AMD_DISPLAY_WIDTH + (float)num), (int)((float)(_am_tp_touch[0].on[1] * OBD_LCD_Y) / AMD_DISPLAY_HEIGHT + (float)num2), 0);
		}
		return 0;
	}

	private static void ObjUtilGetRotPosXY(int pos_x, int pos_y, ref int dest_x, ref int dest_y, ushort dir)
	{
		int num = FX_Mul(pos_x, mtMathSin(dir));
		int num2 = FX_Mul(pos_x, mtMathCos(dir));
		int num3 = FX_Mul(pos_y, mtMathSin(dir));
		int num4 = FX_Mul(pos_y, mtMathCos(dir));
		dest_x = num2 - num3;
		dest_y = num + num4;
	}

	private static float ObjSpdUpSetF(float spd, float add_apd, float max_spd)
	{
		spd += add_apd * FXM_FX32_TO_FLOAT(g_obj.speed);
		if (amIsZerof(max_spd))
		{
			return spd;
		}
		if (add_apd >= 0f)
		{
			if (spd > max_spd)
			{
				spd = max_spd;
			}
		}
		else if (spd < 0f - max_spd)
		{
			spd = 0f - max_spd;
		}
		return spd;
	}

	private static float ObjSpdDownSetF(float spd, float spd_dec)
	{
		if (spd > 0f)
		{
			spd -= spd_dec * FXM_FX32_TO_FLOAT(g_obj.speed);
			if (spd < 0f)
			{
				spd = 0f;
			}
		}
		else
		{
			spd += spd_dec * FXM_FX32_TO_FLOAT(g_obj.speed);
			if (spd > 0f)
			{
				spd = 0f;
			}
		}
		return spd;
	}

	private static float ObjShiftSetF(float pos, float tag, int shift, float max, float min)
	{
		if (pos == tag)
		{
			return pos;
		}
		if (0f == min)
		{
			min = 1f;
		}
		float num = (tag - pos) / (float)(1 << shift);
		if (0f != max)
		{
			if (num > max)
			{
				num = max;
			}
			if (num < 0f - max)
			{
				num = 0f - max;
			}
		}
		if (0f != min)
		{
			if (num > 0f)
			{
				if (num < min)
				{
					num = min;
				}
			}
			else if (num < 0f)
			{
				if (num > 0f - min)
				{
					num = 0f - min;
				}
			}
			else
			{
				if (tag - pos > 0f && num < min)
				{
					num = min;
				}
				if (tag - pos < 0f && num > 0f - min)
				{
					num = 0f - min;
				}
			}
		}
		pos += num;
		if (num > 0f)
		{
			if (pos > tag)
			{
				pos = tag;
			}
		}
		else if (num < 0f && pos < tag)
		{
			pos = tag;
		}
		return pos;
	}

