	private static void ObjInit(byte group, ushort prio, byte pause_level, short lcd_size_x, short lcd_size_y, float disp_width, float disp_height)
	{
		if (obj_ptcb != null)
		{
			ObjExit();
		}
		g_obj = new OBS_OBJECT();
		ObjDispSRand(0u);
		g_obj.speed = 4096;
		g_obj.glb_scale.x = 4096;
		g_obj.glb_scale.y = 4096;
		g_obj.glb_scale.z = 4096;
