		{
			g_obj.glb_scale.x = 4096 - (z >> 1);
			g_obj.glb_scale.y = 4096 - (z >> 1);
		}
		else
		{
			g_obj.glb_scale.x = 4096 - z;
			g_obj.glb_scale.y = 4096 - z;
		}
		g_obj.glb_scale.z = 4096;
	}

	private static OBS_OBJECT_WORK ObjObjectTaskInit()
	{
		return OBM_OBJECT_TASK_DETAIL_INIT(4096, 1, 0, 0, () => OBS_OBJECT_WORK.Create(), "object");
	}

	private static OBS_OBJECT_WORK ObjObjectTaskDetailInit(ushort prio, byte group, byte pause_level, byte obj_pause_level, TaskWorkFactoryDelegate work_size, string name)
	{
		MTS_TASK_TCB tcb = MTM_TASK_MAKE_TCB(_ObjObjectMain, _ObjObjectExit, 0u, pause_level, prio, group, work_size, (name == null) ? "" : name);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(tcb);
		oBS_OBJECT_WORK.tcb = tcb;
		oBS_OBJECT_WORK.pause_level = obj_pause_level;
		oBS_OBJECT_WORK.scale.x = 4096;
		oBS_OBJECT_WORK.scale.y = 4096;
		oBS_OBJECT_WORK.scale.z = 4096;
		if ((g_obj.flag & 0x2000) == 0)
		{
			if ((g_obj.flag & 0x4000) != 0)
			{
				oBS_OBJECT_WORK.flag |= 1048576u;
			}
			else
			{
				oBS_OBJECT_WORK.flag |= 2097152u;
			}
		}
		oBS_OBJECT_WORK.ppViewCheck = _ObjObjectViewOutCheck;
		if ((g_obj.flag & 0x10000) != 0)
		{
			oBS_OBJECT_WORK.flag |= 16u;
		}
		oBS_OBJECT_WORK.field_ajst_w_db_f = 2;
		oBS_OBJECT_WORK.field_ajst_w_db_b = 4;
		oBS_OBJECT_WORK.field_ajst_w_dl_f = 2;
		oBS_OBJECT_WORK.field_ajst_w_dl_b = 4;
		oBS_OBJECT_WORK.field_ajst_w_dt_f = 2;
		oBS_OBJECT_WORK.field_ajst_w_dt_b = 4;
		oBS_OBJECT_WORK.field_ajst_w_dr_f = 2;
		oBS_OBJECT_WORK.field_ajst_w_dr_b = 4;
		oBS_OBJECT_WORK.field_ajst_h_db_r = 1;
		oBS_OBJECT_WORK.field_ajst_h_db_l = 1;
		oBS_OBJECT_WORK.field_ajst_h_dl_r = 1;
		oBS_OBJECT_WORK.field_ajst_h_dl_l = 1;
		oBS_OBJECT_WORK.field_ajst_h_dt_r = 1;
		oBS_OBJECT_WORK.field_ajst_h_dt_l = 1;
		oBS_OBJECT_WORK.field_ajst_h_dr_r = 2;
		oBS_OBJECT_WORK.field_ajst_h_dr_l = 2;
		ObjObjectRegistObject(oBS_OBJECT_WORK);
		return oBS_OBJECT_WORK;
	}

	public static void ObjObjectRegistObject(OBS_OBJECT_WORK pWork)
	{
		pWork.prev = g_obj.obj_list_tail;
		pWork.next = null;
		if (pWork.prev != null)
		{
			pWork.prev.next = pWork;
		}
		else
		{
			g_obj.obj_list_head = pWork;
		}
		g_obj.obj_list_tail = pWork;
	}

	private static void ObjObjectRevokeObject(OBS_OBJECT_WORK pWork)
	{
		if (pWork.prev != null)
		{
			pWork.prev.next = pWork.next;
		}
		else
		{
			g_obj.obj_list_head = pWork.next;
		}
		if (pWork.next != null)
		{
			pWork.next.prev = pWork.prev;
		}
		else
		{
			g_obj.obj_list_tail = pWork.prev;
		}
	}

	private static void ObjObjectClearAllObject()
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = g_obj.obj_list_head;
		while (oBS_OBJECT_WORK != null)
		{
			OBS_OBJECT_WORK next = oBS_OBJECT_WORK.next;
			oBS_OBJECT_WORK.flag |= 4u;
			oBS_OBJECT_WORK = next;
		}
	}

	private static bool ObjObjectCheckClearAllObject()
	{
		if (g_obj.obj_list_head != null)
		{
			return false;
		}
		return true;
	}

	private static OBS_OBJECT_WORK ObjObjectSearchRegistObject(OBS_OBJECT_WORK obj_work, ushort obj_type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = ((obj_work != null) ? obj_work.next : g_obj.obj_list_head);
		while (oBS_OBJECT_WORK != null && oBS_OBJECT_WORK.obj_type != obj_type && obj_type != ushort.MaxValue)
		{
			oBS_OBJECT_WORK = oBS_OBJECT_WORK.next;
		}
		return oBS_OBJECT_WORK;
	}

	private static void ObjObjectTypeSet(OBS_OBJECT_WORK pObj, ushort usType)
	{
		pObj.obj_type = usType;
	}

	private static void ObjObjectParentSet(OBS_OBJECT_WORK pObj, OBS_OBJECT_WORK pParent, uint ulFlag)
	{
		pObj.parent_obj = pParent;
		pObj.flag &= 4294963711u;
		pObj.flag |= ulFlag & 0xE00;
	}

	private static object ObjObjecExWorkAlloc(OBS_OBJECT_WORK pObj, uint ulSize)
	{
		if (pObj.ex_work != null)
		{
			pObj.ex_work = null;
		}
		if (ulSize != 0)
		{
			pObj.ex_work = new byte[ulSize];
			pObj.flag |= 8388608u;
		}
		return pObj.ex_work;
	}

	public static void ObjObjectMain(MTS_TASK_TCB tcb)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(tcb);
		if ((oBS_OBJECT_WORK.flag & 4) != 0)
		{
			objObjectExitDataRelease(tcb);
		}
		else if ((oBS_OBJECT_WORK.flag & 8) != 0)
		{
			oBS_OBJECT_WORK.flag |= 4u;
		}
		else if ((oBS_OBJECT_WORK.flag & 0x10) == 0 && oBS_OBJECT_WORK.ppViewCheck != null && oBS_OBJECT_WORK.ppViewCheck(oBS_OBJECT_WORK) != 0)
		{
			oBS_OBJECT_WORK.flag |= 4u;
		}
		else
		{
			if (objObjectParent(oBS_OBJECT_WORK) != 0)
			{
				return;
			}
			if (oBS_OBJECT_WORK.obj_3d != null)
			{
				if (!ObjAction3dNNModelLoadCheck(oBS_OBJECT_WORK.obj_3d) && (oBS_OBJECT_WORK.flag & 0x100) == 0)
				{
					return;
				}
			}
			else if (oBS_OBJECT_WORK.obj_2d != null && !ObjAction2dAMALoadCheck(oBS_OBJECT_WORK.obj_2d) && (oBS_OBJECT_WORK.flag & 0x100) == 0)
			{
				return;
			}
			if (_g_obj.ppObjPre != null)
			{
				_g_obj.ppObjPre(oBS_OBJECT_WORK);
			}
			objObjectColRideTouchCheck(oBS_OBJECT_WORK);
			oBS_OBJECT_WORK.pos.x -= oBS_OBJECT_WORK.prev_temp_ofst.x;
			oBS_OBJECT_WORK.pos.y -= oBS_OBJECT_WORK.prev_temp_ofst.y;
			oBS_OBJECT_WORK.pos.z -= oBS_OBJECT_WORK.prev_temp_ofst.z;
			uint num = ObjObjectPauseCheck(oBS_OBJECT_WORK.flag);
			if ((num == 0 || (oBS_OBJECT_WORK.flag & 0x40) != 0) && oBS_OBJECT_WORK.ppIn != null)
			{
				oBS_OBJECT_WORK.ppIn(oBS_OBJECT_WORK);
			}
			if ((oBS_OBJECT_WORK.disp_flag & 0x20000000) != 0 && (oBS_OBJECT_WORK.flag & 0x40000000) != 0)
			{
				oBS_OBJECT_WORK.flag |= 2147483648u;
				oBS_OBJECT_WORK.disp_flag |= 1073741824u;
			}
			else
			{
				oBS_OBJECT_WORK.flag &= 2147483647u;
				oBS_OBJECT_WORK.disp_flag &= 3221225471u;
			}
			if (num == 0)
			{
				if (oBS_OBJECT_WORK.vib_timer != 0)
				{
					oBS_OBJECT_WORK.vib_timer = ObjTimeCountDown(oBS_OBJECT_WORK.vib_timer);
				}
				if (oBS_OBJECT_WORK.hitstop_timer != 0)
				{
					oBS_OBJECT_WORK.hitstop_timer = ObjTimeCountDown(oBS_OBJECT_WORK.hitstop_timer);
					if ((oBS_OBJECT_WORK.flag & 0x2000) != 0)
					{
						oBS_OBJECT_WORK.hitstop_timer = 0;
					}
				}
				if ((_g_obj.flag & 0x8000) == 0 || oBS_OBJECT_WORK.hitstop_timer == 0)
				{
					if (oBS_OBJECT_WORK.invincible_timer != 0)
					{
						oBS_OBJECT_WORK.invincible_timer = ObjTimeCountDown(oBS_OBJECT_WORK.invincible_timer);
					}
					if ((oBS_OBJECT_WORK.flag & 0x80000080u) == 0 && oBS_OBJECT_WORK.ppFunc != null)
					{
						oBS_OBJECT_WORK.ppFunc(oBS_OBJECT_WORK);
					}
				}
				if ((oBS_OBJECT_WORK.flag & 0x80000000u) == 0)
				{
					if ((oBS_OBJECT_WORK.move_flag & 0x2000) == 0 && oBS_OBJECT_WORK.ppMove != null)
					{
						oBS_OBJECT_WORK.ppMove(oBS_OBJECT_WORK);
					}
					if ((_g_obj.flag & 0x30) != 0 && (oBS_OBJECT_WORK.move_flag & 0x100) == 0 && ((_g_obj.flag & 0x200000) == 0 || oBS_OBJECT_WORK.hitstop_timer == 0))
					{
						if (oBS_OBJECT_WORK.ppCol != null)
						{
							oBS_OBJECT_WORK.ppCol(oBS_OBJECT_WORK);
						}
						else if (_g_obj.ppCollision != null)
						{
							_g_obj.ppCollision(oBS_OBJECT_WORK);
						}
					}
				}
			}
			oBS_OBJECT_WORK.pos.x += oBS_OBJECT_WORK.temp_ofst.x;
			oBS_OBJECT_WORK.pos.y += oBS_OBJECT_WORK.temp_ofst.y;
			oBS_OBJECT_WORK.pos.z += oBS_OBJECT_WORK.temp_ofst.z;
			oBS_OBJECT_WORK.prev_temp_ofst.x = oBS_OBJECT_WORK.temp_ofst.x;
			oBS_OBJECT_WORK.prev_temp_ofst.y = oBS_OBJECT_WORK.temp_ofst.y;
			oBS_OBJECT_WORK.prev_temp_ofst.z = oBS_OBJECT_WORK.temp_ofst.z;
			if ((oBS_OBJECT_WORK.flag & 0x80000000u) == 0)
			{
				if (num == 0 && oBS_OBJECT_WORK.vib_timer != 0 && (oBS_OBJECT_WORK.flag & 0x4000) == 0)
				{
					oBS_OBJECT_WORK.ofst.x += g_object_vib_tbl[(oBS_OBJECT_WORK.vib_timer >> 13) & 0xF];
					oBS_OBJECT_WORK.ofst.y += g_object_vib_tbl[((oBS_OBJECT_WORK.vib_timer >> 13) + 1) & 0xF];
				}
				if ((num == 0 || (oBS_OBJECT_WORK.flag & 0x10000) != 0) && (_g_obj.flag & 0x40) != 0)
				{
					if (oBS_OBJECT_WORK.ppRec != null)
					{
						oBS_OBJECT_WORK.ppRec(oBS_OBJECT_WORK);
					}
					if (_g_obj.ppRegRecAuto != null)
					{
						_g_obj.ppRegRecAuto(oBS_OBJECT_WORK);
					}
				}
				if ((num == 0 || (oBS_OBJECT_WORK.flag & 0x40000) != 0) && oBS_OBJECT_WORK.ppLast != null)
				{
					oBS_OBJECT_WORK.ppLast(oBS_OBJECT_WORK);
				}
			}
			if (_g_obj.ppObjPost != null)
			{
				_g_obj.ppObjPost(oBS_OBJECT_WORK);
			}
		}
	}

	private static void ObjObjectExit(MTS_TASK_TCB pTcb)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(pTcb);
		if (oBS_OBJECT_WORK.obj_3d != null)
		{
			ObjAction3dNNMotionRelease(oBS_OBJECT_WORK.obj_3d);
			if ((oBS_OBJECT_WORK.flag & 0x20000000) == 0)
			{
				if (oBS_OBJECT_WORK.obj_3d._object != null)
				{
					oBS_OBJECT_WORK.obj_3d._object = null;
				}
				if (oBS_OBJECT_WORK.obj_3d.texlistbuf != null)
				{
					oBS_OBJECT_WORK.obj_3d.texlistbuf = null;
				}
			}
		}
		if (oBS_OBJECT_WORK.obj_3des != null)
		{
			if (oBS_OBJECT_WORK.obj_3des._object != null)
			{
				oBS_OBJECT_WORK.obj_3des._object = null;
			}
			if (oBS_OBJECT_WORK.obj_3des.model_data_work != null)
			{
				ObjDataRelease(oBS_OBJECT_WORK.obj_3des.model_data_work);
				oBS_OBJECT_WORK.obj_3des.model_data_work = null;
			}
			else if (oBS_OBJECT_WORK.obj_3des.model != null)
			{
				uint num = oBS_OBJECT_WORK.obj_3des.flag & 0x40000;
			}
			oBS_OBJECT_WORK.obj_3des.model = null;
			if (oBS_OBJECT_WORK.obj_3des.texlistbuf != null)
			{
				oBS_OBJECT_WORK.obj_3des.texlistbuf = null;
			}
			if (oBS_OBJECT_WORK.obj_3des.ambtex_data_work != null)
			{
				ObjDataRelease(oBS_OBJECT_WORK.obj_3des.ambtex_data_work);
				oBS_OBJECT_WORK.obj_3des.ambtex_data_work = null;
			}
			else if (oBS_OBJECT_WORK.obj_3des.ambtex != null)
			{
				uint num2 = oBS_OBJECT_WORK.obj_3des.flag & 0x20000;
			}
			oBS_OBJECT_WORK.obj_3des.ambtex = null;
			if (oBS_OBJECT_WORK.obj_3des.ecb != null)
			{
				amEffectDelete(oBS_OBJECT_WORK.obj_3des.ecb);
				oBS_OBJECT_WORK.obj_3des.ecb = null;
			}
			if (oBS_OBJECT_WORK.obj_3des.eff_data_work != null)
			{
				ObjDataRelease(oBS_OBJECT_WORK.obj_3des.eff_data_work);
				oBS_OBJECT_WORK.obj_3des.eff_data_work = null;
			}
			else if (oBS_OBJECT_WORK.obj_3des.eff != null)
			{
				uint num3 = oBS_OBJECT_WORK.obj_3des.flag & 0x10000;
			}
			oBS_OBJECT_WORK.obj_3des.eff = null;
		}
		if (oBS_OBJECT_WORK.obj_2d != null && oBS_OBJECT_WORK.obj_2d.act != null)
		{
			AoActDelete(oBS_OBJECT_WORK.obj_2d.act);
			oBS_OBJECT_WORK.obj_2d.act = null;
		}
		if (oBS_OBJECT_WORK.col_work != null)
		{
			if (oBS_OBJECT_WORK.col_work.diff_data_work != null)
			{
				ObjDataRelease(oBS_OBJECT_WORK.col_work.diff_data_work);
			}
			else if (oBS_OBJECT_WORK.col_work.obj_col.diff_data != null)
			{
				uint num4 = oBS_OBJECT_WORK.col_work.obj_col.flag & 0x8000000;
			}
			if (oBS_OBJECT_WORK.col_work.dir_data_work != null)
			{
				ObjDataRelease(oBS_OBJECT_WORK.col_work.dir_data_work);
			}
			else if (oBS_OBJECT_WORK.col_work.obj_col.dir_data != null)
			{
				uint num5 = oBS_OBJECT_WORK.col_work.obj_col.flag & 0x10000000;
			}
			if (oBS_OBJECT_WORK.col_work.attr_data_work != null)
			{
				ObjDataRelease(oBS_OBJECT_WORK.col_work.attr_data_work);
			}
			else if (oBS_OBJECT_WORK.col_work.obj_col.attr_data != null)
			{
				uint num6 = oBS_OBJECT_WORK.col_work.obj_col.flag & 0x20000000;
			}
		}
		if ((oBS_OBJECT_WORK.flag & 0x1F000000) != 0)
		{
			if ((oBS_OBJECT_WORK.flag & 0x8000000) != 0)
			{
				OBS_ACTION3D_NN_WORK obj_3d = oBS_OBJECT_WORK.obj_3d;
			}
			if ((oBS_OBJECT_WORK.flag & 0x10000000) != 0)
			{
				OBS_ACTION3D_ES_WORK obj_3de = oBS_OBJECT_WORK.obj_3des;
			}
			if ((oBS_OBJECT_WORK.flag & 0x4000000) != 0)
			{
				OBS_ACTION2D_AMA_WORK obj_2d = oBS_OBJECT_WORK.obj_2d;
			}
			if ((oBS_OBJECT_WORK.flag & 0x1000000) != 0)
			{
				OBS_COLLISION_WORK col_work = oBS_OBJECT_WORK.col_work;
			}
			if ((oBS_OBJECT_WORK.flag & 0x2000000) != 0)
			{
				bool flag = null != oBS_OBJECT_WORK.rect_work;
			}
		}
		if (oBS_OBJECT_WORK.ex_work != null)
		{
			uint num7 = oBS_OBJECT_WORK.flag & 0x800000;
		}
		ObjObjectRevokeObject(oBS_OBJECT_WORK);
