					pWork.spd.y = pWork.spd_fall_max;
				}
			}
			if ((pWork.move_flag & 0x40) != 0)
			{
				if ((pWork.move_flag & 0x20000) != 0 && (pWork.spd_m != 0 || (pWork.move_flag & 0x40000) == 0))
				{
					int num4 = FX_Mul(pWork.spd_slope, mtMathSin(pWork.dir.z));
					if (num4 != 0)
					{
						pWork.spd_m = ObjSpdUpSet(pWork.spd_m, num4, pWork.spd_slope_max);
					}
					else if (pWork.spd_m > 0)
					{
						if (pWork.spd_m > pWork.spd_slope_max)
						{
							pWork.spd_m = pWork.spd_slope_max;
						}
					}
					else if (pWork.spd_m < -pWork.spd_slope_max)
					{
						pWork.spd_m = -pWork.spd_slope_max;
					}
				}
				if ((pWork.move_flag & 0x8000) == 0)
				{
					num = FX_Mul(pWork.spd_m, mtMathCos(pWork.dir.z));
					num2 = FX_Mul(pWork.spd_m, mtMathSin(pWork.dir.z));
				}
			}
			if ((pWork.move_flag & 0x4000000) != 0)
			{
				pWork.move.x = FX_Mul(pWork.spd.x + num + sSpdX, _g_obj.speed);
				pWork.move.y = FX_Mul(pWork.spd.y + num2 + sSpdY, _g_obj.speed);
			}
			else
			{
				pWork.move.x = FX_Mul(pWork.spd.x + num + sSpdX + _g_obj.scroll[0], _g_obj.speed);
				pWork.move.y = FX_Mul(pWork.spd.y + num2 + sSpdY + _g_obj.scroll[1], _g_obj.speed);
			}
			pWork.move.z = FX_Mul(pWork.spd.z + num3 + pWork.flow.z, _g_obj.speed);
			ObjObjectSpdDirFall(ref pWork.move.x, ref pWork.move.y, pWork.dir_fall);
		}
		pWork.pos.x += pWork.move.x;
		pWork.pos.y += pWork.move.y;
		pWork.pos.z += pWork.move.z;
		pWork.spd.x += pWork.spd_add.x;
		pWork.spd.y += pWork.spd_add.y;
		pWork.spd.z += pWork.spd_add.z;
		pWork.flow.x = 0;
		pWork.flow.y = 0;
		pWork.flow.z = 0;
	}

	private static void objObjectColRideTouchCheck(OBS_OBJECT_WORK pWork)
	{
		if (pWork.col_work != null)
		{
			if (pWork.col_work.obj_col.rider_obj != null && (pWork.col_work.obj_col.rider_obj.flag & 4) != 0)
			{
				pWork.col_work.obj_col.rider_obj = null;
			}
			if (pWork.col_work.obj_col.toucher_obj != null && pWork.col_work.obj_col.toucher_obj != pWork.col_work.obj_col.rider_obj && pWork.col_work.obj_col.toucher_obj != null)
			{
				if (ObjObjectPauseCheck(pWork.flag) == 0 && pWork.col_work.obj_col.toucher_obj != pWork.col_work.obj_col.rider_obj && (pWork.col_work.obj_col.toucher_obj.move_flag & 0x1000000) != 0 && (pWork.move_flag & 0x2000000) != 0)
				{
					int x = pWork.col_work.obj_col.toucher_obj.move.x;
					x = MTM_MATH_CLIP(x, -pWork.col_work.obj_col.toucher_obj.push_max, pWork.col_work.obj_col.toucher_obj.push_max);
					x = MTM_MATH_CLIP(x, -pWork.push_max, pWork.push_max);
					pWork.flow.x += x;
				}
				if ((pWork.col_work.obj_col.toucher_obj.flag & 4) != 0)
				{
					pWork.col_work.obj_col.toucher_obj = null;
				}
			}
		}
		if (pWork.touch_obj != null)
		{
			if (ObjObjectPauseCheck(pWork.flag) == 0 && (pWork.touch_obj.move_flag & 0x2000000) != 0 && (pWork.move_flag & 0x1000000) != 0)
			{
				pWork.flow.x += (short)(pWork.touch_obj.pos.x - pWork.touch_obj.prev_pos.x);
				if ((pWork.touch_obj.move.x & 0xFFF) != 0)
				{
					if (pWork.touch_obj.move.x > 0)
					{
						pWork.flow.x += 4096 - (pWork.touch_obj.move.x & 0xFFF);
					}
					else
					{
						pWork.flow.x -= 4096 + (pWork.touch_obj.move.x & 0xFFF);
					}
				}
			}
			if ((pWork.touch_obj.flag & 4) != 0)
			{
				pWork.touch_obj = null;
			}
		}
		if (pWork.ride_obj == null)
		{
			return;
		}
		if ((pWork.ride_obj.flag & 4) != 0)
		{
			pWork.ride_obj = null;
		}
		else if (ObjObjectPauseCheck(pWork.flag) == 0)
		{
			if ((pWork.ride_obj.move_flag & 0x100) != 0)
			{
				pWork.flow.x += pWork.ride_obj.move.x;
				pWork.flow.y += pWork.ride_obj.move.y;
				pWork.flow.z += pWork.ride_obj.move.z;
			}
			else
			{
				pWork.flow.x += (short)(pWork.ride_obj.pos.x - pWork.ride_obj.prev_pos.x);
				pWork.flow.y += (short)(pWork.ride_obj.pos.y - pWork.ride_obj.prev_pos.y);
				pWork.flow.z += (short)(pWork.ride_obj.pos.z - pWork.ride_obj.prev_pos.z);
			}
			if ((pWork.ride_obj.move.y & 0xFFF) != 0)
			{
				pWork.flow.y += 4096 - (pWork.ride_obj.move.y & 0xFFF);
			}
		}
	}

	private static void ObjObjectFieldRectSet(OBS_OBJECT_WORK pObj, short cLeft, short cTop, short cRight, short cBottom)
	{
		pObj.field_rect[0] = cLeft;
		pObj.field_rect[1] = cTop;
		pObj.field_rect[2] = cRight;
		pObj.field_rect[3] = cBottom;
		pObj.move_flag &= 4294967039u;
	}

	private static void ObjObjectFallSet(OBS_OBJECT_WORK pObj, int fSpdFall, int fSpdFallMax)
	{
		pObj.spd_fall = fSpdFall;
		pObj.spd_fall_max = fSpdFallMax;
		pObj.move_flag |= 128u;
	}

	private void nnCalcNodeMatrixNode(NNS_MATRIX mtx, NNS_OBJECT obj, int nodeidx)
	{
		NNS_NODE nNS_NODE = obj.pNodeList[nodeidx];
		if (nNS_NODE.iParent != -1)
		{
			nnCalcNodeMatrixNode(mtx, obj, nNS_NODE.iParent);
		}
		if ((nNS_NODE.fType & 1) == 0)
		{
			if ((nNS_NODE.fType & 0x2000) != 0)
			{
				nnTranslateMatrixFast(mtx, nNS_NODE.Translation.x, nNS_NODE.Translation.y, nNS_NODE.Translation.z);
			}
			else
			{
				NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
				nnTransformVector(nNS_VECTOR, nncalcnodematrix.nnsBaseMtx, nNS_NODE.Translation);
				nnCopyVectorMatrixTranslation(mtx, nNS_VECTOR);
			}
		}
		if ((nNS_NODE.fType & 0x1000) != 0)
		{
			nnCopyMatrix33(mtx, nncalcnodematrix.nnsBaseMtx);
		}
		else if ((nNS_NODE.fType & 0x1C0000) != 0)
		{
			if ((nNS_NODE.fType & 0x40000) != 0)
			{
				nnNormalizeColumn0(mtx);
			}
			if ((nNS_NODE.fType & 0x80000) != 0)
			{
				nnNormalizeColumn1(mtx);
			}
			if ((nNS_NODE.fType & 0x100000) != 0)
			{
				nnNormalizeColumn2(mtx);
			}
		}
		if ((nNS_NODE.fType & 2) == 0)
		{
			switch (nNS_NODE.fType & 0xF00)
			{
			case 0u:
				nnRotateXYZMatrixFast(mtx, nNS_NODE.Rotation.x, nNS_NODE.Rotation.y, nNS_NODE.Rotation.z);
				break;
			case 256u:
				nnRotateXZYMatrixFast(mtx, nNS_NODE.Rotation.x, nNS_NODE.Rotation.y, nNS_NODE.Rotation.z);
				break;
			case 1024u:
				nnRotateZXYMatrixFast(mtx, nNS_NODE.Rotation.x, nNS_NODE.Rotation.y, nNS_NODE.Rotation.z);
				break;
			default:
				nnRotateXYZMatrixFast(mtx, nNS_NODE.Rotation.x, nNS_NODE.Rotation.y, nNS_NODE.Rotation.z);
				break;
			}
		}
		if ((nNS_NODE.fType & 4) == 0)
		{
			nnScaleMatrixFast(mtx, nNS_NODE.Scaling.x, nNS_NODE.Scaling.y, nNS_NODE.Scaling.z);
		}
	}

	private void nnCalcNodeMatrix(NNS_MATRIX mtx, NNS_OBJECT obj, int nodeidx, NNS_MATRIX basemtx)
	{
		if (basemtx != null)
		{
			nncalcnodematrix.nnsBaseMtx = basemtx;
		}
		else
		{
			nncalcnodematrix.nnsBaseMtx = nngUnitMatrix;
		}
		nnCopyMatrix(mtx, nncalcnodematrix.nnsBaseMtx);
		nnCalcNodeMatrixNode(mtx, obj, nodeidx);
	}

