				NNS_MATERIAL_GLES11_TEXMAP_DESC[] pTexDesc8 = nNS_MATERIAL_GLES11_DESC3.pTexDesc;
				while (num > 0 && (~arrayPointer).Id0 < i)
				{
					++arrayPointer;
					num--;
				}
				while (num > 0 && (~arrayPointer).Id0 == i)
				{
					switch ((~arrayPointer).fType & 0xFFFFFF00u)
					{
					case 512u:
						nnInterpolateFloat(ref pColor8.Diffuse.r, arrayPointer, frame);
						break;
					case 1024u:
						nnInterpolateFloat(ref pColor8.Diffuse.g, arrayPointer, frame);
						break;
					case 2048u:
						nnInterpolateFloat(ref pColor8.Diffuse.b, arrayPointer, frame);
						break;
					case 3584u:
						nnInterpolateFloat3(ref pColor8.Diffuse, arrayPointer, frame);
						break;
					case 4096u:
						nnInterpolateFloat(ref pColor8.Diffuse.a, arrayPointer, frame);
						break;
					case 8192u:
						nnInterpolateFloat(ref pColor8.Specular.r, arrayPointer, frame);
						break;
					case 16384u:
						nnInterpolateFloat(ref pColor8.Specular.g, arrayPointer, frame);
						break;
					case 32768u:
						nnInterpolateFloat(ref pColor8.Specular.b, arrayPointer, frame);
						break;
					case 57344u:
						nnInterpolateFloat3(ref pColor8.Specular, arrayPointer, frame);
						break;
					case 65536u:
						nnInterpolateFloat(ref pColor8.SpecularIntensity, arrayPointer, frame);
						break;
					case 131072u:
					{
						float val2 = 0f;
						if (nnInterpolateFloat(ref val2, arrayPointer, frame) != 0)
						{
							pColor8.Shininess = nnPow(2.0, 10f * val2 + 2f);
						}
						break;
					}
					case 262144u:
						nnInterpolateFloat(ref pColor8.Ambient.r, arrayPointer, frame);
						break;
					case 524288u:
						nnInterpolateFloat(ref pColor8.Ambient.g, arrayPointer, frame);
						break;
					case 1048576u:
						nnInterpolateFloat(ref pColor8.Ambient.b, arrayPointer, frame);
						break;
					case 1835008u:
						nnInterpolateFloat3(ref pColor8.Ambient, arrayPointer, frame);
						break;
					case 2097152u:
						nnInterpolateSint32(ref pTexDesc8[(~arrayPointer).Id1].iTexIdx, arrayPointer, frame);
						break;
					case 8388608u:
						nnInterpolateFloat(ref pTexDesc8[(~arrayPointer).Id1].Offset.u, arrayPointer, frame);
						break;
					case 16777216u:
						nnInterpolateFloat(ref pTexDesc8[(~arrayPointer).Id1].Offset.v, arrayPointer, frame);
						break;
					case 25165824u:
						nnInterpolateFloat2(pTexDesc8[(~arrayPointer).Id1].Offset, arrayPointer, frame);
						break;
					case 33554432u:
						nnInterpolateUint32(ref nNS_MATERIAL_GLES11_DESC3.User, arrayPointer, frame);
						break;
					}
					++arrayPointer;
					num--;
				}
			}
			else
			{
				if ((fType2 & 1) == 0)
				{
					continue;
				}
				NNS_MATERIAL_DESC nNS_MATERIAL_DESC3 = (NNS_MATERIAL_DESC)mmobj.pMatPtrList[i].pMaterial;
				NNS_MATERIAL_COLOR pColor9 = nNS_MATERIAL_DESC3.pColor;
				NNS_MATERIAL_TEXMAP_DESC[] pTexDesc9 = nNS_MATERIAL_DESC3.pTexDesc;
				while (num > 0 && (~arrayPointer).Id0 < i)
				{
					++arrayPointer;
					num--;
				}
				while (num > 0 && (~arrayPointer).Id0 == i)
				{
					switch ((~arrayPointer).fType & 0xFFFFFF00u)
					{
					case 512u:
						nnInterpolateFloat(ref pColor9.Diffuse.r, arrayPointer, frame);
						break;
					case 1024u:
						nnInterpolateFloat(ref pColor9.Diffuse.g, arrayPointer, frame);
						break;
					case 2048u:
						nnInterpolateFloat(ref pColor9.Diffuse.b, arrayPointer, frame);
						break;
					case 3584u:
						nnInterpolateFloat3(ref pColor9.Diffuse, arrayPointer, frame);
						break;
					case 4096u:
						nnInterpolateFloat(ref pColor9.Diffuse.a, arrayPointer, frame);
						break;
					case 8192u:
						nnInterpolateFloat(ref pColor9.Specular.r, arrayPointer, frame);
						break;
					case 16384u:
						nnInterpolateFloat(ref pColor9.Specular.g, arrayPointer, frame);
						break;
					case 32768u:
						nnInterpolateFloat(ref pColor9.Specular.b, arrayPointer, frame);
						break;
					case 57344u:
						nnInterpolateFloat3(ref pColor9.Specular, arrayPointer, frame);
						break;
					case 65536u:
					{
						float val5 = 0f;
						if (nnInterpolateFloat(ref val5, arrayPointer, frame) != 0)
						{
							pColor9.Specular.r *= val5;
							pColor9.Specular.g *= val5;
							pColor9.Specular.b *= val5;
						}
						break;
					}
					case 131072u:
					{
						float val4 = 0f;
						if (nnInterpolateFloat(ref val4, arrayPointer, frame) != 0)
						{
							pColor9.Shininess = nnPow(2.0, 10f * val4 + 2f);
						}
						break;
					}
					case 262144u:
						nnInterpolateFloat(ref pColor9.Ambient.r, arrayPointer, frame);
						break;
					case 524288u:
						nnInterpolateFloat(ref pColor9.Ambient.g, arrayPointer, frame);
						break;
					case 1048576u:
						nnInterpolateFloat(ref pColor9.Ambient.b, arrayPointer, frame);
						break;
					case 1835008u:
						nnInterpolateFloat3(ref pColor9.Ambient, arrayPointer, frame);
						break;
					case 2097152u:
						nnInterpolateSint32(ref pTexDesc9[(~arrayPointer).Id1].iTexIdx, arrayPointer, frame);
						break;
					case 4194304u:
					{
						float val3 = 0f;
						if (nnInterpolateFloat(ref val3, arrayPointer, frame) != 0)
						{
							pTexDesc9[(~arrayPointer).Id1].EnvColor.r = val3;
							pTexDesc9[(~arrayPointer).Id1].EnvColor.g = val3;
							pTexDesc9[(~arrayPointer).Id1].EnvColor.b = val3;
						}
						break;
					}
					case 8388608u:
						nnInterpolateFloat(ref pTexDesc9[(~arrayPointer).Id1].Offset.u, arrayPointer, frame);
						break;
					case 16777216u:
						nnInterpolateFloat(ref pTexDesc9[(~arrayPointer).Id1].Offset.v, arrayPointer, frame);
						break;
					case 25165824u:
						nnInterpolateFloat2(pTexDesc9[(~arrayPointer).Id1].Offset, arrayPointer, frame);
						break;
					case 33554432u:
						nnInterpolateUint32(ref nNS_MATERIAL_DESC3.User, arrayPointer, frame);
						break;
					}
					++arrayPointer;
					num--;
				}
			}
		}
	}

