	public static void amIPhoneAccelerate(ref Vector3 accel)
	{
		NNS_VECTOR core = _am_iphone_accel_data.core;
		NNS_VECTOR sensor = _am_iphone_accel_data.sensor;
		core.x = accel.X;
		core.y = accel.Y;
		core.z = accel.Z;
		sensor.x = 0f - core.y;
		sensor.y = core.x;
		sensor.z = core.z;
		_am_iphone_accel_data.rot_x = nnArcTan2(0f - sensor.z, 0f - sensor.y);
		_am_iphone_accel_data.rot_z = nnArcTan2(sensor.x, 0f - sensor.y);
	}

