	public static void onTouchEvents()
	{
		// Oculta el pad del motor (salto y cruceta); lo dibuja Sonic4Ep1.DrawPadOverlay con los grises 2013.
		if (gm_fix_tcb != null && gm_fix_tcb.work != null)
		{
			((GMS_FIX_MGR_WORK)gm_fix_tcb.work).flag |= 0x800 | 0x1000;
		}
		// En partida los toques van en coordenadas del juego; en menús (selección de fase, título,
		// opciones, pausa) el contenido de 480 px va centrado, así que se descuenta el margen lateral.
		TouchCollection state = IsStageTouchActive() ? Sonic4Ep1.pInstance.GetGameTouches() : Sonic4Ep1.pInstance.GetMenuTouches();
		for (int i = 0; i < 4; i++)
		{
			touchMarked[i] = false;
		}
		for (int j = 0; j < 4; j++)
		{
			int id = 0;
			TouchLocationState touchLocationState;
			if (j >= state.Count)
			{
				touchLocationState = TouchLocationState.Invalid;
				posVector.X = -1f;
				posVector.Y = -1f;
				int num = 0;
				for (num = 0; num < 4 && touchMarked[num]; num++)
				{
				}
				int num2 = num;
				touchMarked[num2] = true;
			}
			else
			{
				TouchLocation touchLocation = state[j];
				float X = touchLocation.Position.X;
				float Y = touchLocation.Position.Y;
				screen2real(ref X, ref Y);
				posVector.X = X;
				posVector.Y = Y;
				touchLocationState = touchLocation.State;
				id = touchLocation.Id;
				int num2 = amFindTouchIndex(id);
				touchMarked[num2] = true;
			}
			switch (touchLocationState)
			{
			case TouchLocationState.Pressed:
				amIPhoneTouchBegan(ref posVector, j, id);
				break;
			case TouchLocationState.Moved:
				amIPhoneTouchMoved(ref posVector, j, id);
				break;
			case TouchLocationState.Released:
				amIPhoneTouchEnded(j);
				break;
			case TouchLocationState.Invalid:
				amIPhoneTouchCanceled(j);
				break;
			}
		}
	}

