	private static int amFindTouchIndex(int id)
	{
		for (int i = 0; i < 4; i++)
		{
			if (_am_iphone_tp_ctrl_data[i].tpdata.id == id)
			{
				return i;
			}
		}
		for (int j = 0; j < 4; j++)
		{
			if (!touchMarked[j])
			{
				return j;
			}
		}
		return 0;
	}

	private static void amIPhoneTouchBegan(ref Vector2 touch, int i, int id)
	{
		AMS_IPHONE_TP_DATA tpdata = _am_iphone_tp_ctrl_data[i].tpdata;
		tpdata.x = (ushort)touch.X;
		tpdata.y = (ushort)touch.Y;
		tpdata.id = id;
		tpdata.touch = 1;
		tpdata.validity = 1;
	}

	private static void amIPhoneTouchMoved(ref Vector2 touch, int i, int id)
	{
		AMS_IPHONE_TP_DATA tpdata = _am_iphone_tp_ctrl_data[i].tpdata;
		tpdata.x = (ushort)touch.X;
		tpdata.y = (ushort)touch.Y;
		tpdata.id = id;
		tpdata.touch = 1;
		tpdata.validity = 1;
	}

	private static void amIPhoneTouchCanceled()
	{
		for (int i = 0; i < 4; i++)
		{
			_am_iphone_tp_ctrl_data[i].tpdata.touch = 0;
			_am_iphone_tp_ctrl_data[i].tpdata.validity = 0;
		}
	}

	private static void amIPhoneTouchCanceled(int i)
	{
		_am_iphone_tp_ctrl_data[i].tpdata.touch = 0;
		_am_iphone_tp_ctrl_data[i].tpdata.validity = 0;
	}

	private static void amIPhoneTouchEnded(int i)
	{
		_am_iphone_tp_ctrl_data[i].tpdata.touch = 0;
	}

	public static int amTextureLoad(NNS_TEXLIST texlist, NNS_TEXFILELIST texfilelist, string filepath)
	{
		mppAssertNotImpl();
		return amTextureLoad(texlist, texfilelist, filepath, null);
	}

	public static int amTextureLoad(NNS_TEXLIST texlist, NNS_TEXFILELIST texfilelist, string filepath, AMS_AMB_HEADER amb)
	{
		int result = 0;
		ArrayPointer<NNS_TEXINFO> arrayPointer = new ArrayPointer<NNS_TEXINFO>(texlist.pTexInfoList);
		ArrayPointer<NNS_TEXFILE> arrayPointer2 = new ArrayPointer<NNS_TEXFILE>(texfilelist.pTexFileList);
		int num = texfilelist.nTex;
		while (num > 0)
		{
			if (amb == null)
			{
				result = amTextureLoad(arrayPointer, arrayPointer2, filepath, null, 0);
			}
			else
			{
				string text = (~arrayPointer2).Filename;
				int num2 = text.LastIndexOf(".pvr", StringComparison.OrdinalIgnoreCase);
				if (num2 > 0)
				{
					text = text.Remove(num2);
					text += ".PNG";
				}
				num2 = Array.IndexOf(amb.files, text);
				Texture2D texture2D;
				if (amb.buf[num2] != null)
				{
					texture2D = (Texture2D)amb.buf[num2];
				}
				else
				{
					// Textura HD (DDS en Content/HD) si existe con este nombre; si no, la PNG original del AMB.
					texture2D = HdTextures.TryLoadPng(m_game.GraphicsDevice, amb.data, amb.offsets[num2]);
					if (texture2D == null)
					{
						using (MemoryStream stream = new MemoryStream(amb.data, amb.offsets[num2], amb.data.Length - amb.offsets[num2]))
						{
							texture2D = Texture2D.FromStream(m_game.GraphicsDevice, stream);
						}
					}
					amb.buf[num2] = texture2D;
				}
				result = amTextureLoad(arrayPointer, arrayPointer2, filepath, texture2D, 0);
			}
			num--;
			++arrayPointer;
			++arrayPointer2;
		}
		return result;
	}

	public static int amTextureLoad(NNS_TEXINFO texinfo, NNS_TEXFILE texfile, string filepath, Texture2D texbuf, int size)
	{
		AMS_PARAM_LOAD_TEXTURE param = new AMS_PARAM_LOAD_TEXTURE();
		param.pTexInfo = texinfo;
		param.tex = texbuf;
		param.size = (uint)size;
		_amTextureSetupLoadParam(ref param, ref texfile, texbuf);
		return amDrawRegistCommand(1, param);
	}

