	public static void _amTextureSetupLoadParam(ref AMS_PARAM_LOAD_TEXTURE param, ref NNS_TEXFILE texfile, Texture2D texload)
	{
		if ((texfile.fType & 0x200) != 0)
		{
			param.minfilter = 0;
			param.magfilter = 0;
		}
		else
		{
			param.minfilter = texfile.MinFilter;
			param.magfilter = texfile.MagFilter;
		}
		if ((texfile.fType & 0x400) != 0)
		{
			param.globalIndex = texfile.GlobalIndex;
		}
		else
		{
			param.globalIndex = 0u;
		}
		if ((texfile.fType & 0x800) != 0)
		{
			param.bank = texfile.Bank;
		}
		else
		{
			param.bank = 0u;
		}
	}

	public static A2S_AMA_HEADER readAMAFile(string name)
	{
		A2S_AMA_HEADER a2S_AMA_HEADER = null;
		using (Stream input = GameData.OpenStream("Content\\" + name))
		{
			using (BinaryReader br = new BinaryReader(input))
			{
				return readAMAFile(br);
			}
		}
	}

	public static A2S_AMA_HEADER readAMAFile(object data)
	{
		if (data is A2S_AMA_HEADER)
		{
			return (A2S_AMA_HEADER)data;
		}
		AmbChunk ambChunk = (AmbChunk)data;
		return readAMAFile(ambChunk.array, ambChunk.offset);
	}

	public static A2S_AMA_HEADER readAMAFile(byte[] data, int offset)
	{
		A2S_AMA_HEADER a2S_AMA_HEADER = null;
		using (MemoryStream input = new MemoryStream(data, offset, data.Length - offset))
