			}
			foreach (KeyValuePair<int, A2S_SUB_MAT[]> item9 in readAMAFile_submatHash)
			{
				br.BaseStream.Seek(item9.Key, SeekOrigin.Begin);
				A2S_SUB_MAT[] value9 = item9.Value;
				int num11 = item9.Value.Length - 1;
				for (int num12 = 0; num12 < num11; num12++)
