				A2S_SUB_HIT[] value12 = item12.Value;
				int num17 = item12.Value.Length;
				for (int num18 = 0; num18 < num17; num18++)
				{
					value12[num18] = new A2S_SUB_HIT();
					value12[num18].flag = br.ReadUInt32();
					value12[num18].type = br.ReadUInt32();
					value12[num18].hit_accele = br.ReadSingle();
					value12[num18].pad = br.ReadUInt32();
					value12[num18].rect.left = br.ReadSingle();
					value12[num18].rect.top = br.ReadSingle();
					value12[num18].rect.right = br.ReadSingle();
					value12[num18].rect.bottom = br.ReadSingle();
					value12[num18].circle.center_x = value12[num18].rect.left;
					value12[num18].circle.radius = value12[num18].rect.right;
					value12[num18].circle.pad = (uint)value12[num18].rect.bottom;
				}
			}
			foreach (KeyValuePair<int, A2S_SUB_KEY[]> item13 in readAMAFile_subkeyHash)
			{
				br.BaseStream.Seek(item13.Key, SeekOrigin.Begin);
				A2S_SUB_KEY[] value13 = item13.Value;
				int num19 = item13.Value.Length;
				for (int num20 = 0; num20 < num19; num20++)
				{
					value13[num20] = default(A2S_SUB_KEY);
					value13[num20].frm = br.ReadUInt32();
					value13[num20].interpol = br.ReadUInt32();
				}
			}
		}
		readAMAFile_nodeHash.Clear();
		readAMAFile_actHash.Clear();
		readAMAFile_mtnHash.Clear();
		readAMAFile_anmHash.Clear();
		readAMAFile_acmHash.Clear();
		readAMAFile_usrHash.Clear();
		readAMAFile_hitHash.Clear();
		readAMAFile_subtrsHash.Clear();
		readAMAFile_submtnHash.Clear();
		readAMAFile_subanmHash.Clear();
		readAMAFile_submatHash.Clear();
		readAMAFile_subacmHash.Clear();
		readAMAFile_subusrHash.Clear();
