	private static string readChars(BinaryReader br)
	{
		int num = 0;
		while (true)
		{
			char c = br.ReadChar();
			if (c == '\0')
			{
				break;
			}
			readChars_name[num] = c;
			num++;
		}
		return new string(readChars_name, 0, num);
	}

