	}

	private static DF_HEADER readDFFile(AmbChunk data)
	{
		DF_HEADER result = default(DF_HEADER);
		result.block_num = BitConverter.ToUInt32(data.array, data.offset);
		result.blocks = new DF_BLOCK[result.block_num];
		int num = data.offset + 4;
		for (int i = 0; i < result.block_num; i++)
		{
			DF_BLOCK dF_BLOCK = new DF_BLOCK();
			result.blocks[i] = dF_BLOCK;
			for (int j = 0; j < 8; j++)
			{
				for (int k = 0; k < 8; k++)
				{
					dF_BLOCK.df[j, k].Data = data.array;
					dF_BLOCK.df[j, k].Offset = num;
					num += 8;
				}
			}
		}
		return result;
	}

	private static DI_HEADER readDIFile(AmbChunk data)
	{
		DI_HEADER result = default(DI_HEADER);
		using (MemoryStream input = new MemoryStream(data.array, data.offset, data.array.Length - data.offset))
		{
			using (BinaryReader binaryReader = new BinaryReader(input))
			{
				result.block_num = binaryReader.ReadUInt32();
				result.blocks = new DI_BLOCK[result.block_num];
				for (int i = 0; i < result.block_num; i++)
				{
					result.blocks[i] = new DI_BLOCK();
					for (int j = 0; j < 8; j++)
					{
						result.blocks[i].di[j] = binaryReader.ReadBytes(8);
					}
				}
				return result;
			}
		}
	}

	private static AT_HEADER readATFile(AmbChunk data)
	{
		AT_HEADER result = default(AT_HEADER);
		using (MemoryStream input = new MemoryStream(data.array, data.offset, data.array.Length - data.offset))
		{
			using (BinaryReader binaryReader = new BinaryReader(input))
			{
				result.block_num = binaryReader.ReadUInt32();
				result.blocks = new AT_BLOCK[result.block_num];
				for (int i = 0; i < result.block_num; i++)
				{
					result.blocks[i] = new AT_BLOCK();
					for (int j = 0; j < 8; j++)
					{
						result.blocks[i].at[j] = binaryReader.ReadBytes(8);
					}
				}
				return result;
			}
		}
	}

	private static MP_HEADER readMPFile(AmbChunk data)
	{
		if (data.length == 0)
		{
			return null;
		}
		MP_HEADER mP_HEADER = new MP_HEADER();
		using (MemoryStream input = new MemoryStream(data.array, data.offset, data.array.Length - data.offset))
		{
			using (BinaryReader binaryReader = new BinaryReader(input))
			{
				mP_HEADER.map_w = binaryReader.ReadUInt16();
				mP_HEADER.map_h = binaryReader.ReadUInt16();
				int num = mP_HEADER.map_w * mP_HEADER.map_h;
				mP_HEADER.blocks = new MP_BLOCK[num];
				for (int i = 0; i < num; i++)
				{
					mP_HEADER.blocks[i] = new MP_BLOCK(binaryReader.ReadUInt16());
				}
				return mP_HEADER;
			}
		}
	}

	private static DC_HEADER readDCFile(byte[] data)
	{
		DC_HEADER result = default(DC_HEADER);
		mppAssertNotImpl();
		return result;
	}

	private static MD_HEADER readMDFile(AmbChunk data)
	{
		if (data.length == 0)
		{
			return null;
		}
		MD_HEADER mD_HEADER = new MD_HEADER();
		using (MemoryStream input = new MemoryStream(data.array, data.offset, data.array.Length - data.offset))
		{
			using (BinaryReader binaryReader = new BinaryReader(input))
			{
				mD_HEADER.map_w = binaryReader.ReadUInt16();
				mD_HEADER.map_h = binaryReader.ReadUInt16();
				int num = mD_HEADER.map_w * mD_HEADER.map_h;
				mD_HEADER.blocks = new MD_BLOCK[num];
				for (int i = 0; i < num; i++)
				{
					mD_HEADER.blocks[i] = new MD_BLOCK(binaryReader.ReadSByte());
				}
				return mD_HEADER;
			}
		}
	}

