	private static void GmMapBuildColData()
	{
		MP_HEADER mP_HEADER = (MP_HEADER)g_gm_gamedat_map_set[4];
		MP_HEADER mP_HEADER2 = (MP_HEADER)g_gm_gamedat_map_set[5];
		g_gm_main_system.map_fcol.map_block_num_x = mP_HEADER.map_w;
		g_gm_main_system.map_fcol.map_block_num_y = mP_HEADER.map_h;
		g_gm_main_system.map_fcol.block_map_datap[0] = mP_HEADER.blocks;
		g_gm_main_system.map_fcol.block_map_datap[1] = mP_HEADER2.blocks;
		DF_HEADER dF_HEADER = readDFFile((AmbChunk)g_gm_gamedat_map_attr_set[1]);
		DI_HEADER dI_HEADER = readDIFile((AmbChunk)g_gm_gamedat_map_attr_set[2]);
		AT_HEADER aT_HEADER = readATFile((AmbChunk)g_gm_gamedat_map_attr_set[0]);
		if (g_gs_main_sys_info.stage_id == 9)
		{
			for (int i = 0; i < aT_HEADER.block_num; i++)
			{
				for (int j = 0; j < 8; j++)
				{
					for (int k = 0; k < 8; k++)
					{
						aT_HEADER.blocks[i].at[j][k] &= 253;
					}
				}
			}
		}
		g_gm_main_system.map_fcol.diff_block_num = dF_HEADER.block_num;
		g_gm_main_system.map_fcol.dir_block_num = dI_HEADER.block_num;
		g_gm_main_system.map_fcol.attr_block_num = aT_HEADER.block_num;
		g_gm_main_system.map_fcol.cl_diff_datap = dF_HEADER.blocks;
		g_gm_main_system.map_fcol.direc_datap = dI_HEADER.blocks;
		g_gm_main_system.map_fcol.char_attr_datap = aT_HEADER.blocks;
		g_gm_main_system.map_fcol.left = 0;
		g_gm_main_system.map_fcol.top = 0;
		g_gm_main_system.map_fcol.right = g_gm_main_system.map_fcol.map_block_num_x * 64;
		g_gm_main_system.map_fcol.bottom = g_gm_main_system.map_fcol.map_block_num_y * 64;
		g_gm_main_system.map_size[0] = g_gm_main_system.map_fcol.map_block_num_x * 64;
		g_gm_main_system.map_size[1] = g_gm_main_system.map_fcol.map_block_num_y * 64;
	}

