	private static void GmMapInit()
	{
		ObjSetDiffCollision(g_gm_main_system.map_fcol);
		if (g_gs_main_sys_info.stage_id >= 0 && g_gs_main_sys_info.stage_id <= 2)
		{
			gmMapTransX = 1f;
		}
		else
		{
			gmMapTransX = 0f;
		}
		gm_map_tcb = MTM_TASK_MAKE_TCB(gmMapMain, gmMapDest, 0u, 0, 12288u, 5, () => new GMS_MAP_SYS_WORK(), "GM_MAP_MAIN");
		GMS_MAP_SYS_WORK gMS_MAP_SYS_WORK = new GMS_MAP_SYS_WORK();
		gm_map_tcb.work = gMS_MAP_SYS_WORK;
		gm_map_draw_command_state = 0u;
		gm_map_draw_margin_adjust = 0u;
		uint stage_id = g_gs_main_sys_info.stage_id;
		GmMapSetMapDrawSize(1);
		gMS_MAP_SYS_WORK.auto_resize = true;
		switch (stage_id)
		{
		case 0u:
		case 1u:
		case 2u:
		case 4u:
		case 6u:
			GmMapSetMapDrawSize(0);
			gMS_MAP_SYS_WORK.auto_resize = false;
			break;
		case 3u:
		case 7u:
		case 11u:
		case 15u:
		case 16u:
			gMS_MAP_SYS_WORK.auto_resize = false;
			break;
		}
		gmMapCreateUsePrimMatrix();
		uint num = 3772834047u;
		if (stage_id == 0 || stage_id == 1)
		{
			num = uint.MaxValue;
		}
		switch (stage_id)
		{
		case 2u:
		case 3u:
			num = 3767175935u;
			break;
		case 14u:
			num = 1616929023u;
			break;
		}
		gm_map_prim_draw_tvx_color = num;
		gm_map_prim_draw_tvx_alpha_set = null;
		if (stage_id == 4 || stage_id == 5 || stage_id == 6 || stage_id == 7)
		{
			gm_map_prim_draw_tvx_alpha_set = gm_map_prim_draw_tvx_alpha_set_z2;
		}
		gm_map_draw_bgm_timer = GMD_MAP_DRAW_BGM_TIMER;
		GMS_MAP_OTHER_MAP_STATE[] map_state = gMS_MAP_SYS_WORK.map_state;
		for (int num2 = 0; num2 < 5; num2++)
		{
			if (g_gm_gamedat_map_set_add[num2 * 2] != null && g_gm_gamedat_map_set_add[num2 * 2 + 1] != null)
			{
				gMS_MAP_SYS_WORK.flag |= (uint)(1 << num2);
				map_state[num2].pos_z = gm_map_addmap_pos_z_tbl[num2];
				MP_HEADER mP_HEADER = (MP_HEADER)g_gm_gamedat_map_set_add[num2 * 2];
				map_state[num2].map_block_num[0] = mP_HEADER.map_w;
				map_state[num2].map_block_num[1] = mP_HEADER.map_h;
				map_state[num2].map_size[0] = map_state[num2].map_block_num[0] * 64;
				map_state[num2].map_size[1] = map_state[num2].map_block_num[1] * 64;
				map_state[num2].scrl_scale[0] = ((float)map_state[num2].map_size[0] - (float)OBD_LCD_X) / ((float)g_gm_main_system.map_size[0] - (float)OBD_LCD_X);
				map_state[num2].scrl_scale[1] = ((float)map_state[num2].map_size[1] - (float)OBD_LCD_Y) / ((float)g_gm_main_system.map_size[1] - (float)OBD_LCD_Y);
				if (g_gs_main_sys_info.stage_id == 1 || g_gs_main_sys_info.stage_id == 2 || g_gs_main_sys_info.stage_id == 8 || g_gs_main_sys_info.stage_id == 10)
				{
					map_state[num2].command_state = gm_map_addmap_command_state_z1_act2_3_z3_act1_3_tbl[num2];
				}
				else if (g_gs_main_sys_info.stage_id == 16)
				{
					map_state[num2].command_state = gm_map_addmap_command_state_zf_tbl[num2];
				}
				else
				{
					map_state[num2].command_state = gm_map_addmap_command_state_tbl[num2];
				}
			}
		}
		if (g_gs_main_sys_info.stage_id == 9)
		{
			gMS_MAP_SYS_WORK.map_state[2].pos_z = 160f;
