	private static void GmMapDrawMap(OBS_ACTION3D_NN_WORK obj3d_tbl, MP_HEADER mp_header, MD_HEADER md_header, float pos_x, float pos_y, float trans_x, float trans_y, float trans_z, bool loop_h)
	{
		float num = 0f;
		float num2 = 0f;
		int num3 = (int)pos_x >> 6;
		int num4 = (int)pos_y >> 6;
		int num5 = (int)(GMD_MAP_DRAW_WIDTH + 2 + gm_map_draw_margin_adjust * 2);
		int num6 = (int)(GMD_MAP_DRAW_HEIGHT + 2 + gm_map_draw_margin_adjust * 2);
		int num7 = num3 - (num5 >> 1);
		int num8 = num3 + (num5 >> 1);
		int num9 = num4 - (num6 >> 1);
		int num10 = num4 + (num6 >> 1);
		if (num7 < 0)
		{
			if (!loop_h)
			{
				num7 = 0;
			}
			else
			{
				num7 += mp_header.map_w;
				num = -(mp_header.map_w << 6);
			}
		}
		else if (num7 >= mp_header.map_w)
		{
			if (!loop_h)
			{
				num7 = mp_header.map_w - num5;
			}
			else
			{
				num7 -= mp_header.map_w;
				num = mp_header.map_w << 6;
			}
		}
		if (num9 < 0)
		{
			num9 = 0;
		}
		if (num8 >= mp_header.map_w)
		{
			if (!loop_h)
			{
				num8 = mp_header.map_w - 1;
			}
			else
			{
				num8 -= mp_header.map_w;
				num2 = mp_header.map_w << 6;
			}
		}
		else if (num8 < 0)
		{
			if (!loop_h)
			{
				num8 = num5;
			}
			else
			{
				num8 += mp_header.map_w;
				num2 = -(mp_header.map_w << 6);
			}
		}
		if (num10 >= mp_header.map_h)
		{
			num10 = mp_header.map_h - 1;
		}
		if (num7 < num8)
		{
			if (loop_h)
			{
				gmMapDrawMapRange(obj3d_tbl, mp_header, md_header, trans_x + num, trans_y, trans_z, num7, num8, num9, num10);
			}
			else
			{
				gmMapDrawMapRange(obj3d_tbl, mp_header, md_header, trans_x, trans_y, trans_z, num7, num8, num9, num10);
			}
		}
		else
		{
			gmMapDrawMapRange(obj3d_tbl, mp_header, md_header, trans_x + num, trans_y, trans_z, num7, mp_header.map_w - 1, num9, num10);
			gmMapDrawMapRange(obj3d_tbl, mp_header, md_header, trans_x + num2, trans_y, trans_z, 0, num8, num9, num10);
		}
	}

