		}
		dest_disp_pos.x += gMS_MAP_OTHER_MAP_STATE.cam_ofst[0];
		if (0f - main_camera_pos[num7].y <= num5)
		{
			dest_disp_pos.y = 0f - num2;
		}
		else if (0f - main_camera_pos[num7].y >= num6)
		{
			dest_disp_pos.y = 0f - ((float)gMS_MAP_OTHER_MAP_STATE.map_size[1] - num2);
		}
		else
		{
			dest_disp_pos.y = 0f - (num2 + (0f - main_camera_pos[num7].y - num2) * gMS_MAP_OTHER_MAP_STATE.scrl_scale[1]);
		}
		dest_disp_pos.z = main_camera_pos[num7].z;
		num7 = 1;
		if ((gMS_MAP_SYS_WORK.flag & 0x80000000u) == 0)
		{
			if (main_camera_pos[num7].x <= num3)
			{
				dest_target_pos.x = num;
			}
			else if (main_camera_pos[num7].x >= num4)
			{
				dest_target_pos.x = (float)gMS_MAP_OTHER_MAP_STATE.map_size[0] - num;
			}
			else
			{
				dest_target_pos.x = num + (main_camera_pos[num7].x - num) * gMS_MAP_OTHER_MAP_STATE.scrl_scale[0];
			}
		}
		else
