	private static bool GmMapIsDrawEnableMMapBack()
	{
		bool result = true;
		OBS_CAMERA oBS_CAMERA = ObjCameraGet(g_obj.glb_camera_id);
		float x = oBS_CAMERA.disp_pos.x;
		float src = 0f - oBS_CAMERA.disp_pos.y;
		switch (g_gs_main_sys_info.stage_id)
		{
		case 0:
			if (GMM_MAP_IS_RANGE(x, 5450f, 5725f) && GMM_MAP_IS_RANGE(src, 1010f, 1520f))
			{
				result = false;
			}
			else if (GMM_MAP_IS_RANGE(x, 8010f, 8500f) && GMM_MAP_IS_RANGE(src, 1200f, 1650f))
			{
				result = false;
			}
			else if (GMM_MAP_IS_RANGE(x, 10055f, 10695f) && GMM_MAP_IS_RANGE(src, 1025f, 1400f))
			{
				result = false;
			}
			break;
		case 1:
			if (GMM_MAP_IS_RANGE(x, 3975f, 4650f) && GMM_MAP_IS_RANGE(src, 1555f, 2200f))
			{
				result = false;
			}
			else if (x > 12415f)
			{
				result = false;
			}
			break;
		case 16:
			if (x < 2450f)
			{
				result = false;
			}
			else if (GMM_MAP_IS_RANGE(x, 3020f, 5600f))
			{
				result = false;
			}
			else if (GMM_MAP_IS_RANGE(x, 6590f, 9200f))
			{
				result = false;
			}
			break;
		}
		return result;
	}

	private static void GmMapSetLight()
	{
		NNS_RGBA col = new NNS_RGBA(1f, 1f, 1f, 1f);
		NNS_VECTOR nNS_VECTOR = new NNS_VECTOR(1f, 1f, 1f);
		float intensity = 1f;
		if (GMM_MAIN_GET_ZONE_TYPE() == 0)
		{
			nNS_VECTOR.x = -1f;
			nNS_VECTOR.y = -1f;
			nNS_VECTOR.z = -1f;
			col.r = 1f;
			col.g = 1f;
			col.b = 1f;
			col.a = 1f;
			intensity = 1f;
		}
		else if (GMM_MAIN_GET_ZONE_TYPE() == 3)
		{
			nNS_VECTOR.x = -0.2f;
			nNS_VECTOR.y = 0.25f;
			nNS_VECTOR.z = -1f;
			col.r = 1f;
			col.g = 1f;
			col.b = 1f;
			col.a = 1f;
			intensity = ((g_gs_main_sys_info.stage_id != 14) ? 1f : 0.4f);
		}
		nnNormalizeVector(nNS_VECTOR, nNS_VECTOR);
		ObjDrawSetParallelLight(NNE_LIGHT_5, ref col, intensity, nNS_VECTOR);
	}

