	private static void gmMapMain(MTS_TASK_TCB tcb)
	{
		int num = GMM_MAIN_GET_ZONE_TYPE();
		if (num == 5)
		{
			if ((g_gm_main_system.game_flag & 0x10000000) != 0 && --gm_map_draw_bgm_timer <= 0)
			{
				g_gm_main_system.game_flag |= 134217728u;
				g_gm_main_system.game_flag &= 4026531839u;
			}
			return;
		}
		int num2 = 0;
		int num3 = gm_map_add_tbl_use_no[num] + 1;
		GMS_MAP_SYS_WORK gMS_MAP_SYS_WORK = (GMS_MAP_SYS_WORK)tcb.work;
		if ((gMS_MAP_SYS_WORK.flag & 0x8000000) != 0)
		{
			return;
		}
		if (ObjObjectPauseCheck(0u) == 0)
		{
			gmMapUpdateDrawMapTvxTexScroll();
		}
		if (!GmMainIsDrawEnable())
		{
			return;
		}
		if ((g_gm_main_system.game_flag & 0x10000000) != 0 && --gm_map_draw_bgm_timer <= 0)
		{
			g_gm_main_system.game_flag |= 134217728u;
			g_gm_main_system.game_flag &= 4026531839u;
		}
		TVX_FILE[] tvxamb = (TVX_FILE[])g_gm_gamedat_map[1];
		NNS_TEXLIST texlist = AoTexGetTexList(gm_map_texture);
		NNS_MATRIX nNS_MATRIX = gmMapMain_mtx;
		nnMakeUnitMatrix(nNS_MATRIX);
		OBS_CAMERA oBS_CAMERA;
		if (gMS_MAP_SYS_WORK.auto_resize)
		{
			oBS_CAMERA = ObjCameraGet(g_obj.glb_camera_id);
			if ((oBS_CAMERA.roll & 0x3FFFF) != 0)
			{
				GmMapSetMapDrawSize(0);
			}
			else if ((oBS_CAMERA.roll & 0x4000) != 0)
			{
				GmMapSetMapDrawSize(2);
			}
			else
			{
				GmMapSetMapDrawSize(1);
			}
		}
		GMS_MAP_OTHER_MAP_STATE[] map_state = gMS_MAP_SYS_WORK.map_state;
		float x;
		float pos_y;
		MP_HEADER mP_HEADER;
		MD_HEADER mD_HEADER;
		for (int num4 = num3 - 1; num4 >= num2; num4--)
		{
			if ((gMS_MAP_SYS_WORK.flag & (uint)(1 << num4)) != 0 && (num4 < 2 || GmMapIsDrawEnableMMapBack()))
			{
				bool loop_h = false;
				if (num4 != 1 && (gMS_MAP_SYS_WORK.flag & 0x80000000u) != 0)
				{
					loop_h = true;
				}
				ObjDraw3DNNSetCameraEx(gm_map_addmap_camera_tbl[num4], 1, map_state[num4].command_state);
				oBS_CAMERA = ObjCameraGet(gm_map_addmap_camera_tbl[num4]);
				x = oBS_CAMERA.disp_pos.x;
				pos_y = 0f - oBS_CAMERA.disp_pos.y;
				GmMapSetDrawState(map_state[num4].command_state);
				mP_HEADER = (MP_HEADER)g_gm_gamedat_map_set_add[num4 * 2];
				mD_HEADER = (MD_HEADER)g_gm_gamedat_map_set_add[1 + num4 * 2];
				gmMapInitDrawMapTvx();
				gmMapSetDrawMapTvx(tvxamb, mP_HEADER, mD_HEADER, x, pos_y, gmMapTransX, 0f, map_state[num4].pos_z, loop_h, mP_HEADER.blocks[0], mD_HEADER.blocks[0]);
				gmMapExecuteDrawMapTvx(nNS_MATRIX, texlist);
			}
		}
		GmMapSetDrawState(0u);
		ObjDraw3DNNSetCameraEx(g_obj.glb_camera_id, g_obj.glb_camera_type, 0u);
		oBS_CAMERA = ObjCameraGet(g_obj.glb_camera_id);
		x = oBS_CAMERA.disp_pos.x;
		pos_y = 0f - oBS_CAMERA.disp_pos.y;
		gmMapInitDrawMapTvx();
		if ((gMS_MAP_SYS_WORK.flag & 0x10000000) == 0)
		{
			mP_HEADER = (MP_HEADER)g_gm_gamedat_map_set[1];
			mD_HEADER = (MD_HEADER)g_gm_gamedat_map_set[3];
			gmMapSetDrawMapTvx(tvxamb, mP_HEADER, mD_HEADER, x, pos_y, gmMapTransX, 0f, -128f, false, mP_HEADER.blocks[0], mD_HEADER.blocks[0]);
		}
		mP_HEADER = (MP_HEADER)g_gm_gamedat_map_set[0];
		mD_HEADER = (MD_HEADER)g_gm_gamedat_map_set[2];
		gmMapSetDrawMapTvx(tvxamb, mP_HEADER, mD_HEADER, x, pos_y, gmMapTransX, 0f, 128f, false, mP_HEADER.blocks[0], mD_HEADER.blocks[0]);
		gmMapExecuteDrawMapTvx(nNS_MATRIX, texlist);
		if (gm_map_tex_draw_count > 0)
		{
			gm_map_tex_draw_count--;
			ObjLoadInitDraw();
			if (gm_map_tex_draw_count == 0)
			{
