	private static void gmMapCreateUsePrimMatrix()
	{
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		for (int i = 0; i < 4; i++)
		{
			nnMakeUnitMatrix(nNS_MATRIX);
			nnRotateZMatrix(nNS_MATRIX, nNS_MATRIX, i * 16384);
			for (int j = 0; j < 4; j++)
			{
				NNS_MATRIX nNS_MATRIX2 = gm_map_use_prim_mtx[i * 4 + j];
				nnCopyMatrix(nNS_MATRIX2, nNS_MATRIX);
				switch (j)
				{
				case 0:
					nnScaleMatrix(nNS_MATRIX2, nNS_MATRIX2, 1f, 1f, 1f);
					break;
				case 1:
					nnScaleMatrix(nNS_MATRIX2, nNS_MATRIX2, -1f, 1f, 1f);
					break;
				case 2:
					nnScaleMatrix(nNS_MATRIX2, nNS_MATRIX2, 1f, -1f, 1f);
					break;
				case 3:
					nnScaleMatrix(nNS_MATRIX2, nNS_MATRIX2, -1f, -1f, 1f);
					break;
				}
				nnTranslateMatrix(nNS_MATRIX2, nNS_MATRIX2, -32f, -32f, 0f);
			}
		}
	}

	private static NNS_MATRIX gmMapGetUsePrimMatrix(int rot, int flip)
	{
		return gm_map_use_prim_mtx[rot * 4 + flip];
	}

