	private static void gmGmkFlagChangeDefFunc(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		if (match_rect.parent_obj == null || match_rect.parent_obj.obj_type != 1)
		{
			return;
		}
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gMS_PLAYER_WORK;
		switch (gMS_ENEMY_COM_WORK.eve_rec.id)
		{
		case 60:
			if ((gMS_ENEMY_COM_WORK.eve_rec.flag & 0x80) != 0)
			{
				if (gMS_PLAYER_WORK.seq_state != 29 && gMS_PLAYER_WORK.seq_state != 49 && gMS_PLAYER_WORK.seq_state != 50 && gMS_PLAYER_WORK.seq_state != 42)
				{
					break;
				}
				gMS_PLAYER_WORK.gmk_flag |= 2048u;
			}
			if (oBS_OBJECT_WORK.obj_type != 1 || (oBS_OBJECT_WORK.move_flag & 0x10) == 0)
			{
				break;
			}
			gMS_PLAYER_WORK.gmk_flag |= 1u;
			if ((gMS_ENEMY_COM_WORK.eve_rec.flag & 0x10) != 0)
			{
				gMS_PLAYER_WORK.gmk_flag |= 2u;
			}
			else if ((gMS_ENEMY_COM_WORK.eve_rec.flag & 2) != 0)
			{
				if ((gMS_PLAYER_WORK.obj_work.disp_flag & 1) == 0)
				{
					gMS_PLAYER_WORK.gmk_flag |= 33554432u;
				}
			}
			else if ((gMS_ENEMY_COM_WORK.eve_rec.flag & 1) != 0 && (gMS_PLAYER_WORK.obj_work.disp_flag & 1) != 0)
			{
				gMS_PLAYER_WORK.gmk_flag |= 33554432u;
			}
			break;
		case 61:
			oBS_OBJECT_WORK.flag &= 4294967294u;
			if (oBS_OBJECT_WORK.obj_type == 1)
			{
				gMS_PLAYER_WORK.graind_prev_ride = 0;
			}
			break;
		case 62:
			oBS_OBJECT_WORK.flag |= 1u;
			if (oBS_OBJECT_WORK.obj_type == 1)
			{
				gMS_PLAYER_WORK.graind_prev_ride = 0;
			}
			break;
		case 99:
			if (oBS_OBJECT_WORK.obj_type == 1)
			{
				GmPlySeqChangeDeath(gMS_PLAYER_WORK);
			}
			break;
		case 131:
			if (oBS_OBJECT_WORK.obj_type == 1)
			{
				ushort flag = gMS_ENEMY_COM_WORK.eve_rec.flag;
				short num = (short)(flag & 7);
				if ((flag & 8) != 0)
				{
					num = (short)(-num);
				}
				gMS_PLAYER_WORK.gmk_camera_center_ofst_x = (short)(num << 3);
				num = (short)((flag & 0x70) >> 4);
				if ((flag & 0x80) != 0)
				{
					num = (short)(-num);
				}
				gMS_PLAYER_WORK.gmk_camera_center_ofst_y = (short)(num << 3);
			}
			break;
		case 162:
			if (oBS_OBJECT_WORK.obj_type == 1)
			{
				OBS_CAMERA oBS_CAMERA = ObjCameraGet(0);
				oBS_CAMERA.flag |= 2147483648u;
			}
			break;
		case 195:
			if (oBS_OBJECT_WORK.obj_type == 1)
			{
				GmGmkSsOnewayThrough(gMS_ENEMY_COM_WORK.eve_rec.flag);
			}
			break;
		case 276:
			GmEndingPlyNopSet();
			break;
		case 277:
			GmEndingPlyBrakeSet();
			break;
		case 283:
			GmMainDatLoadBossBattleStart(gMS_ENEMY_COM_WORK.eve_rec.flag);
			gMS_ENEMY_COM_WORK.enemy_flag |= 65536u;
			gMS_ENEMY_COM_WORK.obj_work.flag |= 10u;
			break;
		case 286:
			GmGmkPressPillarStartup(gMS_ENEMY_COM_WORK.eve_rec.flag);
			break;
		}
	}

	private static void gmGmkBreakLandStay(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_BLAND_WORK gMS_GMK_BLAND_WORK = (GMS_GMK_BLAND_WORK)obj_work;
		OBS_OBJECT_WORK obj_work2 = g_gm_main_system.ply_work[0].obj_work;
		if (obj_work2.ride_obj != obj_work)
		{
			return;
		}
		int num = obj_work.pos.x + gMS_GMK_BLAND_WORK.colrect_left;
		int num2 = obj_work.pos.x + gMS_GMK_BLAND_WORK.colrect_right;
		num -= obj_work2.field_rect[0] << 12;
		num2 -= obj_work2.field_rect[2] << 12;
		if (num <= obj_work2.pos.x && obj_work2.pos.x <= num2)
		{
			int num3 = obj_work2.pos.x - obj_work.pos.x;
			if (num3 <= gMS_GMK_BLAND_WORK.gmk_work.ene_com.col_work.obj_col.width * 4096 / 2)
			{
				int num4 = -(gMS_GMK_BLAND_WORK.gmk_work.ene_com.col_work.obj_col.width * 4096 / 2);
			}
			OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)GmEfctZoneEsCreate(null, 0, 0);
			oBS_OBJECT_WORK.pos.x = obj_work.pos.x;
			oBS_OBJECT_WORK.pos.y = obj_work.pos.y;
			oBS_OBJECT_WORK.pos.z = obj_work.pos.z + 131072;
			if (gMS_GMK_BLAND_WORK.vect == 0)
			{
				oBS_OBJECT_WORK.pos.x += 262144;
			}
			else
			{
				oBS_OBJECT_WORK.pos.x -= 262144;
			}
			gMS_GMK_BLAND_WORK.broken_timer = 45;
			gMS_GMK_BLAND_WORK.quake_timer = 0;
			obj_work.ppFunc = gmGmkBreakLandStay_100;
		}
	}

	private static void gmGmkBreakLandStay_100(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_BLAND_WORK gMS_GMK_BLAND_WORK = (GMS_GMK_BLAND_WORK)obj_work;
		gMS_GMK_BLAND_WORK.broken_timer--;
		if (gMS_GMK_BLAND_WORK.broken_timer <= 0)
		{
			ObjObjectAction3dNNModelReleaseCopy(obj_work);
			ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_breakland_obj_3d_list[(gMS_GMK_BLAND_WORK.vect == 0) ? 2 : 3], gMS_GMK_BLAND_WORK.gmk_work.obj_3d);
			ObjObjectAction3dNNMotionLoad(obj_work, 0, false, ObjDataGet(796), null, 0, null);
			if (gMS_GMK_BLAND_WORK.vect == 32768)
			{
				ObjDrawObjectActionSet(obj_work, 0);
				obj_work.obj_3d.use_light_flag &= 4294967294u;
				obj_work.obj_3d.use_light_flag |= 4u;
				obj_work.obj_3d.use_light_flag |= 65536u;
			}
			else
			{
				ObjDrawObjectActionSet(obj_work, 1);
				obj_work.obj_3d.use_light_flag &= 4294967294u;
				obj_work.obj_3d.use_light_flag |= 2u;
				obj_work.obj_3d.use_light_flag |= 65536u;
			}
			obj_work.disp_flag &= 4294967279u;
			obj_work.disp_flag &= 4294967291u;
			gMS_GMK_BLAND_WORK.gmk_work.ene_com.col_work.obj_col.obj = null;
			GmSoundPlaySE("BreakGround");
			obj_work.ppFunc = gmGmkBreakLandBroken;
		}
		else
		{
			gMS_GMK_BLAND_WORK.quake_timer &= 3;
			obj_work.pos.y += tbl_breaklandquake[gMS_GMK_BLAND_WORK.quake_timer] * 4096;
			gMS_GMK_BLAND_WORK.quake_timer++;
		}
	}

	private static void gmGmkBreakLandBroken(OBS_OBJECT_WORK obj_work)
	{
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.flag |= 8u;
		}
	}

