	public static OBS_OBJECT_WORK GmGmkAnimalInit(OBS_OBJECT_WORK parent_work, int ofs_x, int ofs_y, int ofs_z, byte type, byte vec, ushort timer)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_EFFECT_3DNN_WORK(), parent_work, 0, "GMK_ANIMAL");
		GMS_EFFECT_3DNN_WORK gMS_EFFECT_3DNN_WORK = (GMS_EFFECT_3DNN_WORK)oBS_OBJECT_WORK;
		oBS_OBJECT_WORK.view_out_ofst = 64;
		oBS_OBJECT_WORK.pos.x += ofs_x;
		oBS_OBJECT_WORK.pos.y += ofs_y;
		oBS_OBJECT_WORK.pos.z = -131072 + ofs_z;
		type = ((type == 0) ? ((byte)(mtMathRand() & 1)) : ((byte)((type - 1) & 1)));
		int num = g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id];
		oBS_OBJECT_WORK.user_work = g_gm_gmk_animal_type_id[num][type];
		oBS_OBJECT_WORK.user_flag = vec;
		oBS_OBJECT_WORK.user_timer = timer;
		gmGmkAnimalObjSet(oBS_OBJECT_WORK, gMS_EFFECT_3DNN_WORK.obj_3d);
		oBS_OBJECT_WORK.move_flag |= 16128u;
		oBS_OBJECT_WORK.move_flag &= 4294967167u;
		oBS_OBJECT_WORK.flag |= 512u;
		oBS_OBJECT_WORK.flag |= 2u;
		oBS_OBJECT_WORK.flag &= 4294967279u;
		oBS_OBJECT_WORK.ppFunc = gmGmkAnimalWait;
		return oBS_OBJECT_WORK;
	}

	private static void gmGmkAnimalObjSet(OBS_OBJECT_WORK obj_work, OBS_ACTION3D_NN_WORK dest_obj_3d)
	{
		ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_animal_obj_3d_list[g_gm_gmk_animal_obj_id[obj_work.user_work][0]], dest_obj_3d);
		ObjObjectFieldRectSet(obj_work, -2, -8, 2, 0);
		obj_work.disp_flag |= 4259840u;
	}

	private static void gmGmkAnimalWait(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.user_timer != 0)
		{
			obj_work.user_timer--;
			return;
		}
		ObjObjectAction3dNNModelReleaseCopy(obj_work);
		ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_animal_obj_3d_list[g_gm_gmk_animal_obj_id[obj_work.user_work][1]], obj_work.obj_3d);
		obj_work.move_flag &= 4294952703u;
		obj_work.move_flag |= 1680u;
		obj_work.spd.y = g_gm_gmk_animal_speed_param[obj_work.user_work].jump;
		obj_work.spd_fall = g_gm_gmk_animal_speed_param[obj_work.user_work].gravity;
		obj_work.pos.z = 131072;
		obj_work.ppFunc = gmGmkAnimalJump;
	}

	private static void gmGmkAnimalJump(OBS_OBJECT_WORK obj_work)
	{
		if ((obj_work.move_flag & 1) != 0)
		{
			if (obj_work.user_flag != 0)
			{
				obj_work.spd.x = g_gm_gmk_animal_speed_param[obj_work.user_work].spd_x;
				ObjObjectAction3dNNModelReleaseCopy(obj_work);
				ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_animal_obj_3d_list[g_gm_gmk_animal_obj_id[obj_work.user_work][2]], obj_work.obj_3d);
				obj_work.dir.y = 45056;
			}
			else
			{
				obj_work.spd.x = -g_gm_gmk_animal_speed_param[obj_work.user_work].spd_x;
				ObjObjectAction3dNNModelReleaseCopy(obj_work);
				ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_animal_obj_3d_list[g_gm_gmk_animal_obj_id[obj_work.user_work][3]], obj_work.obj_3d);
				obj_work.dir.y = 45056;
			}
			obj_work.spd.y = g_gm_gmk_animal_speed_param[obj_work.user_work].jump;
			obj_work.move_flag |= 16u;
			obj_work.disp_flag &= 4290772735u;
		}
	}

	private static void gmGmkEndingAnimalMove(OBS_OBJECT_WORK obj_work)
	{
		if ((obj_work.move_flag & 1) == 0)
		{
			return;
		}
		if ((((GMS_ENEMY_COM_WORK)obj_work).eve_rec.flag & 0x18) == 0 || GmEndingAnimalForwardChk())
		{
			obj_work.spd.x = 0;
			ObjObjectAction3dNNModelReleaseCopy(obj_work);
			ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_animal_obj_3d_list[g_gm_gmk_animal_obj_id[obj_work.user_work][1]], obj_work.obj_3d);
			obj_work.dir.y = 45056;
		}
		else
		{
			obj_work.user_flag = (obj_work.user_flag + 1) & 3;
			if ((obj_work.user_flag & 2) != 0)
			{
				obj_work.spd.x = g_gm_gmk_animal_speed_param[obj_work.user_work].spd_x;
				ObjObjectAction3dNNModelReleaseCopy(obj_work);
				ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_animal_obj_3d_list[g_gm_gmk_animal_obj_id[obj_work.user_work][2]], obj_work.obj_3d);
				obj_work.dir.y = 45056;
			}
			else
			{
				obj_work.spd.x = -g_gm_gmk_animal_speed_param[obj_work.user_work].spd_x;
				ObjObjectAction3dNNModelReleaseCopy(obj_work);
				ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_animal_obj_3d_list[g_gm_gmk_animal_obj_id[obj_work.user_work][3]], obj_work.obj_3d);
				obj_work.dir.y = 45056;
			}
		}
		obj_work.spd.y = g_gm_gmk_animal_speed_param[obj_work.user_work].jump;
		obj_work.move_flag |= 16u;
		obj_work.disp_flag &= 4290772735u;
	}

