	private void DmTitleOpDraw2D()
	{
		if (dm_titleop_mgr_tcb == null)
		{
			return;
		}
		DMS_TITLEOP_MGR_WORK dMS_TITLEOP_MGR_WORK = (DMS_TITLEOP_MGR_WORK)dm_titleop_mgr_tcb.work;
		if ((dMS_TITLEOP_MGR_WORK.flag & 0x80000000u) == 0)
		{
			return;
		}
		AoActSetTexture(AoTexGetTexList(dm_titleop_aos_tex[0]));
		int num = 5;
		for (int i = 0; i < num; i++)
		{
			if ((dMS_TITLEOP_MGR_WORK.flag & (uint)(1 << i)) == 0 || (dMS_TITLEOP_MGR_WORK.flag & (uint)(256 << i)) != 0)
			{
				continue;
			}
			AoActAcmPush();
			AoActAcmInit();
			if (i == 1)
			{
				AoActSetFrame(dMS_TITLEOP_MGR_WORK.act[i], dMS_TITLEOP_MGR_WORK.finger_frame);
				AoActAcmApplyTrans(-10f, -15f, 0f);
				AoActAcmApplyScale(0.9f, 0.9f);
				AoActUpdate(dMS_TITLEOP_MGR_WORK.act[i], 0f);
				dMS_TITLEOP_MGR_WORK.finger_frame += 1f;
				if (dMS_TITLEOP_MGR_WORK.finger_frame > 84f)
				{
					dMS_TITLEOP_MGR_WORK.finger_frame = 60f;
				}
			}
			else
			{
				switch (i)
				{
				case 0:
					AoActAcmApplyTrans(0f, -25f, 0f);
					break;
				case 3:
					AoActAcmApplyTrans(0f, -10f, 0f);
					break;
				}
				AoActAcmApplyScale(0.9f, 0.9f);
				AoActUpdate(dMS_TITLEOP_MGR_WORK.act[i]);
			}
			AoActSortRegAction(dMS_TITLEOP_MGR_WORK.act[i]);
			AoActAcmPop(1u);
		}
	}

