	private static void dmTitleOpLoadPostFuncMapFar(DMS_LOGO_COM_LOAD_CONTEXT context)
	{
		dm_titleop_data[context.no] = context.fs_req;
		AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile(dm_titleop_data[context.no]);
		for (int i = 0; i < aMS_AMB_HEADER.file_num; i++)
		{
			string sPath;
			AmbChunk buf = amBindGet(aMS_AMB_HEADER, i, out sPath);
			AMS_AMB_HEADER aMS_AMB_HEADER2 = readAMBFile(buf);
			aMS_AMB_HEADER2.dir = sPath;
			dm_titleop_mapfar_data[i] = aMS_AMB_HEADER2;
		}
	}

