		context.fs_req = null;
	}

	private void dmTitleOpDataBuildMain(MTS_TASK_TCB tcb)
	{
		bool flag = true;
		AOS_TEXTURE[] array = dm_titleop_aos_tex;
		for (int i = 0; i < 1; i++)
		{
			if (!AoTexIsLoaded(array[i]))
			{
				flag = false;
			}
		}
		if (!GmGameDBuildCheckBuildModel())
		{
			flag = false;
		}
		if (flag)
		{
			mtTaskClearTcb(tcb);
			dm_titleop_build_state = true;
		}
	}

	private void dmTitleOpDataBuildDest(MTS_TASK_TCB tcb)
	{
		dm_titleop_build_tcb = null;
	}

	private void dmTitleOpDataFlushMain(MTS_TASK_TCB tcb)
	{
		bool flag = true;
		AOS_TEXTURE[] array = dm_titleop_aos_tex;
		for (int i = 0; i < 1; i++)
		{
			if (!AoTexIsReleased(array[i]))
			{
				flag = false;
			}
		}
		if (!GmGameDBuildCheckFlushModel())
		{
			flag = false;
		}
		if (flag)
		{
			for (int j = 0; j < dm_titleop_aos_tex.Length; j++)
			{
				dm_titleop_aos_tex[j] = null;
			}
			dm_titleop_aos_tex = null;
			dm_titleop_obj_3d_list = null;
			dm_titleop_water_obj_3d_list = null;
			mtTaskClearTcb(tcb);
			dm_titleop_build_state = false;
		}
	}

	private void dmTitleOpDataFlushDest(MTS_TASK_TCB tcb)
	{
		dm_titleop_flush_tcb = null;
	}

	private void dmTitleOpMgrInit()
	{
		dm_titleop_mgr_tcb = MTM_TASK_MAKE_TCB(dmTitleOpMgrMain, dmTitleOpMgrDest, 0u, ushort.MaxValue, 12288u, 0, () => new DMS_TITLEOP_MGR_WORK(), "DM_TOP_MGR");
		DMS_TITLEOP_MGR_WORK dMS_TITLEOP_MGR_WORK = (DMS_TITLEOP_MGR_WORK)dm_titleop_mgr_tcb.work;
		dMS_TITLEOP_MGR_WORK.Clear();
		dmTitleOpCreateObjFarSky();
		dmTitleOpCreateObjFarRock(0u);
		dmTitleOpCreateObjFarRock(1u);
		dmTitleOpCreateObjFarRock(2u);
		dmTitleOpCreateObjFarSea();
		dmTitleOpCreateAction(dMS_TITLEOP_MGR_WORK);
		dMS_TITLEOP_MGR_WORK.flag |= 268435456u;
		dm_titleop_scrl_x_ofst = 0;
	}

	private void dmTitleOpMgrDest(MTS_TASK_TCB tcb)
	{
		dm_titleop_mgr_tcb = null;
	}

	private void dmTitleOpMgrMain(MTS_TASK_TCB tcb)
	{
		DMS_TITLEOP_MGR_WORK dMS_TITLEOP_MGR_WORK = (DMS_TITLEOP_MGR_WORK)tcb.work;
		if ((dMS_TITLEOP_MGR_WORK.flag & 0x20000000) != 0)
		{
			dmTitleOpEndStart(tcb);
			return;
		}
		dMS_TITLEOP_MGR_WORK.frame++;
		if (dMS_TITLEOP_MGR_WORK.frame == 30)
		{
			dMS_TITLEOP_MGR_WORK.flag |= 111u;
		}
		if (dMS_TITLEOP_MGR_WORK.frame == 75)
		{
			dMS_TITLEOP_MGR_WORK.flag |= 16u;
		}
		else if (dMS_TITLEOP_MGR_WORK.frame >= 105)
		{
			dMS_TITLEOP_MGR_WORK.flag |= 1073741824u;
		}
		if ((dMS_TITLEOP_MGR_WORK.flag & 0x10000000) != 0)
		{
			dm_titleop_scrl_x_ofst += -128;
			int num = dm_titleop_scrl_x_ofst / 3145728;
			dm_titleop_scrl_x_ofst -= num * 3145728;
		}
		ObjDraw3DNNUserFunc(_dmTitleOpPreDrawDT, null, 0, 0u);
		ObjDraw3DNNUserFunc(_dmTitleOpFallShaderPreRenderUserFunc, null, 0, 2u);
		amDrawSetFog(0u, 1);
		amDrawSetFogColor(0u, 0.7f, 0.95f, 1f);
		amDrawSetFogRange(0u, 1f, 500f);
		amDrawSetFog(4u, 0);
	}

	private void dmTitleOpCreateObjFarSky()
	{
		DMS_TITLEOP_OBJ_3DNN_WORK dMS_TITLEOP_OBJ_3DNN_WORK = DMM_TITLEOP_CREATE_3D_OBJ(24576, 0, () => new DMS_TITLEOP_OBJ_3DNN_WORK(), "DM_TOP_SKYT");
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)dMS_TITLEOP_OBJ_3DNN_WORK;
		oBS_OBJECT_WORK.obj_type = 1;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, dm_titleop_obj_3d_list[0], dMS_TITLEOP_OBJ_3DNN_WORK.obj_3d);
