		AMS_RENDER_TARGET targetp = _am_render_manager.targetp;
		targetp = ((targetp != _gm_mapFar_render_work) ? _gm_mapFar_render_work : _am_draw_target);
		if (targetp.width != 0)
		{
			amRenderCopyTarget(targetp, color);
		}
	}

