	private static void aoWinSysDrawPrimitveA(NNS_TEXLIST texlist, uint tex_id, float x, float y, float w, float h)
	{
		NNS_PRIM3D_PCT_ARRAY nNS_PRIM3D_PCT_ARRAY = amDrawAlloc_NNS_PRIM3D_PCT(8);
		NNS_PRIM3D_PCT[] buffer = nNS_PRIM3D_PCT_ARRAY.buffer;
		int offset = nNS_PRIM3D_PCT_ARRAY.offset;
		amDrawPushState();
		amDrawInitState();
		nnSetPrimitive3DAlphaFuncGL(519u, 0.5f);
		nnSetPrimitive3DDepthMaskGL(false);
		nnSetPrimitive3DDepthFuncGL(519u);
		nnSetPrimitiveBlend(1);
		amDrawSetFog(0);
		nnSetPrimitiveTexNum(texlist, (int)tex_id);
		nnSetPrimitiveTexState(0, 0, 1, 1);
		nnBeginDrawPrimitive3D(4, 1, 0, 0);
		aoWinSysMakeVertex00A(nNS_PRIM3D_PCT_ARRAY, x, y, w, h);
		nnDrawPrimitive3D(1, nNS_PRIM3D_PCT_ARRAY, 8);
		aoWinSysMakeVertex01A(nNS_PRIM3D_PCT_ARRAY, x, y, w, h);
		nnDrawPrimitive3D(1, nNS_PRIM3D_PCT_ARRAY, 8);
		aoWinSysMakeVertex02A(nNS_PRIM3D_PCT_ARRAY, x, y, w, h);
		nnDrawPrimitive3D(1, nNS_PRIM3D_PCT_ARRAY, 8);
		nnEndDrawPrimitive3D();
		amDrawPopState();
	}

