	{
		ushort? min2 = min;
		ushort? sec2 = sec;
		ushort? msec2 = msec;
		AkUtilFrame60ToTime(frame, ref min2, ref sec2, ref msec2);
		min = min2.Value;
		sec = sec2.Value;
		msec = msec2.Value;
	}

	public static void AkUtilFrame60ToTime(uint frame, ushort? min, ref ushort sec, ushort? msec)
	{
		ushort? sec2 = sec;
		ushort? min2 = null;
		AkUtilFrame60ToTime(frame, ref min2, ref sec2, ref min2);
		sec = sec2.Value;
	}

	public static void AkUtilFrame60ToTime(uint frame, ref ushort? min)
	{
		ushort? sec = null;
		AkUtilFrame60ToTime(frame, ref min, ref sec, ref sec);
	}

	public static void AkUtilFrame60ToTime(uint frame, ref ushort? min, ref ushort? sec)
	{
		ushort? msec = null;
		AkUtilFrame60ToTime(frame, ref min, ref sec, ref msec);
	}

	public static void AkUtilFrame60ToTime(uint frame, ref ushort? min, ref ushort? sec, ref ushort? msec)
	{
		if (frame > AKD_UTIL_FRAME60_TO_TIME_MAX_FRAME)
		{
			frame = (uint)AKD_UTIL_FRAME60_TO_TIME_MAX_FRAME;
		}
		ushort num = (ushort)((int)frame / 3600);
		frame -= (uint)(num * 60 * 60);
		ushort num2 = (ushort)((int)frame / 60);
		frame -= (uint)(num2 * 60);
		ushort num3 = (ushort)(frame * 433 >> 8);
		if (num3 >= 100)
		{
			num3 = 99;
		}
		if (((int?)min).HasValue)
		{
			min = num;
		}
		if (((int?)sec).HasValue)
		{
			sec = num2;
		}
		if (((int?)msec).HasValue)
		{
			msec = num3;
		}
	}

	public static int AkUtilNumValueToDigits(int val, int[] digit_list, int digit_num)
	{
		return AkUtilNumValueToDigits(val, digit_list, digit_num, 10);
	}

	public static int AkUtilNumValueToDigits(int val, int[] digit_list, int digit_num, int radix)
	{
		int num = val;
		int num2 = 1;
		for (int i = 0; i < digit_num; i++)
		{
			int num3 = num % (num2 * radix);
			digit_list[i] = num3 / num2;
			num -= num3;
			num2 *= radix;
		}
		return num;
	}

	public static int AkUtilNumValueToDigits(int val, ArrayPointer<int> digit_list, int digit_num)
	{
		return AkUtilNumValueToDigits(val, digit_list, digit_num, 10);
	}

	public static int AkUtilNumValueToDigits(int val, ArrayPointer<int> digit_list, int digit_num, int radix)
	{
		int num = val;
		int num2 = 1;
		for (int i = 0; i < digit_num; i++)
		{
			int num3 = num % (num2 * radix);
			digit_list.SetPrimitive(i, num3 / num2);
			num -= num3;
			num2 *= radix;
		}
		return num;
	}

