	private static object ObjDataLoadAmbIndex(OBS_DATA_WORK data_work, int index, AMS_AMB_HEADER amb)
	{
		object obj = null;
		if (data_work != null)
		{
			if (data_work.pData == null)
			{
				if (amb != null)
				{
					string sPath;
					if (amb.buf[index] != null)
					{
						data_work.pData = amb.buf[index];
					}
					else if (amb.files[index].IndexOf(".amb", StringComparison.InvariantCultureIgnoreCase) != -1)
					{
						data_work.pData = readAMBFile(amBindGet(amb, index, out sPath));
						((AMS_AMB_HEADER)data_work.pData).dir = sPath;
					}
					else if (amb.files[index].IndexOf(".ame", StringComparison.InvariantCultureIgnoreCase) != -1)
					{
						data_work.pData = readAMEfile(amBindGet(amb, index, out sPath));
					}
					else if (amb.files[index].IndexOf(".ama", StringComparison.InvariantCultureIgnoreCase) != -1)
					{
						data_work.pData = readAMAFile(amBindGet(amb, index, out sPath));
					}
					else
					{
						data_work.pData = amBindGet(amb, index, out sPath);
					}
					amb.buf[index] = data_work.pData;
					data_work.num = 32768;
					data_work.num++;
				}
			}
			else
			{
				data_work.num++;
			}
			return data_work.pData;
		}
		if (amb != null)
		{
			string sPath2;
			if (amb.buf[index] != null)
			{
				obj = amb.buf[index];
			}
			else if (amb.files[index].IndexOf(".amb", StringComparison.InvariantCultureIgnoreCase) == -1)
			{
				obj = ((amb.files[index].IndexOf(".ame", StringComparison.InvariantCultureIgnoreCase) != -1) ? readAMEfile(amBindGet(amb, index, out sPath2)) : ((amb.files[index].IndexOf(".ama", StringComparison.InvariantCultureIgnoreCase) == -1) ? ((object)amBindGet(amb, index, out sPath2)) : ((object)readAMAFile(amBindGet(amb, index, out sPath2)))));
			}
			else
			{
				obj = readAMBFile(amBindGet(amb, index, out sPath2));
				((AMS_AMB_HEADER)obj).dir = sPath2;
			}
			amb.buf[index] = obj;
		}
		return obj;
	}

	private static object ObjDataSet(OBS_DATA_WORK pWork, object pData)
	{
		pWork.pData = pData;
		pWork.num++;
		return pWork.pData;
	}

	private static object ObjDataGetInc(OBS_DATA_WORK pWork)
	{
		if (pWork.pData != null)
		{
			pWork.num++;
		}
		return pWork.pData;
	}

	private static byte[] ObjDataLoad(OBS_DATA_WORK data_work, string filename, object archive)
	{
		byte[] buf = null;
		sFile = filename;
		if (data_work != null)
		{
			if (data_work.pData == null)
			{
				if (archive != null)
				{
					AmbChunk ambChunk = amBindSearch((AMS_AMB_HEADER)archive, sFile);
					buf = new byte[ambChunk.length];
					Buffer.BlockCopy(ambChunk.array, ambChunk.offset, buf, 0, ambChunk.length);
					data_work.pData = buf;
					data_work.num = 32768;
					data_work.num++;
				}
				else
				{
					byte[] buf2;
					amFsRead(sFile, out buf2);
					data_work.pData = buf2;
					if (data_work.pData != null)
					{
						data_work.num++;
					}
				}
			}
			else
			{
				data_work.num++;
			}
			return (byte[])data_work.pData;
		}
		if (archive != null)
		{
			AmbChunk ambChunk2 = amBindSearch((AMS_AMB_HEADER)archive, sFile);
			buf = new byte[ambChunk2.length];
			Buffer.BlockCopy(ambChunk2.array, ambChunk2.offset, buf, 0, ambChunk2.length);
		}
		else
		{
			amFsRead(sFile, out buf);
		}
		return buf;
	}

	private static void ObjDataRelease(OBS_DATA_WORK pWork)
	{
		if (pWork.num != 0 && pWork.pData != null)
		{
			pWork.num--;
			if (pWork.num == 0)
			{
				pWork.pData = null;
			}
			if (pWork.num == 32768)
			{
				pWork.pData = null;
				pWork.num = 0;
			}
		}
	}

	private static void ObjAction3dNNModelLoad(OBS_ACTION3D_NN_WORK obj_3d, OBS_DATA_WORK data_work, string filename, int index, AMS_AMB_HEADER archive, string filename_tex, AMS_AMB_HEADER amb_tex, uint drawflag)
	{
		object obj = null;
		string filepath = null;
		obj_3d.command_state = 0u;
		obj_3d.marge = 0f;
		obj_3d.per = 1f;
		obj_3d.use_light_flag = g_obj.def_user_light_flag;
		nnMakeUnitMatrix(obj_3d.user_obj_mtx);
		nnMakeUnitMatrix(obj_3d.user_obj_mtx_r);
