	private static void ObjAction3dNNMotionLoad(OBS_ACTION3D_NN_WORK obj_3d, int reg_file_id, bool marge, OBS_DATA_WORK data_work, string filename, int index, AMS_AMB_HEADER archive, int motion_num, int mmotion_num)
	{
		object obj = null;
		if ((obj_3d.flag & 0x40000000) == 0)
		{
			obj_3d.flag |= 536870912u;
			OBS_ACTION3D_MTN_LOAD_SETTING oBS_ACTION3D_MTN_LOAD_SETTING = obj_3d.mtn_load_setting[reg_file_id];
			oBS_ACTION3D_MTN_LOAD_SETTING.enable = true;
			oBS_ACTION3D_MTN_LOAD_SETTING.marge = marge;
			oBS_ACTION3D_MTN_LOAD_SETTING.data_work = data_work;
			oBS_ACTION3D_MTN_LOAD_SETTING.filename = "";
			if (filename != null)
			{
				oBS_ACTION3D_MTN_LOAD_SETTING.filename = filename;
			}
			oBS_ACTION3D_MTN_LOAD_SETTING.index = index;
			oBS_ACTION3D_MTN_LOAD_SETTING.archive = archive;
			return;
		}
		if (archive != null)
		{
			obj_3d.flag |= (uint)(131072 << reg_file_id);
		}
		if (filename != null && filename != "")
		{
			obj = ObjDataLoad(data_work, filename, archive);
			if (archive != null && obj == null)
			{
				obj_3d.flag &= (uint)(~(131072 << reg_file_id));
				obj = ObjDataLoad(data_work, filename, null);
			}
		}
		else if (archive != null)
		{
			obj = ObjDataLoadAmbIndex(data_work, index, archive);
			if (archive != null && obj == null)
			{
				obj_3d.flag &= (uint)(~(131072 << reg_file_id));
			}
		}
		else if (data_work != null)
		{
			obj = ObjDataGetInc(data_work);
		}
		if (obj != null)
		{
			obj_3d.mtn[reg_file_id] = obj;
			if (data_work != null)
			{
				obj_3d.mtn_data_work[reg_file_id] = data_work;
			}
			if (obj_3d.motion == null)
			{
				obj_3d.motion = amMotionCreate(obj_3d._object, motion_num, mmotion_num, marge ? 1 : 0);
			}
			if (obj is AMS_AMB_HEADER || obj is AMS_FS)
			{
				AMS_AMB_HEADER amb = readAMBFile(obj);
				amMotionRegistFile(obj_3d.motion, reg_file_id, amb);
			}
			else
			{
				amMotionRegistFile(obj_3d.motion, reg_file_id, obj);
			}
		}
	}

