	private static bool ObjAction3dNNModelLoadCheck(OBS_ACTION3D_NN_WORK obj_3d)
	{
		if ((obj_3d.flag & 0x80000000u) != 0)
		{
			if (amDrawIsRegistComplete(obj_3d.reg_index))
			{
				obj_3d.flag &= 2147483647u;
				obj_3d.flag |= 1073741824u;
				obj_3d.reg_index = -1;
				if (obj_3d.model_data_work != null)
				{
					ObjDataRelease(obj_3d.model_data_work);
					obj_3d.model_data_work = null;
				}
				else if (obj_3d.model != null && (obj_3d.flag & 0x10000) == 0)
				{
					obj_3d.model = null;
				}
				obj_3d.flag &= 4294901759u;
				obj_3d.model = null;
				if ((obj_3d.flag & 0x20000000) != 0)
				{
					int num = 0;
					ArrayPointer<OBS_ACTION3D_MTN_LOAD_SETTING> arrayPointer = new ArrayPointer<OBS_ACTION3D_MTN_LOAD_SETTING>(obj_3d.mtn_load_setting);
					while (num < 4)
					{
						if ((~arrayPointer).enable)
						{
							ObjAction3dNNMotionLoad(obj_3d, num, (~arrayPointer).marge, (~arrayPointer).data_work, (~arrayPointer).filename, (~arrayPointer).index, (~arrayPointer).archive);
							(~arrayPointer).enable = false;
						}
						num++;
						++arrayPointer;
					}
					obj_3d.flag &= 3758096383u;
				}
				if ((obj_3d.flag & 0x10000000) != 0)
				{
					int num2 = 0;
					ArrayPointer<OBS_ACTION3D_MTN_LOAD_SETTING> arrayPointer2 = new ArrayPointer<OBS_ACTION3D_MTN_LOAD_SETTING>(obj_3d.mat_mtn_load_setting);
					while (num2 < 4)
					{
						if ((~arrayPointer2).enable)
						{
							ObjAction3dNNMaterialMotionLoad(obj_3d, num2, (~arrayPointer2).data_work, (~arrayPointer2).filename, (~arrayPointer2).index, (~arrayPointer2).archive);
							(~arrayPointer2).enable = false;
						}
						num2++;
						++arrayPointer2;
					}
					obj_3d.flag &= 4026531839u;
				}
				return true;
			}
		}
		else if ((obj_3d.flag & 0x40000000) != 0)
		{
			return true;
		}
		return false;
	}

	private static void ObjAction3dNNModelRelease(OBS_ACTION3D_NN_WORK obj_3d)
	{
		obj_3d.reg_index = amObjectRelease(obj_3d._object, obj_3d.texlist);
		obj_3d.flag |= 134217728u;
	}

	private static bool ObjAction3dNNModelReleaseCheck(OBS_ACTION3D_NN_WORK obj_3d)
	{
		if ((obj_3d.flag & 0x48000000) == 0)
		{
			return true;
		}
		if (amDrawIsRegistComplete(obj_3d.reg_index))
		{
			if (obj_3d._object != null)
			{
				obj_3d._object = null;
			}
			if (obj_3d.texlistbuf != null)
			{
				obj_3d.texlistbuf = null;
			}
			obj_3d.flag &= 3087007743u;
			if (obj_3d.model_data_work != null)
			{
				ObjDataRelease(obj_3d.model_data_work);
				obj_3d.model_data_work = null;
			}
			else if (obj_3d.model != null && (obj_3d.flag & 0x10000) == 0)
			{
				obj_3d.model = null;
			}
			obj_3d.flag &= 4294901759u;
			return true;
		}
		return false;
	}

	private static void ObjAction3dNNMotionRelease(OBS_ACTION3D_NN_WORK obj_3d)
	{
		if (obj_3d.motion != null)
		{
			amMotionDelete(obj_3d.motion);
			obj_3d.motion = null;
		}
		for (int i = 0; i < 4; i++)
		{
			if (obj_3d.mtn_data_work[i] != null)
			{
				ObjDataRelease(obj_3d.mtn_data_work[i]);
				obj_3d.mtn_data_work[i] = null;
			}
			else if (obj_3d.mtn[i] != null)
			{
				uint num = obj_3d.flag & (uint)(131072 << i);
			}
			obj_3d.flag &= (uint)(~(131072 << i));
			obj_3d.mtn[i] = null;
			if (obj_3d.mat_mtn_data_work[i] != null)
			{
				ObjDataRelease(obj_3d.mat_mtn_data_work[i]);
				obj_3d.mat_mtn_data_work[i] = null;
			}
			else if (obj_3d.mat_mtn[i] != null)
			{
				uint num2 = obj_3d.flag & (uint)(4096 << i);
			}
			obj_3d.flag &= (uint)(~(4096 << i));
			obj_3d.mat_mtn[i] = null;
		}
	}

