	private static void ObjAction3dESTextureLoad(OBS_ACTION3D_ES_WORK obj_3des, OBS_DATA_WORK data_work, string filename, int index, AMS_AMB_HEADER archive, bool load_tex)
	{
		AMS_AMB_HEADER aMS_AMB_HEADER = null;
		TXB_HEADER tXB_HEADER = null;
		if (archive != null)
		{
			obj_3des.flag |= 131072u;
		}
		if (filename != null && filename != "")
		{
			aMS_AMB_HEADER = readAMBFile(ObjDataLoad(data_work, filename, archive));
			if (archive != null && aMS_AMB_HEADER == null)
			{
				obj_3des.flag &= 4294836223u;
				aMS_AMB_HEADER = readAMBFile(ObjDataLoad(data_work, filename, null));
			}
		}
		else if (archive != null)
		{
			aMS_AMB_HEADER = readAMBFile(ObjDataLoadAmbIndex(data_work, index, archive));
			if (aMS_AMB_HEADER == null)
			{
				obj_3des.flag &= 4294836223u;
			}
		}
		else if (data_work != null)
		{
			aMS_AMB_HEADER = readAMBFile(ObjDataGetInc(data_work));
		}
		if (aMS_AMB_HEADER == null)
		{
			return;
		}
		obj_3des.ambtex = aMS_AMB_HEADER;
		if (data_work != null)
		{
			obj_3des.ambtex_data_work = data_work;
		}
		if (!load_tex)
		{
			return;
		}
		tXB_HEADER = readTXBfile(amBindGet(aMS_AMB_HEADER, 0));
		uint num = amTxbGetCount(tXB_HEADER);
		obj_3des.texlistbuf = null;
		nnSetUpTexlist(out obj_3des.texlist, (int)num, ref obj_3des.texlistbuf);
		if (obj_load_initial_set_flag)
		{
			OBS_LOAD_INITIAL_WORK oBS_LOAD_INITIAL_WORK = obj_load_initial_work;
			if (oBS_LOAD_INITIAL_WORK.es_num < 255)
			{
				oBS_LOAD_INITIAL_WORK.obj_3des[oBS_LOAD_INITIAL_WORK.es_num] = obj_3des;
				oBS_LOAD_INITIAL_WORK.es_num++;
			}
		}
		obj_3des.tex_reg_index = amTextureLoad(obj_3des.texlist, amTxbGetTexFileList(tXB_HEADER), filename, aMS_AMB_HEADER);
		obj_3des.flag |= 1073741824u;
	}

