	private static int ObjAction3dESTextureLoadToDwork(OBS_DATA_WORK texlist_dwork, AMS_AMB_HEADER amb_tex, ref object texlist_buf)
	{
		TXB_HEADER tXB_HEADER = null;
		int result;
		if (texlist_dwork.pData == null)
		{
			tXB_HEADER = readTXBfile(amBindGet(amb_tex, 0));
			uint num = amTxbGetCount(tXB_HEADER);
			texlist_buf = null;
			NNS_TEXLIST texlist;
			nnSetUpTexlist(out texlist, (int)num, ref texlist_buf);
			result = amTextureLoad(texlist, amTxbGetTexFileList(tXB_HEADER), null, amb_tex);
			ObjDataSet(texlist_dwork, texlist);
		}
		else
		{
			ObjDataGetInc(texlist_dwork);
			result = -1;
			texlist_buf = null;
		}
		return result;
	}

