		else if ((ucSuf & 0x80) != 0 && (pColObj.attr & 1) != 0)
		{
			result = 0;
		}
		if ((pColObj.flag & 0x40000000) != 0 && result != 8 && result != 0)
		{
			result = ((result <= 0) ? ((sbyte)(result + 8)) : ((sbyte)(result - 8)));
		}
		if (pDir != null && result != 0)
		{
			ushort num5 = (ushort)((pColObj.dir_data != null) ? ((ushort)(pColObj.dir_data[num3] << 8)) : 0);
			if ((pColObj.flag & 4) != 0)
			{
				num5 += pColObj.check_dir;
			}
			if ((pColObj.flag & 8) != 0)
			{
				if ((pColObj.flag & 0x40000000) != 0)
				{
					num5 = (ushort)(-(short)num5);
				}
				if ((pColObj.flag & 0x80000000u) != 0)
				{
					num5 = (ushort)(-((short)num5 + 16384) - 16384);
				}
			}
			pDir[0] = num5;
		}
		if (pAttr != null && result != 0)
		{
			if (pColObj.attr_data != null)
			{
				pAttr[0] = (uint)(pColObj.attr_data[num3 >> 3] | pColObj.attr);
			}
			else
			{
				pAttr[0] = pColObj.attr;
			}
		}
		return result;
	}

	private static int objGetColDataY(OBS_COLLISION_OBJ pColObj, int lPosX, int lPosY, ushort ucSuf, ushort[] pDir, uint[] pAttr)
	{
		sbyte result = 0;
		if (lPosX < pColObj.left || lPosX >= pColObj.right)
		{
			return result;
		}
		if (lPosY < pColObj.top || lPosY >= pColObj.bottom)
		{
			return result;
		}
		ushort num = (ushort)(lPosX - pColObj.left >> 3);
		ushort num2 = (ushort)(lPosY - pColObj.top >> 3);
		if ((pColObj.flag & 0x40000000) != 0)
		{
			num = (ushort)((pColObj.width >> 3) - 1 - num);
		}
		if ((pColObj.flag & 0x80000000u) != 0)
		{
			num2 = (ushort)((pColObj.height >> 3) - 1 - num2);
		}
		ushort num3 = (ushort)(num + num2 * (pColObj.width >> 3));
		int num4 = (lPosX - pColObj.left) & 7;
		if ((pColObj.flag & 0x40000000) != 0)
		{
			num4 = 7 - num4;
		}
		result = (sbyte)pColObj.diff_data[(num3 << 3) + num4];
		result >>= 4;
		result &= 0xF;
		if ((result & 8) != 0)
		{
			result |= -16;
		}
		if (result == -8)
		{
			result = 8;
		}
		if (pColObj.attr_data != null)
		{
			if ((ucSuf & 0x80) != 0 && ((pColObj.attr_data[num3 >> 3] & 1) != 0 || (pColObj.attr & 1) != 0))
			{
				result = 0;
			}
		}
		else if ((ucSuf & 0x80) != 0 && (pColObj.attr & 1) != 0)
		{
			result = 0;
		}
		if ((pColObj.flag & 0x80000000u) != 0 && result != 8 && result != 0)
		{
			result = ((result <= 0) ? ((sbyte)(result + 8)) : ((sbyte)(result - 8)));
		}
		if (pDir != null && result != 0)
		{
			ushort num5 = (ushort)((pColObj.dir_data != null) ? ((ushort)(pColObj.dir_data[num3] << 8)) : 0);
			if ((pColObj.flag & 4) != 0)
			{
				num5 += pColObj.check_dir;
			}
			if ((pColObj.flag & 8) != 0)
			{
				if ((pColObj.flag & 0x40000000) != 0)
				{
					num5 = (ushort)(-(short)num5);
				}
				if ((pColObj.flag & 0x80000000u) != 0)
				{
					num5 = (ushort)(-((short)num5 + 16384) - 16384);
				}
			}
			pDir[0] = num5;
		}
		if (pAttr != null && result != 0)
		{
			if (pColObj.attr_data != null)
			{
				pAttr[0] = (uint)(pColObj.attr_data[num3 >> 3] | pColObj.attr);
			}
			else
			{
				pAttr[0] = pColObj.attr;
			}
		}
		return result;
	}

	private static int objMapGetDiff(int lCol, sbyte sPix, sbyte sDelta)
	{
		if (lCol > 0)
		{
			if (sDelta > 0)
			{
				return lCol - (sPix + 1);
			}
			return 8 - sPix;
		}
		if (sDelta > 0)
		{
			return -(sPix + 1);
		}
		return lCol + sPix;
	}

	private static int objMapGetForward(sbyte sPix, sbyte sDelta)
	{
		if (sDelta > 0)
		{
			return 8 - sPix;
		}
		return 1 + sPix;
	}

	private static int objMapGetBack(sbyte sPix, sbyte sDelta)
	{
		if (sDelta > 0)
		{
			return -(sPix + 1);
		}
		return sPix - 8;
	}

	private static int objMapGetForwardRev(sbyte sPix, sbyte sDelta)
	{
		if (sDelta > 0)
		{
			return 8 - (sPix + 1);
		}
		return sPix;
	}

	private static uint nnCalcClipBoxNode(NNS_NODE node, NNS_MATRIX mtx)
	{
		float boundingBoxX = node.BoundingBoxX;
		float boundingBoxY = node.BoundingBoxY;
		float boundingBoxZ = node.BoundingBoxZ;
		return nnCalcClipBox(node.Center, boundingBoxX, boundingBoxY, boundingBoxZ, mtx);
	}

	private static uint nnCalcClipBox(NNS_VECTOR center, float sx, float sy, float sz, NNS_MATRIX mtx)
	{
		uint num = 0u;
		float n_clip = nngClip3d.n_clip;
		float f_clip = nngClip3d.f_clip;
		NNS_VECTORFAST dst;
		nnmSetUpVectorFast(out dst, center.x, center.y, center.z);
		NNS_VECTORFAST dst2;
		nnTransformVectorFast(out dst2, mtx, dst);
		float num2 = sx * mtx.M20;
		float num3 = sy * mtx.M21;
		float num4 = sz * mtx.M22;
		float num5 = nnAbs(num2) + nnAbs(num3) + nnAbs(num4);
		if (dst2.z > 0f - n_clip + num5 || dst2.z < 0f - f_clip - num5)
		{
			return 16u;
		}
		if (dst2.z > 0f - n_clip - num5)
		{
			num |= 0x104;
		}
		if (dst2.z < 0f - f_clip + num5)
		{
			num |= 0x208;
		}
		float num6 = sx * mtx.M00;
		float num7 = sy * mtx.M01;
		float num8 = sz * mtx.M02;
		if (nngProjectionType != 1)
		{
			num5 = nnAbs(num6 * nngClipPlane.Right.nx + num2 * nngClipPlane.Right.nz) + nnAbs(num7 * nngClipPlane.Right.nx + num3 * nngClipPlane.Right.nz) + nnAbs(num8 * nngClipPlane.Right.nx + num4 * nngClipPlane.Right.nz);
			float num9 = dst2.x * nngClipPlane.Right.nx + dst2.z * nngClipPlane.Right.nz;
			if (num9 > num5)
			{
				return 16u;
			}
			if (num9 > 0f - num5)
			{
				num |= 0x1000;
			}
			num5 = nnAbs(num6 * nngClipPlane.Left.nx + num2 * nngClipPlane.Left.nz) + nnAbs(num7 * nngClipPlane.Left.nx + num3 * nngClipPlane.Left.nz) + nnAbs(num8 * nngClipPlane.Left.nx + num4 * nngClipPlane.Left.nz);
			num9 = dst2.x * nngClipPlane.Left.nx + dst2.z * nngClipPlane.Left.nz;
			if (num9 > num5)
			{
				return 16u;
			}
			if (num9 > 0f - num5)
			{
				num |= 0x2000;
			}
			float num10 = sx * mtx.M10;
			float num11 = sy * mtx.M11;
			float num12 = sz * mtx.M12;
			num5 = nnAbs(num10 * nngClipPlane.Top.ny + num2 * nngClipPlane.Top.nz) + nnAbs(num11 * nngClipPlane.Top.ny + num3 * nngClipPlane.Top.nz) + nnAbs(num12 * nngClipPlane.Top.ny + num4 * nngClipPlane.Top.nz);
			num9 = dst2.y * nngClipPlane.Top.ny + dst2.z * nngClipPlane.Top.nz;
			if (num9 > num5)
			{
				return 16u;
			}
			if (num9 > 0f - num5)
			{
				num |= 0x4000;
			}
			num5 = nnAbs(num10 * nngClipPlane.Bottom.ny + num2 * nngClipPlane.Bottom.nz) + nnAbs(num11 * nngClipPlane.Bottom.ny + num3 * nngClipPlane.Bottom.nz) + nnAbs(num12 * nngClipPlane.Bottom.ny + num4 * nngClipPlane.Bottom.nz);
			num9 = dst2.y * nngClipPlane.Bottom.ny + dst2.z * nngClipPlane.Bottom.nz;
			if (num9 > num5)
			{
				return 16u;
			}
			if (num9 > 0f - num5)
			{
				num |= 0x8000;
			}
			if (num == 0)
			{
				return 2u;
			}
		}
		else
		{
			num5 = nnAbs(num6) + nnAbs(num7) + nnAbs(num8);
			float num9 = dst2.x - nngClipPlane.Right.mul - nngClipPlane.Right.ofs;
			if (num9 > num5)
			{
				return 16u;
			}
			if (num9 > 0f - num5)
			{
				num |= 0x1000;
			}
			num9 = dst2.x - nngClipPlane.Left.mul - nngClipPlane.Left.ofs;
			if (num9 < 0f - num5)
			{
				return 16u;
			}
			if (num9 < num5)
			{
				num |= 0x2000;
			}
			float num10 = sx * mtx.M10;
			float num11 = sy * mtx.M11;
			float num12 = sz * mtx.M12;
			num5 = nnAbs(num10) + nnAbs(num11) + nnAbs(num12);
			num9 = dst2.y - nngClipPlane.Top.mul - nngClipPlane.Top.ofs;
			if (num9 > num5)
			{
				return 16u;
			}
			if (num9 > 0f - num5)
			{
				num |= 0x4000;
			}
			num9 = dst2.y - nngClipPlane.Bottom.mul - nngClipPlane.Bottom.ofs;
			if (num9 < 0f - num5)
			{
				return 16u;
			}
			if (num9 < num5)
			{
				num |= 0x8000;
			}
			if (num == 0)
			{
				return 2u;
			}
		}
		return num & 0x3E;
	}

	private static uint nnCalcClipCore(NNS_VECTOR center, float radius, NNS_MATRIX mtx)
	{
		uint num = 0u;
		float n_clip = nngClip3d.n_clip;
		float f_clip = nngClip3d.f_clip;
		NNS_VECTORFAST dst;
		nnmSetUpVectorFast(out dst, center.x, center.y, center.z);
		NNS_VECTORFAST dst2;
		nnTransformVectorFast(out dst2, mtx, dst);
		if (dst2.z > 0f - n_clip + radius || dst2.z < 0f - f_clip - radius)
		{
			return 16u;
		}
		if (dst2.z > 0f - n_clip - radius)
		{
			num |= 0x104;
		}
		if (dst2.z < 0f - f_clip + radius)
		{
			num |= 0x208;
		}
		if (nngProjectionType != 1)
		{
			float num2 = dst2.x * nngClipPlane.Right.nx + dst2.z * nngClipPlane.Right.nz;
			if (num2 > radius)
			{
				return 16u;
			}
			if (num2 > 0f - radius)
			{
				num |= 0x1000;
			}
			num2 = dst2.x * nngClipPlane.Left.nx + dst2.z * nngClipPlane.Left.nz;
			if (num2 > radius)
			{
				return 16u;
			}
			if (num2 > 0f - radius)
			{
				num |= 0x2000;
			}
			num2 = dst2.y * nngClipPlane.Top.ny + dst2.z * nngClipPlane.Top.nz;
			if (num2 > radius)
			{
				return 16u;
			}
			if (num2 > 0f - radius)
			{
				num |= 0x4000;
			}
			num2 = dst2.y * nngClipPlane.Bottom.ny + dst2.z * nngClipPlane.Bottom.nz;
			if (num2 > radius)
			{
				return 16u;
			}
			if (num2 > 0f - radius)
			{
				num |= 0x8000;
			}
			if (num == 0)
			{
				return 2u;
			}
		}
		else
		{
			float num2 = dst2.y - nngClipPlane.Top.mul - nngClipPlane.Top.ofs;
			if (num2 > radius)
			{
				return 16u;
			}
			if (num2 > 0f - radius)
			{
				num |= 0x4000;
			}
			num2 = dst2.y - nngClipPlane.Bottom.mul - nngClipPlane.Bottom.ofs;
			if (num2 < 0f - radius)
			{
				return 16u;
			}
			if (num2 < radius)
			{
				num |= 0x8000;
			}
			num2 = dst2.x - nngClipPlane.Right.mul - nngClipPlane.Right.ofs;
			if (num2 > radius)
			{
				return 16u;
			}
			if (num2 > 0f - radius)
			{
				num |= 0x1000;
			}
			num2 = dst2.x - nngClipPlane.Left.mul - nngClipPlane.Left.ofs;
			if (num2 < 0f - radius)
			{
				return 16u;
			}
			if (num2 < radius)
			{
				num |= 0x2000;
			}
			if (num == 0)
			{
				return 2u;
			}
		}
		return num & 0x3E;
	}

	private static uint nnCalcClip(NNS_VECTOR center, float radius, NNS_MATRIX mtx)
	{
		if (radius == 0f)
		{
			return 0u;
		}
		radius *= nnEstimateMatrixScaling(mtx);
		return nnCalcClipCore(center, radius, mtx);
	}

	private static uint nnCalcClipUniformScale(NNS_VECTOR center, float radius, NNS_MATRIX mtx, float factor)
	{
		if (radius == 0f)
		{
			return 0u;
		}
		radius *= factor;
		return nnCalcClipCore(center, radius, mtx);
	}

	private static void nnCalcClipSetNodeStatus(uint[] pNodeStatList, NNS_NODE[] pNodeList, int nodeIdx, NNS_MATRIX pNodeMtx, float rootscale, uint flag)
	{
		nnclip.nnsNodeStatList = pNodeStatList;
		nnclip.nnsNodeList = pNodeList;
		NNS_NODE nNS_NODE = pNodeList[nodeIdx];
		if ((pNodeStatList[nodeIdx] & 0x401) != 0)
		{
			return;
		}
		if ((nNS_NODE.fType & 0x10) != 0)
		{
			pNodeStatList[nodeIdx] |= 1u;
		}
		if ((nNS_NODE.fType & 0x20) != 0)
		{
			pNodeStatList[nodeIdx] |= 1u;
			if (nNS_NODE.iChild != -1)
			{
				nnSetUpNodeStatusListFlag(nNS_NODE.iChild, 1u);
			}
		}
		else
		{
			if (flag == 0 || (nNS_NODE.iMatrix == -1 && (flag & 8) == 0))
			{
				return;
			}
			if ((nNS_NODE.fType & 0x200000) != 0 && (nNS_NODE.fType & 0x400000) == 0 && (flag & 0x20) == 0)
			{
				pNodeStatList[nodeIdx] |= nnCalcClipBoxNode(nNS_NODE, pNodeMtx);
			}
			else if ((flag & 0x10) != 0)
			{
				pNodeStatList[nodeIdx] |= nnCalcClip(nNS_NODE.Center, nNS_NODE.Radius, pNodeMtx);
			}
			else
			{
				pNodeStatList[nodeIdx] |= nnCalcClipUniformScale(nNS_NODE.Center, nNS_NODE.Radius, pNodeMtx, rootscale);
			}
			if ((pNodeStatList[nodeIdx] & 0x10) != 0)
			{
				if ((flag & 2) != 0)
				{
					pNodeStatList[nodeIdx] |= 1024u;
				}
				else
				{
					pNodeStatList[nodeIdx] |= 1u;
				}
				if ((flag & 8) != 0 && nNS_NODE.iChild != -1)
				{
					nnSetUpNodeStatusListFlag(nNS_NODE.iChild, pNodeStatList[nodeIdx]);
				}
			}
		}
	}

	private static void nnSetUpNodeStatusListFlag(int nodeidx, uint flag)
	{
		mppAssertNotImpl();
	}

