	private static float nnEstimateMatrixScaling(NNS_MATRIX mtx)
	{
		NNS_VECTORFAST dst;
		nnSetUpVectorFast(out dst, mtx.M00, mtx.M10, mtx.M20);
		NNS_VECTORFAST dst2;
		nnSetUpVectorFast(out dst2, mtx.M01, mtx.M11, mtx.M21);
		NNS_VECTORFAST dst3;
		nnSetUpVectorFast(out dst3, mtx.M02, mtx.M12, mtx.M22);
		float a = nnLengthSqVectorFast(ref dst);
		a = NNM_MAX(a, nnLengthSqVectorFast(ref dst2));
		a = NNM_MAX(a, nnLengthSqVectorFast(ref dst3));
		float a2 = nnAbs(nnDotProductVectorFast(ref dst, ref dst2));
		a2 = NNM_MAX(a2, nnAbs(nnDotProductVectorFast(ref dst, ref dst3)));
		a2 = NNM_MAX(a2, nnAbs(nnDotProductVectorFast(ref dst2, ref dst3)));
		return nnSqrt(a + 2f * a2);
	}

