	public static float amVectorScaleUnit(NNS_VECTOR4D pDst, NNS_VECTOR4D pSrc, float len)
	{
		float num = amSqrt(amPow2(pSrc.x) + amPow2(pSrc.y) + amPow2(pSrc.z));
		amVectorCopy(pDst, pSrc);
		if (!amIsZerof(num))
		{
			len /= num;
			pDst.x *= len;
			pDst.y *= len;
			pDst.z *= len;
		}
		return num;
	}

