	private static Thread amThreadCreate(ref AMS_THREAD thread, ParameterizedThreadStart proc, object arg, AMD_CORE core, int prio, uint stack_size, string name)
	{
		mppAssertNotImpl();
		amAssert(thread);
		amAssert(proc);
		thread.thread_id = new Thread(proc.Invoke);
		if (thread.thread_id != null)
		{
			amAlarmCreate(thread.alarm_exit);
			amMutexCreate(thread.mutex);
			thread.thread_id.Start(arg);
		}
		return thread.thread_id;
	}

