	public static void amMotionRegistFile(AMS_MOTION motion, int file_id, AMS_AMB_HEADER amb)
	{
		int num = 0;
		AMS_MOTION_FILE aMS_MOTION_FILE = motion.mtnfile[0];
		ArrayPointer<NNS_MOTION> arrayPointer = aMS_MOTION_FILE.motion + aMS_MOTION_FILE.motion_num;
		num++;
		int num2 = 1;
		while (num2 < 4)
		{
			ArrayPointer<NNS_MOTION> arrayPointer2 = motion.mtnfile[num].motion + motion.mtnfile[num].motion_num;
			if (arrayPointer < arrayPointer2)
			{
				arrayPointer = arrayPointer2;
			}
			num2++;
			num++;
		}
		if (arrayPointer == null)
		{
			arrayPointer = new ArrayPointer<NNS_MOTION>(motion.mtnbuf, 0);
		}
		aMS_MOTION_FILE = motion.mtnfile[file_id];
		aMS_MOTION_FILE.file = amb;
		aMS_MOTION_FILE.motion = arrayPointer;
		aMS_MOTION_FILE.motion_num = amMotionSetup(arrayPointer, amb);
	}

	public static void amMotionRegistFile(AMS_MOTION motion, int file_id, object buf)
	{
		int num = 0;
		AMS_MOTION_FILE aMS_MOTION_FILE = motion.mtnfile[0];
		ArrayPointer<NNS_MOTION> arrayPointer = aMS_MOTION_FILE.motion + aMS_MOTION_FILE.motion_num;
		num++;
		int num2 = 1;
		while (num2 < 4)
		{
			ArrayPointer<NNS_MOTION> arrayPointer2 = motion.mtnfile[num].motion + motion.mtnfile[num].motion_num;
			if (arrayPointer < arrayPointer2)
			{
				arrayPointer = arrayPointer2;
			}
			num2++;
			num++;
		}
		if (arrayPointer == null)
		{
			arrayPointer = new ArrayPointer<NNS_MOTION>(motion.mtnbuf, 0);
		}
		num = file_id;
		aMS_MOTION_FILE = motion.mtnfile[file_id];
		aMS_MOTION_FILE.file = buf;
		aMS_MOTION_FILE.motion = arrayPointer;
		if (buf is NNS_MOTION)
		{
			aMS_MOTION_FILE.motion_num = 1;
			motion.mtnbuf[0] = (NNS_MOTION)buf;
		}
		else
		{
			aMS_MOTION_FILE.motion_num = amMotionSetup(arrayPointer, buf);
		}
	}

	public static int amMotionSetup(ArrayPointer<NNS_MOTION> motion, AMS_AMB_HEADER amb)
	{
		if (amb.files.Length == 0)
		{
			return 0;
		}
		ArrayPointer<NNS_MOTION> arrayPointer = motion;
		int num = 0;
		for (int i = 0; i < amb.file_num; i++)
		{
			if (amb.buf[i] != null && amb.buf[i] is NNS_MOTION)
			{
				arrayPointer.SetPrimitive((NNS_MOTION)amb.buf[i]);
				++arrayPointer;
				num++;
			}
		}
		return num;
	}

	public static void amMotionSetup(out NNS_MOTION motion, AmbChunk buf)
	{
		motion = null;
		using (MemoryStream input = new MemoryStream(buf.array, buf.offset, buf.array.Length - buf.offset))
		{
			BinaryReader binaryReader = new BinaryReader(input);
			NNS_BINCNK_FILEHEADER nNS_BINCNK_FILEHEADER = NNS_BINCNK_FILEHEADER.Read(binaryReader);
			long num;
			binaryReader.BaseStream.Seek(num = nNS_BINCNK_FILEHEADER.OfsData, SeekOrigin.Begin);
			NNS_BINCNK_DATAHEADER nNS_BINCNK_DATAHEADER = NNS_BINCNK_DATAHEADER.Read(binaryReader);
			long num2 = num;
			binaryReader.BaseStream.Seek(nNS_BINCNK_FILEHEADER.OfsNOF0, SeekOrigin.Begin);
			NNS_BINCNK_NOF0HEADER.Read(binaryReader);
			int num3 = nNS_BINCNK_FILEHEADER.nChunk;
			while (num3 > 0)
			{
				switch (nNS_BINCNK_DATAHEADER.Id)
				{
				case 1095584078u:
				case 1129138510u:
				case 1330465102u:
					binaryReader.BaseStream.Seek(num2 + nNS_BINCNK_DATAHEADER.OfsMainData, SeekOrigin.Begin);
					motion = NNS_MOTION.Read(binaryReader, num2);
					break;
				case 1145980238u:
					return;
				}
				num3++;
				binaryReader.BaseStream.Seek(num += 8 + nNS_BINCNK_DATAHEADER.OfsNextId, SeekOrigin.Begin);
				nNS_BINCNK_DATAHEADER = NNS_BINCNK_DATAHEADER.Read(binaryReader);
			}
		}
	}

	public static int amMotionSetup(ArrayPointer<NNS_MOTION> motion, object _buf)
	{
		AmbChunk ambChunk = (AmbChunk)_buf;
		using (MemoryStream input = new MemoryStream(ambChunk.array, ambChunk.offset, ambChunk.array.Length - ambChunk.offset))
		{
			BinaryReader binaryReader = new BinaryReader(input);
			ArrayPointer<NNS_MOTION> arrayPointer = motion;
			int num = 0;
			arrayPointer.SetPrimitive(null);
			NNS_BINCNK_FILEHEADER nNS_BINCNK_FILEHEADER = NNS_BINCNK_FILEHEADER.Read(binaryReader);
			long num2;
			binaryReader.BaseStream.Seek(num2 = nNS_BINCNK_FILEHEADER.OfsData, SeekOrigin.Begin);
			NNS_BINCNK_DATAHEADER nNS_BINCNK_DATAHEADER = NNS_BINCNK_DATAHEADER.Read(binaryReader);
			long num3 = num2;
			binaryReader.BaseStream.Seek(nNS_BINCNK_FILEHEADER.OfsNOF0, SeekOrigin.Begin);
			NNS_BINCNK_NOF0HEADER.Read(binaryReader);
			for (int i = nNS_BINCNK_FILEHEADER.nChunk; i > 0; i++, binaryReader.BaseStream.Seek(num2 += 8 + nNS_BINCNK_DATAHEADER.OfsNextId, SeekOrigin.Begin), nNS_BINCNK_DATAHEADER = NNS_BINCNK_DATAHEADER.Read(binaryReader))
			{
				switch (nNS_BINCNK_DATAHEADER.Id)
				{
				case 1095584078u:
				case 1129138510u:
				case 1330465102u:
					binaryReader.BaseStream.Seek(num3 + nNS_BINCNK_DATAHEADER.OfsMainData, SeekOrigin.Begin);
					arrayPointer.SetPrimitive(NNS_MOTION.Read(binaryReader, num3));
					++arrayPointer;
					num++;
					continue;
				default:
					continue;
				case 1145980238u:
					break;
				}
				break;
			}
			return num;
		}
	}

	public static void amMotionSet(AMS_MOTION motion, int mbuf_id, int motion_id)
	{
		AMS_MOTION_BUF aMS_MOTION_BUF = motion.mbuf[mbuf_id];
