	public static void amMotionCalc(AMS_MOTION motion, int mbuf_id)
	{
		int num = 0;
		while (num < 2)
		{
			if ((mbuf_id & 1) != 0 && !(motion.mbuf[num].mbuf == null))
			{
				int motion_id = motion.mbuf[num].motion_id;
				int num2 = motion_id >> 16;
				motion_id &= 0xFFFF;
				nnCalcTRSListMotion(motion.mbuf[num].mbuf.array, motion.mbuf[num].mbuf.offset, motion._object, motion.mtnfile[num2].motion[motion_id], motion.mbuf[num].frame);
			}
			num++;
			mbuf_id >>= 1;
		}
	}

