	public static void amEffectLerpColor(out AMS_RGBA8888 pCO, ref AMS_RGBA8888 pC1, ref AMS_RGBA8888 pC2, float rate)
	{
		int num = 0;
		num = (int)(rate * 256f);
		pCO = default(AMS_RGBA8888);
		pCO.r = (byte)((pC1.r << 8) + (pC2.r - pC1.r) * num >> 8);
		pCO.g = (byte)((pC1.g << 8) + (pC2.g - pC1.g) * num >> 8);
		pCO.b = (byte)((pC1.b << 8) + (pC2.b - pC1.b) * num >> 8);
		pCO.a = (byte)((pC1.a << 8) + (pC2.a - pC1.a) * num >> 8);
	}

