	private void amEffectRandomConeVector(ref Vector4 pOut, float s)
	{
		mppAssertNotImpl();
	}

	public static void amEffectRandomConeVectorDeg(NNS_VECTOR4D pOut, float s)
	{
		float pCs = nnCos(NNM_DEGtoA32(s));
		float num = nnRandom() * (1f - pCs) + pCs;
		float num2 = (float)Math.Sqrt(1f - num * num);
		amSinCos(nnRandom() * ((float)Math.PI * 2f), out s, out pCs);
		amVectorSet(pOut, num2 * pCs, num, num2 * s);
		amVectorUnit(pOut);
	}

	private void _amConnectLinkToHead(AMS_AME_LIST head, AMS_AME_LIST list)
	{
		list.next = head.next;
		list.prev = head.next.prev;
		head.next.prev = list;
		head.next = list;
	}

	public static void _amConnectLinkToTail(AMS_AME_LIST tail, AMS_AME_LIST list)
	{
		list.prev = tail.prev;
		list.next = tail.prev.next;
		tail.prev.next = list;
		tail.prev = list;
	}

	public static void amEffectSystemInit()
	{
		NNS_RGBA diffuse = new NNS_RGBA(1f, 1f, 1f, 1f);
		NNS_RGB ambient = new NNS_RGB(1f, 1f, 1f);
		nnSetPrimitive3DMaterial(ref diffuse, ref ambient, 1f);
		_am_enable_draw = 1;
		_am_unit_frame = 1f;
		_am_unit_time = 1f / 60f;
		_am_ecb_alloc = 0;
		_am_ecb_free = 0;
		_am_ecb_head.Clear();
		_am_ecb_tail.Clear();
		_am_ecb_head.next = _am_ecb_tail;
		_am_ecb_tail.prev = _am_ecb_head;
		_am_ecb_buf = New<AMS_AME_ECB>(128);
		_am_ecb_ref = new AMS_AME_ECB[128];
		for (int i = 0; i < 128; i++)
		{
			_am_ecb_ref[i] = _am_ecb_buf[i];
		}
		_am_entry_alloc = 0;
		_am_entry_free = 0;
		_am_entry_buf = new AMS_AME_ENTRY[512];
		_am_entry_ref = new AMS_AME_ENTRY[512];
		for (int j = 0; j < 512; j++)
		{
			_am_entry_buf[j] = new AMS_AME_ENTRY();
			_am_entry_ref[j] = _am_entry_buf[j];
		}
		_am_runtime_alloc = 0;
		_am_runtime_free = 0;
		_am_runtime_buf = new AMS_AME_RUNTIME[512];
		_am_runtime_ref = new AMS_AME_RUNTIME[512];
		for (int k = 0; k < 512; k++)
		{
			_am_runtime_buf[k] = new AMS_AME_RUNTIME();
			_am_runtime_ref[k] = _am_runtime_buf[k];
		}
		_am_work_alloc = 0;
		_am_work_free = 0;
		_am_work_buf = new AMS_AME_RUNTIME_WORK[1024];
		_am_work_ref = new AMS_AME_RUNTIME_WORK[1024];
		for (int l = 0; l < 1024; l++)
		{
			_am_work_buf[l] = new AMS_AME_RUNTIME_WORK();
			_am_work_ref[l] = _am_work_buf[l];
		}
	}

	private void amEffectSystemReset()
	{
		mppAssertNotImpl();
		amEffectSystemInit();
	}

	public static void amEffectExecute()
	{
		for (AMS_AME_ECB aMS_AME_ECB = (AMS_AME_ECB)_am_ecb_head.next; aMS_AME_ECB != _am_ecb_tail; aMS_AME_ECB = (AMS_AME_ECB)aMS_AME_ECB.next)
		{
			if (aMS_AME_ECB.entry_num < 0)
			{
				_amEffectFinalize(aMS_AME_ECB);
			}
		}
	}

	private void amEffectRegistCustomFunc(int classId, AMS_AME_CUSTOM_PARAM pParam)
	{
		mppAssertNotImpl();
		switch (classId & 0xFF00)
		{
		case 256:
		{
			int num = (classId & 0xFF) << 2;
			_am_emitter_func[num] = pParam.pInitFunc;
			_am_emitter_func[num + 1] = pParam.pUpdateFunc;
			_am_emitter_func[num + 2] = pParam.pDrawFunc;
			break;
		}
		case 512:
		{
			int num = (classId & 0xFF) << 2;
			_am_particle_func[num] = pParam.pInitFunc;
			_am_particle_func[num + 1] = pParam.pUpdateFunc;
			_am_particle_func[num + 2] = pParam.pDrawFunc;
			break;
		}
		case 768:
		{
			int num = classId & 0xFF;
			_am_field_func[num] = pParam.pFieldFunc;
			break;
		}
		}
	}

	private void amEffectUnregistCustomFunc(int classId)
	{
		mppAssertNotImpl();
		switch (classId & 0xFF00)
		{
		case 256:
		{
			int num = (classId & 0xFF) << 2;
			_am_emitter_func[num] = null;
			_am_emitter_func[num + 1] = null;
			_am_emitter_func[num + 2] = null;
			break;
		}
		case 512:
		{
			int num = (classId & 0xFF) << 2;
			_am_particle_func[num] = null;
			_am_particle_func[num + 1] = null;
			_am_particle_func[num + 2] = null;
			break;
		}
		case 768:
		{
			int num = classId & 0xFF;
			_am_field_func[num] = null;
			break;
		}
		}
	}

