	private AMS_AME_NODE amEffectSearchNode(AMS_AME_NODE node, int id)
	{
		mppAssertNotImpl();
		AMS_AME_NODE aMS_AME_NODE = null;
		if (node.id == id)
		{
			return node;
		}
		if (node.child != null)
		{
			aMS_AME_NODE = amEffectSearchNode(node.child, id);
			if (aMS_AME_NODE != null)
			{
				return aMS_AME_NODE;
			}
		}
		if (node.sibling != null)
		{
			aMS_AME_NODE = amEffectSearchNode(node.sibling, id);
		}
		return aMS_AME_NODE;
	}

