	private static AMS_AME_ECB _amEffectCreate(AMS_AME_HEADER header, int attribute, int priority)
	{
		AMS_AME_ECB aMS_AME_ECB = _am_ecb_ref[_am_ecb_alloc];
		_am_ecb_alloc++;
		if (_am_ecb_alloc >= 128)
		{
