		NNS_QUATERNION pQuat = default(NNS_QUATERNION);
		amQuatEulerToQuatXYZ(ref pQuat, x, y, z);
		amEffectRotate(ecb, ref pQuat);
	}

	private void amEffectRotate(AMS_AME_ECB ecb, ref NNS_QUATERNION q)
	{
		amQuatMulti(ref ecb.rotate, ref ecb.rotate, ref q);
		for (AMS_AME_ENTRY aMS_AME_ENTRY = ecb.entry_head; aMS_AME_ENTRY != null; aMS_AME_ENTRY = (AMS_AME_ENTRY)aMS_AME_ENTRY.next)
		{
			AMS_AME_RUNTIME runtime = aMS_AME_ENTRY.runtime;
			if ((runtime.state & 0x2000) != 0 && (runtime.node.flag & 0x8000000) == 0)
			{
				if (runtime.work != null)
				{
					amQuatMulti(ref runtime.work.rotate[0], ref runtime.work.rotate[0], ref q);
				}
				if (runtime.work_num + runtime.active_num != 0)
				{
					AMS_AME_LIST next = runtime.work_head.next;
					AMS_AME_LIST work_tail = runtime.work_tail;
					while (next != work_tail)
					{
						AMS_AME_RUNTIME_WORK aMS_AME_RUNTIME_WORK = (AMS_AME_RUNTIME_WORK)next;
						if (runtime.work != null)
						{
							amQuatMulti(ref aMS_AME_RUNTIME_WORK.rotate[0], ref runtime.work.rotate[0], ref q);
						}
						next = next.next;
					}
					next = runtime.active_head.next;
					work_tail = runtime.active_tail;
					while (next != work_tail)
					{
						AMS_AME_RUNTIME_WORK aMS_AME_RUNTIME_WORK = (AMS_AME_RUNTIME_WORK)next;
						if (runtime.work != null)
						{
							amQuatMulti(ref aMS_AME_RUNTIME_WORK.rotate[0], ref runtime.work.rotate[0], ref q);
						}
						next = next.next;
					}
				}
			}
		}
	}

