	public static void _amEffectFinalize(AMS_AME_ECB ecb)
	{
		for (AMS_AME_ENTRY aMS_AME_ENTRY = ecb.entry_head; aMS_AME_ENTRY != null; aMS_AME_ENTRY = (AMS_AME_ENTRY)aMS_AME_ENTRY.next)
		{
			AMS_AME_RUNTIME runtime = aMS_AME_ENTRY.runtime;
			AMS_AME_NODE node = runtime.node;
			if (AMD_AME_SUPER_CLASS_ID(node) == 256 && runtime.parent_runtime != null)
			{
				amEffectDisconnectLink(runtime);
				runtime.parent_runtime.work_num--;
			}
			_amFreeRuntime(aMS_AME_ENTRY.runtime);
			_amDelEntry(ecb, aMS_AME_ENTRY);
		}
		ecb.prev.next = ecb.next;
		ecb.next.prev = ecb.prev;
		_am_ecb_ref[_am_ecb_free] = ecb;
		_am_ecb_free++;
		if (_am_ecb_free >= 128)
		{
			_am_ecb_free = 0;
		}
	}

	public static AMS_AME_RUNTIME _amCreateRuntimeEmitter(AMS_AME_CREATE_PARAM param)
	{
		AMS_AME_RUNTIME aMS_AME_RUNTIME = _amAllocRuntime();
		aMS_AME_RUNTIME.ecb = param.ecb;
		aMS_AME_RUNTIME.node = param.node;
		aMS_AME_RUNTIME.child_head.next = aMS_AME_RUNTIME.child_tail;
		aMS_AME_RUNTIME.child_tail.prev = aMS_AME_RUNTIME.child_head;
		aMS_AME_RUNTIME.work_head.next = aMS_AME_RUNTIME.work_tail;
		aMS_AME_RUNTIME.work_tail.prev = aMS_AME_RUNTIME.work_head;
		aMS_AME_RUNTIME.active_head.next = aMS_AME_RUNTIME.active_tail;
		aMS_AME_RUNTIME.active_tail.prev = aMS_AME_RUNTIME.active_head;
		_amAddEntry(param.ecb, aMS_AME_RUNTIME);
		aMS_AME_RUNTIME.work = _amAllocRuntimeWork();
		param.work = aMS_AME_RUNTIME.work;
		AmeDelegateFunc ameDelegateFunc = _am_emitter_func[(AMD_AME_NODE_TYPE(param.node) & 0xFF) << 2];
		ameDelegateFunc(param);
		for (AMS_AME_NODE aMS_AME_NODE = param.node.child; aMS_AME_NODE != null; aMS_AME_NODE = aMS_AME_NODE.sibling)
		{
			if (!AMD_AME_IS_FIELD(aMS_AME_NODE))
			{
				AMS_AME_RUNTIME list = _amCreateRuntimeGroup(param.ecb, aMS_AME_NODE);
				_amConnectLinkToTail(aMS_AME_RUNTIME.child_tail, list);
				aMS_AME_RUNTIME.child_num++;
			}
		}
		return aMS_AME_RUNTIME;
	}

	private static AMS_AME_RUNTIME _amCreateRuntimeParticle(AMS_AME_CREATE_PARAM param)
	{
		AMS_AME_RUNTIME aMS_AME_RUNTIME = _amAllocRuntime();
		aMS_AME_RUNTIME.ecb = param.ecb;
		aMS_AME_RUNTIME.node = param.node;
		aMS_AME_RUNTIME.state = 16384;
		aMS_AME_RUNTIME.child_head.next = aMS_AME_RUNTIME.child_tail;
		aMS_AME_RUNTIME.child_tail.prev = aMS_AME_RUNTIME.child_head;
		aMS_AME_RUNTIME.work_head.next = aMS_AME_RUNTIME.work_tail;
		aMS_AME_RUNTIME.work_tail.prev = aMS_AME_RUNTIME.work_head;
		aMS_AME_RUNTIME.active_head.next = aMS_AME_RUNTIME.active_tail;
		aMS_AME_RUNTIME.active_tail.prev = aMS_AME_RUNTIME.active_head;
		for (AMS_AME_NODE aMS_AME_NODE = param.node.child; aMS_AME_NODE != null; aMS_AME_NODE = aMS_AME_NODE.sibling)
		{
			if (AMD_AME_IS_PARTICLE(aMS_AME_NODE))
			{
				aMS_AME_RUNTIME.spawn_runtime = _amCreateRuntimeGroup(param.ecb, aMS_AME_NODE);
				break;
			}
		}
		_amAddEntry(param.ecb, aMS_AME_RUNTIME);
		param.runtime = aMS_AME_RUNTIME;
		_amCreateParticle(param);
		return aMS_AME_RUNTIME;
	}

