		for (AMS_AME_NODE aMS_AME_NODE = node.child; aMS_AME_NODE != null; aMS_AME_NODE = aMS_AME_NODE.sibling)
		{
			if (AMD_AME_IS_PARTICLE(aMS_AME_NODE))
