	public static void _amCreateEmitter(AMS_AME_CREATE_PARAM param)
	{
		AMS_AME_RUNTIME aMS_AME_RUNTIME = _amCreateRuntimeEmitter(param);
		aMS_AME_RUNTIME.parent_runtime = param.runtime;
		_amConnectLinkToTail(aMS_AME_RUNTIME.work_tail, aMS_AME_RUNTIME);
		aMS_AME_RUNTIME.work_num++;
		param.runtime = aMS_AME_RUNTIME;
		param.node = aMS_AME_RUNTIME.node;
