	public static void _amCreateParticle(AMS_AME_CREATE_PARAM param)
	{
		AMS_AME_RUNTIME_WORK_MODEL aMS_AME_RUNTIME_WORK_MODEL = (AMS_AME_RUNTIME_WORK_MODEL)_amAllocRuntimeWork();
		param.work = aMS_AME_RUNTIME_WORK_MODEL;
		AmeDelegateFunc ameDelegateFunc = _am_particle_func[(AMD_AME_NODE_TYPE(param.node) & 0xFF) << 2];
		ameDelegateFunc(param);
		if (aMS_AME_RUNTIME_WORK_MODEL.time < 0f)
		{
			_amConnectLinkToTail(param.runtime.work_tail, (AMS_AME_LIST)aMS_AME_RUNTIME_WORK_MODEL);
			param.runtime.work_num++;
		}
		else
		{
			_amConnectLinkToTail(param.runtime.active_tail, (AMS_AME_LIST)aMS_AME_RUNTIME_WORK_MODEL);
			param.runtime.active_num++;
		}
	}

