	public static AMS_AME_RUNTIME _amAllocRuntime()
	{
		AMS_AME_RUNTIME aMS_AME_RUNTIME = _am_runtime_ref[_am_runtime_alloc];
		_am_runtime_alloc++;
		if (_am_runtime_alloc >= 512)
		{
			_am_runtime_alloc = 0;
		}
		aMS_AME_RUNTIME.Clear();
		return aMS_AME_RUNTIME;
	}

	public static void _amFreeRuntime(AMS_AME_RUNTIME runtime)
	{
		if (runtime.work != null)
		{
			AMS_AME_RUNTIME_WORK work = runtime.work;
			amEffectFreeRuntimeWork(work);
		}
		AMS_AME_RUNTIME_WORK aMS_AME_RUNTIME_WORK = (AMS_AME_RUNTIME_WORK)runtime.work_head.next;
		AMS_AME_RUNTIME_WORK aMS_AME_RUNTIME_WORK2 = (AMS_AME_RUNTIME_WORK)runtime.work_tail;
		while (aMS_AME_RUNTIME_WORK != aMS_AME_RUNTIME_WORK2)
		{
			amEffectFreeRuntimeWork(aMS_AME_RUNTIME_WORK);
			aMS_AME_RUNTIME_WORK = (AMS_AME_RUNTIME_WORK)aMS_AME_RUNTIME_WORK.next;
		}
		aMS_AME_RUNTIME_WORK = (AMS_AME_RUNTIME_WORK)runtime.active_head.next;
		aMS_AME_RUNTIME_WORK2 = (AMS_AME_RUNTIME_WORK)runtime.active_tail;
		while (aMS_AME_RUNTIME_WORK != aMS_AME_RUNTIME_WORK2)
		{
			amEffectFreeRuntimeWork(aMS_AME_RUNTIME_WORK);
			aMS_AME_RUNTIME_WORK = (AMS_AME_RUNTIME_WORK)aMS_AME_RUNTIME_WORK.next;
		}
		_am_runtime_ref[_am_runtime_free] = runtime;
		_am_runtime_free++;
		if (_am_runtime_free >= 512)
		{
			_am_runtime_free = 0;
		}
	}

	public static AMS_AME_RUNTIME_WORK _amAllocRuntimeWork()
	{
		AMS_AME_RUNTIME_WORK aMS_AME_RUNTIME_WORK = _am_work_ref[_am_work_alloc];
		_am_work_alloc++;
		if (_am_work_alloc >= 1024)
		{
			_am_work_alloc = 0;
		}
		aMS_AME_RUNTIME_WORK.Clear();
		return aMS_AME_RUNTIME_WORK;
	}

	public static void amEffectFreeRuntimeWork(AMS_AME_RUNTIME_WORK work)
	{
		_am_work_ref[_am_work_free] = work;
		_am_work_free++;
		if (_am_work_free >= 1024)
		{
			_am_work_free = 0;
		}
	}

	public static void _amAddEntry(AMS_AME_ECB ecb, AMS_AME_RUNTIME runtime)
	{
		AMS_AME_ENTRY aMS_AME_ENTRY = _am_entry_ref[_am_entry_alloc];
		_am_entry_alloc++;
		if (_am_entry_alloc >= 512)
		{
			_am_entry_alloc = 0;
		}
		aMS_AME_ENTRY.runtime = runtime;
		if (ecb.entry_head == null)
		{
			ecb.entry_head = aMS_AME_ENTRY;
			aMS_AME_ENTRY.prev = null;
		}
		if (ecb.entry_tail != null)
		{
			aMS_AME_ENTRY.prev = ecb.entry_tail;
			ecb.entry_tail.next = aMS_AME_ENTRY;
		}
		ecb.entry_tail = aMS_AME_ENTRY;
		aMS_AME_ENTRY.next = null;
		ecb.entry_num++;
	}

	public static void _amDelEntry(AMS_AME_ECB ecb, AMS_AME_ENTRY entry)
	{
		if (entry.prev == null)
		{
			ecb.entry_head = (AMS_AME_ENTRY)entry.next;
		}
		else
		{
			entry.prev.next = entry.next;
		}
		if (entry.next == null)
		{
			ecb.entry_tail = (AMS_AME_ENTRY)entry.prev;
		}
		else
		{
			entry.next.prev = entry.prev;
		}
		_am_entry_ref[_am_entry_free] = entry;
		_am_entry_free++;
		if (_am_entry_free >= 512)
		{
			_am_entry_free = 0;
		}
		ecb.entry_num--;
	}

	private static int _amEffectSetDrawMode(AMS_AME_RUNTIME runtime, AMS_PARAM_DRAW_PRIMITIVE param, int NodeBlend)
	{
		AMS_AME_NODE node = runtime.node;
		int result = (param.ablend = 0);
		if ((node.flag & 2) != 0)
		{
			param.aTest = 1;
		}
		else
		{
			param.aTest = 0;
		}
		if ((node.flag & 0x2000000) != 0)
		{
			param.zMask = 1;
		}
		else
		{
			param.zMask = 0;
		}
		if ((node.flag & 0x1000000) == 0)
		{
			param.zTest = 0;
		}
		else
		{
			param.zTest = 1;
		}
		if ((node.flag & 1) != 0)
		{
			result = (param.ablend = 1);
			switch (NodeBlend)
			{
			case 50:
				param.bldSrc = 770;
				param.bldDst = 771;
				param.bldMode = 32774;
				break;
			case 162:
				param.bldSrc = 770;
				param.bldDst = 1;
				param.bldMode = 32774;
				break;
			case 674:
				param.bldSrc = 770;
				param.bldDst = 1;
				param.bldMode = 32779;
				break;
			}
		}
		return result;
	}

	private static uint _amEffectSetMaterial(AMS_AME_RUNTIME runtime, ref int blend, int NodeBlend)
	{
		AMS_AME_NODE node = runtime.node;
		uint num = 0u;
		if ((node.flag & 1) != 0)
		{
			num |= 0x800400;
			switch (NodeBlend)
			{
			case 50:
				blend = 0;
				break;
			case 162:
				blend = 1;
				break;
			case 674:
				blend = 2;
				break;
			}
		}
		return num;
	}

	private static int _amInitOmni(object p)
	{
		AMS_AME_CREATE_PARAM aMS_AME_CREATE_PARAM = (AMS_AME_CREATE_PARAM)p;
		AMS_AME_NODE_OMNI aMS_AME_NODE_OMNI = (AMS_AME_NODE_OMNI)aMS_AME_CREATE_PARAM.node;
		AMS_AME_RUNTIME_WORK_OMNI aMS_AME_RUNTIME_WORK_OMNI = (AMS_AME_RUNTIME_WORK_OMNI)aMS_AME_CREATE_PARAM.work;
		aMS_AME_RUNTIME_WORK_OMNI.time = 0f - aMS_AME_NODE_OMNI.start_time;
