				{
					continue;
				}
				AMS_AME_CREATE_PARAM amEffect_create_param = _amEffect_create_param;
				amVectorSet(amEffect_direction, 0f, 1f, 0f);
				float num = nnRandom() / 2f + nnRandom() * 0.5f;
				float x = aMS_AME_RUNTIME_WORK_SURFACE.width * num - aMS_AME_RUNTIME_WORK_SURFACE.width * 0.5f;
				num = nnRandom() / 2f + nnRandom() * 0.5f;
				float z = aMS_AME_RUNTIME_WORK_SURFACE.height * num - aMS_AME_RUNTIME_WORK_SURFACE.height * 0.5f;
				if ((aMS_AME_NODE_SURFACE.flag & 1) != 0)
				{
