					bool flag = false;
					if (nnRandom() > 0.5f)
					{
						flag = true;
					}
					if (num2 > 0.5f)
					{
						x = aMS_AME_RUNTIME_WORK_SURFACE.width * 0.5f;
						x = ((x > 0f && flag) ? (0f - x) : x);
					}
