				amEffect_create_param.parent_velocity = aMS_AME_RUNTIME_WORK_SURFACE.velocity;
				amEffect_create_param.position = amEffect_position;
				amEffect_create_param.velocity = amEffect_velocity;
				switch (AMD_AME_NODE_TYPE(aMS_AME_RUNTIME2.node) & 0xFF00)
				{
				case 512:
					_amCreateParticle(amEffect_create_param);
					break;
				case 256:
					_amCreateEmitter(amEffect_create_param);
					break;
				}
			}
			next = next.next;
		}
		amMatrixPop();
		return 0;
