					}
					else if ((aMS_AME_NODE_CIRCLE.flag & 2) != 0)
					{
						int num2 = (int)aMS_AME_NODE_CIRCLE.max_count;
						angle = (int)(65535 / num2 * (aMS_AME_RUNTIME2.count % num2));
					}
					float pSn;
					float pCs;
					amSinCos(angle, out pSn, out pCs);
					amVectorSet(nNS_VECTOR4D2, pSn * num, 0f, pCs * num);
					NNS_VECTOR4D nNS_VECTOR4D5 = GlobalPool<NNS_VECTOR4D>.Alloc();
					NNS_QUATERNION pQuat2 = default(NNS_QUATERNION);
					amVectorOuterProduct(nNS_VECTOR4D5, nNS_VECTOR4D4, nNS_VECTOR4D2);
					amVectorUnit(nNS_VECTOR4D5);
					amQuatRotAxisToQuat(ref pQuat2, nNS_VECTOR4D5, NNM_DEGtoRAD((int)aMS_AME_RUNTIME_WORK_CIRCLE.spread));
					amQuatMultiVector(nNS_VECTOR4D4, nNS_VECTOR4D4, ref pQuat2, null);
					GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D5);
					amMatrixCalcVector(nNS_VECTOR4D2, nNS_VECTOR4D2);
					amMatrixCalcVector(nNS_VECTOR4D4, nNS_VECTOR4D4);
					amVectorScale(nNS_VECTOR4D3, nNS_VECTOR4D4, aMS_AME_RUNTIME_WORK_CIRCLE.offset + aMS_AME_RUNTIME_WORK_CIRCLE.offset_chaos * nnRandom());
					amVectorAdd(nNS_VECTOR4D2, nNS_VECTOR4D3);
					amVectorScale(nNS_VECTOR4D3, nNS_VECTOR4D4, aMS_AME_NODE_CIRCLE.speed + aMS_AME_NODE_CIRCLE.speed_chaos * nnRandom());
					aMS_AME_CREATE_PARAM.ecb = aMS_AME_RUNTIME.ecb;
					aMS_AME_CREATE_PARAM.runtime = aMS_AME_RUNTIME2;
					aMS_AME_CREATE_PARAM.node = aMS_AME_RUNTIME2.node;
					aMS_AME_CREATE_PARAM.parent_position = aMS_AME_RUNTIME_WORK_CIRCLE.position;
					aMS_AME_CREATE_PARAM.parent_velocity = aMS_AME_RUNTIME_WORK_CIRCLE.velocity;
					aMS_AME_CREATE_PARAM.position = nNS_VECTOR4D2;
					aMS_AME_CREATE_PARAM.velocity = nNS_VECTOR4D3;
					switch (AMD_AME_NODE_TYPE(aMS_AME_RUNTIME2.node) & 0xFF00)
					{
					case 512:
						_amCreateParticle(aMS_AME_CREATE_PARAM);
						break;
					case 256:
						_amCreateEmitter(aMS_AME_CREATE_PARAM);
						break;
					}
				}
			}
			next = next.next;
		}
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D2);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D3);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D4);
		amMatrixPop();
		return 0;
	}

