	public static int _amInitSimpleSprite(object p)
	{
		AMS_AME_CREATE_PARAM aMS_AME_CREATE_PARAM = (AMS_AME_CREATE_PARAM)p;
		AMS_AME_NODE_SPRITE aMS_AME_NODE_SPRITE = (AMS_AME_NODE_SPRITE)aMS_AME_CREATE_PARAM.node;
		AMS_AME_RUNTIME_WORK_SIMPLE_SPRITE aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE = (AMS_AME_RUNTIME_WORK_SIMPLE_SPRITE)aMS_AME_CREATE_PARAM.work;
		aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.time = 0f - aMS_AME_NODE_SPRITE.start_time;
		aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.set_color(aMS_AME_NODE_SPRITE.color_start.r, aMS_AME_NODE_SPRITE.color_start.g, aMS_AME_NODE_SPRITE.color_start.b, (byte)(aMS_AME_NODE_SPRITE.color_start.a * aMS_AME_CREATE_PARAM.ecb.transparency >> 8));
		amVectorAdd(aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.position, aMS_AME_CREATE_PARAM.parent_position, aMS_AME_CREATE_PARAM.position);
		amVectorAdd(aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.position, aMS_AME_NODE_SPRITE.translate);
		amVectorScale(aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.velocity, aMS_AME_CREATE_PARAM.parent_velocity, aMS_AME_NODE_SPRITE.inheritance_rate);
		amVectorAdd(aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.velocity, aMS_AME_CREATE_PARAM.velocity);
		float num = aMS_AME_NODE_SPRITE.size + aMS_AME_NODE_SPRITE.size_chaos * nnRandom();
		aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.set_size(num * aMS_AME_NODE_SPRITE.scale_x_start, num * aMS_AME_NODE_SPRITE.scale_y_start, num, 0f);
		if ((aMS_AME_NODE_SPRITE.flag & 0x8000) != 0)
		{
			aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_time = 0f;
			aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_no = 0;
			if ((aMS_AME_NODE_SPRITE.flag & 0x80000) != 0)
			{
				aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_no = (int)(100f * nnRandom()) % aMS_AME_NODE_SPRITE.tex_anim.key_num;
			}
			AMS_AME_TEX_ANIM_KEY aMS_AME_TEX_ANIM_KEY = aMS_AME_NODE_SPRITE.tex_anim.key_buf[aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_no];
			Vector4 vector = new Vector4(aMS_AME_TEX_ANIM_KEY.l, aMS_AME_TEX_ANIM_KEY.t, aMS_AME_TEX_ANIM_KEY.r, aMS_AME_TEX_ANIM_KEY.b);
			aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.set_st(vector.X, vector.Y, vector.Z, vector.W);
		}
		else if ((aMS_AME_NODE_SPRITE.flag & 0x2000) != 0)
		{
			aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.set_st(aMS_AME_NODE_SPRITE.cropping_l, aMS_AME_NODE_SPRITE.cropping_t, aMS_AME_NODE_SPRITE.cropping_r, aMS_AME_NODE_SPRITE.cropping_b);
		}
		else
		{
			aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.set_st(0f, 0f, 1f, 1f);
		}
		if ((aMS_AME_NODE_SPRITE.flag & 0x100000) != 0 || ((aMS_AME_NODE_SPRITE.flag & 0x20000) != 0 && nnRandom() > 0.5f))
		{
			aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.flag |= 8u;
			aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.set_st(aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.st.z, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.st.y, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.st.x, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.st.w);
		}
		if ((aMS_AME_NODE_SPRITE.flag & 0x200000) != 0 || ((aMS_AME_NODE_SPRITE.flag & 0x40000) != 0 && nnRandom() > 0.5f))
		{
			aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.flag |= 16u;
			aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.set_st(aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.st.x, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.st.w, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.st.z, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.st.y);
		}
		return 0;
	}

	public static int _amUpdateSimpleSprite(object r)
	{
		AMS_AME_RUNTIME aMS_AME_RUNTIME = (AMS_AME_RUNTIME)r;
		AMS_AME_NODE_SPRITE aMS_AME_NODE_SPRITE = (AMS_AME_NODE_SPRITE)aMS_AME_RUNTIME.node;
		AMS_AME_LIST next = aMS_AME_RUNTIME.active_head.next;
		AMS_AME_LIST active_tail = aMS_AME_RUNTIME.active_tail;
		int transparency = aMS_AME_RUNTIME.ecb.transparency;
		float num;
		float num2;
		if (aMS_AME_NODE_SPRITE.life >= 0f)
		{
			num = aMS_AME_NODE_SPRITE.life;
			num2 = 1f / num;
		}
		else
		{
			num = float.MaxValue;
			num2 = 0f;
		}
		float size_rate = aMS_AME_RUNTIME.ecb.size_rate;
		float num3 = aMS_AME_NODE_SPRITE.scale_x_start * size_rate;
		float num4 = aMS_AME_NODE_SPRITE.scale_y_start * size_rate;
		float num5 = aMS_AME_NODE_SPRITE.scale_x_end * size_rate;
		float num6 = aMS_AME_NODE_SPRITE.scale_y_end * size_rate;
		while (next != active_tail)
		{
			AMS_AME_RUNTIME_WORK_SIMPLE_SPRITE aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE = (AMS_AME_RUNTIME_WORK_SIMPLE_SPRITE)(AMS_AME_RUNTIME_WORK)next;
			aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.time += _am_unit_frame;
			float num7 = aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.time * num2;
			NNS_VECTOR4D amEffect_vel = _amEffect_vel;
			amVectorScale(amEffect_vel, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.velocity, _am_unit_time);
			amVectorAdd(aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.position, amEffect_vel);
			if (aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.time >= num)
			{
				if (aMS_AME_RUNTIME.spawn_runtime != null)
				{
					_amCreateSpawnParticle(aMS_AME_RUNTIME, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE);
				}
				amEffectDisconnectLink((AMS_AME_LIST)aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE);
				aMS_AME_RUNTIME.active_num--;
				amEffectFreeRuntimeWork(aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE);
			}
			else
			{
				float num8 = 1f - num7;
				float num9 = num3 * num8 + num5 * num7;
				float num10 = num4 * num8 + num6 * num7;
				Vector4D_Buf size = aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.size;
				aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.set_size(size.z * num9, size.z * num10, size.z, size.w);
				AMS_RGBA8888 pCO;
				amEffectLerpColor(out pCO, ref aMS_AME_NODE_SPRITE.color_start, ref aMS_AME_NODE_SPRITE.color_end, num7);
				pCO.a = (byte)(pCO.a * transparency >> 8);
				aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.set_color(pCO.color);
				if ((aMS_AME_NODE_SPRITE.flag & 0x8000) != 0)
				{
					AMS_AME_TEX_ANIM tex_anim = aMS_AME_NODE_SPRITE.tex_anim;
					if ((aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.flag & 2) == 0)
					{
						aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_time += _am_unit_frame;
						if (aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_time >= tex_anim.key_buf[aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_no].time)
						{
							aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_time = 0f;
							aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_no++;
							if (aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_no == tex_anim.key_num)
							{
								if ((aMS_AME_NODE_SPRITE.flag & 0x10000) != 0)
								{
									aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_no = 0;
								}
								else
								{
									aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_no = tex_anim.key_num - 1;
									aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.flag |= 2u;
								}
							}
						}
					}
					AMS_AME_TEX_ANIM_KEY aMS_AME_TEX_ANIM_KEY = tex_anim.key_buf[aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.tex_no];
					Vector4 vector = new Vector4(aMS_AME_TEX_ANIM_KEY.l, aMS_AME_TEX_ANIM_KEY.t, aMS_AME_TEX_ANIM_KEY.r, aMS_AME_TEX_ANIM_KEY.b);
					if ((aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.flag & 8) != 0)
					{
						float x = vector.X;
						vector.X = vector.Z;
						vector.Z = x;
					}
					if ((aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.flag & 0x10) != 0)
					{
						float y = vector.Y;
						vector.Y = vector.W;
						vector.W = y;
					}
					aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.set_st(vector.X, vector.Y, vector.Z, vector.W);
				}
				else if ((aMS_AME_NODE_SPRITE.flag & 0x4000) != 0)
				{
					float num11 = aMS_AME_NODE_SPRITE.scroll_u * _am_unit_time;
					float num12 = aMS_AME_NODE_SPRITE.scroll_v * _am_unit_time;
					if ((aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.flag & 8) != 0)
					{
						num11 = 0f - num11;
					}
					if ((aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.flag & 0x10) != 0)
					{
						num12 = 0f - num12;
					}
					Vector4D_Quat st = aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.st;
					Vector4 vector2 = new Vector4(st.x + num11, st.y + num12, st.z + num11, st.w + num12);
					aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.set_st(vector2.X, vector2.Y, vector2.Z, vector2.W);
				}
			}
			next = next.next;
		}
		return 0;
	}

	public static int _amDrawSimpleSprite(object r)
	{
		AMS_AME_RUNTIME aMS_AME_RUNTIME = (AMS_AME_RUNTIME)r;
		AMS_AME_NODE_SPRITE aMS_AME_NODE_SPRITE = (AMS_AME_NODE_SPRITE)aMS_AME_RUNTIME.node;
		AMS_AME_RUNTIME_WORK_SIMPLE_SPRITE aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE = (AMS_AME_RUNTIME_WORK_SIMPLE_SPRITE)(AMS_AME_RUNTIME_WORK)aMS_AME_RUNTIME.active_head.next;
		AMS_AME_LIST next = aMS_AME_RUNTIME.active_head.next;
		AMS_AME_LIST active_tail = aMS_AME_RUNTIME.active_tail;
		AMS_PARAM_DRAW_PRIMITIVE aMS_PARAM_DRAW_PRIMITIVE = amDrawAlloc_AMS_PARAM_DRAW_PRIMITIVE();
		int ablend = _amEffectSetDrawMode(aMS_AME_RUNTIME, aMS_PARAM_DRAW_PRIMITIVE, aMS_AME_NODE_SPRITE.blend);
		SNNS_VECTOR pDst = default(SNNS_VECTOR);
		SNNS_VECTOR pDst2 = default(SNNS_VECTOR);
		SNNS_VECTOR pDst3 = default(SNNS_VECTOR);
		float z_bias = aMS_AME_NODE_SPRITE.z_bias;
		amVectorSet(ref pDst, z_bias * _am_ef_worldViewMtx.M20, z_bias * _am_ef_worldViewMtx.M21, z_bias * _am_ef_worldViewMtx.M22);
		amVectorSet(ref pDst2, _am_ef_worldViewMtx.M10, _am_ef_worldViewMtx.M11, _am_ef_worldViewMtx.M12);
		amVectorSet(ref pDst3, _am_ef_worldViewMtx.M00, _am_ef_worldViewMtx.M01, _am_ef_worldViewMtx.M02);
		SNNS_VECTOR pDst4 = default(SNNS_VECTOR);
		SNNS_VECTOR dst = default(SNNS_VECTOR);
		SNNS_VECTOR dst2 = default(SNNS_VECTOR);
		if ((aMS_AME_NODE_SPRITE.flag & 0x1000) != 0)
		{
			NNS_PRIM3D_PCT_ARRAY nNS_PRIM3D_PCT_ARRAY = amDrawAlloc_NNS_PRIM3D_PCT(6 * aMS_AME_RUNTIME.active_num);
			NNS_PRIM3D_PCT[] buffer = nNS_PRIM3D_PCT_ARRAY.buffer;
			int num = nNS_PRIM3D_PCT_ARRAY.offset;
			float sortZ = 0f;
			while (next != active_tail)
			{
				aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE = (AMS_AME_RUNTIME_WORK_SIMPLE_SPRITE)(AMS_AME_RUNTIME_WORK)next;
				nnScaleVector(ref dst, ref pDst3, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.size.y);
				nnScaleVector(ref dst2, ref pDst2, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.size.x);
				amVectorAdd(ref pDst4, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.position, ref pDst);
				sortZ = nnDistanceVector(ref pDst4, _am_ef_camPos);
				nnSubtractVector(ref buffer[num + 2].Pos, ref pDst4, ref dst);
				nnAddVector(ref buffer[num + 2].Pos, ref buffer[num + 2].Pos, ref dst2);
				nnAddVector(ref buffer[num].Pos, ref pDst4, ref dst);
				nnAddVector(ref buffer[num].Pos, ref buffer[num].Pos, ref dst2);
				nnSubtractVector(ref buffer[num + 5].Pos, ref pDst4, ref dst);
				nnSubtractVector(ref buffer[num + 5].Pos, ref buffer[num + 5].Pos, ref dst2);
				nnAddVector(ref buffer[num + 1].Pos, ref pDst4, ref dst);
				nnSubtractVector(ref buffer[num + 1].Pos, ref buffer[num + 1].Pos, ref dst2);
				buffer[num + 5].Col = AMD_RGBA8888(aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.color.r, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.color.g, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.color.b, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.color.a);
				buffer[num].Col = (buffer[num + 1].Col = (buffer[num + 2].Col = buffer[num + 5].Col));
				Vector4D_Quat st = aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.st;
				buffer[num].Tex.u = st.x;
				buffer[num].Tex.v = st.y;
				buffer[num + 1].Tex.u = st.z;
				buffer[num + 1].Tex.v = st.y;
				buffer[num + 2].Tex.u = st.x;
				buffer[num + 2].Tex.v = st.w;
				buffer[num + 5].Tex.u = st.z;
				buffer[num + 5].Tex.v = st.w;
				buffer[num + 3] = buffer[num + 1];
				buffer[num + 4] = buffer[num + 2];
				num += 6;
				next = next.next;
			}
			aMS_PARAM_DRAW_PRIMITIVE.format3D = 4;
			aMS_PARAM_DRAW_PRIMITIVE.type = 0;
			aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D = nNS_PRIM3D_PCT_ARRAY;
			aMS_PARAM_DRAW_PRIMITIVE.texlist = aMS_AME_RUNTIME.texlist;
			aMS_PARAM_DRAW_PRIMITIVE.texId = aMS_AME_NODE_SPRITE.texture_id;
			aMS_PARAM_DRAW_PRIMITIVE.count = 6 * aMS_AME_RUNTIME.active_num;
			aMS_PARAM_DRAW_PRIMITIVE.ablend = ablend;
			aMS_PARAM_DRAW_PRIMITIVE.sortZ = sortZ;
			amDrawPrimitive3D(aMS_AME_RUNTIME.ecb.drawState, aMS_PARAM_DRAW_PRIMITIVE);
		}
		else
		{
			NNS_PRIM3D_PC[] array = amDrawAlloc_NNS_PRIM3D_PC(6 * aMS_AME_RUNTIME.active_num);
			int num2 = 0;
			NNS_PRIM3D_PC[] vtxPC3D = array;
			float sortZ2 = 0f;
			while (next != active_tail)
			{
				aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE = (AMS_AME_RUNTIME_WORK_SIMPLE_SPRITE)(AMS_AME_RUNTIME_WORK)next;
				nnScaleVector(ref dst, ref pDst3, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.size.x);
				nnScaleVector(ref dst2, ref pDst2, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.size.y);
				amVectorAdd(ref pDst4, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.position, ref pDst);
				sortZ2 = nnDistanceVector(ref pDst4, _am_ef_camPos);
				nnSubtractVector(ref array[num2 + 2].Pos, ref pDst4, ref dst);
				nnAddVector(ref array[num2 + 2].Pos, ref array[num2 + 2].Pos, ref dst2);
				nnAddVector(ref array[num2].Pos, ref pDst4, ref dst);
				nnAddVector(ref array[num2].Pos, ref array[num2].Pos, ref dst2);
				nnSubtractVector(ref array[num2 + 5].Pos, ref pDst4, ref dst);
				nnSubtractVector(ref array[num2 + 5].Pos, ref array[num2 + 5].Pos, ref dst2);
				nnAddVector(ref array[num2 + 1].Pos, ref pDst4, ref dst);
				nnSubtractVector(ref array[num2 + 1].Pos, ref array[num2 + 1].Pos, ref dst2);
				array[num2 + 5].Col = AMD_RGBA8888(aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.color.r, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.color.g, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.color.b, aMS_AME_RUNTIME_WORK_SIMPLE_SPRITE.color.a);
				array[num2].Col = (array[num2 + 1].Col = (array[num2 + 2].Col = array[num2 + 5].Col));
				array[num2 + 3] = array[num2 + 1];
				array[num2 + 4] = array[num2 + 2];
				num2 += 6;
				next = next.next;
			}
			aMS_PARAM_DRAW_PRIMITIVE.format3D = 2;
			aMS_PARAM_DRAW_PRIMITIVE.type = 0;
			aMS_PARAM_DRAW_PRIMITIVE.vtxPC3D = vtxPC3D;
			aMS_PARAM_DRAW_PRIMITIVE.texlist = aMS_AME_RUNTIME.texlist;
			aMS_PARAM_DRAW_PRIMITIVE.texId = -1;
			aMS_PARAM_DRAW_PRIMITIVE.count = 6 * aMS_AME_RUNTIME.active_num;
			aMS_PARAM_DRAW_PRIMITIVE.ablend = ablend;
			aMS_PARAM_DRAW_PRIMITIVE.sortZ = sortZ2;
			amDrawPrimitive3D(aMS_AME_RUNTIME.ecb.drawState, aMS_PARAM_DRAW_PRIMITIVE);
		}
		return 0;
	}

	public static int _amInitSprite(object p)
	{
		AMS_AME_CREATE_PARAM aMS_AME_CREATE_PARAM = (AMS_AME_CREATE_PARAM)p;
		AMS_AME_NODE_SPRITE aMS_AME_NODE_SPRITE = (AMS_AME_NODE_SPRITE)aMS_AME_CREATE_PARAM.node;
		AMS_AME_RUNTIME_WORK_SPRITE aMS_AME_RUNTIME_WORK_SPRITE = (AMS_AME_RUNTIME_WORK_SPRITE)aMS_AME_CREATE_PARAM.work;
		aMS_AME_RUNTIME_WORK_SPRITE.time = 0f - aMS_AME_NODE_SPRITE.start_time;
		AMS_RGBA8888 color_start = aMS_AME_NODE_SPRITE.color_start;
		color_start.color = aMS_AME_NODE_SPRITE.color_start.color;
		color_start.a = (byte)(color_start.a * aMS_AME_CREATE_PARAM.ecb.transparency >> 8);
		aMS_AME_RUNTIME_WORK_SPRITE.set_color(color_start.color);
		amVectorAdd(aMS_AME_RUNTIME_WORK_SPRITE.position, aMS_AME_CREATE_PARAM.parent_position, aMS_AME_CREATE_PARAM.position);
		amVectorAdd(aMS_AME_RUNTIME_WORK_SPRITE.position, aMS_AME_NODE_SPRITE.translate);
		amVectorScale(aMS_AME_RUNTIME_WORK_SPRITE.velocity, aMS_AME_CREATE_PARAM.parent_velocity, aMS_AME_NODE_SPRITE.inheritance_rate);
		amVectorAdd(aMS_AME_RUNTIME_WORK_SPRITE.velocity, aMS_AME_CREATE_PARAM.velocity);
		float num = aMS_AME_NODE_SPRITE.size + aMS_AME_NODE_SPRITE.size_chaos * nnRandom();
		aMS_AME_RUNTIME_WORK_SPRITE.set_size(num * aMS_AME_NODE_SPRITE.scale_x_start, num * aMS_AME_NODE_SPRITE.scale_x_start, num, 0f);
		aMS_AME_RUNTIME_WORK_SPRITE.twist = aMS_AME_NODE_SPRITE.twist_angle + aMS_AME_NODE_SPRITE.twist_angle_chaos * nnRandom();
		if ((aMS_AME_NODE_SPRITE.flag & 4) != 0 && nnRandom() > 0.5f)
		{
			aMS_AME_RUNTIME_WORK_SPRITE.flag |= 4u;
		}
		if ((aMS_AME_RUNTIME_WORK_SPRITE.flag & 4) != 0)
		{
			aMS_AME_RUNTIME_WORK_SPRITE.twist_speed = 0f - aMS_AME_NODE_SPRITE.twist_angle_speed;
		}
		else
		{
			aMS_AME_RUNTIME_WORK_SPRITE.twist_speed = aMS_AME_NODE_SPRITE.twist_angle_speed;
		}
		if ((aMS_AME_NODE_SPRITE.flag & 0x8000) != 0)
		{
			aMS_AME_RUNTIME_WORK_SPRITE.tex_time = 0f;
			aMS_AME_RUNTIME_WORK_SPRITE.tex_no = 0;
			if ((aMS_AME_NODE_SPRITE.flag & 0x80000) != 0)
			{
				aMS_AME_RUNTIME_WORK_SPRITE.tex_no = (int)(100f * nnRandom()) % aMS_AME_NODE_SPRITE.tex_anim.key_num;
			}
			AMS_AME_TEX_ANIM_KEY aMS_AME_TEX_ANIM_KEY = aMS_AME_NODE_SPRITE.tex_anim.key_buf[aMS_AME_RUNTIME_WORK_SPRITE.tex_no];
			aMS_AME_RUNTIME_WORK_SPRITE.set_st(aMS_AME_TEX_ANIM_KEY.l, aMS_AME_TEX_ANIM_KEY.t, aMS_AME_TEX_ANIM_KEY.r, aMS_AME_TEX_ANIM_KEY.b);
		}
		else if ((aMS_AME_NODE_SPRITE.flag & 0x2000) != 0)
		{
			aMS_AME_RUNTIME_WORK_SPRITE.set_st(aMS_AME_NODE_SPRITE.cropping_l, aMS_AME_NODE_SPRITE.cropping_t, aMS_AME_NODE_SPRITE.cropping_r, aMS_AME_NODE_SPRITE.cropping_b);
		}
		else
		{
			aMS_AME_RUNTIME_WORK_SPRITE.set_st(0f, 0f, 1f, 1f);
		}
		if ((aMS_AME_NODE_SPRITE.flag & 0x100000) != 0 || ((aMS_AME_NODE_SPRITE.flag & 0x20000) != 0 && nnRandom() > 0.5f))
		{
			aMS_AME_RUNTIME_WORK_SPRITE.flag |= 8u;
			aMS_AME_RUNTIME_WORK_SPRITE.set_st(aMS_AME_RUNTIME_WORK_SPRITE.st.z, aMS_AME_RUNTIME_WORK_SPRITE.st.y, aMS_AME_RUNTIME_WORK_SPRITE.st.x, aMS_AME_RUNTIME_WORK_SPRITE.st.w);
		}
		if ((aMS_AME_NODE_SPRITE.flag & 0x200000) != 0 || ((aMS_AME_NODE_SPRITE.flag & 0x40000) != 0 && nnRandom() > 0.5f))
		{
			aMS_AME_RUNTIME_WORK_SPRITE.flag |= 16u;
			aMS_AME_RUNTIME_WORK_SPRITE.set_st(aMS_AME_RUNTIME_WORK_SPRITE.st.x, aMS_AME_RUNTIME_WORK_SPRITE.st.w, aMS_AME_RUNTIME_WORK_SPRITE.st.z, aMS_AME_RUNTIME_WORK_SPRITE.st.y);
		}
		return 0;
	}

	public static int _amUpdateSprite(object r)
	{
		AMS_AME_RUNTIME aMS_AME_RUNTIME = (AMS_AME_RUNTIME)r;
		AMS_AME_NODE_SPRITE aMS_AME_NODE_SPRITE = (AMS_AME_NODE_SPRITE)aMS_AME_RUNTIME.node;
		AMS_AME_LIST active_tail = aMS_AME_RUNTIME.active_tail;
		AMS_AME_LIST next = aMS_AME_RUNTIME.active_head.next;
		int transparency = aMS_AME_RUNTIME.ecb.transparency;
		float num;
		float num2;
		if (aMS_AME_NODE_SPRITE.life >= 0f)
		{
			num = aMS_AME_NODE_SPRITE.life;
			num2 = 1f / num;
		}
		else
		{
			num = float.MaxValue;
			num2 = 0f;
		}
		float size_rate = aMS_AME_RUNTIME.ecb.size_rate;
		float num3 = aMS_AME_NODE_SPRITE.scale_x_start * size_rate;
		float num4 = aMS_AME_NODE_SPRITE.scale_y_start * size_rate;
		float num5 = aMS_AME_NODE_SPRITE.scale_x_end * size_rate;
		float num6 = aMS_AME_NODE_SPRITE.scale_y_end * size_rate;
		NNS_VECTOR4D nNS_VECTOR4D = GlobalPool<NNS_VECTOR4D>.Alloc();
		while (next != active_tail)
		{
			AMS_AME_RUNTIME_WORK_SPRITE aMS_AME_RUNTIME_WORK_SPRITE = (AMS_AME_RUNTIME_WORK_SPRITE)(AMS_AME_RUNTIME_WORK)next;
			aMS_AME_RUNTIME_WORK_SPRITE.time += _am_unit_frame;
			float num7 = aMS_AME_RUNTIME_WORK_SPRITE.time * num2;
			amVectorScale(nNS_VECTOR4D, aMS_AME_RUNTIME_WORK_SPRITE.velocity, _am_unit_time);
			amVectorAdd(aMS_AME_RUNTIME_WORK_SPRITE.position, nNS_VECTOR4D);
			if (aMS_AME_RUNTIME_WORK_SPRITE.time >= num)
			{
				if (aMS_AME_RUNTIME.spawn_runtime != null)
				{
					_amCreateSpawnParticle(aMS_AME_RUNTIME, aMS_AME_RUNTIME_WORK_SPRITE);
				}
				amEffectDisconnectLink((AMS_AME_LIST)aMS_AME_RUNTIME_WORK_SPRITE);
				aMS_AME_RUNTIME.active_num--;
				amEffectFreeRuntimeWork(aMS_AME_RUNTIME_WORK_SPRITE);
			}
			else
			{
				float num8 = 1f - num7;
				float num9 = num3 * num8 + num5 * num7;
				float num10 = num4 * num8 + num6 * num7;
				aMS_AME_RUNTIME_WORK_SPRITE.set_size(aMS_AME_RUNTIME_WORK_SPRITE.size.z * num9, aMS_AME_RUNTIME_WORK_SPRITE.size.z * num10, aMS_AME_RUNTIME_WORK_SPRITE.size.z, aMS_AME_RUNTIME_WORK_SPRITE.size.w);
				aMS_AME_RUNTIME_WORK_SPRITE.twist += aMS_AME_RUNTIME_WORK_SPRITE.twist_speed * _am_unit_time;
				AMS_RGBA8888 pCO;
				amEffectLerpColor(out pCO, ref aMS_AME_NODE_SPRITE.color_start, ref aMS_AME_NODE_SPRITE.color_end, num7);
				pCO.a = (byte)(pCO.a * transparency >> 8);
				aMS_AME_RUNTIME_WORK_SPRITE.set_color(pCO.color);
				if ((aMS_AME_NODE_SPRITE.flag & 0x8000) != 0)
				{
					AMS_AME_TEX_ANIM tex_anim = aMS_AME_NODE_SPRITE.tex_anim;
					if ((aMS_AME_RUNTIME_WORK_SPRITE.flag & 2) == 0)
					{
						aMS_AME_RUNTIME_WORK_SPRITE.tex_time += _am_unit_frame;
						if (aMS_AME_RUNTIME_WORK_SPRITE.tex_time >= tex_anim.key_buf[aMS_AME_RUNTIME_WORK_SPRITE.tex_no].time)
						{
							aMS_AME_RUNTIME_WORK_SPRITE.tex_time = 0f;
							aMS_AME_RUNTIME_WORK_SPRITE.tex_no++;
							if (aMS_AME_RUNTIME_WORK_SPRITE.tex_no == tex_anim.key_num)
							{
								if ((aMS_AME_NODE_SPRITE.flag & 0x10000) != 0)
								{
									aMS_AME_RUNTIME_WORK_SPRITE.tex_no = 0;
								}
								else
								{
									aMS_AME_RUNTIME_WORK_SPRITE.tex_no = tex_anim.key_num - 1;
									aMS_AME_RUNTIME_WORK_SPRITE.flag |= 2u;
								}
							}
						}
					}
					AMS_AME_TEX_ANIM_KEY aMS_AME_TEX_ANIM_KEY = tex_anim.key_buf[aMS_AME_RUNTIME_WORK_SPRITE.tex_no];
					aMS_AME_RUNTIME_WORK_SPRITE.set_st(aMS_AME_TEX_ANIM_KEY.l, aMS_AME_TEX_ANIM_KEY.t, aMS_AME_TEX_ANIM_KEY.r, aMS_AME_TEX_ANIM_KEY.b);
					if ((aMS_AME_RUNTIME_WORK_SPRITE.flag & 8) != 0)
					{
						aMS_AME_RUNTIME_WORK_SPRITE.set_st(aMS_AME_RUNTIME_WORK_SPRITE.st.z, aMS_AME_RUNTIME_WORK_SPRITE.st.y, aMS_AME_RUNTIME_WORK_SPRITE.st.x, aMS_AME_RUNTIME_WORK_SPRITE.st.w);
					}
					if ((aMS_AME_RUNTIME_WORK_SPRITE.flag & 0x10) != 0)
					{
						aMS_AME_RUNTIME_WORK_SPRITE.set_st(aMS_AME_RUNTIME_WORK_SPRITE.st.x, aMS_AME_RUNTIME_WORK_SPRITE.st.w, aMS_AME_RUNTIME_WORK_SPRITE.st.z, aMS_AME_RUNTIME_WORK_SPRITE.st.y);
					}
				}
				else if ((aMS_AME_NODE_SPRITE.flag & 0x4000) != 0)
				{
					float num11 = aMS_AME_NODE_SPRITE.scroll_u * _am_unit_time;
					float num12 = aMS_AME_NODE_SPRITE.scroll_v * _am_unit_time;
					if ((aMS_AME_RUNTIME_WORK_SPRITE.flag & 8) != 0)
					{
						num11 = 0f - num11;
					}
					if ((aMS_AME_RUNTIME_WORK_SPRITE.flag & 0x10) != 0)
					{
						num12 = 0f - num12;
					}
					aMS_AME_RUNTIME_WORK_SPRITE.set_st(aMS_AME_RUNTIME_WORK_SPRITE.st.x + num11, aMS_AME_RUNTIME_WORK_SPRITE.st.y + num12, aMS_AME_RUNTIME_WORK_SPRITE.st.z + num11, aMS_AME_RUNTIME_WORK_SPRITE.st.w + num12);
				}
			}
			next = next.next;
		}
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D);
		return 0;
	}

	public static int _amDrawSprite(object r)
	{
		AMS_AME_RUNTIME aMS_AME_RUNTIME = (AMS_AME_RUNTIME)r;
		AMS_AME_NODE_SPRITE aMS_AME_NODE_SPRITE = (AMS_AME_NODE_SPRITE)aMS_AME_RUNTIME.node;
		AMS_AME_LIST next = aMS_AME_RUNTIME.active_head.next;
		AMS_AME_LIST active_tail = aMS_AME_RUNTIME.active_tail;
		AMS_PARAM_DRAW_PRIMITIVE aMS_PARAM_DRAW_PRIMITIVE = GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Alloc();
		int ablend = _amEffectSetDrawMode(aMS_AME_RUNTIME, aMS_PARAM_DRAW_PRIMITIVE, aMS_AME_NODE_SPRITE.blend);
		SNNS_VECTOR pDst = default(SNNS_VECTOR);
		SNNS_VECTOR pDst2 = default(SNNS_VECTOR);
		SNNS_VECTOR pDst3 = default(SNNS_VECTOR);
		float z_bias = aMS_AME_NODE_SPRITE.z_bias;
		amVectorSet(ref pDst, z_bias * _am_ef_worldViewMtx.M20, z_bias * _am_ef_worldViewMtx.M21, z_bias * _am_ef_worldViewMtx.M22);
		amVectorSet(ref pDst2, _am_ef_worldViewMtx.M10, _am_ef_worldViewMtx.M11, _am_ef_worldViewMtx.M12);
		amVectorSet(ref pDst3, _am_ef_worldViewMtx.M00, _am_ef_worldViewMtx.M01, _am_ef_worldViewMtx.M02);
		SNNS_VECTOR pDst4 = default(SNNS_VECTOR);
		SNNS_VECTOR pDst5 = default(SNNS_VECTOR);
		SNNS_VECTOR pDst6 = default(SNNS_VECTOR);
		if ((aMS_AME_NODE_SPRITE.flag & 0x1000) != 0)
		{
			NNS_PRIM3D_PCT_ARRAY nNS_PRIM3D_PCT_ARRAY = amDrawAlloc_NNS_PRIM3D_PCT(6 * aMS_AME_RUNTIME.active_num);
			NNS_PRIM3D_PCT[] buffer = nNS_PRIM3D_PCT_ARRAY.buffer;
			int num = nNS_PRIM3D_PCT_ARRAY.offset;
			float sortZ = 0f;
			while (next != active_tail)
			{
				AMS_AME_RUNTIME_WORK_SPRITE aMS_AME_RUNTIME_WORK_SPRITE = (AMS_AME_RUNTIME_WORK_SPRITE)(AMS_AME_RUNTIME_WORK)next;
				float pSn;
				float pCs;
				amSinCos(aMS_AME_RUNTIME_WORK_SPRITE.twist, out pSn, out pCs);
				amVectorGetAverage(ref pDst5, ref pDst3, ref pDst2, pCs, 0f - pSn);
				amVectorGetAverage(ref pDst6, ref pDst3, ref pDst2, pSn, pCs);
				nnScaleVector(ref pDst5, ref pDst5, aMS_AME_RUNTIME_WORK_SPRITE.size.x);
				nnScaleVector(ref pDst6, ref pDst6, aMS_AME_RUNTIME_WORK_SPRITE.size.y);
				amVectorAdd(ref pDst4, aMS_AME_RUNTIME_WORK_SPRITE.position, ref pDst);
				sortZ = nnDistanceVector(ref pDst4, _am_ef_camPos);
				nnSubtractVector(ref buffer[num].Pos, ref pDst4, ref pDst5);
				nnAddVector(ref buffer[num].Pos, ref buffer[num].Pos, ref pDst6);
				nnAddVector(ref buffer[num + 1].Pos, ref pDst4, ref pDst5);
				nnAddVector(ref buffer[num + 1].Pos, ref buffer[num + 1].Pos, ref pDst6);
				nnSubtractVector(ref buffer[num + 2].Pos, ref pDst4, ref pDst5);
				nnSubtractVector(ref buffer[num + 2].Pos, ref buffer[num + 2].Pos, ref pDst6);
				nnAddVector(ref buffer[num + 5].Pos, ref pDst4, ref pDst5);
				nnSubtractVector(ref buffer[num + 5].Pos, ref buffer[num + 5].Pos, ref pDst6);
				buffer[num + 5].Col = AMD_RGBA8888(aMS_AME_RUNTIME_WORK_SPRITE.color.r, aMS_AME_RUNTIME_WORK_SPRITE.color.g, aMS_AME_RUNTIME_WORK_SPRITE.color.b, aMS_AME_RUNTIME_WORK_SPRITE.color.a);
				buffer[num].Col = (buffer[num + 1].Col = (buffer[num + 2].Col = buffer[num + 5].Col));
				buffer[num].Tex.u = aMS_AME_RUNTIME_WORK_SPRITE.st.x;
				buffer[num].Tex.v = aMS_AME_RUNTIME_WORK_SPRITE.st.y;
				buffer[num + 1].Tex.u = aMS_AME_RUNTIME_WORK_SPRITE.st.z;
				buffer[num + 1].Tex.v = aMS_AME_RUNTIME_WORK_SPRITE.st.y;
				buffer[num + 2].Tex.u = aMS_AME_RUNTIME_WORK_SPRITE.st.x;
				buffer[num + 2].Tex.v = aMS_AME_RUNTIME_WORK_SPRITE.st.w;
				buffer[num + 5].Tex.u = aMS_AME_RUNTIME_WORK_SPRITE.st.z;
				buffer[num + 5].Tex.v = aMS_AME_RUNTIME_WORK_SPRITE.st.w;
				buffer[num + 3] = buffer[num + 1];
				buffer[num + 4] = buffer[num + 2];
				num += 6;
				next = next.next;
			}
			aMS_PARAM_DRAW_PRIMITIVE.format3D = 4;
			aMS_PARAM_DRAW_PRIMITIVE.type = 0;
			aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D = nNS_PRIM3D_PCT_ARRAY;
			aMS_PARAM_DRAW_PRIMITIVE.texlist = aMS_AME_RUNTIME.texlist;
			aMS_PARAM_DRAW_PRIMITIVE.texId = aMS_AME_NODE_SPRITE.texture_id;
			aMS_PARAM_DRAW_PRIMITIVE.count = 6 * aMS_AME_RUNTIME.active_num;
			aMS_PARAM_DRAW_PRIMITIVE.ablend = ablend;
			aMS_PARAM_DRAW_PRIMITIVE.sortZ = sortZ;
			amDrawPrimitive3D(aMS_AME_RUNTIME.ecb.drawState, aMS_PARAM_DRAW_PRIMITIVE);
		}
		else
		{
			NNS_PRIM3D_PC[] array = amDrawAlloc_NNS_PRIM3D_PC(6 * aMS_AME_RUNTIME.active_num);
			int num2 = 0;
			NNS_PRIM3D_PC[] vtxPC3D = array;
			float sortZ2 = 0f;
			while (next != active_tail)
			{
				AMS_AME_RUNTIME_WORK_SPRITE aMS_AME_RUNTIME_WORK_SPRITE = (AMS_AME_RUNTIME_WORK_SPRITE)(AMS_AME_RUNTIME_WORK)next;
				float pSn2;
				float pCs2;
				amSinCos(aMS_AME_RUNTIME_WORK_SPRITE.twist, out pSn2, out pCs2);
				amVectorGetAverage(ref pDst5, ref pDst3, ref pDst2, pCs2, 0f - pSn2);
				amVectorGetAverage(ref pDst6, ref pDst3, ref pDst2, pSn2, pCs2);
				nnScaleVector(ref pDst5, ref pDst5, aMS_AME_RUNTIME_WORK_SPRITE.size.x);
				nnScaleVector(ref pDst6, ref pDst6, aMS_AME_RUNTIME_WORK_SPRITE.size.y);
				amVectorAdd(ref pDst4, aMS_AME_RUNTIME_WORK_SPRITE.position, ref pDst);
				sortZ2 = nnDistanceVector(ref pDst4, _am_ef_camPos);
				nnSubtractVector(ref array[num2].Pos, ref pDst4, ref pDst5);
				nnAddVector(ref array[num2].Pos, ref array[num2].Pos, ref pDst6);
				nnAddVector(ref array[num2 + 1].Pos, ref pDst4, ref pDst5);
				nnAddVector(ref array[num2 + 1].Pos, ref array[num2 + 1].Pos, ref pDst6);
				nnSubtractVector(ref array[num2 + 2].Pos, ref pDst4, ref pDst5);
				nnSubtractVector(ref array[num2 + 2].Pos, ref array[num2 + 2].Pos, ref pDst6);
				nnAddVector(ref array[num2 + 5].Pos, ref pDst4, ref pDst5);
				nnSubtractVector(ref array[num2 + 5].Pos, ref array[num2 + 5].Pos, ref pDst6);
				array[num2 + 5].Col = AMD_RGBA8888(aMS_AME_RUNTIME_WORK_SPRITE.color.r, aMS_AME_RUNTIME_WORK_SPRITE.color.g, aMS_AME_RUNTIME_WORK_SPRITE.color.b, aMS_AME_RUNTIME_WORK_SPRITE.color.a);
				array[num2].Col = (array[num2 + 1].Col = (array[num2 + 2].Col = array[num2 + 5].Col));
				array[num2 + 3] = array[num2 + 1];
				array[num2 + 4] = array[num2 + 2];
				num2 += 6;
				next = next.next;
			}
			aMS_PARAM_DRAW_PRIMITIVE.format3D = 2;
			aMS_PARAM_DRAW_PRIMITIVE.type = 0;
			aMS_PARAM_DRAW_PRIMITIVE.vtxPC3D = vtxPC3D;
			aMS_PARAM_DRAW_PRIMITIVE.texlist = aMS_AME_RUNTIME.texlist;
			aMS_PARAM_DRAW_PRIMITIVE.texId = -1;
			aMS_PARAM_DRAW_PRIMITIVE.count = 6 * aMS_AME_RUNTIME.active_num;
			aMS_PARAM_DRAW_PRIMITIVE.ablend = ablend;
			aMS_PARAM_DRAW_PRIMITIVE.sortZ = sortZ2;
			amDrawPrimitive3D(aMS_AME_RUNTIME.ecb.drawState, aMS_PARAM_DRAW_PRIMITIVE);
		}
		GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Release(aMS_PARAM_DRAW_PRIMITIVE);
		return 0;
	}

	public static int _amInitLine(object p)
	{
