		aMS_AME_RUNTIME_WORK_LINE.set_outside_color(inside_color_start.color);
		amVectorAdd(aMS_AME_RUNTIME_WORK_LINE.position, aMS_AME_CREATE_PARAM.parent_position, aMS_AME_CREATE_PARAM.position);
		amVectorAdd(aMS_AME_RUNTIME_WORK_LINE.position, aMS_AME_NODE_LINE.translate);
		amVectorScale(aMS_AME_RUNTIME_WORK_LINE.velocity, aMS_AME_CREATE_PARAM.parent_velocity, aMS_AME_NODE_LINE.inheritance_rate);
		amVectorAdd(aMS_AME_RUNTIME_WORK_LINE.velocity, aMS_AME_CREATE_PARAM.velocity);
		if ((aMS_AME_NODE_LINE.flag & 0x8000) != 0)
		{
			aMS_AME_RUNTIME_WORK_LINE.tex_time = 0f;
			aMS_AME_RUNTIME_WORK_LINE.tex_no = 0;
			if ((aMS_AME_NODE_LINE.flag & 0x80000) != 0)
			{
				aMS_AME_RUNTIME_WORK_LINE.tex_no = (int)(100f * nnRandom()) % aMS_AME_NODE_LINE.tex_anim.key_num;
			}
			AMS_AME_TEX_ANIM_KEY aMS_AME_TEX_ANIM_KEY = aMS_AME_NODE_LINE.tex_anim.key_buf[aMS_AME_RUNTIME_WORK_LINE.tex_no];
			aMS_AME_RUNTIME_WORK_LINE.set_st(aMS_AME_TEX_ANIM_KEY.l, aMS_AME_TEX_ANIM_KEY.t, aMS_AME_TEX_ANIM_KEY.r, aMS_AME_TEX_ANIM_KEY.b);
		}
		else if ((aMS_AME_NODE_LINE.flag & 0x2000) != 0)
		{
			aMS_AME_RUNTIME_WORK_LINE.set_st(aMS_AME_NODE_LINE.cropping_l, aMS_AME_NODE_LINE.cropping_t, aMS_AME_NODE_LINE.cropping_r, aMS_AME_NODE_LINE.cropping_b);
		}
		else
		{
			aMS_AME_RUNTIME_WORK_LINE.set_st(0f, 0f, 1f, 1f);
		}
		if ((aMS_AME_NODE_LINE.flag & 0x100000) != 0 || ((aMS_AME_NODE_LINE.flag & 0x20000) != 0 && nnRandom() > 0.5f))
		{
			aMS_AME_RUNTIME_WORK_LINE.flag |= 8u;
			aMS_AME_RUNTIME_WORK_LINE.set_st(aMS_AME_RUNTIME_WORK_LINE.st.z, aMS_AME_RUNTIME_WORK_LINE.st.y, aMS_AME_RUNTIME_WORK_LINE.st.x, aMS_AME_RUNTIME_WORK_LINE.st.w);
		}
