		amVectorAdd(aMS_AME_RUNTIME_WORK_MODEL.position, aMS_AME_NODE_MODEL.translate);
		amVectorScale(aMS_AME_RUNTIME_WORK_MODEL.velocity, aMS_AME_CREATE_PARAM.parent_velocity, aMS_AME_NODE_MODEL.inheritance_rate);
		amVectorAdd(aMS_AME_RUNTIME_WORK_MODEL.velocity, aMS_AME_CREATE_PARAM.velocity);
