			amVectorRandom(nNS_VECTOR4D);
			NNS_QUATERNION pQuat = aMS_AME_RUNTIME_WORK_MODEL.rotate;
			amQuatRotAxisToQuat(ref pQuat, nNS_VECTOR4D, nnRandom() * 2f * (float)Math.PI);
			aMS_AME_RUNTIME_WORK_MODEL.rotate = pQuat;
