	public static int _amUpdateModel(object r)
	{
		AMS_AME_RUNTIME aMS_AME_RUNTIME = (AMS_AME_RUNTIME)r;
		AMS_AME_NODE_MODEL aMS_AME_NODE_MODEL = (AMS_AME_NODE_MODEL)aMS_AME_RUNTIME.node;
		AMS_AME_RUNTIME_WORK_MODEL aMS_AME_RUNTIME_WORK_MODEL = (AMS_AME_RUNTIME_WORK_MODEL)(AMS_AME_RUNTIME_WORK)aMS_AME_RUNTIME.active_head.next;
		AMS_AME_LIST next = aMS_AME_RUNTIME.active_head.next;
		AMS_AME_LIST active_tail = aMS_AME_RUNTIME.active_tail;
		int transparency = aMS_AME_RUNTIME.ecb.transparency;
		float num;
		float num2;
		if (aMS_AME_NODE_MODEL.life >= 0f)
		{
			num = aMS_AME_NODE_MODEL.life;
			num2 = 1f / num;
		}
		else
		{
			num = float.MaxValue;
			num2 = 0f;
		}
		NNS_VECTOR4D nNS_VECTOR4D = GlobalPool<NNS_VECTOR4D>.Alloc();
		NNS_VECTOR4D nNS_VECTOR4D2 = GlobalPool<NNS_VECTOR4D>.Alloc();
		amVectorScale(nNS_VECTOR4D, aMS_AME_NODE_MODEL.scale_start, aMS_AME_RUNTIME.ecb.size_rate);
		amVectorScale(nNS_VECTOR4D2, aMS_AME_NODE_MODEL.scale_end, aMS_AME_RUNTIME.ecb.size_rate);
		while (next != active_tail)
		{
			aMS_AME_RUNTIME_WORK_MODEL = (AMS_AME_RUNTIME_WORK_MODEL)(AMS_AME_RUNTIME_WORK)next;
			aMS_AME_RUNTIME_WORK_MODEL.time += _am_unit_frame;
			float num3 = aMS_AME_RUNTIME_WORK_MODEL.time * num2;
			NNS_VECTOR4D nNS_VECTOR4D3 = GlobalPool<NNS_VECTOR4D>.Alloc();
			amVectorScale(nNS_VECTOR4D3, aMS_AME_RUNTIME_WORK_MODEL.velocity, _am_unit_time);
			amVectorAdd(aMS_AME_RUNTIME_WORK_MODEL.position, nNS_VECTOR4D3);
			GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D3);
			if (aMS_AME_RUNTIME_WORK_MODEL.time >= num)
			{
				if (aMS_AME_RUNTIME.spawn_runtime != null)
				{
					_amCreateSpawnParticle(aMS_AME_RUNTIME, aMS_AME_RUNTIME_WORK_MODEL);
				}
				amEffectDisconnectLink((AMS_AME_LIST)aMS_AME_RUNTIME_WORK_MODEL);
				aMS_AME_RUNTIME.active_num--;
				amEffectFreeRuntimeWork(aMS_AME_RUNTIME_WORK_MODEL);
			}
			else
			{
				NNS_QUATERNION pQuat = default(NNS_QUATERNION);
				NNS_VECTOR4D nNS_VECTOR4D4 = GlobalPool<NNS_VECTOR4D>.Alloc();
				Vector4D_Buf rotate_axis = aMS_AME_RUNTIME_WORK_MODEL.rotate_axis;
				nNS_VECTOR4D4.x = rotate_axis.x;
				nNS_VECTOR4D4.y = rotate_axis.y;
				nNS_VECTOR4D4.z = rotate_axis.z;
				nNS_VECTOR4D4.w = rotate_axis.w;
				amQuatRotAxisToQuat(ref pQuat, nNS_VECTOR4D4, nNS_VECTOR4D4.w * _am_unit_time);
				NNS_QUATERNION pDst = aMS_AME_RUNTIME_WORK_MODEL.rotate;
				amQuatMulti(ref pDst, ref pDst, ref pQuat);
				aMS_AME_RUNTIME_WORK_MODEL.rotate = pDst;
				amVectorGetInner(nNS_VECTOR4D4, nNS_VECTOR4D, nNS_VECTOR4D2, num3);
				aMS_AME_RUNTIME_WORK_MODEL.set_scale(nNS_VECTOR4D4);
				AMS_RGBA8888 pCO;
				amEffectLerpColor(out pCO, ref aMS_AME_NODE_MODEL.color_start, ref aMS_AME_NODE_MODEL.color_end, num3);
				pCO.a = (byte)(pCO.a * transparency >> 8);
				aMS_AME_RUNTIME_WORK_MODEL.set_color(pCO.color);
				aMS_AME_RUNTIME_WORK_MODEL.scroll_u += aMS_AME_NODE_MODEL.scroll_u * _am_unit_time;
				aMS_AME_RUNTIME_WORK_MODEL.scroll_v += aMS_AME_NODE_MODEL.scroll_v * _am_unit_time;
				GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D4);
			}
			next = aMS_AME_RUNTIME_WORK_MODEL.next;
		}
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D2);
		return 0;
	}

	public static int _amDrawModel(object r)
	{
