			nNS_VECTOR.x = aMS_AME_RUNTIME_WORK_MODEL.scale.x;
			nNS_VECTOR.y = aMS_AME_RUNTIME_WORK_MODEL.scale.y;
			nNS_VECTOR.z = aMS_AME_RUNTIME_WORK_MODEL.scale.z;
			amDrawObjectSetMaterial(aMS_AME_RUNTIME.ecb.drawObjState, ecb.pObj, aMS_AME_RUNTIME.texlist, nNS_VECTOR, ref color, num2, num3, blend, num);
			aMS_AME_RUNTIME_WORK_MODEL.set_scale(nNS_VECTOR);
			amMatrixPop();
			next = aMS_AME_RUNTIME_WORK_MODEL.next;
		}
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
		return 0;
	}

	public static void _amApplyGravity(AMS_AME_ECB ecb, AMS_AME_NODE node, AMS_AME_RUNTIME_WORK work)
	{
		AMS_AME_NODE_GRAVITY aMS_AME_NODE_GRAVITY = (AMS_AME_NODE_GRAVITY)node;
		float am_unit_time = _am_unit_time;
		NNS_VECTOR4D nNS_VECTOR4D = GlobalPool<NNS_VECTOR4D>.Alloc();
		NNS_VECTOR4D nNS_VECTOR4D2 = GlobalPool<NNS_VECTOR4D>.Alloc();
		amVectorCopy(nNS_VECTOR4D2, aMS_AME_NODE_GRAVITY.direction);
		if ((aMS_AME_NODE_GRAVITY.flag & 2) != 0)
		{
			amQuatMultiVector(nNS_VECTOR4D2, nNS_VECTOR4D2, ref ecb.rotate, null);
		}
		amVectorScale(nNS_VECTOR4D, nNS_VECTOR4D2, aMS_AME_NODE_GRAVITY.magnitude * am_unit_time * am_unit_time * 0.5f);
		amVectorAdd(work.position, nNS_VECTOR4D);
		amVectorScale(nNS_VECTOR4D, nNS_VECTOR4D2, aMS_AME_NODE_GRAVITY.magnitude * am_unit_time);
		amVectorAdd(work.velocity, nNS_VECTOR4D);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D2);
	}

	public static void _amApplyUniform(AMS_AME_ECB ecb, AMS_AME_NODE node, AMS_AME_RUNTIME_WORK work)
	{
		AMS_AME_NODE_UNIFORM aMS_AME_NODE_UNIFORM = (AMS_AME_NODE_UNIFORM)node;
		float am_unit_time = _am_unit_time;
		NNS_VECTOR4D nNS_VECTOR4D = GlobalPool<NNS_VECTOR4D>.Alloc();
		amVectorScale(nNS_VECTOR4D, aMS_AME_NODE_UNIFORM.direction, aMS_AME_NODE_UNIFORM.magnitude * am_unit_time);
		if ((aMS_AME_NODE_UNIFORM.flag & 2) != 0)
		{
			amQuatMultiVector(nNS_VECTOR4D, nNS_VECTOR4D, ref ecb.rotate, null);
		}
		amVectorAdd(work.position, nNS_VECTOR4D);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D);
	}

	public static void _amApplyRadial(AMS_AME_ECB ecb, AMS_AME_NODE node, AMS_AME_RUNTIME_WORK work)
	{
		AMS_AME_NODE_RADIAL aMS_AME_NODE_RADIAL = (AMS_AME_NODE_RADIAL)node;
		float am_unit_time = _am_unit_time;
		NNS_VECTOR4D nNS_VECTOR4D = GlobalPool<NNS_VECTOR4D>.Alloc();
		NNS_VECTOR4D nNS_VECTOR4D2 = GlobalPool<NNS_VECTOR4D>.Alloc();
		amVectorCopy(nNS_VECTOR4D2, aMS_AME_NODE_RADIAL.position);
		if ((aMS_AME_NODE_RADIAL.flag & 1) != 0)
		{
			amVectorAdd(nNS_VECTOR4D2, ecb.translate);
		}
		amVectorSub(nNS_VECTOR4D, work.position, nNS_VECTOR4D2);
		float num = 1f / (float)Math.Pow(amVectorScalor(nNS_VECTOR4D), aMS_AME_NODE_RADIAL.attenuation);
		amVectorScaleUnit(nNS_VECTOR4D, nNS_VECTOR4D, aMS_AME_NODE_RADIAL.magnitude * num * am_unit_time);
		amVectorAdd(work.position, nNS_VECTOR4D);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D2);
	}

	public static void _amApplyVortex(AMS_AME_ECB ecb, AMS_AME_NODE node, AMS_AME_RUNTIME_WORK work)
	{
		AMS_AME_NODE_VORTEX aMS_AME_NODE_VORTEX = (AMS_AME_NODE_VORTEX)node;
		NNS_VECTOR4D nNS_VECTOR4D = GlobalPool<NNS_VECTOR4D>.Alloc();
		NNS_VECTOR4D nNS_VECTOR4D2 = GlobalPool<NNS_VECTOR4D>.Alloc();
		NNS_VECTOR4D nNS_VECTOR4D3 = GlobalPool<NNS_VECTOR4D>.Alloc();
		NNS_VECTOR4D nNS_VECTOR4D4 = GlobalPool<NNS_VECTOR4D>.Alloc();
		amVectorCopy(nNS_VECTOR4D, aMS_AME_NODE_VORTEX.position);
		amVectorCopy(nNS_VECTOR4D3, aMS_AME_NODE_VORTEX.axis);
		if ((aMS_AME_NODE_VORTEX.flag & 1) != 0)
		{
			amVectorAdd(nNS_VECTOR4D, ecb.translate);
		}
		if ((aMS_AME_NODE_VORTEX.flag & 2) != 0)
		{
			amQuatMultiVector(nNS_VECTOR4D3, nNS_VECTOR4D3, ref ecb.rotate, null);
		}
		amVectorSub(nNS_VECTOR4D2, work.position, nNS_VECTOR4D);
		amVectorOuterProduct(nNS_VECTOR4D4, nNS_VECTOR4D3, nNS_VECTOR4D2);
		amVectorScale(nNS_VECTOR4D2, nNS_VECTOR4D4, _am_unit_time);
		amVectorAdd(work.velocity, nNS_VECTOR4D2);
		amVectorOuterProduct(nNS_VECTOR4D4, nNS_VECTOR4D3, nNS_VECTOR4D4);
		amVectorScale(nNS_VECTOR4D2, nNS_VECTOR4D4, _am_unit_time);
		amVectorAdd(work.velocity, nNS_VECTOR4D2);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D2);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D3);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D4);
	}

	public static void _amApplyDrag(AMS_AME_ECB ecb, AMS_AME_NODE node, AMS_AME_RUNTIME_WORK work)
	{
		AMS_AME_NODE_DRAG aMS_AME_NODE_DRAG = (AMS_AME_NODE_DRAG)node;
		float am_unit_time = _am_unit_time;
		NNS_VECTOR4D nNS_VECTOR4D = GlobalPool<NNS_VECTOR4D>.Alloc();
		NNS_VECTOR4D nNS_VECTOR4D2 = GlobalPool<NNS_VECTOR4D>.Alloc();
		NNS_VECTOR4D nNS_VECTOR4D3 = GlobalPool<NNS_VECTOR4D>.Alloc();
		amVectorCopy(nNS_VECTOR4D3, aMS_AME_NODE_DRAG.position);
		if ((aMS_AME_NODE_DRAG.flag & 1) != 0)
		{
			amVectorAdd(nNS_VECTOR4D3, ecb.translate);
		}
		amVectorSub(nNS_VECTOR4D2, work.position, nNS_VECTOR4D3);
		amVectorUnit(nNS_VECTOR4D2);
		amVectorScale(nNS_VECTOR4D, nNS_VECTOR4D2, aMS_AME_NODE_DRAG.magnitude * am_unit_time * am_unit_time * 0.5f);
		amVectorAdd(work.position, nNS_VECTOR4D);
		amVectorScale(nNS_VECTOR4D, nNS_VECTOR4D2, aMS_AME_NODE_DRAG.magnitude * am_unit_time);
		amVectorAdd(work.velocity, nNS_VECTOR4D);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D2);
		GlobalPool<NNS_VECTOR4D>.Release(nNS_VECTOR4D3);
	}

	public static void _amApplyNoise(AMS_AME_ECB ecb, AMS_AME_NODE node, AMS_AME_RUNTIME_WORK work)
	{
		AMS_AME_NODE_NOISE aMS_AME_NODE_NOISE = (AMS_AME_NODE_NOISE)node;
		float num = aMS_AME_NODE_NOISE.magnitude * _am_unit_time;
		SNNS_VECTOR4D pSrc = default(SNNS_VECTOR4D);
		pSrc.x = (nnRandom() - 0.5f) * num * aMS_AME_NODE_NOISE.axis.x;
		pSrc.y = (nnRandom() - 0.5f) * num * aMS_AME_NODE_NOISE.axis.y;
		pSrc.z = (nnRandom() - 0.5f) * num * aMS_AME_NODE_NOISE.axis.z;
		pSrc.w = 1f;
		amVectorAdd(work.position, ref pSrc);
	}

