	private static void GmPlyEfctCreateHomingCursol(GMS_PLAYER_WORK ply_work)
	{
		if (ply_work.enemy_obj == null)
		{
			return;
		}
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)ply_work.enemy_obj;
		if (gMS_ENEMY_COM_WORK.obj_work.obj_type == 2 || gMS_ENEMY_COM_WORK.obj_work.obj_type == 3)
		{
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctCmnEsCreate(gMS_ENEMY_COM_WORK.obj_work, 95);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.ppFunc = gmPlyEfctHomingCursolMain;
			OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_COM_WORK.rect_work[2];
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_timer = oBS_RECT_WORK.rect.left + oBS_RECT_WORK.rect.right >> 1 << 12;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_work = (uint)(oBS_RECT_WORK.rect.top + oBS_RECT_WORK.rect.bottom >> 1 << 12);
			if ((gMS_ENEMY_COM_WORK.obj_work.disp_flag & 1) != 0)
			{
				gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_timer = -gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_timer;
			}
			if ((gMS_ENEMY_COM_WORK.obj_work.disp_flag & 2) != 0)
			{
				gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_work = 0 - gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_work;
			}
			GmComEfctSetDispOffset(gMS_EFFECT_3DES_WORK, gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_timer, (int)gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_work, 524288);
		}
	}

	private static void GmPlyEfctCreateJumpDash(GMS_PLAYER_WORK ply_work)
	{
