		obj_work.user_timer++;
		if (obj_work.user_timer >= 15)
		{
			obj_work.user_timer = 0;
			gmPlyEfctCreateInvincibleTail((GMS_PLAYER_WORK)obj_work.parent_obj);
		}
		int user_work = (int)(obj_work.user_work + 1);
		obj_work.user_work = (uint)user_work;
