			obj_work.ppFunc = GmEffectDefaultMainFuncDeleteAtEndCopyDirZ;
		}
		GmEffectDefaultMainFuncDeleteAtEndCopyDirZ(obj_work);
		if ((obj_work.flag & 0xC) == 0 && gMS_EFFECT_3DES_WORK.efct_com.obj_work.user_timer == 82 && (gMS_PLAYER_WORK.player_flag & 0x4000) == 0)
