		oBS_OBJECT_WORK.view_out_ofst -= 128;
		ushort num = (ushort)(g_gs_main_sys_info.stage_id - 21);
		SSpecial sSpecial = SSpecial.CreateInstance();
		if (sSpecial[num].IsGetEmerald())
		{
			flag = true;
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_ss_1up_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
