		else
		{
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_ss_emerald_obj_3d_list[num], gMS_ENEMY_3D_WORK.obj_3d);
			ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, false, ObjDataGet(912), null, 0, null);
			ObjDrawObjectActionSet(oBS_OBJECT_WORK, num);
		}
		oBS_OBJECT_WORK.pos.z = -131072;
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194308u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 2u;
		oBS_OBJECT_WORK.ppFunc = gmGmkSsEmeraldMain;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[0].flag &= 4294967291u;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		oBS_RECT_WORK.ppDef = gmGmkSsEmeraldDefFunc;
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		ObjRectWorkSet(oBS_RECT_WORK, -4, -4, 4, 4);
		int efct_zone_idx = ((!flag) ? (1 + num) : 0);
