	public static void GmGmkPulleyDrawServerMain()
	{
		if (!GmMainIsDrawEnable())
		{
			return;
		}
		GMS_GMK_PULLEY_MANAGER gMS_GMK_PULLEY_MANAGER = gm_gmk_pulley_manager;
		if (gMS_GMK_PULLEY_MANAGER.num == 0)
		{
			return;
		}
		AMS_PARAM_DRAW_PRIMITIVE aMS_PARAM_DRAW_PRIMITIVE = GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Alloc();
		aMS_PARAM_DRAW_PRIMITIVE.type = 1;
		aMS_PARAM_DRAW_PRIMITIVE.ablend = 0;
		aMS_PARAM_DRAW_PRIMITIVE.bldSrc = 768;
		aMS_PARAM_DRAW_PRIMITIVE.bldDst = 774;
		aMS_PARAM_DRAW_PRIMITIVE.bldMode = 32774;
		aMS_PARAM_DRAW_PRIMITIVE.aTest = 1;
		aMS_PARAM_DRAW_PRIMITIVE.zMask = 0;
		aMS_PARAM_DRAW_PRIMITIVE.zTest = 1;
		aMS_PARAM_DRAW_PRIMITIVE.noSort = 1;
		aMS_PARAM_DRAW_PRIMITIVE.texlist = gMS_GMK_PULLEY_MANAGER.texlist;
		aMS_PARAM_DRAW_PRIMITIVE.texId = (int)gMS_GMK_PULLEY_MANAGER.tex_id;
		uint col = GmMainGetLightColor();
		aMS_PARAM_DRAW_PRIMITIVE.uwrap = 1;
		aMS_PARAM_DRAW_PRIMITIVE.vwrap = 1;
		aMS_PARAM_DRAW_PRIMITIVE.count = (int)(gMS_GMK_PULLEY_MANAGER.num * 6 - 2);
		aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D = amDrawAlloc_NNS_PRIM3D_PCT(aMS_PARAM_DRAW_PRIMITIVE.count);
		NNS_PRIM3D_PCT[] buffer = aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D.buffer;
		int offset = aMS_PARAM_DRAW_PRIMITIVE.vtxPCT3D.offset;
		aMS_PARAM_DRAW_PRIMITIVE.format3D = 4;
		NNS_MATRIX nNS_MATRIX = GlobalPool<NNS_MATRIX>.Alloc();
		NNS_VECTOR nNS_VECTOR = GlobalPool<NNS_VECTOR>.Alloc();
		Vector3 vector = default(Vector3);
		for (int i = 0; i < gMS_GMK_PULLEY_MANAGER.num; i++)
		{
			int num = offset + i * 6;
			int num2 = offset + i * 6 - 1;
			int num3 = offset + i * 6 + 4;
			GMS_GMK_PULLEY_REGISTER gMS_GMK_PULLEY_REGISTER = gMS_GMK_PULLEY_MANAGER.reg[i];
			vector.X = FX_FX32_TO_F32(gMS_GMK_PULLEY_REGISTER.vec.x);
			vector.Y = FX_FX32_TO_F32(gMS_GMK_PULLEY_REGISTER.vec.y);
			vector.Z = FX_FX32_TO_F32(gMS_GMK_PULLEY_REGISTER.vec.z);
			NNS_VECTOR[] array = gm_gmk_pulley_pos[gMS_GMK_PULLEY_REGISTER.type];
			NNS_TEXCOORD[] array2 = gm_gmk_pulley_tex[gMS_GMK_PULLEY_REGISTER.type];
			if (gMS_GMK_PULLEY_REGISTER.flip != 0)
			{
				nnMakeRotateYMatrix(nNS_MATRIX, gMS_GMK_PULLEY_REGISTER.flip);
			}
			float num4 = 0f;
			if (gMS_GMK_PULLEY_REGISTER.type == 2)
			{
				num4 = 2f;
			}
			for (int j = 0; j < 4; j++)
			{
				if (gMS_GMK_PULLEY_REGISTER.flip != 0)
				{
					nnTransformVector(nNS_VECTOR, nNS_MATRIX, array[j]);
				}
				else
				{
					nnCopyVector(nNS_VECTOR, array[j]);
				}
				int num5 = num + j;
				buffer[num5].Pos.x = nNS_VECTOR.x + vector.X;
				buffer[num5].Pos.y = nNS_VECTOR.y - vector.Y + num4;
				buffer[num5].Pos.z = nNS_VECTOR.z + vector.Z;
				buffer[num5].Tex.u = array2[j].u;
				buffer[num5].Tex.v = array2[j].v;
				buffer[num5].Col = col;
			}
			if (i != 0)
			{
				buffer[num2] = buffer[num];
			}
			if (i != gMS_GMK_PULLEY_MANAGER.num - 1)
			{
				buffer[num3] = buffer[num + 3];
			}
		}
		GlobalPool<NNS_VECTOR>.Release(nNS_VECTOR);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX);
		NNS_MATRIX nNS_MATRIX2 = GlobalPool<NNS_MATRIX>.Alloc();
		nnMakeUnitMatrix(nNS_MATRIX2);
		amMatrixPush(nNS_MATRIX2);
		ObjDraw3DNNDrawPrimitive(aMS_PARAM_DRAW_PRIMITIVE, 0u, 0, 0);
		amMatrixPop();
		GlobalPool<AMS_PARAM_DRAW_PRIMITIVE>.Release(aMS_PARAM_DRAW_PRIMITIVE);
		GlobalPool<NNS_MATRIX>.Release(nNS_MATRIX2);
		gMS_GMK_PULLEY_MANAGER.num = 0u;
	}

	private static void gmGmkPulleyBaseExit(MTS_TASK_TCB tcb)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = mtTaskGetTcbWork(tcb);
