		{
			GsSoundStopSeHandle(gMS_GMK_PULLEY_WORK.se_handle);
			GsSoundFreeSeHandle(gMS_GMK_PULLEY_WORK.se_handle);
			gMS_GMK_PULLEY_WORK.se_handle = null;
		}
		GmEnemyDefaultExit(tcb);
	}

	private static void gmGmkPulleyDefFunc(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_ENEMY_COM_WORK != null && gMS_PLAYER_WORK != null && gMS_PLAYER_WORK.obj_work.obj_type == 1 && gMS_PLAYER_WORK.gmk_obj != (OBS_OBJECT_WORK)gMS_ENEMY_COM_WORK)
		{
			GmPlySeqInitPulley(gMS_PLAYER_WORK, gMS_ENEMY_COM_WORK);
			ObjDrawObjectActionSet3DNN(gMS_ENEMY_COM_WORK.obj_work, 3, 0);
			if ((gMS_PLAYER_WORK.obj_work.disp_flag & 1) != 0)
			{
				gMS_ENEMY_COM_WORK.obj_work.dir.y = 32768;
			}
			else
			{
				gMS_ENEMY_COM_WORK.obj_work.dir.y = 0;
			}
			gMS_ENEMY_COM_WORK.obj_work.user_flag = (uint)(gMS_ENEMY_COM_WORK.obj_work.user_flag & -32769);
			((OBS_OBJECT_WORK)gMS_ENEMY_COM_WORK).ppFunc = gmGmkPulleyMove;
			ObjRectWorkSet(gMS_ENEMY_COM_WORK.rect_work[2], -32, 9, 32, 24);
		}
	}

	private static void gmGmkPulleyMove(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (gMS_PLAYER_WORK.gmk_obj != obj_work)
		{
			gmGmkPulleySecedeSet(obj_work, 0);
			obj_work.flag |= 2u;
			obj_work.user_timer = 36;
			return;
		}
		if (obj_work.spd.x > 0)
		{
			obj_work.spd.x -= 64;
			if (obj_work.spd.x < 0)
			{
				obj_work.spd.x = 0;
			}
		}
		else
		{
			obj_work.spd.x += 64;
			if (obj_work.spd.x > 0)
			{
				obj_work.spd.x = 0;
			}
		}
		if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 2) != 0)
		{
			if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 1) != 0)
			{
				obj_work.spd.x -= 128;
			}
			else
			{
				obj_work.spd.x += 128;
			}
		}
		if ((g_gs_main_sys_info.game_flag & 1) != 0)
		{
			int num = MTM_MATH_CLIP(GmPlayerKeyGetGimmickRotZ(gMS_PLAYER_WORK), -24576, 24576);
			num = num * 160 / 24576;
			obj_work.spd.x += num;
		}
		else
		{
			int num2 = MTM_MATH_CLIP(gMS_PLAYER_WORK.key_rot_z, -24576, 24576);
			num2 = num2 * 160 / 24576;
			obj_work.spd.x += num2;
		}
		if (gMS_PLAYER_WORK.act_state != 59 && obj_work.spd.x > -256 && obj_work.spd.x < 256)
		{
			obj_work.user_flag |= 32768u;
		}
		if ((gMS_PLAYER_WORK.act_state != 59 && gMS_PLAYER_WORK.act_state != 66) || (gMS_PLAYER_WORK.obj_work.disp_flag & 8) != 0)
		{
			int num3;
			int id;
			if ((gMS_PLAYER_WORK.obj_work.disp_flag & 1) != 0)
			{
				num3 = 56;
				id = 0;
			}
			else
			{
				num3 = 56;
				id = 0;
			}
			if ((obj_work.spd.x < -256 || obj_work.spd.x > 256) && (obj_work.user_flag & 0x8000) != 0)
			{
				GmPlayerActionChange(gMS_PLAYER_WORK, 59);
				ObjDrawObjectActionSet3DNN(obj_work, 4, 0);
				obj_work.user_flag = (uint)(obj_work.user_flag & -32769);
			}
			else if (gMS_PLAYER_WORK.act_state != num3)
			{
				GmPlayerActionChange(gMS_PLAYER_WORK, num3);
				gMS_PLAYER_WORK.obj_work.disp_flag |= 4u;
				ObjDrawObjectActionSet3DNN(obj_work, id, 0);
				obj_work.disp_flag |= 4u;
			}
		}
		obj_work.dir.z = (ushort)MTM_MATH_CLIP((short)(obj_work.spd.x / 4), -10240, 10240);
		gMS_ENEMY_3D_WORK.ene_com.target_dp_dir.z = obj_work.dir.z;
		int num4;
		int num5;
		if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 1) != 0)
		{
			num4 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x - gMS_ENEMY_3D_WORK.ene_com.eve_rec.left * 64 * 4096;
			num5 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x;
		}
		else
		{
			num4 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x;
			num5 = gMS_ENEMY_3D_WORK.ene_com.born_pos_x + gMS_ENEMY_3D_WORK.ene_com.eve_rec.left * 64 * 4096;
		}
		if (obj_work.pos.x < num4)
		{
			if (gMS_PLAYER_WORK.obj_work.pos.x > num4 + 32768)
			{
				gMS_PLAYER_WORK.obj_work.pos.x = num4 + 32768;
			}
			gmGmkPulleySonicTakeOffSet(gMS_PLAYER_WORK, obj_work.spd.x);
			gmGmkPulleySecedeSet(obj_work, num4);
			obj_work.user_timer = 0;
		}
		else if (obj_work.pos.x > num5)
		{
			if (gMS_PLAYER_WORK.obj_work.pos.x < num5 - 32768)
			{
				gMS_PLAYER_WORK.obj_work.pos.x = num5 - 32768;
			}
			gmGmkPulleySonicTakeOffSet(gMS_PLAYER_WORK, obj_work.spd.x);
			gmGmkPulleySecedeSet(obj_work, num5);
			obj_work.user_timer = 0;
		}
		if (obj_work.ppFunc == new MPP_VOID_OBS_OBJECT_WORK(gmGmkPulleyMove) && MTM_MATH_ABS(obj_work.spd.x) > 4096)
		{
			gmGmkPulleySparkInit(obj_work);
		}
		else
		{
			gmGmkPulleySparkKill(obj_work);
		}
		ObjObjectMove(obj_work);
		if ((gMS_ENEMY_3D_WORK.ene_com.eve_rec.flag & 2) != 0)
		{
			int num6 = MTM_MATH_ABS(gMS_ENEMY_3D_WORK.ene_com.born_pos_x - obj_work.pos.x);
			num6 /= 2;
			obj_work.pos.y = gMS_ENEMY_3D_WORK.ene_com.born_pos_y + num6;
		}
	}

	private static void gmGmkPulleySonicTakeOffSet(GMS_PLAYER_WORK ply_work, int spd_x)
	{
		ply_work.obj_work.spd.y = 0;
		ply_work.obj_work.spd.z = 0;
		ply_work.obj_work.dir.z = 0;
		ply_work.obj_work.spd_m = spd_x;
		ply_work.obj_work.spd.y = -12288;
		GmPlySeqChangeSequence(ply_work, 17);
		if (spd_x > 0)
		{
			if (ply_work.obj_work.spd.x < 16384)
			{
				ply_work.obj_work.spd.x = 16384;
			}
			else if (ply_work.obj_work.spd.x > 24576)
			{
				ply_work.obj_work.spd.x = 24576;
			}
		}
		else if (ply_work.obj_work.spd.x > -16384)
		{
			ply_work.obj_work.spd.x = -16384;
		}
		else if (ply_work.obj_work.spd.x < -24576)
		{
			ply_work.obj_work.spd.x = -24576;
		}
		ply_work.obj_work.spd.x = ply_work.obj_work.spd.x / 2;
		ply_work.obj_work.spd.y = -12288;
		GmPlySeqSetJumpState(ply_work, 0, 7u);
	}

	private static void gmGmkPulleySecedeSet(OBS_OBJECT_WORK obj_work, int pos_x)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if (pos_x != 0)
		{
			obj_work.pos.x = pos_x;
		}
		obj_work.spd.x = 0;
		obj_work.spd.y = 0;
		obj_work.spd_m = 0;
		obj_work.dir.z = 0;
		gMS_ENEMY_3D_WORK.ene_com.target_dp_dir.z = obj_work.dir.z;
		ObjDrawObjectActionSet3DNN(obj_work, 5, 0);
		obj_work.ppFunc = gmGmkPulleySecede;
		ObjRectWorkSet(gMS_ENEMY_3D_WORK.ene_com.rect_work[2], -4, 9, 4, 24);
		gmGmkPulleySparkKill(obj_work);
		GMS_GMK_PULLEY_WORK gMS_GMK_PULLEY_WORK = (GMS_GMK_PULLEY_WORK)obj_work;
		if (gMS_GMK_PULLEY_WORK.se_handle != null)
		{
			GsSoundStopSeHandle(gMS_GMK_PULLEY_WORK.se_handle);
			GsSoundFreeSeHandle(gMS_GMK_PULLEY_WORK.se_handle);
			gMS_GMK_PULLEY_WORK.se_handle = null;
		}
	}

	private static void gmGmkPulleySecede(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.user_timer != 0)
		{
			obj_work.user_timer--;
			if (obj_work.user_timer == 0)
			{
				obj_work.flag &= 4294967293u;
			}
		}
		if ((obj_work.disp_flag & 8) != 0)
		{
			ObjDrawObjectActionSet3DNN(obj_work, 0, 0);
			obj_work.disp_flag |= 4u;
			obj_work.ppFunc = null;
		}
	}

