	private static OBS_OBJECT_WORK GmGmkPressWallInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		UNREFERENCED_PARAMETER(type);
		GMS_GMK_PWALL_WORK gMS_GMK_PWALL_WORK = (GMS_GMK_PWALL_WORK)GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_PWALL_WORK(), "Gmk_PressWall");
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gMS_GMK_PWALL_WORK;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)gMS_GMK_PWALL_WORK;
		if (g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id] == 2)
		{
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_presswall_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
			oBS_OBJECT_WORK.ppOut = gmGmkPressWall_ppOut;
			if (eve_rec.height == 0)
			{
				gMS_GMK_PWALL_WORK.wall_height = 0;
				oBS_OBJECT_WORK.pos.y -= 524288;
			}
			else
			{
				gMS_GMK_PWALL_WORK.wall_height = eve_rec.height * 64 * 4096;
				oBS_OBJECT_WORK.pos.y -= gMS_GMK_PWALL_WORK.wall_height;
			}
			oBS_OBJECT_WORK.pos.z = 913408;
		}
		else
		{
			ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_presswall_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
			oBS_OBJECT_WORK.ppOut = gmGmkPressWall_ppOut;
			ObjAction3dNNMaterialMotionLoad(oBS_OBJECT_WORK.obj_3d, 0, null, null, 1, (AMS_AMB_HEADER)ObjDataGet(895).pData);
			ObjDrawObjectActionSet3DNNMaterial(oBS_OBJECT_WORK, 0);
			oBS_OBJECT_WORK.disp_flag |= 4u;
			if (eve_rec.height == 0)
			{
				gMS_GMK_PWALL_WORK.wall_height = 0;
				oBS_OBJECT_WORK.pos.y -= 786432;
			}
			else
			{
				gMS_GMK_PWALL_WORK.wall_height = eve_rec.height * 192 * 4096;
				oBS_OBJECT_WORK.pos.y -= gMS_GMK_PWALL_WORK.wall_height;
			}
			oBS_OBJECT_WORK.pos.z = 1044480;
		}
		oBS_OBJECT_WORK.move_flag |= 8448u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.flag |= 2u;
		if (eve_rec.width != 0)
		{
			gMS_GMK_PWALL_WORK.wall_speed = eve_rec.width * 4096 / 10;
		}
		else
		{
			gMS_GMK_PWALL_WORK.wall_speed = 4096;
		}
		mtTaskChangeTcbDestructor(oBS_OBJECT_WORK.tcb, gmGmkPressWallExit);
		gMS_GMK_PWALL_WORK.se_handle = null;
		gmGmkPressWallStart(oBS_OBJECT_WORK);
		return oBS_OBJECT_WORK;
	}

	private static OBS_OBJECT_WORK GmGmkPressWallStopInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK;
		if (g_gm_gamedat_zone_type_tbl[g_gs_main_sys_info.stage_id] == 2 && pwall == null)
		{
			oBS_OBJECT_WORK = GmGmkPressWallInit(eve_rec, pos_x, pos_y, type);
			oBS_OBJECT_WORK.user_flag = 1u;
		}
		oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENEMY_3D_WORK(), "Gmk_PressWallStopper");
		oBS_OBJECT_WORK.user_flag = 0u;
		if ((eve_rec.flag & 1) != 0)
		{
			oBS_OBJECT_WORK.user_flag = 1u;
		}
		gmGmkPressWallStopperStart(oBS_OBJECT_WORK);
		return oBS_OBJECT_WORK;
	}

	private static OBS_OBJECT_WORK GmGmkPressWallControlerInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		UNREFERENCED_PARAMETER(type);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_PWALLCTRL_WORK(), "Gmk_PressWallControler");
		GMS_GMK_PWALLCTRL_WORK gMS_GMK_PWALLCTRL_WORK = (GMS_GMK_PWALLCTRL_WORK)oBS_OBJECT_WORK;
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		oBS_RECT_WORK.ppDef = null;
		oBS_RECT_WORK.ppHit = null;
		oBS_RECT_WORK.flag &= 4294967291u;
		if (eve_rec.left != 0)
		{
			ObjRectWorkSet(oBS_RECT_WORK, (short)(eve_rec.left * 2), 0, (short)(eve_rec.width * 2), 1);
			oBS_OBJECT_WORK.user_flag = 0u;
			oBS_OBJECT_WORK.user_timer = eve_rec.height * 819;
		}
		else
		{
			oBS_RECT_WORK.ppDef = null;
			oBS_RECT_WORK.ppHit = null;
			ObjRectWorkSet(oBS_RECT_WORK, 0, (short)(eve_rec.top * 2), 1, (short)(eve_rec.height * 2));
			gMS_GMK_PWALLCTRL_WORK.line_top = eve_rec.top * 2 * 4096 + oBS_OBJECT_WORK.pos.y;
			gMS_GMK_PWALLCTRL_WORK.line_bottom = eve_rec.height * 2 * 4096 + oBS_OBJECT_WORK.pos.y;
			oBS_OBJECT_WORK.user_flag = 1u;
			oBS_OBJECT_WORK.user_timer = eve_rec.width * 819;
		}
		oBS_OBJECT_WORK.flag &= 4294967293u;
		if ((eve_rec.flag & 1) != 0)
		{
			oBS_OBJECT_WORK.user_flag |= 2u;
		}
		if ((eve_rec.flag & 2) != 0)
		{
			oBS_OBJECT_WORK.user_flag |= 4u;
		}
		gmGmkPressWallControlerStart(oBS_OBJECT_WORK);
		return oBS_OBJECT_WORK;
	}

