	private static void gmGmkPressWallStopperMain(OBS_OBJECT_WORK obj_work)
	{
		if (pwall == null)
		{
			obj_work.flag |= 8u;
		}
		else if (obj_work.user_flag == 0 || (obj_work.pos.y >= g_obj.camera[0][1] - 524288 && obj_work.pos.y <= g_obj.camera[0][1] + 1572864))
		{
			if (pwall.gmk_work.ene_com.obj_work.pos.x > obj_work.pos.x)
			{
				GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)obj_work;
				pwall.gmk_work.ene_com.obj_work.pos.x = obj_work.pos.x;
				pwall.wall_speed = 0;
				obj_work.flag |= 8u;
				gMS_ENEMY_COM_WORK.enemy_flag |= 65536u;
			}
			if (obj_work.user_work_OBJECT != pwall)
			{
				GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK2 = (GMS_ENEMY_COM_WORK)obj_work;
				obj_work.flag |= 8u;
				gMS_ENEMY_COM_WORK2.enemy_flag |= 65536u;
			}
		}
	}

