	private static void gmGmkPressWallControler(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_PWALLCTRL_WORK gMS_GMK_PWALLCTRL_WORK = (GMS_GMK_PWALLCTRL_WORK)obj_work;
		GMS_PLAYER_WORK ply_work = gMS_GMK_PWALLCTRL_WORK.ply_work;
		if (pwall != null && (obj_work.user_flag & 1) != 0 && obj_work.pos.x > gMS_GMK_PWALLCTRL_WORK.last_ply_x && obj_work.pos.x <= ply_work.obj_work.pos.x && ((obj_work.user_flag & 2) == 0 || (ply_work.obj_work.pos.y >= gMS_GMK_PWALLCTRL_WORK.line_top && ply_work.obj_work.pos.y <= gMS_GMK_PWALLCTRL_WORK.line_bottom)))
		{
			if ((obj_work.user_flag & 4) != 0 && pwall.gmk_work.ene_com.obj_work.pos.x <= g_obj.camera[0][0] - 32768)
			{
				pwall.gmk_work.ene_com.obj_work.pos.x = g_obj.camera[0][0] - 32768;
			}
			pwall.wall_speed = obj_work.user_timer;
			if (pwall.wall_speed == 0)
			{
				pwall.stop_wall = true;
			}
			obj_work.flag |= 8u;
			gMS_GMK_PWALLCTRL_WORK.gmk_work.ene_com.enemy_flag |= 65536u;
		}
		else
		{
			gMS_GMK_PWALLCTRL_WORK.last_ply_x = ply_work.obj_work.pos.x;
			gMS_GMK_PWALLCTRL_WORK.last_ply_y = ply_work.obj_work.pos.y;
		}
	}

