		GMS_GMK_PWALLCTRL_WORK gMS_GMK_PWALLCTRL_WORK = (GMS_GMK_PWALLCTRL_WORK)obj_work;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (gMS_GMK_PWALLCTRL_WORK.ply_work = g_gm_main_system.ply_work[0]);
		gMS_GMK_PWALLCTRL_WORK.last_ply_x = gMS_PLAYER_WORK.obj_work.pos.x;
		gMS_GMK_PWALLCTRL_WORK.last_ply_y = gMS_PLAYER_WORK.obj_work.pos.y;
		obj_work.disp_flag |= 32u;
		obj_work.move_flag |= 8960u;
		obj_work.ppFunc = gmGmkPressWallControler;
	}

