	private static void _gmGmkPopSteam(GMS_GMK_P_STEAM_WORK pwork)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((pwork.status & 1) != 0)
		{
			if (gMS_PLAYER_WORK.seq_state == 24)
			{
				pwork.ply_work = null;
				pwork.status &= 65532;
				return;
			}
			int num;
			int num2;
			if ((pwork.steamvect & 0x4000) != 0)
			{
				num = 0;
				num2 = pwork.steampower;
				if ((pwork.steamvect & 0x8000) != 0)
				{
					num2 = -num2;
				}
			}
			else
			{
				num2 = 0;
				num = pwork.steampower;
				if ((pwork.steamvect & 0x8000) != 0)
				{
					num = -num;
				}
			}
			GmPlySeqGmkInitPopSteamJump(gMS_PLAYER_WORK, num, num2, pwork.gmk_work.ene_com.eve_rec.top << 13);
			if ((pwork.status & 2) == 0)
			{
				GmSoundPlaySE("Steam");
				GMM_PAD_VIB_SMALL();
			}
			pwork.status |= 2;
		}
		else
		{
			pwork.status &= 65533;
		}
		pwork.status &= 65534;
	}

