		obj_work.flag &= 4294967293u;
		gMS_GMK_P_STEAM_WORK.opt_steam = (OBS_OBJECT_WORK)GmEfctCmnEsCreate(obj_work, tbl_popsteam_effct[0][gMS_GMK_P_STEAM_WORK.steamsize]);
		gMS_GMK_P_STEAM_WORK.opt_steam.dir.z = obj_work.dir.z;
