	private static void gmGmkPopSteamInterval_100(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_P_STEAM_WORK gMS_GMK_P_STEAM_WORK = (GMS_GMK_P_STEAM_WORK)obj_work;
		gMS_GMK_P_STEAM_WORK.timer -= (short)(gMS_GMK_P_STEAM_WORK.steamwait / 60);
		if (gMS_GMK_P_STEAM_WORK.timer <= 0)
		{
			if (gMS_GMK_P_STEAM_WORK.opt_steam != null)
			{
				ObjDrawKillAction3DES(gMS_GMK_P_STEAM_WORK.opt_steam);
				gMS_GMK_P_STEAM_WORK.opt_steam = null;
			}
			gMS_GMK_P_STEAM_WORK.timer = 0;
			gmGmkPopSteamWait(obj_work);
		}
		else
		{
			_gmGmkPopSteam(gMS_GMK_P_STEAM_WORK);
		}
	}

	private static void gmGmkPopSteamWait(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_P_STEAM_WORK gMS_GMK_P_STEAM_WORK = (GMS_GMK_P_STEAM_WORK)obj_work;
		for (int i = 0; i < 3; i++)
		{
			gMS_GMK_P_STEAM_WORK.opt_steam_int[i] = null;
		}
		obj_work.flag |= 2u;
		obj_work.ppFunc = gmGmkPopSteamWait_100;
		gmGmkPopSteamWait_100(obj_work);
	}

	private static void gmGmkPopSteamWait_100(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_P_STEAM_WORK gMS_GMK_P_STEAM_WORK = (GMS_GMK_P_STEAM_WORK)obj_work;
		gMS_GMK_P_STEAM_WORK.timer++;
		if (gMS_GMK_P_STEAM_WORK.timer >= gMS_GMK_P_STEAM_WORK.steamwait)
		{
			if (gMS_GMK_P_STEAM_WORK.opt_steam_int[0] != null)
			{
				for (int i = 0; i < 3; i++)
				{
					ObjDrawKillAction3DES(gMS_GMK_P_STEAM_WORK.opt_steam_int[i]);
					gMS_GMK_P_STEAM_WORK.opt_steam_int[i] = null;
				}
			}
			obj_work.user_timer = 0;
			obj_work.pos.x = gMS_GMK_P_STEAM_WORK.pos_x;
			obj_work.pos.y = gMS_GMK_P_STEAM_WORK.pos_y;
			gmGmkPopSteamInterval(obj_work);
		}
		else
		{
			if (gMS_GMK_P_STEAM_WORK.timer >= gMS_GMK_P_STEAM_WORK.steamwait * 3 / 4)
			{
				obj_work.pos.x = gMS_GMK_P_STEAM_WORK.pos_x + (tbl_psteam_viv[obj_work.user_timer][0] << 12);
				obj_work.pos.y = gMS_GMK_P_STEAM_WORK.pos_y + (tbl_psteam_viv[obj_work.user_timer][1] << 12);
				obj_work.user_timer++;
				obj_work.user_timer %= 10;
			}
			_gmGmkPopSteam(gMS_GMK_P_STEAM_WORK);
		}
	}

	private static void _ModgmGmkPopSteamStart(GMS_GMK_P_STEAM_WORK pwork, ref short u)
	{
		if (pwork.steamsize == 2)
		{
			u /= 96;
			u *= 128;
		}
		else if (pwork.steamsize == 0)
		{
			u /= 96;
			u *= 64;
		}
	}

	private static void gmGmkPopSteamStart(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_P_STEAM_WORK gMS_GMK_P_STEAM_WORK = (GMS_GMK_P_STEAM_WORK)obj_work;
		gMS_GMK_P_STEAM_WORK.gmk_work.ene_com.rect_work[0].flag &= 4294967291u;
		gMS_GMK_P_STEAM_WORK.gmk_work.ene_com.rect_work[1].flag &= 4294967291u;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_GMK_P_STEAM_WORK.gmk_work.ene_com.rect_work[2];
		oBS_RECT_WORK.ppDef = gmGmkPopSteamHit;
		oBS_RECT_WORK.ppHit = null;
		ObjRectAtkSet(oBS_RECT_WORK, 0, 0);
		ObjRectDefSet(oBS_RECT_WORK, 65534, 0);
		ObjRectWorkSet(oBS_RECT_WORK, tbl_gm_gmk_upbumper_rect[gMS_GMK_P_STEAM_WORK.obj_type][0], tbl_gm_gmk_upbumper_rect[gMS_GMK_P_STEAM_WORK.obj_type][1], tbl_gm_gmk_upbumper_rect[gMS_GMK_P_STEAM_WORK.obj_type][2], tbl_gm_gmk_upbumper_rect[gMS_GMK_P_STEAM_WORK.obj_type][3]);
		oBS_RECT_WORK.flag &= 4294966271u;
		obj_work.flag &= 4294967293u;
		switch (gMS_GMK_P_STEAM_WORK.obj_type)
		{
		case 0:
			obj_work.dir.z = 0;
			gMS_GMK_P_STEAM_WORK.steamvect = 49152;
			_ModgmGmkPopSteamStart(gMS_GMK_P_STEAM_WORK, ref oBS_RECT_WORK.rect.top);
			break;
		case 1:
			obj_work.dir.z = 16384;
			gMS_GMK_P_STEAM_WORK.steamvect = 0;
			_ModgmGmkPopSteamStart(gMS_GMK_P_STEAM_WORK, ref oBS_RECT_WORK.rect.right);
			break;
		case 2:
			obj_work.dir.z = 32768;
			gMS_GMK_P_STEAM_WORK.steamvect = 16384;
			_ModgmGmkPopSteamStart(gMS_GMK_P_STEAM_WORK, ref oBS_RECT_WORK.rect.bottom);
			break;
		case 3:
			obj_work.dir.z = 49152;
			gMS_GMK_P_STEAM_WORK.steamvect = 32768;
			_ModgmGmkPopSteamStart(gMS_GMK_P_STEAM_WORK, ref oBS_RECT_WORK.rect.left);
			break;
		default:
			_ModgmGmkPopSteamStart(gMS_GMK_P_STEAM_WORK, ref oBS_RECT_WORK.rect.top);
			break;
		}
		gMS_GMK_P_STEAM_WORK.timer = 0;
		gMS_GMK_P_STEAM_WORK.status = 0;
		gMS_GMK_P_STEAM_WORK.opt_steam = null;
		gMS_GMK_P_STEAM_WORK.pos_x = obj_work.pos.x;
		gMS_GMK_P_STEAM_WORK.pos_y = obj_work.pos.y;
		if (gMS_GMK_P_STEAM_WORK.steamwait > 0)
		{
			uint sync_time = g_gm_main_system.sync_time;
			sync_time %= (uint)(gMS_GMK_P_STEAM_WORK.steamwait + 60);
			if (sync_time < 60)
			{
				gMS_GMK_P_STEAM_WORK.timer = (short)(sync_time * gMS_GMK_P_STEAM_WORK.steamwait / 60);
				gmGmkPopSteamInterval(obj_work);
			}
			else
			{
				gMS_GMK_P_STEAM_WORK.timer = (short)(gMS_GMK_P_STEAM_WORK.steamwait - (sync_time - 60));
				gmGmkPopSteamWait(obj_work);
			}
			create_steampipe(obj_work, gMS_GMK_P_STEAM_WORK.obj_type);
			gMS_GMK_P_STEAM_WORK.opt_timer = create_steamtimer(obj_work, gMS_GMK_P_STEAM_WORK.obj_type);
		}
		else
		{
			OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)GmEfctCmnEsCreate(obj_work, tbl_popsteam_effct[1][gMS_GMK_P_STEAM_WORK.steamsize]);
			oBS_OBJECT_WORK.dir.z = obj_work.dir.z;
			oBS_OBJECT_WORK.pos.z -= 4096;
			gmGmkPopSteamStay(obj_work);
		}
	}

	private static void gmGmkPopSteamHit(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_GMK_P_STEAM_WORK gMS_GMK_P_STEAM_WORK = (GMS_GMK_P_STEAM_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_PLAYER_WORK == g_gm_main_system.ply_work[0])
		{
			gMS_GMK_P_STEAM_WORK.ply_work = gMS_PLAYER_WORK;
			gMS_GMK_P_STEAM_WORK.status |= 1;
		}
		mine_rect.flag &= 4294573823u;
	}

	private static void create_steampipe(OBS_OBJECT_WORK parent_obj, int obj_type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_GMK_POPSTEAMPARTS_WORK(), null, 0, "Gmk_PopSteamPipe");
		GMS_GMK_POPSTEAMPARTS_WORK gMS_GMK_POPSTEAMPARTS_WORK = (GMS_GMK_POPSTEAMPARTS_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_popsteam_obj_3d_list[tbl_popsteam_pipe_model_id[obj_type]], gMS_GMK_POPSTEAMPARTS_WORK.eff_work.obj_3d);
		oBS_OBJECT_WORK.ppOut = gmGmkBeltPopSteam_ppOutUseDirModel;
		oBS_OBJECT_WORK.parent_obj = parent_obj;
		oBS_OBJECT_WORK.pos.x = parent_obj.pos.x + tbl_popsteam_pipe_off[obj_type][0];
		oBS_OBJECT_WORK.pos.y = parent_obj.pos.y + tbl_popsteam_pipe_off[obj_type][1];
		oBS_OBJECT_WORK.pos.z = parent_obj.pos.z - 65536;
		oBS_OBJECT_WORK.dir.z = parent_obj.dir.z;
		oBS_OBJECT_WORK.flag &= 4294966271u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.disp_flag &= 4294967039u;
		oBS_OBJECT_WORK.ppFunc = null;
	}

	private static void gmGmkPopSteamTimer(OBS_OBJECT_WORK obj_work)
	{
		GMS_GMK_P_STEAM_WORK gMS_GMK_P_STEAM_WORK = (GMS_GMK_P_STEAM_WORK)obj_work.parent_obj;
		uint num = 65536u;
		int num2 = 4096;
		num *= (uint)gMS_GMK_P_STEAM_WORK.timer;
		num /= (uint)gMS_GMK_P_STEAM_WORK.steamwait;
		obj_work.dir.z = obj_work.parent_obj.dir.z;
		obj_work.dir.z += (ushort)num;
		num2 += (int)num;
		obj_work.parent_ofst.z = num2 >> 3;
		obj_work.ofst.x = obj_work.parent_obj.ofst.x;
		obj_work.ofst.y = obj_work.parent_obj.ofst.x;
	}

	private static OBS_OBJECT_WORK create_steamtimer(OBS_OBJECT_WORK parent_obj, int obj_type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_GMK_POPSTEAMPARTS_WORK(), null, 0, "Gmk_PopSteamTimer");
		GMS_GMK_POPSTEAMPARTS_WORK gMS_GMK_POPSTEAMPARTS_WORK = (GMS_GMK_POPSTEAMPARTS_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_popsteam_obj_3d_list[12], gMS_GMK_POPSTEAMPARTS_WORK.eff_work.obj_3d);
		oBS_OBJECT_WORK.parent_obj = parent_obj;
		oBS_OBJECT_WORK.parent_ofst.x = tbl_popsteam_timer_off[obj_type][0];
		oBS_OBJECT_WORK.parent_ofst.y = tbl_popsteam_timer_off[obj_type][1];
		oBS_OBJECT_WORK.parent_ofst.z = 0;
		oBS_OBJECT_WORK.dir.z = parent_obj.dir.z;
		oBS_OBJECT_WORK.flag |= 1024u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.disp_flag &= 4294967039u;
		oBS_OBJECT_WORK.ppFunc = gmGmkPopSteamTimer;
		return oBS_OBJECT_WORK;
	}

	private static OBS_OBJECT_WORK gmGmkPopSteamInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type, int obj_type)
	{
		UNREFERENCED_PARAMETER(type);
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_GMK_P_STEAM_WORK(), "Gmk_PopSteam");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		int num = tbl_popsteam_model_id[obj_type][0];
		if (eve_rec.height == 0)
		{
			num = tbl_popsteam_model_id[obj_type][1];
		}
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_popsteam_obj_3d_list[num], gMS_ENEMY_3D_WORK.obj_3d);
		oBS_OBJECT_WORK.ppOut = gmGmkBeltPopSteam_ppOutUseDirModel;
		oBS_OBJECT_WORK.pos.z = 622592;
		oBS_OBJECT_WORK.move_flag |= 256u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		GMS_GMK_P_STEAM_WORK gMS_GMK_P_STEAM_WORK = (GMS_GMK_P_STEAM_WORK)oBS_OBJECT_WORK;
		if ((eve_rec.flag & 3) == 2)
		{
			gMS_GMK_P_STEAM_WORK.steamsize = 2;
		}
		else if ((eve_rec.flag & 3) == 1)
		{
			gMS_GMK_P_STEAM_WORK.steamsize = 0;
		}
		else
		{
			gMS_GMK_P_STEAM_WORK.steamsize = 1;
		}
		gMS_GMK_P_STEAM_WORK.steampower = eve_rec.width * 2;
		gMS_GMK_P_STEAM_WORK.steampower <<= 12;
		if (gMS_GMK_P_STEAM_WORK.steampower == 0)
		{
			gMS_GMK_P_STEAM_WORK.steampower = 61440;
		}
		gMS_GMK_P_STEAM_WORK.steamwait = (short)(eve_rec.height * 2);
		gMS_GMK_P_STEAM_WORK.obj_type = obj_type;
		return oBS_OBJECT_WORK;
	}

