	private static void gmGmkItemMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		if (gMS_ENEMY_3D_WORK.ene_com.eve_rec.byte_param[1] != 0)
		{
			ObjObjectAction3dNNModelReleaseCopy(obj_work);
			ObjObjectCopyAction3dNNModel(obj_work, gm_gmk_item_obj_3d_list[1], gMS_ENEMY_3D_WORK.obj_3d);
			obj_work.disp_flag |= 16777216u;
			nnMakeUnitMatrix(obj_work.obj_3d.user_obj_mtx_r);
			nnTranslateMatrix(obj_work.obj_3d.user_obj_mtx_r, obj_work.obj_3d.user_obj_mtx_r, 0f, -1f / FXM_FX32_TO_FLOAT(g_obj.draw_scale.y), 0f);
			if (g_gs_main_sys_info.stage_id == 2)
			{
				GmEfctZoneEsCreate(obj_work, 0, 1);
			}
			else if (GMM_MAIN_GET_ZONE_TYPE() == 2)
			{
				if (GmMainIsWaterLevel() && obj_work.pos.y - 196608 >> 12 > g_gm_main_system.water_level)
				{
					GmEfctZoneEsCreate(obj_work, 2, 9);
				}
				else
				{
					GmEfctCmnEsCreate(obj_work, 39);
				}
			}
			else
			{
				GmEfctCmnEsCreate(obj_work, 39);
			}
			gmGmkItemCreatePopUpEffect(obj_work, (int)obj_work.user_work);
			obj_work.ppFunc = gmGmkItemEffectWatiMain;
			obj_work.user_timer = 245760;
			if (gmGmkItemConvEvtId(gMS_ENEMY_3D_WORK.ene_com.eve_rec.id) == 67)
			{
				obj_work.user_timer = 1;
			}
			obj_work.flag |= 16u;
			if (obj_work.user_flag != 0)
			{
				GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = (GMS_EFFECT_3DES_WORK)obj_work.user_flag_OBJECT;
				gMS_EFFECT_3DES_WORK.efct_com.obj_work.flag |= 8u;
			}
		}
		if ((obj_work.move_flag & 0x80) != 0 && (obj_work.move_flag & 1) != 0)
		{
			obj_work.move_flag &= 4294967151u;
			obj_work.spd.y = (obj_work.spd_add.y = 0);
			obj_work.flag &= 4294967293u;
		}
	}

	private static void gmGmkItemEffectWatiMain(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_timer = ObjTimeCountDown(obj_work.user_timer);
		if (obj_work.user_timer <= 0)
		{
			GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)obj_work;
			if (gMS_ENEMY_COM_WORK.target_obj != null)
			{
				switch (gmGmkItemConvEvtId(gMS_ENEMY_COM_WORK.eve_rec.id))
				{
				case 63:
					GmPlayerItemHiSpeedSet((GMS_PLAYER_WORK)gMS_ENEMY_COM_WORK.target_obj);
					break;
				case 64:
					GmPlayerItemInvincibleSet((GMS_PLAYER_WORK)gMS_ENEMY_COM_WORK.target_obj);
					break;
				case 65:
					GmPlayerItemRing10Set((GMS_PLAYER_WORK)gMS_ENEMY_COM_WORK.target_obj);
					break;
				case 66:
					GmPlayerItemBarrierSet((GMS_PLAYER_WORK)gMS_ENEMY_COM_WORK.target_obj);
					break;
				case 67:
					GmPlayerItem1UPSet((GMS_PLAYER_WORK)gMS_ENEMY_COM_WORK.target_obj);
					break;
				}
			}
			gMS_ENEMY_COM_WORK.target_obj = null;
			obj_work.flag &= 4294967279u;
			obj_work.ppFunc = gmGmkItemFallCheckMain;
		}
		gmGmkItemFallCheckMain(obj_work);
	}

	private static void gmGmkItemFallCheckMain(OBS_OBJECT_WORK obj_work)
	{
		if ((obj_work.move_flag & 0x80) != 0 && (obj_work.move_flag & 1) != 0)
		{
			obj_work.move_flag &= 4294967151u;
			obj_work.spd.y = (obj_work.spd_add.y = 0);
		}
	}

	private static ushort gmGmkItemConvEvtId(ushort eve_id)
	{
		if (g_gs_main_sys_info.game_mode == 1 && eve_id == 67)
		{
			eve_id = 65;
		}
		return eve_id;
	}

