	private static void gmGmkItemBodyDefFunc(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_ENEMY_COM_WORK != null && gMS_PLAYER_WORK != null && gMS_PLAYER_WORK.obj_work.obj_type == 1 && gMS_PLAYER_WORK.obj_work.touch_obj == gMS_ENEMY_COM_WORK.obj_work)
		{
			short num = gMS_PLAYER_WORK.obj_work.field_rect[1];
			int num2 = gMS_ENEMY_COM_WORK.col_work.obj_col.height + gMS_ENEMY_COM_WORK.col_work.obj_col.ofst_y << 12;
			if (gMS_PLAYER_WORK.obj_work.pos.y + num >= gMS_ENEMY_COM_WORK.obj_work.pos.y + num2 && gMS_PLAYER_WORK.obj_work.move.y <= 0)
			{
				gMS_ENEMY_COM_WORK.obj_work.spd.y = -8192;
				gMS_ENEMY_COM_WORK.obj_work.move_flag |= 144u;
				gMS_ENEMY_COM_WORK.obj_work.move_flag &= 4294967294u;
				gMS_ENEMY_COM_WORK.obj_work.flag |= 2u;
			}
		}
	}

	private static void gmGmkItemDamageDefFunc(OBS_RECT_WORK mine_rect, OBS_RECT_WORK match_rect)
	{
		GMS_ENEMY_COM_WORK gMS_ENEMY_COM_WORK = (GMS_ENEMY_COM_WORK)mine_rect.parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)match_rect.parent_obj;
		if (gMS_ENEMY_COM_WORK != null && gMS_PLAYER_WORK != null && gMS_PLAYER_WORK.obj_work.obj_type == 1 && (gMS_PLAYER_WORK.seq_state == 19 || gMS_PLAYER_WORK.seq_state == 10 || gMS_PLAYER_WORK.obj_work.touch_obj != gMS_ENEMY_COM_WORK.obj_work) && (gMS_PLAYER_WORK.seq_state == 19 || gMS_PLAYER_WORK.seq_state == 10 || (gMS_PLAYER_WORK.obj_work.move.y > 0 && gMS_PLAYER_WORK.obj_work.pos.x + (gMS_PLAYER_WORK.obj_work.field_rect[2] << 12) >= gMS_ENEMY_COM_WORK.obj_work.pos.x - 81920 && gMS_PLAYER_WORK.obj_work.pos.x + (gMS_PLAYER_WORK.obj_work.field_rect[0] << 12) <= gMS_ENEMY_COM_WORK.obj_work.pos.x + 81920)))
		{
			gMS_ENEMY_COM_WORK.eve_rec.byte_param[1] = 1;
			gMS_ENEMY_COM_WORK.obj_work.flag |= 2u;
			gMS_ENEMY_COM_WORK.col_work.obj_col.obj = null;
			gMS_ENEMY_COM_WORK.obj_work.move_flag |= 144u;
			gMS_ENEMY_COM_WORK.obj_work.move_flag &= 4294967294u;
			gMS_ENEMY_COM_WORK.target_obj = gMS_PLAYER_WORK.obj_work;
			GmPlySeqAtkReactionInit(gMS_PLAYER_WORK);
			GmSoundPlaySE("Enemy");
			GMM_PAD_VIB_SMALL();
		}
	}

	private static bool gmGmkItemMaterialCallback(NNS_DRAWCALLBACK_VAL val, object param)
	{
		if (param != null)
		{
			GMS_GMK_ITEM_MAT_CB_PARAM gMS_GMK_ITEM_MAT_CB_PARAM = (GMS_GMK_ITEM_MAT_CB_PARAM)param;
			uint num = ObjDraw3DNNGetMaterialUserData(val);
			if (num == 0 || num == 64 || num == gMS_GMK_ITEM_MAT_CB_PARAM.draw_id)
			{
				return nnPutMaterialCore(val) == 1;
			}
		}
		return false;
	}

	private static void gmGmkItemCreatePopUpEffect(OBS_OBJECT_WORK parent_obj, int mat_id)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_EFFECT_CREATE_WORK(() => new GMS_EFFECT_3DNN_WORK(), null, 0, "GMK_ITEM_POP");
		GMS_EFFECT_3DNN_WORK gMS_EFFECT_3DNN_WORK = (GMS_EFFECT_3DNN_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_gmk_item_obj_3d_list[2], gMS_EFFECT_3DNN_WORK.obj_3d);
		oBS_OBJECT_WORK.pos.x = parent_obj.pos.x;
		oBS_OBJECT_WORK.pos.y = parent_obj.pos.y + -86016;
		oBS_OBJECT_WORK.pos.z = -524288;
		gMS_EFFECT_3DNN_WORK.obj_3d.material_cb_func = gmGmkItemMaterialCallback;
		oBS_OBJECT_WORK.ppOut = gmGmkItemOut;
		oBS_OBJECT_WORK.user_work = (uint)mat_id;
		oBS_OBJECT_WORK.flag |= 18u;
		oBS_OBJECT_WORK.disp_flag |= 4194304u;
		oBS_OBJECT_WORK.move_flag &= 4294967167u;
		oBS_OBJECT_WORK.scale.x = (oBS_OBJECT_WORK.scale.y = 6144);
		oBS_OBJECT_WORK.ppFunc = gmGmkItemPopUpEffectMain;
		oBS_OBJECT_WORK.spd.y = -10240;
		oBS_OBJECT_WORK.spd_add.y = 320;
	}

	private static void gmGmkItemPopUpEffectMain(OBS_OBJECT_WORK obj_work)
	{
		if (obj_work.spd.y == 0)
		{
			obj_work.user_timer = ObjTimeCountDown(obj_work.user_timer);
			if (obj_work.user_timer <= 0)
			{
				obj_work.flag |= 4u;
			}
		}
		else if (obj_work.spd.y + obj_work.spd_add.y >= 0)
		{
			obj_work.spd.y = (obj_work.spd_add.y = 0);
			obj_work.user_timer = 122880;
			obj_work.move_flag |= 8192u;
		}
	}

	private static void GmEneGardonBuild()
	{
		gm_ene_gardon_obj_3d_list = GmGameDBuildRegBuildModel(readAMBFile(GmGameDatGetEnemyData(677)), readAMBFile(GmGameDatGetEnemyData(678)), 0u);
	}

	private static void GmEneGardonFlush()
	{
		AMS_AMB_HEADER aMS_AMB_HEADER = readAMBFile(GmGameDatGetEnemyData(677));
		GmGameDBuildRegFlushModel(gm_ene_gardon_obj_3d_list, aMS_AMB_HEADER.file_num);
	}

	private static OBS_OBJECT_WORK GmEneGardonInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENE_GARDON_WORK(), "ENE_GARDON");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_ENE_GARDON_WORK gMS_ENE_GARDON_WORK = (GMS_ENE_GARDON_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_gardon_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(679), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.z = 0;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -11, -24, 11, 0);
		oBS_RECT_WORK.flag |= 1024u;
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		oBS_RECT_WORK.ppDef = gmEneGardonDefFunc;
		ObjRectWorkSet(oBS_RECT_WORK, -24, -32, 24, 0);
		oBS_RECT_WORK.flag |= 1024u;
		oBS_RECT_WORK.flag |= 4u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -32, 19, 0);
		oBS_RECT_WORK.flag &= 4294967291u;
		ObjObjectFieldRectSet(oBS_OBJECT_WORK, -4, -8, 4, -2);
		oBS_OBJECT_WORK.move_flag |= 128u;
		if ((eve_rec.flag & 1) == 0)
		{
			oBS_OBJECT_WORK.disp_flag |= 1u;
		}
		oBS_OBJECT_WORK.user_work = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left << 12));
		oBS_OBJECT_WORK.user_flag = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left + eve_rec.width << 12));
		gMS_ENE_GARDON_WORK.spd_dec = 51;
		gMS_ENE_GARDON_WORK.spd_dec_dist = 10240;
		gmEneGardonWalkInit(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

	private static int gmEneGardonGetLength2N(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((gMS_PLAYER_WORK.player_flag & 0x400) != 0)
		{
			return int.MaxValue;
		}
		int x = gMS_PLAYER_WORK.obj_work.pos.x - obj_work.pos.x;
		int x2 = gMS_PLAYER_WORK.obj_work.pos.y - obj_work.pos.y;
		float num = FX_FX32_TO_F32(x);
		float num2 = FX_FX32_TO_F32(x2);
		return (int)(num * num + num2 * num2);
	}

	private static int gmEneGardonIsPlayerAttack()
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if (gMS_PLAYER_WORK.seq_state == 19 || gMS_PLAYER_WORK.seq_state == 17 || gMS_PLAYER_WORK.seq_state == 10)
		{
			return 1;
		}
		return 0;
	}

	private static int gmEneGardonIsPlayerFront(OBS_OBJECT_WORK obj_work)
	{
		GMS_PLAYER_WORK gMS_PLAYER_WORK = g_gm_main_system.ply_work[0];
		if ((obj_work.disp_flag & 1) != 0)
		{
			if (obj_work.pos.x > gMS_PLAYER_WORK.obj_work.pos.x)
			{
				return 1;
			}
		}
		else if (obj_work.pos.x < gMS_PLAYER_WORK.obj_work.pos.x)
		{
			return 1;
		}
		return 0;
	}

	private static void gmEneGardonAtkRectOff(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		oBS_RECT_WORK.flag &= 4294967291u;
	}

	private static void gmEneGardonAtkRectOn(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		oBS_RECT_WORK.flag |= 4u;
	}

	private static void gmEneGardonDefFunc(OBS_RECT_WORK my_rect, OBS_RECT_WORK your_rect)
	{
		OBS_OBJECT_WORK parent_obj = my_rect.parent_obj;
		OBS_OBJECT_WORK parent_obj2 = your_rect.parent_obj;
		GMS_ENE_GARDON_WORK gMS_ENE_GARDON_WORK = (GMS_ENE_GARDON_WORK)parent_obj;
		GMS_PLAYER_WORK gMS_PLAYER_WORK = (GMS_PLAYER_WORK)parent_obj2;
		if (parent_obj2 == null || 1 != parent_obj2.obj_type)
		{
			return;
		}
		if (gMS_PLAYER_WORK.seq_state == 19 || gMS_PLAYER_WORK.seq_state == 20)
		{
			if (gmEneGardonIsPlayerFront(parent_obj) != 0)
			{
				GmEneComActionSetDependHFlip(parent_obj, 8, 9);
				parent_obj.disp_flag &= 4294967291u;
				gMS_ENE_GARDON_WORK.shield = 1;
				GmPlySeqAtkReactionInit(gMS_PLAYER_WORK);
				gMS_PLAYER_WORK.obj_work.spd.y = (int)((float)gMS_PLAYER_WORK.obj_work.spd.y * 1.5f);
				GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctEneEsCreate(parent_obj, 5);
				gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.x = parent_obj.pos.x;
				gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.y = parent_obj.pos.y;
				GmEffect3DESAddDispOffset(gMS_EFFECT_3DES_WORK, 0f, 30f, 0f);
				GmSoundPlaySE("Casino1");
				gmEneGardonAtkRectOff(parent_obj);
			}
			else
			{
				GmEnemyDefaultDefFunc(my_rect, your_rect);
			}
		}
		else if (parent_obj.pos.y - FX_F32_TO_FX32(20f) > parent_obj2.pos.y)
		{
			if (gmEneGardonIsPlayerFront(parent_obj) != 0 || (parent_obj.disp_flag & 1) != (parent_obj2.disp_flag & 1))
			{
				GmEneComActionSetDependHFlip(parent_obj, 8, 9);
				parent_obj.disp_flag &= 4294967291u;
				gMS_ENE_GARDON_WORK.shield = 1;
				GmPlySeqAtkReactionInit(gMS_PLAYER_WORK);
				gMS_PLAYER_WORK.obj_work.spd.y = (int)((float)gMS_PLAYER_WORK.obj_work.spd.y * 1.5f);
				GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctEneEsCreate(parent_obj, 5);
				gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.x = parent_obj.pos.x;
				gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.y = parent_obj.pos.y;
				GmEffect3DESAddDispOffset(gMS_EFFECT_3DES_WORK, 0f, 30f, 0f);
				GmSoundPlaySE("Casino1");
			}
			else
			{
				GmEnemyDefaultDefFunc(my_rect, your_rect);
			}
		}
		else if (gmEneGardonIsPlayerFront(parent_obj) != 0)
		{
			GmEneComActionSetDependHFlip(parent_obj, 4, 5);
			parent_obj.disp_flag &= 4294967291u;
			gMS_ENE_GARDON_WORK.shield = 2;
			gMS_PLAYER_WORK.obj_work.disp_flag ^= 1u;
			GmPlySeqChangeSequence(gMS_PLAYER_WORK, 10);
			if (gMS_PLAYER_WORK.obj_work.spd_m != 0)
			{
				gMS_PLAYER_WORK.obj_work.spd_m = -gMS_PLAYER_WORK.obj_work.spd_m;
				if (MTM_MATH_ABS(gMS_PLAYER_WORK.obj_work.spd_m) < 32768)
				{
					if ((gMS_PLAYER_WORK.obj_work.disp_flag & 1) != 0)
					{
						gMS_PLAYER_WORK.obj_work.spd_m = -32768;
					}
					else
					{
						gMS_PLAYER_WORK.obj_work.spd_m = 32768;
					}
				}
			}
			else if (parent_obj.pos.x > gMS_PLAYER_WORK.obj_work.pos.x)
			{
				gMS_PLAYER_WORK.obj_work.spd_m = -49152;
				gMS_PLAYER_WORK.obj_work.disp_flag |= 1u;
			}
			else
			{
				gMS_PLAYER_WORK.obj_work.spd_m = 49152;
				gMS_PLAYER_WORK.obj_work.disp_flag &= 4294967294u;
			}
			GMS_EFFECT_3DES_WORK gMS_EFFECT_3DES_WORK = GmEfctEneEsCreate(parent_obj, 5);
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.x = parent_obj.pos.x;
			gMS_EFFECT_3DES_WORK.efct_com.obj_work.pos.y = parent_obj.pos.y;
			GmSoundPlaySE("Casino1");
		}
		else
		{
			GmEnemyDefaultDefFunc(my_rect, your_rect);
		}
	}

	private static void gmEneGardonWalkInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GmEneComActionSetDependHFlip(obj_work, 0, 1);
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneGardonWalkMain;
		obj_work.move_flag &= 4294967291u;
		if ((obj_work.disp_flag & 1) != 0)
		{
			obj_work.spd.x = -1024;
		}
		else
		{
			obj_work.spd.x = 1024;
		}
	}

	private static void gmEneGardonWalkMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_GARDON_WORK gMS_ENE_GARDON_WORK = (GMS_ENE_GARDON_WORK)obj_work;
		if (gMS_ENE_GARDON_WORK.shield != 0)
		{
			obj_work.spd.x = 0;
			if ((obj_work.disp_flag & 8) != 0)
			{
				if (gMS_ENE_GARDON_WORK.shield == 1)
				{
					GmEneComActionSetDependHFlip(obj_work, 10, 11);
				}
				else
				{
					GmEneComActionSetDependHFlip(obj_work, 6, 7);
				}
				gmEneGardonAtkRectOn(obj_work);
				gMS_ENE_GARDON_WORK.shield = 0;
				obj_work.ppFunc = gmEneGardonWalkWait;
			}
			return;
		}
		if ((obj_work.disp_flag & 1) != 0)
		{
			obj_work.spd.x = -1024;
		}
		else
		{
			obj_work.spd.x = 1024;
		}
		if (obj_work.obj_3d.frame[0] >= 40f && obj_work.obj_3d.frame[0] <= 60f)
		{
			obj_work.spd.x = 0;
		}
		if (obj_work.obj_3d.frame[0] >= 100f && obj_work.obj_3d.frame[0] <= 120f)
		{
			obj_work.spd.x = 0;
		}
		if (gmEneGardonGetLength2N(obj_work) <= 4)
		{
			obj_work.ppFunc = gmEneGardonWaitToWalkInit;
		}
		else if ((obj_work.move_flag & 4) != 0 || GmEneComCheckMoveLimit(obj_work, (int)obj_work.user_work, (int)obj_work.user_flag) == 0)
		{
			gmEneGardonWaitToFlipInit(obj_work);
		}
	}

	private static void gmEneGardonWalkWait(OBS_OBJECT_WORK obj_work)
	{
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.ppFunc = gmEneGardonWaitToWalkInit;
		}
	}

	private static void gmEneGardonWaitToFlipInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		obj_work.ppFunc = gmEneGardonWaitToFlipMain;
		obj_work.spd.x = 0;
		GMS_ENE_GARDON_WORK gMS_ENE_GARDON_WORK = (GMS_ENE_GARDON_WORK)obj_work;
		gMS_ENE_GARDON_WORK.timer = 1;
		GmEneComActionSetDependHFlip(obj_work, 0, 1);
	}

	private static void gmEneGardonWaitToFlipMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_GARDON_WORK gMS_ENE_GARDON_WORK = (GMS_ENE_GARDON_WORK)obj_work;
		if (gMS_ENE_GARDON_WORK.timer > 0)
		{
			gMS_ENE_GARDON_WORK.timer--;
		}
		else
		{
			gmEneGardonFlipInit(obj_work);
		}
	}

	private static void gmEneGardonWaitToWalkInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		obj_work.ppFunc = gmEneGardonWaitToWalkMain;
		obj_work.spd.x = 0;
		GMS_ENE_GARDON_WORK gMS_ENE_GARDON_WORK = (GMS_ENE_GARDON_WORK)obj_work;
		gMS_ENE_GARDON_WORK.timer = 60;
		GmEneComActionSetDependHFlip(obj_work, 0, 1);
		obj_work.disp_flag |= 4u;
		gmEneGardonAtkRectOn(obj_work);
		gMS_ENE_GARDON_WORK.shield = 0;
	}

	private static void gmEneGardonWaitToWalkMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_GARDON_WORK gMS_ENE_GARDON_WORK = (GMS_ENE_GARDON_WORK)obj_work;
		if (gMS_ENE_GARDON_WORK.shield != 0)
		{
			obj_work.spd.x = 0;
			if ((obj_work.disp_flag & 8) != 0)
			{
				if (gMS_ENE_GARDON_WORK.shield == 1)
				{
					GmEneComActionSetDependHFlip(obj_work, 10, 11);
				}
				else
				{
					GmEneComActionSetDependHFlip(obj_work, 6, 7);
				}
				gmEneGardonAtkRectOn(obj_work);
				gMS_ENE_GARDON_WORK.shield = 0;
				obj_work.ppFunc = gmEneGardonWalkWait;
			}
		}
		else if (gmEneGardonGetLength2N(obj_work) > 4)
		{
			obj_work.ppFunc = gmEneGardonWalkInit;
		}
	}

	private static void gmEneGardonFlipInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GmEneComActionSetDependHFlip(obj_work, 2, 3);
		obj_work.ppFunc = gmEneGardonFlipMain;
	}

	private static void gmEneGardonFlipMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_GARDON_WORK gMS_ENE_GARDON_WORK = (GMS_ENE_GARDON_WORK)obj_work;
		if (gMS_ENE_GARDON_WORK.shield != 0)
		{
			obj_work.disp_flag ^= 1u;
			obj_work.ppFunc = gmEneGardonWalkMain;
			return;
		}
		gmEneGardonSetWalkSpeed((GMS_ENE_GARDON_WORK)obj_work);
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.disp_flag ^= 1u;
			gmEneGardonWalkInit(obj_work);
		}
	}

	private static int gmEneGardonSetWalkSpeed(GMS_ENE_GARDON_WORK gardon_work)
	{
		int result = 0;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)gardon_work;
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			if (oBS_OBJECT_WORK.obj_3d.act_id[0] == 2 && oBS_OBJECT_WORK.obj_3d.frame[0] >= 20f)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, gardon_work.spd_dec, 1024);
			}
			else if (oBS_OBJECT_WORK.pos.x <= (int)oBS_OBJECT_WORK.user_work + gardon_work.spd_dec_dist)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdDownSet(oBS_OBJECT_WORK.spd.x, gardon_work.spd_dec);
				result = 1;
				if (oBS_OBJECT_WORK.spd.x == 0 && oBS_OBJECT_WORK.pos.x > (int)oBS_OBJECT_WORK.user_work)
				{
					oBS_OBJECT_WORK.spd.x = (int)oBS_OBJECT_WORK.user_work - oBS_OBJECT_WORK.pos.x;
					if (oBS_OBJECT_WORK.spd.x < -gardon_work.spd_dec)
					{
						oBS_OBJECT_WORK.spd.x = -gardon_work.spd_dec;
					}
				}
			}
			else if (oBS_OBJECT_WORK.spd.x > -1024)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, -gardon_work.spd_dec, 1024);
			}
		}
		else if (oBS_OBJECT_WORK.obj_3d.act_id[0] == 2 && oBS_OBJECT_WORK.obj_3d.frame[0] >= 20f)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, -gardon_work.spd_dec, 1024);
		}
		else if (oBS_OBJECT_WORK.pos.x >= (int)oBS_OBJECT_WORK.user_flag - gardon_work.spd_dec_dist)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdDownSet(oBS_OBJECT_WORK.spd.x, gardon_work.spd_dec);
			result = 1;
			if (oBS_OBJECT_WORK.spd.x == 0 && oBS_OBJECT_WORK.pos.x < (int)oBS_OBJECT_WORK.user_flag)
			{
				oBS_OBJECT_WORK.spd.x = (int)oBS_OBJECT_WORK.user_flag - oBS_OBJECT_WORK.pos.x;
				if (oBS_OBJECT_WORK.spd.x > gardon_work.spd_dec)
				{
					oBS_OBJECT_WORK.spd.x = gardon_work.spd_dec;
				}
			}
		}
		else if (oBS_OBJECT_WORK.spd.x < 1024)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, gardon_work.spd_dec, 1024);
		}
		return result;
	}

