	private static OBS_OBJECT_WORK GmEneBukuInit(GMS_EVE_RECORD_EVENT eve_rec, int pos_x, int pos_y, byte type)
	{
		OBS_OBJECT_WORK oBS_OBJECT_WORK = GMM_ENEMY_CREATE_WORK(eve_rec, pos_x, pos_y, () => new GMS_ENE_BUKU_WORK(), "ENE_BUKU");
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)oBS_OBJECT_WORK;
		GMS_ENE_BUKU_WORK gMS_ENE_BUKU_WORK = (GMS_ENE_BUKU_WORK)oBS_OBJECT_WORK;
		ObjObjectCopyAction3dNNModel(oBS_OBJECT_WORK, gm_ene_buku_obj_3d_list[0], gMS_ENEMY_3D_WORK.obj_3d);
		ObjObjectAction3dNNMotionLoad(oBS_OBJECT_WORK, 0, true, ObjDataGet(698), null, 0, null);
		ObjDrawObjectSetToon(oBS_OBJECT_WORK);
		oBS_OBJECT_WORK.pos.z = 0;
		OBS_RECT_WORK oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[1];
		ObjRectWorkSet(oBS_RECT_WORK, -8, -8, 8, 8);
		oBS_RECT_WORK.flag |= 4u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[0];
		ObjRectWorkSet(oBS_RECT_WORK, -16, -16, 16, 16);
		oBS_RECT_WORK.flag |= 4u;
		gMS_ENEMY_3D_WORK.ene_com.rect_work[2].flag &= 4294967291u;
		oBS_RECT_WORK = gMS_ENEMY_3D_WORK.ene_com.rect_work[2];
		ObjRectWorkSet(oBS_RECT_WORK, -19, -16, 19, 16);
		oBS_RECT_WORK.flag &= 4294967291u;
		oBS_OBJECT_WORK.move_flag |= 256u;
		oBS_OBJECT_WORK.move_flag &= 4294967167u;
		if ((eve_rec.flag & 1) == 0)
		{
			oBS_OBJECT_WORK.disp_flag |= 1u;
		}
		oBS_OBJECT_WORK.user_work = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left << 12));
		oBS_OBJECT_WORK.user_flag = (uint)(oBS_OBJECT_WORK.pos.x + (eve_rec.left + eve_rec.width << 12));
		gMS_ENE_BUKU_WORK.spd_dec = 102;
		gMS_ENE_BUKU_WORK.spd_dec_dist = 20480;
		gmEneBukuWalkInit(oBS_OBJECT_WORK);
		GMS_EFFECT_3DES_WORK efct_work = GmEfctEneEsCreate(oBS_OBJECT_WORK, 9);
		GmComEfctSetDispOffsetF(efct_work, -24f, -5f, 0f);
		oBS_OBJECT_WORK.obj_3d.use_light_flag &= 4294967294u;
		oBS_OBJECT_WORK.obj_3d.use_light_flag |= 64u;
		return oBS_OBJECT_WORK;
	}

	private static void gmEneBukuWalkInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GmEneComActionSetDependHFlip(obj_work, 0, 1);
		obj_work.disp_flag |= 4u;
		obj_work.ppFunc = gmEneBukuWalkMain;
		obj_work.move_flag &= 4294967291u;
		if ((obj_work.disp_flag & 1) != 0)
		{
			obj_work.spd.x = -2048;
		}
		else
		{
			obj_work.spd.x = 2048;
		}
	}

	private static void gmEneBukuWalkMain(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENE_BUKU_WORK gMS_ENE_BUKU_WORK = (GMS_ENE_BUKU_WORK)obj_work;
		if (gmEneBukuSetWalkSpeed(gMS_ENE_BUKU_WORK) != 0)
		{
			gmEneBukuFlipInit(obj_work);
		}
		if (gMS_ENE_BUKU_WORK.timer > 0)
		{
			gMS_ENE_BUKU_WORK.timer--;
		}
		else
		{
			gMS_ENE_BUKU_WORK.timer = 216000 + mtMathRand() % 30;
		}
	}

	private static void gmEneBukuFwMain(OBS_OBJECT_WORK obj_work)
	{
		obj_work.user_timer = ObjTimeCountDown(obj_work.user_timer);
		if (obj_work.user_timer <= 0)
		{
			gmEneBukuFlipInit(obj_work);
		}
	}

	private static void gmEneBukuFlipInit(OBS_OBJECT_WORK obj_work)
	{
		GMS_ENEMY_3D_WORK gMS_ENEMY_3D_WORK = (GMS_ENEMY_3D_WORK)obj_work;
		GmEneComActionSet3DNNBlendDependHFlip(obj_work, 2, 3);
		obj_work.ppFunc = gmEneBukuFlipMain;
	}

	private static void gmEneBukuFlipMain(OBS_OBJECT_WORK obj_work)
	{
		gmEneBukuSetWalkSpeed((GMS_ENE_BUKU_WORK)obj_work);
		if ((obj_work.disp_flag & 8) != 0)
		{
			obj_work.disp_flag ^= 1u;
			gmEneBukuWalkInit(obj_work);
		}
	}

	private static int gmEneBukuSetWalkSpeed(GMS_ENE_BUKU_WORK buku_work)
	{
		int result = 0;
		OBS_OBJECT_WORK oBS_OBJECT_WORK = (OBS_OBJECT_WORK)buku_work;
		if ((oBS_OBJECT_WORK.disp_flag & 1) != 0)
		{
			if (oBS_OBJECT_WORK.obj_3d.act_id[0] == 3 && oBS_OBJECT_WORK.obj_3d.frame[0] >= 20f)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, buku_work.spd_dec, 2048);
			}
			else if (oBS_OBJECT_WORK.pos.x <= (int)oBS_OBJECT_WORK.user_work + buku_work.spd_dec_dist)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdDownSet(oBS_OBJECT_WORK.spd.x, buku_work.spd_dec);
				result = 1;
				if (oBS_OBJECT_WORK.spd.x == 0 && oBS_OBJECT_WORK.pos.x > (int)oBS_OBJECT_WORK.user_work)
				{
					oBS_OBJECT_WORK.spd.x = (int)oBS_OBJECT_WORK.user_work - oBS_OBJECT_WORK.pos.x;
					if (oBS_OBJECT_WORK.spd.x < -buku_work.spd_dec)
					{
						oBS_OBJECT_WORK.spd.x = -buku_work.spd_dec;
					}
				}
			}
			else if (oBS_OBJECT_WORK.spd.x > -2048)
			{
				oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, -buku_work.spd_dec, 2048);
			}
		}
		else if (oBS_OBJECT_WORK.obj_3d.act_id[0] == 2 && oBS_OBJECT_WORK.obj_3d.frame[0] >= 20f)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, -buku_work.spd_dec, 2048);
		}
		else if (oBS_OBJECT_WORK.pos.x >= (int)oBS_OBJECT_WORK.user_flag - buku_work.spd_dec_dist)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdDownSet(oBS_OBJECT_WORK.spd.x, buku_work.spd_dec);
			result = 1;
			if (oBS_OBJECT_WORK.spd.x == 0 && oBS_OBJECT_WORK.pos.x < (int)oBS_OBJECT_WORK.user_flag)
			{
				oBS_OBJECT_WORK.spd.x = (int)oBS_OBJECT_WORK.user_flag - oBS_OBJECT_WORK.pos.x;
				if (oBS_OBJECT_WORK.spd.x > buku_work.spd_dec)
				{
					oBS_OBJECT_WORK.spd.x = buku_work.spd_dec;
				}
			}
		}
		else if (oBS_OBJECT_WORK.spd.x < 2048)
		{
			oBS_OBJECT_WORK.spd.x = ObjSpdUpSet(oBS_OBJECT_WORK.spd.x, buku_work.spd_dec, 2048);
		}
		return result;
	}

	private static void GmEfctZoneBuildDataInit(int zone_no)
	{
		gm_efct_zone_proc_state = 1;
		gm_efct_zone_target_zone_no = zone_no;
	}

	private static void GmEfctZoneBuildDataLoopInit()
	{
		object texlist_buf = null;
		GMS_EFCT_ZONE_CREATE_INFO gMS_EFCT_ZONE_CREATE_INFO = gm_efct_zone_create_info[gm_efct_zone_target_zone_no];
		int num = 0;
		OBS_DATA_WORK pWork = ObjDataGet(6);
		AMS_AMB_HEADER amb = readAMBFile(ObjDataGetInc(pWork));
		gm_efct_zone_model_reg_num = 1;
		if (gm_efct_zone_model_reg_num > 0)
		{
			gm_efct_zone_model_reg_id_list = new int[gm_efct_zone_model_reg_num];
			gm_efct_zone_mdl_tex_reg_id_list = new int[gm_efct_zone_model_reg_num];
			for (int i = 0; i < gm_efct_zone_model_reg_num; i++)
			{
				gm_efct_zone_model_reg_id_list[i] = -1;
				gm_efct_zone_mdl_tex_reg_id_list[i] = -1;
			}
		}
		OBS_DATA_WORK oBS_DATA_WORK = ObjDataGet(509);
		ObjDataLoadAmbIndex(oBS_DATA_WORK, gm_efct_zone_texamb_index_tbl[gm_efct_zone_target_zone_no], amb);
		gm_efct_zone_tex_reg_id = ObjAction3dESTextureLoadToDwork(ObjDataGet(510), readAMBFile(oBS_DATA_WORK.pData), ref texlist_buf);
		for (int j = 0; j < gMS_EFCT_ZONE_CREATE_INFO.num; j++)
		{
			int model_idx = gMS_EFCT_ZONE_CREATE_INFO.zone_create_param[j].create_param.model_idx;
			int model_dwork_no = gMS_EFCT_ZONE_CREATE_INFO.zone_create_param[j].model_dwork_no;
			int index = gmEfctZoneGetObjectDworkNo(model_dwork_no);
			int mdl_ambtex_idx = gMS_EFCT_ZONE_CREATE_INFO.zone_create_param[j].mdl_ambtex_idx;
			int index2 = gmEfctZoneGetMdlAmbtexDworkNo(model_dwork_no);
			int index3 = gmEfctZoneGetMdlTexlistDworkNo(model_dwork_no);
			if (model_idx != -1)
			{
				oBS_DATA_WORK = ObjDataGet(index2);
				ObjDataLoadAmbIndex(oBS_DATA_WORK, mdl_ambtex_idx, amb);
				gm_efct_zone_mdl_tex_reg_id_list[num] = ObjAction3dESTextureLoadToDwork(ObjDataGet(index3), readAMBFile(oBS_DATA_WORK.pData), ref texlist_buf);
				ObjDataLoadAmbIndex(ObjDataGet(model_dwork_no), model_idx, amb);
				gm_efct_zone_model_reg_id_list[num] = ObjAction3dESModelLoadToDwork(ObjDataGet(index), (AmbChunk)ObjDataGet(model_dwork_no).pData, 0u);
				num++;
			}
		}
	}

	private static bool GmEfctZoneBuildDataLoop()
	{
		bool flag = true;
		if (gm_efct_zone_target_zone_no == -1)
		{
			return flag;
		}
		if (gm_efct_zone_proc_state == 0)
		{
			return true;
		}
		if (gm_efct_zone_proc_state == 1)
		{
			if (GsMainSysGetDisplayListRegistNum() < 208)
			{
				GmEfctZoneBuildDataLoopInit();
				gm_efct_zone_proc_state = 2;
			}
			return false;
		}
		if (gm_efct_zone_tex_reg_id != -1)
		{
			if (amDrawIsRegistComplete(gm_efct_zone_tex_reg_id))
			{
				gm_efct_zone_tex_reg_id = -1;
			}
			else
			{
				flag = false;
			}
		}
		for (int i = 0; i < gm_efct_zone_model_reg_num; i++)
		{
			if (gm_efct_zone_mdl_tex_reg_id_list[i] != -1)
			{
				if (amDrawIsRegistComplete(gm_efct_zone_mdl_tex_reg_id_list[i]))
				{
					gm_efct_zone_mdl_tex_reg_id_list[i] = -1;
				}
				else
				{
					flag = false;
				}
			}
			if (gm_efct_zone_model_reg_id_list[i] != -1)
			{
				if (amDrawIsRegistComplete(gm_efct_zone_model_reg_id_list[i]))
				{
					gm_efct_zone_model_reg_id_list[i] = -1;
				}
				else
				{
					flag = false;
				}
			}
		}
		if (flag)
		{
			gm_efct_zone_target_zone_no = -1;
			gm_efct_zone_proc_state = 0;
		}
		return flag;
	}

	private static void GmEfctZoneFlushDataInit(int zone_no)
	{
		gm_efct_zone_proc_state = 1;
		gm_efct_zone_target_zone_no = zone_no;
	}

	private static void GmEfctZoneFlushDataLoopInit()
	{
		GMS_EFCT_ZONE_CREATE_INFO gMS_EFCT_ZONE_CREATE_INFO = gm_efct_zone_create_info[gm_efct_zone_target_zone_no];
		int num = 0;
		for (int i = 0; i < gMS_EFCT_ZONE_CREATE_INFO.num; i++)
		{
			GMS_EFCT_ZONE_CREATE_PARAM gMS_EFCT_ZONE_CREATE_PARAM = gMS_EFCT_ZONE_CREATE_INFO.zone_create_param[i];
			int model_dwork_no = gMS_EFCT_ZONE_CREATE_PARAM.model_dwork_no;
			int index = gmEfctZoneGetObjectDworkNo(model_dwork_no);
			if (gMS_EFCT_ZONE_CREATE_PARAM.create_param.model_idx != -1)
			{
				gm_efct_zone_model_reg_id_list[num] = ObjAction3dESModelReleaseDwork(ObjDataGet(index));
				OBS_DATA_WORK pWork = ObjDataGet(model_dwork_no);
				ObjDataRelease(pWork);
				gm_efct_zone_mdl_tex_reg_id_list[num] = ObjAction3dESTextureReleaseDwork(ObjDataGet(gmEfctZoneGetMdlTexlistDworkNo(model_dwork_no)));
				ObjDataRelease(ObjDataGet(gmEfctZoneGetMdlAmbtexDworkNo(model_dwork_no)));
				num++;
			}
		}
		gm_efct_zone_tex_reg_id = ObjAction3dESTextureReleaseDwork(ObjDataGet(510));
		OBS_DATA_WORK pWork2 = ObjDataGet(509);
		ObjDataRelease(pWork2);
		OBS_DATA_WORK pWork3 = ObjDataGet(6);
		ObjDataRelease(pWork3);
	}

	private static bool GmEfctZoneFlushDataLoop()
	{
		bool flag = true;
		int num = 0;
		if (gm_efct_zone_proc_state == 0)
		{
			return true;
		}
		if (gm_efct_zone_proc_state == 1)
		{
			if (GsMainSysGetDisplayListRegistNum() < 248)
			{
				GmEfctZoneFlushDataLoopInit();
				gm_efct_zone_proc_state = 2;
			}
			return false;
		}
		GMS_EFCT_ZONE_CREATE_INFO gMS_EFCT_ZONE_CREATE_INFO = gm_efct_zone_create_info[gm_efct_zone_target_zone_no];
		if (gm_efct_zone_model_reg_num != 0)
		{
			for (int i = 0; i < gMS_EFCT_ZONE_CREATE_INFO.num; i++)
			{
				GMS_EFCT_ZONE_CREATE_PARAM gMS_EFCT_ZONE_CREATE_PARAM = gMS_EFCT_ZONE_CREATE_INFO.zone_create_param[i];
				int model_dwork_no = gMS_EFCT_ZONE_CREATE_PARAM.model_dwork_no;
				int index = gmEfctZoneGetObjectDworkNo(model_dwork_no);
				if (gMS_EFCT_ZONE_CREATE_PARAM.create_param.model_idx == -1)
				{
					continue;
				}
				if (gm_efct_zone_model_reg_id_list[num] != -1)
				{
					if (ObjAction3dESModelReleaseDworkCheck(ObjDataGet(index), gm_efct_zone_model_reg_id_list[num]))
					{
						gm_efct_zone_model_reg_id_list[num] = -1;
					}
					else
					{
						flag = false;
					}
				}
				if (gm_efct_zone_mdl_tex_reg_id_list[num] != -1)
				{
					if (ObjAction3dESTextureReleaseDworkCheck(ObjDataGet(gmEfctZoneGetMdlTexlistDworkNo(model_dwork_no)), gm_efct_zone_mdl_tex_reg_id_list[num]))
					{
						gm_efct_zone_mdl_tex_reg_id_list[num] = -1;
					}
					else
					{
						flag = false;
					}
				}
				num++;
			}
		}
		if (gm_efct_zone_tex_reg_id != -1)
		{
			if (ObjAction3dESTextureReleaseDworkCheck(ObjDataGet(510), gm_efct_zone_tex_reg_id))
			{
				gm_efct_zone_tex_reg_id = -1;
			}
			else
			{
				flag = false;
			}
		}
		if (flag)
		{
			if (gm_efct_zone_mdl_tex_reg_id_list != null)
			{
				gm_efct_zone_mdl_tex_reg_id_list = null;
			}
			if (gm_efct_zone_model_reg_id_list != null)
			{
				gm_efct_zone_model_reg_id_list = null;
				gm_efct_zone_model_reg_num = 0;
			}
			gm_efct_zone_target_zone_no = -1;
			gm_efct_zone_proc_state = 0;
		}
		return flag;
	}

	private static GMS_EFFECT_3DES_WORK GmEfctZoneEsCreate(OBS_OBJECT_WORK parent_obj, int zone_no, int efct_zone_idx)
	{
		GMS_EFCT_ZONE_CREATE_INFO gMS_EFCT_ZONE_CREATE_INFO = gm_efct_zone_create_info[zone_no];
		GMS_EFCT_ZONE_CREATE_PARAM gMS_EFCT_ZONE_CREATE_PARAM = gMS_EFCT_ZONE_CREATE_INFO.zone_create_param[efct_zone_idx];
		OBS_DATA_WORK model_dwork;
		OBS_DATA_WORK object_dwork;
		OBS_DATA_WORK oBS_DATA_WORK;
		OBS_DATA_WORK texlist_dwork;
		if (gMS_EFCT_ZONE_CREATE_PARAM.create_param.model_idx != -1)
		{
			int model_dwork_no = gMS_EFCT_ZONE_CREATE_PARAM.model_dwork_no;
			int index = gmEfctZoneGetObjectDworkNo(model_dwork_no);
			model_dwork = ObjDataGet(model_dwork_no);
			object_dwork = ObjDataGet(index);
			oBS_DATA_WORK = ObjDataGet(gmEfctZoneGetMdlAmbtexDworkNo(model_dwork_no));
			texlist_dwork = ObjDataGet(gmEfctZoneGetMdlTexlistDworkNo(model_dwork_no));
		}
		else
		{
			model_dwork = null;
			object_dwork = null;
			oBS_DATA_WORK = ObjDataGet(509);
			texlist_dwork = ObjDataGet(510);
		}
		return GmEffect3dESCreateByParam(gMS_EFCT_ZONE_CREATE_PARAM.create_param, parent_obj, ObjDataGet(6).pData, ObjDataGet(gmEfctZoneGetAmeDworkNo(zone_no, gMS_EFCT_ZONE_CREATE_PARAM.create_param.ame_idx)), oBS_DATA_WORK, texlist_dwork, model_dwork, object_dwork);
	}

	private static int gmEfctZoneGetAmeDworkNo(int zone_no, int ame_amb_idx)
	{
		int num = 511;
		for (int i = 0; i < zone_no; i++)
		{
			num += gm_efct_zone_texamb_index_tbl[i];
		}
		return num + ame_amb_idx;
	}

	private static int gmEfctZoneGetObjectDworkNo(int model_dwork_no)
	{
		return 584 + (model_dwork_no - 582);
	}

	private static int gmEfctZoneGetMdlAmbtexDworkNo(int model_dwork_no)
	{
		return 586 + (model_dwork_no - 586);
	}

	private static int gmEfctZoneGetMdlTexlistDworkNo(int model_dwork_no)
	{
		return 588 + (model_dwork_no - 588);
	}

