				{
					main_work.win_mode = (uint)i;
					break;
				}
			}
			main_work.flag |= 1024u;
			GsSoundPlaySe("Window", main_work.se_handle);
		}
		else
		{
			main_work.proc_update = dmStaffRollProcTrophyCheck;
		}
	}

	private static void dmStaffRollProcWindowOpenEfct(DMS_STFRL_MAIN_WORK main_work)
	{
		if ((main_work.flag & 0x200) != 0)
		{
			main_work.proc_update = dmStaffRollProcWindowAnnounceIdle;
			main_work.proc_input = dmStaffRollInputProcWin;
			main_work.flag |= 64u;
			main_work.flag &= 4294966783u;
