	private static void dmStaffRollProcWindowAnnounceIdle(DMS_STFRL_MAIN_WORK main_work)
	{
		if (main_work.proc_input != null)
		{
			main_work.proc_input(main_work);
		}
		if (main_work.win_mode == 0 && (main_work.flag & 4) != 0)
