			main_work.flag &= 4294967291u;
			main_work.flag &= 4294967293u;
		}
	}

	private static void dmStaffRollProcWindowCloseEfct(DMS_STFRL_MAIN_WORK main_work)
	{
		if ((main_work.flag & 0x200) != 0)
