	private static void dmStaffRollSetWinOpenEfct(DMS_STFRL_MAIN_WORK main_work)
	{
		if (main_work.win_timer > 8f)
		{
			main_work.flag |= 512u;
			main_work.win_timer = 0f;
			for (uint num = 0u; num < 2; num++)
			{
				main_work.win_size_rate[num] = 1f;
			}
		}
		else
		{
			main_work.win_timer += 1f;
		}
		for (uint num2 = 0u; num2 < 2; num2++)
		{
			if (0f != main_work.win_timer)
			{
				main_work.win_size_rate[num2] = main_work.win_timer / 8f;
			}
			else
			{
				main_work.win_size_rate[num2] = 1f;
			}
			if (main_work.win_size_rate[num2] > 1f)
			{
				main_work.win_size_rate[num2] = 1f;
			}
		}
	}

	private static void dmStaffRollSetWinCloseEfct(DMS_STFRL_MAIN_WORK main_work)
	{
		for (uint num = 0u; num < 2; num++)
		{
			if (0f != main_work.win_timer)
			{
				main_work.win_size_rate[num] = main_work.win_timer / 8f;
			}
			else
			{
				main_work.win_size_rate[num] = 0f;
			}
		}
		if (main_work.win_timer < 0f)
		{
			main_work.flag |= 512u;
			main_work.win_timer = 0f;
			for (uint num2 = 0u; num2 < 2; num2++)
